#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    int status_flag;
    char source_ip[16]; // IP address as string (IPv4)
} DataPacket;

typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode* next;
} PacketNode;

typedef struct {
    PacketNode* head;
    pthread_mutex_t lock;
} PacketList;

#define EXPIRATION_THRESHOLD_SECONDS 3600 // Default expiration threshold

// Load expiration threshold from environment variable or use default
int get_expiration_threshold() {
    char* env_value = getenv("PACKET_EXPIRATION_THRESHOLD");
    if (env_value) {
        return atoi(env_value);
    }
    return EXPIRATION_THRESHOLD_SECONDS;
}

void init_packet_list(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_packet_list(PacketList* list) {
    PacketNode* current = list->head;
    while (current != NULL) {
        PacketNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

DataPacket* find_packet_by_id(PacketList* list, int id) {
    pthread_mutex_lock(&list->lock);

    PacketNode* current = list->head;
    while (current != NULL) {
        if (current->packet.id == id) {
            pthread_mutex_unlock(&list->lock);
            return &current->packet;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void add_packet(PacketList* list, DataPacket* packet) {
    pthread_mutex_lock(&list->lock);

    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) {
        perror("Failed to allocate memory for new packet");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    *new_node->packet = *packet;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void update_packet(PacketList* list, int id, DataPacket* updated_packet) {
    pthread_mutex_lock(&list->lock);

    PacketNode* current = list->head;
    while (current != NULL) {
        if (current->packet.id == id) {
            *current->packet = *updated_packet;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void purge_expired_packets(PacketList* list) {
    time_t now = time(NULL);
    int expiration_threshold = get_expiration_threshold();

    pthread_mutex_lock(&list->lock);

    PacketNode *current = list->head, *prev = NULL;

    while (current != NULL) {
        if ((now - current->packet.timestamp) > expiration_threshold) {
            if (prev == NULL) {
                // Removing head
                list->head = current->next;
                free(current);
                current = list->head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

