    FILE *log_file;
    FILE *report_file;
    EventFilter *filters;
    size_t filter_count;
    size_t memory_usage;
    size_t max_memory_usage;
    double max_execution_time;
    time_t start_time;
    int interrupted;
} ProcessContext;

// Function prototypes
