int load_configuration(const char *config_path, ProcessContext *context);
int process_log(ProcessContext *context);
void serialize_state(ProcessContext *context);
void deserialize_state(ProcessContext *context);

int main(int argc, char **argv) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <log_file> <report_file> <config_file> <memory_threshold> <max_execution_time>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_path = argv[1];
    const char *report_path = argv[2];
    const char *config_path = argv[3];
    size_t max_memory_usage = strtoul(argv[4], NULL, 10);
