    context.report_file = fopen(report_path, "w");
    context.max_memory_usage = max_memory_usage;
    context.max_execution_time = max_execution_time;

    if (!context.log_file || !context.report_file) {
        perror("Failed to open files");
        return EXIT_FAILURE;
    }

