['Here is a C implementation of a dynamically allocated buffer for managing log messages in a high-performance application:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_LEVEL 5
#define BUFFER_GROWTH_FACTOR 2

typedef enum {
    LOG_ERROR,
    LOG_WARN,
    LOG_INFO,
    LOG_DEBUG,
    LOG_TRACE
} LogLevel;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t used;
    LogLevel minLevel;
} LogBuffer;

LogBuffer* create_log_buffer(size_t initial_capacity, LogLevel level) {
    LogBuffer *log_buf = (LogBuffer *)malloc(sizeof(LogBuffer));
    if (!log_buf) return NULL;

    log_buf->buffer = (char *)calloc(initial_capacity, sizeof(char));
    if (!log_buf->buffer) {
        free(log_buf);
        return NULL;
    }

    log_buf->capacity = initial_capacity;
    log_buf->used = 0;
    log_buf->minLevel = level;

    return log_buf;
}

void free_log_buffer(LogBuffer *log_buf) {
    if (log_buf) {
        free(log_buf->buffer);
        free(log_buf);
    }
}

int log_message(LogBuffer *log_buf, LogLevel level, const char *format, ...) {
    if (level < log_buf->minLevel) return 0;

    va_list args;
    va_start(args, format);

    size_t message_len = vsnprintf(NULL, 0, format, args);
    va_end(args);

    if (message_len >= log_buf->capacity - log_buf->used) {
        size_t new_capacity = log_buf->capacity * BUFFER_GROWTH_FACTOR;
        while (new_capacity <= log_buf->used + message_len + 1) {
            new_capacity *= BUFFER_GROWTH_FACTOR;
        }

        char *new_buffer = (char *)realloc(log_buf->buffer, new_capacity);
        if (!new_buffer) return -1;

        log_buf->buffer = new_buffer;
        log_buf->capacity = new_capacity;
    }

    va_start(args, format);
    vsnprintf(log_buf->buffer + log_buf->used, message_len + 1, format, args);
    va_end(args);

    log_buf->used += message_len + 1;

    return 0;
}

int main() {
    LogBuffer *log_buf = create_log_buffer(256, LOG_INFO);
    if (!log_buf) {
        fprintf(stderr, "Failed to initialize log buffer\n");
        return EXIT_FAILURE;
    }

    log_message(log_buf, LOG_ERROR, "Error occurred: %s", "Out of memory");
    log_message(log_buf, LOG_INFO, "Application started at %s", "12:00 PM");

    printf("Log Buffer Contents:\n%s", log_buf->buffer);

    free_log_buffer(log_buf);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Buffer**: The buffer automatically grows as needed to accommodate new messages.
- **Conditional Logging**: Messages are logged only if they meet or exceed the specified minimum log level.
- **Memory Management**: Efficiently reallocates memory to prevent overflows and minimize wasted space.
- **Scalability**: Designed to handle increased message throughput by dynamically adjusting the buffer size.
- **Usability**: Provides a simple interface for logging with custom messages and formatting.
- **Maintainability**: Structured in a way that facilitates easy future enhancements.']

