import java.util.concurrent.*;
import java.util.logging.*;
import com.example.pokemon.library.PokemonTypeLibrary; // Assume this is the external library

public class PokemonWeaknessService {

    private static final Logger logger = Logger.getLogger(PokemonWeaknessService.class.getName());
    private final ConcurrentMap<String, String> cache;
    private final ScheduledExecutorService scheduler;
    private final int maxCacheSize;

    public PokemonWeaknessService(int cacheRefreshIntervalSeconds, int maxCacheSize) {
        this.cache = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.maxCacheSize = maxCacheSize;
        scheduleCacheRefresh(cacheRefreshIntervalSeconds);
    }

    private void scheduleCacheRefresh(long intervalSeconds) {
        scheduler.scheduleAtFixedRate(this::refreshCache, 0, intervalSeconds, TimeUnit.SECONDS);
    }

    private void refreshCache() {
        cache.clear();
        logger.info("Cache refreshed at " + System.currentTimeMillis());
    }

    public String getWeaknessInfo(String pokemonName) {
        return cache.computeIfAbsent(pokemonName, this::fetchWeaknessInfoFromLibrary);
    }

    private String fetchWeaknessInfoFromLibrary(String pokemonName) {
        try {
            String weakness = PokemonTypeLibrary.getWeaknessInformation(pokemonName);
            if (weakness == null) {
                logger.warning("Failed to find weaknesses for: " + pokemonName + " at " + System.currentTimeMillis());
                return "Unknown";
            }
            pruneCacheIfNeeded();
            return weakness;
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error fetching data for " + pokemonName, e);
            return "Error retrieving data";
        }
    }

    private void pruneCacheIfNeeded() {
        if (cache.size() > maxCacheSize) {
            cache.entrySet().removeIf(entry -> true); // Implement a specific LRU or LFU strategy here
            logger.info("Pruned cache to maintain size limit.");
        }
    }

    public static void main(String[] args) {
        PokemonWeaknessService service = new PokemonWeaknessService(300, 100);
        System.out.println(service.getWeaknessInfo("Pikachu"));
    }
}

// Unit Tests
import org.junit.jupiter.api.*;
import java.util.concurrent.*;

class PokemonWeaknessServiceTest {

    @Test
    void testConcurrentAccess() throws InterruptedException {
        PokemonWeaknessService service = new PokemonWeaknessService(1, 10);
        ExecutorService executor = Executors.newFixedThreadPool(10);

        CountDownLatch latch = new CountDownLatch(100);
        for (int i = 0; i < 100; i++) {
            executor.submit(() -> {
                service.getWeaknessInfo("Pikachu");
                latch.countDown();
            });
        }

        latch.await();
        executor.shutdown();

        Assertions.assertTrue(service.cache.containsKey("Pikachu"));
    }

    @Test
    void testCacheRefresh() throws InterruptedException {
        PokemonWeaknessService service = new PokemonWeaknessService(1, 10);

        String initialResult = service.getWeaknessInfo("Charizard");
        Thread.sleep(1500); // Wait for the cache to refresh

        String refreshedResult = service.getWeaknessInfo("Charizard");

        Assertions.assertNotSame(initialResult, refreshedResult);
    }

    @Test
    void testUnknownType() {
        PokemonWeaknessService service = new PokemonWeaknessService(1, 10);

        String result = service.getWeaknessInfo("UnknownPokemon");
        Assertions.assertEquals("Unknown", result);
    }
}
```

### Assumptions and Design Choices

- **Cache Management**: A `ConcurrentHashMap` is used for thread-safe caching. The cache size is capped using a simple pruning strategy, which can be refined to LRU or LFU as needed.

- **Concurrency Control**: `computeIfAbsent` ensures atomicity of checks-and-update operations on the cache, minimizing race conditions.

- **Logging**: Utilizes Java's built-in logging mechanism for recording failures and cache refreshes securely.

- **Cache Refresh Strategy**: Implemented a periodic clearing to prevent stale data without disrupting service.

- **Testing**: Unit tests cover concurrent access, cache refresh validity, and handling unknown types. 

This design balances performance with maintainability, supporting high throughput while maintaining low latency in responses.']

