#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

// Logging framework placeholder (replace with actual logging library)
#define LOG_INFO(...) printf("INFO: " __VA_ARGS__)
#define LOG_ERROR(...) fprintf(stderr, "ERROR: " __VA_ARGS__)

typedef struct {
    const char *key;
    size_t key_len;
    const char *iv;
} crypto_ctx;

pthread_mutex_t crypto_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to perform encryption/decryption
int process_crypto(const char *data_in, size_t data_in_len,
                   unsigned char **data_out, size_t *data_out_len,
                   crypto_ctx *ctx, int encrypt) {
    if (!data_in || !data_out || !data_out_len || !ctx || !ctx->key || !ctx->iv)
        return -1;

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        LOG_ERROR("Failed to create cipher context\n");
        return -1;
    }

    int dir = encrypt ? 1 : 0;
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();

    pthread_mutex_lock(&crypto_lock);

    if (EVP_CipherInit_ex(cipher_ctx, cipher, NULL, 
                          (unsigned char *)ctx->key, 
                          (unsigned char *)ctx->iv, dir) != 1) {
        LOG_ERROR("Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(cipher_ctx);
        pthread_mutex_unlock(&crypto_lock);
        return -1;
    }

    *data_out_len = data_in_len + EVP_CIPHER_block_size(cipher);

    if (EVP_CipherUpdate(cipher_ctx, *data_out, data_out_len,
                         (unsigned char *)data_in, data_in_len) != 1) {
        LOG_ERROR("Cipher update failed\n");
        EVP_CIPHER_CTX_free(cipher_ctx);
        pthread_mutex_unlock(&crypto_lock);
        return -1;
    }

    if (EVP_CipherFinal_ex(cipher_ctx, *data_out + *data_out_len, data_out_len) != 1) {
        LOG_ERROR("Cipher finalization failed\n");
        EVP_CIPHER_CTX_free(cipher_ctx);
        pthread_mutex_unlock(&crypto_lock);
        return -1;
    }

    pthread_mutex_unlock(&crypto_lock);

    EVP_CIPHER_CTX_free(cipher_ctx);
    return 0;
}

// Main function to handle command sequence
void crypto_command_handler(const char *commands[], int num_commands, 
                            const crypto_ctx *ctx) {
    unsigned char *output = NULL;
    size_t output_len = 0;

    for (int i = 0; i < num_commands; ++i) {
        if (!strcmp(commands[i], "encrypt")) {
            // Encrypt data
            int ret = process_crypto("data_to_encrypt", strlen("data_to_encrypt"),
                                     &output, &output_len, ctx, 1);
            if (ret == 0)
                LOG_INFO("Encryption successful\n");
            else
                LOG_ERROR("Encryption failed\n");
        } else if (!strcmp(commands[i], "decrypt")) {
            // Decrypt data
            int ret = process_crypto(output, output_len,
                                     &output, &output_len, ctx, 0);
            if (ret == 0)
                LOG_INFO("Decryption successful\n");
            else
                LOG_ERROR("Decryption failed\n");
        }
    }

    free(output); // Free allocated memory for output
}

int main() {
    const char *commands[] = {"encrypt", "decrypt"};
    int num_commands = sizeof(commands) / sizeof(commands[0]);

    crypto_ctx ctx = { .key = "0123456789abcdef0123456789abcdef",
                       .key_len = 32,
                       .iv = "1234567890abcdef" };

    crypto_command_handler(commands, num_commands, &ctx);
    return 0;
}
