#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_SEMAPHORES 5000

typedef struct {
    sem_t semaphore;
    int id;
    pthread_mutex_t lock;
    unsigned long wait_time;
    unsigned long signal_count;
} SemaphoreInfo;

SemaphoreInfo* semaphores[MAX_SEMAPHORES];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void log_anomaly(int sem_id, const char* message) {
    printf("Anomaly in semaphore %d: %s\n", sem_id, message);
}

int create_semaphore() {
    pthread_mutex_lock(&global_lock);

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (semaphores[i] == NULL) {
            SemaphoreInfo* sem_info = malloc(sizeof(SemaphoreInfo));
            if (!sem_info) {
                perror("Failed to allocate memory for semaphore");
                pthread_mutex_unlock(&global_lock);
                return -1;
            }

            sem_init(&sem_info->semaphore, 0, 0);
            sem_info->id = i;
            pthread_mutex_init(&sem_info->lock, NULL);
            sem_info->wait_time = 0;
            sem_info->signal_count = 0;

            semaphores[i] = sem_info;
            pthread_mutex_unlock(&global_lock);
            return i;
        }
    }

    log_anomaly(-1, "Failed to create semaphore: maximum limit reached");
    pthread_mutex_unlock(&global_lock);
    return -1;
}

int delete_semaphore(int sem_id) {
    pthread_mutex_lock(&global_lock);

    if (sem_id < 0 || sem_id >= MAX_SEMAPHORES || semaphores[sem_id] == NULL) {
        log_anomaly(sem_id, "Invalid semaphore ID for deletion");
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    SemaphoreInfo* sem_info = semaphores[sem_id];
    sem_destroy(&sem_info->semaphore);
    pthread_mutex_destroy(&sem_info->lock);
    free(sem_info);

    semaphores[sem_id] = NULL;

    pthread_mutex_unlock(&global_lock);
    return 0;
}

int semaphore_wait(int sem_id) {
    if (sem_id < 0 || sem_id >= MAX_SEMAPHORES || semaphores[sem_id] == NULL)
        return -1;

    SemaphoreInfo* sem_info = semaphores[sem_id];

    pthread_mutex_lock(&sem_info->lock);
    clock_t start_time = clock();

    if (sem_wait(&sem_info->semaphore) != 0) {
        log_anomaly(sem_id, "Semaphore wait failed");
        pthread_mutex_unlock(&sem_info->lock);
        return -1;
    }

    sem_info->wait_time += (clock() - start_time);

    pthread_mutex_unlock(&sem_info->lock);
    return 0;
}

int semaphore_signal(int sem_id) {
    if (sem_id < 0 || sem_id >= MAX_SEMAPHORES || semaphores[sem_id] == NULL)
        return -1;

    SemaphoreInfo* sem_info = semaphores[sem_id];

    pthread_mutex_lock(&sem_info->lock);
    sem_post(&sem_info->semaphore);

    sem_info->signal_count++;
    if (sem_info->wait_time > 100000) {
        log_anomaly(sem_id, "Excessive wait time detected");
    }

    pthread_mutex_unlock(&sem_info->lock);
    return 0;
}

void query_semaphore_state(int sem_id) {
    if (sem_id < 0 || sem_id >= MAX_SEMAPHORES || semaphores[sem_id] == NULL)
        return;

    SemaphoreInfo* sem_info = semaphores[sem_id];

    pthread_mutex_lock(&global_lock);
    printf("Semaphore ID: %d\n", sem_id);
    printf("Wait Time: %lu\n", sem_info->wait_time);
    printf("Signal Count: %lu\n", sem_info->signal_count);
    pthread_mutex_unlock(&global_lock);
}

void monitor_semaphores() {
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (semaphores[i] != NULL) {
            SemaphoreInfo* sem_info = semaphores[i];

            pthread_mutex_lock(&sem_info->lock);
            if (sem_info->wait_time > 100000 || sem_info->signal_count > 1000) {
                log_anomaly(i, "Monitoring detected potential bottleneck");
            }
            pthread_mutex_unlock(&sem_info->lock);
        }
    }
}
```

This code provides a robust system for managing a collection of semaphores with thread safety and monitoring. The `SemaphoreInfo` structure holds each semaphore's data, including its ID, wait time, and signal count, allowing the system to track usage patterns. Functions are provided for creating, deleting, waiting on, signaling, and querying semaphore states, along with logging anomalies like excessive wait times or frequent signals. This design aims to minimize memory overhead while ensuring scalability and efficiency under high load conditions.']

