['```cpp
#include <iostream>

// Definition of Node structure
struct Node {
    int data;
    Node* prev;
    Node* next;

    Node(int value) : data(value), prev(nullptr), next(nullptr) {}
};

// Definition of the DoublyLinkedList class
class DoublyLinkedList {
public:
    Node* head;
    Node* tail;

    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    // Function to insert after or append
    bool insertAfterOrAppend(int findValue, int newValue);

private:
    void freeList();
};

// Implementation of the insertAfterOrAppend function
bool DoublyLinkedList::insertAfterOrAppend(int findValue, int newValue) {
    Node* newNode = new (std::nothrow) Node(newValue);
    if (!newNode) return false; // Memory allocation failed

    if (!head) {  // List is empty
        head = tail = newNode;
    } else {
        Node* current = head;

        while (current && current->data != findValue) {
            current = current->next;
        }

        if (current) {  // Found the node to insert after
            newNode->prev = current;
            newNode->next = current->next;

            if (current == tail) {  // Updating the tail pointer
                tail = newNode;
            } else {
                current->next->prev = newNode;
            }

            current->next = newNode;
        } else {  // Node not found, append at the end
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    return true;
}

// Helper function to free all nodes in the list
void DoublyLinkedList::freeList() {
    while (head) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }
    tail = nullptr;
}

int main() {
    DoublyLinkedList dll;

    // Example usage:
    dll.insertAfterOrAppend(1, 2);  // Appends since list is empty
    dll.insertAfterOrAppend(3, 4);  // Appends again

    std::cout << "List after operations:" << std::endl;
    Node* current = dll.head;
    while (current) {
        std::cout << current->data << " ";
        current = current->next;
    }
    std::cout << std::endl;

    dll.freeList();  // Clean up
    return 0;
}
```']

['Here's a C++ application that integrates with a third-party API to handle requests concurrently, supporting both synchronous and asynchronous modes, with dynamic switching based on load:

```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <functional>
#include <future>
#include <chrono>
#include <atomic>
#include <unordered_map>

// Mocking third-party API client
class APIClient {
public:
    void requestSync() {
        // Simulate synchronous request processing
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    void requestAsync() {
        // Simulate asynchronous request processing
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
};

// Throttling and rate limiting
class RateLimiter {
    std::atomic<int> limit;
    std::mutex mtx;
    int requests = 0;

public:
    RateLimiter(int maxRequestsPerSecond) : limit(maxRequestsPerSecond) {}

    bool tryAcquire() {
        std::lock_guard<std::mutex> lock(mtx);
        if (requests < limit.load()) {
            ++requests;
            return true;
        }
        return false;
    }

    void reset() {
        std::lock_guard<std::mutex> lock(mtx);
        requests = 0;
    }
};

// Request handler with retry and backoff strategy
class RequestHandler {
    APIClient& client;
    int maxRetries;
    double baseBackoff;

public:
    RequestHandler(APIClient& apiClient, int retries, double backoff)
        : client(apiClient), maxRetries(retries), baseBackoff(backoff) {}

    void handleRequest(bool async = false) {
        for (int attempt = 0; attempt < maxRetries; ++attempt) {
            try {
                if (async) {
                    client.requestAsync();
                } else {
                    client.requestSync();
                }
                return;
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(baseBackoff * pow(2, attempt))));
            }
        }
    }
};

// Thread pool for concurrent processing
class ThreadPool {
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;

public:
    ThreadPool(size_t threads) : stop(false) {
        for (size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers)
            worker.join();
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queueMutex);

            if (stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task] { (*task)(); });
        }
        condition.notify_one();
        return res;
    }
};

// Main application class
class Application {
    APIClient apiClient;
    RateLimiter rateLimiter{100}; // 100 requests per second
    RequestHandler requestHandler{apiClient, 3, 100};
    ThreadPool pool{std::thread::hardware_concurrency()};
    std::atomic<bool> asyncMode{false};

public:
    void processRequest() {
        if (!rateLimiter.tryAcquire()) {
            std::cout << "Rate limit exceeded. Request throttled.\n";
            return;
        }

        bool currentAsyncMode = asyncMode.load();
        pool.enqueue([this, currentAsyncMode] { requestHandler.handleRequest(currentAsyncMode); });
    }

    void switchProcessingMode(bool useAsync) {
        asyncMode.store(useAsync);
    }
};

int main() {
    Application app;

    // Simulate incoming requests
    for (int i = 0; i < 1000; ++i) {
        app.processRequest();
    }

    // Switch to asynchronous mode based on load
    app.switchProcessingMode(true);

    std::this_thread::sleep_for(std::chrono::seconds(10));

    return 0;
}
```

### Key Features:

- **APIClient**: Simulates third-party API interactions.
- **RateLimiter**: Implements a basic rate limiting strategy.
- **RequestHandler**: Handles requests with retry and exponential backoff.
- **ThreadPool**: Manages concurrent request processing.
- **Application**: Orchestrates the entire process, supporting dynamic mode switching.

### Testing:

For testing, you would mock dependencies using frameworks like Google Mock or create custom test doubles to simulate different scenarios. This code is a foundational structure; further enhancements and real-world API integration would be necessary for production use.']

['Below is a simplified version of a modular C++ logging framework that addresses the requirements you specified. This example uses modern C++ features such as `std::async`, smart pointers, and mutexes for thread safety.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <memory>

enum class LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
};

class Logger {
public:
    Logger(size_t bufferSize, const std::string& logFile)
        : buffer_size_(bufferSize), log_file_path_(logFile) 
    {
        log_thread_ = std::thread(&Logger::processLogs, this);
    }

    ~Logger() {
        shutdown_ = true;
        cv_.notify_all();
        if (log_thread_.joinable()) {
            log_thread_.join();
        }
    }

    void setLogLevel(LogLevel level) {
        log_level_ = level;
    }

    void asyncLog(const std::string& message, LogLevel level) {
        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());

        if (level >= log_level_) {
            std::lock_guard<std::mutex> lock(mutex_);
            buffer_.emplace(now, message, level);

            if (buffer_.size() >= buffer_size_) {
                cv_.notify_one();
            }
        }
    }

private:
    struct LogEntry {
        std::time_t timestamp;
        std::string message;
        LogLevel level;
    };

    void processLogs() {
        std::ofstream log_file(log_file_path_, std::ios::app);

        while (!shutdown_) {
            std::unique_lock<std::mutex> lock(mutex_);

            cv_.wait(lock, [this] { return buffer_.size() > 0 || shutdown_; });

            auto end = std::min(buffer_size(), buffer_.size());
            for (size_t i = 0; i < end; ++i) {
                const LogEntry& entry = buffer_.front();

                if (log_file.is_open()) {
                    log_file << std::ctime(&entry.timestamp)
                             << "[" << getLevelString(entry.level) 
                             << "] " << entry.message << "\n";
                }

                buffer_.pop();
            }

            lock.unlock();

            if (buffer_size() > 0 && shutdown_) {
                lock.lock(); // Re-lock to flush remaining logs
                while (!buffer_.empty()) {
                    const LogEntry& entry = buffer_.front();

                    if (log_file.is_open()) {
                        log_file << std::ctime(&entry.timestamp)
                                 << "[" << getLevelString(entry.level) 
                                 << "] " << entry.message << "\n";
                    }

                    buffer_.pop();
                }
            }
        }

        if (log_file.is_open()) {
            log_file.close();
        }
    }

    const char* getLevelString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO:  return "INFO";
            case LogLevel::WARN:  return "WARN";
            case LogLevel::ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }

    size_t buffer_size() const { return buffer_.size(); }

    std::atomic<bool> shutdown_{false};
    std::thread log_thread_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<LogEntry> buffer_;
    LogLevel log_level_{LogLevel::DEBUG};
    size_t buffer_size_;
    std::string log_file_path_;
};

int main() {
    Logger logger(1000, "app.log");

    // Example usage
    logger.setLogLevel(LogLevel::INFO);

    for (int i = 0; i < 5000; ++i) {
        logger.asyncLog("This is a test log entry " + std::to_string(i), LogLevel::DEBUG);
        if (i % 100 == 0) {
            logger.asyncLog("This is an info log entry " + std::to_string(i), LogLevel::INFO);
        }
    }

    std::this_thread::sleep_for(std::chrono::seconds(1));

    return 0;
}
```

### Key Features:
- **Asynchronous Logging**: Uses a separate thread to handle logging, reducing latency during peak loads.
- **Thread Safety**: Utilizes mutexes and condition variables to ensure safe concurrent access.
- **Dynamic Configuration**: Allows changing log levels at runtime.
- **Buffer Management**: Implements a buffer to batch log entries for more efficient writing.
- **Log Rotation/Storage Handling**: This example writes logs to a file; in a real-world scenario, you would add logic for rotating logs based on size or time and handling storage limits.

This code provides a foundational framework that can be expanded with additional features such as external logging service integration, dynamic destination configuration, and more sophisticated log rotation mechanisms.']

