public class ConfigurationSettings
{
    public int WindowWidth { get; set; }
    public int WindowHeight { get; set; }
    public int FrameRateLimit { get; set; }
    public float MouseSensitivity { get; set; }
    public int MaxNetworkConnections { get; set; }

    // Additional versioning info
    public string Version { get; set; }
}

public class GameEngineConfigLoader
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();
    private ConfigurationSettings _currentConfig;
    private static Dictionary<string, ConfigurationSettings> _configCache = new();
    private HttpClient _httpClient;

    public GameEngineConfigLoader(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<ConfigurationSettings> LoadConfigurationAsync(string filePath, string remoteUrl = null)
    {
        try
        {
            var config = await LoadFromFileAsync(filePath);

            if (!string.IsNullOrEmpty(remoteUrl))
            {
                var remoteConfig = await LoadFromRemoteAsync(remoteUrl);
                MergeConfigs(config, remoteConfig);
            }

            CacheConfiguration(config);
            MonitorConfigurationChanges(config);

            return config;
        }
        catch (Exception ex)
        {
            logger.Error(ex, "Failed to load configuration.");
            throw new InvalidOperationException("Error loading configuration.", ex);
        }
    }

    private async Task<ConfigurationSettings> LoadFromFileAsync(string filePath)
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException($"The file {filePath} was not found.");
        }

        var json = await File.ReadAllTextAsync(filePath);
        return JsonConvert.DeserializeObject<ConfigurationSettings>(json);
    }

    private async Task<ConfigurationSettings> LoadFromRemoteAsync(string remoteUrl)
    {
        try
        {
            var response = await _httpClient.GetAsync(remoteUrl);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to fetch configuration from {remoteUrl}. Status code: {response.StatusCode}");
            }

            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<ConfigurationSettings>(json);
        }
        catch (Exception ex)
        {
            logger.Warn(ex, "Remote configuration loading failed. Using cached settings if available.");
            throw;
        }
    }

    private void MergeConfigs(ConfigurationSettings localConfig, ConfigurationSettings remoteConfig)
    {
        // Priority to remote config; merge logic can be adjusted as needed
        foreach (var property in typeof(ConfigurationSettings).GetProperties())
        {
            var value = property.GetValue(remoteConfig);
            if (value != null)
            {
                property.SetValue(localConfig, value);
            }
        }
    }

    private void CacheConfiguration(ConfigurationSettings config)
    {
        _configCache[config.Version] = config;
    }

    private void MonitorConfigurationChanges(ConfigurationSettings newConfig)
    {
        var previousConfig = _currentConfig;

        if (previousConfig != null && !AreConfigsEqual(previousConfig, newConfig))
        {
            logger.Info($"Configuration changed from version {previousConfig?.Version} to {newConfig.Version}");
            // Trigger alerts or notifications as needed
        }

        _currentConfig = newConfig;
    }

    private bool AreConfigsEqual(ConfigurationSettings config1, ConfigurationSettings config2)
    {
        return config1.WindowWidth == config2.WindowWidth &&
               config1.WindowHeight == config2.WindowHeight &&
               config1.FrameRateLimit == config2.FrameRateLimit &&
               config1.MouseSensitivity == config2.MouseSensitivity &&
               config1.MaxNetworkConnections == config2.MaxNetworkConnections;
    }

    public ConfigurationSettings GetCurrentConfig()
    {
        return _currentConfig;
    }
}

// Usage
