using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
import System.Threading;
using System.Xml.Linq;

public class XmlDirectoryManager
{
    private static readonly object LockObject = new object();
    private static bool environmentVariableSet = false;

    public XElement ParseAndProcessXml(string xmlFilePath, string elementName)
    {
        if (!File.Exists(xmlFilePath))
            throw new FileNotFoundException($"XML file not found: {xmlFilePath}");

        XDocument xmlDoc = XDocument.Load(xmlFilePath);
        var elements = xmlDoc.Descendants(elementName).ToList();

        if (elements.Count == 0)
            return new XElement("default", new XAttribute("message", "No matching element found"));

        XElement mergedElement;
        if (elements.Count > 1)
        {
            mergedElement = elements.First();
            foreach (var element in elements.Skip(1))
            {
                foreach (var attribute in element.Attributes())
                    mergedElement.SetAttributeValue(attribute.Name, attribute.Value);
            }
        }
        else
        {
            mergedElement = elements.First();
        }

        ProcessEnvironmentVariable("MY_ENV_VAR");

        return mergedElement;
    }

    private void ProcessEnvironmentVariable(string envVar)
    {
        lock (LockObject)
        {
            if (!environmentVariableSet)
            {
                environmentVariableSet = true;

                string dirPath = Environment.GetEnvironmentVariable(envVar);

                if (!string.IsNullOrEmpty(dirPath))
                {
                    ValidateAndAdjustDirectoryStructure(dirPath);
                }
            }
        }
    }

    private void ValidateAndAdjustDirectoryStructure(string baseDir)
    {
        var expectedSubDirs = new[] { "subdir1", "subdir2" };
        var existingSubDirs = Directory.GetDirectories(baseDir);

        foreach (var subDir in expectedSubDirs)
        {
            string fullPath = Path.Combine(baseDir, subDir);
            if (!Directory.Exists(fullPath))
                Directory.CreateDirectory(fullPath);
        }

        var dirsToRemove = existingSubDirs.Where(dir => !expectedSubDirs.Any(subDir => dir.EndsWith(Path.DirectorySeparatorChar + subDir))).ToList();

        foreach (var dir in dirsToRemove)
        {
            try
            {
                Directory.Delete(dir, true);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error removing directory {dir}: {ex.Message}");
            }
        }
    }

    public static void Main(string[] args)
    {
        var manager = new XmlDirectoryManager();
        string xmlFilePath = "config.xml";
        string elementName = "elementToMatch";

        try
        {
            XElement result = manager.ParseAndProcessXml(xmlFilePath, elementName);
            Console.WriteLine(result.ToString());
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
