['Below is a Java implementation that addresses the requirements specified in your task:

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class HashProcessor {

    private static final Logger logger = Logger.getLogger(HashProcessor.class.getName());
    private static final int MAX_CHUNK_SIZE = 1 * 1024 * 1024; // 1 MB
    private static final int CACHE_SIZE_LIMIT = 1000;

    private final Map<String, String> hashCache;
    private final ConcurrentHashMap<String, Integer> frequencyMap;
    private MessageDigest messageDigest;

    public HashProcessor() throws NoSuchAlgorithmException {
        this.messageDigest = MessageDigest.getInstance("SHA-256");
        this.hashCache = new HashMap<>();
        this.frequencyMap = new ConcurrentHashMap<>();
    }

    public synchronized String processStreamInput(byte[] inputData) throws Exception {
        if (inputData.length > MAX_CHUNK_SIZE || containsControlCharacters(inputData)) {
            throw new IllegalArgumentException("Invalid input data");
        }

        String inputString = new String(inputData, StandardCharsets.UTF_8);
        String cacheKey = generateCacheKey(inputString);

        // Cache hit
        if (hashCache.containsKey(cacheKey)) {
            frequencyMap.merge(cacheKey, 1, Integer::sum);
            logger.info("Duplicate hash request for key: " + cacheKey);
            return hashCache.get(cacheKey);
        }

        // Cache miss
        String hashDigest = computeHash(inputString);

        if (hashCache.size() >= CACHE_SIZE_LIMIT) {
            evictOldestEntry();
        }

        hashCache.put(cacheKey, hashDigest);
        frequencyMap.merge(cacheKey, 1, Integer::sum);
        logger.info("Unique hash request for key: " + cacheKey);

        return hashDigest;
    }

    private boolean containsControlCharacters(byte[] data) {
        for (byte b : data) {
            if ((b < 32 || b == 127) && b != '\t') { // Allow tab character
                return true;
            }
        }
        return false;
    }

    private String computeHash(String inputString) throws Exception {
        byte[] hashBytes = messageDigest.digest(inputString.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b & 0xff));
        }
        return sb.toString();
    }

    private String generateCacheKey(String inputString) {
        return Integer.toHexString(inputString.hashCode()) + "_" + inputString.length();
    }

    private void evictOldestEntry() {
        // Simple eviction strategy: remove the first entry
        String oldestKey = null;
        long oldestFrequency = Long.MAX_VALUE;

        for (Map.Entry<String, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() < oldestFrequency) {
                oldestFrequency = entry.getValue();
                oldestKey = entry.getKey();
            }
        }

        if (oldestKey != null) {
            hashCache.remove(oldestKey);
            frequencyMap.remove(oldestKey);
        }
    }
}
```

### Key Components:
- **Validation:** The input is checked for control characters, and its size does not exceed 1 MB.
- **Hashing & Caching:** Uses SHA-256 for hashing. Maintains a cache for storing hash digests with a simple eviction strategy when the cache exceeds a certain limit.
- **Thread Safety:** The `processStreamInput` method is synchronized to ensure thread safety during cache access and updates.
- **Statistics Logging:** Logs information about unique and duplicate requests.
- **Fallback Mechanism:** While not fully implemented, the design supports efficient caching for fallback in case of service unavailability.']

