            if ($_REQUEST['sub_action'] === 'delete' && $_REQUEST['id']) {
                return $response = ['message' => 'confirmation', 'data' => ['Please confirm the deletion.']];

            } elseif ($_REQUEST['sub_action'] === 'confirm_delete' && isset($_REQUEST['confirm'])) {
                // Perform actual deletion
                if ($this->deleteUserById($_REQUEST['id'])) {
                    $this->logOperation('DELETE', $_REQUEST);
                    $response = ['message' => 'success', 'data' => []];

                    // Notify via external API about the deletion (pseudo-code)
                    $this->notifyExternalService(['action' => 'delete', 'userId' => $_REQUEST['id']]);
                } else {
                    throw new Exception('Failed to delete user.');
                }
            }

            // Create or update user
            if ($_REQUEST['id']) {
                $response = $this->updateUser($_REQUEST);
            } else {
                $response = $this->createUser($_REQUEST);
            }

        } catch (Exception $e) {
            $response['data'] = ['error' => $e->getMessage()];
        }

        return json_encode($response);
    }

    private function validateRequest($request) {
        // Check required fields
        if (!isset($request['name'], $request['email'], $request['password'])) {
            return false;
        }

        // Validate email format and uniqueness
        if (!$this->isValidEmail($request['email']) || !$this->isUniqueEmail($request['email'])) {
            return false;
        }

        // Check password strength
        if (!$this->isStrongPassword($request['password'])) {
            return false;
        }

        return true;
    }

    private function isValidEmail($email) {
        return filter_var($email, FILTER_VALIDATE_EMAIL);
    }

    private function isUniqueEmail($email) {
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM users WHERE email = ?");
        $stmt->bind_param('s', $email);
        $stmt->execute();
        $stmt->bind_result($count);
        $stmt->fetch();
        return $count === 0;
    }

    private function isStrongPassword($password) {
        // Example: Must be at least 8 characters long and contain a mix of letters, numbers, and symbols
        return preg_match('/^(?=.*\d)(?=.*[A-Za-z])[A-Za-z\d@$!%*#?&]{8,}$/', $password);
    }

    private function createUser($data) {
        try {
            $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
            $passwordHash = password_hash($data['password'], PASSWORD_DEFAULT);
            $stmt->bind_param('sss', $data['name'], $data['email'], $passwordHash);

            if ($stmt->execute()) {
                $this->logOperation('CREATE', $data);

                // Notify via external API about the creation (pseudo-code)
                $this->notifyExternalService(['action' => 'create', 'userId' => $stmt->insert_id]);
                return ['message' => 'success', 'data' => []];
            } else {
                throw new Exception('Failed to create user.');
            }
        } catch (Exception $e) {
            return ['message' => 'error', 'data' => ['error' => $e->getMessage()]];
        }
    }

    private function updateUser($data) {
        try {
            if (!isset($data['id'])) throw new Exception('User ID is required for update.');

            // Build the SQL query dynamically
            $fields = [];
            foreach (['name', 'email', 'password'] as $field) {
                if (isset($data[$field])) {
                    $fields[] = "$field = ?";
                    if ($field === 'password') {
                        $data[$field] = password_hash($data[$field], PASSWORD_DEFAULT);
                    }
                }
            }

            if (empty($fields)) throw new Exception('No fields to update.');

            $stmt = $this->db->prepare("UPDATE users SET " . implode(', ', $fields) . " WHERE id = ?");
            array_push($data, $data['id']);
            $types = str_repeat('s', count($data) - 1) . 'i';

            $stmt->bind_param($types, ...array_values($data));

            if ($stmt->execute()) {
                $this->logOperation('UPDATE', $data);

                // Notify via external API about the update (pseudo-code)
                $this->notifyExternalService(['action' => 'update', 'userId' => $data['id']]);
                return ['message' => 'success', 'data' => []];
            } else {
                throw new Exception('Failed to update user.');
            }
        } catch (Exception $e) {
            return ['message' => 'error', 'data' => ['error' => $e->getMessage()]];
        }
    }

    private function deleteUserById($id) {
        try {
            if (!$id) return false;

            $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
            $stmt->bind_param('i', $id);

            return $stmt->execute();
        } catch (Exception $e) {
            // Log and handle error
            return false;
        }
    }

    private function logOperation($action, $data) {
        // Pseudo code for logging operation without exposing sensitive info like passwords
        unset($data['password']);
        file_put_contents('operation_log.txt', json_encode(['action' => $action, 'data' => $data]) . PHP_EOL, FILE_APPEND);
    }

    private function notifyExternalService($payload) {
        // Pseudo code for notifying an external service (API call handling)
        try {
            $ch = curl_init('https://external.api/notify');
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload));
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

            // Execute and handle failures
            if (curl_exec($ch) === false) {
                throw new Exception('Failed to notify external service.');
            }

            curl_close($ch);
        } catch (Exception $e) {
            // Log notification failure
        }
    }
}

// Example usage:
$db = new mysqli("localhost", "username", "password", "database");
$userManager = new UserManager($db);
echo $userManager->manageUser($_REQUEST);

?>
