        if (sanitizedHtml == null)
            return false;

        // Cache key based on the section and element IDs
        var cacheKey = $"{sectionId}:{elementId}";

        lock (CacheLock)
        {
            ContentCache[cacheKey] = sanitizedHtml;
        }

