    private ExternalConfigService configService; // Assume this service is defined elsewhere
    private DependencyManager dependencyManager; // Assume this manager is defined elsewhere

    public MoSTState loadMoSTStateFromFile(String filePath) {
        ObjectInputStream objectInputStream = null;
        try {
            objectInputStream = new ObjectInputStream(new FileInputStream(filePath));
            Object obj = objectInputStream.readObject();

            if (obj instanceof MoSTState) {
                MoSTState mostState = (MoSTState) obj;
                recycleThemeBitmap(mostState.getThemeBitmap()); // Assume this method is defined elsewhere
                return mostState;
            }
        } catch (Exception e) {
            logger.severe("Error loading state from file: " + e.getMessage());
        } finally {
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (Exception e) {
                    logger.warning("Failed to close ObjectInputStream: " + e.getMessage());
                }
            }
        }
        return null;
    }

    public void updateThemeCache() {
