// User Management Service Class
public class UserService
{
    private readonly UserManager<IdentityUser> _userManager;
    private readonly SignInManager<IdentityUser> _signInManager;

    public UserService(UserManager<IdentityUser> userManager, SignInManager<IdentityUser> signInManager)
    {
        _userManager = userManager;
        _signInManager = signInManager;
    }

    // Method to create user with validation and MFA setup
    public async Task<IdentityResult> CreateUserAsync(string username, string password, bool enableMfa)
    {
        var user = new IdentityUser { UserName = username };

        // Customizable validation rules
        if (!IsValidUsername(user.UserName) || !IsValidPassword(password))
            return IdentityResult.Failed(new IdentityError { Description = "Invalid username or password" });

        var result = await _userManager.CreateAsync(user, password);
        if (result.Succeeded && enableMfa)
        {
            // Set up MFA during account creation
            await SetupMultiFactorAuthenticationAsync(user.Id);
        }
        return result;
    }

    private bool IsValidUsername(string username) => !string.IsNullOrWhiteSpace(username) && username.Length >= 5;

    private bool IsValidPassword(string password) => password.Length >= 8; // Example rule

    private async Task SetupMultiFactorAuthenticationAsync(string userId)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user != null)
        {
            var token = await _userManager.GenerateTwoFactorTokenAsync(user, "Email");
            // Send the MFA token to the user's email or other configured channel
        }
    }

    // Periodic cleanup of inactive users
    public async Task CleanupInactiveUsersAsync(TimeSpan inactivityPeriod)
    {
        var inactiveUsers = await _userManager.Users
            .Where(u => DateTime.UtcNow - u.LockoutEnd >= inactivityPeriod || (u.LastLoginTimeUtc.HasValue && DateTime.UtcNow - u.LastLoginTimeUtc.Value > inactivityPeriod))
            .ToListAsync();

        foreach (var user in inactiveUsers)
        {
            // Logic to delete or disable the account
            await _userManager.DeleteAsync(user);
        }
    }
}

