["```javascript
const fs = require('fs');
const path = require('path');
const mime = require('mime-types');
const { createReadStream } = require('stream');
const readline = require('readline');

async function readFilesFromDirectory(directoryPath, fileExtensions, contentTypes) {
  const results = [];

  try {
    // Get all files from the directory
    const files = await fs.promises.readdir(directoryPath);

    for (let fileName of files) {
      const filePath = path.join(directoryPath, fileName);
      const stats = await fs.promises.stat(filePath);

      if (!stats.isFile()) continue;

      const extension = path.extname(fileName).substring(1);
      const mimeType = mime.lookup(filePath);

      if (fileExtensions.includes(extension) && contentTypes.includes(mimeType)) {
        let fileContentMatches = false;

        // Efficiently read the file for specific content patterns using stream
        const rl = readline.createInterface({
          input: createReadStream(filePath)
        });

        for await (const line of rl) {
          if (/* condition to match line with desired content */) {
            fileContentMatches = true;
            break;
          }
        }

        if (fileContentMatches) {
          results.push(fileName);
        }
      }
    }
  } catch (error) {
    console.error('Error reading files:', error); // Consider integrating with logging system
    throw new Error(`Failed to read directory: ${error.message}`);
  }

  return results;
}

module.exports = { readFilesFromDirectory };
```

### Key Points:
- **File Filtering:** Filters by extension and MIME type using `mime-types`.
- **Efficient Content Reading:** Uses streams with `readline` for memory efficiency.
- **Error Handling:** Catches and logs errors, suitable for integration with logging systems.
- **Performance Optimization:** Handles files asynchronously to minimize CPU and memory usage."]

['Here is a JavaScript implementation of a function to manage a suite of asynchronous unit tests for a given module:

```javascript
const blueslip = require('blueslip');

async function runTests(moduleName, testSuite) {
    const startTime = Date.now();
    console.log(`Starting tests for module: ${moduleName}`);

    // Load the module and initialize any necessary dependencies
    let module;
    try {
        module = await (async () => { 
            return new Promise((resolve, reject) => {
                try {
                    resolve(require(moduleName));
                } catch (error) {
                    reject(`Failed to load module ${moduleName}: ${error}`);
                }
            });
        })();
    } catch (error) {
        console.error(error);
        return;
    }

    // Define a function to run each test
    async function executeTest(test, index) {
        try {
            const testStart = Date.now();
            console.log(`Running test: ${test.name}`);

            // Mock dependencies using blueslip
            const mockContext = blueslip.mockContext(module);
            await test.func(mockContext);

            // Reset blueslip to clear state after each test
            blueslip.reset();

            const duration = Date.now() - testStart;
            console.log(`Test "${test.name}" passed in ${duration}ms`);
        } catch (error) {
            const duration = Date.now() - test.start || 0;
            console.error(`Test "${test.name}" failed after ${duration}ms with error:`, error);
        }
    }

    // Execute tests asynchronously
    for (let i = 0; i < testSuite.length; i++) {
        await executeTest(testSuite[i], i).catch((error) => {
            console.error(`Error during test execution: ${error}`);
        });
    }

    const totalTime = Date.now() - startTime;
    console.log(`All tests completed in ${totalTime}ms`);
}

// Usage example
const myModuleTests = [
    { name: 'Test 1', func: async (mockContext) => { /* Test logic using mockContext */ } },
    { name: 'Test 2', func: async (mockContext) => { /* Test logic using mockContext */ } }
];

runTests('myModule', myModuleTests);
```

### Key Considerations:

1. **Dynamic Module Loading**: The `require` function is used within a promise to handle asynchronous loading and error management.

2. **Resource Management**: Each test uses `blueslip.mockContext` to simulate dependencies, ensuring that the state is reset after each test with `blueslip.reset()`.

3. **Logging**: Detailed logging provides insights into test execution times and outcomes without becoming a performance bottleneck.

4. **Failure Handling**: Tests are executed in sequence, allowing the suite to continue even if individual tests fail.

5. **Integration**: The function is designed to be integrated easily with existing frameworks by accepting module names and test suites as parameters.

6. **Memory Optimization**: Each test's context is reset, minimizing memory usage and preventing leaks.

7. **Timeouts and Concurrency**: These features can be added by wrapping `test.func` calls in a timeout mechanism or using concurrent execution patterns like `Promise.all`.

8. **Extensibility**: The function accepts an array of tests, making it easy to add new tests without modifying the core logic.']

["```javascript
// newsSearch.js

const axios = require('axios');
const natural = require('natural');

// Configuration object for API settings
const config = {
  apiKey: process.env.NEWS_API_KEY,
  apiUrl: process.env.NEWS_API_URL || 'https://api.example.com/articles',
  trendingTopicsSource: process.env.TRENDING_TOPICS_URL || 'https://api.example.com/trending'
};

// Function to fetch and parse trending topics
async function fetchTrendingTopics() {
  try {
    const response = await axios.get(config.trendingTopicsSource);
    return response.data.topics;
  } catch (error) {
    console.error('Error fetching trending topics:', error);
    return [];
  }
}

// Function to extract keywords using NLP
function extractKeywords(query) {
  const tokenizer = new natural.WordTokenizer();
  const tokens = tokenizer.tokenize(query.toLowerCase());

  // Use a basic stop words list; can be extended for better results
  const stopwords = ['the', 'and', 'in', 'of', 'to'];
  return tokens.filter(word => !stopwords.includes(word));
}

// Function to fetch articles from news API
async function searchArticles(query, keywords) {
  try {
    const response = await axios.get(config.apiUrl, {
      params: { q: query, apiKey: config.apiKey }
    });
    return response.data.articles || [];
  } catch (error) {
    console.error('Error fetching articles:', error);
    return [];
  }
}

// Function to score articles based on keywords and recency
function scoreArticles(articles, keywords, trendingTopics) {
  const now = new Date();
  return articles.map(article => {
    let score = 0;

    // Score by keyword matches
    const titleWords = article.title.toLowerCase().split(/\s+/);
    keywords.forEach(keyword => {
      if (titleWords.includes(keyword)) score += 10;
    });

    // Boost for trending topics
    if (trendingTopics.includes(article.title.toLowerCase())) score += 20;

    // Recency scoring, newer articles get a higher boost
    const pubDate = new Date(article.publishedAt);
    const daysDifference = Math.floor((now - pubDate) / (1000 * 60 * 60 * 24));
    if (daysDifference < 7) score += 30;

    return { ...article, score };
  }).sort((a, b) => b.score - a.score);
}

// Main function to retrieve and sort relevant articles
async function getRelevantArticles(query) {
  const keywords = extractKeywords(query);
  const trendingTopics = await fetchTrendingTopics();

  // Fetch articles with throttling mechanism
  await new Promise(resolve => setTimeout(resolve, 1000)); // Example throttling delay

  let articles = [];
  try {
    articles = await searchArticles(query, keywords);
  } catch (error) {
    console.error('Error during article retrieval:', error);
  }

  return scoreArticles(articles, keywords, trendingTopics).map(({ title, url, publishedAt, score }) => ({
    title,
    URL: url,
    publicationDate: publishedAt
  }));
}

module.exports = { getRelevantArticles };
```

### Design Decisions:

1. **Modularity**: The code is broken into functions for keyword extraction, API requests, and scoring. This ensures separation of concerns.

2. **Error Handling**: Each asynchronous operation has try-catch blocks to handle network errors gracefully.

3. **Throttling**: A simple delay mechanism is included before making API calls to respect rate limits. More sophisticated solutions like token bucket algorithms can be implemented for production-level throttling.

4. **Scoring Mechanism**: Articles are scored based on keyword matches, trending topics, and recency of publication to ensure relevance.

5. **Configurability**: The API configuration is done via environment variables or a settings object to allow flexibility with different APIs.

6. **Performance Optimization**: A delay mechanism for throttling helps manage high loads; however, more advanced methods could be considered in production environments."]

['```javascript
function generateFooterScripts(scripts) {
    const validUrlPattern = new RegExp(
        '^(https?|ftp):\\/\\/' +
        '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.?)+[a-z]{2,}|' +
        '((\\d{1,3}\\.){3}\\d{1,3}))' +
        '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*' +
        '(\\?[;&a-z\\d%_.~+=-]*)?' +
        '(\\#[-a-z\\d_]*)?$',
        'i'
    );

    const validPriorityRange = (priority) => priority >= 1 && priority <= 10;
    const defaultLowestPriority = 11;

    let uniqueIds = new Set();
    let renderedScripts = [];

    scripts.forEach(script => {
        const { id, src, async: isAsync, priority } = script;

        if (!validUrlPattern.test(src)) {
            throw new Error(`Invalid URL for script with ID ${id}: ${src}`);
        }

        if (uniqueIds.has(id)) {
            console.warn(`Duplicate ID found for script ${id}. Adjusting ID to ensure uniqueness.`);
            id += `_${new Date().getTime()}`;
        }

        uniqueIds.add(id);

        const finalPriority = validPriorityRange(priority) ? priority : defaultLowestPriority;
        renderedScripts.push({
            id,
            src,
            isAsync,
            priority: finalPriority
        });
    });

    // Sort scripts by priority
    renderedScripts.sort((a, b) => a.priority - b.priority);

    return `
        <footer>
            ${renderedScripts.map(script => {
                const asyncAttribute = script.isAsync ? 'async' : '';
                return `<script id="${script.id}" src="${script.src}" ${asyncAttribute}></script>`;
            }).join('')}
        </footer>
    `;
}

