<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Dynamic JS Loader</title>
</head>
<body>

<script>
class DynamicJSLoader {
    constructor(files, debugLog = true) {
        this.files = files;
        this.debugLog = debugLog;
        this.fileStatus = {};
        this.baseUrl = "https://example.com/js/"; // Adjust the base URL accordingly
    }

    async loadFiles() {
        const promises = this.files.map(file => this.loadFile(file));
        await Promise.all(promises);
        console.log('All files processed.');
    }

    loadFile(file) {
        return new Promise((resolve, reject) => {
            if (!file || typeof file !== 'string') {
                this.logStatus(file, 'missing');
                resolve();
                return;
            }

            const modifiedFileName = this.modifyExtension(file);
            const scriptTag = document.createElement('script');

            scriptTag.src = `${this.baseUrl}${modifiedFileName}`;
            scriptTag.async = true;

            scriptTag.onload = () => {
                this.logStatus(modifiedFileName, 'loaded');
                resolve();
            };

            scriptTag.onerror = () => {
                this.logStatus(modifiedFileName, 'failed');
                reject(new Error(`Failed to load file: ${modifiedFileName}`));
            };

            document.head.appendChild(scriptTag);
        }).catch(error => console.error(error.message));
    }

    modifyExtension(filename) {
        const extensionIndex = filename.lastIndexOf('.');
        if (extensionIndex === -1) return `${filename}.0.min.js`;

        const namePart = filename.substring(0, extensionIndex);
        const numericSequence = namePart.length.toString();
        return `${namePart}.${numericSequence}.min.js`;
    }

    logStatus(fileName, status) {
        if (!this.debugLog) return;

        this.fileStatus[fileName] = status;
        console.log(`File: ${fileName}, Status: ${status}`);
    }
}

// Example usage:
const filesToLoad = [
    'app.js',
    'utils.js',
    'main.js',
    // More file names as needed
];

const loader = new DynamicJSLoader(filesToLoad);
loader.loadFiles();
</script>

</body>
</html>
```

