<?php

class StringGenerator {
    private $characterSets = [
        'uppercase' => range('A', 'Z'),
        'lowercase' => range('a', 'z'),
        'digits'    => range(0, 9),
        'special'   => ['!', '@', '#', '$', '%', '^', '&', '*', '(', ')']
    ];

    public function generateString($length = 10, $sets = ['uppercase', 'lowercase', 'digits']) {
        if ($length < 1) {
            throw new InvalidArgumentException("Length must be greater than zero.");
        }

        $characters = [];
        foreach ($sets as $set) {
            if (isset($this->characterSets[$set])) {
                $characters = array_merge($characters, $this->characterSets[$set]);
            }
        }

        if (empty($characters)) {
            throw new RuntimeException("No valid character sets provided.");
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, count($characters) - 1);
            $randomString .= $characters[$randomIndex];
        }

        return $randomString;
    }
}

class FileReader {
    private $directory;

    public function __construct($directory) {
        if (!is_dir($directory)) {
            throw new InvalidArgumentException("Invalid directory path.");
        }

        $this->directory = rtrim($directory, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;
    }

    public function readFileAsync($filename) {
        return new \React\Promise\Promise(function ($resolve, $reject) use ($filename) {
            $filePath = $this->directory . $filename;

            if (!file_exists($filePath)) {
                $reject(new RuntimeException("File not found: {$filename}"));
                return;
            }

            if (!is_readable($filePath)) {
                $reject(new RuntimeException("Cannot read file: {$filename}. Check permissions."));
                return;
            }

            try {
                $content = file_get_contents($filePath);
                $resolve($content);
            } catch (\Exception $e) {
                $reject($e);
            }
        });
    }

    public function listFiles() {
        if (!is_readable($this->directory)) {
            throw new RuntimeException("Cannot read directory: {$this->directory}");
        }

        return array_diff(scandir($this->directory), ['.', '..']);
    }
}

// Usage Example
require 'vendor/autoload.php';

$stringGenerator = new StringGenerator();
$fileReader = new FileReader('/path/to/your/directory');

$randomString = $stringGenerator->generateString(15, ['uppercase', 'lowercase', 'special']);
echo "Generated string: {$randomString}\n";

React\EventLoop\Factory::create()->addTimer(0.001, function () use ($fileReader) {
    foreach ($fileReader->listFiles() as $filename) {
        $fileReader->readFileAsync($filename)
            ->then(function ($content) use ($filename) {
                echo "Read content of {$filename}: \n$content\n";
            })
            ->otherwise(function (\Exception $e) use ($filename) {
                echo "Error reading {$filename}: {$e->getMessage()}\n";
            });
    }
});

\React\EventLoop\Factory::create()->run();
```

**Notes:**
- Ensure `react/event-loop` is installed via Composer for asynchronous file operations.
- This script assumes you're running within an environment that supports ReactPHP and promises. It combines synchronous string generation with asynchronous file reading, maintaining efficiency without blocking execution. 
- Error handling is incorporated through exceptions and promise rejection callbacks, ensuring robust operation even under error conditions like missing files or permission issues.']

