const axios = require('axios');
const NodeCache = require('node-cache');

class PEMCertificateGenerator {
  constructor(apiUrl, clientId, clientSecret) {
    this.apiUrl = apiUrl;
    this.clientId = clientId;
    this.clientSecret = clientSecret;
    this.cache = new NodeCache({ stdTTL: 300 });
    this.retryDelays = [1000, 2000, 4000]; // Exponential backoff delays
  }

  async generatePEMCertificate(userId) {
    let retryCount = 0;

    const fetchData = async () => {
      try {
        if (this.cache.has(`user_${userId}`)) {
          return this.cache.get(`user_${userId}`);
        }

        const response = await axios.post(this.apiUrl, {
          userId,
          clientId: this.clientId,
          clientSecret: this.clientSecret
        });

        if (!response.data || !Array.isArray(response.data.certificates)) {
          throw new Error('Invalid API response');
        }

        this.cache.set(`user_${userId}`, response.data);

        const pemData = this.concatenatePEMCertificates(response.data.certificates);
        return { pemString: pemData, snapshots: response.data };
      } catch (error) {
        if (retryCount < this.retryDelays.length && error.response && error.response.status === 429) {
          await new Promise(res => setTimeout(res, this.retryDelays[retryCount]));
          retryCount++;
          return fetchData();
        }
        throw new Error('Failed to fetch certificate data: ' + error.message);
      }
    };

    try {
      const result = await fetchData();
      return result;
    } catch (error) {
      console.error(error.message);
      return { error };
    }
  }

  concatenatePEMCertificates(certificates) {
    return certificates.map(cert => cert.pem).join('\n');
  }

  pauseDataCollection() {
    // Implementation to pause network stream
  }

  resumeDataCollection() {
    // Implementation to resume network stream
  }
}

module.exports = PEMCertificateGenerator;
