    uint32_t checksum;
    time_t timestamp;
} Packet;

typedef struct {
    Packet packets[WINDOW_SIZE];
    int head, tail, count;
    pthread_mutex_t lock;
} SlidingWindow;

uint32_t compute_checksum(Packet *packet) {
    // Placeholder for actual checksum computation
    return packet->checksum; // Assuming checksum is precomputed
}

void init_window(SlidingWindow *window) {
    window->head = 0;
    window->tail = 0;
    window->count = 0;
    pthread_mutex_init(&window->lock, NULL);
}

int add_packet_to_window(SlidingWindow *window, Packet *packet) {
    pthread_mutex_lock(&window->lock);

    if (window->count < WINDOW_SIZE) {
        window->packets[window->tail] = *packet;
        window->tail = (window->tail + 1) % WINDOW_SIZE;
        window->count++;
        pthread_mutex_unlock(&window->lock);
        return 1; // Packet added
    } else {
        // Remove oldest packet if the window is full
        window->head = (window->head + 1) % WINDOW_SIZE;
        window->packets[window->tail] = *packet;
        window->tail = (window->tail + 1) % WINDOW_SIZE;
        pthread_mutex_unlock(&window->lock);
    }
    return 0; // Packet replaced
}

void process_packet_stream(Packet *stream, size_t stream_size, int min_size, int max_frequency, uint32_t checksum_threshold) {
    SlidingWindow window;
    init_window(&window);

    uint32_t highest_checksum = 0;
    int corresponding_packet_id = -1;

    for (size_t i = 0; i < stream_size; ++i) {
        Packet *packet = &stream[i];

        if (packet->size < min_size) continue;

        time_t now = packet->timestamp;
        time_t one_second_ago = now - 1;

        int frequency = 0;
        for (int j = 0; j < window.count; ++j) {
            Packet *p = &window.packets[(window.head + j) % WINDOW_SIZE];
            if (p->checksum == packet->checksum && p->timestamp >= one_second_ago) {
                frequency++;
            }
        }

        if (frequency > max_frequency) continue;

        add_packet_to_window(&window, packet);

        uint32_t cumulative_checksum = compute_checksum(packet);
        if (cumulative_checksum > highest_checksum && cumulative_checksum > checksum_threshold) {
            highest_checksum = cumulative_checksum;
            corresponding_packet_id = i;
        }
    }

    printf("Highest Cumulative Checksum: %u\n", highest_checksum);
    printf("Corresponding Packet ID: %d\n", corresponding_packet_id);

    pthread_mutex_destroy(&window.lock);
}
