class Character {
public:
    enum AttackType { ATTACK_1, ATTACK_2 };

private:
    int id;
    std::unordered_map<AttackType, std::chrono::steady_clock::time_point> cooldowns;
    mutable std::mutex mtx;

public:
    explicit Character(int characterId) : id(characterId) {}

    // Select an attack for the character with dynamic cooldown management
    AttackType select_attack() {
        std::lock_guard<std::mutex> lock(mtx);

        auto now = std::chrono::steady_clock::now();

        // Calculate random cooldown between 5 and 15 seconds
        int cooldown_seconds = get_random_cooldown();

        bool can_use_attack_1 = (cooldowns[ATTACK_1] == std::chrono::steady_clock::time_point() || 
                                 now >= cooldowns[ATTACK_1] + std::chrono::seconds(cooldown_seconds));

        if(can_use_attack_1) {
            cooldowns[ATTACK_1] = now;
            log_attack_selection(ATTACK_1, cooldown_seconds);
            return ATTACK_1;
        }

        bool can_use_attack_2 = (cooldowns[ATTACK_2] == std::chrono::steady_clock::time_point() || 
                                 now >= cooldowns[ATTACK_2] + std::chrono::seconds(cooldown_seconds));

        if(can_use_attack_2) {
            cooldowns[ATTACK_2] = now;
            log_attack_selection(ATTACK_2, cooldown_seconds);
            return ATTACK_2;
        }

        // If both attacks are on cooldown, choose randomly
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);

        AttackType selected_attack = static_cast<AttackType>(dis(gen));
        cooldowns[selected_attack] = now;

        log_attack_selection(selected_attack, cooldown_seconds);
        return selected_attack;
    }

private:
    int get_random_cooldown() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(5, 15);
        return dis(gen);
    }

    void log_attack_selection(AttackType attack_type, int cooldown_seconds) {
        // Implement logging logic here
        // Example: std::cout << "Character ID: " << id << ", Selected Attack: " 
        //                 << (attack_type == ATTACK_1 ? "ATTACK_1" : "ATTACK_2") 
        //                 << ", Cooldown: " << cooldown_seconds << " seconds\n";
    }
};

// Example usage
void character_thread(Character& char_instance) {
    for(int i = 0; i < 10; ++i) {
        char_instance.select_attack();
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

int main() {
    const int num_characters = 1000;
    Character characters[num_characters];

    std::vector<std::thread> threads;

    for(int i = 0; i < num_characters; ++i) {
        threads.emplace_back(character_thread, std::ref(characters[i]));
    }

    for(auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

