#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

// Assuming the shared library provides these functions:
extern int parse_config_file(const char* filepath, Config** config);
extern void release_config(Config* config);

typedef struct {
    char* key;
    char* value;
} KeyValuePair;

typedef struct {
    size_t count;
    KeyValuePair* pairs;
} Config;

typedef struct {
    size_t count;
    Config** configs;
} ConfigList;

ConfigList* load_directory_configs(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) return NULL;

    ConfigList* config_list = malloc(sizeof(ConfigList));
    if (!config_list) {
        closedir(dir);
        return NULL;
    }
    config_list->count = 0;
    config_list->configs = NULL;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);
        struct stat path_stat;
        if (stat(path, &path_stat) != 0) {
            // Handle error
            closedir(dir);
            free(config_list);
            return NULL;
        }

        if (S_ISDIR(path_stat.st_mode)) {
            ConfigList* nested_configs = load_directory_configs(path);
            if (!nested_configs) {
                closedir(dir);
                free(config_list);
                return NULL;
            }
            config_list->configs = realloc(config_list->configs, 
                                          (config_list->count + nested_configs->count) * sizeof(Config*));
            memcpy(config_list->configs + config_list->count, 
                   nested_configs->configs, 
                   nested_configs->count * sizeof(Config*));
            config_list->count += nested_configs->count;

            for (size_t i = 0; i < nested_configs->count; ++i) {
                release_config(nested_configs->configs[i]);
            }
            free(nested_configs->configs);
            free(nested_configs);

        } else if (S_ISREG(path_stat.st_mode)) {
            Config* config = NULL;
            if (parse_config_file(path, &config) != 0) {
                closedir(dir);
                free(config_list->configs);
                free(config_list);
                return NULL;
            }
            config_list->configs = realloc(config_list->configs, 
                                          (config_list->count + 1) * sizeof(Config*));
            config_list->configs[config_list->count] = config;
            ++config_list->count;
        }
    }

    closedir(dir);
    return config_list;
}

void free_config_list(ConfigList* config_list) {
    if (!config_list) return;

    for (size_t i = 0; i < config_list->count; ++i) {
        release_config(config_list->configs[i]);
    }
    free(config_list->configs);
    free(config_list);
}
```

This code provides a function `load_directory_configs` that loads configuration files from a directory recursively. It handles nested directories and uses memory allocation dynamically to store configurations parsed using an external library's parsing functions. The function is designed for extensibility and efficient resource management, with error handling integrated at critical points.']

