```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// A simple representation of a DOM node for illustration purposes.
typedef struct DomNode {
    char* tag; // HTML tag name
    size_t content_length;
    char* content; // Node's content
    int children_count;
    struct DomNode** children;
} DomNode;

// Callback function type definition
typedef int (*filter_callback)(DomNode*);

// A structure to hold shared state for concurrent execution
typedef struct {
    char* buffer;
    size_t current_size;
    size_t size_limit;
    pthread_mutex_t mutex; // Mutex to protect the shared buffer
} SharedState;

int traverse_dom(DomNode* node, SharedState* state, filter_callback callback) {
    if (!node || !callback(node)) return 0;

    pthread_mutex_lock(&state->mutex);

    size_t new_size = state->current_size + node->content_length;
    if (new_size > state->size_limit) {
        pthread_mutex_unlock(&state->mutex);
        return 0; // Skip this node to prevent buffer overflow
    }

    strncat(state->buffer, node->content, node->content_length);

    state->current_size = new_size;

    pthread_mutex_unlock(&state->mutex);

    for (int i = 0; i < node->children_count; ++i) {
        traverse_dom(node->children[i], state, callback);
    }

    return 1;
}

void process_web_page(DomNode* root, size_t size_limit, filter_callback callback) {
    if (!root || !callback) return;

    // Initialize shared state
    SharedState state = {0};
    state.size_limit = size_limit;
    pthread_mutex_init(&state.mutex, NULL);

    // Allocate initial buffer
    state.buffer = malloc(size_limit + 1);
    if (!state.buffer) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    state.current_size = 0;
    state.buffer[0] = '\0';

    traverse_dom(root, &state, callback);

    // Output or process the buffer as needed
    printf("Processed content: %s\n", state.buffer);

    free(state.buffer);
    pthread_mutex_destroy(&state.mutex);
}
```

### Key Points:

- **Thread Safety**: The function uses a mutex to ensure that access to the shared buffer is thread-safe.

- **Memory Management**: The string buffer is dynamically allocated and freed after use. This minimizes heap allocation overhead by reusing the buffer for each traversal.

- **Error Handling**: Out-of-memory conditions are checked, and an appropriate error message is printed.

- **Efficient Traversal**: The function avoids unnecessary recursive calls by skipping nodes that would exceed the size limit when their content is appended to the buffer. 

This implementation should be adapted further based on your specific DOM structure and requirements.']

