#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to hold cached resources for reuse.
typedef struct {
    char *buffer;
} CacheEntry;

#define CACHE_SIZE 10

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;

void init_cache() {
    // Initialize the cache with default values
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].buffer = NULL;
    }
}

CacheEntry* get_cached_entry(size_t size) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].buffer != NULL && strlen(cache[i].buffer) >= size) {
            // Recycle the cached buffer
            return &cache[i];
        }
    }

    // If no suitable cache entry is found, use a new one if possible
    if (cache_count < CACHE_SIZE) {
        CacheEntry *new_entry = &cache[cache_count++];
        new_entry->buffer = malloc(size);
        return new_entry;
    }

    // No free cache entries, allocate a fresh buffer
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    new_entry->buffer = malloc(size);
    return (CacheEntry*) new_entry;
}

void release_cache(CacheEntry *entry) {
    if (entry != NULL && entry->buffer != NULL) {
        free(entry->buffer);
        entry->buffer = NULL;
    }
}

void process_log_file(const char *filename, const char *binary_directory) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    // Buffer for binary data
    char binary_buffer[1024];
    snprintf(binary_buffer, sizeof(binary_buffer), "%s/binary_data.bin", binary_directory);

    FILE *binary_file = fopen(binary_buffer, "rb");
    if (!binary_file) {
        fprintf(stderr, "Failed to open binary file.\n");
        fclose(file);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        CacheEntry *entry = get_cached_entry(len + 1);

        // Store the log entry in the cache buffer
        strncpy(entry->buffer, line, len + 1);

        // Parse and process the entry here
        char *token;
        char *rest = entry->buffer;

        double last_num1 = 0.0, last_num2 = 0.0;
        int field_count = 0;

        while ((token = strtok_r(rest, " ", &rest))) {
            field_count++;
            if (field_count > 1 && field_count == strlen(entry->buffer)) {
                // Assume the last two fields are numerical
                last_num2 = atof(token);
            } else if (field_count > 0) {
                last_num1 = atof(token);
            }
        }

        double average = (last_num1 + last_num2) / 2.0;

        // Replace the last field with the calculated average and print
        char *new_line = strtok(entry->buffer, "\n");
        new_line[strlen(new_line) - strlen(token)] = '\0';
        printf("%s %.2f\n", entry->buffer, average);

        release_cache(entry);
    }

    fclose(binary_file);
    fclose(file);

    // Cleanup any remaining cached entries
    for (int i = 0; i < cache_count; i++) {
        release_cache(&cache[i]);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <log_file> <binary_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_cache();
    process_log_file(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
