#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BASE_NAME_LENGTH 100
#define MAX_FILENAME_LENGTH 255

char* modify_filename_extension(const char* filename, const char* new_type) {
    if (!filename || !new_type) return NULL;

    // Calculate lengths
    size_t len = strlen(filename);
    if (len == 0 || len > MAX_FILENAME_LENGTH) return NULL;

    // Find the last dot in the filename to separate base name and extension
    char* ext_pos = strrchr(filename, '.');
    const char *base_name;
    size_t base_len, ext_len = 0;

    if (ext_pos) {
        base_name = filename;
        ext_len = len - (ext_pos - filename);
        base_len = ext_pos - base_name;
    } else {
        base_name = filename;
        base_len = len;
    }

    // Truncate base name if it exceeds MAX_BASE_NAME_LENGTH
    if (base_len > MAX_BASE_NAME_LENGTH) {
        base_len = MAX_BASE_NAME_LENGTH;
    }

    // Calculate random number of digits based on the base name length
    int num_digits = base_len >= 3 ? rand() % base_len + 1 : 1;

    // Check if new filename will fit within limits
    size_t new_filename_length = base_len + num_digits + strlen(new_type) + 2; // +2 for underscore and null terminator
    if (new_filename_length > MAX_FILENAME_LENGTH) return NULL;

    char* new_filename = malloc(MAX_FILENAME_LENGTH + 1);
    if (!new_filename) return NULL;

    // Construct the new filename
    snprintf(new_filename, MAX_FILENAME_LENGTH + 1, "%.*s_%d.%s", 
             (int)base_len, base_name, num_digits, new_type);

    return new_filename;
}

int main() {
    srand(time(NULL));  // Seed random number generator

    const char* filename = "example_file.txt";
    const char* new_type = "bak";

    char* modified_filename = modify_filename_extension(filename, new_type);
    if (modified_filename) {
        printf("Modified Filename: %s\n", modified_filename);
        free(modified_filename);  // Remember to free the allocated memory
    } else {
        printf("Error modifying filename.\n");
    }

    return 0;
}
