['Below is a simplified version of how you might structure such a C library using OpenSSL for cryptographic operations. This example focuses on providing a basic framework that integrates AES, Camellia, MD5, SHA, and RSA with SHA1. It includes modular APIs, error handling, thread safety, and logging hooks.

```c
#include <openssl/evp.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ERROR(...) fprintf(stderr, __VA_ARGS__)
#define LOG_INFO(...) printf(__VA_ARGS__)

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *md_ctx;
} CryptoContext;

// Function prototypes
int initialize_crypto();
void cleanup_crypto();
CryptoContext* create_context(EVP_CIPHER *cipher, EVP_MD *digest);
void free_context(CryptoContext *ctx);
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len,
                 CryptoContext *ctx, const unsigned char *key, size_t keylen,
                 const unsigned char *iv, size_t ivlen);
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len,
                 CryptoContext *ctx, const unsigned char *key, size_t keylen,
                 const unsigned char *iv, size_t ivlen);
int sign_data(const unsigned char *data, size_t data_len,
              unsigned char *signature, unsigned int *sig_len,
              EVP_PKEY *pkey, EVP_MD *digest);
int verify_signature(const unsigned char *data, size_t data_len,
                     const unsigned char *signature, size_t sig_len,
                     EVP_PKEY *pkey, EVP_MD *digest);

// Mutex for thread safety
pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the cryptographic library
int initialize_crypto() {
    if (EVP_add_cipher(&aes_128_cbc) != 1 || EVP_add_digest(&md5()) != 1) {
        LOG_ERROR("Failed to add AES or MD5\n");
        return -1;
    }
    // Add other ciphers and digests similarly
    return 0;
}

// Cleanup resources used by the cryptographic library
void cleanup_crypto() {
    EVP_cleanup();
}

// Create a new crypto context
CryptoContext* create_context(EVP_CIPHER *cipher, EVP_MD *digest) {
    CryptoContext *ctx = malloc(sizeof(CryptoContext));
    if (!ctx) return NULL;

    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!ctx->cipher_ctx) {
        free(ctx);
        LOG_ERROR("Failed to create cipher context\n");
        return NULL;
    }

    ctx->md_ctx = EVP_MD_CTX_create();
    if (!ctx->md_ctx) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx);
        LOG_ERROR("Failed to create digest context\n");
        return NULL;
    }

    return ctx;
}

// Free a crypto context
void free_context(CryptoContext *ctx) {
    if (ctx) {
        if (ctx->cipher_ctx) EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        if (ctx->md_ctx) EVP_MD_CTX_destroy(ctx->md_ctx);
        free(ctx);
    }
}

// Encrypt data using the specified cipher
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len,
                 CryptoContext *ctx, const unsigned char *key, size_t keylen,
                 const unsigned char *iv, size_t ivlen) {
    pthread_mutex_lock(&crypto_mutex);

    if (!EVP_EncryptInit_ex(ctx->cipher_ctx, ctx->cipher, NULL, key, iv)) {
        LOG_ERROR("Encryption initialization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    int len;
    if (!EVP_EncryptUpdate(ctx->cipher_ctx, ciphertext, &len, plaintext, plaintext_len)) {
        LOG_ERROR("Encryption update failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }
    *ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx->cipher_ctx, ciphertext + len, &len)) {
        LOG_ERROR("Encryption finalization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }
    *ciphertext_len += len;

    pthread_mutex_unlock(&crypto_mutex);
    return 0;
}

// Decrypt data using the specified cipher
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len,
                 CryptoContext *ctx, const unsigned char *key, size_t keylen,
                 const unsigned char *iv, size_t ivlen) {
    pthread_mutex_lock(&crypto_mutex);

    if (!EVP_DecryptInit_ex(ctx->cipher_ctx, ctx->cipher, NULL, key, iv)) {
        LOG_ERROR("Decryption initialization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    int len;
    if (!EVP_DecryptUpdate(ctx->cipher_ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        LOG_ERROR("Decryption update failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }
    *plaintext_len = len;

    if (!EVP_DecryptFinal_ex(ctx->cipher_ctx, plaintext + len, &len)) {
        LOG_ERROR("Decryption finalization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }
    *plaintext_len += len;

    pthread_mutex_unlock(&crypto_mutex);
    return 0;
}

// Sign data using the specified RSA key and digest
int sign_data(const unsigned char *data, size_t data_len,
              unsigned char *signature, unsigned int *sig_len,
              EVP_PKEY *pkey, EVP_MD *digest) {
    pthread_mutex_lock(&crypto_mutex);

    if (!EVP_SignInit_ex(ctx->md_ctx, digest, NULL)) {
        LOG_ERROR("Signature initialization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    if (!EVP_SignUpdate(ctx->md_ctx, data, data_len)) {
        LOG_ERROR("Signature update failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    if (!EVP_SignFinal(ctx->md_ctx, signature, sig_len, pkey)) {
        LOG_ERROR("Signature finalization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    pthread_mutex_unlock(&crypto_mutex);
    return 0;
}

// Verify a signature using the specified RSA key and digest
int verify_signature(const unsigned char *data, size_t data_len,
                     const unsigned char *signature, size_t sig_len,
                     EVP_PKEY *pkey, EVP_MD *digest) {
    pthread_mutex_lock(&crypto_mutex);

    if (!EVP_VerifyInit_ex(ctx->md_ctx, digest, NULL)) {
        LOG_ERROR("Verification initialization failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    if (!EVP_VerifyUpdate(ctx->md_ctx, data, data_len)) {
        LOG_ERROR("Verification update failed\n");
        pthread_mutex_unlock(&crypto_mutex);
        return -1;
    }

    int result = EVP_VerifyFinal(ctx->md_ctx, signature, sig_len, pkey);
    if (result != 1) {
        LOG_ERROR("Verification failed\n");
    }

    pthread_mutex_unlock(&crypto_mutex);
    return result;
}

// Example usage
int main() {
    initialize_crypto();

    // Example: Encrypt and decrypt data
    unsigned char plaintext[] = "This is a test message.";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];
    int ciphertext_len, decryptedtext_len;

    EVP_CIPHER *cipher = EVP_aes_128_cbc();
    const unsigned char key[] = "0123456789abcdef";
    const unsigned char iv[] = "fedcba9876543210";

    CryptoContext *ctx = create_context(cipher, NULL);
    if (!ctx) {
        LOG_ERROR("Failed to create context\n");
        cleanup_crypto();
        return -1;
    }

    encrypt_data(plaintext, strlen((char *)plaintext), ciphertext, &ciphertext_len,
                 ctx, key, sizeof(key), iv, sizeof(iv));
    decrypt_data(ciphertext, ciphertext_len, decryptedtext, &decryptedtext_len,
                 ctx, key, sizeof(key), iv, sizeof(iv));

    printf("Decrypted text is: %s\n", decryptedtext);

    free_context(ctx);
    cleanup_crypto();

    return 0;
}
```

### Key Points:
- **Modular Design**: The library uses OpenSSL's EVP functions to handle different cryptographic algorithms.
- **Thread Safety**: A mutex (`crypto_mutex`) ensures thread safety for concurrent operations.
- **Error Handling**: Each function checks the success of its operations and logs errors if they occur.
- **Logging**: Basic logging is implemented using `fprintf` and `printf`.
- **Dynamic Memory Management**: The library manages memory for cipher and digest contexts dynamically.

### Extensibility:
- New algorithms can be added by registering them with OpenSSL's EVP functions (`EVP_add_cipher`, `EVP_add_digest`) and updating the API to support these new types.

### Documentation & Testing:
- Comprehensive documentation should describe each function, its parameters, return values, and error codes.
- Unit tests should cover all functionalities, including edge cases and error conditions. Consider using a testing framework like CUnit or Check for this purpose.']

