#define KEY_LENGTH 32 // 256 bits for AES-256
#define IV_LENGTH 16  // 128 bits for CBC mode

// Function to derive a key and an IV from the password using PBKDF2-HMAC-SHA256
int derive_key_iv(const char *password, const unsigned char *salt,
                  int salt_len, unsigned char *key, size_t key_len,
                  unsigned char *iv, size_t iv_len) {
    if (!EVP_PBE_derive_KEY_rfc6072(EVP_aes_256_cbc(), EVP_sha256(),
                                    password, strlen(password), 
                                    salt, salt_len, NULL, 0, key, &key_len)) {
        return -1;
    }

    // Generate IV using the derived key and a different HMAC-SHA256
    if (!RAND_bytes(iv, iv_len)) {
        return -1;
    }

    return 0;
}

EVP_CIPHER_CTX* initialize_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Failed to generate random salt\n");
        return NULL;
    }

    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];

    if (derive_key_iv(password, salt, sizeof(salt), key, KEY_LENGTH,
                      iv, IV_LENGTH) != 0) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Key/IV derivation failed\n");
        return NULL;
    }

    int result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (!result) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Encryption initialization failed\n");
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

