int validate_audience(const char *aud) {
    const char *valid_audiences[] = {"app_1", "app_2"};
    size_t count = sizeof(valid_audiences) / sizeof(valid_audiences[0]);
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(aud, valid_audiences[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

int jwt_is_valid(const char *jwt) {
    // Parse JWT manually or use a library to parse the claims
    // For simplicity, we'll assume claims are extracted as key-value pairs in a map-like structure
    const char *claims[] = {"iss=trusted_entity_1", "sub=user_123", "exp=1700000000", "nbf=1600000000", "aud=app_1"};
    int claim_count = sizeof(claims) / sizeof(claims[0]);

    time_t current_time = time(NULL);

    for (int i = 0; i < claim_count; ++i) {
        char *claim = strdup(claims[i]);
        char *key = strtok(claim, "=");
        char *value = strtok(NULL, "=");

        if (!key || !value) continue;

        if (strcmp(key, "iss") == 0 && !validate_issuer(value)) return 0;
        if (strcmp(key, "sub") == 0 && !validate_subject(value)) return 0;
        if (strcmp(key, "exp") == 0) {
            long exp_time = atol(value);
            if (exp_time <= current_time) return 0;
        }
        if (strcmp(key, "nbf") == 0) {
            long nbf_time = atol(value);
            if (nbf_time > current_time) return 0;
        }
        if (strcmp(key, "aud") == 0 && !validate_audience(value)) return 0;

        free(claim);
    }

    return 1;
}

void *validate_jwt_concurrently(void *jwt) {
    int result = jwt_is_valid((const char *)jwt);
    printf("JWT valid: %d\n", result);
    return NULL;
}

int main() {
    pthread_t threads[10];
    const char *jwts[] = {"<token1>", "<token2>", "<token3>"}; // Replace with actual JWT strings

    for (size_t i = 0; i < sizeof(jwts) / sizeof(jwts[0]); ++i) {
        pthread_create(&threads[i], NULL, validate_jwt_concurrently, (void *)jwts[i]);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
