```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageProcessor
{
    private static readonly int MaxMessagesPerKey = 1000; // Define when to rotate keys
    private readonly ConcurrentQueue<string> _messageQueue = new();
    private readonly object _keyLock = new();
    private byte[] _currentKey;
    private long _messageCount = 0;

    public MessageProcessor(byte[] initialKey)
    {
        _currentKey = initialKey ?? throw new ArgumentNullException(nameof(initialKey));
        Task.Run(() => ProcessMessagesAsync());
    }

    public void EnqueueMessage(string base64EncodedMessage)
    {
        _messageQueue.Enqueue(base64EncodedMessage);
    }

    private async Task ProcessMessagesAsync()
    {
        while (true)
        {
            if (_messageQueue.TryDequeue(out var message))
            {
                await Task.Run(() => TryDecryptAndProcessMessage(message));
            }
        }
    }

    private string TryDecryptAndProcessMessage(string base64EncodedMessage)
    {
        try
        {
            var parts = base64EncodedMessage.Split('|');
            if (parts.Length != 3) return "Invalid message format";

            var encryptedDataBase64 = parts[0];
            var ivBase64 = parts[1];
            var mac = parts[2];

            using var hmac = new HMACSHA256(_currentKey);
            var computedMac = hmac.ComputeHash(Encoding.UTF8.GetBytes(encryptedDataBase64 + ivBase64));

            if (!AreMacEqual(mac, computedMac)) return "MAC verification failed";

            var encryptedData = Convert.FromBase64String(encryptedDataBase64);
            var iv = Convert.FromBase64String(ivBase64);

            using var tdes = new TripleDESCryptoServiceProvider
            {
                Key = _currentKey,
                Mode = CipherMode.CBC,
                Padding = PaddingMode.PKCS7
            };

            using var decryptor = tdes.CreateDecryptor(tdes.Key, iv);
            using var msDecrypt = new MemoryStream(encryptedData);
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using var srDecrypt = new StreamReader(csDecrypt);

            var decryptedMessage = srDecrypt.ReadToEnd();
            _messageCount++;
            RotateKeyIfNeeded();

            LogDecryptionAttempt(true, base64EncodedMessage);
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            LogDecryptionAttempt(false, base64EncodedMessage, ex.Message);
            return "Decryption failed";
        }
    }

    private void RotateKeyIfNeeded()
    {
        lock (_keyLock)
        {
            if (_messageCount >= MaxMessagesPerKey)
            {
                _currentKey = GenerateNewKey();
                _messageCount = 0;
            }
        }
    }

    private byte[] GenerateNewKey() => new RngCryptoServiceProvider().GetBytes(24);

    private bool AreMacEqual(byte[] mac1, byte[] mac2)
    {
        for (int i = 0; i < mac1.Length; i++)
        {
            if (mac1[i] != mac2[i]) return false;
        }
        return true;
    }

    private void LogDecryptionAttempt(bool success, string message, string errorMessage = null)
    {
        var logMessage = $"{DateTime.UtcNow}: {success ? "Success" : "Failure"} - Message: {message} {(errorMessage != null ? $", Error: {errorMessage}" : "")}";
        Console.WriteLine(logMessage);
        // Implement additional logging mechanism if needed
    }
}
```

### Key Points:
- **Concurrency**: Utilizes `ConcurrentQueue` for thread-safe message handling and asynchronous processing.
- **MAC Validation**: Uses HMAC-SHA256 to verify the integrity of the message before decryption.
- **Key Rotation**: Automatically rotates the encryption key after a predefined number of messages.
- **Logging**: Logs each decryption attempt with timestamp, success/failure status, and error details if applicable.
- **Error Handling**: Catches exceptions during decryption and logs them for troubleshooting.']

