using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class UniqueIdentifierService
{
    private readonly ConcurrentDictionary<string, string> _cache = new();
    private static readonly object _lockObject = new();

    public string GenerateUniqueId(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        // Check cache first
        if (_cache.TryGetValue(input, out var cachedHash))
        {
            LogOperation(input, cachedHash);
            return cachedHash;
        }

        string hash = GenerateMd5Hash(input);

        // Store in cache
        _cache.TryAdd(input, hash);

        LogOperation(input, hash);
        return hash;
    }

    private string GenerateMd5Hash(string input)
    {
        using (var md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            // Convert to a hex string
            StringBuilder sb = new();
            foreach (byte b in hashBytes)
                sb.Append(b.ToString("x2"));

            return sb.ToString();
        }
    }

    private void LogOperation(string input, string hash)
    {
        // Use async logging to minimize impact on performance
        Task.Run(() => ExternalLoggingService.LogAsync(new HashLog
        {
            Input = input,
            Hash = hash,
            Timestamp = DateTime.UtcNow
        }));
    }

    public class HashLog
    {
        public string Input { get; set; }
        public string Hash { get; set; }
        public DateTime Timestamp { get; set; }
    }
}

public static class ExternalLoggingService
{
    private static readonly SemaphoreSlim _semaphore = new(5); // Limit concurrent log operations

    public static async Task LogAsync(UniqueIdentifierService.HashLog log)
    {
        await _semaphore.WaitAsync();
        try
        {
            // Simulate logging to an external service
            Console.WriteLine($"Logging: {log.Input} => {log.Hash}");
            await Task.Delay(10); // Simulate network latency
        }
        finally
        {
            _semaphore.Release();
        }
    }
}
