using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace AesCbcDecryptionModule
{
    public class DecryptionService
    {
        private readonly byte[] _encryptionKey;
        private readonly ILoggingService _loggingService;

        public DecryptionService(byte[] encryptionKey, ILoggingService loggingService)
        {
            _encryptionKey = encryptionKey ?? throw new ArgumentNullException(nameof(encryptionKey));
            _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
        }

        public async Task<byte[]> DecryptAsync(byte[] ciphertext, byte[] iv)
        {
            if (ciphertext == null || iv == null) throw new ArgumentNullException("Ciphertext or IV cannot be null.");

            using var loggerScope = await _loggingService.BeginLogOperationAsync();

            DateTime startTime = DateTime.UtcNow;

            try
            {
                using var aes = Aes.Create();
                aes.Key = _encryptionKey;
                aes.IV = iv;
                aes.Padding = PaddingMode.PKCS7;

                using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                using var ms = new MemoryStream(ciphertext);
                using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

                var decryptedData = ReadFully(cs);

                if (!VerifyHmac(decryptedData))
                {
                    throw new InvalidOperationException("Decryption failed integrity check.");
                }

                DateTime endTime = DateTime.UtcNow;

                await _loggingService.LogOperationAsync(loggerScope, "Success", startTime, endTime);
                return decryptedData;
            }
            catch (Exception ex)
            {
                DateTime endTime = DateTime.UtcNow;

                await _loggingService.LogErrorAsync(loggerScope, "Failure", ex.Message, startTime, endTime);

                throw new DecryptionException("An error occurred during decryption.", ex);
            }
        }

        private byte[] ReadFully(Stream input)
        {
            using var ms = new MemoryStream();
            input.CopyTo(ms);
            return ms.ToArray();
        }

        private bool VerifyHmac(byte[] decryptedData)
        {
            // Assuming the HMAC is stored at the end of the data, extract and verify
            if (decryptedData.Length < 32) return false;

            byte[] hmacFromData = new byte[32];
            Array.Copy(decryptedData, decryptedData.Length - 32, hmacFromData, 0, 32);

            using var sha256 = SHA256.Create();
            byte[] dataWithoutHmac = new byte[decryptedData.Length - 32];
            Array.Copy(decryptedData, 0, dataWithoutHmac, 0, dataWithoutHmac.Length);

            byte[] computedHmac = hmacFromData(dataWithoutHmac, _encryptionKey);

            return hmacFromData.SequenceEqual(computedHmac);
        }

        private byte[] ComputeHmac(byte[] data, byte[] key)
        {
            using var hmac = new HMACSHA256(key);
            return hmac.ComputeHash(data);
        }
    }

    public interface ILoggingService
    {
        Task<LogScope> BeginLogOperationAsync();
        Task LogOperationAsync(LogScope scope, string status, DateTime startTime, DateTime endTime);
        Task LogErrorAsync(LogScope scope, string status, string errorMessage, DateTime startTime, DateTime endTime);
    }

    public class LogScope { /* Implementation details for tracking log sessions */ }

    public class DecryptionException : Exception
    {
        public DecryptionException(string message, Exception innerException)
            : base(message, innerException) { }
    }
}

