```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Text.Json;

public class CustomDataStructure
{
    // Define your custom data structure here.
    public string Property1 { get; set; }
    public int Property2 { get; set; }

    // Add more properties as needed.
}

public static class DataHandler
{
    public static CustomDataStructure LoadAndDeserialize(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("The specified file does not exist.");

        try
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            using (GZipStream decompressionStream = new GZipStream(fileStream, CompressionMode.Decompress))
            using (StreamReader streamReader = new StreamReader(decompressionStream))
            {
                string jsonData = streamReader.ReadToEnd();

                // Deserialize JSON to CustomDataStructure
                return JsonSerializer.Deserialize<CustomDataStructure>(jsonData);
            }
        }
        catch (IOException ioEx)
        {
            Console.WriteLine($"I/O Error: {ioEx.Message}");
            throw;
        }
        catch (JsonException jsonEx)
        {
            Console.WriteLine($"JSON Deserialization Error: {jsonEx.Message}");
            throw;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
            throw;
        }
    }

    public static void SaveAndCompress(CustomDataStructure data, string filePath)
    {
        try
        {
            using (FileStream fileStream = File.Create(filePath))
            using (GZipStream compressionStream = new GZipStream(fileStream, CompressionMode.Compress))
            using (StreamWriter streamWriter = new StreamWriter(compressionStream))
            {
                // Serialize CustomDataStructure to JSON and write it to the compressed stream
                string jsonData = JsonSerializer.Serialize(data);
                streamWriter.Write(jsonData);
            }
        }
        catch (IOException ioEx)
        {
            Console.WriteLine($"I/O Error: {ioEx.Message}");
            throw;
        }
    }

    public static void Main()
    {
        // Example usage of the LoadAndDeserialize and SaveAndCompress methods
        string filePath = "example.gz";

        // Simulate saving data
        CustomDataStructure exampleData = new CustomDataStructure 
        { 
            Property1 = "Example", 
            Property2 = 42 
        };
        SaveAndCompress(exampleData, filePath);

        // Load and deserialize data
        var loadedData = LoadAndDeserialize(filePath);
        Console.WriteLine($"Property1: {loadedData.Property1}, Property2: {loadedData.Property2}");
    }
}
```

### Justification for Choices:

1. **Serialization Method**: `System.Text.Json` is chosen over `BinaryFormatter` due to its modern support, better security profile (as `BinaryFormatter` is known for potential security vulnerabilities), and cross-platform capabilities.

2. **Compression**: `GZipStream` provides a simple yet effective compression mechanism that balances speed with compression ratio, suitable for both small and large data sizes.

3. **Error Handling**: The function implements robust error handling to catch specific exceptions like I/O errors and JSON parsing issues, making debugging easier.

4. **Scalability & Performance**: By using streams (`FileStream`, `GZipStream`), the code efficiently manages memory usage when dealing with large files, reducing potential disk I/O bottlenecks and minimizing loading times.

5. **Maintainability**: The use of JSON serialization makes it straightforward to extend or modify data structures in the future without tight coupling between components, enhancing maintainability compared to binary formats.

This solution provides a balanced approach focusing on performance, ease of maintenance, and compatibility with modern .NET environments.']

