['Below is a JavaScript implementation using Node.js that meets your requirements:

```javascript
const express = require('express');
const { spawn } = require('child_process');
const redis = require('redis');
const client = redis.createClient(); // Assumes Redis is running on localhost default port

const app = express();
const PORT = 3000;

// Middleware to handle high concurrency and non-blocking requests
app.use((req, res, next) => {
    res.header("Access-Control-Allow-Origin", "*");
    next();
});

// Function to execute shell command without blocking server
async function executeShellCommand(command, args, clientResponse, limit = 10000) {
    return new Promise((resolve, reject) => {
        const child = spawn(command, args);

        let outputData = '';

        // Handle data from stdout and stderr
        child.stdout.on('data', (data) => {
            console.log(`stdout: ${data}`);
            if (outputData.length + data.length > limit) {
                clientResponse.status(413).send('Output too large');
                reject(new Error('Output size exceeded'));
                process.kill(child.pid);
            } else {
                outputData += data;
            }
        });

        child.stderr.on('data', (data) => {
            console.error(`stderr: ${data}`);
            if (outputData.length + data.length > limit) {
                clientResponse.status(413).send('Output too large');
                reject(new Error('Output size exceeded'));
                process.kill(child.pid);
            } else {
                outputData += data;
            }
        });

        // Handle child process exit
        child.on('close', (code) => {
            console.log(`child process exited with code ${code}`);
            if (code === 0) {
                resolve(outputData.toString());
            } else {
                reject(new Error(`Command failed with exit code ${code}`));
            }
        });
    }).catch((error) => {
        // Handle potential errors gracefully
        console.error('Error executing shell command:', error);
        clientResponse.status(500).send('Internal server error');
    });
}

// Endpoint to trigger shell command execution
app.get('/execute-command', async (req, res) => {
    const { command, args } = req.query;

    // Ensure the request is valid and contains necessary parameters
    if (!command || !args) {
        return res.status(400).send('Bad Request: Missing command or arguments');
    }

    try {
        const result = await executeShellCommand(command, args.split(','), res);
        res.send(result);
    } catch (error) {
        console.error(`Failed to execute shell command: ${error.message}`);
        res.status(500).send('Internal server error');
    }
});

app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

### Explanation:

- **Non-blocking Execution**: The `executeShellCommand` function uses `child_process.spawn` for non-blocking execution of shell commands.

- **Concurrency Handling**: Express.js handles concurrent requests efficiently using its built-in mechanisms, and the non-blocking nature of Node.js ensures responsiveness.

- **Output Limitation**: The output size is limited to prevent resource exhaustion, sending a 413 error if exceeded.

- **Logging**: Detailed logging for debugging purposes is included in stdout and stderr handlers.

- **Graceful Error Handling**: Errors during command execution are logged and sent as HTTP 500 responses to the client.

This setup ensures that your Node.js application remains responsive under high concurrency while efficiently managing resources. The function can scale well due to its non-blocking design, making it suitable for integration with Redis and MongoDB in a larger architecture.']

