        with self.lock:
            for _ in range(num_vertices):
                vertex_id = str(uuid.uuid4())
                self.vertices[vertex_id] = {
                    "id": vertex_id,
                    "properties": {},
                    "timestamp": time.time(),
                    "user_id": transaction_id
                }
                self.logger.log(f"Added vertex {vertex_id} to graph.", transaction_id)

    def add_edges(self, transaction_id, edges_data):
        with self.lock:
            for edge in edges_data:
                src_id = edge['src']
                dst_id = edge['dst']
                if src_id in self.vertices and dst_id in self.vertices:
                    edge_id = str(uuid.uuid4())
                    edge_record = {
                        "id": edge_id,
                        "source": src_id,
                        "destination": dst_id,
                        "properties": edge.get('properties', {}),
                        "timestamp": time.time(),
                        "user_id": transaction_id
                    }
                    self.edges.append(edge_record)
                    self.logger.log(f"Added edge {edge_id} between {src_id} and {dst_id}.", transaction_id)

    def set_vertex_property(self, vertex_id, property_name, value):
        with self.lock:
            if vertex_id in self.vertices:
                self.vertices[vertex_id]['properties'][property_name] = value

    def set_edge_property(self, edge_id, property_name, value):
        with self.lock:
            for edge in self.edges:
                if edge['id'] == edge_id:
