        // Handle errors
    }

    int final_len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + *len, &final_len)) {
        // Handle errors
    }

    *len += final_len;
}

void packet_manager_init(PacketManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_PACKETS; ++i) {
        manager->packets[i].id = -1; // Indicates an empty slot
    }
}

int add_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (manager->packets[i].id == -1) {
            manager->packets[i] = (DataPacket){.id = id, .timestamp = now, .status = 1};
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // No space available
}

int update_packet(PacketManager *manager, int id, time_t timestamp, int status) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (manager->packets[i].id == id) {
            manager->packets[i].timestamp = timestamp;
            manager->packets[i].status = status;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

DataPacket* get_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (manager->packets[i].id == id) {
            DataPacket *packet = &manager->packets[i];
            pthread_mutex_unlock(&manager->lock);
            return packet;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Packet not found
}

void purge_expired_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (manager->packets[i].id != -1 &&
            difftime(now, manager->packets[i].timestamp) > EXPIRATION_THRESHOLD) {
            manager->packets[i].id = -1;
            manager->packets[i].status = 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage:
int main() {
    PacketManager manager;
    packet_manager_init(&manager);

    int key[32] = {0}; // Example AES key
    unsigned char iv[16] = {0}; // Example IV

    add_packet(&manager, 1);
    update_packet(&manager, 1, time(NULL), 1);

    DataPacket *packet = get_packet(&manager, 1);
    if (packet) {
        printf("Packet ID: %d\n", packet->id);
    }

    purge_expired_packets(&manager);

    return 0;
}
