#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int key;
    char buffer[BUFFER_SIZE];
} record;

typedef struct {
    record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} RecordStore;

void log_memory_usage(const char* message, size_t used) {
    printf("%s: %zu records allocated\n", message, used);
}

int allocate_record(RecordStore *store, int key, const char *data) {
    pthread_mutex_lock(&store->lock);

    if (store->count >= MAX_RECORDS) {
        pthread_cond_wait(&store->cond_var, &store->lock);
        // Check again after waking up
        if (store->count >= MAX_RECORDS) {
            pthread_mutex_unlock(&store->lock);
            return -1; // No space left
        }
    }

    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&store->lock);
        return -2; // Allocation failed
    }

    new_record->key = key;
    strncpy(new_record->buffer, data, BUFFER_SIZE - 1);
    store->records[store->count++] = new_record;

    log_memory_usage("Allocate", store->count);

    pthread_mutex_unlock(&store->lock);
    return 0; // Success
}

void free_record(RecordStore *store) {
    pthread_mutex_lock(&store->lock);

    if (store->count > 0) {
        record *last = store->records[--store->count];
        free(last);
        pthread_cond_signal(&store->cond_var);
    }

    log_memory_usage("Free", store->count);

    pthread_mutex_unlock(&store->lock);
}

void serialize(RecordStore *store, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&store->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < store->count; ++i) {
        fwrite(store->records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

int deserialize(RecordStore *store, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&store->lock);
    store->count = 0;
    for (size_t i = 0; i < count && store->count < MAX_RECORDS; ++i) {
        record *new_record = malloc(sizeof(record));
        if (!new_record) break;

        fread(new_record, sizeof(record), 1, file);
        store->records[store->count++] = new_record;
    }
    pthread_mutex_unlock(&store->lock);

    fclose(file);
    return 0; // Success
}

void initialize_store(RecordStore *store) {
    pthread_mutex_init(&store->lock, NULL);
    pthread_cond_init(&store->cond_var, NULL);
    store->count = 0;
}

void destroy_store(RecordStore *store) {
    for (size_t i = 0; i < store->count; ++i) {
        free(store->records[i]);
    }
    pthread_mutex_destroy(&store->lock);
    pthread_cond_destroy(&store->cond_var);
}
```

### Design Choices:
- **Thread Safety**: Used `pthread_mutex` and `pthread_cond` to manage concurrent access.
- **Memory Management**: Dynamically allocated each record and used a count to track them. Implemented checks to prevent overflows.
- **Logging**: Simple logging function to track memory usage.
- **Serialization/Deserialization**: Implemented using binary file operations for efficiency.
- **Scalability**: Utilized condition variables to manage growth patterns dynamically.
- **Error Handling**: Provided error codes and checked all resource allocations.
- **Integration**: Used standard C libraries, minimizing dependencies.']

