#include <limits>

class RandomNumberProcessor {
public:
    RandomNumberProcessor() : generator(std::random_device{}()) {}

    ~RandomNumberProcessor() = default;

    void processInput(size_t size) {
        if (size == 0) return;

        std::vector<int> numbers(size);
        int number;
        for (size_t i = 0; i < size; ++i) {
            if (!(std::cin >> number)) {
                std::cerr << "Error: Invalid input encountered." << std::endl;
                exit(EXIT_FAILURE);
            }
            numbers[i] = number;
        }

        int largestNumber = findLargest(numbers);
        std::cout << "The largest number is: " << largestNumber << std::endl;
    }

private:
    std::mt19937 generator;

    int findLargest(const std::vector<int>& numbers) {
        if (numbers.empty()) return std::numeric_limits<int>::min();

        int maxNum = std::numeric_limits<int>::min();
        for (int num : numbers) {
            if (num > maxNum) {
                maxNum = num;
            }
        }

        return maxNum;
    }
};

int main() {
    RandomNumberProcessor processor;

    size_t numberOfIntegers;
    std::cout << "Enter the number of integers: ";
    if (!(std::cin >> numberOfIntegers)) {
        std::cerr << "Error: Invalid input for number of integers." << std::endl;
        return EXIT_FAILURE;
    }

    processor.processInput(numberOfIntegers);

    return 0;
}
