ServiceManager* init_service_manager(const char *config_files[], size_t num_configs) {
    ServiceManager *manager = malloc(sizeof(ServiceManager));
    if (!manager) return NULL;

    manager->services = malloc(num_configs * sizeof(Service *));
    if (!manager->services) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    for (size_t i = 0; i < num_configs; ++i) {
        load_json_config(config_files[i], manager);
    }

    if (!validate_services(manager)) {
        free_service_manager(manager);
        return NULL;
    }

