    return manager;
}

void load_json_config(const char *filename, ServiceManager *manager) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file: %s\n", filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = malloc(length + 1);
    fread(data, 1, length, file);
    fclose(file);
    data[length] = '\0';

    json_object *parsed_json = json_tokener_parse(data);
    free(data);

    if (!json_object_is_type(parsed_json, json_type_array)) {
        fprintf(stderr, "Invalid JSON format in %s\n", filename);
        return;
    }

    size_t array_len = json_object_array_length(parsed_json);
    for (size_t i = 0; i < array_len; ++i) {
        json_object *service_obj = json_object_array_get_idx(parsed_json, i);

        Service *service = malloc(sizeof(Service));
        if (!service) continue;

        service->service_name = strdup(json_object_get_string(json_object_object_get(service_obj, "name")));
        service->port_number = (int)json_object_get_int(json_object_object_get(service_obj, "port"));
        strncpy(service->protocol_type, json_object_get_string(json_object_object_get(service_obj, "protocol")), 3);
        service->callback = mock_callback; // Replace with actual callback assignment logic
        service->priority_level = (int)json_object_get_int(json_object_object_get(service_obj, "priority"));

        manager->services[manager->count++] = service;
    }

    json_object_put(parsed_json);
}

int validate_services(ServiceManager *manager) {
    int port_check[65536] = {0}; // Assuming 16-bit ports

    for (size_t i = 0; i < manager->count; ++i) {
        Service *service = manager->services[i];

        if (!service || service->port_number <= 0 || service->port_number >= 65536) {
            fprintf(stderr, "Invalid port number: %d\n", service->port_number);
            return 0;
        }

        if (port_check[service->port_number]) {
            fprintf(stderr, "Duplicate port detected: %d\n", service->port_number);
            return 0;
        }

        port_check[service->port_number] = 1;
    }

    // Check external dependencies
    if (!check_external_dependencies()) {
        fprintf(stderr, "External dependencies not met.\n");
        return 0;
    }

    return 1;
}

void free_service_manager(ServiceManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        Service *service = manager->services[i];
        if (service) {
            free(service->service_name);
            free(service);
        }
    }
    free(manager->services);
    free(manager);
}

