#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    int status_flag;
    char source_ip[16]; // IPv4 address
} DataPacket;

// Define a node for the linked list
typedef struct PacketNode {
    DataPacket data;
    struct PacketNode *next;
} PacketNode;

// Define the head of the linked list and lock for thread safety
PacketNode *head = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Function to add or update a packet
void addOrUpdatePacket(int packet_id, const char *source_ip, int status_flag) {
    pthread_rwlock_wrlock(&rwlock);

    PacketNode *current = head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            strcpy(current->data.source_ip, source_ip);
            current->data.status_flag = status_flag;
            current->data.timestamp = time(NULL);
            pthread_rwlock_unlock(&rwlock);
            return;
        }
        current = current->next;
    }

    // If not found, create a new node
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    if (!new_node) {
        pthread_rwlock_unlock(&rwlock);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data.packet_id = packet_id;
    strcpy(new_node->data.source_ip, source_ip);
    new_node->data.status_flag = status_flag;
    new_node->data.timestamp = time(NULL);
    new_node->next = head;
    head = new_node;

    pthread_rwlock_unlock(&rwlock);
}

// Function to retrieve a packet by ID
DataPacket *getPacket(int packet_id) {
    pthread_rwlock_rdlock(&rwlock);

    PacketNode *current = head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            DataPacket *packet = &current->data;
            pthread_rwlock_unlock(&rwlock);
            return packet;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&rwlock);
    return NULL;
}

// Function to purge expired packets
void purgeExpiredPackets(time_t expiration_threshold) {
    pthread_rwlock_wrlock(&rwlock);

    PacketNode *current = head;
    PacketNode *prev = NULL;

    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > expiration_threshold) {
            PacketNode *to_delete = current;
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&rwlock);
}

// Function to configure the expiration threshold
void setExpirationThreshold(time_t threshold) {
    // This function can be expanded to read from a config file or environment variable
    static time_t expiration_threshold = 3600; // Default 1 hour

    if (threshold > 0 && threshold < 86400 * 30) { // 30 days max
        expiration_threshold = threshold;
    }
}

// Example usage
int main() {
    setExpirationThreshold(600); // Set expiration to 10 minutes for testing

    addOrUpdatePacket(1, "192.168.0.1", 1);
    DataPacket *packet = getPacket(1);
    if (packet) {
        printf("Packet ID: %d, Source IP: %s\n", packet->packet_id, packet->source_ip);
    }

    // Simulate waiting for expiration
    sleep(601); // Wait longer than the threshold

    purgeExpiredPackets(expiration_threshold);

    return 0;
}
```

This code provides a basic implementation of managing `DataPacket` structures using a linked list with thread safety and an expiration feature. It includes functions to add or update packets, retrieve packets by ID, and purge expired packets based on a configurable threshold.']

