int manage_memory(long limit, size_t key_size) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory
    long *offsets = malloc(limit * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record *records = malloc(key_size * sizeof(record));

    if (!offsets || !keys || !records) {
        log_error("Memory allocation failed");
        pthread_mutex_destroy(&lock);
        free(offsets); free(keys); free(records);
        return 1;
