    // Initialize keys
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = i;
    }
    log_info("Keys initialized");

    // Configuration values
    int random_range = get_config_int("random_range", 100);
    size_t string_length = get_config_int("string_length", 10);

    // Initialize records
    for (size_t i = 0; i < key_size; ++i) {
        records[i].value = rand() % random_range;
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        records[i].string = malloc(string_length);
        if (!records[i].string) {
            log_error("Memory allocation for record string failed");
            error_flag = 1;
            break;
        }

        // Fill with random alphabetic characters
        for (size_t j = 0; j < string_length; ++j) {
            records[i].string[j] = 'A' + rand() % 26;
        }

        if (config_compression_enabled()) {
            compress_string(records[i].string, string_length);
        }
        log_info("Record initialized");
    }

    pthread_mutex_unlock(&lock);

    // Deallocate memory
    free(offsets);
    free(keys);
    for (size_t i = 0; i < key_size; ++i) {
        free(records[i].string);
    }
    free(records);
    pthread_mutex_destroy(&lock);

    return error_flag;
}

int main() {
    int error_occurred = manage_memory(100, 50);
    if (error_occurred) {
        log_error("An error occurred during memory management");
    } else {
        log_info("Memory management completed successfully");
    }
    return 0;
}
