#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    long offset;
    int key;
} OffsetRecord;

typedef struct {
    int value;
    OffsetRecord *offset_record_ptr;
} KeyRecord;

typedef struct {
    int random_value;
} RandomValue;

void manage_memory(int num_offset_records, int num_key_records, int num_random_values) {
    // Step 1: Validate input to prevent integer overflow and excessive memory usage
    if (num_offset_records <= 0 || num_key_records <= 0 || num_random_values <= 0) {
        fprintf(stderr, "Invalid number of records specified.\n");
        return;
    }

    size_t max_size = SIZE_MAX / sizeof(OffsetRecord);
    if ((size_t)num_offset_records > max_size) {
        fprintf(stderr, "Number of offset records exceeds memory limits.\n");
        return;
    }

    size_t key_max_size = SIZE_MAX / sizeof(KeyRecord);
    if ((size_t)num_key_records > key_max_size) {
        fprintf(stderr, "Number of key records exceeds memory limits.\n");
        return;
    }

    // Step 2: Allocate memory for OffsetRecords
    OffsetRecord *offset_records = (OffsetRecord *)malloc(num_offset_records * sizeof(OffsetRecord));
    if (!offset_records) {
        perror("Failed to allocate memory for offset records.");
        return;
    }

    // Step 3: Allocate memory for KeyRecords and associate with OffsetRecords
    KeyRecord *key_records = (KeyRecord *)malloc(num_key_records * sizeof(KeyRecord));
    if (!key_records) {
        perror("Failed to allocate memory for key records.");
        free(offset_records);
        return;
    }

    // Step 4: Error handling and linking KeyRecords to OffsetRecords
    for (int i = 0; i < num_key_records; ++i) {
        if (i >= num_offset_records) {
            fprintf(stderr, "Index %d out of bounds for offset records.\n", i);
            key_records[i].offset_record_ptr = NULL;
        } else {
            key_records[i].offset_record_ptr = &offset_records[i];
        }
    }

    // Step 5: Allocate memory for RandomValues
    RandomValue *random_values = (RandomValue *)malloc(num_random_values * sizeof(RandomValue));
    if (!random_values) {
        perror("Failed to allocate memory for random values.");
        free(offset_records);
        free(key_records);
        return;
    }

    // Step 6: Initialize RandomValues with random numbers between 0 and 100
    srand((unsigned int)time(NULL)); // Seed the random number generator
    for (int i = 0; i < num_random_values; ++i) {
        random_values[i].random_value = rand() % 101;
    }

    // Simulate high-load environment: process all data structures
    printf("Processing %d OffsetRecords, %d KeyRecords, and %d RandomValues...\n", num_offset_records, num_key_records, num_random_values);
    for (int i = 0; i < num_key_records; ++i) {
        if (key_records[i].offset_record_ptr != NULL) {
            printf("KeyRecord[%d] -> Offset: %ld, Key: %d\n", i, key_records[i].offset_record_ptr->offset, key_records[i].offset_record_ptr->key);
        }
    }

    for (int i = 0; i < num_random_values; ++i) {
        printf("RandomValue[%d] -> Value: %d\n", i, random_values[i].random_value);
    }

    // Step 7: Free all allocated memory
    free(offset_records);
    free(key_records);
    free(random_values);

    // Documenting trade-offs:
    // - Memory allocation checks prevent overflow and excessive usage.
    // - Random number generation uses efficient seeding with time(NULL).
    // - The function is designed for easy extension by following similar patterns for additional data structures.
    // - Stress testing can be simulated by increasing the input sizes and observing performance impacts.
}

int main() {
    int num_offset_records, num_key_records, num_random_values;

    printf("Enter number of OffsetRecords: ");
    if (scanf("%d", &num_offset_records) != 1 || num_offset_records <= 0) {
        fprintf(stderr, "Invalid input for number of offset records.\n");
        return EXIT_FAILURE;
    }

    printf("Enter number of KeyRecords: ");
    if (scanf("%d", &num_key_records) != 1 || num_key_records <= 0) {
        fprintf(stderr, "Invalid input for number of key records.\n");
        return EXIT_FAILURE;
    }

    printf("Enter number of RandomValues: ");
    if (scanf("%d", &num_random_values) != 1 || num_random_values <= 0) {
        fprintf(stderr, "Invalid input for number of random values.\n");
        return EXIT_FAILURE;
    }

    manage_memory(num_offset_records, num_key_records, num_random_values);
    return EXIT_SUCCESS;
}
