#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 256

typedef struct {
    char *data;
} Data;

typedef struct {
    int id;
    time_t timestamp;
    int status_flag;
    Data payload;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    double expiration_threshold; // in seconds
} PacketManager;

PacketManager* create_packet_manager(double expiration_threshold) {
    PacketManager *manager = malloc(sizeof(PacketManager));
    manager->packets = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->expiration_threshold = expiration_threshold;
    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    if (manager == NULL) return;

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->packets[i]->payload.data);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Packet* find_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->packets[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void add_packet(PacketManager *manager, Packet *packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 4;
        manager->packets = realloc(manager->packets, new_capacity * sizeof(Packet*));
        manager->capacity = new_capacity;
    }

    packet->id = manager->size + 1; // Simple ID generation
    manager->packets[manager->size++] = packet;

    pthread_mutex_unlock(&manager->lock);
}

void update_packet(PacketManager *manager, Packet *packet) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i]->id == packet->id) {
            memcpy(manager->packets[i], packet, sizeof(Packet));
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

Packet* get_packet(PacketManager *manager, int id) {
    return find_packet(manager, id);
}

void purge_expired_packets(PacketManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size;) {
        Packet *packet = manager->packets[i];
        if (difftime(current_time, packet->timestamp) > manager->expiration_threshold) {
            free(packet->payload.data);
            free(packet);
            memmove(&manager->packets[i], &manager->packets[i + 1],
                    (manager->size - i - 1) * sizeof(Packet*));
            --manager->size;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void serialize_packets(PacketManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->size; ++i) {
        Packet *packet = manager->packets[i];
        fwrite(packet, sizeof(Packet), 1, file);
        size_t data_len = strlen(packet->payload.data) + 1;
        fwrite(&data_len, sizeof(size_t), 1, file);
        fwrite(packet->payload.data, sizeof(char), data_len, file);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void deserialize_packets(PacketManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    manager->packets = realloc(manager->packets, size * sizeof(Packet*));
    manager->capacity = size;
    manager->size = size;

    for (size_t i = 0; i < size; ++i) {
        Packet *packet = malloc(sizeof(Packet));
        fread(packet, sizeof(Packet), 1, file);
        size_t data_len;
        fread(&data_len, sizeof(size_t), 1, file);
        packet->payload.data = malloc(data_len);
        fread(packet->payload.data, sizeof(char), data_len, file);
        manager->packets[i] = packet;
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

int validate_data(const char *data) {
    // Example validation: non-empty and within size limit
    return strlen(data) > 0 && strlen(data) <= MAX_PAYLOAD_SIZE;
}

void read_and_store_valid_data(PacketManager *manager) {
    char input[MAX_PAYLOAD_SIZE + 1];
    while (fgets(input, sizeof(input), stdin)) {
        input[strcspn(input, "\n")] = '\0'; // Remove newline

        if (validate_data(input)) {
            Packet *packet = malloc(sizeof(Packet));
            packet->payload.data = strdup(input);
            packet->timestamp = time(NULL);
            packet->status_flag = 1; // Example status
            add_packet(manager, packet);
        }
    }
}

void print_statistics(const PacketManager *manager) {
    printf("Current packets: %zu\n", manager->size);
    printf("Capacity: %zu\n", manager->capacity);
}

int main() {
    double expiration_threshold = 300.0; // Example threshold of 5 minutes
    PacketManager *manager = create_packet_manager(expiration_threshold);

    read_and_store_valid_data(manager);

    serialize_packets(manager, "packets.dat");
    deserialize_packets(manager, "packets.dat");

    print_statistics(manager);
    purge_expired_packets(manager);
    destroy_packet_manager(manager);

    return 0;
}
