#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LENGTH 1024
#define MEMORY_LIMIT (10 * 1024 * 1024) // Example memory limit, adjust as needed

typedef struct File {
    char path[MAX_PATH_LENGTH];
    time_t last_modified;
} File;

typedef struct DirectoryEntry {
    char name[256]; 
    struct File* files;
    size_t file_count;
    struct DirectoryEntry* next;
} DirectoryEntry;

typedef struct Archive {
    DirectoryEntry* directories;
    size_t directory_count;
} Archive;

Archive archive = {NULL, 0};
size_t total_memory_usage = 0;
size_t max_entries = MEMORY_LIMIT / sizeof(File); // Initial rough estimate

void handle_out_of_memory(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

DirectoryEntry* create_directory_entry(const char* name) {
    DirectoryEntry* dir = (DirectoryEntry*)malloc(sizeof(DirectoryEntry));
    if (!dir) {
        handle_out_of_memory("Failed to allocate memory for directory entry.");
        return NULL;
    }
    strncpy(dir->name, name, sizeof(dir->name) - 1);
    dir->files = NULL;
    dir->file_count = 0;
    dir->next = NULL;
    return dir;
}

File* create_file(const char* path, time_t last_modified) {
    File* file = (File*)malloc(sizeof(File));
    if (!file || total_memory_usage + sizeof(File) > MEMORY_LIMIT) {
        handle_out_of_memory("Failed to allocate memory for file.");
        free(file);
        return NULL;
    }
    strncpy(file->path, path, MAX_PATH_LENGTH - 1);
    file->last_modified = last_modified;
    total_memory_usage += sizeof(File);
    return file;
}

void add_file_to_directory(DirectoryEntry* dir, File* file) {
    if (!dir || !file) return;

    dir->files = (File*)realloc(dir->files, (dir->file_count + 1) * sizeof(File));
    if (!dir->files) {
        handle_out_of_memory("Failed to reallocate memory for files.");
        free(file);
        return;
    }
    dir->files[dir->file_count++] = *file;
}

void insert_file_into_archive(const char* path, time_t last_modified) {
    if (total_memory_usage + sizeof(File) > MEMORY_LIMIT || 
        archive.directory_count * sizeof(DirectoryEntry) + total_memory_usage > MEMORY_LIMIT) {
        handle_out_of_memory("Memory limit exceeded.");
        return;
    }

    // Example: All files go into a single directory
    DirectoryEntry* dir = create_directory_entry("AllFiles");
    if (!dir) return;

    File* file = create_file(path, last_modified);
    if (!file) {
        free(dir);
        return;
    }

    add_file_to_directory(dir, file);

    // Insert into archive structure
    Archive temp_archive = {NULL, 0};
    temp_archive.directories = (DirectoryEntry*)malloc(sizeof(DirectoryEntry));
    if (!temp_archive.directories) {
        handle_out_of_memory("Failed to allocate memory for directories.");
        free(file);
        free(dir);
        return;
    }
    *temp_archive.directories = *dir;

    DirectoryEntry* current = temp_archive.directories;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = archive.directories;
    archive.directories = temp_archive.directories;
    archive.directory_count++;
}

void sort_files_by_last_modified(DirectoryEntry* dir) {
    if (!dir || !dir->files) return;

    size_t n = dir->file_count;
    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = 0; j < n - i - 1; ++j) {
            if (dir->files[j].last_modified > dir->files[j + 1].last_modified) {
                File temp = dir->files[j];
                dir->files[j] = dir->files[j + 1];
                dir->files[j + 1] = temp;
            }
        }
    }
}

void sort_all_files_in_archive() {
    DirectoryEntry* current = archive.directories;
    while (current) {
        sort_files_by_last_modified(current);
        current = current->next;
    }
}

void serialize_archive(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&archive.directory_count, sizeof(size_t), 1, file);

    DirectoryEntry* dir = archive.directories;
    while (dir) {
        size_t name_len = strlen(dir->name);
        fwrite(&name_len, sizeof(size_t), 1, file);
        fwrite(dir->name, sizeof(char), name_len + 1, file);

        fwrite(&dir->file_count, sizeof(size_t), 1, file);

        for (size_t i = 0; i < dir->file_count; ++i) {
            size_t path_len = strlen(dir->files[i].path);
            fwrite(&path_len, sizeof(size_t), 1, file);
            fwrite(dir->files[i].path, sizeof(char), path_len + 1, file);

            fwrite(&dir->files[i].last_modified, sizeof(time_t), 1, file);
        }

        dir = dir->next;
    }

    fclose(file);
}

void deserialize_archive(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    fread(&archive.directory_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < archive.directory_count; ++i) {
        DirectoryEntry* dir = create_directory_entry("");
        if (!dir) continue;

        size_t name_len;
        fread(&name_len, sizeof(size_t), 1, file);
        fread(dir->name, sizeof(char), name_len + 1, file);

        fread(&dir->file_count, sizeof(size_t), 1, file);

        dir->files = (File*)malloc(dir->file_count * sizeof(File));
        if (!dir->files) {
            handle_out_of_memory("Failed to allocate memory for deserialized files.");
            free(dir);
            continue;
        }

        for (size_t j = 0; j < dir->file_count; ++j) {
            size_t path_len;
            fread(&path_len, sizeof(size_t), 1, file);
            fread(dir->files[j].path, sizeof(char), path_len + 1, file);

            fread(&dir->files[j].last_modified, sizeof(time_t), 1, file);
        }

        // Link the new directory entry
        DirectoryEntry* current = archive.directories;
        if (current == NULL) {
            archive.directories = dir;
        } else {
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = dir;
        }
    }

    fclose(file);
}

int main() {
    // Example usage
    insert_file_into_archive("/path/to/file1", time(NULL));
    insert_file_into_archive("/path/to/file2", time(NULL));

    sort_all_files_in_archive();

    serialize_archive("archive.bin");
    deserialize_archive("archive.bin");

    return 0;
}
