#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    int status_flag;
} DataPacket;

typedef struct PacketNode {
    DataPacket data;
    struct PacketNode* next;
} PacketNode;

typedef struct {
    PacketNode* head;
    pthread_mutex_t mutex;
} PacketManager;

void initialize_manager(PacketManager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroy_manager(PacketManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    PacketNode* current = manager->head;
    while (current != NULL) {
        PacketNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void add_packet(PacketManager* manager, DataPacket packet) {
    pthread_mutex_lock(&manager->mutex);

    PacketNode** curr = &manager->head;

    while (*curr != NULL && (*curr)->data.packet_id < packet.packet_id) {
        curr = &((*curr)->next);
    }

    if (*curr != NULL && (*curr)->data.packet_id == packet.packet_id) {
        (*curr)->data = packet;
    } else {
        PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
        if (!new_node) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Handle memory allocation failure gracefully
        }
        new_node->data = packet;
        new_node->next = *curr;
        *curr = new_node;
    }

    pthread_mutex_unlock(&manager->mutex);
}

DataPacket* get_packet(PacketManager* manager, int packet_id) {
    pthread_mutex_lock(&manager->mutex);

    PacketNode* current = manager->head;

    while (current != NULL && current->data.packet_id != packet_id) {
        current = current->next;
    }

    DataPacket* result = NULL;
    if (current != NULL) {
        result = &current->data;
    }

    pthread_mutex_unlock(&manager->mutex);
    return result;
}

void purge_expired_packets(PacketManager* manager, time_t expiration_threshold) {
    pthread_mutex_lock(&manager->mutex);

    PacketNode** curr = &manager->head;

    while (*curr != NULL) {
        if (time(NULL) - (*curr)->data.timestamp > expiration_threshold) {
            PacketNode* to_delete = *curr;
            *curr = (*curr)->next;
            free(to_delete);
        } else {
            curr = &((*curr)->next);
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Example test function
void stress_test() {
    PacketManager manager;
    initialize_manager(&manager);

    for (int i = 0; i < 1000; ++i) {
        DataPacket packet = { .packet_id = rand(), .timestamp = time(NULL), .status_flag = rand() % 2 };
        add_packet(&manager, packet);
    }

    purge_expired_packets(&manager, 60);

    for (int i = 0; i < 1000; ++i) {
        int id = rand();
        DataPacket* pkt = get_packet(&manager, id);
        if (pkt != NULL) {
            printf("Found packet: ID=%d, Timestamp=%ld, Status=%d\n", pkt->packet_id, pkt->timestamp, pkt->status_flag);
        }
    }

    destroy_manager(&manager);
}
```']

