```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Configuration structure
typedef struct {
    int random_range_min;
    int random_range_max;
    int string_length;
    int compress_strings; // 0 for uncompressed, 1 for compressed
} Config;

// Record structure
typedef struct {
    int value;
    char status;
    char *dynamic_string;
} record;

// Global variables for thread safety and error handling
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int error_flag = 0;

// Function prototypes
void load_config(const char *filename, Config *config);
void validate_config(const Config *config);
char random_alpha_char();
char* generate_random_string(int length);
void initialize_arrays(long **offsets, int size_offsets,
                       int **keys, int size_keys,
                       record **records, int size_records, const Config *config);
void free_resources(long *offsets, int size_offsets,
                    int *keys, int size_keys,
                    record *records, int size_records);

// Main function
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config config;
    load_config(argv[1], &config);
    validate_config(&config);

    int size_offsets = 100; // Example size
    int size_keys = 50;     // Example size
    int size_records = 30;  // Example size

    long *offsets;
    int *keys;
    record *records;

    initialize_arrays(&offsets, size_offsets,
                      &keys, size_keys,
                      &records, size_records, &config);

    if (error_flag) {
        fprintf(stderr, "Memory allocation error encountered.\n");
        free_resources(offsets, size_offsets, keys, size_keys, records, size_records);
        return EXIT_FAILURE;
    }

    // Deallocate resources
    free_resources(offsets, size_offsets, keys, size_keys, records, size_records);

    return EXIT_SUCCESS;
}

// Function implementations

void load_config(const char *filename, Config *config) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening config file");
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d %d %d %d", &config->random_range_min,
           &config->random_range_max, &config->string_length,
           &config->compress_strings);

    fclose(file);
}

void validate_config(const Config *config) {
    if (config->random_range_min >= config->random_range_max ||
        config->string_length <= 0 || (config->compress_strings != 0 && config->compress_strings != 1)) {
        fprintf(stderr, "Invalid configuration settings.\n");
        exit(EXIT_FAILURE);
    }
}

char random_alpha_char() {
    char letters[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    return letters[rand() % sizeof(letters) - 1];
}

char* generate_random_string(int length) {
    char *str = malloc(length + 1); // +1 for null-terminator
    if (!str) {
        error_flag = 1;
        return NULL;
    }

    for (int i = 0; i < length; i++) {
        str[i] = random_alpha_char();
    }
    str[length] = '\0';

    return str;
}

void initialize_arrays(long **offsets, int size_offsets,
                       int **keys, int size_keys,
                       record **records, int size_records, const Config *config) {

    pthread_mutex_lock(&lock);

    // Allocate and initialize the 'long' offset array
    *offsets = malloc(size_offsets * sizeof(long));
    if (!*offsets) {
        error_flag = 1;
        pthread_mutex_unlock(&lock);
        return;
    }
    for (int i = 0; i < size_offsets; i++) {
        (*offsets)[i] = i;
    }

    // Allocate and initialize the 'int' key array
    *keys = malloc(size_keys * sizeof(int));
    if (!*keys) {
        error_flag = 1;
        free(*offsets);
        pthread_mutex_unlock(&lock);
        return;
    }
    for (int i = 0; i < size_keys; i++) {
        (*keys)[i] = i;
    }

    // Allocate and initialize the 'record' array
    *records = malloc(size_records * sizeof(record));
    if (!*records) {
        error_flag = 1;
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < size_records; i++) {
        (*records)[i].value = rand() % (config->random_range_max - config->random_range_min + 1) +
                              config->random_range_min;
        (*records)[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        // Handle string allocation
        if (config->compress_strings) {
            char *compressed_str = malloc(3 * (config->string_length + 1)); // Example compression factor
            if (!compressed_str) {
                error_flag = 1;
                break;
            }
            // Assume simple run-length encoding for compression example:
            int j = 0, count;
            (*records)[i].dynamic_string = compressed_str;
            while (j < config->string_length) {
                char ch = random_alpha_char();
                count = rand() % 9 + 1; // Example counts
                snprintf(compressed_str, 3, "%c%d", ch, count);
                compressed_str += 3;
                j += count;
            }
            *compressed_str = '\0';
        } else {
            char *str = generate_random_string(config->string_length);
            if (!str) {
                error_flag = 1;
                break;
            }
            (*records)[i].dynamic_string = str;
        }
    }

    pthread_mutex_unlock(&lock);
}

void free_resources(long *offsets, int size_offsets,
                    int *keys, int size_keys,
                    record *records, int size_records) {
    if (offsets) free(offsets);
    if (keys) free(keys);

    for (int i = 0; i < size_records && records != NULL; i++) {
        if (records[i].dynamic_string) free(records[i].dynamic_string);
    }

    if (records) free(records);
}
```

### Key Points:

1. **Thread Safety**: Mutexes are used to ensure thread safety during memory allocation and initialization.
2. **Error Handling**: An error flag is set on any allocation failure, and resources are freed appropriately upon errors.
3. **Configuration Management**: Configuration values are loaded from a file and validated before use.
4. **Randomness**: Random number generation is seeded once for reproducibility.
5. **Dynamic String Allocation**: Strings are allocated dynamically with either compression or plain random characters.
6. **Resource Cleanup**: All allocated resources are freed at the end of execution to prevent memory leaks.

For actual deployment, consider integrating a more robust logging mechanism and improving error handling based on application requirements.']

