} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficArray;

// Initialize the dynamic array
int init_traffic_array(TrafficArray *array, size_t initial_capacity) {
    array->events = (TrafficEvent *)malloc(initial_capacity * sizeof(TrafficEvent));
    if (!array->events) return -1;
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    log_event("Initialized TrafficArray");
    return 0;
}

// Resize the dynamic array
static void resize_array(TrafficArray *array, size_t new_capacity) {
    TrafficEvent *new_events = (TrafficEvent *)realloc(array->events, new_capacity * sizeof(TrafficEvent));
    if (!new_events) return; // Handle realloc failure gracefully in real applications
    array->events = new_events;
    array->capacity = new_capacity;
}

// Add an event to the dynamic array
int add_traffic_event(TrafficArray *array, TrafficEvent event) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resize_array(array, array->capacity * 2);
    }

    array->events[array->size++] = event;
    log_event("Added Traffic Event");

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Remove an event by index
int remove_traffic_event(TrafficArray *array, size_t index) {
    if (index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);

    memmove(&array->events[index], &array->events[index + 1],
            (array->size - index - 1) * sizeof(TrafficEvent));
    array->size--;

    log_event("Removed Traffic Event");

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Retrieve events within a specified time range
int get_events_in_range(const TrafficArray *array, uint64_t start_time, uint64_t end_time,
                        TrafficEvent **out_events, size_t *out_size) {
