    *out_events = (TrafficEvent *)malloc(count * sizeof(TrafficEvent));
    size_t j = 0;

    for (size_t i = 0; i < array->size; ++i) {
        if (array->events[i].timestamp >= start_time && array->events[i].timestamp <= end_time) {
            (*out_events)[j++] = array->events[i];
        }
    }

    *out_size = count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Serialize the array to disk
int serialize_traffic_array(const TrafficArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

