    resize_array(array, new_size);
    array->size = new_size;

    fread(array->events, sizeof(TrafficEvent), new_size, file);

    fclose(file);
    log_event("Deserialized TrafficArray");

    return 0;
}

// Clean up the dynamic array
void free_traffic_array(TrafficArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->events);
    log_event("Freed TrafficArray");
}
