#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 10 // 10 MB limit for example

struct OffsetRecord {
    long offset;
    int key;
};

struct KeyRecord {
    int value;
    struct OffsetRecord* offset_record;
};

struct RandomValue {
    int value;
};

unsigned int seed = 12345; // Example seed for RNG
pthread_mutex_t rng_lock;

void custom_random(int *num) {
    pthread_mutex_lock(&rng_lock);
    *num = (seed *= 1103515245 + 12345) >> 16 % 101;
    pthread_mutex_unlock(&rng_lock);
}

bool safe_multiply(size_t a, size_t b, size_t* result) {
    if (a == 0 || b == 0) {
        *result = 0;
        return true;
    }
    if ((SIZE_MAX / a) < b) {
        return false;
    }
    *result = a * b;
    return true;
}

bool safe_add(size_t a, size_t b, size_t* result) {
    if (a > SIZE_MAX - b) {
        return false;
    }
    *result = a + b;
    return true;
}

void* manage_memory(void* args) {
    int num_offset_records, num_key_records, num_random_values;

    // Simulated user input
    num_offset_records = 1000; 
    num_key_records = 500;
    num_random_values = 2000;

    size_t offset_record_size = sizeof(struct OffsetRecord);
    size_t key_record_size = sizeof(struct KeyRecord);

    size_t total_memory_needed = 0;

    if (!safe_multiply(num_offset_records, offset_record_size, &total_memory_needed) ||
        !safe_add(total_memory_needed, num_key_records * key_record_size, &total_memory_needed)) {
        printf("Integer overflow detected. Exiting.\n");
        return NULL;
    }

    if (total_memory_needed > MAX_MEMORY_LIMIT) {
        printf("Memory allocation exceeds system limit. Exiting.\n");
        return NULL;
    }

    struct OffsetRecord* offset_records = malloc(total_memory_needed);
    if (!offset_records) {
        perror("Failed to allocate memory for OffsetRecords");
        return NULL;
    }

    struct KeyRecord* key_records = (struct KeyRecord*)((char*)offset_records + num_offset_records * sizeof(struct OffsetRecord));
    if (!key_records) { // This check is redundant due to previous malloc, but it's kept for clarity
        perror("Failed to allocate memory for KeyRecords");
        free(offset_records);
        return NULL;
    }

    struct RandomValue* random_values = malloc(num_random_values * sizeof(struct RandomValue));
    if (!random_values) {
        perror("Failed to allocate memory for RandomValues");
        free(offset_records);
        return NULL;
    }

    // Initialize KeyRecords with corresponding OffsetRecords
    for (int i = 0; i < num_key_records; ++i) {
        int index = rand() % num_offset_records; // Example of random index selection

        if (index >= num_offset_records) { 
            printf("Out-of-bounds access, using fallback mechanism.\n");
            index = num_offset_records - 1;
        }

        key_records[i].offset_record = &((struct OffsetRecord*)offset_records)[index];
    }

    // Initialize RandomValues in parallel
    pthread_t threads[4]; // Example: Using 4 threads for simplicity
    int thread_count = 4;

    void* init_random_values(void* arg) {
        int start_idx = *(int*)arg;
        int end_idx = (start_idx + num_random_values / thread_count > num_random_values) ? 
                      num_random_values : start_idx + num_random_values / thread_count;

        for (int i = start_idx; i < end_idx; ++i) {
            custom_random(&random_values[i].value);
        }

        return NULL;
    }

    int thread_indices[4] = {0, 1000, 2000, 3000};

    pthread_mutex_init(&rng_lock, NULL);

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, init_random_values, &thread_indices[i])) {
            perror("Failed to create thread");
            free(offset_records);
            free(random_values);
            return NULL;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&rng_lock);

    // Free allocated memory
    free(offset_records); 
    free(random_values);

    printf("Memory management completed successfully.\n");

    return NULL;
}

int main() {
    manage_memory(NULL);
    return 0;
}
