int remove_traffic_event_by_id(TrafficEventManager* manager, int unique_id) {
    if (!manager) return -1;

    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->unique_id == unique_id) {
            free(manager->events[i]->metadata_json);
            free(manager->events[i]);

            memmove(&manager->events[i], &manager->events[i + 1], (manager->count - i - 1) * sizeof(TrafficEvent*));
            manager->count--;

            pthread_rwlock_unlock(&manager->lock);
