TrafficEvent* get_events_in_time_range(TrafficEventManager* manager, time_t start, time_t end) {
    if (!manager) return NULL;

    pthread_rwlock_rdlock(&manager->lock);

    size_t num_events = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->timestamp >= start && manager->events[i]->timestamp <= end) {
            num_events++;
        }
    }

    TrafficEvent* result = malloc(num_events * sizeof(TrafficEvent));
    if (!result) {
        pthread_rwlock_unlock(&manager->lock);
        return NULL;
    }

    size_t j = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->timestamp >= start && manager->events[i]->timestamp <= end) {
            result[j++] = *manager->events[i];
        }
