}

void serialize_events(const TrafficEventManager* manager, const char* filename) {
    if (!manager || !filename) return;

    pthread_rwlock_rdlock(&manager->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_rwlock_unlock(&manager->lock);
        return;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        TrafficEvent* event = manager->events[i];
        fprintf(file, "%ld,%s,%d,\"%s\"\n", event->timestamp, event->event_type, event->unique_id, event->metadata_json);
    }

    fclose(file);
    pthread_rwlock_unlock(&manager->lock);
}

int deserialize_events(TrafficEventManager* manager, const char* filename) {
    if (!manager || !filename) return -1;

    pthread_rwlock_wrlock(&manager->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        TrafficEvent* event = malloc(sizeof(TrafficEvent));
        if (!event) break;

        sscanf(line, "%ld,%63[^,],%d,\"%[^\"]\"", &event->timestamp, event->event_type, &event->unique_id, event->metadata_json);

        if (manager->count == manager->capacity) {
            size_t new_capacity = manager->capacity * 2;
            TrafficEvent** new_events = realloc(manager->events, new_capacity * sizeof(TrafficEvent*));
            if (!new_events) break;

            manager->events = new_events;
            manager->capacity = new_capacity;
        }

        manager->events[manager->count++] = event;
    }

    fclose(file);
    pthread_rwlock_unlock(&manager->lock);

    return 0;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_rwlock_t` for efficient read-write locking.
