typedef struct {
    RX_UE_INFORMATION_TAG rxInfo;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint16_t maxRNTI; // To track unique RNTIs
} LinkedList;

LinkedList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

// Function prototypes
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data);
void destroy_list(LinkedList* list);
int insert_unique_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data);
int get_directory_depth(const char* path, int currentDepth);
void serialize_list(LinkedList* list, const char* filename);
int deserialize_list(LinkedList* list, const char* filename);

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void destroy_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

int insert_unique_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (data.rnti > list->maxRNTI && data.rnti <= MAX_NODES) {
        Node** current = &list->head;
        while (*current != NULL) {
            if ((*current)->data.rnti == data.rnti) {
                pthread_mutex_unlock(&list->lock);
                return -1; // RNTI already exists
            }
            current = &(*current)->next;
        }

        Node* new_node = create_node(data);
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }

        *current = new_node;
        list->maxRNTI = (data.rnti > list->maxRNTI) ? data.rnti : list->maxRNTI;

        pthread_mutex_unlock(&list->lock);
        return 0; // Success
    }

    pthread_mutex_unlock(&list->lock);
    return -3; // RNTI out of range or not unique
}

int get_directory_depth(const char* path, int currentDepth) {
    DIR *d;
    struct dirent *dir;
    struct stat fileStat;

    if (stat(path, &fileStat) != 0) {
        perror("Failed to access directory");
        return -1; // Error accessing the directory
    }

    if (!S_ISDIR(fileStat.st_mode)) {
        return currentDepth; // Not a directory
    }

    int maxDepth = currentDepth;

    d = opendir(path);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0)
                continue;

            char newPath[PATH_MAX];
            snprintf(newPath, sizeof(newPath), "%s/%s", path, dir->d_name);

            int depth = get_directory_depth(newPath, currentDepth + 1);
            if (depth > maxDepth) {
                maxDepth = depth;
            }
        }
        closedir(d);
    }

    return maxDepth;
}

void serialize_list(LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

int deserialize_list(LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return -1; // Error opening file
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        if (insert_unique_node(list, data) != 0) {
            fprintf(stderr, "Failed to insert node during deserialization\n");
            destroy_list(list);
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -2; // Failed to insert
        }
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

