typedef struct UserSession {
    int session_id;
    char name[100];
    char email[100];
    time_t last_activity;
    int is_connected;
    struct UserSession *next;
} UserSession;

// Global head of the list
UserSession *session_list = NULL;

// Function to add a new user session
int add_session(int session_id, const char *name, const char *email) {
    if (!authenticate_user(name, email)) {
        log_event("Authentication failed for adding session.");
        return -1;
    }

    UserSession *new_session = (UserSession *)malloc(sizeof(UserSession));
    if (!new_session) {
        log_event("Memory allocation failed for new session.");
        return -1;
    }

    new_session->session_id = session_id;
    strncpy(new_session->name, name, sizeof(new_session->name) - 1);
    strncpy(new_session->email, email, sizeof(new_session->email) - 1);
    time(&new_session->last_activity);
    new_session->is_connected = 1;
    new_session->next = session_list;
    session_list = new_session;

    log_event("New session added.");
    return 0;
}

// Function to update an existing user session
int update_session(int session_id, const char *name, const char *email) {
    UserSession *current = session_list;
    while (current) {
        if (current->session_id == session_id) {
            if (!authenticate_user(name, email)) {
                log_event("Authentication failed for updating session.");
                return -1;
            }

            strncpy(current->name, name, sizeof(current->name) - 1);
            strncpy(current->email, email, sizeof(current->email) - 1);
            time(&current->last_activity);

            log_event("Session updated.");
            return 0;
        }
        current = current->next;
    }

    log_event("Session not found for update.");
    return -1;
}

// Function to retrieve a session by its identifier
UserSession *get_session(int session_id) {
    UserSession *current = session_list;
    while (current) {
        if (current->session_id == session_id) {
            return current;
        }
        current = current->next;
    }

    log_event("Session not found.");
    return NULL;
}

// Function to disconnect inactive sessions
void disconnect_inactive_sessions(time_t inactivity_threshold) {
    time_t now;
    time(&now);
    UserSession *current = session_list;
    UserSession *prev = NULL;

    while (current) {
        if (difftime(now, current->last_activity) > inactivity_threshold && current->is_connected) {
            log_event("Disconnecting inactive session.");

            if (prev) {
                prev->next = current->next;
            } else {
                session_list = current->next;
            }

            UserSession *to_free = current;
            current = current->next;
            free(to_free);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Function to clean up all sessions
void cleanup_sessions() {
    UserSession *current = session_list;
    while (current) {
        UserSession *to_free = current;
        current = current->next;
        free(to_free);
    }
    session_list = NULL;

    log_event("All sessions cleaned up.");
}

// Example usage
int main() {
    add_session(1, "Alice", "alice@example.com");
    add_session(2, "Bob", "bob@example.com");

    update_session(1, "Alice Updated", "alice_updated@example.com");

    UserSession *session = get_session(1);
    if (session) {
        printf("Retrieved session: %d\n", session->session_id);
    }

    disconnect_inactive_sessions(60); // Disconnect sessions inactive for more than 60 seconds

    cleanup_sessions();
    return 0;
}
