#include <filesystem>
#include <fstream>
#include <memory>
#include <algorithm>
#include <zlib.h> // For compression

namespace fs = std::filesystem;

struct FileRecord {
    std::string path;
    uintmax_t size;
    bool is_directory;
};

class FileAnalysisUtility {
public:
    FileAnalysisUtility(size_t max_records, int recursion_depth)
        : maxRecords_(max_records), recursionDepth_(recursion_depth) {}

    void analyzeFiles() {
        std::vector<std::string> file_paths;
        std::string line;

        while (std::getline(std::cin, line)) {
            if (!line.empty()) {
                file_paths.push_back(line);
            }
        }

        for (const auto& path : file_paths) {
            try {
                analyzeDirectory(path, 0);
            } catch (const fs::filesystem_error& e) {
                std::cerr << "Error: " << e.what() << "\n";
            }
        }

        serializeData("output.ser", CompressionLevel::Medium);
    }

private:
    size_t maxRecords_;
    int recursionDepth_;

    std::vector<FileRecord> records_;

    void analyzeDirectory(const fs::path& dir, int current_depth) {
        if (current_depth > recursionDepth_ || records_.size() >= maxRecords_) return;

        try {
            for (const auto& entry : fs::recursive_directory_iterator(dir)) {
                if (records_.size() >= maxRecords_) break;
                FileRecord record = {entry.path().string(), entry.file_size(fs::file_size_option::skip_symlinks), entry.is_directory()};
                records_.push_back(record);
            }
        } catch (const fs::filesystem_error& e) {
            std::cerr << "Error: " << e.what() << "\n";
        }
    }

    void serializeData(const std::string& filename, CompressionLevel level) {
        std::ofstream ofs(filename, std::ios::binary);
        if (!ofs.is_open()) {
            throw std::runtime_error("Failed to open file for writing");
        }

        // Simple serialization logic
        size_t record_count = records_.size();
        ofs.write(reinterpret_cast<const char*>(&record_count), sizeof(record_count));

        for (const auto& record : records_) {
            size_t path_length = record.path.size();
            ofs.write(reinterpret_cast<const char*>(&path_length), sizeof(path_length));
            ofs.write(record.path.c_str(), path_length);

            uintmax_t file_size = record.size;
            ofs.write(reinterpret_cast<const char*>(&file_size), sizeof(file_size));

            bool is_directory = record.is_directory;
            ofs.write(reinterpret_cast<const char*>(&is_directory), sizeof(is_directory));
        }

        // Compression logic (simplified)
        if (level != CompressionLevel::None) {
            compressFile(ofs, level);
        }
    }

    void compressFile(std::ofstream& ofs, CompressionLevel level) {
        // Placeholder for compression logic using zlib
        std::string data; // Collect all serialized data in memory

        uLongf compressed_size = compressBound(data.size());
        std::vector<Bytef> compressed_data(compressed_size);

        if (compress2(compressed_data.data(), &compressed_size, reinterpret_cast<const Bytef*>(data.data()), data.size(), level) != Z_OK) {
            throw std::runtime_error("Compression failed");
        }

        ofs.write(reinterpret_cast<char*>(&compressed_size), sizeof(compressed_size));
        ofs.write(reinterpret_cast<char*>(compressed_data.data()), compressed_size);
    }

public:
    enum class CompressionLevel { None, Low, Medium, High };
};

int main() {
    size_t max_records = 10000;
    int recursion_depth = 5;

    FileAnalysisUtility utility(max_records, recursion_depth);
    utility.analyzeFiles();

    return 0;
}
