    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Utility function prototypes
int simulate_interference(CRC_INDICATION_REL8_TAG* tag);
void verify_crc_integrity(const CRC_INDICATION_REL8_TAG* tag);

// Function to process file and convert JPEG to PDF
int process_file_and_convert(const char* input_filename, size_t list_size, const char* output_filename) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < list_size; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 256; // Simulate valid tag
        pdu_list[i].RNTI = rand() % 1024; // Simulate valid RNTI

        if (simulate_interference(&pdu_list[i].tag) != 0) {
            free(pdu_list);
            fprintf(stderr, "Failed to simulate interference\n");
            return -1;
        }

        verify_crc_integrity(&pdu_list[i].tag);
    }

    // External tool command template
    char command[256];
    snprintf(command, sizeof(command), "jpeg_to_pdf_tool %s %s", input_filename, output_filename);

    pid_t pid = fork();
    if (pid == -1) {
        free(pdu_list);
        perror("fork failed");
        return -1;
    }

    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        _exit(EXIT_FAILURE); // If execl fails
    } else { // Parent process
        int status;
        pid_t result = waitpid(pid, &status, WNOHANG);

        if (result == 0) {
            kill(pid, SIGKILL);
            fprintf(stderr, "Conversion tool timeout\n");
            free(pdu_list);
            return -1;
        } else if (result == pid && !WIFEXITED(status)) {
            kill(pid, SIGKILL);
            waitpid(pid, NULL, 0); // Clean up child process
            fprintf(stderr, "Conversion tool crashed\n");
            free(pdu_list);
            return -1;
        }

        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Conversion failed with status %d\n", WEXITSTATUS(status));
            free(pdu_list);
            return -1;
        }
    }

    free(pdu_list);
    return 0; // Success
}

int simulate_interference(CRC_INDICATION_REL8_TAG* tag) {
    if (!tag) return -1;

    // Simulate interference pattern logic
    tag->CRCFLAG = (rand() % 2) ? 1 : 0;
    return 0;
}

void verify_crc_integrity(const CRC_INDICATION_REL8_TAG* tag) {
    if (!tag) return;

    // Verify integrity logic
    if (tag->CRCFLAG != 1 && tag->CRCFLAG != 0) {
        fprintf(stderr, "Invalid CRCFLAG detected\n");
        exit(EXIT_FAILURE);
    }
}
```']

