    char username[50];
    unsigned char password_hash[SHA256_DIGEST_LENGTH];
    time_t last_updated;
} UserData;

pthread_mutex_t packet_mutex = PTHREAD_MUTEX_INITIALIZER;
DataPacket *packets[MAX_PACKETS];
UserData *users[1000];  // Assuming max users
int packet_count = 0;
int user_count = 0;

void hash_password(const char *password, unsigned char *output) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(output, &sha256);
}

int add_packet(DataPacket *packet, time_t expiration_threshold) {
    pthread_mutex_lock(&packet_mutex);

    // Purge expired packets
    for (int i = 0; i < packet_count; ++i) {
        if (difftime(time(NULL), packets[i]->timestamp) > expiration_threshold) {
            free(packets[i]);
            memmove(&packets[i], &packets[i+1], sizeof(DataPacket *) * (packet_count - i - 1));
            --packet_count;
            --i;
        }
    }

    if (packet_count < MAX_PACKETS) {
        packets[packet_count++] = packet;
        pthread_mutex_unlock(&packet_mutex);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&packet_mutex);
        return -1; // Failure due to capacity limit
    }
}

DataPacket* get_packet_by_id(int id, time_t expiration_threshold) {
    pthread_mutex_lock(&packet_mutex);

    for (int i = 0; i < packet_count; ++i) {
        if (packets[i]->id == id &&
            difftime(time(NULL), packets[i]->timestamp) <= expiration_threshold) {
            pthread_mutex_unlock(&packet_mutex);
            return packets[i];
        }
    }

    pthread_mutex_unlock(&packet_mutex);
    return NULL;
}

void update_packet(int id, const char *new_data) {
    pthread_mutex_lock(&packet_mutex);

    for (int i = 0; i < packet_count; ++i) {
        if (packets[i]->id == id) {
            strncpy(packets[i]->data, new_data, sizeof(packets[i]->data));
            packets[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&packet_mutex);
            return;
        }
    }

    pthread_mutex_unlock(&packet_mutex);
}

void manage_packet_and_user_data(int operation, void *data) {
    // This function would use a switch or if-else to route to specific operations.
    // For simplicity and brevity, only packet-related functions are shown above.

    time_t expiration_threshold = 3600; // Example: 1 hour

    switch (operation) {
        case 1: { // Add packet
            DataPacket *packet = (DataPacket *)data;
            add_packet(packet, expiration_threshold);
            break;
        }
        case 2: { // Get packet by ID
            int id = *(int *)data;
            DataPacket *packet = get_packet_by_id(id, expiration_threshold);
            if (packet) {
                printf("Packet data: %s\n", packet->data);
            } else {
                printf("Packet not found or expired.\n");
            }
            break;
        }
        case 3: { // Update packet
            int *id = (int *)data;
            const char *new_data = *(const char **)((char *)data + sizeof(int));
            update_packet(*id, new_data);
            break;
        }
    }

    // User data management functions would be implemented here.
}

// Example usage:
int main() {
    DataPacket packet1 = { .id = 1, .timestamp = time(NULL) };
    strcpy(packet1.data, "Example Packet Data");
    manage_packet_and_user_data(1, &packet1);

    int id = 1;
    manage_packet_and_user_data(2, &id);

    const char *new_data = "Updated Packet Data";
    manage_packet_and_user_data(3, (void *)&id);
    manage_packet_and_user_data(2, &id);

    pthread_mutex_destroy(&packet_mutex);
    return 0;
}
```

### Key Design Decisions:

