#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define BATCH_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI; // Radio Network Temporary Identifier
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_rnti_unique(List* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0; // RNTI not unique
        current = current->next;
    }
    return 1; // RNTI is unique
}

void insert_entry(List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->count >= MAX_ENTRIES || !is_rnti_unique(list, entry.RNTI)) {
        fprintf(stderr, "Insertion failed: Max entries reached or duplicate RNTI.\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation for node failed");
        return;
    }

    memcpy(&new_node->data, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    log_operation("Inserted entry with RNTI: %u", entry.RNTI);
}

void batch_insert(List* list, NFAPI_CRC_INDICATION_PDU_T entries[], size_t num_entries) {
    if (num_entries > BATCH_SIZE) return;

    for (size_t i = 0; i < num_entries; ++i) {
        insert_entry(list, entries[i]);
    }
}

void log_operation(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stdout, format, args);
    fprintf(stdout, "\n");
    fflush(stdout); // Ensure logs are written immediately
    va_end(args);
}

void cleanup_unused_entries(List* list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL && list->count > 0) {
        if (!entry_is_active(current->data)) { // Define this function based on your criteria
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
            list->count--;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);

    log_operation("Cleaned up unused entries");
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// A stub function for network communication simulation
void handle_network_communication(List* list) {
    // Simulate message-passing and handling
}

int main() {
    List* nfa_list = create_list();
    if (!nfa_list) {
        fprintf(stderr, "Failed to initialize list.\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL)); // Seed for random CRCFLAG

    NFAPI_CRC_INDICATION_PDU_T example_entry = { .RX_UE_INFORMATION_TAG = 1234,
                                                .RNTI = rand() % MAX_ENTRIES + 1,
                                                .CRC_INDICATION_REL8_TAG = rand() % 256,
                                                .CRCFLAG = rand() & 1 };

    batch_insert(nfa_list, &example_entry, 1);

    handle_network_communication(nfa_list);

    cleanup_unused_entries(nfa_list);
    destroy_list(nfa_list);

    return EXIT_SUCCESS;
}
