int allocate_records(record **records, size_t num_records, unsigned int seed, int log_enabled) {
    static FILE *log_file = NULL;
    if (log_enabled && !log_file) {
        log_file = fopen("memory_log.txt", "w");
    }

    pthread_mutex_lock(&mutex);

    record *recs = malloc(num_records * sizeof(record));
    if (!recs) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand(seed);

    long offset_value = 0;
    int key_value = 0;

    for (size_t i = 0; i < num_records; ++i) {
        recs[i].offset = offset_value++;
        recs[i].key = key_value++;

