        recs[i].value = rand() % 1000; 

        recs[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        char *str = malloc(STRING_LENGTH + 1);
        if (!str) {
            fprintf(stderr, "Failed to allocate memory for string at index %zu\n", i);
            free_records(recs, num_records);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        for (size_t j = 0; j < STRING_LENGTH; ++j) {
            str[j] = 'A' + rand() % 26;
        }
        str[STRING_LENGTH] = '\0';

        recs[i].dynamic_string = str;

        if (log_enabled) {
            fprintf(log_file, "%ld: Allocated string '%s' for record at index %zu\n", time(NULL), str, i);
        }
    }

    *records = recs;
    pthread_mutex_unlock(&mutex);

    return 0;
}

void free_records(record *records, size_t num_records) {
    if (!records) return;

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].dynamic_string);
    }

    free(records);
    pthread_mutex_unlock(&mutex);
}

