#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define SESSION_ID_LEN 36
#define IP_ADDR_LEN 16

typedef struct {
    char session_id[SESSION_ID_LEN];
    char client_ip[IP_ADDR_LEN];
    time_t last_activity;
    int ref_count;
    char session_type[32]; // Example metadata field
    char additional_attrs[128]; // Additional attributes, JSON or key-value string
} Session;

typedef struct {
    Session *sessions[MAX_SESSIONS];
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        manager->sessions[i] = NULL;
    }

    return manager;
}

int add_session(SessionManager *manager, Session *session, size_t timeout_seconds) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Limit reached
    }

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (!manager->sessions[i]) {
            manager->sessions[i] = session;
            session->last_activity = time(NULL);
            manager->count++;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Failed to add
}

void expire_sessions(SessionManager *manager, size_t timeout_seconds) {
    pthread_mutex_lock(&manager->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && difftime(current_time, manager->sessions[i]->last_activity) > timeout_seconds) {
            free(manager->sessions[i]);
            manager->sessions[i] = NULL;
            manager->count--;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

Session* find_session_by_id(SessionManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && strcmp(manager->sessions[i]->session_id, session_id) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return manager->sessions[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void serialize_sessions(SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i]) {
            fwrite(manager->sessions[i], sizeof(Session), 1, file);
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void deserialize_sessions(SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    manager->count = count;

    for (size_t i = 0; i < MAX_SESSIONS && i < count; ++i) {
        Session *session = malloc(sizeof(Session));
        if (!session) continue;

        fread(session, sizeof(Session), 1, file);
        manager->sessions[i] = session;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void cleanup_session_manager(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i]) free(manager->sessions[i]);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    SessionManager *manager = create_session_manager(MAX_SESSIONS);

    // Example usage
    Session session1 = {.session_id = "1234567890abcdef1234567890abcdef", .client_ip = "192.168.0.1"};
    add_session(manager, &session1, 300);
    expire_sessions(manager, 60);

    serialize_sessions(manager, "sessions.dat");
    deserialize_sessions(manager, "sessions.dat");

    cleanup_session_manager(manager);

    return 0;
}
```

