typedef enum {
    NFAPI_MSG_TYPE_A,
    NFAPI_MSG_TYPE_B,
    // Add more message types as needed
} NFAPI_MSG_TYPE;

typedef struct {
    int param1;
    float param2;
    char *param3; // Example parameter, modify as necessary
    NFAPI_MSG_TYPE type;
} NFAPI_MESSAGE_T;

typedef struct Node {
    NFAPI_MESSAGE_T message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int count;
} MessageList;

// Initialize the list
MessageList* create_message_list() {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Validate message
int validate_message(NFAPI_MESSAGE_T* msg) {
    // Example validation logic
    if (msg == NULL || msg->type < NFAPI_MSG_TYPE_A || 
        msg->type > NFAPI_MSG_TYPE_B || 
        msg->param3 == NULL) return 0;
    return 1; // Valid message
}

// Add a new message to the list
int add_message(MessageList* list, NFAPI_MESSAGE_T* msg) {
    if (!list || !msg || !validate_message(msg)) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    pthread_mutex_lock(&list->lock);
    newNode->message = *msg;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Remove a message from the list by type and param1
int remove_message(MessageList* list, NFAPI_MSG_TYPE type, int param1) {
    if (!list || !type) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->message.type == type && 
            current->message.param1 == param1) {

            if (prev == NULL) { // Head of the list
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

// Free the message list
void free_message_list(MessageList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    MessageList* msgList = create_message_list();

    NFAPI_MESSAGE_T msg1 = { .param1 = 10, .param2 = 20.5f, .param3 = "Example", .type = NFAPI_MSG_TYPE_A };
    add_message(msgList, &msg1);

    remove_message(msgList, NFAPI_MSG_TYPE_A, 10);

    free_message_list(msgList);

    return 0;
}
