    for (size_t i = 0; i < db->capacity; ++i) {
        free(db->records[i]);
    }

    free(db->offsets);
    free(db->keys);
    free(db->records);

    pthread_mutex_destroy(&db->lock);
    free(db);

    log_message("Database freed");
}

