#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for configuration settings.
typedef struct {
    char *key;
    char *value;
    int version;
} ConfigSetting;

// Define a node for the hash table.
typedef struct HashNode {
    ConfigSetting setting;
    struct HashNode *next;
} HashNode;

#define TABLE_SIZE 101

// Global variables
HashNode **hashTable = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int version_threshold = 1; // Default threshold

// Simple hash function for string keys.
unsigned int hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % TABLE_SIZE;
}

// Logging mechanism
typedef enum { LOG_INFO, LOG_WARN, LOG_ERROR } LogLevel;

void log_message(LogLevel level, const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    const char *level_str;
    switch (level) {
        case LOG_INFO: level_str = "INFO"; break;
        case LOG_WARN: level_str = "WARN"; break;
        case LOG_ERROR: level_str = "ERROR"; break;
    }

    printf("[%s] [%s]: %s\n", timestamp, level_str, message);
}

// Initialize the hash table
void init_hash_table() {
    pthread_mutex_lock(&lock);
    hashTable = (HashNode **)calloc(TABLE_SIZE, sizeof(HashNode *));
    if (!hashTable) {
        log_message(LOG_ERROR, "Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&lock);
}

// Deallocate a node
void free_node(HashNode *node) {
    if (node) {
        free(node->setting.key);
        free(node->setting.value);
        free(node);
    }
}

// Add or update configuration setting
void add_or_update_setting(const char *key, const char *value, int version) {
    pthread_mutex_lock(&lock);

    unsigned int index = hash_function(key);
    HashNode *current = hashTable[index];

    while (current) {
        if (strcmp(current->setting.key, key) == 0) {
            free(current->setting.value);
            current->setting.version = version;
            current->setting.value = strdup(value);
            log_message(LOG_INFO, "Updated configuration setting");
            pthread_mutex_unlock(&lock);
            return;
        }
        current = current->next;
    }

    // Add new node
    HashNode *new_node = (HashNode *)malloc(sizeof(HashNode));
    if (!new_node) {
        log_message(LOG_ERROR, "Failed to allocate memory for new hash node");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->setting.key = strdup(key);
    new_node->setting.value = strdup(value);
    new_node->setting.version = version;
    new_node->next = hashTable[index];
    hashTable[index] = new_node;

    log_message(LOG_INFO, "Added new configuration setting");
    pthread_mutex_unlock(&lock);
}

// Retrieve a configuration setting by key
ConfigSetting *get_setting(const char *key) {
    pthread_mutex_lock(&lock);

    unsigned int index = hash_function(key);
    HashNode *current = hashTable[index];

    while (current) {
        if (strcmp(current->setting.key, key) == 0) {
            ConfigSetting *result = malloc(sizeof(ConfigSetting));
            if (!result) {
                log_message(LOG_ERROR, "Failed to allocate memory for result");
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            *result = current->setting;
            pthread_mutex_unlock(&lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL; // Not found
}

// Invalidate outdated settings
void invalidate_outdated_settings() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode *current = hashTable[i];
        HashNode *prev = NULL;

        while (current) {
            if (current->setting.version < version_threshold) {
                if (prev) {
                    prev->next = current->next;
                } else {
                    hashTable[i] = current->next;
                }
                HashNode *to_delete = current;
                current = current->next;
                free_node(to_delete);
                log_message(LOG_INFO, "Invalidated outdated configuration setting");
            } else {
                prev = current;
                current = current->next;
            }
        }
    }

    pthread_mutex_unlock(&lock);
}

// Free all allocated memory
void cleanup() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode *current = hashTable[i];
        while (current) {
            HashNode *to_delete = current;
            current = current->next;
            free_node(to_delete);
        }
    }
    free(hashTable);
}

// Example usage of the function
void configure_and_manage_storage() {
    init_hash_table();

    // Simulate adding/updating settings
    add_or_update_setting("setting1", "value1", 2);
    add_or_update_setting("setting2", "value2", 3);

    // Retrieve a setting
    ConfigSetting *retrieved = get_setting("setting1");
    if (retrieved) {
        printf("Retrieved: %s=%s, version=%d\n", retrieved->key, retrieved->value, retrieved->version);
        free(retrieved->key);
        free(retrieved->value);
        free(retrieved);
    }

    // Invalidate outdated settings
    invalidate_outdated_settings();

    cleanup();
}

int main() {
    configure_and_manage_storage();
    return 0;
}
```

This code defines a C function `configure_and_manage_storage` that initializes and manages a dynamically allocated hash table for configuration settings. It includes functions to add, update, retrieve, and invalidate settings based on version thresholds. Logging is integrated with different levels of verbosity, and thread safety is ensured using mutex locks. The example usage in the `main` function demonstrates how to use these capabilities.']

