#include <stdio.h>
#include <stdlib.h>
import <string.h>

#define DEFAULT_MEMORY_LIMIT 1000 // Number of events before hitting limit

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double timestamp;
    char* identifier;
    char message[1024];
} Event;

typedef struct {
    char* version;
    char* config_params;
} Metadata;

typedef struct {
    double* timestamps;
    char** identifiers;
    Point* points;
    Event* events;
    Metadata* metadata;
    size_t event_count;
    size_t memory_limit;
} DataStructures;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

DataStructures* initialize_data_structures(size_t size) {
    DataStructures* ds = (DataStructures*)custom_malloc(sizeof(DataStructures));
    ds->memory_limit = DEFAULT_MEMORY_LIMIT > size ? size : DEFAULT_MEMORY_LIMIT;
    ds->event_count = 0;

    // Allocate memory for events
    ds->events = (Event*)custom_malloc(ds->memory_limit * sizeof(Event));

    // Initialize arrays with initial size and allow dynamic growth
    ds->timestamps = (double*)custom_malloc(ds->memory_limit * sizeof(double));
    ds->identifiers = (char**)custom_malloc(ds->memory_limit * sizeof(char*));
    ds->points = (Point*)custom_malloc(ds->memory_limit * sizeof(Point));

    for (size_t i = 0; i < size; ++i) {
        // Initialize identifiers
        ds->identifiers[i] = (char*)custom_malloc(50); // Assuming max identifier length of 50
        sprintf(ds->identifiers[i], "ID_%zu", i);

        // Initialize timestamps and points with some values for demonstration
        ds->timestamps[i] = i * 1.0;
        ds->points[i].x = i * 1.0f;
        ds->points[i].y = (i + 1) * 1.0f;

        // Use a template to fill message
        snprintf(ds->events[i].message, sizeof(ds->events[i].message), 
                 "Event at time %lf with ID %s", ds->timestamps[i], ds->identifiers[i]);
    }

    // Initialize metadata
    ds->metadata = (Metadata*)custom_malloc(sizeof(Metadata));
    ds->metadata->version = strdup("1.0");
    ds->metadata->config_params = strdup("default_config");

    return ds;
}

void serialize_data_structures(const DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    size_t metadata_size = sizeof(Metadata);
    fwrite(&metadata_size, sizeof(size_t), 1, file);

    size_t version_len = strlen(ds->metadata->version) + 1;
    fwrite(&version_len, sizeof(size_t), 1, file);
    fwrite(ds->metadata->version, sizeof(char), version_len, file);

    size_t config_params_len = strlen(ds->metadata->config_params) + 1;
    fwrite(&config_params_len, sizeof(size_t), 1, file);
    fwrite(ds->metadata->config_params, sizeof(char), config_params_len, file);

    fwrite(&ds->event_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < ds->event_count; ++i) {
        fwrite(&(ds->events[i].timestamp), sizeof(double), 1, file);
        size_t id_len = strlen(ds->identifiers[i]) + 1;
        fwrite(&id_len, sizeof(size_t), 1, file);
        fwrite(ds->identifiers[i], sizeof(char), id_len, file);
        fwrite(&(ds->points[i].x), sizeof(float), 1, file);
        fwrite(&(ds->points[i].y), sizeof(float), 1, file);
        fwrite(ds->events[i].message, sizeof(char), strlen(ds->events[i].message) + 1, file);
    }

    fclose(file);
}

DataStructures* deserialize_data_structures(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }

    DataStructures* ds = (DataStructures*)custom_malloc(sizeof(DataStructures));

    size_t metadata_size;
    fread(&metadata_size, sizeof(size_t), 1, file);

    Metadata* metadata = (Metadata*)custom_malloc(metadata_size);

    size_t version_len;
    fread(&version_len, sizeof(size_t), 1, file);
    metadata->version = (char*)custom_malloc(version_len * sizeof(char));
    fread(metadata->version, sizeof(char), version_len, file);

    size_t config_params_len;
    fread(&config_params_len, sizeof(size_t), 1, file);
    metadata->config_params = (char*)custom_malloc(config_params_len * sizeof(char));
    fread(metadata->config_params, sizeof(char), config_params_len, file);

    fread(&ds->event_count, sizeof(size_t), 1, file);

    ds->events = (Event*)custom_malloc(ds->event_count * sizeof(Event));
    ds->identifiers = (char**)custom_malloc(ds->event_count * sizeof(char*));
    ds->points = (Point*)custom_malloc(ds->event_count * sizeof(Point));

    for (size_t i = 0; i < ds->event_count; ++i) {
        fread(&(ds->events[i].timestamp), sizeof(double), 1, file);

        size_t id_len;
        fread(&id_len, sizeof(size_t), 1, file);
        ds->identifiers[i] = (char*)custom_malloc(id_len * sizeof(char));
        fread(ds->identifiers[i], sizeof(char), id_len, file);

        fread(&(ds->points[i].x), sizeof(float), 1, file);
        fread(&(ds->points[i].y), sizeof(float), 1, file);

        ds->events[i].message[0] = '\0'; // Ensure message buffer is initialized
        for (size_t j = 0; ; ++j) {
            if (!fread(&ds->events[i].message[j], sizeof(char), 1, file)) break;
            if (ds->events[i].message[j] == '\0') break;
        }
    }

    fclose(file);

    ds->metadata = metadata;

    return ds;
}

void free_data_structures(DataStructures* ds) {
    for (size_t i = 0; i < ds->event_count; ++i) {
        free(ds->identifiers[i]);
    }

    free(ds->timestamps);
    free(ds->identifiers);
    free(ds->points);
    free(ds->events);

    free(ds->metadata->version);
    free(ds->metadata->config_params);
    free(ds->metadata);

    free(ds);
}

void log_event(const char* message) {
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) return;

    time_t now;
    time(&now);
    fprintf(log_file, "[%s] %s\n", ctime(&now), message);

    fclose(log_file);
}

int main() {
    DataStructures* ds = initialize_data_structures(10);
    serialize_data_structures(ds, "data.bin");

    DataStructures* loaded_ds = deserialize_data_structures("data.bin");

    free_data_structures(ds);
    free_data_structures(loaded_ds);

    log_event("Data structures initialized and serialized successfully.");

    return 0;
}
