#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define PURGE_THRESHOLD_PERCENTAGE 30

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager() {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_or_update_record(RecordManager* manager, int key, long offset, int value_range) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            manager->records[i].offset = offset;
            manager->records[i].value = rand() % value_range + 1;
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record* new_records = realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count].key = key;
    manager->records[manager->count].offset = offset;
    manager->records[manager->count].value = rand() % value_range + 1;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

Record* get_record(RecordManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->records[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void purge_records(RecordManager* manager, long offset_threshold) {
    pthread_mutex_lock(&manager->lock);

    size_t write_index = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset > offset_threshold) {
            if (write_index != i) {
                manager->records[write_index] = manager->records[i];
            }
            ++write_index;
        }
    }

    size_t new_count = write_index;
    if ((100 * new_count / manager->capacity) < PURGE_THRESHOLD_PERCENTAGE) {
        Record* resized_records = realloc(manager->records, (manager->capacity / 2) * sizeof(Record));
        if (resized_records) {
            manager->records = resized_records;
            manager->capacity /= 2;
        }
    }

    manager->count = new_count;

    pthread_mutex_unlock(&manager->lock);
}

// Example usage and testing
int main() {
    srand(time(NULL));

    RecordManager* manager = create_record_manager();
    if (!manager) return -1;

    for (int i = 0; i < 50; ++i) {
        int key = rand() % 20;
        long offset = rand() % 10000;
        add_or_update_record(manager, key, offset, 100);
    }

    Record* record = get_record(manager, 10);
    if (record) {
        printf("Record found: Key=%d, Offset=%ld, Value=%d\n", record->key, record->offset, record->value);
    } else {
        printf("Record not found.\n");
    }

    purge_records(manager, 5000);

    destroy_record_manager(manager);
    return 0;
}
```

This code implements a `RecordManager` that manages dynamically allocated records with thread safety using mutexes. It supports adding/updating records and retrieving them by key. A purging mechanism helps manage memory usage based on an offset threshold, and the array resizes as needed. The main function demonstrates example usage.']

