    int status = resolution_results[index].status_code;
    if (status == 0) {
        unsigned char ip_bytes[4] = {resolution_results[index].ip[0],
                                     resolution_results[index].ip[1],
                                     resolution_results[index].ip[2],
                                     resolution_results[index].ip[3]};
        int last_field_1 = packet->data[-2];
        int last_field_2 = packet->data[-1];

        float average = (last_field_1 + last_field_2 +
                         ip_bytes[0] + ip_bytes[1] + ip_bytes[2] + ip_bytes[3]) / 4.0;

        printf("Processed Packet Average: %f\n", average);
    } else {
        fprintf(stderr, "DNS resolution failed for hostname: %s\n", hostname);
    }

    // Free allocated memory
    free(packet->data);
    return NULL;
}

void start_packet_processing() {
    pthread_t thread_pool[THREAD_POOL_SIZE];

    while (1) {
        Packet *packet = malloc(sizeof(Packet));
        if (!packet) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        int packet_size = recvfrom(0, packet->data, MAX_PACKET_SIZE, 0, NULL, NULL);
        if (packet_size > 0) {
            packet->length = packet_size;

            // Find a free thread and assign the task
            for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
                if (pthread_tryjoin_np(thread_pool[i], NULL)) {  # If not running
                    pthread_create(&thread_pool[i], NULL, process_packet, packet);
                    break;
                }
            }
        }
    }
}

int main() {
    printf("Starting Network Traffic Analysis Tool\n");

    start_packet_processing();

    return 0;
}
```

### Notes:
1. **Dependencies:** This code assumes a POSIX environment and uses `pthread` for threading. DNS resolution is performed using the Python `dns.resolver` as an example, which may need adjustment based on actual C libraries like `libdns`.
2. **Error Handling:** The program includes basic error handling for memory allocation and packet reception.
3. **Concurrency Management:** A thread pool of fixed size (`THREAD_POOL_SIZE`) manages concurrent processing to prevent resource exhaustion.
4. **Performance:** Memory is dynamically allocated per packet and freed after processing to manage system resources efficiently.

This code provides a foundation but will require further adaptation to specific environments, such as including appropriate headers and libraries for DNS resolution in C.']

