#include <stdio.h>
#include <stdlib.h>
import threading

typedef struct {
    int value;
    char buffer[256];
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    int version_id;
    int record_count;
    int max_records;
    pthread_mutex_t lock;
} VersionedDataStructure;

void error_exit(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

VersionedDataStructure* create_structure(int max_records) {
    VersionedDataStructure* vds = (VersionedDataStructure*)malloc(sizeof(VersionedDataStructure));
    if (!vds) error_exit("Failed to allocate memory for VersionedDataStructure");

    pthread_mutex_init(&vds->lock, NULL);

    vds->offsets = (long*)calloc(max_records, sizeof(long));
    if (!vds->offsets) error_exit("Failed to allocate memory for offsets");

    vds->keys = (int*)calloc(max_records, sizeof(int));
    if (!vds->keys) {
        free(vds->offsets);
        error_exit("Failed to allocate memory for keys");
    }

    vds->records = (Record**)calloc(max_records, sizeof(Record*));
    if (!vds->records) {
        free(vds->keys);
        free(vds->offsets);
        error_exit("Failed to allocate memory for records");
    }

    vds->version_id = 0;
    vds->record_count = 0;
    vds->max_records = max_records;

    return vds;
}

void destroy_structure(VersionedDataStructure* vds) {
    pthread_mutex_lock(&vds->lock);

    for (int i = 0; i < vds->record_count; ++i) {
        free(vds->records[i]);
    }

    free(vds->records);
    free(vds->keys);
    free(vds->offsets);

    pthread_mutex_unlock(&vds->lock);
    pthread_mutex_destroy(&vds->lock);
    free(vds);
}

void add_record(VersionedDataStructure* vds, int value) {
    pthread_mutex_lock(&vds->lock);

    if (vds->record_count >= vds->max_records) {
        fprintf(stderr, "Memory limit reached. Cannot add more records.\n");
        pthread_mutex_unlock(&vds->lock);
        return;
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) error_exit("Failed to allocate memory for a new record");

    new_record->value = value;
    snprintf(new_record->buffer, sizeof(new_record->buffer), "Data for %d", value);

    vds->records[vds->record_count] = new_record;
    vds->keys[vds->record_count] = value;
    ++vds->record_count;

    pthread_mutex_unlock(&vds->lock);
}

int find_largest(VersionedDataStructure* vds) {
    pthread_mutex_lock(&vds->lock);

    int largest = (vds->record_count > 0) ? vds->keys[0] : INT_MIN;
    for (int i = 1; i < vds->record_count; ++i) {
        if (vds->keys[i] > largest) {
            largest = vds->keys[i];
        }
    }

    pthread_mutex_unlock(&vds->lock);
    return largest;
}

void serialize(VersionedDataStructure* vds, const char *filename) {
    pthread_mutex_lock(&vds->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) error_exit("Failed to open file for serialization");

    fwrite(&vds->version_id, sizeof(int), 1, file);
    fwrite(&vds->record_count, sizeof(int), 1, file);

    for (int i = 0; i < vds->record_count; ++i) {
        Record* record = vds->records[i];
        int value = record->value;
        fwrite(&value, sizeof(int), 1, file);
        fwrite(record->buffer, sizeof(char), 256, file);
    }

    fclose(file);

    pthread_mutex_unlock(&vds->lock);
}

void deserialize(VersionedDataStructure* vds, const char *filename) {
    pthread_mutex_lock(&vds->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) error_exit("Failed to open file for deserialization");

    fread(&vds->version_id, sizeof(int), 1, file);
    int record_count;
    fread(&record_count, sizeof(int), 1, file);

    if (record_count > vds->max_records) {
        fprintf(stderr, "Deserialization error: Record count exceeds max limit\n");
        fclose(file);
        pthread_mutex_unlock(&vds->lock);
        return;
    }

    for (int i = 0; i < record_count; ++i) {
        int value;
        fread(&value, sizeof(int), 1, file);

        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) error_exit("Failed to allocate memory during deserialization");

        fread(new_record->buffer, sizeof(char), 256, file);
        new_record->value = value;

        vds->records[i] = new_record;
    }

    vds->record_count = record_count;

    fclose(file);

    pthread_mutex_unlock(&vds->lock);
}

void print_largest(VersionedDataStructure* vds) {
    int largest = find_largest(vds);
    printf("The largest integer is: %d\n", largest);
}

int main() {
    VersionedDataStructure* vds = create_structure(100);

    printf("Enter integers (end with -1): ");
    int num;
    while (scanf("%d", &num) && num != -1) {
        add_record(vds, num);
    }

    print_largest(vds);

    serialize(vds, "data.bin");
    deserialize(vds, "data.bin");

    destroy_structure(vds);

    return 0;
}
