int resolve_hostname(char *hostname, u_char ip_address[16]) {
    struct addrinfo hints, *res;
    int err;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Support for IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "Error resolving hostname: %s\n", gai_strerror(err));
        return -1;
    }

    memcpy(ip_address, &((struct sockaddr_in *) res->ai_addr)->sin_addr, sizeof(struct in_addr));
    freeaddrinfo(res);

    return 0; // Success
}

// Function to generate a random record
Record* generate_random_record(long offset) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    record->value = rand() % 1000; // Example range, adjust as needed.
    record->status_indicator = (rand() % 2 == 0) ? 'A' : 'B';

    char *random_str = malloc(11); // Extra space for null terminator
    if (!random_str) {
        perror("Failed to allocate memory for random string");
        free(record);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 10; ++i) {
        random_str[i] = 'a' + rand() % 26;
    }
    random_str[10] = '\0';

    record->random_string = random_str;

    return record;
}

// Function to add a traffic event
void add_traffic_event(const char* timestamp, const char* event_type, long unique_id, const char* metadata) {
    pthread_mutex_lock(&event_mutex);

    if (size >= capacity) {
        capacity *= 2;
        TrafficEvent *new_array = realloc(event_array, sizeof(TrafficEvent) * capacity);
        if (!new_array) {
            perror("Failed to resize event array");
            pthread_mutex_unlock(&event_mutex);
            return;
        }
        event_array = new_array;
    }

    // Initialize JSON object
    json_object *jobj = json_tokener_parse(metadata);

    // Create a new traffic event
    TrafficEvent event;
    event.timestamp = time(NULL);  // Use current timestamp or parse from input
    strncpy(event.event_type, event_type, sizeof(event.event_type));
    event.unique_id = unique_id;

    char *metadata_json_str = strdup(json_object_to_json_string(jobj)); 
    if (!metadata_json_str) {
        perror("Failed to duplicate JSON string");
        json_object_put(jobj);
        pthread_mutex_unlock(&event_mutex);
        return;
    }

    strncpy(event.metadata_json, metadata_json_str, sizeof(event.metadata_json));
    free(metadata_json_str);

    // Add event to array
    event_array[size++] = event;

    json_object_put(jobj);  // Free JSON object

    // Signal any waiting threads
    pthread_cond_signal(&event_cond);

    pthread_mutex_unlock(&event_mutex);
}

// Function to remove a traffic event by unique ID
void remove_traffic_event(long unique_id) {
    pthread_mutex_lock(&event_mutex);

    for (size_t i = 0; i < size; ++i) {
        if (event_array[i].unique_id == unique_id) {
            memmove(&event_array[i], &event_array[i + 1], sizeof(TrafficEvent) * (size - i - 1));
            --size;
            break;
        }
    }

    pthread_mutex_unlock(&event_mutex);
}

// Function to get events in a specified time range
TrafficEvent* get_events_in_range(time_t start_time, time_t end_time) {
    size_t count = 0;

    // Count how many events are within the range
    for (size_t i = 0; i < size; ++i) {
        if (event_array[i].timestamp >= start_time && event_array[i].timestamp <= end_time) {
            ++count;
        }
    }

    TrafficEvent *result = malloc(sizeof(TrafficEvent) * count);
    if (!result) {
        perror("Failed to allocate memory for result");
        return NULL;
    }

    size_t j = 0;
    pthread_mutex_lock(&event_mutex);

    // Fill the result array with events in the specified range
    for (size_t i = 0; i < size; ++i) {
        if (event_array[i].timestamp >= start_time && event_array[i].timestamp <= end_time) {
            result[j++] = event_array[i];
        }
    }

    pthread_mutex_unlock(&event_mutex);

    return result;
}

// Function to serialize and deserialize events
void serialize_events(const char *filename);
void deserialize_events(const char *filename);

int main() {
