#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int signalStrength;
    int noiseLevel;
} MeasurementReport;

typedef struct {
    int UEIdentifier;
    int FrequencyBand;
    MeasurementReport report;
} UeMeasurementData;

typedef struct Node {
    UeMeasurementData data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MeasurementList;

void initializeList(MeasurementList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addOrUpdateUeMeasurementData(MeasurementList* list, UeMeasurementData newData) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.UEIdentifier != newData.UEIdentifier) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Not found, add new entry
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        *newNode = (Node){.data = newData, .next = NULL};

        if (prev == NULL) { // Insert at head
            newNode->next = list->head;
            list->head = newNode;
        } else {
            prev->next = newNode;
            newNode->next = current;
        }
    } else { // Update existing entry
        current->data = newData;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

UeMeasurementData* retrieveUeMeasurementData(MeasurementList* list, int ueIdentifier) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL && current->data.UEIdentifier != ueIdentifier) {
        current = current->next;
    }

    UeMeasurementData* result = NULL;
    if (current != NULL) {
        result = &(current->data);
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

void freeList(MeasurementList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example external data integration function
void updateFrequencyBandWithExternalData(UeMeasurementData* data) {
    // Simulate fetching frequency band information from an external source
    int latencySimulated = 1; // Placeholder for latency simulation

    if (latencySimulated > 0) {
        printf("Retrieved new Frequency Band: %d\n", data->FrequencyBand);
    } else {
        printf("Failed to retrieve Frequency Band due to latency.\n");
    }
}

// Example usage
int main() {
    MeasurementList list;
    initializeList(&list);

    UeMeasurementData sampleData = {1, 900, {100, -50}};
    addOrUpdateUeMeasurementData(&list, sampleData);

    UeMeasurementData* retrievedData = retrieveUeMeasurementData(&list, 1);
    if (retrievedData) {
        printf("UE ID: %d, Frequency Band: %d\n", retrievedData->UEIdentifier, retrievedData->FrequencyBand);
        updateFrequencyBandWithExternalData(retrievedData);
    }

    freeList(&list);

    return 0;
}
