#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for records
typedef struct {
    int value;
    char *str;
} record;

// Function prototypes
int validate_key(int key);
void log_event(const char* event, const char* details);

// Global variables for logging and external data management
volatile int logging_enabled = 0;
pthread_mutex_t active_keys_lock;
pthread_mutex_t logging_lock;
int *active_keys; // External data source pointer (should be initialized elsewhere)
size_t num_active_keys;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t peak_memory_usage;
} component_data;

component_data* init_components(size_t num_offsets, size_t num_keys,
                                int min_value, int max_value, size_t memory_limit,
                                unsigned int seed) {
    pthread_mutex_init(&active_keys_lock, NULL);
    pthread_mutex_init(&logging_lock, NULL);

    component_data *data = malloc(sizeof(component_data));
    if (!data) return NULL;

    data->peak_memory_usage = 0;

    // Allocate offsets
    long *offsets = calloc(num_offsets, sizeof(long));
    if (!offsets) goto error_cleanup;

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }

    data->offsets = offsets;

    // Allocate keys and validate
    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) goto error_cleanup;

    size_t unique_key_count = 0;
    while (unique_key_count < num_keys) {
        int key = rand_r(&seed) % 10000; // Example range for potential keys

        pthread_mutex_lock(&active_keys_lock);
        if (!validate_key(key)) {
            pthread_mutex_unlock(&active_keys_lock);
            continue;
        }
        pthread_mutex_unlock(&active_keys_lock);

        keys[unique_key_count++] = key;

        log_event(logging_enabled ? "Allocate" : "", "Key");
    }

    data->keys = keys;

    // Determine the number of records
    size_t num_records = (num_offsets < num_keys) ? num_offsets : num_keys;

    // Allocate records
    record *records = malloc(num_records * sizeof(record));
    if (!records) goto error_cleanup;

    for (size_t i = 0; i < num_records; ++i) {
        int value_range = max_value - min_value + 1;
        records[i].value = rand_r(&seed) % value_range + min_value;

        char *str = malloc(11); // 10 chars + null terminator
        if (!str || (data->peak_memory_usage + 11 > memory_limit)) {
            free(str);
            goto error_cleanup;
        }

        for (int j = 0; j < 10; ++j) {
            str[j] = 'A' + (rand_r(&seed) % 26); // Random alphabetic characters
        }
        str[10] = '\0';

        records[i].str = str;

        log_event(logging_enabled ? "Allocate" : "", "Record String");
    }

    data->records = records;

    return data;

error_cleanup:
    if (data->offsets) free(data->offsets);
    if (data->keys) free(data->keys);
    if (data->records) {
        for (size_t i = 0; i < ((num_offsets < num_keys) ? num_offsets : num_keys); ++i) {
            free(data->records[i].str);
        }
        free(data->records);
    }
    free(data);

    pthread_mutex_destroy(&active_keys_lock);
    pthread_mutex_destroy(&logging_lock);

    return NULL;
}

void free_components(component_data *data) {
    if (!data) return;

    if (data->offsets) {
        free(data->offsets);
        log_event(logging_enabled ? "Free" : "", "Offsets");
    }
    if (data->keys) {
        free(data->keys);
        log_event(logging_enabled ? "Free" : "", "Keys");
    }
    if (data->records) {
        for (size_t i = 0; i < ((data->offsets == NULL || data->keys == NULL) 
                               ? 0 : (((long *)data->offsets)[0] <= ((int*)data->keys)[0] ?
                                      (long)(*(data->offsets)) : (*(data->keys)))) ; ++i) {
            free(data->records[i].str);
        }
        free(data->records);
        log_event(logging_enabled ? "Free" : "", "Records");
    }

    free(data);

    pthread_mutex_destroy(&active_keys_lock);
    pthread_mutex_destroy(&logging_lock);
}

// Simulate a key validation function
int validate_key(int key) {
    // Lock to ensure thread safety
    pthread_mutex_lock(&active_keys_lock);
    for (size_t i = 0; i < num_active_keys; ++i) {
        if (key == active_keys[i]) {
            pthread_mutex_unlock(&active_keys_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&active_keys_lock);

    return 1;
}

// Logging function
void log_event(const char* event, const char* details) {
    if (!logging_enabled) return;

    time_t now = time(NULL);
    pthread_mutex_lock(&logging_lock);
    printf("[%s] Event: %s, Details: %s\n", ctime(&now), event, details);
    pthread_mutex_unlock(&logging_lock);
}
```

### Key Points:
- **Thread Safety:** Mutexes are used to ensure thread safety during key validation and logging.
- **Memory Management:** The function ensures all allocated memory is freed in case of an error, avoiding leaks.
- **Logging:** Simple conditional logging based on a global flag, with timestamps for debugging purposes.
- **Randomness:** Uses `rand_r()` for reproducibility across threads with a seed.']

