    for (size_t i = 1; i < n; ++i) {
        if (pdus[i].timestamp <= pdus[i - 1].timestamp) {
            fprintf(stderr, "Error: Non-monotonic timestamps detected.\n");
            return -1;
        }
    }
    return 0;
