['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

void initialize_pool(MemoryPool *pool, size_t initial_capacity) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->offsets = malloc(pool->capacity * sizeof(long));
    pool->keys = malloc(pool->capacity * sizeof(int));
    pool->records = malloc(pool->capacity * sizeof(Record *));

    if (!pool->offsets || !pool->keys || !pool->records) {
        fprintf(stderr, "Error: Memory allocation failed for memory pool\n");
        exit(EXIT_FAILURE);
    }
}

void free_pool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]);
    }
    free(pool->records);
}

int add_record(MemoryPool *pool, int value, const char *charset, size_t charset_size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        fprintf(stderr, "Error: Maximum record capacity reached\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Error: Memory allocation failed for a new record\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    record->value = value;
    srand(time(NULL) ^ (size_t)pthread_self());
    for (int i = 0; i < BUFFER_SIZE - 1; ++i) {
        record->buffer[i] = charset[rand() % charset_size];
    }
    record->buffer[BUFFER_SIZE - 1] = '\0';

    pool->offsets[pool->count] = rand(); // Random offset for illustration
    pool->keys[pool->count] = value;
    pool->records[pool->count] = record;
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void resize_pool(MemoryPool *pool, size_t new_capacity) {
    long *new_offsets = realloc(pool->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(pool->keys, new_capacity * sizeof(int));
    Record **new_records = realloc(pool->records, new_capacity * sizeof(Record *));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Error: Memory reallocation failed for memory pool\n");
        exit(EXIT_FAILURE);
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;
    pool->capacity = new_capacity;
}

void serialize_pool(const MemoryPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for serialization\n");
        return;
    }

    pthread_mutex_lock(&pool->lock);
    fwrite(&pool->count, sizeof(size_t), 1, file);
    fwrite(pool->offsets, sizeof(long), pool->count, file);
    fwrite(pool->keys, sizeof(int), pool->count, file);

    for (size_t i = 0; i < pool->count; ++i) {
        fwrite(&pool->records[i]->value, sizeof(int), 1, file);
        fwrite(pool->records[i]->buffer, BUFFER_SIZE, 1, file);
    }
    pthread_mutex_unlock(&pool->lock);

    fclose(file);
}

void deserialize_pool(MemoryPool *pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for deserialization\n");
        return;
    }

    pthread_mutex_lock(&pool->lock);
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    resize_pool(pool, count);
    pool->count = count;

    fread(pool->offsets, sizeof(long), count, file);
    fread(pool->keys, sizeof(int), count, file);

    for (size_t i = 0; i < count; ++i) {
        pool->records[i] = malloc(sizeof(Record));
        if (!pool->records[i]) {
            fprintf(stderr, "Error: Memory allocation failed during deserialization\n");
            fclose(file);
            pthread_mutex_unlock(&pool->lock);
            return;
        }

        fread(&pool->records[i]->value, sizeof(int), 1, file);
        fread(pool->records[i]->buffer, BUFFER_SIZE, 1, file);
    }
    pthread_mutex_unlock(&pool->lock);

    fclose(file);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

