} CRC_Indication_Array;

int init_crc_array(CRC_Indication_Array *crc_array, size_t initial_capacity) {
    crc_array->capacity = initial_capacity;
    crc_array->size = 0;
    pthread_mutex_init(&crc_array->mutex, NULL);

    void *ptr;
    if (posix_memalign((void**)&crc_array->array, 16, crc_array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        return -1; // Allocation failed
    }

    for (size_t i = 0; i < crc_array->capacity; ++i) {
        crc_array->array[i].CRCFLAG = rand(); // Randomly generate CRCFLAG
    }

    return 0;
}

void free_crc_array(CRC_Indication_Array *crc_array) {
    pthread_mutex_lock(&crc_array->mutex);
    if (crc_array->array != NULL) {
        free(crc_array->array);
        crc_array->array = NULL;
    }
    pthread_mutex_unlock(&crc_array->mutex);
    pthread_mutex_destroy(&crc_array->mutex);
}

int add_crc_pdu(CRC_Indication_Array *crc_array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&crc_array->mutex);

    if (crc_array->size >= crc_array->capacity) {
        size_t new_capacity = crc_array->capacity * 2;
        if (new_capacity > MAX_SIZE) {
            // Handle exceeding max capacity
            pthread_mutex_unlock(&crc_array->mutex);
            return -1; // Exceeded maximum allowable size
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array;
        if (posix_memalign((void**)&new_array, 16, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -1; // Allocation failed
        }

        memcpy(new_array, crc_array->array, crc_array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        free(crc_array->array);
        crc_array->array = new_array;
        crc_array->capacity = new_capacity;
    }

    crc_array->array[crc_array->size++] = pdu;

    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}
