ENBList* create_list() {
    ENBList* list = malloc(sizeof(ENBList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_list(ENBList* list) {
    ListNode *current = list->head, *next_node;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(ENBList* list, LTE_ENBCONTEXTINFO new_context) {
    ListNode **indirect = &list->head;

    pthread_mutex_lock(&list->lock);

    while (*indirect != NULL) {
        if ((*indirect)->data.ENB_ID == new_context.ENB_ID) {
            printf("Error: Duplicate ENB_ID encountered.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        indirect = &(*indirect)->next;
    }

    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        printf("Memory allocation failed for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = new_context;
    new_node->next = NULL;

    *indirect = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_from_list(ENBList* list, int enb_id) {
    ListNode **indirect = &list->head;

    pthread_mutex_lock(&list->lock);

    while (*indirect != NULL) {
        if ((*indirect)->data.ENB_ID == enb_id) {
            ListNode *to_free = *indirect;
            *indirect = (*indirect)->next;
            free(to_free);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        indirect = &(*indirect)->next;
    }

    printf("Error: ENB_ID not found.\n");
    pthread_mutex_unlock(&list->lock);
    return -1;
}

int update_s1ap_status(ENBList* list, unsigned long teid, char new_status) {
    ListNode *current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (current->data.S1AP_TEID == teid) {
            current->data.s1ap_status = new_status;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    printf("Error: S1AP_TEID not found.\n");
    pthread_mutex_unlock(&list->lock);
    return -1;
}

LTE_ENBCONTEXTINFO* find_latest_by_teid(ENBList* list, unsigned long teid) {
    ListNode *current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (current->data.S1AP_TEID == teid) {
            pthread_mutex_unlock(&list->lock);
            return &(current->data);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void check_s1ap_status_integrity(ENBList* list, char expected_status) {
