#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <sys/stat.h>
#include <time.h>

// Define a structure for file metadata
typedef struct {
    char *path;
    char type[20];  // Regular, Directory, Archive, Symlink
    time_t last_modified;
    size_t size;
} FileMetadata;

// Node in the linked list
typedef struct ListNode {
    FileMetadata data;
    struct ListNode *next;
} ListNode;

// Linked List structure
typedef struct {
    ListNode *head;
    int count;
    pthread_mutex_t lock;
    size_t limit;  // Maximum allowed memory usage in bytes
} LinkedList;

// Function to create a new list node
ListNode* create_node(const char *path, const char *type, time_t last_modified, size_t size) {
    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return NULL;

    node->data.path = strdup(path);
    strncpy(node->data.type, type, sizeof(node->data.type) - 1);
    node->data.last_modified = last_modified;
    node->data.size = size;

    node->next = NULL;
    return node;
}

// Function to initialize the linked list
LinkedList* create_list(size_t limit) {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->limit = limit;

    return list;
}

// Function to check the current memory usage of the linked list
size_t get_current_usage(LinkedList *list) {
    size_t total_size = sizeof(LinkedList);
    ListNode *current = list->head;

    while (current != NULL) {
        total_size += sizeof(ListNode) + strlen(current->data.path) + 1;
        current = current->next;
    }

    return total_size;
}

// Function to add a file path to the linked list
int add_to_list(LinkedList *list, const char *path, const char *type, time_t last_modified, size_t size) {
    pthread_mutex_lock(&list->lock);

    if (get_current_usage(list) + sizeof(ListNode) + strlen(path) + 1 > list->limit) {
        fprintf(stderr, "Memory limit reached. Cannot add more entries.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    ListNode *new_node = create_node(path, type, last_modified, size);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node: %s\n", strerror(errno));
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    // Log the insertion operation
    printf("Added %s of type %s to the list.\n", path, type);
    return 0;
}

// Function to serialize the linked list into a file
int serialize_list(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(FileMetadata), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    printf("List serialized to %s.\n", filename);
    return 0;
}

// Function to deserialize the linked list from a file
int deserialize_list(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading: %s\n", strerror(errno));
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    list->head = NULL; // Clear the current list
    FileMetadata data;

    while (fread(&data, sizeof(FileMetadata), 1, file)) {
        add_to_list(list, data.path, data.type, data.last_modified, data.size);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    printf("List deserialized from %s.\n", filename);
    return 0;
}

// Function to print the summary report
void generate_summary(LinkedList *list) {
    int file_count = 0, dir_count = 0, archive_count = 0, symlink_count = 0;
    size_t total_size = 0;

    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.type, "Regular") == 0) file_count++;
        else if (strcmp(current->data.type, "Directory") == 0) dir_count++;
        else if (strcmp(current->data.type, "Archive") == 0) archive_count++;
        else if (strcmp(current->data.type, "Symlink") == 0) symlink_count++;

        total_size += current->data.size;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    printf("Summary Report:\n");
    printf("Total Files: %d\n", file_count);
    printf("Total Directories: %d\n", dir_count);
    printf("Total Archives: %d\n", archive_count);
    printf("Total Symlinks: %d\n", symlink_count);
    printf("Total Size (bytes): %zu\n", total_size);
}

// Function to free the linked list
void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next_node = current->next;
        free(current->data.path);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Main function for demonstration purposes
int main() {
    LinkedList *file_list = create_list(1024 * 1024); // 1 MB limit

    add_to_list(file_list, "/path/to/file1.txt", "Regular", time(NULL), 12345);
    add_to_list(file_list, "/path/to/dir1", "Directory", time(NULL), 0);

    serialize_list(file_list, "file_list.dat");
    deserialize_list(file_list, "file_list.dat");

    generate_summary(file_list);

    free_list(file_list);
    return 0;
}
