    if (N <= 0) {
        fprintf(stderr, "Error: Invalid list size.\n");
        return;
    }

    srand(time(NULL));

    unsigned short last_rnti = 0;
    for (size_t i = 0; i < N; ++i) {
        int retry_count = 0;
        while (1) {
            pthread_mutex_lock(&nfa_lock);
            list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            do {
                list[i].RNTI = rand() % MAX_RNTI + 1;
            } while (list[i].RNTI == last_rnti);

            list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
            list[i].CRCFLAG = rand() % (CRCFLAG_MAX - CRCFLAG_MIN + 1) + CRCFLAG_MIN;

            if (persist_RNTI(list[i].RNTI) == 0) {
                last_rnti = list[i].RNTI;
                pthread_mutex_unlock(&nfa_lock);
                break;
            }
            retry_count++;
            pthread_mutex_unlock(&nfa_lock);

            if (retry_count > 3) { // Retry limit
                fprintf(stderr, "Error: Failed to persist RNTI after retries.\n");
                return;
            }

            usleep(100000); // Wait before retrying
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *resource_id;
    char *data;
} Resource;

Resource resources[1024];
int resource_count = 0;
pthread_mutex_t api_lock = PTHREAD_MUTEX_INITIALIZER;

void put_resource(char *id, char *new_data) {
    pthread_mutex_lock(&api_lock);
    for (int i = 0; i < resource_count; ++i) {
        if (strcmp(resources[i].resource_id, id) == 0) {
            free(resources[i].data);
            resources[i].data = strdup(new_data);
            printf("Resource %s updated.\n", id);
            pthread_mutex_unlock(&api_lock);
            return;
        }
    }
    if (resource_count < 1024) {
        resources[resource_count].resource_id = strdup(id);
        resources[resource_count].data = strdup(new_data);
        resource_count++;
        printf("Resource %s created.\n", id);
    } else {
        fprintf(stderr, "Error: Resource limit reached.\n");
    }
    pthread_mutex_unlock(&api_lock);
}

void delete_resource(char *id) {
    pthread_mutex_lock(&api_lock);
    for (int i = 0; i < resource_count; ++i) {
        if (strcmp(resources[i].resource_id, id) == 0) {
            free(resources[i].data);
            resources[i].resource_id = NULL;
            printf("Resource %s deleted.\n", id);

            // Shift remaining resources
            for (int j = i; j < resource_count - 1; ++j) {
                resources[j] = resources[j + 1];
            }
            resource_count--;
            break;
        }
    }
    pthread_mutex_unlock(&api_lock);
}

// Example usage of web API functions
int main() {
    put_resource("123", "{\"name\":\"example\"}");
    delete_resource("123");
    return 0;
}
