    if (fd < 0) handle_error("Failed to open file for serialization");

    ftruncate(fd, session_count * sizeof(Session));
    Session *mapped = mmap(NULL, session_count * sizeof(Session), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped == MAP_FAILED) handle_error("Memory mapping failed");

    memcpy(mapped, sessions, session_count * sizeof(Session));

    munmap(mapped, session_count * sizeof(Session));
    close(fd);
}

