#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *message;
    time_t timestamp;
    int error_code;
} LogEntry;

typedef struct {
    int id;
    char *data;
    int value;
} Record;

typedef struct {
    size_t num_offsets;
    long *offsets;

    size_t num_keys;
    char **keys;

    size_t num_records;
    Record **records;

    size_t num_logs;
    LogEntry **logs;
} DataStructure;

void log_entry(DataStructure *ds, const char *message, int error_code) {
    ds->num_logs++;
    ds->logs = realloc(ds->logs, sizeof(LogEntry *) * ds->num_logs);
    if (!ds->logs) {
        perror("Failed to allocate memory for logs");
        exit(EXIT_FAILURE);
    }

    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Failed to allocate memory for log entry");
        exit(EXIT_FAILURE);
    }

    entry->message = strdup(message);
    entry->timestamp = time(NULL);
    entry->error_code = error_code;

    ds->logs[ds->num_logs - 1] = entry;
}

Record *create_record(int id, const char *data, int value) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    record->id = id;
    record->value = value;

    size_t len = strlen(data) + 1;
    record->data = malloc(len);
    if (!record->data) {
        perror("Failed to allocate memory for record data");
        free(record);
        exit(EXIT_FAILURE);
    }

    strcpy(record->data, data);

    return record;
}

DataStructure initialize_data_structures(size_t num_offsets, size_t num_keys, size_t num_records, int min_value, int max_value) {
    DataStructure ds = {0};

    // Initialize offsets
    ds.num_offsets = num_offsets;
    ds.offsets = malloc(sizeof(long) * num_offsets);
    if (!ds.offsets) {
        log_entry(&ds, "Failed to allocate memory for offsets", 1);
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < ds.num_offsets; ++i) {
        ds.offsets[i] = rand();
    }

    // Initialize keys
    ds.num_keys = num_keys;
    ds.keys = malloc(sizeof(char *) * num_keys);
    if (!ds.keys) {
        log_entry(&ds, "Failed to allocate memory for keys", 1);
        free(ds.offsets);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < ds.num_keys; ++i) {
        char key[16];
        snprintf(key, sizeof(key), "key%d", (int)i);
        ds.keys[i] = strdup(key);
        if (!ds.keys[i]) {
            log_entry(&ds, "Failed to allocate memory for a key string", 1);
            free(ds.offsets);
            while (i-- > 0) free(ds.keys[i]);
            free(ds.keys);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize records
    ds.num_records = num_records;
    ds.records = malloc(sizeof(Record *) * num_records);
    if (!ds.records) {
        log_entry(&ds, "Failed to allocate memory for record pointers", 1);
        free(ds.offsets);
        while (num_keys-- > 0) free(ds.keys[num_keys]);
        free(ds.keys);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < ds.num_records; ++i) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        Record *record = create_record((int)i, "Example Data", value);
        if (!record) {
            log_entry(&ds, "Failed to allocate memory for a record", 1);
            free(ds.offsets);
            while (num_keys-- > 0) free(ds.keys[num_keys]);
            free(ds.keys);
            free(ds.records);
            exit(EXIT_FAILURE);
        }
        ds.records[i] = record;
    }

    log_entry(&ds, "Data structures initialized successfully", 0);

    return ds;
}

void free_data_structures(DataStructure *ds) {
    for (size_t i = 0; i < ds->num_records; ++i) {
        free(ds->records[i]->data);
        free(ds->records[i]);
    }
    free(ds->records);

    for (size_t i = 0; i < ds->num_keys; ++i) {
        free(ds->keys[i]);
    }
    free(ds->keys);
    free(ds->offsets);

    for (size_t i = 0; i < ds->num_logs; ++i) {
        free(ds->logs[i]->message);
        free(ds->logs[i]);
    }
    free(ds->logs);
}

void merge_data_structures(DataStructure *ds1, DataStructure *ds2) {
    size_t original_num_records = ds1->num_records;

    // Merge offsets
    ds1->offsets = realloc(ds1->offsets, sizeof(long) * (ds1->num_offsets + ds2->num_offsets));
    if (!ds1->offsets) {
        log_entry(ds1, "Failed to reallocate memory for merged offsets", 1);
        exit(EXIT_FAILURE);
    }

    memcpy(&ds1->offsets[ds1->num_offsets], ds2->offsets, sizeof(long) * ds2->num_offsets);
    ds1->num_offsets += ds2->num_offsets;

    // Merge keys
    char **new_keys = realloc(ds1->keys, sizeof(char *) * (ds1->num_keys + ds2->num_keys));
    if (!new_keys) {
        log_entry(ds1, "Failed to reallocate memory for merged keys", 1);
        exit(EXIT_FAILURE);
    }

    memcpy(&ds1->keys[ds1->num_keys], ds2->keys, sizeof(char *) * ds2->num_keys);
    ds1->num_keys += ds2->num_keys;

    // Merge records
    Record **new_records = realloc(ds1->records, sizeof(Record *) * (ds1->num_records + ds2->num_records));
    if (!new_records) {
        log_entry(ds1, "Failed to reallocate memory for merged records", 1);
        exit(EXIT_FAILURE);
    }

    memcpy(&ds1->records[original_num_records], ds2->records, sizeof(Record *) * ds2->num_records);
    ds1->num_records += ds2->num_records;

    // Merge logs
    LogEntry **new_logs = realloc(ds1->logs, sizeof(LogEntry *) * (ds1->num_logs + ds2->num_logs));
    if (!new_logs) {
        log_entry(ds1, "Failed to reallocate memory for merged logs", 1);
        exit(EXIT_FAILURE);
    }

    memcpy(&ds1->logs[ds1->num_logs], ds2->logs, sizeof(LogEntry *) * ds2->num_logs);
    ds1->num_logs += ds2->num_logs;

    free(ds2->offsets);
    free(ds2->keys);
    free(ds2->records);
    free(ds2->logs);

    ds1->offsets = new_keys;
    ds1->keys = new_records;
    ds1->records = new_records;
    ds1->logs = new_logs;

    log_entry(ds1, "Data structures merged successfully", 0);
}

int main() {
    DataStructure ds1 = initialize_data_structures(10, 5, 3, 100, 200);
    DataStructure ds2 = initialize_data_structures(8, 4, 2, 150, 250);

    merge_data_structures(&ds1, &ds2);

    for (size_t i = 0; i < ds1.num_logs; ++i) {
        printf("Log %zu: [%ld] Error Code: %d Message: %s\n", i + 1, ds1.logs[i]->timestamp, ds1.logs[i]->error_code, ds1.logs[i]->message);
    }

    free_data_structures(&ds1);

    return 0;
}
```

This implementation initializes the required data structures with specified sizes, randomizes integer values within a given range, and manages memory allocation and deallocation events through logging. It also includes merging functionality for combining two sets of initialized data structures into one unified structure while ensuring robust error handling and efficient memory management.']

