use std::env;
use std::fs;
use std::path::Path;

fn set_directory_env_var(env_var: &str, dir_name: &str) -> std::io::Result<()> {
    if let Ok(path_str) = env::var(env_var) {
        if Path::new(&path_str).exists() {
            println!("Using existing directory from environment variable.");
            return Ok(());
        }
    }

    let path = format!("{}/{}", env::current_dir()?.display(), dir_name);
    fs::create_dir_all(&path)?;

    println!("Setting environment variable {} to {}", env_var, &path);
    std::env::set_var(env_var, &path);

    Ok(())
}
