        // Simulate system load check (CPU, Memory)
        size_t newMaxSessions = maxSessions; // Adjust based on metrics

        {
            std::lock_guard<std::mutex> lock(sessionMutex);
            if(newMaxSessions != maxSessions) {
                maxSessions = newMaxSessions;
                sessions.resize(maxSessions); // Resize with default constructor
            }
        }
    }
}

// Function to serialize session list to a file
void serializeSessions(const std::string& filename) {
    std::lock_guard<std::mutex> lock(sessionMutex);
    nlohmann::json j = nlohmann::json::array();
    for(const auto& session : sessions) {
        if(!session.sessionID.empty()) { // Serialize only valid sessions
            j.push_back({{"sessionID", session.sessionID},
                         {"clientIP", session.clientIP},
                         {"lastActivity", std::chrono::duration_cast<std::chrono::seconds>(
                             session.lastActivity.time_since_epoch()).count()},
                         {"referenceCount", session.referenceCount},
                         {"metadata", session.metadata}});
        }
    }

