// Function to deserialize session list from a file
void deserializeSessions(const std::string& filename) {
    std::ifstream file(filename);
    if(file.is_open()) {
        nlohmann::json j;
        file >> j;

        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions.clear();
        for(auto& item : j) {
            UserSession session = {item["sessionID"].get<std::string>(),
                                   item["clientIP"].get<std::string>(),
                                   std::chrono::system_clock::from_time_t(item["lastActivity"].get<int>()),
                                   item["referenceCount"].get<int>(),
                                   item["metadata"].get<nlohmann::json>()};
            sessions.push_back(session);
        }

        file.close();
    } else {
        std::cerr << "Unable to open file for deserialization: " << filename << '\n';
