        // Serialize and deserialize for demonstration
        serializeSessions("sessions.json");
        deserializeSessions("sessions.json");
    }

    fetchDataThread.join();
    adjustMemoryLimitThread.join();
}

int main() {
    selectAndCooldownAttack();
    return 0;
}
