#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 255

typedef struct {
    char original_filename[MAX_FILENAME_LENGTH];
    char new_filename[MAX_FILENAME_LENGTH];
    time_t timestamp;
    pid_t process_id;
} LogEntry;

// Logging function
void log_file_modification(const LogEntry *entry) {
    FILE *log_file = fopen("file_renames.log", "a");
    if (log_file == NULL) return; // Error handling can be expanded

    fprintf(log_file, "Original: %s -> New: %s at %ld by process %d\n",
            entry->original_filename, entry->new_filename, entry->timestamp, entry->process_id);

    fclose(log_file);
}

// Function to generate a random number of digits
int generate_random_digits(int base_name_length) {
    return rand() % base_name_length + 1;
}

// Thread-safe rename function with collision detection and logging
void rename_with_timestamp_and_unique_number(const char *directory_path, const char *filename, const char *new_filetype) {
    if (filename == NULL || directory_path == NULL || new_filetype == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Extract base name and extension
    char base_name[MAX_FILENAME_LENGTH], ext[10];
    strncpy(base_name, filename, sizeof(base_name));
    strncat(base_name, "\0", 1); // Ensure null termination

    char *dot = strrchr(base_name, '.');
    if (dot != NULL) {
        strncpy(ext, dot, sizeof(ext));
        *dot = '\0'; // Remove extension from base name
    } else {
        strcpy(ext, ""); // No extension found
    }

    // Check filename length constraints
    size_t base_length = strlen(base_name);
    if (base_length > 100) {
        fprintf(stderr, "Base filename is too long\n");
        return;
    }

    // Generate random digits and new filename
    int num_digits = generate_random_digits(base_length);
    char number_str[num_digits + 1];
    snprintf(number_str, sizeof(number_str), "%0*d", num_digits, rand());

    char new_filename[MAX_FILENAME_LENGTH];
    snprintf(new_filename, sizeof(new_filename), "%s_%d%s.%s",
             base_name, (int)time(NULL), number_str, new_filetype);

    // Validate new filename length
    if (strlen(directory_path) + 1 + strlen(new_filename) > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "New filename exceeds maximum allowed length\n");
        return;
    }

    char full_new_path[MAX_FILENAME_LENGTH];
    snprintf(full_new_path, sizeof(full_new_path), "%s/%s", directory_path, new_filename);

    // Ensure unique filename
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    DIR *dir = opendir(directory_path);
    if (!dir) {
        fprintf(stderr, "Unable to open directory: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);
        return;
    }

    struct dirent *entry;
    int unique = 0;

    while ((entry = readdir(dir)) != NULL && !unique) {
        if (strcmp(entry->d_name, new_filename) == 0) {
            snprintf(number_str, sizeof(number_str), "%0*d", num_digits, rand());
            snprintf(new_filename, sizeof(new_filename), "%s_%d%s.%s",
                     base_name, (int)time(NULL), number_str, new_filetype);

            snprintf(full_new_path, sizeof(full_new_path), "%s/%s", directory_path, new_filename);
        } else {
            unique = 1;
        }
    }

    closedir(dir);

    if (!unique) {
        fprintf(stderr, "Failed to generate a unique filename after several attempts\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Rename file
    char full_old_path[MAX_FILENAME_LENGTH];
    snprintf(full_old_path, sizeof(full_old_path), "%s/%s", directory_path, filename);

    if (rename(full_old_path, full_new_path) != 0) {
        fprintf(stderr, "Failed to rename file: %s\n", strerror(errno));
    } else {
        // Log the modification
        LogEntry log_entry;
        strncpy(log_entry.original_filename, filename, sizeof(log_entry.original_filename));
        strncpy(log_entry.new_filename, new_filename, sizeof(log_entry.new_filename));
        log_entry.timestamp = time(NULL);
        log_entry.process_id = getpid();

        log_file_modification(&log_entry);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    // Seed the random number generator
    srand((unsigned)time(NULL));

    rename_with_timestamp_and_unique_number("/path/to/directory", "example.txt", "newtype");
    return 0;
}
