#define MAX_ALGORITHMS 10

typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    // Additional contexts for other algorithms
} CryptoContext;

typedef struct {
    const char *name;
    int (*encrypt)(const unsigned char *plaintext, int plaintext_len,
                   unsigned char *ciphertext, int *ciphertext_len, void *key);
    int (*decrypt)(const unsigned char *ciphertext, int ciphertext_len,
                   unsigned char *plaintext, int *plaintext_len, void *key);
} CipherAlgorithm;

typedef struct {
    const char *name;
    int (*digest)(const unsigned char *data, size_t length, unsigned char *md_value);
} DigestAlgorithm;

typedef struct {
    CipherAlgorithm ciphers[MAX_ALGORITHMS];
    DigestAlgorithm digests[MAX_ALGORITHMS];
    pthread_mutex_t lock;
    // Resource pooling and logging structures
} CryptoLibrary;

// Function prototypes for core operations
int initialize_crypto_library(CryptoLibrary *lib);
void cleanup_crypto_library(CryptoLibrary *lib);
int add_cipher_algorithm(CryptoLibrary *lib, CipherAlgorithm algo);
int remove_cipher_algorithm(CryptoLibrary *lib, const char *name);
int add_digest_algorithm(CryptoLibrary *lib, DigestAlgorithm algo);
int remove_digest_algorithm(CryptoLibrary *lib, const char *name);

// Example AES encryption/decryption functions
int aes_encrypt(const unsigned char *plaintext, int plaintext_len,
                unsigned char *ciphertext, int *ciphertext_len, void *key) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0)
        goto err;

    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) <= 0)
        goto err;

    int plaintext_tail = len;
    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) <= 0)
        goto err;

    *ciphertext_len = plaintext_tail + len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                unsigned char *plaintext, int *plaintext_len, void *key) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0)
        goto err;

    int len;
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) <= 0)
        goto err;

    int plaintext_tail = len;
    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) <= 0)
        goto err;

    *plaintext_len = plaintext_tail + len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

// Initialize and cleanup functions
int initialize_crypto_library(CryptoLibrary *lib) {
    pthread_mutex_init(&lib->lock, NULL);
    // Initialize other resources, logging, etc.
    return 0;
}

void cleanup_crypto_library(CryptoLibrary *lib) {
    pthread_mutex_destroy(&lib->lock);
    // Cleanup contexts and other resources
}

int add_cipher_algorithm(CryptoLibrary *lib, CipherAlgorithm algo) {
    pthread_mutex_lock(&lib->lock);
    for (int i = 0; i < MAX_ALGORITHMS; ++i) {
        if (!lib->ciphers[i].name) {
            lib->ciphers[i] = algo;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // No space
}

int remove_cipher_algorithm(CryptoLibrary *lib, const char *name) {
    pthread_mutex_lock(&lib->lock);
    for (int i = 0; i < MAX_ALGORITHMS; ++i) {
        if (strcmp(lib->ciphers[i].name, name) == 0) {
            lib->ciphers[i].name = NULL;
            pthread_mutex_unlock(&lib->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return -1; // Not found
}

// Implement similar functions for digest algorithms and other operations

int main() {
    CryptoLibrary lib;
    initialize_crypto_library(&lib);

    CipherAlgorithm aes_algo = {
        .name = "AES-256-CBC",
        .encrypt = aes_encrypt,
        .decrypt = aes_decrypt
    };

    add_cipher_algorithm(&lib, aes_algo);

    // Further usage and cleanup

    remove_cipher_algorithm(&lib, "AES-256-CBC");
    cleanup_crypto_library(&lib);

    return 0;
}
