#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_LINE_LENGTH 1024
#define DNS_CACHE_SIZE 1000

typedef struct {
    char hostname[256];
    u_char ip_address[16]; // IPv6 support
} dns_cache_entry;

dns_cache_entry dns_cache[DNS_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_count = 0;

// Function prototypes
void* resolve_dns_async(void* arg);
char** process_files(const char* directory_path);
void free_memory(char** lines, int count);

// DNS resolution function
u_char* resolve_hostname(const char* hostname) {
    struct addrinfo hints, *res;
    int status;
    u_char ip_buffer[16];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[i].ip_address;
        }
    }

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution error: %s\n", gai_strerror(status));
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    // Assume first result is what we want
    void* addr = &((struct sockaddr_in*)res->ai_addr)->sin_addr;
    struct sockaddr_in6 *addr_v6 = (struct sockaddr_in6 *) res->ai_addr;

    if (res->ai_family == AF_INET) {
        inet_ntop(AF_INET, addr, ip_buffer, sizeof(ip_buffer));
    } else if (res->ai_family == AF_INET6) {
        inet_ntop(AF_INET6, &addr_v6->sin6_addr, ip_buffer, sizeof(ip_buffer));
    }

    freeaddrinfo(res);

    // Add to cache
    strncpy(dns_cache[cache_count].hostname, hostname, 255);
    memcpy(dns_cache[cache_count].ip_address, ip_buffer, sizeof(ip_buffer));

    pthread_mutex_unlock(&cache_lock);
    return dns_cache[cache_count++ % DNS_CACHE_SIZE].ip_address;
}

// Asynchronous DNS resolution worker
void* resolve_dns_async(void* arg) {
    char** lines = (char**)arg;
    int count = *((int*)arg + 1);

    for (int i = 0; i < count; ++i) {
        // Assuming hostname is first field in each line
        char* token = strtok(lines[i], " ");
        if (token && strlen(token) > 0) {
            u_char* ip_address = resolve_hostname(token);
            if (ip_address) {
                printf("Resolved %s to ", token);
                for (int j = 0; j < 16; ++j) {
                    printf("%02x", ip_address[j]);
                    if (j == 7 && ip_address[8] != 0) printf(":");
                }
                printf("\n");
            } else {
                fprintf(stderr, "DNS resolution failed for %s\n", token);
            }
        }
    }

    free(arg + 2); // Free the line pointers
    return NULL;
}

// Process files and allocate memory for lines
char** process_files(const char* directory_path) {
    // This is a placeholder function to illustrate file processing
    // In practice, you would use open, read, mmap, etc. to handle files

    int num_lines = 10; // Example number of lines processed
    int line_capacity = 100;
    char** lines = malloc(sizeof(char*) * line_capacity);

    for (int i = 0; i < num_lines; ++i) {
        lines[i] = malloc(MAX_LINE_LENGTH);
        snprintf(lines[i], MAX_LINE_LENGTH, "hostname%d %d %d", i, rand() % 100, rand() % 200);
    }

    return lines;
}

// Free dynamically allocated memory
void free_memory(char** lines, int count) {
    for (int i = 0; i < count; ++i) {
        free(lines[i]);
    }
    free(lines);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* directory_path = argv[1];
    char** lines = process_files(directory_path);
    int count = 10; // Example line count

    pthread_t threads[4]; // Example thread pool size
    for (int i = 0; i < 4; ++i) {
        char** args = malloc(sizeof(char*) * 3);
        args[0] = lines;
        *((int*)(args + 1)) = count;

        if (pthread_create(&threads[i], NULL, resolve_dns_async, args) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_memory(lines, count);

    return EXIT_SUCCESS;
}
```

### Key Points:
