    free(manager);
}

Session* createSession(SessionManager *manager, const char *sessionID, const char *clientIP) {
    if (!manager || !sessionID || !clientIP) return NULL;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resizeSessions(manager);
    }

    Session *newSession = (Session*)malloc(sizeof(Session));
    if (!newSession) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    newSession->sessionID = strdup(sessionID);
    newSession->clientIP = strdup(clientIP);
    newSession->lastActivity = time(NULL);
    newSession->refCount = 1;
    // Assume allocateMetadata is a function to allocate memory for metadata
    newSession->metadata = allocateMetadata();

    manager->sessions[manager->count++] = newSession;

    pthread_mutex_unlock(&manager->lock);

    return newSession;
}

void updateSessionActivity(SessionManager *manager, const char *sessionID) {
    if (!manager || !sessionID) return;

    Session *session = findSessionById(manager, sessionID);
    if (session) {
        pthread_rwlock_wrlock(&manager->rwlock);
        session->lastActivity = time(NULL);
        pthread_rwlock_unlock(&manager->rwlock);
    }
}

void incrementRefCount(SessionManager *manager, const char *sessionID) {
    if (!manager || !sessionID) return;

    Session *session = findSessionById(manager, sessionID);
    if (session) {
        pthread_mutex_lock(&manager->lock);
        session->refCount++;
        pthread_mutex_unlock(&manager->lock);
    }
}

void decrementRefCount(SessionManager *manager, const char *sessionID) {
    if (!manager || !sessionID) return;

    Session *session = findSessionById(manager, sessionID);
    if (session) {
        pthread_mutex_lock(&manager->lock);
        if (--session->refCount == 0) {
            // Free the session
            free(session->sessionID);
            free(session->clientIP);
            customFreeMetadata(session->metadata);
            free(session);

            // Remove from sessions array
            size_t index = findIndexById(manager, sessionID);
            for (size_t i = index; i < manager->count - 1; ++i) {
                manager->sessions[i] = manager->sessions[i + 1];
            }
            manager->count--;
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

void serializeSessions(SessionManager *manager, const char *filename) {
    if (!manager || !filename) return;

    pthread_rwlock_rdlock(&manager->rwlock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_rwlock_unlock(&manager->rwlock);
        return;
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        Session *session = manager->sessions[i];
        size_t idLen = strlen(session->sessionID) + 1;
        size_t ipLen = strlen(session->clientIP) + 1;

        fwrite(&idLen, sizeof(size_t), 1, file);
        fwrite(session->sessionID, sizeof(char), idLen, file);

        fwrite(&ipLen, sizeof(size_t), 1, file);
        fwrite(session->clientIP, sizeof(char), ipLen, file);

        fwrite(&session->lastActivity, sizeof(time_t), 1, file);
        fwrite(&session->refCount, sizeof(int), 1, file);

        // Assume serializeMetadata is a function to serialize metadata
        size_t metaSize;
        char *metaDataSerialized = serializeMetadata(session->metadata, &metaSize);
        fwrite(&metaSize, sizeof(size_t), 1, file);
        fwrite(metaDataSerialized, sizeof(char), metaSize, file);
        free(metaDataSerialized);
    }

    fclose(file);

    pthread_rwlock_unlock(&manager->rwlock);
}

void deserializeSessions(SessionManager *manager, const char *filename) {
    if (!manager || !filename) return;

    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < count; ++i) {
        size_t idLen, ipLen, metaSize;
        char *sessionID, *clientIP, *metaDataSerialized;

        fread(&idLen, sizeof(size_t), 1, file);
        sessionID = malloc(idLen);
        fread(sessionID, sizeof(char), idLen, file);

        fread(&ipLen, sizeof(size_t), 1, file);
        clientIP = malloc(ipLen);
        fread(clientIP, sizeof(char), ipLen, file);

        time_t lastActivity;
        int refCount;

        fread(&lastActivity, sizeof(time_t), 1, file);
        fread(&refCount, sizeof(int), 1, file);

        Session *newSession = (Session*)malloc(sizeof(Session));
        newSession->sessionID = sessionID;
        newSession->clientIP = clientIP;
        newSession->lastActivity = lastActivity;
        newSession->refCount = refCount;

        // Assume deserializeMetadata is a function to deserialize metadata
        fread(&metaSize, sizeof(size_t), 1, file);
        metaDataSerialized = malloc(metaSize);
        fread(metaDataSerialized, sizeof(char), metaSize, file);
        newSession->metadata = deserializeMetadata(metaDataSerialized, metaSize);
        free(metaDataSerialized);

        manager->sessions[manager->count++] = newSession;
    }
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

static void resizeSessions(SessionManager *manager) {
    size_t newCapacity = manager->capacity * 2;
    Session **newSessions = (Session**)realloc(manager->sessions, newCapacity * sizeof(Session*));
    if (!newSessions) return;

    manager->sessions = newSessions;
    manager->capacity = newCapacity;
}

static Session* findSessionById(SessionManager *manager, const char *sessionID) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->sessionID, sessionID) == 0) {
            return manager->sessions[i];
        }
    }
    return NULL;
}

static Session* findSessionByIP(SessionManager *manager, const char *clientIP) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->clientIP, clientIP) == 0) {
            return manager->sessions[i];
        }
    }
    return NULL;
}

static size_t findIndexById(SessionManager *manager, const char *sessionID) {
