using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class CustomDataStructure {
    // Define your custom data structure fields here
}

public static CustomDataStructure DeserializeDataFromBinaryFile(string filePath) {
    if (string.IsNullOrEmpty(filePath)) throw new ArgumentException("FilePath cannot be null or empty.", nameof(filePath));

    try {
        using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read)) {
            BinaryFormatter formatter = new BinaryFormatter();

            CustomDataStructure data = (CustomDataStructure)formatter.Deserialize(fileStream);
            return data;
        }
    } catch (FileNotFoundException ex) {
        Console.Error.WriteLine($"File not found: {ex.Message}");
        throw;
    } catch (IOException ex) {
        Console.Error.WriteLine($"I/O error occurred: {ex.Message}");
        throw;
    } catch (SerializationException ex) {
        Console.Error.WriteLine($"Data corruption detected in file: {ex.Message}");
        throw;
    } catch (Exception ex) {
        Console.Error.WriteLine($"An unexpected error occurred: {ex.Message}");
        throw new InvalidOperationException("Failed to deserialize data from the binary file.", ex);
    }
}
