#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 10

typedef struct {
    int value;
    char status;
    char *name;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t count;
    pthread_mutex_t lock;
    int error_flag;
} MemoryManager;

void initialize_random() {
    srand((unsigned) time(NULL));
}

char random_char() {
    return 'A' + rand() % 26; // Randomly choose between A-Z
}

int generate_random_status() {
    return (rand() % 2 == 0) ? 'A' : 'B';
}

char* allocate_random_string() {
    char *str = malloc(MAX_STRING_LENGTH);
    if (!str) return NULL;
    for (int i = 0; i < MAX_STRING_LENGTH - 1; ++i) {
        str[i] = random_char();
    }
    str[MAX_STRING_MEMORY_FRAGMENTATION-1] = '\0';
    return str;
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

MemoryManager* create_memory_manager(size_t count) {
    MemoryManager *manager = safe_malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->count = count;
    pthread_mutex_init(&manager->lock, NULL);
    manager->error_flag = 0;

    // Allocate memory for offsets and keys
    manager->offsets = (long *)safe_malloc(count * sizeof(long));
    manager->keys = (int *)safe_malloc(count * sizeof(int));

    if (!manager->offsets || !manager->keys) {
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < count; ++i) {
        manager->offsets[i] = i;
        manager->keys[i] = i;
    }

    // Allocate memory for records array pointers
    manager->records = (Record **)safe_malloc(count * sizeof(Record *));
    if (!manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    // Initialize each record
    for (size_t i = 0; i < count; ++i) {
        Record *record = safe_malloc(sizeof(Record));
        if (!record) {
            manager->error_flag = 1;
            break;
        }

        record->value = rand() % 100; // Random value in range [0, 99]
        record->status = generate_random_status();
        record->name = allocate_random_string();

        if (!record->name) {
            free(record);
            manager->error_flag = 1;
            break;
        }

        pthread_mutex_lock(&manager->lock);
        manager->records[i] = record;
        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

void free_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
