#define MAX_NAME_LENGTH 50

typedef struct {
    int id;
    char name[MAX_NAME_LENGTH];
    int quantity;
} Item;

// Predefined set of names for initialization
const char *name_set[] = {"apple", "banana", "cherry", "date", "elderberry"};
const size_t num_names = sizeof(name_set) / sizeof(name_set[0]);

typedef struct {
    Item **items;
    size_t count;
    pthread_mutex_t lock;
} ItemList;

ItemList* create_item_list(size_t initial_size);
void free_item_list(ItemList *list);
void populate_random_names(ItemList *list);
void update_quantities(ItemList *list, int (*callback)(Item *));
void iterate_and_update(ItemList *list);

ItemList* create_item_list(size_t initial_size) {
    ItemList *list = (ItemList *)malloc(sizeof(ItemList));
    list->items = (Item **)calloc(initial_size, sizeof(Item *));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_item_list(ItemList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i]);
    }
    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void populate_random_names(ItemList *list) {
    if (!list || !list->items) return;

    for (size_t i = 0; i < list->count; ++i) {
        list->items[i]->id = i;
        snprintf(list->items[i]->name, MAX_NAME_LENGTH, "%s", name_set[rand() % num_names]);
        list->items[i]->quantity = rand() % 100; // Random initial quantity
    }
}

void add_item(ItemList *list) {
    if (!list || !list->items) return;

    pthread_mutex_lock(&list->lock);
    size_t new_size = (list->count + 1) * sizeof(Item *);
    Item **new_items = (Item **)realloc(list->items, new_size);

    if (new_items) {
        list->items = new_items;
        list->items[list->count] = malloc(sizeof(Item));
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_quantities(ItemList *list, int (*callback)(Item *)) {
    if (!list || !list->items || !callback) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        list->items[i]->quantity = callback(list->items[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_and_update(ItemList *list) {
    if (!list || !list->items) return;

    printf("Iterating and updating items...\n");
    update_quantities(list, [](Item *item) -> int {
        // Example: increment quantity by 10
        return item->quantity + 10;
    });
}

int main() {
    srand((unsigned int)time(NULL));

    ItemList *list = create_item_list(5);

    for (size_t i = 0; i < 5; ++i) {
        add_item(list);
    }

    populate_random_names(list);

    iterate_and_update(list);

    // Example output
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        printf("Item %d: %s, Quantity: %d\n", list->items[i]->id, list->items[i]->name, list->items[i]->quantity);
    }
    pthread_mutex_unlock(&list->lock);

    free_item_list(list);
    return 0;
}
```

