#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_CONCURRENT_QUERIES 10
#define MAX_RETRIES 3
#define RETRY_BACKOFF_MS 200

typedef struct Node {
    char hostname[256];
    struct sockaddr_in addr;
    time_t expiration_time;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DNSCache;

DNSCache cache = {NULL, PTHREAD_MUTEX_INITIALIZER};

void free_list(Node* node) {
    while (node) {
        Node* temp = node;
        node = node->next;
        free(temp);
    }
}

Node* lookup_cache(const char* hostname) {
    pthread_mutex_lock(&cache.lock);
    Node* current = cache.head;
    while (current) {
        if (strcmp(current->hostname, hostname) == 0 && current->expiration_time > time(NULL)) {
            pthread_mutex_unlock(&cache.lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

void insert_cache(const char* hostname, struct sockaddr_in addr, int ttl) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    strcpy(new_node->hostname, hostname);
    new_node->addr = addr;
    new_node->expiration_time = time(NULL) + ttl;

    pthread_mutex_lock(&cache.lock);
    new_node->next = cache.head;
    cache.head = new_node;
    pthread_mutex_unlock(&cache.lock);
}

void* dns_query(void* arg) {
    char* hostname = (char*)arg;
    Node* cached_result = lookup_cache(hostname);

    if (cached_result) {
        return (void*)&cached_result->addr;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        // Simulate DNS query
        struct sockaddr_in result;
        int success = simulate_dns_query(hostname, &result);

        if (success) {
            int ttl = extract_ttl_from_response();
            insert_cache(hostname, result, ttl);
            return (void*)&result;
        }

        usleep(RETRY_BACKOFF_MS * 1000);
    }
    pthread_exit(NULL);
}

int main() {
    // Example usage
    char* hostnames[] = {"example.com", "test.com"};
    int num_hosts = sizeof(hostnames) / sizeof(char*);

    pthread_t threads[MAX_CONCURRENT_QUERIES];
    struct sockaddr_in* results[num_hosts];

    for (int i = 0; i < num_hosts; ++i) {
        int idx = i % MAX_CONCURRENT_QUERIES;
        pthread_create(&threads[idx], NULL, dns_query, hostnames[i]);
    }

    for (int i = 0; i < num_hosts; ++i) {
        int idx = i % MAX_CONCURRENT_QUERIES;
        void* result;
        pthread_join(threads[idx], &result);
        if (result) {
            results[i] = (struct sockaddr_in*)result;
            printf("Resolved: %s -> %s\n", hostnames[i],
                   inet_ntoa(results[i]->sin_addr));
        } else {
            fprintf(stderr, "Failed to resolve: %s\n", hostnames[i]);
        }
    }

    free_list(cache.head);
    return 0;
}

int simulate_dns_query(const char* hostname, struct sockaddr_in* result) {
    // Simulate an external DNS query and populate `result`
    // In a real scenario, this would call the DNS API
    // For simplicity, we'll just assign a dummy IP address for demonstration

    if (strcmp(hostname, "example.com") == 0) {
        inet_pton(AF_INET, "93.184.216.34", &result->sin_addr);
        return 1;
    } else if (strcmp(hostname, "test.com") == 0) {
        inet_pton(AF_INET, "203.0.113.195", &result->sin_addr);
        return 1;
    }

    return 0;
}

int extract_ttl_from_response() {
    // Simulate extraction of TTL from a DNS response
    return 300; // 5 minutes for demonstration purposes
}
```

This code includes:
- A basic linked list for caching DNS responses.
- Thread management to handle concurrent queries up to the configured limit (`MAX_CONCURRENT_QUERIES`).
- Retry logic with exponential backoff.
- Cache lookup and insertion functions to manage DNS response storage efficiently.

Adjustments can be made to suit specific API requirements, error handling needs, or scaling considerations.']

