#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes

typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
    uint8_t ip_version;
    uint8_t protocol_type;
    uint16_t payload_length;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t current_size;
    pthread_mutex_t lock;
} PacketList;

void log_error(const char* message) {
    // Integrate with external logging service
    fprintf(stderr, "Error: %s\n", message);
}

void validate_packet_header(PacketHeader* header) {
    if (header->ip_version != 4 && header->ip_version != 6) {
        log_error("Invalid IP version");
        return;
    }
    // Add more validation rules as needed
}

PacketList* create_packet_list() {
    PacketList* list = malloc(sizeof(PacketList));
    if (!list) {
        log_error("Failed to allocate memory for packet list");
        return NULL;
    }

    list->head = NULL;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void cleanup_packet_list(PacketList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->current_size = 0;
}

int add_packet_header(PacketList* list, PacketHeader header) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size * sizeof(Node) + sizeof(PacketHeader) > MAX_MEMORY_LIMIT) {
        log_error("Memory limit exceeded");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    validate_packet_header(&header);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for packet header");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&new_node->header, &header, sizeof(PacketHeader));
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* cleanup_thread(void* arg) {
    PacketList* list = (PacketList*)arg;

    while (1) {
        // Perform cleanup periodically
        sleep(10); // Example interval

        pthread_mutex_lock(&list->lock);

        // Implement specific cleanup logic here
        // For demonstration, we're just resetting the list
        cleanup_packet_list(list);

        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

void serialize_packet_list(const PacketList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&current->header, sizeof(PacketHeader), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize_packet_list(PacketList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    PacketHeader header;
    while (fread(&header, sizeof(PacketHeader), 1, file)) {
        add_packet_header(list, header);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void destroy_packet_list(PacketList* list) {
    cleanup_packet_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
