#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/stat.h>

#define MAX_NAME_LEN 50
#define NAME_OPTIONS 5

typedef struct Item {
    int id;
    char name[MAX_NAME_LEN];
    int quantity;
    struct Item* next;
} Item;

typedef struct List {
    Item* head;
    pthread_mutex_t lock;
} List;

List* initialize_list(int N);
void destroy_list(List* list);
Item* create_item(int index, const char* names[]);
void update_quantity_callback(Item* item, void (*callback)(int*));
void iterate_and_update(List* list, int (*callback_func)(int quantity));

// Database and file operations
#include "database.h"  // Assume this is a header for database connection pooling

List* initialize_list(int N) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    const char* names[NAME_OPTIONS] = {"Apple", "Banana", "Cherry", "Date", "Elderberry"};

    for (int i = 0; i < N; ++i) {
        Item* item = create_item(i, names);
        if (!item) {
            destroy_list(list);
            return NULL;
        }

        pthread_mutex_lock(&list->lock);
        item->next = list->head;
        list->head = item;
        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

void destroy_list(List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Item* current = list->head;
    while (current) {
        Item* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

Item* create_item(int index, const char* names[]) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) return NULL;

    item->id = index;
    int rand_index = rand() % NAME_OPTIONS;
    strncpy(item->name, names[rand_index], MAX_NAME_LEN);
    item->quantity = 0;
    item->next = NULL;

    return item;
}

void update_quantity_callback(Item* item, void (*callback)(int*)) {
    if (item && callback) {
        callback(&item->quantity);
    }
}

void iterate_and_update(List* list, int (*callback_func)(int quantity)) {
    if (!list || !list->head || !callback_func) return;

    pthread_mutex_lock(&list->lock);
    Item* current = list->head;

    while (current) {
        current->quantity = callback_func(current->quantity);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Database and file operations
void verify_and_create_directory(const char* path, int retries, int delay_ms) {
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        for (int i = 0; i < retries; ++i) {
            if (mkdir(path, 0700) == 0) break;
            sleep(delay_ms / 1000);
            delay_ms *= 2;
        }
    }
}

void convert_jpeg_to_pdf(const char* jpeg_path, const char* output_dir, const char* pdf_filename) {
    // Assume library function `jpeg_to_pdf` is available
    char full_output_path[256];
    snprintf(full_output_path, sizeof(full_output_path), "%s/%s", output_dir, pdf_filename);

    int result = jpeg_to_pdf(jpeg_path, full_output_path);
    if (result != 0) {
        fprintf(stderr, "Error converting JPEG to PDF: %d\n", result);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <file_name> <list_size> <output_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* file_name = argv[1];
    int list_size = atoi(argv[2]);
    const char* output_dir = argv[3];

    srand(time(NULL));

    List* item_list = initialize_list(list_size);
    if (!item_list) {
        fprintf(stderr, "Failed to initialize the list.\n");
        return EXIT_FAILURE;
    }

    // Simulate a callback function for updating quantities
    int update_callback(int quantity) {
        return quantity + 1;  // Example: increment by 1
    }

    iterate_and_update(item_list, update_callback);

    verify_and_create_directory(output_dir, 5, 100); // Retry with exponential backoff

    const char* pdf_filename = "output.pdf";
    convert_jpeg_to_pdf(file_name, output_dir, pdf_filename);

    destroy_list(item_list);
    return EXIT_SUCCESS;
}
```

### Key Points:
