using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Xml;

public class ConfigManager : IDisposable
{
    private const int MaxRecords = 1000; // Maximum records allowed
    private long[] offsetValues;
    private int[] keys;
    private Record[] records;
    private int totalRecords;
    private readonly object lockObject = new object();

    public struct Record
    {
        public int Value;
        public char[] Buffer;

        public Record(int value)
        {
            Value = value;
            Buffer = new char[256];
        }
    }

    public ConfigManager(int size)
    {
        if (size <= 0 || size > MaxRecords)
        {
            throw new ArgumentException("Invalid size specified.");
        }

        offsetValues = new long[size];
        keys = new int[size];
        records = new Record[size];

        totalRecords = 0;
    }

    public void LoadFromXml(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine("XML file not found.");
            return;
        }

        XmlDocument doc = new XmlDocument();
        try
        {
            doc.Load(filePath);
            XmlNode tileNode = doc.SelectSingleNode("/configuration/tile");
            XmlNode worldNode = doc.SelectSingleNode("/configuration/world");
            XmlNode cameraNode = doc.SelectSingleNode("/configuration/camera");

            if (tileNode != null)
                SetTileSettings(tileNode);

            if (worldNode != null)
                SetWorldSettings(worldNode);

            if (cameraNode != null)
                SetCameraSpeed(cameraNode);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading XML: {ex.Message}");
        }
    }

    private void SetTileSettings(XmlNode tileNode)
    {
        long size = GetLongFromXmlNode(tileNode, "size", 1);

        // Handle the logic for setting tile size
    }

    private void SetWorldSettings(XmlNode worldNode)
    {
        int width = GetIntFromXmlNode(worldNode, "width", 100);
        int height = GetIntFromXmlNode(worldNode, "height", 100);

        // Handle the logic for setting world dimensions
    }

    private void SetCameraSpeed(XmlNode cameraNode)
    {
        double speed = GetDoubleFromXmlNode(cameraNode, "speed", 1.0);

        // Handle the logic for setting camera speed
    }

    private long GetLongFromXmlNode(XmlNode node, string elementName, long defaultValue)
    {
        if (node[elementName] == null) return defaultValue;

        if (!long.TryParse(node[elementName].InnerText, out var value))
            throw new FormatException($"Invalid format for {elementName}.");

        return value;
    }

    private int GetIntFromXmlNode(XmlNode node, string elementName, int defaultValue)
    {
        if (node[elementName] == null) return defaultValue;

        if (!int.TryParse(node[elementName].InnerText, out var value))
            throw new FormatException($"Invalid format for {elementName}.");

        return value;
    }

    private double GetDoubleFromXmlNode(XmlNode node, string elementName, double defaultValue)
    {
        if (node[elementName] == null) return defaultValue;

        if (!double.TryParse(node[elementName].InnerText, out var value))
            throw new FormatException($"Invalid format for {elementName}.");

        return value;
    }

    public bool AddRecord(int key, int value, string charSet)
    {
        lock (lockObject)
        {
            if (totalRecords >= records.Length)
            {
                Console.WriteLine("Memory limit reached. Cannot add more records.");
                return false;
            }

            try
            {
                var record = new Record(value);
                GenerateRandomBuffer(record.Buffer, charSet);

                offsetValues[totalRecords] = 0; // Initialize with default offset
                keys[totalRecords] = key;
                records[totalRecords] = record;

                totalRecords++;
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to add record: {ex.Message}");
                return false;
            }
        }
    }

    private void GenerateRandomBuffer(char[] buffer, string charSet)
    {
        var rng = new RNGCryptoServiceProvider();
        byte[] randomBytes = new byte[buffer.Length];
        rng.GetBytes(randomBytes);

        for (int i = 0; i < buffer.Length; i++)
        {
            int index = randomBytes[i] % charSet.Length;
            buffer[i] = charSet[index];
        }
    }

    public void SerializeToFile(string filePath)
    {
        try
        {
            using (var writer = new BinaryWriter(File.Open(filePath, FileMode.Create)))
            {
                // Write totalRecords first
                writer.Write(totalRecords);

                for (int i = 0; i < totalRecords; i++)
                {
                    writer.Write(offsetValues[i]);
                    writer.Write(keys[i]);

                    var record = records[i];
                    writer.Write(record.Value);
                    writer.Write(new string(record.Buffer));
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Serialization error: {ex.Message}");
        }
    }

    public void DeserializeFromFile(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine("Deserialization file not found.");
            return;
        }

        try
        {
            using (var reader = new BinaryReader(File.Open(filePath, FileMode.Open)))
            {
                totalRecords = reader.ReadInt32();

                for (int i = 0; i < totalRecords; i++)
                {
                    offsetValues[i] = reader.ReadInt64();
                    keys[i] = reader.ReadInt32();

                    var record = records[i];
                    record.Value = reader.ReadInt32();
                    string bufferString = reader.ReadString();
                    Array.Copy(bufferString.ToCharArray(), record.Buffer, Math.Min(record.Buffer.Length, bufferString.Length));
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Deserialization error: {ex.Message}");
        }
    }

    public void Dispose()
    {
        if (records != null)
        {
            foreach (var record in records)
            {
                // Clean up resources if needed
            }
        }
    }
}
