#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <zlib.h>

typedef struct Job {
    int id;
    int priority;
    char *data; // Compressed data
} Job;

typedef struct Node {
    Job job;
    struct Node* next;
} Node;

typedef struct PriorityQueue {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    double loadFactor;
} PriorityQueue;

PriorityQueue* createQueue(size_t initialCapacity, double loadFactor) {
    PriorityQueue* queue = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->count = 0;
    queue->capacity = initialCapacity;
    queue->loadFactor = loadFactor;
    return queue;
}

void resizeIfNeeded(PriorityQueue* queue) {
    if (queue->count >= queue->capacity * queue->loadFactor) {
        // Resize logic: double the capacity
        size_t newCapacity = queue->capacity * 2;
        // Adjust internal data structures as needed
        queue->capacity = newCapacity;
    }
}

void enqueue(PriorityQueue* queue, Job job) {
    pthread_mutex_lock(&queue->lock);
    resizeIfNeeded(queue);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->job = job;

    if (!queue->head || job.priority > queue->head->job.priority) {
        newNode->next = queue->head;
        queue->head = newNode;
    } else {
        Node* current = queue->head;
        while (current->next && current->next->job.priority >= job.priority) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    queue->count++;
    pthread_mutex_unlock(&queue->lock);
}

Job dequeue(PriorityQueue* queue) {
    Job job = {0, 0, NULL};
    pthread_mutex_lock(&queue->lock);

    if (queue->head) {
        Node* nodeToDelete = queue->head;
        queue->head = nodeToDelete->next;
        job = nodeToDelete->job;
        free(nodeToDelete);
        queue->count--;
    }

    pthread_mutex_unlock(&queue->lock);
    return job;
}

char* compressData(const char* data, size_t originalSize) {
    uLongf compressedSize = compressBound(originalSize);
    char* compressedData = (char*)malloc(compressedSize);

    if (compress((Bytef*)compressedData, &compressedSize, (const Bytef*)data, originalSize) == Z_OK) {
        return compressedData;
    }

    free(compressedData);
    return NULL;
}

char* decompressData(const char* compressedData, size_t compressedSize, size_t originalSize) {
    char* decompressedData = (char*)malloc(originalSize);

    if (uncompress((Bytef*)decompressedData, &originalSize, (const Bytef*)compressedData, compressedSize) == Z_OK) {
        return decompressedData;
    }

    free(decompressedData);
    return NULL;
}

void retryWithBackoff(Job* job, int attempt) {
    // Exponential backoff logic
    double waitTime = pow(2, attempt); // Example: 2^attempt seconds
    printf("Retrying job %d in %.0f seconds\n", job->id, waitTime);
    sleep(waitTime);

    // Re-enqueue the job after delay
    enqueue(jobQueue, *job);
}

void logJobFailure(Job* job) {
    // Log failure for monitoring purposes
    printf("Job %d failed\n", job->id);
}

void monitorResourceUsage(PriorityQueue* queue) {
    pthread_t monitorThread;
    pthread_create(&monitorThread, NULL, (void*)[](void* arg) -> void* {
        PriorityQueue* q = (PriorityQueue*)arg;

        while (1) {
            sleep(5); // Check every 5 seconds
            double currentLoad = ((double)q->count / q->capacity);

            if (currentLoad > 0.8) { // Threshold for alerting
                printf("Warning: Queue load is at %.2f%%\n", currentLoad * 100);
            }
        }

        return NULL;
    }, queue);
}

// Example usage of the above functions
int main() {
    PriorityQueue* jobQueue = createQueue(10, 0.75);

    // Start resource monitoring in a separate thread
    monitorResourceUsage(jobQueue);

    char* data = "Job Data";
    size_t originalSize = strlen(data) + 1;

    Job newJob;
    newJob.id = 1;
    newJob.priority = 5;
    newJob.data = compressData(data, originalSize);

    enqueue(jobQueue, newJob);

    // Simulate job processing
    while (jobQueue->count > 0) {
        Job jobToProcess = dequeue(jobQueue);

        if (!processJob(&jobToProcess)) { // Assume processJob is defined elsewhere
            logJobFailure(&jobToProcess);
            retryWithBackoff(&jobToProcess, 1); // Retry with initial backoff attempt
        }

        free(jobToProcess.data);
    }

    return 0;
}
