int validate_range(int min, int max, int *range_size) {
    if (min >= max || max - min > INT_MAX) {
        return 0;
    }
    *range_size = max - min;
    return 1;
}

void initialize_arrays(size_t offset_count, size_t key_count, size_t record_count, int range_min, int range_max) {
    // Validate the input sizes and ranges
    if (offset_count <= 0 || key_count <= 0 || record_count <= 0) {
        fprintf(stderr, "Array sizes must be positive integers.\n");
        exit(EXIT_FAILURE);
    }

    int range_size;
    if (!validate_range(range_min, range_max, &range_size)) {
        fprintf(stderr, "Invalid range for random values.\n");
        exit(EXIT_FAILURE);
