#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_SYSTEM_MEMORY 1024 * 1024 * 100 // Example: 100 MB
#define SEGMENT_SIZE 1024 * 1024           // Example: 1 MB

typedef struct {
    long offset;
    int key;
} OffsetRecord;

typedef struct {
    int value;
    OffsetRecord* offset_record_ptr;
} KeyRecord;

typedef struct {
    int random_value;
} RandomValue;

static size_t total_allocated_memory = 0;
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void reseed_random_generator();

int is_safe_allocation(size_t requested_size) {
    pthread_mutex_lock(&memory_lock);
    if (total_allocated_memory + requested_size > MAX_SYSTEM_MEMORY) {
        pthread_mutex_unlock(&memory_lock);
        return 0; // Unsafe
    }
    total_allocated_memory += requested_size;
    pthread_mutex_unlock(&memory_lock);
    return 1; // Safe
}

void free_all() {
    pthread_mutex_lock(&memory_lock);
    total_allocated_memory = 0;
    pthread_mutex_unlock(&memory_lock);
}

void* allocate_segmented(size_t size) {
    void* ptr = malloc(size + SEGMENT_SIZE - (size % SEGMENT_SIZE));
    if (!ptr) return NULL;

    // Ensure alignment to segment boundaries
    char* aligned_ptr = (char*)ptr + ((uintptr_t)ptr % SEGMENT_SIZE);
    pthread_mutex_lock(&memory_lock);

    if (!is_safe_allocation((aligned_ptr - ptr) + size)) {
        free(ptr);
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    total_allocated_memory += (aligned_ptr - ptr) + size;
    pthread_mutex_unlock(&memory_lock);
    return aligned_ptr;
}

void initialize_offset_records(OffsetRecord** offset_array, int num_elements) {
    if (!offset_array || num_elements <= 0) return;

    *offset_array = allocate_segmented(num_elements * sizeof(OffsetRecord));
    if (*offset_array) memset(*offset_array, 0, num_elements * sizeof(OffsetRecord));
}

void initialize_key_records(KeyRecord** key_array, int num_elements, OffsetRecord* offset_array, size_t offset_count) {
    if (!key_array || !offset_array || num_elements <= 0) return;

    *key_array = allocate_segmented(num_elements * sizeof(KeyRecord));
    if (*key_array) {
        memset(*key_array, 0, num_elements * sizeof(KeyRecord));
        for (int i = 0; i < num_elements; ++i) {
            int index = rand() % offset_count; // Example: random valid index
            (*key_array)[i].offset_record_ptr = &offset_array[index];
        }
    }
}

void initialize_random_values(RandomValue** random_values, int num_elements) {
    if (!random_values || num_elements <= 0) return;

    *random_values = allocate_segmented(num_elements * sizeof(RandomValue));
    if (*random_values) {
        memset(*random_values, 0, num_elements * sizeof(RandomValue));

        #define NUM_THREADS 4
        pthread_t threads[NUM_THREADS];
        int chunk_size = num_elements / NUM_THREADS;
        void* arg = malloc(sizeof(size_t) * NUM_THREADS);

        for (int i = 0; i < NUM_THREADS; ++i) {
            ((size_t*)arg)[i] = (size_t)(i * chunk_size);
            pthread_create(&threads[i], NULL, [] (void* param) -> void* {
                size_t start_idx = *(size_t*)param;
                int local_seed = rand() % 1000 + 1; // Example seed
                for (size_t i = start_idx; i < start_idx + chunk_size && i < num_elements; ++i) {
                    ((RandomValue*)(*random_values))[i].random_value = rand_r(&local_seed);
                }
                reseed_random_generator();
                return NULL;
            }, &arg[i * sizeof(size_t)]);
        }

        for (int i = 0; i < NUM_THREADS; ++i)
            pthread_join(threads[i], NULL);

        free(arg);
    }
}

void reseed_random_generator() {
    static unsigned int next = 1;
    next = next * 1103515245 + 12345;
    srand(next >> 16);
}

int main() {
    OffsetRecord* offset_array = NULL;
    KeyRecord* key_array = NULL;
    RandomValue* random_values = NULL;

    int num_offset_records, num_key_records, num_random_values;

    printf("Enter number of OffsetRecords: ");
    scanf("%d", &num_offset_records);
    printf("Enter number of KeyRecords: ");
    scanf("%d", &num_key_records);
    printf("Enter number of RandomValues: ");
    scanf("%d", &num_random_values);

    initialize_offset_records(&offset_array, num_offset_records);
    initialize_key_records(&key_array, num_key_records, offset_array, num_offset_records);
    initialize_random_values(&random_values, num_random_values);

    // Usage and processing logic...

    free_all();

    if (offset_array) free(offset_array);
    if (key_array) free(key_array);
    if (random_values) free(random_values);

    return 0;
}
