#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double latitude;
    double longitude;
} GeoLocation;

typedef struct {
    time_t timestamp;
    char eventType[50];
    int uniqueID;
    int severityLevel; // 1 to 10, 10 being the highest
    GeoLocation geoLocation;
} TrafficEvent;

typedef struct Node {
    TrafficEvent event;
    struct Node* next;
} Node;

// Dynamic array of TrafficEvents
typedef struct {
    Node* head;
    size_t size;
} TrafficEventList;

void initTrafficEventList(TrafficEventList* list) {
    list->head = NULL;
    list->size = 0;
}

Node* createNode(const TrafficEvent* event) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    memcpy(&newNode->event, event, sizeof(TrafficEvent));
    newNode->next = NULL;
    return newNode;
}

void addTrafficEvent(TrafficEventList* list, const TrafficEvent* event) {
    Node* newNode = createNode(event);
    if (!newNode) return;

    if (list->head == NULL || list->head->event.timestamp > event->timestamp) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->event.timestamp < event->timestamp) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    list->size++;
}

void removeTrafficEvent(TrafficEventList* list, int uniqueID) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->event.uniqueID != uniqueID) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (prev == NULL) { // Remove head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
}

void updateTrafficEvent(TrafficEventList* list, int uniqueID, const TrafficEvent* updatedEvent) {
    Node *current = list->head;

    while (current != NULL && current->event.uniqueID != uniqueID) {
        current = current->next;
    }

    if (current == NULL) return;

    memcpy(&current->event, updatedEvent, sizeof(TrafficEvent));
}

void serializeTrafficEvents(const TrafficEventList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    size_t count;
    Node* current = list->head;

    fwrite(&count, sizeof(size_t), 1, file);

    while (current != NULL) {
        fwrite(&(current->event), sizeof(TrafficEvent), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserializeTrafficEvents(TrafficEventList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    TrafficEvent event;
    while (fread(&event, sizeof(TrafficEvent), 1, file)) {
        addTrafficEvent(list, &event);
    }

    fclose(file);
}

void freeTrafficEvents(TrafficEventList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;
}

TrafficEvent generateRandomEvent() {
    TrafficEvent event;
    srand(time(NULL));
    event.timestamp = time(NULL) + rand() % (60 * 60); // within the next hour
    snprintf(event.eventType, sizeof(event.eventType), "EventType%d", rand() % 5);
    event.uniqueID = rand();
    event.severityLevel = rand() % 10 + 1;
    event.geoLocation.latitude = -90.0 + (180.0 * ((double)rand() / RAND_MAX));
    event.geoLocation.longitude = -180.0 + (360.0 * ((double)rand() / RAND_MAX));

    return event;
}

void simulateTrafficEvents(TrafficEventList* list, size_t numEvents) {
    for (size_t i = 0; i < numEvents; ++i) {
        TrafficEvent event = generateRandomEvent();
        addTrafficEvent(list, &event);
    }
}

int main() {
    srand(time(NULL));

    TrafficEventList list;
    initTrafficEventList(&list);

    simulateTrafficEvents(&list, 100); // Simulate 100 random events

    serializeTrafficEvents(&list, "traffic_data.bin");
    freeTrafficEvents(&list);

    initTrafficEventList(&list);
    deserializeTrafficEvents(&list, "traffic_data.bin");

    freeTrafficEvents(&list);

    return 0;
}
```

