dataset_t* create_dataset(size_t max_records, const char* charset, size_t max_record_size) {
    dataset_t* ds = (dataset_t*)malloc(sizeof(dataset_t));
    if (!ds) {
        log_message(1, "Memory allocation failed for dataset.");
        return NULL;
    }

    ds->entries = NULL;
    ds->count = 0;
    ds->capacity = 0;
    ds->max_records = max_records;
    pthread_mutex_init(&ds->lock, NULL);
    ds->charset = charset;
