}

int resize_dataset(dataset_t* ds, size_t new_capacity) {
    entry_t* new_entries = realloc(ds->entries, new_capacity * sizeof(entry_t));
    if (!new_entries) {
        log_message(1, "Memory allocation failed during resizing.");
        return -1;
    }

    ds->capacity = new_capacity;
    ds->entries = new_entries;
    log_message(2, "Dataset resized.");
    return 0;
}

int add_record(dataset_t* ds, long offset, int key, const char* buffer_content) {
    if (ds->count >= ds->max_records) {
        log_message(1, "Maximum record count exceeded.");
        return -1;
    }

    with synchronized(ds.lock):
        if (resize_dataset(ds, ds->capacity + 10) != 0) {
            return -1;
        }

        entry_t new_entry = {offset, key};
        snprintf(new_entry.record.buffer, sizeof(new_entry.record.buffer), "%s", buffer_content);
        new_entry.record.value = rand() % 100; // Example value generation
        ds->entries[ds->count++] = new_entry;

    log_message(2, "Record added.");
    return 0;
}

int process_input(dataset_t* ds) {
    long offset;
    int key;
    while (fscanf(stdin, "%ld %d", &offset, &key) == 2) {
        char buffer_content[256];
        for (int i = 0; i < sizeof(buffer_content) - 1; ++i) {
            buffer_content[i] = ds->charset[rand() % strlen(ds->charset)];
        }
        buffer_content[sizeof(buffer_content) - 1] = '\0';

        if (add_record(ds, offset, key, buffer_content) != 0) {
            log_message(1, "Failed to add record.");
            return -1;
        }
    }

    log_message(2, "Input processing completed.");
    return 0;
}

int serialize_dataset(const dataset_t* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message(1, "Failed to open file for serialization.");
        return -1;
    }

    with synchronized(ds.lock):
        fwrite(&ds->count, sizeof(size_t), 1, file);
        fwrite(ds->entries, sizeof(entry_t), ds->count, file);

    fclose(file);
    log_message(2, "Dataset serialized.");
    return 0;
}

dataset_t* deserialize_dataset(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message(1, "Failed to open file for deserialization.");
        return NULL;
    }

    dataset_t* ds = create_dataset(100, "abcdefghijklmnopqrstuvwxyz", 256);
    if (!ds) {
        fclose(file);
        return NULL;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    with synchronized(ds.lock):
        if (resize_dataset(ds, count) != 0) {
            free_dataset(ds);
            fclose(file);
            return NULL;
        }

        fread(ds->entries, sizeof(entry_t), count, file);
        ds->count = count;

    fclose(file);
    log_message(2, "Dataset deserialized.");
    return ds;
}

void configure_logging(int level, FILE* output) {
    log_level = level;
    if (output != NULL) {
        log_file = output;
    }
}

int main() {
    dataset_t* ds = create_dataset(1000, "abcdefghijklmnopqrstuvwxyz", 256);
    if (!ds) return EXIT_FAILURE;

    configure_logging(2, stdout);

    process_input(ds);

    serialize_dataset(ds, "dataset.bin");

    free_dataset(ds);

    return EXIT_SUCCESS;
}
```

This code provides a solution that processes input from standard input to create records in a dynamically allocated dataset. It includes thread safety using mutex locks and manages the memory efficiently with resizing mechanisms. Serialization and deserialization functions are implemented for saving/loading the dataset, along with flexible logging capabilities.']

['Here is a C implementation for the `configure_and_manage_storage` function, incorporating the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define metadata structure
typedef struct {
    time_t timestamp;
    char event_type[50];
} Metadata;

// Define configuration setting structure
typedef struct ConfigSetting {
    char *key;
    char *value;
    int version;
    Metadata metadata;
    struct ConfigSetting *next; // For chaining in hash table
} ConfigSetting;

// Define logging level
typedef enum { INFO, DEBUG, ERROR } LogLevel;

// Logging backend interface
typedef struct {
    void (*log)(LogLevel level, const char* message);
} LogBackend;

// File-based log backend example
void file_log(LogLevel level, const char* message) {
    // Example implementation for logging to a file
    FILE *file = fopen("config.log", "a");
    if (file) {
        fprintf(file, "[%ld] %s: %s\n", time(NULL), level == INFO ? "INFO" : level == DEBUG ? "DEBUG" : "ERROR", message);
        fclose(file);
    }
}

LogBackend file_backend = { .log = file_log };

// Hash table size
#define HASH_TABLE_SIZE 256

typedef struct {
    ConfigSetting *table[HASH_TABLE_SIZE];
    pthread_mutex_t locks[HASH_TABLE_SIZE]; // Array of mutexes for each bucket
    int version_threshold;
} Storage;

unsigned int hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

void free_setting(ConfigSetting *setting) {
    if (setting) {
        free(setting->key);
        free(setting->value);
        free(setting);
    }
}

ConfigStorage* configure_and_manage_storage(int version_threshold, LogBackend backend) {
    Storage *storage = malloc(sizeof(Storage));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        storage->table[i] = NULL;
        pthread_mutex_init(&storage->locks[i], NULL);
    }
    storage->version_threshold = version_threshold;

    // Example logging initialization
    backend.log(INFO, "Storage configured with version threshold: %d", version_threshold);

    return (ConfigStorage *)storage;
}

void add_or_update_setting(Storage *storage, const char *key, const char *value) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&storage->locks[index]);

    ConfigSetting *current = storage->table[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            free(current->value);
            current->value = strdup(value);
            current->version++;
            current->metadata.timestamp = time(NULL);
            strcpy(current->metadata.event_type, "UPDATE");
            // Log update
            storage->backend.log(INFO, "Updated setting: %s", key);
            pthread_mutex_unlock(&storage->locks[index]);
            return;
        }
        current = current->next;
    }

    ConfigSetting *new_setting = malloc(sizeof(ConfigSetting));
    new_setting->key = strdup(key);
    new_setting->value = strdup(value);
    new_setting->version = 1;
    new_setting->metadata.timestamp = time(NULL);
    strcpy(new_setting->metadata.event_type, "ADD");
    new_setting->next = storage->table[index];
    storage->table[index] = new_setting;

    // Log addition
    storage->backend.log(INFO, "Added setting: %s", key);

    pthread_mutex_unlock(&storage->locks[index]);
}

ConfigSetting* get_setting(Storage *storage, const char *key) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&storage->locks[index]);

    ConfigSetting *current = storage->table[index];
    while (current) {
        if (strcmp(current->key, key) == 0 && current->version >= storage->version_threshold) {
            pthread_mutex_unlock(&storage->locks[index]);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&storage->locks[index]);
    return NULL; // Key not found or outdated
}

void invalidate_outdated_settings(Storage *storage) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&storage->locks[i]);

        ConfigSetting *current = storage->table[i];
        ConfigSetting *prev = NULL;
        while (current) {
            if (current->version < storage->version_threshold) {
                if (prev)
                    prev->next = current->next;
                else
                    storage->table[i] = current->next;

                ConfigSetting *to_free = current;
                current = current->next;
                free_setting(to_free);

                // Log invalidation
                storage->backend.log(INFO, "Invalidated outdated setting: %s", to_free->key);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&storage->locks[i]);
    }
}

void free_storage(Storage *storage) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        ConfigSetting *current = storage->table[i];
        while (current) {
            ConfigSetting *to_free = current;
            current = current->next;
            free_setting(to_free);
        }
        pthread_mutex_destroy(&storage->locks[i]);
    }
    free(storage);
}

int main() {
    LogBackend backend = file_backend; // Example backend
    Storage *storage = configure_and_manage_storage(1, backend);

    add_or_update_setting(storage, "key1", "value1");
    ConfigSetting *setting = get_setting(storage, "key1");

    if (setting) {
        printf("Retrieved setting: %s=%s\n", setting->key, setting->value);
    }

    invalidate_outdated_settings(storage);

    free_storage(storage);
    return 0;
}
```

### Explanation:

- **Data Structures**: 
  - `ConfigSetting`: Holds configuration settings with key, value, version, and metadata.
  - `Metadata`: Stores timestamps and event types for change tracking.
  - `LogBackend`: Interface for logging mechanisms.

- **Hash Table**:
  - Uses separate chaining to handle collisions.
  - Each bucket has its own mutex for thread safety.

- **Logging**:
  - Supports different log levels and backends (e.g., file-based).
  - Logs changes with timestamps and event types.

- **Thread Safety**:
  - Fine-grained locking using an array of mutexes, one per hash table bucket.

- **Memory Management**:
  - Safely allocates and deallocates memory for settings and metadata.

- **Version Control**:
  - Settings are invalidated based on a version threshold.

This implementation is designed to be modular, allowing easy integration with different storage backends and logging mechanisms.']

