    }
    logMessage("Records array allocated and initialized.");

cleanup:
    if (errorFlag) {
        free(offsets);
        free(keys);
        if (*records) free(*records);
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}

void freeResources(long* offsets, int* keys, Record* records) {
