// File Path Processor
class FilePathProcessor {
public:
    void processFilePaths() {
        std::mutex mtx;
        std::condition_variable cv;
        std::queue<std::string> pathQueue;
        std::unordered_map<std::string, int> cache;
        std::atomic<int> activeThreads{0};
        const size_t CACHE_SIZE = 100;

        auto worker = [&]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [&] { return !pathQueue.empty() || shutdown; });
                if (shutdown && pathQueue.empty()) break;

                auto path = pathQueue.front();
                pathQueue.pop();
                lock.unlock();

                int depth = calculateDepth(path, cache, CACHE_SIZE);

                std::cout << "Path: " << path << ", Depth: " << depth << std::endl;
            }
        };

        bool shutdown = false;
        while (std::cin) {
            std::string line;
            if (!std::getline(std::cin, line)) break;
            {
                std::lock_guard<std::mutex> lock(mtx);
                pathQueue.push(line);
            }
            cv.notify_one();
        }

        shutdown = true;
        cv.notify_all();

        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            activeThreads++;
            std::thread(worker).detach();
        }

        while (activeThreads > 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

private:
    int calculateDepth(const std::string& path, 
                       std::unordered_map<std::string, int>& cache, 
                       size_t cacheSize) {
        if (cache.find(path) != cache.end()) return cache[path];

        // Simulate directory depth calculation
        int depth = path.count('/') + 1;

        // Evict least recently used entry if cache is full
        if (cache.size() >= cacheSize) {
            auto it = cache.begin();
