['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock; // Read-write lock for thread safety
} RecordList;

// Function to create a new node
Node* create_node(int value, long offset, int key) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->record.value = value;
    new_node->record.offset = malloc(sizeof(long));
    new_node->record.key = malloc(sizeof(int));

    if (!new_node->record.offset || !new_node->record.key) {
        free(new_node);
        return NULL;
    }

    *new_node->record.offset = offset;
    *new_node->record.key = key;
    new_node->next = NULL;

    return new_node;
}

// Function to initialize the record list
RecordList* init_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);

    return list;
}

// Add a new record to the list
void add_record(RecordList* list, int value, long offset, int key) {
    pthread_rwlock_wrlock(&list->lock);

    Node *new_node = create_node(value, offset, key);
    if (!new_node) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_rwlock_unlock(&list->lock);
}

// Remove a record from the list by key
void remove_record(RecordList* list, int key) {
    pthread_rwlock_wrlock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && *current->record.key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    if (prev == NULL) { // Head is the node to be deleted
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->record.offset);
    free(current->record.key);
    free(current);

    pthread_rwlock_unlock(&list->lock);
}

// Function to serialize a record into binary format
size_t serialize_record(const Record* record, unsigned char** buffer) {
    size_t offset_size = sizeof(long);
    size_t key_size = sizeof(int);

    size_t total_size = sizeof(record->value) + offset_size + key_size;
    *buffer = (unsigned char*)malloc(total_size);

    if (!*buffer) return 0;

    unsigned char* ptr = *buffer;
    memcpy(ptr, &record->value, sizeof(record->value));
    ptr += sizeof(record->value);
    memcpy(ptr, record->offset, offset_size);
    ptr += offset_size;
    memcpy(ptr, record->key, key_size);

    return total_size;
}

// Function to deserialize a binary buffer into a Record
Record* deserialize_record(const unsigned char* buffer) {
    size_t value_size = sizeof(int);
    size_t offset_size = sizeof(long);
    size_t key_size = sizeof(int);

    if (!buffer) return NULL;

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = *((int*)(buffer));
    buffer += value_size;
    record->offset = (long*)malloc(offset_size);
    memcpy(record->offset, buffer, offset_size);
    buffer += offset_size;
    record->key = (int*)malloc(key_size);
    memcpy(record->key, buffer, key_size);

    return record;
}

// Function to clean up the record list
void free_record_list(RecordList* list) {
    pthread_rwlock_wrlock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->record.offset);
        free(current->record.key);
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

// Unit tests
void test_record_management() {
    RecordList* list = init_record_list();
    if (!list) return;

    add_record(list, 10, 100, 1);
    add_record(list, 20, 200, 2);

    pthread_rwlock_rdlock(&list->lock);
    Node *current = list->head;

    while (current != NULL) {
        printf("Record: value=%d, offset=%ld, key=%d\n", current->record.value,
               *(current->record.offset), *(current->record.key));

        // Serialize the record
        unsigned char* buffer;
        size_t size = serialize_record(&current->record, &buffer);
        if (size > 0) {
            Record *deserialized = deserialize_record(buffer);
            printf("Deserialized: value=%d, offset=%ld, key=%d\n", deserialized->value,
                   *(deserialized->offset), *(deserialized->key));

            free(deserialized->offset);
            free(deserialized->key);
            free(deserialized);
            free(buffer);
        }

        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);

    remove_record(list, 1);

    free_record_list(list);
}

int main() {
    test_record_management();
    return 0;
}
