```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DATASETS 1000

typedef struct {
    int id;
    time_t timestamp;
    int *values;
    size_t count; // Number of integer values in the dataset
} DataSet;

typedef struct {
    DataSet datasets[MAX_DATASETS];
    pthread_mutex_t lock;
} DataManager;

DataManager data_manager = { .lock = PTHREAD_MUTEX_INITIALIZER };

// Utility function to calculate mean
double calculate_mean(int *data, size_t n) {
    if (n == 0) return 0.0;
    long sum = 0;
    for (size_t i = 0; i < n; ++i) {
        sum += data[i];
    }
    return (double)sum / n;
}

// Utility function to calculate median
double calculate_median(int *data, size_t n) {
    if (n == 0) return 0.0;

    // Copy data and sort it
    int *sorted_data = malloc(n * sizeof(int));
    memcpy(sorted_data, data, n * sizeof(int));

    qsort(sorted_data, n, sizeof(int), (int (*)(const void *, const void *)) strcmp);

    double median;
    if (n % 2 == 0) {
        median = ((double)sorted_data[n / 2 - 1] + sorted_data[n / 2]) / 2.0;
    } else {
        median = (double)sorted_data[n / 2];
    }

    free(sorted_data);
    return median;
}

// Utility function to calculate mode
int calculate_mode(int *data, size_t n, int *mode_count) {
    if (n == 0) return -1;

    int max_count = 0;
    int mode_value = data[0];
    int counts[MAX_DATASETS] = {0};

    for (size_t i = 0; i < n; ++i) {
        counts[data[i]]++;
    }

    for (int i = 0; i < MAX_DATASETS; ++i) {
        if (counts[i] > max_count) {
            max_count = counts[i];
            mode_value = i;
        }
    }

    *mode_count = max_count;
    return mode_value;
}

// Function to process and analyze datasets
void process_and_analyze_data_sets(int min_values) {
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        pthread_mutex_lock(&data_manager.lock);

        int id, value;
        time_t timestamp = time(NULL);
        DataSet *ds = NULL;

        // Parse the input to extract identifier and values
        if (sscanf(line, "%d:", &id) == 1) {
            ds = find_dataset_by_id(data_manager.datasets, MAX_DATASETS, id);
            if (!ds) {
                // Create new dataset
                ds = create_new_dataset(id, timestamp);
                log_operation("Created new dataset with ID: %d", id);
            }

            // Update the existing or newly created dataset
            char *token = strtok(line + strlen(line), ":");
            while (token != NULL) {
                if (sscanf(token, "%d", &value) == 1) {
                    add_value_to_dataset(ds, value);
                }
                token = strtok(NULL, ":");
            }

            // Check for minimum values condition
            if (ds->count < min_values) {
                log_operation("Dataset ID %d removed due to insufficient data points.", id);
                remove_dataset(data_manager.datasets, MAX_DATASETS, ds);
            } else {
                // Calculate statistical metrics
                int mode_count = 0;
                double mean = calculate_mean(ds->values, ds->count);
                double median = calculate_median(ds->values, ds->count);
                int mode = calculate_mode(ds->values, ds->count, &mode_count);

                printf("ID: %d\n", id);
                printf("Mean: %.2f\n", mean);
                printf("Median: %.2f\n", median);
                printf("Mode: %d (Count: %d)\n", mode, mode_count);
            }
        }

        pthread_mutex_unlock(&data_manager.lock);
    }
}

// Additional helper functions would be defined here:
// - find_dataset_by_id
// - create_new_dataset
// - add_value_to_dataset
// - remove_dataset
// - log_operation

// Main function for demonstration (not part of the module)
int main() {
    process_and_analyze_data_sets(3);
    return 0;
}
