#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

void initialize_records(record **records, size_t *size) {
    const size_t initial_size = 10;
    const size_t threshold = 80; // Threshold for resizing

    if (*size == 0) {
        *records = (record *)malloc(initial_size * sizeof(record));
        if (*records == NULL) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        *size = initial_size;
    }

    srand(time(NULL)); // Seed for random offset generation
    size_t current_count = 0;

    while (current_count < *size) {
        record r;
        r.key = current_count; // Unique key per iteration
        r.offset = rand() % 10000; // Random offset between 0 and 9999

        (*records)[current_count++] = r;
    }

    if ((double)current_count / *size > threshold / 100.0) {
        size_t new_size = *size * 2;
        record *new_records = (record *)realloc(*records, new_size * sizeof(record));
        if (new_records == NULL) {
            perror("Failed to reallocate memory");
            free(*records);
            exit(EXIT_FAILURE);
        }
        *records = new_records;
        *size = new_size;
    }
}

// Example usage
int main() {
    record *records = NULL;
    size_t size = 0;

    initialize_records(&records, &size);

    for (size_t i = 0; i < size && i < 10; ++i) { // Print first 10 records as example
        printf("Record %zu: Key = %d, Offset = %ld\n", i, records[i].key, records[i].offset);
    }

    free(records);
    return 0;
}
