<?php

class UserAccountManager {
    private $db;

    public function __construct(PDO $db) {
        $this->db = $db;
    }

    public function handleRequest($data) {
        if (!$this->validateData($data)) {
            return "Invalid data provided.";
        }

        if (isset($data['sub_action']) && $data['sub_action'] === 'delete') {
            return $this->deleteUserAccount($data['id']);
        } elseif (isset($data['id'])) {
            return $this->updateUserAccount($data);
        } else {
            return $this->createUserAccount($data);
        }
    }

    private function validateData($data) {
        if (empty($data['email']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            return false;
        }

        if (strlen($data['password']) < 8) {
            return false;
        }

        // Add more validation rules as needed
        return true;
    }

    private function createUserAccount($data) {
        $stmt = $this->db->prepare("INSERT INTO users (email, password) VALUES (:email, :password)");
        $stmt->execute([
            ':email' => $data['email'],
            ':password' => password_hash($data['password'], PASSWORD_DEFAULT)
        ]);

        return "User created successfully.";
    }

    private function updateUserAccount($data) {
        $stmt = $this->db->prepare("UPDATE users SET email = :email, password = :password WHERE id = :id");
        $stmt->execute([
            ':id' => $data['id'],
            ':email' => $data['email'],
            ':password' => password_hash($data['password'], PASSWORD_DEFAULT)
        ]);

        return "User updated successfully.";
    }

    private function deleteUserAccount($id) {
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = :id");
        $stmt->execute([':id' => $id]);

        return "User deleted successfully.";
    }
}

// Example usage
try {
    $pdo = new PDO('mysql:host=localhost;dbname=testdb', 'username', 'password');
    $userManager = new UserAccountManager($pdo);

    $data = [
        'email' => 'user@example.com',
        'password' => 'securepassword123'
    ];

    echo $userManager->handleRequest($data);
} catch (PDOException $e) {
    echo "Connection failed: " . $e->getMessage();
}
