#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RECORD_COUNT 100
#define OFFSET_ARRAY_SIZE 50
#define KEY_ARRAY_SIZE 50
#define FIELD_NAMES_COUNT 10

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    char field_name[50];
    int resource_id;
    char url[200];
} DialogField;

void handleMemoryError(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void refreshDialogFields(Record records[], int record_count, DialogField dialog_fields[], int field_names_count) {
    srand(time(NULL));

    long *offset_array = (long *)malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    if (offset_array == NULL) {
        handleMemoryError("Failed to allocate offset_array");
        return;
    }

    int *key_array = (int *)malloc(KEY_ARRAY_SIZE * sizeof(int));
    if (key_array == NULL) {
        free(offset_array);
        handleMemoryError("Failed to allocate key_array");
        return;
    }

    Record *records_array = (Record *)malloc(RECORD_COUNT * sizeof(Record));
    if (records_array == NULL) {
        free(key_array);
        free(offset_array);
        handleMemoryError("Failed to allocate records_array");
        return;
    }

    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offset_array[i] = rand() % 10000;
    }

    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        key_array[i] = rand() % 100;
    }

    for (int i = 0; i < RECORD_COUNT; i++) {
        records_array[i].key = key_array[rand() % KEY_ARRAY_SIZE];
        records_array[i].offset = offset_array[rand() % OFFSET_ARRAY_SIZE];
    }

    char field_names[FIELD_NAMES_COUNT][50] = {"field1", "field2", "field3", "field4", "field5",
                                               "field6", "field7", "field8", "field9", "field10"};

    for (int i = 0; i < record_count; i++) {
        for (int j = 0; j < field_names_count; j++) {
            if (strcmp(dialog_fields[j].field_name, field_names[j]) == 0) {
                dialog_fields[j].resource_id = records_array[i].key;
                snprintf(dialog_fields[j].url, sizeof(dialog_fields[j].url),
                         "http://example.com/resource_%d", records_array[i].offset);
            }
        }
    }

    free(offset_array);
    free(key_array);
    free(records_array);
}
