#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

// Product structure definition
typedef struct {
    int id;
    char name[50];
    double price;
    unsigned int quantity;
} Product;

// Inventory structure with a linked list for dynamic resizing
typedef struct Node {
    Product product;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Inventory;

// Function prototypes
Inventory* initialize_inventory(int num_products, const char** names, double* prices);
void free_inventory(Inventory* inventory);
EVP_CIPHER* get_cipher(const char* mode);
void update_product_quantity_and_price(Inventory* inventory, void (*callback)(Product*, double*));
void iterate_inventory(Inventory* inventory);

// Initialize inventory with dynamic memory allocation
Inventory* initialize_inventory(int num_products, const char** names, double* prices) {
    Inventory* inventory = malloc(sizeof(Inventory));
    if (!inventory) return NULL;

    inventory->head = NULL;
    pthread_mutex_init(&inventory->lock, NULL);

    for (int i = 0; i < num_products; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) continue;

        new_node->product.id = i;
        strncpy(new_node->product.name, names[i], sizeof(new_node->product.name) - 1);
        new_node->product.price = prices[i];
        new_node->product.quantity = 0; // Initialize with zero quantity
        new_node->next = inventory->head;
        inventory->head = new_node;
    }
    return inventory;
}

// Free allocated memory for the inventory
void free_inventory(Inventory* inventory) {
    if (!inventory) return;

    Node* current = inventory->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&inventory->lock);
    free(inventory);
}

// Get a cipher based on the mode
EVP_CIPHER* get_cipher(const char* mode) {
    if (strcmp(mode, "ECB") == 0) return EVP_des_ecb();
    else if (strcmp(mode, "EDE") == 0) return EVP_des_ede3_nid(0);
    else if (strcmp(mode, "EDE3") == 0) return EVP_des_ede3();
    else if (strcmp(mode, "CFB") == 0) return EVP_des_cfb64();
    else if (strcmp(mode, "NULL") == 0) return EVP_null_cipher();

    fprintf(stderr, "Unsupported cipher mode\n");
    return NULL;
}

// Update product quantity and price using a callback function
void update_product_quantity_and_price(Inventory* inventory, void (*callback)(Product*, double*)) {
    pthread_mutex_lock(&inventory->lock);

    Node* current = inventory->head;
    while (current) {
        if (callback) {
            double new_price;
            callback(&current->product, &new_price);
            current->product.price = new_price;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&inventory->lock);
}

// Iterate over the inventory
void iterate_inventory(Inventory* inventory) {
    pthread_mutex_lock(&inventory->lock);

    Node* current = inventory->head;
    while (current) {
        printf("Product ID: %d, Name: %s, Price: %.2f, Quantity: %u\n",
               current->product.id,
               current->product.name,
               current->product.price,
               current->product.quantity);
        current = current->next;
    }

    pthread_mutex_unlock(&inventory->lock);
}

// Example callback function
void example_callback(Product* product, double* new_price) {
    // Logic to calculate the new price and update quantity
    *new_price = product->price * 1.05; // Increase price by 5%
    product->quantity += 10;            // Add 10 units
}

// Example usage
int main() {
    const char* names[] = {"Product A", "Product B"};
    double prices[] = {100.0, 200.0};

    Inventory* inventory = initialize_inventory(2, names, prices);
    if (!inventory) return EXIT_FAILURE;

    iterate_inventory(inventory);

    update_product_quantity_and_price(inventory, example_callback);

    iterate_inventory(inventory);

    free_inventory(inventory);

    return EXIT_SUCCESS;
}
