import subprocess
import time
import logging
from typing import List

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DNSManager:
    def __init__(self, servers: List[str], timeout: int = 5):
        self.servers = servers
        self.timeout = timeout
        self.best_server = None

    def run_command(self, command: str) -> str:
        try:
            result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            return result.stdout.decode().strip()
        except subprocess.CalledProcessError as e:
            logging.error(f"Command '{command}' failed with error: {e.stderr.decode().strip()}")
            raise

    def ping_server(self, server_ip: str) -> float:
        command = f"ping -c 1 -W {self.timeout} {server_ip}"
        try:
            start_time = time.time()
            self.run_command(command)
            end_time = time.time()
            return end_time - start_time
        except Exception as e:
            logging.warning(f"Ping to server {server_ip} failed: {e}")
            return float('inf')

    def update_dns_configuration(self):
        # Find the best DNS server based on ping times
        response_times = {}
        for server in self.servers:
            try:
                response_time = self.ping_server(server)
                response_times[server] = response_time
            except Exception as e:
                logging.error(f"Failed to evaluate server {server}: {e}")

        if not response_times:
            raise RuntimeError("No reachable DNS servers available")

        # Select the server with the lowest response time
        self.best_server = min(response_times, key=response_times.get)
        logging.info(f"Selected best DNS server: {self.best_server} with response time {response_times[self.best_server]}s")

    def configure_system_dns(self):
        command = f"systemd-resolve --set-dns={self.best_server}"
        try:
            self.run_command(command)
            logging.info("DNS configuration updated successfully.")
        except Exception as e:
            logging.error(f"Failed to update DNS configuration: {e}")
            raise

    def monitor_and_adapt(self):
        while True:
            try:
                self.update_dns_configuration()
                self.configure_system_dns()
                time.sleep(60)  # Check every minute
            except Exception as e:
                logging.error(f"Error during monitoring and adaptation: {e}")

def main(servers: List[str]):
    manager = DNSManager(servers)
    manager.monitor_and_adapt()

if __name__ == "__main__":
    dns_servers = ["8.8.8.8", "1.1.1.1", "9.9.9.9"]  # Example server IPs
    main(dns_servers)
```

This script manages a distributed DNS server configuration system with dynamic updates and redundancy. It uses `subprocess` to execute commands like `ping`, ensuring the best DNS server is selected based on response time. The script handles errors robustly, logs detailed information, and adapts to changes in server availability.']

