#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Item {
    int intValue;
    float floatValue;
    struct Item* next;  // Pointer for linked list structure
} Item;

// Function to initialize a dynamic collection of items using a linked list
Item* createItemsLinkedList(int numItems) {
    if (numItems <= 0) return NULL;

    srand(time(NULL));  // Seed the random number generator

    // Allocate memory for the head of the list
    Item* head = malloc(sizeof(Item));
    if (!head) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    Item* current = head;

    for (int i = 0; i < numItems; ++i) {
        // Allocate memory for the next item
        current->next = malloc(sizeof(Item));
        if (!current->next) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Initialize the item with random values
        current->intValue = rand() % 100 + 1;
        current->floatValue = (float)rand() / RAND_MAX;

        // Move to the next node
        current = current->next;
    }

    // Terminate the list
    current->next = NULL;

    return head;  // Return the head of the list
}

// Function to free the memory allocated for a linked list of items
void freeItemsLinkedList(Item* head) {
    Item *current = head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int numItems = 10;  // Example number of items
    Item* items = createItemsLinkedList(numItems);

    // For demonstration: traverse the list and print values
    Item* current = items;
    while (current != NULL) {
        printf("Int: %d, Float: %.2f\n", current->intValue, current->floatValue);
        current = current->next;
    }

    freeItemsLinkedList(items);  // Clean up allocated memory

    return 0;
}
