#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define MAX_LIMIT 1024

typedef struct {
    int value;
} record;

typedef struct {
    int key;
    long offset;
    record rec;
} entry;

typedef struct {
    entry *entries;
    size_t capacity;
    size_t count;
} table;

table* create_table() {
    table *tbl = (table*) malloc(sizeof(table));
    if (!tbl) return NULL;

    tbl->capacity = INITIAL_CAPACITY;
    tbl->count = 0;
    tbl->entries = (entry*) calloc(tbl->capacity, sizeof(entry));
    if (!tbl->entries) {
        free(tbl);
        return NULL;
    }

    return tbl;
}

int resize_table(table *tbl, size_t new_capacity) {
    entry *new_entries = (entry*) realloc(tbl->entries, new_capacity * sizeof(entry));
    if (!new_entries) return -1;

    memset(new_entries + tbl->capacity, 0, (new_capacity - tbl->capacity) * sizeof(entry));
    tbl->entries = new_entries;
    tbl->capacity = new_capacity;

    return 0;
}

int insert_entry(table *tbl, int key, long offset, record rec) {
    if (tbl->count >= MAX_LIMIT) return -1;

    size_t index = 0;
    while ((index < tbl->capacity) && (tbl->entries[index].key != 0)) {
        if (tbl->entries[index].key == key) {
            tbl->entries[index].offset += offset; // handle collision by updating the offset
            tbl->entries[index].rec = rec;
            return 0;
        }
        index++;
    }

    if (index >= tbl->capacity && resize_table(tbl, tbl->capacity * 2) != 0) {
        return -1;
    }

    while ((tbl->entries[key % tbl->capacity].key != 0) && 
           (tbl->entries[key % tbl->capacity].key == key)) {
        key++;
    }

    if (key >= MAX_LIMIT) return -1;

    tbl->entries[index = key % tbl->capacity] = (entry){.key = key, .offset = offset, .rec = rec};
    tbl->count++;

    return 0;
}

void validate_and_update_offsets(table *tbl) {
    for (size_t i = 0; i < tbl->count; ++i) {
        if (tbl->entries[i].key != 0 && tbl->entries[i].offset <= 0) {
            printf("Error: Invalid offset for key %d\n", tbl->entries[i].key);
            tbl->entries[i].offset = -1;
        }
    }

    long cumulative_offset = 0;
    for (size_t i = 0; i < tbl->capacity; ++i) {
        if (tbl->entries[i].key != 0) {
            tbl->entries[i].offset = cumulative_offset++;
        }
    }
}

void free_table(table *tbl) {
    free(tbl->entries);
    free(tbl);
}

int main() {
    table *myTable = create_table();
    if (!myTable) {
        fprintf(stderr, "Failed to allocate memory for the table\n");
        return EXIT_FAILURE;
    }

    record rec1 = {.value = 10};
    insert_entry(myTable, 1, 100, rec1);

    validate_and_update_offsets(myTable);

    free_table(myTable);
    return EXIT_SUCCESS;
}
