#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the DataPacket structure
typedef struct {
    int id;
    time_t timestamp;
    int status_flag; // 0 for inactive, 1 for active
    int priority_level;
} DataPacket;

// Node in a linked list to store packets
typedef struct PacketNode {
    DataPacket data;
    struct PacketNode* next;
} PacketNode;

// Linked list structure to manage DataPackets
typedef struct {
    PacketNode* head;
    pthread_mutex_t lock;
} PacketList;

// Function prototypes
void init_packet_list(PacketList* list);
int add_packet(PacketList* list, int id, time_t timestamp, int status_flag, int priority_level);
int update_packet(PacketList* list, int id, int new_status_flag, int new_priority_level);
DataPacket* get_packet_by_id(PacketList* list, int id);
void purge_expired_packets(PacketList* list, time_t expiration_threshold);
void sort_packets_by_priority(PacketList* list);
void free_packet_list(PacketList* list);

// Function implementations
void init_packet_list(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int add_packet(PacketList* list, int id, time_t timestamp, int status_flag, int priority_level) {
    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) return -1;

    new_node->data.id = id;
    new_node->data.timestamp = timestamp;
    new_node->data.status_flag = status_flag;
    new_node->data.priority_level = priority_level;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head || list->head->data.priority_level < priority_level) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        PacketNode* current = list->head;
        while (current->next && current->next->data.priority_level >= priority_level) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int update_packet(PacketList* list, int id, int new_status_flag, int new_priority_level) {
    pthread_mutex_lock(&list->lock);
    PacketNode *current = list->head, *prev = NULL;

    while (current) {
        if (current->data.id == id) {
            current->data.status_flag = new_status_flag;
            current->data.priority_level = new_priority_level;

            // Re-sort the node if priority level changed
            if (prev || list->head != current || prev && prev->data.priority_level < new_priority_level) {
                PacketNode* temp = current;
                if (prev) {
                    prev->next = current->next;
                } else {
                    list->head = current->next;
                }
                temp->next = NULL;

                current = list->head;
                while (current && current->data.priority_level >= new_priority_level) {
                    prev = current;
                    current = current->next;
                }

                if (!prev) {
                    temp->next = list->head;
                    list->head = temp;
                } else {
                    temp->next = prev->next;
                    prev->next = temp;
                }
            }
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Packet not found
}

DataPacket* get_packet_by_id(PacketList* list, int id) {
    pthread_mutex_lock(&list->lock);
    PacketNode *current = list->head;

    while (current) {
        if (current->data.id == id) {
            DataPacket* packet_copy = (DataPacket*)malloc(sizeof(DataPacket));
            if (!packet_copy) {
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            *packet_copy = current->data;
            pthread_mutex_unlock(&list->lock);
            return packet_copy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Packet not found
}

void purge_expired_packets(PacketList* list, time_t expiration_threshold) {
    pthread_mutex_lock(&list->lock);
    PacketNode *current = list->head, *prev = NULL;

    while (current) {
        if (difftime(time(NULL), current->data.timestamp) > expiration_threshold) {
            PacketNode* temp = current;
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void sort_packets_by_priority(PacketList* list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || !list->head->next) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    PacketNode *sorted = NULL;

    while (list->head) {
        PacketNode* current = list->head;
        PacketNode* next = current->next;
        list->head = next;

        if (!sorted || sorted->data.priority_level <= current->data.priority_level) {
            current->next = sorted;
            sorted = current;
        } else {
            PacketNode* temp = sorted;
            while (temp->next && temp->next->data.priority_level > current->data.priority_level) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }
    }

    list->head = sorted;

    pthread_mutex_unlock(&list->lock);
}

void free_packet_list(PacketList* list) {
    pthread_mutex_lock(&list->lock);

    PacketNode *current = list->head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    // Example usage
    PacketList packet_list;
    init_packet_list(&packet_list);

    add_packet(&packet_list, 1, time(NULL), 1, 10);
    add_packet(&packet_list, 2, time(NULL), 0, 20);

    DataPacket* packet = get_packet_by_id(&packet_list, 1);
    if (packet) {
        printf("Packet ID: %d\n", packet->id);
        free(packet);
    }

    update_packet(&packet_list, 1, 0, 15);

    purge_expired_packets(&packet_list, 60); // Purge packets older than 60 seconds

    sort_packets_by_priority(&packet_list);

    free_packet_list(&packet_list);
    return 0;
}
