['Below is a C implementation for managing a dynamic collection of records with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct DynamicCollection {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection *collection = malloc(sizeof(DynamicCollection));
    collection->records = calloc(initial_capacity, sizeof(Record *));
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_rwlock_init(&collection->rwlock, NULL);
    return collection;
}

void destroy_collection(DynamicCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->offset);
        free(collection->records[i]->key);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

void resize_collection(DynamicCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    Record **new_records = realloc(collection->records, new_capacity * sizeof(Record *));
    if (new_records) {
        memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(Record *));
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
}

void add_record(DynamicCollection *collection, int value, long offset, int key) {
    pthread_rwlock_wrlock(&collection->rwlock);
    if (collection->count == collection->capacity) {
        resize_collection(collection);
    }

    Record *record = malloc(sizeof(Record));
    record->value = value;
    record->offset = malloc(sizeof(long));
    *(record->offset) = offset;
    record->key = malloc(sizeof(int));
    *(record->key) = key;

    collection->records[collection->count++] = record;
    pthread_rwlock_unlock(&collection->rwlock);
}

Record* get_record(DynamicCollection *collection, size_t index) {
    pthread_rwlock_rdlock(&collection->rwlock);
    Record *record = NULL;
    if (index < collection->count) {
        record = collection->records[index];
    }
    pthread_rwlock_unlock(&collection->rwlock);
    return record;
}

void update_record(DynamicCollection *collection, size_t index, int value, long offset, int key) {
    pthread_rwlock_wrlock(&collection->rwlock);
    if (index < collection->count) {
        Record *record = collection->records[index];
        record->value = value;
        *(record->offset) = offset;
        *(record->key) = key;
    }
    pthread_rwlock_unlock(&collection->rwlock);
}

void serialize_record(const Record *record, FILE *file) {
    fwrite(&record->value, sizeof(int), 1, file);
    long offset = *(record->offset);
    fwrite(&offset, sizeof(long), 1, file);
    int key = *(record->key);
    fwrite(&key, sizeof(int), 1, file);
}

void deserialize_record(Record *record, FILE *file) {
    fread(&record->value, sizeof(int), 1, file);
    long offset;
    fread(&offset, sizeof(long), 1, file);
    record->offset = malloc(sizeof(long));
    *(record->offset) = offset;
    fread(&(record->key), sizeof(int), 1, file);
    record->key = malloc(sizeof(int));
    memcpy(record->key, &(record->key), sizeof(int));
}

void unit_tests() {
    // Implement unit tests to validate functionality and thread safety
    DynamicCollection *collection = create_collection(2);

    add_record(collection, 10, 1000, 1);
    add_record(collection, 20, 2000, 2);

    Record *record = get_record(collection, 0);
    printf("Record 0: %d, %ld, %d\n", record->value, *(record->offset), *(record->key));

    update_record(collection, 1, 30, 3000, 3);
    record = get_record(collection, 1);
    printf("Updated Record 1: %d, %ld, %d\n", record->value, *(record->offset), *(record->key));

    FILE *file = fopen("records.dat", "wb");
    for (size_t i = 0; i < collection->count; ++i) {
        serialize_record(get_record(collection, i), file);
    }
    fclose(file);

    Record deserialized_record;
    file = fopen("records.dat", "rb");
    deserialize_record(&deserialized_record, file);
    printf("Deserialized Record: %d, %ld, %d\n", deserialized_record.value, *(deserialized_record.offset), *(deserialized_record.key));
    fclose(file);

    destroy_collection(collection);
}

int main() {
    unit_tests();
    return 0;
}
```

### Key Features:
- **Dynamic Memory Management**: The collection dynamically resizes to accommodate more records.
- **Thread Safety**: Uses `pthread_rwlock_t` for read-write locks, allowing concurrent reads and exclusive writes.
