typedef struct {
    int value;
    long* offset;
    int* key;
} Record;

#define MAX_RECORDS 1000
#define JSON_SIZE 1024
#define PROTOBUF_SIZE 512
#define LOG_BUFFER_SIZE 4096

Record records[MAX_RECORDS];
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char* json_data;
    unsigned char protobuf_data[PROTOBUF_SIZE];
} SerializedData;

void error_exit(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

int load_records_from_file(const char *file_path, Record **records_out) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        return -1;
    }

    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, fp);
    if (num_records > MAX_RECORDS) {
        fclose(fp);
        return -2;
    }

    *records_out = malloc(num_records * sizeof(Record));
    if (!*records_out) {
        fclose(fp);
        return -3;
    }

    for (size_t i = 0; i < num_records; ++i) {
        fread(&(*records_out)[i].value, sizeof(int), 1, fp);
        size_t offset_ptr_size;
        fread(&offset_ptr_size, sizeof(size_t), 1, fp);
        if (offset_ptr_size != sizeof(long*)) {
            free(*records_out);
            fclose(fp);
            return -4;
        }
        fread(&(*records_out)[i].offset, sizeof(long*), 1, fp);

        size_t key_ptr_size;
        fread(&key_ptr_size, sizeof(size_t), 1, fp);
        if (key_ptr_size != sizeof(int*)) {
            free(*records_out);
            fclose(fp);
            return -5;
        }
        fread(&(*records_out)[i].key, sizeof(int*), 1, fp);
    }

    fclose(fp);
    return 0;
}

int serialize_records(SerializedData *data) {
    pthread_mutex_lock(&record_lock);

    char json[JSON_SIZE] = {0};
    int num_records = sizeof(records) / sizeof(Record);

    // JSON serialization
    strcpy(json, "[");
    for (int i = 0; i < num_records; ++i) {
        if (i > 0) strcat(json, ",");
        char record_json[256];
        sprintf(record_json, "{\"value\": %d, \"offset\": %ld, \"key\": %d}", records[i].value,
                *records[i].offset, *records[i].key);
        strcat(json, record_json);
    }
    strcat(json, "]");

    // ProtoBuf serialization (pseudo-code for illustration)
    unsigned char proto_buffer[PROTOBUF_SIZE] = {0};
    int proto_size = 0;
    for (int i = 0; i < num_records; ++i) {
        // Serialize each record to protobuf format
        // This is a placeholder. Actual implementation needed.
        memcpy(&proto_buffer[proto_size], &records[i].value, sizeof(int));
        proto_size += sizeof(int);
        // Add offset and key similarly...
    }

    pthread_mutex_unlock(&record_lock);

    data->json_data = strdup(json);
    if (!data->json_data) {
        return -1;
    }
    memcpy(data->protobuf_data, proto_buffer, proto_size);

    return 0;
}

int compress_and_serialize(SerializedData *data) {
    uLongf compressed_size = PROTOBUF_SIZE + (PROTOBUF_SIZE / 10) + 12; // Extra space for gzip
    unsigned char compressed[compressed_size];

    int status = compress2(compressed, &compressed_size, data->protobuf_data, PROTOBUF_SIZE, Z_BEST_COMPRESSION);
    if (status != Z_OK) {
        return -1;
    }

    FILE *fp = fopen("serialized_records.bin", "wb");
    if (!fp) {
        return -2;
    }
    fwrite(compressed, compressed_size, 1, fp);
    fclose(fp);

    return 0;
}

void log_message(const char *message) {
    static char buffer[LOG_BUFFER_SIZE];
    static size_t current_pos = 0;

    size_t len = strlen(message);
    if (current_pos + len < LOG_BUFFER_SIZE) {
        memcpy(&buffer[current_pos], message, len);
        current_pos += len;
        buffer[current_pos++] = '\n';
    } else {
        fwrite(buffer, current_pos, 1, stdout);
        current_pos = 0;
        log_message(message); // Retry logging after clearing buffer
    }
}

void initialize_records(const char *file_path) {
    int status = load_records_from_file(file_path, &records[0]);
    if (status != 0) {
        error_exit("Failed to load records.");
    }
}

// Unit Tests Placeholder - Implement comprehensive unit tests here

int main() {
    const char *data_file = "data.bin";

    initialize_records(data_file);

    SerializedData serialized_data;
    int status = serialize_records(&serialized_data);
    if (status != 0) {
        error_exit("Serialization failed.");
    }

    status = compress_and_serialize(&serialized_data);
    if (status != 0) {
        error_exit("Compression and serialization to file failed.");
    }

    log_message("Records processed successfully.");

    free(serialized_data.json_data);

    return 0;
}
