#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_SEMAPHORES 5000
#define SEMAPHORE_NAME_LEN 32

typedef struct {
    sem_t semaphore;
    int priority;
    time_t last_used;
} SemaphoreEntry;

typedef struct {
    SemaphoreEntry *semaphores[MAX_SEMAPHORES];
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    int (*resource_monitor)(void);
    void (*adjust_semaphore_limits)(size_t new_limit);
} SemaphoreManager;

SemaphoreManager* create_manager(int (*resource_monitor)(void), void (*adjust_semaphore_limits)(size_t)) {
    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->count = 0;
    manager->capacity = MAX_SEMAPHORES;
    memset(manager->semaphores, 0, sizeof(manager->semaphores));
    pthread_mutex_init(&manager->lock, NULL);
    manager->resource_monitor = resource_monitor;
    manager->adjust_semaphore_limits = adjust_semaphore_limits;

    return manager;
}

void destroy_manager(SemaphoreManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        sem_destroy(&(manager->semaphores[i]->semaphore));
        free(manager->semaphores[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int create_semaphore(SemaphoreManager *manager, int priority) {
    if (!manager || manager->count >= manager->capacity) return -1;

    SemaphoreEntry *entry = malloc(sizeof(SemaphoreEntry));
    if (!entry) return -1;

    sem_init(&(entry->semaphore), 0, 0);
    entry->priority = priority;
    time(&entry->last_used);

    pthread_mutex_lock(&manager->lock);
    manager->semaphores[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);

    if (manager->resource_monitor && manager->adjust_semaphore_limits) {
        int load = manager->resource_monitor();
        if (load > 80) { // Example threshold for high resource usage
            size_t new_limit = manager->capacity / 2; 
            manager->adjust_semaphore_limits(new_limit);
        }
    }

    return 0;
}

int destroy_semaphore(SemaphoreManager *manager, int index) {
    if (!manager || index < 0 || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);
    sem_destroy(&(manager->semaphores[index]->semaphore));
    free(manager->semaphores[index]);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->semaphores[i] = manager->semaphores[i + 1];
    }
    manager->semaphores[--manager->count] = NULL;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int acquire_semaphore(SemaphoreManager *manager, int index, unsigned int timeout) {
    if (!manager || index < 0 || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);
    time_t start = time(NULL);
    while (sem_trywait(&(manager->semaphores[index]->semaphore)) == -1 && 
           (timeout == 0 || difftime(time(NULL), start) < timeout)) {
        if (sem_trywait(&(manager->semaphores[index]->semaphore)) != -1) break;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1; // Sleep for 1 second
        nanosleep(&ts, NULL);
    }
    time(&manager->semaphores[index]->last_used);
    pthread_mutex_unlock(&manager->lock);

    return sem_trywait(&(manager->semaphores[index]->semaphore)) == 0 ? 0 : -1;
}

int release_semaphore(SemaphoreManager *manager, int index) {
    if (!manager || index < 0 || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);
    sem_post(&(manager->semaphores[index]->semaphore));
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void evict_unused_semaphores(SemaphoreManager *manager, time_t max_idle_time) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    size_t i = 0;
    while (i < manager->count) {
        if (difftime(time(NULL), manager->semaphores[i]->last_used) > max_idle_time) {
            destroy_semaphore(manager, i);
        } else {
            ++i;
        }
    }
