#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct Dataset {
    Record* head;
    size_t current_size;
    size_t max_threshold;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(size_t max_threshold) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) {
        perror("Failed to allocate memory for Dataset");
        return NULL;
    }

    dataset->head = NULL;
    dataset->current_size = 0;
    dataset->max_threshold = max_threshold;
    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void release_dataset(Dataset* dataset) {
    if (!dataset) return;

    Record* current = dataset->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_or_update_record(Dataset* dataset, int key, long offset) {
    if (!dataset || dataset->current_size >= dataset->max_threshold) {
        fprintf(stderr, "Failed to add/update record: memory limit reached or invalid dataset.\n");
        return -1;
    }

    pthread_mutex_lock(&dataset->lock);

    Record* current = dataset->head;
    Record* prev = NULL;

    while (current && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current) {
        current->offset = offset;
    } else {
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            perror("Failed to allocate memory for Record");
            pthread_mutex_unlock(&dataset->lock);
            return -1;
        }

        new_record->key = key;
        new_record->offset = offset;
        new_record->next = NULL;

        if (prev) {
            prev->next = new_record;
        } else {
            dataset->head = new_record;
        }

        dataset->current_size++;
    }

    pthread_mutex_unlock(&dataset->lock);
    return 0;
}

```

