#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    int status; // 0 for inactive, 1 for active
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t packet_count;
    size_t memory_usage;
    time_t expiration_threshold;
} PacketManager;

PacketManager* create_packet_manager(time_t expiration_threshold) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->packet_count = 0;
    manager->memory_usage = 0;
    manager->expiration_threshold = expiration_threshold;

    return manager;
}

void destroy_packet_manager(PacketManager* manager) {
    if (!manager) return;

    Node *current, *next;
    pthread_mutex_lock(&manager->lock);

    current = manager->head;
    while (current) {
        next = current->next;
        free(current);
        manager->memory_usage -= sizeof(Node); // Adjust based on actual memory usage
        manager->packet_count--;
        current = next;
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_packet(PacketManager* manager, int id) {
    if (!manager) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->packet.id = id;
    new_node->packet.timestamp = time(NULL);
    new_node->packet.status = 1;
    new_node->next = NULL;

    pthread_mutex_lock(&manager->lock);

    new_node->next = manager->head;
    manager->head = new_node;

    manager->packet_count++;
    manager->memory_usage += sizeof(Node); // Adjust based on actual memory usage

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_packet(PacketManager* manager, int id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current) {
        if (current->packet.id == id && current->packet.status == 1) {
            // Update logic here
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

DataPacket* get_packet(PacketManager* manager, int id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current) {
        if (current->packet.id == id && current->packet.status == 1) {
            pthread_mutex_unlock(&manager->lock);
            return &current->packet;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void purge_expired_packets(PacketManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    time_t now = time(NULL);

    while (current) {
        if (difftime(now, current->packet.timestamp) > manager->expiration_threshold && current->packet.status == 1) {
            if (prev) {
                prev->next = current->next;
            } else {
                manager->head = current->next;
            }

            Node *temp = current;
            current = current->next;

            free(temp);
            manager->memory_usage -= sizeof(Node); // Adjust based on actual memory usage
            manager->packet_count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void monitor_packet_manager(PacketManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    printf("Packet Count: %zu\n", manager->packet_count);
    printf("Memory Usage: %zu bytes\n", manager->memory_usage);

    pthread_mutex_unlock(&manager->lock);
}
```

