} Summary;

const char* predefined_words[] = {"apple", "banana", "cherry", "date", "elderberry"};
const int num_predefined_words = sizeof(predefined_words) / sizeof(predefined_words[0]);

void initialize_memory(double** doubles, char*** strings, Record*** records, Metadata*** metadata_pointers, Config*** configs, size_t* total_count) {
    *total_count = 5;

    // Allocate memory for arrays
    *doubles = (double*)malloc(*total_count * sizeof(double));
    if (*doubles == NULL) goto fail;

    *strings = (char**)malloc(*total_count * sizeof(char*));
    if (*strings == NULL) goto fail_doubles;

    *records = (Record**)malloc(*total_count * sizeof(Record*));
    if (*records == NULL) goto fail_strings;

    *metadata_pointers = (Metadata**)malloc(*total_count * sizeof(Metadata*));
    if (*metadata_pointers == NULL) goto fail_records;

    *configs = (Config**)malloc(*total_count * sizeof(Config*));
    if (*configs == NULL) goto fail_metadata_pointers;

    srand(time(NULL));

    // Initialize double array
    for (size_t i = 0; i < *total_count; ++i) {
        (*doubles)[i] = (double)(rand() % 100 + 1);
    }

    // Initialize char strings
    const size_t max_string_length = 50;
    for (size_t i = 0; i < *total_count; ++i) {
        (*strings)[i] = (char*)malloc(max_string_length * sizeof(char));
        if ((*strings)[i] == NULL) goto fail_configs;

        snprintf((*strings)[i], max_string_length, "%s", predefined_words[rand() % num_predefined_words]);
    }

    // Initialize records and metadata pointers
    for (size_t i = 0; i < *total_count; ++i) {
        (*records)[i] = (Record*)malloc(sizeof(Record));
        if ((*records)[i] == NULL) goto fail_strings_cleanup;

        (*records)[i]->number = rand() % 100 + 1;
        (*records)[i]->decimal = (float)(rand() / (RAND_MAX + 1.0));

        (*metadata_pointers)[i] = (Metadata*)malloc(sizeof(Metadata));
        if ((*metadata_pointers)[i] == NULL) goto fail_records_cleanup;

        (*metadata_pointers)[i]->string = strdup(predefined_words[rand() % num_predefined_words]);
        if ((*metadata_pointers)[i]->string == NULL) goto fail_metadata_cleanup;

        (*metadata_pointers)[i]->value = rand() % 50 + 1;
        (*records)[i]->meta_data = *metadata_pointers[i];
    }

    // Initialize config array
    for (size_t i = 0; i < *total_count; ++i) {
        (*configs)[i] = (Config*)malloc(sizeof(Config));
        if ((*configs)[i] == NULL) goto fail_metadata_cleanup;

        (*configs)[i]->flag = true;
        (*configs)[i]->integer_value = rand() % 1000 + 1;
    }

    // Allocate and return summary
    Summary* summary = (Summary*)malloc(sizeof(Summary));
    if (summary == NULL) {
        for (size_t i = 0; i < *total_count; ++i) free((*strings)[i]);
        fail_strings_cleanup:
        for (size_t i = 0; i < *total_count; ++i) free(*metadata_pointers[i]);
        fail_metadata_cleanup:
        for (size_t i = 0; i < *total_count; ++i) free(*records[i]);
        fail_records_cleanup:
        for (size_t i = 0; i < *total_count; ++i) free((*configs)[i]);
        fail_configs:
        free(*metadata_pointers);
        fail_metadata_pointers:
        free(*records);
        fail_records:
        free(*strings);
        fail_strings:
        free(*doubles);
        fail_doubles:
    } else {
        summary->doubles_count = *total_count;
        summary->strings_count = *total_count;
        summary->records_count = *total_count;
        summary->metadata_count = *total_count;
        summary->configs_count = *total_count;

        // Return the summary
        printf("Memory initialized successfully.\n");
    }
}

int main() {
    double* doubles = NULL;
    char** strings = NULL;
    Record** records = NULL;
    Metadata** metadata_pointers = NULL;
    Config** configs = NULL;
    size_t total_count;

    initialize_memory(&doubles, &strings, &records, &metadata_pointers, &configs, &total_count);

    // Free all allocated memory
    for (size_t i = 0; i < total_count; ++i) {
        free(strings[i]);
        free(metadata_pointers[i]->string);
        free(metadata_pointers[i]);
        free(records[i]);
        free(configs[i]);
    }
    free(strings);
    free(metadata_pointers);
    free(records);
    free(configs);
    free(doubles);

    return 0;
}
