['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1048576 // 1 MB

typedef struct {
    int key;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t n, m, k;
} MemoryManager;

int validate_parameters(size_t n, size_t m, size_t k) {
    if (n == 0 || m == 0 || k == 0) return -1; // Invalid parameters
    size_t total_size = n * sizeof(long) + m * sizeof(int) + k * sizeof(record);
    if (total_size > MAX_MEMORY) return -2; // Exceeds memory limit
    return 0;
}

void initialize_records(record *records, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % 2001 - 1000; // Random value between -1000 and 1000
    }
}

MemoryManager* allocate_memory(size_t n, size_t m, size_t k) {
    if (validate_parameters(n, m, k)) return NULL;

    MemoryManager *manager = (MemoryManager *)malloc(sizeof(MemoryManager));
    if (!manager) return NULL; // Failed to allocate manager

    long total_size = n * sizeof(long) + m * sizeof(int) + k * sizeof(record);

    void *block = malloc(total_size);
    if (!block) {
        free(manager);
        return NULL;
    }

    manager->offsets = (long *)block;
    block = (char *)block + n * sizeof(long);

    manager->keys = (int *)block;
    block = (char *)block + m * sizeof(int);

    manager->records = (record *)block;

    manager->n = n;
    manager->m = m;
    manager->k = k;

    initialize_records(manager->records, k);

    return manager;
}

void free_memory(MemoryManager *manager) {
    if (manager) {
        free(manager->records); // Since records is the last block
        free(manager);
    }
}

// Example usage:
int main() {
    size_t n = 1000;
    size_t m = 500;
    size_t k = 250;

    MemoryManager *mm = allocate_memory(n, m, k);

    if (!mm) {
        printf("Failed to allocate memory.\n");
        return EXIT_FAILURE;
    }

    // Use the allocated memory...

    free_memory(mm);
    return EXIT_SUCCESS;
}
