        return NULL;
    }
    log_operation("Allocation", "Allocated a new node");
    return new_node;
}

int rnti_exists(unsigned int rnti) {
    for (int i = 0; i < node_count; ++i) {
        if (rnti_set[i] == rnti) {
            return 1;
        }
    }
    return 0;
}

void add_rnti_to_set(unsigned int rnti) {
    if (node_count < MAX_NODES) {
        rnti_set[node_count++] = rnti;
    }
}

int create_and_populate_nfaapi_crc_indication_list(const char* label, void (*f)(const char*, const char*), const char* module) {
    pthread_mutex_lock(&mutex);

    log_operation("Module Load", module);

    f(label, module); // Execute the test function

    Node* current = head;
    while (current != NULL) {
        Node* next_node = current->next;

        // Check RNTI uniqueness
        if (!rnti_exists(current->data.RNTI)) {
            add_rnti_to_set(current->data.RNTI);
        } else {
            log_operation("Error", "Duplicate RNTI detected");
            pthread_mutex_unlock(&mutex);
            return -1; // Error code for duplicate RNTI
        }

        free(current); // Deallocate node
        log_operation("Deallocation", "Deallocated a node");

        current = next_node;
    }

    head = NULL;
    memset(rnti_set, 0, sizeof(rnti_set));
    node_count = 0;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

