int validate_parameters(int num_records, const int* keys, const long* offsets, 
                        int min_value, int max_value) {
    if (num_records <= 0 || !keys || !offsets) return 0;
    if (min_value > max_value) return 0;
    return 1;
}

record* initialize_records(int num_records, int *keys, long *offsets, 
                          int min_value, int max_value) {
    if (!validate_parameters(num_records, keys, offsets, min_value, max_value)) {
        return NULL;
    }

    srand(time(NULL));

    // Allocate memory for records
    record* records = (record*)aligned_alloc(alignof(record), num_records * sizeof(record));
    if (!records) return NULL;

    // Track used offsets to ensure uniqueness
    int *used_offsets = (int *)calloc(num_records, sizeof(int)); 
    if (!used_offsets) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        // Ensure unique offsets
        long offset;
        do {
            offset = offsets[rand() % num_records];
        } while (used_offsets[offset]);

        used_offsets[offset] = 1; // Mark this offset as used

        records[i].offset = &offsets[offset];

        // Assign a key, ensuring it points to an existing key
        int key_index = rand() % num_records;
        records[i].key = &keys[key_index];
    }

    free(used_offsets);

    return records;
}

void free_resources(record* records, int num_records) {
    if (records) free(records);
}

