// Define Item structure
typedef struct Item {
    int id;
    float value;
} Item;

// Memory block for custom allocator
#define BLOCK_SIZE 1024

typedef struct Block {
    size_t size;
    int free;
    void *data;
    struct Block *next;
} Block;

Block *freeList = NULL;
pthread_mutex_t memMutex = PTHREAD_MUTEX_INITIALIZER;

// Custom memory allocator functions
void *bestFitAlloc(size_t size) {
    pthread_mutex_lock(&memMutex);
    Block *current = freeList, *prev = NULL, *bestFit = NULL, *last = NULL;

    while (current) {
        if (current->free && current->size >= size) {
            if (!bestFit || current->size < bestFit->size) {
                bestFit = current;
                last = prev;
            }
        }
        prev = current;
        current = current->next;
    }

    if (bestFit) {
        bestFit->free = 0;
        pthread_mutex_unlock(&memMutex);
        return bestFit->data;
    } else {
        void *newBlock = malloc(BLOCK_SIZE + size);
        Block *block = (Block *)((char *)newBlock + BLOCK_SIZE);
        block->size = size;
        block->free = 0;
        block->next = NULL;

        if (last) last->next = block;
        else freeList = block;

        pthread_mutex_unlock(&memMutex);
        return newBlock;
    }
}

void worstFitFree(void *ptr) {
    pthread_mutex_lock(&memMutex);
    Block *current = freeList, *prev = NULL;

    while (current && current->data != ptr) {
        prev = current;
        current = current->next;
    }

    if (current) {
        current->free = 1;
    }
    pthread_mutex_unlock(&memMutex);
}

