```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    void* customData;  // Assume this points to a valid structure elsewhere
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

// Function to initialize the record array with a given initial capacity
int initRecordArray(RecordArray *array, size_t initialCapacity) {
    if (initialCapacity == 0) return -1;

    array->records = (Record *)calloc(initialCapacity, sizeof(Record));
    if (!array->records) {
        perror("Failed to allocate memory");
        return -1;
    }

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return 0;
}

// Function to add a new record
int addRecord(RecordArray *array, int key, long offset, void* customData) {
    if (key < 0 || offset < 0) {
        fprintf(stderr, "Out-of-range error: key or offset\n");
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    // Resize if necessary
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;  // Simple doubling strategy to minimize reallocations
        Record *newRecords = (Record *)realloc(array->records, newCapacity * sizeof(Record));

        if (!newRecords) {
            perror("Failed to resize memory");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->records = newRecords;
        array->capacity = newCapacity;
    }

    // Add the new record
    Record *record = &array->records[array->count++];
    record->key = key;
    record->offset = offset;
    record->customData = customData;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to free allocated memory
void freeRecordArray(RecordArray *array) {
    if (array->records) {
        free(array->records);
        array->records = NULL;
    }

    pthread_mutex_destroy(&array->lock);
    array->count = 0;
    array->capacity = 0;
}

// Example usage
int main() {
    RecordArray recordArray;

    if (initRecordArray(&recordArray, 10) != 0) {
        fprintf(stderr, "Failed to initialize record array\n");
        return EXIT_FAILURE;
    }

    // Simulate adding records from an external data source
    for (size_t i = 0; i < 25; ++i) {  // Adding more than initial capacity
        if (addRecord(&recordArray, i, i * 1000L, NULL) != 0) {
            fprintf(stderr, "Failed to add record\n");
        }
    }

    freeRecordArray(&recordArray);

    return EXIT_SUCCESS;
}
```

