```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB in bytes

typedef struct {
    int value;
    long offset;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t n;
    size_t m;
    size_t k;
} ResourceManager;

// Union-Find structure
typedef struct {
    int* parent;
    size_t size;
} UnionFind;

int validateInputs(size_t n, size_t m, size_t k) {
    if (n <= 0 || m <= 0 || k <= 0)
        return -1;
    size_t memoryUsage = sizeof(long) * n + sizeof(int) * m + sizeof(Record) * k;
    if (memoryUsage > MAX_MEMORY_USAGE)
        return -2;
    return 0;
}

long* allocateLongArray(size_t n, int errorCode) {
    long* array = NULL;
    if (errorCode == 0) {
        array = (long*)malloc(n * sizeof(long));
        if (!array) exit(errorCode);
    }
    return array;
}

int* allocateIntArray(size_t m, int errorCode) {
    int* array = NULL;
    if (errorCode == 0) {
        array = (int*)malloc(m * sizeof(int));
        if (!array) exit(errorCode);
    }
    return array;
}

Record* allocateRecordArray(size_t k, int errorCode) {
    Record* array = NULL;
    if (errorCode == 0) {
        array = (Record*)malloc(k * sizeof(Record));
        if (!array) exit(errorCode);
    }
    return array;
}

UnionFind* createUnionFind(size_t size) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->parent = (int*)calloc(size, sizeof(int));
    for (size_t i = 0; i < size; ++i)
        uf->parent[i] = -1;
    uf->size = size;
    return uf;
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] < 0)
        return x;
    else
        return uf->parent[x] = find(uf, uf->parent[x]);
}

void unionSets(UnionFind* uf, int x, int y) {
    x = find(uf, x);
    y = find(uf, y);
    if (x != y) {
        if (uf->parent[y] < uf->parent[x])
            uf->parent[x] = y;
        else {
            if (uf->parent[x] == uf->parent[y])
                --uf->parent[x];
            uf->parent[y] = x;
        }
    }
}

size_t countDisjointSets(UnionFind* uf) {
    size_t count = 0;
    for (size_t i = 0; i < uf->size; ++i)
        if (uf->parent[i] < 0)
            ++count;
    return count;
}

ResourceManager* resourceManager(size_t n, size_t m, size_t k) {
    int errorCode = validateInputs(n, m, k);
    if (errorCode != 0) {
        printf("Error: Invalid inputs. Code %d\n", errorCode);
        return NULL;
    }

    ResourceManager* manager = (ResourceManager*)malloc(sizeof(ResourceManager));
    manager->offsets = allocateLongArray(n, errorCode);
    manager->keys = allocateIntArray(m, errorCode);
    manager->records = allocateRecordArray(k, errorCode);

    srand(time(NULL));
    for (size_t i = 0; i < k; ++i) {
        manager->records[i].value = rand() % 2001 - 1000;
        manager->records[i].offset = rand();
    }

    manager->n = n;
    manager->m = m;
    manager->k = k;

    return manager;
}

void freeResourceManager(ResourceManager* manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
    }
}

size_t processArray(int* array, size_t length) {
    UnionFind* uf = createUnionFind(length);
    for (size_t i = 0; i < length - 1; ++i)
        unionSets(uf, array[i], array[i + 1]);
    size_t disjointSets = countDisjointSets(uf);

    free(uf->parent);
    free(uf);

    return disjointSets;
}

int main() {
    // Example usage of resourceManager
    ResourceManager* manager = resourceManager(1000, 500, 200);
    if (manager) {
        printf("ResourceManager initialized successfully.\n");
        freeResourceManager(manager);
    }

    // Simulate processing an array for disjoint sets
    size_t length = 1000000;
    int* array = (int*)malloc(length * sizeof(int));
    for (size_t i = 0; i < length; ++i)
        array[i] = rand() % length;

    clock_t start = clock();
    size_t disjointSets = processArray(array, length);
    clock_t end = clock();

    printf("Number of disjoint sets: %zu\n", disjointSets);
    printf("Processing time: %.2f ms\n", (double)(end - start) * 1000 / CLOCKS_PER_SEC);

    free(array);

    return 0;
}
```

