#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    uint64_t packet_id;
    time_t timestamp;
    int status_flag; // Example: 0 for active, 1 for inactive
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PacketList;

// Memory pool structure
typedef struct {
    size_t item_size;
    void** free_list;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t pool_lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t item_size, size_t initial_size);
void destroy_memory_pool(MemoryPool* pool);
DataPacket* allocate_packet(MemoryPool* pool);
void deallocate_packet(MemoryPool* pool, DataPacket* packet);

// Packet management
typedef struct {
    PacketList list;
    MemoryPool* pool;
} PacketManager;

PacketManager* init_packet_manager(size_t pool_size);
void destroy_packet_manager(PacketManager* manager);
DataPacket* add_packet(PacketManager* manager, uint64_t packet_id);
DataPacket* get_packet(PacketManager* manager, uint64_t packet_id);
int update_packet(PacketManager* manager, uint64_t packet_id, int status_flag);
void purge_expired_packets(PacketManager* manager, time_t current_time);

// Database integration (pseudo-code placeholders)
int db_connect();
int db_disconnect();
int serialize_and_store(DataPacket* packet);
DataPacket* deserialize_from_db(uint64_t packet_id);

// Command-line configuration
typedef struct {
    time_t expiration_threshold;
} Config;

Config parse_config(int argc, char** argv);

// Logging and monitoring
void log_memory_usage(PacketManager* manager);
void alert_excessive_usage(PacketManager* manager);

// Error handling (pseudo-code placeholders)
void handle_error(const char* error_message);

MemoryPool* create_memory_pool(size_t item_size, size_t initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->item_size = item_size;
    pool->max_size = initial_size;
    pool->current_size = 0;
    pool->free_list = calloc(initial_size, sizeof(void*));

    pthread_mutex_init(&pool->pool_lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        pool->free_list[i] = malloc(item_size);
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->pool_lock);

    for (size_t i = 0; i < pool->max_size; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    free(pool);
}

DataPacket* allocate_packet(MemoryPool* pool) {
    pthread_mutex_lock(&pool->pool_lock);

    if (pool->current_size == 0) {
        pthread_mutex_unlock(&pool->pool_lock);
        return NULL; // Pool exhausted
    }

    void** slot = &pool->free_list[--pool->current_size];
    DataPacket* packet = *slot;
    *slot = pool->free_list[pool->current_size];

    pthread_mutex_unlock(&pool->pool_lock);

    return packet;
}

void deallocate_packet(MemoryPool* pool, DataPacket* packet) {
    pthread_mutex_lock(&pool->pool_lock);

    if (pool->current_size == pool->max_size) {
        pthread_mutex_unlock(&pool->pool_lock);
        free(packet); // Pool is full, fallback to standard allocation
        return;
    }

    *(&pool->free_list[pool->current_size]++) = packet;

    pthread_mutex_unlock(&pool->pool_lock);
}

PacketManager* init_packet_manager(size_t pool_size) {
    PacketManager* manager = malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->pool = create_memory_pool(sizeof(DataPacket), pool_size);
    if (!manager->pool) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->list.lock, NULL);
    manager->list.head = NULL;

    // Initialize database connection
    if (db_connect() != 0) {
        destroy_packet_manager(manager);
        return NULL;
    }

    return manager;
}

void destroy_packet_manager(PacketManager* manager) {
    if (!manager) return;

    Node* current = manager->list.head;
    while (current) {
        Node* next = current->next;
        deallocate_packet(manager->pool, &current->data);
        free(current);
        current = next;
    }

    destroy_memory_pool(manager->pool);

    // Close database connection
    db_disconnect();

    pthread_mutex_destroy(&manager->list.lock);
    free(manager);
}

DataPacket* add_packet(PacketManager* manager, uint64_t packet_id) {
    if (!manager) return NULL;

    DataPacket* packet = allocate_packet(manager->pool);
    if (!packet) handle_error("Memory allocation failed");

    pthread_mutex_lock(&manager->list.lock);

    // Check for existing packet
    Node** curr = &manager->list.head;
    while (*curr) {
        if ((*curr)->data.packet_id == packet_id) {
            pthread_mutex_unlock(&manager->list.lock);
            return NULL; // Packet already exists
        }
        curr = &(*curr)->next;
    }

    *curr = malloc(sizeof(Node));
    if (!*curr) {
        deallocate_packet(manager->pool, packet);
        pthread_mutex_unlock(&manager->list.lock);
        handle_error("Memory allocation failed");
        return NULL;
    }

    (*curr)->data.packet_id = packet_id;
    (*curr)->data.timestamp = time(NULL);
    (*curr)->data.status_flag = 0; // Active
    (*curr)->next = NULL;

    pthread_mutex_unlock(&manager->list.lock);

    // Serialize and store in DB
    if (serialize_and_store(&(*curr)->data) != 0) {
        handle_error("Database operation failed");
    }

    return &(*curr)->data;
}

DataPacket* get_packet(PacketManager* manager, uint64_t packet_id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->list.lock);

    Node* current = manager->list.head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            pthread_mutex_unlock(&manager->list.lock);
            return &current->data;
        }
        current = current->next;
    }

    // Fallback to database retrieval
    DataPacket* packet = deserialize_from_db(packet_id);
    pthread_mutex_unlock(&manager->list.lock);

    if (packet) {
        // Add to in-memory list for quick access next time
        Node* node = malloc(sizeof(Node));
        if (!node) {
            handle_error("Memory allocation failed");
            return NULL;
        }

        node->data = *packet; // Copy data
        pthread_mutex_lock(&manager->list.lock);

        node->next = manager->list.head;
        manager->list.head = node;

        pthread_mutex_unlock(&manager->list.lock);
    }

    return packet;
}

int update_packet(PacketManager* manager, uint64_t packet_id, int status_flag) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->list.lock);

    Node* current = manager->list.head;
    while (current) {
        if (current->data.packet_id == packet_id) {
            current->data.status_flag = status_flag;
            pthread_mutex_unlock(&manager->list.lock);
            // Update in DB
            if (serialize_and_store(&current->data) != 0) {
                handle_error("Database operation failed");
                return -1;
            }
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->list.lock);
    return -1; // Packet not found
}

void purge_expired_packets(PacketManager* manager, time_t current_time) {
    if (!manager) return;

    pthread_mutex_lock(&manager->list.lock);

    Node** curr = &manager->list.head;
    while (*curr) {
        Node* entry = *curr;
        if (difftime(current_time, entry->data.timestamp) > 0) { // Expired
            *curr = entry->next;
            deallocate_packet(manager->pool, &entry->data);
            free(entry);

            // Remove from DB
            // pseudo-function: db_remove(packet_id)
        } else {
            curr = &(*curr)->next;
        }
    }

    pthread_mutex_unlock(&manager->list.lock);
}

Config parse_config(int argc, char** argv) {
    Config config;

    if (argc < 2) {
        handle_error("Insufficient arguments for configuration");
        exit(EXIT_FAILURE);
    }

    // Example: --expiration=3600
    if (strncmp(argv[1], "--expiration=", strlen("--expiration=")) == 0) {
        config.expiration_threshold = strtoul(&argv[1][strlen("--expiration=")], NULL, 10);
    } else {
        handle_error("Invalid configuration");
        exit(EXIT_FAILURE);
    }

    return config;
}

void log_memory_usage(PacketManager* manager) {
    if (!manager) return;

    size_t used = (size_t)(sizeof(DataPacket) * (manager->pool->max_size - manager->pool->current_size));
    size_t total = sizeof(DataPacket) * manager->pool->max_size;

    printf("Memory Usage: %zu/%zu bytes\n", used, total);
}

void alert_excessive_usage(PacketManager* manager) {
    if (!manager) return;

    size_t used = (size_t)(sizeof(DataPacket) * (manager->pool->max_size - manager->pool->current_size));
    size_t total = sizeof(DataPacket) * manager->pool->max_size;

    if ((used / (double)total) > 0.8) {
        printf("Alert: Memory usage exceeded 80%%\n");
    }
}

int main(int argc, char** argv) {
    Config config = parse_config(argc, argv);

    PacketManager* manager = init_packet_manager(INITIAL_POOL_SIZE);
    if (!manager) return EXIT_FAILURE;

    // Simulate operations
    add_packet(manager, 1);
    DataPacket* packet = get_packet(manager, 1);
    if (packet) update_packet(manager, 1, 1);

    purge_expired_packets(manager, time(NULL));

    log_memory_usage(manager);
    alert_excessive_usage(manager);

    destroy_packet_manager(manager);
    return EXIT_SUCCESS;
}
