        IMemoryCache cache,
        ILogger<ContentUpdateService> logger,
        IElementUpdater elementUpdater)
    {
        _htmlSanitizer = htmlSanitizer ?? throw new ArgumentNullException(nameof(htmlSanitizer));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _elementUpdater = elementUpdater ?? throw new ArgumentNullException(nameof(elementUpdater));
    }

    public async Task<string> UpdateElementContentAsync(int pageSectionId, int elementId, string htmlContent)
    {
        try
        {
            // Validate inputs
            if (pageSectionId <= 0 || elementId <= 0)
                return "Invalid IDs provided.";

            var cacheKey = GetCacheKey(pageSectionId, elementId);

            if (_cache.TryGetValue(cacheKey, out string cachedHtml))
            {
                _logger.LogInformation("Serving content from cache.");
                return "Page refreshed with cached data.";
            }

            // Sanitize HTML
            var sanitizedContent = _htmlSanitizer.Sanitize(htmlContent);

            // Validate HTML version compatibility
            if (!IsVersionCompatible(sanitizedContent, elementId))
                return "Incompatible HTML version.";

            // Update content using service class in a background task for high throughput
            await Task.Run(() => _elementUpdater.UpdateElementHtml(pageSectionId, elementId, sanitizedContent));

            // Cache the updated content
            var cacheEntryOptions = new MemoryCacheEntryOptions()
                .SetSlidingExpiration(TimeSpan.FromMinutes(5))
                .SetPriority(CacheItemPriority.High);

            _cache.Set(cacheKey, sanitizedContent, cacheEntryOptions);

            return "Page refreshed.";
        }
        catch (Exception ex)
