['Below is an implementation of a C function that initializes and manages a list of `NFAPI_MESSAGE_T` structures, ensuring thread-safe operations using mutexes for synchronization. The design considers high-throughput scenarios with concurrent access.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Assuming these are defined elsewhere in the framework
typedef struct {
    int type;
    time_t timestamp;
    char* payload;
} NFAPI_MESSAGE_T;

// Node structure for the message list
struct MessageNode {
    NFAPI_MESSAGE_T message;
    struct MessageNode* next;
};

// List management structure
typedef struct {
    struct MessageNode* head;
    pthread_mutex_t lock;
    void (*log_function)(const char*); // Logging function pointer
} MessageList;

// Function to log messages
void default_log(const char* message) {
    printf("%s\n", message);
}

// Initialize the message list
MessageList* init_message_list(void (*log_func)(const char*)) {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->log_function = log_func ? log_func : default_log;

    return list;
}

// Validate message integrity
int validate_message(NFAPI_MESSAGE_T* message) {
    if (message == NULL || message->payload == NULL) {
        return 0; // Invalid
    }
    // Additional validation logic can be added here
    return 1; // Valid
}

// Add a message to the list, prioritized by type and timestamp
void add_message(MessageList* list, NFAPI_MESSAGE_T message) {
    if (!validate_message(&message)) {
        list->log_function("Invalid message encountered.");
        return;
    }

    struct MessageNode* new_node = (struct MessageNode*)malloc(sizeof(struct MessageNode));
    if (!new_node) {
        list->log_function("Memory allocation failed for new node.");
        return;
    }

    new_node->message = message;

    pthread_mutex_lock(&list->lock);

    // Insert node in order of priority: type, then timestamp
    struct MessageNode** current = &list->head;
    while (*current != NULL) {
        if (message.type < (*current)->message.type ||
            (message.type == (*current)->message.type && message.timestamp < (*current)->message.timestamp)) {
            break;
        }
        current = &(*current)->next;
    }

    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Remove a specific message from the list
void remove_message(MessageList* list, NFAPI_MESSAGE_T target) {
    pthread_mutex_lock(&list->lock);

    struct MessageNode **current = &list->head;
    while (*current != NULL) {
        if ((*current)->message.type == target.type &&
            (*current)->message.timestamp == target.timestamp) {

            struct MessageNode* temp = *current;
            *current = (*current)->next;

            free(temp->message.payload); // Assuming payload was dynamically allocated
            free(temp);
            pthread_mutex_unlock(&list->lock);

            list->log_function("Message removed successfully.");
            return;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    list->log_function("Target message not found for removal.");
}

// Cleanup the message list
void free_message_list(MessageList* list) {
    if (list == NULL) return;

    struct MessageNode* current = list->head;
    while (current != NULL) {
        struct MessageNode* temp = current;
        current = current->next;

        free(temp->message.payload); // Assuming payload was dynamically allocated
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    list->log_function("Message list freed successfully.");
}

// Usage example:
// void custom_log(const char* message) {
//     // Custom logging implementation, e.g., write to file or console.
// }
//
// int main() {
//     MessageList* msg_list = init_message_list(custom_log);
//     NFAPI_MESSAGE_T message = { .type = 1, .timestamp = time(NULL), .payload = strdup("Payload data") };
//     add_message(msg_list, message);
//     remove_message(msg_list, message);
//     free_message_list(msg_list);
//     return 0;
// }
