#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t mutex;
} record_array;

record_array* create_record_array(size_t num_records, const int *keys, const long *offsets,
                                  int min_value, int max_value) {
    if (!num_records || !keys || !offsets || min_value > max_value) return NULL;

    // Calculate memory requirements
    size_t total_mem = num_records * sizeof(record);
    for (size_t i = 0; i < num_records; ++i) {
        total_mem += sizeof(long) + sizeof(int); // For offset and key pointers
    }

    record_array *ra = malloc(sizeof(record_array));
    if (!ra) return NULL;

    ra->records = calloc(num_records, sizeof(record));
    if (!ra->records) {
        free(ra);
        return NULL;
    }

    pthread_mutex_init(&ra->mutex, NULL);

    // Seed random number generator
    srand(time(NULL));

    // Initialize record array with unique offsets and random values
    int used_offsets[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        used_offsets[i] = -1;
    }

    pthread_mutex_lock(&ra->mutex);
    for (size_t i = 0; i < num_records; ++i) {
        ra->records[i].value = min_value + rand() % (max_value - min_value + 1);

        long unique_offset = -1;
        while (unique_offset == -1 || used_offsets[(int)unique_offset] != -1) {
            unique_offset = offsets[i];
            if (used_offsets[(int)unique_offset] != -1) {
                // Generate a random offset until it is unique
                unique_offset = rand() % num_records;
            }
        }

        used_offsets[(int)unique_offset] = 1;

        ra->records[i].offset = malloc(sizeof(long));
        if (!ra->records[i].offset) {
            pthread_mutex_unlock(&ra->mutex);
            for (size_t j = 0; j < i; ++j) {
                free(ra->records[j].offset);
                free(ra->records[j].key);
            }
            free(ra->records);
            free(ra);
            return NULL;
        }

        *ra->records[i].offset = unique_offset;

        ra->records[i].key = malloc(sizeof(int));
        if (!ra->records[i].key) {
            pthread_mutex_unlock(&ra->mutex);
            for (size_t j = 0; j <= i; ++j) {
                free(ra->records[j].offset);
                free(ra->records[j].key);
            }
            free(ra->records);
            free(ra);
            return NULL;
        }

        *ra->records[i].key = keys[i];
    }
    pthread_mutex_unlock(&ra->mutex);

    ra->count = num_records;

    return ra;
}

void destroy_record_array(record_array *ra) {
    if (!ra) return;

    for (size_t i = 0; i < ra->count; ++i) {
        free(ra->records[i].offset);
        free(ra->records[i].key);
    }
    free(ra->records);
    pthread_mutex_destroy(&ra->mutex);
    free(ra);
}
```']

