['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define CHUNK_SIZE 1024
#define MAX_HOSTNAMES 5
#define CACHE_SIZE 100

typedef struct {
    char hostnames[MAX_HOSTNAMES][256];
    int numeric_fields[3];
} Chunk;

typedef struct {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* thread_func(void *arg);
int resolve_hostname(char *hostname, char *ip_address);
double calculate_average(Chunk *chunk);

typedef struct {
    FILE *file;
    size_t chunk_size;
    pthread_t *threads;
    int num_threads;
} ThreadPool;

ThreadPool* create_thread_pool(size_t chunk_size, int num_threads) {
    ThreadPool *pool = (ThreadPool *)malloc(sizeof(ThreadPool));
    pool->file = NULL;
    pool->chunk_size = chunk_size;
    pool->threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    pool->num_threads = num_threads;
    return pool;
}

void destroy_thread_pool(ThreadPool *pool) {
    free(pool->threads);
    free(pool);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file_path> <num_threads>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
    int num_threads = atoi(argv[2]);

    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    ThreadPool *pool = create_thread_pool(CHUNK_SIZE, num_threads);

    char chunk_buffer[CHUNK_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(chunk_buffer, 1, CHUNK_SIZE, file)) > 0) {
        Chunk *chunk = (Chunk *)malloc(sizeof(Chunk));
        if (!chunk) {
            perror("Failed to allocate memory for chunk");
            fclose(file);
            destroy_thread_pool(pool);
            return EXIT_FAILURE;
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, thread_func, chunk)) {
            fprintf(stderr, "Error creating thread\n");
            free(chunk);
            continue;
        }
        pthread_detach(thread);

        if ((bytes_read % sizeof(Chunk)) != 0) {
            break; // Incomplete chunk
        }
    }

    fclose(file);
    destroy_thread_pool(pool);
    return EXIT_SUCCESS;
}

void* thread_func(void *arg) {
    Chunk *chunk = (Chunk *)arg;

    for (int i = 0; i < MAX_HOSTNAMES; ++i) {
        if (strlen(chunk->hostnames[i]) > 0) {
            char ip_address[INET6_ADDRSTRLEN] = {0};
            if (!resolve_hostname(chunk->hostnames[i], ip_address)) {
                fprintf(stderr, "Failed to resolve hostname: %s\n", chunk->hostnames[i]);
            } else {
                // Use resolved IP address for calculations
                // Example: Convert first octet of IP to integer and store in numeric_fields[2]
                struct sockaddr_in sa;
                inet_pton(AF_INET, ip_address, &(sa.sin_addr));
                chunk->numeric_fields[2] = (int)sa.sin_addr.s_addr & 0xFF;
            }
        } else {
            chunk->numeric_fields[i] = 0; // Treat missing fields as zero
        }
    }

    double average = calculate_average(chunk);
    printf("Average: %f\n", average);

    free(chunk);
    return NULL;
}

int resolve_hostname(char *hostname, char *ip_address) {
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            strcpy(ip_address, dns_cache[i].ip_address);
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&cache_lock);

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return 0; // DNS resolution failed
    }

    struct sockaddr_in *addr = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(addr->sin_addr), ip_address, INET6_ADDRSTRLEN);

    freeaddrinfo(res);

    pthread_mutex_lock(&cache_lock);
    if (cache_count < CACHE_SIZE) {
        strcpy(dns_cache[cache_count].hostname, hostname);
        strcpy(dns_cache[cache_count].ip_address, ip_address);
        cache_count++;
    }
    pthread_mutex_unlock(&cache_lock);

    return 1;
}

double calculate_average(Chunk *chunk) {
    int sum = chunk->numeric_fields[0] + chunk->numeric_fields[1] + chunk->numeric_fields[2];
    return (double)sum / 3.0;
}
```']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_MESSAGE "Default Message"
#define MAX_STRING_CACHE_SIZE 100
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 99

typedef struct {
    char *message;
    int value;
} Data;

typedef struct {
    char **cache;
    size_t size;
    pthread_mutex_t lock;
} StringCache;

StringCache string_cache = { .cache = NULL, .size = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void init_string_cache(size_t capacity) {
    if (string_cache.cache != NULL) return; // already initialized
    string_cache.size = capacity;
    string_cache.cache = malloc(sizeof(char *) * capacity);
}

char* get_or_allocate_string(const char* message) {
    pthread_mutex_lock(&string_cache.lock);

    for (size_t i = 0; i < string_cache.size; ++i) {
        if (string_cache.cache[i] != NULL && strcmp(string_cache.cache[i], message) == 0) {
            pthread_mutex_unlock(&string_cache.lock);
            return string_cache.cache[i];
        }
    }

    char *new_string = strdup(message); // Fallback if cache misses
    for (size_t i = 0; i < string_cache.size; ++i) {
        if (string_cache.cache[i] == NULL) { // Find first empty slot
            string_cache.cache[i] = new_string;
            pthread_mutex_unlock(&string_cache.lock);
            return new_string;
        }
    }

    pthread_mutex_unlock(&string_cache.lock);
    free(new_string); // No space in cache, free allocated memory
    return strdup(message); // Allocate outside of the cache
}

void cleanup_string_cache() {
    for (size_t i = 0; i < string_cache.size; ++i) {
        if (string_cache.cache[i] != NULL)
            free(string_cache.cache[i]);
    }
    free(string_cache.cache);
    string_cache.cache = NULL;
    pthread_mutex_unlock(&string_cache.lock);
}

void initialize_data_array(Data *array, size_t count) {
    init_string_cache(MAX_STRING_CACHE_SIZE);

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < count; ++i) {
        int rand_value;

        do {
            rand_value = INT_RANGE_MIN + rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1);
        } while (i > 0 && array[i-1].value == rand_value); // Ensure no two consecutive have the same value

        array[i].message = get_or_allocate_string(DEFAULT_MESSAGE);
        if (array[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed for string.\n");
            exit(EXIT_FAILURE);
        }

        array[i].value = rand_value;
    }

    pthread_mutex_destroy(&string_cache.lock); // Cleanup mutex after use
}

int main() {
    size_t data_count = 10; // Example size of the array to initialize
    Data *data_array = malloc(sizeof(Data) * data_count);
    if (data_array == NULL) {
        fprintf(stderr, "Memory allocation failed for data array.\n");
        exit(EXIT_FAILURE);
    }

    initialize_data_array(data_array, data_count);

