#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <unistd.h>
import os

#define MAX_FIELDS 50
#define LINE_BUFFER_SIZE 1024
#define LOG_FILE "program_log.txt"
#define CONFIG_FILE "config.json"

typedef struct {
    char **fields;
    u_char *ip_addresses[2];
} LineData;

typedef struct {
    double retry_interval;
    int max_log_size;
} Config;

// Error codes
enum {
    ERR_SUCCESS = 0,
    ERR_FILE_OPEN,
    ERR_MEMORY_ALLOCATION,
    ERR_DNS_RESOLUTION,
    ERR_LOGGING,
};

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL || fseek(log_file, 0L, SEEK_END) != 0 || ftell(log_file) > 1048576) {
        // Log size exceeded or file open failed
        pthread_mutex_unlock(&log_mutex);
        return;
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
    pthread_mutex_unlock(&log_mutex);
}

Config load_config() {
    Config config = {1.0, 1048576};
    // Load configuration from external source
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (config_file) {
        fscanf(config_file, "{\"retry_interval\":%lf,\"max_log_size\":%d}", &config.retry_interval, &config.max_log_size);
        fclose(config_file);
    }
    return config;
}

void free_line_data(LineData *line_data) {
    for (int i = 0; line_data->fields[i]; ++i) {
        free(line_data->fields[i]);
    }
    free(line_data->fields);

    if (line_data->ip_addresses[0]) free(line_data->ip_addresses[0]);
    if (line_data->ip_addresses[1]) free(line_data->ip_addresses[1]);
}

u_char* resolve_hostname(const char *hostname, Config config) {
    struct hostent *host;
    int retries = 3;

    while (retries--) {
        host = gethostbyname(hostname);
        if (host != NULL) {
            return (u_char *)inet_ntoa(*(struct in_addr *)host->h_addr_list[0]);
        }
        sleep(config.retry_interval);
    }

    log_message("DNS resolution failed");
    return NULL;
}

double calculate_average(double num1, double num2) {
    return (num1 + num2) / 2.0;
}

void process_line(char *line, Config config) {
    LineData line_data = {NULL};
    char *token;
    int field_count = 0;

    token = strtok(line, " ,\t\n");
    while (token && field_count < MAX_FIELDS - 1) {
        line_data.fields[field_count] = strdup(token);
        if (field_count == MAX_FIELDS - 2 || field_count == MAX_FIELDS - 3) {
            line_data.ip_addresses[field_count - (MAX_FIELDS - 4)] = resolve_hostname(line_data.fields[field_count], config);
            if (!line_data.ip_addresses[field_count - (MAX_FIELDS - 4)]) {
                free_line_data(&line_data);
                log_message("Error in DNS resolution, skipping line");
                return;
            }
        }
        token = strtok(NULL, " ,\t\n");
        ++field_count;
    }
    line_data.fields[field_count] = NULL;

    if (field_count >= 4 && 
        isdigit(line_data.fields[MAX_FIELDS - 2][0]) &&
        isdigit(line_data.fields[MAX_FIELDS - 1][0])) {

        double num1 = atof(line_data.fields[MAX_FIELDS - 2]);
        double num2 = atof(line_data.fields[MAX_FIELDS - 1]);

        double average = calculate_average(num1, num2);
        log_message("Average of last two numeric fields: ");
        char avg_log[50];
        sprintf(avg_log, "%f", average);
        strcat(log_message, avg_log);

        printf("%s\n", line); // Print in CSV format
    }

    free_line_data(&line_data);
}

void *thread_func(void *arg) {
    FILE *file = fopen("input.txt", "r");
    if (!file) {
        log_message("Error opening file");
        pthread_exit((void *)ERR_FILE_OPEN);
    }

    Config config = load_config();
    char buffer[LINE_BUFFER_SIZE];

    while (fgets(buffer, LINE_BUFFER_SIZE, file)) {
        process_line(buffer, config);
    }

    fclose(file);
    pthread_exit((void *)ERR_SUCCESS);
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, thread_func, NULL) != 0) {
        log_message("Error creating thread");
        return ERR_FILE_OPEN;
    }

    void *status;
    if (pthread_join(thread_id, &status) != 0) {
        log_message("Thread join failed");
        return ERR_SUCCESS;
    }

    return (int)(intptr_t)status;
}
