#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <zlib.h> // For compression

#define MAX_BUFFER_SIZE 256
#define MEMORY_THRESHOLD 80 * 1024 * 1024 // 80 MB threshold

typedef struct {
    int value;
    char buffer[MAX_BUFFER_SIZE];
    time_t timestamp;
} record;

typedef enum {
    FORMAT_BINARY,
    FORMAT_TEXT
} format_type;

typedef enum {
    ALGORITHM_NONE,
    ALGORITHM_ZLIB
    // Add other algorithms here as needed.
} compression_algorithm;

typedef struct {
    record *records;
    size_t count;
    size_t capacity;
} record_array;

// Helper functions
void set_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void generate_random_buffer(char *buffer, size_t size) {
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_=+[]{}|;:'\",.<>?/\\";
    for (size_t i = 0; i < size - 1; ++i) { // Leave space for null terminator
        buffer[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    buffer[size - 1] = '\0';
}

record_array* allocate_records(size_t initial_capacity) {
    record_array *array = malloc(sizeof(record_array));
    if (!array) {
        set_error("Failed to allocate memory for record array");
        return NULL;
    }

    array->records = malloc(initial_capacity * sizeof(record));
    if (!array->records) {
        free(array);
        set_error("Failed to allocate memory for records");
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    return array;
}

void free_records(record_array *array) {
    if (array) {
        free(array->records);
        free(array);
    }
}

int expand_record_array(record_array *array, size_t new_capacity) {
    record *new_records = realloc(array->records, new_capacity * sizeof(record));
    if (!new_records) {
        set_error("Failed to reallocate memory for records");
        return -1;
    }

    array->records = new_records;
    array->capacity = new_capacity;
    return 0;
}

int add_record(record_array *array, int value, const char *text, time_t timestamp) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 10 : array->capacity * 2;
        if (expand_record_array(array, new_capacity) != 0) return -1;
    }

    record *rec = &array->records[array->count++];
    rec->value = value;

    strncpy(rec->buffer, text, MAX_BUFFER_SIZE);
    rec->timestamp = timestamp;

    return 0;
}

void serialize(record_array *array, const char *filename, format_type fmt, compression_algorithm comp_alg) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        set_error("Failed to open file for writing");
        return;
    }

    size_t record_size = sizeof(int) + MAX_BUFFER_SIZE + sizeof(time_t);
    void *data_buffer = malloc(record_size * array->count);

    if (!data_buffer) {
        fclose(file);
        set_error("Failed to allocate memory for data buffer");
        return;
    }

    char *ptr = (char *)data_buffer;
    for (size_t i = 0; i < array->count; ++i) {
        record *rec = &array->records[i];

        if (fmt == FORMAT_BINARY) {
            memcpy(ptr, &(rec->value), sizeof(int));
            ptr += sizeof(int);
            memcpy(ptr, rec->buffer, MAX_BUFFER_SIZE);
            ptr += MAX_BUFFER_SIZE;
            memcpy(ptr, &(rec->timestamp), sizeof(time_t));
            ptr += sizeof(time_t);
        } else if (fmt == FORMAT_TEXT) {
            fprintf(file, "%d %s %ld\n", rec->value, rec->buffer, rec->timestamp);
            continue; // Skip binary buffer copy for text format
        }
    }

    if (comp_alg == ALGORITHM_ZLIB) {
        uLongf compressed_size = compressBound(record_size * array->count);
        unsigned char *compressed_data = malloc(compressed_size);

        if (!compressed_data || compress(compressed_data, &compressed_size, data_buffer, record_size * array->count) != Z_OK) {
            free(data_buffer);
            fclose(file);
            set_error("Compression failed");
            return;
        }

        fwrite(compressed_data, 1, compressed_size, file);
        free(compressed_data);
    } else {
        fwrite(data_buffer, 1, record_size * array->count, file);
    }

    free(data_buffer);
    fclose(file);
}

int deserialize(record_array **array_ptr, const char *filename, format_type fmt, compression_algorithm comp_alg) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        set_error("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    void *data_buffer = malloc(filesize);
    if (!data_buffer) {
        fclose(file);
        set_error("Failed to allocate memory for data buffer");
        return -1;
    }

    fread(data_buffer, 1, filesize, file);
    fclose(file);

    record_array *array = *array_ptr;

    size_t record_size = sizeof(int) + MAX_BUFFER_SIZE + sizeof(time_t);
    uLongf decompressed_size = record_size * array->count;

    if (comp_alg == ALGORITHM_ZLIB) {
        unsigned char *decompressed_data = malloc(decompressed_size);

        if (!decompressed_data || uncompress(decompressed_data, &decompressed_size, data_buffer, filesize) != Z_OK) {
            free(data_buffer);
            set_error("Decompression failed");
            return -1;
        }

        memcpy(data_buffer, decompressed_data, decompressed_size);
        free(decompressed_data);
    }

    char *ptr = (char *)data_buffer;
    for (size_t i = 0; i < array->count && ptr - (char *)data_buffer < filesize; ++i) {
        record *rec = &array->records[i];

        if (fmt == FORMAT_BINARY) {
            memcpy(&(rec->value), ptr, sizeof(int));
            ptr += sizeof(int);
            memcpy(rec->buffer, ptr, MAX_BUFFER_SIZE);
            ptr += MAX_BUFFER_SIZE;
            memcpy(&(rec->timestamp), ptr, sizeof(time_t));
            ptr += sizeof(time_t);
        } else if (fmt == FORMAT_TEXT) {
            fscanf(file, "%d %255s %ld", &(rec->value), rec->buffer, &(rec->timestamp));
            continue; // Skip binary buffer copy for text format
        }
    }

    free(data_buffer);
    return 0;
}

void monitor_memory_usage() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    if (usage.ru_maxrss > MEMORY_THRESHOLD) {
        set_error("Memory usage is approaching threshold");
        // Trigger alert or log message here
    }
}
