#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} Record;

typedef enum { LOW, MEDIUM, HIGH } LogLevel;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(LogLevel level, const char *message) {
    if (level == LOW || level == MEDIUM || level == HIGH) {
        printf("%s\n", message);
    }
}

char *generate_random_buffer(const char *charset, size_t length) {
    char *buffer = malloc(length + 1);
    if (!buffer) {
        log_message(HIGH, "Memory allocation failed for buffer");
        return NULL;
    }

    const char *ptr = charset;
    while (length-- > 0) {
        buffer[length] = ptr[rand() % strlen(ptr)];
    }
    buffer[length] = '\0';

    return buffer;
}

void serialize_data(FILE *file, long offsets[], int keys[], Record records[], size_t num_records) {
    pthread_mutex_lock(&mutex);
    if (fwrite(offsets, sizeof(long), num_records, file) != num_records ||
        fwrite(keys, sizeof(int), num_records, file) != num_records ||
        fwrite(records, sizeof(Record), num_records, file) != num_records) {
        log_message(HIGH, "Serialization failed");
    }
    pthread_mutex_unlock(&mutex);
}

void deserialize_data(FILE *file, long offsets[], int keys[], Record records[], size_t num_records) {
    pthread_mutex_lock(&mutex);
    if (fread(offsets, sizeof(long), num_records, file) != num_records ||
        fread(keys, sizeof(int), num_records, file) != num_records ||
        fread(records, sizeof(Record), num_records, file) != num_records) {
        log_message(HIGH, "Deserialization failed");
    }
    pthread_mutex_unlock(&mutex);
}

int process_input_data(size_t size_param) {
    if (size_param > MAX_RECORDS) {
        log_message(MEDIUM, "Exceeding record limit");
        return -1;
    }

    long *offsets = malloc(size_param * sizeof(long));
    int *keys = malloc(size_param * sizeof(int));
    Record *records = malloc(size_param * sizeof(Record));

    if (!offsets || !keys || !records) {
        log_message(HIGH, "Memory allocation failed");
        free(offsets); free(keys); free(records);
        return -1;
    }

    srand(time(NULL));
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    for (size_t i = 0; i < size_param; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
        records[i].value = rand();

        char *buffer_content = generate_random_buffer(charset, BUFFER_SIZE);
        if (buffer_content) {
            strncpy(records[i].buffer, buffer_content, BUFFER_SIZE - 1);
            free(buffer_content);
        }
    }

    FILE *file = fopen("data.bin", "wb");
    if (!file) {
        log_message(HIGH, "Failed to open file for writing");
        free(offsets); free(keys); free(records);
        return -1;
    }

    serialize_data(file, offsets, keys, records, size_param);
    fclose(file);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}

int main() {
    size_t size = 100; // Example size parameter
    if (process_input_data(size) != 0) {
        log_message(HIGH, "Data processing failed");
    } else {
        log_message(LOW, "Data processed successfully");
    }

    return 0;
}
