['Below is a conceptual implementation outline in C with explanations on how you might structure such functionality. Note that this example focuses primarily on the core aspects of managing records from an XML configuration file and ensuring concurrency safety using threading mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

#define MAX_RECORDS 1024
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t count;
    pthread_mutex_t lock;
} config_manager_t;

config_manager_t* create_config_manager(size_t initial_size) {
    config_manager_t *manager = (config_manager_t *)malloc(sizeof(config_manager_t));
    manager->offsets = malloc(initial_size * sizeof(long));
    manager->keys = malloc(initial_size * sizeof(int));
    manager->records = malloc(initial_size * sizeof(record_t));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_config_manager(config_manager_t *manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int read_xml_and_configure(config_manager_t *manager, const char *file_path) {
    xmlDocPtr doc;
    xmlNodePtr cur;

    if ((doc = xmlReadFile(file_path, NULL, 0)) == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);
    for (cur = xmlDocGetRootElement(doc); cur; cur = cur->next) {
        if (xmlStrEqual(cur->name, (const xmlChar *)"setting")) {
            xmlChar *key_attr = xmlGetProp(cur, (const xmlChar *)"key");
            long offset_value = strtol((char *)xmlGetProp(cur, (const xmlChar *)"offset"), NULL, 10);
            int key_value = atoi((char *)key_attr);

            if (manager->count < MAX_RECORDS) {
                manager->offsets[manager->count] = offset_value;
                manager->keys[manager->count] = key_value;

                record_t *record = &manager->records[manager->count];
                record->value = atoi((char *)xmlGetProp(cur, (const xmlChar *)"value"));
                strncpy(record->buffer, (char *)xmlNodeListGetString(doc, cur->children, 1), BUFFER_SIZE - 1);
                record->buffer[BUFFER_SIZE - 1] = '\0';

                manager->count++;
            } else {
                fprintf(stderr, "Maximum number of records reached\n");
                break;
            }
        }
    }
    xmlFreeDoc(doc);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

