#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_CONCURRENT_QUERIES 5

typedef struct {
    char hostname[256];
    u_char ip_address[16];
    int status; // -1 for error, 0 for success
} dns_result_t;

typedef struct request_node {
    dns_result_t *result;
    struct request_node *next;
} request_node_t;

typedef struct {
    request_node_t *head;
    pthread_mutex_t lock;
} request_queue_t;

request_queue_t queue = {NULL, PTHREAD_MUTEX_INITIALIZER};

void enqueue_request(dns_result_t *result) {
    request_node_t *new_node = malloc(sizeof(request_node_t));
    new_node->result = result;
    new_node->next = NULL;

    pthread_mutex_lock(&queue.lock);
    if (queue.head == NULL) {
        queue.head = new_node;
    } else {
        request_node_t *temp = queue.head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&queue.lock);
}

dns_result_t* dequeue_request() {
    pthread_mutex_lock(&queue.lock);
    if (queue.head == NULL) {
        pthread_mutex_unlock(&queue.lock);
        return NULL;
    }

    request_node_t *temp = queue.head;
    dns_result_t *result = temp->result;
    queue.head = queue.head->next;
    free(temp);

    pthread_mutex_unlock(&queue.lock);
    return result;
}

int perform_dns_resolution(dns_result_t *result) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(result->hostname, NULL, &hints, &res)) != 0) {
        result->status = -1;
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), result->ip_address, 16);
        freeaddrinfo(res);
        result->status = 0;
        return 0;
    }

    freeaddrinfo(res);
    result->status = -1;
    return -1;
}

void* dns_worker(void *arg) {
    while (1) {
        dns_result_t *request = dequeue_request();
        if (!request) continue;

        perform_dns_resolution(request);

        // Simulate caching or external service interaction here

        printf("Resolved %s to %s\n", request->hostname, inet_ntoa(*(struct in_addr*)request->ip_address));
    }
}

int dns_resolve_async(const char *hostname) {
    if (strlen(hostname) >= 256) return -1;

    dns_result_t *result = malloc(sizeof(dns_result_t));
    strcpy(result->hostname, hostname);
    result->status = -1;

    enqueue_request(result);

    static pthread_mutex_t worker_count_lock = PTHREAD_MUTEX_INITIALIZER;
    static int active_workers = 0;

    pthread_mutex_lock(&worker_count_lock);
    if (active_workers < MAX_CONCURRENT_QUERIES) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, dns_worker, NULL);
        active_workers++;
    }
    pthread_mutex_unlock(&worker_count_lock);

    return 0; // Task enqueued
}

int main() {
    for (int i = 0; i < 10; i++) {
        char hostname[256];
        snprintf(hostname, sizeof(hostname), "example%d.com", i);
        dns_resolve_async(hostname);
    }

    sleep(5); // Allow time for async processing
    return 0;
}
```

This code sets up a basic framework to handle DNS resolution requests asynchronously using threads. It manages concurrency by limiting the number of active worker threads and uses a queue to manage incoming requests. The implementation assumes an external mechanism for DNS caching or service integration, which can be added where indicated in `dns_worker`. Adjustments may be necessary depending on specific system constraints and performance needs.']

