    int depth = validate_and_traverse(path, 0);
    if (depth == -1) {
        fprintf(stderr, "Invalid path: %s\n", path);
        free(new_path->path);
        free(new_path);
    } else {
        new_path->fd_offset = (long)depth; // Store the depth for demonstration
        file_paths[count++] = new_path;
    }

    pthread_mutex_unlock(&lock);
}

// Validate and traverse the filesystem to determine directory depth
int validate_and_traverse(const char *path, int current_depth) {
    struct stat sb;
    if (lstat(path, &sb) != 0) { // Use lstat for handling symbolic links
        perror("Failed to get file status");
        return -1;
    }

    if (!S_ISDIR(sb.st_mode)) {
        fprintf(stderr, "Not a directory: %s\n", path);
        return -1;
    }

    char new_path[PATH_MAX];
    DIR *dir = opendir(path);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    struct dirent *entry;
    int max_depth = current_depth;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(new_path, sizeof(new_path), "%s/%s", path, entry->d_name);

        // Recursively determine depth
        int new_depth = validate_and_traverse(new_path, current_depth + 1);
        if (new_depth != -1) {
            max_depth = new_depth > max_depth ? new_depth : max_depth;
        }
    }

    closedir(dir);
    return max_depth;
}

// Free allocated resources
void free_resources() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; ++i) {
        free(file_paths[i]->path);
        free(file_paths[i]);
    }

    free(file_paths);
    file_paths = NULL;

    pthread_mutex_unlock(&lock);
}

