#define MAX_MEMORY_LIMIT (1024 * 1024) // Example limit, adjust as needed

struct OffsetRecord {
    long offset;
    int key;
};

struct KeyRecord {
    int value;
    struct OffsetRecord* record_ptr;
};

struct RandomValue {
    int value;
};

// Thread-local storage for random number generator
__thread uint32_t tls_rand_state;

void reseed_rng() {
    // Use time-based seed for simplicity; replace with more robust approach if needed
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    srand((unsigned int)time(NULL));
    tls_rand_state = rand();
    pthread_mutex_unlock(&lock);
}

uint32_t thread_safe_random() {
    tls_rand_state ^= (tls_rand_state << 13);
    tls_rand_state ^= (tls_rand_state >> 17);
    tls_rand_state ^= (tls_rand_state << 5);
    return tls_rand_state;
}

struct OffsetRecord* allocate_offset_records(size_t num_elements) {
    if ((num_elements == 0) || (num_elements > MAX_MEMORY_LIMIT / sizeof(struct OffsetRecord))) {
        fprintf(stderr, "Invalid number of elements.\n");
        return NULL;
    }

    struct OffsetRecord* records = malloc(num_elements * sizeof(struct OffsetRecord));
    if (!records) {
        perror("Failed to allocate memory for OffsetRecords.");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        records[i].offset = thread_safe_random() % 1000; // Random offset in range [0, 999]
        records[i].key = rand() % 256; // Random key in range [0, 255]
    }

    return records;
}

struct KeyRecord* allocate_key_records(size_t num_elements, struct OffsetRecord** offset_records) {
    if ((num_elements == 0) || (num_elements > MAX_MEMORY_LIMIT / sizeof(struct KeyRecord))) {
        fprintf(stderr, "Invalid number of elements for KeyRecords.\n");
        return NULL;
    }

    struct KeyRecord* key_records = malloc(num_elements * sizeof(struct KeyRecord));
    if (!key_records) {
        perror("Failed to allocate memory for KeyRecords.");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        int random_index = rand() % num_elements;
        key_records[i].value = rand() % 100; // Random value in range [0, 99]
        key_records[i].record_ptr = &offset_records[random_index][0]; // Point to corresponding OffsetRecord
    }

    return key_records;
}

struct RandomValue* initialize_random_values(size_t num_elements) {
    if ((num_elements == 0) || (num_elements > MAX_MEMORY_LIMIT / sizeof(struct RandomValue))) {
        fprintf(stderr, "Invalid number of elements for RandomValues.\n");
        return NULL;
    }

    struct RandomValue* random_values = malloc(num_elements * sizeof(struct RandomValue));
    if (!random_values) {
        perror("Failed to allocate memory for RandomValues.");
        return NULL;
    }

    // Parallel initialization using threads
    pthread_t threads[num_elements];
    size_t count_per_thread = num_elements / (size_t)sysconf(_SC_NPROCESSORS_ONLN);

    void* thread_function(void* arg) {
        size_t start_idx = *(size_t*)arg;
        for (size_t i = start_idx; i < start_idx + count_per_thread && i < num_elements; ++i) {
            random_values[i].value = thread_safe_random() % 101; // Random value in range [0, 100]
        }
        return NULL;
    }

    for (size_t i = 0; i < num_elements; i += count_per_thread) {
        size_t* idx = malloc(sizeof(size_t));
        if (!idx) {
            perror("Failed to allocate memory for thread index.");
            break;
        }
        *idx = i;
        pthread_create(&threads[i / count_per_thread], NULL, thread_function, (void*)idx);
    }

    for (size_t i = 0; i < num_elements; i += count_per_thread) {
        pthread_join(threads[i / count_per_thread], NULL);
        free((size_t*)&threads[i / count_per_thread]);
    }

    return random_values;
}

void free_resources(struct OffsetRecord* offset_records, struct KeyRecord* key_records, struct RandomValue* random_values) {
    if (offset_records) {
        free(offset_records);
    }
    if (key_records) {
        free(key_records);
    }
    if (random_values) {
        free(random_values);
    }
}

int main() {
    size_t num_offset_records = 100; // Example number, should be user input
    size_t num_key_records = 50;     // Example number, should be user input
    size_t num_random_values = 200;  // Example number, should be user input

    struct OffsetRecord* offset_records = allocate_offset_records(num_offset_records);
    if (!offset_records) {
        return EXIT_FAILURE;
    }

    struct KeyRecord* key_records = allocate_key_records(num_key_records, &offset_records);
    if (!key_records) {
        free(offset_records);
        return EXIT_FAILURE;
    }

    struct RandomValue* random_values = initialize_random_values(num_random_values);
    if (!random_values) {
        free_resources(offset_records, key_records, NULL);
        return EXIT_FAILURE;
    }

    // Use the allocated and initialized resources...

    free_resources(offset_records, key_records, random_values);

    return EXIT_SUCCESS;
}
