#include <iostream>
#include <forward_list>
#include <string>
#include <vector>
#include <fstream>
#include <cstdlib> // For rand() and srand()
#include <ctime>   // For time()

// Define the record structure
struct Record {
    int value;
    char buffer[256];

    Record(int val = 0) : value(val) { 
        std::fill(buffer, buffer + 256, '\0'); 
    }
};

class ResourceManager {
public:
    ResourceManager(size_t maxRecords)
        : totalAllocated(0), maxRecords(maxRecords) {}

    bool allocateResources(size_t size) {
        if (totalAllocated + size > maxRecords) {
            std::cerr << "Memory allocation limit reached." << std::endl;
            return false;
        }

        offsets.resize(totalAllocated + size);
        keys.resize(totalAllocated + size);
        records.resize(totalAllocated + size);

        for (size_t i = totalAllocated; i < totalAllocated + size; ++i) {
            offsets[i] = static_cast<long>(i); // Example offset initialization
            keys[i] = static_cast<int>(rand() % 1000); // Random key initialization

            records[i] = Record(keys[i]);
            randomizeBuffer(records[i].buffer);
        }

        totalAllocated += size;
        return true;
    }

    bool serialize(const std::string& filename) {
        std::ofstream outFile(filename, std::ios::binary);
        if (!outFile.is_open()) {
            std::cerr << "Failed to open file for writing: " << filename << std::endl;
            return false;
        }

        // Serialize offsets
        outFile.write(reinterpret_cast<const char*>(&totalAllocated), sizeof(totalAllocated));
        outFile.write(reinterpret_cast<const char*>(offsets.data()), totalAllocated * sizeof(long));

        // Serialize keys and records
        for (size_t i = 0; i < totalAllocated; ++i) {
            outFile.write(reinterpret_cast<const char*>(&keys[i]), sizeof(int));
            outFile.write(records[i].buffer, 256);
        }

        return true;
    }

    bool deserialize(const std::string& filename) {
        std::ifstream inFile(filename, std::ios::binary);
        if (!inFile.is_open()) {
            std::cerr << "Failed to open file for reading: " << filename << std::endl;
            return false;
        }

        size_t newSize = 0;
        inFile.read(reinterpret_cast<char*>(&newSize), sizeof(newSize));

        if (newSize > maxRecords) {
            std::cerr << "Deserialization exceeds memory limit." << std::endl;
            return false;
        }

        offsets.resize(newSize);
        keys.resize(newSize);
        records.resize(newSize);

        inFile.read(reinterpret_cast<char*>(offsets.data()), newSize * sizeof(long));
        for (size_t i = 0; i < newSize; ++i) {
            inFile.read(reinterpret_cast<char*>(&keys[i]), sizeof(int));
            inFile.read(records[i].buffer, 256);
        }

        totalAllocated = newSize;
        return true;
    }

private:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    size_t totalAllocated;
    const size_t maxRecords;

    void randomizeBuffer(char* buffer, size_t size) {
        static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for (size_t i = 0; i < size - 1; ++i) { // Reserve last character for null-termination
            buffer[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        buffer[size - 1] = '\0';
    }
};

void refreshDialogFields(std::forward_list<std::string>& fieldNames, int resourceId, const std::string& url, std::queue<std::string>& messageQueue) {
    for (auto it = fieldNames.begin(); it != fieldNames.end();) {
        bool foundMatch = false;

        // Simulate checking and sending messages
        for (const auto& fieldName : {"Field1", "Field2", "Field3"}) {  // Example predefined fields
            if (*it == fieldName) {
                std::string messageResult = "Success";  // Mock result

                // If successful, update the dialog field
                if (messageResult == "Success") {
                    std::cout << "Updating field: " << *it << " with result: " << messageResult << std::endl;
                } else {
                    messageQueue.push(messageResult);
                }

                foundMatch = true;
                break;
            }
        }

        // If no match, append to queue
        if (!foundMatch) {
            messageQueue.push("No match for field: " + *it);
        }

        it = fieldNames.erase_after(it);
    }
}

int main() {
    srand(static_cast<unsigned int>(time(0)));  // Seed random number generator

    ResourceManager manager(100); // Example limit of 100 records
    if (!manager.allocateResources(10)) { // Allocate space for 10 records
        return -1;
    }

