    int status_flag; // 0 for success, non-zero for errors
    time_t execution_time;
} CommandLog;

typedef struct MemorySegment {
    void* start_address;
    size_t segment_size;
    size_t used_memory;
} MemorySegment;

// Global variables
MemorySegment memory_segments[10]; // Example segmentation with fixed number of segments
int num_segments = 0;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_local CommandLog command_logs[MAX_COMMANDS];
static int command_log_count = 0;

void initialize_memory_system() {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < sizeof(memory_segments) / sizeof(MemorySegment); ++i) {
        memory_segments[i].start_address = NULL;
        memory_segments[i].segment_size = 0;
        memory_segments[i].used_memory = 0;
    }
    num_segments = 0;
    pthread_mutex_unlock(&memory_lock);
}

void* allocate_memory(size_t size) {
    if (size <= 0 || total_memory_used() + size > SYSTEM_MEMORY_LIMIT)
        return NULL;

    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < num_segments; ++i) {
        if (memory_segments[i].used_memory + size <= memory_segments[i].segment_size) {
            void* address = (char*)memory_segments[i].start_address + memory_segments[i].used_memory;
            memory_segments[i].used_memory += size;
            pthread_mutex_unlock(&memory_lock);
            return address;
        }
    }

    if (num_segments < sizeof(memory_segments) / sizeof(MemorySegment)) {
        void* new_segment = malloc(1 << 20); // Allocate a segment of 1 MB
        if (!new_segment) {
            pthread_mutex_unlock(&memory_lock);
            return NULL;
        }
        memory_segments[num_segments].start_address = new_segment;
        memory_segments[num_segments].segment_size = (1 << 20);
        memory_segments[num_segments].used_memory = size;

        void* address = (char*)new_segment;
        num_segments++;
        pthread_mutex_unlock(&memory_lock);
        return address;
    }

    pthread_mutex_unlock(&memory_lock);
    return NULL;
}

size_t total_memory_used() {
    size_t total = 0;
    for (int i = 0; i < num_segments; ++i) {
        total += memory_segments[i].used_memory;
    }
    return total;
}

void free_memory_system() {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < num_segments; ++i) {
        if (memory_segments[i].start_address) {
            free(memory_segments[i].start_address);
            memory_segments[i].start_address = NULL;
            memory_segments[i].segment_size = 0;
            memory_segments[i].used_memory = 0;
        }
    }
    num_segments = 0;
    pthread_mutex_unlock(&memory_lock);
}

Node* create_node(const char* name, NodeType type) {
    Node* node = (Node*)allocate_memory(sizeof(Node));
    if (!node)
        return NULL;

    strncpy(node->name, name, MAX_NAME_LENGTH - 1);
    node->name[MAX_NAME_LENGTH - 1] = '\0';
    node->type = type;
    node->size = 0;
    node->parent = NULL;
    node->children = (Node**)allocate_memory(sizeof(Node*) * 10); // Initial capacity
    if (!node->children) {
        free(node);
        return NULL;
    }
    node->child_count = 0;

    command_logs[command_log_count].status_flag = 1; // Assuming success
    strncpy(command_logs[command_log_count].command_details, "Create Node", sizeof(command_logs[command_log_count].command_details) - 1);
    command_logs[command_log_count].execution_time = time(NULL);
    command_log_count++;

    return node;
}

void log_command(const char* details, int status_flag) {
    strncpy(command_logs[command_log_count].command_details, details, sizeof(command_logs[command_log_count].command_details) - 1);
    command_logs[command_log_count].status_flag = status_flag;
    command_logs[command_log_count].execution_time = time(NULL);
    command_log_count++;
}

void execute_command(const char* command) {
    // Example of handling commands; expand as needed
    if (strncmp(command, "CREATE", 6) == 0) {
        const char* name_start = command + 7;
        Node* node = create_node(name_start, DIRECTORY);
        log_command("Execute Create Command", node ? 1 : -1);
    }
    // Add more command handlers as needed
}

void free_all_nodes(Node* root) {
    for (int i = 0; i < root->child_count; ++i) {
        free_all_nodes(root->children[i]);
    }
    if (root->children) {
        free(root->children);
    }
    free(root);
}

int main() {
    initialize_memory_system();

    // Example usage
    Node* root = create_node("root", DIRECTORY);
    execute_command("CREATE subdir");

    // Clean up
    free_all_nodes(root);
    free_memory_system();

    return 0;
}
