            log_message("Failed to allocate PDU");
            break;
        }
        pdus[i] = *pdu;
        free(pdu);
    }

    return pdus;
}

void destroy_pdus_array(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t num_pdus) {
