#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_HOSTNAMES 3
#define CACHE_SIZE 100

typedef struct {
    char hostname[256];
    u_char ip_address[16];
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

u_char* resolve_hostname(const char* hostname) {
    pthread_mutex_lock(&cache_lock);

    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[i].ip_address;
        }
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
    inet_ntop(AF_INET, &(addr->sin_addr), dns_cache[cache_count].ip_address, sizeof(dns_cache[cache_count].ip_address));
    strcpy(dns_cache[cache_count].hostname, hostname);

    if (++cache_count >= CACHE_SIZE) {
        cache_count = 0; // Simple circular buffer
    }

    freeaddrinfo(res);

    pthread_mutex_unlock(&cache_lock);
    return dns_cache[(cache_count - 1 + CACHE_SIZE) % CACHE_SIZE].ip_address;
}

void* process_line(void* arg) {
    char *line = (char*)arg;

    char hostnames[MAX_HOSTNAMES][256] = {0};
    int numeric_fields[2] = {0, 0};
    u_char ip_addresses[MAX_HOSTNAMES][16] = {{0}};

    sscanf(line, "%255[^ ] %255[^ ] %255[^ ] %d %d", hostnames[0], hostnames[1], hostnames[2], &numeric_fields[0], &numeric_fields[1]);

    for (int i = 0; i < MAX_HOSTNAMES; ++i) {
        if (strlen(hostnames[i]) > 0) {
            ip_addresses[i] = resolve_hostname(hostnames[i]);
        }
    }

    int sum = numeric_fields[0] + numeric_fields[1];
    for (int i = 0; i < MAX_HOSTNAMES && ip_addresses[i][0]; ++i) {
        unsigned long ip;
        inet_pton(AF_INET, (const char*)ip_addresses[i], &ip);
        sum += ip;
    }

    int average = sum / ((MAX_HOSTNAMES * 2) - count_non_empty(hostnames, MAX_HOSTNAMES));

    printf("%s %s %s %d %d %d\n", hostnames[0], hostnames[1], hostnames[2], numeric_fields[0], numeric_fields[1], average);

    free(line);
    return NULL;
}

int count_non_empty(char* array[], int max) {
    int count = 0;
    for (int i = 0; i < max && strlen(array[i]) > 0; ++i) {
        ++count;
    }
    return count;
}

void process_file(const char* filename, pthread_t* thread_pool, int pool_size) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Error getting file size");
        close(fd);
        return;
    }

    char* map = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("Error mapping file");
        close(fd);
        return;
    }

    pthread_mutex_t line_lock = PTHREAD_MUTEX_INITIALIZER;

    for (char *line = map; line < map + sb.st_size;) {
        char *newline = strchr(line, '\n');
        if (!newline) newline = map + sb.st_size;

        size_t len = newline - line;
        char* new_line = malloc(len + 1);
        strncpy(new_line, line, len);
        new_line[len] = '\0';

        pthread_mutex_lock(&line_lock);
        for (int i = 0; i < pool_size && new_line != NULL; ++i) {
            if (pthread_tryjoin_np(thread_pool[i], NULL) == EBUSY) {
                pthread_create(&thread_pool[i], NULL, process_line, (void*)new_line);
                break;
            }
        }
        pthread_mutex_unlock(&line_lock);

        line = newline + 1;
    }

    munmap(map, sb.st_size);
    close(fd);
}

int load_resource_bundle(const char* path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening resource file");
        return -1;
    }

    int count = 0;
    while (fgetc(file) != EOF) {
        ++count;
        fseek(file, -1, SEEK_CUR);
    }

    rewind(file);
    fclose(file);

    return count;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int pool_size = 4; // Example thread pool size
    pthread_t thread_pool[pool_size];

    for (int i = 1; i < argc; ++i) {
        process_file(argv[i], thread_pool, pool_size);
    }

    for (int i = 0; i < pool_size; ++i) {
        pthread_join(thread_pool[i], NULL);
    }

    int bundle_count = load_resource_bundle("resource.txt");
    printf("Resource bundle contains %d items.\n", bundle_count);

    return EXIT_SUCCESS;
}
