#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define SYSTEM_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB for example
#define MAX_OFFSET_RECORDS 10000
#define MAX_KEY_RECORDS 5000

struct OffsetRecord {
    long offset;
    int key;
};

struct KeyRecord {
    int value;
    struct OffsetRecord* record;
};

struct RandomValue {
    int value;
};

pthread_mutex_t rng_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned int custom_rand_r(unsigned int *seed) {
    unsigned int const a = 1103515245U;
    unsigned int const c = 12345U;
    return (*seed *= a) += c;
}

void reseed_rng(unsigned int* seed, unsigned long long timestamp) {
    pthread_mutex_lock(&rng_mutex);
    *seed ^= (unsigned int)(timestamp >> 32);
    pthread_mutex_unlock(&rng_mutex);
}

// Thread-safe random number generation
int thread_safe_random(int min, int max, unsigned int* seed) {
    pthread_mutex_lock(&rng_mutex);
    int range = max - min + 1;
    int result = min + (custom_rand_r(seed) % range);
    if (pthread_self() == pthread_self()) { // Periodically reseed
        reseed_rng(seed, clock());
    }
    pthread_mutex_unlock(&rng_mutex);
    return result;
}

bool validate_and_allocate(size_t elements, size_t element_size, void** ptr) {
    size_t total_size = elements * element_size;
    if (total_size > SYSTEM_MEMORY_LIMIT || elements == 0) {
        fprintf(stderr, "Memory allocation request exceeds system limits.\n");
        return false;
    }
    *ptr = malloc(total_size);
    if (*ptr == NULL) {
        perror("Failed to allocate memory");
        return false;
    }
    return true;
}

void* get_external_random_number() {
    // Simulate network latency and rate-limiting
    static int counter = 0;
    pthread_mutex_lock(&pthread_self()); // Use thread's own mutex for simplicity
    if (++counter % 10 == 0) { // Rate limit: every 10th call simulates delay
        sleep(1); // Simulate network latency
    }
    pthread_mutex_unlock(&pthread_self());
    return malloc(sizeof(int));
}

bool initialize_data_structures(size_t offset_count, size_t key_count, size_t random_value_count,
                                struct OffsetRecord*** offset_records_out,
                                struct KeyRecord*** key_records_out,
                                struct RandomValue*** random_values_out) {

    unsigned int seed = time(NULL);

    if (!validate_and_allocate(offset_count, sizeof(struct OffsetRecord), (void**)offset_records_out)) return false;
    if (!validate_and_allocate(key_count, sizeof(struct KeyRecord), (void**)key_records_out)) {
        free(*offset_records_out);
        return false;
    }
    if (!validate_and_allocate(random_value_count, sizeof(struct RandomValue), (void**)random_values_out)) {
        free(*offset_records_out);
        free(*key_records_out);
        return false;
    }

    for (size_t i = 0; i < offset_count; ++i) {
        (*offset_records_out)[i].offset = thread_safe_random(1, 100000, &seed);
        (*offset_records_out)[i].key = i;
    }

    for (size_t i = 0; i < key_count; ++i) {
        int rand_value = thread_safe_random(1, 100, &seed);
        if (rand_value % 10 == 0) { // Simulate random external service failure
            (*key_records_out)[i].record = NULL;
        } else {
            size_t offset_index = rand_value % offset_count;
            (*key_records_out)[i].record = &((*offset_records_out)[offset_index]);
        }
        (*key_records_out)[i].value = i;
    }

    #pragma omp parallel for
    for (size_t i = 0; i < random_value_count; ++i) {
        int* external_rand_ptr = get_external_random_number();
        if (external_rand_ptr == NULL) {
            free(*random_values_out);
            free(*offset_records_out);
            free(*key_records_out);
            return false;
        }
        (*random_values_out)[i].value = *external_rand_ptr > 100 ? 100 : *external_rand_ptr;
        free(external_rand_ptr);
    }

    return true;
}

void cleanup_data_structures(struct OffsetRecord* offset_records, struct KeyRecord* key_records,
                             struct RandomValue* random_values) {
    if (offset_records) free(offset_records);
    if (key_records) free(key_records);
    if (random_values) free(random_values);
}
