#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PROFILES 1000
#define NAME_SIZE 50
#define EMAIL_SIZE 100
#define PHONE_SIZE 20
#define INTEREST_SIZE 200

typedef struct {
    char id[20];
    time_t timestamp;
} Version;

typedef struct {
    char interests[INTEREST_SIZE];
} InterestList;

typedef struct ProfileNode {
    char name[NAME_SIZE];
    char email[EMAIL_SIZE];
    char phone[PHONE_SIZE];
    Version version;
    InterestList *interests;
    struct ProfileNode *next;
} ProfileNode;

typedef struct {
    ProfileNode *head;
    pthread_mutex_t lock;
    size_t profile_count;
    size_t memory_usage;
} UserProfileCollection;

UserProfileCollection collection = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};

void log_change(const char *change) {
    // Implement logging logic here
}

int add_profile(const char *name, const char *email, const char *phone, InterestList *interests) {
    pthread_mutex_lock(&collection.lock);

    if (collection.profile_count >= MAX_PROFILES) {
        printf("Profile limit exceeded.\n");
        pthread_mutex_unlock(&collection.lock);
        return -1;
    }

    ProfileNode *new_profile = malloc(sizeof(ProfileNode));
    if (!new_profile) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&collection.lock);
        return -2;
    }

    strncpy(new_profile->name, name, NAME_SIZE);
    strncpy(new_profile->email, email, EMAIL_SIZE);
    strncpy(new_profile->phone, phone, PHONE_SIZE);

    // Generate unique version ID and timestamp
    snprintf(new_profile->version.id, 20, "%lu", (unsigned long)time(NULL));
    new_profile->version.timestamp = time(NULL);

    new_profile->interests = malloc(sizeof(InterestList));
    if (!new_profile->interests) {
        free(new_profile);
        printf("Memory allocation failed for interests.\n");
        pthread_mutex_unlock(&collection.lock);
        return -3;
    }
    memcpy(new_profile->interests, interests, sizeof(InterestList));

    new_profile->next = collection.head;
    collection.head = new_profile;

    collection.profile_count++;
    collection.memory_usage += sizeof(ProfileNode) + sizeof(InterestList);

    log_change("Added profile");

    pthread_mutex_unlock(&collection.lock);
    return 0;
}

ProfileNode* find_profile_by_email(const char *email) {
    pthread_mutex_lock(&collection.lock);

    ProfileNode *current = collection.head;
    while (current) {
        if (strcmp(current->email, email) == 0) {
            pthread_mutex_unlock(&collection.lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection.lock);
    return NULL;
}

int update_profile(const char *email, const char *name, const char *phone, InterestList *interests) {
    ProfileNode *profile = find_profile_by_email(email);

    if (!profile) {
        printf("Profile not found.\n");
        return -1;
    }

    pthread_mutex_lock(&collection.lock);

    strncpy(profile->name, name, NAME_SIZE);
    strncpy(profile->phone, phone, PHONE_SIZE);

    free(profile->interests);
    profile->interests = malloc(sizeof(InterestList));
    if (!profile->interests) {
        printf("Memory allocation failed for interests.\n");
        pthread_mutex_unlock(&collection.lock);
        return -2;
    }
    memcpy(profile->interests, interests, sizeof(InterestList));

    // Update version
    snprintf(profile->version.id, 20, "%lu", (unsigned long)time(NULL));
    profile->version.timestamp = time(NULL);

    log_change("Updated profile");

    pthread_mutex_unlock(&collection.lock);
    return 0;
}

int remove_profile(const char *email) {
    pthread_mutex_lock(&collection.lock);

    ProfileNode **indirect = &collection.head;
    while (*indirect) {
        if (strcmp((*indirect)->email, email) == 0) {
            ProfileNode *to_remove = *indirect;
            *indirect = to_remove->next;

            free(to_remove->interests);
            free(to_remove);

            collection.profile_count--;
            collection.memory_usage -= sizeof(ProfileNode) + sizeof(InterestList);

            log_change("Removed profile");

            pthread_mutex_unlock(&collection.lock);
            return 0;
        }
        indirect = &(*indirect)->next;
    }

    printf("Profile not found.\n");
    pthread_mutex_unlock(&collection.lock);
    return -1;
}

int export_profiles(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return -1;
    }

    pthread_mutex_lock(&collection.lock);

    ProfileNode *current = collection.head;
    while (current) {
        fwrite(current, sizeof(ProfileNode), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&collection.lock);
    return 0;
}

int import_profiles(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        return -1;
    }

    pthread_mutex_lock(&collection.lock);

    ProfileNode new_profile;
    while (fread(&new_profile, sizeof(ProfileNode), 1, file)) {
        if (collection.profile_count >= MAX_PROFILES) {
            printf("Profile limit exceeded during import.\n");
            break;
        }

        // Reconstruct interest list
        InterestList *interests = malloc(sizeof(InterestList));
        if (!interests) {
            printf("Memory allocation failed for interests during import.\n");
            break;
        }
        memcpy(interests, new_profile.interests, sizeof(InterestList));

        ProfileNode *new_node = malloc(sizeof(ProfileNode));
        if (!new_node) {
            free(interests);
            printf("Memory allocation failed during import.\n");
            break;
        }

        *new_node = new_profile;
        new_node->interests = interests;

        new_node->next = collection.head;
        collection.head = new_node;

        collection.profile_count++;
        collection.memory_usage += sizeof(ProfileNode) + sizeof(InterestList);
    }

    fclose(file);
    pthread_mutex_unlock(&collection.lock);
    return 0;
}

void cleanup() {
    pthread_mutex_lock(&collection.lock);

    ProfileNode *current = collection.head;
    while (current) {
        ProfileNode *next = current->next;
        free(current->interests);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&collection.lock);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Memory Management**: Allocates and frees memory for profiles and interests dynamically.
- **Error Handling**: Provides error messages and returns error codes for various failure scenarios.
- **Logging**: Placeholder function `log_change()` is used for logging changes.
- **File Operations**: Supports exporting and importing profiles to/from a file.
- **Versioning**: Each profile has a version with a unique ID and timestamp.

This code provides a robust foundation for managing user profiles in memory, supporting concurrent operations and ensuring data consistency.']

