```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <uuid/uuid.h>

#define MAX_TITLE_LENGTH 50
#define METADATA_SIZE_THRESHOLD 1024

typedef enum {
    CATEGORY_A,
    CATEGORY_B,
    CATEGORY_C
} Category;

typedef struct Metadata {
    char *key;
    char *value;
    struct Metadata *next;
} Metadata;

typedef struct Document {
    char *title;
    Category category;
    Metadata *metadata;
} Document;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function declarations for configuration and logging
int get_max_title_length();
char **get_word_list(int *word_count);
Category *get_categories(int *category_count);
int get_metadata_size_threshold();
void log_message(const char *message);

// Helper function to generate a random integer as string
char* int_to_string(int num) {
    char *str = (char *)malloc(12); // Enough for 32-bit int
    if (!str) return NULL;
    snprintf(str, 12, "%d", num);
    return str;
}

// Helper function to generate a random title
char* generate_title(char **word_list, int word_count, int max_length, int encrypt) {
    char *title = (char *)malloc(max_length + 1);
    if (!title) return NULL;

    int len = 0;
    while (len < max_length && rand() % word_count > 0) {
        const char *word = word_list[rand() % word_count];
        int word_len = strlen(word);
        if (len + word_len + 1 <= max_length) {
            strcat(title, word);
            len += word_len;
            title[len++] = ' ';
        }
    }
    title[len] = '\0';

    // Optional encryption (placeholder for actual implementation)
    if (encrypt) {
        // Encrypt the title here
    }

    return title;
}

// Helper function to generate a random category
Category generate_category(int category_count) {
    return (Category)(rand() % category_count);
}

// Helper function to initialize metadata
Metadata* init_metadata(int size_threshold) {
    Metadata *head = NULL, *tail = NULL;
    while (1) {
        uuid_t uuid;
        uuid_generate(uuid);
        char *key = (char *)malloc(37); // UUID string length + null terminator
        if (!key) break;
        uuid_unparse(uuid, key);

        int value_int = rand();
        char *value = int_to_string(value_int);
        if (!value) {
            free(key);
            break;
        }

        Metadata *new_entry = (Metadata *)malloc(sizeof(Metadata));
        if (!new_entry) {
            free(key);
            free(value);
            break;
        }
        new_entry->key = key;
        new_entry->value = value;
        new_entry->next = NULL;

        // Append to the list
        if (tail) {
            tail->next = new_entry;
        } else {
            head = new_entry;
        }
        tail = new_entry;

        int current_size = strlen(key) + strlen(value);
        if (current_size > size_threshold) break;  // Check metadata size threshold
    }

    return head;
}

// Main function to create and initialize a document
Document* create_document() {
    pthread_mutex_lock(&lock);

    Document *doc = (Document *)malloc(sizeof(Document));
    if (!doc) {
        log_message("Failed to allocate memory for document");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int max_title_length = get_max_title_length();
    char **word_list;
    int word_count;
    word_list = get_word_list(&word_count);

    int encrypt = 1; // Example: encryption enabled
    doc->title = generate_title(word_list, word_count, max_title_length, encrypt);
    if (!doc->title) {
        log_message("Failed to allocate memory for title");
        free(doc);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int category_count;
    Category *categories = get_categories(&category_count);
    doc->category = generate_category(category_count);

    int metadata_size_threshold = get_metadata_size_threshold();
    doc->metadata = init_metadata(metadata_size_threshold);
    if (!doc->metadata) {
        log_message("Failed to allocate memory for metadata");
        free(doc->title);
        free(doc);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_mutex_unlock(&lock);
    log_message("Document created successfully");

    return doc;
}

// Dummy implementations of configuration and logging functions
int get_max_title_length() { return MAX_TITLE_LENGTH; }
char** get_word_list(int *word_count) {
    static char *words[] = {"Alpha", "Beta", "Gamma", "Delta"};
    *word_count = 4;
    return words;
}
Category* get_categories(int *category_count) {
    static Category categories[] = {CATEGORY_A, CATEGORY_B, CATEGORY_C};
    *category_count = 3;
    return categories;
}
int get_metadata_size_threshold() { return METADATA_SIZE_THRESHOLD; }
void log_message(const char *message) {
    printf("%s\n", message);
}

int main() {
    Document *doc = create_document();
    if (doc) {
        // Use the document
        free(doc->title);
        Metadata *meta = doc->metadata;
        while (meta) {
            Metadata *temp = meta;
            meta = meta->next;
            free(temp->key);
            free(temp->value);
            free(temp);
        }
        free(doc);
    }
    return 0;
}
```

This code provides a modular approach to creating and initializing `Document` structures with the specified features. It includes thread safety, error handling, configuration management, and logging mechanisms.']

