using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

public class HtmlUpdateService
{
    public bool UpdateHtmlContent(int pageSectionId, int elementId, string htmlContent)
    {
        // Implement the logic to update HTML content in a thread-safe manner.
        return true; // Simulate successful operation.
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapPost("/update-html", async context =>
            {
                if (!int.TryParse(context.Request.Form["pageSectionId"], out int pageSectionId) ||
                    !int.TryParse(context.Request.Form["elementId"], out int elementId))
                {
                    context.Response.StatusCode = StatusCodes.Status400BadRequest;
                    await context.Response.WriteAsync("Invalid request parameters.");
                    return;
                }

                string htmlContent = context.Request.Form["htmlContent"];

                HtmlUpdateService service = new HtmlUpdateService();
                bool success = service.UpdateHtmlContent(pageSectionId, elementId, htmlContent);

                if (success)
                {
                    context.Response.ContentType = "application/json";
                    await context.Response.WriteAsync("{\"message\":\"Page should be refreshed.\"}");
                }
                else
                {
                    context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                    await context.Response.WriteAsync("Error processing request.");
                }
            });
        });

        app.Use(async (context, next) =>
        {
            await next();
        });
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        CreateHostBuilder(args).Build().Run();
    }

    public static IHostBuilder CreateHostBuilder(string[] args) =>
        Host.CreateDefaultBuilder(args)
            .ConfigureWebHostDefaults(webBuilder =>
            {
