#define MAX_PATH 1024
#define MEMORY_LIMIT 1048576 // Adjust this as necessary

typedef struct File {
    char path[MAX_PATH];
    struct Directory *directory;
    time_t last_modified;
    int ownership_group;
} File;

typedef struct Directory {
    char name[256];
    struct File **files;
    int file_count;
    int is_read_only;
} Directory;

