    File **files;
    int count;
} ArchiveEntry;

typedef struct SymlinkReference {
    char target_path[MAX_PATH];
} SymlinkReference;

typedef struct LogRecord {
    char operation[50];
    char details[256];
} LogRecord;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
} LinkedList;

LinkedList files_list = {NULL};
LinkedList directories_list = {NULL};
LinkedList archives_list = {NULL};
LinkedList symlinks_list = {NULL};
LinkedList logs_list = {NULL};

unsigned long total_memory_allocated = 0;
int max_entries_reached = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to add a node to the linked list
void add_node(LinkedList *list, void *data) {
    pthread_mutex_lock(&lock);
    if (max_entries_reached) {
        fprintf(stderr, "Error: Maximum entry count reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Check memory limit
    unsigned long current_size = sizeof(Node) + (data == NULL ? 0 : sizeof(*data));
    if ((total_memory_allocated + current_size) > MEMORY_LIMIT) {
        fprintf(stderr, "Error: Memory usage exceeds the predefined limit.\n");
        free(new_node);
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    total_memory_allocated += current_size;
    if (total_memory_allocated >= MEMORY_LIMIT) {
        max_entries_reached = 1;
    }

    pthread_mutex_unlock(&lock);
}

// Function to serialize the linked lists
void serialize_data_structure(const char *filename) {
    // Implement serialization logic here
}

// Function to deserialize the linked lists
void deserialize_data_structure(const char *filename) {
    // Implement deserialization logic here
}

