    char line[MAX_PATH];

    while (fgets(line, sizeof(line), stdin)) {
        if (line[strlen(line) - 1] == '\n') {
            line[strlen(line) - 1] = '\0'; // Remove newline character
        }

        File *file = malloc(sizeof(File));
        if (!file) {
            fprintf(stderr, "Memory allocation failed for file.\n");
            continue;
