class XmlParserWithConfig
{
    private static readonly object lockObject = new object();
    private static readonly string ConfigFilePath = "config.xml";

    public List<XElement> ParseXmlAndFindElements(string xmlContent, string elementName)
    {
        XDocument doc = XDocument.Parse(xmlContent);
        XPathNavigator navigator = doc.CreateNavigator();

        XPathNodeIterator nodes = navigator.Select($"/root/{elementName}");
        var elements = new List<XElement>();

        while (nodes.MoveNext())
        {
            elements.Add((XElement)nodes.Current);
        }

        return elements;
    }

    public string GetOrCreateUniqueDirectory(string baseName)
    {
        string directoryPath;

        lock (lockObject)
        {
            XDocument configDoc = LoadConfig();
            XElement setting = configDoc.Root?.Element("Setting");

            if (setting != null && !string.IsNullOrEmpty(setting.Value))
            {
                directoryPath = setting.Value;
            }
            else
            {
                string timestamp = DateTime.UtcNow.ToString("yyyyMMddHHmmssfff");
                string uniqueId = Guid.NewGuid().ToString();
                directoryPath = Path.Combine(baseName, $"{timestamp}_{uniqueId}");

                if (!Directory.Exists(directoryPath))
                {
                    Directory.CreateDirectory(directoryPath);
                    setting = new XElement("Setting", directoryPath);

                    configDoc.Root?.Add(setting);
                    SaveConfig(configDoc);
                }
            }
        }

        return directoryPath;
    }

    private XDocument LoadConfig()
    {
        try
        {
            if (File.Exists(ConfigFilePath))
            {
                return XDocument.Load(ConfigFilePath);
            }
        }
        catch (Exception ex)
        {
            Log($"Error loading config file: {ex.Message}");
        }

        // Return a new document with the root element for atomic updates.
        return new XDocument(new XElement("Config"));
    }

    private void SaveConfig(XDocument doc)
    {
        try
        {
            using (var stream = new FileStream(ConfigFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
            {
                doc.Save(stream);
            }
        }
        catch (Exception ex)
        {
            Log($"Error saving config file: {ex.Message}");
        }
    }

    private void Log(string message)
    {
        // Simulated logging functionality
        Console.WriteLine($"{DateTime.UtcNow}: {message}");
    }
}
