#include <time.h>
#include <unistd.h>
#include <errno.h>

#define MAX_RETRIES 5

typedef struct {
    uint16_t rnti;
    uint32_t rx_ue_information_tag;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint8_t crc_flag;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T ue_info_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int success;
    char error_message[256];
} DatabaseResponse;

DatabaseResponse storeInDatabase(const NFAPI_CRC_INDICATION_PDU_T* pdu, size_t count);

void exponentialBackoff(int attempt) {
    sleep((1 << attempt));
}

NFAPI_CRC_INDICATION_PDU_T* populateNfadBWithCRCIndications(size_t num_pdus, int thread_id) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    srand(time(NULL) ^ (unsigned int)pthread_self());

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&mutex);

        pdus[i].ue_info_tag.rnti = rand() % 65536;
        pdus[i].ue_info_tag.rx_ue_information_tag = rand();
        pdus[i].crc_indication_rel8_tag.crc_flag = (rand() % 2);

        DatabaseResponse response;
        int attempt = 0;

        while (attempt < MAX_RETRIES) {
            response = storeInDatabase(&pdus[i], 1);
            if (response.success) break;
            exponentialBackoff(attempt++);
        }

        pthread_mutex_unlock(&mutex);
    }

    return pdus;
}

int loadResourceBundleFromFile(const char* filepath, void** bundle_out) {
    FILE* file = fopen(filepath, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned int* item_count = malloc(sizeof(unsigned int));
    if (!item_count) {
        fclose(file);
        return -2;
    }

    fread(item_count, sizeof(unsigned int), 1, file);
    *bundle_out = malloc(filesize);
    if (!(*bundle_out)) {
        free(item_count);
        fclose(file);
        return -3;
    }

    fread(*bundle_out, filesize - sizeof(unsigned int), 1, file);

    fclose(file);

    return (int)(*item_count);
}
