```java
import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class FileHashService {

    private static final Logger logger = Logger.getLogger(FileHashService.class.getName());
    private final ExecutorService executorService;
    private final ConcurrentHashMap<String, String> hashCache;
    private final ScheduledExecutorService cacheEvictionScheduler;

    public FileHashService(int threadPoolSize) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.hashCache = new ConcurrentHashMap<>();
        this.cacheEvictionScheduler = Executors.newScheduledThreadPool(1);

        // Schedule periodic eviction for the cache to balance memory usage and data freshness
        this.cacheEvictionScheduler.scheduleAtFixedRate(this::evictOldEntries, 10, 10, TimeUnit.MINUTES);
    }

    public CompletableFuture<List<FileHashResult>> processFiles(List<String> filePaths) {
        List<CompletableFuture<FileHashResult>> futures = filePaths.stream()
            .map(this::processFile)
            .collect(Collectors.toList());

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(v -> futures.stream()
                        .map(CompletableFuture::join)
                        .collect(Collectors.toList()));
    }

    private CompletableFuture<FileHashResult> processFile(String filePath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                validateFileName(filePath);

                // Check cache first
                String cachedHash = hashCache.get(filePath);
                if (cachedHash != null) {
                    logger.info("Cache hit for: " + filePath);
                    return new FileHashResult(filePath, cachedHash);
                }

                byte[] fileData = Files.readAllBytes(new File(filePath).toPath());

                // Fetch metadata and handle potential failures
                String mimeType = fetchMimeTypeSafely(filePath);

                // Compute hash
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                byte[] hashBytes = digest.digest(fileData);
                String fileHash = bytesToHex(hashBytes);

                // Cache the result
                hashCache.put(filePath, fileHash);

                return new FileHashResult(filePath, fileHash, mimeType);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error processing file: " + filePath, e);
                throw new RuntimeException("File processing failed", e);
            }
        }, executorService);
    }

    private void validateFileName(String fileName) throws IllegalArgumentException {
        if (fileName.length() > 255 || !fileName.matches("[\\w,.\\s-]*")) { // Simplified validation
            throw new IllegalArgumentException("Invalid file name: " + fileName);
        }
    }

    private String fetchMimeTypeSafely(String filePath) {
        try {
            // Simulate fetching MIME type from external service
            return "application/octet-stream";  // Placeholder for actual implementation
        } catch (Exception e) {
            logger.log(Level.WARNING, "Failed to fetch MIME type: " + filePath, e);
            return "unknown";
        }
    }

    private String bytesToHex(byte[] hashBytes) {
        StringBuilder hexString = new StringBuilder(2 * hashBytes.length);
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void evictOldEntries() {
        // Eviction logic; for simplicity, clear cache every interval
        hashCache.clear();
        logger.info("Cache entries have been cleared.");
    }

    public static class FileHashResult {
        private final String filePath;
        private final String fileHash;
        private final String mimeType;

        public FileHashResult(String filePath, String fileHash) {
            this(filePath, fileHash, "unknown");
        }

        public FileHashResult(String filePath, String fileHash, String mimeType) {
            this.filePath = filePath;
            this.fileHash = fileHash;
            this.mimeType = mimeType;
        }

        // Getters
    }

    public static void main(String[] args) {
        FileHashService service = new FileHashService(10);

        List<String> filesToProcess = List.of(
                "/path/to/file1.txt",
                "/path/to/file2.png"
        );

        service.processFiles(filesToProcess)
            .thenAccept(results -> results.forEach(result ->
                System.out.println("File: " + result.filePath +
                        ", Hash: " + result.fileHash +
                        ", MIME Type: " + result.mimeType)));
    }
}
```

