#include "json-c/json.h"
#include "logging_framework.h" // hypothetical logging framework

typedef struct {
    long timestamp;
    char eventType[50];
    int uniqueId;
    char* metadataJson;
} TrafficEvent;

#define MAX_EVENT_NAME_LENGTH 11
#define EVENT_ARRAY_INITIAL_CAPACITY 10

typedef struct {
    TrafficEvent** events;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} TrafficEventManager;

// Function prototypes
void initTrafficEventManager(TrafficEventManager* manager);
int addTrafficEvent(TrafficEventManager* manager, TrafficEvent* event);
int removeTrafficEventByTimestamp(TrafficEventManager* manager, long startTimestamp, long endTimestamp);
TrafficEvent* getEventsInRange(TrafficEventManager* manager, long startTimestamp, long endTimestamp);
void freeTrafficEventManager(TrafficEventManager* manager);

// Utility functions
static TrafficEvent* createRandomTrafficEvent(int sequentialOffset);
static char* generateRandomString(size_t length);
static int serializeJsonToFile(const char *filename, json_object *jsonObj);
static json_object* deserializeJsonFromFile(const char *filename);

void initTrafficEventManager(TrafficEventManager* manager) {
    manager->events = malloc(sizeof(TrafficEvent*) * EVENT_ARRAY_INITIAL_CAPACITY);
    if (manager->events == NULL) {
        perror("Failed to allocate memory for events array");
        exit(EXIT_FAILURE);
    }
    manager->capacity = EVENT_ARRAY_INITIAL_CAPACITY;
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);
}

int addTrafficEvent(TrafficEventManager* manager, TrafficEvent* event) {
    if (pthread_rwlock_wrlock(&manager->lock)) {
        perror("Failed to acquire write lock");
        return -1;
    }

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        TrafficEvent** newEvents = realloc(manager->events, sizeof(TrafficEvent*) * newCapacity);
        if (!newEvents) {
            perror("Failed to reallocate memory for events array");
            pthread_rwlock_unlock(&manager->lock);
            return -1;
        }
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }

    manager->events[manager->count++] = event;

    // Log the event
    logEvent("Insert", event);  // Hypothetical logging function

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

int removeTrafficEventByTimestamp(TrafficEventManager* manager, long startTimestamp, long endTimestamp) {
    if (pthread_rwlock_wrlock(&manager->lock)) {
        perror("Failed to acquire write lock");
        return -1;
    }

    for (size_t i = 0; i < manager->count;) {
        if (manager->events[i]->timestamp >= startTimestamp && manager->events[i]->timestamp <= endTimestamp) {
            free(manager->events[i]->metadataJson);
            free(manager->events[i]);
            memmove(&manager->events[i], &manager->events[i + 1], sizeof(TrafficEvent*) * (manager->count - i - 1));
            manager->count--;
        } else {
            i++;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

TrafficEvent* getEventsInRange(TrafficEventManager* manager, long startTimestamp, long endTimestamp) {
    if (pthread_rwlock_rdlock(&manager->lock)) {
        perror("Failed to acquire read lock");
        return NULL;
    }

    TrafficEvent* result = malloc(sizeof(TrafficEvent) * manager->count);
    size_t resCount = 0;

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->events[i]->timestamp >= startTimestamp && manager->events[i]->timestamp <= endTimestamp) {
            result[resCount++] = *manager->events[i];
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return resCount > 0 ? result : NULL;
}

void freeTrafficEventManager(TrafficEventManager* manager) {
    if (pthread_rwlock_wrlock(&manager->lock)) {
        perror("Failed to acquire write lock");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < manager->count; i++) {
        free(manager->events[i]->metadataJson);
        free(manager->events[i]);
    }

    free(manager->events);
    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

static TrafficEvent* createRandomTrafficEvent(int sequentialOffset) {
    TrafficEvent* event = malloc(sizeof(TrafficEvent));
    if (!event) {
        perror("Failed to allocate memory for TrafficEvent");
        return NULL;
    }

    time_t now = time(NULL);
    event->timestamp = (long)now + sequentialOffset;

    snprintf(event->eventType, sizeof(event->eventType), "EventType%d", sequentialOffset);
    event->uniqueId = rand() % 10000 + 1; // Unique ID generation

    char* randomString = generateRandomString(MAX_EVENT_NAME_LENGTH - 1);
    if (!randomString) {
        free(event);
        return NULL;
    }

    json_object *jobj = json_object_new_object();
    json_object_object_add(jobj, "value", json_object_new_int(rand() % 100));
    json_object_object_add(jobj, "status", json_object_new_string("AB"[rand() % 2]));

    char* jsonString = strdup(json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY));
    if (!jsonString) {
        free(randomString);
        json_object_put(jobj); // Free the json object
        free(event);
        return NULL;
    }

    event->metadataJson = malloc(strlen(jsonString) + strlen(randomString) + 2);
    snprintf(event->metadataJson, strlen(jsonString) + strlen(randomString) + 2, "%s, \"%s\"", jsonString, randomString);

    free(randomString);
    free(jsonString);
    json_object_put(jobj); // Free the json object

    return event;
}

static char* generateRandomString(size_t length) {
    static const char alphanum[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    char *str = malloc(length + 1);
    if (!str) return NULL;

    for (size_t i = 0; i < length; ++i)
        str[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
    str[length] = '\0';

    return str;
}

// Serialization and deserialization stubs
static int serializeJsonToFile(const char *filename, json_object *jsonObj) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for serialization");
        return -1;
    }

    const char* jsonString = strdup(json_object_to_json_string_ext(jsonObj, JSON_C_TO_STRING_PRETTY));
    if (fwrite(jsonString, 1, strlen(jsonString), file) != strlen(jsonString)) {
        free(jsonString);
        fclose(file);
        perror("Failed to write JSON string to file");
        return -1;
    }

    free(jsonString);
    fclose(file);
    return 0;
}

static json_object* deserializeJsonFromFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for deserialization");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    char* buffer = malloc(length + 1);
    if (!buffer) {
        fclose(file);
        perror("Failed to allocate memory for JSON string buffer");
        return NULL;
    }

    if (fread(buffer, 1, length, file) != length) {
        free(buffer);
        fclose(file);
        perror("Failed to read JSON string from file");
        return NULL;
    }

    buffer[length] = '\0';
    json_object* jsonObj = json_tokener_parse(buffer);

    free(buffer);
    fclose(file);

    if (!jsonObj) {
        fprintf(stderr, "Invalid JSON in file %s\n", filename);
    }

    return jsonObj;
}
```

