} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    arr->head = NULL;
    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    return arr;
}

void generate_random_string(char *str, size_t length) {
