        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (length) {
        --length; // Leave space for null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(int tag, int rnti, int crcTag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = crcTag;
    pdu.CRCFLAG = rand() % 2;

    char responseHeaders[51];
    generate_random_string(responseHeaders, 50);
    pdu.responseDetail.responseHeaders = malloc(51);
    strcpy(pdu.responseDetail.responseHeaders, responseHeaders);

    float latency = (rand() / (float)RAND_MAX) * 100.0; // Random latency
    char status = rand() % 2 ? 'S' : 'F'; // Random status

    // Assume `logEntry` logs this information
    printf("Inserting PDU with RNTI: %d, CRCFLAG: %d\n", rnti, pdu.CRCFLAG);

    return pdu;
}

void insert_pdu(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&arr->lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = pdu;
    newNode->next = arr->head;
    arr->head = newNode;
    arr->count++;

    // Assume `logEntry` logs this insertion
    printf("PDU inserted with RNTI: %d\n", pdu.RNTI);

    pthread_mutex_unlock(&arr->lock);
}

void delete_pdu(DynamicArray *arr, int rnti) {
    pthread_mutex_lock(&arr->lock);

    Node *current = arr->head;
    Node *previous = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    if (previous == NULL) {
        arr->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->data.responseDetail.responseHeaders);
    free(current);

    arr->count--;

    // Assume `logEntry` logs this deletion
    printf("PDU deleted with RNTI: %d\n", rnti);

    pthread_mutex_unlock(&arr->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(DynamicArray *arr, int rnti) {
    pthread_mutex_lock(&arr->lock);

    Node *current = arr->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = NULL;
    if (current != NULL) {
        result = &current->data;

        // Assume `logEntry` logs this retrieval
        printf("PDU retrieved with RNTI: %d\n", rnti);
    }

    pthread_mutex_unlock(&arr->lock);
    return result;
}

void cleanup_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    Node *current = arr->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data.responseDetail.responseHeaders);
        free(current);
        current = next;
    }

    arr->head = NULL;
    arr->count = 0;

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

// Placeholder for rate-limiting logic
void apply_rate_limit() {
    // Implement rate limiting mechanism here
}

int main() {
