### C# High-Performance Concurrent HTTP Server

```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using System.Threading.Tasks;

public class PageUpdateService
{
    public Task UpdateElementHtmlAsync(string sectionId, string elementId, string htmlContent)
    {
        // Implement the logic to update HTML content here.
        return Task.CompletedTask;
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllers();
        services.AddSingleton<PageUpdateService>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapPost("/update-element", async context =>
            {
                var pageUpdateService = context.RequestServices.GetRequiredService<PageUpdateService>();

                if (!context.Request.HasFormContentType)
                {
                    context.Response.StatusCode = 400;
                    await context.Response.WriteAsync("Bad Request");
                    return;
                }

                var form = await context.Request.ReadFormAsync();
                string sectionId = form["sectionId"];
                string elementId = form["elementId"];
                string htmlContent = form["htmlContent"];

                if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
                {
                    context.Response.StatusCode = 400;
                    await context.Response.WriteAsync("Bad Request");
                    return;
                }

                try
                {
                    await pageUpdateService.UpdateElementHtmlAsync(sectionId, elementId, htmlContent);
                    context.Response.ContentType = "application/json";
                    await context.Response.WriteAsync("{\"status\":\"refresh\"}");
                }
                catch (Exception)
                {
                    context.Response.StatusCode = 500;
                    await context.Response.WriteAsync("Internal Server Error");
                }
            });
        });
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        Host.CreateDefaultBuilder(args)
            .ConfigureWebHostDefaults(webBuilder =>
            {
                webBuilder.UseStartup<Startup>();
            })
            .Build()
            .Run();
    }
}
```

