void serialize_data_structure(record* records, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(&count, sizeof(count), 1, file);
    fwrite(records, sizeof(record), count, file);

    fclose(file);
}

void deserialize_data_structure(record** records, int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    fread(count, sizeof(int), 1, file);
    *records = malloc(sizeof(record) * (*count));
    if (!(*records)) {
        perror("Memory allocation failed during deserialization");
        fclose(file);
        return;
    }

    fread(*records, sizeof(record), *count, file);

    fclose(file);
}

