    process_file_paths(&max_depth_tracker, MAX_DEPTH);

    record* records = NULL;
    int count = 0;
    deserialize_data_structure(&records, &count, "data.bin");

    serialize_data_structure(records, count, "new_data.bin");

    free(records);
    return 0;
}
