namespace fs = std::filesystem;

class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& io_service, const std::string& server)
        : resolver_(io_service), socket_(io_service) {
        boost::asio::ip::tcp::resolver::query query(server, "http");
        auto endpoints = resolver_.resolve(query);
        boost::asio::async_connect(socket_, endpoints,
            [this](boost::system::error_code ec, boost::asio::ip::tcp::endpoint) {
                if (!ec) {
                    // Start the session.
                    doRead();
                }
            });
    }

    void sendRequest(const std::string& request);

private:
    void doRead();
    void doWrite();

    boost::asio::ip::tcp::resolver resolver_;
    boost::asio::ip::tcp::socket socket_;
    enum { max_length = 1024 };
    char data_[max_length];
};

void SandeshClient::sendRequest(const std::string& request) {
    auto self(shared_from_this());
    boost::asio::async_write(socket_, boost::asio::buffer(request),
        [this, self](boost::system::error_code ec, std::size_t /*length*/) {
            if (!ec)
                doRead();
        });
}

void SandeshClient::doRead() {
    auto self(shared_from_this());
    socket_.async_read_some(boost::asio::buffer(data_, max_length),
        [this, self](boost::system::error_code ec, std::size_t length) {
            if (!ec)
                doWrite(length);
            else
                std::cerr << "Error on receive: " << ec.message() << std::endl;
        });
}

void SandeshClient::doWrite(std::size_t length) {
    auto self(shared_from_this());
    boost::asio::async_write(socket_, boost::asio::buffer(data_, length),
        [this, self](boost::system::error_code ec, std::size_t /*length*/) {
            if (!ec)
                doRead();
            else
                std::cerr << "Error on send: " << ec.message() << std::endl;
        });
}

