typedef struct {
    int value;
} record;

SQLHANDLE initializeAndQueryDatabase(const char *connectionString, const char *commandTemplate, record *records, size_t numRecords) {
    if (!records || !numRecords) return NULL;

    // Memory allocation for offset and keys arrays
    long *offsets = (long *)calloc(numRecords, sizeof(long));
    int *keys = (int *)malloc(numRecords * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Random number generator initialization
    srand((unsigned)time(NULL));

    SQLHANDLE envHandle = NULL, dbHandle = NULL, stmtHandle = NULL;
    RETCODE retcode;

    // Allocate environment handle
    retcode = SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &envHandle);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error allocating environment handle\n");
        goto cleanup;
    }

    // Set the ODBC version environment attribute
    retcode = SQLSetEnvAttr(envHandle, SQL_ATTR_ODBC_VERSION, (void *)SQL_OV_ODBC3, 0);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error setting ODBC version\n");
        goto cleanup;
    }

    // Allocate connection handle
    retcode = SQLAllocHandle(SQL_HANDLE_DBC, envHandle, &dbHandle);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error allocating database handle\n");
        goto cleanup;
    }

    // Connect to the database
    retcode = SQLConnect(dbHandle, (SQLCHAR *)connectionString, SQL_NTS, NULL, 0, NULL, 0);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error connecting to the database\n");
        goto cleanup;
    }

    // Allocate statement handle
    retcode = SQLAllocHandle(SQL_HANDLE_STMT, dbHandle, &stmtHandle);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error allocating statement handle\n");
        goto cleanup;
    }

    // Construct the parameterized SQL command
    char sqlCommand[1024] = {0};
    snprintf(sqlCommand, sizeof(sqlCommand), commandTemplate, numRecords);

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = i * sizeof(record);
        keys[i] = records[i].value;
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }

    // Prepare the SQL statement
    retcode = SQLPrepare(stmtHandle, (SQLCHAR *)sqlCommand, SQL_NTS);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error preparing SQL statement\n");
        goto cleanup;
    }

    // Bind parameters (example: offset and key)
    for (size_t i = 0; i < numRecords; ++i) {
        SQLBindParameter(stmtHandle, i + 1, SQL_PARAM_INPUT, SQL_C_LONG, SQL_INTEGER, 0, 0, &keys[i], 0, NULL);
    }

    // Execute the statement
    retcode = SQLExecute(stmtHandle);
    if (retcode != SQL_SUCCESS && retcode != SQL_SUCCESS_WITH_INFO) {
        fprintf(stderr, "Error executing SQL statement\n");
        goto cleanup;
    }

    return stmtHandle; // Return IDataReader equivalent

cleanup:
    free(offsets);
    free(keys);

    if (stmtHandle) SQLFreeHandle(SQL_HANDLE_STMT, stmtHandle);
    if (dbHandle) {
        SQLDisconnect(dbHandle);
        SQLFreeHandle(SQL_HANDLE_DBC, dbHandle);
    }
    if (envHandle) SQLFreeHandle(SQL_HANDLE_ENV, envHandle);

    return NULL;
}
