#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_HEADERS_LENGTH 50

typedef struct {
    int latency;
    char status_indicator;
    char *response_headers;
} ResponseDetail;

typedef struct {
    // Dummy structures for illustration
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG; // Randomly set
    ResponseDetail response_detail;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
    pthread_mutex_t lock;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t list_lock;
    int size;
} DynamicArray;

DynamicArray* create_array() {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->list_lock, NULL);
    array->size = 0;
    return array;
}

void free_response_detail(ResponseDetail *detail) {
    if (detail && detail->response_headers) {
        free(detail->response_headers);
    }
}

void free_node(Node *node) {
    if (node) {
        free_response_detail(&node->data.response_detail);
        pthread_mutex_destroy(&node->lock);
        free(node);
    }
}

void insert_pdu(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = pdu;
    pthread_mutex_init(&new_node->lock, NULL);

    char response_headers[MAX_HEADERS_LENGTH + 1];
    for (int i = 0; i < MAX_HEADERS_LENGTH; i++) {
        int rand_value = rand() % 62;
        if (rand_value < 10) {
            response_headers[i] = '0' + rand_value;
        } else if (rand_value < 36) {
            response_headers[i] = 'A' + (rand_value - 10);
        } else {
            response_headers[i] = 'a' + (rand_value - 36);
        }
    }
    response_headers[MAX_HEADERS_LENGTH] = '\0';
    new_node->data.response_detail.response_headers = strdup(response_headers);

    pthread_mutex_lock(&array->list_lock);
    if (!array->head) {
        array->head = new_node;
        new_node->next = NULL;
    } else {
        Node *current = array->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
        new_node->next = NULL;
    }
    array->size++;
    pthread_mutex_unlock(&array->list_lock);

    // Log entry
    printf("Inserted PDU with RNTI: %d\n", pdu.RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(DynamicArray *array, int rnti) {
    pthread_mutex_lock(&array->list_lock);
    Node *current = array->head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &current->data;
            pthread_mutex_unlock(&current->lock);
            pthread_mutex_unlock(&array->list_lock);
            return pdu;
        }
        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }
    pthread_mutex_unlock(&array->list_lock);
    return NULL;
}

void delete_pdu(DynamicArray *array, int rnti) {
    pthread_mutex_lock(&array->list_lock);
    Node **indirect = &array->head;
    while (*indirect) {
        Node *current = *indirect;
        if (current->data.RNTI == rnti) {
            pthread_mutex_lock(&current->lock);
            *indirect = current->next;
            free_node(current);
            array->size--;
            pthread_mutex_unlock(&array->list_lock);
            return;
        }
        indirect = &current->next;
    }
    pthread_mutex_unlock(&array->list_lock);
}

void cleanup_array(DynamicArray *array) {
    Node *current = array->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free_node(temp);
    }
    pthread_mutex_destroy(&array->list_lock);
    free(array);
}

int main() {
    srand(time(NULL));
    DynamicArray *array = create_array();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 2001, rand(), {0.0f, 'S', NULL}};
    insert_pdu(array, pdu1);

    NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = retrieve_pdu(array, 1001);
    if (retrieved_pdu) {
        printf("Retrieved PDU with RNTI: %d\n", retrieved_pdu->RNTI);
    }

    delete_pdu(array, 1001);

    cleanup_array(array);
    return 0;
}
