using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net;
using System.Threading;
using System.Threading.Tasks;

public class TextProcessingUtility
{
    private static readonly object _logLock = new object();
    private static readonly BlockingCollection<string> _lineQueue = new BlockingCollection<string>(new ConcurrentQueue<string>());
    private const int MaxFieldsPerLine = 50;
    private const string LogFilePath = "process.log";
    private const long MaxLogFileSize = 1024 * 1024; // 1 MB

    public static void Main(string[] args)
    {
        if (args.Length < 1) throw new ArgumentException("Input file path is required.");

        var filePath = args[0];

        Task.Run(() => MonitorResourceUsage());

        try
        {
            using (var reader = File.OpenText(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    _lineQueue.Add(line);
                }
                _lineQueue.CompleteAdding();
            }

            var processingTasks = Enumerable.Range(0, Environment.ProcessorCount).Select(_ => Task.Run(ProcessLines)).ToArray();
            Task.WaitAll(processingTasks);

        }
        catch (Exception ex)
        {
            Log($"Error: {ex.Message}");
        }
    }

    private static void ProcessLines()
    {
        foreach (var line in _lineQueue.GetConsumingEnumerable())
        {
            try
            {
                var fields = line.Split(new[] { '\t', ' ' }, StringSplitOptions.RemoveEmptyEntries);

                if (fields.Length > MaxFieldsPerLine) continue;

                string? firstHostname = null, secondHostname = null;

                if (fields.Length >= 48)
                    firstHostname = fields[48];
                if (fields.Length == MaxFieldsPerLine)
                    secondHostname = fields[49];

                ProcessHostnames(firstHostname, secondHostname);
            }
            catch (Exception ex)
            {
                Log($"Error processing line: {ex.Message}");
            }
        }
    }

    private static void ProcessHostnames(string? firstHostname, string? secondHostname)
    {
        try
        {
            if (!string.IsNullOrEmpty(firstHostname))
            {
                ResolveAndLog(firstHostname);
            }
            if (!string.IsNullOrEmpty(secondHostname))
            {
                ResolveAndLog(secondHostname);
            }
        }
        catch (Exception ex)
        {
            Log($"DNS resolution error: {ex.Message}");
        }
    }

    private static void ResolveAndLog(string hostname, int retryCount = 3)
    {
        for (int attempt = 0; attempt < retryCount; attempt++)
        {
            try
            {
                var addresses = Dns.GetHostAddresses(hostname);
                Log($"Resolved {hostname}: {string.Join(", ", addresses.Select(a => a.ToString()))}");
                return;
            }
            catch (SocketException)
            {
                Thread.Sleep(1000); // Retry after 1 second delay for simplicity.
            }
        }

        Log($"Failed to resolve hostname: {hostname} after {retryCount} attempts.");
    }

    private static void MonitorResourceUsage()
    {
        while (true)
        {
            var cpuUsage = GetCpuUsage();
            var memoryUsage = GC.GetTotalMemory(true);
            Console.WriteLine($"CPU Usage: {cpuUsage}% - Memory Usage: {memoryUsage / 1024 / 1024} MB");

            Thread.Sleep(5000); // Monitor every 5 seconds.
        }
    }

    private static int GetCpuUsage()
    {
        var cpuCounter = new PerformanceCounter("Processor", "% Processor Time", "_Total");
        return (int)cpuCounter.NextValue();
    }

    private static void Log(string message)
    {
        lock (_logLock)
        {
            if (!File.Exists(LogFilePath) || new FileInfo(LogFilePath).Length < MaxLogFileSize)
            {
                using var writer = File.AppendText(LogFilePath);
                writer.WriteLine($"{DateTime.Now}: {message}");
            }
            else
            {
                using var rotatedLogWriter = File.CreateText("process.log.old");
                using var currentLogReader = File.OpenText(LogFilePath);
                while (!currentLogReader.EndOfStream)
                    rotatedLogWriter.WriteLine(currentLogReader.ReadLine());

                using var writer = File.AppendText(LogFilePath);
                writer.WriteLine($"{DateTime.Now}: {message}");
            }
        }
    }
}
```

