import<stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>

#define MAX_RESPONSE_HEADERS 50
#define RATE_LIMIT 10000 // operations per second

typedef struct {
    float latency;
    char status;
    char *response_headers;
} ResponseDetail;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRCFLAG;
    ResponseDetail response_detail;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    unsigned long operations_count;
    time_t last_reset_time;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->operations_count = 0;
    array->last_reset_time = time(NULL);
    return array;
}

void free_response_detail(ResponseDetail *detail) {
    if (detail && detail->response_headers) {
        free(detail->response_headers);
    }
}

void free_node(Node *node) {
    if (node) {
        free_response_detail(&node->data.response_detail);
        free(node);
    }
}

int rate_limit_check(DynamicArray *array) {
    time_t current_time = time(NULL);
    if (current_time != array->last_reset_time) {
        array->operations_count = 0;
        array->last_reset_time = current_time;
    }

    return array->operations_count < RATE_LIMIT;
}

void increment_operation_count(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    if (rate_limit_check(array)) {
        array->operations_count++;
        pthread_mutex_unlock(&array->lock);
        return;
    }
    pthread_mutex_unlock(&array->lock);
    fprintf(stderr, "Rate limit exceeded\n");
}

void random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

void insert_pdu(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!rate_limit_check(array)) return;

    increment_operation_count(array);

    Node *new_node = malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = array->head;
    array->head = new_node;

    // Log the insertion
    printf("Inserted PDU with RX_UE_INFORMATION_TAG: %lu\n", pdu.RX_UE_INFORMATION_TAG);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(DynamicArray *array, unsigned long RNTI) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&array->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void delete_pdu(DynamicArray *array, unsigned long RNTI) {
    if (!rate_limit_check(array)) return;

    increment_operation_count(array);

    pthread_mutex_lock(&array->lock);

    Node **indirect = &array->head;
    while (*indirect) {
        if ((*indirect)->data.RNTI == RNTI) {
            Node *to_delete = *indirect;
            *indirect = to_delete->next;
            free_node(to_delete);
            pthread_mutex_unlock(&array->lock);
            return;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void destroy_dynamic_array(DynamicArray *array) {
    Node *current = array->head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

