#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000000

typedef enum { ACTIVE, INACTIVE } PacketStatus;

typedef struct {
    char identifier[64];
    time_t timestamp;
    PacketStatus status;
    int value;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} PacketList;

typedef struct {
    PacketList packets;
    time_t expiration_threshold;
    FILE* log_file;
    int log_level; // 0: None, 1: Basic, 2: Detailed
} PacketManager;

PacketManager manager = {NULL, 3600, stdout, 1};

void log_message(const char* message) {
    if (manager.log_level > 0) {
        fprintf(manager.log_file, "%s\n", message);
        fflush(manager.log_file);
    }
}

Node* create_node(const DataPacket* packet) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    *node->packet = *packet;
    node->next = NULL;
    return node;
}

void destroy_packet_list(PacketList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_or_update_packet(const char* identifier, int value) {
    pthread_mutex_lock(&manager.packets.lock);

    Node** curr = &manager.packets.head;
    while (*curr) {
        if (strcmp((*curr)->packet.identifier, identifier) == 0) {
            (*curr)->packet.value = value;
            log_message("Packet updated");
            pthread_mutex_unlock(&manager.packets.lock);
            return 1;
        }
        curr = &(*curr)->next;
    }

    DataPacket new_packet = {.timestamp = time(NULL), .status = ACTIVE, .value = value};
    strncpy(new_packet.identifier, identifier, sizeof(new_packet.identifier) - 1);

    Node* node = create_node(&new_packet);
    if (!node) {
        pthread_mutex_unlock(&manager.packets.lock);
        return 0;
    }

    *curr = node;
    manager.packets.count++;
    log_message("Packet added");
    pthread_mutex_unlock(&manager.packets.lock);
    return 1;
}

DataPacket* get_packet(const char* identifier) {
    pthread_mutex_lock(&manager.packets.lock);

    Node* current = manager.packets.head;
    while (current) {
        if (strcmp(current->packet.identifier, identifier) == 0) {
            DataPacket* packet = malloc(sizeof(DataPacket));
            *packet = current->packet;
            pthread_mutex_unlock(&manager.packets.lock);
            return packet;
