    time_t cache_expiry_time;
} MemoryManager;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int random_status_char() {
    return (rand() % 2 == 0) ? 'A' : 'B';
}

char* generate_random_string(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *random_string = malloc(length + 1);

    if (!random_string) return NULL;

    for (size_t i = 0; i < length; i++) {
        random_string[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_string[length] = '\0';
    return random_string;
}

u_char* resolve_hostname_to_ip(const char *hostname, size_t *ip_length) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char *ip_address = NULL;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &ipv4->sin_addr, ipstr, INET_ADDRSTRLEN);

        if (!ip_address) {
            ip_address = malloc(INET_ADDRSTRLEN);
            strncpy((char*)ip_address, ipstr, INET_ADDRSTRLEN);
            *ip_length = strlen(ipstr);
        }
    }

    freeaddrinfo(res);
    return ip_address;
}

int initialize_memory_manager(MemoryManager *manager, size_t num_records) {
    if (!manager) return 0;

    pthread_mutex_init(&manager->lock, NULL);

    manager->num_records = num_records;

    // Allocate memory
    manager->offsets = malloc(num_records * sizeof(long));
    manager->keys = malloc(num_records * sizeof(int));
    manager->records = malloc(num_records * sizeof(Record));

    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0;
    }

    // Initialize memory
    for (size_t i = 0; i < num_records; ++i) {
        manager->offsets[i] = (long)i;

        manager->keys[i] = (int)i;

        manager->records[i].value = rand() % 100; // Example range: 0-99
        manager->records[i].status = random_status_char();

        char *random_name = generate_random_string(RANDOM_STRING_LENGTH);
        if (!random_name) {
            fprintf(stderr, "Failed to allocate memory for random string\n");
            return 0;
        }
        manager->records[i].name = random_name;
    }

    // Cache management
    manager->ip_address_cache = NULL;
    manager->cache_expiry_time = 0;

    return 1;
}

void cleanup_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_records; ++i) {
        free(manager->records[i].name);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    if (manager->ip_address_cache) {
        free(manager->ip_address_cache);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int update_ip_cache(MemoryManager *manager, const char *hostname) {
    time_t current_time;
    size_t ip_length;

    if (!manager || !hostname) return 0;

    pthread_mutex_lock(&manager->lock);

    // Check cache expiry
    current_time = time(NULL);
    if (manager->ip_address_cache && current_time < manager->cache_expiry_time) {
        pthread_mutex_unlock(&manager->lock);
        return 1; // Cache is valid
    }

    u_char *new_ip_address = resolve_hostname_to_ip(hostname, &ip_length);
    if (!new_ip_address) {
        fprintf(stderr, "Failed to resolve hostname\n");
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    free(manager->ip_address_cache); // Free old cache
    manager->ip_address_cache = new_ip_address;

    // Set a TTL of 60 seconds for the cache
    manager->cache_expiry_time = current_time + 60;

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

int main() {
    initialize_random();

    MemoryManager manager;
    size_t num_records = 100; // Example size

    if (initialize_memory_manager(&manager, num_records)) {
        printf("Memory initialized successfully\n");

        const char *hostname = "example.com";
        if (update_ip_cache(&manager, hostname)) {
            printf("IP cache updated for hostname: %s\n", hostname);
        }

        cleanup_memory_manager(&manager);
    } else {
        fprintf(stderr, "Failed to initialize memory manager\n");
    }

    return 0;
}
