#define MAX_CACHE_SIZE 100

typedef struct {
    char *identifier;
    char name[50];
    char email[100];
    time_t lastActivityTimestamp;
    int connectionStatus; // 0: disconnected, 1: connected
} UserSession;

typedef struct CacheNode {
    UserSession session;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    CacheNode *head;
    CacheNode *tail;
    size_t size;
} LRUCache;

LRUCache* createCache(size_t maxSize) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    return cache;
}

void moveToHead(CacheNode** head, CacheNode* node) {
    if (*head == node || !node) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (*head == node) *head = node->next;

    node->next = NULL;
    node->prev = *head;
    if (*head) (*head)->prev = node;
    *head = node;

    if (!(*head)->prev) cache->tail = *head;
}

void removeNode(CacheNode** head, CacheNode* node) {
    if (node->next) node->next->prev = node->prev;
    if (node->prev) node->prev->next = node->next;
    if (*head == node) *head = node->next;

    if (!(*head)) cache->tail = NULL;
}

void evictLRU(LRUCache* cache) {
    if (!cache->tail) return;

    CacheNode* lru = cache->tail;
    removeNode(&(cache->head), lru);
    free(lru);
    cache->size--;
}

