    if (session) {
        moveToHead(&(cache->head), &(session->node)); // Assuming node is part of struct
    } else {
        // Fallback to external data source or database
    }
    return session;
}

void disconnectInactiveSessions(LRUCache* cache, time_t inactivityThreshold) {
    time_t currentTime = time(NULL);
    CacheNode *current = cache->tail;

    while (current != NULL) {
        if ((currentTime - current->session.lastActivityTimestamp) > inactivityThreshold) {
            removeNode(&(cache->head), current);
            CacheNode* temp = current;
            current = current->prev;
            free(temp);
            cache->size--;
        } else {
            break; // Cache is ordered, no need to check further
        }
    }
}

