        return NULL;
    }

    char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t charsetSize = sizeof(charset) - 1;

    for (size_t i = 0; i < numToAllocate; ++i) {
        newRecords[i].value = rand() % 1000; // Random int value
        for (int j = 0; j < BUFFER_SIZE - 1; ++j) {
            newRecords[i].buffer[j] = charset[rand() % charsetSize];
        }
        newRecords[i].buffer[BUFFER_SIZE - 1] = '\0';
    }

    globalData.records = realloc(globalData.records, (globalData.numRecords + numToAllocate) * sizeof(record_t));
    if (!globalData.records) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(newRecords);
        pthread_mutex_unlock(&globalData.mutex);
        return NULL;
    }

    memcpy(globalData.records + globalData.numRecords, newRecords, numToAllocate * sizeof(record_t));
    totalAllocatedRecords += numToAllocate;
    globalData.numRecords += numToAllocate;

    free(newRecords);
    pthread_mutex_unlock(&globalData.mutex);

    // Simulate serialization (writing to file)
    FILE* file = fopen("crc_indications.bin", "ab");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return NULL;
    }

    size_t recordsWritten = fwrite(globalData.records, sizeof(record_t), globalData.numRecords, file);
    fclose(file);

    if (recordsWritten != globalData.numRecords) {
        fprintf(stderr, "Failed to write all records to the file\n");
    }

    return NULL;
}

void deserialize_cfdi_with_crc_indications() {
