    if (bytesRead > 0) {
        globalData.records = realloc(globalData.records, bytesRead * sizeof(record_t));
        if (!globalData.records) {
            fprintf(stderr, "Memory reallocation failed during deserialization\n");
            return;
        }

        memcpy(globalData.records, buffer, bytesRead * sizeof(record_t));
        globalData.numRecords = bytesRead;
