    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_RECORDS) {
        printf("Max records reached. Consider removing old records.\n");
        pthread_mutex_unlock(&list->lock);
        return -1; // Max size exceeded
    }

    UserRecord *new_record = malloc(sizeof(UserRecord));
    if (!new_record) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation error
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->status = status;

    list->records[list->count++] = new_record;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int update_record(RecordList *list, size_t id, long new_offset, int new_key, unsigned char required_status) {
    if (id >= MAX_RECORDS || id >= list->count) {
        printf("Invalid ID.\n");
        return -1; // Invalid ID
    }

    pthread_mutex_lock(&list->lock);

    UserRecord *record = list->records[id];
    if (record->status != required_status) {
        printf("Update condition not met. Status mismatch.\n");
        pthread_mutex_unlock(&list->lock);
        return -2; // Condition not met
    }

    record->offset = new_offset;
    record->key = new_key;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int delete_record(RecordList *list, size_t id) {
    if (id >= MAX_RECORDS || id >= list->count) {
        printf("Invalid ID.\n");
        return -1; // Invalid ID
    }

    pthread_mutex_lock(&list->lock);

    UserRecord *record = list->records[id];
    free(record);
    for (size_t i = id; i < list->count - 1; ++i) {
        list->records[i] = list->records[i + 1];
    }
    list->records[--list->count] = NULL;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void cleanup_record_list(RecordList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }
    pthread_mutex_destroy(&list->lock);
}

int main() {
    RecordList record_list;
    initialize_record_list(&record_list);

    add_record(&record_list, 100L, 1, 1);
    update_record(&record_list, 0, 200L, 2, 1); // Only updates if status is 1
    delete_record(&record_list, 0);

    cleanup_record_list(&record_list);
    return 0;
}
