void log_event(const char* eventType, const char* description) {
    pthread_mutex_lock(&lock);
    LogEntry *entry = malloc(sizeof(LogEntry));
    time_t now;
    time(&now);
    entry->timestamp = now;
    strncpy(entry->eventType, eventType, sizeof(entry->eventType)-1);
    strncpy(entry->description, description, sizeof(entry->description)-1);
    entry->next = NULL;

    static LogEntry *logHead = NULL;
    if (logHead == NULL) {
        logHead = entry;
    } else {
        LogEntry *current = logHead;
        while (current->next != NULL) current = current->next;
        current->next = entry;
    }
    pthread_mutex_unlock(&lock);
}

