        log_event("Error", "Memory limit exceeded.");
        return -1;
    }

    // Allocate and initialize memory for each structure
    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) goto error;

    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) goto cleanup_offsets;

    *records = malloc(size * sizeof(Record*));
    if (*records == NULL) goto cleanup_keys;
    for (int i = 0; i < size; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) goto cleanup_records;
    }

    *timestamps = malloc(size * sizeof(double));
    if (*timestamps == NULL) goto cleanup_all_records;

    *identifiers = malloc(size * sizeof(char*));
    if (*identifiers == NULL) goto cleanup_timestamps;
    for (int i = 0; i < size; ++i) {
        (*identifiers)[i] = malloc(128);
        if ((*identifiers)[i] == NULL) goto cleanup_identifiers;
    }

    *points = malloc(size * sizeof(Point*));
    if (*points == NULL) goto cleanup_all_identifiers;
    for (int i = 0; i < size; ++i) {
        (*points)[i] = malloc(sizeof(Point));
        if ((*points)[i] == NULL) goto cleanup_points;
    }

    *events = malloc(size * sizeof(Event*));
    if (*events == NULL) goto cleanup_all_points;
    for (int i = 0; i < size; ++i) {
        (*events)[i] = malloc(sizeof(Event));
        if ((*events)[i] == NULL) goto cleanup_events;
    }

    *metadata = malloc(sizeof(Metadata));
    if (*metadata == NULL) goto cleanup_all_events;

    // Initialize history
    *history = NULL;
    for (int i = 0; i < size; ++i) {
