    }
    free(*points); *points = NULL;
cleanup_points:
cleanup_all_points:
    for (int i = 0; i < size; ++i) {
        if ((*events)[i] != NULL) free((*events)[i]);
    }
    free(*events); *events = NULL;
cleanup_events:
cleanup_all_events:
    free(*metadata); *metadata = NULL;

    log_event("Error", "Memory allocation failed.");
    return -1;
}

void release_resources() {
    pthread_mutex_lock(&lock);

    // Free all global resources
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) for (int i = 0; i < totalRecords; ++i) if (records[i]) free(records[i]);
    if (timestamps) free(timestamps);
    if (identifiers) for (int i = 0; i < totalEvents; ++i) if (identifiers[i]) free(identifiers[i]);
    if (points) for (int i = 0; i < totalRecords; ++i) if (points[i]) free(points[i]);
    if (events) for (int i = 0; i < totalEvents; ++i) if (events[i]) free(events[i]);
    if (metadata) free(metadata);

    // Free history log
    LogEntry *current = logHead;
    while (current != NULL) {
        LogEntry *next = current->next;
        free(current);
        current = next;
    }
    logHead = NULL;

    totalRecords = 0;
    totalEvents = 0;

    pthread_mutex_unlock(&lock);
}

char* serialize_data_to_file(void *data, size_t size, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_event("Error", "Failed to open file for serialization.");
        return NULL;
    }

    fwrite(data, 1, size, file);
    fclose(file);

    // Return a status message
    char* msg = malloc(100 * sizeof(char));
    sprintf(msg, "Data serialized to %s.", filename);
    log_event("Info", msg);
    free(msg);

    return NULL;  // Return NULL if success (no error)
}

void* deserialize_data_from_file(const char* filename, size_t *size) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_event("Error", "Failed to open file for deserialization.");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    fseek(file, 0, SEEK_SET);

    void* data = malloc(*size);
    if (data == NULL) {
        log_event("Error", "Failed to allocate memory for deserialization.");
        fclose(file);
        return NULL;
    }

    fread(data, 1, *size, file);
    fclose(file);

    log_event("Info", "Data deserialized successfully.");

    return data;
}

int main() {
    // Example usage
    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;
    double *timestamps = NULL;
    char **identifiers = NULL;
    Point **points = NULL;
    Event **events = NULL;
    Metadata *metadata = NULL;
    LogEntry *history = NULL;

    if (allocate_structures(10, &offsets, &keys, &records, &timestamps,
                            &identifiers, &points, &events, &metadata, &history) != 0) {
        fprintf(stderr, "Allocation failed\n");
    }

    // Perform operations...

    release_resources();
    return 0;
}
