    static int *keys = NULL;
    static record *records = NULL;

    static size_t num_elements = 0;
    static size_t capacity_offsets = INITIAL_SIZE;
    static size_t capacity_keys = INITIAL_SIZE;
    static size_t capacity_records = INITIAL_SIZE;

    if (!offsets || !keys || !records) {
        initialize_arrays(&offsets, &keys, INITIAL_SIZE);
        records = malloc(INITIAL_SIZE * sizeof(record));
        if (!records) {
