unsigned long hash_function(const char *str, size_t size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % size;
}

HashTable* create_hash_table(time_t inactive_threshold) {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(INITIAL_SIZE, sizeof(HashTableNode *));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->size = INITIAL_SIZE;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    ht->inactive_threshold = inactive_threshold;

    return ht;
}

void purge_inactive_devices(HashTable *ht) {
    time_t now = time(NULL);
    for (size_t i = 0; i < ht->size; ++i) {
        HashTableNode *current = ht->table[i];
        while (current) {
            HashTableNode *to_delete = NULL;
            if ((now - current->device_state.last_update) > ht->inactive_threshold) {
                to_delete = current;
                current = current->next;
                // Assume free_device_state is implemented
                free(to_delete);
                --ht->count;
            } else {
                current = current->next;
            }
        }
    }
}

void resize_hash_table(HashTable *ht, size_t new_size) {
    HashTableNode **new_table = calloc(new_size, sizeof(HashTableNode *));
    if (!new_table) return;

    for (size_t i = 0; i < ht->size; ++i) {
        HashTableNode *node = ht->table[i];
        while (node) {
            unsigned long new_index = hash_function(node->device_state.device_id, new_size);
            HashTableNode *next_node = node->next;

            node->next = new_table[new_index];
            new_table[new_index] = node;

            node = next_node;
        }
    }

    free(ht->table);
    ht->table = new_table;
    ht->size = new_size;
}

void add_or_update_device(HashTable *ht, DeviceState *state) {
    pthread_mutex_lock(&ht->lock);

    if (ht->count >= MAX_TABLE_SIZE) {
        resize_hash_table(ht, ht->size * 2);
    }

    unsigned long index = hash_function(state->device_id, ht->size);
    HashTableNode *node = ht->table[index];

    while (node) {
        if (strcmp(node->device_state.device_id, state->device_id) == 0) {
            node->device_state.last_update = time(NULL);
            node->device_state.operational_status = state->operational_status;
            node->device_state.failure_count = state->failure_count;
            // Assume update_configuration is implemented
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        node = node->next;
    }

    HashTableNode *new_node = malloc(sizeof(HashTableNode));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        return; // Handle error appropriately.
    }

    new_node->device_state = *state;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;

    ++ht->count;
    pthread_mutex_unlock(&ht->lock);
}

DeviceState* get_device(HashTable *ht, const char *device_id) {
    unsigned long index = hash_function(device_id, ht->size);
    HashTableNode *node = ht->table[index];

    while (node) {
        if (strcmp(node->device_state.device_id, device_id) == 0) {
            return &node->device_state;
        }
        node = node->next;
    }

    return NULL; // Device not found
}

// Assume implementation for freeing a DeviceState
void free_device_state(HashTableNode *node);

// Function to periodically purge inactive devices
void* purge_inactive_thread(void *arg) {
    HashTable *ht = (HashTable*) arg;

    while (1) {
        sleep(60); // Purge every 60 seconds

        pthread_mutex_lock(&ht->lock);
        purge_inactive_devices(ht);
        pthread_mutex_unlock(&ht->lock);
    }

    return NULL;
}

// Function to create and start the purging thread
void start_purge_thread(HashTable *ht) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, purge_inactive_thread, ht)) {
        perror("Failed to create purge thread");
    }
}
