#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 1000

typedef struct {
    char mac_address[18];
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} ConfigList;

// Function prototypes
void init_config_list(ConfigList* list);
int add_configuration(ConfigList* list, NetworkConfig* config);
NetworkConfig* get_configuration(ConfigList* list, const char* mac_address);
int serialize_to_file(const char* filename, ConfigList* list);
int deserialize_from_file(const char* filename, ConfigList* list);
void free_config_list(ConfigList* list);

// Initialize the configuration list
void init_config_list(ConfigList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new configuration to the list
int add_configuration(ConfigList* list, NetworkConfig* config) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_CONFIGS) {
        printf("Memory limit reached. Cannot add more configurations.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Check for unique MAC address
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->config.mac_address, config->mac_address) == 0) {
            printf("MAC address already exists.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current = current->next;
    }

    // Allocate new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Copy configuration data
    memcpy(&(new_node->config), config, sizeof(NetworkConfig));

    // Insert at head
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Retrieve a configuration by MAC address
NetworkConfig* get_configuration(ConfigList* list, const char* mac_address) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->config.mac_address, mac_address) == 0) {
            NetworkConfig* config = &current->config;
            pthread_mutex_unlock(&list->lock);
            return config;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Serialize the configuration list to a file
int serialize_to_file(const char* filename, ConfigList* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    fwrite(&(list->count), sizeof(int), 1, file);
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->config), sizeof(NetworkConfig), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

// Deserialize the configuration list from a file
int deserialize_from_file(const char* filename, ConfigList* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Clear existing configurations
    free_config_list(list);

    int count;
    fread(&count, sizeof(int), 1, file);
    list->count = count;

    while (count-- > 0) {
        NetworkConfig config;
        fread(&config, sizeof(NetworkConfig), 1, file);

        add_configuration(list, &config);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

// Free the configuration list
void free_config_list(ConfigList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    ConfigList config_list;
    init_config_list(&config_list);

    // Example usage
    NetworkConfig config1 = {"00:11:22:33:44:55", "192.168.1.2", "255.255.255.0", "192.168.1.1"};
    add_configuration(&config_list, &config1);

    serialize_to_file("configurations.dat", &config_list);
    free_config_list(&config_list);
    init_config_list(&config_list);
    deserialize_from_file("configurations.dat", &config_list);

    free_config_list(&config_list);
    return 0;
}
