// Definitions for sensor_info struct, enum sensor_status, and other constants
typedef struct {
    int id;
    char name[50];
    double average_temperature;
} sensor_info;

enum sensor_status { ONLINE, OFFLINE };

const char* predefined_sensor_names[] = {"SensorA", "SensorB", "SensorC"};
const size_t num_predefined_names = sizeof(predefined_sensor_names) / sizeof(predefined_sensor_names[0]);
const int id_range_min = 100;
const int id_range_max = 999;

// Global error flag and mutex for thread safety
static volatile int memory_allocation_error = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void manage_memory(size_t timestamp_limit, size_t num_sensors) {
    long *timestamps = NULL;
    float *temperatures = NULL;
    sensor_info *sensors = NULL;
    enum sensor_status *statuses = NULL;
    char **event_logs = NULL;

    // Allocate memory with error checking
    pthread_mutex_lock(&lock);
    timestamps = (long *)aligned_alloc(64, timestamp_limit * sizeof(long));
    if (!timestamps) goto cleanup;

    temperatures = (float *)malloc(timestamp_limit * sizeof(float));
    if (!temperatures) goto cleanup;

    sensors = (sensor_info *)calloc(num_sensors, sizeof(sensor_info));
    if (!sensors) goto cleanup;

    statuses = (enum sensor_status *)malloc(num_sensors * sizeof(enum sensor_status));
    if (!statuses) goto cleanup;

    event_logs = (char **)malloc(num_sensors * sizeof(char *));
    if (!event_logs) goto cleanup;

    pthread_mutex_unlock(&lock);

    // Initialize timestamps with sequential values
    time_t current_time = time(NULL);
    for (size_t i = 0; i < timestamp_limit; ++i) {
        timestamps[i] = current_time + i;
    }

    // Initialize temperatures with random values
    srand(time(NULL));
    for (size_t i = 0; i < timestamp_limit; ++i) {
        temperatures[i] = -50.0f + ((float)(rand() % 171)); // 120 - (-50)
    }

    // Initialize sensor_info structures and statuses
    for (size_t i = 0; i < num_sensors; ++i) {
        sensors[i].id = id_range_min + rand() % (id_range_max - id_range_min + 1);

        int name_index = rand() % num_predefined_names;
        strncpy(sensors[i].name, predefined_sensor_names[name_index], sizeof(sensors[i].name));
        sensors[i].name[sizeof(sensors[i].name) - 1] = '\0';

        double sum_temperature = 0.0;
        for (int j = i * 5; j < (i + 1) * 5 && j < timestamp_limit; ++j) {
            sum_temperature += temperatures[j];
        }
        sensors[i].average_temperature = sum_temperature / ((i + 1) * 5 > timestamp_limit ? timestamp_limit % 5 : 5);

        statuses[i] = (rand() % 2 == 0) ? ONLINE : OFFLINE;
    }

    // Initialize event logs
    const char* predefined_messages[] = {"Initialization complete", "Sensor online", "Error encountered"};
    for (size_t i = 0; i < num_sensors; ++i) {
        size_t message_length = 200;
        event_logs[i] = (char *)malloc(message_length);
        if (!event_logs[i]) goto cleanup;

        int msg_index = rand() % (sizeof(predefined_messages) / sizeof(predefined_messages[0]));
        strncpy(event_logs[i], predefined_messages[msg_index], message_length - 1);

        char random_part[20];
        for (size_t j = strlen(event_logs[i]); j < message_length - 10; ++j) {
            if ((rand() % 2) == 0)
                event_logs[i][j] = 'A' + (rand() % 26); // Random letter
            else
                event_logs[i][j] = '0' + (rand() % 10); // Random digit
        }
        event_logs[i][message_length - 1] = '\0'; // Null-terminate
    }

    return; // Successful execution

cleanup:
    memory_allocation_error = 1;
    if (timestamps) free(timestamps);
    if (temperatures) free(temperatures);
    if (sensors) free(sensors);
    if (statuses) free(statuses);
    for (size_t i = 0; i < num_sensors && event_logs[i]; ++i) {
        if (event_logs[i]) free(event_logs[i]);
    }
    if (event_logs) free(event_logs);

    pthread_mutex_unlock(&lock);
}

int main() {
    manage_memory(100, 5);
    // Use the allocated data structures here
    // ...
    return 0;
}
