['Below is a C implementation that addresses the described requirements for managing `UserSession` structures. The solution includes dynamic list management, persistence to disk, session expiration handling, and thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char sessionID[32];
    char userIP[16];
    time_t startTime;
    time_t expirationTime;
} UserSession;

typedef struct Node {
    UserSession data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SessionList;

void initSessionList(SessionList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

UserSession* createSession(const char* sessionID, const char* userIP, time_t expirationTime) {
    UserSession* newSession = (UserSession*)malloc(sizeof(UserSession));
    strncpy(newSession->sessionID, sessionID, sizeof(newSession->sessionID) - 1);
    strncpy(newSession->userIP, userIP, sizeof(newSession->userIP) - 1);
    newSession->startTime = time(NULL);
    newSession->expirationTime = expirationTime;
    return newSession;
}

void addSession(SessionList* list, UserSession* session) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *session;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

void removeExpiredSessions(SessionList* list) {
    pthread_mutex_lock(&list->lock);

    Node **curr = &list->head;
    while (*curr != NULL) {
        if (time(NULL) > (*curr)->data.expirationTime) {
            Node *expiredNode = *curr;
            *curr = expiredNode->next;
            free(expiredNode);
        } else {
            curr = &(*curr)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void listActiveSessions(SessionList* list, time_t startTimeWindow, time_t endTimeWindow) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.startTime >= startTimeWindow && current->data.expirationTime <= endTimeWindow) {
            printf("Session ID: %s, IP: %s\n", current->data.sessionID, current->data.userIP);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void saveSessionsToDisk(SessionList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "w");
    if (!file) return;

    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "%s,%s,%ld,%ld\n", current->data.sessionID, current->data.userIP,
                current->data.startTime, current->data.expirationTime);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void loadSessionsFromDisk(SessionList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "r");
    if (!file) return;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        UserSession session;
        sscanf(line, "%31[^,],%15[^,],%ld,%ld", session.sessionID, session.userIP,
               &session.startTime, &session.expirationTime);

        addSession(list, &session);
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void freeSessions(SessionList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *nextNode = current->next;
        free(current);
        current = nextNode;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

void cleanup(SessionList* list) {
    removeExpiredSessions(list);
    saveSessionsToDisk(list, "sessions.dat");
    freeSessions(list);
    pthread_mutex_destroy(&list->lock);
}
```

### Key Points:
- **Thread Safety**: Mutex locks ensure safe concurrent access.
- **Dynamic List Management**: Uses a linked list for session management.
- **Persistence**: Sessions are saved to and loaded from disk in CSV format.
- **Efficiency**: Regularly removes expired sessions to manage memory.
- **Configurability**: Can be adapted to different persistence mechanisms by modifying the `saveSessionsToDisk` and `loadSessionsFromDisk` functions.']

