int* create_structures(size_t num_offsets, size_t num_keys, size_t num_records,
                       int** keys_array, record*** records_array,
                       long*** offset_values) {

    // Calculate the total required memory
    size_t total_size = 
        sizeof(long) * num_offsets +
        sizeof(int) * num_keys +
        sizeof(record) * num_records;

    if (total_size > MAX_MEMORY_USAGE) {
        log_message(LOG_LEVEL_INFO, "Memory usage exceeds system limit.");
        return NULL;
    }

    // Allocate memory for offsets
    *offset_values = malloc(sizeof(long) * num_offsets);
    if (!*offset_values) {
        log_message(LOG_LEVEL_INFO, "Failed to allocate memory for offset values");
        return NULL;
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offset_values)[i] = rand() % (RANDOM_VALUE_MAX - RANDOM_VALUE_MIN + 1) + RANDOM_VALUE_MIN;
    }

    // Allocate memory for keys
    *keys_array = malloc(sizeof(int) * num_keys);
    if (!*keys_array) {
        log_message(LOG_LEVEL_INFO, "Failed to allocate memory for keys");
        free(*offset_values);
        return NULL;
    }

    // Initialize keys with random values within a range
    for (size_t i = 0; i < num_keys; ++i) {
        (*keys_array)[i] = rand() % (RANDOM_VALUE_MAX - RANDOM_VALUE_MIN + 1) + RANDOM_VALUE_MIN;
    }

    // Allocate memory for records
    *records_array = malloc(sizeof(record) * num_records);
    if (!*records_array) {
        log_message(LOG_LEVEL_INFO, "Failed to allocate memory for records");
        free(*offset_values);
        free(*keys_array);
        return NULL;
    }

    // Initialize each record with a random value and log the process
    for (size_t i = 0; i < num_records; ++i) {
        (*records_array)[i].value = rand() % (RANDOM_VALUE_MAX - RANDOM_VALUE_MIN + 1) + RANDOM_VALUE_MIN;
