        snprintf(log_msg, sizeof(log_msg), "Record created with value: %d", (*records_array)[i].value);
        log_message(LOG_LEVEL_DEBUG, "%s", log_msg);
    }

    return (int*)1; // Return success
}

void free_structures(long** offset_values, int* keys_array, record** records_array) {
    if (offset_values && *offset_values) {
        free(*offset_values);
    }
    if (keys_array) {
        free(keys_array);
    }
    if (records_array && *records_array) {
        free(*records_array);
    }
}

