```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <pthread.h>
#include <openssl/evp.h>

typedef struct {
    int network_timeout;
    int logging_verbosity;
} Config;

typedef struct {
    int status_code;
    u_char ip_address[16]; // Maximum size for IPv6 address
    unsigned char hashed_password[EVP_MAX_MD_SIZE];
} Result;

#define DNS_RETRIES 3
#define MAX_DNS_RETRY_DELAY 1

pthread_mutex_t dns_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_event(int verbosity, const char* message) {
    if (verbosity > 0) {
        printf("%s\n", message);
    }
}

int get_dns_status_code() {
    return h_errno;
}

unsigned char *hash_password(const unsigned char *password, size_t password_len, unsigned int *hashed_length) {
    EVP_MD_CTX *mdctx;
    const EVP_MD *md;
    unsigned char *result;
    unsigned int len;

    if (!(md = EVP_get_digestbyname("SHA256"))) {
        fprintf(stderr, "Unknown message digest SHA256\n");
        exit(1);
    }

    mdctx = EVP_MD_CTX_new();
    if (!mdctx) {
        perror("EVP_MD_CTX_new");
        exit(1);
    }

    if (1 != EVP_DigestInit_ex(mdctx, md, NULL)) {
        fprintf(stderr, "EVP_DigestInit_ex failed\n");
        exit(1);
    }

    if (1 != EVP_DigestUpdate(mdctx, password, password_len)) {
        fprintf(stderr, "EVP_DigestUpdate failed\n");
        exit(1);
    }

    result = malloc(EVP_MAX_MD_SIZE);
    if (!result) {
        perror("malloc");
        exit(1);
    }

    if (1 != EVP_DigestFinal_ex(mdctx, result, &len)) {
        fprintf(stderr, "EVP_DigestFinal_ex failed\n");
        exit(1);
    }
    *hashed_length = len;

    EVP_MD_CTX_free(mdctx);

    return result;
}

Result resolveAndHash(const char* hostname, size_t ip_address_len, const char* password, Config config) {
    Result res;
    struct addrinfo hints, *resolv_result, *ptr;
    int status;
    unsigned char *hashed_password;
    unsigned int hashed_length;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for (int attempt = 0; attempt < DNS_RETRIES; ++attempt) {
        pthread_mutex_lock(&dns_mutex);
        if ((status = getaddrinfo(hostname, NULL, &hints, &resolv_result)) == 0) {
            for (ptr = resolv_result; ptr != NULL; ptr = ptr->ai_next) {
                void *addr;
                char ipstr[INET6_ADDRSTRLEN];

                if (ptr->ai_family == AF_INET) { // IPv4
                    struct sockaddr_in *ipv4 = (struct sockaddr_in *)ptr->ai_addr;
                    addr = &(ipv4->sin_addr);
                } else { // IPv6
                    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)ptr->ai_addr;
                    addr = &(ipv6->sin6_addr);
                }

                inet_ntop(ptr->ai_family, addr, ipstr, sizeof(ipstr));
                log_event(config.logging_verbosity, "Resolved IP: ");
                log_event(config.logging_verbosity, ipstr);

                if (inet_pton(ptr->ai_family, ipstr, res.ip_address) > 0) {
                    pthread_mutex_unlock(&dns_mutex);
                    freeaddrinfo(resolv_result);
                    res.status_code = 0;
                    hashed_password = hash_password((unsigned char *)password, strlen(password), &hashed_length);
                    memcpy(res.hashed_password, hashed_password, hashed_length);
                    free(hashed_password);
                    return res;
                }
            }
        } else {
            log_event(config.logging_verbosity, "DNS resolution failed");
        }

        pthread_mutex_unlock(&dns_mutex);

        if (attempt < DNS_RETRIES - 1) {
            sleep(MAX_DNS_RETRY_DELAY);
        }
    }

    freeaddrinfo(resolv_result);
    res.status_code = get_dns_status_code();
    memset(res.hashed_password, 0, EVP_MAX_MD_SIZE); // Ensure the hashed password is empty on failure

    return res;
}
```

### Key Considerations:

1. **Concurrency and Thread Safety**: The function uses a mutex (`pthread_mutex_t`) to ensure thread-safe access when performing DNS resolution.

2. **Retry Mechanism**: It retries DNS resolution up to three times with a one-second delay if it fails initially.

3. **Logging**: Logs events based on the verbosity level provided in the configuration struct.

4. **Password Hashing**: Utilizes OpenSSL's SHA-256 for hashing the password securely.

5. **Resource Management**: Uses dynamic memory allocation and ensures proper cleanup to manage resources efficiently.

This code is designed with considerations for large-scale deployment scenarios, balancing DNS resolution latency, network reliability, and resource usage constraints.']

