// Function to generate a random Gaussian-distributed value
float gaussian_random(float mean, float stddev) {
    static double oldU = 0.0;
    double u, v, S;

    if (oldU == 0.0)
        u = (double)rand() / RAND_MAX;
    else 
        u = oldU;

    v = (double)rand() / RAND_MAX;
    S = u * u + v * v;

    while(S >= 1.0 || S == 0) {
        if(oldU == 0.0)
            u = (double)rand() / RAND_MAX;
        else
            u = oldU;

        v = (double)rand() / RAND_MAX;
        S = u * u + v * v;
    }

    double gauss = sqrt(-2.0 * log(S) / S) * v;
    oldU = u;

    return mean + stddev * gauss;
}

int initializeReports(size_t numReports, size_t numDataPointsPerReport, Report** reports) {
    if (!reports || !(*reports)) {
        return -1; // Invalid argument
    }

    *reports = malloc(numReports * sizeof(Report));
    if (*reports == NULL) {
        return -2; // Memory allocation failure
    }

    for (size_t i = 0; i < numReports; ++i) {
        (*reports)[i].numDataPoints = numDataPointsPerReport;
        (*reports)[i].dataPoints = malloc(numDataPointsPerReport * sizeof(DataPoint));
        if ((*reports)[i].dataPoints == NULL) {
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free((*reports)[j].dataPoints);
            }
            free(*reports);
            *reports = NULL;
            return -3; // Memory allocation failure during initialization of DataPoint array
