            (*reports)[i].dataPoints[j].i = (int)(gaussian_random(mean, stddev));
            (*reports)[i].dataPoints[j].f = gaussian_random(mean, stddev);
        }
    }

    return 0; // Success
}

void freeReports(Report* reports, size_t numReports) {
    if (!reports) {
        return;
    }

    for (size_t i = 0; i < numReports; ++i) {
        if (reports[i].dataPoints != NULL) {
            free(reports[i].dataPoints);
        }
    }

    free(reports);
}

