} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t count;
    pthread_mutex_t lock;
    time_t expiration_threshold;  // e.g., packets older than this are expired
} PacketManager;

// Forward declarations for helper functions
static int find_packet_index(PacketManager *manager, const char *packet_id);
static void purge_expired_packets(PacketManager *manager);

PacketManager* create_packet_manager(time_t expiration_threshold) {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->packets = (DataPacket**)calloc(MAX_PACKETS, sizeof(DataPacket*));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->expiration_threshold = expiration_threshold;

    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->packets[i]) {
                free(manager->packets[i]->packet_id);
                free(manager->packets[i]);
            }
        }
        free(manager->packets);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_packet(PacketManager *manager, const char *packet_id) {
    pthread_mutex_lock(&manager->lock);

    if (find_packet_index(manager, packet_id) != -1) {
        pthread_mutex_unlock(&manager->lock);
        return 0; // Packet already exists
    }

    DataPacket *new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    new_packet->packet_id = strdup(packet_id);
    new_packet->timestamp = time(NULL);
    new_packet->status = PACKET_NEW;

    if (manager->count < MAX_PACKETS) {
        manager->packets[manager->count++] = new_packet;
        pthread_mutex_unlock(&manager->lock);
        return 1; // Success
    }

    free(new_packet->packet_id);
    free(new_packet);
    pthread_mutex_unlock(&manager->lock);
    return 0; // No space for new packet
}

int update_packet(PacketManager *manager, const char *packet_id) {
    pthread_mutex_lock(&manager->lock);

    int index = find_packet_index(manager, packet_id);
    if (index == -1) {
        pthread_mutex_unlock(&manager->lock);
        return 0; // Packet not found
    }

    manager->packets[index]->timestamp = time(NULL); // Update timestamp or other attributes
    manager->packets[index]->status = PACKET_ACTIVE;
    pthread_mutex_unlock(&manager->lock);
    return 1; // Success
}

DataPacket* get_packet(PacketManager *manager, const char *packet_id) {
    pthread_mutex_lock(&manager->lock);

    int index = find_packet_index(manager, packet_id);
    DataPacket *result = (index != -1) ? manager->packets[index] : NULL;

    pthread_mutex_unlock(&manager->lock);
    return result;
}

void purge_expired_packets(PacketManager *manager) {
    time_t now = time(NULL);

    for (size_t i = 0; i < manager->count;) {
        if (now - manager->packets[i]->timestamp > manager->expiration_threshold) {
            DataPacket *expired_packet = manager->packets[i];

            // Log expiration
            printf("Purging expired packet ID: %s\n", expired_packet->packet_id);

            free(expired_packet->packet_id);
            free(expired_packet);

            manager->packets[i] = manager->packets[--manager->count];

            if (i < manager->count) {
                // Re-check the same index since it's now occupied by a previous packet
            }
        } else {
            ++i;
        }
    }
}

void manage_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    purge_expired_packets(manager);

    // Simulate integration with external data source and logging service

    pthread_mutex_unlock(&manager->lock);
}

static int find_packet_index(PacketManager *manager, const char *packet_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->packets[i]->packet_id, packet_id) == 0) {
            return i;
        }
    }
    return -1;
}

