    if (add_packet(manager, "packet1")) {
        printf("Packet added successfully.\n");
    }

    manage_packets(manager);

    DataPacket *retrieved_packet = get_packet(manager, "packet1");
    if (retrieved_packet) {
        printf("Retrieved packet ID: %s\n", retrieved_packet->packet_id);
    } else {
        printf("Packet not found.\n");
    }

    destroy_packet_manager(manager);

    return 0;
}
