#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct NetworkNode {
    int id;
    int status; // Assume some predefined status codes
    struct NetworkNode** connections;
    size_t connection_count;
} NetworkNode;

typedef struct NodeMap {
    NetworkNode* nodes[MAX_NODES];
    pthread_mutex_t lock;
} NodeMap;

// Function prototypes
NetworkNode* create_node(int id);
void add_connection(NetworkNode* node, NetworkNode* target);
void remove_connection(NetworkNode* node, int target_id);
NetworkNode* get_node(NodeMap* map, int id);
void update_node_status(NetworkNode* node, int new_status);
void free_node(NetworkNode* node);

// Create a new network node
NetworkNode* create_node(int id) {
    NetworkNode* node = malloc(sizeof(NetworkNode));
    if (!node) return NULL;
    node->id = id;
    node->status = 0; // Default status
    node->connections = malloc(MAX_NODES * sizeof(NetworkNode*));
    node->connection_count = 0;
    return node;
}

// Add a connection to another node
void add_connection(NetworkNode* node, NetworkNode* target) {
    if (node->connection_count < MAX_NODES) {
        node->connections[node->connection_count++] = target;
    }
}

// Remove a connection by id
void remove_connection(NetworkNode* node, int target_id) {
    for (size_t i = 0; i < node->connection_count; ++i) {
        if (node->connections[i]->id == target_id) {
            memmove(&node->connections[i], &node->connections[i + 1],
                    (node->connection_count - i - 1) * sizeof(NetworkNode*));
            --node->connection_count;
            break;
        }
    }
}

// Get a node by id from the map
NetworkNode* get_node(NodeMap* map, int id) {
    pthread_mutex_lock(&map->lock);
    for (int i = 0; i < MAX_NODES; ++i) {
        if (map->nodes[i] && map->nodes[i]->id == id) {
            NetworkNode* node = map->nodes[i];
            pthread_mutex_unlock(&map->lock);
            return node;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}

// Update the status of a node
void update_node_status(NetworkNode* node, int new_status) {
    pthread_mutex_lock(&(node ? &pthread_self() : 0)); // Locking for thread safety
    if (node) {
        node->status = new_status;
    }
    pthread_mutex_unlock(&(node ? &pthread_self() : 0));
}

// Free a network node and its connections
void free_node(NetworkNode* node) {
    if (!node) return;
    for (size_t i = 0; i < node->connection_count; ++i) {
        free(node->connections[i]);
    }
    free(node->connections);
    free(node);
}

// Initialize the node map with locks
void init_node_map(NodeMap* map) {
    memset(map, 0, sizeof(NodeMap));
    pthread_mutex_init(&map->lock, NULL);
}

// Deallocate resources for node map
void destroy_node_map(NodeMap* map) {
    pthread_mutex_lock(&map->lock);
    for (int i = 0; i < MAX_NODES; ++i) {
        if (map->nodes[i]) {
            free_node(map->nodes[i]);
        }
    }
    pthread_mutex_unlock(&map->lock);
    pthread_mutex_destroy(&map->lock);
}

// API function to add a node
void add_node(NodeMap* map, int id) {
    pthread_mutex_lock(&map->lock);
    if (get_node(map, id)) {
        printf("Node with ID %d already exists.\n", id);
        pthread_mutex_unlock(&map->lock);
        return;
    }
    NetworkNode* node = create_node(id);
    map->nodes[id % MAX_NODES] = node; // Simple hash function
    pthread_mutex_unlock(&map->lock);
}

// API function to remove a node
void remove_node(NodeMap* map, int id) {
    pthread_mutex_lock(&map->lock);
    NetworkNode* node = get_node(map, id);
    if (node) {
        free_node(node);
        map->nodes[id % MAX_NODES] = NULL;
    }
    pthread_mutex_unlock(&map->lock);
}

// Randomly initialize an array of records
void init_random_records(int* records, size_t count, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i] = rand() % (max - min + 1) + min;
    }
}

int main() {
    NodeMap map;
    init_node_map(&map);

    // Example usage
    add_node(&map, 1);
    add_node(&map, 2);

    NetworkNode* node1 = get_node(&map, 1);
    NetworkNode* node2 = get_node(&map, 2);
