// Utility function to modify file extensions
function modifyFileExtension(filename) {
    const baseName = filename.replace(/\.[^/.]+$/, ""); // Remove original extension
    const digitsCount = baseName.length % 10 + 1; // Example logic for number of digits
    return `${baseName}-${new Array(digitsCount).fill('X').join('')}.js`;
}

// Caching mechanism
class Cache {
    constructor(ttl) {
        this.ttl = ttl;
        this.store = new Map();
    }

    get(key) {
        const item = this.store.get(key);
        if (!item || Date.now() > item.expiry) {
            this.store.delete(key);
            return null;
        }
        return item.value;
    }

    set(key, value) {
        const expiry = Date.now() + this.ttl;
        this.store.set(key, { value, expiry });
    }
}

// Logging utility
class Logger {
    constructor(remoteStorageUrl) {
        this.logs = [];
        this.remoteStorageUrl = remoteStorageUrl;
    }

    log(message) {
        const timestamp = new Date().toISOString();
        const logEntry = `${timestamp} - ${message}`;
        console.log(logEntry);
        this.logs.push(logEntry);

        // Store logs locally
        localStorage.setItem('executionLogs', JSON.stringify(this.logs));

        // Optionally send logs to remote storage
        fetch(this.remoteStorageUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ timestamp, message })
        }).catch(error => console.error('Failed to log remotely:', error));
    }
}

// Main utility function for loading and executing scripts
async function loadAndExecuteScripts(fileNames) {
    const cache = new Cache(60000); // 60 seconds TTL
    const logger = new Logger('https://example.com/logs');
    const maxConcurrentRequests = 5;
    let activeRequests = 0;

    async function fetchFileMetadata(fileName) {
        try {
            const cachedData = cache.get(fileName);
            if (cachedData) return cachedData;

            await sleep(100); // Backoff strategy
            const response = await fetch(`https://api.example.com/files/${fileName}`);
            if (!response.ok) throw new Error('Network response was not ok');

            const data = await response.json();
            cache.set(fileName, data);
            return data;
        } catch (error) {
            logger.log(`Failed to fetch metadata for ${fileName}: ${error.message}`);
            return null;
        }
    }

    async function loadScript(src) {
        try {
            const script = document.createElement('script');
            script.src = src;
            document.head.appendChild(script);
            await new Promise(resolve => script.onload = resolve);
            logger.log(`Successfully loaded and executed ${src}`);
        } catch (error) {
            logger.log(`Failed to execute ${src}: ${error.message}`);
        }
    }

    async function processFiles() {
        for (const fileName of fileNames) {
            while (activeRequests >= maxConcurrentRequests) await new Promise(resolve => setTimeout(resolve, 100));

            activeRequests++;
            const modifiedFileName = modifyFileExtension(fileName);
            const metadata = await fetchFileMetadata(modifiedFileName);

            if (!metadata || !metadata.active || new Date(metadata.lastModified) < new Date()) {
                logger.log(`Skipping ${modifiedFileName}, not valid or outdated`);
                activeRequests--;
                continue;
            }

            loadScript(`/path/to/scripts/${modifiedFileName}`);
        }
    }

    processFiles().then(() => logger.log('All files processed'));
}

// Helper function for exponential backoff
function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Periodically check for updates
setInterval(async () => {
    const fileNames = ['file1.js', 'file2.js', 'file3.js']; // Example filenames
    await loadAndExecuteScripts(fileNames);
}, 60000); // Check every minute

```

