        free_memory(reports, num_reports, floats, keys);
        return EXIT_FAILURE;
    }

    // Write output data to file
    if (write_output_data(argv[2], &reports, num_reports) != 0) {
        fprintf(stderr, "Failed to write output data\n");
    }

    // Clean up resources
    free_memory(reports, num_reports, floats, keys);
    cache_evict(cache);

    return EXIT_SUCCESS;
}

// Function implementations

int generate_reports(report ***reports, size_t num_reports, double **floats, short **keys) {
    if (num_reports == 0) {
        *reports = NULL;
        return 0;
    }

    *reports = malloc(num_reports * sizeof(report *));
    if (*reports == NULL) {
        fprintf(stderr, "Memory allocation failed for reports\n");
        return -1;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < num_reports; ++i) {
        report *report = generate_report(10); // Example size
        if (!report) {
            fprintf(stderr, "Memory allocation failed for data points\n");
            free_memory(*reports, i, NULL, NULL);
            return -1;
        }

        (*reports)[i] = report;

        pthread_mutex_lock(&lock);
        cache_insert(cache, report); // Insert into cache
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    *floats = malloc(num_reports * sizeof(double));
    if (*floats == NULL) {
        fprintf(stderr, "Memory allocation failed for floats\n");
        free_memory(*reports, num_reports, NULL, keys);
        return -1;
    }

    *keys = malloc(num_reports * sizeof(short));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free_memory(*reports, num_reports, floats, NULL);
        return -1;
    }

    // Example initialization
    for (size_t i = 0; i < num_reports; ++i) {
        (*floats)[i] = gaussian_random();
        (*keys)[i] = (short)i;
    }

    return 0;
}

void free_memory(report **reports, size_t num_reports, double *floats, short *keys) {
    for (size_t i = 0; i < num_reports; ++i) {
        free(reports[i]->points);
        free(reports[i]);
    }
    free(reports);
    if (floats) free(floats);
    if (keys) free(keys);
}

double gaussian_random() {
    // Placeholder for Gaussian distribution generator
    return ((double)rand() / RAND_MAX - 0.5) * 2;
}

report *generate_report(size_t count) {
    report *r = malloc(sizeof(report));
    if (!r) return NULL;

    r->points = malloc(count * sizeof(data_point));
    if (!r->points) {
        free(r);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        r->points[i].s = (short)(rand() % 100);
        r->points[i].i = rand();
        r->points[i].f = (float)gaussian_random();
    }
    r->count = count;

    return r;
}

cache_node* initialize_cache() {
    cache_node *node = malloc(sizeof(cache_node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for cache\n");
        exit(EXIT_FAILURE);
    }

    node->head = NULL;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void cache_insert(cache_node *node, report *report) {
    pthread_mutex_lock(&node->lock);

    if (node->head == NULL || node->head->next == NULL) {
        cache_entry *entry = malloc(sizeof(cache_entry));
        entry->report = report;
        entry->next = node->head;
        node->head = entry;
    } else {
        cache_evict(node); // Evict oldest entry
        cache_entry *entry = malloc(sizeof(cache_entry));
        entry->report = report;
        entry->next = node->head;
        node->head = entry;
    }

    pthread_mutex_unlock(&node->lock);
}

report *cache_lookup(cache_node *node, size_t index) {
    pthread_mutex_lock(&node->lock);

    cache_entry *current = node->head;
    for (size_t i = 0; current != NULL && i < index; ++i) {
        current = current->next;
    }

    report *result = (current != NULL) ? current->report : NULL;

    pthread_mutex_unlock(&node->lock);
    return result;
}

void cache_evict(cache_node *node) {
    if (!node->head || !node->head->next) return;

    cache_entry *entry_to_remove = node->head;
    node->head = node->head->next;
    free(entry_to_remove->report->points);
    free(entry_to_remove->report);
    free(entry_to_remove);

    // Keep the cache size within limits
    while (node->head && node->head->next) {
        entry_to_remove = node->head->next;
        node->head->next = entry_to_remove->next;
        free(entry_to_remove->report->points);
        free(entry_to_remove->report);
        free(entry_to_remove);
    }
}

int read_input_data(const char *filename, double **floats, short **keys) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    size_t num_elements;
    fscanf(file, "%zu", &num_elements);

    *floats = malloc(num_elements * sizeof(double));
    if (*floats == NULL) {
        fclose(file);
        return -1;
    }

    *keys = malloc(num_elements * sizeof(short));
    if (*keys == NULL) {
        free(*floats);
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        fscanf(file, "%lf", &(*floats)[i]);
        fscanf(file, "%hd", &(*keys)[i]);
    }

    fclose(file);

    return 0;
}

int write_output_data(const char *filename, report ***reports, size_t num_reports) {
    FILE *file = fopen(filename, "w");
    if (!file) return -1;

    for (size_t i = 0; i < num_reports; ++i) {
        fprintf(file, "%zu ", (*reports)[i]->count);
        for (size_t j = 0; j < (*reports)[i]->count; ++j) {
            fprintf(file, "(%hd, %d, %.2f) ",
                    (*reports)[i]->points[j].s,
                    (*reports)[i]->points[j].i,
                    (*reports)[i]->points[j].f);
        }
        fputc('\n', file);
    }

    fclose(file);

    return 0;
}
