public class DisjointPairsProcessor {
    private static final Logger logger = Logger.getLogger(DisjointPairsProcessor.class.getName());

    public static void main(String[] args) {
        int[] inputArray = {1, 2, 3, 4, 5, 6};
        try {
            boolean result = processDisjointPairs(inputArray);
            System.out.println("Verification Result: " + result);
        } catch (Exception e) {
            System.err.println("Error processing disjoint pairs: " + e.getMessage());
        }
    }

    public static boolean processDisjointPairs(int[] array) throws IOException, InterruptedException {
        int attempts = 0;
        while (attempts < 3) {
            try {
                long startTime = System.currentTimeMillis();
                List<int[]> disjointPairs = findDisjointPairs(array);
                long endTime = System.currentTimeMillis();

                if (verifyWithExternalService(disjointPairs)) {
                    logMetrics(startTime, endTime, attempts);
                    return true;
                } else {
                    array = getRandomizedSubset(array);
                    attempts++;
                }
            } catch (OutOfMemoryError e) {
                logger.log(Level.SEVERE, "Out of memory error encountered", e);
                Thread.sleep(1000); // Wait before retrying
            }
        }
        throw new RuntimeException("Failed to verify disjoint pairs after 3 attempts");
    }

    private static List<int[]> findDisjointPairs(int[] array) throws InterruptedException {
        int numCores = Runtime.getRuntime().availableProcessors();
        ExecutorService executor = Executors.newFixedThreadPool(numCores);
        UnionFind uf = new UnionFind(array.length);

        long unionFindStartTime = System.currentTimeMillis();

        for (int i = 0; i < array.length - 1; i++) {
            executor.submit(() -> {
                if (!uf.connected(i, i + 1)) {
                    uf.union(i, i + 1);
                }
            });
        }

        executor.shutdown();
        try {
            executor.awaitTermination(60, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        long unionFindEndTime = System.currentTimeMillis();

        List<int[]> disjointPairs = new ArrayList<>();
        for (int i = 0; i < array.length - 1; i++) {
            if (!uf.connected(i, i + 1)) {
                disjointPairs.add(new int[]{array[i], array[i + 1]});
            }
        }

        logger.log(Level.INFO, "Union-Find operations took: " + (unionFindEndTime - unionFindStartTime) + " ms");

        return disjointPairs;
    }

    private static boolean verifyWithExternalService(List<int[]> pairs) {
        // Simulate external service call
        Random random = new Random();
        return random.nextBoolean(); // Replace with actual service verification logic
    }

    private static void logMetrics(long startTime, long endTime, int attempts) throws IOException {
        Map<String, Object> metrics = new HashMap<>();
        metrics.put("totalExecutionTime", endTime - startTime);
        metrics.put("attempts", attempts);

        try (FileWriter writer = new FileWriter("execution_metrics.json")) {
            writer.write(new Gson().toJson(metrics));
        }
    }

    private static int[] getRandomizedSubset(int[] array) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < array.length; i++) {
            indices.add(i);
        }
        Collections.shuffle(indices);

        int subsetSize = Math.min(array.length / 2, 100); // Limit subset size
        int[] subset = new int[subsetSize];
        for (int i = 0; i < subsetSize; i++) {
            subset[i] = array[indices.get(i)];
        }

        return subset;
    }
}

class UnionFind {
    private final int[] parent;
    private final int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]);
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP != rootQ) {
            if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }

    public boolean connected(int p, int q) {
        return find(p) == find(q);
    }
}
