        iValue = static_cast<int>(normalDist(generator));
        fValue = static_cast<float>(normalDist(generator));
    }
};

struct AttackLog {
    DataPoint* dataPoints;
    size_t numDataPoints;

    AttackLog(size_t numPoints) : numDataPoints(numPoints), dataPoints(nullptr) {}

    ~AttackLog() { delete[] dataPoints; }

    bool initializeData(std::mt19937& generator, std::normal_distribution<float>& normalDist) {
        try {
            dataPoints = new DataPoint[numDataPoints];
        } catch (const std::bad_alloc&) {
            return false;
        }

        for (size_t i = 0; i < numDataPoints; ++i) {
            dataPoints[i].populate(generator, normalDist);
        }

        return true;
    }
};

