#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkNode {
    int id;
    char *connectedNodes; // Comma-separated list of node IDs
    int networkHealth;   // 0 for healthy, non-zero for different status levels
} NetworkNode;

typedef struct NodeList {
    NetworkNode *nodes;
    size_t count;
    pthread_mutex_t lock;
} NodeList;

void logOperation(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

NetworkNode* createNode(int id, const char *connections, int health) {
    NetworkNode *node = malloc(sizeof(NetworkNode));
    if (!node) return NULL;

    node->id = id;
    node->connectedNodes = strdup(connections ? connections : "");
    node->networkHealth = health;

    logOperation("Created new node.");
    return node;
}

void freeNode(NetworkNode *node) {
    if (node) {
        free(node->connectedNodes);
        free(node);
        logOperation("Freed a node.");
    }
}

int addNode(NodeList *list, int id, const char *connections, int health) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->nodes[i].id == id) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Node already exists
        }
    }

    NetworkNode *node = createNode(id, connections, health);
    if (!node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    list->nodes = realloc(list->nodes, sizeof(NetworkNode) * (list->count + 1));
    if (!list->nodes) {
        freeNode(node);
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory reallocation failed
    }

    list->nodes[list->count++] = *node;
    pthread_mutex_unlock(&list->lock);
    logOperation("Added new node to the network.");
    return 0; // Success
}

NetworkNode* getNode(NodeList *list, int id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->nodes[i].id == id) {
            NetworkNode *nodeCopy = createNode(list->nodes[i].id, list->nodes[i].connectedNodes, list->nodes[i].networkHealth);
            pthread_mutex_unlock(&list->lock);
            return nodeCopy;
        }
    }

    pthread_mutex_unlock(&list->lock);
    logOperation("Searched for a node.");
    return NULL; // Node not found
}

int updateConnections(NodeList *list, int id, const char *newConnections) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->nodes[i].id == id) {
            free(list->nodes[i].connectedNodes);
            list->nodes[i].connectedNodes = strdup(newConnections ? newConnections : "");

            pthread_mutex_unlock(&list->lock);
            logOperation("Updated node connections.");
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Node not found
}

