#define MAX_STRUCTS 10000

typedef struct {
    int enodeb_id;
    char gummei[6]; // Assumed size for GUMMEI string, adjust as needed.
    int plmn_count;
    int *plmn_ids; // Dynamic list of PLMN_IDs
} LTE_ENBCONTEXT_CONFIGURE_REQUEST_T;

typedef struct {
    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T* structures[MAX_STRUCTS];
    size_t count;
    pthread_mutex_t lock;
} ENBContextList;

// Function prototypes
int validate_gummei(const char *gummei);
ENBContextList* create_enb_context_list();
void destroy_enb_context_list(ENBContextList *list);
int add_structure(ENBContextList *list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *structure);
LTE_ENBCONTEXT_CONFIGURE_REQUEST_T* get_structure(ENBContextList *list, size_t index);
void remove_structure(ENBContextList *list, size_t index);

// Function implementations
int validate_gummei(const char *gummei) {
    // Basic validation logic for GUMMEI, modify as needed.
    return strlen(gummei) == 5 && gummei[2] == ':';
}

ENBContextList* create_enb_context_list() {
    ENBContextList *list = (ENBContextList *)malloc(sizeof(ENBContextList));
    if (!list) {
        perror("Failed to allocate memory for ENB context list");
        return NULL;
    }
    memset(list, 0, sizeof(ENBContextList));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_enb_context_list(ENBContextList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->structures[i]->plmn_ids);
        free(list->structures[i]);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_structure(ENBContextList *list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *structure) {
    if (!validate_gummei(structure->gummei)) {
        fprintf(stderr, "Invalid GUMMEI: %s\n", structure->gummei);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTS) {
        fprintf(stderr, "Reached maximum capacity of ENB context list.\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    int *plmn_ids = (int *)malloc(structure->plmn_count * sizeof(int));
    if (!plmn_ids) {
        perror("Failed to allocate memory for PLMN IDs");
        pthread_mutex_unlock(&list->lock);
        return -3;
    }
    memcpy(plmn_ids, structure->plmn_ids, structure->plmn_count * sizeof(int));

    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *new_struct = (LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *)malloc(sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T));
    if (!new_struct) {
        perror("Failed to allocate memory for new structure");
        free(plmn_ids);
        pthread_mutex_unlock(&list->lock);
        return -4;
    }

    *new_struct = *structure;
    new_struct->plmn_ids = plmn_ids;

    list->structures[list->count++] = new_struct;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

LTE_ENBCONTEXT_CONFIGURE_REQUEST_T* get_structure(ENBContextList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);
    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *structure = list->structures[index];
    pthread_mutex_unlock(&list->lock);

    return structure;
}

void remove_structure(ENBContextList *list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    free(list->structures[index]->plmn_ids);
    free(list->structures[index]);
    memmove(&list->structures[index], &list->structures[index + 1], (list->count - index - 1) * sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *));
    list->count--;
    pthread_mutex_unlock(&list->lock);
}
