void load_crypto_primitives() {
    // Register algorithms using OpenSSL functions
    EVP_add_cipher(&evp_aes_128_cbc);
    EVP_add_digest(&evp_md5);
    EVP_add_cipher(&evp_camellia_128_ecb);
