    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

DataPacket* find_packet_by_id(int id) {
    pthread_mutex_lock(&packets_mutex);
    DataPacket *packet = NULL;
    for (int i = 0; i < packet_count; ++i) {
        if (packets[i]->id == id) {
            packet = packets[i];
            break;
        }
    }
    pthread_mutex_unlock(&packets_mutex);
    return packet;
}

void purge_expired_packets() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&packets_mutex);
    for (int i = 0; i < packet_count; ++i) {
        if ((current_time - packets[i]->timestamp) > expiration_threshold) {
            free(packets[i]);
            memmove(&packets[i], &packets[i + 1], (packet_count - i - 1) * sizeof(DataPacket *));
            --packet_count;
            --i; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&packets_mutex);
}

void add_packet(int id, int status) {
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (!new_packet) {
        log_message("Failed to allocate memory for new packet.");
        return;
    }

    new_packet->id = id;
    new_packet->timestamp = time(NULL);
    new_packet->status = status;

    pthread_mutex_lock(&packets_mutex);
    if (packet_count < MAX_PACKETS) {
        packets[packet_count++] = new_packet;
    } else {
        free(new_packet);
        log_message("Packet limit reached.");
    }
    pthread_mutex_unlock(&packets_mutex);

    purge_expired_packets();
}

void update_packet_status(int id, int status) {
    DataPacket *packet = find_packet_by_id(id);
    if (packet != NULL) {
        packet->status = status;
        log_message("Updated packet status.");
    } else {
        log_message("Packet not found for updating.");
    }
}

DataPacket* retrieve_packet(int id) {
