                free(chunk.memory);

                int configValidation = validateConfig(configPath, schema);
                if (configValidation != 0) {
                    apiResponse.status_code = -2;
                    free(response_data);
                } else {
                    apiResponse.response_data = response_data;
                    apiResponse.status_code = 0; // Success
                }
            } else {
                apiResponse.status_code = -3; // Memory allocation failure
            }
        }

        curl_easy_cleanup(curl_handle);
    } else {
        apiResponse.status_code = -4; // Failed to initialize CURL
    }

    curl_global_cleanup();
    return apiResponse;
}
