#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    int* keyPtr;
} Record;

// Function to manage memory for data structures and initialize them
int dynamicMemoryManagement(size_t offsetsSize, long** offsetArray, int** keysArray, Record*** recordsArray) {
    if (offsetsSize == 0 || !offsetArray || !keysArray || !recordsArray) return -1;

    // Allocate and initialize the offsets array
    *offsetArray = (long*)malloc(offsetsSize * sizeof(long));
    if (*offsetArray == NULL) return -2;
    for (size_t i = 0; i < offsetsSize; ++i) {
        (*offsetArray)[i] = 0;
    }

    // Calculate the size of the keys array
    size_t keysSize = offsetsSize / 2;

    // Allocate and initialize the keys array
    *keysArray = (int*)malloc(keysSize * sizeof(int));
    if (*keysArray == NULL) {
        free(*offsetArray);
        return -3;
    }
    for (size_t i = 0; i < keysSize; ++i) {
        (*keysArray)[i] = i;
    }

    // Allocate and initialize the records array
    *recordsArray = (Record**)malloc(offsetsSize * sizeof(Record*));
    if (*recordsArray == NULL) {
        free(*offsetArray);
        free(*keysArray);
        return -4;
    }
    for (size_t i = 0; i < offsetsSize; ++i) {
        (*recordsArray)[i] = (Record*)malloc(sizeof(Record));
        if ((*recordsArray)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free((*recordsArray)[j]);
            free(*offsetArray);
            free(*keysArray);
            free(*recordsArray);
            return -5;
        }
        (*recordsArray)[i]->value = rand() % 201 - 100; // Random value between -100 and 100
        if (i < keysSize) {
            (*recordsArray)[i]->keyPtr = &((*keysArray)[i]);
        } else {
            (*recordsArray)[i]->keyPtr = NULL;
        }
    }

    return 0; // Success
}

// Function to free all allocated memory
void freeAllocatedMemory(long* offsetArray, int* keysArray, Record** recordsArray, size_t offsetsSize) {
    if (offsetArray != NULL) free(offsetArray);
    if (keysArray != NULL) free(keysArray);
    if (recordsArray != NULL) {
        for (size_t i = 0; i < offsetsSize; ++i) {
            if (recordsArray[i] != NULL) free(recordsArray[i]);
        }
        free(recordsArray);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t offsetsSize = 10;
    long* offsetArray = NULL;
    int* keysArray = NULL;
    Record** recordsArray = NULL;

    if (dynamicMemoryManagement(offsetsSize, &offsetArray, &keysArray, &recordsArray) == 0) {
        // Memory management was successful
        for (size_t i = 0; i < offsetsSize; ++i) {
            printf("Record %zu: Value = %d, Key = %d\n",
                   i, recordsArray[i]->value, recordsArray[i]->keyPtr ? *recordsArray[i]->keyPtr : -1);
        }
    } else {
        fprintf(stderr, "Memory management failed.\n");
    }

    // Free the allocated memory
    freeAllocatedMemory(offsetArray, keysArray, recordsArray, offsetsSize);

    return 0;
}
