// Structure to hold algorithm information
typedef struct {
    char *name;
    void *(*init)(void);
    void (*release)(void *);
    int usage_count;
} Algorithm;

// Node for linked list of algorithms
typedef struct AlgorithmNode {
    Algorithm algo;
    struct AlgorithmNode *next;
} AlgorithmNode;

// Global variables for algorithm management
AlgorithmNode *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize an algorithm (dummy implementation)
void *hash_init(void) { return malloc(1); }
void hash_release(void *ptr) { free(ptr); }

void *cipher_init(void) { return malloc(1); }
void cipher_release(void *ptr) { free(ptr); }

// Function to add a new algorithm
AlgorithmNode* add_algorithm(char *name, void *(*init)(void), void (*release)(void *)) {
    AlgorithmNode *new_node = (AlgorithmNode *)malloc(sizeof(AlgorithmNode));
    if (!new_node) return NULL;

    new_node->algo.name = strdup(name);
    new_node->algo.init = init;
    new_node->algo.release = release;
    new_node->algo.usage_count = 0;
    new_node->next = NULL;

    pthread_mutex_lock(&lock);

    // Append to the list
    if (!head) {
        head = new_node;
    } else {
        AlgorithmNode *current = head;
        while (current->next) current = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&lock);
    return new_node;
}

// Function to get an algorithm by name
Algorithm* get_algorithm(char *name) {
    pthread_mutex_lock(&lock);

    AlgorithmNode *current = head;
    while (current) {
        if (strcmp(current->algo.name, name) == 0) {
            current->algo.usage_count++;
            pthread_mutex_unlock(&lock);
            return &current->algo;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to initialize and lazily load algorithms
void initialize_algorithms() {
    add_algorithm("SHA256", hash_init, hash_release);
    add_algorithm("AES128", cipher_init, cipher_release);
}

// Monitoring function to print usage statistics
void monitor_usage(void) {
    pthread_mutex_lock(&lock);

    AlgorithmNode *current = head;
    while (current) {
        printf("Algorithm: %s, Usage Count: %d\n", current->algo.name, current->algo.usage_count);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Main function to demonstrate usage
int main() {
    initialize_algorithms();

    Algorithm *algo1 = get_algorithm("SHA256");
    if (algo1) algo1->init(NULL); // Simulate initialization

    Algorithm *algo2 = get_algorithm("AES128");
    if (algo2) algo2->init(NULL);

    monitor_usage();

    // Clean up
    pthread_mutex_destroy(&lock);
    return 0;
}
