#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

// Define constants for password policy
#define MIN_PASSWORD_LENGTH 8
#define PASSWORD_HISTORY_LIMIT 5

typedef struct {
    char* identifier;
    char* name;
    char* email;
    char** previous_passwords;
    int num_previous_passwords;
    time_t last_active;
} UserProfile;

typedef struct {
    UserProfile** profiles;
    size_t count;
    pthread_mutex_t lock;
} UserProfileManager;

// Function prototypes
int add_or_update_profile(UserProfileManager* manager, UserProfile* profile);
UserProfile* get_profile_by_identifier(UserProfileManager* manager, const char* identifier);
void purge_inactive_profiles(UserProfileManager* manager, time_t inactivity_threshold);
int is_password_valid(const char* password, char** previous_passwords, int num_previous_passwords);
int update_user_password_in_db(const char* identifier, const char* new_password);

// Implementation
int add_or_update_profile(UserProfileManager* manager, UserProfile* profile) {
    pthread_mutex_lock(&manager->lock);

    // Find existing profile by identifier or create a new one if not found
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->profiles[i]->identifier, profile->identifier) == 0) {
            free(manager->profiles[i]->name);
            free(manager->profiles[i]->email);
            free(manager->profiles[i]->identifier);

            manager->profiles[i]->name = strdup(profile->name);
            manager->profiles[i]->email = strdup(profile->email);
            manager->profiles[i]->identifier = strdup(profile->identifier);
            manager->profiles[i]->last_active = time(NULL);

            // Password update logic
            if (is_password_valid(profile->password, manager->profiles[i]->previous_passwords,
                                  manager->profiles[i]->num_previous_passwords)) {
                // Shift passwords in history and add new password
                for (int j = manager->profiles[i]->num_previous_passwords; j > 0; --j) {
                    manager->profiles[i]->previous_passwords[j] = manager->profiles[i]->previous_passwords[j - 1];
                }
                char* new_pwd_copy = strdup(profile->password);
                manager->profiles[i]->previous_passwords[0] = new_pwd_copy;
                if (manager->profiles[i]->num_previous_passwords < PASSWORD_HISTORY_LIMIT) {
                    ++manager->profiles[i]->num_previous_passwords;
                }

                // Update password in database
                update_user_password_in_db(manager->profiles[i]->identifier, profile->password);
            } else {
                printf("Password validation failed.\n");
            }
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    // Add new profile if not found
    UserProfile** new_profiles = realloc(manager->profiles, (manager->count + 1) * sizeof(UserProfile*));
    if (!new_profiles) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }
    manager->profiles = new_profiles;
    manager->profiles[manager->count] = profile;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

UserProfile* get_profile_by_identifier(UserProfileManager* manager, const char* identifier) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->profiles[i]->identifier, identifier) == 0) {
            UserProfile* profile_copy = malloc(sizeof(UserProfile));
            *profile_copy = *(manager->profiles[i]);
            pthread_mutex_unlock(&manager->lock);
            return profile_copy;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Profile not found
}

void purge_inactive_profiles(UserProfileManager* manager, time_t inactivity_threshold) {
    pthread_mutex_lock(&manager->lock);

    size_t active_count = 0;
    UserProfile** active_profiles = malloc(manager->count * sizeof(UserProfile*));

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(time(NULL), manager->profiles[i]->last_active) <= inactivity_threshold) {
            active_profiles[active_count++] = manager->profiles[i];
        } else {
            // Free resources of inactive profiles
            free(manager->profiles[i]->identifier);
            free(manager->profiles[i]->name);
            free(manager->profiles[i]->email);
            for (int j = 0; j < manager->profiles[i]->num_previous_passwords; ++j) {
                free(manager->profiles[i]->previous_passwords[j]);
            }
            free(manager->profiles[i]->previous_passwords);
        }
    }

    // Reallocate active profiles array
    if (active_count != manager->count) {
        manager->profiles = realloc(active_profiles, active_count * sizeof(UserProfile*));
        manager->count = active_count;
    } else {
        free(active_profiles); // No change in size needed
    }

    pthread_mutex_unlock(&manager->lock);
}

int is_password_valid(const char* password, char** previous_passwords, int num_previous_passwords) {
    if (strlen(password) < MIN_PASSWORD_LENGTH) return 0;

    int has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;
    for (size_t i = 0; password[i] != '\0'; ++i) {
        if (password[i] >= 'A' && password[i] <= 'Z') has_upper = 1;
        else if (password[i] >= 'a' && password[i] <= 'z') has_lower = 1;
        else if (password[i] >= '0' && password[i] <= '9') has_digit = 1;
        else has_special = 1;
    }

    if (!(has_upper && has_lower && has_digit && has_special)) return 0;

    for (int i = 0; i < num_previous_passwords; ++i) {
        if (strcmp(password, previous_passwords[i]) == 0) return 0;
    }
    return 1;
}

int update_user_password_in_db(const char* identifier, const char* new_password) {
    // Placeholder for database update logic
    printf("Updating password in DB for %s\n", identifier);
    return 0; // Success
}

// Example usage
int main() {
    UserProfileManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

    UserProfile* profile1 = malloc(sizeof(UserProfile));
    profile1->identifier = strdup("user123");
    profile1->name = strdup("John Doe");
    profile1->email = strdup("john@example.com");
    profile1->previous_passwords = malloc(PASSWORD_HISTORY_LIMIT * sizeof(char*));
    profile1->num_previous_passwords = 0;
    profile1->last_active = time(NULL);

    add_or_update_profile(&manager, profile1);

    UserProfile* retrieved_profile = get_profile_by_identifier(&manager, "user123");
    if (retrieved_profile) {
        printf("Retrieved: %s\n", retrieved_profile->name);
        free(retrieved_profile->identifier);
        free(retrieved_profile->name);
        free(retrieved_profile->email);
        for (int i = 0; i < retrieved_profile->num_previous_passwords; ++i) {
            free(retrieved_profile->previous_passwords[i]);
        }
        free(retrieved_profile->previous_passwords);
        free(retrieved_profile);
    }

    purge_inactive_profiles(&manager, 30 * 24 * 60 * 60); // Example: 30 days inactivity threshold

    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.profiles[i]->identifier);
        free(manager.profiles[i]->name);
        free(manager.profiles[i]->email);
        for (int j = 0; j < manager.profiles[i]->num_previous_passwords; ++j) {
            free(manager.profiles[i]->previous_passwords[j]);
        }
        free(manager.profiles[i]->previous_passwords);
        free(manager.profiles[i]);
    }

    free(manager.profiles);
    return 0;
}
