// Mock NetworkServiceManager interface
class NetworkServiceManager {
public:
    virtual bool start_service(const std::string& name) = 0;
    virtual void stop_service(const std::string& name) = 0;
};

class MockNetworkServiceManager : public NetworkServiceManager {
private:
    bool success_;
public:
    MockNetworkServiceManager(bool success) : success_(success) {}
    bool start_service(const std::string&) override {
        return success_;
    }
    void stop_service(const std::string&) override {}
