#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
} record_t;

typedef struct MemoryBlock {
    size_t size;
    void *ptr;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock *memory_pool = NULL;

// Custom memory allocator
void* custom_alloc(size_t size) {
    MemoryBlock **current = &memory_pool;

    while (*current) {
        if ((*current)->size >= size) {
            void *result = (*current)->ptr;
            (*current)->ptr += size;
            (*current)->size -= size;

            if ((*current)->size == 0) { // Free the block entirely
                MemoryBlock *temp = *current;
                *current = (*current)->next;
                free(temp);
            }

            return result;
        }
        current = &(*current)->next;
    }

    void *new_block = malloc(size + sizeof(MemoryBlock));
    if (!new_block) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    MemoryBlock *block = (MemoryBlock *)new_block;
    block->size = size;
    block->ptr = new_block + sizeof(MemoryBlock);
    block->next = NULL;

    *current = block;

    return block->ptr;
}

void custom_free(void *ptr) {
    // Custom free is not implemented, as memory blocks are managed by the allocator's design
    // This function can be expanded to implement a more complex freeing strategy if needed.
}

// Dynamic array structure
typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t capacity;
} DynamicArray;

void initialize_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->offsets = (long *)custom_alloc(initial_capacity * sizeof(long));
    array->keys = (int *)custom_alloc(initial_capacity * sizeof(int));
    array->records = (record_t *)custom_alloc(initial_capacity * sizeof(record_t));

    memset(array->offsets, 0, initial_capacity * sizeof(long));
    memset(array->keys, 0, initial_capacity * sizeof(int));
    for (size_t i = 0; i < initial_capacity; ++i) {
        array->records[i].value = 0;
    }
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    if (new_capacity > MAX_RECORDS) {
        fprintf(stderr, "Exceeded maximum record capacity\n");
        return;
    }

    long *new_offsets = (long *)custom_alloc(new_capacity * sizeof(long));
    int *new_keys = (int *)custom_alloc(new_capacity * sizeof(int));
    record_t *new_records = (record_t *)custom_alloc(new_capacity * sizeof(record_t));

    size_t old_capacity = array->capacity;
    memcpy(new_offsets, array->offsets, old_capacity * sizeof(long));
    memcpy(new_keys, array->keys, old_capacity * sizeof(int));
    memcpy(new_records, array->records, old_capacity * sizeof(record_t));

    custom_free(array->offsets);
    custom_free(array->keys);
    custom_free(array->records);

    array->offsets = new_offsets;
    array->keys = new_keys;
    array->records = new_records;
    array->capacity = new_capacity;

    memset(new_offsets + old_capacity, 0, (new_capacity - old_capacity) * sizeof(long));
    memset(new_keys + old_capacity, 0, (new_capacity - old_capacity) * sizeof(int));
    for (size_t i = old_capacity; i < new_capacity; ++i) {
        new_records[i].value = 0;
    }
}

void free_dynamic_array(DynamicArray *array) {
    custom_free(array->offsets);
    custom_free(array->keys);
    custom_free(array->records);
}

int main() {
    DynamicArray array;
    initialize_dynamic_array(&array, 10);

    // Example usage
    array.keys[0] = 1;
    array.records[0].value = 100;

    resize_dynamic_array(&array, 20);

    free_dynamic_array(&array);
    return 0;
}
