```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 1000

typedef struct NetworkNode {
    char id[256];
    int health_status;
    struct NetworkNode **connected_nodes;
    size_t connection_count;
    pthread_mutex_t lock;
} NetworkNode;

typedef struct {
    // Simulated structures
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
} PduList;

// Function declarations
NetworkNode* create_node(const char *id);
void destroy_node(NetworkNode *node);
int add_connection(NetworkNode *node, NetworkNode *target);
void update_health_status(NetworkNode *node, int status);
NetworkNode* get_node_by_id(NetworkNode **nodes, size_t count, const char *id);
void simulate_interference(PduList *list, size_t n);

// Implementations
NetworkNode* create_node(const char *id) {
    NetworkNode *node = (NetworkNode *)malloc(sizeof(NetworkNode));
    if (!node) return NULL;

    strncpy(node->id, id, sizeof(node->id) - 1);
    node->health_status = 100; // Assume full health initially
    node->connected_nodes = NULL;
    node->connection_count = 0;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void destroy_node(NetworkNode *node) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);
    for (size_t i = 0; i < node->connection_count; ++i) {
        free(node->connected_nodes[i]);
    }
    free(node->connected_nodes);
    pthread_mutex_unlock(&node->lock);

    pthread_mutex_destroy(&node->lock);
    free(node);
}

int add_connection(NetworkNode *node, NetworkNode *target) {
    if (!node || !target) return -1;

    pthread_mutex_lock(&node->lock);
    size_t new_count = node->connection_count + 1;
    node->connected_nodes = realloc(node->connected_nodes, new_count * sizeof(NetworkNode *));
    if (!node->connected_nodes) {
        pthread_mutex_unlock(&node->lock);
        return -1;
    }
    node->connected_nodes[node->connection_count++] = target;
    pthread_mutex_unlock(&node->lock);

    return 0;
}

void update_health_status(NetworkNode *node, int status) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);
    node->health_status = status;
    pthread_mutex_unlock(&node->lock);
}

NetworkNode* get_node_by_id(NetworkNode **nodes, size_t count, const char *id) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(nodes[i]->id, id) == 0) {
            return nodes[i];
        }
    }
    return NULL;
}

void simulate_interference(PduList *list, size_t n) {
    pthread_mutex_lock(&list->lock);

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        snprintf(list->pdus[i].RX_UE_INFORMATION_TAG, sizeof(list->pdus[i].RX_UE_INFORMATION_TAG), "Tag_%zu", i);
        list->pdus[i].RNTI = rand() % 1000;
        list->pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        list->pdus[i].CRCFLAG = (list->pdus[i].CRC_INDICATION_REL8_TAG & 1) ? 1 : 0; // Example CRC flag logic
    }

    list->count = n;
    pthread_mutex_unlock(&list->lock);
}

void free_pdu_list(PduList *list) {
    if (!list || !list->pdus) return;

    pthread_mutex_lock(&list->lock);
    free(list->pdus);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

int main() {
    // Example usage
    NetworkNode *nodes[MAX_NODES];
    for (size_t i = 0; i < MAX_NODES; ++i) {
        nodes[i] = create_node("Node_");
        snprintf(nodes[i]->id + strlen(nodes[i]->id), sizeof(nodes[i]->id) - strlen(nodes[i]->id), "%zu", i);
    }

    PduList pdu_list;
    pthread_mutex_init(&pdu_list.lock, NULL);

    simulate_interference(&pdu_list, 10);

    for (size_t i = 0; i < MAX_NODES; ++i) {
        destroy_node(nodes[i]);
    }

    free_pdu_list(&pdu_list);
    return 0;
}
```

### Key Points:
- **NetworkNode Structure**: Manages nodes with unique IDs, health status, and connections.
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe operations on nodes and PDU lists.
- **Memory Management**: Custom allocation and deallocation to prevent leaks.
- **Interference Simulation**: Generates interference patterns in a list of PDUs.
- **Error Handling**: Includes checks for memory allocation failures.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEY_LENGTH 256
#define HASH_TABLE_SIZE 1024
#define LOG_BUFFER_SIZE 4096

typedef struct {
    char key[MAX_KEY_LENGTH];
    char value[256]; // Adjust size as necessary.
    int version;
} Record;

typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char message[LOG_BUFFER_SIZE];
    struct LogEntry* next;
} LogEntry;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

LogEntry* log_head = NULL;

void log_message(LogLevel level, const char* format, ...) {
    pthread_mutex_lock(&log_mutex);

    va_list args;
    va_start(args, format);
    vsnprintf(log_head->message, LOG_BUFFER_SIZE, format, args);

    time(&log_head->timestamp);
    log_head->level = level;

    LogEntry* new_entry = malloc(sizeof(LogEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&log_mutex);
        return;
    }
    new_entry->next = log_head;
    log_head = new_entry;

    va_end(args);

    pthread_mutex_unlock(&log_mutex);
}

unsigned int hash_function(const char* key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % HASH_TABLE_SIZE;
}

typedef struct Bucket {
    Record* records;
    size_t count;
    pthread_mutex_t mutex;
} Bucket;

Bucket* create_buckets() {
    Bucket* buckets = calloc(HASH_TABLE_SIZE, sizeof(Bucket));
    if (!buckets) {
        log_message(ERROR, "Failed to allocate memory for hash table buckets.");
        return NULL;
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        buckets[i].records = malloc(sizeof(Record) * 16); // Initial size
        if (!buckets[i].records) {
            log_message(ERROR, "Failed to allocate memory for records in bucket %d.", i);
            free(buckets);
            return NULL;
        }
        buckets[i].count = 0;
        pthread_mutex_init(&buckets[i].mutex, NULL);
    }

    return buckets;
}

void destroy_buckets(Bucket* buckets) {
    if (!buckets) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        free(buckets[i].records);
        pthread_mutex_destroy(&buckets[i].mutex);
    }
    free(buckets);
}

void resize_bucket_if_needed(Bucket* bucket) {
    if (bucket->count >= 16) { // Threshold for resizing
        size_t new_size = 32;
        Record* new_records = realloc(bucket->records, sizeof(Record) * new_size);
        if (!new_records) {
            log_message(ERROR, "Failed to resize records array for a bucket.");
            return;
        }
        bucket->records = new_records;

        log_message(INFO, "Resized records array for a bucket.");
    }
}

void add_record(Bucket* buckets, const char* key, const char* value, int version) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&buckets[index].mutex);

    // Check if the record exists and update or insert accordingly
    for (size_t i = 0; i < buckets[index].count; ++i) {
        if (strcmp(buckets[index].records[i].key, key) == 0) {
            strcpy(buckets[index].records[i].value, value);
            buckets[index].records[i].version = version;
            log_message(INFO, "Updated record for key: %s", key);
            pthread_mutex_unlock(&buckets[index].mutex);
            return;
        }
    }

    // Insert new record
    if (buckets[index].count == 16) {
        resize_bucket_if_needed(&buckets[index]);
    }
    strcpy(buckets[index].records[buckets[index].count].key, key);
    strcpy(buckets[index].records[buckets[index].count].value, value);
    buckets[index].records[buckets[index].count].version = version;
    ++buckets[index].count;

    log_message(INFO, "Added new record for key: %s", key);

    pthread_mutex_unlock(&buckets[index].mutex);
}

Record* get_record(Bucket* buckets, const char* key, int min_version) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&buckets[index].mutex);

    for (size_t i = 0; i < buckets[index].count; ++i) {
        if (strcmp(buckets[index].records[i].key, key) == 0 && 
            buckets[index].records[i].version >= min_version) {
            Record* record = &buckets[index].records[i];
            pthread_mutex_unlock(&buckets[index].mutex);
            return record;
        }
    }

    pthread_mutex_unlock(&buckets[index].mutex);
    return NULL; // Not found or version too low
}

void invalidate_records(Bucket* buckets, int max_version) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&buckets[i].mutex);

        size_t valid_count = 0;
        for (size_t j = 0; j < buckets[i].count; ++j) {
            if (buckets[i].records[j].version <= max_version) {
                // Mark the record as invalid by setting version to -1
                buckets[i].records[j].version = -1;
            } else {
                if (valid_count != j) {
                    buckets[i].records[valid_count] = buckets[i].records[j];
                }
                ++valid_count;
            }
        }

        buckets[i].count = valid_count;
        log_message(INFO, "Invalidated outdated records in bucket %d", i);

        pthread_mutex_unlock(&buckets[i].mutex);
    }
}

void configure_and_manage_storage() {
    Bucket* buckets = create_buckets();
    if (!buckets) return;

    add_record(buckets, "exampleKey1", "value1", 1);
    Record* record = get_record(buckets, "exampleKey1", 0);
    if (record) {
        printf("Retrieved Record: %s:%d\n", record->key, record->version);
    }

    invalidate_records(buckets, 0);

    destroy_buckets(buckets);

    // Clean up log
    while (log_head) {
        LogEntry* to_free = log_head;
        log_head = log_head->next;
        free(to_free);
    }
}

int main() {
    configure_and_manage_storage();
    return 0;
}
