#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10000
#define MAX_SESSIONS 50000

typedef struct {
    int client_id;
    char connection_state[20];
    char *messages;
} SessionContext;

typedef struct {
    SessionContext **sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionPool;

void log_operation(const char *operation, int client_id) {
    time_t now = time(NULL);
    printf("[%s] %s: Client ID %d\n", ctime(&now), operation, client_id);
}

SessionPool* create_session_pool() {
    SessionPool *pool = malloc(sizeof(SessionPool));
    pool->sessions = calloc(INITIAL_CAPACITY, sizeof(SessionContext *));
    pool->count = 0;
    pool->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&pool->lock, NULL);
    log_operation("Created session pool", -1);
    return pool;
}

int find_session_index(SessionPool *pool, int client_id) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->sessions[i]->client_id == client_id)
            return i;
    }
    return -1;
}

void resize_pool_if_needed(SessionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity && pool->capacity < MAX_SESSIONS) {
        size_t new_capacity = pool->capacity * 2;
        SessionContext **new_sessions = realloc(pool->sessions, new_capacity * sizeof(SessionContext *));
        if (!new_sessions) {
            log_operation("Memory allocation failed during resize", -1);
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        memset(new_sessions + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(SessionContext *));
        pool->sessions = new_sessions;
        pool->capacity = new_capacity;
    }
    pthread_mutex_unlock(&pool->lock);
}

void add_session(SessionPool *pool, int client_id, const char *connection_state, const char *message) {
    pthread_mutex_lock(&pool->lock);

    if (find_session_index(pool, client_id) != -1) {
        log_operation("Duplicate Client ID", client_id);
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    resize_pool_if_needed(pool);

    SessionContext *session = malloc(sizeof(SessionContext));
    session->client_id = client_id;
    strncpy(session->connection_state, connection_state, sizeof(session->connection_state) - 1);
    session->messages = strdup(message); // In a real scenario, handle message list more robustly

    pool->sessions[pool->count++] = session;

    log_operation("Session created", client_id);

    pthread_mutex_unlock(&pool->lock);
}

void remove_inactive_sessions(SessionPool *pool) {
    time_t current_time = time(NULL);
    size_t i = 0;
    pthread_mutex_lock(&pool->lock);
    while (i < pool->count) {
        // Assuming a field 'last_active' exists, and checking it here
        // For this example, we simply free all sessions to simulate cleanup
        SessionContext *session = pool->sessions[i];
        free(session->messages);
        free(session);
        memmove(&pool->sessions[i], &pool->sessions[i + 1], (pool->count - i - 1) * sizeof(SessionContext *));
        pool->count--;
    }
    pthread_mutex_unlock(&pool->lock);

    log_operation("Inactive sessions cleaned up", -1);
}

void destroy_session_pool(SessionPool *pool) {
    remove_inactive_sessions(pool); // Clean up before destruction
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->sessions[i]) {
            free(pool->sessions[i]->messages);
            free(pool->sessions[i]);
        }
    }
    free(pool->sessions);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
    log_operation("Destroyed session pool", -1);
}

// Example function to demonstrate cleanup
void schedule_periodic_cleanup(SessionPool *pool) {
    // Placeholder for a real scheduling mechanism, like using timers or dedicated threads
    remove_inactive_sessions(pool);
}

