#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char eventType[256];
    int priority;
    uint64_t uniqueID;
} Event;

typedef struct {
    Event *events;
    size_t capacity;
    size_t count;
} EventCollection;

EventCollection* create_event_collection(size_t initial_capacity) {
    if (initial_capacity <= 0) return NULL;

    EventCollection *collection = malloc(sizeof(EventCollection));
    if (!collection) return NULL;

    collection->events = malloc(initial_capacity * sizeof(Event));
    if (!collection->events) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

int add_event(EventCollection *collection, time_t timestamp, const char *eventType, int priority, uint64_t uniqueID) {
    if (!collection || !eventType || strlen(eventType) >= sizeof(collection->events[0].eventType)) return -1;

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Event *new_events = realloc(collection->events, new_capacity * sizeof(Event));
        if (!new_events) return -1;

        collection->events = new_events;
        collection->capacity = new_capacity;
    }

    Event *event = &collection->events[collection->count++];
    event->timestamp = timestamp;
    strncpy(event->eventType, eventType, sizeof(event->eventType) - 1);
    event->priority = priority;
    event->uniqueID = uniqueID;

    return 0;
}

int remove_event(EventCollection *collection, uint64_t uniqueID) {
    if (!collection) return -1;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i].uniqueID == uniqueID) {
            memmove(&collection->events[i], &collection->events[i + 1],
                    (collection->count - i - 1) * sizeof(Event));
            --collection->count;
            return 0;
        }
    }

    return -1; // Event not found
}

int update_event(EventCollection *collection, uint64_t uniqueID, time_t timestamp, const char *eventType, int priority) {
    if (!collection || !eventType || strlen(eventType) >= sizeof(collection->events[0].eventType)) return -1;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i].uniqueID == uniqueID) {
            collection->events[i].timestamp = timestamp;
            strncpy(collection->events[i].eventType, eventType, sizeof(collection->events[i].eventType) - 1);
            collection->events[i].priority = priority;
            return 0;
        }
    }

    return -1; // Event not found
}

void sort_events_by_timestamp(EventCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count - 1; ++i) {
        for (size_t j = i + 1; j < collection->count; ++j) {
            if (collection->events[i].timestamp > collection->events[j].timestamp) {
                Event temp = collection->events[i];
                collection->events[i] = collection->events[j];
                collection->events[j] = temp;
            }
        }
    }
}

void free_event_collection(EventCollection *collection) {
    if (!collection) return;

    free(collection->events);
    free(collection);
}
