#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// Third-party library headers (placeholders)
// #include "third_party_logging.h"
// #include "third_party_random_generation.h"

typedef struct {
    char *key;
    long value;
    float *floatArray;
    size_t floatArraySize;
} Entry;

typedef struct {
    Entry **entries;
    size_t count;
    pthread_mutex_t mutex;
} Collection;

void log_message(const char *message) {
    // Placeholder for logging function
    printf("%s\n", message);
}

// Gaussian distribution random generator placeholder
float gaussian_random(float mean, float stddev) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    static double V1 = 0, V2;
    static int phase = 0;

    if (phase == 0) {
        double U1 = (double)rand() / RAND_MAX;
        double U2 = (double)rand() / RAND_MAX;
        V1 = sqrt(-2 * log(U1)) * cos(2 * M_PI * U2);
        V2 = sqrt(-2 * log(U1)) * sin(2 * M_PI * U2);
        phase = 1;
    } else {
        phase = 0;
    }

    pthread_mutex_unlock(&lock);
    return mean + stddev * V1;
}

int resize_float_array(float **array, size_t currentSize, size_t newSize) {
    float *newArray = realloc(*array, newSize * sizeof(float));
    if (!newArray) {
        log_message("Failed to allocate memory for resizing the float array.");
        return -1;
    }
    memset(newArray + currentSize, 0, (newSize - currentSize) * sizeof(float)); // Zero-initialize new elements
    *array = newArray;
    return 0;
}

Collection *init_collection(size_t entryCount) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) {
        log_message("Failed to allocate memory for collection.");
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    collection->entries = calloc(entryCount, sizeof(Entry *));
    if (!collection->entries) {
        log_message("Failed to allocate memory for entries.");
        free(collection);
        return NULL;
    }

    collection->count = entryCount;
    return collection;
}

int populate_entry(Entry *entry, const char *key, long value, size_t initialSize, float mean, float stddev) {
    if (!entry || !key) return -1;

    pthread_mutex_lock(&entry->mutex);

    entry->key = strdup(key);
    entry->value = value;
    entry->floatArraySize = initialSize;
    entry->floatArray = malloc(initialSize * sizeof(float));
    if (!entry->floatArray) {
        log_message("Failed to allocate memory for float array.");
        pthread_mutex_unlock(&entry->mutex);
        return -1;
    }

    for (size_t i = 0; i < initialSize; ++i) {
        entry->floatArray[i] = gaussian_random(mean, stddev);
    }

    pthread_mutex_unlock(&entry->mutex);
    log_message("Entry populated successfully.");
    return 0;
}

void free_entry(Entry *entry) {
    if (!entry) return;

    pthread_mutex_lock(&entry->mutex);

    free(entry->key);
    free(entry->floatArray);

    pthread_mutex_unlock(&entry->mutex);
}

void free_collection(Collection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]) {
            free_entry(collection->entries[i]);
            free(collection->entries[i]);
        }
    }

    pthread_mutex_destroy(&collection->mutex);
    free(collection->entries);
    free(collection);

    log_message("Collection and all entries freed.");
}

int serialize_collection(const Collection *collection, const char *filename) {
    if (!collection || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return -1;
    }

    pthread_mutex_lock(&collection->mutex);

    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        Entry *entry = collection->entries[i];
        if (!entry) continue;

        size_t keyLength = strlen(entry->key) + 1;
        fwrite(&keyLength, sizeof(size_t), 1, file);
        fwrite(entry->key, sizeof(char), keyLength, file);

        fwrite(&entry->value, sizeof(long), 1, file);
        fwrite(&entry->floatArraySize, sizeof(size_t), 1, file);
        fwrite(entry->floatArray, sizeof(float), entry->floatArraySize, file);
    }

    pthread_mutex_unlock(&collection->mutex);

    fclose(file);
    log_message("Collection serialized successfully.");
    return 0;
}

int deserialize_collection(Collection **collectionPtr, const char *filename) {
    if (!collectionPtr || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    Collection *collection = init_collection(count);
    if (!collection) {
        fclose(file);
        return -1;
    }

    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < count; ++i) {
        size_t keyLength;
        fread(&keyLength, sizeof(size_t), 1, file);

        Entry *entry = malloc(sizeof(Entry));
        entry->key = malloc(keyLength);
        fread(entry->key, sizeof(char), keyLength, file);

        fread(&entry->value, sizeof(long), 1, file);
        fread(&entry->floatArraySize, sizeof(size_t), 1, file);

        entry->floatArray = malloc(entry->floatArraySize * sizeof(float));
        fread(entry->floatArray, sizeof(float), entry->floatArraySize, file);

        collection->entries[i] = entry;
    }

    pthread_mutex_unlock(&collection->mutex);
    fclose(file);

    *collectionPtr = collection;
    log_message("Collection deserialized successfully.");
    return 0;
}

int main() {
    Collection *collection = init_collection(5);
    if (!collection) return EXIT_FAILURE;

    for (size_t i = 0; i < collection->count; ++i) {
        char key[20];
        snprintf(key, sizeof(key), "key%d", (int)i + 1);

        Entry *entry = malloc(sizeof(Entry));
        entry->mutex = PTHREAD_MUTEX_INITIALIZER;

        if (populate_entry(entry, key, i, 10, 0.0f, 1.0f) == -1) {
            free_entry(entry);
            free(entry);
            continue;
        }

        collection->entries[i] = entry;
    }

    serialize_collection(collection, "collection.bin");

    Collection *newCollection;
    deserialize_collection(&newCollection, "collection.bin");

    free_collection(newCollection);

    free_collection(collection);

    return EXIT_SUCCESS;
}
