#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *key;
    long value;
    float *floatArray;
    size_t floatSize;
} Entry;

#define MAX_ENTRIES 100

Entry *entries = NULL;
size_t entryCount = 0;
size_t maxFloatArraySize = 50; // Default maximum float array size
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to generate Gaussian-distributed values
float gaussian(float mean, float stddev) {
    static unsigned long int seed = 123456789;
    const float a = 16807.0f;
    const float m = 2147483647.0f;
    const float q = (float)(m / a);
    const float r = (float)(m % a);
    float x, y, z;

    do {
        seed = (unsigned long int)(a * ((double)seed - q * (int)(seed / q)));
        x = (float)(seed / m);

        seed = (unsigned long int)(a * ((double)seed - q * (int)(seed / q)));
        y = (float)(seed / m);
    } while (y == 0.0f || y == 1.0f);

    z = x + y - 1.0f;
    if (z < 0.0f) {
        return mean + stddev * sqrt(-2.0f * log(x)) * sin(6.28318530717958623f * y);
    } else {
        return mean + stddev * sqrt(-2.0f * log(z)) * cos(6.28318530717958623f * y);
    }
}

// Initialize the entries array
void initEntries(size_t size) {
    pthread_mutex_lock(&mutex);
    if (entries != NULL) {
        free(entries[0].key);
        free(entries[0].floatArray);
        free(entries);
    }

    entries = malloc(sizeof(Entry) * size);
    entryCount = 0;
    for (size_t i = 0; i < size; i++) {
        entries[i].key = NULL;
        entries[i].value = 0;
        entries[i].floatArray = NULL;
        entries[i].floatSize = 0;
    }
    pthread_mutex_unlock(&mutex);
}

// Add an entry
int addEntry(const char *key, long value) {
    pthread_mutex_lock(&mutex);

    if (entryCount >= MAX_ENTRIES) {
        printf("Max entries reached.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    size_t index = entryCount++;
    entries[index].key = strdup(key);
    entries[index].value = value;
    entries[index].floatArray = malloc(maxFloatArraySize * sizeof(float));
    if (!entries[index].floatArray) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    entries[index].floatSize = maxFloatArraySize;

    // Populate the float array with Gaussian values
    for (size_t i = 0; i < entries[index].floatSize; i++) {
        entries[index].floatArray[i] = gaussian(0.0f, 1.0f);
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Remove an entry
void removeEntry(size_t index) {
    pthread_mutex_lock(&mutex);

    if (index >= entryCount) {
        printf("Invalid index.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    free(entries[index].key);
    free(entries[index].floatArray);

    for (size_t i = index; i < entryCount - 1; i++) {
        entries[i] = entries[i + 1];
    }
    entryCount--;

    pthread_mutex_unlock(&mutex);
}

// Free all allocated memory
void freeEntries() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < entryCount; i++) {
        free(entries[i].key);
        free(entries[i].floatArray);
    }
    free(entries);
    entries = NULL;
    entryCount = 0;

    pthread_mutex_unlock(&mutex);
}

// Parse command line arguments
void parseArgs(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Usage: %s [options]\n", argv[0]);
            // Print man page details
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            maxFloatArraySize = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Handle output file
        }
    }
}

int main(int argc, char *argv[]) {
    parseArgs(argc, argv);

    initEntries(MAX_ENTRIES);

    // Example usage
    addEntry("exampleKey", 12345L);
    removeEntry(0);
    freeEntries();

    return 0;
}
