#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <map>
#include <memory>
#include <boost/algorithm/string.hpp>
#include <boost/filesystem.hpp>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>

using namespace boost::filesystem;
using namespace std;

struct Service {
    string name;
    int port;
    string protocol;
    function<void()> callback;
    int priority;

    Service(const string& n, int p, const string& proto, function<void()> cb, int pr)
        : name(n), port(p), protocol(proto), callback(cb), priority(pr) {}
};

class NetworkServiceManager {
private:
    vector<unique_ptr<Service>> services;
    map<int, bool> ports;

    void loadConfigurations(const vector<string>& file_paths) {
        for (const auto& path : file_paths) {
            ptree pt;
            read_json(path, pt);
            const ptree& service_node = pt.get_child("services");

            for (const auto& s : service_node) {
                string name = s.second.get<string>("name");
                int port = s.second.get<int>("port");
                string protocol = s.second.get<string>("protocol");
                int priority = s.second.get<int>("priority");

                if (ports[port]) {
                    cerr << "Duplicate port found: " << port << endl;
                    continue;
                }

                ports[port] = true;
                services.emplace_back(make_unique<Service>(name, port, protocol, []() {}, priority));
            }
        }
    }

public:
    NetworkServiceManager(const vector<string>& file_paths) {
        loadConfigurations(file_paths);
        sort(services.begin(), services.end(),
             [](const unique_ptr<Service>& a, const unique_ptr<Service>& b) {
                 return a->priority < b->priority;
             });
    }

    const vector<unique_ptr<Service>>& getServices() const {
        return services;
    }
};

struct Record {
    int value;
    char metadata[256];
    string* path;
};

long determineMaxDepth(const path& start_path) {
    long max_depth = 0;

    function<void(const path&, long)> traverse = [&](const path& p, long depth) {
        if (!exists(p)) return;

        if (is_directory(p)) {
            directory_iterator end_iter;
            for (directory_iterator dir_itr(p); dir_itr != end_iter; ++dir_itr) {
                if (is_directory(dir_itr->status())) {
                    traverse(dir_itr->path(), depth + 1);
                }
            }
            max_depth = max(max_depth, static_cast<long>(depth));
        }
    };

    traverse(start_path, 0);
    return max_depth;
}

void processPaths() {
    vector<string> file_paths;
    string input;

    while (getline(cin, input) && !input.empty()) {
        file_paths.push_back(input);
    }

    long* offsets = new (nothrow) long[file_paths.size()];
    int* indices = new (nothrow) int[file_paths.size()];
    Record* records = new (nothrow) Record[file_paths.size() * 10]; // Arbitrary max number of records per path
    string* paths = new (nothrow) string[file_paths.size()];

    if (!offsets || !indices || !records || !paths) {
        cerr << "Memory allocation failed." << endl;
        return;
    }

    long largest_depth = 0;
    size_t record_count = 0;

    for (size_t i = 0; i < file_paths.size(); ++i) {
        path p(file_paths[i]);
        if (!exists(p)) {
            cerr << "Path does not exist: " << file_paths[i] << endl;
            continue;
        }

        long depth = determineMaxDepth(p);
        largest_depth = max(largest_depth, depth);

        offsets[i] = sizeof(Record) * record_count; // Example offset calculation
        indices[i] = static_cast<int>(depth);       // Store directory depth as index

        for (size_t j = 0; j < 10 && record_count < array_size(records); ++j) {
            records[record_count].value = j;
            strcpy(records[record_count].metadata, "Example metadata");
            paths[i] = file_paths[i];
            records[record_count].path = &paths[i];
            record_count++;
        }
    }

    // Serialize example (simple file-based)
    ofstream out_file("data.bin", ios::binary);
    if (!out_file) {
        cerr << "Failed to open output file for serialization." << endl;
        return;
    }

    size_t record_size = sizeof(Record) * record_count;
    out_file.write(reinterpret_cast<char*>(records), record_size);

    // Deserialize example
    ifstream in_file("data.bin", ios::binary);
    if (!in_file) {
        cerr << "Failed to open input file for deserialization." << endl;
        return;
    }

    char* buffer = new char[record_size];
    in_file.read(buffer, record_size);

    // Cleanup
    delete[] offsets;
    delete[] indices;
    delete[] records;
    delete[] paths;
    delete[] buffer;
}

int main() {
    vector<string> file_paths = {"config1.json", "config2.json"};
    NetworkServiceManager manager(file_paths);

    for (const auto& service : manager.getServices()) {
        cout << "Service: " << service->name << ", Port: " << service->port
             << ", Protocol: " << service->protocol << ", Priority: " << service->priority << endl;
    }

    processPaths();
    return 0;
}
