#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PROFILES 1000
#define DEFAULT_PROFILE_SIZE 10

typedef struct PreferenceNode {
    char *preference;
    struct PreferenceNode *next;
} PreferenceNode;

typedef struct UserProfile {
    char *name;
    char *email;
    PreferenceNode *preferences;
} UserProfile;

typedef struct ProfileCollection {
    int capacity;
    int count;
    UserProfile **profiles;
} ProfileCollection;

ProfileCollection* create_profile_collection(int initial_size) {
    if (initial_size > MAX_PROFILES || initial_size <= 0) {
        fprintf(stderr, "Error: Invalid size parameter\n");
        return NULL;
    }

    ProfileCollection *collection = malloc(sizeof(ProfileCollection));
    if (!collection) {
        perror("Failed to allocate memory for profile collection");
        return NULL;
    }

    collection->capacity = initial_size;
    collection->count = 0;
    collection->profiles = calloc(initial_size, sizeof(UserProfile*));
    if (!collection->profiles) {
        perror("Failed to allocate memory for profiles array");
        free(collection);
        return NULL;
    }

    return collection;
}

int add_profile(ProfileCollection *collection, const char *name, const char *email) {
    if (!collection || !name || !email || collection->count >= collection->capacity || collection->capacity > MAX_PROFILES) {
        fprintf(stderr, "Error: Cannot add profile\n");
        return -1;
    }

    UserProfile *profile = malloc(sizeof(UserProfile));
    if (!profile) {
        perror("Failed to allocate memory for new profile");
        return -1;
    }

    profile->name = strdup(name);
    profile->email = strdup(email);
    profile->preferences = NULL;

    collection->profiles[collection->count++] = profile;

    return 0;
}

void free_profile(UserProfile *profile) {
    if (!profile) return;

    free(profile->name);
    free(profile->email);

    PreferenceNode *current = profile->preferences;
    while (current) {
        PreferenceNode *temp = current;
        current = current->next;
        free(temp->preference);
        free(temp);
    }
}

void free_profile_collection(ProfileCollection *collection) {
    if (!collection) return;

    for (int i = 0; i < collection->count; ++i) {
        free_profile(collection->profiles[i]);
    }

    free(collection->profiles);
    free(collection);
}

int serialize_profiles(const ProfileCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    fwrite(&collection->count, sizeof(int), 1, file);

    for (int i = 0; i < collection->count; ++i) {
        UserProfile *profile = collection->profiles[i];

        size_t name_len = strlen(profile->name) + 1;
        fwrite(&name_len, sizeof(size_t), 1, file);
        fwrite(profile->name, sizeof(char), name_len, file);

        size_t email_len = strlen(profile->email) + 1;
        fwrite(&email_len, sizeof(size_t), 1, file);
        fwrite(profile->email, sizeof(char), email_len, file);

        int pref_count = 0;
        PreferenceNode *current = profile->preferences;
        while (current) {
            pref_count++;
            current = current->next;
        }

        fwrite(&pref_count, sizeof(int), 1, file);

        for (int j = 0; j < pref_count; ++j) {
            current = profile->preferences;
            for (int k = 0; k < j && current; ++k)
                current = current->next;

            size_t pref_len = strlen(current->preference) + 1;
            fwrite(&pref_len, sizeof(size_t), 1, file);
            fwrite(current->preference, sizeof(char), pref_len, file);
        }
    }

    fclose(file);

    return 0;
}

int deserialize_profiles(ProfileCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fread(&collection->count, sizeof(int), 1, file);

    if (collection->count > collection->capacity || collection->count <= 0) {
        fprintf(stderr, "Error: Invalid number of profiles in file\n");
        fclose(file);
        return -1;
    }

    for (int i = 0; i < collection->count; ++i) {
        size_t name_len;
        fread(&name_len, sizeof(size_t), 1, file);

        char *name = malloc(name_len);
        if (!name) {
            perror("Failed to allocate memory for profile name");
            fclose(file);
            return -1;
        }
        fread(name, sizeof(char), name_len, file);

        size_t email_len;
        fread(&email_len, sizeof(size_t), 1, file);

        char *email = malloc(email_len);
        if (!email) {
            perror("Failed to allocate memory for profile email");
            free(name);
            fclose(file);
            return -1;
        }
        fread(email, sizeof(char), email_len, file);

        int pref_count;
        fread(&pref_count, sizeof(int), 1, file);

        UserProfile *profile = malloc(sizeof(UserProfile));
        if (!profile) {
            perror("Failed to allocate memory for new profile");
            free(name);
            free(email);
            fclose(file);
            return -1;
        }

        profile->name = name;
        profile->email = email;

        PreferenceNode *head = NULL, **tail = &head;
        for (int j = 0; j < pref_count; ++j) {
            size_t pref_len;
            fread(&pref_len, sizeof(size_t), 1, file);

            char *preference = malloc(pref_len);
            if (!preference) {
                perror("Failed to allocate memory for preference");

                while (head) {
                    PreferenceNode *temp = head;
                    head = head->next;
                    free(temp->preference);
                    free(temp);
                }

                free(profile->name);
                free(profile->email);
                free(profile);
                fclose(file);
                return -1;
            }

            fread(preference, sizeof(char), pref_len, file);

            *tail = malloc(sizeof(PreferenceNode));
            if (!*tail) {
                perror("Failed to allocate memory for preference node");

                while (head) {
                    PreferenceNode *temp = head;
                    head = head->next;
                    free(temp->preference);
                    free(temp);
                }

                free(preference);
                free(profile->name);
                free(profile->email);
                free(profile);
                fclose(file);
                return -1;
            }

            (*tail)->preference = preference;
            (*tail)->next = NULL;
            tail = &(*tail)->next;
        }

        profile->preferences = head;
        collection->profiles[i] = profile;
    }

    fclose(file);

    return 0;
}

void optimize_performance(ProfileCollection *collection) {
    // Example: Implement caching mechanism for frequent read/write
    // This function would contain optimization techniques like reducing file I/O frequency,
    // implementing a memory cache, or using faster serialization formats.

    // For demonstration purposes, let's assume we're improving the deserialization performance by caching profiles.
}

int main() {
    ProfileCollection *collection = create_profile_collection(DEFAULT_PROFILE_SIZE);

    if (collection) {
        add_profile(collection, "John Doe", "john@example.com");
        serialize_profiles(collection, "profiles.dat");

        ProfileCollection *new_collection = create_profile_collection(DEFAULT_PROFILE_SIZE);

        deserialize_profiles(new_collection, "profiles.dat");
        optimize_performance(new_collection);

        free_profile_collection(new_collection);
        free_profile_collection(collection);
    }

    return 0;
}
