#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_PATH_LENGTH 4096
#define MAX_RECORDS 1000

typedef struct {
    int value;
    char metadata[256];
    char *path;
    char *metadata_ptr;
    int *timestamp;
    int *parent_index;
    int *directory_depth;
} Record;

typedef struct {
    long *fd_offsets;
    int *dir_indices;
    Record **records;
    char **paths;
    char **metadatas;
    int *timestamps;
    int *parent_indices;
    size_t record_count;
    pthread_mutex_t lock;
} FileSystemData;

void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int get_directory_depth(const char *path, int current_depth) {
    struct stat st;
    if (lstat(path, &st) != 0) return current_depth;

    if (S_ISLNK(st.st_mode)) return current_depth;

    char new_path[MAX_PATH_LENGTH];
    snprintf(new_path, sizeof(new_path), "%s/", path);

    DIR *dir = opendir(new_path);
    if (!dir) return current_depth;

    struct dirent *entry;
    int max_depth = current_depth;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(new_path, sizeof(new_path), "%s%s", new_path, entry->d_name);
        int depth = get_directory_depth(new_path, current_depth + 1);
        if (depth > max_depth) max_depth = depth;
    }

    closedir(dir);
    return max_depth;
}

void process_file_paths(FileSystemData *fs_data, size_t size) {
    pthread_mutex_init(&fs_data->lock, NULL);

    fs_data->fd_offsets = malloc(size * sizeof(long));
    fs_data->dir_indices = malloc(size * sizeof(int));
    fs_data->records = malloc(size * sizeof(Record *));
    fs_data->paths = malloc(size * sizeof(char *));
    fs_data->metadatas = malloc(size * sizeof(char *));
    fs_data->timestamps = malloc(size * sizeof(int));
    fs_data->parent_indices = malloc(size * sizeof(int));

    if (!fs_data->fd_offsets || !fs_data->dir_indices || !fs_data->records ||
        !fs_data->paths || !fs_data->metadatas || !fs_data->timestamps ||
        !fs_data->parent_indices) {
        error("Memory allocation failed");
    }

    fs_data->record_count = 0;

    char path[MAX_PATH_LENGTH];
    while (fgets(path, sizeof(path), stdin)) {
        if (fs_data->record_count >= size) break;

        pthread_mutex_lock(&fs_data->lock);

        long fd_offset = lseek(STDIN_FILENO, 0, SEEK_CUR);
        fs_data->fd_offsets[fs_data->record_count] = fd_offset;

        int dir_index = fs_data->record_count;
        fs_data->dir_indices[dir_index] = dir_index;

        Record *record = malloc(sizeof(Record));
        if (!record) {
            error("Memory allocation failed");
        }

        char *file_path = strdup(path);
        struct stat st;
        if (stat(file_path, &st) == -1) {
            free(file_path);
            pthread_mutex_unlock(&fs_data->lock);
            continue;
        }

        int timestamp = st.st_mtime;
        int parent_index = -1; // Assuming root paths have no parent
        int directory_depth = get_directory_depth(file_path, 0);

        record->value = dir_index;
        snprintf(record->metadata, sizeof(record->metadata), "File modified at %d", timestamp);
        record->path = file_path;
        record->metadata_ptr = strdup(record->metadata);
        record->timestamp = &fs_data->timestamps[fs_data->record_count];
        *record->timestamp = timestamp;
        record->parent_index = &fs_data->parent_indices[fs_data->record_count];
        *record->parent_index = parent_index;
        record->directory_depth = &fs_data->dir_indices[fs_data->record_count]; // Use dir_indices for depth
        *(record->directory_depth) = directory_depth;

        fs_data->records[dir_index] = record;
        fs_data->paths[dir_index] = file_path;
        fs_data->metadatas[dir_index] = record->metadata_ptr;

        fs_data->record_count++;

        pthread_mutex_unlock(&fs_data->lock);
    }

    int max_depth = 0, max_depth_index = -1;
    for (size_t i = 0; i < fs_data->record_count; i++) {
        if (*(fs_data->records[i]->directory_depth) > max_depth) {
            max_depth = *(fs_data->records[i]->directory_depth);
            max_depth_index = i;
        }
    }

    if (max_depth_index != -1) {
        printf("Path with largest directory depth: %s\n", fs_data->paths[max_depth_index]);
    } else {
        printf("No valid paths found.\n");
    }

    pthread_mutex_destroy(&fs_data->lock);
}

void free_file_system_data(FileSystemData *fs_data) {
    for (size_t i = 0; i < fs_data->record_count; i++) {
        free(fs_data->records[i]->path);
        free(fs_data->records[i]->metadata_ptr);
        free(fs_data->records[i]);
    }

    free(fs_data->fd_offsets);
    free(fs_data->dir_indices);
    free(fs_data->records);
    free(fs_data->paths);
    free(fs_data->metadatas);
    free(fs_data->timestamps);
    free(fs_data->parent_indices);
}

int main() {
    FileSystemData fs_data;
    process_file_paths(&fs_data, MAX_RECORDS);
    free_file_system_data(&fs_data);
    return 0;
}
