int find_largest_integer(int *keys, size_t count) {
    if (count == 0) return INT_MIN;

    int largest = keys[0];
    for (size_t i = 1; i < count; ++i) {
        if (keys[i] > largest)
            largest = keys[i];
    }
    return largest;
}

void initialize_record(Record *record) {
    record->value = rand();
    for (int i = 0; i < BUFFER_SIZE - 1; ++i) {
        record->buffer[i] = random_char();
    }
    record->buffer[BUFFER_SIZE - 1] = '\0';
}

void initialize_manager(NetworkServiceManager *manager, size_t count) {
    manager->offsets = (long *)malloc(count * sizeof(long));
    manager->keys = (int *)malloc(count * sizeof(int));
    manager->records = (Record *)malloc(count * sizeof(Record));
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);
}

void free_manager(NetworkServiceManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

