    while (count < max_count && scanf("%d", &value) == 1) {
        keys[count++] = value;
    }
}

void serialize_manager(const NetworkServiceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->keys, sizeof(int), manager->count, file);
    fwrite(manager->records, sizeof(Record), manager->count, file);

    fclose(file);
}

void deserialize_manager(NetworkServiceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fread(&manager->count, sizeof(size_t), 1, file);
    manager->keys = (int *)realloc(manager->keys, manager->count * sizeof(int));
    manager->records = (Record *)realloc(manager->records, manager->count * sizeof(Record));

    fread(manager->keys, sizeof(int), manager->count, file);
    fread(manager->records, sizeof(Record), manager->count, file);

    fclose(file);
}

void add_record(NetworkServiceManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count < MAX_RECORDS) {
        initialize_record(&manager->records[manager->count]);
        manager->keys[manager->count] = rand();
        ++manager->count;
    }

    pthread_mutex_unlock(&manager->lock);
}

void process_records(NetworkServiceManager *manager) {
    int largest = find_largest_integer(manager->keys, manager->count);
    printf("Largest integer: %d\n", largest);

    for (size_t i = 0; i < manager->count; ++i) {
        printf("Record value: %d, buffer: %s\n", manager->records[i].value, manager->records[i].buffer);
    }
}

int main() {
    initialize_random_seed();

    NetworkServiceManager manager;
    size_t count = 100; // Example capacity
    initialize_manager(&manager, count);

    read_integers_from_stdin(manager.keys, count);

    for (size_t i = 0; i < manager.count; ++i) {
        add_record(&manager);
    }

    process_records(&manager);

    serialize_manager(&manager, "network_service.dat");
    NetworkServiceManager new_manager;
    initialize_manager(&new_manager, MAX_RECORDS);
    deserialize_manager(&new_manager, "network_service.dat");

    free_manager(&manager);
    free_manager(&new_manager);

    return 0;
}
