typedef struct {
    int value;
    char status;
    char *name;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t **records;
    size_t offset_count, key_count, record_count;
    pthread_mutex_t lock;
    int error_flag;
    Config config; // Assume a configuration structure
} MemoryManager;

void log_error(const char *message);
void log_info(const char *message);

MemoryManager* initialize_memory_manager(size_t offset_limit, size_t key_size, size_t record_size) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) {
        log_error("Failed to allocate memory for manager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->offset_count = offset_limit;
    manager->key_count = key_size;
    manager->record_count = record_size;
    manager->error_flag = 0;

    // Load configuration
    if (!config_load(&manager->config)) {
        log_error("Failed to load config");
        free(manager);
        return NULL;
    }

    // Allocate memory with mutex lock for thread-safety
    pthread_mutex_lock(&manager->lock);

    manager->offsets = malloc(sizeof(long) * offset_limit);
    if (!manager->offsets) {
        log_error("Failed to allocate offsets");
        manager->error_flag = 1;
        goto cleanup;
    }

    manager->keys = malloc(sizeof(int) * key_size);
    if (!manager->keys) {
        log_error("Failed to allocate keys");
        manager->error_flag = 1;
        goto cleanup;
    }

    manager->records = malloc(sizeof(record_t*) * record_size);
    if (!manager->records) {
        log_error("Failed to allocate records");
        manager->error_flag = 1;
        goto cleanup;
    }

    for (size_t i = 0; i < offset_limit; ++i) {
        manager->offsets[i] = i;
    }

    for (size_t i = 0; i < key_size; ++i) {
        manager->keys[i] = i;
    }

    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < record_size; ++i) {
        record_t *record = malloc(sizeof(record_t));
        if (!record) {
            log_error("Failed to allocate a single record");
            manager->error_flag = 1;
            goto cleanup;
        }

        int range_min = config_get_int(&manager->config, "random_range_min", 0);
        int range_max = config_get_int(&manager->config, "random_range_max", 100);

        record->value = rand() % (range_max - range_min + 1) + range_min;

        record->status = (rand() % 2 == 0) ? 'A' : 'B';

        size_t str_length = config_get_int(&manager->config, "string_length", 10);
        char *name = malloc(str_length + 1); // +1 for null terminator
        if (!name) {
            log_error("Failed to allocate string name");
            manager->error_flag = 1;
            free(record);
            goto cleanup;
        }

        for (size_t j = 0; j < str_length; ++j) {
            name[j] = 'A' + rand() % 26;
        }
        name[str_length] = '\0';

        // Optional compression can be applied here
        if (config_get_bool(&manager->config, "compress_strings", false)) {
            // Placeholder for compression logic
        }

        record->name = name;
        manager->records[i] = record;

        log_info("Record allocated");
    }

    pthread_mutex_unlock(&manager->lock);
    return manager;

cleanup:
    pthread_mutex_unlock(&manager->lock);
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < record_size && !manager->error_flag; ++i) {
            free(manager->records[i]);
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }

    return NULL;
}

void deallocate_memory_manager(MemoryManager *manager) {
    if (!manager || manager->error_flag) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->records[i]->name);
        free(manager->records[i]);
    }

    free(manager->records);
    free(manager->keys);
    free(manager->offsets);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_info("Memory deallocated");
}

void log_error(const char *message) {
    // Implement logging of errors
}

void log_info(const char *message) {
    // Implement logging of information
}
