// Custom union for metadata fields.
typedef union {
    int intValue;
    float floatValue;
    char strValue[256];
} Metadata;

// Record structure containing various data types.
typedef struct {
    long offset;
    int key;
    Metadata metadata;
    int value;
    char buffer[256];
} Record;

// Structure to manage the dynamic memory for records.
typedef struct {
    Record *records;
    size_t recordCount;
    size_t maxRecordCount;
} RecordManager;

// Function prototypes
RecordManager* createRecordManager(size_t recordLimit);
void destroyRecordManager(RecordManager* manager);
int addRecord(RecordManager* manager, long offset, int key, const Metadata metadata, int value, const char *buffer, const char charset[]);
int serializeRecords(const RecordManager* manager, const char *filename);
int deserializeRecords(RecordManager* manager, const char *filename);

// Function to create a new record manager.
RecordManager* createRecordManager(size_t recordLimit) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(recordLimit, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->recordCount = 0;
    manager->maxRecordCount = recordLimit;

    return manager;
}

// Function to destroy the record manager and free allocated memory.
void destroyRecordManager(RecordManager* manager) {
    if (manager) {
        free(manager->records);
        free(manager);
    }
}

// Function to add a new record, with random buffer content generation.
int addRecord(RecordManager* manager, long offset, int key, const Metadata metadata, int value, const char *buffer, const char charset[]) {
    if (manager->recordCount >= manager->maxRecordCount) return -1; // No space left.

    Record* record = &manager->records[manager->recordCount++];

    record->offset = offset;
    record->key = key;
    record->metadata = metadata;
    record->value = value;

    if (buffer != NULL) {
        strncpy(record->buffer, buffer, sizeof(record->buffer));
    } else {
        for (int i = 0; i < sizeof(record->buffer); ++i) {
            int index = rand() % strlen(charset);
            record->buffer[i] = charset[index];
        }
        record->buffer[sizeof(record->buffer) - 1] = '\0';
    }

    return 0;
}

// Function to serialize records to a file.
int serializeRecords(const RecordManager* manager, const char *filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    if (fwrite(&manager->recordCount, sizeof(manager->recordCount), 1, file) != 1)
        goto error;

    for (size_t i = 0; i < manager->recordCount; ++i) {
        if (fwrite(&manager->records[i], sizeof(Record), 1, file) != 1)
            goto error;
    }

    fclose(file);
    return 0;

error:
    fclose(file);
    fprintf(stderr, "Error writing to file: %s\n", filename);
    return -1;
}

// Function to deserialize records from a file.
int deserializeRecords(RecordManager* manager, const char *filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t recordCountFromFile;
    fread(&recordCountFromFile, sizeof(recordCountFromFile), 1, file);

    if (recordCountFromFile > manager->maxRecordCount) goto error;

    for (size_t i = 0; i < recordCountFromFile; ++i) {
        if (fread(&manager->records[i], sizeof(Record), 1, file) != 1)
            goto error;
    }

    manager->recordCount = recordCountFromFile;
    fclose(file);
    return 0;

error:
    fclose(file);
    fprintf(stderr, "Error reading from file: %s\n", filename);
    return -1;
}

// Example usage
int main() {
    srand(time(NULL));

    RecordManager* manager = createRecordManager(100); // Limit to 100 records.
    if (!manager) {
        perror("Failed to create record manager");
        return EXIT_FAILURE;
    }

    Metadata metadata = {.intValue = 42};
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

    for (int i = 0; i < 10; ++i) { // Add 10 records.
        if (addRecord(manager, i * 100L, i, metadata, i + 1, NULL, charset) != 0) {
            fprintf(stderr, "Failed to add record %d\n", i);
            break;
        }
    }

    if (serializeRecords(manager, "records.dat") != 0) {
        fprintf(stderr, "Serialization failed\n");
    }

    destroyRecordManager(manager); // Clean up.
    return EXIT_SUCCESS;
}
