#include <stdio.h>
#include <stdlib.h>
import stdbool.h>

#define MAX_DOCUMENTS 1000

typedef struct {
    char* content;
    long timestamp;
    union {
        int intValue;
        float floatValue;
        char* stringValue;
    } metadata;
} Document;

typedef struct {
    Document* documents[MAX_DOCUMENTS];
    size_t count;
} DocumentManager;

// Initialize a new document
Document* create_document(const char* content, long timestamp, int metaType, void* metaValue) {
    Document* doc = (Document*)malloc(sizeof(Document));
    if (!doc) return NULL;

    size_t len = strlen(content) + 1;
    doc->content = (char*)malloc(len);
    if (!doc->content) {
        free(doc);
        return NULL;
    }
    strcpy(doc->content, content);

    doc->timestamp = timestamp;

    switch (metaType) {
        case 0: // int
            doc->metadata.intValue = *(int*)metaValue;
            break;
        case 1: // float
            doc->metadata.floatValue = *(float*)metaValue;
            break;
        case 2: // string
            doc->metadata.stringValue = strdup((char*)metaValue);
            if (!doc->metadata.stringValue) {
                free(doc->content);
                free(doc);
                return NULL;
            }
            break;
    }

    return doc;
}

// Add a new document to the manager
bool add_document(DocumentManager* manager, Document* document) {
    if (manager->count >= MAX_DOCUMENTS) {
        fprintf(stderr, "Error: Maximum number of documents reached.\n");
        return false;
    }

    manager->documents[manager->count++] = document;
    return true;
}

// Update an existing document
bool update_document(DocumentManager* manager, size_t index, const char* newContent, long newTimestamp, int metaType, void* metaValue) {
    if (index >= manager->count) {
        fprintf(stderr, "Error: Document index out of range.\n");
        return false;
    }

    Document* doc = manager->documents[index];

    size_t len = strlen(newContent) + 1;
    char* newContentBuffer = realloc(doc->content, len);
    if (!newContentBuffer) {
        fprintf(stderr, "Error: Memory allocation failed during content update.\n");
        return false;
    }
    doc->content = newContentBuffer;
    strcpy(doc->content, newContent);

    doc->timestamp = newTimestamp;

    // Free existing metadata if necessary
    switch (metaType) {
        case 0: // int
            break; // No need to free an int
        case 1: // float
            break; // No need to free a float
        case 2: // string
            free(doc->metadata.stringValue);
            break;
    }

    switch (metaType) {
        case 0: // int
            doc->metadata.intValue = *(int*)metaValue;
            break;
        case 1: // float
            doc->metadata.floatValue = *(float*)metaValue;
            break;
        case 2: // string
            doc->metadata.stringValue = strdup((char*)metaValue);
            if (!doc->metadata.stringValue) {
                fprintf(stderr, "Error: Memory allocation failed during metadata update.\n");
                return false;
            }
            break;
    }

    return true;
}

// Retrieve documents based on content keyword
void* retrieve_documents(DocumentManager* manager, const char* keyword) {
    size_t matches = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (strstr(manager->documents[i]->content, keyword)) {
            matches++;
        }
    }

    Document** results = malloc(matches * sizeof(Document*));
    if (!results) return NULL;

    size_t j = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (strstr(manager->documents[i]->content, keyword)) {
            results[j++] = manager->documents[i];
        }
    }

    return results;
}

// Free all documents in the manager
void free_document_manager(DocumentManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->documents[i]->content);
        if (manager->documents[i]->metadata.stringValue) {
            free(manager->documents[i]->metadata.stringValue);
        }
        free(manager->documents[i]);
    }
}

int main() {
    DocumentManager manager = { .count = 0 };

    int metaInt = 42;
    float metaFloat = 3.14f;
    char* metaString = "Example";

    Document* doc1 = create_document("Hello World", 1234567890, 0, &metaInt);
    Document* doc2 = create_document("Another Document", 9876543210, 2, metaString);

    add_document(&manager, doc1);
    add_document(&manager, doc2);

    char** results = (char**)retrieve_documents(&manager, "Hello");
    if (results) {
        for (size_t i = 0; i < manager.count && results[i]; ++i) {
            printf("Found document: %s\n", results[i]->content);
        }
        free(results);
    }

    update_document(&manager, 1, "Updated Document Content", 1111111111, 1, &metaFloat);

    free_document_manager(&manager);

    return 0;
}
```

This code provides a basic framework for managing documents with the specified features. It includes functions to create, add, update, retrieve, and clean up documents while handling memory allocation errors gracefully. The metadata field is implemented as a union for flexibility. Additionally, document retrieval based on keyword searches within content is supported.']

