#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PipelineStage {
    char* buffer;
    size_t length;
    struct PipelineStage* next;
} PipelineStage;

typedef struct DataPacket {
    void* payload;
    size_t size;
    PipelineStage* source_stage;
} DataPacket;

#define MAX_STAGES 100
#define MAX_PACKETS 100

// Function to detect cycles in the linked list using Floyd's Tortoise and Hare algorithm
int has_cycle(PipelineStage* head) {
    if (!head || !head->next) return 0;

    PipelineStage *slow = head, *fast = head->next;

    while (fast && fast->next) {
        if (slow == fast) return 1; // Cycle detected
        slow = slow->next;
        fast = fast->next->next;
    }
    return 0; // No cycle
}

void process_pipeline(int num_stages, int num_packets) {
    if (num_stages <= 0 || num_stages > MAX_STAGES || num_packets <= 0 || num_packets > MAX_PACKETS) {
        fprintf(stderr, "Invalid number of stages or packets\n");
        return;
    }

    PipelineStage* head = NULL;
    PipelineStage** current_stage = &head;

    // Create pipeline stages
    for (int i = 0; i < num_stages; ++i) {
        PipelineStage* new_stage = malloc(sizeof(PipelineStage));
        if (!new_stage) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        new_stage->buffer = NULL;
        new_stage->length = 0;
        new_stage->next = NULL;

        *current_stage = new_stage;
        current_stage = &new_stage->next;
    }

    if (has_cycle(head)) {
        fprintf(stderr, "Cycle detected in pipeline stages\n");
        return;
    }

    DataPacket* packets = malloc(num_packets * sizeof(DataPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for data packets\n");
        return;
    }

    PipelineStage* stage = head;
    while (stage) {
        // Simulate buffer processing
        size_t prefix_length = 5; // Example fixed prefix length
        char* new_buffer = malloc(prefix_length + stage->length + 1);
        if (!new_buffer) {
            fprintf(stderr, "Memory allocation failed for pipeline stage buffer\n");
            return;
        }

        snprintf(new_buffer, prefix_length + 1, "prefix"); // Simulate adding a prefix
        strcat(new_buffer, stage->buffer ? stage->buffer : "");

        free(stage->buffer);
        stage->buffer = new_buffer;
        stage->length += prefix_length;

        stage = stage->next;
    }

    for (int i = 0; i < num_packets; ++i) {
        packets[i].payload = malloc(10); // Simulate data packet payload size
        if (!packets[i].payload) {
            fprintf(stderr, "Memory allocation failed for data packet payload\n");
            return;
        }

        snprintf((char*)packets[i].payload, 10, "data%d", i);
        packets[i].size = strlen((char*)packets[i].payload);
        packets[i].source_stage = head; // Example assignment
    }

    // Clean up
    stage = head;
    while (stage) {
        PipelineStage* next_stage = stage->next;
        free(stage->buffer);
        free(stage);
        stage = next_stage;
    }

    for (int i = 0; i < num_packets; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}
