['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

void log_allocation_failure(const char *message) {
    FILE *log_file = fopen("memory.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void* safe_malloc(size_t size, const char *error_message) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_allocation_failure(error_message);
    }
    return ptr;
}

int generate_unique_random_int(int min, int max, int *used_keys, int num_used) {
    int rand_num;
    do {
        rand_num = (rand() % (max - min + 1)) + min;
    } while (binary_search(used_keys, num_used, rand_num));
    return rand_num;
}

int binary_search(int *arr, int size, int target) {
    int low = 0, high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target)
            return 1;
        else if (arr[mid] < target)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return 0;
}

void populate_keys(int *keys, int num_keys, int min_key, int max_key) {
    int used_keys[num_keys];
    memset(used_keys, -1, sizeof(used_keys));

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = generate_unique_random_int(min_key, max_key, used_keys, i);
        used_keys[i] = keys[i];
    }
}

void populate_records(record *records, int num_records, int min_value, int max_value) {
    for (int i = 0; i < num_records; ++i) {
        records[i].value = (rand() % (max_value - min_value + 1)) + min_value;
    }
}

void manage_memory_allocation(int n, int min_key, int max_key, int min_value, int max_value) {
    if (n <= 0 || max_key < min_key || max_value < min_value) {
        log_allocation_failure("Invalid input parameters.");
        return;
    }

    srand(time(NULL));

    long *offsets = safe_malloc(n * sizeof(long), "Failed to allocate memory for offsets.");
    if (!offsets) return;

    int num_keys = n / 2;
    int *keys = safe_malloc(num_keys * sizeof(int), "Failed to allocate memory for keys.");
    if (!keys) {
        free(offsets);
        return;
    }

    record *records = safe_malloc(num_keys * sizeof(record), "Failed to allocate memory for records.");
    if (!records) {
        free(keys);
        free(offsets);
        return;
    }

    populate_keys(keys, num_keys, min_key, max_key);
    populate_records(records, num_keys, min_value, max_value);

    // Simulate data processing...

    free(keys);
    free(records);
    free(offsets);
}

int main() {
    int n = 10; // Example value
    int min_key = 1;
    int max_key = 20;
    int min_value = 5;
    int max_value = 15;

    manage_memory_allocation(n, min_key, max_key, min_value, max_value);

    return 0;
}
