    size_t value;
} Node;

typedef struct {
    Node *nodes;
    size_t capacity;
    size_t size;
} NodeList;

int allocate_memory(NodeList *list, size_t new_capacity) {
    Node *new_nodes = realloc(list->nodes, new_capacity * sizeof(Node));
    if (!new_nodes) return -1; // Memory allocation failed
    list->nodes = new_nodes;
    list->capacity = new_capacity;
    for (size_t i = list->size; i < new_capacity; ++i) {
        list->nodes[i].key = '\0';  // Initialize unused nodes
        list->nodes[i].value = 0;
    }
    return 0;
}

void log_memory_usage(const NodeList *list, const char *action) {
    printf("Action: %s | Capacity: %zu | Size: %zu\n", action, list->capacity, list->size);
}

NodeList* create_node_list(size_t initial_capacity, const char *keys, size_t min_value, size_t max_value) {
    NodeList *list = malloc(sizeof(NodeList));
    if (!list) return NULL;

    srand((unsigned int)time(NULL));  // Seed for random number generation

    list->capacity = (initial_capacity > INITIAL_CAPACITY) ? initial_capacity : INITIAL_CAPACITY;
    list->size = 0;

    if (allocate_memory(list, list->capacity) != 0) {
        free(list);
        return NULL;  // Allocation failed
    }

    size_t key_length = strlen(keys);
    for (size_t i = 0; i < key_length && list->size < list->capacity; ++i) {
        Node *node = &list->nodes[list->size];
        node->key = keys[i];
        node->value = min_value + rand() % (max_value - min_value + 1);
        log_memory_usage(list, "Add");
        list->size++;
    }

    return list;
}

int add_node(NodeList *list, char key, size_t value) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        if (allocate_memory(list, new_capacity) != 0) return -1; // Reallocation failed
    }

    Node *node = &list->nodes[list->size];
    node->key = key;
    node->value = value;
    log_memory_usage(list, "Add");
    list->size++;
    return 0;
}

void free_node_list(NodeList *list) {
    free(list->nodes);
    free(list);
}

const Node* get_node(const NodeList *list, size_t index) {
    if (index < list->size) {
        return &list->nodes[index];
    }
    return NULL;  // Index out of bounds
}

void iterate_list(const NodeList *list, void (*callback)(int direction, const Node *)) {
    for (int i = 0; i < list->size; ++i) {
        callback(1 /* forward */, &list->nodes[i]);
    }
    for (int i = list->size - 1; i >= 0; --i) {
        callback(-1 /* backward */, &list->nodes[i]);
    }
}

void node_callback(int direction, const Node *node) {
    printf("Direction: %s | Key: %c | Value: %zu\n", (direction == 1 ? "Forward" : "Backward"), node->key, node->value);
}
