public:
    bool isLeaf;
    std::vector<OctreeNode*> children;
    int depth;

    OctreeNode(int depth) : isLeaf(true), depth(depth) {}
};

class Octree {
private:
    OctreeNode* root;
    size_t featureSize;
    size_t numLeafNodes;
    float spatialResolution;
    std::shared_mutex mutex_;

public:
    Octree(size_t featureSize, size_t numLeafNodes, float spatialResolution)
        : featureSize(featureSize), numLeafNodes(numLeafNodes), spatialResolution(spatialResolution) {
        root = new OctreeNode(0);
    }

    ~Octree() {
        clear(root);
    }

    void clear(OctreeNode* node) {
        if (!node->isLeaf) {
            for (auto child : node->children) {
                clear(child);
            }
            delete node;
        }
    }

    // Thread-safe methods to modify and access the octree
    void addNode(size_t depth, size_t x, size_t y, size_t z) {
        std::unique_lock lock(mutex_);
        addNodeInternal(root, depth, x, y, z);
    }

private:
    void addNodeInternal(OctreeNode* node, size_t depth, size_t x, size_t y, size_t z) {
        if (depth == numLeafNodes || node->isLeaf) {
            // Handle leaf node logic
            return;
        }

        int index = ((x & 1) << 2) | ((y & 1) << 1) | (z & 1);
        if (!node->children[index]) {
            node->children.push_back(new OctreeNode(depth + 1));
        }

        addNodeInternal(node->children[index], depth + 1, x >> 1, y >> 1, z >> 1);
    }
};

