#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_PACKETS 10000000
#define EXPIRATION_THRESHOLD_SECONDS 3600

typedef struct {
    uint64_t id;
    time_t timestamp;
    int status_flag;
    int value;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    pthread_mutex_t lock;
    size_t count;
} PacketManager;

// Custom memory pool allocator (simplified)
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

PacketManager packet_manager = { .count = 0 };

void add_or_update_packet(uint64_t id, int value) {
    pthread_mutex_lock(&packet_manager.lock);

    for (size_t i = 0; i < packet_manager.count; ++i) {
        if (packet_manager.packets[i]->id == id) {
            packet_manager.packets[i]->value = value;
            packet_manager.packets[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&packet_manager.lock);
            return;
        }
    }

    if (packet_manager.count < MAX_PACKETS) {
        DataPacket *new_packet = aligned_alloc(64, sizeof(DataPacket));
        new_packet->id = id;
        new_packet->timestamp = time(NULL);
        new_packet->value = value;
        new_packet->status_flag = 1; // Active
        packet_manager.packets[packet_manager.count++] = new_packet;
    }

    pthread_mutex_unlock(&packet_manager.lock);
}

void purge_expired_packets() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&packet_manager.lock);

    for (size_t i = 0; i < packet_manager.count; ) {
        if (current_time - packet_manager.packets[i]->timestamp > EXPIRATION_THRESHOLD_SECONDS) {
            free(packet_manager.packets[i]);
            packet_manager.packets[i] = packet_manager.packets[--packet_manager.count];
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&packet_manager.lock);
}

void fetch_and_update_values() {
    // Simulated external data source update
    for (size_t i = 0; i < packet_manager.count; ++i) {
        if (packet_manager.packets[i]->status_flag == 1) {
            // Simulate fetching new value
            packet_manager.packets[i]->value += rand() % 10;
        }
    }
}

void find_and_print_largest_integer() {
    int largest = INT_MIN;

    for (size_t i = 0; i < packet_manager.count; ++i) {
        if (packet_manager.packets[i]->status_flag == 1 && packet_manager.packets[i]->value > largest) {
            largest = packet_manager.packets[i]->value;
        }
    }

    printf("Largest integer: %d\n", largest);
}

void read_integers_and_find_largest() {
    int num, largest = INT_MIN;

    while (scanf("%d", &num) == 1) {
        if (num > largest) {
            largest = num;
        }
    }

    printf("Largest integer from input: %d\n", largest);
}

void manage_data_flows() {
    pthread_mutex_init(&packet_manager.lock, NULL);

    // Example usage
    add_or_update_packet(1, 100);
    purge_expired_packets();
    fetch_and_update_values();
    find_and_print_largest_integer();

    read_integers_and_find_largest();

    // Cleanup
    for (size_t i = 0; i < packet_manager.count; ++i) {
        free(packet_manager.packets[i]);
    }
    pthread_mutex_destroy(&packet_manager.lock);
}

int main() {
    manage_data_flows();
    return 0;
}
