```c
#include <stdio.h>
#include <stdlib.h>
#include <mysql/mysql.h>

void executeQuery(MYSQL *conn, int supervisorId) {
    const char *query = "SELECT employee_name, city, address FROM Employees WHERE supervisor_id = ?";

    if (mysql_real_query(conn, query, strlen(query))) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        return;
    }

    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (!stmt) {
        fprintf(stderr, "Failed to initialize statement\n");
        return;
    }

    if (mysql_stmt_prepare(stmt, query, strlen(query))) {
        fprintf(stderr, "Prepare statement failed: %s\n", mysql_stmt_error(stmt));
        return;
    }

    MYSQL_BIND bind[1];
    memset(bind, 0, sizeof(bind));

    int param = supervisorId;
    bind[0].buffer_type = MYSQL_TYPE_LONG;
    bind[0].buffer = (char *)&param;

    if (mysql_stmt_bind_param(stmt, bind)) {
        fprintf(stderr, "Bind parameter failed: %s\n", mysql_stmt_error(stmt));
        return;
    }

    if (mysql_stmt_execute(stmt)) {
        fprintf(stderr, "Execute statement failed: %s\n", mysql_stmt_error(stmt));
        return;
    }

    MYSQL_RES *result = mysql_stmt_result_metadata(stmt);
    if (!result) {
        fprintf(stderr, "Result metadata unavailable\n");
        return;
    }

    int num_fields = mysql_num_fields(result);

    MYSQL_BIND bind_result[num_fields];
    char **column_values = (char **)malloc(num_fields * sizeof(char *));
    for (int i = 0; i < num_fields; ++i) {
        column_values[i] = (char *)malloc(1024);
        memset(column_values[i], 0, 1024);

        bind_result[i].buffer_type = MYSQL_TYPE_STRING;
        bind_result[i].buffer = column_values[i];
        bind_result[i].buffer_length = 1024;
    }

    if (mysql_stmt_bind_result(stmt, bind_result)) {
        fprintf(stderr, "Bind result set failed: %s\n", mysql_stmt_error(stmt));
        return;
    }

    while (!mysql_stmt_fetch(stmt)) {
        for (int i = 0; i < num_fields; ++i) {
            printf("%s ", column_values[i]);
        }
        putchar('\n');
    }

    for (int i = 0; i < num_fields; ++i) {
        free(column_values[i]);
    }
    free(column_values);

    mysql_free_result(result);
    mysql_stmt_close(stmt);
}

int main() {
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database", 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        return 1;
    }

    int supervisorId = 123; // Example input
    executeQuery(conn, supervisorId);

    mysql_close(conn);
    return 0;
}
