#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>
#include <time.h>

// Configuration settings structure
typedef struct {
    int value_range_min;
    int value_range_max;
    size_t string_length;
    int compression_enabled;
} Config;

// Global configuration and state variables
Config config = {0, 100, 50, 0};
int error_flag = 0;
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t peak_memory_usage = 0;
size_t current_memory_usage = 0;

// Record structure
typedef struct {
    int value;
    char status;
    char *name;
} Record;

// Logging function prototype
void log_message(const char *message);

// Performance monitoring functions
void start_timer();
double stop_timer();

// Configuration loader (mock implementation for simplicity)
void load_config() {
    pthread_mutex_lock(&config_mutex);

    // Simulated loading from a file
    config.value_range_min = 0;
    config.value_range_max = 100;
    config.string_length = 50;
    config.compression_enabled = 1;

    pthread_mutex_unlock(&config_mutex);
}

// Function to manage memory for the data structures
void manage_memory(size_t num_elements) {
    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;

    // Allocate and initialize offsets and keys
    offsets = (long *)malloc(num_elements * sizeof(long));
    keys = (int *)malloc(num_elements * sizeof(int));
    records = (Record **)malloc(num_elements * sizeof(Record *));

    if (!offsets || !keys || !records) {
        log_message("Memory allocation failed");
        error_flag = 1;
        goto cleanup;
    }

    pthread_mutex_lock(&memory_mutex);
    current_memory_usage += num_elements * (sizeof(long) + sizeof(int) + sizeof(Record *));

    if (current_memory_usage > peak_memory_usage)
        peak_memory_usage = current_memory_usage;

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = i;
        keys[i] = rand() % 10000; // Ensure unique by choosing a large range
        records[i] = (Record *)malloc(sizeof(Record));

        if (!records[i]) {
            log_message("Memory allocation for record failed");
            error_flag = 1;
            goto cleanup;
        }

        current_memory_usage += sizeof(Record);

        // Initialize the record with random value and status
        records[i]->value = rand() % (config.value_range_max - config.value_range_min + 1) 
                            + config.value_range_min;
        records[i]->status = (rand() % 2 == 0) ? 'A' : 'B';
        size_t string_len = config.string_length;

        // Allocate and initialize the dynamic string
        records[i]->name = (char *)malloc(string_len);
        if (!records[i]->name) {
            log_message("Memory allocation for record name failed");
            error_flag = 1;
            free(records[i]);
            records[i] = NULL;
            current_memory_usage -= sizeof(Record);
            goto cleanup;
        }

        // Simulate string content
        snprintf(records[i]->name, string_len, "Record_%zu", i);
    }

    pthread_mutex_unlock(&memory_mutex);

cleanup:
    if (error_flag) {
        log_message("Error encountered, cleaning up.");
    }

    pthread_mutex_lock(&memory_mutex);
    free(offsets);
    free(keys);
    for (size_t i = 0; i < num_elements; ++i) {
        if (records[i]) {
            free(records[i]->name);
            free(records[i]);
            current_memory_usage -= sizeof(Record) + config.string_length;
        }
    }
    free(records);
    pthread_mutex_unlock(&memory_mutex);

    // Log memory usage statistics
    log_message("Memory management completed. Peak usage: ");
    printf("%zu\n", peak_memory_usage);
}

// Main function demonstrating multi-threaded execution
int main() {
    load_config();

    size_t num_elements = 1000; // Example number of elements to manage
    pthread_t threads[4];

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))manage_memory, &num_elements)) {
            log_message("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_join(threads[i], NULL)) {
            log_message("Failed to join thread");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

// Logging function implementation
void log_message(const char *message) {
    printf("%s\n", message);
}

// Performance monitoring functions implementation
static clock_t start_clock;

void start_timer() {
    start_clock = clock();
}

double stop_timer() {
    return (double)(clock() - start_clock) / CLOCKS_PER_SEC;
}
