['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_PATH_LENGTH 1024
#define MAX_RECORDS 1000

typedef struct {
    int value;
    char buffer[256];
    char *path;
} record_t;

int max_depth = 0;
pthread_mutex_t depth_mutex = PTHREAD_MUTEX_INITIALIZER;

int calculate_depth(const char *base_path, const char *current_path) {
    char path[MAX_PATH_LENGTH];
    snprintf(path, MAX_PATH_LENGTH, "%s/%s", base_path, current_path);
    int depth = 0;
    char *token = strtok(strdup(path), "/");
    while (token != NULL) {
        if (*token != '.') { // Skip '.' and '..'
            depth++;
        }
        token = strtok(NULL, "/");
    }

    pthread_mutex_lock(&depth_mutex);
    if (depth > max_depth) {
        max_depth = depth;
    }
    pthread_mutex_unlock(&depth_mutex);

    return depth;
}

void traverse_directory(const char *base_path, int current_depth) {
    DIR *dir = opendir(base_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char path[MAX_PATH_LENGTH];
        snprintf(path, MAX_PATH_LENGTH, "%s/%s", base_path, entry->d_name);

        struct stat st;
        if (stat(path, &st) != 0) continue;

        if (S_ISDIR(st.st_mode)) {
            traverse_directory(path, current_depth + 1);
        } else {
            // Process file
            calculate_depth(base_path, entry->d_name);
        }
    }

    closedir(dir);
}

void process_paths(size_t size) {
    long *file_offsets = malloc(size * sizeof(long));
    int *dir_indices = malloc(size * sizeof(int));
    record_t *records = malloc(size * sizeof(record_t));
    char **paths = malloc(size * sizeof(char *));
    if (!file_offsets || !dir_indices || !records || !paths) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    while (count < size && fgets(input_buffer, sizeof(input_buffer), stdin)) {
        char *path = strdup(input_buffer);
        if (!path) continue;

        paths[count] = path;
