// record_module.c

#include "record_module.h"
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_BUFFER_SIZE 256

Record records[MAX_RECORDS];
int num_records = 0;
pthread_mutex_t lock;

void init_module() {
    pthread_mutex_init(&lock, NULL);
}

// Function to add a record
int add_record(Record *record) {
    if (num_records >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&lock);

    // Ensure no two consecutive records have the same key
    if (num_records > 0 && records[num_records - 1].key == record->key) {
        pthread_mutex_unlock(&lock);
        return -2;
    }

    memcpy(records + num_records, record, sizeof(Record));
    num_records++;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to get a record by key
Record* get_record(int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }
    return NULL;
}

// Serialize records to file
void serialize_records(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&lock);
    fwrite(&num_records, sizeof(int), 1, file);

    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }

    pthread_mutex_unlock(&lock);
    fclose(file);
}

// Deserialize records from file
int deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int count;
    fread(&count, sizeof(int), 1, file);

    pthread_mutex_lock(&lock);
    num_records = 0;

    while (num_records < count && fread(records + num_records, sizeof(Record), 1, file)) {
        num_records++;
    }

    pthread_mutex_unlock(&lock);
    fclose(file);
    return 0;
}

// Validate NFA PDU structure
int validate_nfa_pdu(NFAPICRCIndicationPDU pdu, NFAPICRCIndicationPDU *prev_pdu) {
    if (pdu.crc_indication_rel8_tag < CRC_RANGE_MIN || 
        pdu.crc_indication_rel8_tag > CRC_RANGE_MAX) {
        return -1;
    }

    if (prev_pdu && prev_pdu->rnti == pdu.rnti) {
        return -2;
    }

    return 0;
}

