UserProfile* get_profile_by_name(const char *name) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.cache[i] && strcmp(cache.cache[i]->name, name) == 0) {
            cache.access_count[i]++;
            return cache.cache[i];
        }
    }

    // Check the main profile list
    for (int i = 0; i < profile_count; ++i) {
        if (strcmp(profiles[i]->name, name) == 0) {
            int least_accessed_index = -1;
            int min_access_count = CACHE_SIZE;

            for (int j = 0; j < CACHE_SIZE; ++j) {
                if (cache.access_count[j] < min_access_count) {
                    min_access_count = cache.access_count[j];
                    least_accessed_index = j;
