#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <queue>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <unordered_map>

namespace TransactionUtilities {

    enum class LogLevel {
        DEBUG,
        INFO,
        WARN,
        ERROR
    };

    struct LogEntry {
        LogLevel level;
        std::string message;
        std::string transactionId;
        std::string tag;
    };

    class TransactionLogger {
    public:
        static TransactionLogger& getInstance(const std::string& logFilePath, LogLevel defaultLevel, const std::string& transactionId);

        void setLogLevel(LogLevel level) { this->logLevel = level; }
        void addTagFilter(const std::string& tag);
        void removeTagFilter(const std::string& tag);

        template <typename... Args>
        void log(LogLevel level, const std::string& message, const std::string& tag = "") {
            if (level >= this->logLevel && (!tagFilters.empty() || tag.empty())) {
                LogEntry entry{level, message, transactionId, tag};
                std::lock_guard<std::mutex> lock(queueMutex);
                logQueue.push(entry);
                cv.notify_one();
            }
        }

        void flushLogs();
        void resetLogFilePath(const std::string& newPath);

    private:
        TransactionLogger(const std::string& logFilePath, LogLevel defaultLevel, const std::string& transactionId);
        ~TransactionLogger();

        static TransactionLogger* instance;
        std::ofstream logFile;
        LogLevel logLevel;
        std::string transactionId;
        std::mutex queueMutex;
        std::queue<LogEntry> logQueue;
        std::condition_variable cv;
        std::thread loggerThread;
        std::atomic<bool> running{true};
        std::unordered_set<std::string> tagFilters;

        void processLogs();

        // Prevent copying
        TransactionLogger(const TransactionLogger&) = delete;
        TransactionLogger& operator=(const TransactionLogger&) = delete;
    };

    TransactionLogger* TransactionLogger::instance = nullptr;

    TransactionLogger::TransactionLogger(const std::string& logFilePath, LogLevel defaultLevel, const std::string& transactionId)
        : logLevel(defaultLevel), transactionId(transactionId) {
        logFile.open(logFilePath, std::ios_base::app);
        loggerThread = std::thread(&TransactionLogger::processLogs, this);
    }

    TransactionLogger::~TransactionLogger() {
        running.store(false);
        cv.notify_all();
        if (loggerThread.joinable()) {
            loggerThread.join();
        }
        logFile.close();
    }

    void TransactionLogger::processLogs() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !logQueue.empty() || !running; });

            while (!logQueue.empty()) {
                LogEntry entry = logQueue.front();
                logQueue.pop();

                if (!tagFilters.count(entry.tag)) {
                    logFile << "[" << toString(entry.level) << "] [" << entry.transactionId << "] " << entry.message << std::endl;
                }
            }
        }

        // Flush remaining logs
        while (!logQueue.empty()) {
            LogEntry entry = logQueue.front();
            logQueue.pop();

            if (!tagFilters.count(entry.tag)) {
                logFile << "[" << toString(entry.level) << "] [" << entry.transactionId << "] " << entry.message << std::endl;
            }
        }
    }

    void TransactionLogger::flushLogs() {
        std::lock_guard<std::mutex> lock(queueMutex);
        cv.notify_one();
        logFile.flush();
    }

    void TransactionLogger::resetLogFilePath(const std::string& newPath) {
        std::lock_guard<std::mutex> lock(queueMutex);
        if (logFile.is_open()) {
            logFile.close();
        }
        logFile.open(newPath, std::ios_base::app);
    }

    TransactionLogger& TransactionLogger::getInstance(const std::string& logFilePath, LogLevel defaultLevel, const std::string& transactionId) {
        if (!instance) {
            instance = new TransactionLogger(logFilePath, defaultLevel, transactionId);
        }
        return *instance;
    }

    void TransactionLogger::addTagFilter(const std::string& tag) {
        std::lock_guard<std::mutex> lock(queueMutex);
        tagFilters.insert(tag);
    }

    void TransactionLogger::removeTagFilter(const std::string& tag) {
        std::lock_guard<std::mutex> lock(queueMutex);
        tagFilters.erase(tag);
    }

    std::string toString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO:  return "INFO";
            case LogLevel::WARN:  return "WARN";
            case LogLevel::ERROR: return "ERROR";
            default:              return "UNKNOWN";
        }
    }

} // namespace TransactionUtilities

int main() {
    auto& logger = TransactionUtilities::TransactionLogger::getInstance("transactions.log", TransactionUtilities::LogLevel::INFO, "TX12345");

    logger.log(TransactionUtilities::LogLevel::DEBUG, "Starting transaction processing");
    logger.addTagFilter("critical");
    logger.log(TransactionUtilities::LogLevel::WARN, "Low balance warning", "financial");
    logger.log(TransactionUtilities::LogLevel::ERROR, "Transaction failed due to network issue", "network");
    logger.removeTagFilter("critical");

    logger.flushLogs();
    return 0;
}
```']

