    config->string_length = 10;
    config->use_compression = 0; // Change to 1 for compression
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message("DNS resolution error: ");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr = &(p->ai_addr)->sin_addr;
        inet_ntop(p->ai_family, addr, ip_address, sizeof(in_addr_t));
        break;
    }

    freeaddrinfo(res);
    return 0;
}

void allocate_memory(long limit, int key_size, record **records, long **offsets, int **keys, int *error_flag) {
    pthread_mutex_lock(&mutex);

    *error_flag = 0;

    // Allocate and initialize offsets
    *offsets = malloc(limit * sizeof(long));
    if (*offsets == NULL) {
        *error_flag = 1;
        log_message("Error allocating memory for offsets");
        goto cleanup;
    }
    for (long i = 0; i < limit; ++i) {
        (*offsets)[i] = i;
    }

    // Allocate and initialize keys
    *keys = malloc(key_size * sizeof(int));
    if (*keys == NULL) {
        *error_flag = 1;
        log_message("Error allocating memory for keys");
        goto cleanup;
    }
    for (int i = 0; i < key_size; ++i) {
        (*keys)[i] = i;
    }

    // Allocate and initialize records
    *records = malloc(key_size * sizeof(record));
    if (*records == NULL) {
        *error_flag = 1;
        log_message("Error allocating memory for records");
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    config_t config;
    initialize_config(&config);

    for (int i = 0; i < key_size; ++i) {
        (*records)[i].value = rand() % (config.range_max - config.range_min + 1) + config.range_min;
        (*records)[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        char buffer[config.string_length + 1];
        for (int j = 0; j < config.string_length; ++j) {
            buffer[j] = 'a' + rand() % 26;
        }
        buffer[config.string_length] = '\0';

        if (config.use_compression) {
            unsigned char *compressed_str;
            size_t compressed_size = compress_string(buffer, strlen(buffer), &compressed_str);
            if (compressed_size == 0) {
                *error_flag = 1;
                log_message("Error compressing string");
                free(compressed_str);
                goto cleanup;
            }
            (*records)[i].dynamic_string = malloc(compressed_size);
            if ((*records)[i].dynamic_string == NULL) {
                *error_flag = 1;
                log_message("Error allocating memory for compressed string");
                free(compressed_str);
                goto cleanup;
            }
            memcpy((*records)[i].dynamic_string, compressed_str, compressed_size);
            free(compressed_str);
        } else {
            (*records)[i].dynamic_string = strdup(buffer);
            if ((*records)[i].dynamic_string == NULL) {
                *error_flag = 1;
                log_message("Error duplicating string");
                goto cleanup;
            }
        }
    }

    pthread_mutex_unlock(&mutex);
    return;

cleanup:
    deallocate_memory(records, offsets, keys, key_size);

    pthread_mutex_unlock(&mutex);
}

void deallocate_memory(record **records, long *offsets, int *keys, size_t records_count) {
    if (*records != NULL) {
        for (size_t i = 0; i < records_count; ++i) {
            free((*records)[i].dynamic_string);
        }
        free(*records);
        log_message("Deallocated memory for records");
    }
    if (offsets != NULL) {
        free(offsets);
        log_message("Deallocated memory for offsets");
    }
    if (keys != NULL) {
        free(keys);
        log_message("Deallocated memory for keys");
    }
}
