    if (!record->data) {
        free(record);
        fprintf(stderr, "Data memory allocation failed\n");
        return NULL;
    }
    return record;
}

// Function to serialize a record using MessagePack (mocked)
void serialize_record(Record *record) {
    pthread_mutex_lock(&data_mutex);
    // Mock serialization logic
    printf("Serializing record of size %zu\n", record->size);
    pthread_mutex_unlock(&data_mutex);
}

// Asynchronous upload function
void* async_upload(void *arg) {
    Record *record = (Record*) arg;
    int retries = 3;

    while (retries--) {
        if (serialize_record(record)) {
            printf("Upload successful\n");
            break;
        } else {
            fprintf(stderr, "Upload failed, retrying...\n");
            sleep(1); // Simulate wait before retry
        }
    }

    if (!retries) {
        fprintf(stderr, "Failed to upload record after retries\n");
    }

    return NULL;
}

// Function to process data and manage records
void process_data() {
    pthread_t threads[5];
    Record *records[5];

    // Allocate records based on configuration
    for (int i = 0; i < 5; ++i) {
        if (current_count >= max_records) {
            fprintf(stderr, "Max record limit reached\n");
            return;
        }
        records[i] = allocate_record(i == 0 ? timestamp_config : measurement_config);
        if (!records[i]) {
            // Handle allocation failure
            continue;
        }
        current_count++;
    }

    // Start asynchronous uploads
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, async_upload, records[i]);
    }

    // Join threads
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
        free(records[i]->data);
        free(records[i]);
    }
}

// Function to initialize the system
void init_system() {
    pthread_mutex_init(&data_mutex, NULL);
    load_configuration();
}

// Main function
int main() {
    init_system();

    while (1) { // Simulate continuous processing
        process_data();
        sleep(2); // Simulate time between data batches
    }

    pthread_mutex_destroy(&data_mutex);
    free(timestamp_config.fields);
    free(measurement_config.fields);

    return 0;
}
