void add_network_connection(ConnectionList *list, const char *client_ip, int port_number, float flow_rate_indicator) {
    if (list->current_size >= list->max_size) {
        // Dynamic memory adjustment based on load
        size_t new_size = list->max_size + 256;
        NetworkConnection* temp_list = realloc(list->connections, new_size * sizeof(NetworkConnection));

        if (!temp_list) {
