#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DOCUMENTS 10000
#define METADATA_SIZE 1024

typedef struct {
    unsigned char *content;
    size_t content_size;
} FileContent;

typedef struct {
    char metadata[METADATA_SIZE];
    int document_size;
    FileContent *file_content;
} MetadataEntry;

typedef struct {
    pthread_mutex_t lock;
    MetadataEntry *entries;
    size_t count;
    size_t capacity;
} DocumentManager;

DocumentManager* init_document_manager() {
    DocumentManager *manager = malloc(sizeof(DocumentManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->entries = calloc(MAX_DOCUMENTS, sizeof(MetadataEntry));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = MAX_DOCUMENTS;
    return manager;
}

int process_document(DocumentManager *manager, const char *metadata, int document_size, unsigned char *file_content) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_DOCUMENTS) {
        fprintf(stderr, "Document limit reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    MetadataEntry *entry = &manager->entries[manager->count++];
    strncpy(entry->metadata, metadata, METADATA_SIZE - 1);
    entry->metadata[METADATA_SIZE - 1] = '\0';
    entry->document_size = document_size;

    entry->file_content = malloc(sizeof(FileContent));
    if (!entry->file_content) {
        fprintf(stderr, "Memory allocation failed for file content.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    entry->file_content->content = malloc(document_size);
    if (!entry->file_content->content) {
        free(entry->file_content);
        fprintf(stderr, "Memory allocation failed for document content.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    memcpy(entry->file_content->content, file_content, document_size);
    entry->file_content->content_size = document_size;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_document_manager(DocumentManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i].file_content->content);
        free(manager->entries[i].file_content);
    }

    free(manager->entries);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int serialize_document_manager(DocumentManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(manager->entries[i].metadata, sizeof(char), METADATA_SIZE, file);
        int document_size = manager->entries[i].document_size;
        fwrite(&document_size, sizeof(int), 1, file);

        unsigned char *content = manager->entries[i].file_content->content;
        size_t content_size = manager->entries[i].file_content->content_size;
        fwrite(content, sizeof(unsigned char), content_size, file);
    }

    fclose(file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int deserialize_document_manager(DocumentManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (count > MAX_DOCUMENTS) {
        fprintf(stderr, "Document limit exceeded in file.\n");
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
        MetadataEntry *entry = &manager->entries[i];
        fread(entry->metadata, sizeof(char), METADATA_SIZE, file);

        int document_size;
        fread(&document_size, sizeof(int), 1, file);
        entry->document_size = document_size;

        entry->file_content = malloc(sizeof(FileContent));
        if (!entry->file_content) {
            fprintf(stderr, "Memory allocation failed for file content.\n");
            fclose(file);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        entry->file_content->content = malloc(document_size);
        if (!entry->file_content->content) {
            free(entry->file_content);
            fprintf(stderr, "Memory allocation failed for document content.\n");
            fclose(file);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        fread(entry->file_content->content, sizeof(unsigned char), document_size, file);
        entry->file_content->content_size = document_size;
    }

    manager->count = count;
    fclose(file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}
