// Check for integer overflow
int is_safe_multiplication(size_t a, size_t b) {
    if (a == 0 || b <= SIZE_MAX / a)
        return 1;
    return 0;
}

// Allocate memory with checks
void *safe_malloc(size_t num_elements, size_t element_size) {
    if (!is_safe_multiplication(num_elements, element_size)) {
        log_error("Integer overflow detected in memory allocation.");
        return NULL;
    }

    void *memory = malloc(num_elements * element_size);
    if (memory == NULL || num_elements * element_size > MAX_MEMORY) {
        log_error("Memory allocation failed or exceeded system limit.");
        free(memory); // Free any partially allocated memory
        return NULL;
    }
    return memory;
}

// Initialize and manage OffsetRecords array
OffsetRecord **manage_offset_records(size_t num_elements) {
    if (!is_safe_multiplication(num_elements, sizeof(OffsetRecord *))) {
        log_error("Integer overflow detected in offset record allocation.");
        return NULL;
    }

    OffsetRecord **offset_array = safe_malloc(num_elements, sizeof(OffsetRecord *));
    if (offset_array == NULL)
        return NULL;

    for (size_t i = 0; i < num_elements; ++i) {
        offset_array[i] = safe_malloc(1, sizeof(OffsetRecord));
        if (offset_array[i] == NULL) {
            // Free previously allocated memory on error
            while (i > 0) {
                free(offset_array[--i]);
            }
            free(offset_array);
            return NULL;
        }
    }

    return offset_array;
}

// Initialize and manage KeyRecords array with segmentation
KeyRecord **manage_key_records(size_t num_elements, OffsetRecord **offset_records) {
    if (!is_safe_multiplication(num_elements, sizeof(KeyRecord *))) {
        log_error("Integer overflow detected in key record allocation.");
        return NULL;
    }

    size_t segment_size = num_elements / 4; // Divide into 4 segments
    KeyRecord ***segments = safe_malloc(4, sizeof(KeyRecord **));
    if (segments == NULL)
        return NULL;

    for (int i = 0; i < 4; ++i) {
        segments[i] = safe_malloc(segment_size, sizeof(KeyRecord *));
        if (segments[i] == NULL) {
            // Free previously allocated memory on error
            while (i > 0) {
                free(segments[--i]);
            }
            free(segments);
            return NULL;
        }

        for (size_t j = 0; j < segment_size; ++j) {
            size_t index = i * segment_size + j;
            segments[i][j] = safe_malloc(1, sizeof(KeyRecord));
            if (segments[i][j] == NULL) {
                // Free previously allocated memory on error
                while (j > 0) {
                    free(segments[i][--j]);
                }
                free(segments[i]);
                continue;
