            segments[i][j]->value = j; // Initialize with some value
            if (index < num_elements)
                segments[i][j]->offset_record_ptr = offset_records[index];
        }
    }

    return (KeyRecord **)segments[0]; // Flatten the array for simplicity
}

// Custom random number generator - Linear Congruential Generator
uint32_t lcg_state;

uint32_t custom_random() {
    lcg_state = lcg_state * 1664525 + 1013904223;
    return (lcg_state >> 16) & 0x7FFF; // Return a value between 0 and 32767
}

// Thread-safe random number generator using thread-local storage
uint32_t generate_random() {
    static __thread uint32_t seed = rand(); // Initialize with system random
    return (custom_random() + seed) % 101;
