            pthread_create(&threads[i / chunk_size], NULL, initialize_random_value, &indices[i]);
        }
    }

    for (size_t i = 0; i < num_elements / chunk_size + 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return random_array;
}

