    char description[MAX_DESC];
    time_t dueDate;
    int priorityLevel;
    int userId;
    TaskType type;
    TaskState state;
    struct Task *next;
} Task;

typedef struct TaskList {
    Task *head;
    size_t listSize;
    pthread_mutex_t lock;
} TaskList;

TaskList scheduledTasks, recurringTasks, oneTimeTasks, completedTasks, archivedTasks;

size_t totalMemoryAllocated = 0;

void initializeTaskList(TaskList *list) {
    list->head = NULL;
    list->listSize = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void addTask(TaskList *taskList, Task *newTask) {
    if (totalMemoryAllocated + sizeof(Task) > MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }

    pthread_mutex_lock(&taskList->lock);

    newTask->next = taskList->head;
    taskList->head = newTask;
    taskList->listSize++;
    totalMemoryAllocated += sizeof(Task);

    // Memory management and cleanup not shown for brevity

    pthread_mutex_unlock(&taskList->lock);
}

void serializeTasks(const TaskList *taskList, FILE *file) {
    pthread_mutex_lock(&taskList->lock);

    Task *current = taskList->head;
    while (current != NULL) {
        fwrite(current, sizeof(Task), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&taskList->lock);
}

void deserializeTasks(TaskList *taskList, FILE *file) {
    pthread_mutex_lock(&taskList->lock);

    Task taskBuffer;
    while (fread(&taskBuffer, sizeof(Task), 1, file)) {
        Task *newTask = malloc(sizeof(Task));
        if (!newTask) {
            perror("Failed to allocate memory for new task");
            break;
        }
        memcpy(newTask, &taskBuffer, sizeof(Task));

        addTask(taskList, newTask);
    }

    pthread_mutex_unlock(&taskList->lock);
}

void generateReport(const TaskList *scheduledTasks, const TaskList *recurringTasks,
                    const TaskList *oneTimeTasks, const TaskList *completedTasks) {
    size_t totalTasks = scheduledTasks->listSize + recurringTasks->listSize +
                        oneTimeTasks->listSize + completedTasks->listSize;
    printf("Total Tasks: %zu\n", totalTasks);

    // Additional reporting logic not shown for brevity
}

