    while (current != NULL) {
        fprintf(file, "%s,%s,%ld,%d,%d,%d,%d\n", current->taskName,
                current->description, current->dueDate,
                current->priorityLevel, current->userId,
                current->type, current->state);

        current = current->next;
    }

    fclose(file);
}

