    initializeTaskList(&recurringTasks);
    initializeTaskList(&oneTimeTasks);
    initializeTaskList(&completedTasks);
    initializeTaskList(&archivedTasks);

    // Add tasks, serialize/deserialize, generate reports, etc.

    return 0;
}
