#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define PATH_MAX 4096

typedef struct {
    int value;
    char metadata[256];
    char *path;
    int metadata_field;
} Record;

typedef struct {
    long *fd_offsets;
    int *dir_indices;
    Record **records;
    char **paths;
    int *metadata;
    size_t count;
} FileSystemData;

void log_operation(const char *operation, const char *path) {
    FILE *log_file = fopen("operations.log", "a");
    if (!log_file) return;
    time_t now = time(NULL);
    fprintf(log_file, "%s - %s: %s\n", ctime(&now), operation, path);
    fclose(log_file);
}

int allocate_memory(FileSystemData *data, size_t record_count) {
    data->fd_offsets = malloc(record_count * sizeof(long));
    data->dir_indices = malloc(record_count * sizeof(int));
    data->records = malloc(record_count * sizeof(Record *));
    data->paths = malloc(record_count * sizeof(char *));
    data->metadata = malloc(record_count * sizeof(int));

    if (!data->fd_offsets || !data->dir_indices || !data->records ||
        !data->paths || !data->metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    memset(data->fd_offsets, 0, record_count * sizeof(long));
    memset(data->dir_indices, 0, record_count * sizeof(int));
    memset(data->records, 0, record_count * sizeof(Record *));
    memset(data->paths, 0, record_count * sizeof(char *));
    memset(data->metadata, 0, record_count * sizeof(int));

    data->count = 0;
    return 0;
}

void free_memory(FileSystemData *data) {
    for (size_t i = 0; i < data->count; ++i) {
        if (data->records[i]) {
            free(data->records[i]->metadata);
            free(data->records[i]);
        }
        free(data->paths[i]);
    }
    free(data->fd_offsets);
    free(data->dir_indices);
    free(data->records);
    free(data->paths);
    free(data->metadata);
}

int get_directory_depth(const char *path) {
    int depth = 0;
    const char *p = path;

    while (*p == '/') p++;
    while (*p) {
        if (*p == '/') depth++;
        p++;
    }
    return depth;
}

void process_path(FileSystemData *data, const char *path) {
    if (data->count >= MAX_RECORDS) {
        fprintf(stderr, "Max record count exceeded\n");
        return;
    }

    Record *record = malloc(sizeof(Record));
    record->value = rand();  // Example value
    snprintf(record->metadata, sizeof(record->metadata), "Metadata for %s", path);
    record->path = strdup(path);
    record->metadata_field = rand();  // Example metadata

    data->records[data->count] = record;
    data->paths[data->count] = strdup(path);

    log_operation("Process Path", path);

    data->count++;
}

void find_largest_depth(FileSystemData *data) {
    int max_depth = -1;
    char *deepest_path = NULL;

    for (size_t i = 0; i < data->count; ++i) {
        int depth = get_directory_depth(data->paths[i]);
        if (depth > max_depth) {
            max_depth = depth;
            deepest_path = data->paths[i];
        }
    }

    if (deepest_path) {
        printf("Path with largest directory depth: %s\n", deepest_path);
    } else {
        printf("No valid paths found\n");
    }
}

void *read_paths(void *arg) {
    FileSystemData *data = (FileSystemData *)arg;
    char path[PATH_MAX];

    while (fgets(path, sizeof(path), stdin)) {
        size_t len = strlen(path);
        if (len > 0 && path[len - 1] == '\n') path[--len] = '\0';
        process_path(data, path);
    }

    return NULL;
}

void serialize(FileSystemData *data, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        return;
    }
    fwrite(&data->count, sizeof(size_t), 1, file);
    fwrite(data->paths, sizeof(char *), data->count, file);

    for (size_t i = 0; i < data->count; ++i) {
        size_t len = strlen(data->paths[i]) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(data->paths[i], sizeof(char), len, file);
    }
    fclose(file);
}

void deserialize(FileSystemData *data, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return;
    }

    fread(&data->count, sizeof(size_t), 1, file);
    data->paths = malloc(data->count * sizeof(char *));
    fseek(file, data->count * sizeof(char *), SEEK_CUR);

    for (size_t i = 0; i < data->count; ++i) {
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        char *path = malloc(len);
        fread(path, sizeof(char), len, file);
        data->paths[i] = path;
    }
    fclose(file);
}

void compress_data(const void *data, size_t length) {
    // Implement a custom compression algorithm here
}

void decompress_data(void *dest, const void *src, size_t length) {
    // Implement a custom decompression algorithm here
}

void put_resource(int id, const char *body) {
    // Simulate updating resource via HTTP PUT
    printf("Resource %d updated with body: %s\n", id, body);
}

void delete_resource(int id) {
    // Simulate deleting resource via HTTP DELETE
    printf("Resource %d deleted\n", id);
}

int main() {
    FileSystemData data;
    if (allocate_memory(&data, MAX_RECORDS) != 0) return EXIT_FAILURE;

    pthread_t reader_thread;
    pthread_create(&reader_thread, NULL, read_paths, &data);
    pthread_join(reader_thread, NULL);

    find_largest_depth(&data);

    serialize(&data, "filesystem_data.bin");
    deserialize(&data, "filesystem_data.bin");

    free_memory(&data);

    return EXIT_SUCCESS;
}
