#define MAX_METADATA_SIZE 1024
#define MAX_ITEMS 100

typedef struct {
    char content[256]; // Assuming max name size from predefined set
} Item;

typedef struct MetadataEntry {
    char buffer[MAX_METADATA_SIZE];
    int documentSize;
    unsigned char* fileContent;
} MetadataEntry;

typedef struct FileContent {
    unsigned char* data;
    size_t size;
} FileContent;

typedef struct DocumentData {
    long *fileOffsets;
    int *docIds;
    MetadataEntry *metadataEntries;
    FileContent *fileContents;
    int documentCount;
    int maxDocuments;
} DocumentData;

DocumentData* initialize_document_data(int maxDocs) {
    if (maxDocs <= 0) return NULL;

    DocumentData* docData = malloc(sizeof(DocumentData));
    if (!docData) {
        fprintf(stderr, "Failed to allocate memory for DocumentData.\n");
        return NULL;
    }

    docData->fileOffsets = malloc(maxDocs * sizeof(long));
    docData->docIds = malloc(maxDocs * sizeof(int));
    docData->metadataEntries = malloc(maxDocs * sizeof(MetadataEntry));
    docData->fileContents = malloc(maxDocs * sizeof(FileContent));
    if (!docData->fileOffsets || !docData->docIds ||
        !docData->metadataEntries || !docData->fileContents) {
        fprintf(stderr, "Failed to allocate memory for document structures.\n");
        free(docData->fileOffsets);
        free(docData->docIds);
        free(docData->metadataEntries);
        free(docData->fileContents);
        free(docData);
        return NULL;
    }

    docData->documentCount = 0;
    docData->maxDocuments = maxDocs;

    for (int i = 0; i < maxDocs; ++i) {
        memset(&docData->metadataEntries[i].buffer, 0, MAX_METADATA_SIZE);
        docData->metadataEntries[i].fileContent = NULL;
        docData->fileContents[i].data = NULL;
        docData->fileContents[i].size = 0;
    }

    return docData;
}

void free_document_data(DocumentData* docData) {
    if (!docData) return;

    for (int i = 0; i < docData->documentCount; ++i) {
        free(docData->metadataEntries[i].fileContent);
        free(docData->fileContents[i].data);
    }

    free(docData->fileOffsets);
    free(docData->docIds);
    free(docData->metadataEntries);
    free(docData->fileContents);
    free(docData);
}

int add_document(DocumentData* docData, const char* content) {
    if (!docData || !content || docData->documentCount >= docData->maxDocuments) {
        fprintf(stderr, "Invalid input or document limit reached.\n");
        return -1;
    }

    int docId = docData->documentCount++;
    long offset = rand() % 1000000; // Simulate file offset
    size_t contentSize = strlen(content);

    char* randomMetadata = malloc(MAX_METADATA_SIZE);
    if (!randomMetadata) {
        fprintf(stderr, "Failed to allocate memory for metadata.\n");
        return -1;
    }

    const char* charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < MAX_METADATA_SIZE - 1 && i < contentSize; ++i) {
        randomMetadata[i] = charset[rand() % strlen(charset)];
    }
    randomMetadata[MAX_METADATA_SIZE - 1] = '\0';

    docData->fileOffsets[docId] = offset;
    docData->docIds[docId] = docId;

    strncpy(docData->metadataEntries[docId].buffer, randomMetadata, MAX_METADATA_SIZE);
    free(randomMetadata);

    docData->metadataEntries[docId].documentSize = contentSize;

    unsigned char* fileContent = malloc(contentSize);
    if (!fileContent) {
        fprintf(stderr, "Failed to allocate memory for document content.\n");
        return -1;
    }

    memcpy(fileContent, content, contentSize);
    docData->metadataEntries[docId].fileContent = fileContent;

    FileContent* fileCont = &docData->fileContents[docId];
    fileCont->data = malloc(contentSize);
    if (!fileCont->data) {
        fprintf(stderr, "Failed to allocate memory for file content.\n");
        free(fileContent);
        return -1;
    }

    memcpy(fileCont->data, content, contentSize);
    fileCont->size = contentSize;

    return 0;
}

void serialize_document_data(DocumentData* docData, const char* fileName) {
    if (!docData || !fileName) return;

    FILE *file = fopen(fileName, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", fileName);
        return;
    }

    fwrite(&docData->documentCount, sizeof(int), 1, file);
    fwrite(docData->fileOffsets, sizeof(long), docData->documentCount, file);
    fwrite(docData->docIds, sizeof(int), docData->documentCount, file);

    for (int i = 0; i < docData->documentCount; ++i) {
        fwrite(&docData->metadataEntries[i].documentSize, sizeof(int), 1, file);
        fwrite(docData->metadataEntries[i].buffer, MAX_METADATA_SIZE, 1, file);
        if (docData->metadataEntries[i].fileContent) {
            fwrite(docData->metadataEntries[i].fileContent, docData->metadataEntries[i].documentSize, 1, file);
        }
    }

    fclose(file);
}

int deserialize_document_data(DocumentData* docData, const char* fileName) {
    if (!docData || !fileName) return -1;

    FILE *file = fopen(fileName, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading: %s\n", fileName);
        return -1;
    }

    int docCount;
    fread(&docCount, sizeof(int), 1, file);

    if (docData->documentCount != 0 || docCount > docData->maxDocuments) {
        fprintf(stderr, "Inconsistent document count.\n");
        fclose(file);
        return -1;
    }

    fread(docData->fileOffsets, sizeof(long), docCount, file);
    fread(docData->docIds, sizeof(int), docCount, file);

    for (int i = 0; i < docCount; ++i) {
        int size;
        fread(&size, sizeof(int), 1, file);
        fread(docData->metadataEntries[i].buffer, MAX_METADATA_SIZE, 1, file);

        unsigned char* content = malloc(size);
        if (!content) {
            fprintf(stderr, "Failed to allocate memory for deserializing document content.\n");
            fclose(file);
            return -1;
        }

        fread(content, size, 1, file);
        docData->metadataEntries[i].documentSize = size;
        docData->metadataEntries[i].fileContent = content;

        FileContent* fileCont = &docData->fileContents[i];
        fileCont->data = malloc(size);
        if (!fileCont->data) {
            fprintf(stderr, "Failed to allocate memory for deserializing file content.\n");
            free(content);
            fclose(file);
            return -1;
        }

        memcpy(fileCont->data, content, size);
        fileCont->size = size;
    }

    docData->documentCount = docCount;

    fclose(file);

    return 0;
}

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

Node* create_item_list(int n) {
    if (n <= 0 || n > MAX_ITEMS) return NULL;

    const char* names[] = {"Apple", "Banana", "Cherry"};
    Node* head = malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for item list.\n");
        return NULL;
    }

    head->next = NULL;
    Node *current = head;

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < n; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Failed to allocate memory for new node.\n");
            break;
        }

        strcpy(newNode->item.content, names[rand() % 3]);
        newNode->item.id = i;
        newNode->item.quantity = rand() % 100; // Random quantity

        current->next = newNode;
        current = newNode;

        if (i == n - 1) {
            current->next = NULL;
        }
    }

    return head;
}

void free_item_list(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

void update_quantities(Node* head, int (*callback)(Item*)) {
    if (!head || !callback) return;

    Node* current = head->next; // Skip dummy head node
    while (current) {
        current->item.quantity = callback(&current->item);
        current = current->next;
    }
}

int increase_quantity(Item* item) {
    return item->quantity + 10; // Example increment
}

void print_items(Node* head) {
    Node* current = head->next;
    while (current) {
        printf("ID: %d, Name: %s, Quantity: %d\n", current->item.id, current->item.content, current->item.quantity);
        current = current->next;
    }
}

int main() {
    DocumentData* docData = initialize_document_data(10);
    if (!docData) return EXIT_FAILURE;

    add_document(docData, "This is a test document.");
    serialize_document_data(docData, "documents.dat");
    deserialize_document_data(docData, "documents.dat");

    Node* itemList = create_item_list(5);
    if (itemList) {
        update_quantities(itemList, increase_quantity);
        print_items(itemList);
        free_item_list(itemList);
    }

    free_document_data(docData);

    return EXIT_SUCCESS;
}
