    bool loadFromJson(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            return false;
        }

        json j;
        file >> j;

        for (auto& item : j.items()) {
            NetworkServiceConfig service = {
                .name = item.value()["name"],
                .port = item.value()["port"],
                .protocol = item.value()["protocol"],
                .callback = nullptr,  // Assign real callbacks based on config
                .priority = item.value()["priority"]
            };

            std::lock_guard<std::mutex> lock(configMutex);
            if (!service.validate() || services.find(service.name) != services.end()) {
                return false; // Invalid or duplicate service
            }

            services[service.name] = service;
        }

        return true;
    }

    void initializeServices() {
        std::vector<std::thread> threads;

        for (const auto& [name, config] : services) {
            threads.emplace_back([this, &config]() {
                // Load balancing and failover logic can be added here
                std::cout << "Initializing service: " << config.name << std::endl;
                // Simulate handling connections using the callback
                if (config.callback != nullptr) {
                    config.callback(config.port);
