void initialize_structures(double** double_array, size_t array_size,
                           Node*** node_array, size_t node_count,
                           Element*** element_list, size_t element_count,
                           int is_circular) {
    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of doubles and fill with random values
    *double_array = (double*)malloc(array_size * sizeof(double));
    if (*double_array == NULL) {
        perror("Failed to allocate double array");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array_size; ++i) {
        // Fill with random doubles between 0.0 and 1.0
        (*double_array)[i] = ((double)rand() / RAND_MAX);
    }

    // Allocate memory for the node array
    *node_array = (Node**)malloc(node_count * sizeof(Node*));
    if (*node_array == NULL) {
        perror("Failed to allocate node array");
        exit(EXIT_FAILURE);
    }

    // Initialize nodes and create a linked list
    Node* prev_node = NULL;
    for (size_t i = 0; i < node_count; ++i) {
        (*node_array)[i] = create_node((*double_array)[rand() % array_size]);

        if (prev_node != NULL) {
            prev_node->next = (*node_array)[i];
        }

        prev_node = (*node_array)[i];
    }

    // Allocate memory for the element list
    *element_list = (Element**)malloc(element_count * sizeof(Element*));
    if (*element_list == NULL) {
        perror("Failed to allocate element list");
        exit(EXIT_FAILURE);
    }

    Node* head = (*node_array)[0];  // Assume first node as head for initialization

    for (size_t i = 0; i < element_count; ++i) {
        (*element_list)[i] = (Element*)malloc(sizeof(Element));
        if ((*element_list)[i] == NULL) {
            perror("Failed to allocate element");
            exit(EXIT_FAILURE);
        }

        (*element_list)[i]->key = rand() % 1000; // Assign random key
        (*element_list)[i]->list_head = head;
    }

    // If circular, make the list circular by linking last node to head
    if (is_circular && prev_node != NULL) {
        prev_node->next = head;
    } else {
        if (prev_node != NULL) {
            prev_node->next = NULL;  // Terminate the linear list
        }
    }
}

// Function to create a new node with given value
Node* create_node(double value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }

    new_node->value = value;
    new_node->next = NULL;

    return new_node;
}

// Function to free the linked list
void free_linked_list(Node* head, int is_circular) {
    if (is_circular && head != NULL) {
        // Break circularity for freeing
        Node* current = head;
        while (current->next != head) {
            current = current->next;
        }
        current->next = NULL;  // Now it's linear
    }

    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

