    for (size_t i = 0; i < 5; ++i) {
        free(nodes_array[i]);
    }
    free(nodes_array);

    for (size_t i = 0; i < 3; ++i) {
        free(elements_list[i]);
    }
    free(elements_list);

    free(array_of_doubles);

