```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    float data;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

// Initialize the record list
void initRecordList(RecordList *list) {
    list->capacity = 10; // Initial capacity
    list->count = 0;
    list->records = (Record *)malloc(list->capacity * sizeof(Record));
    if (!list->records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

// Resize the record array
void resizeIfNeeded(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Record *new_records = (Record *)realloc(list->records, new_capacity * sizeof(Record));
        if (!new_records) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

// Add a new record
void addRecord(RecordList *list, long offset, float data) {
    resizeIfNeeded(list);

    pthread_mutex_lock(&list->lock);
    list->records[list->count].offset = offset;
    list->records[list->count].data = data;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Remove a record by index
void removeRecord(RecordList *list, size_t index) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = index; i < list->count - 1; ++i) {
        list->records[i] = list->records[i + 1];
    }
    list->count--;

    // Optional: Shrink the array if it's too sparse
    if (list->capacity > 10 && list->count < list->capacity / 4) {
        size_t new_capacity = list->capacity / 2;
        Record *new_records = (Record *)realloc(list->records, new_capacity * sizeof(Record));
        if (new_records) {
            list->records = new_records;
            list->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Update data using a transformation function
void updateRecords(RecordList *list, float (*transform)(float)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->records[i].data = transform(list->records[i].data);
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the record list
void freeRecordList(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    free(list->records);
    list->records = NULL;
    list->capacity = 0;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example transformation function
float exampleTransform(float data) {
    return data * 2.0f; // Simple doubling for demonstration
}

int main() {
    RecordList list;
    initRecordList(&list);

    addRecord(&list, 1, 10.5);
    addRecord(&list, 2, 20.3);

    updateRecords(&list, exampleTransform);

    removeRecord(&list, 0);

    freeRecordList(&list);

    return 0;
}
```

### Key Points:
- **Memory Management**: Uses dynamic memory allocation with `malloc` and `realloc`, resizing the array as needed.
- **Thread Safety**: Utilizes a mutex to ensure thread-safe operations on the list.
- **Resource Management**: Ensures proper cleanup of resources using `free` and `pthread_mutex_destroy`.
- **Scalability**: The list can grow dynamically, but you may need to adjust initial capacity based on expected usage.
- **Maintainability**: Code is modular with clear separation of concerns for initialization, resizing, adding, removing, updating, and freeing records.']

