Node* create_circular_doubly_linked_list(size_t num_nodes);
Element** initialize_2d_grid(int rows, int cols, Node* circular_list);
void resize_2d_grid(Element*** grid, int* current_rows, int* current_cols, int new_rows, int new_cols, Node* circular_list);

// Initialize the array of doubles with random numbers
void initialize_double_array(double** arr, size_t size) {
    *arr = (double*)malloc(size * sizeof(double));
    if (*arr == NULL) {
        fprintf(stderr, "Memory allocation failed for double array.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL)); // Seed random number generator
    for (size_t i = 0; i < size; ++i) {
        (*arr)[i] = ((double)rand() / RAND_MAX) * 100.0; // Random values between 0 and 100
    }
}

// Create a circular doubly linked list with nodes containing random double values
Node* create_circular_doubly_linked_list(size_t num_nodes) {
    Node* head = NULL;
    for (size_t i = 0; i < num_nodes; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed for linked list node.\n");
            exit(EXIT_FAILURE);
        }
        new_node->value = ((double)rand() / RAND_MAX) * 100.0; // Random values between 0 and 100

        if (head == NULL) { // First node
            head = new_node;
            head->prev = head;
            head->next = head;
        } else {
            Node* last = head->prev;

            new_node->next = head;
            new_node->prev = last;
            last->next = new_node;
            head->prev = new_node;
        }
    }
    return head;
}

// Initialize a 2D grid of Elements
Element** initialize_2d_grid(int rows, int cols, Node* circular_list) {
    Element** grid = (Element**)malloc(rows * sizeof(Element*));
    if (grid == NULL) {
        fprintf(stderr, "Memory allocation failed for 2D grid.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < rows; ++i) {
        grid[i] = (Element*)malloc(cols * sizeof(Element));
        if (grid[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for row %d in 2D grid.\n", i);
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < cols; ++j) {
            grid[i][j].key = rand() % 100; // Random keys
            grid[i][j].linked_list_ptr = circular_list;
            circular_list = circular_list->next; // Cycle through the list to assign pointers
        }
    }

    return grid;
}

// Resize the 2D grid of Elements while maintaining linked list integrity
void resize_2d_grid(Element*** grid, int* current_rows, int* current_cols, int new_rows, int new_cols, Node* circular_list) {
    Element** new_grid = (Element**)malloc(new_rows * sizeof(Element*));
    if (new_grid == NULL) {
        fprintf(stderr, "Memory allocation failed for resized 2D grid.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < new_rows; ++i) {
        new_grid[i] = (Element*)malloc(new_cols * sizeof(Element));
        if (new_grid[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for row %d in resized 2D grid.\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Copy data from old grid to new grid
    int copy_rows = (*current_rows < new_rows) ? *current_rows : new_rows;
    int copy_cols = (*current_cols < new_cols) ? *current_cols : new_cols;

    for (int i = 0; i < copy_rows; ++i) {
        for (int j = 0; j < copy_cols; ++j) {
            new_grid[i][j] = (*grid)[i][j];
        }
    }

    // Free old grid
    for (int i = 0; i < *current_rows; ++i) {
        free((*grid)[i]);
    }
    free(*grid);

    // Assign resized dimensions
    *grid = new_grid;
    *current_rows = new_rows;
    *current_cols = new_cols;

    // Re-initialize the remaining rows and columns if any
    for (int i = copy_rows; i < new_rows; ++i) {
        for (int j = 0; j < new_cols; ++j) {
            (*grid)[i][j].key = rand() % 100;
            (*grid)[i][j].linked_list_ptr = circular_list;
            circular_list = circular_list->next;
        }
    }
}

