    resize_2d_grid(&element_grid, &grid_rows, &grid_cols, 10, 10, linked_list_head);

    // Free allocated memory
    for (int i = 0; i < grid_rows; ++i) {
        free(element_grid[i]);
    }
    free(element_grid);

    Node* current = linked_list_head;
    do {
        Node* temp = current->next;
        free(current);
        current = temp;
    } while (current != linked_list_head);

    free(double_array);

    return 0;
}
