#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    double value;
    struct node *next;
} Node;

typedef struct element {
    int key;
    Node *linked_list;
} Element;

typedef struct TrafficEvent {
    time_t timestamp;
    char event_type[50];
    int unique_id;
    int severity_level;
    double latitude;
    double longitude;
} TrafficEvent;

// Function prototypes
Node* create_node(double value);
Element* initialize_element(int key, Node *linked_list);
void free_linked_list(Node *head, int is_circular);
void populate_array_with_random_numbers(double *array, size_t size, double min, double max);
TrafficEvent* create_traffic_event();
void add_traffic_event(TrafficEvent **traffic_events, size_t *count, TrafficEvent *new_event);
void remove_traffic_event(TrafficEvent **traffic_events, size_t *count, int unique_id);
void update_traffic_event(TrafficEvent *event, const char *type, int severity, double lat, double lon);
int compare_events(const void *a, const void *b);

// Function implementations
Node* create_node(double value) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

Element* initialize_element(int key, Node *linked_list) {
    Element *element = (Element *)malloc(sizeof(Element));
    if (!element) return NULL;
    element->key = key;
    element->linked_list = linked_list;
    return element;
}

void free_linked_list(Node *head, int is_circular) {
    Node *temp;
    while (head) {
        temp = head;
        head = head->next;
        if (!is_circular && !head) break;
        free(temp);
    }
}

void populate_array_with_random_numbers(double *array, size_t size, double min, double max) {
    for (size_t i = 0; i < size; ++i) {
        array[i] = min + ((double)rand() / RAND_MAX) * (max - min);
    }
}

TrafficEvent* create_traffic_event() {
    TrafficEvent *event = (TrafficEvent *)malloc(sizeof(TrafficEvent));
    if (!event) return NULL;

    event->timestamp = time(NULL);
    snprintf(event->event_type, sizeof(event->event_type), "EventType_%d", rand());
    event->unique_id = rand();
    event->severity_level = rand() % 5 + 1; // Severity levels from 1 to 5
    event->latitude = (rand() / (double)RAND_MAX) * 180.0 - 90.0;
    event->longitude = (rand() / (double)RAND_MAX) * 360.0 - 180.0;

    return event;
}

void add_traffic_event(TrafficEvent **traffic_events, size_t *count, TrafficEvent *new_event) {
    *traffic_events = realloc(*traffic_events, (*count + 1) * sizeof(TrafficEvent));
    if (!*traffic_events) return;

    (*traffic_events)[*count] = *new_event;
    (*count)++;
}

void remove_traffic_event(TrafficEvent **traffic_events, size_t *count, int unique_id) {
    for (size_t i = 0; i < *count; ++i) {
        if ((*traffic_events)[i].unique_id == unique_id) {
            memmove(&(*traffic_events)[i], &(*traffic_events)[i + 1], (*count - i - 1) * sizeof(TrafficEvent));
            *count -= 1;
            *traffic_events = realloc(*traffic_events, *count * sizeof(TrafficEvent));
            return;
        }
    }
}

void update_traffic_event(TrafficEvent *event, const char *type, int severity, double lat, double lon) {
    if (event) {
        snprintf(event->event_type, sizeof(event->event_type), "%s", type);
        event->severity_level = severity;
        event->latitude = lat;
        event->longitude = lon;
    }
}

int compare_events(const void *a, const void *b) {
    TrafficEvent *event_a = (TrafficEvent *)a;
    TrafficEvent *event_b = (TrafficEvent *)b;

    if (event_a->severity_level != event_b->severity_level)
        return event_b->severity_level - event_a->severity_level; // Higher severity first

    double dist_a = sqrt(event_a->latitude * event_a->latitude + event_a->longitude * event_a->longitude);
    double dist_b = sqrt(event_b->latitude * event_b->latitude + event_b->longitude * event_b->longitude);

    return (dist_a > dist_b) - (dist_a < dist_b); // Closer events first
}

int main() {
    srand(time(NULL));

    size_t array_size = 10;
    double min_value = 0.0, max_value = 100.0;

    double *random_numbers = malloc(array_size * sizeof(double));
    if (random_numbers) {
        populate_array_with_random_numbers(random_numbers, array_size, min_value, max_value);

        Node *head = create_node(random_numbers[0]);
        for (size_t i = 1; i < array_size; ++i) {
            Node *current = head;
            while (current->next) current = current->next;
            current->next = create_node(random_numbers[i]);
        }

        Element *element = initialize_element(1, head);

        int is_circular = 0;
        free_linked_list(head, is_circular);
        free(element);

        free(random_numbers);
    }

    size_t traffic_event_count = 0;
    TrafficEvent *traffic_events = NULL;

    for (int i = 0; i < 5; ++i) {
        TrafficEvent *new_event = create_traffic_event();
        if (new_event)
            add_traffic_event(&traffic_events, &traffic_event_count, new_event);
    }

    qsort(traffic_events, traffic_event_count, sizeof(TrafficEvent), compare_events);

    for (size_t i = 0; i < traffic_event_count; ++i) {
        printf("Event ID: %d, Severity: %d\n", traffic_events[i].unique_id, traffic_events[i].severity_level);
    }

    free(traffic_events);

    return 0;
}
