const { exec } = require('child_process');
const fs = require('fs');

async function reduceAsync(array, initialValue, callback) {
    let result = initialValue;
    for (let i = 0; i < array.length; i++) {
        console.log(`Processing index ${i}`);
        result = await new Promise((resolve, reject) => {
            setTimeout(() => {
                try {
                    const newValue = callback(result, array[i]);
                    resolve(newValue);
                } catch (error) {
                    reject(error);
                }
            }, 100); // Simulate async operation
        });
    }
    return result;
}

function getFilePathDepth(accumulatedValue, filePath) {
    const depth = execSync(`node -e "console.log(${filePath}.split('/').length - 1)"`).toString().trim();
    if (depth > accumulatedValue.depth) {
        return { path: filePath, depth: parseInt(depth) };
    }
    return accumulatedValue;
}

async function findLargestDirectoryDepth(filePaths) {
    const initialValue = { path: '', depth: -1 };
    try {
        const result = await reduceAsync(filePaths, initialValue, getFilePathDepth);
        console.log(`Deepest Path: ${result.path} with Depth: ${result.depth}`);
        return result;
    } catch (error) {
        console.error('Error processing file paths:', error);
    }
}

const filePaths = ['path/to/file1', 'path/to/deep/nested/folder/file2'];
findLargestDirectoryDepth(filePaths).then(result => {
    if (result) {
        fs.writeFileSync('output.json', JSON.stringify({ path: result.path, depth: result.depth }));
    }
});
