async function transformAndUpdateElements(selectors, transformations, apiConfig, fallbackState) {
  const elements = selectors.flatMap(selector => document.querySelectorAll(selector));

  const updateResource = async (element, apiKey) => {
    try {
      const response = await fetch(apiConfig.url.replace(':key', element.dataset.key), {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(apiConfig.transformedElementBody(element))
      });

      if (!response.ok) throw new Error(`Failed to update resource with key ${element.dataset.key}`);
    } catch (error) {
      console.error(error);
      revertToFallbackState(element, fallbackState);
    }
  };

  const revertToFallbackState = (element, state) => {
    for (const [key, value] of Object.entries(state)) {
      element.setAttribute(key, value);
    }
  };

  const processElements = async () => {
    await Promise.all(
      elements.map(async element => {
        let currentElement = element;

        for (const transform of transformations) {
          currentElement = await transform(currentElement);
          if (!currentElement) break; // Break if transformation returns null/undefined
        }

        await updateResource(element, apiConfig.apiKey);
      })
    );
  };

  const deleteElements = async () => {
    await Promise.all(
      elements.map(async element => {
        try {
          const response = await fetch(`${apiConfig.url.replace(':key', element.dataset.key)}`, {
            method: 'DELETE'
          });

          if (!response.ok) throw new Error(`Failed to delete resource with key ${element.dataset.key}`);

          element.remove();
        } catch (error) {
          console.error(error);
        }
      })
    );
  };

  await processElements();

  // Optional deletion step
  if (apiConfig.deleteAfterTransform) {
    await deleteElements();
  }

  return elements.length;
}
