#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000000
#define TRANSACTION_EXPIRY_TIME (60 * 60) // seconds

typedef enum { PENDING, SUCCESSFUL, FAILED } TransactionStatus;

typedef struct {
    int transaction_id;
    time_t timestamp;
    double amount;
    TransactionStatus status;
} Transaction;

typedef struct {
    Transaction *transactions[MAX_TRANSACTIONS];
    int count;
    pthread_mutex_t lock;
} TransactionManager;

TransactionManager* create_transaction_manager() {
    TransactionManager *manager = (TransactionManager *)malloc(sizeof(TransactionManager));
    if (!manager) return NULL;
    manager->count = 0;
    for (int i = 0; i < MAX_TRANSACTIONS; ++i)
        manager->transactions[i] = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_transaction_manager(TransactionManager *manager) {
    if (!manager) return;
    for (int i = 0; i < manager->count; ++i) {
        free(manager->transactions[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Transaction* create_transaction(int transaction_id, time_t timestamp, double amount, TransactionStatus status) {
    Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
    if (!transaction) return NULL;
    transaction->transaction_id = transaction_id;
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    transaction->status = status;
    return transaction;
}

int add_transaction(TransactionManager *manager, int transaction_id, time_t timestamp, double amount, TransactionStatus status) {
    if (manager->count >= MAX_TRANSACTIONS)
        return -1; // Memory limit reached

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->transactions[i] && manager->transactions[i]->transaction_id == transaction_id) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Transaction ID already exists
        }
    }

    Transaction *new_transaction = create_transaction(transaction_id, timestamp, amount, status);
    if (!new_transaction) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Memory allocation failed
    }

    manager->transactions[manager->count++] = new_transaction;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

Transaction* get_transaction(TransactionManager *manager, int transaction_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->transactions[i] && manager->transactions[i]->transaction_id == transaction_id) {
            Transaction *result = manager->transactions[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

int update_transaction(TransactionManager *manager, int transaction_id, double amount, TransactionStatus status) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->transactions[i] && manager->transactions[i]->transaction_id == transaction_id) {
            manager->transactions[i]->amount = amount;
            manager->transactions[i]->status = status;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Not found
}

void expire_transactions(TransactionManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count;) {
        if (current_time - manager->transactions[i]->timestamp > TRANSACTION_EXPIRY_TIME) {
            free(manager->transactions[i]);
            manager->transactions[i] = manager->transactions[--manager->count];
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int serialize_transactions(TransactionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(int), 1, file);
    for (int i = 0; i < manager->count; ++i) {
        Transaction *transaction = manager->transactions[i];
        fwrite(transaction, sizeof(Transaction), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return 0;
}

int deserialize_transactions(TransactionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int count;
    fread(&count, sizeof(int), 1, file);

    pthread_mutex_lock(&manager->lock);

    for (int i = manager->count; i < count; ++i) {
        Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
        if (!transaction) {
            fclose(file);
            pthread_mutex_unlock(&manager->lock);
            return -2;
        }
        fread(transaction, sizeof(Transaction), 1, file);
        manager->transactions[i] = transaction;
    }

    manager->count = count;

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return 0;
}
