#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

typedef struct {
    long offset;
    int key;
    char status; // 'N' for normal, 'E' for error
} record;

#define STATUS_NORMAL 'N'
#define STATUS_ERROR   'E'

typedef struct memory_pool {
    void *base;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool;

void init_memory_pool(memory_pool *pool, size_t block_size, size_t total_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->used_blocks = 0;
    pool->base = malloc(block_size * total_blocks);
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_memory_pool(memory_pool *pool) {
    free(pool->base);
    pthread_mutex_destroy(&pool->lock);
}

record* allocate_record(memory_pool *pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_blocks >= pool->total_blocks) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *ptr = ((char*)pool->base) + (pool->block_size * pool->used_blocks);
    record *new_record = (record *)ptr;

    new_record->offset = offset;
    new_record->key = key;
    new_record->status = STATUS_NORMAL;

    pool->used_blocks++;
    pthread_mutex_unlock(&pool->lock);

    return new_record;
}

void compact_memory_pool(memory_pool *pool) {
    // In a real-world scenario, implement logic to defragment memory
    // and potentially merge free blocks.
}

void monitor_memory_usage(const memory_pool *pool) {
    size_t used_bytes = pool->used_blocks * pool->block_size;
    printf("Memory Usage: %zu bytes / %zu bytes\n", used_bytes, pool->total_blocks * pool->block_size);
}

int main() {
    memory_pool pool;

    // Initialize a memory pool with block size 128 bytes and total 1000 blocks.
    init_memory_pool(&pool, sizeof(record) + sizeof(long) + sizeof(int), 1000);

    long offsets[] = {1, 2, 3, 4};
    int keys[] = {10, 20, 30, 40};

    for (size_t i = 0; i < sizeof(offsets)/sizeof(offsets[0]); ++i) {
        record *rec = allocate_record(&pool, offsets[i], keys[i]);
        if (rec && rec->status == STATUS_ERROR) {
            fprintf(stderr, "Error allocating memory for record %zu\n", i);
        }
    }

    monitor_memory_usage(&pool);

    // Compact the pool and monitor again
    compact_memory_pool(&pool);
    monitor_memory_usage(&pool);

    destroy_memory_pool(&pool);

    return 0;
}
```

### Key Features:
1. **Thread Safety**: Uses `pthread_mutex_t` for locking to ensure that memory operations are thread-safe.
2. **Memory Pool**: Manages a fixed-size pool of blocks, minimizing fragmentation and improving allocation performance.
3. **Error Handling**: Sets the status flag in case of allocation failures.
4. **Monitoring**: Provides simple reporting on memory usage after major operations.
5. **Periodic Compaction**: Placeholder for implementing defragmentation logic.

This example demonstrates how to balance performance with maintainability, allowing for future enhancements such as compaction algorithms or integration with logging libraries.']

