SensorData* create_sensor_data(size_t initial_capacity) {
    SensorData *data = malloc(sizeof(SensorData));
    data->readings = malloc(initial_capacity * sizeof(SensorReading));
    data->count = 0;
    data->capacity = initial_capacity;
    pthread_mutex_init(&data->lock, NULL);
    return data;
}

void add_reading(SensorData *data, int id, const char *sensor_type, double value) {
    pthread_mutex_lock(&data->lock);

    if (data->count == data->capacity) {
        data->capacity *= 2;
        data->readings = realloc(data->readings, data->capacity * sizeof(SensorReading));
    }

    SensorReading new_reading = {id, time(NULL), "", value};
    strncpy(new_reading.sensor_type, sensor_type, sizeof(new_reading.sensor_type));

    data->readings[data->count++] = new_reading;
    log_action("Add", id, time(NULL));

    pthread_mutex_unlock(&data->lock);
}

SensorReading* get_reading_by_id(SensorData *data, int id) {
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->count; ++i) {
        if (data->readings[i].id == id) {
            SensorReading *reading = &data->readings[i];
            log_action("Retrieve", id, time(NULL));
            pthread_mutex_unlock(&data->lock);
            return reading;
        }
    }

    pthread_mutex_unlock(&data->lock);
    return NULL;
}

void update_reading(SensorData *data, int id, double new_value) {
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->count; ++i) {
        if (data->readings[i].id == id) {
            data->readings[i].value = new_value;
            log_action("Update", id, time(NULL));
            break;
        }
    }

    pthread_mutex_unlock(&data->lock);
}

void filter_readings(SensorData *data) {
    pthread_mutex_lock(&data->lock);

    size_t j = 0;
    for (size_t i = 0; i < data->count; ++i) {
        if (data->readings[i].value >= data->noise_threshold) {
            data->readings[j++] = data->readings[i];
        }
    }

    data->count = j;
    log_action("Filter", -1, time(NULL));

    pthread_mutex_unlock(&data->lock);
}

void apply_moving_average(SensorData *data) {
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->count; ++i) {
        if (i >= 2) {
            double avg = (data->readings[i-2].value + data->readings[i-1].value + data->readings[i].value) / 3.0;
            data->readings[i].value = avg;
        }
    }

    log_action("Smooth", -1, time(NULL));
    pthread_mutex_unlock(&data->lock);
}

double fetch_calibration_factor(const char *api_key) {
