void retry_strategy_with_exponential_backoff(double (*fetch_func)(const char*), const char *api_key) {
    int retries = 5;
    double delay = 1.0;

    while (retries--) {
        double factor = fetch_func(api_key);
        if (factor != -1) return; // Successful retrieval

        sleep(delay);
        delay *= 2;
    }
}

void log_action(const char *action, int sensor_id, time_t timestamp) {
    printf("Action: %s, Sensor ID: %d, Timestamp: %ld\n", action, sensor_id, timestamp);
}

