#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 128
#define INITIAL_CAPACITY 16

typedef struct {
    char* name;
    // Assuming preferences are handled separately for simplicity.
} Preferences;

typedef struct {
    int user_id;
    char name[MAX_NAME_LENGTH];
    Preferences* preferences;
} UserProfile;

typedef struct {
    UserProfile** profiles;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} ProfileCollection;

// Initialize profile collection
int init_profile_collection(ProfileCollection* collection) {
    if (!collection) return -1;

    collection->profiles = malloc(INITIAL_CAPACITY * sizeof(UserProfile*));
    if (!collection->profiles) return -1;
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;

    pthread_rwlock_init(&collection->lock, NULL);
    return 0;
}

// Resize the profile array
static int resize_profile_collection(ProfileCollection* collection) {
    size_t new_capacity = collection->capacity * 2;
    UserProfile** new_profiles = realloc(collection->profiles, new_capacity * sizeof(UserProfile*));
    if (!new_profiles) return -1;

    collection->profiles = new_profiles;
    collection->capacity = new_capacity;
    return 0;
}

// Add a new profile
int add_profile(ProfileCollection* collection, int user_id, const char* name) {
    pthread_rwlock_wrlock(&collection->lock);

    if (user_id < 0 || !name || strlen(name) >= MAX_NAME_LENGTH) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->profiles[i]->user_id == user_id) {
            pthread_rwlock_unlock(&collection->lock);
            return -2; // User ID already exists
        }
    }

    if (collection->count >= collection->capacity && resize_profile_collection(collection)) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    UserProfile* profile = malloc(sizeof(UserProfile));
    if (!profile) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    profile->user_id = user_id;
    strncpy(profile->name, name, MAX_NAME_LENGTH);
    profile->preferences = NULL; // Initialize preferences as needed

    collection->profiles[collection->count++] = profile;

    pthread_rwlock_unlock(&collection->lock);
    return 0;
}

// Update an existing profile
int update_profile(ProfileCollection* collection, int user_id, const char* name) {
    pthread_rwlock_wrlock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->profiles[i]->user_id == user_id) {
            if (!name || strlen(name) >= MAX_NAME_LENGTH) {
                pthread_rwlock_unlock(&collection->lock);
                return -1;
            }
            strncpy(collection->profiles[i]->name, name, MAX_NAME_LENGTH);
            // Update preferences as needed
            pthread_rwlock_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&collection->lock);
    return -2; // User ID not found
}

// Retrieve a profile by user ID
UserProfile* get_profile(ProfileCollection* collection, int user_id) {
    pthread_rwlock_rdlock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->profiles[i]->user_id == user_id) {
            UserProfile* profile = collection->profiles[i];
            pthread_rwlock_unlock(&collection->lock);
            return profile;
        }
    }

    pthread_rwlock_unlock(&collection->lock);
    return NULL;
}

// Clean up resources
void destroy_profile_collection(ProfileCollection* collection) {
    if (!collection) return;

    pthread_rwlock_wrlock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->profiles[i]->preferences);
        free(collection->profiles[i]);
    }

    free(collection->profiles);
    pthread_rwlock_unlock(&collection->lock);
    pthread_rwlock_destroy(&collection->lock);
}
