import threading

typedef enum { FILE_ENTRY, DIRECTORY_ENTRY, ARCHIVE_ENTRY, SYMLINK_ENTRY, DEVICE_ENTRY } EntryType;

typedef struct {
    char* path;
    EntryType type;
    size_t size; // Memory used by this entry
} FileEntry;

typedef struct {
    FileEntry** entries;
    size_t count;
    size_t capacity;
    size_t total_memory_used;
    pthread_mutex_t lock;
} EntryList;

// Function prototypes
void initialize_entry_list(EntryList* list, size_t initial_capacity);
int add_file_path(EntryList* list, const char* path, EntryType type, size_t size);
void serialize_to_file(const EntryList* list, const char* filename);
int deserialize_from_file(EntryList* list, const char* filename);
void cleanup_entry_list(EntryList* list);

// Initialize the entry list with a given capacity
void initialize_entry_list(EntryList* list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->entries = malloc(initial_capacity * sizeof(FileEntry*));
    list->count = 0;
    list->capacity = initial_capacity;
    list->total_memory_used = 0;
}

// Add a new file path to the entry list
int add_file_path(EntryList* list, const char* path, EntryType type, size_t size) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity || 
        list->total_memory_used + size > MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Exceeds limits
    }

    FileEntry* entry = malloc(sizeof(FileEntry));
    if (!entry) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    entry->path = strdup(path);
    entry->type = type;
    entry->size = size;

    list->entries[list->count++] = entry;
    list->total_memory_used += sizeof(FileEntry*) + strlen(path) + 1 + size;

    // External logging system integration
    log_operation("Added", path);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Serialize the entry list to a file
void serialize_to_file(const EntryList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < list->count; ++i) {
        FileEntry* entry = list->entries[i];
        size_t path_length = strlen(entry->path) + 1;

        fwrite(&entry->type, sizeof(EntryType), 1, file);
        fwrite(&path_length, sizeof(size_t), 1, file);
        fwrite(entry->path, sizeof(char), path_length, file);
    }

    fclose(file);
}

// Deserialize the entry list from a file
int deserialize_from_file(EntryList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (list->capacity < count) {
        free(list->entries);
        list->entries = malloc(count * sizeof(FileEntry*));
        list->capacity = count;
    }

    list->total_memory_used = 0;
    list->count = 0;

    for (size_t i = 0; i < count; ++i) {
        EntryType type;
        size_t path_length;

        fread(&type, sizeof(EntryType), 1, file);
        fread(&path_length, sizeof(size_t), 1, file);

        char* path = malloc(path_length);
        fread(path, sizeof(char), path_length, file);

        int result = add_file_path(list, path, type, sizeof(FileEntry*) + path_length);

        if (result != 0) {
            free(path);
            fclose(file);
            return -1;
        }

        free(path);
    }

    fclose(file);
    return 0;
}

// Clean up the entry list
void cleanup_entry_list(EntryList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]->path);
        free(list->entries[i]);
    }

    free(list->entries);
    list->count = 0;
    list->capacity = 0;
    list->total_memory_used = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Logging system integration (example implementation)
