LibraryConfig lib_config = {0};

void initialize_library() {
    memset(&lib_config, 0, sizeof(LibraryConfig));
    lib_config.max_buffer_size = DEFAULT_BUFFER_SIZE;
    lib_config.timeout = 30.0; // seconds
    lib_config.compression_enabled = 1;

    pthread_rwlock_init(&lib_config.config_lock, NULL);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        memset(&lib_config.connections[i], 0, sizeof(Connection));
        pthread_mutex_init(&lib_config.connections[i].lock, NULL);
    }
}

void cleanup_library() {
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (lib_config.connections[i].buffer) {
            free(lib_config.connections[i].buffer);
        }
        pthread_mutex_destroy(&lib_config.connections[i].lock);
    }
    pthread_rwlock_destroy(&lib_config.config_lock);
}

void configure_connection(Connection *conn, const char *ip, int port, ProtocolType protocol) {
    strncpy(conn->ip, ip, INET_ADDRSTRLEN - 1);
    conn->port = port;
    conn->protocol = protocol;
    conn->state = CLOSED;

    pthread_mutex_lock(&lib_config.config_lock);
    conn->buffer_size = lib_config.max_buffer_size;
    pthread_mutex_unlock(&lib_config.config_lock);

    conn->buffer = (unsigned char *)malloc(conn->buffer_size);
    if (!conn->buffer) {
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }
}

void update_library_config(size_t max_buffer_size, double timeout, int compression_enabled) {
    pthread_rwlock_wrlock(&lib_config.config_lock);
    lib_config.max_buffer_size = max_buffer_size;
    lib_config.timeout = timeout;
    lib_config.compression_enabled = compression_enabled;
    pthread_rwlock_unlock(&lib_config.config_lock);
}

void handle_connection(Connection *conn) {
    pthread_mutex_lock(&conn->lock);
    // Simulate connection handling logic
    conn->state = CONNECTED;
    printf("Connection established to %s:%d\n", conn->ip, conn->port);
    pthread_mutex_unlock(&conn->lock);
}

