#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <fstream>
#include <random>
#include <atomic>

struct Session {
    std::string sessionId;
    std::string clientIp;
    std::time_t lastActivity;
    int refCount;
    std::string metadata;
    bool isActive;

    Session(std::string id, std::string ip)
        : sessionId(id), clientIp(ip), lastActivity(std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())),
          refCount(0), metadata(""), isActive(true) {}
};

class SessionManager {
public:
    SessionManager(size_t maxSessions);
    ~SessionManager();

    bool addSession(const std::string& sessionId, const std::string& clientIp);
    void expireSessions();
    void serializeToFile(const std::string& filename) const;
    void deserializeFromFile(const std::string& filename);

    std::optional<Session> getSessionById(const std::string& id) const;
    std::vector<Session> getSessionsByIp(const std::string& ip) const;

    void adjustMemoryLimitBasedOnLoad();
    void dynamicAdjustmentOfExpirationThreshold();

private:
    mutable std::mutex mtx_;
    std::unordered_map<std::string, Session> sessionsById_;
    std::unordered_map<std::string, std::vector<Session>> sessionsByIp_;
    size_t maxSessions_;
    std::atomic<int> activeSessionCount_{0};
    float averageActivityLevel_ = 1.0f;
    int cooldownPeriodSeconds_;

    void selectAndCooldownAttack() const;
};

SessionManager::SessionManager(size_t maxSessions)
    : maxSessions_(maxSessions), cooldownPeriodSeconds_(9) {}

SessionManager::~SessionManager() {
    expireSessions();
}

bool SessionManager::addSession(const std::string& sessionId, const std::string& clientIp) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (sessionsById_.size() >= maxSessions_) return false;

    sessionsById_[sessionId] = {sessionId, clientIp};
    sessionsByIp_[clientIp].push_back(sessionsById_[sessionId]);
    ++activeSessionCount_;
    return true;
}

void SessionManager::expireSessions() {
    std::lock_guard<std::mutex> lock(mtx_);
    auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    for (auto it = sessionsById_.begin(); it != sessionsById_.end();) {
        if (!it->second.isActive && std::difftime(now, it->second.lastActivity) > 30) { // 30 seconds inactivity timeout
            sessionsByIp_[it->second.clientIp].erase(
                std::remove_if(sessionsByIp_[it->second.clientIp].begin(), sessionsByIp_[it->second.clientIp].end(),
                               [&it](const Session& s) { return s.sessionId == it->first; }),
                sessionsByIp_[it->second.clientIp].end());
            it = sessionsById_.erase(it);
            --activeSessionCount_;
        } else {
            ++it;
        }
    }
}

void SessionManager::serializeToFile(const std::string& filename) const {
    std::lock_guard<std::mutex> lock(mtx_);
    std::ofstream ofs(filename, std::ios::binary | std::ios::out);
    for (const auto& [id, session] : sessionsById_) {
        size_t len = session.sessionId.size();
        ofs.write(reinterpret_cast<const char*>(&len), sizeof(len));
        ofs.write(session.sessionId.c_str(), len);

        len = session.clientIp.size();
        ofs.write(reinterpret_cast<const char*>(&len), sizeof(len));
        ofs.write(session.clientIp.c_str(), len);

        ofs.write(reinterpret_cast<const char*>(&session.lastActivity), sizeof(session.lastActivity));
        ofs.write(reinterpret_cast<const char*>(&session.refCount), sizeof(session.refCount));

        len = session.metadata.size();
        ofs.write(reinterpret_cast<const char*>(&len), sizeof(len));
        ofs.write(session.metadata.c_str(), len);

        ofs.write(reinterpret_cast<const char*>(&session.isActive), sizeof(session.isActive));
    }
}

void SessionManager::deserializeFromFile(const std::string& filename) {
    std::lock_guard<std::mutex> lock(mtx_);
    std::ifstream ifs(filename, std::ios::binary | std::ios::in);
    while (ifs.good()) {
        size_t len;
        ifs.read(reinterpret_cast<char*>(&len), sizeof(len));
        if (!ifs) break;

        std::string sessionId(len, ' ');
        ifs.read(&sessionId[0], len);

        ifs.read(reinterpret_cast<char*>(&len), sizeof(len));
        std::string clientIp(len, ' ');
        ifs.read(&clientIp[0], len);

        std::time_t lastActivity;
        ifs.read(reinterpret_cast<char*>(&lastActivity), sizeof(lastActivity));

        int refCount;
        ifs.read(reinterpret_cast<char*>(&refCount), sizeof(refCount));

        ifs.read(reinterpret_cast<char*>(&len), sizeof(len));
        std::string metadata(len, ' ');
        ifs.read(&metadata[0], len);

        bool isActive;
        ifs.read(reinterpret_cast<char*>(&isActive), sizeof(isActive));

        addSession(sessionId, clientIp);
    }
}

std::optional<Session> SessionManager::getSessionById(const std::string& id) const {
    std::lock_guard<std::mutex> lock(mtx_);
    auto it = sessionsById_.find(id);
    if (it != sessionsById_.end()) return it->second;
    return {};
}

std::vector<Session> SessionManager::getSessionsByIp(const std::string& ip) const {
    std::lock_guard<std::mutex> lock(mtx_);
    auto it = sessionsByIp_.find(ip);
    if (it != sessionsByIp_.end()) return it->second;
    return {};
}

void SessionManager::adjustMemoryLimitBasedOnLoad() {
    // Placeholder for logic to adjust maxSessions_ based on system load metrics
}

void SessionManager::dynamicAdjustmentOfExpirationThreshold() {
    // Adjust expiration threshold based on average activity level
    float newThreshold = 30.0f * averageActivityLevel_; // Example adjustment
    std::lock_guard<std::mutex> lock(mtx_);
    for (auto& [id, session] : sessionsById_) {
        if (!session.isActive && std::difftime(std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()), session.lastActivity) > newThreshold) {
            session.isActive = false;
            --activeSessionCount_;
        }
    }
}

void SessionManager::selectAndCooldownAttack() const {
    static auto lastAttackTime = std::chrono::steady_clock::now();
    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() < cooldownPeriodSeconds_) return;

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 3);
    int attack = dis(gen);

    std::cout << "Selected Attack: " << attack << std::endl;
    lastAttackTime = now;
}
```

This code implements a session manager with dynamic memory management, serialization/deserialization, and a cooldown-based random attack selection mechanism. It ensures thread safety, handles edge cases, and includes mechanisms for adjusting session expiration based on activity levels.']

