typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
} record_t;

const int MAX_STRUCTURES = 1000; // Example maximum limit
const int RECORD_RANGE_MIN = 1;
const int RECORD_RANGE_MAX = 100;

pthread_mutex_t log_mutex;

void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message); // Simulating logging
    pthread_mutex_unlock(&log_mutex);
}

int validate_input(int n) {
    if (n <= 0) {
        fprintf(stderr, "Error: Input size must be positive.\n");
        return -1;
    }
    if (n > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Input size exceeds maximum limit of %d.\n", MAX_STRUCTURES);
        return -1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pis(int n, int *offsets, int *keys, record_t **records) {
    if (validate_input(n)) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfas = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfas) {
        log_message("Memory allocation failed for nfa_pis.");
        return NULL;
    }

    offsets = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    if (!offsets || !keys) {
        free(nfas);
        log_message("Memory allocation failed for offsets or keys.");
        return NULL;
    }

    *records = (record_t *)malloc(n * sizeof(record_t));
    if (!(*records)) {
        free(nfas);
        free(offsets);
        free(keys);
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        // Initialize NFAPI_CRC_INDICATION_PDU_T
        nfas[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        nfas[i].RNTI = rand() % 1000;
        nfas[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        nfas[i].CRCFLAG = rand() % 2;

        // Initialize offsets and keys
        offsets[i] = (long)(rand() % 10000);
        keys[i] = rand() % 1000;

        // Initialize records with random values within range
        (*records)[i].value = RECORD_RANGE_MIN + rand() % (RECORD_RANGE_MAX - RECORD_RANGE_MIN + 1);
    }

    return nfas;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T *nfas, long *offsets, int *keys, record_t *records) {
    if (nfas) free(nfas);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int main() {
    pthread_mutex_init(&log_mutex, NULL);

    int n;
    printf("Enter the number of structures: ");
    scanf("%d", &n);

    long *offsets = NULL;
    int *keys = NULL;
    record_t *records = NULL;

    NFAPI_CRC_INDICATION_PDU_T *nfas = create_nfa_pis(n, offsets, keys, &records);

    if (nfas) {
        // Use the structures as needed
        log_message("Structures created successfully.");

        // Free resources
        free_resources(nfas, offsets, keys, records);
    } else {
        log_message("Failed to create structures. Check logs for details.");
    }

    pthread_mutex_destroy(&log_mutex);

    return 0;
}
