ImagePipeline* optimizeImageProcessingPipeline(size_t width, size_t height, int bpp) {
    if (width == 0 || height == 0 || bpp <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    size_t totalMemory = width * height * ((bpp + 7) / 8);
    if (totalMemory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Requested memory exceeds the limit of 10 MB.\n");
        return NULL;
    }

    ImagePipeline* pipeline = malloc(sizeof(ImagePipeline));
    if (!pipeline) {
        perror("Failed to allocate memory for ImagePipeline.");
        return NULL;
    }

    pthread_mutex_init(&pipeline->mutex, NULL);

    pipeline->data = malloc(sizeof(ImageData));
    if (!pipeline->data) {
        free(pipeline);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    pipeline->data->pixels = malloc(totalMemory);
    if (!pipeline->data->pixels) {
        free(pipeline->data);
        free(pipeline);
        fprintf(stderr, "Memory allocation for pixels failed.\n");
        return NULL;
    }

    pipeline->data->width = width;
    pipeline->data->height = height;
    pipeline->data->bpp = bpp;

    int connectRetries = 0;
    while (connectRetries < RETRY_LIMIT) {
        if (connectToImageSource() == 0) {
            break;
        }
        ++connectRetries;
    }

    if (connectRetries == RETRY_LIMIT) {
        free(pipeline->data->pixels);
        free(pipeline->data);
        free(pipeline);
        fprintf(stderr, "Failed to connect to image source after %d retries.\n", RETRY_LIMIT);
        return NULL;
    }

    int fetchResult = fetchImageData(&pipeline->data->pixels, &width, &height, &bpp);
    if (fetchResult != 0) {
        free(pipeline->data->pixels);
        free(pipeline->data);
        free(pipeline);
        disconnectFromImageSource();
        fprintf(stderr, "Failed to fetch image data.\n");
        return NULL;
    }

    clock_t start;

    // Apply transformations with timing
    applyGrayscale(pipeline->data);

    startTimer(&start);
    applyEdgeDetection(pipeline->data);
    printf("Edge Detection took %f ms\n", endTimer(start) * 1000.0);

    startTimer(&start);
    applyNoiseReduction(pipeline->data);
    printf("Noise Reduction took %f ms\n", endTimer(start) * 1000.0);

    disconnectFromImageSource();

    return pipeline;
}

void freePipeline(ImagePipeline* pipeline) {
    if (!pipeline) return;

    pthread_mutex_lock(&pipeline->mutex);
    if (pipeline->data && pipeline->data->pixels) {
        free(pipeline->data->pixels);
    }
    if (pipeline->data) {
        free(pipeline->data);
    }
    pthread_mutex_unlock(&pipeline->mutex);

    pthread_mutex_destroy(&pipeline->mutex);
    free(pipeline);
}

