#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 64

typedef struct {
    int rnti;
    // Add other UE information fields as needed.
} RX_UE_INFO_TAG;

typedef struct {
    RX_UE_INFO_TAG ue_info_tag;
    unsigned char *uci_buffer;
    size_t uci_size;
} LTE_PHY_RX_FRAME_INFO;

typedef struct MemoryPoolNode {
    void *memory;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    pthread_mutex_t lock;
    MemoryPoolNode *free_list;
    size_t block_size;
    int pool_initialized;
} MemoryPool;

MemoryPool global_memory_pool = { .lock = PTHREAD_MUTEX_INITIALIZER, .pool_initialized = 0 };

void initialize_memory_pool(size_t block_size) {
    if (global_memory_pool.pool_initialized) return;

    pthread_mutex_lock(&global_memory_pool.lock);
    if (!global_memory_pool.pool_initialized) {
        global_memory_pool.block_size = block_size;
        global_memory_pool.free_list = NULL;

        for (int i = 0; i < INITIAL_POOL_SIZE; ++i) {
            MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
            node->memory = malloc(block_size);
            node->next = global_memory_pool.free_list;
            global_memory_pool.free_list = node;
        }

        global_memory_pool.pool_initialized = 1;
    }
    pthread_mutex_unlock(&global_memory_pool.lock);
}

void *allocate_from_pool(size_t size) {
    pthread_mutex_lock(&global_memory_pool.lock);

    if (!global_memory_pool.pool_initialized || size > global_memory_pool.block_size) {
        void *memory = malloc(size);
        pthread_mutex_unlock(&global_memory_pool.lock);
        return memory;
    }

    MemoryPoolNode *node = global_memory_pool.free_list;
    if (node) {
        global_memory_pool.free_list = node->next;
        void *allocated_memory = node->memory;

        pthread_mutex_unlock(&global_memory_pool.lock);
        return allocated_memory;
    }

    pthread_mutex_unlock(&global_memory_pool.lock);

    // Fallback allocation
    return malloc(size);
}

void deallocate_to_pool(void *memory, size_t size) {
    if (!global_memory_pool.pool_initialized || size > global_memory_pool.block_size) {
        free(memory);
        return;
    }

    MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
    node->memory = memory;
    node->next = global_memory_pool.free_list;

    pthread_mutex_lock(&global_memory_pool.lock);
    global_memory_pool.free_list = node;
    pthread_mutex_unlock(&global_memory_pool.lock);
}

typedef struct {
    LTE_PHY_RX_FRAME_INFO **frames;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} FrameArrayManager;

void initialize_frame_array_manager(FrameArrayManager *manager, size_t initial_capacity) {
    manager->frames = malloc(initial_capacity * sizeof(LTE_PHY_RX_FRAME_INFO*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_rwlock_init(&manager->rwlock, NULL);
}

LTE_PHY_RX_FRAME_INFO *create_frame(RX_UE_INFO_TAG ue_info_tag, size_t uci_size) {
    initialize_memory_pool(uci_size);

