void insert_frame(FrameArrayManager *manager, LTE_PHY_RX_FRAME_INFO *frame) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->frames = realloc(manager->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO*));
        manager->capacity = new_capacity;
