uint64_t rotateLeft(uint64_t x, unsigned k) {
    return (x << k) | (x >> (64 - k));
}

// Thread-safe custom RNG
uint64_t rngNext(RNGState* state) {
    const uint64_t s0 = state->state[0];
    uint64_t s1 = state->state[1];
    const uint64_t result = s0 + s1;

    s1 ^= s0;
    state->state[0] = rotateLeft(s0, 24) ^ s1 ^ (s1 << 16); // a, b
    state->state[1] = rotateLeft(s1, 37); // c

    return result;
}

// Thread-safe random number generator initialization
void rngInit(RNGState* state, uint64_t seed) {
    pthread_mutex_lock(&rngMutex);
    state->state[0] = seed;
    state->state[1] = seed ^ 0x9E3779B97F4A7C15ULL; // Arbitrary constant
    pthread_mutex_unlock(&rngMutex);
}

