        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash;
}

// Check for potential overflow
size_t safeMultiply(size_t a, size_t b) {
    if (a == 0 || b == 0)
        return 0;

    if (b > SIZE_MAX / a)
        return SIZE_MAX;

    return a * b;
}

void manageDynamicMemoryAllocation(size_t numOffsetRecords, size_t numKeyRecords, size_t numRandomValues) {
    size_t systemLimit = getSystemMemoryLimit();

    // Allocate memory for OffsetRecord array
    size_t offsetArraySize = safeMultiply(numOffsetRecords, sizeof(OffsetRecord));
    if (offsetArraySize > systemLimit || numOffsetRecords == 0) {
        logAnomaly("Failed to allocate memory for OffsetRecords due to overflow or invalid input.");
        return;
    }

    OffsetRecord* offsetArray = (OffsetRecord*)malloc(offsetArraySize);
    if (!offsetArray) {
        logAnomaly("Memory allocation failed for OffsetRecords.");
        return;
    }

    // Allocate memory for KeyRecord array
    size_t keyArraySize = safeMultiply(numKeyRecords, sizeof(KeyRecord));
    if (keyArraySize > systemLimit || numKeyRecords == 0) {
        logAnomaly("Failed to allocate memory for KeyRecords due to overflow or invalid input.");
        free(offsetArray);
        return;
    }

    KeyRecord* keyArray = (KeyRecord*)malloc(keyArraySize);
    if (!keyArray) {
        logAnomaly("Memory allocation failed for KeyRecords.");
        free(offsetArray);
        return;
    }

    // Initialize KeyRecords and manage out-of-bounds indices
    for (size_t i = 0; i < numKeyRecords; ++i) {
        keyArray[i].value = rand() % 100; // Example value assignment
        if (i < numOffsetRecords)
            keyArray[i].offsetRecordPtr = &offsetArray[i];
        else
            logAnomaly("Out-of-bounds index access for KeyRecord.");
    }

    // Allocate memory for RandomValue array
    size_t randomArraySize = safeMultiply(numRandomValues, sizeof(RandomValue));
    if (randomArraySize > systemLimit || numRandomValues == 0) {
        logAnomaly("Failed to allocate memory for RandomValues due to overflow or invalid input.");
        free(offsetArray);
        free(keyArray);
        return;
    }

    RandomValue* randomArray = (RandomValue*)malloc(randomArraySize);
    if (!randomArray) {
        logAnomaly("Memory allocation failed for RandomValues.");
        free(offsetArray);
        free(keyArray);
        return;
    }

    // Initialize RNG state
    uint64_t seed = cryptoHash((const char*)&rand());
    RNGState rngState;
    rngInit(&rngState, seed);

    // Parallel initialization of RandomValue array using a thread pool (mock)
    #define NUM_THREADS 4
    pthread_t threads[NUM_THREADS];
    size_t chunkSize = numRandomValues / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS; ++i) {
        size_t start = i * chunkSize;
        size_t end = (i == NUM_THREADS - 1) ? numRandomValues : start + chunkSize;

        pthread_create(&threads[i], NULL, (void* (*)(void*))[] (void* arg){
            RNGState localRngState = rngState; // Copy for thread safety
            size_t* range = (size_t*)arg;
            size_t start = range[0];
            size_t end = range[1];

            for (size_t j = start; j < end; ++j) {
                randomArray[j].randomValue = (int)(rngNext(&localRngState) % 101);
            }
        }, malloc(sizeof(size_t) * 2), &start, &end);

    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free(randomArray);
    free(keyArray);
    free(offsetArray);
}

int main() {
