// Define constants
#define MAX_RNTI 4096

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t allocated_size;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
int initialize_memory_pool(MemoryPool* pool, size_t initial_size);
int resize_memory_pool(MemoryPool* pool, size_t new_size);
void free_memory_pool(MemoryPool* pool);
int populate_pdu_list(MemoryPool* pool, int N);

static pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned int used_rntis[MAX_RNTI] = {0};

// Initialize memory pool
int initialize_memory_pool(MemoryPool* pool, size_t initial_size) {
    if (pthread_mutex_init(&pool->lock, NULL) != 0) return -1;
    pool->pdu_list = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->allocated_size = initial_size;
    if (!pool->pdu_list) {
        pthread_mutex_destroy(&pool->lock);
        return -1;
    }
    return 0;
}

// Resize memory pool
int resize_memory_pool(MemoryPool* pool, size_t new_size) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T* resized_list = realloc(pool->pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!resized_list) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    pool->pdu_list = resized_list;
    pool->allocated_size = new_size;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Free memory pool
void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->pdu_list);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Populate PDU list with unique RNTIs and random CRCFLAG values
int populate_pdu_list(MemoryPool* pool, int N) {
    if (N > pool->allocated_size) {
        if (resize_memory_pool(pool, N) != 0) return -1;
    }

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < N; ++i) {
        unsigned int rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (__sync_fetch_and_or(&used_rntis[rnti], 1));

        pool->pdu_list[i].RX_UE_INFORMATION_TAG = rand(); // Assign random tag
        pool->pdu_list[i].RNTI = rnti;
        pool->pdu_list[i].CRC_INDICATION_REL8_TAG = rand(); // Assign random CRC tag
        pool->pdu_list[i].CRCFLAG = rand() & 1; // Random CRCFLAG: 0 or 1
    }

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Main function for testing
int main() {
    srand(time(NULL));

    MemoryPool pool;
    if (initialize_memory_pool(&pool, 10) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return EXIT_FAILURE;
    }

    int N = 20; // Example: Populate with 20 structures
    if (populate_pdu_list(&pool, N) != 0) {
        fprintf(stderr, "Failed to populate PDU list\n");
        free_memory_pool(&pool);
        return EXIT_FAILURE;
    }

    // Output the populated data for verification
    for (int i = 0; i < N; ++i) {
        printf("PDU[%d]: RX_UE_TAG=%u, RNTI=%u, CRC_TAG=%u, CRCFLAG=%d\n",
               i, pool.pdu_list[i].RX_UE_INFORMATION_TAG,
               pool.pdu_list[i].RNTI, pool.pdu_list[i].CRC_INDICATION_REL8_TAG,
               pool.pdu_list[i].CRCFLAG);
    }

    free_memory_pool(&pool);
    return EXIT_SUCCESS;
}
