class MemoryPool {
    constructor(initialCapacity = 10) {
        this.capacity = initialCapacity;
        this.pool = [];
        this.totalAllocated = 0;
    }

    allocate(size) {
        if (this.totalAllocated >= this.capacity) return null;

        let record = { size, data: new Array(size).fill(0) };
        this.pool.push(record);
        this.totalAllocated++;
        return record.data;
    }

    deallocate(record) {
        const index = this.pool.indexOf(record);
        if (index !== -1) {
            this.pool.splice(index, 1);
            this.totalAllocated--;
        }
    }

    resize(newCapacity) {
        this.capacity = newCapacity;
    }

    getUsage() {
        return { capacity: this.capacity, used: this.totalAllocated };
    }
}

