        return Array.from({ length: size }, () =>
            charset[Math.floor(Math.random() * charset.length)]
        ).join('');
    }

    let articles = [];
    const entities = nlpModel.extractEntities(queryString.toLowerCase().split(' '));
    if (!entities || entities.length === 0) return [];

