    new_entry.RNTI = rand();
    new_entry.CRC_INDICATION_REL8_TAG = rand();
    new_entry.CRCFLAG = rand() % 2;

    list->data[list->size++] = new_entry;

    // Log batch
    static char log_buffer[LOG_BATCH_SIZE][256];
    static int log_count = 0;
    snprintf(log_buffer[log_count], sizeof(log_buffer[log_count]), "Added entry: RNTI=%d, CRCFLAG=%d", 
             new_entry.RNTI, new_entry.CRCFLAG);
    log_count++;
    if (log_count >= LOG_BATCH_SIZE) {
        for (int i = 0; i < LOG_BATCH_SIZE; ++i) {
            log_service(log_buffer[i]);
        }
        log_count = 0;
    }
    pthread_mutex_unlock(&list->lock);
}

void resize_dynamic_list(DynamicList* list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, 
                                                                               new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory for data array");
        return;
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void free_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    int num_structs = 100000; // This would be user input in practice
    if (num_structs > MAX_STRUCTS) {
        fprintf(stderr, "Requested number exceeds maximum limit.\n");
        return EXIT_FAILURE;
    }

    DynamicList* list = init_dynamic_list();
    if (!list) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_structs; ++i) {
        add_to_dynamic_list(list);
    }

    free_dynamic_list(list);
    return EXIT_SUCCESS;
}
