function processWidgets(containerId, widgetList) {
    const validWidgetTypes = new Set(['typeA', 'typeB', 'typeC']); // Predefined types
    const container = document.getElementById(containerId);
    let existingIds = new Set();
    let cache = {};

    if (!container) throw new Error('Container not found');

    widgetList.forEach(widget => {
        // Validate and normalize widget ID
        let id = widget.id || `widget-${Math.random().toString(36).substr(2, 9)}`;
        while (existingIds.has(id)) {
            id += '-dup';
        }
        existingIds.add(id);

        // Validate widget type
        if (!validWidgetTypes.has(widget.type)) {
            console.warn(`Unrecognized widget type: ${widget.type}`);
            return;
        }

        // Validate data-url with regex pattern for URLs
        const urlPattern = /^(https?:\/\/(?:www\.|(?!www))[a-zA-Z0-9][a-zA-Z0-9-]+[a-zA-Z0-9]\.[^\s]{2,}|www\.[a-zA-Z0-9][a-zA-Z0-9-]+[a-zA-Z0-9]\.[^\s]{2,}|https?:\/\/(?:www\.|(?!www))[a-zA-Z0-9]+\.[^\s]{2,}|www\.[a-zA-Z0-9]+\.[^\s]{2,})$/;
        if (!urlPattern.test(widget.dataUrl)) {
            throw new Error(`Malformed URL for widget with id: ${id}`);
        }

        // Check cache or fetch data
        if (cache[widget.dataUrl]) {
            widget.data = cache[widget.dataUrl];
        } else {
            fetchWidgetData(widget.dataUrl).then(data => {
                cache[widget.dataUrl] = data;
                widget.data = data;
            }).catch(err => console.error(`Error fetching data for ${id}:`, err));
        }
    });

    // Sort widgets by priority
    widgetList.sort((a, b) => (b.priority || 0) - (a.priority || 0));

    // Create and append widget elements
    const fragment = document.createDocumentFragment();

    async function createWidgetElements() {
        for (const widget of widgetList) {
            if (!widget.data) continue; // Skip widgets that failed data fetch

            const element = document.createElement('div');
            element.id = id;
            element.className = `widget ${widget.type} ${widget.cssClasses || ''}`;

            // Populate the element with content based on type
            switch (widget.type) {
                case 'typeA':
                    element.innerHTML = `<span>${widget.data}</span>`;
                    break;
                case 'typeB':
                    element.innerHTML = `<p>${widget.data.title}: ${widget.data.content}</p>`;
                    break;
                case 'typeC':
                    element.innerHTML = `<img src="${widget.data.imageUrl}" alt="${widget.data.altText}">`;
                    break;
            }

            fragment.appendChild(element);
        }

        container.appendChild(fragment);
    }

    createWidgetElements();

    return container.outerHTML;
}

// Simulated fetch function for widget data
async function fetchWidgetData(url) {
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Network response was not ok');
        return await response.json();
    } catch (error) {
        console.error(`Fetch error: ${error}`);
        throw error;
    }
}
