['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 10000
#define CONNECTION_SIZE sizeof(Connection)
#define MEMORY_LIMIT (MAX_CONNECTIONS * CONNECTION_SIZE)

typedef enum {
    STATUS_ACTIVE,
    STATUS_IDLE,
    STATUS_CLOSED
} Status;

typedef struct {
    int id;
    time_t timestamp;
    Status status;
} Connection;

typedef struct {
    Connection* connections[MAX_CONNECTIONS];
    size_t count;
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_size) {
    if (initial_size > MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Initial size exceeds maximum allowed connections.\n");
        return NULL;
    }

    ConnectionManager* manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    if (!manager) {
        perror("Memory allocation failed for connection manager");
        return NULL;
    }

    memset(manager, 0, sizeof(ConnectionManager));
    manager->count = initial_size;

    for (size_t i = 0; i < manager->count; ++i) {
        Connection* conn = (Connection*)malloc(CONNECTION_SIZE);
        if (!conn) {
            perror("Memory allocation failed for connection");
            // Clean up previously allocated connections
            while (i--) free(manager->connections[i]);
            free(manager);
            return NULL;
        }
        manager->connections[i] = conn;
    }

    return manager;
}

void log_event(const char* event, int id) {
    time_t now;
    time(&now);
    printf("Event: %s | Connection ID: %d | Timestamp: %ld\n", event, id, now);
}

int add_connection(ConnectionManager* manager) {
    if (manager->count >= MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Maximum connection limit reached.\n");
        return -1;
    }

    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!manager->connections[i]) {
            manager->connections[i] = (Connection*)malloc(CONNECTION_SIZE);
            if (!manager->connections[i]) {
                perror("Memory allocation failed for connection");
                return -1;
            }

            manager->connections[i]->id = i;
            time(&manager->connections[i]->timestamp);
            manager->connections[i]->status = STATUS_ACTIVE;

            log_event("Connection Established", i);

            ++manager->count;
            return 0;
        }
    }

    fprintf(stderr, "Error: Unable to find space for new connection.\n");
    return -1;
}

void close_idle_connections(ConnectionManager* manager) {
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i] && manager->connections[i]->status == STATUS_IDLE) {
            log_event("Connection Closed", manager->connections[i]->id);

            free(manager->connections[i]);
            manager->connections[i] = NULL;
            --manager->count;
        }
    }
}

void shutdown_manager(ConnectionManager* manager) {
    close_idle_connections(manager);

    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[i]) {
            log_event("Connection Closed", manager->connections[i]->id);

            free(manager->connections[i]);
            manager->connections[i] = NULL;
        }
    }

    free(manager);
}

int main() {
    ConnectionManager* manager = create_connection_manager(100);

    if (!manager) return EXIT_FAILURE;

    for (int i = 0; i < 105; ++i) { // Attempt to add more connections than initialized
        if (add_connection(manager) != 0) break;
    }

    shutdown_manager(manager);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a dynamic connection manager in C, handling up to 10,000 connections. It allocates memory efficiently, logs events, and ensures robust error handling for out-of-bounds access and allocation failures. The function is designed with extensibility in mind, allowing future enhancements such as additional attributes or integration with external systems.']

