#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

// Define the structure based on given description
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        _Atomic(int) CRCFLAG;  // Atomic for thread-safe random setting
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to initialize a new node with random values (simplified)
Node* create_node(uint16_t rnti) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    // Initialize structure with given RNTI and random other values
    newNode->data.RX_UE_INFORMATION_TAG = rand() % 256;
    newNode->data.RNTI = rnti;
    _Atomic_store(&newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG, rand() % 2);

    newNode->next = NULL;
    return newNode;
}

// Function to insert a node into the sorted linked list
void insert_sorted(Node** head_ref, Node* new_node) {
    if (*head_ref == NULL || (*head_ref)->data.RNTI >= new_node->data.RNTI) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->next->data.RNTI < new_node->data.RNTI) {
            current = current->next;
        }
        if (current->next != NULL && current->next->data.RNTI == new_node->data.RNTI) {
            printf("Error: Duplicate RNTI detected (%u)\n", new_node->data.RNTI);
            free(new_node);
            return;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Thread-safe function to manage the list
void* manage_list(void* arg) {
    Node** head_ref = (Node**)arg;
    pthread_mutex_t lock;

    // Initialize mutex for thread safety
    pthread_mutex_init(&lock, NULL);

    while (1) {  // Simulating continuous processing
        uint16_t new_rnti = rand() % 65536;  // Simulate generation of RNTI
        Node* new_node = create_node(new_rnti);

        if (!new_node) {
            printf("Memory allocation failed\n");
            continue;
        }

        pthread_mutex_lock(&lock);
        insert_sorted(head_ref, new_node);
        pthread_mutex_unlock(&lock);

        // Simulate time delay or other operations
    }

    pthread_mutex_destroy(&lock);
    return NULL;
}

int main() {
    Node* head = NULL;

    // Start multiple threads for concurrent insertion
    const int num_threads = 4;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, manage_list, &head);
    }

    // Join threads (in a real-world application, consider more graceful exit handling)
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

### Key Considerations:

- **Thread Safety**: A mutex is used to protect the critical section where nodes are inserted into the list. For a truly lock-free approach, more advanced techniques like atomic operations or concurrent data structures would be needed.

- **Memory Management**: Each node's memory allocation is checked, and duplicates based on `RNTI` are logged and skipped.

- **Performance Optimization**: The list insertion maintains sorted order, which simplifies duplicate checking but may introduce overhead if not optimized further for larger lists.

- **Scalability and Future Enhancements**: The code is designed with modularity in mind to allow easy expansion or modification for additional features or data fields.']

