#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE_ENBCONTEXT_CONFIGURE_REQUEST_T
typedef struct {
    int enodeb_id;
    char gummei[10]; // Assuming GUMMEI is a fixed length string of max 9 chars + '\0'
    int plmn_count;
    char **plmns; // List of PLMN_IDs, assumed to be strings here
} LTE_ENBCONTEXT_CONFIGURE_REQUEST_T;

// Define the structure for managing dynamic list
typedef struct {
    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *requests;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

// Function prototypes
DynamicList* create_dynamic_list(size_t initial_capacity);
int add_request(DynamicList *list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T request);
void free_dynamic_list(DynamicList *list);

// Helper functions for validation
int is_valid_gummei(const char *gummei) {
    if (strlen(gummei) >= sizeof(((LTE_ENBCONTEXT_CONFIGURE_REQUEST_T*)0)->gummei)) return 0;
    // Additional GUMMEI validation logic can be added here
    return 1;
}

int is_valid_request(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *request) {
    if (request->enodeb_id < 0 || !is_valid_gummei(request->gummei)) return 0;
    for (int i = 0; i < request->plmn_count; ++i) {
        if (!request->plmns[i] || strlen(request->plmns[i]) == 0) return 0;
    }
    return 1;
}

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        return NULL;
    }

    list->requests = calloc(initial_capacity, sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T));
    if (!list->requests) {
        fprintf(stderr, "Failed to allocate memory for requests\n");
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_request(DynamicList *list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T request) {
    if (!is_valid_request(&request)) {
        fprintf(stderr, "Invalid request data\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *new_requests =
            realloc(list->requests, new_capacity * sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T));
        if (!new_requests) {
            fprintf(stderr, "Failed to reallocate memory for requests\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->requests = new_requests;
        list->capacity = new_capacity;
    }

    memcpy(&list->requests[list->count], &request, sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T));
    ++list->count;

    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void free_dynamic_list(DynamicList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        LTE_ENBCONTEXT_CONFIGURE_REQUEST_T *req = &list->requests[i];
        for (int j = 0; j < req->plmn_count; ++j) {
            free(req->plmns[j]);
        }
        free(req->plmns);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list->requests);
    free(list);
}
```

### Key Features Implemented:

- **Thread-Safety**: Mutex locks ensure that multiple threads can safely add requests to the list.
- **Dynamic Resizing**: The dynamic resizing doubles the capacity when necessary, accommodating up to 10,000 structures efficiently.
- **Validation Logic**: Validates `GUMMEI` and `PLMN_IDs`, rejecting invalid or malformed data without impacting performance significantly.
- **Error Handling**: Gracefully handles memory allocation failures with appropriate error messages.
- **Memory Management**: Efficiently allocates/deallocates memory for requests and their internal resources.']

