// Function to allocate a new session
int createSession(SessionManager *manager, const char *sessionID, const char *url) {
    if (manager->activeCount >= MAX_SESSIONS) {
        fprintf(stderr, "Error: Maximum session limit reached.\n");
        return -1;
    }

    UserSession *newSession = malloc(sizeof(UserSession));
    if (!newSession) {
        fprintf(stderr, "Error: Memory allocation failed for new session.\n");
        return -1;
    }

    strncpy(newSession->sessionID, sessionID, sizeof(newSession->sessionID) - 1);
    newSession->timestamp = time(NULL);
    newSession->status = ACTIVE;
    strncpy(newSession->lastAccessedURL, url, sizeof(newSession->lastAccessedURL) - 1);

    manager->sessions[manager->activeCount++] = newSession;
    logEvent("Initiated", sessionID);

    return 0;
}

// Function to terminate a session
int terminateSession(SessionManager *manager, const char *sessionID) {
    for (int i = 0; i < manager->activeCount; ++i) {
        if (strcmp(manager->sessions[i]->sessionID, sessionID) == 0) {
            manager->sessions[i]->status = TERMINATED;
            logEvent("Terminated", sessionID);
            return 0;
        }
