    time_t now = time(NULL);
    for (int i = 0; i < manager->activeCount;) {
        if (difftime(now, manager->sessions[i]->timestamp) > 3600 && // Example: 1 hour expiration
            manager->sessions[i]->status == ACTIVE) {

            terminateSession(manager, manager->sessions[i]->sessionID);
            free(manager->sessions[i]);
            manager->sessions[i] = manager->sessions[--manager->activeCount];
