#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 1024
#define UCI_BUFFER_SIZE 256

typedef struct {
    int valid;
    int RNTI; // Resource Allocation ID
} RX_UE_INFO_TAG;

typedef struct {
    RX_UE_INFO_TAG ue_info_tag;
    unsigned char *uci_buffer; // Uplink Control Information buffer
} LTE_PHY_RX_FRAME_INFO;

typedef struct Node {
    LTE_PHY_RX_FRAME_INFO frame_info;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t pool_size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int active_frames;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->pool_size = initial_size;
    pool->active_frames = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) break;
        node->frame_info.uci_buffer = malloc(UCI_BUFFER_SIZE);
        if (!node->frame_info.uci_buffer) {
            free(node);
            break;
        }
        node->next = pool->head;
        pool->head = node;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    Node* current = pool->head;
    while (current) {
        Node* next = current->next;
        free(current->frame_info.uci_buffer);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond_var);
    free(pool);
}

LTE_PHY_RX_FRAME_INFO allocate_frame(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    while (!pool->head && pool->active_frames < pool->pool_size) {
        pthread_cond_wait(&pool->cond_var, &pool->lock);
    }

    if (pool->head == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return (LTE_PHY_RX_FRAME_INFO){0}; // Allocation failed
    }

    Node* node = pool->head;
    pool->head = node->next;
    pool->active_frames++;

    LTE_PHY_RX_FRAME_INFO frame_info = node->frame_info;
    free(node);

    pthread_mutex_unlock(&pool->lock);
    return frame_info;
}

void deallocate_frame(MemoryPool* pool, LTE_PHY_RX_FRAME_INFO* frame_info) {
    if (!frame_info->uci_buffer) return;

    Node* node = malloc(sizeof(Node));
    node->frame_info = *frame_info;
    node->next = NULL;

    pthread_mutex_lock(&pool->lock);

    node->next = pool->head;
    pool->head = node;
    pool->active_frames--;

    pthread_cond_signal(&pool->cond_var);
    pthread_mutex_unlock(&pool->lock);
}

void resize_memory_pool(MemoryPool* pool, size_t new_size) {
    if (new_size <= pool->pool_size) return;

    for (size_t i = pool->pool_size; i < new_size; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) break;
        node->frame_info.uci_buffer = malloc(UCI_BUFFER_SIZE);
        if (!node->frame_info.uci_buffer) {
            free(node);
            break;
        }
        node->next = pool->head;
        pool->head = node;
    }

    pthread_mutex_lock(&pool->lock);
    pool->pool_size = new_size;
    pthread_mutex_unlock(&pool->lock);
}

void garbage_collection(MemoryPool* pool) {
    // Simplified example: could be scheduled periodically
    while (1) {
        sleep(10); // Garbage collection interval

        pthread_mutex_lock(&pool->lock);

        if (pool->active_frames < pool->pool_size / 2 && pool->head == NULL) {
            resize_memory_pool(pool, pool->pool_size / 2);
        }

        pthread_mutex_unlock(&pool->lock);
    }
}

int main() {
    MemoryPool* pool = create_memory_pool(INITIAL_POOL_SIZE);

    // Example usage: Start a separate thread for garbage collection
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, (void*)garbage_collection, pool);

    // Allocate and deallocate frames in the pool as needed

    // Ensure to join threads and destroy the memory pool properly
    pthread_join(gc_thread, NULL);
    destroy_memory_pool(pool);

    return 0;
}
```

