#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10000
#define CONNECTION_SIZE sizeof(Connection)
#define MEMORY_LIMIT (MAX_CONNECTIONS * CONNECTION_SIZE)
#define RETRY_BASE_DELAY 100 // milliseconds

typedef enum {
    ACTIVE,
    IDLE,
    CLOSED
} ConnectionStatus;

typedef struct {
    int uniqueID;
    time_t timestamp;
    ConnectionStatus status;
    char clientIP[16]; // Assuming IPv4 addresses
    time_t sessionExpiry;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_capacity) {
    if (initial_capacity > MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Initial capacity exceeds maximum allowed connections.\n");
        return NULL;
    }

    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) {
        perror("Failed to allocate memory for ConnectionManager");
        return NULL;
    }

    manager->connections = calloc(initial_capacity, sizeof(Connection));
    if (!manager->connections) {
        perror("Failed to allocate memory for connections");
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (manager) {
        free(manager->connections);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_connection(ConnectionManager *manager, Connection new_conn) {
    if (!manager || manager->count >= MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Maximum connection count exceeded or invalid manager.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    // Ensure that no more connections are added once memory limit is reached
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity * CONNECTION_SIZE > MEMORY_LIMIT) {
            fprintf(stderr, "Error: Memory limit exceeded.\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        Connection *new_connections = realloc(manager->connections, new_capacity * sizeof(Connection));
        if (!new_connections) {
            perror("Failed to reallocate memory for connections");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    memcpy(manager->connections + manager->count, &new_conn, sizeof(Connection));
    manager->connections[manager->count].timestamp = time(NULL); // Current timestamp
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int close_idle_connections(ConnectionManager *manager) {
    if (!manager) {
        fprintf(stderr, "Error: Invalid manager.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].status == IDLE && 
            difftime(now, manager->connections[i].timestamp) > (manager->connections[i].sessionExpiry - now)) {
            manager->connections[i].status = CLOSED;
            // Log connection closure
            printf("Connection %d closed at %ld\n", manager->connections[i].uniqueID, now);
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void log_connection_event(int uniqueID, const char *event) {
    time_t timestamp = time(NULL);
    printf("Event: %s for connection ID %d at %ld\n", event, uniqueID, timestamp);
}

// Example function to handle load and graceful shutdown, with retry logic
int retry_with_exponential_backoff(void (*operation)(void), int max_attempts) {
    int attempt = 0;
    int delay = RETRY_BASE_DELAY;

    while (attempt < max_attempts) {
        operation();

        if (/* Operation succeeded condition */) {
            return 0; // Success
        }

        sleep(delay / 1000); // Convert milliseconds to seconds for sleep
        delay *= 2;
        attempt++;
    }

    fprintf(stderr, "Operation failed after %d attempts\n", max_attempts);
    return -1;
}

// Main function to demonstrate usage
int main() {
    ConnectionManager *manager = create_connection_manager(1000);
    if (!manager) return EXIT_FAILURE;

    Connection conn = { .uniqueID = 1, .status = ACTIVE, .clientIP = "192.168.1.1", .sessionExpiry = time(NULL) + 300 };

    if (add_connection(manager, conn) == -1) {
        destroy_connection_manager(manager);
        return EXIT_FAILURE;
    }

    close_idle_connections(manager);

    destroy_connection_manager(manager);
    return EXIT_SUCCESS;
}
```

This code provides a basic structure for managing network connections in C. It includes dynamic memory management, thread safety with mutexes, and some error handling. The connection manager supports adding connections up to a maximum capacity, resizing the memory dynamically, and closing idle connections. Additionally, it includes logging of events and retry logic using exponential backoff. You can expand this code further based on your specific requirements, such as integrating a caching mechanism or implementing advanced load balancing strategies.']

