    initialize_records(offsets, keys, records, num_records);

    // Free allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].data);
    }
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
