['Below is a simplified C implementation of the described task using POSIX threads (pthreads) for concurrency, along with some basic memory management and error handling mechanisms. This example covers the core requirements but may need further refinement for specific use cases:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1000

typedef struct Record {
    int key;
    long offset;
    double weight;
    char identifier[10];
    float score;
    struct Record *next; // for chaining in hash table
} Record;

typedef struct Node {
    Record *record;
    struct Node *next; // linked list for insertion order
} Node;

typedef struct SortedNode {
    Record *record;
    struct SortedNode *next; // sorted by key
} SortedNode;

Record **hashTable;
pthread_mutex_t locks[TABLE_SIZE];
int nextKey = 0;
Node *headInsertionOrder = NULL;
SortedNode *headSortedOrder = NULL;
pthread_rwlock_t readWriteLock = PTHREAD_RWLOCK_INITIALIZER;

void initializeHashTable(int seed) {
    srand(seed);
    hashTable = (Record **)malloc(TABLE_SIZE * sizeof(Record *));
    if (!hashTable) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&locks[i], NULL);
    }
}

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

Record *createRecord(char identifier[], float score, long offsetRange, double weightRange) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    record->key = nextKey++;
    record->offset = rand() % offsetRange;
    record->weight = ((double)rand() / RAND_MAX) * weightRange;
    strncpy(record->identifier, identifier, sizeof(record->identifier));
    record->score = score;
    record->next = NULL;
    return record;
}

void insertRecord(char identifier[], float score, long offsetRange, double weightRange) {
    pthread_rwlock_wrlock(&readWriteLock);

    Record *record = createRecord(identifier, score, offsetRange, weightRange);
    unsigned int index = hash(record->key);

    pthread_mutex_lock(&locks[index]);
    record->next = hashTable[index];
    hashTable[index] = record;
    pthread_mutex_unlock(&locks[index]);

    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for linked list node");
        exit(EXIT_FAILURE);
    }
    newNode->record = record;
    newNode->next = headInsertionOrder;
    headInsertionOrder = newNode;

    SortedNode *sortedNode = (SortedNode *)malloc(sizeof(SortedNode));
    if (!sortedNode) {
        perror("Failed to allocate memory for sorted linked list node");
        exit(EXIT_FAILURE);
    }
    sortedNode->record = record;

    pthread_mutex_lock(&locks[index]);
    if (!headSortedOrder || headSortedOrder->record->key > record->key) {
        sortedNode->next = headSortedOrder;
        headSortedOrder = sortedNode;
    } else {
        SortedNode *current = headSortedOrder;
        while (current->next && current->next->record->key < record->key) {
            current = current->next;
        }
        sortedNode->next = current->next;
        current->next = sortedNode;
    }
    pthread_mutex_unlock(&locks[index]);

    pthread_rwlock_unlock(&readWriteLock);
}

void iterateInsertionOrder(void (*callback)(Record*)) {
    Node *current = headInsertionOrder;
    while (current) {
        callback(current->record);
        current = current->next;
    }
}

void iterateKeySortedOrder(void (*callback)(Record*)) {
    SortedNode *current = headSortedOrder;
    while (current) {
        callback(current->record);
        current = current->next;
    }
}

void freeResources() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&locks[i]);
    }
    free(hashTable);

    Node *node = headInsertionOrder;
    while (node) {
        Record *record = node->record;
        Node *nextNode = node->next;
        free(record);
        free(node);
        node = nextNode;
    }

    SortedNode *sortedNode = headSortedOrder;
    while (sortedNode) {
        Record *record = sortedNode->record;
        SortedNode *nextSortedNode = sortedNode->next;
        // Do not free record as it is shared with insertion order list
        free(sortedNode);
        sortedNode = nextSortedNode;
    }

    pthread_rwlock_destroy(&readWriteLock);
}

int main() {
    initializeHashTable(42);  // Optional seed for reproducibility

    insertRecord("A", 95.5, 1000, 50.0);
    insertRecord("B", 88.2, 2000, 75.0);

    iterateInsertionOrder([](Record *record) {
        printf("Insertion Order: %d %s\n", record->key, record->identifier);
    });

    iterateKeySortedOrder([](Record *record) {
        printf("Key Sorted Order: %d %s\n", record->key, record->identifier);
    });

    freeResources();
    return 0;
}
```

### Notes:
- **Concurrency:** The use of `pthread_rwlock_t` allows for multiple readers or a single writer at any time. Mutexes are used to protect hash table indices.
- **Memory Management:** Allocates and deallocates memory dynamically, ensuring no leaks with careful tracking of resources.
- **Error Handling:** Basic error handling is included, primarily focusing on allocation failures.
- **Scalability:** The design should scale well with increasing records; however, performance tuning might be necessary for specific large datasets.

This code provides a basic foundation and would need enhancements like better error recovery, more sophisticated memory pooling strategies, and detailed logging for production use.']

