#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
    long* offset_ref;
} record;

typedef struct {
    pthread_mutex_t lock;
    atomic_int initialized;
} random_state;

// Function prototypes
long* allocate_offsets(int n);
int* allocate_keys(int m);
record* allocate_records(int k, long* offsets);
void generate_random_values(record* records, int limit, random_state* state);
void free_resources(long** offsets, int** keys, record** records);
void initialize_random_state(random_state* state);
void finalize_random_state(random_state* state);

// Memory allocation functions
long* allocate_offsets(int n) {
    if (n <= 0) return NULL;
    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* allocate_keys(int m) {
    if (m <= 0) return NULL;
    int* keys = malloc(m * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free_resources((long**)&offsets, &keys, (record**)&records);
        exit(EXIT_FAILURE);
    }
    return keys;
}

record* allocate_records(int k, long* offsets) {
    if (k <= 0 || !offsets) return NULL;
    record* records = malloc(k * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free_resources(&offsets, &keys, &records);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < k; ++i) {
        records[i].offset_ref = &offsets[i % ((k > 0) ? k : 1)];
    }
    return records;
}

// Random value generation
void generate_random_values(record* records, int limit, random_state* state) {
    if (!records || !state->initialized) return;

    pthread_mutex_lock(&state->lock);
    int total = 0;
    for (int i = 0; i < 100 && total < limit; ++i) {
        int rand_val = rand() % (limit - total + 1);
        records[i].value = rand_val;
        total += rand_val;
        if (total >= limit) break;
    }
    pthread_mutex_unlock(&state->lock);
}

// Memory deallocation
void free_resources(long** offsets, int** keys, record** records) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) free(*records);
}

// Random state initialization and finalization
void initialize_random_state(random_state* state) {
    pthread_mutex_init(&state->lock, NULL);
    atomic_store(&state->initialized, 1);
}

void finalize_random_state(random_state* state) {
    pthread_mutex_destroy(&state->lock);
}

int main() {
    int n = 1000, m = 500, k = 300, L = 10000;
    random_state rand_state;

    initialize_random_state(&rand_state);

    long* offsets = allocate_offsets(n);
    int* keys = allocate_keys(m);
    record* records = allocate_records(k, offsets);

    generate_random_values(records, L, &rand_state);

    free_resources(&offsets, &keys, &records);
    finalize_random_state(&rand_state);

    return 0;
}
```

