#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h>

typedef struct {
    int key;
    char identifier;
    float score;
    char *file_path;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node **table;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
    unsigned long seed;
} HashTable;

HashTable* create_hash_table(size_t initial_size, unsigned long seed) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = initial_size;
    ht->count = 0;
    ht->seed = seed;
    pthread_mutex_init(&ht->lock, NULL);
    pthread_rwlock_init(&ht->rwlock, NULL);

    ht->table = calloc(initial_size, sizeof(Node*));
    return ht;
}

unsigned long hash(int key, size_t size) {
    unsigned long hash_value = (key * 2654435761u) % size;
    return hash_value;
}

void resize_hash_table(HashTable *ht);

int insert_record(HashTable *ht, Record record) {
    pthread_rwlock_wrlock(&ht->rwlock);

    if ((float)ht->count / ht->size > 0.7) {
        resize_hash_table(ht);
    }

    size_t index = hash(record.key, ht->size);
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = ht->table[index];
    ht->table[index] = node;

    ht->count++;
    pthread_rwlock_unlock(&ht->rwlock);

    return 0;
}

void resize_hash_table(HashTable *ht) {
    size_t new_size = ht->size * 2;
    Node **new_table = calloc(new_size, sizeof(Node*));

    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->table[i];

        while (node) {
            size_t index = hash(node->record.key, new_size);
            Node *next_node = node->next;

            node->next = new_table[index];
            new_table[index] = node;
            node = next_node;
        }
    }

    free(ht->table);
    ht->size = new_size;
    ht->table = new_table;
}

Record* lookup_record(HashTable *ht, int key) {
    pthread_rwlock_rdlock(&ht->rwlock);

    size_t index = hash(key, ht->size);
    Node *node = ht->table[index];

    while (node) {
        if (node->record.key == key) {
            Record *result = malloc(sizeof(Record));
            memcpy(result, &node->record, sizeof(Record));
            pthread_rwlock_unlock(&ht->rwlock);
            return result;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&ht->rwlock);
    return NULL;
}

void free_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->table[i];

        while (node) {
            Node *next_node = node->next;
            free(node->record.file_path);
            free(node);
            node = next_node;
        }
    }

    pthread_rwlock_destroy(&ht->rwlock);
    pthread_mutex_destroy(&ht->lock);
    free(ht->table);
    free(ht);
}

void export_to_json(HashTable *ht, const char *filename) {
    json_t *root = json_array();

    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->table[i];

        while (node) {
            json_t *record_obj = json_object();

            json_object_set_new(record_obj, "key", json_integer(node->record.key));
            json_object_set_new(record_obj, "identifier", json_string(&node->record.identifier, 1));
            json_object_set_new(record_obj, "score", json_real(node->record.score));
            json_object_set_new(record_obj, "file_path", json_string(node->record.file_path));

            json_array_append_new(root, record_obj);
            node = node->next;
        }
    }

    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Unable to open file for writing");
        return;
    }

    char *json_str = json_dumps(root, JSON_INDENT(4));
    fprintf(fp, "%s", json_str);
    fclose(fp);

    free(json_str);
    json_decref(root);
}

void cleanup_record(Record *record) {
    if (record && record->file_path) {
        free(record->file_path);
    }
    free(record);
}

// Example function to generate random records
void populate_hash_table_with_random_data(HashTable *ht, size_t num_records) {
    srand(ht->seed);

    for (size_t i = 0; i < num_records; ++i) {
        Record record;

        record.key = rand() % 10000;
        record.identifier = 'A' + rand() % 26;
        record.score = (float)(rand() % 100) / 10.0;

        size_t path_len = rand() % 20 + 5; // Random length between 5 and 25
        char *path = malloc(path_len + 1);

        for (size_t j = 0; j < path_len; ++j) {
            path[j] = 'A' + rand() % 26;
        }
        path[path_len] = '\0';

        record.file_path = strdup(path);

        insert_record(ht, record);
    }
}

int main() {
    size_t initial_size = 16;
    unsigned long seed = time(NULL); // Example seed for reproducibility

    HashTable *ht = create_hash_table(initial_size, seed);
    populate_hash_table_with_random_data(ht, 100);

    export_to_json(ht, "records.json");

    Record *record = lookup_record(ht, 42);
    if (record) {
        printf("Record found: Key=%d, Identifier=%c, Score=%.2f, File Path=%s\n",
               record->key, record->identifier, record->score, record->file_path);

        cleanup_record(record);
    } else {
        printf("Record not found.\n");
    }

    free_hash_table(ht);

    return 0;
}
