import hashlib
from tifffile import TiffFile, TiffPageSeries
from proprietary_compression_lib import detect_compression_type, decompress_data

class TIFFProcessingError(Exception):
    pass

def parseTIFFAndHash(file_path):
    def read_file_in_chunks(file_obj, chunk_size=1024*1024):
        while True:
            data = file_obj.read(chunk_size)
            if not data:
                break
            yield data

    try:
        with open(file_path, 'rb') as f:
            header_bytes = f.read(24)  # Assuming the compression type can be determined from first 24 bytes

            compression_type = detect_compression_type(header_bytes)

            if compression_type == "proprietary":
                decompressed_data = b''
                for chunk in read_file_in_chunks(f):
                    decompressed_chunk = decompress_data(chunk, compression_type)
                    decompressed_data += decompressed_chunk
                tiff_content = decompressed_data
            else:
                f.seek(0)  # Reset file pointer after reading header
                tiff_content = b''.join(read_file_in_chunks(f))

        try:
            with TiffFile(io.BytesIO(tiff_content)) as tif:
                pages = TiffPageSeries(pages=tif.pages)

                if not pages:
                    raise TIFFProcessingError("No TIFF image pages found.")

                hash_md5 = hashlib.md5()

                for page in pages:
                    tile = page.asarray(memmap=True)  # Efficiently read tiles of the image
                    hash_md5.update(tile.tobytes())

                return hash_md5.hexdigest()

        except Exception as e:
            raise TIFFProcessingError(f"Failed to process TIFF: {str(e)}")

    except IOError as io_err:
        raise TIFFProcessingError(f"I/O error({io_err.errno}): {io_err.strerror}")

# Usage example
try:
    file_hash = parseTIFFAndHash('path/to/tiff_or_compressed_tiff_file.tif')
    print("MD5 Hash:", file_hash)
except TIFFProcessingError as e:
    print("Error processing TIFF file:", str(e))
