['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 101

typedef struct Record {
    int key;
    long offset;
    double weight;
    char identifier;
    float score;
    struct Record *next_in_chain;
    struct Record *next_in_order;
} Record;

typedef struct HashTable {
    Record **buckets;
    pthread_mutex_t lock;
} HashTable;

typedef struct LinkedList {
    Record *head;
    pthread_rwlock_t rwlock;
} LinkedList;

HashTable *create_hash_table();
LinkedList *create_linked_list();
void insert_record(HashTable *table, LinkedList *order_list, LinkedList *key_sorted, int key_seed);
Record *find_record(HashTable *table, int key);
void destroy_resources(HashTable *table, LinkedList *order_list, LinkedList *key_sorted);

unsigned long hash(int key) {
    return (unsigned long)key % TABLE_SIZE;
}

HashTable *create_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    table->buckets = calloc(TABLE_SIZE, sizeof(Record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

LinkedList *create_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void insert_record(HashTable *table, LinkedList *order_list, LinkedList *key_sorted, int key_seed) {
    pthread_mutex_lock(&table->lock);

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&table->lock);
        perror("Failed to allocate memory for new record");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL) ^ (key_seed << 16));

    new_record->key = rand() % TABLE_SIZE;
    while (find_record(table, new_record->key)) {
        new_record->key = rand() % TABLE_SIZE;
    }
    new_record->offset = rand() % 1000000L;
    new_record->weight = (double)(rand() % 10000) / 100.0;
    new_record->identifier = 'A' + rand() % 26;
    new_record->score = (float)(rand() % 1000) / 10.0;

    unsigned long index = hash(new_record->key);
    new_record->next_in_chain = table->buckets[index];
    table->buckets[index] = new_record;

    pthread_mutex_unlock(&table->lock);

    pthread_rwlock_wrlock(&order_list->rwlock);
    new_record->next_in_order = order_list->head;
    order_list->head = new_record;
    pthread_rwlock_unlock(&order_list->rwlock);

    // Insert into key sorted linked list
    pthread_rwlock_wrlock(&key_sorted->rwlock);
    Record *current = key_sorted->head, *previous = NULL;
    while (current && current->key < new_record->key) {
        previous = current;
        current = current->next_in_order;
    }
    if (!previous) {
        new_record->next_in_order = key_sorted->head;
        key_sorted->head = new_record;
    } else {
        new_record->next_in_order = previous->next_in_order;
        previous->next_in_order = new_record;
    }
    pthread_rwlock_unlock(&key_sorted->rwlock);
}

Record *find_record(HashTable *table, int key) {
    unsigned long index = hash(key);

    pthread_mutex_lock(&table->lock);
    Record *record = table->buckets[index];
    while (record) {
        if (record->key == key) {
            pthread_mutex_unlock(&table->lock);
            return record;
        }
        record = record->next_in_chain;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

void destroy_resources(HashTable *table, LinkedList *order_list, LinkedList *key_sorted) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Record *record = table->buckets[i];
        while (record) {
            Record *next = record->next_in_chain;
            free(record);
            record = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);

    Record *record = order_list->head;
    while (record) {
        Record *next = record->next_in_order;
        free(record);
        record = next;
    }
    pthread_rwlock_destroy(&order_list->rwlock);
    free(order_list);

    record = key_sorted->head;
    while (record) {
        Record *next = record->next_in_order;
        free(record);
        record = next;
    }
    pthread_rwlock_destroy(&key_sorted->rwlock);
    free(key_sorted);
}

int main() {
    HashTable *table = create_hash_table();
    LinkedList *order_list = create_linked_list();
    LinkedList *key_sorted = create_linked_list();

    insert_record(table, order_list, key_sorted, 12345);

    Record *found = find_record(table, 1); // Example lookup
    if (found) {
        printf("Record found with key: %d\n", found->key);
    } else {
        printf("Record not found.\n");
    }

    destroy_resources(table, order_list, key_sorted);
    return 0;
}
```

This code implements a hash table with chaining for collision resolution and supports concurrent operations using mutexes and read-write locks. It also maintains linked lists for insertion order and key-sorted iteration. The `main` function demonstrates basic usage.']

