// Sandesh client to send GET request and verify response
void sandeshClient() {
    try {
        boost::asio::io_context ioc;
        tcp::resolver resolver(ioc);
        auto const results = resolver.resolve("example.com", "http");
        beast::tcp_stream stream(ioc);
        stream.connect(results);

        http::request<http::string_body> req{http::verb::get, "/", 11};
        req.set(http::field::host, "example.com");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        http::write(stream, req);

        beast::flat_buffer buffer;
        http::response<http::dynamic_body> res;

        http::read(stream, buffer, res);

        if (res.result() == http::status::ok) {
            std::cout << "Response verified: " << res.body() << std::endl;
        } else {
            std::cerr << "Unexpected response status: " << res.result_int() << std::endl;
