        for (const auto& file : configFiles) {
            std::ifstream ifs(file);
            nlohmann::json j = nlohmann::json::parse(ifs);

            for (auto& item : j["services"]) {
                if (services.find(item["port"].get<int>()) != services.end()) {
                    throw std::runtime_error("Duplicate port detected");
                }

                Service service;
                service.name = item["name"];
                service.port = item["port"];
                service.protocol = item["protocol"];
                // Assuming callback functions are defined elsewhere
                service.callback = nullptr; 
                service.priority = item["priority"];

                services[service.port] = service;
            }
        }

        Service* serviceArray = new Service[services.size()];
        size_t index = 0;

        for (auto& [port, svc] : services) {
            serviceArray[index++] = svc;
        }

        serviceCount = services.size();
        return serviceArray;
    } catch (std::exception& e) {
        std::cerr << "Error loading network services: " << e.what() << std::endl;
