        pthread_mutex_lock(&memory_pool.lock);

        if (memory_pool.count >= MAX_RECORDS) {
            log_message("Memory limit reached");
            pthread_mutex_unlock(&memory_pool.lock);
            break;
        }

        Record *record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            pthread_mutex_unlock(&memory_pool.lock);
