        memory_pool.records[memory_pool.count++] = record;
        pthread_mutex_unlock(&memory_pool.lock);

        // Simulate processing delay
        usleep(1000); 
    }

    log_message("Processing file ended");
}

void *worker_thread(void *arg) {
    FileTask *task = (FileTask *)arg;

    size_t total_size = task->size; // Assume size is set appropriately
    size_t chunk_size = total_size / BATCH_SIZE;

    for (size_t i = 0; i < BATCH_SIZE; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == BATCH_SIZE - 1) ? total_size : start + chunk_size;

        process_file(task, start, end);
    }

    return NULL;
}

void report_progress(size_t processed, size_t total) {
    log_message("Progress update: ");
    printf("%zu/%zu files processed\n", processed, total);
