} DocumentProcessor;

void initialize_processor(DocumentProcessor *processor) {
    memset(processor, 0, sizeof(*processor));
    pthread_mutex_init(&processor->lock, NULL);
}

void cleanup_entry(Entry *entry) {
    free(entry->float_array);
    entry->float_array = NULL;
}

void cleanup_processor(DocumentProcessor *processor) {
    for (size_t i = 0; i < processor->total_processed; ++i) {
        if (processor->entries[i].file_content) {
            free(processor->entries[i].file_content->content);
            free(processor->entries[i].file_content);
        }
    }
    pthread_mutex_destroy(&processor->lock);
}

float gaussian_random(float mean, float stddev) {
    static const double two_pi = 2.0 * M_PI;
    static double phi = 0;
    if (phi == 0) {
        phi = rand() / (RAND_MAX + 1.0);
    }
    return mean + stddev * sqrt(-2.0 * log(rand() / (RAND_MAX + 1.0))) * cos(two_pi * phi++);
}

void resize_float_array(Entry *entry, size_t new_size) {
    float *new_array = realloc(entry->float_array, new_size * sizeof(float));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed for resizing float array\n");
        cleanup_entry(entry);
        exit(EXIT_FAILURE);
    }
    entry->float_array = new_array;
    memset(new_array + entry->float_count, 0, (new_size - entry->float_count) * sizeof(float));
    entry->max_float_count = new_size;
}

void populate_with_gaussian(Entry *entry, float mean, float stddev, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (i >= entry->max_float_count) {
            resize_float_array(entry, entry->max_float_count ? entry->max_float_count * 2 : 1);
        }
        entry->float_array[i] = gaussian_random(mean, stddev);
    }
    entry->float_count = count;
}

int add_metadata_entry(DocumentProcessor *processor, const char *metadata, int doc_size, FileContent *file_content) {
    pthread_mutex_lock(&processor->lock);

    if (processor->total_processed >= MAX_DOCUMENTS) {
        fprintf(stderr, "Document limit exceeded\n");
        pthread_mutex_unlock(&processor->lock);
        return -1;
    }

    MetadataEntry *entry = &processor->entries[processor->total_processed];
    strncpy(entry->metadata, metadata, METADATA_SIZE - 1);
    entry->metadata[METADATA_SIZE - 1] = '\0';
    entry->document_size = doc_size;

    FileContent *content_copy = malloc(sizeof(FileContent));
    if (!content_copy) {
        fprintf(stderr, "Memory allocation failed for file content\n");
        pthread_mutex_unlock(&processor->lock);
        return -1;
    }

    content_copy->size = doc_size;
    content_copy->content = malloc(doc_size);
    if (!content_copy->content) {
        fprintf(stderr, "Memory allocation failed for document content\n");
        free(content_copy);
        pthread_mutex_unlock(&processor->lock);
        return -1;
    }
    memcpy(content_copy->content, file_content->content, doc_size);

    entry->file_content = content_copy;

    processor->total_processed++;
    pthread_mutex_unlock(&processor->lock);
    return 0;
}

void serialize_processor(DocumentProcessor *processor, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        return;
    }

    fwrite(&processor->total_processed, sizeof(size_t), 1, file);
    for (size_t i = 0; i < processor->total_processed; ++i) {
        MetadataEntry *entry = &processor->entries[i];
        fwrite(entry->metadata, METADATA_SIZE, 1, file);
        fwrite(&entry->document_size, sizeof(int), 1, file);
        size_t content_size = entry->file_content ? entry->file_content->size : 0;
        fwrite(&content_size, sizeof(size_t), 1, file);
        if (content_size > 0) {
            fwrite(entry->file_content->content, content_size, 1, file);
        }
    }

    fclose(file);
}

void deserialize_processor(DocumentProcessor *processor, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return;
    }

    size_t total_processed;
    fread(&total_processed, sizeof(size_t), 1, file);
    if (total_processed > MAX_DOCUMENTS) {
        fprintf(stderr, "Deserialized document count exceeds maximum allowed\n");
        fclose(file);
        return;
    }
    processor->total_processed = total_processed;

    for (size_t i = 0; i < total_processed; ++i) {
        MetadataEntry *entry = &processor->entries[i];
        fread(entry->metadata, METADATA_SIZE, 1, file);
        fread(&entry->document_size, sizeof(int), 1, file);

        size_t content_size;
        fread(&content_size, sizeof(size_t), 1, file);
        if (content_size > 0) {
            FileContent *content_copy = malloc(sizeof(FileContent));
            content_copy->size = content_size;
            content_copy->content = malloc(content_size);
            fread(content_copy->content, content_size, 1, file);

            entry->file_content = content_copy;
        }
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    DocumentProcessor processor;
    initialize_processor(&processor);

    // Example usage
    FileContent example_file_content = { .content = "Example content", .size = 16 };
    add_metadata_entry(&processor, "Example metadata", example_file_content.size, &example_file_content);

    serialize_processor(&processor, "documents.dat");
    deserialize_processor(&processor, "documents.dat");

    cleanup_processor(&processor);

    return 0;
}
