#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define MESSAGE_SIZE 1024

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    char *key;
    char *value;
} KeyValuePair;

typedef struct {
    double timestamp;
    char *identifier;
    char message[MESSAGE_SIZE];
} Event;

typedef struct {
    double *timestamps;
    char **identifiers;
    Point *points;
    Event *events;
    char **categories;
    KeyValuePair **metadata;
    size_t event_count;
    pthread_mutex_t mutex;
} DataManager;

const char *category_list[] = {"Category1", "Category2", "Category3"};
size_t num_categories = sizeof(category_list) / sizeof(category_list[0]);

int allocate_data_manager(DataManager **manager, size_t initial_size) {
    if (initial_size > MAX_EVENTS) {
        fprintf(stderr, "Requested size exceeds maximum allowed events.\n");
        return -1;
    }

    *manager = malloc(sizeof(DataManager));
    if (!*manager) {
        perror("Failed to allocate DataManager");
        return -1;
    }

    (*manager)->timestamps = calloc(initial_size, sizeof(double));
    (*manager)->identifiers = calloc(initial_size, sizeof(char *));
    (*manager)->points = calloc(initial_size, sizeof(Point));
    (*manager)->events = calloc(initial_size, sizeof(Event));
    (*manager)->categories = malloc(num_categories * sizeof(char *));
    for (size_t i = 0; i < num_categories; ++i) {
        (*manager)->categories[i] = strdup(category_list[i]);
    }
    (*manager)->metadata = calloc(initial_size, sizeof(KeyValuePair *));
    (*manager)->event_count = 0;

    pthread_mutex_init(&(*manager)->mutex, NULL);

    return 0;
}

void free_data_manager(DataManager *manager) {
    for (size_t i = 0; i < manager->event_count; ++i) {
        if (manager->events[i].identifier)
            free(manager->events[i].identifier);
        free(manager->timestamps + i);
        free(manager->identifiers[i]);
        free(manager->points + i);
        free(manager->events[i].message);

        for (size_t j = 0; manager->metadata[i] && manager->metadata[i][j]; ++j) {
            free(manager->metadata[i][j].key);
            free(manager->metadata[i][j].value);
            free(manager->metadata[i][j]);
        }
        free(manager->metadata[i]);
    }

    for (size_t i = 0; i < num_categories; ++i) {
        free(manager->categories[i]);
    }

    free(manager->timestamps);
    free(manager->identifiers);
    free(manager->points);
    free(manager->events);
    free(manager->categories);
    free(manager->metadata);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_event(DataManager *manager, double timestamp, const char *identifier, const char *message_template) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->event_count >= MAX_EVENTS) {
        fprintf(stderr, "Maximum number of events reached.\n");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    size_t idx = manager->event_count++;
    manager->timestamps[idx] = timestamp;

    manager->events[idx].identifier = strdup(identifier);
    snprintf(manager->events[idx].message, MESSAGE_SIZE, message_template);

    // Example of adding metadata
    manager->metadata[idx] = malloc(sizeof(KeyValuePair *));
    manager->metadata[idx][0] = malloc(sizeof(KeyValuePair));
    manager->metadata[idx][0]->key = strdup("example_key");
    manager->metadata[idx][0]->value = strdup("example_value");

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void log_operation(const char *message) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int serialize_data_manager(DataManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->mutex);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    fwrite(&manager->event_count, sizeof(size_t), 1, file);
    fwrite(manager->timestamps, sizeof(double), manager->event_count, file);

    for (size_t i = 0; i < manager->event_count; ++i) {
        size_t len = strlen(manager->events[i].identifier);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(manager->events[i].identifier, sizeof(char), len + 1, file);

        len = strlen(manager->events[i].message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(manager->events[i].message, sizeof(char), len + 1, file);

        fwrite(&(manager->points[i]), sizeof(Point), 1, file);

        size_t metadata_count = 0;
        for (size_t j = 0; manager->metadata[i] && manager->metadata[i][j]; ++j) {
            metadata_count++;
        }
        fwrite(&metadata_count, sizeof(size_t), 1, file);
        for (size_t j = 0; manager->metadata[i] && manager->metadata[i][j]; ++j) {
            size_t key_len = strlen(manager->metadata[i][j]->key);
            size_t value_len = strlen(manager->metadata[i][j]->value);
            fwrite(&key_len, sizeof(size_t), 1, file);
            fwrite(manager->metadata[i][j]->key, sizeof(char), key_len + 1, file);
            fwrite(&value_len, sizeof(size_t), 1, file);
            fwrite(manager->metadata[i][j]->value, sizeof(char), value_len + 1, file);
        }
    }

    fclose(file);
    pthread_mutex_unlock(&manager->mutex);

    log_operation("Serialized data manager to file");
    return 0;
}

int deserialize_data_manager(DataManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->mutex);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    fread(&manager->event_count, sizeof(size_t), 1, file);
    manager->timestamps = realloc(manager->timestamps, manager->event_count * sizeof(double));
    fread(manager->timestamps, sizeof(double), manager->event_count, file);

    for (size_t i = 0; i < manager->event_count; ++i) {
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        manager->events[i].identifier = malloc(len + 1);
        fread(manager->events[i].identifier, sizeof(char), len + 1, file);

        fread(&len, sizeof(size_t), 1, file);
        fread(manager->events[i].message, sizeof(char), len + 1, file);

        fread(&(manager->points[i]), sizeof(Point), 1, file);

        size_t metadata_count;
        fread(&metadata_count, sizeof(size_t), 1, file);
        manager->metadata[i] = malloc(metadata_count * sizeof(KeyValuePair *));
        for (size_t j = 0; j < metadata_count; ++j) {
            manager->metadata[i][j] = malloc(sizeof(KeyValuePair));
            fread(&(manager->metadata[i][j]->key), sizeof(size_t), 1, file);
            manager->metadata[i][j]->key = malloc(manager->metadata[i][j]->key + 1);
            fread(manager->metadata[i][j]->key, sizeof(char), manager->metadata[i][j]->key + 1, file);

            fread(&(manager->metadata[i][j]->value), sizeof(size_t), 1, file);
            manager->metadata[i][j]->value = malloc(manager->metadata[i][j]->value + 1);
            fread(manager->metadata[i][j]->value, sizeof(char), manager->metadata[i][j]->value + 1, file);
        }
    }

    fclose(file);
    pthread_mutex_unlock(&manager->mutex);

    log_operation("Deserialized data manager from file");
    return 0;
}

int main() {
    DataManager *manager = NULL;
    if (allocate_data_manager(&manager, 10) != 0) {
        return -1;
    }

    add_event(manager, 1627849200.0, "Event1", "This is a test event message.");
    serialize_data_manager(manager, "data.dat");
    deserialize_data_manager(manager, "data.dat");

    free_data_manager(manager);
    return 0;
}
