#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h>  // For JSON parsing
#include <curl/curl.h> // For interacting with external API

#define MAX_PACKETS 1024
#define CONFIG_FILE "config.json"

typedef struct {
    int id;
    time_t timestamp;
    int status_flag; // Example: 0 = inactive, 1 = active
    char *payload;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
    time_t expiration_threshold;
} PacketManager;

// Helper structure for reading integers from input
typedef struct {
    int *array;
    size_t size;
} IntList;

// Function to read configuration file and set parameters
int load_config(const char *filename, time_t *expiration_threshold) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *json_data = malloc(fsize + 1);
    fread(json_data, 1, fsize, file);
    fclose(file);
    json_data[fsize] = 0;

    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);
    free(json_data);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *exp_threshold = json_object_get(root, "expirationThreshold");
    if (json_is_number(exp_threshold)) {
        *expiration_threshold = json_integer_value(exp_threshold);
    } else {
        fprintf(stderr, "Invalid expiration threshold in config file.\n");
        json_decref(root);
        return -1;
    }

    json_decref(root);
    return 0;
}

// Function to read integers from standard input
IntList *read_integers_from_input() {
    IntList *int_list = malloc(sizeof(IntList));
    int_list->array = NULL;
    int_list->size = 0;

    printf("Enter integers (end with a non-integer):\n");
    int value;
    while (scanf("%d", &value) == 1) {
        int_list->array = realloc(int_list->array, sizeof(int) * (int_list->size + 1));
        if (!int_list->array) {
            perror("Failed to allocate memory for integer list");
            free(int_list);
            return NULL;
        }
        int_list->array[int_list->size++] = value;
    }

    // Clear the input buffer
    while (getchar() != '\n');

    return int_list;
}

// Helper function to find and print the largest integer in an array
int find_largest_integer(const IntList *int_list) {
    if (int_list->size == 0) {
        fprintf(stderr, "No integers provided.\n");
        return -1; // or some other appropriate value
    }

    int max = int_list->array[0];
    for (size_t i = 1; i < int_list->size; ++i) {
        if (int_list->array[i] > max) {
            max = int_list->array[i];
        }
    }

    printf("Largest integer: %d\n", max);
    return max;
}

// Function to add a new packet
void add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_PACKETS) {
        fprintf(stderr, "Maximum number of packets reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->id == packet->id) {
            fprintf(stderr, "Packet with ID %d already exists.\n", packet->id);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);

    printf("Packet with ID %d added.\n", packet->id);
}

// Function to update an existing packet
void update_packet(PacketManager *manager, int id, time_t timestamp, int status_flag, const char *payload) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->id == id) {
            manager->packets[i]->timestamp = timestamp;
            manager->packets[i]->status_flag = status_flag;
            free(manager->packets[i]->payload);
            manager->packets[i]->payload = strdup(payload);

            pthread_mutex_unlock(&manager->lock);
            printf("Packet with ID %d updated.\n", id);
            return;
        }
    }

    fprintf(stderr, "Packet with ID %d not found.\n", id);
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a packet by its identifier
DataPacket *get_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->id == id) {
            DataPacket *packet = manager->packets[i];
            pthread_mutex_unlock(&manager->lock);
            return packet;
        }
    }

    fprintf(stderr, "Packet with ID %d not found.\n", id);
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to purge expired packets
void purge_expired_packets(PacketManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if ((current_time - manager->packets[i]->timestamp) > manager->expiration_threshold) {
            printf("Purging expired packet with ID %d.\n", manager->packets[i]->id);
            free(manager->packets[i]->payload);
            free(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], sizeof(DataPacket *) * (manager->count - i - 1));
            --manager->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to initialize and manage packets
void initialize_and_manage_packets() {
    PacketManager manager = { .packets = {NULL}, .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

    if (load_config(CONFIG_FILE, &manager.expiration_threshold) != 0) {
        fprintf(stderr, "Failed to load configuration.\n");
        return;
    }

    // Example of adding packets
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->id = 1;
    new_packet->timestamp = time(NULL);
    new_packet->status_flag = 1;
    new_packet->payload = strdup("Sample Payload");

    add_packet(&manager, new_packet);

    // Example of updating a packet
    update_packet(&manager, 1, time(NULL), 0, "Updated Payload");

    // Example of retrieving a packet
    DataPacket *packet = get_packet(&manager, 1);
    if (packet) {
        printf("Retrieved Packet ID %d\n", packet->id);
    }

    // Read and process integers from input
    IntList *int_list = read_integers_from_input();
    if (int_list) {
        find_largest_integer(int_list);
        free(int_list->array);
        free(int_list);
    }

    // Purge expired packets periodically
    purge_expired_packets(&manager);

    // Clean up remaining packets
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.packets[i]->payload);
        free(manager.packets[i]);
    }
}

// Function to interact with an external API for packet validation and authentication
void validate_packet_with_api(DataPacket *packet) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        char url[256];
        snprintf(url, sizeof(url), "https://api.example.com/validate?packet_id=%d", packet->id);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        // Set other necessary options for the request

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "CURL failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
}

int main() {
    initialize_and_manage_packets();
    return 0;
}
