```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} RecordList;

#define VALUE_RANGE 100

// Function prototypes
RecordList* create_record_list(size_t max_records);
int add_record(RecordList *list, long offset, int key, int value);
int remove_record(RecordList *list, int key);
Record* query_by_key(RecordList *list, int key);
Record* query_by_offset(RecordList *list, long offset);
void serialize_record_list(const RecordList *list, const char *filename);
int deserialize_record_list(RecordList *list, const char *filename);
void free_record_list(RecordList *list);

// Create a new record list with a specified maximum capacity
RecordList* create_record_list(size_t max_records) {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record*)calloc(max_records, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = max_records;
    list->count = 0;
    pthread_rwlock_init(&list->lock, NULL);

    return list;
}

// Add a record to the list
int add_record(RecordList *list, long offset, int key, int value) {
    if (value < 0 || value >= VALUE_RANGE) return -1;

    pthread_rwlock_wrlock(&list->lock);
    if (list->count >= list->capacity) {
        pthread_rwlock_unlock(&list->lock);
        return -2; // Limit reached
    }

    Record *record = &list->records[list->count++];
    record->offset = offset;
    record->key = key;
    record->value = value;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Remove a record by key
int remove_record(RecordList *list, int key) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            memmove(&list->records[i], &list->records[i + 1], 
                    (list->count - i - 1) * sizeof(Record));
            --list->count;
            pthread_rwlock_unlock(&list->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return -1; // Key not found
}

// Query a record by key
Record* query_by_key(RecordList *list, int key) {
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            Record *record = &list->records[i];
            pthread_rwlock_unlock(&list->lock);
            return record;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

// Query a record by offset
Record* query_by_offset(RecordList *list, long offset) {
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].offset == offset) {
            Record *record = &list->records[i];
            pthread_rwlock_unlock(&list->lock);
            return record;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

// Serialize the record list to a file
void serialize_record_list(const RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(list->records, sizeof(Record), list->count, file);

    fclose(file);
}

// Deserialize the record list from a file
int deserialize_record_list(RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > list->capacity) {
        fclose(file);
        return -2; // Exceeds capacity
    }

    fread(list->records, sizeof(Record), count, file);
    list->count = count;

    fclose(file);
    return 0;
}

// Free the record list resources
void free_record_list(RecordList *list) {
    if (list) {
        free(list->records);
        pthread_rwlock_destroy(&list->lock);
        free(list);
    }
}

// Example usage
int main() {
    RecordList *list = create_record_list(1000);
    if (!list) return 1;

    add_record(list, 123456789L, 1, 42);
    Record *record = query_by_key(list, 1);
    if (record) printf("Record found: key=%d, offset=%ld, value=%d\n", record->key, record->offset, record->value);

    serialize_record_list(list, "records.dat");
    free_record_list(list);

    list = create_record_list(1000);
    deserialize_record_list(list, "records.dat");

    free_record_list(list);
    return 0;
}
```

### Key Points:
- **Synchronization**: Uses `pthread_rwlock_t` for concurrent access.
- **Memory Management**: Dynamically allocates memory based on user-defined limits.
- **Serialization/Deserialization**: Uses binary format to minimize overhead.
- **Error Handling**: Returns error codes for invalid operations.

This is a basic implementation and should be extended with more robust error handling, logging, and integration tests as required.']

