#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { TYPE_A, TYPE_B, TYPE_C } ResourceType;
typedef struct {
    char base_id[64];
    char version_id[64];
    int size;
    ResourceType type;
    char category[32][64];  // Assume a resource can belong to multiple categories
    int num_categories;
    unsigned long access_frequency;
    time_t expiration_timestamp;
    time_t last_accessed;
    int priority;  // Priority of the resource
    char version_info[256];
    struct Resource* next_version;
} Resource;

typedef struct {
    Resource* head;
    Resource* tail;
    pthread_mutex_t lock;
} LRUList;

typedef struct {
    Resource** resources;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
    pthread_mutex_t eviction_lock;
    pthread_cond_t cond_var;
    size_t current_size;
    double hit_rate;
    double miss_rate;
    time_t last_report_time;
    LRUList lru_list;
} Cache;

Cache* create_cache(size_t capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->resources = (Resource**)calloc(capacity, sizeof(Resource*));
    if (!cache->resources) {
        free(cache);
        return NULL;
    }

    cache->capacity = capacity;
    cache->count = 0;
    pthread_rwlock_init(&cache->lock, NULL);
    pthread_mutex_init(&cache->eviction_lock, NULL);
    pthread_cond_init(&cache->cond_var, NULL);
    cache->current_size = 0;
    cache->hit_rate = 0.0;
    cache->miss_rate = 0.0;
    cache->last_report_time = time(NULL);

    pthread_mutex_init(&cache->lru_list.lock, NULL);
    cache->lru_list.head = cache->lru_list.tail = NULL;

    return cache;
}

void destroy_cache(Cache* cache) {
    if (!cache) return;

    for (size_t i = 0; i < cache->capacity; ++i) {
        Resource* res = cache->resources[i];
        while (res) {
            Resource* next = res->next_version;
            free(res);
            res = next;
        }
    }

    free(cache->resources);
    pthread_rwlock_destroy(&cache->lock);
    pthread_mutex_destroy(&cache->eviction_lock);
    pthread_cond_destroy(&cache->cond_var);
    pthread_mutex_destroy(&cache->lru_list.lock);

    free(cache);
}

void* get_resource(Cache* cache, const char* base_id) {
    pthread_rwlock_rdlock(&cache->lock);

    for (size_t i = 0; i < cache->capacity; ++i) {
        Resource* res = cache->resources[i];
        while (res) {
            if (strcmp(res->base_id, base_id) == 0) {
                pthread_rwlock_unlock(&cache->lock);

                // Update LRU
                pthread_mutex_lock(&cache->lru_list.lock);
                if (res != cache->lru_list.head) {
                    // Remove from current position
                    if (res->next_version) res->next_version->last_accessed = time(NULL);
                    // Move to head
                    if (cache->lru_list.head == NULL) {
                        cache->lru_list.head = cache->lru_list.tail = res;
                    } else {
                        if (res == cache->lru_list.tail) cache->lru_list.tail = res->next_version;
                        res->last_accessed = time(NULL);
                        res->next_version = cache->lru_list.head;
                        cache->lru_list.head = res;
                    }
                }
                pthread_mutex_unlock(&cache->lru_list.lock);

                // Update access frequency and last accessed
                res->access_frequency++;
                res->last_accessed = time(NULL);

                return res;
            }
            res = res->next_version;
        }
    }

    pthread_rwlock_unlock(&cache->lock);
    return NULL;  // Miss
}

void add_or_update_resource(Cache* cache, Resource* resource) {
    size_t index = hash_function(resource->base_id) % cache->capacity;

    pthread_mutex_lock(&cache->eviction_lock);

    // Check if the resource already exists and update it
    Resource* existing_res = get_resource(cache, resource->base_id);
    if (existing_res) {
        // Update metadata, versioning, etc.
        strcpy(existing_res->version_info, resource->version_info);
        existing_res->size = resource->size;
        existing_res->type = resource->type;
        memcpy(existing_res->category, resource->category, sizeof(resource->category));
        existing_res->num_categories = resource->num_categories;
        existing_res->priority = resource->priority;
        existing_res->expiration_timestamp = resource->expiration_timestamp;

        pthread_mutex_lock(&cache->lru_list.lock);
        if (existing_res != cache->lru_list.head) {
            // Remove from current position
            if (existing_res->next_version) existing_res->next_version->last_accessed = time(NULL);
            // Move to head
            if (cache->lru_list.head == NULL) {
                cache->lru_list.head = cache->lru_list.tail = existing_res;
            } else {
                if (existing_res == cache->lru_list.tail) cache->lru_list.tail = existing_res->next_version;
                existing_res->last_accessed = time(NULL);
                existing_res->next_version = cache->lru_list.head;
                cache->lru_list.head = existing_res;
            }
        }
        pthread_mutex_unlock(&cache->lru_list.lock);

        pthread_mutex_unlock(&cache->eviction_lock);
    } else {
        // Add new resource
        if (cache->count == cache->capacity) {
            evict_resource(cache);  // Evict based on policy
        }

        Resource* res = (Resource*)malloc(sizeof(Resource));
        if (!res) {
            pthread_mutex_unlock(&cache->eviction_lock);
            return;
        }
        *res = *resource;

        pthread_rwlock_wrlock(&cache->lock);
        cache->resources[index] = res;
        cache->count++;
        pthread_rwlock_unlock(&cache->lock);

        pthread_mutex_lock(&cache->lru_list.lock);
        if (cache->lru_list.head == NULL) {
            cache->lru_list.head = cache->lru_list.tail = res;
        } else {
            res->next_version = cache->lru_list.head;
            cache->lru_list.head = res;
        }
        pthread_mutex_unlock(&cache->lru_list.lock);

        pthread_mutex_unlock(&cache->eviction_lock);
    }
}

void evict_resource(Cache* cache) {
    // Implement eviction policy (LRU, LFU, LRA-C, etc.)
    // For simplicity, let's assume we're using LRU here
    Resource* res_to_evict = NULL;

    pthread_mutex_lock(&cache->lru_list.lock);
    if (cache->lru_list.tail) {
        res_to_evict = cache->lru_list.tail;
        if (cache->lru_list.head == cache->lru_list.tail) {
            cache->lru_list.head = cache->lru_list.tail = NULL;
        } else {
            cache->lru_list.tail = res_to_evict->next_version;
            res_to_evict->next_version = NULL;
        }
    }
    pthread_mutex_unlock(&cache->lru_list.lock);

    if (res_to_evict) {
        size_t index = hash_function(res_to_evict->base_id) % cache->capacity;

        pthread_rwlock_wrlock(&cache->lock);
        if (cache->resources[index] == res_to_evict) {
            cache->resources[index] = res_to_evict->next_version;
        }
        cache->count--;
        pthread_rwlock_unlock(&cache->lock);

        free(res_to_evict);
    }
}

void purge_expired_resources(Cache* cache) {
    time_t now = time(NULL);

    pthread_rwlock_wrlock(&cache->lock);
    for (size_t i = 0; i < cache->capacity; ++i) {
        Resource* res = cache->resources[i];
        while (res) {
            if (res->expiration_timestamp < now) {
                // Mark resource as expired and remove it
                Resource* next = res->next_version;
                free(res);
                cache->resources[i] = next;
                cache->count--;
            }
            res = res->next_version;
        }
    }
    pthread_rwlock_unlock(&cache->lock);
}

void generate_report(Cache* cache) {
    // Generate and print cache usage report
    printf("Cache Report:\n");
    printf("  Hit Rate: %.2f\n", cache->hit_rate);
    printf("  Miss Rate: %.2f\n", cache->miss_rate);
    printf("  Current Size: %zu\n", cache->current_size);
    // Additional metrics can be added here
}

size_t hash_function(const char* str) {
    size_t hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash;
}

void adjust_cache_size(Cache* cache, size_t new_capacity) {
    pthread_mutex_lock(&cache->eviction_lock);

    Resource** old_resources = cache->resources;
    size_t old_capacity = cache->capacity;

    cache->resources = (Resource**)calloc(new_capacity, sizeof(Resource*));
    if (!cache->resources) {
        cache->resources = old_resources;
        pthread_mutex_unlock(&cache->eviction_lock);
        return;
    }

    cache->capacity = new_capacity;
    cache->count = 0;

    for (size_t i = 0; i < old_capacity; ++i) {
        Resource* res = old_resources[i];
        while (res) {
            size_t index = hash_function(res->base_id) % new_capacity;
            pthread_rwlock_wrlock(&cache->lock);
            cache->resources[index] = res;
            cache->count++;
            pthread_rwlock_unlock(&cache->lock);

            res = res->next_version;
        }
    }

    free(old_resources);
    pthread_mutex_unlock(&cache->eviction_lock);
}

// Implement additional features as needed...
