#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <zlib.h> // For compression

#define MAX_EVENTS 10000
#define MEMORY_LIMIT (1024 * 1024 * 512) // 512 MB
#define LOG_FILE "trading_log.txt"
#define TEMPLATE_COUNT 3
#define TEMPLATE_SIZE 256
#define STRING_BUFFER_SIZE 64
#define POINT_BUFFER_SIZE 32

typedef struct {
    int key;
    long offset;
} OffsetKey;

typedef struct {
    int field1, field2, field3; // Example fields with random values
    char message[TEMPLATE_SIZE];
} Record;

typedef struct {
    double timestamp;
} Timestamp;

typedef struct {
    char identifier[STRING_BUFFER_SIZE];
} Identifier;

typedef struct {
    float x, y;
} Point;

typedef struct EventNode {
    OffsetKey offset_key;
    Record record;
    Timestamp timestamp;
    Identifier identifier;
    Point point;
    struct EventNode* next;
} EventNode;

typedef struct {
    EventNode* head;
    size_t total_events;
    long memory_usage;
} History;

History history = {NULL, 0, 0};

void log_event(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void add_event(OffsetKey offset_key, Record record, Timestamp timestamp, Identifier identifier, Point point) {
    if (history.total_events >= MAX_EVENTS || history.memory_usage >= MEMORY_LIMIT) {
        log_event("Memory limit exceeded or event limit reached.");
        return;
    }

    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) {
        log_event("Failed to allocate memory for a new event.");
        return;
    }

    memcpy(&new_node->offset_key, &offset_key, sizeof(OffsetKey));
    memcpy(&new_node->record, &record, sizeof(Record));
    memcpy(&new_node->timestamp, &timestamp, sizeof(Timestamp));
    strcpy(new_node->identifier.identifier, identifier.identifier);
    new_node->point = point;
    new_node->next = NULL;

    history.head = (history.head == NULL) ? new_node : history.head;
    while (history.head->next != NULL)
        history.head = history.head->next;
    history.head->next = new_node;

    size_t node_size = sizeof(EventNode);
    history.total_events++;
    history.memory_usage += node_size;
}

void free_history() {
    EventNode* current = history.head;
    while (current) {
        EventNode* temp = current;
        current = current->next;
        free(temp);
    }
    history.head = NULL;
    history.total_events = 0;
    history.memory_usage = 0;
}

void generate_message(Record* record) {
    const char* templates[TEMPLATE_COUNT] = {
        "Transaction ID: %d, Value1: %d",
        "Alert: Field2 value is %d",
        "Update: New position (x: %.2f, y: %.2f)"
    };

    int template_index = rand() % TEMPLATE_COUNT;
    if (template_index == 0) {
        snprintf(record->message, TEMPLATE_SIZE, templates[template_index], record->field1);
    } else if (template_index == 1) {
        snprintf(record->message, TEMPLATE_SIZE, templates[template_index], record->field2);
    } else {
        float x = (float)record->field3 / 10;
        float y = (float)(record->field1 + record->field2) / 20;
        snprintf(record->message, TEMPLATE_SIZE, templates[template_index], x, y);
    }
}

void handle_threshold() {
    if (history.total_events > MAX_EVENTS * 0.9) { // Alert at 90% capacity
        log_event("Threshold alert: Event count is nearing the limit.");
    }
}

void serialize_history(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_event("Failed to open file for serialization.");
        return;
    }

    unsigned long compressed_size = compressBound(sizeof(History));
    Bytef* compressed_data = (Bytef*)malloc(compressed_size);
    uLongf final_compressed_size = compressed_size;

    int result = compress(compressed_data, &final_compressed_size, (const Bytef*)&history, sizeof(History));
    if (result != Z_OK) {
        log_event("Compression failed during serialization.");
        free(compressed_data);
        fclose(file);
        return;
    }

    fwrite(&final_compressed_size, sizeof(uLongf), 1, file);
    fwrite(compressed_data, final_compressed_size, 1, file);

    free(compressed_data);
    fclose(file);
}

void deserialize_history(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_event("Failed to open file for deserialization.");
        return;
    }

    uLongf compressed_size;
    fread(&compressed_size, sizeof(uLongf), 1, file);

    Bytef* compressed_data = (Bytef*)malloc(compressed_size);
    fread(compressed_data, compressed_size, 1, file);

    int result = uncompress((Bytef*)&history, &compressed_size, compressed_data, compressed_size);
    if (result != Z_OK) {
        log_event("Decompression failed during deserialization.");
        free(compressed_data);
        fclose(file);
        return;
    }

    free(compressed_data);
    fclose(file);
}

void init_random() {
    srand((unsigned int)time(NULL));
}
