```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 100

typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp; // For expiration management
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_record_list() {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->records, 0, sizeof(Record*) * MAX_RECORDS);
    return list;
}

void destroy_record_list(RecordList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(RecordList *list, long offset, int key, int value) {
    if (list->count >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&list->lock);

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    record->offset = offset;
    record->key = key;
    record->value = value;
    record->timestamp = time(NULL);

    list->records[list->count++] = record;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->key == key) {
            free(list->records[i]);
            memmove(&list->records[i], &list->records[i + 1],
                    sizeof(Record*) * (list->count - i - 1));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

Record* query_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->key == key) {
            Record *record = list->records[i];
            pthread_mutex_unlock(&list->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void serialize_records(const char *filename, RecordList *list) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(list->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

int deserialize_records(const char *filename, RecordList *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (count > MAX_RECORDS) {
        fclose(file);
        return -2;
    }

    pthread_mutex_lock(&list->lock);
    list->count = 0;

    for (size_t i = 0; i < count; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fclose(file);
            pthread_mutex_unlock(&list->lock);
            return -3;
        }
        fread(record, sizeof(Record), 1, file);
        list->records[list->count++] = record;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

void remove_expired_records(RecordList *list, time_t expiration_time) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count;) {
        if (difftime(time(NULL), list->records[i]->timestamp) > expiration_time) {
            free(list->records[i]);
            memmove(&list->records[i], &list->records[i + 1],
                    sizeof(Record*) * (list->count - i - 1));
            --list->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    RecordList *list = create_record_list();
    add_record(list, 12345L, 1, rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN);
    serialize_records("records.bin", list);

    destroy_record_list(list);
    return 0;
}
