// Initialize the record list with a given upper limit.
RecordList* create_record_list(size_t max_records) {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record *)calloc(max_records, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = max_records;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add a record to the list.
bool add_record(RecordList *list, long offset, int key, int value) {
    if (list->count >= list->capacity) return false;

    pthread_mutex_lock(&list->lock);

    Record new_record = {offset, key, value};
    list->records[list->count++] = new_record;

    pthread_mutex_unlock(&list->lock);

    return true;
}

// Remove a record from the list based on its key.
bool remove_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            memmove(&list->records[i], &list->records[i + 1], 
                    (list->count - i - 1) * sizeof(Record));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

// Query a record by its key.
bool query_record(RecordList *list, int key, Record *record) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            *record = list->records[i];
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

