        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 10; ++i) {
        printf("Task ID: %d, Priority: %d\n", tasks[i].pkt_id, tasks[i].priority);
    }

    free(tasks);

    return EXIT_SUCCESS;
}
