['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float temperature;
    float humidity;
    char metadata[1024];
} DataRecord;

typedef struct MetricSetting {
    char *key;
    char *value;
    int version;
    time_t timestamp;
    struct MetricSetting *next; // For handling hash table collisions
} MetricSetting;

#define MAX_RECORDS 10000
#define MEMORY_LIMIT 1048576 // Example limit in bytes

typedef struct SensorDataList {
    DataRecord records[MAX_RECORDS];
    long timestamps[MAX_RECORDS];
    int device_ids[MAX_RECORDS];
    size_t count;
    size_t capacity;
} SensorDataList;

typedef struct {
    MetricSetting **table;
    size_t table_size;
    pthread_rwlock_t rwlock;
    SensorDataList data_list;
    size_t memory_used;
    pthread_mutex_t flush_lock;
} EnvironmentManager;

// Hash function for metrics
size_t hash_key(const char *key, size_t table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % table_size;
}

// Initialize environment manager
void init_environment_manager(EnvironmentManager *manager, size_t table_size) {
    manager->table_size = table_size;
    manager->table = calloc(table_size, sizeof(MetricSetting*));
    pthread_rwlock_init(&manager->rwlock, NULL);
    manager->data_list.count = 0;
    manager->data_list.capacity = MAX_RECORDS;
    manager->memory_used = 0;
    pthread_mutex_init(&manager->flush_lock, NULL);
}

// Add or update metric setting
void manage_metric_setting(EnvironmentManager *manager, const char *key, const char *value, int version) {
    size_t index = hash_key(key, manager->table_size);
    MetricSetting *metric = manager->table[index];

    pthread_rwlock_wrlock(&manager->rwlock);

    while (metric != NULL) {
        if (strcmp(metric->key, key) == 0) {
            // Update existing setting
            free(metric->value);
            metric->version = version;
            time(&(metric->timestamp));

            metric->value = strdup(value);
            break;
        }
        metric = metric->next;
    }

    if (!metric || (strcmp(metric->key, key) != 0)) {
        // Add new setting
        MetricSetting *new_metric = malloc(sizeof(MetricSetting));
        new_metric->key = strdup(key);
        new_metric->value = strdup(value);
        new_metric->version = version;
        time(&(new_metric->timestamp));

        new_metric->next = manager->table[index];
        manager->table[index] = new_metric;
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

// Retrieve metric setting
char* get_metric_setting(EnvironmentManager *manager, const char *key) {
    size_t index = hash_key(key, manager->table_size);

    pthread_rwlock_rdlock(&manager->rwlock);
    MetricSetting *metric = manager->table[index];

    while (metric != NULL) {
        if (strcmp(metric->key, key) == 0)
            break;
        metric = metric->next;
    }

    char* value = metric ? strdup(metric->value) : NULL;

    pthread_rwlock_unlock(&manager->rwlock);
    return value;
}

// Add sensor data record
int add_sensor_data_record(EnvironmentManager *manager, long timestamp, int device_id, DataRecord record) {
    pthread_mutex_lock(&manager->flush_lock);

    if (manager->data_list.count >= manager->data_list.capacity || 
        sizeof(manager->data_list.records) + sizeof(record) > MEMORY_LIMIT)
    {
        fprintf(stderr, "Memory limit exceeded or capacity reached\n");
        pthread_mutex_unlock(&manager->flush_lock);
        return -1;
    }

    manager->data_list.timestamps[manager->data_list.count] = timestamp;
    manager->data_list.device_ids[manager->data_list.count] = device_id;

    memcpy(&(manager->data_list.records[manager->data_list.count]), &record, sizeof(record));
    manager->memory_used += sizeof(record);
    manager->data_list.count++;

    pthread_mutex_unlock(&manager->flush_lock);
    return 0;
}

// Serialize data to file
void serialize_data(EnvironmentManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return;

    fwrite(&(manager->data_list.count), sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->data_list.count; ++i) {
        fwrite(&(manager->data_list.timestamps[i]), sizeof(long), 1, file);
        fwrite(&(manager->data_list.device_ids[i]), sizeof(int), 1, file);
        fwrite(&(manager->data_list.records[i]), sizeof(DataRecord), 1, file);
    }

    fclose(file);
}

// Deserialize data from file
void deserialize_data(EnvironmentManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file)
        return;

    fread(&(manager->data_list.count), sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->data_list.count; ++i) {
        fread(&(manager->data_list.timestamps[i]), sizeof(long), 1, file);
        fread(&(manager->data_list.device_ids[i]), sizeof(int), 1, file);
        fread(&(manager->data_list.records[i]), sizeof(DataRecord), 1, file);
    }

    fclose(file);
}

// Periodically flush cached metrics to disk
void *periodic_flush(void *arg) {
    EnvironmentManager *manager = (EnvironmentManager *)arg;

    while (1) {
        sleep(60); // Flush every minute

        pthread_mutex_lock(&manager->flush_lock);

        char filename[] = "metrics_backup.bin";
        serialize_data(manager, filename);

        pthread_mutex_unlock(&manager->flush_lock);
    }

    return NULL;
}

// Clean up resources
void cleanup_environment_manager(EnvironmentManager *manager) {
    for (size_t i = 0; i < manager->table_size; ++i) {
        MetricSetting *metric = manager->table[i];
        while (metric != NULL) {
            MetricSetting *next_metric = metric->next;
            free(metric->key);
            free(metric->value);
            free(metric);
            metric = next_metric;
        }
    }

    free(manager->table);
    pthread_rwlock_destroy(&manager->rwlock);
    pthread_mutex_destroy(&manager->flush_lock);

    // Optionally clean up serialized data files if needed
}

int main() {
    EnvironmentManager manager;
    init_environment_manager(&manager, 101); // Example hash table size

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, periodic_flush, &manager);

    // Example usage of the manager
    manage_metric_setting(&manager, "temperature_threshold", "25.0", 1);
    DataRecord record = {.temperature = 22.5, .humidity = 60.0};
    add_sensor_data_record(&manager, time(NULL), 1234, record);

    // Cleanup and exit
    pthread_cancel(flush_thread);
    cleanup_environment_manager(&manager);

    return 0;
}
