// Define a record structure
typedef struct {
    int value;
    char *user_id;
} Record;

// Function prototypes
void initialize_arrays(long n, int *offsets, int *keys);
void free_memory(long n, long *offsets, int *keys, Record *records);
void set_random_values(Record *records, size_t count, int min_value, int max_value);
void log_event(const char *event, size_t size);

// Global logging flag
static int logging_enabled = 1;

// Initialize arrays and records
void initialize_arrays(long n, long **offsets, int **keys, Record ***records) {
    if (!logging_enabled) return;

    // Allocate memory for offsets and keys
    *offsets = malloc(n * sizeof(long));
    *keys = malloc(n * sizeof(int));

    if (*offsets == NULL || *keys == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    log_event("Allocated offsets", n * sizeof(long));
    log_event("Allocated keys", n * sizeof(int));

    // Initialize arrays with dummy data
    for (long i = 0; i < n; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % 100;
    }

    // Allocate memory for records
    *records = malloc(n * sizeof(Record));

    if (*records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    log_event("Allocated records", n * sizeof(Record));

    for (size_t i = 0; i < n; ++i) {
        (*records)[i].value = 0;
        // Allocate memory for user_id
        char *id = malloc(10); // Example size
        if (id == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        snprintf(id, 10, "ID%ld", i);
        (*records)[i].user_id = id;
    }
}

// Free all allocated memory
void free_memory(long n, long *offsets, int *keys, Record *records) {
    if (logging_enabled) {
        log_event("Freed offsets", n * sizeof(long));
        log_event("Freed keys", n * sizeof(int));
    }

    free(offsets);
    free(keys);

    for (long i = 0; i < n; ++i) {
        free(records[i].user_id);
    }

    if (logging_enabled) {
        log_event("Freed records", n * sizeof(Record));
    }
    free(records);
}

// Set random values within a range
void set_random_values(Record *records, size_t count, int min_value, int max_value) {
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        do {
            records[i].value = rand() % (max_value - min_value + 1) + min_value;
        } while (records[i].value < min_value || records[i].value > max_value);
    }
}

// Logging function
void log_event(const char *event, size_t size) {
    time_t now = time(NULL);
    printf("%s: Allocated %zu bytes at %s", event, size, ctime(&now));
}

// Serialize records to a binary format
int serialize_records(Record *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    if (fwrite(records, sizeof(Record), count, file) != count) {
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

// Unit tests
void test_functionality() {
    const long n = 5;
    long *offsets;
    int *keys;
    Record *records;

    initialize_arrays(n, &offsets, &keys, &records);

    set_random_values(records, n, 10, 20);

    for (long i = 0; i < n; ++i) {
        printf("Record %ld: Value = %d, User ID = %s\n", i, records[i].value, records[i].user_id);
    }

    if (serialize_records(records, n, "records.bin") == 0) {
        printf("Serialization successful.\n");
    } else {
        fprintf(stderr, "Failed to serialize records.\n");
    }

    free_memory(n, offsets, keys, records);
}

int main() {
    test_functionality();
    return 0;
}
