    // Execute command-line tool to convert JPEG to PDF
    const int retryCount = 3; // Retry up to 3 times for transient errors
    const int compressionLevel = 5; // Example compression level
    if (convertJPEGToPDF(fileName, outputDir, retryCount, compressionLevel) != 0) {
        logMessage("Failed to convert JPEG to PDF");
    }

    // Free allocated memory
    free(list);
}

// Utility function to log messages with timestamp and user identifier
void logMessage(const char *format, ...) {
    pthread_mutex_lock(&mutex);

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] [User: %ld]", buffer, getuid()); // Example user identifier

    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);

    pthread_mutex_unlock(&mutex);
}

// Utility function to create directory if it does not exist
int createDirectoryIfNotExists(const char *path) {
    struct stat st = {0};

    if (stat(path, &st) == -1) {
        int ret = mkdir(path, 0755); // Example permissions
        if (ret != 0 && errno != EEXIST) {
            logMessage("Failed to create directory %s: %s", path, strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Utility function to convert JPEG to PDF
int convertJPEGToPDF(const char *inputFileName, const char *outputPath, int retryCount, int compressionLevel) {
    char command[256];
    snprintf(command, sizeof(command), "convert %s/%s.pdf -compress %d %s/output.pdf", outputPath, inputFileName, compressionLevel, outputPath);

    for (int attempt = 0; attempt < retryCount; ++attempt) {
        if (system(command) == 0) {
            logMessage("Successfully converted %s to PDF in %s", inputFileName, outputPath);
            return 0;
        } else {
            logMessage("Attempt %d: Failed to convert %s to PDF. Error: %s", attempt + 1, inputFileName, strerror(errno));
            sleep(1); // Wait before retrying
        }
    }

    return -1; // Return failure after retries
}

