#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    int statusFlag;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PacketQueue;

// Helper function to validate string length
char* validateStringLength(const char* input, size_t maxLength) {
    if (strlen(input) >= maxLength) {
        return NULL;
    }
    char* result = malloc(maxLength + 2); // +1 for '\0', +1 for '/'
    if (!result) {
        return NULL;
    }
    snprintf(result, maxLength + 2, "%s/", input);
    return result;
}

// Function to initialize the queue
void initQueue(PacketQueue* q) {
    q->head = NULL;
    pthread_mutex_init(&q->lock, NULL);
}

// Function to add a packet
int addPacket(PacketQueue* q, DataPacket newPacket) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->data = newPacket;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);
    newNode->next = q->head;
    q->head = newNode;
    pthread_mutex_unlock(&q->lock);

    return 0;
}

// Function to update a packet by ID
int updatePacket(PacketQueue* q, int packetID, DataPacket updatedData) {
    pthread_mutex_lock(&q->lock);

    Node *current = q->head, *prev = NULL;
    while (current != NULL && current->data.packetID != packetID) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Packet not found
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    current->data = updatedData;

    pthread_mutex_unlock(&q->lock);
    return 0;
}

// Function to retrieve a packet by ID
DataPacket* getPacket(PacketQueue* q, int packetID) {
    pthread_mutex_lock(&q->lock);

    Node *current = q->head;
    while (current != NULL && current->data.packetID != packetID) {
        current = current->next;
    }

    DataPacket* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&q->lock);
    return result;
}

// Function to purge expired packets
void purgeExpiredPackets(PacketQueue* q, time_t expirationThreshold) {
    pthread_mutex_lock(&q->lock);

    Node *current = q->head, *prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > expirationThreshold) {
            if (prev == NULL) { // Head is expired
                q->head = current->next;
                free(current);
                current = q->head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&q->lock);
}

// Function to destroy the queue
void destroyQueue(PacketQueue* q) {
    pthread_mutex_lock(&q->lock);

    Node *current = q->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    q->head = NULL;
    pthread_mutex_unlock(&q->lock);
    pthread_mutex_destroy(&q->lock);
}
```']

['Here's a C implementation for managing a dynamically allocated hash table that stores `NetworkConnection` objects:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HASH_TABLE_SIZE 1048576 // A prime number close to 1 million for better distribution

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_CLOSED
} ConnectionStatus;

typedef struct {
    int connectionID;
    time_t lastActivityTimestamp;
    ConnectionStatus status;
    double bandwidthUsage;
} NetworkConnection;

typedef struct HashNode {
    NetworkConnection data;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **table;
} HashTable;

unsigned int hash(int connectionID) {
    return connectionID % HASH_TABLE_SIZE;
}

HashTable* createHashTable() {
    HashTable *hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->table = (HashNode**)calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
    if (!hashTable->table) {
        free(hashTable);
        return NULL;
    }
    return hashTable;
}

void destroyHashTable(HashTable *hashTable) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hashTable->table[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(hashTable->table);
    free(hashTable);
}

void addOrUpdateConnection(HashTable *hashTable, NetworkConnection connection) {
    unsigned int index = hash(connection.connectionID);
    HashNode *node = hashTable->table[index];

    while (node) {
        if (node->data.connectionID == connection.connectionID) {
            node->data.lastActivityTimestamp = connection.lastActivityTimestamp;
            node->data.status = connection.status;
            node->data.bandwidthUsage = connection.bandwidthUsage;
            return;
        }
        node = node->next;
    }

    HashNode *newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) return;

    newNode->data = connection;
    newNode->next = hashTable->table[index];
    hashTable->table[index] = newNode;
}

NetworkConnection* getConnectionByID(HashTable *hashTable, int connectionID) {
    unsigned int index = hash(connectionID);
    HashNode *node = hashTable->table[index];

    while (node) {
        if (node->data.connectionID == connectionID) {
            return &node->data;
        }
        node = node->next;
    }

    return NULL;
}

void removeInactiveConnections(HashTable *hashTable, time_t currentTime, int inactiveDurationSeconds) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hashTable->table[i];
        HashNode *prev = NULL;

        while (node) {
            if (currentTime - node->data.lastActivityTimestamp > inactiveDurationSeconds) {
                if (prev) {
                    prev->next = node->next;
                } else {
                    hashTable->table[i] = node->next;
                }
                HashNode *temp = node;
                node = node->next;
                free(temp);
            } else {
                prev = node;
                node = node->next;
            }
        }
    }
}

// Example usage
int main() {
    HashTable *hashTable = createHashTable();

    NetworkConnection conn1 = {1, time(NULL), STATUS_ACTIVE, 100.0};
    addOrUpdateConnection(hashTable, conn1);

    // Simulate passage of time and inactivity removal
    sleep(5);
    removeInactiveConnections(hashTable, time(NULL), 3);

    NetworkConnection *conn = getConnectionByID(hashTable, 1);
    if (conn) {
        printf("Connection ID: %d\n", conn->connectionID);
    } else {
        printf("Connection not found or removed due to inactivity.\n");
    }

    destroyHashTable(hashTable);
    return 0;
}
```

### Key Features:

- **Dynamic Memory Management**: Efficient allocation and deallocation of nodes.
- **Hash Table Structure**: Uses a simple chaining method for collision resolution.
- **Add/Update Functionality**: Updates existing connections or adds new ones.
- **Retrieval by ID**: Allows fetching connection details using the unique ID.
- **Inactivity Cleanup**: Removes connections inactive beyond a specified duration.
- **Scalability and Maintainability**: Designed to handle up to 1 million entries with minimal overhead, allowing for future enhancements like logging.']

['Below is an example implementation of the `resourceManager` function in C. This code includes resource allocation and deallocation, configuration validation, logging, memory management strategies, and performance monitoring.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for configuration settings
typedef struct {
    int minInt;
    int maxInt;
    size_t stringLength;
    int useCompression;
} Config;

// Define a record structure
typedef struct {
    int value;
    char status;
    char *data;
} Record;

// Global variables for logging and configuration management
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;
Config currentConfig = {0, 100, 256, 1};
int peakUsage = 0;
size_t totalAllocatedMemory = 0;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

// Function declarations
void validateConfig(const Config *config);
void logMessage(const char *message);
char* compressString(const char *str);
char* decompressString(const char *str, size_t originalSize);

// The resourceManager function
void resourceManager(int action, Record **records, int recordCount) {
    static pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;
    time_t startTime, endTime;

    if (action == 0) { // Allocation
        pthread_mutex_lock(&memoryMutex);
        pthread_mutex_lock(&configMutex);

        validateConfig(&currentConfig);

        for (int i = 0; i < recordCount; ++i) {
            records[i] = malloc(sizeof(Record));
            if (!records[i]) {
                logMessage("Memory allocation failed for Record");
                return;
            }

            records[i]->value = rand() % (currentConfig.maxInt - currentConfig.minInt + 1) + currentConfig.minInt;
            records[i]->status = 'A'; // Assume active status

            size_t dataLength = currentConfig.useCompression ? sizeof(char) : currentConfig.stringLength * sizeof(char);
            records[i]->data = malloc(dataLength);

            if (!records[i]->data) {
                free(records[i]);
                logMessage("Memory allocation failed for Record Data");
                return;
            }

            // Fill the dynamically allocated string with random data
            char *buffer = malloc(currentConfig.stringLength + 1);
            if (currentConfig.useCompression && buffer) {
                for (size_t j = 0; j < currentConfig.stringLength; ++j)
                    buffer[j] = rand() % 256;
                buffer[currentConfig.stringLength] = '\0';
                char *compressedData = compressString(buffer);

                strncpy(records[i]->data, compressedData, dataLength);
                free(compressedData);
            } else {
                for (size_t j = 0; j < currentConfig.stringLength; ++j)
                    records[i]->data[j] = rand() % 256;
                records[i]->data[currentConfig.stringLength] = '\0';
            }
            free(buffer);

            pthread_mutex_lock(&logMutex);
            peakUsage = totalAllocatedMemory > peakUsage ? totalAllocatedMemory : peakUsage;
            totalAllocatedMemory += sizeof(Record) + dataLength;
            logMessage("Resource allocation successful");
            pthread_mutex_unlock(&logMutex);
        }

        pthread_mutex_unlock(&configMutex);
        pthread_mutex_unlock(&memoryMutex);

    } else if (action == 1) { // Deallocation
        pthread_mutex_lock(&memoryMutex);

        for (int i = 0; i < recordCount; ++i) {
            if (!records[i]) continue;

            free(records[i]->data);
            free(records[i]);
            pthread_mutex_lock(&logMutex);
            totalAllocatedMemory -= sizeof(Record) + currentConfig.stringLength * sizeof(char);
            logMessage("Resource deallocation successful");
            pthread_mutex_unlock(&logMutex);
        }

        pthread_mutex_unlock(&memoryMutex);
    }
}

// Function to validate configuration settings
void validateConfig(const Config *config) {
    if (config->minInt >= config->maxInt || config->stringLength == 0) {
        logMessage("Invalid configuration: minInt should be less than maxInt and string length must be non-zero");
    }
}

// Logging function implementation
void logMessage(const char *message) {
    printf("%s\n", message);
}

char* compressString(const char *str) {
    // Dummy compression (placeholder)
    return strdup(str);
}

char* decompressString(const char *str, size_t originalSize) {
    // Dummy decompression (placeholder)
    char *decompressed = malloc(originalSize + 1);
    strncpy(decompressed, str, originalSize);
    decompressed[originalSize] = '\0';
    return decompressed;
}
```

This implementation handles resource allocation and deallocation while considering configuration validation, logging, compression, and thread safety. Adjustments might be needed based on specific external dependencies or additional requirements.']

['Below is a C++ implementation for the `handleDynamicSessions` function based on your requirements:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <mutex>
#include <filesystem>
#include <fstream>

namespace fs = std::filesystem;

struct Session {
    std::string sessionID;
    std::string clientIP;
    std::time_t lastActivity;
    int refCount;
    std::string metadata;
};

struct Record {
    int value;
    char buffer[256];
    std::string* path;
};

class DynamicSessionManager {
public:
    DynamicSessionManager(size_t maxSessions, size_t maxRecords)
        : maxSessions(maxSessions), maxRecords(maxRecords), totalRecords(0) {}

    void handleDynamicSessions() {
        std::mutex mtx;
        while (true) {
            std::string path;
            if (!std::getline(std::cin, path)) break;

            processPath(path, &mtx);

            // Simulate system load metrics
            adjustMemoryAllocation();
        }
    }

private:
    size_t maxSessions;
    size_t maxRecords;
    size_t totalRecords;
    std::vector<Session> sessions;
    std::unordered_map<std::string, Record*> records;

    void processPath(const std::string& path, std::mutex* mtx) {
        std::lock_guard<std::mutex> lock(*mtx);

        try {
            int depth = calculateDirectoryDepth(path);
            size_t recordIndex = totalRecords++;
            if (totalRecords > maxRecords) return;

            Record* newRecord = allocateRecord(recordIndex);
            newRecord->value = static_cast<int>(depth);
            std::snprintf(newRecord->buffer, sizeof(newRecord->buffer), "Metadata for %s", path.c_str());
            newRecord->path = new std::string(path);

            records[path] = newRecord;
        } catch (const std::exception& e) {
            std::cerr << "Error processing path: " << e.what() << '\n';
        }
    }

    int calculateDirectoryDepth(const std::string& path) {
        int depth = 0;
        for (const auto& entry : fs::recursive_directory_iterator(path)) {
            if (fs::is_directory(entry.status())) {
                size_t currentDepth = entry.path().string().count('/') - path.count('/');
                depth = std::max(depth, static_cast<int>(currentDepth));
            }
        }
        return depth;
    }

    Record* allocateRecord(size_t index) {
        if (totalRecords >= maxRecords) throw std::runtime_error("Max records exceeded");

        Record* record = new Record();
        if (!record) throw std::bad_alloc();

        // Log creation
        logAction("Created", record->path);

        return record;
    }

    void adjustMemoryAllocation() {
        // Simulate adjusting memory based on system metrics
    }

    void logAction(const std::string& action, const std::string* path) {
        auto now = std::chrono::system_clock::now();
        std::time_t timestamp = std::chrono::system_clock::to_time_t(now);
        std::cout << "[" << std::ctime(&timestamp) << "] " << action
                  << " session for path: " << (path ? *path : "unknown") << '\n';
    }

    void serializeSessions(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (!file) throw std::runtime_error("Failed to open file for serialization");

        // Serialize sessions
        for (const auto& session : sessions) {
            file.write(session.sessionID.c_str(), session.sessionID.size());
            file.put('\0');
            file.write(session.clientIP.c_str(), session.clientIP.size());
            file.put('\0');
            file.write(reinterpret_cast<const char*>(&session.lastActivity), sizeof(session.lastActivity));
            file.write(reinterpret_cast<const char*>(&session.refCount), sizeof(session.refCount));
            file.write(session.metadata.c_str(), session.metadata.size());
            file.put('\0');
        }
    }

    void deserializeSessions(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) throw std::runtime_error("Failed to open file for deserialization");

        // Deserialize sessions
        while (!file.eof()) {
            Session session;
            std::getline(file, session.sessionID, '\0');
            std::getline(file, session.clientIP, '\0');
            file.read(reinterpret_cast<char*>(&session.lastActivity), sizeof(session.lastActivity));
            file.read(reinterpret_cast<char*>(&session.refCount), sizeof(session.refCount));
            std::getline(file, session.metadata, '\0');

            if (!session.sessionID.empty()) {
                sessions.push_back(session);
            }
        }
    }
};

int main() {
    DynamicSessionManager manager(1000, 500); // Example limits
    manager.handleDynamicSessions();
    return 0;
}
```

### Key Points:
- **Concurrency Control**: Uses a mutex to ensure thread safety during concurrent modifications.
- **File System Traversal**: Efficiently calculates directory depth using `std::filesystem`.
- **Memory Management**: Dynamically allocates memory for records and sessions, with checks to prevent exceeding limits.
- **Serialization/Deserialization**: Provides mechanisms to serialize and deserialize session data to/from a file.
- **Logging**: Logs actions with timestamps for analysis.
- **Error Handling**: Gracefully handles errors like failed allocations or exceeding limits.']

['```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>

#define MAX_PATH_LENGTH 4096
#define MAX_LINKED_LIST_SIZE 10000

typedef struct Node {
    int id;
    char metadata[128];
    char *path;
    time_t last_access_time;
    int is_symlink;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t count;
} LinkedList;

void initLinkedList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

Node* createNode(const char *path_str) {
    struct stat path_stat;
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;

    // Extract metadata and check symlink
    int err = lstat(path_str, &path_stat);
    if (err != 0) {
        free(new_node);
        return NULL; // Handle non-existent path
    }

    new_node->path = strdup(path_str);
    new_node->last_access_time = path_stat.st_atime;
    new_node->is_symlink = S_ISLNK(path_stat.st_mode);

    // Metadata extraction placeholder
    snprintf(new_node->metadata, sizeof(new_node->metadata), "Size: %ld", (long)path_stat.st_size);
    new_node->id = rand();  // Simple id generation

    return new_node;
}

void addNode(LinkedList *list, Node *node) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LINKED_LIST_SIZE) {
        fprintf(stderr, "Reached maximum linked list size\n");
        free(node->path);
        free(node);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    node->next = list->head;
    list->head = node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

int getDirDepth(const char *path) {
    int depth = 1; // Root directory is depth 1
    while (*path == '/') path++; // Skip leading '/'

    while (*path != '\0') {
        if (*path == '/') depth++;
        path++;
    }

    return depth;
}

void findMaxDepth(LinkedList *list) {
    Node *current = list->head;
    const char *max_path = NULL;
    int max_depth = 0;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        int depth = getDirDepth(current->path);
        if (depth > max_depth) {
            max_depth = depth;
            max_path = current->path;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    if (max_path) {
        printf("Path with largest directory depth: %s, Depth: %d\n", max_path, max_depth);
    } else {
        printf("No paths processed.\n");
    }
}

void freeLinkedList(LinkedList *list) {
    Node *current = list->head;

    while (current != NULL) {
        Node *next = current->next;
        free(current->path);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    list->head = NULL;
}

void processFilePaths() {
    LinkedList paths_list;
    initLinkedList(&paths_list);

    char path[MAX_PATH_LENGTH];

    while (fgets(path, sizeof(path), stdin) != NULL) {
        // Remove newline character
        size_t len = strlen(path);
        if (len > 0 && path[len - 1] == '\n') {
            path[--len] = '\0';
        }

        Node *new_node = createNode(path);
        if (new_node) {
            addNode(&paths_list, new_node);
        } else {
            fprintf(stderr, "Error processing path: %s\n", path);
        }
    }

    findMaxDepth(&paths_list);

    freeLinkedList(&paths_list);
}

int main() {
    processFilePaths();
    return 0;
}
```

This code snippet implements the task as described. It processes file paths from standard input, storing them in a linked list and identifying the path with the largest directory depth. The code is designed to handle resource constraints efficiently and includes basic error handling for non-existent paths or memory allocation failures.']

['Below is a simplified version of the C library that addresses your requirements. This implementation provides basic functionality with thread safety, serialization/deserialization, logging, packet monitoring, network health checks, and testing mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>

#define MAX_CONFIGS 10000
#define LOG_VERBOSITY_LOW 0
#define LOG_VERBOSITY_HIGH 1

typedef struct {
    unsigned char mac[6];
    struct in_addr ip;
    struct in_addr subnet_mask;
    struct in_addr gateway;
} NetworkConfig;

typedef struct {
    NetworkConfig configs[MAX_CONFIGS];
    int count;
    pthread_mutex_t lock;
} ConfigManager;

typedef struct {
    int verbosity_level;
    pthread_mutex_t lock;
} Logger;

typedef struct {
    // Placeholder for packet monitoring data
} PacketMonitor;

// Function prototypes
int init_config_manager(ConfigManager *manager);
void free_config_manager(ConfigManager *manager);
int add_config(ConfigManager *manager, NetworkConfig config);
int remove_config(ConfigManager *manager, unsigned char mac[6]);
int serialize_configs(const ConfigManager *manager, const char *filename);
int deserialize_configs(ConfigManager *manager, const char *filename);
void log_message(Logger *logger, int level, const char *message);
void monitor_packets(PacketMonitor *monitor);
int ping_network_interface(const char *ip);

// Initialize the configuration manager
int init_config_manager(ConfigManager *manager) {
    if (!manager) return -1;
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    return 0;
}

void free_config_manager(ConfigManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
    }
}

int add_config(ConfigManager *manager, NetworkConfig config) {
    if (!manager || manager->count >= MAX_CONFIGS) return -1;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (memcmp(manager->configs[i].mac, config.mac, sizeof(config.mac)) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate MAC address
        }
    }

    manager->configs[manager->count++] = config;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_config(ConfigManager *manager, unsigned char mac[6]) {
    if (!manager || !mac) return -1;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (memcmp(manager->configs[i].mac, mac, sizeof(mac)) == 0) {
            memmove(&manager->configs[i], &manager->configs[i + 1],
                    (manager->count - i - 1) * sizeof(NetworkConfig));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // MAC not found
}

int serialize_configs(const ConfigManager *manager, const char *filename) {
    if (!manager || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&manager->count, sizeof(manager->count), 1, file);
    fwrite(manager->configs, sizeof(NetworkConfig), manager->count, file);

    fclose(file);
    return 0;
}

int deserialize_configs(ConfigManager *manager, const char *filename) {
    if (!manager || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fread(&manager->count, sizeof(manager->count), 1, file);
    fread(manager->configs, sizeof(NetworkConfig), manager->count, file);

    fclose(file);
    return 0;
}

void log_message(Logger *logger, int level, const char *message) {
    if (!logger || !message) return;

    pthread_mutex_lock(&logger->lock);

    if (level <= logger->verbosity_level) {
        printf("%s\n", message);
    }

    pthread_mutex_unlock(&logger->lock);
}

void monitor_packets(PacketMonitor *monitor) {
    // Placeholder for packet monitoring logic
}

int ping_network_interface(const char *ip) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) return -1;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, ip, &addr.sin_addr);

    // Send ICMP Echo Request
    char msg[] = "ping";
    if (sendto(sock, msg, sizeof(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return -1;
    }

    // Receive ICMP Echo Reply
    char buf[128];
    struct sockaddr_in from;
    socklen_t from_len = sizeof(from);
    if (recvfrom(sock, buf, sizeof(buf), 0,
                 (struct sockaddr *)&from, &from_len) < 0) {
        close(sock);
        return -1;
    }

    close(sock);
    return 0; // Success
}

// Testing functions
void test_add_remove_config() {
    ConfigManager manager;
    init_config_manager(&manager);

    NetworkConfig config = { .mac = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55} };
    inet_pton(AF_INET, "192.168.1.2", &config.ip);
    inet_pton(AF_INET, "255.255.255.0", &config.subnet_mask);
    inet_pton(AF_INET, "192.168.1.1", &config.gateway);

    add_config(&manager, config);
    remove_config(&manager, config.mac);

    free_config_manager(&manager);
}

void test_serialization() {
    ConfigManager manager;
    init_config_manager(&manager);

    NetworkConfig config = { .mac = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55} };
    inet_pton(AF_INET, "192.168.1.2", &config.ip);
    add_config(&manager, config);

    serialize_configs(&manager, "configs.dat");
    free_config_manager(&manager);

    ConfigManager new_manager;
    init_config_manager(&new_manager);
    deserialize_configs(&new_manager, "configs.dat");

