['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_MAX_CONNECTIONS 10

typedef struct {
    int connection_id;
    char client_hostname[256];
    int port_number;
    time_t last_successful_communication;
    int retry_count;
} Connection;

typedef struct Node {
    Connection *connection;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t max_connections;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_max) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->max_connections = initial_max;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

int add_connection(ConnectionPool *pool, int connection_id, const char *hostname, int port) {
    pthread_mutex_lock(&pool->lock);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory allocation failed
    }

    new_node->connection = malloc(sizeof(Connection));
    if (!new_node->connection) {
        free(new_node);
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    new_node->connection->connection_id = connection_id;
    strncpy(new_node->connection->client_hostname, hostname, sizeof(new_node->connection->client_hostname) - 1);
    new_node->connection->port_number = port;
    new_node->connection->last_successful_communication = time(NULL);
    new_node->connection->retry_count = 0;

    new_node->next = pool->head;
    pool->head = new_node;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

Connection* find_connection(ConnectionPool *pool, int connection_id) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head;
    while (current) {
        if (current->connection->connection_id == connection_id) {
            pthread_mutex_unlock(&pool->lock);
            return current->connection;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL; // Not found
}

void prune_inactive_connections(ConnectionPool *pool, time_t timeout) {
    pthread_mutex_lock(&pool->lock);

    Node **current = &(pool->head);
    while (*current) {
        Node *entry = *current;
        if (difftime(time(NULL), entry->connection->last_successful_communication) > timeout) {
            *current = entry->next;
            free(entry->connection);
            free(entry);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void destroy_connection_pool(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head;
    while (current) {
        Node *tmp = current;
        current = current->next;
        free(tmp->connection);
        free(tmp);
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void test_connection_pool() {
    ConnectionPool *pool = create_connection_pool(INITIAL_MAX_CONNECTIONS);

    add_connection(pool, 1, "localhost", 8080);
    add_connection(pool, 2, "remotehost", 9090);

    Connection *conn = find_connection(pool, 1);
    if (conn) {
        printf("Found connection: %s:%d\n", conn->client_hostname, conn->port_number);
    }

    prune_inactive_connections(pool, 60); // Prune connections inactive for more than 60 seconds

    destroy_connection_pool(pool);
}

int main() {
    test_connection_pool();
    return 0;
}
```

This C code provides a basic implementation of a connection pool manager with thread safety and simple pruning logic. It handles dynamic memory allocation, error checking, and includes a test function to demonstrate its usage. Adjustments may be necessary for more complex scenarios, such as dynamic resizing based on system metrics or advanced logging features.']

