#include <time.h>

// Define a structure for CRC indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
int allocate_and_populate_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t n_pdus, unsigned int seed, uint16_t rnti_start, uint16_t rnti_end) {
    if (n_pdus <= 0) {
        fprintf(stderr, "Invalid number of PDUs requested.\n");
        return -1;
    }

    const size_t MAX_PDUS = 10000; // Example system-defined threshold
    if (n_pdus > MAX_PDUS) {
        fprintf(stderr, "Requested PDUs exceed maximum allowed limit.\n");
        return -2;
    }

    // Allocate memory for the array of PDUs
    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -3;
    }

    // Seed the random number generator
    srand(seed);

    // Validate RNTI range
    if (rnti_start >= rnti_end || rnti_start > 65535 || rnti_end > 65535) {
        fprintf(stderr, "Invalid RNTI range provided.\n");
        free(*pdus);
        return -4;
    }

    uint16_t *used_rntis = (uint16_t *)malloc((rnti_end - rnti_start + 1) * sizeof(uint16_t));
    if (used_rntis == NULL) {
        fprintf(stderr, "Memory allocation for RNTI tracking failed.\n");
        free(*pdus);
        return -5;
    }

    // Initialize used RNTIs
    for (size_t i = 0; i < (rnti_end - rnti_start + 1); ++i) {
        used_rntis[i] = 0xFFFF;
    }

    size_t unique_rntis_count = 0;

    for (size_t i = 0; i < n_pdus; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Generate a random RX_UE_INFORMATION_TAG

        int rnti_assigned = 0;
        while (!rnti_assigned) {
            uint16_t candidate_rnti = rnti_start + (rand() % (rnti_end - rnti_start + 1));

            if (used_rntis[candidate_rnti - rnti_start] == 0xFFFF) {
                used_rntis[candidate_rnti - rnti_start] = candidate_rnti;
                unique_rntis_count++;
                (*pdus)[i].RNTI = candidate_rnti;
                rnti_assigned = 1;
            }
        }

        // Randomly set CRCFLAG
        (*pdus)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    }

    free(used_rntis);
    return 0; // Success
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    int result = allocate_and_populate_pdus(&pdus, 100, 42, 1, 500);

    if (result == 0) {
        printf("PDUs allocated and populated successfully.\n");
    } else {
        printf("Error occurred: %d\n", result);
    }

    // Free allocated memory
    free(pdus);
    return 0;
}
