#define MAX_MEMORY_SIZE 1024 * 1024 // Example maximum memory size, adjust as needed
#define LOG_FILE "usage.log"
#define OUTPUT_FILE "output.txt"

typedef struct {
    int value;
    double timestamp;
    char status_flag;
} Record;

typedef struct PoolNode {
    Record record;
    struct PoolNode* next;
} PoolNode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t records_count);
int initialize_records(long num_records, long offset_values[], int keys[], Record** records, PoolNode** pool_head, int min_value, int max_value);
void free_resources(long offset_values[], int keys[], Record* records, PoolNode* pool_head);
void fill_random_record(Record* record, int min_value, int max_value);

int initialize_records(long num_records, long offset_values[], int keys[], Record** records, PoolNode** pool_head, int min_value, int max_value) {
    size_t total_size = sizeof(long) * 3 + sizeof(int) * 2 + sizeof(Record) * num_records;

    if (total_size > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Memory allocation error: Exceeds maximum allowed memory.\n");
        return -1; // Error code for exceeding max memory
    }

    offset_values = (long*) malloc(sizeof(long) * 3);
    keys = (int*) malloc(sizeof(int) * num_records);

    if (!offset_values || !keys) {
        free_resources(offset_values, keys, NULL, *pool_head);
        return -2; // Error code for allocation failure
    }

    Record* records_array = *records = (Record*) calloc(num_records, sizeof(Record));
    if (!records_array) {
        free_resources(offset_values, keys, records_array, *pool_head);
        return -3; // Error code for allocation failure
    }

    PoolNode** current_pool_node = pool_head;
    while (*current_pool_node != NULL && num_records > 0) {
        Record* record_to_reuse = &(*current_pool_node)->record;
        fill_random_record(record_to_reuse, min_value, max_value);

        *records_array++ = *record_to_reuse;
        PoolNode* temp_node = *current_pool_node;
        *current_pool_node = (*current_pool_node)->next;

        free(temp_node);

        num_records--;
    }

    while (num_records > 0) {
        fill_random_record(records_array++, min_value, max_value);
        num_records--;
    }

    log_memory_usage(num_records + 3); // Log initial allocation
    return 0; // Success code
}

void free_resources(long offset_values[], int keys[], Record* records, PoolNode* pool_head) {
    if (offset_values) free(offset_values);
    if (keys) free(keys);
    if (records) free(records);

    while (pool_head != NULL) {
        PoolNode* temp_node = pool_head;
        pool_head = pool_head->next;
        free(temp_node);
    }
}

void fill_random_record(Record* record, int min_value, int max_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    static const char status_flags[] = {'A', 'B', 'C'};

    record->value = rand() % (max_value - min_value + 1) + min_value;
    record->timestamp = (double)(mktime(tm_info)) / 86400.0; // Current day of year
    record->status_flag = status_flags[rand() % sizeof(status_flags)];
}

void log_memory_usage(size_t records_count) {
    FILE* file = fopen(LOG_FILE, "a");
    if (!file) return;

    time_t now = time(NULL);
    fprintf(file, "%s: Monitoring %zu records\n", ctime(&now), records_count);

    fclose(file);
}

void iterate_and_print(Record* records, long num_records, const char* filename, int append) {
    FILE* file = fopen(filename, append ? "a" : "w");
    if (!file) return;

    for (long i = 0; i < num_records; ++i) {
        fprintf(file, "Record %ld: Value=%d, Timestamp=%.2f, Status='%c'\n", 
                i + 1, records[i].value, records[i].timestamp, records[i].status_flag);
    }

    fclose(file);
}

