['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB max memory usage
#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    long offset;
    int has_key;
    int has_offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    unsigned int allocations;
    unsigned int deallocations;
} Collection;

void log_time(const char* message) {
    time_t start = time(NULL);
    printf("%s at %ld\n", message, start);
}

Collection* init_collection() {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(INITIAL_CAPACITY, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->allocations = 0;
    collection->deallocations = 0;

    log_time("Collection initialized");
    return collection;
}

int resize_collection(Collection* collection, size_t new_capacity) {
    Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    collection->records = new_records;
    collection->capacity = new_capacity;
    log_time("Collection resized");
    return 0;
}

int add_record(Collection* collection, int key, long offset) {
    if (collection == NULL || collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        if (new_capacity * sizeof(Record) > MAX_MEMORY_USAGE) return -1;

        if (resize_collection(collection, new_capacity)) return -1;
    }

    Record* record = &collection->records[collection->count++];
    record->key = key;
    record->offset = offset;
    record->has_key = 1;
    record->has_offset = 1;

    collection->allocations++;
    log_time("Record added");
    return 0;
}

int remove_record(Collection* collection, size_t index) {
    if (index >= collection->count) return -1;

    // Shift remaining records left
    for (size_t i = index; i < collection->count - 1; ++i) {
        collection->records[i] = collection->records[i + 1];
    }

    collection->count--;
    collection->deallocations++;
    log_time("Record removed");
    return 0;
}

void report(Collection* collection) {
    printf("Allocations: %u\n", collection->allocations);
    printf("Deallocations: %u\n", collection->deallocations);
    printf("Current count: %zu\n", collection->count);
    printf("Current capacity: %zu\n", collection->capacity);
}

void free_collection(Collection* collection) {
    if (collection) {
        free(collection->records);
        free(collection);
        log_time("Collection freed");
    }
}

int main() {
    Collection* collection = init_collection();
    if (!collection) {
        printf("Failed to initialize collection\n");
        return 1;
    }

    // Simulating adding records
    for (int i = 0; i < 20; ++i) {
        add_record(collection, i, i * 100L);
    }

    // Simulating removing a record
    remove_record(collection, 5);

    report(collection);
    free_collection(collection);

    return 0;
}
