import java.io.BufferedReader;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;

public class ExternalCommandExecutor {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MS = 2000; // Delay between retries

    public static void main(String[] args) {
        String command = "your_command_here";
        File tempFile = createTempFile();

        try {
            executeCommandWithRetries(command, tempFile);
        } catch (Exception e) {
            System.err.println("Failed to execute command: " + e.getMessage());
        } finally {
            deleteTempFile(tempFile);
        }
    }

    private static void executeCommandWithRetries(String command, File tempFile) throws Exception {
        int attempt = 0;
        boolean success = false;

        while (attempt < MAX_RETRIES && !success) {
            try {
                int exitCode = runExternalCommand(command, tempFile);
                if (isTransientError(exitCode)) {
                    System.err.println("Transient error encountered. Retrying...");
                    Thread.sleep(RETRY_DELAY_MS);
                } else {
                    success = true;
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Execution failed: " + e.getMessage());
            }
            attempt++;
        }

        if (!success) {
            throw new Exception("Command execution failed after retries.");
        }
    }

    private static int runExternalCommand(String command, File tempFile) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command, null, tempFile);

        int exitCode = handleProcessStreams(process);
        process.waitFor();

        return exitCode;
    }

    private static int handleProcessStreams(Process process) throws IOException {
        try (BufferedReader stdOutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader stdErrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            String line;
            while ((line = stdOutReader.readLine()) != null) {
                System.out.println("OUTPUT: " + line);
            }

            while ((line = stdErrReader.readLine()) != null) {
                System.err.println("ERROR: " + line);
            }
        }

        return process.exitValue();
    }

    private static boolean isTransientError(int exitCode) {
        // Define transient error codes and conditions here
        return exitCode == 1 || exitCode == 2; // Example transient error codes
    }

    private static File createTempFile() throws IOException {
        File tempFile = Files.createTempFile("command_output_", ".tmp").toFile();
        tempFile.deleteOnExit();
        return tempFile;
    }

    private static void deleteTempFile(File tempFile) {
        if (tempFile != null && tempFile.exists()) {
            try {
                boolean deleted = tempFile.delete();
                if (!deleted) {
                    System.err.println("Failed to delete temporary file: " + tempFile.getPath());
                }
            } catch (SecurityException e) {
                System.err.println("Permission denied when deleting temporary file: " + tempFile.getPath());
            }
        }
    }
}
```

This Java application handles the execution of an external command with retry logic for transient errors, manages a temporary file's lifecycle, and processes both standard output and error streams effectively. It also ensures proper cleanup of resources, even in case of failures.']

['```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <fstream>
#include <memory>
#include <mutex>
#include <thread>
#include <chrono>
#include <nlohmann/json.hpp> // Assuming use of the nlohmann/json library for JSON parsing

enum class TaskStatus { Pending, InProgress, Completed, Cancelled };

class Task {
public:
    int id;
    std::string description;
    int priority;
    TaskStatus status;

    Task(int id = 0, const std::string& description = "", int priority = 1, TaskStatus status = TaskStatus::Pending)
        : id(id), description(description), priority(priority), status(status) {}
};

class TaskManager {
private:
    struct MemoryInfo {
        size_t peakUsage;
        size_t currentUsage;
    };

    static constexpr size_t MAX_MEMORY_USAGE = 1024 * 1024; // e.g., 1MB
    std::vector<std::unique_ptr<Task>> tasks;
    std::unordered_map<int, Task*> taskPool;
    std::mutex mtx;
    MemoryInfo memoryInfo;

    void logMemoryUsage() {
        std::ofstream logFile("task_usage.log", std::ios_base::app);
        if (logFile) {
            auto now = std::chrono::system_clock::now();
            auto now_c = std::chrono::system_clock::to_time_t(now);
            logFile << std::ctime(&now_c) 
                    << "Current: " << memoryInfo.currentUsage 
                    << ", Peak: " << memoryInfo.peakUsage 
                    << ", Tasks: " << tasks.size() << "\n";
        }
    }

public:
    TaskManager() : memoryInfo{0, 0} {}

    bool initializeFromAPI(const std::string& apiUrl) {
        std::lock_guard<std::mutex> lock(mtx);

        // Simulate fetching data from an API
        nlohmann::json jsonData = simulateAPICall(apiUrl);

        for (const auto& taskData : jsonData["tasks"]) {
            if (taskPool.empty()) {
                tasks.emplace_back(std::make_unique<Task>());
            }

            Task* task = taskPool.empty() ? tasks.back().get() : taskPool.begin()->second;

            // Ensure id is unique and sequential
            int newId = tasks.size() + 1;

            task->id = newId;
            task->description = taskData["description"].get<std::string>();
            task->priority = std::clamp(taskData["priority"].get<int>(), 1, 10);

            static const std::unordered_map<std::string, TaskStatus> statusMap{
                {"Pending", TaskStatus::Pending},
                {"In Progress", TaskStatus::InProgress},
                {"Completed", TaskStatus::Completed},
                {"Cancelled", TaskStatus::Cancelled}
            };

            task->status = statusMap.at(taskData["status"].get<std::string>());

            // Reuse or allocate new
            if (taskPool.find(newId) != taskPool.end()) {
                taskPool.erase(newId);
            } else {
                tasks.emplace_back(std::make_unique<Task>(*task));
            }

            // Update memory info
            size_t currentUsage = calculateMemoryUsage();
            memoryInfo.currentUsage = currentUsage;
            if (currentUsage > memoryInfo.peakUsage) {
                memoryInfo.peakUsage = currentUsage;
                logMemoryUsage();
            }

            if (currentUsage > MAX_MEMORY_USAGE) {
                // Handle memory overflow by deallocating
                return false;
            }
        }

        return true;
    }

    void printTasksToFile(const std::string& filePath) const {
        std::ofstream outFile(filePath, std::ios_base::out | std::ios_base::trunc);
        if (!outFile) {
            std::cerr << "Failed to open file for writing\n";
            return;
        }

        for (const auto& task : tasks) {
            outFile << "ID: " << task->id 
                    << ", Description: " << task->description
                    << ", Priority: " << task->priority 
                    << ", Status: " 
                    << static_cast<int>(task->status) << "\n";
        }
    }

    void filterTasks(int minPriority, TaskStatus statusFilter, std::vector<Task*>& filteredTasks) const {
        for (const auto& task : tasks) {
            if (task->priority >= minPriority && task->status == statusFilter) {
                filteredTasks.push_back(task.get());
            }
        }
    }

private:
    nlohmann::json simulateAPICall(const std::string&) {
        // Simulated JSON response
        return R"([{"description": "Task 1", "priority": 5, "status": "Pending"},
                  {"description": "Task 2", "priority": 3, "status": "Completed"}])"_json;
    }

    size_t calculateMemoryUsage() {
        // Simplified memory usage calculation
        return tasks.size() * sizeof(Task);
    }
};

// Example of how to use the TaskManager class within an application:
int main() {
    TaskManager manager;

    if (manager.initializeFromAPI("http://api.example.com/tasks")) {
        std::vector<Task*> filteredTasks;
        manager.filterTasks(3, TaskStatus::Pending, filteredTasks);

        for (const auto* task : filteredTasks) {
            std::cout << "Filtered Task ID: " << task->id << "\n";
        }

        manager.printTasksToFile("task_output.txt");
