// Free the dynamic array
void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    for (size_t i = 0; i < array->context_count; ++i) {
        pthread_mutex_lock(&array->contexts[i].message_list.lock);
        for (size_t j = 0; j < array->contexts[i].message_list.message_count; ++j) {
            free(array->contexts[i].message_list.messages[j].content);
        }
        free(array->contexts[i].message_list.messages);
        pthread_mutex_unlock(&array->contexts[i].message_list.lock);
        pthread_mutex_destroy(&array->contexts[i].message_list.lock);
    }

    free(array->contexts);
    pthread_mutex_destroy(&array->lock);

    free(array);
}

// Add a message to the context for the given cell ID
int add_message_to_context(DynamicArray* array, int cell_id, LTE_DL_CCCH_MSG_TYPE_1_T message) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->context_count; ++i) {
        if (array->contexts[i].cell_id == cell_id) {
            MessageList* list = &array->contexts[i].message_list;
            pthread_mutex_lock(&list->lock);

            if (list->message_count >= list->capacity) {
                size_t new_capacity = list->capacity ? list->capacity * 2 : INITIAL_CAPACITY;
                LTE_DL_CCCH_MSG_TYPE_1_T* new_messages = (LTE_DL_CCCH_MSG_TYPE_1_T*)realloc(list->messages, new_capacity * sizeof(LTE_DL_CCCH_MSG_TYPE_1_T));
                if (!new_messages) {
                    pthread_mutex_unlock(&list->lock);
                    pthread_mutex_unlock(&array->lock);
                    return -1;
                }
                list->messages = new_messages;
                list->capacity = new_capacity;
            }

            list->messages[list->message_count] = message;
            ++list->message_count;

            pthread_mutex_unlock(&list->lock);
            pthread_mutex_unlock(&array->lock);

            return 0;
        }
    }

    if (array->context_count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : INITIAL_CAPACITY;
        LTE_ENB_RRC_UE_CONTEXT_T* new_contexts = (LTE_ENB_RRC_UE_CONTEXT_T*)realloc(array->contexts, new_capacity * sizeof(LTE_ENB_RRC_UE_CONTEXT_T));
        if (!new_contexts) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }

    LTE_ENB_RRC_UE_CONTEXT_T* context = &array->contexts[array->context_count++];
    context->cell_id = cell_id;
    context->rrc_connection_state = 0; // Default state

    MessageList* list = &context->message_list;
    pthread_mutex_init(&list->lock, NULL);
    list->messages = (LTE_DL_CCCH_MSG_TYPE_1_T*)malloc(INITIAL_CAPACITY * sizeof(LTE_DL_CCCH_MSG_TYPE_1_T));
    if (!list->messages) {
        free_dynamic_array(array); // Clean up
        return -1;
    }
    list->capacity = INITIAL_CAPACITY;
    list->message_count = 0;

    pthread_mutex_unlock(&array->lock);

    add_message_to_context(array, cell_id, message);
    return 0;
}

// Update a specific message in the context for the given cell ID
int update_message_in_context(DynamicArray* array, int cell_id, int message_index, LTE_DL_CCCH_MSG_TYPE_1_T new_message) {
    if (!array || message_index < 0) return -1;

    pthread_mutex_lock(&array->lock);

