#include <time.h>

#define MAX_BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[MAX_BUFFER_SIZE];
    time_t timestamp;
} Record;

typedef struct {
    size_t accessFrequency;
    time_t lastAccessedTimestamp;
} Metadata;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    Metadata **metadata;
    size_t capacity;
    size_t currentSize;
    pthread_mutex_t lock; // For thread safety
} DataStructure;

DataStructure* initialize_data_structure(size_t size, unsigned int seed) {
    srand(seed);

    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed for DataStructure\n");
        return NULL;
    }

    ds->capacity = size;
    ds->currentSize = 0;

    ds->offsets = (long *)calloc(size, sizeof(long));
    ds->keys = (int *)malloc(size * sizeof(int));
    ds->records = (Record *)malloc(size * sizeof(Record));
    ds->metadata = (Metadata **)malloc(size * sizeof(Metadata*));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->metadata) {
        fprintf(stderr, "Memory allocation failed for arrays\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->metadata);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        ds->keys[i] = rand();
        snprintf(ds->records[i].buffer, MAX_BUFFER_SIZE, "%.*s", 
                 rand() % MAX_BUFFER_SIZE + 1, "abcdefghijklmnopqrstuvwxyz");
        ds->records[i].timestamp = time(NULL);
        ds->metadata[i] = (Metadata *)malloc(sizeof(Metadata));
        if (!ds->metadata[i]) {
            fprintf(stderr, "Memory allocation failed for Metadata\n");
            // Free previously allocated memory
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            while (--i >= 0) free(ds->metadata[i]);
            free(ds->metadata);
            free(ds);
            return NULL;
        }
    }

    return ds;
}

void free_data_structure(DataStructure *ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->capacity; ++i) {
        free(ds->metadata[i]);
    }

    pthread_mutex_destroy(&ds->lock);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->metadata);
    free(ds);
}

size_t loadResourceBundleFromFile(const char *filename, char ***bundle, size_t *bundleSize) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return 0;
    }

    // Assuming each line is a separate item
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *content = (char *)malloc(fileSize + 1);
    if (!content) {
        fprintf(stderr, "Memory allocation failed for file content\n");
        fclose(file);
        return 0;
    }

    fread(content, fileSize, 1, file);
    fclose(file);

    // Count lines
    size_t itemCount = 0;
    char *line = strtok(content, "\n");
    while (line) {
        itemCount++;
        line = strtok(NULL, "\n");
    }

    if (itemCount == 0) {
        free(content);
        fprintf(stderr, "No valid items found in file\n");
        return 0;
    }

    char **items = (char **)malloc(itemCount * sizeof(char *));
    if (!items) {
        free(content);
        fprintf(stderr, "Memory allocation failed for bundle items\n");
        return 0;
    }

    // Tokenize again to fill the array
    fseek(file, 0, SEEK_SET);
    fread(content, fileSize, 1, file);
    fclose(file);

    char *lineStart = content;
    size_t index = 0;
    while ((content[strcspn(lineStart, "\n")] = '\0', line = strtok(lineStart, "\n"))) {
        items[index++] = strdup(line);
        lineStart = content + strlen(line) + 1;
    }

    free(content);

    *bundle = items;
    if (bundleSize) *bundleSize = itemCount;

    return itemCount;
}

void freeResourceBundle(char **bundle, size_t bundleSize) {
    for (size_t i = 0; i < bundleSize; ++i) {
        free(bundle[i]);
    }
    free(bundle);
}
