// Record structure definition
typedef struct {
    int value;
    char buffer[256];
    time_t timestamp;
} record_t;

// Metadata structure for auxiliary data
typedef struct {
    int access_frequency;
    time_t last_accessed;
} metadata_t;

// Data structure to manage records and associated resources
typedef struct {
    long *offsets;
    int *keys;
    record_t **records;
    metadata_t **metadata;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t lock;
