#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char *str;
    int counter;
} item;

#define MAX_STRING_LENGTH 256

enum { SUCCESS = 0, ALLOCATION_FAILURE };

int initialize_items(int max_size, unsigned int seed) {
    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        return ALLOCATION_FAILURE;
    }

    double *doubles = malloc(max_size * sizeof(double));
    char **strings = malloc(max_size * MAX_STRING_LENGTH * sizeof(char*));
    item **items = malloc(max_size * sizeof(item*));

    if (!doubles || !strings || !items) {
        free(doubles);
        free(strings);
        free(items);
        pthread_mutex_destroy(&mutex);
        return ALLOCATION_FAILURE;
    }

    srand(seed);

    for (int i = 0; i < max_size; ++i) {
        // Allocate and initialize each string with a unique identifier
        strings[i] = malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!strings[i]) {
            goto cleanup_failure;
        }
        snprintf(strings[i], MAX_STRING_LENGTH, "ID_%d", i);

        // Allocate and initialize the item structure
        items[i] = malloc(sizeof(item));
        if (!items[i]) {
            free(strings[i]);
            goto cleanup_failure;
        }

        doubles[i] = (double)rand() / RAND_MAX;  // Initialize double with random value
        items[i]->value = doubles[i];
        items[i]->str = strings[i];
        items[i]->counter = rand();  // Initialize counter with a random number

        pthread_mutex_lock(&mutex);
    }

    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);

    return SUCCESS;

cleanup_failure:
    for (int i = 0; i < max_size; ++i) {
        if (strings[i]) free(strings[i]);
        if (items[i]) free(items[i]);
    }
    free(doubles);
    free(strings);
    free(items);
    pthread_mutex_destroy(&mutex);
    return ALLOCATION_FAILURE;
}
```

