void* allocate_aligned(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Failed allocation
    }
#else
#error "Platform not supported for aligned memory allocation."
#endif
    return ptr;
}

void log_message(const char* message) {
    printf("%s\n", message);
}

record_t* initialize_records(size_t max_size, int value_range_min, int value_range_max) {
    record_t *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;

    // Seed the random number generator
    srand((unsigned int)(time(NULL) ^ (getpid() << 16)));

    size_t attempt_size = max_size;
    while (attempt_size > 0) {
        offsets = allocate_aligned(attempt_size * sizeof(long), sizeof(long));
        keys = allocate_aligned(attempt_size * sizeof(int), sizeof(int));
        records = allocate_aligned(attempt_size * sizeof(record_t), sizeof(record_t));

        if (!offsets || !keys || !records) {
            log_message("Failed to allocate memory. Reducing size and retrying...");
            attempt_size /= 2; // Reduce request size
            continue;
        }

        bool all_initialized = true;
        for (size_t i = 0; i < attempt_size; ++i) {
            offsets[i] = rand() % 1000; // Example offset value
            keys[i] = rand() % (value_range_max - value_range_min + 1) + value_range_min;

            if (!is_key_unique(keys[i])) {
                log_message("Key collision detected. Retrying...");
                all_initialized = false;
                break;
            }

            int unique_value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
            bool is_value_unique = true;

            for (size_t j = 0; j < i; ++j) {
                if (records[j].value == unique_value) {
                    is_value_unique = false;
                    break;
                }
            }

            while (!is_value_unique) {
                unique_value++;
                if (unique_value > value_range_max) {
                    log_message("Unable to find a unique value within the specified range.");
                    all_initialized = false;
                    goto cleanup; // Exit loop on failure
                }

                is_value_unique = true;
                for (size_t j = 0; j < i; ++j) {
                    if (records[j].value == unique_value) {
                        is_value_unique = false;
                        break;
                    }
                }
            }

            records[i].value = unique_value;
            records[i].key_ptr = &keys[i];
            records[i].offset_ptr = &offsets[i];

            log_message("Record initialized successfully.");
        }

        if (all_initialized) {
            return records; // Successful initialization
        }

    cleanup:
        free(offsets);
        free(keys);
        free(records);

        attempt_size /= 2;
    }

    log_message("Unable to allocate memory for requested size. Please adjust input parameters.");
    return NULL;
}

int main() {
    size_t max_records = 1000; // Example maximum size
