```csharp
using System;
using System.Data;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Serilog;

public class ThemeManager
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly string _defaultThemeDirectory = "DefaultThemeDir";

    public ThemeManager(HttpClient httpClient, IMemoryCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));

        Log.Logger = new LoggerConfiguration()
            .WriteTo.Console()
            .WriteTo.File("logs/theme_manager.txt", rollingInterval: RollingInterval.Day)
            .CreateLogger();
    }

    public static ServiceProvider InitializeEnvironment(string configurationPath)
    {
        var services = new ServiceCollection();

        // Load Configuration
        var configurationBuilder = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile(configurationPath, optional: false, reloadOnChange: true);

        IConfigurationRoot configuration = configurationBuilder.Build();

        services.AddSingleton<IConfiguration>(configuration);

        // Set up HttpClient
        services.AddHttpClient();

        // Set up Memory Cache
        services.AddMemoryCache();

        return services.BuildServiceProvider();
    }

    public async Task<DataTableReader> SendDataAsync(byte[] data)
    {
        try
        {
            var response = await _httpClient.PostAsync("https://remote-server.com/api/data", new ByteArrayContent(data));

            if (!response.IsSuccessStatusCode)
            {
                Log.Error("Failed to send data: {Status} {Reason}", response.StatusCode, response.ReasonPhrase);
                throw new HttpRequestException($"Server responded with status code: {response.StatusCode}");
            }

            var dataTable = await response.Content.ReadAsAsync<DataTable>();
            return dataTable.CreateDataReader();
        }
        catch (Exception ex)
        {
            Log.Error(ex, "An error occurred while sending data.");
            throw;
        }
    }

    public void ConfigureThemeDirectory(string themeDir = null)
    {
        _defaultThemeDirectory = string.IsNullOrEmpty(themeDir) ? _defaultThemeDirectory : themeDir;
    }

    public bool TryParseAndCachePngFile(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
            {
                Log.Warning("PNG file not found: {FilePath}", filePath);
                return false;
            }

            using (var stream = File.OpenRead(filePath))
            {
                var bitmapData = new byte[stream.Length];
                stream.Read(bitmapData, 0, bitmapData.Length);

                _cache.Set(Path.GetFileName(filePath), bitmapData, TimeSpan.FromMinutes(30));
                Log.Information("Cached PNG file: {FilePath}", filePath);
            }

            return true;
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Error parsing and caching PNG file: {FilePath}", filePath);
            return false;
        }
    }
}

