#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <limits.h>

#define MAX_RECORDS 1000
#define LOGGING_THRESHOLD 10

typedef struct Record {
    long offset;
    int key;
    int value;
    int priority; // Lower values indicate higher priority
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int size;
    // Priority queue logic or any other efficient structure can be added here.
} PriorityQueue;

PriorityQueue pq = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

// Mock functions for logging and analytics integration
void log_entry(const Record* record) {
    // Integrate with existing logging framework
}

void perform_analytics() {
    // Connect to external analytics module
}

int random_value_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void init_record(Record* record, long offset, int key, int priority, int value_min, int value_max) {
    record->offset = offset;
    record->key = key;
    record->value = random_value_in_range(value_min, value_max);
    record->priority = priority;
}

Node* create_node(const Record* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    *(&new_node->record) = *(Record*)record;
    new_node->next = NULL;
    return new_node;
}

void insert_record(long offset, int key, int priority, int value_min, int value_max) {
    Record new_record;
    init_record(&new_record, offset, key, priority, value_min, value_max);

    Node* new_node = create_node(&new_record);
    if (!new_node) return;

    pthread_mutex_lock(&pq.lock);

    // Insert node based on priority
    if (pq.head == NULL || pq.head->record.priority > priority) {
        new_node->next = pq.head;
        pq.head = new_node;
    } else {
        Node* current = pq.head;
        while (current->next != NULL && current->next->record.priority <= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pq.size++;

    if (pq.size % LOGGING_THRESHOLD == 0) {
        log_entry(&new_record);
    }

    perform_analytics();

    pthread_mutex_unlock(&pq.lock);
}

Record* retrieve_record(int key, int* found) {
    pthread_mutex_lock(&pq.lock);

    Node* current = pq.head;
    while (current != NULL) {
        if (current->record.key == key) {
            *found = 1;
            Record* record = malloc(sizeof(Record));
            *record = current->record;
            // Remove node
            if (current == pq.head) {
                pq.head = current->next;
            } else {
                Node* prev = pq.head;
                while (prev->next != current) {
                    prev = prev->next;
                }
                prev->next = current->next;
            }

            free(current);
            pq.size--;

            pthread_mutex_unlock(&pq.lock);
            return record;
        }
        current = current->next;
    }

    *found = 0;
    pthread_mutex_unlock(&pq.lock);
    return NULL;
}

void delete_record(int key) {
    int found;
    retrieve_record(key, &found);

    if (!found) {
        // Handle deletion failure or log it
    }
}

int main() {
    srand(time(NULL));

    insert_record(1, 101, 5, 0, 100);
    insert_record(2, 102, 3, 10, 50);

    int found;
    Record* record = retrieve_record(101, &found);
    if (found) {
        printf("Retrieved: %d\n", record->value);
        free(record);
    }

    delete_record(102);

    return 0;
}
```

