    long timestamp;
} Event;

typedef struct {
    size_t num_events;
    size_t capacity;
    Event **events_array;
} Log;

Log* create_logs(size_t num_logs) {
    if (num_logs == 0) return NULL;

    Log *logs = malloc(num_logs * sizeof(Log));
    if (!logs) return NULL;

    for (size_t i = 0; i < num_logs; ++i) {
        logs[i].num_events = 0;
        logs[i].capacity = INITIAL_EVENT_SIZE;
        logs[i].events_array = calloc(logs[i].capacity, sizeof(Event*));
        if (!logs[i].events_array) {
            // Free previously allocated logs
            for (size_t j = 0; j < i; ++j) {
                free(logs[j].events_array);
            }
            free(logs);
            return NULL;
        }

        // Initialize events with unique strings and default data
        char identifier[MAX_STRING_LENGTH];
        snprintf(identifier, sizeof(identifier), "log%d", (int)(i + 1));

        for (size_t j = 0; j < logs[i].capacity; ++j) {
            Data *data = malloc(sizeof(Data));
            if (!data) {
                // Free previously allocated events
