#define MAX_NAME_LENGTH 100
#define MAX_CONTACT_INFO_LENGTH 200
#define MAX_ADDRESS_LENGTH 300

typedef enum { PENDING, CONFIRMED, SHIPPED, CANCELLED } OrderStatus;

typedef struct {
    char name[MAX_NAME_LENGTH];
    char contact_info[MAX_CONTACT_INFO_LENGTH];
} CustomerDetails;

typedef struct {
    int item_id;
    char description[100];
    int quantity;
    double price;
} OrderItem;

typedef struct Order {
    int order_id;
    CustomerDetails customer_details;
    OrderItem *items; // Dynamically allocated array
    int num_items;
    char shipping_address[MAX_ADDRESS_LENGTH];
    OrderStatus status;
    time_t last_updated;
    struct Order *next;
} Order;

typedef struct {
    Order *head;
    int (*compare)(Order *, Order *);
} OrderList;

int compare_orders_by_id(const void *a, const void *b) {
    return ((Order *)a)->order_id - ((Order *)b)->order_id;
}

OrderList* create_order_list() {
    OrderList *list = (OrderList*)malloc(sizeof(OrderList));
    list->head = NULL;
    list->compare = compare_orders_by_id;
    return list;
}

void free_order_items(OrderItem *items, int num) {
    if (!items) return;
    for (int i = 0; i < num; ++i) {
        // Free any dynamically allocated resources within each item if necessary
    }
    free(items);
}

void free_order(Order *order) {
    if (!order) return;
    free_order_items(order->items, order->num_items);
    free(order);
}

Order* find_order_by_id(OrderList *list, int order_id) {
    Order *current = list->head;
    while (current) {
        if (current->order_id == order_id) return current;
        current = current->next;
    }
    return NULL;
}

void add_or_update_order(OrderList *list, Order *new_order) {
    Order *existing_order = find_order_by_id(list, new_order->order_id);
    if (existing_order) {
        // Update existing order
        memcpy(&existing_order->customer_details, &new_order->customer_details, sizeof(CustomerDetails));
        free_order_items(existing_order->items, existing_order->num_items);
        existing_order->num_items = new_order->num_items;
        existing_order->items = (OrderItem *)malloc(sizeof(OrderItem) * new_order->num_items);
        memcpy(existing_order->items, new_order->items, sizeof(OrderItem) * new_order->num_items);
        strncpy(existing_order->shipping_address, new_order->shipping_address, MAX_ADDRESS_LENGTH);
        existing_order->status = new_order->status;
        existing_order->last_updated = time(NULL);
    } else {
        // Add new order
        new_order->next = list->head;
        list->head = new_order;
    }
}

void cancel_inactive_orders(OrderList *list, int inactive_threshold_seconds) {
    time_t current_time = time(NULL);
    Order *current = list->head;
    Order **prev_ptr = &(list->head);

    while (current) {
        if ((current_time - current->last_updated) > inactive_threshold_seconds && current->status != CANCELLED) {
            *prev_ptr = current->next;
            free_order(current);
            current = *prev_ptr;
        } else {
            prev_ptr = &current->next;
            current = current->next;
        }
    }
}

void generate_summary_report(OrderList *list, time_t start_date, time_t end_date) {
    Order *current = list->head;
    double total_revenue = 0.0;
    int order_count = 0;

    while (current) {
        if (current->last_updated >= start_date && current->last_updated <= end_date) {
            for (int i = 0; i < current->num_items; ++i) {
                total_revenue += current->items[i].quantity * current->items[i].price;
            }
            order_count++;
        }
        current = current->next;
    }

    double average_order_value = order_count > 0 ? total_revenue / order_count : 0.0;

    printf("Summary Report:\n");
    printf("Total Revenue: %.2f\n", total_revenue);
    printf("Average Order Value: %.2f\n", average_order_value);
}

void free_order_list(OrderList *list) {
    while (list->head) {
        Order *current = list->head;
        list->head = current->next;
        free_order(current);
    }
    free(list);
}
```

This code provides a basic implementation for managing orders with dynamic memory allocation. It includes functions to add or update orders, cancel inactive ones, and generate summary reports within specified date ranges. The linked-list structure allows efficient order management, while ensuring safe memory handling.']

