#define MAX_PACKETS 1000000

typedef struct {
    int id;
    time_t timestamp;
    int status; // 0 = active, 1 = expired
    int value;
} Packet;

typedef struct {
    Packet *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
    int expiration_threshold_seconds;
} PacketManager;

void log_message(const char *message) {
    printf("%s\n", message); // Simplified logging for demonstration
}

PacketManager* create_packet_manager(int expiration_threshold_seconds) {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->expiration_threshold_seconds = expiration_threshold_seconds;
    memset(manager->packets, 0, sizeof(manager->packets));
    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        free(manager->packets[i]);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void purge_expired_packets(PacketManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        if (difftime(current_time, manager->packets[i]->timestamp) > manager->expiration_threshold_seconds) {
            free(manager->packets[i]);
            manager->packets[i] = NULL;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int find_packet_index(PacketManager *manager, int id) {
    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        if (manager->packets[i]->id == id) return i;
    }
    return -1;
}

void add_or_update_packet(PacketManager *manager, Packet *new_packet) {
    int index = find_packet_index(manager, new_packet->id);

    pthread_mutex_lock(&manager->lock);

    if (index != -1) { // Update existing packet
        manager->packets[index]->timestamp = time(NULL);
        manager->packets[index]->value = new_packet->value;
        log_message("Packet updated");
    } else { // Add new packet
        if (manager->count < MAX_PACKETS) {
            manager->packets[manager->count++] = malloc(sizeof(Packet));
            memcpy(manager->packets[manager->count - 1], new_packet, sizeof(Packet));
            log_message("Packet added");
        } else {
            log_message("Packet manager full: unable to add packet");
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

Packet* retrieve_packet(PacketManager *manager, int id) {
    int index = find_packet_index(manager, id);

    if (index != -1) {
        return manager->packets[index];
    } else {
        log_message("Packet not found");
        return NULL;
    }
}

void update_packets_from_data_source(PacketManager *manager) {
    // Simulate external data source interaction
    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        if (rand() % 10 == 0) { // Randomly choose some packets to update
            Packet *packet = manager->packets[i];
            packet->value += rand(); // Simulate new data value
            log_message("Packet updated from external source");
        }
    }
}

void handle_network_failure(PacketManager *manager) {
    log_message("Network failure detected: retrying...");
    // Implement retry logic here, e.g., exponential backoff
}

int main() {
    PacketManager *manager = create_packet_manager(60); // Expiry threshold of 60 seconds

    if (!manager) {
        fprintf(stderr, "Failed to initialize packet manager\n");
        return EXIT_FAILURE;
    }

    Packet new_packet = { .id = 1, .timestamp = time(NULL), .status = 0, .value = 100 };
    add_or_update_packet(manager, &new_packet);

    // Simulate periodic update from data source
    while (1) {
        purge_expired_packets(manager);
        update_packets_from_data_source(manager);

        sleep(5); // Wait for 5 seconds before next cycle
    }

    destroy_packet_manager(manager);

    return EXIT_SUCCESS;
}
