#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_RECORDS 1000
#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB for simplicity

typedef struct {
    int key;
    long offset;
    char* description;
} Record;

typedef struct {
    Record* records[MAX_RECORDS];
    size_t total_memory_usage;
    size_t record_count;
    int key_range_min, key_range_max;
    int offset_range_min, offset_range_max;
    int description_length;
} DataStore;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

char* generate_random_sentence(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyz ";
    char *sentence = malloc(length + 1);
    if (!sentence) {
        log_error("Memory allocation for sentence failed.");
        return NULL;
    }

    for (int i = 0; i < length; i++) {
        sentence[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    sentence[length] = '\0';

    return sentence;
}

void validate_configuration(DataStore *store, const char* config_file_path) {
    // Placeholder for configuration validation logic
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        log_error("Failed to open configuration file.");
        return;
    }

    fscanf(file, "%d %d", &store->key_range_min, &store->key_range_max);
    fscanf(file, "%d %d", &store->offset_range_min, &store->offset_range_max);
    fscanf(file, "%d", &store->description_length);

    if (store->key_range_min >= store->key_range_max || 
        store->offset_range_min >= store->offset_range_max ||
        store->description_length <= 0) {
        log_error("Invalid configuration settings.");
        fclose(file);
        return;
    }

    fclose(file);
}

void create_record(DataStore *store, int key, long offset, char* description) {
    size_t record_size = sizeof(Record);
    size_t desc_len = strlen(description);

    if (record_size + desc_len + 1 > MAX_MEMORY_USAGE || store->total_memory_usage + record_size + desc_len + 1 > MAX_MEMORY_USAGE) {
        log_error("Memory limit exceeded.");
        free(description);
        return;
    }

    Record *record = malloc(record_size);
    if (!record) {
        log_error("Memory allocation for record failed.");
        free(description);
        return;
    }

    record->key = key;
    record->offset = offset;
    record->description = description;

    store->records[store->record_count++] = record;
    store->total_memory_usage += (record_size + desc_len + 1);

    printf("Record created: Key=%d, Offset=%ld, Description Length=%zu\n", key, offset, desc_len);
}

void initialize_data_store(DataStore *store) {
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % (store->key_range_max - store->key_range_min + 1) + store->key_range_min;
        long offset = rand() % (store->offset_range_max - store->offset_range_min + 1) + store->offset_range_min;

        char *description = generate_random_sentence(store->description_length);
        if (!description) {
            continue;
        }

        create_record(store, key, offset, description);

        if (store->total_memory_usage >= MAX_MEMORY_USAGE || store->record_count == MAX_RECORDS) {
            break;
        }
    }
}

void free_data_store(DataStore *store) {
    for (size_t i = 0; i < store->record_count; i++) {
        free(store->records[i]->description);
        free(store->records[i]);
    }

    memset(store, 0, sizeof(DataStore));
}

int main(int argc, char* argv[]) {
    DataStore store;
    memset(&store, 0, sizeof(DataStore));

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    validate_configuration(&store, argv[1]);
    initialize_data_store(&store);

    // Example of freeing the data store
    free_data_store(&store);

    return 0;
}
```

