#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for bounds and version threshold
#define MAX_FRAMES 1024
#define LOG_BUFFER_SIZE 4096

typedef struct {
    int rnti;
    // Other frame-specific data can be added here
} RX_UE_INFORMATION_TAG;

typedef struct {
