} NFAPI_RX_FRAME_T;

typedef struct {
    char *key;
    char *value;
    int version;
} ConfigSetting;

typedef struct ConfigNode {
    ConfigSetting setting;
    struct ConfigNode *next;
} ConfigNode;

typedef struct {
    NFAPI_RX_FRAME_T frames[MAX_FRAMES];
    size_t frame_count;
    pthread_mutex_t mutex;
} FrameManager;

typedef struct {
    ConfigNode **buckets;
    int bucket_count;
    int version_threshold;
    pthread_rwlock_t rwlock;
} ConfigManager;

typedef enum {
    LOG_ERROR,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char message[LOG_BUFFER_SIZE];
    struct LogEntry *next;
} LogEntry;

typedef struct {
    LogEntry *head;
    pthread_mutex_t mutex;
} LogManager;

// Function prototypes
