NFAPI_RX_FRAME_T* get_frame(FrameManager *fm, uint32_t rnti);
void update_config(ConfigManager *cm, const char *key, const char *value, int version);
char* get_config(const ConfigManager *cm, const char *key);
void invalidate_configs(ConfigManager *cm);

// Function implementations

FrameManager* resource_manager_init() {
    FrameManager *fm = malloc(sizeof(FrameManager));
    if (!fm) return NULL;

    fm->frame_count = 0;
    pthread_mutex_init(&fm->mutex, NULL);

    LogManager *lm = malloc(sizeof(LogManager));
    lm->head = NULL;
    pthread_mutex_init(&lm->mutex, NULL);

    ConfigManager *cm = malloc(sizeof(ConfigManager));
    cm->bucket_count = 16; // Example bucket count
    cm->buckets = calloc(cm->bucket_count, sizeof(ConfigNode*));
    if (!cm->buckets) {
        free(fm);
        free(lm);
        return NULL;
    }
    cm->version_threshold = 5; // Configurable version threshold
    pthread_rwlock_init(&cm->rwlock, NULL);

    log_message(LOG_INFO, "Resource manager initialized.");

    return (void *)malloc(sizeof(FrameManager) + sizeof(LogManager) + sizeof(ConfigManager));
}

void resource_manager_destroy(void *rm) {
    FrameManager *fm = (FrameManager *)((char *)rm);
    ConfigManager *cm = (ConfigManager *)((char *)rm + sizeof(FrameManager));

    // Free all frames
    pthread_mutex_lock(&fm->mutex);
    for (size_t i = 0; i < fm->frame_count; ++i) {
        free(((NFAPI_RX_FRAME_T*)fm->frames)[i].ue_info_tag.key); // Assuming dynamic allocation of keys
    }
    pthread_mutex_unlock(&fm->mutex);

    // Free configuration settings
    pthread_rwlock_wrlock(&cm->rwlock);
    for (int i = 0; i < cm->bucket_count; ++i) {
        ConfigNode *node = cm->buckets[i];
        while (node) {
            ConfigNode *next = node->next;
            free(node->setting.key);
            free(node->setting.value);
            free(node);
            node = next;
        }
    }
    pthread_rwlock_unlock(&cm->rwlock);

    // Free managers
    pthread_mutex_destroy(&fm->mutex);
    pthread_rwlock_destroy(&cm->rwlock);
    free(fm->frames);  // Assuming dynamic allocation of frame array if needed
    free(cm->buckets);
    free(rm);
}

void add_frame(FrameManager *fm, NFAPI_RX_FRAME_T frame) {
    pthread_mutex_lock(&fm->mutex);
    if (fm->frame_count < MAX_FRAMES) {
        fm->frames[fm->frame_count++] = frame;
        log_message(LOG_INFO, "Frame added.");
    } else {
        log_message(LOG_ERROR, "Max frames reached. Cannot add more frames.");
    }
    pthread_mutex_unlock(&fm->mutex);
}

NFAPI_RX_FRAME_T* get_frame(FrameManager *fm, uint32_t rnti) {
    pthread_mutex_lock(&fm->mutex);
    for (size_t i = 0; i < fm->frame_count; ++i) {
        if (fm->frames[i].rnti == rnti) {
            log_message(LOG_INFO, "Frame retrieved.");
            pthread_mutex_unlock(&fm->mutex);
            return &fm->frames[i];
        }
    }
    log_message(LOG_ERROR, "Frame not found.");
    pthread_mutex_unlock(&fm->mutex);
    return NULL;
}

void update_config(ConfigManager *cm, const char *key, const char *value, int version) {
    size_t hash = abs((size_t)key % cm->bucket_count);
    ConfigNode **bucket = &cm->buckets[hash];

    pthread_rwlock_wrlock(&cm->rwlock);

    ConfigNode *node = *bucket;
    while (node) {
        if (strcmp(node->setting.key, key) == 0) {
            free(node->setting.value);
            node->setting.value = strdup(value);
            node->setting.version = version;
            log_message(LOG_INFO, "Config updated.");
            pthread_rwlock_unlock(&cm->rwlock);
            return;
        }
        node = node->next;
    }

    ConfigNode *new_node = malloc(sizeof(ConfigNode));
    new_node->setting.key = strdup(key);
    new_node->setting.value = strdup(value);
    new_node->setting.version = version;
    new_node->next = *bucket;
    *bucket = new_node;

    log_message(LOG_INFO, "Config added.");
    pthread_rwlock_unlock(&cm->rwlock);
}

char* get_config(const ConfigManager *cm, const char *key) {
    size_t hash = abs((size_t)key % cm->bucket_count);

    pthread_rwlock_rdlock(&cm->rwlock);

    ConfigNode *node = cm->buckets[hash];
    while (node) {
        if (strcmp(node->setting.key, key) == 0) {
            char *value_copy = strdup(node->setting.value);
            log_message(LOG_INFO, "Config retrieved.");
            pthread_rwlock_unlock(&cm->rwlock);
            return value_copy;
        }
        node = node->next;
    }

    log_message(LOG_ERROR, "Config not found.");
    pthread_rwlock_unlock(&cm->rwlock);
    return NULL;
}

void invalidate_configs(ConfigManager *cm) {
    pthread_rwlock_wrlock(&cm->rwlock);

    for (int i = 0; i < cm->bucket_count; ++i) {
        ConfigNode *node = cm->buckets[i];
        while (node) {
            if (node->setting.version < cm->version_threshold) {
                ConfigNode *to_delete = node;
                node = node->next;
                free(to_delete->setting.key);
                free(to_delete->setting.value);
                free(to_delete);
                cm->buckets[i] = node;
            } else {
                node = node->next;
            }
        }
    }

    log_message(LOG_INFO, "Outdated configs invalidated.");
    pthread_rwlock_unlock(&cm->rwlock);
}

void log_message(LogLevel level, const char *message) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    // Assuming LogManager is initialized and accessible
    extern LogManager *log_manager;

    pthread_mutex_lock(&log_manager->mutex);

    LogEntry *entry = malloc(sizeof(LogEntry));
    strncpy(entry->message, message, LOG_BUFFER_SIZE);
    entry->timestamp = now;
    entry->level = level;
    entry->next = log_manager->head;
    log_manager->head = entry;

    pthread_mutex_unlock(&log_manager->mutex);

    // External logging system integration can be added here
}
