} UserProfile;

UserProfile* profilesHead = NULL;
int totalProfiles = 0;
const int MAX_PROFILES = 1000; // Example limit

void addProfile(const char* username, const char* email, const char* phone) {
    if (totalProfiles >= MAX_PROFILES) {
        fprintf(stderr, "Maximum profile count exceeded.\n");
        return;
    }

    UserProfile* newProfile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!newProfile) {
        perror("Failed to allocate memory for new profile.");
        return;
    }

    strncpy(newProfile->username, username, MAX_USERNAME);
    strncpy(newProfile->email, email, MAX_EMAIL);
    strncpy(newProfile->phone, phone, MAX_PHONE);

    newProfile->activityLogs = NULL;
    newProfile->preferences = NULL;
    newProfile->next = profilesHead;
    profilesHead = newProfile;

    totalProfiles++;
}

void freeActivityLog(ActivityLog* log) {
    if (log) {
        freeActivityLog(log->next);
        free(log);
    }
}

void freePreferenceSettings(PreferenceSettings* setting) {
    if (setting) {
        freePreferenceSettings(setting->next);
        free(setting);
    }
}

void freeProfiles() {
    UserProfile* current = profilesHead;
    while (current) {
        UserProfile* next = current->next;
        freeActivityLog(current->activityLogs);
        freePreferenceSettings(current->preferences);
        free(current);
        current = next;
    }
    totalProfiles = 0;
}

