// Main function to construct and manage the linked list
Node* construct_nfa_list(int N, RX_UE_INFORMATION_TAG* rx_ue_info_tag) {
    Node *head = NULL;
    Node *current = NULL;

    initialize_rnti_pool();

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&list_mutex);

        NFAPI_CRC_INDICATION_PDU_T pdu = generate_pdu(rx_ue_info_tag);

        // Allocate memory for new node
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list_mutex);
            log_error("Memory allocation failed");
            break;
        }

        newNode->data = pdu;
        newNode->next = NULL;

        if (!head) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

