#include <shared_mutex>
#include <thread>
#include <chrono>
#include <algorithm>

// Mock external inventory management API and message broker service.
namespace InventoryAPI {
    struct ProductInventory {
        int productId;
        std::string name;
        std::string category;
        int stockQuantity;
        double price;
        std::time_t lastPurchaseDate;

        ProductInventory(int id, const std::string& n, const std::string& cat, 
                         int stock, double p, std::time_t date)
            : productId(id), name(n), category(cat), stockQuantity(stock), 
              price(p), lastPurchaseDate(date) {}
    };

    void fetchRealTimeStockUpdates(std::vector<ProductInventory>& products);
}

// Mock message broker service
namespace MessageBroker {
    void notifyRetailers(int productId, const InventoryAPI::ProductInventory& product);
}

class ProductCache {
public:
    using CacheItem = std::pair<int, InventoryAPI::ProductInventory>;
    using LRUCacheMap = std::unordered_map<int, typename std::list<CacheItem>::iterator>;

private:
    std::list<CacheItem> itemList;
    LRUCacheMap cacheMap;
    size_t capacity;

public:
    explicit ProductCache(size_t maxCapacity) : capacity(maxCapacity) {}

    bool get(int productId, InventoryAPI::ProductInventory& product);
    void put(const CacheItem& item);

private:
    void evictIfNeeded();
};

bool ProductCache::get(int productId, InventoryAPI::ProductInventory& product) {
    std::shared_lock<std::shared_mutex> lock(mutex_);
    auto it = cacheMap.find(productId);
    if (it == cacheMap.end()) return false;

    itemList.splice(itemList.begin(), itemList, it->second);
    product = it->second->second;
    return true;
}

void ProductCache::put(const CacheItem& item) {
    std::unique_lock<std::shared_mutex> lock(mutex_);
    auto it = cacheMap.find(item.first);
    if (it != cacheMap.end()) {
        itemList.erase(it->second);
        cacheMap.erase(it);
    }

    itemList.push_front(item);
    cacheMap[item.first] = itemList.begin();
    evictIfNeeded();
}

void ProductCache::evictIfNeeded() {
    while (itemList.size() > capacity) {
        auto last = itemList.end(); --last;
        cacheMap.erase(last->first);
        itemList.pop_back();
    }
}

class InventoryManager {
private:
    std::unordered_map<int, InventoryAPI::ProductInventory> products_;
    ProductCache cache_;
    mutable std::shared_mutex rwMutex_;

public:
    explicit InventoryManager(size_t cacheSize) : cache_(cacheSize) {}

    void addProduct(const InventoryAPI::ProductInventory& product);
    bool updateProduct(int productId, const InventoryAPI::ProductInventory& updatedProduct);
    bool getProductById(int productId, InventoryAPI::ProductInventory& product);

    void reorderProductsBasedOnStock();

private:
    void fetchAndRefreshFromAPI();

public:
    static void logOperation(const std::string& operation, 
                             const InventoryAPI::ProductInventory& product) {
        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);
        std::cout << "[" << std::ctime(&time_t_now)
                  << "] " << operation << ": Product ID: " 
                  << product.productId << ", Name: " << product.name
                  << ", Stock: " << product.stockQuantity << std::endl;
    }
};

void InventoryManager::addProduct(const InventoryAPI::ProductInventory& product) {
    std::unique_lock<std::shared_mutex> lock(rwMutex_);
    products_[product.productId] = product;
    cache_.put({product.productId, product});

    logOperation("Added", product);
}

bool InventoryManager::updateProduct(int productId, const InventoryAPI::ProductInventory& updatedProduct) {
    std::unique_lock<std::shared_mutex> lock(rwMutex_);
    auto it = products_.find(productId);
    if (it == products_.end()) return false;

    it->second = updatedProduct;
    cache_.put({productId, updatedProduct});

    logOperation("Updated", updatedProduct);

    MessageBroker::notifyRetailers(productId, updatedProduct);

    return true;
}

bool InventoryManager::getProductById(int productId, InventoryAPI::ProductInventory& product) {
    if (cache_.get(productId, product)) return true;

    std::shared_lock<std::shared_mutex> lock(rwMutex_);
    auto it = products_.find(productId);
    if (it == products_.end()) return false;

    product = it->second;
    cache_.put({productId, product});
    return true;
}

void InventoryManager::reorderProductsBasedOnStock() {
    std::shared_lock<std::shared_mutex> lock(rwMutex_);
    fetchAndRefreshFromAPI();

    auto sortedIt = std::stable_sort(
        products_.begin(), products_.end(),
        [](const auto& a, const auto& b) {
            return a.second.stockQuantity < b.second.stockQuantity;
        });

    for (auto it = sortedIt; it != products_.end(); ++it) {
        logOperation("Reordered", it->second);
    }
}

void InventoryManager::fetchAndRefreshFromAPI() {
    InventoryAPI::fetchRealTimeStockUpdates(products_);
    for (const auto& [id, product] : products_) {
        cache_.put({id, product});
    }
}
