['Below is a C code implementing the specified functionality:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define INACTIVITY_TIMEOUT 300 // seconds

typedef struct Session {
    char sessionID[50];
    char clientIP[16];
    time_t lastActivity;
    int isActive;
} Session;

typedef struct {
    Session* sessions[MAX_SESSIONS];
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* createSessionManager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    memset(manager, 0, sizeof(SessionManager));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int addSession(SessionManager* manager, const char* sessionID, const char* clientIP) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory limit reached
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->sessionID, sessionID) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Session already exists
        }
    }

    Session* newSession = (Session*)malloc(sizeof(Session));
    strcpy(newSession->sessionID, sessionID);
    strcpy(newSession->clientIP, clientIP);
    time(&(newSession->lastActivity));
    newSession->isActive = 1;

    manager->sessions[manager->count++] = newSession;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void updateLastActivity(SessionManager* manager, const char* sessionID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->sessionID, sessionID) == 0) {
            time(&(manager->sessions[i]->lastActivity));
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void expireSessions(SessionManager* manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(now, manager->sessions[i]->lastActivity) > INACTIVITY_TIMEOUT && manager->sessions[i]->isActive) {
            manager->sessions[i]->isActive = 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void serializeSessions(const SessionManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        Session* session = manager->sessions[i];
        fwrite(sessionID, sizeof(char), strlen(sessionID)+1, file);
        fwrite(clientIP, sizeof(char), strlen(clientIP)+1, file);
        fwrite(&lastActivity, sizeof(time_t), 1, file);
        fwrite(&isActive, sizeof(int), 1, file);
    }

    fclose(file);
}

void deserializeSessions(SessionManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    fread(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        Session* session = (Session*)malloc(sizeof(Session));

        char buffer[50];
        size_t len;
        fread(buffer, sizeof(char), 50, file);
        len = strlen(buffer)+1;
        strncpy(sessionID, buffer, len);

        fread(buffer, sizeof(char), 16, file);
        len = strlen(buffer)+1;
        strncpy(clientIP, buffer, len);

        fread(&lastActivity, sizeof(time_t), 1, file);
        fread(&isActive, sizeof(int), 1, file);

        pthread_mutex_lock(&manager->lock);
        manager->sessions[i] = session;
        pthread_mutex_unlock(&manager->lock);
    }

    fclose(file);
}

Session* getSessionByID(SessionManager* manager, const char* sessionID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->sessionID, sessionID) == 0) {
            Session* foundSession = manager->sessions[i];
            pthread_mutex_unlock(&manager->lock);
            return foundSession;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

void freeSessionManager(SessionManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Key Points:
- **Concurrency**: The code uses a mutex to handle concurrent access, ensuring that operations on the session list are thread-safe.
- **Memory Management**: Allocates memory for each new session and tracks them within a fixed-size array. This prevents over-allocation beyond `MAX_SESSIONS`.
- **Session Expiry**: Regularly checks for inactive sessions and marks them as inactive based on inactivity timeout.
- **Serialization**: Provides serialization and deserialization mechanisms to save/load the session list from/to a file.
- **Session Lookup**: Implements efficient lookup by session ID using linear search, which could be optimized further with hash tables if necessary.']

['Below is a C implementation for a thread-safe key-value store that meets the specified requirements. This implementation uses a scalable hash table with dynamic resizing and employs mutexes for concurrency control.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    int key;
    long offset;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} KeyValueStore;

// Hash function
unsigned int hash(int key, size_t capacity) {
    return (key & 0x7FFFFFFF) % capacity;
}

// Initialize the key-value store
KeyValueStore* create_store() {
    KeyValueStore* store = (KeyValueStore*)malloc(sizeof(KeyValueStore));
    if (!store) {
        perror("Failed to allocate memory for store");
        exit(EXIT_FAILURE);
    }

    store->capacity = INITIAL_CAPACITY;
    store->size = 0;
    store->table = (Node**)calloc(store->capacity, sizeof(Node*));
    if (!store->table) {
        free(store);
        perror("Failed to allocate memory for table");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Resize the hash table
void resize(KeyValueStore* store);

// Insert a record into the key-value store
int insert_record(KeyValueStore* store, int key, long offset) {
    pthread_mutex_lock(&store->lock);

    if (store->size >= LOAD_FACTOR * store->capacity) {
        resize(store);
    }

    unsigned int index = hash(key, store->capacity);
    Node* node = store->table[index];

    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&store->lock);
            return 0; // Key already exists
        }
        node = node->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&store->lock);
        perror("Failed to allocate memory for new node");
        return -1;
    }

    new_node->key = key;
    new_node->offset = offset;
    new_node->next = store->table[index];
    store->table[index] = new_node;
    store->size++;

    pthread_mutex_unlock(&store->lock);
    return 1; // Record inserted
}

// Lookup a record by key
long lookup_record(KeyValueStore* store, int key) {
    pthread_mutex_lock(&store->lock);

    unsigned int index = hash(key, store->capacity);
    Node* node = store->table[index];

    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&store->lock);
            return node->offset;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&store->lock);
    return -1; // Key not found
}

// Delete a record by key
int delete_record(KeyValueStore* store, int key) {
    pthread_mutex_lock(&store->lock);

    unsigned int index = hash(key, store->capacity);
    Node *node = store->table[index], *prev = NULL;

    while (node) {
        if (node->key == key) {
            if (prev) {
                prev->next = node->next;
            } else {
                store->table[index] = node->next;
            }
            free(node);
            store->size--;
            pthread_mutex_unlock(&store->lock);
            return 1; // Record deleted
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&store->lock);
    return 0; // Key not found
}

// Resize the hash table when load factor is exceeded
void resize(KeyValueStore* store) {
    size_t new_capacity = store->capacity * 2;
    Node** new_table = (Node**)calloc(new_capacity, sizeof(Node*));
    if (!new_table) {
        perror("Failed to allocate memory for resized table");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < store->capacity; i++) {
        Node* node = store->table[i];
        while (node) {
            unsigned int new_index = hash(node->key, new_capacity);
            Node* next_node = node->next;

            node->next = new_table[new_index];
            new_table[new_index] = node;
            node = next_node;
        }
    }

    free(store->table);
    store->table = new_table;
    store->capacity = new_capacity;
}

// Free the key-value store
void destroy_store(KeyValueStore* store) {
    for (size_t i = 0; i < store->capacity; i++) {
        Node* node = store->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(store->table);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

// Example usage
int main() {
    KeyValueStore* store = create_store();

    insert_record(store, 1, 100);
    printf("Offset for key 1: %ld\n", lookup_record(store, 1));

    delete_record(store, 1);
    printf("Offset for key 1 after deletion: %ld\n", lookup_record(store, 1));

    destroy_store(store);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Resizing**: Automatically resizes the hash table when the load factor exceeds a threshold.
- **Memory Management**: Allocates and deallocates memory efficiently, with error handling for allocation failures.
- **Concurrency Considerations**: Locks are used to manage concurrent access, minimizing contention by resizing only when necessary.
- **Error Handling**: Gracefully handles allocation errors and invalid inputs.
- **Duplicate Key Handling**: Overwrites existing records or rejects new entries based on implementation choice (here it rejects).

This code provides a robust foundation for managing key-value pairs in a multithreaded environment.']

