DataPipeline* create_pipeline(size_t max_records) {
    DataPipeline* pipeline = (DataPipeline*)malloc(sizeof(DataPipeline));
    if (!pipeline) return NULL;

    pipeline->offsets = (long*)calloc(max_records, sizeof(long));
    pipeline->keys = (int*)calloc(max_records, sizeof(int));
    pipeline->records = (Record*)calloc(max_records, sizeof(Record));
    pipeline->metadata_tags = (Metadata*)calloc(max_records, sizeof(Metadata));
    pipeline->allocated_records = 0;

    if (!pipeline->offsets || !pipeline->keys || !pipeline->records || !pipeline->metadata_tags) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline->metadata_tags);
        free(pipeline);
        return NULL;
    }

    pthread_mutex_init(&pipeline->lock, NULL);
    return pipeline;
}

void destroy_pipeline(DataPipeline* pipeline) {
    if (pipeline) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline->metadata_tags);
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline);
    }
}

int add_record(DataPipeline* pipeline, int key, const char* charset, size_t charset_len) {
    if (!pipeline || pipeline->allocated_records >= MAX_RECORDS)
        return -1;

    pthread_mutex_lock(&pipeline->lock);

    // Memory usage check (simplified for demonstration purposes)
    size_t memory_usage = sizeof(long) * MAX_RECORDS + 
                          sizeof(int) * MAX_RECORDS +
                          sizeof(Record) * pipeline->allocated_records +
                          sizeof(Metadata) * pipeline->allocated_records;

    if (memory_usage >= MEMORY_LIMIT) {
        pthread_mutex_unlock(&pipeline->lock);
        return -1;
    }

    int index = pipeline->allocated_records++;
    pipeline->keys[index] = key;

    // Randomly generate buffer content
    for (size_t i = 0; i < CHAR_BUFFER_SIZE - 1; ++i) {
        pipeline->records[index].buffer[i] = charset[rand() % charset_len];
    }
    pipeline->records[index].buffer[CHAR_BUFFER_SIZE - 1] = '\0';

    // Metadata setup
    time(&pipeline->metadata_tags[index].creation_timestamp);
    pipeline->metadata_tags[index].update_frequency = MIN_UPDATE_FREQUENCY;

    pthread_mutex_unlock(&pipeline->lock);
    return index;
}

int update_record(DataPipeline* pipeline, size_t record_index, int new_value) {
    if (!pipeline || record_index >= pipeline->allocated_records)
        return -1;

    Metadata* metadata = &pipeline->metadata_tags[record_index];
    time_t current_time;
    time(&current_time);

    if (difftime(current_time, metadata->creation_timestamp) < MIN_UPDATE_FREQUENCY) {
        return -2; // Update frequency constraint not met
    }

    pthread_mutex_lock(&pipeline->lock);
    pipeline->records[record_index].value = new_value;
    metadata->creation_timestamp = current_time; // Reset timestamp on update

    pthread_mutex_unlock(&pipeline->lock);
    return 0;
}

int serialize_pipeline(DataPipeline* pipeline, const char* filename) {
    if (!pipeline || !filename)
        return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&(pipeline->allocated_records), sizeof(size_t), 1, file);
    fwrite(pipeline->offsets, sizeof(long), MAX_RECORDS, file);
    fwrite(pipeline->keys, sizeof(int), MAX_RECORDS, file);
    fwrite(pipeline->records, sizeof(Record), pipeline->allocated_records, file);
    fwrite(pipeline->metadata_tags, sizeof(Metadata), pipeline->allocated_records, file);

    fclose(file);
    return 0;
}

int deserialize_pipeline(DataPipeline* pipeline, const char* filename) {
    if (!pipeline || !filename)
        return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t loaded_records;
    fread(&loaded_records, sizeof(size_t), 1, file);

    // Ensure we don't load more records than the pipeline can hold
    if (loaded_records > MAX_RECORDS)
        return -2;

    fread(pipeline->offsets, sizeof(long), MAX_RECORDS, file);
    fread(pipeline->keys, sizeof(int), MAX_RECORDS, file);
    fread(pipeline->records, sizeof(Record), loaded_records, file);
    fread(pipeline->metadata_tags, sizeof(Metadata), loaded_records, file);

    pipeline->allocated_records = loaded_records;

    fclose(file);
    return 0;
}

