#define METADATA_SIZE 256
#define MAX_SENSOR_VALUE 100

typedef struct {
    long offset;
    int key;
    int sensor_value;
    char metadata[METADATA_SIZE];
} SensorRecord;

void generate_random_metadata(char *buffer, size_t buffer_size) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (buffer == NULL || buffer_size == 0)
        return;

    for (size_t i = 0; i < buffer_size - 1; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        buffer[i] = charset[key];
    }
    buffer[buffer_size - 1] = '\0';
}

SensorRecord* create_sensor_records(size_t record_count, size_t *allocated_size) {
    if (record_count == 0) return NULL;

    SensorRecord* records = malloc(record_count * sizeof(SensorRecord));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for sensor records.\n");
        exit(EXIT_FAILURE);
    }

    *allocated_size = record_count;
    srand(time(NULL));

    for (size_t i = 0; i < record_count; ++i) {
        records[i].offset = rand() % 10000; // Example offset generation
        records[i].key = rand() % 100;      // Example key generation
        records[i].sensor_value = rand() % MAX_SENSOR_VALUE + 1;
        generate_random_metadata(records[i].metadata, METADATA_SIZE);
    }

    return records;
}

void free_sensor_records(SensorRecord *records) {
    if (records)
        free(records);
}

int main() {
    size_t record_count;
    printf("Enter the number of sensor records to create: ");
    scanf("%zu", &record_count);

    if (record_count == 0) {
        fprintf(stderr, "Error: Record count must be greater than zero.\n");
        return EXIT_FAILURE;
    }

    size_t allocated_size = 0;
    SensorRecord *records = create_sensor_records(record_count, &allocated_size);
    if (!records)
        return EXIT_FAILURE;

    // Example usage
    for (size_t i = 0; i < allocated_size; ++i) {
        printf("Offset: %ld, Key: %d, Value: %d, Metadata: %s\n",
               records[i].offset, records[i].key,
               records[i].sensor_value, records[i].metadata);
    }

    free_sensor_records(records);
    return EXIT_SUCCESS;
}
