// Definition of event struct
typedef struct Event {
    time_t timestamp;
    char description[256];
    struct Event* next;  // Linked list of related events
} Event;

// Definition of measurement struct
typedef struct Measurement {
    double value;
    int count;
    char *label;
    Event *related_event;
} Measurement;

// Logger function to track errors and memory allocations
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function prototypes
