int get_int_input();
char* get_char_pointer_input();
time_t get_timestamp();
void populate_measurements(Measurement **measurements, int count);

// Main function to manage dynamic memory allocation and initialization
void initialize_components(int measurement_count) {
    if (measurement_count <= 0) {
        log_error("Invalid number of measurements.");
        return;
    }

    // Dynamic memory allocation for each component
    double *doubles = (double *)malloc(measurement_count * sizeof(double));
    char *chars = (char *)malloc(measurement_count * sizeof(char));
    Measurement **measurements = (Measurement **)malloc(measurement_count * sizeof(Measurement *));
    Event **events = (Event **)malloc(measurement_count * sizeof(Event *));

    if (!doubles || !chars || !measurements || !events) {
        log_error("Memory allocation failed.");
        free(doubles);
        free(chars);
        free(measurements);
        free(events);
        return;
    }

    // Initialize doubles, chars and populate measurements
    for (int i = 0; i < measurement_count; ++i) {
        doubles[i] = get_double_input();
        chars[i] = get_char_pointer_input()[0];

        measurements[i] = (Measurement *)malloc(sizeof(Measurement));
        events[i] = (Event *)malloc(sizeof(Event));

        if (!measurements[i] || !events[i]) {
            log_error("Memory allocation for measurement or event failed.");
            free(doubles);
            free(chars);
            free(measurements);
            free(events);

            // Free any previously allocated memory
            for (int j = 0; j < i; ++j) {
                if (measurements[j]) free(measurements[j]);
                if (events[j]) free(events[j]);
            }

            return;
        }

        events[i]->timestamp = get_timestamp();
        strcpy(events[i]->description, "Sample Event Description");
        events[i]->next = NULL;

        measurements[i]->value = doubles[i];
        measurements[i]->count = get_int_input();
        measurements[i]->label = &chars[i];  // Pointer to single char
        measurements[i]->related_event = events[i];
    }

    populate_measurements(measurements, measurement_count);

    // Logging successful initialization
    printf("Components initialized successfully.\n");

    // Free allocated memory (for demonstration purposes)
    for (int i = 0; i < measurement_count; ++i) {
        free(measurements[i]);
        free(events[i]);
    }
    free(doubles);
    free(chars);
    free(measurements);
    free(events);
}

// Helper functions
double get_double_input() {
    double input;
    printf("Enter a double value: ");
    if (scanf("%lf", &input) != 1) {
        log_error("Failed to read double value.");
        exit(EXIT_FAILURE);
    }
    return input;
}

int get_int_input() {
    int input;
    printf("Enter an integer count: ");
    if (scanf("%d", &input) != 1) {
        log_error("Failed to read integer value.");
        exit(EXIT_FAILURE);
    }
    return input;
}

char* get_char_pointer_input() {
    char buffer[256];
    printf("Enter a character for label: ");
    if (scanf("%s", buffer) != 1 || strlen(buffer) == 0) {
        log_error("Failed to read character.");
        exit(EXIT_FAILURE);
    }
    return strdup(buffer); // Duplicate string for safety
}

time_t get_timestamp() {
    time_t now = time(NULL);
    if (now == ((time_t)-1)) {
        log_error("Failed to retrieve current timestamp.");
        exit(EXIT_FAILURE);
    }
    return now;
}

void populate_measurements(Measurement **measurements, int count) {
    for (int i = 0; i < count; ++i) {
        // Simulate population with user input
        printf("Populating measurement %d\n", i + 1);

        measurements[i]->value *= 2.0; // Example modification
        measurements[i]->count += 10; // Example increment

        if (measurements[i]->label && *measurements[i]->label) {
            (*measurements[i]->label) = toupper(*measurements[i]->label); // Capitalize label character
        }
    }
}

// Main entry point for testing purposes
int main() {
    int num_measurements;
    printf("Enter number of measurements to initialize: ");
    if (scanf("%d", &num_measurements) != 1 || num_measurements <= 0) {
        log_error("Invalid input for number of measurements.");
        return EXIT_FAILURE;
    }

    initialize_components(num_measurements);
    return EXIT_SUCCESS;
}
