['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    int id;
    time_t timestamp;
    int status; // 0 for inactive, 1 for active
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    unsigned long expiration_threshold;
    const char *log_file_path;
    int log_level;
} PacketManager;

// Forward declarations
static void* purge_expired_packets(void *arg);
static void load_from_file(PacketManager *pm, const char *file_path);
static void save_to_file(PacketManager *pm, const char *file_path);

PacketManager* init_packet_manager(unsigned long expiration_threshold, const char *log_file_path, int log_level) {
    PacketManager *pm = malloc(sizeof(PacketManager));
    if (!pm) return NULL;

    pm->count = 0;
    pthread_mutex_init(&pm->lock, NULL);
    pthread_cond_init(&pm->cond, NULL);
    pm->expiration_threshold = expiration_threshold;
    pm->log_file_path = log_file_path;
    pm->log_level = log_level;

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        pm->packets[i] = NULL;
    }

    pthread_t purge_thread;
    if (pthread_create(&purge_thread, NULL, purge_expired_packets, pm)) {
        free(pm);
        return NULL;
    }

    return pm;
}

int add_packet(PacketManager *pm, int id, time_t timestamp, int status) {
    pthread_mutex_lock(&pm->lock);

    while (pm->count >= MAX_PACKETS) {
        pthread_cond_wait(&pm->cond, &pm->lock);
    }

    DataPacket *packet = malloc(sizeof(DataPacket));
    if (!packet) {
        pthread_mutex_unlock(&pm->lock);
        return -1;
    }

    packet->id = id;
    packet->timestamp = timestamp;
    packet->status = status;

    pm->packets[pm->count++] = packet;

    pthread_mutex_unlock(&pm->lock);

    // Log addition
    if (pm->log_level >= LOG_LEVEL_INFO) {
        FILE *log_file = fopen(pm->log_file_path, "a");
        if (log_file) {
            fprintf(log_file, "Packet added: ID=%d\n", id);
            fclose(log_file);
        }
    }

    return 0;
}

int update_packet(PacketManager *pm, int id, time_t timestamp, int status) {
    pthread_mutex_lock(&pm->lock);

    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i] && pm->packets[i]->id == id) {
            pm->packets[i]->timestamp = timestamp;
            pm->packets[i]->status = status;

            pthread_mutex_unlock(&pm->lock);

            // Log update
            if (pm->log_level >= LOG_LEVEL_INFO) {
                FILE *log_file = fopen(pm->log_file_path, "a");
                if (log_file) {
                    fprintf(log_file, "Packet updated: ID=%d\n", id);
                    fclose(log_file);
                }
            }

            return 0;
        }
    }

    pthread_mutex_unlock(&pm->lock);

    // Log failure to update
    if (pm->log_level >= LOG_LEVEL_ERROR) {
        FILE *log_file = fopen(pm->log_file_path, "a");
        if (log_file) {
            fprintf(log_file, "Packet update failed: ID=%d\n", id);
            fclose(log_file);
        }
    }

    return -1;
}

DataPacket* get_packet(PacketManager *pm, int id) {
    pthread_mutex_lock(&pm->lock);

    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i] && pm->packets[i]->id == id) {
            DataPacket *packet = pm->packets[i];
            pthread_mutex_unlock(&pm->lock);
            return packet;
        }
    }

    pthread_mutex_unlock(&pm->lock);

    return NULL;
}

static void* purge_expired_packets(void *arg) {
    PacketManager *pm = (PacketManager *)arg;

    while (1) {
        sleep(60); // Run every minute

        time_t now = time(NULL);
        pthread_mutex_lock(&pm->lock);

        for (size_t i = 0; i < pm->count;) {
            if (pm->packets[i] && (now - pm->packets[i]->timestamp) > pm->expiration_threshold) {
                free(pm->packets[i]);
                pm->packets[i] = pm->packets[--pm->count];

                // Log purge
                if (pm->log_level >= LOG_LEVEL_INFO) {
                    FILE *log_file = fopen(pm->log_file_path, "a");
                    if (log_file) {
                        fprintf(log_file, "Packet purged: ID=%d\n", pm->packets[i]->id);
                        fclose(log_file);
                    }
                }
            } else {
                ++i;
            }
        }

        pthread_cond_broadcast(&pm->cond);
        pthread_mutex_unlock(&pm->lock);
    }

    return NULL;
}

void save_to_file(PacketManager *pm, const char *file_path) {
    FILE *file = fopen(file_path, "w");
    if (!file) return;

    for (size_t i = 0; i < pm->count; ++i) {
        fprintf(file, "%d %ld %d\n", pm->packets[i]->id, pm->packets[i]->timestamp, pm->packets[i]->status);
    }

    fclose(file);
}

void load_from_file(PacketManager *pm, const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return;

    while (fscanf(file, "%d %ld %d", &id, &timestamp, &status) == 3) {
        add_packet(pm, id, timestamp, status);
    }

    fclose(file);
}

void cleanup(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);

    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i]) {
            free(pm->packets[i]);
        }
    }

    pthread_mutex_unlock(&pm->lock);
    pthread_mutex_destroy(&pm->lock);
    pthread_cond_destroy(&pm->cond);

    save_to_file(pm, "backup.dat");
    free(pm);
}

int main() {
    PacketManager *pm = init_packet_manager(3600, "packet_log.txt", LOG_LEVEL_INFO);
    if (!pm) return EXIT_FAILURE;

    add_packet(pm, 1, time(NULL), 1);
    update_packet(pm, 1, time(NULL), 0);

    DataPacket *dp = get_packet(pm, 1);
    if (dp) {
        printf("Packet ID: %d\n", dp->id);
    }

    load_from_file(pm, "backup.dat");
    save_to_file(pm, "current_backup.dat");

    cleanup(pm);

    return EXIT_SUCCESS;
}
```

