['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
    int index;
    char *label;
} Measurement;

typedef struct Record {
    int key;
    long offset;
    double weight;
    char identifier;
    float score;
    struct Record *next;
} Record;

typedef struct {
    Record **buckets;
    size_t capacity;
    pthread_mutex_t *locks;
} HashTable;

static inline unsigned int hash_function(int key, size_t capacity) {
    return key % capacity;
}

void init_random_seed(unsigned long seed) {
    srand(seed);
}

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->buckets = calloc(capacity, sizeof(Record *));
    table->locks = calloc(capacity, sizeof(pthread_mutex_t));

    for (size_t i = 0; i < capacity; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *entry = table->buckets[i];
        while (entry != NULL) {
            Record *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    pthread_mutex_destroy(&table->locks[0]);
    for (size_t i = 1; i < table->capacity; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table->buckets);
    free(table->locks);
    free(table);
}

void insert_record(HashTable *table, int key, long offset_range, double weight_range, char identifier, float score) {
    size_t index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->locks[index]);

    Record *entry = malloc(sizeof(Record));
    entry->key = key;
    entry->offset = rand() % offset_range;
    entry->weight = ((double)rand() / RAND_MAX) * weight_range;
    entry->identifier = identifier;
    entry->score = score;

    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    pthread_mutex_unlock(&table->locks[index]);
}

Record* find_record(HashTable *table, int key) {
    size_t index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->locks[index]);

    Record *entry = table->buckets[index];
    while (entry != NULL) {
        if (entry->key == key) {
            pthread_mutex_unlock(&table->locks[index]);
            return entry;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

Measurement* create_measurement(double value, int index, const char *label) {
    Measurement *m = malloc(sizeof(Measurement));
    m->value = value;
    m->index = index;
    if (label != NULL) {
        m->label = strdup(label);
    } else {
        m->label = NULL;
    }
    return m;
}

void free_measurement(Measurement *measurement) {
    if (measurement->label != NULL) {
        free(measurement->label);
    }
    free(measurement);
}
```

This code defines a C library for managing dynamic memory allocation and a concurrent hash table. The library supports arrays of `double`, `char`, and custom `Measurement` structs, as well as concurrent operations on a hash table designed to handle collisions using chaining.

- **Dynamic Memory Management**: Functions `create_measurement` and `free_measurement` manage dynamic allocation and deallocation for the `Measurement` struct.
- **Concurrent Hash Table**: The library includes functions for creating (`create_hash_table`) and freeing (`free_hash_table`) a concurrent hash table with separate locks per bucket to support multithreading. Records are inserted using `insert_record`, which allocates memory dynamically and uses a hash function to determine the bucket index.
- **Random Initialization**: A seed is optionally set for reproducibility in random number generation during record insertion (`init_random_seed`).

The library focuses on performance, minimizing unnecessary allocations, and ensuring thread safety through careful synchronization.']

