    int max_retries = 5;
    int delay = 1000;  // Initial delay in milliseconds

    while (retries < max_retries) {
        if (func("api_key", "username", "password")) {
            return;
        }
        usleep(delay * 1000);
        delay *= 2;  // Exponential backoff
        retries++;
