public class Entry
{
    public char[] Key { get; set; }
    public long Value { get; set; }
    private float[] _floatArray;
    private readonly int _maxSize;

    public Entry(int maxSize)
    {
        _maxSize = maxSize;
        _floatArray = new float[_maxSize];
    }

    public void PopulateWithGaussian(float mean, float stdDev)
    {
        Random rand = new Random();

        for (int i = 0; i < _floatArray.Length; i++)
        {
            // Box-Muller transform
            double u1 = rand.NextDouble(); 
            double u2 = rand.NextDouble();

            var r = Math.Sqrt(-2.0 * Math.Log(u1));
            var theta = 2.0 * Math.PI * u2;

            _floatArray[i] = (float)(mean + stdDev * r * Math.Sin(theta));
        }
    }

    public void ResizeIfNeeded(int newSize)
    {
        if (newSize <= _maxSize) return;

        float[] newArray = new float[newSize];
        Array.Copy(_floatArray, newArray, _floatArray.Length);
        _floatArray = newArray;
    }
}

