#include <stdio.h>
#include <stdlib.h>
import random

#define INITIAL_RECORD_CAPACITY 10

typedef struct {
    int value;
} record_t;

typedef struct {
    long* offset_values;
    int* keys;
    record_t* records;
    size_t capacity;
    size_t count;
} memory_pool_t;

typedef struct {
    size_t total_allocations;
    size_t successful_allocations;
    size_t errors;
} status_t;

// Function to initialize the memory pool
memory_pool_t* init_memory_pool(size_t num_offsets, size_t num_keys) {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->offset_values = (long*)calloc(num_offsets, sizeof(long));
    pool->keys = (int*)calloc(num_keys, sizeof(int));

    if (!pool->offset_values || !pool->keys) {
        free(pool->offset_values);
        free(pool->keys);
        free(pool);
        return NULL;
    }

    pool->records = (record_t*)malloc(INITIAL_RECORD_CAPACITY * sizeof(record_t));
    if (!pool->records) {
        free(pool->offset_values);
        free(pool->keys);
        free(pool);
        return NULL;
    }

    pool->capacity = INITIAL_RECORD_CAPACITY;
    pool->count = 0;

    return pool;
}

// Function to resize records array
int resize_records(memory_pool_t* pool, size_t new_capacity) {
    record_t* resized_array = (record_t*)realloc(pool->records, new_capacity * sizeof(record_t));
    if (!resized_array) return -1;

    pool->records = resized_array;
    pool->capacity = new_capacity;

    return 0; // Success
}

// Function to add a random record and ensure no duplicate values
int add_record(memory_pool_t* pool, int min_value, int max_value, status_t* status) {
    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        if (resize_records(pool, new_capacity) != 0) {
            status->errors++;
            return -1; // Resizing failed
        }
    }

    int value;
    do {
        value = random.randint(min_value, max_value);
    } while (contains_value(pool->records, pool->count, value));

    record_t new_record = { .value = value };
    pool->records[pool->count] = new_record;
    pool->count++;
    status->successful_allocations++;

    return 0; // Success
}

// Function to check if the records array contains a specific value
int contains_value(record_t* records, size_t count, int value) {
    for (size_t i = 0; i < count; i++) {
        if (records[i].value == value) {
            return 1;
        }
    }
    return 0;
}

// Function to validate memory integrity
int validate_memory(memory_pool_t* pool, status_t* status) {
    // Simple validation: Check for null pointers and count consistency
    if (!pool || !pool->offset_values || !pool->keys || !pool->records) {
        status->errors++;
        return -1; // Integrity check failed
    }

    if (pool->count > pool->capacity) {
        status->errors++;
        return -1; // Count exceeds capacity
    }

    return 0; // Integrity check passed
}

// Function to free the memory pool
void free_memory_pool(memory_pool_t* pool, status_t* status) {
    if (pool) {
        free(pool->offset_values);
        free(pool->keys);
        free(pool->records);
        free(pool);

        // Track allocation of freeing itself
        status->successful_allocations++;
    }
}

// Example usage function
void example_usage() {
    memory_pool_t* pool = init_memory_pool(100, 50);
    if (!pool) {
        printf("Memory initialization failed.\n");
        return;
    }

    status_t status = { .total_allocations = 0, .successful_allocations = 0, .errors = 0 };

    for (int i = 0; i < 20; ++i) {
        if (add_record(pool, 1, 100, &status) != 0) {
            printf("Failed to add record.\n");
        }
    }

    if (validate_memory(pool, &status) == 0) {
        printf("Memory integrity validated successfully.\n");
    } else {
        printf("Memory integrity validation failed.\n");
    }

    free_memory_pool(pool, &status);
}

int main() {
    example_usage();
    return 0;
}
