#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkNode {
    int id;
    char **peers;
    size_t peer_count;
    int status; // 0: inactive, 1: active
    time_t last_active;
} NetworkNode;

typedef struct ListNode {
    NetworkNode *node;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} NetworkList;

NetworkList* create_network_list() {
    NetworkList *list = (NetworkList*)malloc(sizeof(NetworkList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node_peers(char **peers) {
    for (size_t i = 0; peers && i < peer_count; ++i) {
        free(peers[i]);
    }
    free(peers);
}

void add_network_node(NetworkList *list, int id, char **initial_peers, size_t peer_count, int status) {
    pthread_mutex_lock(&list->lock);

    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    NetworkNode *network_node = (NetworkNode*)malloc(sizeof(NetworkNode));

    network_node->id = id;
    network_node->peer_count = peer_count;
    network_node->peers = malloc(peer_count * sizeof(char*));
    memcpy(network_node->peers, initial_peers, peer_count * sizeof(char*));
    network_node->status = status;
    network_node->last_active = time(NULL);

    new_node->node = network_node;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void update_connections(NetworkList *list, int id, char **new_peers, size_t peer_count) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current) {
        if (current->node->id == id) {
            free_node_peers(current->node->peers);
            current->node->peer_count = peer_count;
            current->node->peers = malloc(peer_count * sizeof(char*));
            memcpy(current->node->peers, new_peers, peer_count * sizeof(char*));
            current->node->last_active = time(NULL); // Assume update means active
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

NetworkNode* get_node_by_id(NetworkList *list, int id) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current) {
        if (current->node->id == id) {
            current->node->last_active = time(NULL); // Update last active
            pthread_mutex_unlock(&list->lock);
            return current->node;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void disconnect_inactive_nodes(NetworkList *list, int inactivity_threshold_seconds) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    ListNode *prev = NULL;

    while (current) {
        if ((now - current->node->last_active) > inactivity_threshold_seconds && current->node->status == 1) {
            prev = current;
            current = current->next;
            free_node_peers(prev->node->peers);
            free(prev->node);

            if (prev == list->head) {
                list->head = current;
            } else {
                prev->next = current;
            }

            free(prev); // Free the ListNode
        } else {
            current->node->last_active = now; // Update last active for remaining nodes
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_network_list(NetworkList *list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;

    while (current) {
        ListNode *temp = current;
        current = current->next;
        free_node_peers(temp->node->peers);
        free(temp->node);
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
