                                             int versionNumber)
    {
        try
        {
            ValidateInput(pageSectionId, elementId, htmlContent, versionNumber);

            // Construct cache key
            var cacheKey = $"{pageSectionId}:{elementId}:{versionNumber}";

            if (!_cache.TryGetValue(cacheKey, out string cachedHtml))
            {
                using (_dataLockService.Lock(elementId))
                {
                    await FetchAndUpdateElementAsync(pageSectionId, elementId, htmlContent, versionNumber);

                    // Update cache
                    _cache.Set(cacheKey, htmlContent, TimeSpan.FromMinutes(10));
