#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    float timestamp;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

int load_records(const char *filename, RecordCollection *collection) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file '%s'\n", filename);
        return -1;
    }

    size_t n;
    fread(&n, sizeof(size_t), 1, file);

    if (n < 10 || n > 10000) {
        fprintf(stderr, "Error: Invalid number of records in file\n");
        fclose(file);
        return -2;
    }

    collection->capacity = n;
    pthread_mutex_init(&collection->lock, NULL);

    collection->records = malloc(n * sizeof(Record));
    if (!collection->records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(file);
        return -3;
    }

    size_t read_count = fread(collection->records, sizeof(Record), n, file);
    if (ferror(file)) {
        fprintf(stderr, "Error: Error reading from file '%s'\n", filename);
        free(collection->records);
        collection->records = NULL;
        pthread_mutex_destroy(&collection->lock);
        fclose(file);
        return -4;
    }

    // Handle partial reads
    if (read_count < n) {
        fprintf(stderr, "Warning: Only %zu out of %zu records were read\n", read_count, n);
    }

    collection->count = read_count;
    fclose(file);

    return 0; // Success
}

void free_records(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    if (collection->records) {
        free(collection->records);
        collection->records = NULL;
    }
    collection->capacity = 0;
    collection->count = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    const char *filename = "data.bin";
    RecordCollection collection;

    int status = load_records(filename, &collection);

    if (status == 0) {
        printf("Successfully loaded %zu records.\n", collection.count);
    } else {
        fprintf(stderr, "Failed to load records with error code: %d\n", status);
    }

    free_records(&collection);

    return status;
}
```

### Key Points:
- **Error Handling**: The function checks for file opening errors, memory allocation failures, and read errors.
- **Thread Safety**: A mutex is used to ensure thread-safe operations on the `RecordCollection`.
- **Memory Management**: Memory is dynamically allocated based on the number of records specified in the file. It's freed upon completion to prevent leaks.
- **Partial Reads**: The function handles cases where not all expected data is read from the file, logging a warning instead of failing outright.
- **Boundary Checks**: Ensures `n` (number of records) is within the specified range before proceeding with memory allocation and reading.']

