#include <shared_mutex>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <memory>
#include <json/json.h> // Assume JsonCpp or similar library for JSON handling

// Base class for jsonifiable records
class Jsonifiable {
public:
    virtual ~Jsonifiable() = default;
    virtual std::string serialize() const = 0;
    virtual void deserialize(const std::string& data) = 0;
};

// Concrete record type
class Record : public Jsonifiable {
private:
    long offset;
    int key;
    int value;

public:
    Record(long offset, int key, int value)
        : offset(offset), key(key), value(value) {}

    long getOffset() const { return offset; }
    int getKey() const { return key; }

    std::string serialize() const override {
        Json::Value root;
        root["offset"] = offset;
        root["key"] = key;
        root["value"] = value;
        Json::StreamWriterBuilder writer;
        return Json::writeString(writer, root);
    }

    void deserialize(const std::string& data) override {
        Json::CharReaderBuilder reader;
        Json::Value root;
        std::unique_ptr<Json::CharReader> const jsonReader(reader.newCharReader());
        if (!jsonReader->parse(data.c_str(), data.c_str() + data.size(), &root, nullptr)) {
            throw std::runtime_error("Invalid JSON format");
        }
        offset = root["offset"].asInt64();
        key = root["key"].asInt();
        value = root["value"].asInt();
    }
};

// Registry for factory functions
using FactoryFunction = std::function<std::unique_ptr<Jsonifiable>(long, int, int)>;

class RecordFactory {
private:
    std::unordered_map<std::string, FactoryFunction> factories;
    mutable std::shared_mutex mutex_;

public:
    void registerFactory(const std::string& type, FactoryFunction factory) {
        std::unique_lock lock(mutex_);
        factories[type] = std::move(factory);
    }

    std::unique_ptr<Jsonifiable> createRecord(const std::string& type, long offset, int key, int value) const {
        std::shared_lock lock(mutex_);
        auto it = factories.find(type);
        if (it != factories.end()) {
            return it->second(offset, key, value);
        }
        throw std::runtime_error("Unsupported record type");
    }
};

// Thread-safe dynamic list of records
class RecordManager {
private:
    std::unordered_map<int, std::shared_ptr<Record>> records;
    mutable std::shared_mutex mutex_;
    size_t upper_limit_;

public:
    explicit RecordManager(size_t upper_limit) : upper_limit_(upper_limit) {}

    void addRecord(std::shared_ptr<Record> record) {
        if (records.size() >= upper_limit_) throw std::runtime_error("Upper limit reached");
        std::unique_lock lock(mutex_);
        records[record->getKey()] = record;
    }

    bool removeRecord(int key) {
        std::unique_lock lock(mutex_);
        return records.erase(key) > 0;
    }

    std::shared_ptr<Record> queryByKey(int key) const {
        std::shared_lock lock(mutex_);
        auto it = records.find(key);
        if (it != records.end()) {
            return it->second;
        }
        return nullptr;
    }

    std::vector<std::shared_ptr<Record>> queryByOffset(long offset) const {
        std::shared_lock lock(mutex_);
        std::vector<std::shared_ptr<Record>> result;
        for (const auto& [key, record] : records) {
            if (record->getOffset() == offset) {
                result.push_back(record);
            }
        }
        return result;
    }

    size_t getActiveRecordsCount() const {
        std::shared_lock lock(mutex_);
        return records.size();
    }
};

// Packet task example for priority-based handling
struct PacketTask {
    int id;
    int priority;
    // Additional packet details...

    bool operator<(const PacketTask& other) const {
        return priority < other.priority;  // Higher numbers indicate higher priority
    }
};

class TaskManager {
private:
    std::vector<PacketTask> tasks;
    mutable std::mutex mutex_;

public:
    void addTask(const PacketTask& task) {
        std::lock_guard lock(mutex_);
        tasks.push_back(task);
        std::sort(tasks.begin(), tasks.end());
    }

    bool removeTask(int id) {
        std::lock_guard lock(mutex_);
        auto it = std::remove_if(tasks.begin(), tasks.end(),
                                 [id](const PacketTask& task) { return task.id == id; });
        if (it != tasks.end()) {
            tasks.erase(it, tasks.end());
            return true;
        }
        return false;
    }

    void executeTasks() {
        std::lock_guard lock(mutex_);
        for (auto& task : tasks) {
            // Process each task
        }
        tasks.clear();
    }
};

// Integration tests can be added as needed to simulate production environments

int main() {
    RecordFactory factoryRegistry;
    factoryRegistry.registerFactory("Record", [](long offset, int key, int value) -> std::unique_ptr<Jsonifiable> {
        return std::make_unique<Record>(offset, key, value);
    });

    RecordManager recordManager(1000); // Assume a limit of 1000 records
    auto record = factoryRegistry.createRecord("Record", 123456789L, 1, 42);
    recordManager.addRecord(record);

    TaskManager taskManager;
    taskManager.addTask({.id = 1, .priority = 10});
    taskManager.executeTasks();

    return 0;
}
```

This code provides a basic structure for managing JSONifiable records in a multi-threaded environment while ensuring thread safety and efficient operations. The `RecordManager` uses an unordered map with shared locking to allow concurrent reads. The `TaskManager` sorts tasks by priority, handling potential issues like duplicate IDs through careful management.

For integration with external data stores and more complex scenarios (like network packet loss detection), further customization will be necessary based on specific application requirements and environment constraints.']

