#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_ERROR_LOG_SIZE 1024

typedef struct {
    int value;
} record_t;

typedef struct {
    long* offsets;
    int* keys;
    record_t* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} memory_pool_t;

typedef struct {
    size_t total_allocations;
    size_t successful_allocations;
    size_t errors;
    float utilization;
} status_t;

void log_error(const char* message, size_t requested_size) {
    FILE* log_file = fopen("memory_errors.log", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] Error: %s Size: %zu\n", ctime(&now), message, requested_size);
        fclose(log_file);
    }
}

int validate_memory_pool(memory_pool_t* pool) {
    pthread_mutex_lock(&(pool->lock));
    int valid = (pool->offsets != NULL && pool->keys != NULL && pool->records != NULL);
    pthread_mutex_unlock(&(pool->lock));
    return valid;
}

void resize_records_array(memory_pool_t* pool, size_t new_capacity) {
    pthread_mutex_lock(&(pool->lock));

    record_t* new_records = realloc(pool->records, sizeof(record_t) * new_capacity);
    if (!new_records) {
        log_error("Failed to resize records array", sizeof(record_t) * new_capacity);
        pthread_mutex_unlock(&(pool->lock));
        return;
    }

    pool->capacity = new_capacity;
    memset(new_records + pool->size, 0, (new_capacity - pool->size) * sizeof(record_t));
    pool->records = new_records;

    pthread_mutex_unlock(&(pool->lock));
}

void initialize_memory_pool(memory_pool_t* pool, size_t initial_size) {
    pthread_mutex_init(&(pool->lock), NULL);
    pool->capacity = INITIAL_CAPACITY;
    pool->size = 0;

    pool->offsets = calloc(pool->capacity, sizeof(long));
    if (!pool->offsets) {
        log_error("Failed to allocate offsets", pool->capacity * sizeof(long));
        return;
    }

    pool->keys = calloc(pool->capacity, sizeof(int));
    if (!pool->keys) {
        free(pool->offsets);
        log_error("Failed to allocate keys", pool->capacity * sizeof(int));
        return;
    }

    pool->records = malloc(sizeof(record_t) * pool->capacity);
    if (!pool->records) {
        free(pool->offsets);
        free(pool->keys);
        log_error("Failed to allocate records", sizeof(record_t) * pool->capacity);
        return;
    }
}

void* export_to_csv(void* data, size_t size) {
    // Export logic here
    return NULL;  // Return the exported data
}

int main() {
    memory_pool_t pool;
    initialize_memory_pool(&pool, INITIAL_CAPACITY);

    if (!validate_memory_pool(&pool)) {
        fprintf(stderr, "Memory pool validation failed.\n");
        return EXIT_FAILURE;
    }

    size_t index = 0;

    while (index < pool.capacity) {
        resize_records_array(&pool, pool.capacity * 2);

        for (; index < pool.size; ++index) {
            srand(time(NULL) + rand());
            pool.records[index].value = rand() % 100;
        }

        if (index >= pool.capacity) {
            size_t new_size = pool.capacity > INITIAL_CAPACITY ? pool.capacity / 2 : INITIAL_CAPACITY;
            resize_records_array(&pool, new_size);
        }

        index++;
    }

    export_to_csv(pool.records, sizeof(record_t) * pool.size);

    free(pool.offsets);
    free(pool.keys);
    free(pool.records);

    pthread_mutex_destroy(&(pool.lock));

    return EXIT_SUCCESS;
}
```

