int populateRecords(Record records[], int recordCount, int minKey, int maxKey, long minOffset, long maxOffset) {
    srand(time(NULL));
    for (int i = 0; i < recordCount; i++) {
        int key, offset;
        do {
            key = rand() % (maxKey - minKey + 1) + minKey;
        } while (!isValidKey(records, i, key));

        do {
            offset = rand() % (long)(maxOffset - minOffset + 1) + minOffset;
        } while (!isValidOffset(records, i, offset));

        records[i].key = key;
        records[i].offset = offset;
    }
    return 0;
}

int isValidKey(Record records[], int currentIndex, int key) {
    for (int i = 0; i < currentIndex; i++) {
        if (records[i].key == key) {
            return 0;
        }
    }
    return 1;
}

int isValidOffset(Record records[], int currentIndex, long offset) {
    for (int i = 0; i < currentIndex; i++) {
        if (records[i].offset == offset) {
            return 0;
        }
    }
    return 1;
}

void populateDialogFields(DialogField fields[], int fieldCount, char* validNames[], int nameCount, Record records[]) {
    srand(time(NULL));

    for (int i = 0; i < fieldCount; i++) {
        if (!(fields[i] = malloc(sizeof(*fields) + strlen(validNames[rand() % nameCount]) + 1))) {
            perror("Failed to allocate memory");
            cleanup(fields, i);
            return;
        }

        char* name = (char*)(fields[i] + 1);
        strcpy(name, validNames[rand() % nameCount]);
        int uniqueName = 0;

        while (!uniqueName) {
            uniqueName = 1;
            for (int j = 0; j < i; j++) {
                if (strcmp(fields[j]->name, name) == 0) {
                    free(fields[i]);
                    fields[i] = NULL;
                    uniqueName = 0;
                    break;
                }
            }

            if (!uniqueName) {
                strcpy(name, validNames[rand() % nameCount]);
            }
        }

        fields[i]->name = name;
        fields[i]->value = rand() % (int)(records[0].offset - records[0].key + 1) + records[0].key;
    }
}

void cleanup(DialogField fields[], int count) {
    for (int i = 0; i < count; i++) {
        if (fields[i]) {
            free(fields[i]);
        }
    }
}

