['Here's a simplified version of the C code that addresses your requirements. This implementation uses POSIX threads for concurrency, SQLite for database interaction, and provides basic structures for memory management and validation:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sqlite3.h>
#include <time.h>

#define INITIAL_CAPACITY 10000
#define MAX_VALUE 1000000

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} RecordList;

static sqlite3 *db;
static const char *kDatabaseName = "records.db";

void init_db() {
    if (sqlite3_open(kDatabaseName, &db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        exit(1);
    }
}

int create_table() {
    const char *sql = "CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, value INT UNIQUE);";
    return sqlite3_exec(db, sql, 0, 0, 0);
}

void cleanup_db() {
    sqlite3_close(db);
}

RecordList* init_record_list() {
    RecordList *list = malloc(sizeof(RecordList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for RecordList\n");
        exit(1);
    }
    list->data = malloc(INITIAL_CAPACITY * sizeof(int));
    if (!list->data) {
        free(list);
        fprintf(stderr, "Memory allocation failed for record data\n");
        exit(1);
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_record_list(RecordList *list) {
    size_t new_capacity = list->capacity * 2;
    int *new_data = realloc(list->data, new_capacity * sizeof(int));
    if (!new_data) {
        fprintf(stderr, "Memory allocation failed during resizing\n");
        exit(1);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

int insert_unique_record(RecordList *list, int value) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i] == value) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    if (list->size >= list->capacity) {
        resize_record_list(list);
    }

    list->data[list->size++] = value;

    // Insert into database
    char sql[256];
    snprintf(sql, sizeof(sql), "INSERT INTO records (value) VALUES (%d);", value);
    char *err_msg = 0;
    if (sqlite3_exec(db, sql, 0, 0, &err_msg) != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", err_msg);
        sqlite3_free(err_msg);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_record_list(RecordList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    init_db();
    create_table();

    RecordList *record_list = init_record_list();

    srand(time(NULL));
    for (size_t i = 0; i < 20000; ++i) {
        int value = rand() % MAX_VALUE;
        if (insert_unique_record(record_list, value) != 0) {
            fprintf(stderr, "Failed to insert record with value: %d\n", value);
        }
    }

    free_record_list(record_list);
    cleanup_db();

    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread safety.
- **Database Integration**: Uses SQLite for persistent storage.
- **Dynamic Resizing**: Doubles the capacity when needed.
- **Unique Validation**: Checks for uniqueness before insertion.
- **Error Handling**: Logs errors and exits on critical failures.

### Considerations:
- This is a basic implementation. For production, consider more advanced concurrency control (e.g., read-write locks), error recovery strategies, and detailed logging mechanisms.
- Performance monitoring and profiling are not included in this snippet but should be integrated using tools like `gprof` or custom logging for latency/throughput metrics.
- Automated tests should be written separately to validate functionality under various conditions.']

