typedef struct {
    int node_id;
    long *offsets;
    int *keys;
    size_t num_connections;
    char health_status[20];
} NetworkNode;

typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct NodeRecord {
    NetworkNode *node;
    struct NodeRecord *next;
} NodeRecord;

typedef struct {
    NodeRecord *head;
    pthread_mutex_t lock;
} NodeList;

NodeList* create_node_list() {
    NodeList *list = (NodeList*)malloc(sizeof(NodeList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_offsets_keys(long *offsets, int *keys, size_t num_connections) {
    if (offsets) free(offsets);
    if (keys) free(keys);
}

NetworkNode* create_network_node(int node_id, long *offsets, int *keys, size_t num_connections, const char *health_status) {
    NetworkNode *node = (NetworkNode*)malloc(sizeof(NetworkNode));
    node->node_id = node_id;
    node->offsets = offsets ? malloc(num_connections * sizeof(long)) : NULL;
    memcpy(node->offsets, offsets, num_connections * sizeof(long));
    node->keys = keys ? malloc(num_connections * sizeof(int)) : NULL;
    memcpy(node->keys, keys, num_connections * sizeof(int));
    node->num_connections = num_connections;
    strncpy(node->health_status, health_status, sizeof(node->health_status) - 1);
    return node;
}

void add_node(NodeList *list, NetworkNode *node) {
    pthread_mutex_lock(&list->lock);
    NodeRecord *record = (NodeRecord*)malloc(sizeof(NodeRecord));
    record->node = node;
    record->next = list->head;
    list->head = record;
    pthread_mutex_unlock(&list->lock);
}

NetworkNode* get_node_by_id(NodeList *list, int node_id) {
    pthread_mutex_lock(&list->lock);
    NodeRecord *current = list->head;
    while (current) {
        if (current->node->node_id == node_id) {
            pthread_mutex_unlock(&list->lock);
            return current->node;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_node_connections(NodeList *list, int node_id, long *new_offsets, int *new_keys, size_t num_connections) {
    pthread_mutex_lock(&list->lock);
    NodeRecord *current = list->head;
    while (current) {
        if (current->node->node_id == node_id) {
            free_offsets_keys(current->node->offsets, current->node->keys, current->node->num_connections);
            current->node->offsets = new_offsets ? malloc(num_connections * sizeof(long)) : NULL;
            memcpy(current->node->offsets, new_offsets, num_connections * sizeof(long));
            current->node->keys = new_keys ? malloc(num_connections * sizeof(int)) : NULL;
            memcpy(current->node->keys, new_keys, num_connections * sizeof(int));
            current->node->num_connections = num_connections;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void detect_and_repair_partitions(NodeList *list) {
    // Placeholder for partition detection and repair logic
}

void log_operation(const char *operation, int node_id) {
    time_t now = time(NULL);
    printf("[%s] %s on node ID: %d\n", ctime(&now), operation, node_id);
}

void free_node_list(NodeList *list) {
    pthread_mutex_lock(&list->lock);
    NodeRecord *current = list->head;
    while (current) {
        NodeRecord *next = current->next;
        free_offsets_keys(current->node->offsets, current->node->keys, current->node->num_connections);
        free(current->node);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void update_topology(NodeList *list) {
