    long offsets[] = {1, 2, 3};
    int keys[] = {10, 20, 30};
    NetworkNode *node = create_network_node(1, offsets, keys, 3, "Healthy");
    add_node(network, node);

    log_operation("Added", node->node_id);

    long new_offsets[] = {4, 5, 6};
    int new_keys[] = {40, 50, 60};
    update_node_connections(network, 1, new_offsets, new_keys, 3);

    log_operation("Updated connections", node->node_id);

    NetworkNode *retrieved_node = get_node_by_id(network, 1);
    if (retrieved_node) {
