#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000
#define MAX_STATE_NAME_LENGTH 50

typedef struct {
    time_t timestamp;
    int bufferID;
    char logMessage[256];
} LogEntry;

typedef struct {
    char stateName[MAX_STATE_NAME_LENGTH];
    int configID;
    char status[50];
} LoggerState;

typedef struct {
    LogEntry* entries;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

void initLoggerManager(LogManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->entries = malloc(MAX_LOG_ENTRIES * sizeof(LogEntry));
    if (manager->entries == NULL) {
        fprintf(stderr, "Memory allocation for log entries failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
}

void freeLoggerManager(LogManager* manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}

int addLogEntry(LogManager* manager, time_t timestamp, int bufferID, const char* logMessage) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_LOG_ENTRIES) {
        fprintf(stderr, "Maximum number of log entries reached\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].bufferID == bufferID) {
            fprintf(stderr, "Duplicate buffer ID detected: %d\n", bufferID);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->entries[manager->count].timestamp = timestamp;
    manager->entries[manager->count].bufferID = bufferID;
    strncpy(manager->entries[manager->count].logMessage, logMessage, sizeof(manager->entries[manager->count].logMessage) - 1);

    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void updateLoggerState(LoggerState* states, size_t count, const char* stateName, int configID, const char* status) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(states[i].stateName, stateName) == 0) {
            fprintf(stderr, "Duplicate or invalid state name detected: %s\n", stateName);
            return;
        }
    }

    strncpy(states[count].stateName, stateName, MAX_STATE_NAME_LENGTH - 1);
    states[count].configID = configID;
    strncpy(states[count].status, status, sizeof(states[count].status) - 1);
}

int main() {
    LogManager manager;
    initLoggerManager(&manager);

    // Example usage
    addLogEntry(&manager, time(NULL), 1, "This is a log message");

    LoggerState states[10];
    updateLoggerState(states, 0, "InitialState", 101, "Active");

    freeLoggerManager(&manager);

    return 0;
}
