void freeFrameStats(FrameStats *frames, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (frames[i].packetList != NULL) {
            free(frames[i].packetList);
        }
    }
    free(frames);
}

// Comparator function for qsort
int compareSignalStrength(const void *a, const void *b) {
    FrameStats *frameA = (FrameStats *)a;
    FrameStats *frameB = (FrameStats *)b;

    // Sort in descending order of signal strength
    return frameB->signalStrength - frameA->signalStrength;
}

// Sort the FrameStats array by signal strength using qsort
void sortFrameStatsBySignalStrength(FrameStats *frames, size_t count) {
    qsort(frames, count, sizeof(FrameStats), compareSignalStrength);
}

int main() {
    const size_t frameCount = 10000; // Example size
    FrameStats *frameArray = NULL;

    populateFrameStats(&frameArray, frameCount);

    sortFrameStatsBySignalStrength(frameArray, frameCount);

    freeFrameStats(frameArray, frameCount);

    return 0;
}
