#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the dynamic list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the dynamic list structure
typedef struct {
    Node* head;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} DynamicList;

// Function prototypes
DynamicList* create_list(size_t initial_capacity);
bool insert(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data);
NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicList* list, size_t index);
bool delete_element(DynamicList* list, size_t index);
void clear_list(DynamicList* list);
static void resize_if_needed(DynamicList* list);
static bool set_crcflag(NFAPI_CRC_INDICATION_PDU_T* data, unsigned int seed);

// Create a new dynamic list
DynamicList* create_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    // Pre-allocate a block of memory for the nodes
    Node* node_block = (Node*)malloc(initial_capacity * sizeof(Node));
    if (!node_block) {
        free(list);
        return NULL;
    }

    list->head = node_block;
    for (size_t i = 0; i < initial_capacity - 1; ++i) {
        node_block[i].next = &node_block[i + 1];
    }
    node_block[initial_capacity - 1].next = NULL;

    return list;
}

// Insert a new element into the dynamic list
bool insert(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_if_needed(list);
    }

    Node* node = &list->head[list->size];
    node->data = data;
    node->next = NULL;

    ++list->size;
    bool success = true;

    pthread_mutex_unlock(&list->lock);
    return success;
}

// Resize the list if needed
static void resize_if_needed(DynamicList* list) {
    size_t new_capacity = list->capacity * 2;
    Node* new_node_block = (Node*)realloc(list->head, new_capacity * sizeof(Node));

    if (!new_node_block) return; // Handle memory allocation failure gracefully

    list->head = new_node_block;
    for (size_t i = list->capacity; i < new_capacity - 1; ++i) {
        new_node_block[i].next = &new_node_block[i + 1];
    }
    new_node_block[new_capacity - 1].next = NULL;

    list->capacity = new_capacity;
}

// Get an element by index
NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicList* list, size_t index) {
    if (index >= list->size) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* node = &list->head[index];
    NFAPI_CRC_INDICATION_PDU_T* data = &node->data;

    pthread_mutex_unlock(&list->lock);
    return data;
}

// Delete an element by index
bool delete_element(DynamicList* list, size_t index) {
    if (index >= list->size) return false;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    // Move the last node to the position of the one being deleted
    size_t last_index = list->size - 1;
    if (last_index > index) {
        Node* last_node = &list->head[last_index];
        *current = *(last_node);
    }

    --list->size;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Clear the dynamic list and free resources
void clear_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    // Reset size and capacity, freeing only the node block
    free(list->head);

    list->head = NULL;
    list->size = 0;
    list->capacity = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Randomly set CRCFLAG based on a provided seed
static bool set_crcflag(NFAPI_CRC_INDICATION_PDU_T* data, unsigned int seed) {
    if (!data) return false;

    srand(seed ^ (unsigned int)data); // Mix in the address for uniqueness
    data->CRCFLAG = rand() % 2 == 0;
    return true;
}

// Example usage with CRCFLAG setting
void example_usage() {
    DynamicList* list = create_list(10);
    if (!list) {
        fprintf(stderr, "Failed to create dynamic list\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < 15; ++i) { // Insert more than initial capacity
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();

        set_crcflag(&pdu, 42); // Use a fixed seed for demonstration

        if (!insert(list, pdu)) {
            fprintf(stderr, "Failed to insert element\n");
            clear_list(list);
            return;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* retrieved = get_element(list, 5);
    if (retrieved) {
        printf("Retrieved: RX=%d, RNTI=%d, CRC_TAG=%d, CRCFLAG=%d\n",
               retrieved->RX_UE_INFORMATION_TAG,
               retrieved->RNTI,
               retrieved->CRC_INDICATION_REL8_TAG,
               retrieved->CRCFLAG);
    }

    if (!delete_element(list, 5)) {
        fprintf(stderr, "Failed to delete element\n");
    }

    clear_list(list);
}
