    cache_item* items_head;
} cache_node;

void initialize_cache(cache_node** cache, size_t num_nodes) {
    if (cache == NULL || num_nodes <= 0) return;

    *cache = (cache_node*)malloc(num_nodes * sizeof(cache_node));
    if (*cache == NULL) {
        fprintf(stderr, "Memory allocation failed for cache nodes.\n");
        exit(EXIT_FAILURE);
    }

