    for (size_t i = 0; i < num_nodes; ++i) {
        (*cache)[i].offset = rand() % 10000;
        (*cache)[i].key = rand() % 1000;
        (*cache)[i].items_head = NULL;

        // Define load criteria, e.g., number of items per node
        size_t num_items = (rand() % 10) + 1; // Random number between 1 and 10

        for (size_t j = 0; j < num_items; ++j) {
            cache_item* new_item = (cache_item*)malloc(sizeof(cache_item));
            if (new_item == NULL) {
                fprintf(stderr, "Memory allocation failed for cache item.\n");
                exit(EXIT_FAILURE);
            }

            new_item->value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
            new_item->next = (*cache)[i].items_head;
            (*cache)[i].items_head = new_item;
        }
    }
}

void free_cache(cache_node* cache, size_t num_nodes) {
    if (cache == NULL) return;

    for (size_t i = 0; i < num_nodes; ++i) {
        cache_item* current = cache[i].items_head;
        while (current != NULL) {
            cache_item* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(cache);
}

