['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <json-c/json.h>

typedef struct {
    long timestamp;
    int event_type;
    long unique_id;
    char *metadata_json;
} TrafficEvent;

typedef struct {
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
    TrafficEvent **events;
    size_t capacity;
    size_t count;
    long next_id;
} TrafficEventManager;

TrafficEventManager* create_traffic_event_manager(size_t initial_capacity) {
    TrafficEventManager *manager = malloc(sizeof(TrafficEventManager));
    manager->events = malloc(initial_capacity * sizeof(TrafficEvent *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->next_id = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);
    return manager;
}

void free_traffic_event_manager(TrafficEventManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        json_object_put(json_tokener_parse(manager->events[i]->metadata_json));
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

TrafficEvent* create_traffic_event(int event_type) {
    TrafficEvent *event = malloc(sizeof(TrafficEvent));
    event->timestamp = time(NULL);
    event->event_type = event_type;
    event->unique_id = (long)(rand() % 1000000);

    json_object *jobj = json_object_new_object();
    json_object_object_add(jobj, "random_value", json_object_new_int(rand()));
    const char *status = rand() % 2 ? "A" : "B";
    json_object_object_add(jobj, "status_indicator", json_object_new_string(status));

    char *random_str = malloc(11);
    for (int i = 0; i < 10; ++i) {
        random_str[i] = 'a' + rand() % 26;
    }
    random_str[10] = '\0';
    json_object_object_add(jobj, "random_string", json_object_new_string(random_str));
    free(random_str);

    event->metadata_json = strdup(json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY));
    json_object_put(jobj);
    return event;
}

void add_traffic_event(TrafficEventManager *manager, TrafficEvent *event) {
    pthread_rwlock_wrlock(&manager->rwlock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->events = realloc(manager->events, new_capacity * sizeof(TrafficEvent *));
        manager->capacity = new_capacity;
    }
    manager->events[manager->count++] = event;
    pthread_rwlock_unlock(&manager->rwlock);
}

void remove_traffic_event(TrafficEventManager *manager, long unique_id) {
    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->unique_id == unique_id) {
            json_object_put(json_tokener_parse(manager->events[i]->metadata_json));
            free(manager->events[i]);
            memmove(&manager->events[i], &manager->events[i + 1],
                    (manager->count - i - 1) * sizeof(TrafficEvent *));
            manager->count--;
            break;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
}

TrafficEvent* get_traffic_event_by_id(TrafficEventManager *manager, long unique_id) {
    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->unique_id == unique_id) {
            TrafficEvent *event = malloc(sizeof(TrafficEvent));
            memcpy(event, manager->events[i], sizeof(TrafficEvent));
            pthread_rwlock_unlock(&manager->rwlock);
            return event;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
    return NULL;
}

void serialize_traffic_event_manager(const TrafficEventManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "[\n");
    for (size_t i = 0; i < manager->count; ++i) {
        json_object *jobj = json_tokener_parse(manager->events[i]->metadata_json);
        const char *json_str = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY);
        fprintf(file, "    %s,\n", json_str);
        json_object_put(jobj);
    }
    fprintf(file, "]");
    fclose(file);
}

void deserialize_traffic_event_manager(TrafficEventManager *manager, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    fread(buffer, 1, length, file);
    buffer[length] = '\0';
    fclose(file);

    json_object *jobj = json_tokener_parse(buffer);
    json_object_array_foreach(jobj, i, jvalue) {
        TrafficEvent *event = create_traffic_event(0); // Default event type
        event->timestamp = time(NULL);
        event->unique_id = manager->next_id++;
        event->metadata_json = strdup(json_object_to_json_string_ext(jvalue, 0));
        add_traffic_event(manager, event);
    }
    json_object_put(jobj);
    free(buffer);
}

void populate_nfa_crc_indication_pdu(int n, NFAPI_CRC_INDICATION_PDU_T *pdus) {
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        pdus[i].rnti = rand();
        pdus[i].rx_ue_info_tag = rand() % 100;
        pdus[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
}

void log_event(const char *message) {
    printf("[LOG] %s\n", message);
}
