typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;  // For singly linked list
    // struct NFAPI_CRC_INDICATION_PDU_T *prev;  // Uncomment for doubly linked list
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_list(int count) {
    if (count <= 0) return NULL;

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            pthread_mutex_unlock(&lock);
            return NULL; // Memory allocation failed
        }

        new_node->rxUeInformationTag.RNTI = rand() % 1000000;  // Random RNTI for demonstration
        new_node->rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG = rand() % 2;  // Random CRCFLAG

        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;

        // For doubly linked list, uncomment the following line:
        // new_node->prev = tail;  
    }

    pthread_mutex_unlock(&lock);

    return head;
}

void validate_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    if (!head) return;

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->rxUeInformationTag.RNTI == 0 || current->rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG < 0 ||
            current->rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG > 1) {
            fprintf(stderr, "Invalid data in node: RNTI=%lu CRCFLAG=%d\n",
                    (unsigned long)current->rxUeInformationTag.RNTI,
                    current->rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG);
        }
        current = current->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *current = head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    int num_nodes = 10;  // Example: user input for the number of nodes
    NFAPI_CRC_INDICATION_PDU_T *list = create_list(num_nodes);

    if (list) {
        validate_list(list);

        free_list(list);
    } else {
        fprintf(stderr, "Failed to create list.\n");
    }

    return 0;
}
```

### Assumptions and Considerations:
1. **Memory Allocation**: Use of `malloc` ensures dynamic allocation for each node.
2. **Thread Safety**: A mutex is used to ensure thread-safe operations on the linked list during creation, validation, and deallocation.
3. **Error Handling**: Basic error handling checks are in place; e.g., if memory allocation fails or invalid data is detected.
4. **Data Initialization**: Randomized initialization for `RNTI` and `CRCFLAG`.
5. **Doubly vs Singly Linked List**: The code supports both structures, but only singly linked list logic is active by default (uncomment `prev` in the struct to enable doubly linked features).
6. **Performance**: The design balances between ease of element access and memory usage; more sophisticated data structures might be needed for better performance under high concurrency.
7. **Validation**: Ensures all nodes have valid data before returning the list.

This implementation focuses on simplicity, correctness, and thread safety while providing a foundation to expand upon based on specific application requirements.']

