#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <curl/curl.h>
#include <string.h>
#include "openssl/evp.h"
#include "openssl/aes.h"

#define MAX_URLS 100
#define BUFFER_SIZE 1024

typedef struct {
    char *data;
    size_t length;
} HTTPResponse;

typedef struct {
    char *key; // Encryption key for AES
    int mode;  // 0: ECB, 1: CBC, 2: GCM, 3: CTR, 4: None
} EncryptionConfig;

typedef struct {
    CURL *curl_handle;
    char *url;
    HTTPResponse response;
} FetchTask;

typedef struct {
    pthread_t thread_id;
    FetchTask task;
} ThreadPoolWorker;

// Function prototypes
size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata);
void* fetch_url(void *arg);
void initialize_thread_pool(ThreadPoolWorker workers[], int count);
void destroy_thread_pool(ThreadPoolWorker workers[], int count);
HTTPResponse* encrypt_response(HTTPResponse *response, EncryptionConfig config);
void log_error(const char *message);

// Main function
int main(int argc, char **argv) {
    CURLM *multi_handle;
    int still_running = 0;

    // Initialize cURL multi interface
    curl_global_init(CURL_GLOBAL_ALL);
    multi_handle = curl_multi_init();

    // Thread pool for concurrent requests
    ThreadPoolWorker workers[MAX_URLS];
    initialize_thread_pool(workers, MAX_URLS);

    char *urls[] = {
        "http://example.com",
        "http://testsite.com"
        // Add more URLs as needed
    };

    int num_urls = sizeof(urls) / sizeof(urls[0]);
    for (int i = 0; i < num_urls; ++i) {
        FetchTask task;
        task.url = urls[i];
        task.response.data = malloc(BUFFER_SIZE);
        task.response.length = 0;

        if (!task.response.data) {
            log_error("Failed to allocate memory for response data.");
            continue;
        }

        int worker_idx = i % MAX_URLS; // Simple round-robin distribution
        workers[worker_idx].task = task;
        curl_multi_add_handle(multi_handle, curl_easy_init());

        pthread_create(&workers[worker_idx].thread_id, NULL, fetch_url, &workers[worker_idx]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_URLS; ++i) {
        pthread_join(workers[i].thread_id, NULL);
    }

    // Clean up resources
    destroy_thread_pool(workers, MAX_URLS);
    curl_multi_cleanup(multi_handle);
    curl_global_cleanup();

    return 0;
}

// Fetch URL function
void* fetch_url(void *arg) {
    ThreadPoolWorker *worker = (ThreadPoolWorker *)arg;
    CURLcode res;

    curl_easy_setopt(worker->curl_handle, CURLOPT_URL, worker->task.url);
    curl_easy_setopt(worker->curl_handle, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(worker->curl_handle, CURLOPT_WRITEDATA, &worker->task.response);

    res = curl_easy_perform(worker->curl_handle);

    if (res != CURLE_OK) {
        log_error("CURL error: %s", curl_easy_strerror(res));
    }

    // Encrypt response data
    EncryptionConfig config = { .key = "0123456789abcdef", .mode = 1 }; // Example config
    HTTPResponse *encrypted_response = encrypt_response(&worker->task.response, config);

    // Serialize to file (example)
    FILE *file = fopen("output.txt", "a");
    if (file) {
        fwrite(encrypted_response->data, 1, encrypted_response->length, file);
        fclose(file);
    }

    free(worker->task.response.data);
    curl_easy_cleanup(worker->curl_handle);

    return NULL;
}

// Initialize thread pool
void initialize_thread_pool(ThreadPoolWorker workers[], int count) {
    for (int i = 0; i < count; ++i) {
        workers[i].thread_id = 0;
        workers[i].task.curl_handle = curl_easy_init();
        if (!workers[i].task.curl_handle) {
            log_error("Failed to initialize cURL handle.");
        }
    }
}

// Destroy thread pool
void destroy_thread_pool(ThreadPoolWorker workers[], int count) {
    for (int i = 0; i < count; ++i) {
        curl_easy_cleanup(workers[i].task.curl_handle);
    }
}

// Write data callback
size_t write_data(void *ptr, size_t size, size_t nmemb, void *userdata) {
    HTTPResponse *response = (HTTPResponse *)userdata;
    response->length += size * nmemb;

    if (response->length + size * nmemb > BUFFER_SIZE) {
        // Expand buffer
        char *new_data = realloc(response->data, response->length + size * nmemb);
        if (!new_data) {
            log_error("Failed to reallocate memory for HTTP response.");
            return 0;
        }
        response->data = new_data;
    }

    memcpy(response->data + response->length - size * nmemb, ptr, size * nmemb);
    return size * nmemb;
}

// Encrypt response data
HTTPResponse* encrypt_response(HTTPResponse *response, EncryptionConfig config) {
    // Example AES encryption implementation (ECB mode)
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0, AES_BLOCK_SIZE); // Zero IV for simplicity

    int len;
    unsigned char encrypted_data[response->length + AES_BLOCK_SIZE];
    int encrypted_length;

    EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, (unsigned char *)config.key, iv);
    EVP_EncryptUpdate(ctx, encrypted_data, &len, (unsigned char*)response->data, response->length);
    encrypted_length = len;
    EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len);
    encrypted_length += len;

    HTTPResponse *encrypted_response = malloc(sizeof(HTTPResponse));
    encrypted_response->data = malloc(encrypted_length);
    encrypted_response->length = encrypted_length;
    memcpy(encrypted_response->data, encrypted_data, encrypted_length);

    EVP_CIPHER_CTX_free(ctx);
    return encrypted_response;
}

// Log error messages
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

### Notes:
- This code provides a basic structure for the described utility. It uses cURL for HTTP requests and OpenSSL for AES encryption.
- The thread pool is implemented using POSIX threads (`pthread`).
- Memory management is handled with dynamic allocation and deallocation.
- Error handling includes logging error messages.
- The AES encryption example uses ECB mode; additional modes can be implemented similarly.
- Performance monitoring, detailed logging, and configuration options are left as exercises for further implementation.']

