['Below is a C code implementation for managing memory for dynamically allocated arrays `offsets`, `keys`, and `records`. It includes AES-256-CBC encryption context initialization, dynamic resizing, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
#include <pthread.h>

#define INITIAL_OFFSETS_SIZE 1024
#define OFFSET_GROWTH_INCREMENT 1024
#define MAX_OFFSET_SUM 1000000
#define INACTIVE_THRESHOLD 60 // seconds

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
    time_t last_accessed;
    int active;
} record;

typedef struct {
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    EVP_CIPHER_CTX *ctx_enc;
    EVP_CIPHER_CTX *ctx_dec;
} cipher_context;

pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int init_cipher_context(cipher_context *cipher_ctx, const char *password) {
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL,
                        (unsigned char *)password, strlen(password),
                        1, cipher_ctx->key, cipher_ctx->iv)) {
        return 0;
    }

    cipher_ctx->ctx_enc = EVP_CIPHER_CTX_new();
    cipher_ctx->ctx_dec = EVP_CIPHER_CTX_new();

    if (!cipher_ctx->ctx_enc || !cipher_ctx->ctx_dec) {
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(cipher_ctx->ctx_enc, EVP_aes_256_cbc(), NULL,
                                cipher_ctx->key, cipher_ctx->iv) ||
        1 != EVP_DecryptInit_ex(cipher_ctx->ctx_dec, EVP_aes_256_cbc(), NULL,
                                cipher_ctx->key, cipher_ctx->iv)) {
        return 0;
    }

    return 1;
}

void cleanup_cipher_context(cipher_context *cipher_ctx) {
    if (cipher_ctx->ctx_enc) EVP_CIPHER_CTX_free(cipher_ctx->ctx_enc);
    if (cipher_ctx->ctx_dec) EVP_CIPHER_CTX_free(cipher_ctx->ctx_dec);
}

int allocate_and_initialize(int offsets_size, int keys_size, record **records,
                            long ***offsets, int ***keys, cipher_context *cipher_ctx,
                            const char *password) {
    if (!init_cipher_context(cipher_ctx, password)) {
        log_error("Failed to initialize cipher context");
        return 0;
    }

    srand(time(NULL));
    *offsets = malloc(offsets_size * sizeof(long));
    *keys = malloc(keys_size * sizeof(int));

    if (!*offsets || !*keys) {
        log_error("Memory allocation failed for offsets or keys");
        cleanup_cipher_context(cipher_ctx);
        return 0;
    }

    long offset_sum = 0;
    for (int i = 0; i < offsets_size; ++i) {
        (*offsets)[i] = rand() % 1000 + 1;
        offset_sum += (*offsets)[i];
    }

    if (offset_sum > MAX_OFFSET_SUM) {
        log_error("Offset sum exceeds maximum limit");
        free(*offsets);
        free(*keys);
        cleanup_cipher_context(cipher_ctx);
        return 0;
    }

    for (int i = 0; i < keys_size; ++i) {
        (*keys)[i] = rand() % 100 + 1;
    }

    *records = malloc(keys_size * sizeof(record));
    if (!*records) {
        log_error("Memory allocation failed for records");
        free(*offsets);
        free(*keys);
        cleanup_cipher_context(cipher_ctx);
        return 0;
    }

    for (int i = 0; i < keys_size; ++i) {
        (*records)[i].value = rand() % 1000 + 1;
        (*records)[i].offset_ptr = &((*offsets)[i]);
        (*records)[i].key_ptr = &(*keys)[i];
        (*records)[i].last_accessed = time(NULL);
        (*records)[i].active = 1;
    }

    return 1;
}

void resize_offsets(long **offsets, int *current_size) {
    int new_size = *current_size + OFFSET_GROWTH_INCREMENT;
    long *new_array = realloc(*offsets, new_size * sizeof(long));
    if (!new_array) {
        log_error("Memory reallocation failed for offsets");
        return;
    }
    *offsets = new_array;
    memset(&((*offsets)[*current_size]), 0, OFFSET_GROWTH_INCREMENT * sizeof(long));
    *current_size = new_size;
}

void resize_records(record **records, int *current_size) {
    int new_size = current_size ? (*current_size << 1) : INITIAL_OFFSETS_SIZE;
    record *new_array = realloc(*records, new_size * sizeof(record));
    if (!new_array) {
        log_error("Memory reallocation failed for records");
        return;
    }
    *records = new_array;
    memset(&((*records)[*current_size]), 0, (*current_size) * sizeof(record));
    *current_size = new_size;
}

void mark_inactive_records(record *records, int size) {
    time_t now = time(NULL);
    for (int i = 0; i < size; ++i) {
        if (now - records[i].last_accessed > INACTIVE_THRESHOLD) {
            records[i].active = 0;
        }
    }
}

void reorganize_records(record *records, int size) {
    pthread_mutex_lock(&records_mutex);
    qsort(records, size, sizeof(record), [](const void *a, const void *b) -> int {
        return ((record *)b)->last_accessed - ((record *)a)->last_accessed;
    });
    pthread_mutex_unlock(&records_mutex);
}

void simulate_background_process(void *args) {
    while (1) {
        sleep(30); // Simulate periodic operation
        reorganize_records(*((record **)args), *((int *)args + 1));
    }
}
```

This code provides a comprehensive solution for managing dynamically allocated arrays with encryption, resizing, and background processing. It includes error handling and logging to ensure robustness under varying loads.']

