void log_message(const char* message) {
    printf("%s\n", message);
}

int check_rate_limit() {
    unsigned long current_time_ns = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    if (current_time_ns - last_creation_time_ns < rate_limit_period_ns) {
        return 0; // Rate limit exceeded
    }
    last_creation_time_ns = current_time_ns;
    return 1; // Allowed to proceed
}

LTE_ENODEB_MESSAGE_PDU_T* allocate_enodeb_message_pdu_array(size_t N) {
    pthread_mutex_lock(&lock);

    if (!check_rate_limit()) {
        pthread_mutex_unlock(&lock);
        log_message("Rate limit exceeded, operation aborted.");
        return NULL;
    }

    LTE_ENODEB_MESSAGE_PDU_T* array = malloc(N * sizeof(LTE_ENODEB_MESSAGE_PDU_T));
    if (array == NULL) {
        pthread_mutex_unlock(&lock);
        log_message("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].cell_info.ENODEB_CELL_INFO_TAG = rand() % 100; // Random valid tag
        array[i].cell_info.CELL_ID = rand() % 10000;           // Random cell ID
        array[i].measurement_report.MEASUREMENT_REPORT_TAG = rand() % 100;
        array[i].measurement_report.MEAS_FLAG = rand() % 2;   // Randomly set MEAS_FLAG

        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Created structure at index %zu", i);
        log_message(log_buf);
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void free_enodeb_message_pdu_array(LTE_ENODEB_MESSAGE_PDU_T* array) {
    if (array != NULL) {
        free(array);
    }
}
