#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <json-c/json.h>

#define MAX_EVENTS 10000000

typedef struct {
    int random_int;
    char status_indicator;
    char alpha_chars[11];
} Record;

typedef struct {
    long timestamp;
    int event_type;
    int unique_id;
    json_object *metadata;
    Record record;
} TrafficEvent;

typedef struct {
    TrafficEvent **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
} TrafficEventManager;

TrafficEventManager* create_traffic_event_manager(size_t initial_capacity) {
    TrafficEventManager *manager = (TrafficEventManager *)malloc(sizeof(TrafficEventManager));
    manager->events = (TrafficEvent **)calloc(initial_capacity, sizeof(TrafficEvent *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);
    return manager;
}

void destroy_traffic_event_manager(TrafficEventManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        json_object_put(manager->events[i]->metadata);
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->mutex);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager->metadata);
}

void generate_random_record(Record *record) {
    record->random_int = rand();
    record->status_indicator = (rand() % 2 == 0) ? 'A' : 'B';
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int i = 0; i < 10; ++i) {
        record->alpha_chars[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    record->alpha_chars[10] = '\0';
}

TrafficEvent* create_traffic_event(long timestamp, int event_type, int unique_id) {
    TrafficEvent *event = (TrafficEvent *)malloc(sizeof(TrafficEvent));
    event->timestamp = timestamp;
    event->event_type = event_type;
    event->unique_id = unique_id;

    json_object *metadata = json_object_new_object();
    json_object_object_add(metadata, "example_key", json_object_new_string("example_value"));
    event->metadata = metadata;

    generate_random_record(&event->record);

    // Logging integration placeholder
    printf("TrafficEvent created: %d\n", unique_id);

    return event;
}

void add_traffic_event(TrafficEventManager *manager, TrafficEvent *event) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->events = (TrafficEvent **)realloc(manager->events, new_capacity * sizeof(TrafficEvent *));
    }

    manager->events[manager->count++] = event;

    pthread_rwlock_unlock(&manager->rwlock);
}

void query_events(TrafficEventManager *manager, int (*filter)(const TrafficEvent *)) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (filter(manager->events[i])) {
            // Process event
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

// Example filter function
int example_filter(const TrafficEvent *event) {
    return event->record.status_indicator == 'A';
}

int main() {
    srand(time(NULL));
    TrafficEventManager *manager = create_traffic_event_manager(100);

    for (int i = 0; i < 1000; ++i) {
        add_traffic_event(manager, create_traffic_event(time(NULL), rand() % 10, i));
    }

    query_events(manager, example_filter);

    destroy_traffic_event_manager(manager);
    return 0;
}
