```python
from flask import Flask, request, jsonify, abort
import logging

app = Flask(__name__)
rate_limiting_enabled = True

resources = {}

@app.route('/resource/<int:id>', methods=['PUT'])
def update_resource(id):
    if rate_limiting_enabled:
        # Implement rate limiting logic here
        pass

    data = request.json
    if not data or 'updated_data' not in data:
        abort(400, description="Invalid input data")

    resource = resources.get(id)
    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    # Update the resource with new data
    resource.update(data['updated_data'])

    logging.info(f"Resource {id} updated successfully.")
    return jsonify(resource)

@app.route('/resource/<int:id>', methods=['DELETE'])
def delete_resource(id):
    if rate_limiting_enabled:
        # Implement rate limiting logic here
        pass

    resource = resources.pop(id, None)
    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    new_resource = {"id": id, "data": {}}
    resources[id] = new_resource

    logging.info(f"Resource {id} deleted and replaced with default values.")
    return jsonify(new_resource)

if __name__ == '__main__':
    app.run(debug=True)
```

