                    if current_section:
                        sections.append(current_section)

                    header_match = re.match(r'\[(.+?)\s+(\d+)\]', stripped_line)
                    if not header_match:
                        raise MalformedSectionException(f"Malformed section header: {stripped_line}")

                    section_name, seq_num = header_match.groups()
                    current_section = {'header': section_name, 'seq_num': int(seq_num), 'lines': []}
                    is_comment_or_empty = False
                else:
                    # Collect lines under the current section
                    if not is_comment_or_empty:
                        current_section['lines'].append(stripped_line)

            # Append the last collected section
            if current_section:
                sections.append(current_section)

        logger.info(f"Total sections parsed: {len(sections)}")

        # Sort the sections based on their names in lexicographical order
        sections.sort(key=lambda x: x['header'])

        # Extract sequence number from the last section header
        if sections:
            last_header_seq_num = sections[-1]['seq_num']
            logger.info(f"Sequence number of the last section header: {last_header_seq_num}")

        # Validate each section's structure
