```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <sys/syslog.h>
#include <string.h>
#include <unistd.h>
#include <zlib.h>

// Configuration structure
typedef struct {
    size_t alignment;
    size_t padding;
    size_t max_size;
} Config;

// Record structure
typedef struct {
    int value;
    int *key_ptr;
    long *offset_ptr;
} Record;

// Global variables for synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to read configuration from file
Config load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    Config config = {16, 8, 1024}; // Default values

    if (file) {
        fscanf(file, "%zu %zu %zu", &config.alignment, &config.padding, &config.max_size);
        fclose(file);
    } else {
        syslog(LOG_ERR, "Failed to open configuration file.");
    }

    return config;
}

// Function to compress data using zlib
size_t compress_data(const void *data, size_t input_size, unsigned char **compressed_data) {
    uLongf compressed_size = compressBound(input_size);
    *compressed_data = malloc(compressed_size);

    if (compress(*compressed_data, &compressed_size, (const Bytef *)data, input_size) != Z_OK) {
        free(*compressed_data);
        return 0;
    }

    return compressed_size;
}

// Function to allocate and initialize arrays
int allocate_and_initialize_arrays(size_t max_size, long **offsets, int **keys, Record ***records) {
    pthread_mutex_lock(&mutex);

    Config config = load_config("config.txt");

    size_t actual_size = min(max_size, config.max_size);
    while (actual_size > 0) {
        *offsets = aligned_alloc(config.alignment, actual_size * sizeof(long));
        if (*offsets == NULL) {
            syslog(LOG_ERR, "Failed to allocate memory for offsets.");
            break;
        }

        *keys = aligned_alloc(config.alignment, actual_size * sizeof(int));
        if (*keys == NULL) {
            free(*offsets);
            syslog(LOG_ERR, "Failed to allocate memory for keys.");
            break;
        }

        Record *record_array = malloc(actual_size * sizeof(Record));
        if (record_array == NULL) {
            free(*offsets);
            free(*keys);
            syslog(LOG_ERR, "Failed to allocate memory for records.");
            break;
        }

        for (size_t i = 0; i < actual_size; ++i) {
            (*records)[i] = &record_array[i];
            record_array[i].value = rand(); // Example initialization
            record_array[i].key_ptr = &((*keys)[i]);
            record_array[i].offset_ptr = &((*offsets)[i]);

            (*offsets)[i] = i * config.padding; // Example offset calculation
            (*keys)[i] = rand(); // Example key generation
        }

        syslog(LOG_INFO, "Successfully allocated memory for %zu records.", actual_size);
        pthread_mutex_unlock(&mutex);

        return 1;
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to deallocate arrays
void deallocate_arrays(long *offsets, int *keys, Record **records) {
    free(offsets);
    free(keys);
    free(*records);
    syslog(LOG_INFO, "Successfully deallocated memory.");
}

// Main function for testing
int main() {
    openlog("MemoryAllocator", LOG_PID | LOG_CONS, LOG_USER);

    long *offsets = NULL;
    int *keys = NULL;
    Record **records = malloc(1024 * sizeof(Record *));

    if (!allocate_and_initialize_arrays(1024, &offsets, &keys, records)) {
        syslog(LOG_ERR, "Allocation failed.");
    }

    deallocate_arrays(offsets, keys, records);

    closelog();
    return 0;
}
```

### Key Points:
- **Synchronization**: Uses `pthread_mutex_t` to ensure thread safety.
- **Configuration**: Reads from a file for alignment, padding, and max size.
- **Compression**: Utilizes zlib for compressing metadata.
- **Logging**: Logs using syslog for allocation success/failure.
- **Error Handling**: Checks for memory allocation failures and logs errors.
- **Deallocation**: Provides a function to free allocated memory.']

