```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure.
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for singly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked List structure with thread-safe access and logging
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int size;
} LinkedList;

// Logging function prototype
void log_message(const char* message);

// Function prototypes
LinkedList* create_linked_list();
int add_pdu_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
void free_linked_list(LinkedList* list);
int validate_list(LinkedList* list);
void perform_garbage_collection(LinkedList* list);

// Create a new linked list
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_message("Failed to allocate memory for the list.");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

// Add a PDU structure to the linked list
int add_pdu_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) {
        log_message("Attempted to add to a null list.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Failed to allocate memory for a new node.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Randomly set CRCFLAG
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Free all memory associated with the linked list
void free_linked_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Validate all structures in the linked list
int validate_list(LinkedList* list) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == 0 || current->data.RNTI == 0) {
            log_message("Validation failed: Invalid data found in the list.");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // List is valid
}

// Perform garbage collection by removing nodes with specific criteria (example)
void perform_garbage_collection(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node dummy;
    dummy.next = list->head;
    Node* prev = &dummy;
    Node* current = list->head;

    while (current) {
        if (current->data.CRC_INDICATION_REL8_TAG.CRCFLAG == 0) { // Example condition
            prev->next = current->next;
            free(current);
            list->size--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    list->head = dummy.next;
    pthread_mutex_unlock(&list->lock);
}

// Logging function implementation (simplified)
void log_message(const char* message) {
    printf("Log: %s\n", message);
}
```

