// Function prototypes
void initializeRxDpuList(RxDpuList *list);
int addRxPdu(RxDpuList *list, const RxPduHeader *header, unsigned int rnti, int crcStatus);
void resizeRxDpuList(RxDpuList *list);

// Initialize the RxDpuList with initial capacity
void initializeRxDpuList(RxDpuList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = 10; // Initial capacity can be adjusted as needed
    list->pdus = (RxPdu *)malloc(list->capacity * sizeof(RxPdu));
}

// Add an RxPdu to the list with thread safety and dynamic resizing
int addRxPdu(RxDpuList *list, const RxPduHeader *header, unsigned int rnti, int crcStatus) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resizeRxDpuList(list);
    }

    RxPdu newPdu;
    newPdu.header = *header; // Assuming a shallow copy is sufficient
    newPdu.rnti = rnti;
    newPdu.crcStatus = crcStatus;

    list->pdus[list->count++] = newPdu;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Resize the RxDpuList when capacity is reached
void resizeRxDpuList(RxDpuList *list) {
    size_t newCapacity = list->capacity * 2;
    RxPdu *newArray = (RxPdu *)realloc(list->pdus, newCapacity * sizeof(RxPdu));

    if (newArray != NULL) {
        list->pdus = newArray;
        list->capacity = newCapacity;
    } else {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        // Consider logging the error or retrying
    }
}

// Cleanup function to free allocated resources
void cleanupRxDpuList(RxDpuList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdus);
    list->pdus = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}
