#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char status;
    char *dynamic_string;
} Record;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define ALPHABET "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
#define STRING_LENGTH 10
#define RECORD_MAX_VALUE_RANGE 100

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t offset_count;
    size_t key_count;
    size_t record_count;
} MemoryManager;

int allocate_memory(MemoryManager *manager, size_t offset_count, size_t key_count, size_t record_count) {
    pthread_mutex_lock(&lock);

    manager->offsets = (long *)malloc(offset_count * sizeof(long));
    if (!manager->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        pthread_mutex_unlock(&lock);
        return 1;
    }

    manager->keys = (int *)malloc(key_count * sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        pthread_mutex_unlock(&lock);
        return 1;
    }

    manager->records = (Record **)malloc(record_count * sizeof(Record *));
    if (!manager->records) {
        free(manager->offsets);
        free(manager->keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        pthread_mutex_unlock(&lock);
        return 1;
    }

    for (size_t i = 0; i < offset_count; ++i)
        manager->offsets[i] = i;

    for (size_t i = 0; i < key_count; ++i)
        manager->keys[i] = i;

    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            free(manager->records);
            free(manager->keys);
            free(manager->offsets);
            fprintf(stderr, "Memory allocation failed for a record\n");
            pthread_mutex_unlock(&lock);
            return 1;
        }

        record->value = rand() % RECORD_MAX_VALUE_RANGE;
        record->status = (rand() % 2 == 0) ? 'A' : 'B';

        char *string = (char *)malloc(STRING_LENGTH + 1);
        if (!string) {
            free(record);
            free(manager->records);
            free(manager->keys);
            free(manager->offsets);
            fprintf(stderr, "Memory allocation failed for dynamic string\n");
            pthread_mutex_unlock(&lock);
            return 1;
        }

        for (int j = 0; j < STRING_LENGTH; ++j)
            string[j] = ALPHABET[rand() % strlen(ALPHABET)];

        string[STRING_LENGTH] = '\0';
        record->dynamic_string = string;

        manager->records[i] = record;
    }

    manager->offset_count = offset_count;
    manager->key_count = key_count;
    manager->record_count = record_count;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void deallocate_memory(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < manager->record_count; ++i)
        free(manager->records[i]->dynamic_string);

    free(manager->records);
    free(manager->keys);
    free(manager->offsets);

    memset(manager, 0, sizeof(MemoryManager));

    pthread_mutex_unlock(&lock);
}

int main() {
    MemoryManager manager = {0};
    size_t offset_count = 100;
    size_t key_count = 50;
    size_t record_count = 30;

    if (allocate_memory(&manager, offset_count, key_count, record_count) != 0) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    // Simulate operations on manager's data...

    deallocate_memory(&manager);

    return EXIT_SUCCESS;
}
