    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} LockFreeList;

// Global variables for thread-safe hash table and list
HashTable* rnti_hash_table = NULL;  // A global lock-free hash table.
LockFreeList* nfa_list = NULL;
SlabAllocator* slab_allocator = NULL;

void initialize_system() {
    rnti_hash_table = create_lock_free_hash_table();
    nfa_list = (LockFreeList*)malloc(sizeof(LockFreeList));
    if (!nfa_list) {
        log_error("Failed to allocate memory for LockFreeList.");
        return;
    }
    nfa_list->head = NULL;
    nfa_list->size = 0;

    slab_allocator = create_slab_allocator(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ELEMENTS);
    if (!slab_allocator) {
        log_error("Failed to initialize slab allocator.");
        free(nfa_list);
        return;
    }
}

void cleanup_system() {
    destroy_lock_free_hash_table(rnti_hash_table);
    // Free list nodes
    Node* current = nfa_list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_slab(slab_allocator, (char*)current);  // Assuming `free_slab` frees allocated memory.
        current = next;
    }
    destroy_slab_allocator(slab_allocator);
    free(nfa_list);
}

bool insert_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!rnti_hash_table || !slab_allocator) return false;

    if (lookup_rnti(rnti_hash_table, pdu.RNTI)) {
        log_info("Duplicate RNTI detected. Insertion failed.");
        return false;
    }

    Node* new_node = allocate_slab(slab_allocator);
    if (!new_node) {
        log_error("Failed to allocate slab for new PDU.");
        return false;
    }
    new_node->data = pdu;
    new_node->next = nfa_list->head;

    // Lock-free update of the linked list
    Node* expected_head = NULL;
    while (!compare_and_swap(&nfa_list->head, &expected_head, new_node)) {
        if (expected_head) {
            free_slab(slab_allocator, (char*)new_node);
            return false;  // Retry on failure or handle appropriately
        }
    }

    hash_insert(rnti_hash_table, pdu.RNTI, new_node);

    nfa_list->size++;
    log_info("Successfully inserted PDU with RNTI: %d", pdu.RNTI);
    return true;
}

bool delete_pdu(int rnti) {
    if (!rnti_hash_table) return false;

    Node* node = hash_lookup(rnti_hash_table, rnti);
    if (!node) {
        log_info("RNTI: %d not found for deletion.", rnti);
        return false;
    }

    // Lock-free removal of the linked list
    Node** current_ptr = &nfa_list->head;
    while (*current_ptr && *current_ptr != node) {
        current_ptr = &(*current_ptr)->next;
    }
    if (!*current_ptr) {
        log_error("Node not found in list for deletion.");
        return false;
    }

    Node* next_node = node->next;
    hash_remove(rnti_hash_table, rnti);
    *current_ptr = next_node;

    free_slab(slab_allocator, (char*)node);

    nfa_list->size--;
    log_info("Successfully deleted PDU with RNTI: %d", rnti);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(int rnti) {
    Node* node = hash_lookup(rnti_hash_table, rnti);
    if (!node) {
        log_info("RNTI: %d not found for retrieval.", rnti);
        return NULL;
    }
    return &(node->data);
}

