#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char status;
    char *name;
} record;

void initialize_memory(long **offsets, int *keys, record **records, size_t offset_size, size_t key_size, size_t record_size, int min_value, int max_value) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int error_flag = 0; // 1 if any allocation fails
    srand(time(NULL));

    // Allocate and initialize offsets array
    *offsets = (long *)malloc(offset_size * sizeof(long));
    if (*offsets == NULL) { error_flag = 1; goto cleanup; }
    for (size_t i = 0; i < offset_size; ++i) {
        (*offsets)[i] = i;
    }

    // Allocate and initialize keys array
    *keys = (int *)malloc(key_size * sizeof(int));
    if (*keys == NULL) { error_flag = 1; goto cleanup; }
    for (size_t i = 0; i < key_size; ++i) {
        (*keys)[i] = i;
    }

    // Allocate and initialize records array
    *records = (record *)malloc(record_size * sizeof(record));
    if (*records == NULL) { error_flag = 1; goto cleanup; }

    for (size_t i = 0; i < record_size; ++i) {
        pthread_mutex_lock(&lock);

        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
        (*records)[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        // Allocate and initialize name string
        (*records)[i].name = (char *)malloc(11); // 10 chars + null terminator
        if ((*records)[i].name == NULL) { error_flag = 1; goto cleanup; }
        for (int j = 0; j < 10; ++j) {
            (*records)[i].name[j] = 'A' + rand() % 26;
        }
        (*records)[i].name[10] = '\0';

        pthread_mutex_unlock(&lock);
    }

cleanup:
    if (error_flag) {
        free(*offsets); *offsets = NULL;
        free(*keys); *keys = NULL;
        if (*records != NULL) {
            for (size_t i = 0; i < record_size; ++i) {
                free((*records)[i].name);
            }
            free(*records); *records = NULL;
        }
    }
}

void deallocate_memory(long *offsets, int *keys, record *records, size_t record_size) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        for (size_t i = 0; i < record_size; ++i) {
            free(records[i].name);
        }
        free(records);
    }
}
