    pthread_mutex_lock(&pm->lock);

    if (pm->capacity >= MAX_PACKETS) {
        log_packet_action("Add failed: Capacity reached");
        pthread_mutex_unlock(&pm->lock);
        return -1;
    }

    // Increment version number for new packet
