    // Add to list
    node->next = pm->head;
    pm->head = node;

    log_packet_action("Packet added");

    pthread_mutex_unlock(&pm->lock);
    return 0;
}

DataPacket* packet_manager_get(PacketManager* pm, uint32_t id, uint8_t version) {
    pthread_mutex_lock(&pm->lock);

    PacketNode* current = pm->head;
    while (current) {
        if (current->packet.id == id && current->packet.version == version) {
            log_packet_action("Packet retrieved");
            pthread_mutex_unlock(&pm->lock);
            return &current->packet;
        }
        current = current->next;
    }

    log_packet_action("Get failed: Packet not found");
    pthread_mutex_unlock(&pm->lock);
    return NULL;
}

int packet_manager_update(PacketManager* pm, uint32_t id) {
    pthread_mutex_lock(&pm->lock);

    PacketNode* current = pm->head;
    while (current) {
        if (current->packet.id == id) {
            // Increment version number
            current->packet.version++;

            compress_and_encrypt_data(&current->packet, pm->encryption_key);
            log_packet_action("Packet updated");

            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
        current = current->next;
    }

    log_packet_action("Update failed: Packet not found");
    pthread_mutex_unlock(&pm->lock);
    return -1;
}

void purge_expired_packets(PacketManager* pm) {
    time_t now = time(NULL);

    pthread_mutex_lock(&pm->lock);

    PacketNode *current = pm->head, *prev = NULL;
    while (current) {
        if (now - current->packet.timestamp > pm->expiration_threshold) {
            PacketNode* to_delete = current;
            current = current->next;

            if (prev) {
                prev->next = current;
            } else {
                pm->head = current;
            }

            free(to_delete);
            log_packet_action("Expired packet purged");
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&pm->lock);
}

void adjust_expiration_threshold(PacketManager* pm, time_t new_threshold) {
    pthread_mutex_lock(&pm->lock);
    pm->expiration_threshold = new_threshold;
    log_packet_action("Expiration threshold adjusted");
    pthread_mutex_unlock(&pm->lock);
}

void packet_manager_init(PacketManager* pm, size_t capacity, time_t expiration_threshold, int rate_limit, void (*log_callback)(const char*)) {
    pm->head = NULL;
    pm->capacity = capacity;
    pm->expiration_threshold = expiration_threshold;
    pm->rate_limit = rate_limit;
    pm->log_action = log_callback;

