    for (int i = 0; i < 16; ++i) {
        pm->encryption_key[i] = new_key[i];
    }

    log_packet_action("Encryption key rotated");
    pthread_mutex_unlock(&pm->lock);
}

void shutdown_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);

    // Clear sensitive data
    for (int i = 0; i < 16; ++i) {
        pm->encryption_key[i] = 0;
    }

