typedef struct {
    char ENODEB_ID[32];
    int MME_CODE;
    int MNC;
} GUMMEI;

typedef struct {
    char PLMN_ID[5]; // e.g., "310260" for AT&T USA
} PLMNID;

typedef struct {
    char ENODEB_ID[32];
    GUMMEI GUMMEI;
    PLMNID* PLMNs;
    size_t PLMN_count;
} LTE_ENBCONTEXT_CONFIGURE_REQUEST_T;

typedef struct Node {
    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for dynamic list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->size = 0;

    // Log creation
    printf("[INFO] DynamicList created with capacity %zu\n", initial_capacity);

    return list;
}

void free_node(Node* node) {
    if (node) {
        free(node->data.PLMNs);
        free(node);
    }
}

bool insert_unique_gummei(DynamicList* list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T new_entry) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (strcmp(current->data.ENODEB_ID, new_entry.ENODEB_ID) == 0 &&
            current->data.GUMMEI.MME_CODE == new_entry.GUMMEI.MME_CODE &&
            current->data.GUMMEI.MNC == new_entry.GUMMEI.MNC) {

            pthread_mutex_unlock(&list->lock);
            // Log duplicate GUMMEI
            printf("[ERROR] Duplicate GUMMEI found. Entry not added.\n");
            return false;
        }
        current = current->next;
    }

    if (list->size >= list->capacity && list->capacity < MAX_CAPACITY) {
        list->capacity *= 2;
        // Log resizing
        printf("[INFO] Resizing dynamic list to capacity %zu\n", list->capacity);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        perror("Failed to allocate memory for new node");
        return false;
    }

    memcpy(&new_node->data, &new_entry, sizeof(LTE_ENBCONTEXT_CONFIGURE_REQUEST_T));
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // Log insertion
    printf("[INFO] New entry inserted. Total size: %zu\n", list->size);

    pthread_mutex_unlock(&list->lock);
    return true;
}

void delete_entry(DynamicList* list, const char* enodeb_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (strcmp(current->data.ENODEB_ID, enodeb_id) == 0) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free_node(current);
            list->size--;

            // Log deletion
            printf("[INFO] Entry deleted. Total size: %zu\n", list->size);

            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void batch_insert(DynamicList* list, LTE_ENBCONTEXT_CONFIGURE_REQUEST_T entries[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        insert_unique_gummei(list, entries[i]);
    }
}

void cleanup_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);

    // Log cleanup
    printf("[INFO] DynamicList cleaned up and destroyed\n");
}

void garbage_collection(DynamicList* list) {
