    pthread_mutex_lock(&list->lock);

    // Actual garbage collection logic goes here

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList* list = create_dynamic_list(INITIAL_CAPACITY);

    if (!list) return EXIT_FAILURE;

    LTE_ENBCONTEXT_CONFIGURE_REQUEST_T example_entry = {
        .ENODEB_ID = "ENB1234",
        .GUMMEI = { .MME_CODE = 1, .MNC = 02 },
        .PLMN_count = 2,
        .PLMNs = malloc(2 * sizeof(PLMNID))
    };

    if (!example_entry.PLMNs) {
        perror("Failed to allocate memory for PLMNs");
        cleanup_dynamic_list(list);
        return EXIT_FAILURE;
    }

    strcpy(example_entry.PLMNs[0].PLMN_ID, "310260");
    strcpy(example_entry.PLMNs[1].PLMN_ID, "311012");

    insert_unique_gummei(list, example_entry);

    // Cleanup and exit
