        frames[i].payload = payload;

        pthread_mutex_unlock(&lock);

        log_message(log_level, "MAC frame created and checksum verified.");
    }

    // Validate device
    int retries = 3;
    while (!is_device_supported_and_enabled(device) && retries > 0) {
        log_message(WARN, "Device not supported or disabled. Retrying...");
        --retries;
    }

    if (retries == 0) {
        free(frames);
        log_message(log_level, "Failed to validate device after multiple attempts.");
        return NULL;
    }

    // Measure latency and adjust buffer size
    unsigned int current_latency = measure_latency(device);
    if (current_latency > LATENCY_THRESHOLD) {
        adjust_buffer_size(&N, current_latency);
        log_message(INFO, "Buffer size adjusted based on latency measurement.");
    }

    pthread_mutex_destroy(&lock);

    return frames;
}

void free_mac_frames(MAC_FRAME_T* frames) {
    free(frames);
}
```

This implementation covers dynamic memory allocation for `MAC_FRAME_T` structures, checksum calculation, device validation with retries, latency measurement and buffer size adjustment, logging at various steps, and synchronization using a mutex to handle potential race conditions in a multi-threaded environment. Additionally, it includes error handling for memory allocation failures.']

