#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PRODUCTS 1000

typedef struct {
    int id;
    char name[50];
    int quantity;
    double price;
} Product;

Product inventory[MAX_PRODUCTS];
pthread_mutex_t mutexes[MAX_PRODUCTS];

// Simulated external product database service
void fetch_product_data(int index, char **name, double *price) {
    // Dummy data fetching logic
    const char *names[] = {"ProductA", "ProductB", "ProductC"};
    double prices[] = {10.99, 15.49, 7.89};

    if (index < sizeof(names) / sizeof(char*)) {
        *name = strdup(names[index]);
        *price = prices[index];
    } else {
        *name = strdup("Unknown");
        *price = 0.0;
    }
}

void initialize_inventory(int num_products) {
    for (int i = 0; i < num_products && i < MAX_PRODUCTS; ++i) {
        inventory[i].id = i;
        char *name;
        double price;

        fetch_product_data(i, &name, &price);

        strcpy(inventory[i].name, name);
        free(name); // Free allocated memory
        inventory[i].quantity = 0;
        inventory[i].price = price;

        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void update_product(int index, int quantity, double price) {
    if (index < MAX_PRODUCTS && index >= 0) {
        pthread_mutex_lock(&mutexes[index]);

        if (inventory[index].quantity != -1 || inventory[index].price != -1.0) { // Check for valid state
            inventory[index].quantity = quantity;
            inventory[index].price = price;
        }

        pthread_mutex_unlock(&mutexes[index]);
    }
}

void free_resources() {
    for (int i = 0; i < MAX_PRODUCTS; ++i) {
        if (pthread_mutex_trylock(&mutexes[i]) == 0) {
            pthread_mutex_unlock(&mutexes[i]); // Ensure it's unlocked
            pthread_mutex_destroy(&mutexes[i]);
        }
    }
}

int main() {
    int num_products = 3;
    initialize_inventory(num_products);

    update_product(1, 100, 20.99);
    printf("Product %d: %s, Quantity: %d, Price: %.2f\n", inventory[1].id, 
           inventory[1].name, inventory[1].quantity, inventory[1].price);

    free_resources();
    return 0;
}
```

### Key Points:

- **Fixed-size Array**: The system uses a fixed-size array for product storage. This choice simplifies memory management and reduces overhead compared to dynamic structures like linked lists.

- **Concurrency Handling**: Each product has an associated mutex to manage concurrent access, ensuring thread safety during updates.

- **Memory Management**: Proper allocation and deallocation of resources are handled to avoid leaks. The `strdup` function is used for string copying from the simulated database service.

- **Error Handling**: Basic error handling is implemented to ensure that operations only proceed if valid indices are accessed.

### Performance Considerations:

- **Execution Speed**: Using a fixed-size array provides constant-time access to elements, which is efficient for both reads and writes.

- **Memory Usage**: Fixed-size arrays can lead to wasted memory if the number of products is much less than `MAX_PRODUCTS`, but they offer predictable performance characteristics.

- **Concurrency**: Mutexes ensure data integrity in multi-threaded environments but introduce some overhead. This trade-off is acceptable given the need for thread safety.

This implementation provides a scalable, efficient inventory management system with considerations for concurrency and memory usage.']

