config *load_configurations(const char *directory_path, struct summary **summary) {
    DIR *dir = opendir(directory_path);
    if (!dir) {
        log_error("Failed to open directory");
        return NULL;
    }

    config *configs = NULL;
    size_t count = 0;

    pthread_t threads[1024];
    char **file_paths = malloc(1024 * sizeof(char *));
    int thread_count = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            size_t path_len = strlen(directory_path) + strlen(entry->d_name) + 2;
            char *file_path = malloc(path_len);
            snprintf(file_path, path_len, "%s/%s", directory_path, entry->d_name);

            if (thread_count < 1024) {
                file_paths[thread_count] = file_path;
                pthread_create(&threads[thread_count], NULL, load_file, &file_paths[thread_count]);
                thread_count++;
            } else {
                log_error("Exceeded maximum number of concurrent threads");
                free(file_path);
            }
        }
    }

    closedir(dir);

    for (int i = 0; i < thread_count; ++i) {
        config *cfg;
        pthread_join(threads[i], (void **)&cfg);
        if (cfg) {
            configs = realloc(configs, (count + 1) * sizeof(config));
            configs[count++] = *cfg;
            free(cfg); // Free the individual config as it's now copied
        }
    }

    free(file_paths);

    struct summary *summary_struct = malloc(sizeof(struct summary));
    if (!summary_struct) {
        log_error("Failed to allocate memory for summary");
        free_configurations(configs, count, NULL);
        return NULL;
    }

    summary_struct->doubles_count = 0;
    summary_struct->strings_count = 0;
    summary_struct->records_count = 0;
    summary_struct->metadatas_count = 0;
    summary_struct->configs_count = count;

    for (size_t i = 0; i < count; ++i) {
        summary_struct->doubles_count += 10; // Example size
        summary_struct->strings_count += 5; // Example size
        summary_struct->records_count += 3; // Example size
        summary_struct->metadatas_count += 2; // Example size
    }

    *summary = summary_struct;
    return configs;
}

// Function to free all allocated memory for configurations
