    if (!configs || !count) return;

    for (size_t i = 0; i < count; ++i) {
        if (configs[i].doubles) free(configs[i].doubles);
        if (configs[i].strings) {
            for (size_t j = 0; j < configs[i].count / 3; ++j) { // Example size
