#define MAX_MEMORY_USAGE 1048576 // 1 MB

typedef struct {
    int field;
    long offset;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t num_offsets;
    size_t num_keys;
    long *offsets;
    int *keys;
    record *records;
    u_char *ip_address;
    int error_flag;
} memory_manager;

void log_error(const char *message) {
    perror(message);
}

size_t calculate_memory_usage(size_t num_offsets, size_t num_keys, size_t num_records) {
    return sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_records;
}

int dns_resolution(memory_manager *mgr, const char *hostname) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_error("DNS resolution failed");
        mgr->error_flag = 1;
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *) res->ai_addr;
    mgr->ip_address = malloc(sizeof(u_char) * INET_ADDRSTRLEN);
    if (!mgr->ip_address) {
        log_error("Memory allocation failed for IP address");
        mgr->error_flag = 1;
        freeaddrinfo(res);
        return -1;
    }

    snprintf((char *) mgr->ip_address, INET_ADDRSTRLEN, "%s",
             inet_ntoa(ipv4->sin_addr));

    freeaddrinfo(res);
    return 0;
}

memory_manager *initialize_memory_manager(size_t num_offsets, size_t num_keys, size_t num_records) {
    memory_manager *mgr = malloc(sizeof(memory_manager));
    if (!mgr) {
        log_error("Memory allocation failed for manager");
        return NULL;
    }

    pthread_mutex_init(&mgr->mutex, NULL);
    mgr->num_offsets = num_offsets;
    mgr->num_keys = num_keys;
    mgr->records = malloc(sizeof(record) * num_records);
    mgr->offsets = malloc(sizeof(long) * num_offsets);
    mgr->keys = malloc(sizeof(int) * num_keys);
    mgr->ip_address = NULL;

    if (!mgr->records || !mgr->offsets || !mgr->keys) {
        log_error("Memory allocation failed");
        pthread_mutex_destroy(&mgr->mutex);
        free(mgr->records);
        free(mgr->offsets);
        free(mgr->keys);
        free(mgr);
        return NULL;
    }

    mgr->error_flag = 0;

    // Initialize arrays
    for (size_t i = 0; i < num_offsets; ++i) {
        mgr->offsets[i] = i;
    }
    for (size_t i = 0; i < num_keys; ++i) {
        mgr->keys[i] = i;
    }

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        mgr->records[i].offset = rand() % num_offsets; // Example, replace with appropriate logic
        mgr->records[i].field = rand() % 2001 - 1000;
    }

    return mgr;
}

void deallocate_memory_manager(memory_manager *mgr) {
    if (pthread_mutex_lock(&mgr->mutex)) {
        log_error("Mutex lock failed");
        return;
    }

    if (mgr->offsets) free(mgr->offsets);
    if (mgr->keys) free(mgr->keys);
    if (mgr->records) free(mgr->records);
    if (mgr->ip_address) free(mgr->ip_address);

    pthread_mutex_unlock(&mgr->mutex);
    pthread_mutex_destroy(&mgr->mutex);
    free(mgr);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const size_t num_offsets = 100;
    const size_t num_keys = 50;
    const size_t num_records = 30;

    memory_manager *mgr = initialize_memory_manager(num_offsets, num_keys, num_records);
    if (!mgr || calculate_memory_usage(num_offsets, num_keys, num_records) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Failed to initialize memory manager or memory limit exceeded\n");
        return EXIT_FAILURE;
    }

    if (dns_resolution(mgr, argv[1])) {
        fprintf(stderr, "DNS resolution failed\n");
        deallocate_memory_manager(mgr);
        return EXIT_FAILURE;
    }

    printf("IP Address: %s\n", mgr->ip_address);

    deallocate_memory_manager(mgr);
    return EXIT_SUCCESS;
}
```

