```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure types as per your application needs.
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef unsigned long RX_UE_INFORMATION_TAG; // Assuming it's a type alias.

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the dynamic list structure with a mutex for concurrency control.
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI
    Node* current = list->head;
    while (current) {
        if (current->data.rnti == element.rnti) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate found, do not add.
        }
        current = current->next;
    }

    // Add new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1; // Element added successfully.
}

int remove_element(CRCList* list, unsigned long rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Not found
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    if (prev == NULL) {
        list->head = current->next; // Remove head
    } else {
        prev->next = current->next; // Bypass the node to remove
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void print_list(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RNTI: %lu, CRCFLAG: %d\n", current->data.rnti, current->data.crc_ind_rel8_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example unit tests
void run_tests() {
    // Test creation and destruction of list
    CRCList* list = create_list();
    assert(list != NULL);

    NFAPI_CRC_INDICATION_PDU_T element1 = { .ue_info_tag = 123, .rnti = 456, .crc_ind_rel8_tag = {.CRCFLAG = 1} };
    add_element(list, element1);

    // Test adding duplicate
    assert(add_element(list, element1) == 0);

    NFAPI_CRC_INDICATION_PDU_T element2 = { .ue_info_tag = 789, .rnti = 101112, .crc_ind_rel8_tag = {.CRCFLAG = 0} };
    add_element(list, element2);

    // Test removing element
    assert(remove_element(list, 456) == 1); 
    assert(remove_element(list, 9999) == 0); 

    // Print list to verify contents
    print_list(list);

    // Clean up
    destroy_list(list);
}

int main() {
    run_tests();
    return 0;
}
```

### Key Points:
- **Concurrency**: The `pthread_mutex_t` lock ensures thread safety for concurrent access.
- **Memory Management**: Proper allocation and deallocation are handled to avoid leaks. 
- **Usability**: Functions provide a clear API for list operations, allowing easy extension.
- **Scalability**: Designed to handle dynamic growth efficiently.

This code provides a robust foundation for managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures while ensuring data integrity and safe memory management.']

