    int N;       // Number of elements
    unsigned int seed; // Seed for random number generator
} Config;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to estimate available system memory (stub implementation)
size_t get_available_memory() {
    return 1024 * 1024 * 1024; // Assume 1GB available for simplicity
}

// Function to log messages
void log_message(const char* message) {
    printf("%s\n", message);
}

int create_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list, Config* config) {
    if (config->N < 1 || config->N > MAX_ELEMENTS) {
        log_message("Invalid number of elements. Must be between 1 and 1000.");
        return -1;
    }

    pthread_mutex_lock(&lock);

    size_t available_memory = get_available_memory();
    size_t max_allocatable_memory = (available_memory * MAX_MEMORY_PERCENTAGE) / 100;

    // Calculate memory required for the list
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = config->N * element_size;

    if (total_memory_required > max_allocatable_memory) {
        log_message("Memory limit exceeded. Adjusting number of elements.");
        int reduced_elements = (int)(max_allocatable_memory / element_size);
        if (reduced_elements < 1) {
            pthread_mutex_unlock(&lock);
            return -2;
        }
        config->N = reduced_elements;
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(config->N * element_size);
    if (*list == NULL) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return -3;
    }

    srand(config->seed);

    for (int i = 0; i < config->N; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand(); // Randomly populate
        (*list)[i].RNTI = rand() & 0xFFFF;
        (*list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    }

    pthread_mutex_unlock(&lock);
    log_message("List created successfully.");
    return 0;
}

// Cleanup function
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
