['Below is a simplified C implementation of an inventory management system that meets the outlined requirements. This code uses threads, mutexes for synchronization, dynamic memory allocation, and linked lists to manage products efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Product structure definition
typedef struct {
    int id;
    char name[50];
    float price;
    int quantity;
} Product;

// Node for linked list
typedef struct ProductNode {
    Product product;
    struct ProductNode* next;
} ProductNode;

// Inventory system structure
typedef struct {
    ProductNode* head;
    pthread_mutex_t lock;
} InventorySystem;

// Function prototypes
void init_inventory(InventorySystem *inventory, int initial_size);
Product* add_product(InventorySystem *inventory, const char *name, float price, int quantity);
Product* find_product_by_id(InventorySystem *inventory, int id);
int remove_product(InventorySystem *inventory, int id);
void update_quantity_and_price(Product *product, int delta_quantity, float new_price, void (*callback)(int, float));
void search_products(InventorySystem *inventory, const char *search_name);
void free_inventory(InventorySystem *inventory);

// Callback function prototype
void example_callback(int quantity_change, float price_change) {
    printf("Callback: Quantity changed by %d, Price changed by %.2f\n", quantity_change, price_change);
}

int main() {
    InventorySystem inventory;
    pthread_mutex_init(&inventory.lock, NULL);
    init_inventory(&inventory, 5);

    // Simulate adding products
    add_product(&inventory, "ProductA", 10.99, 100);
    add_product(&inventory, "ProductB", 20.49, 200);

    // Example of updating a product's quantity and price
    ProductNode *node = inventory.head;
    while (node != NULL && node->product.id == 1) {
        update_quantity_and_price(&(node->product), -10, 11.99, example_callback);
        break;
    }

    // Search for a product by name
    search_products(&inventory, "ProductA");

    // Clean up
    free_inventory(&inventory);
    pthread_mutex_destroy(&inventory.lock);

    return 0;
}

void init_inventory(InventorySystem *inventory, int initial_size) {
    inventory->head = NULL;

    for (int i = 0; i < initial_size; ++i) {
        ProductNode* new_node = malloc(sizeof(ProductNode));
        if (!new_node) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        // Simulate fetching name and price from external service
        snprintf(new_node->product.name, sizeof(new_node->product.name), "Product%d", i+1);
        new_node->product.price = 5.0 * (i + 1);
        new_node->product.quantity = 0;
        new_node->product.id = i;
        new_node->next = inventory->head;
        inventory->head = new_node;
    }
}

Product* add_product(InventorySystem *inventory, const char *name, float price, int quantity) {
    pthread_mutex_lock(&inventory->lock);

    ProductNode* new_node = malloc(sizeof(ProductNode));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&inventory->lock);
        return NULL;
    }

    strcpy(new_node->product.name, name);
    new_node->product.price = price;
    new_node->product.quantity = quantity;
    new_node->product.id = (inventory->head ? inventory->head->product.id : 0) + 1;

    new_node->next = inventory->head;
    inventory->head = new_node;

    pthread_mutex_unlock(&inventory->lock);
    return &new_node->product;
}

Product* find_product_by_id(InventorySystem *inventory, int id) {
    pthread_mutex_lock(&inventory->lock);

    ProductNode* current = inventory->head;
    while (current != NULL) {
        if (current->product.id == id) {
            pthread_mutex_unlock(&inventory->lock);
            return &current->product;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&inventory->lock);
    return NULL;
}

int remove_product(InventorySystem *inventory, int id) {
    pthread_mutex_lock(&inventory->lock);

    ProductNode* current = inventory->head;
    ProductNode* prev = NULL;

    while (current != NULL && current->product.id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&inventory->lock);
        return 0;
    }

    if (prev == NULL) {
        inventory->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&inventory->lock);
    return 1;
}

void update_quantity_and_price(Product *product, int delta_quantity, float new_price, void (*callback)(int, float)) {
    product->quantity += delta_quantity;
    float price_change = new_price - product->price;
    product->price = new_price;

    callback(delta_quantity, price_change);
}

void search_products(InventorySystem *inventory, const char *search_name) {
    pthread_mutex_lock(&inventory->lock);

    ProductNode* current = inventory->head;
    while (current != NULL) {
        if (strstr(current->product.name, search_name)) {
            printf("Product found: ID=%d, Name=%s, Price=%.2f, Quantity=%d\n",
                   current->product.id, current->product.name,
                   current->product.price, current->product.quantity);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&inventory->lock);
}

void free_inventory(InventorySystem *inventory) {
    ProductNode* current = inventory->head;
    while (current != NULL) {
        ProductNode* next_node = current->next;
        free(current);
        current = next_node;
    }
}
```

### Key Features:
- **Thread Safety**: Uses mutexes to ensure thread-safe operations on the inventory.
- **Dynamic Memory Management**: Uses linked lists for dynamic resizing, allowing efficient addition and removal of products.
- **Concurrency Handling**: The `pthread_mutex` is used to protect shared resources against race conditions.
- **Callback Functionality**: Demonstrates how to update product attributes with a callback function.
- **Product Search**: Allows searching by product name.

### Trade-offs:
- **Linked List vs. Array**: Linked lists provide flexibility for dynamic resizing, but at the cost of additional overhead compared to arrays (e.g., pointer chasing).
- **Concurrency Overhead**: Mutexes ensure safety but may introduce contention and reduce performance under high concurrency.
- **Memory Management**: Dynamic allocation requires careful management to avoid leaks; freeing resources is handled in `free_inventory`.

This code provides a scalable foundation for an inventory system, focusing on maintainability, scalability, and thread safety. Further enhancements could include integrating with external services using asynchronous I/O or network libraries like `libcurl` for product data retrieval, and implementing more advanced search and reporting features.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the record structure
typedef struct Record {
    int key;
    int value;
    char metadata[256];
} Record;

// Define the node for linked list
typedef struct Node {
    long offset;
    struct Node* next;
} Node;

// Function prototypes
void initialize_records(Record** records, int keys[], long offsets[], int size, int range);
void validate_integrity(Node* head);

// Thread-safe function to manage records in a linked list
Node* manage_dynamic_records(int key_array_size, int offset_array_size, int record_array_size, 
                             int key_range, Node* head) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Arrays for keys, offsets, and records
    int* keys = (int*)malloc(key_array_size * sizeof(int));
    long* offsets = (long*)malloc(offset_array_size * sizeof(long));
    Record** records = (Record**)malloc(record_array_size * sizeof(Record*));

    if (!keys || !offsets || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize keys and offsets with random values
    for (int i = 0; i < key_array_size; ++i) {
        keys[i] = rand() % key_range;
    }
    for (long i = 0; i < offset_array_size; ++i) {
        offsets[i] = i * sizeof(Record);
    }

    // Initialize records
    initialize_records(records, keys, offsets, record_array_size, key_range);

    // Insertion into linked list with thread safety
    pthread_mutex_lock(&lock);
    Node* current = head;
    for (int i = 0; i < record_array_size; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        new_node->offset = offsets[i];
        new_node->next = current;
        current = new_node;
    }
    pthread_mutex_unlock(&lock);

    // Validate the integrity of the linked list
    validate_integrity(head);

    free(keys);
    free(offsets);
    for (int i = 0; i < record_array_size; ++i) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);

    pthread_mutex_destroy(&lock);

    return head;
}

// Helper function to initialize records
void initialize_records(Record** records, int keys[], long offsets[], int size, int range) {
    for (int i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        records[i]->key = keys[i];
        records[i]->value = rand() % range;
        snprintf(records[i]->metadata, sizeof(records[i]->metadata), "Metadata for key %d", records[i]->key);
    }
}

// Helper function to validate the integrity of the linked list
void validate_integrity(Node* head) {
    Node* current = head;
    while (current != NULL && current->next != NULL) {
        if (current->offset >= current->next->offset) {
            fprintf(stderr, "Linked list integrity violation\n");
            break;
        }
        current = current->next;
    }
}
```

This code provides a C function to manage records using a linked list with thread safety. It initializes arrays for keys and offsets, creates record structures, and inserts them into the linked list while ensuring data integrity and handling potential race conditions using mutex locks.']

["```javascript
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

// Simple in-memory cache (for demonstration purposes)
let cache = {};

async function getConfig(url) {
    try {
        const response = await axios.get(url);
        return response.data; // Assumes the config is a JSON array of directory paths
    } catch (error) {
        console.error(`Error fetching configuration: ${error.message}`);
        throw error;
    }
}

async function readFilesByExtension(directories, extensionFilter) {
    const tasks = directories.map(async (directory) => {
        try {
            const files = await getDirectoryContents(directory);
            return filterAndReadFiles(files, directory, extensionFilter);
        } catch (error) {
            console.error(`Error reading directory ${directory}: ${error.message}`);
            return [];
        }
    });

    const results = await Promise.all(tasks);
    return results.flat();
}

async function getDirectoryContents(directory) {
    try {
        const entries = await fs.readdir(directory, { withFileTypes: true });
        return Promise.all(entries.map((entry) => path.join(directory, entry.name)));
    } catch (error) {
        console.error(`Error reading directory contents: ${error.message}`);
        throw error;
    }
}

async function filterAndReadFiles(files, directory, extensionFilter) {
    const filteredFiles = files.filter(file => file.endsWith(extensionFilter));

    // Check cache
    const cachedResults = filteredFiles.map(file => 
        cache[file] ? { path: file, content: cache[file] } : null
    ).filter(Boolean);

    const remainingFiles = filteredFiles.filter(file => !cache[file]);

    if (remainingFiles.length > 0) {
        try {
            const readTasks = remainingFiles.map(async (file) => {
                try {
                    const content = await fs.readFile(file, 'utf-8');
                    cache[file] = content; // Update cache
                    return { path: file, content };
                } catch (error) {
                    console.error(`Error reading file ${file}: ${error.message}`);
                }
            });

            const results = await Promise.all(readTasks);
            cachedResults.push(...results.filter(Boolean));
        } catch (error) {
            console.error(`Error processing files in directory: ${error.message}`);
        }
    }

    return cachedResults;
}

async function loadAndProcessFiles(configUrl, extensionFilter) {
    try {
        const directories = await getConfig(configUrl);
        if (!Array.isArray(directories)) {
            throw new Error('Configuration should be an array of directory paths');
        }
        const filesData = await readFilesByExtension(directories, `.${extensionFilter}`);

        // Output or process the collected file data as needed
        console.log(filesData);

    } catch (error) {
        console.error(`Error loading and processing files: ${error.message}`);
    }
}

// Example usage:
const configServiceUrl = 'https://example.com/config';  // Replace with actual URL
loadAndProcessFiles(configServiceUrl, 'txt');  // Filter for .txt files

module.exports = { loadAndProcessFiles };
