#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define the structures
typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Configuration structure
typedef struct {
    size_t N;                  // Number of elements in the list
    uint32_t seed;             // Seed for random number generation
    int use_seed;              // Flag to determine if a seed should be used (1) or not (0)
} Config;

#define MAX_N 1000

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to get available memory - placeholder function
size_t get_available_memory() {
    return 1024 * 1024 * 1024; // Assume 1GB of free memory for example
}

void* populate_list(void* config_ptr) {
    Config* config = (Config*)config_ptr;

    if (config->N < 1 || config->N > MAX_N) {
        printf("Warning: N is out of bounds. Adjusting to max supported value.\n");
        config->N = config->N < 1 ? 1 : MAX_N;
    }

    // Limit memory usage to 50% of available system memory
    size_t max_memory_usage = get_available_memory() / 2;

    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&mutex);

    while (config->N * element_size > max_memory_usage) {
        printf("Memory pressure detected. Reducing list size.\n");
        config->N /= 2; // Reduce the list size by half if memory limit is exceeded
    }

    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(config->N * element_size);
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Seed random number generator if required
    if (config->use_seed && config->seed != 0) {
        srand(config->seed);
    } else {
        srand((unsigned int)time(NULL)); // Use current time as seed for randomness
    }

    for (size_t i = 0; i < config->N; ++i) {
        list[i].ue_info_tag.RNTI = rand() % UINT16_MAX;
        list[i].rnti = rand() % UINT16_MAX;

        if (config->use_seed && config->seed != 0) {
            // Generate CRCFLAG using a seeded RNG for reproducibility
            list[i].crc_indication_rel8.CRCFLAG = (rand() % 2);
        } else {
            // Use unseeded randomness
            list[i].crc_indication_rel8.CRCFLAG = (rand() & 1);
        }
    }

    pthread_mutex_unlock(&mutex);

    return list;
}

// Function to free allocated memory
void free_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}

int main(int argc, char** argv) {
    Config config = {500, 42, 1}; // Example configuration

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)populate_list(&config);

    if (list) {
        printf("List populated successfully with %zu elements.\n", config.N);
        free_list(list);
    }

    return 0;
}
