### Explanation:
- **Memory Management**: The function dynamically allocates memory for a list of structures and ensures that usage doesn't exceed 50% of available system memory. It reduces the size if needed.

- **Concurrency**: Uses a mutex to ensure thread safety when accessing shared resources.

- **Random Number Generation**: Allows initialization using a seed or defaults to randomness based on current time, providing options for reproducibility.

- **Edge Case Handling**: Limits `N` within bounds and adjusts in response to memory pressure.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define BUFFER_SIZE 256
#define MAX_RECORDS 1000

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
    double timestamp;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t total_records;
    size_t max_records;
} CollectionManager;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int resolve_hostname(const char* hostname, u_char* ip_buffer) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        log_error("DNS resolution failed");
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip_buffer, INET_ADDRSTRLEN);
    freeaddrinfo(res);

    return 0;
}

void initialize_collections(CollectionManager* cm, size_t size) {
    if (cm == NULL || size > MAX_RECORDS) {
        log_error("Invalid parameters for collection initialization");
        return;
    }

    cm->max_records = size;
    cm->total_records = 0;

    cm->offsets = malloc(size * sizeof(long));
    cm->keys = malloc(size * sizeof(int));
    cm->records = malloc(size * sizeof(Record));

    if (cm->offsets == NULL || cm->keys == NULL || cm->records == NULL) {
        log_error("Memory allocation failed for collections");
        free(cm->offsets);
        free(cm->keys);
        free(cm->records);
        return;
    }
}

void cleanup_collections(CollectionManager* cm) {
    if (cm != NULL) {
        free(cm->offsets);
        free(cm->keys);
        free(cm->records);
    }
}

int add_record(CollectionManager* cm, int key, const char* charset) {
    if (cm == NULL || cm->total_records >= cm->max_records) {
        log_error("Cannot add more records: collection is full or invalid");
        return -1;
    }

    int index = cm->total_records++;
    cm->keys[index] = key;

    Record *record = &cm->records[index];
    record->value = rand() % 100; // Example range [0, 99]

    for (int i = 0; i < BUFFER_SIZE - 1; ++i) {
        record->buffer[i] = charset[rand() % strlen(charset)];
    }
    record->buffer[BUFFER_SIZE - 1] = '\0';

    time_t current_time;
    time(&current_time);
    struct tm *local_time = localtime(&current_time);
    if (local_time == NULL) {
        log_error("Failed to get local time");
        return -1;
    }

    record->timestamp = difftime(time(NULL), mktime(local_time));

    cm->offsets[index] = index; // Example offset

    return 0;
}

int serialize_to_file(const CollectionManager* cm, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        log_error("Failed to open file for serialization");
        return -1;
    }

    size_t written = fwrite(cm->offsets, sizeof(long), cm->total_records, file);
    if (written != cm->total_records) {
        log_error("Serialization failed: offset array write error");
        fclose(file);
        return -1;
    }

    written = fwrite(cm->keys, sizeof(int), cm->total_records, file);
    if (written != cm->total_records) {
        log_error("Serialization failed: keys array write error");
        fclose(file);
        return -1;
    }

    written = fwrite(cm->records, sizeof(Record), cm->total_records, file);
    if (written != cm->total_records) {
        log_error("Serialization failed: records array write error");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int deserialize_from_file(CollectionManager* cm, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        log_error("Failed to open file for deserialization");
        return -1;
    }

    size_t read = fread(cm->offsets, sizeof(long), cm->max_records, file);
    if (read != cm->max_records) {
        log_error("Deserialization failed: offset array read error");
        fclose(file);
        return -1;
    }

    read = fread(cm->keys, sizeof(int), cm->max_records, file);
    if (read != cm->max_records) {
        log_error("Deserialization failed: keys array read error");
        fclose(file);
        return -1;
    }

    read = fread(cm->records, sizeof(Record), cm->max_records, file);
    if (read != cm->max_records) {
        log_error("Deserialization failed: records array read error");
        fclose(file);
        return -1;
    }

    cm->total_records = read; // Update total records after successful deserialization

    fclose(file);
    return 0;
}

int main() {
    CollectionManager manager;
    initialize_collections(&manager, 100);

    if (add_record(&manager, 42, "abcdefghijklmnopqrstuvwxyz") != 0) {
        log_error("Failed to add record");
    }

    u_char ip_buffer[INET_ADDRSTRLEN];
    if (resolve_hostname("example.com", ip_buffer) == 0) {
        printf("IP Address: %s\n", ip_buffer);
    } else {
        log_error("Hostname resolution failed in main");
    }

    serialize_to_file(&manager, "data.bin");

    CollectionManager new_manager;
    initialize_collections(&new_manager, MAX_RECORDS);

    if (deserialize_from_file(&new_manager, "data.bin") != 0) {
        log_error("Failed to deserialize file in main");
    }

    cleanup_collections(&manager);
    cleanup_collections(&new_manager);

    return 0;
}
