#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 // 1 MB for example
#define LOG_FILE "usage.log"
#define OUTPUT_FILE "output.txt"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;

void log_usage(size_t peak_usage, size_t current_usage, int num_records) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] Peak Usage: %zu bytes, Current Usage: %zu bytes, Records: %d\n",
                ctime(&now), peak_usage, current_usage, num_records);
        fclose(log_file);
    }
}

int append_to_output_file(NFAPI_CRC_INDICATION_PDU_T *records, int count) {
    pthread_mutex_lock(&file_lock);

    FILE *output_file = fopen(OUTPUT_FILE, "a");
    if (output_file == NULL) {
        perror("Failed to open output file");
        pthread_mutex_unlock(&file_lock);
        return -1;
    }

    for (int i = 0; i < count; ++i) {
        fprintf(output_file, "RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRCFLAG: %d\n",
                records[i].RX_UE_INFORMATION_TAG,
                records[i].RNTI,
                records[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    fclose(output_file);
    pthread_mutex_unlock(&file_lock);
    return 0;
}

int manage_nfa_records(int n) {
    size_t peak_usage = 0;
    size_t current_usage = 0;

    NFAPI_CRC_INDICATION_PDU_T *records_pool = NULL;
    int record_count = 0;

    if (n <= 0 || MAX_MEMORY_BUDGET / sizeof(NFAPI_CRC_INDICATION_PDU_T) < n)
        return -1;

    records_pool = malloc(MAX_MEMORY_BUDGET);
    if (!records_pool) {
        perror("Failed to allocate memory pool");
        return -1;
    }

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *record = &records_pool[record_count];

        current_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (current_usage > peak_usage)
            peak_usage = current_usage;

        record->RX_UE_INFORMATION_TAG = rand() % 1000;
        record->RNTI = rand() % 65535;
        record->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        ++record_count;

        if (current_usage >= MAX_MEMORY_BUDGET) {
            fprintf(stderr, "Memory budget exceeded\n");
            free(records_pool);
            return -1;
        }
    }

    log_usage(peak_usage, current_usage, record_count);

    int result = append_to_output_file(records_pool, record_count);
    if (result == 0) {
        // Optionally clear records for reuse
        memset(records_pool, 0, MAX_MEMORY_BUDGET);
    } else {
        free(records_pool);
        return -1;
    }

    free(records_pool);
    return 0;
}

int main() {
    int N = 100; // Example value
    if (manage_nfa_records(N) != 0) {
        fprintf(stderr, "Failed to manage NFA records\n");
    }
    return 0;
}
