    // Calculate the simple hash of the input string.
    unsigned long md5_hash = simple_md5_hash(input_string);

    for (int i = 0; i < count; ++i) {
        indications[i].RNTI = (md5_hash + i) % 65536; // Ensure RNTI is within valid range
        indications[i].RX_UE_INFORMATION_TAG = md5_hash ^ (i * 31); // Unique tag generation
