#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int sequence_number;
    int pdcp_sn;
    char *payload_buffer;
} LTE_PDCP_SDU;

#define MAX_MEMORY_SIZE 1024 * 1024 // Example max memory size (1 MB)
#define PAYLOAD_BUFFER_SIZE 256     // Example payload buffer size
#define ERROR_STATUS -1

typedef struct {
    LTE_PDCP_SDU *records;
    int count;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* initialize_dynamic_array() {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = NULL;
    array->count = 0;
    array->current_memory_usage = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int append_record(DynamicArray *array, int sequence_number, int pdcp_sn, const char *data_pattern) {
    pthread_mutex_lock(&array->lock);

    size_t new_memory_usage = sizeof(LTE_PDCP_SDU) + PAYLOAD_BUFFER_SIZE;
    if (array->current_memory_usage + new_memory_usage > MAX_MEMORY_SIZE) {
        printf("Memory limit exceeded. Cannot append record.\n");
        pthread_mutex_unlock(&array->lock);
        return ERROR_STATUS;
    }

    LTE_PDCP_SDU *new_record = realloc(array->records, sizeof(LTE_PDCP_SDU) * (array->count + 1));
    if (!new_record) {
        printf("Memory allocation failed. Cleaning up.\n");
        free(array->records);
        array->records = NULL;
        pthread_mutex_unlock(&array->lock);
        return ERROR_STATUS;
    }

    new_record[array->count].sequence_number = sequence_number;
    new_record[array->count].pdcp_sn = pdcp_sn;
    new_record[array->count].payload_buffer = (char *)malloc(PAYLOAD_BUFFER_SIZE);
    if (!new_record[array->count].payload_buffer) {
        printf("Memory allocation for payload buffer failed. Cleaning up.\n");
        free(new_record);
        array->records = NULL;
        pthread_mutex_unlock(&array->lock);
        return ERROR_STATUS;
    }

    strncpy(new_record[array->count].payload_buffer, data_pattern, PAYLOAD_BUFFER_SIZE);

    array->records = new_record;
    array->count++;
    array->current_memory_usage += new_memory_usage;

    log_memory_usage(array);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void log_memory_usage(DynamicArray *array) {
    FILE *log_file = fopen("usage.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - Peak: %zu bytes, Current: %zu bytes, Records: %d\n",
                ctime(&now), array->current_memory_usage, array->current_memory_usage, array->count);
        fclose(log_file);
    }
}

int write_records_to_file(DynamicArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "a");
    if (!file) {
        printf("Failed to open file %s.\n", filename);
        pthread_mutex_unlock(&array->lock);
        return ERROR_STATUS;
    }

    LTE_PDCP_SDU temp_records[array->count];
    memcpy(temp_records, array->records, sizeof(LTE_PDCP_SDU) * array->count);

    // Sort records by sequence number
    for (int i = 0; i < array->count - 1; i++) {
        for (int j = i + 1; j < array->count; j++) {
            if (temp_records[i].sequence_number > temp_records[j].sequence_number) {
                LTE_PDCP_SDU tmp = temp_records[i];
                temp_records[i] = temp_records[j];
                temp_records[j] = tmp;
            }
        }
    }

    for (int i = 0; i < array->count; i++) {
        fprintf(file, "Seq: %d, PDCP SN: %d, Payload: %s\n",
                temp_records[i].sequence_number,
                temp_records[i].pdcp_sn,
                temp_records[i].payload_buffer);
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void cleanup_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->count; i++) {
        free(array->records[i].payload_buffer);
    }

    free(array->records);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Usage example
/*
int main() {
    DynamicArray *array = initialize_dynamic_array();
    if (!array) return 1;

    append_record(array, 3, 100, "PatternA");
    append_record(array, 1, 101, "PatternB");
    append_record(array, 2, 102, "PatternC");

    write_records_to_file(array, "output.txt");

    cleanup_dynamic_array(array);
    return 0;
}
*/
```']

