public class WebAppManager
{
    private static readonly SemaphoreSlim semaphore = new SemaphoreSlim(1, 1);
    private ILogger logger; // Assume dependency injection for logging framework
    private int maxRetries;
    private TimeSpan retryDelay;

    public WebAppManager(ILogger<WebAppManager> logger, int maxRetries = 3, int retryDelayMilliseconds = 1000)
    {
        this.logger = logger;
        this.maxRetries = maxRetries;
        this.retryDelay = TimeSpan.FromMilliseconds(retryDelayMilliseconds);
    }

    public async Task<string> AddAndStartWebAppAsync(string directoryPath, string siteName, string errorLogFilePath)
    {
        if (!await semaphore.WaitAsync(0))
            return null;

        try
        {
            // Verify web.config existence and cache it if needed
            var webConfigCache = GetWebConfigFile(directoryPath);
            if (webConfigCache == null) return null; // Return null if no web.config found

            // Validate directory permissions and structure
            if (!IsDirectoryWritable(directoryPath) || !ValidateDirectoryStructure(directoryPath))
                throw new UnauthorizedAccessException("Insufficient permissions or invalid directory structure.");

            var metrics = new Metrics();
            metrics.StartTime = DateTime.UtcNow;

            for (int attempt = 0; attempt < maxRetries; attempt++)
            {
                try
                {
                    await AddSiteToIISAsync(directoryPath, siteName);
                    Process process = StartWebAppProcess(siteName);

                    // Monitor site health and restart if needed
                    metrics.Duration = DateTime.UtcNow - metrics.StartTime;
                    logger.LogInformation($"Operation successful: {metrics}");
                    return $"Successfully started site: {siteName}";
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, "Error while adding or starting web application.");
                    await LogToFileAsync(errorLogFilePath, ex);

                    if (attempt < maxRetries - 1) 
                        await Task.Delay(retryDelay);
                }
            }

            return null;
        }
        finally
        {
            semaphore.Release();
        }
    }

