#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 10000
#define MAX_ITEMS_PER_NODE 1000

typedef struct item {
    double value;
    struct item *next;
} Item;

typedef struct node {
    long offset;
    int key;
    Item *items;
    size_t item_count;
    struct node *next; // For linking nodes in a list for efficient deallocation
} Node;

static Node *node_head = NULL; // Head of the linked list of allocated nodes

// Logging function to monitor memory usage and resource limits
void log_memory_usage(size_t node_count, size_t total_item_count) {
    printf("Memory Usage: %zu nodes, %zu items\n", node_count, total_item_count);
}

Node* allocate_node(long offset, int key) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }

    node->offset = offset;
    node->key = key;
    node->items = NULL;
    node->item_count = 0;
    node->next = node_head; // Insert at the head for easy reverse deallocation
    node_head = node;

    log_memory_usage(MAX_NODES - (node_head ? node_head->next : NULL), 0);

    return node;
}

Item* allocate_item(Node *node) {
    if (!node || node->item_count >= MAX_ITEMS_PER_NODE) {
        return NULL;
    }

    Item *new_item = (Item*)malloc(sizeof(Item));
    if (!new_item) {
        perror("Failed to allocate memory for item");
        return NULL;
    }

    new_item->value = rand() / (double)(RAND_MAX); // Random value initialization
    new_item->next = node->items;

    node->items = new_item;
    node->item_count++;

    log_memory_usage(MAX_NODES - (node_head ? node_head->next : NULL), node_head ? node_head->next->item_count : 0);

    return new_item;
}

void deallocate_node(Node *node) {
    if (!node) {
        return;
    }

    Item *current = node->items, *tmp;
    while (current) {
        tmp = current->next;
        free(current);
        current = tmp;
    }

    Node **tracer = &node_head;
    while (*tracer && *tracer != node) {
        tracer = &(*tracer)->next;
    }

    if (*tracer) {
        *tracer = node->next; // Remove from linked list
        free(node);

        log_memory_usage(MAX_NODES - (node_head ? node_head->next : NULL), node_head ? node_head->next->item_count : 0);
    }
}

void deallocate_all_nodes() {
    while (node_head) {
        Node *temp = node_head;
        node_head = temp->next;

        Item *current = temp->items, *tmp;
        while (current) {
            tmp = current->next;
            free(current);
            current = tmp;
        }

        free(temp);
    }

    log_memory_usage(0, 0); // All nodes deallocated
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    Node *nodes[MAX_NODES];
    size_t node_count = 0;

    // Example: Allocate some nodes and items
    while (node_count < MAX_NODES) {
        Node *new_node = allocate_node(node_count, rand());
        if (!new_node) break; // Allocation failed

        nodes[node_count++] = new_node;

        for (size_t i = 0; i < MAX_ITEMS_PER_NODE && (rand() % 2); ++i) {
            Item *new_item = allocate_item(new_node);
            if (!new_item) break; // Allocation failed
        }
    }

    // Simulate deallocation of empty nodes
    for (size_t i = 0; i < node_count; ++i) {
        if (nodes[i]->item_count == 0) { // Node is "empty"
            deallocate_node(nodes[i]);
        }
    }

    // Deallocate all remaining nodes at the end
    deallocate_all_nodes();

    return 0;
}
```

This C program manages memory for a variable number of `node` structures, each potentially containing multiple `item` structures. It uses a linked list to track allocated nodes for efficient reverse order deallocation. The logging system monitors memory usage and handles dynamic allocation failures with error messages.']

