void generate_and_manage_logs(size_t numPdus, const char* logfile);
void add_log_entry(unsigned long logID, time_t timestamp, const char* message, int severityLevel);
void update_log_entry_by_id(unsigned long logID, const char* newMessage, int newSeverityLevel);
LogEntry* get_log_entry_by_id(unsigned long logID);
int parse_and_sort_logs(const char* logfile);
void filter_logs_within_time_range(time_t start, time_t end, int minSeverity);

// Helper functions
unsigned int generate_random_number() {
    return rand();
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(size_t numPdus) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(numPdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < numPdus; ++i) {
        pdus[i].rxUEInformationTag = generate_random_number();
        pdus[i].rnti = generate_random_number();
        memset(pdus[i].crcIndicationRel8Tag, generate_random_number() % 256, sizeof(pdus[i].crcIndicationRel8Tag));
        pdus[i].crcFlag = (generate_random_number() & 1) ? 1 : 0;
    }
    return pdus;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    free(pdus);
}

// Log management functions
void add_log_entry(unsigned long logID, time_t timestamp, const char* message, int severityLevel) {
    pthread_mutex_lock(&lock);

    // Resize the logs array if necessary
    if (logCount == 0 || logs[logCount - 1].logID >= logID) {
        size_t newSize = (logCount + 1) * sizeof(LogEntry);
        LogEntry* newLogs = realloc(logs, newSize);
        if (!newLogs) {
            perror("Failed to allocate memory for logs");
            pthread_mutex_unlock(&lock);
            return;
        }
        logs = newLogs;

        logs[logCount].logID = logID;
        logs[logCount].timestamp = timestamp;
        strncpy(logs[logCount].message, message, sizeof(logs[logCount].message) - 1);
        logs[logCount].severityLevel = severityLevel;
        logCount++;
    } else {
        // Insert in sorted order
        for (size_t i = 0; i < logCount; ++i) {
            if (logs[i].logID >= logID) {
                memmove(&logs[i + 1], &logs[i], (logCount - i) * sizeof(LogEntry));
                logs[i].logID = logID;
                logs[i].timestamp = timestamp;
                strncpy(logs[i].message, message, sizeof(logs[i].message) - 1);
                logs[i].severityLevel = severityLevel;
                logCount++;
                break;
            }
        }
    }

    pthread_mutex_unlock(&lock);
}

void update_log_entry_by_id(unsigned long logID, const char* newMessage, int newSeverityLevel) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < logCount; ++i) {
        if (logs[i].logID == logID) {
            strncpy(logs[i].message, newMessage, sizeof(logs[i].message) - 1);
            logs[i].severityLevel = newSeverityLevel;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

LogEntry* get_log_entry_by_id(unsigned long logID) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < logCount; ++i) {
        if (logs[i].logID == logID) {
            LogEntry* entry = malloc(sizeof(LogEntry));
            if (entry) {
                *entry = logs[i];
            }
            pthread_mutex_unlock(&lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Parsing and sorting
int parse_and_sort_logs(const char* logfile) {
    FILE* file = fopen(logfile, "r");
    if (!file) {
        perror("Failed to open log file");
        return -1;
    }

    LogEntry entry;
    while (fscanf(file, "%lu %ld \"%[^\"]\" %d\n", &entry.logID, &entry.timestamp, entry.message, &entry.severityLevel) == 4) {
        add_log_entry(entry.logID, entry.timestamp, entry.message, entry.severityLevel);
    }

    fclose(file);

    // Sort logs based on timestamp
    qsort(logs, logCount, sizeof(LogEntry), (int (*)(const void*, const void*))strcmp);

    return 0;
}

void filter_logs_within_time_range(time_t start, time_t end, int minSeverity) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < logCount; ++i) {
        if (logs[i].timestamp >= start && logs[i].timestamp <= end && logs[i].severityLevel > minSeverity) {
            printf("Log ID: %lu, Timestamp: %ld, Message: %s, Severity: %d\n",
                   logs[i].logID, logs[i].timestamp, logs[i].message, logs[i].severityLevel);
        }
    }

    pthread_mutex_unlock(&lock);
}

// Main function
void generate_and_manage_logs(size_t numPdus, const char* logfile) {
    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T* pdus = create_pdu_array(numPdus);

    if (parse_and_sort_logs(logfile) != 0) {
        fprintf(stderr, "Error parsing log file\n");
    }

    // Example usage
    add_log_entry(1, time(NULL), "Log entry message", 5);
    update_log_entry_by_id(1, "Updated log message", 10);

    LogEntry* entry = get_log_entry_by_id(1);
    if (entry) {
        printf("Retrieved Log: ID=%lu, Message=%s, Severity=%d\n",
               entry->logID, entry->message, entry->severityLevel);
        free(entry);
    }

    filter_logs_within_time_range(time(NULL) - 3600, time(NULL), 3);

    free_pdu_array(pdus);
    free(logs);
}
