// Function to initialize the storage system
StorageSystem* init_storage_system(size_t config_array_size, int min_value, int max_value) {
    if (config_array_size == 0 || min_value > max_value) return NULL;

    StorageSystem* system = malloc(sizeof(StorageSystem));
    if (!system) return NULL;

    pthread_mutex_init(&system->mutex, NULL);

    system->array_size = config_array_size;
    system->count = 0;

    // Allocate memory for offsets and keys
    system->offsets = calloc(system->array_size, sizeof(long));
    system->keys = malloc(system->array_size * sizeof(int));

    if (!system->offsets || !system->keys) {
        free(system->offsets);
        free(system->keys);
        pthread_mutex_destroy(&system->mutex);
        free(system);
        return NULL;
    }

    // Allocate memory for records
    system->records = malloc(system->array_size * sizeof(Record));
    if (!system->records) {
        free(system->offsets);
        free(system->keys);
        pthread_mutex_destroy(&system->mutex);
        free(system);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    // Populate records with random values
    for (size_t i = 0; i < system->array_size; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && value == system->records[i-1].value);

        system->records[i].value = value;
    }

    return system;
}

// Function to resize the record array
int resize_storage_system(StorageSystem* system, size_t new_size) {
    if (!system || !new_size) return -1;

    pthread_mutex_lock(&system->mutex);

    Record* new_records = realloc(system->records, new_size * sizeof(Record));
    if (!new_records) {
        pthread_mutex_unlock(&system->mutex);
        return -1;
    }

    // Initialize the newly allocated records
    for (size_t i = system->array_size; i < new_size; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (i > 0 && value == system->records[i-1].value);

        new_records[i].value = value;
    }

    // Update the system
    system->records = new_records;
    system->array_size = new_size;

    pthread_mutex_unlock(&system->mutex);
    return 0;
}

// Function to add a record (thread-safe)
int add_record(StorageSystem* system, int min_value, int max_value) {
    if (!system || system->count >= system->array_size * RESIZE_THRESHOLD_MULTIPLIER) return -1;

    pthread_mutex_lock(&system->mutex);

    // Check if resizing is needed
    if (system->count >= system->array_size) {
        size_t new_size = system->array_size * RESIZE_THRESHOLD_MULTIPLIER;
        if (resize_storage_system(system, new_size) != 0) {
            pthread_mutex_unlock(&system->mutex);
            return -1;
        }
    }

    // Add a new record with a random value
    int value;
    do {
        value = rand() % (max_value - min_value + 1) + min_value;
    } while (system->count > 0 && value == system->records[system->count-1].value);

    system->records[system->count++].value = value;

    pthread_mutex_unlock(&system->mutex);
    return 0;
}

// Function to free the storage system
void free_storage_system(StorageSystem* system) {
    if (!system) return;

    pthread_mutex_destroy(&system->mutex);
    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system);
}
