    char description[256];
} NetworkEvent;

// Global variables for event management
NetworkEvent *eventArray = NULL;
size_t eventCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addOrUpdateEvent(NFAPI_EVENT_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);

    // Search for existing event by identifier
    for (size_t i = 0; i < eventCount; ++i) {
        if (eventArray[i].id == pdu->identifier) {
            // Update the existing event
            strncpy(eventArray[i].sourceID, "Source", sizeof(eventArray[i].sourceID));
            strncpy(eventArray[i].destinationID, "Destination", sizeof(eventArray[i].destinationID));
            snprintf(eventArray[i].description, sizeof(eventArray[i].description), 
                     "Updated Event: %s", pdu->eventType);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Allocate more memory if needed
    if (eventCount == 0 || eventArray[eventCount - 1].id != 0) {
        size_t newSize = eventCount * 2 + 10; // Initial capacity and growth strategy
        NetworkEvent *newArray = realloc(eventArray, newSize * sizeof(NetworkEvent));
        if (!newArray) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&mutex);
            return;
        }
        eventArray = newArray;
    }

    // Add new event
    eventArray[eventCount].id = pdu->identifier;
    strncpy(eventArray[eventCount].sourceID, "Source", sizeof(eventArray[eventCount].sourceID));
    strncpy(eventArray[eventCount].destinationID, "Destination", sizeof(eventArray[eventCount].destinationID));
    snprintf(eventArray[eventCount].description, sizeof(eventArray[eventCount].description), 
             "Event: %s", pdu->eventType);
    eventCount++;

    pthread_mutex_unlock(&mutex);
}

NetworkEvent* getEventById(int identifier) {
    NetworkEvent *result = NULL;
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < eventCount; ++i) {
        if (eventArray[i].id == identifier) {
            result = &eventArray[i];
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
    return result;
}

void printEventsInTimeWindow(long startTime, long endTime, const char *criteria) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < eventCount; ++i) {
        NetworkEvent *event = &eventArray[i];
        if (event->timestamp >= startTime && event->timestamp <= endTime &&
            strstr(event->description, criteria) != NULL) { // Example criterion check
            printf("Event ID: %d, Source: %s, Description: %s\n", 
                   event->id, event->sourceID, event->description);
        }
    }

    pthread_mutex_unlock(&mutex);
}

void freeResources() {
    pthread_mutex_lock(&mutex);

    if (eventArray) {
        free(eventArray);
        eventArray = NULL;
    }

    pthread_mutex_unlock(&mutex);
}

// Helper function for sorting
int compareEvents(const void *a, const void *b) {
    NetworkEvent *eventA = (NetworkEvent *)a;
    NetworkEvent *eventB = (NetworkEvent *)b;

    // Sort primarily by timestamp then by priority (if any)
    if (eventA->timestamp != eventB->timestamp) {
        return eventA->timestamp - eventB->timestamp;
    }

    // If timestamps are equal, sort by another criterion such as priority
    // Placeholder: assuming priority is an integer in the description for simplicity
    int priorityA = atoi(eventA->description + 6); // Example parse
    int priorityB = atoi(eventB->description + 6);

    return priorityA - priorityB;
}

void process_network_events(NFAPI_EVENT_PDU_T *pduStream, size_t streamSize) {
    for (size_t i = 0; i < streamSize; ++i) {
        addOrUpdateEvent(&pduStream[i]);
    }

    // Sort events based on timestamp and priority
    qsort(eventArray, eventCount, sizeof(NetworkEvent), compareEvents);

    // Further processing can be added here like filtering or categorizing
}

// Example usage
