// traffic_event.h

#ifndef TRAFFIC_EVENT_H
#define TRAFFIC_EVENT_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    int index;
    char *description;
} Measurement;

typedef struct {
    long timestamp;
    char event_type[50];
    int unique_key;
    char metadata_json[1024];
} TrafficEvent;

typedef struct Node {
    TrafficEvent data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array();
void free_dynamic_array(DynamicArray* array);
int add_traffic_event(DynamicArray* array, TrafficEvent event);
TrafficEvent* get_traffic_event_by_range(DynamicArray* array, long start_time, long end_time);
int remove_traffic_event(DynamicArray* array, int key);
void serialize_array(const DynamicArray* array, const char* filename);
DynamicArray* deserialize_array(const char* filename);

void log_performance_metrics();

#endif // TRAFFIC_EVENT_H

// traffic_event.c

#include "traffic_event.h"
#include <json-c/json.h>
#include <time.h>
#include <string.h>

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = array->tail = NULL;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_node(Node* node) {
    free(node->data.metadata_json);
    free(node->data.event_type);
    free(node->next);
    free(node->prev);
    free(node);
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_traffic_event(DynamicArray* array, TrafficEvent event) {
    if (!array || !pthread_mutex_lock(&array->lock)) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    memcpy(&new_node->data, &event, sizeof(TrafficEvent));
    new_node->next = NULL;
    new_node->prev = array->tail;

    if (array->tail) {
        array->tail->next = new_node;
    } else {
        array->head = new_node;
    }

    array->tail = new_node;
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

TrafficEvent* get_traffic_event_by_range(DynamicArray* array, long start_time, long end_time) {
    if (!array || !pthread_mutex_lock(&array->lock)) return NULL;

    Node* current = array->head;
    while (current) {
        if (current->data.timestamp >= start_time && current->data.timestamp <= end_time) {
            pthread_mutex_unlock(&array->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

int remove_traffic_event(DynamicArray* array, int key) {
    if (!array || !pthread_mutex_lock(&array->lock)) return -1;

    Node *current = array->head;
    while (current) {
        if (current->data.unique_key == key) {
            if (current->prev) current->prev->next = current->next;
            else array->head = current->next;

            if (current->next) current->next->prev = current->prev;
            else array->tail = current->prev;

            free_node(current);
            array->size--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1;
}

void serialize_array(const DynamicArray* array, const char* filename) {
    if (!array || !filename) return;

    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "[\n");

    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    while (current) {
        fprintf(file, "\t{ \"timestamp\": %ld, \"event_type\": \"%s\", \"unique_key\": %d, \"metadata_json\": \"%s\" }",
                current->data.timestamp, current->data.event_type, current->data.unique_key, current->data.metadata_json);

        if (current->next) fprintf(file, ",\n");
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);

    fprintf(file, "\n]");
    fclose(file);
}

DynamicArray* deserialize_array(const char* filename) {
    if (!filename) return NULL;

    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    DynamicArray* array = create_dynamic_array();
    if (!array) goto cleanup;

    char buffer[2048];
    fread(buffer, 1, sizeof(buffer), file);
    fclose(file);

    json_object *parsed_json;
    parsed_json = json_tokener_parse(buffer);
    json_object *json_array = json_object_array_get_idx(parsed_json, 0);

    for (int i = 0; i < json_object_array_length(json_array); i++) {
        json_object *json_obj = json_object_array_get_idx(json_array, i);

        TrafficEvent event;
        event.timestamp = json_object_get_int(json_object_object_get(json_obj, "timestamp"));
        strncpy(event.event_type, json_object_get_string(json_object_object_get(json_obj, "event_type")), sizeof(event.event_type));
        event.unique_key = json_object_get_int(json_object_object_get(json_obj, "unique_key"));

        const char* metadata_str = json_object_get_string(json_object_object_get(json_obj, "metadata_json"));
        size_t len = strlen(metadata_str) + 1;
        event.metadata_json = (char*)malloc(len);
        memcpy(event.metadata_json, metadata_str, len);

        add_traffic_event(array, event);
    }

    json_object_put(parsed_json);

cleanup:
    if (!array && file) fclose(file);
    return array;
}

void log_performance_metrics() {
    // Implement logging of performance metrics
}

