    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 256, PTHREAD_MUTEX_INITIALIZER};
EventCollection event_collection = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (!memory_pool.pool) {
        memory_pool.pool_size = size;
        memory_pool.pool = malloc(size);
        memset(memory_pool.pool, 0, size);
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

void *allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    void *ptr = memory_pool.pool; // Simplified allocation for example
    if (ptr) {
        memory_pool.pool += size;
    } else {
        ptr = malloc(size);
    }
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void free_memory(void *ptr) {
    // Implement deallocation logic if necessary
}

void add_event(time_t timestamp, EventType event_type, const char *description) {
    pthread_mutex_lock(&event_collection.lock);
    if (event_collection.count < MAX_EVENTS) {
        Event *new_event = allocate_memory(sizeof(Event));
        new_event->timestamp = timestamp;
        new_event->event_type = event_type;
        new_event->description = strdup(description); // Allocate and copy description
        event_collection.events[event_collection.count++] = new_event;
    } else {
        fprintf(stderr, "Event collection full\n");
    }
    pthread_mutex_unlock(&event_collection.lock);
}

void retrieve_events(time_t start, time_t end, Event **out_events, size_t *out_count) {
    pthread_mutex_lock(&event_collection.lock);
    *out_count = 0;
    for (size_t i = 0; i < event_collection.count; ++i) {
        if (event_collection.events[i]->timestamp >= start && 
            event_collection.events[i]->timestamp <= end) {
            if (*out_count < MAX_EVENTS) {
                out_events[(*out_count)++] = event_collection.events[i];
            }
        }
    }
    pthread_mutex_unlock(&event_collection.lock);
}

void clear_events() {
    pthread_mutex_lock(&event_collection.lock);
    for (size_t i = 0; i < event_collection.count; ++i) {
        free(event_collection.events[i]->description);
        free_memory(event_collection.events[i]);
    }
    memset(event_collection.events, 0, sizeof(event_collection.events));
    event_collection.count = 0;
    pthread_mutex_unlock(&event_collection.lock);
}

void log_event(const char *message) {
    // Simple logging function
    printf("LOG: %s\n", message);
}

int main() {
    initialize_memory_pool(1024 * 1024); // Initialize a 1MB memory pool

    add_event(time(NULL), EVENT_TYPE_A, "Event A occurred");
    add_event(time(NULL) + 100, EVENT_TYPE_B, "Event B occurred");

    Event *events[10];
    size_t count;
    retrieve_events(time(NULL), time(NULL) + 200, events, &count);

    for (size_t i = 0; i < count; ++i) {
        printf("Timestamp: %ld, Type: %d, Description: %s\n", 
               events[i]->timestamp, events[i]->event_type, events[i]->description);
    }

    clear_events();
    return 0;
}
