#define MAX_ELEMENTS 10000
#define BUFFER_SIZE 256
#define ERROR_CODE_LIMIT_REACHED -1

typedef struct Record {
    int key;
    time_t timestamp;
    char buffer[BUFFER_SIZE];
} Record;

typedef struct Node {
    int sequence_number;
    Record record;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    int count;
    pthread_mutex_t lock;
    const char *charset;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_data_structure() {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    return list;
}

void free_record(Record *record) {
    if (record) {
        free(record);
    }
}

int generate_random_buffer(char *buffer, size_t length, const char *charset) {
    size_t charset_size = strlen(charset);
    for (size_t i = 0; i < length - 1; ++i) {
        buffer[i] = charset[rand() % charset_size];
    }
    buffer[length - 1] = '\0';
    return 0;
}

int add_record(NFAPI_CRC_INDICATION_PDU_T *list, int key) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_LIMIT_REACHED;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation error
    }

    new_node->sequence_number = list->count + 1;
    new_node->record.key = key;
    new_node->record.timestamp = time(NULL);

    generate_random_buffer(new_node->record.buffer, BUFFER_SIZE, list->charset);

    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }

    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int change_charset(NFAPI_CRC_INDICATION_PDU_T *list, const char *new_charset) {
    pthread_mutex_lock(&list->lock);

    if (new_charset == NULL || strlen(new_charset) == 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid charset
    }

    list->charset = new_charset;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize(NFAPI_CRC_INDICATION_PDU_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    fwrite(&list->count, sizeof(int), 1, file);

    Node *current = list->head;
    while (current != NULL) {
        fwrite(&(current->sequence_number), sizeof(int), 1, file);
        fwrite(&(current->record.key), sizeof(int), 1, file);
        fwrite(&current->record.timestamp, sizeof(time_t), 1, file);
        fwrite(current->record.buffer, BUFFER_SIZE, 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

int deserialize(NFAPI_CRC_INDICATION_PDU_T *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int count;
    fread(&count, sizeof(int), 1, file);

    pthread_mutex_lock(&list->lock);

    free_data_structure(list); // Clear existing data

    for (int i = 0; i < count; ++i) {
        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -1;
        }

        fread(&(new_node->sequence_number), sizeof(int), 1, file);
        fread(&(new_node->record.key), sizeof(int), 1, file);
        fread(&new_node->record.timestamp, sizeof(time_t), 1, file);
        fread(new_node->record.buffer, BUFFER_SIZE, 1, file);

        new_node->prev = list->tail;
        new_node->next = NULL;

        if (list->head == NULL) {
            list->head = new_node;
        } else {
            list->tail->next = new_node;
        }

        list->tail = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

void free_data_structure(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (!list) return;

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

