#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    int *keyPtr;
} record;

// Function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Function to generate a random integer within a range
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Thread-safe memory allocation with limit enforcement
void *thread_safe_malloc(size_t size, size_t *current_usage, size_t max_memory) {
    if (*current_usage + size > max_memory) {
        fprintf(stderr, "Memory usage exceeded the maximum allowed limit.\n");
        return NULL;
    }
    void *ptr = malloc(size);
    if (ptr != NULL) {
        *current_usage += size;
    }
    return ptr;
}

// Custom free function to track memory deallocation
void thread_safe_free(void **ptr, size_t current_usage, size_t size) {
    if (*ptr != NULL) {
        free(*ptr);
        current_usage -= size;
        *ptr = NULL;
    }
}

// Function to create and initialize arrays and records with constraints
int create_and_initialize_arrays(
    long **offsets, int offset_count,
    int **keys, int key_count,
    record **records, int record_count,
    int value_min, int value_max,
    size_t max_memory) {

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t current_usage = 0;

    // Allocate memory for offsets
    *offsets = (long *) thread_safe_malloc(offset_count * sizeof(long), &current_usage, max_memory);
    if (*offsets == NULL) goto cleanup;
    for (int i = 0; i < offset_count; ++i) {
        (*offsets)[i] = rand_range(1, 100); // Example initialization
    }

    // Allocate memory for keys and records in one go to minimize fragmentation
    size_t total_key_size = key_count * sizeof(int);
    size_t record_struct_size = record_count * sizeof(record);

    char *block = (char *) thread_safe_malloc(total_key_size + record_struct_size, &current_usage, max_memory);
    if (block == NULL) goto cleanup;

    // Extract keys and records from the block
    *keys = (int *)(block);
    *records = (record *)(block + total_key_size);

    for (int i = 0; i < key_count; ++i) {
        (*keys)[i] = rand_range(1, 100); // Example initialization with potential delay handling
    }

    for (int i = 0; i < record_count; ++i) {
        (*records)[i].keyPtr = &(*keys)[i];
        (*records)[i].value = rand_range(value_min, value_max);
    }

    pthread_mutex_destroy(&lock);

    return 0;

cleanup:
    // Free all allocated memory in case of failure
    if (*offsets != NULL) {
        free(*offsets);
    }
    if (block != NULL) {
        free(block);
    }
    pthread_mutex_destroy(&lock);
    return -1;
}

