    EVENT_TYPE_ALERT,
    EVENT_TYPE_NORMAL
} event_type;

struct sensor_metadata {
    int sensor_id;
    char name[128];
    time_t last_calibration;
};

struct sensor_event {
    float reading_value;
    time_t timestamp;
    event_type type;
};

// Global variables for tracking allocations and events
size_t total_events_allocated = 0;
const size_t max_events = 1000; // Define a maximum limit for safety

// Function prototypes
void* safe_malloc(size_t size);
void log_error(const char *message);
int resolve_mac_address(int device_id, u_char mac[6]);
void free_resources(void *, void *, void *);
int dns_resolve_mac(int device_id, u_char *mac);

// Main function to dynamically manage collections
void initialize_sensor_collections(size_t num_sensors) {
    if (num_sensors <= 0) {
        log_error("Invalid number of sensors.");
        return;
    }

    float *temperature_readings = safe_malloc(num_sensors * sizeof(float));
    struct sensor_metadata *sensor_metadata_array = safe_malloc(num_sensors * sizeof(struct sensor_metadata));
    struct sensor_event *sensor_events = safe_malloc(max_events * sizeof(struct sensor_event));

    if (!temperature_readings || !sensor_metadata_array || !sensor_events) {
        free_resources(temperature_readings, sensor_metadata_array, sensor_events);
        log_error("Memory allocation failed.");
        return;
    }

    // Initialize collections
    for (size_t i = 0; i < num_sensors; ++i) {
        sensor_metadata_array[i].sensor_id = i + 1;
        snprintf(sensor_metadata_array[i].name, sizeof(sensor_metadata_array[i].name), "Sensor_%zu", i + 1);
        sensor_metadata_array[i].last_calibration = time(NULL);

        // Example: Generate random temperature reading
        temperature_readings[i] = (float)rand() / RAND_MAX * 100.0;

        if (resolve_mac_address(i + 1, sensor_metadata_array[i].mac)) {
            log_error("MAC address resolution failed for device ID.");
            free_resources(temperature_readings, sensor_metadata_array, sensor_events);
            return;
        }
    }

    // Example: Add an event
    if (total_events_allocated < max_events) {
        struct sensor_event new_event = {75.5f, time(NULL), EVENT_TYPE_NORMAL};
        memcpy(&sensor_events[total_events_allocated++], &new_event, sizeof(struct sensor_event));
    } else {
        log_error("Maximum events allocated.");
    }

    // Example: Serialize to a file
    FILE *file = fopen("sensor_data.bin", "wb");
    if (file) {
        fwrite(temperature_readings, sizeof(float), num_sensors, file);
        fwrite(sensor_metadata_array, sizeof(struct sensor_metadata), num_sensors, file);
        fwrite(sensor_events, sizeof(struct sensor_event), total_events_allocated, file);
        fclose(file);
    }

    // Example: Deserialize from a file
    file = fopen("sensor_data.bin", "rb");
    if (file) {
        fread(temperature_readings, sizeof(float), num_sensors, file);
        fread(sensor_metadata_array, sizeof(struct sensor_metadata), num_sensors, file);
        fread(sensor_events, sizeof(struct sensor_event), total_events_allocated, file);
        fclose(file);
    }

    // Clean up
    free_resources(temperature_readings, sensor_metadata_array, sensor_events);
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed.");
    }
    return ptr;
}

void log_error(const char *message) {
    FILE *log_file = fopen("sensor_error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        // If logging to file fails, fallback to stderr
        fprintf(stderr, "Logging failed: %s. Stderr used as fallback.\n", message);
    }
}

int resolve_mac_address(int device_id, u_char mac[6]) {
    int retries = 5;
    while (retries-- > 0) {
        if (dns_resolve_mac(device_id, mac)) {
            return 1; // Success
        }
        sleep(1 << (5 - retries)); // Exponential backoff
    }
    return 0; // Failure after retries
}

int dns_resolve_mac(int device_id, u_char *mac) {
    char hostname[256];
    snprintf(hostname, sizeof(hostname), "device%d.local", device_id);
    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET6;

    if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
        for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
            if (p->ai_addr->sa_family == AF_LINK) { // Check for link layer address
                struct sockaddr_dl *sdl = (struct sockaddr_dl *)p->ai_addr;
                memcpy(mac, LLADDR(sdl), 6);
                freeaddrinfo(res);
                return 1; // Success
            }
        }
    }
    freeaddrinfo(res);
    return 0; // Failure
}

void free_resources(void *temp_readings, void *metadata_array, void *events) {
    if (temp_readings) free(temp_readings);
    if (metadata_array) free(metadata_array);
    if (events) free(events);
}
