    entry **array;
    size_t size;
    pthread_mutex_t lock;
} dynamic_array;

dynamic_array* init_dynamic_array(size_t min_size, size_t max_size) {
    if (min_size > max_size) return NULL;

    dynamic_array *da = malloc(sizeof(dynamic_array));
    if (!da) return NULL;

    da->array = calloc(max_size, sizeof(entry *));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = min_size;
    pthread_mutex_init(&da->lock, NULL);

    // Initialize entries with empty buffers and timestamps
    time_t current_time = time(NULL);
    for (size_t i = 0; i < min_size; ++i) {
        entry *e = malloc(sizeof(entry));
        if (!e) {
            for (size_t j = 0; j <= i; ++j) free(da->array[j]);
            free(da->array);
            pthread_mutex_destroy(&da->lock);
            free(da);
            return NULL;
        }

        e->buffer = calloc(1, sizeof(char)); // Start with an empty buffer
        e->key = 0;
        e->timestamp = current_time;
        da->array[i] = e;
    }

    return da;
}

void set_entry(dynamic_array *da, size_t index, const char *init_str, int key) {
