typedef struct {
    FrameStats *head;
    int count;
    float averagePacketRate;
    int threshold;
    void (*logWarning)(const char*);
} FrameStatsManager;

FrameStatsManager* create_manager(int initialThreshold, void (*logWarningFunc)(const char*)) {
    FrameStatsManager* manager = (FrameStatsManager*)malloc(sizeof(FrameStatsManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->count = 0;
    manager->averagePacketRate = 0.0f;
    manager->threshold = initialThreshold;
    manager->logWarning = logWarningFunc ? logWarningFunc : (void(*)(const char*))NULL;

    return manager;
}

int add_frame(FrameStatsManager* manager, int frameNumber, double timestamp, int packetCount) {
    if (!manager) return -1;

    FrameStats *current = manager->head;
    while (current != NULL) {
        if (current->frameNumber == frameNumber) {
            if (manager->logWarning)
                manager->logWarning("Duplicate frame number encountered.");
            return 0; // Duplicate frameNumber, ignored
        }
        current = current->next;
    }

    FrameStats *newFrame = (FrameStats*)malloc(sizeof(FrameStats));
    if (!newFrame) return -1;

    newFrame->frameNumber = frameNumber;
    newFrame->timestamp = timestamp;
    newFrame->packetCount = packetCount;
    newFrame->next = manager->head;
    manager->head = newFrame;
    manager->count++;

    float totalPacketRate = manager->averagePacketRate * (manager->count - 1) + packetCount;
    manager->averagePacketRate = totalPacketRate / manager->count;

    return 1; // Success
}

void resize_manager(FrameStatsManager* manager, int newThreshold) {
    if (!manager) return;

    manager->threshold = newThreshold;
    // Resize logic can be implemented here as needed (e.g., reorganizing data)
}

void reset_manager(FrameStatsManager* manager) {
    if (!manager) return;

    FrameStats *current = manager->head;
    while (current != NULL) {
        FrameStats *temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->count = 0;
    manager->averagePacketRate = 0.0f;
}

void destroy_manager(FrameStatsManager* manager) {
    if (!manager) return;

    reset_manager(manager);
    free(manager);
}

// Example logWarning function
