#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    int *key_ptr;
} Record;

// Logging function prototype
void log_event(const char *message);

// Custom allocator (simple example)
void *custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_event("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void *ptr) {
    free(ptr);
}

// Global memory usage tracker
size_t current_memory_usage = 0;

// Mutex for thread-safe operations
pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

#define MAX_MEMORY_USAGE 104857600 // 100MB

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
} DataArray;

DataArray* allocate_data_arrays(size_t initial_size, int max_memory_usage) {
    pthread_mutex_lock(&memory_mutex);

    // Calculate memory requirement
    size_t offset_mem = initial_size * sizeof(long);
    size_t key_mem = initial_size * sizeof(int);
    size_t record_mem = initial_size * sizeof(Record);

    if ((current_memory_usage + offset_mem + key_mem + record_mem) > max_memory_usage) {
        pthread_mutex_unlock(&memory_mutex);
        log_event("Exceeded maximum memory usage");
        return NULL;
    }

    DataArray* data_array = custom_malloc(sizeof(DataArray));

    // Allocate and initialize arrays
    data_array->offsets = custom_malloc(offset_mem);
    data_array->keys = custom_malloc(key_mem);
    data_array->records = custom_malloc(record_mem);

    for (size_t i = 0; i < initial_size; ++i) {
        data_array->offsets[i] = 0;
        data_array->keys[i] = -1; // Assume invalid key initially
        data_array->records[i].value = 0;
        data_array->records[i].key_ptr = &data_array->keys[i];
    }

    current_memory_usage += offset_mem + key_mem + record_mem;

    pthread_mutex_unlock(&memory_mutex);

    log_event("Data arrays allocated and initialized");

    return data_array;
}

void deallocate_data_arrays(DataArray* data_array) {
    if (!data_array) return;

    pthread_mutex_lock(&memory_mutex);
    current_memory_usage -= (sizeof(long) * data_array->size +
                             sizeof(int) * data_array->size +
                             sizeof(Record) * data_array->size);

    custom_free(data_array->offsets);
    custom_free(data_array->keys);
    custom_free(data_array->records);
    custom_free(data_array);

    pthread_mutex_unlock(&memory_mutex);

    log_event("Data arrays deallocated");
}

// Logging function implementation
void log_event(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    size_t initial_size = 1000;
    int max_memory_usage = MAX_MEMORY_USAGE;

    DataArray* data_array = allocate_data_arrays(initial_size, max_memory_usage);

    if (data_array) {
        // Use the allocated arrays...

        deallocate_data_arrays(data_array);
    }

    return 0;
}
