pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;

void log_usage(size_t current_usage, size_t peak_usage) {
    FILE *log_file = fopen("usage.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - Current Usage: %zu bytes, Peak Usage: %zu bytes\n",
                ctime(&now), current_usage, peak_usage);
        fclose(log_file);
    }
}

void* manage_nfa_records(void *arg) {
    MemoryPool pool;
    pthread_mutex_init(&pool.lock, NULL);
    pool.pool_size = 0;
    size_t peak_usage = 0;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *record = malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE);
        if (!record) break;

        pthread_mutex_lock(&pool.lock);
        pool.pool[i] = record;
        pool.pool_size++;
        size_t current_usage = pool.pool_size * NFAPI_CRC_INDICATION_PDU_T_SIZE;

        if (current_usage > peak_usage) {
            peak_usage = current_usage;
        }

        log_usage(current_usage, peak_usage);

        pthread_mutex_unlock(&pool.lock);
    }

    while (1) {
        pthread_mutex_lock(&pool.lock);

        for (size_t i = 0; i < pool.pool_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *record = pool.pool[i];

            if (!record) continue;

            // Simulate filling in the structure
            record->RX_UE_INFORMATION_TAG = rand();
            record->RNTI = rand();
            record->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

            pthread_mutex_lock(&file_lock);
            FILE *output_file = fopen("output.txt", "a");
            if (output_file) {
                fprintf(output_file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n",
                        record->RX_UE_INFORMATION_TAG, record->RNTI,
                        record->CRC_INDICATION_REL8_TAG.CRCFLAG);
                fclose(output_file);
            }
            pthread_mutex_unlock(&file_lock);

            // Validation mechanism
            if (record->CRC_INDICATION_REL8_TAG.CRCFLAG == 0) { // Example validation failure
                fprintf(stderr, "Validation failed for RNTI %d. Attempting correction.\n",
                        record->RNTI);
                record->CRC_INDICATION_REL8_TAG.CRCFLAG = 1; // Correct the CRCFLAG
            }
        }

        pthread_mutex_unlock(&pool.lock);

        sleep(5); // Sleep to simulate periodic updates
    }

    pthread_mutex_destroy(&pool.lock);
    return NULL;
}

int main() {
    const int NUM_THREADS = 4;
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, manage_nfa_records, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
