    list->count = decompressed_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    free(compressed_data);
    free(decompressed_data);
    fclose(file);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void start_cleanup_thread(SessionList *list) {
