} Record;

// Function to generate random numbers from normal distribution using Box-Muller transform
double rand_normal(double mean, double stddev) {
    static int haveSpare = 0;
    static double spare;

    if (haveSpare) {
        haveSpare = 0;
        return mean + stddev * spare;
    } else {
        double u1, u2;
        do { u1 = rand() / (RAND_MAX + 1.0); } while (u1 == 0);
        do { u2 = rand() / (RAND_MAX + 1.0); } while (u2 == 0);

        spare = sqrt(-2 * log(u1)) * sin(2 * M_PI * u2);
        haveSpare = 1;
        return mean + stddev * sqrt(-2 * log(u1)) * cos(2 * M_PI * u2);
    }
}

// Function to manage dynamic memory allocation for an array of records
Record* allocate_records(size_t num_records, double mean, double stddev) {
    if (num_records == 0) return NULL;

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Predefined list of strings
    const char* string_list[] = {"Alpha", "Beta", "Gamma", "Delta", "Epsilon"};
