        strncpy(records[i].name, selected_string, sizeof(records[i].name));
        records[i].name[sizeof(records[i].name) - 1] = '\0';

        // Assign a random double value from normal distribution
        records[i].value = rand_normal(mean, stddev);
    }

    return records;
}

