### Part 2: JavaScript Engine Framework using Node.js

Create a `fetchAndParseHTML.js` script for fetching and parsing HTML content.

```javascript
const https = require('https');
const { JSDOM } = require('jsdom');

class HTMLFetcher {
    constructor(urls, maxConcurrency) {
        this.urls = urls;
        this.maxConcurrency = maxConcurrency;
        this.results = [];
        this.semaphore = new Semaphore(this.maxConcurrency);
    }

    async fetchHTML() {
        const promises = this.urls.map(url => 
            this.semaphore.acquire().then(() => this.fetchAndParse(url))
                .finally(() => this.semaphore.release())
        );

        await Promise.all(promises);
        return this.results;
    }

    fetchAndParse(url) {
        return new Promise((resolve, reject) => {
            https.get(url, response => {
                if (response.statusCode !== 200) {
                    reject(new Error(`Failed to load page: ${url}`));
                    return;
                }

                let data = '';

                response.on('data', chunk => data += chunk);
                response.on('end', () => {
                    try {
                        const dom = new JSDOM(data);
                        const title = dom.window.document.querySelector('title').textContent;
                        const h1 = dom.window.document.querySelector('h1') ? dom.window.document.querySelector('h1').textContent : '';
                        const paragraphs = Array.from(dom.window.document.querySelectorAll('p')).map(p => p.textContent);

                        resolve({ url, title, h1, paragraphs });
                    } catch (err) {
                        reject(err);
                    }
                });

            }).on('error', err => reject(err));
        });
    }
}

class Semaphore {
    constructor(count) {
        this.count = count;
        this.waiting = [];
    }

    acquire() {
        return new Promise(resolve => {
            if (this.count > 0) {
                this.count--;
                resolve();
            } else {
                this.waiting.push(resolve);
            }
        });
    }

    release() {
        if (this.waiting.length > 0) {
            const next = this.waiting.shift();
            next();
        } else {
            this.count++;
        }
    }
}

module.exports = HTMLFetcher;
```

