#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for LTE UE Context Information
typedef struct {
    char ue_identity[16]; // Assuming UE identity is 15 digits + null terminator
    char rrc_message_complete[256]; // Placeholder size for RRC message
} LTE_UE_Context;

// Node for the hash table
struct HashNode {
    LTE_UE_Context context;
    struct HashNode* next;
};

// Hash table structure with thread safety mechanisms
typedef struct {
    int capacity;
    struct HashNode** buckets;
    pthread_mutex_t locks[256]; // Simplified fixed number of locks for example purposes
} ContextHashTable;

unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % 256; // Using a small fixed modulus for simplicity
}

ContextHashTable* create_context_table(int capacity) {
    ContextHashTable* table = (ContextHashTable*)malloc(sizeof(ContextHashTable));
    table->capacity = capacity;
    table->buckets = (struct HashNode**)calloc(capacity, sizeof(struct HashNode*));

    for (int i = 0; i < 256; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

void free_context_table(ContextHashTable* table) {
    for (int i = 0; i < table->capacity; ++i) {
        struct HashNode* node = table->buckets[i];
        while (node) {
            struct HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);

    for (int i = 0; i < 256; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table);
}

void add_context(ContextHashTable* table, LTE_UE_Context context) {
    unsigned long index = hash_function(context.ue_identity);
    pthread_mutex_lock(&table->locks[index % 256]);

    struct HashNode* new_node = (struct HashNode*)malloc(sizeof(struct HashNode));
    memcpy(&new_node->context, &context, sizeof(LTE_UE_Context));
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index % 256]);
}

LTE_UE_Context* get_context(ContextHashTable* table, const char *ue_identity) {
    unsigned long index = hash_function(ue_identity);
    pthread_mutex_lock(&table->locks[index % 256]);

    struct HashNode* node = table->buckets[index];
    while (node) {
        if (strcmp(node->context.ue_identity, ue_identity) == 0) {
            LTE_UE_Context* context = &node->context;
            pthread_mutex_unlock(&table->locks[index % 256]);
            return context;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index % 256]);
    return NULL; // Context not found
}

void update_context(ContextHashTable* table, const char *ue_identity, LTE_UE_Context new_context) {
    unsigned long index = hash_function(ue_identity);
    pthread_mutex_lock(&table->locks[index % 256]);

    struct HashNode* node = table->buckets[index];
    while (node) {
        if (strcmp(node->context.ue_identity, ue_identity) == 0) {
            memcpy(&node->context, &new_context, sizeof(LTE_UE_Context));
            pthread_mutex_unlock(&table->locks[index % 256]);
            return;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index % 256]);
}

int main() {
    ContextHashTable* table = create_context_table(1024);

    LTE_UE_Context context1 = {"123456789012345", "RRC Message Complete"};
    add_context(table, context1);

    LTE_UE_Context* retrieved_context = get_context(table, "123456789012345");
    if (retrieved_context) {
        printf("Retrieved UE Identity: %s\n", retrieved_context->ue_identity);
    } else {
        printf("Context not found.\n");
    }

    LTE_UE_Context updated_context = {"123456789012345", "Updated RRC Message Complete"};
    update_context(table, "123456789012345", updated_context);

    retrieved_context = get_context(table, "123456789012345");
    if (retrieved_context) {
        printf("Updated UE Identity: %s\n", retrieved_context->ue_identity);
    } else {
        printf("Context not found.\n");
    }

    free_context_table(table);
    return 0;
}
