#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char buffer[256];
    time_t timestamp;
} record;

typedef struct {
    size_t size;
    time_t last_modified;
} metadata;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    metadata **metadata;
    size_t current_size;
    size_t memory_limit;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    unsigned char logging_enabled;
    size_t compression_threshold;
    double memory_usage_threshold;
    FILE *log_file;
} config;

void log_message(config *cfg, const char *message) {
    if (cfg->logging_enabled) {
        printf("%s\n", message);
        if (cfg->log_file) {
            fprintf(cfg->log_file, "%s\n", message);
            fflush(cfg->log_file);
        }
    }
}

config* initialize_config(size_t size_limit, unsigned char logging, const char *logfile_name,
                          size_t compression_threshold, double memory_usage_threshold) {
    config *cfg = (config *)malloc(sizeof(config));
    if (!cfg) return NULL;

    cfg->memory_limit = size_limit;
    cfg->logging_enabled = logging;
    cfg->compression_threshold = compression_threshold;
    cfg->memory_usage_threshold = memory_usage_threshold;

    pthread_mutex_init(&cfg->lock, NULL);
    pthread_cond_init(&cfg->cond_var, NULL);

    if (logfile_name) {
        cfg->log_file = fopen(logfile_name, "a");
        if (!cfg->log_file) {
            free(cfg);
            return NULL;
        }
    } else {
        cfg->log_file = NULL;
    }

    cfg->offsets = (long *)malloc(size_limit * sizeof(long));
    cfg->keys = (int *)malloc(size_limit * sizeof(int));
    cfg->records = (record **)malloc(size_limit * sizeof(record *));
    cfg->metadata = (metadata **)malloc(size_limit * sizeof(metadata *));
    if (!cfg->offsets || !cfg->keys || !cfg->records || !cfg->metadata) {
        free(cfg);
        return NULL;
    }

    cfg->current_size = 0;

    log_message(cfg, "Configuration initialized.");

    return cfg;
}

char* generate_random_buffer(size_t length, const char *charset) {
    char *buffer = (char *)malloc(length + 1);
    if (!buffer) return NULL;

    for (size_t i = 0; i < length; ++i) {
        buffer[i] = charset[rand() % strlen(charset)];
    }
    buffer[length] = '\0';

    return buffer;
}

int add_record(config *cfg, int key_value, const char *charset) {
    pthread_mutex_lock(&cfg->lock);

    if (cfg->current_size >= cfg->memory_limit) {
        log_message(cfg, "Memory limit reached. Cannot add more records.");
        pthread_mutex_unlock(&cfg->lock);
        return -1;
    }

    record *new_record = (record *)malloc(sizeof(record));
    metadata *new_meta = (metadata *)malloc(sizeof(metadata));

    if (!new_record || !new_meta) {
        log_message(cfg, "Memory allocation failed for new records.");
        pthread_mutex_unlock(&cfg->lock);
        return -1;
    }

    cfg->records[cfg->current_size] = new_record;
    cfg->metadata[cfg->current_size] = new_meta;

    new_record->value = key_value;
    new_record->buffer = generate_random_buffer(256, charset);
    if (!new_record->buffer) {
        free(new_record);
        free(new_meta);
        pthread_mutex_unlock(&cfg->lock);
        return -1;
    }
    time(&(new_record->timestamp));

    new_meta->size = sizeof(record);
    time(&(new_meta->last_modified));

    cfg->keys[cfg->current_size] = key_value;
    cfg->offsets[cfg->current_size] = cfg->current_size;

    ++cfg->current_size;

    pthread_mutex_unlock(&cfg->lock);

    return 0;
}

void serialize_data(config *cfg, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message(cfg, "Failed to open file for serialization.");
        return;
    }

    size_t record_size = sizeof(record);
    size_t metadata_size = sizeof(metadata);

    fwrite(&cfg->current_size, sizeof(size_t), 1, file);
    fwrite(cfg->records, record_size, cfg->current_size, file);
    fwrite(cfg->metadata, metadata_size, cfg->current_size, file);

    fclose(file);
}

void deserialize_data(config *cfg, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message(cfg, "Failed to open file for deserialization.");
        return;
    }

    size_t new_current_size;
    fread(&new_current_size, sizeof(size_t), 1, file);

    if (new_current_size > cfg->memory_limit) {
        log_message(cfg, "Deserialized data exceeds memory limit.");
        fclose(file);
        return;
    }

    for (size_t i = 0; i < new_current_size; ++i) {
        record *rec = (record *)malloc(sizeof(record));
        metadata *meta = (metadata *)malloc(sizeof(metadata));

        fread(rec, sizeof(record), 1, file);
        fread(meta, sizeof(metadata), 1, file);

        cfg->records[i] = rec;
        cfg->metadata[i] = meta;

        cfg->keys[i] = rec->value;
        cfg->offsets[i] = i;
    }

    cfg->current_size = new_current_size;
    fclose(file);
}

void cleanup_config(config *cfg) {
    if (cfg) {
        for (size_t i = 0; i < cfg->current_size; ++i) {
            free(cfg->records[i]->buffer);
            free(cfg->records[i]);
            free(cfg->metadata[i]);
        }

        free(cfg->offsets);
        free(cfg->keys);
        free(cfg->records);
        free(cfg->metadata);

        pthread_mutex_destroy(&cfg->lock);
        pthread_cond_destroy(&cfg->cond_var);

        if (cfg->log_file) {
            fclose(cfg->log_file);
        }
        free(cfg);
    }
}
