#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_AGE 1000000

typedef struct {
    long offset;
    int key;
    time_t timestamp;
} OffsetRecord;

typedef struct {
    int value;
    OffsetRecord* recordPointer;
    int referenceCount;
} KeyRecord;

typedef struct {
    int value;
} RandomValue;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* message) {
    FILE* logFile = fopen("operations.log", "a");
    if (logFile != NULL) {
        time_t now = time(NULL);
        fprintf(logFile, "[%ld] %s\n", now, message);
        fclose(logFile);

        // Implement daily log rotation
        rename("operations.log", "operations_backup.log"); 
        FILE* newLogFile = fopen("operations.log", "w");
        if (newLogFile) {
            fclose(newLogFile);
        }
    }
}

int validate_input(size_t input, size_t max_size) {
    if (input > max_size) {
        log_operation("Input exceeds maximum allowed size.");
        return 0;
    }
    return 1;
}

OffsetRecord* allocate_offset_records(size_t count) {
    OffsetRecord* records = malloc(count * sizeof(OffsetRecord));
    if (!records) {
        log_operation("Failed to allocate memory for OffsetRecords");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = i; // Example initialization
        records[i].key = i % 100; // Example key assignment
        records[i].timestamp = time(NULL);

        if ((time(NULL) - records[i].timestamp) > MAX_AGE) {
            log_operation("Timestamp exceeds maximum age.");
            free(records);
            return NULL;
        }
    }

    log_operation("Successfully allocated and initialized OffsetRecords");
    return records;
}

int custom_index(size_t index, size_t count) {
    // Simple hash function with modulo to prevent overflow
    return index % count;
}

KeyRecord* allocate_key_records(size_t offset_count, size_t key_record_count, OffsetRecord* offset_records) {
    if (!offset_records || !validate_input(key_record_count, SIZE_MAX / sizeof(KeyRecord))) {
        log_operation("Invalid input or memory allocation failed for KeyRecords");
        return NULL;
    }

    KeyRecord* records = malloc(key_record_count * sizeof(KeyRecord));
    if (!records) {
        log_operation("Failed to allocate memory for KeyRecords");
        return NULL;
    }

    for (size_t i = 0; i < key_record_count; ++i) {
        int index = custom_index(i, offset_count);
        records[i].value = rand() % 100; // Example value assignment
        if (index >= 0 && index < offset_count) {
            records[i].recordPointer = &offset_records[index];
        } else {
            records[i].recordPointer = NULL;
            log_operation("Index out of bounds, setting pointer to NULL");
        }
        records[i].referenceCount = (records[i].recordPointer == NULL) ? 0 : 1;
    }

    log_operation("Successfully allocated and initialized KeyRecords");
    return records;
}

void set_random_value(int* value) {
    pthread_mutex_lock(&mutex);
    *value = rand() % 101; // Random number between 0 and 100
    pthread_mutex_unlock(&mutex);
}

RandomValue* allocate_random_values(size_t count) {
    if (!validate_input(count, SIZE_MAX / sizeof(RandomValue))) {
        log_operation("Invalid input or memory allocation failed for RandomValues");
        return NULL;
    }

    RandomValue* values = malloc(count * sizeof(RandomValue));
    if (!values) {
        log_operation("Failed to allocate memory for RandomValues");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        set_random_value(&values[i].value);
    }

    log_operation("Successfully allocated and initialized RandomValues");
    return values;
}

void free_memory(OffsetRecord* offsetRecords, KeyRecord* keyRecords, RandomValue* randomValues) {
    if (offsetRecords) free(offsetRecords);
    if (keyRecords) free(keyRecords);
    if (randomValues) free(randomValues);

    log_operation("Memory successfully freed.");
}
