['Below is an implementation of the described functionality in C, using dynamic arrays with custom management functions. The code includes thread safety mechanisms and logging features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int EUTRAN_RRC_CU_MSG_T;
    int NAS_MESSAGE;
    int NAS_IE;
    int sequence_number;
} LTE_ENB_API_NAS_IE_T;

#define INITIAL_CAPACITY 10
#define LOG_BUFFER_SIZE 256

pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cfc_array;
    size_t capacity;
    size_t size;
} CRCArray;

typedef struct {
    LTE_ENB_API_NAS_IE_T *nas_ies;
    size_t capacity;
    size_t size;
} NASIEArray;

void log_message(const char *message) {
    static char buffer[LOG_BUFFER_SIZE];
    snprintf(buffer, LOG_BUFFER_SIZE, "%s\n", message);
    printf("%s", buffer);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_array(size_t capacity) {
    return (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

LTE_ENB_API_NAS_IE_T* allocate_nas_ie_array(size_t capacity) {
    return (LTE_ENB_API_NAS_IE_T*)calloc(capacity, sizeof(LTE_ENB_API_NAS_IE_T));
}

void resize_array(CRCArray *array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* temp = allocate_array(new_capacity);

    if (!temp) {
        log_message("Memory allocation failed during resize.");
        return;
    }

    memcpy(temp, array->cfc_array, array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(array->cfc_array);

    array->capacity = new_capacity;
    array->cfc_array = temp;
}

void add_crc_pdu(CRCArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array_mutex);

    if (array->size == array->capacity) {
        resize_array(array);
    }

    if (array->size < array->capacity) {
        array->cfc_array[array->size++] = pdu;
        log_message("Added NFAPI_CRC_INDICATION_PDU_T.");
    } else {
        log_message("Failed to add NFAPI_CRC_INDICATION_PDU_T due to capacity error.");
    }

    pthread_mutex_unlock(&array_mutex);
}

void remove_crc_pdu(CRCArray *array, int (*condition)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array_mutex);

    size_t i = 0;
    while (i < array->size) {
        if (condition(&array->cfc_array[i])) {
            memmove(&array->cfc_array[i], &array->cfc_array[i + 1],
                    (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
            log_message("Removed NFAPI_CRC_INDICATION_PDU_T based on condition.");
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&array_mutex);
}

void update_crcflag(CRCArray *array, int index, int new_flag) {
    pthread_mutex_lock(&array_mutex);

    if (index >= 0 && index < array->size) {
        array->cfc_array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = new_flag;
        log_message("Updated CRCFLAG.");
    } else {
        log_message("Attempted out-of-bounds update on CRCFLAG.");
    }

    pthread_mutex_unlock(&array_mutex);
}

void init_crc_array(CRCArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->cfc_array = allocate_array(array->capacity);

    if (!array->cfc_array) {
        log_message("Failed to initialize CRC Array.");
    } else {
        log_message("Initialized CRC Array.");
    }
}

void init_nas_ie_array(NASIEArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->nas_ies = allocate_nas_ie_array(array->capacity);

    if (!array->nas_ies) {
        log_message("Failed to initialize NAS IE Array.");
    } else {
        log_message("Initialized NAS IE Array.");
    }
}

void add_nas_ie(NASIEArray *array, LTE_ENB_API_NAS_IE_T ie) {
    pthread_mutex_lock(&array_mutex);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_ENB_API_NAS_IE_T* temp = allocate_nas_ie_array(new_capacity);

        if (!temp) {
            log_message("Memory allocation failed during resize of NAS IE Array.");
            pthread_mutex_unlock(&array_mutex);
            return;
        }

        memcpy(temp, array->nas_ies, array->size * sizeof(LTE_ENB_API_NAS_IE_T));
        free(array->nas_ies);

        array->capacity = new_capacity;
        array->nas_ies = temp;
    }

    if (array->size < array->capacity) {
        array->nas_ies[array->size++] = ie;
        log_message("Added LTE_ENB_API_NAS_IE_T.");
    } else {
        log_message("Failed to add LTE_ENB_API_NAS_IE_T due to capacity error.");
    }

    pthread_mutex_unlock(&array_mutex);
}

void free_crc_array(CRCArray *array) {
    pthread_mutex_lock(&array_mutex);

    if (array->cfc_array) {
        free(array->cfc_array);
        array->size = 0;
        array->capacity = 0;

        log_message("Freed CRC Array.");
    }

    pthread_mutex_unlock(&array_mutex);
}

void free_nas_ie_array(NASIEArray *array) {
    pthread_mutex_lock(&array_mutex);

    if (array->nas_ies) {
        free(array->nas_ies);
        array->size = 0;
        array->capacity = 0;

        log_message("Freed NAS IE Array.");
    }

    pthread_mutex_unlock(&array_mutex);
}

// Example condition function
int is_invalid_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu->RX_UE_INFORMATION_TAG == -1; // Define your own invalid condition
}

void update_nasi_field(NASIEArray *array, int index, int new_nas_ie) {
    pthread_mutex_lock(&array_mutex);

    if (index >= 0 && index < array->size) {
        array->nas_ies[index].NAS_IE = new_nas_ie;
        log_message("Updated NAS IE field.");
    } else {
        log_message("Attempted out-of-bounds update on NAS IE field.");
    }

    pthread_mutex_unlock(&array_mutex);
}

