using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Microsoft.Extensions.Logging;

public class AesCbcDecryptor : IDisposable
{
    private readonly ILogger<AesCbcDecryptor> _logger;
    private readonly SymmetricAlgorithm _aes;
    private static readonly ReaderWriterLockSlim Locker = new ReaderWriterLockSlim();
    private readonly Dictionary<string, byte[]> _keyCache = new Dictionary<string, byte[]>();
    private readonly object _cacheLock = new object();

    public AesCbcDecryptor(ILogger<AesCbcDecryptor> logger)
    {
        _aes = Aes.Create();
        _aes.Mode = CipherMode.CBC;
        _aes.Padding = PaddingMode.PKCS7;
        _logger = logger;
    }

    public string Decrypt(string encryptedText, byte[] key, byte[] iv)
    {
        locker.EnterReadLock();
        try
        {
            var cacheKey = $"{Convert.ToBase64String(key)}-{Convert.ToBase64String(iv)}";
            if (!_keyCache.TryGetValue(cacheKey, out var cachedIv))
            {
                lock (_cacheLock)
                {
                    if (!_keyCache.TryGetValue(cacheKey, out cachedIv))
                    {
                        _keyCache[cacheKey] = iv;
                        cachedIv = iv;
                    }
                }
            }

            _aes.Key = key;
            _aes.IV = cachedIv;

            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
            _logger.LogInformation("Decryption started.");

            try
            {
                byte[] cipherTextBytes = Convert.FromBase64String(encryptedText);
                using (var decryptor = _aes.CreateDecryptor(_aes.Key, _aes.IV))
                using (var memoryStream = new MemoryStream(cipherTextBytes))
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                using (var reader = new StreamReader(cryptoStream))
                {
                    var plaintext = reader.ReadToEnd();

                    stopwatch.Stop();
                    _logger.LogInformation("Decryption succeeded.");
                    return plaintext;
                }
            }
            catch (Exception ex)
            {
                stopwatch.Stop();
                _logger.LogError(ex, "Decryption failed.");
                throw; // Optionally rethrow or handle differently
            }
        }
        finally
        {
            locker.ExitReadLock();
        }
    }

    public void RotateKeys(byte[] newKey, byte[] newIv)
    {
        locker.EnterWriteLock();
        try
        {
            _aes.Key = newKey;
            _aes.IV = newIv;

            // Clear the cache when rotating keys to prevent using old IVs with new keys
            lock (_cacheLock)
            {
                _keyCache.Clear();
            }

            _logger.LogInformation("Keys rotated.");
        }
        finally
        {
            locker.ExitWriteLock();
        }
    }

    public void Dispose()
    {
        _aes?.Dispose();
    }
}

