```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char status;
    char *info;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} TrafficEvent;

typedef struct {
    TrafficEvent **events;
    size_t size;
    pthread_mutex_t lock;
    int error_flag;
} TrafficEventManager;

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

TrafficEventManager* create_traffic_event_manager(size_t limit) {
    TrafficEventManager *manager = malloc(sizeof(TrafficEventManager));
    if (!manager) return NULL;

    manager->events = calloc(limit, sizeof(TrafficEvent *));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->size = limit;
    pthread_mutex_init(&manager->lock, NULL);
    manager->error_flag = 0;

    for (size_t i = 0; i < limit; ++i) {
        TrafficEvent *event = malloc(sizeof(TrafficEvent));
        if (!event) {
            manager->error_flag = 1;
            break;
        }

        event->offset = i;
        event->key = i;

        Record *record = &event->record;
        record->value = rand() % 100; // Example range
        record->status = (rand() % 2 == 0) ? 'A' : 'B';

        char random_string[11];
        generate_random_string(random_string, sizeof(random_string));
        record->info = strdup(random_string);
        if (!record->info) {
            manager->error_flag = 1;
            free(event);
            break;
        }

        pthread_mutex_lock(&manager->lock);
        manager->events[i] = event;
        pthread_mutex_unlock(&manager->lock);

        if (manager->error_flag) {
            for (size_t j = 0; j <= i; ++j) {
                TrafficEvent *ev = manager->events[j];
                if (ev) {
                    free(ev->record.info);
                    free(ev);
                }
            }
            break;
        }
    }

    return manager;
}

void destroy_traffic_event_manager(TrafficEventManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        TrafficEvent *event = manager->events[i];
        if (event) {
            free(event->record.info);
            free(event);
        }
    }
    free(manager->events);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int serialize_traffic_event_manager(const TrafficEventManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->size; ++i) {
        TrafficEvent *event = manager->events[i];
        if (event) {
            fwrite(&event->offset, sizeof(long), 1, file);
            fwrite(&event->key, sizeof(int), 1, file);

            Record record = event->record;
            fwrite(&record.value, sizeof(int), 1, file);
            fputc(record.status, file);

            size_t len = strlen(record.info) + 1;
            fwrite(&len, sizeof(size_t), 1, file);
            fwrite(record.info, sizeof(char), len, file);
        }
    }
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return 0;
}

int deserialize_traffic_event_manager(TrafficEventManager **manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t limit;
    fread(&limit, sizeof(size_t), 1, file);

    *manager = create_traffic_event_manager(limit);
    if (!*manager || (*manager)->error_flag) {
        fclose(file);
        return -1;
    }

    pthread_mutex_lock((*manager)->lock);
    for (size_t i = 0; i < limit; ++i) {
        TrafficEvent *event = malloc(sizeof(TrafficEvent));
        fread(&event->offset, sizeof(long), 1, file);
        fread(&event->key, sizeof(int), 1, file);

        Record record;
        fread(&record.value, sizeof(int), 1, file);
        char status;
        fgetc(file);
        record.status = status;

        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        record.info = malloc(len);
        if (!record.info) {
            (*manager)->error_flag = 1;
            break;
        }
        fread(record.info, sizeof(char), len, file);

        event->record = record;
        (*manager)->events[i] = event;

        if ((*manager)->error_flag) {
            for (size_t j = 0; j <= i; ++j) {
                TrafficEvent *ev = (*manager)->events[j];
                if (ev) {
                    free(ev->record.info);
                    free(ev);
                }
            }
            break;
        }
    }
    pthread_mutex_unlock((*manager)->lock);

    fclose(file);
    return 0;
}

// Example usage
int main() {
    srand(time(NULL));

    TrafficEventManager *manager = create_traffic_event_manager(10);
    if (!manager || manager->error_flag) {
        fprintf(stderr, "Failed to initialize traffic event manager\n");
        return EXIT_FAILURE;
    }

    serialize_traffic_event_manager(manager, "traffic_data.bin");

    TrafficEventManager *loadedManager = NULL;
    if (deserialize_traffic_event_manager(&loadedManager, "traffic_data.bin") != 0) {
        fprintf(stderr, "Failed to load traffic data from disk\n");
        destroy_traffic_event_manager(manager);
        return EXIT_FAILURE;
    }

    destroy_traffic_event_manager(loadedManager);
    destroy_traffic_event_manager(manager);

    return EXIT_SUCCESS;
}
```

