LogEntry* find_log_entry(LogEntry **head, int log_id) {
    pthread_mutex_lock(&log_lock);
    LogEntry *current = *head;
    while (current) {
        if (current->log_id == log_id) {
            pthread_mutex_unlock(&log_lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&log_lock);
    return NULL;
}

void add_or_update_log_entry(LogEntry **head, int log_id, const char *message, SeverityLevel severity) {
    LogEntry *entry = find_log_entry(head, log_id);

    if (entry) {
        free(entry->message); // Free existing message
        entry->message = strdup(message);
        entry->severity = severity;
    } else {
        entry = create_log_entry(log_id, message, severity);
        if (!entry) return;

        pthread_mutex_lock(&log_lock);
        entry->next = *head;
        *head = entry;
        pthread_mutex_unlock(&log_lock);
    }
}

void free_all_logs(LogEntry **head) {
    LogEntry *current = *head;
    while (current) {
        LogEntry *temp = current;
        current = current->next;
        free_log_entry(temp);
    }
    *head = NULL;
}

// Comparison function for qsort
int compare_timestamps(const void *a, const void *b) {
    time_t timestamp_a = ((LogEntry *)a)->timestamp;
    time_t timestamp_b = ((LogEntry *)b)->timestamp;

    return (timestamp_a > timestamp_b) - (timestamp_a < timestamp_b);
}

void sort_logs(LogEntry **head) {
    pthread_mutex_lock(&log_lock);

    if (!*head || !(*head)->next) {
        pthread_mutex_unlock(&log_lock);
        return;
    }

    // Convert linked list to array for sorting
    LogEntry *current = *head;
    int count = 0;
    while (current) {
        count++;
        current = current->next;
    }

    LogEntry **array = malloc(count * sizeof(LogEntry *));
    if (!array) return;

    current = *head;
    for (int i = 0; i < count; ++i) {
        array[i] = current;
        current = current->next;
    }

    // Use qsort for efficient sorting
    qsort(array, count, sizeof(LogEntry *), compare_timestamps);

    // Convert sorted array back to linked list
    LogEntry dummy;
    dummy.next = NULL;
    *head = &dummy;

    for (int i = 0; i < count; ++i) {
        array[i]->next = dummy.next;
        dummy.next = array[i];
    }

    free(array);
    pthread_mutex_unlock(&log_lock);
}

void manage_logs_and_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num_pdus, LogEntry **logs_head) {
