#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

#define MAX_RECORDS 1000
#define CACHE_SIZE 50
#define LOG_BUFFER_SIZE 1024

typedef struct {
    int value;
    char buffer[256];
    float priority_level;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    time_t event_timestamp;
} CollectionRecord;

typedef struct CacheNode {
    CollectionRecord* record;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    size_t size;
} LRUCache;

pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t record_mutex = PTHREAD_MUTEX_INITIALIZER;

size_t total_memory_budget = 1024 * 1024; // Example budget
size_t records_count = 0;

LRUCache cache;

void log_message(const char* message) {
    static char log_buffer[LOG_BUFFER_SIZE];
    snprintf(log_buffer, LOG_BUFFER_SIZE, "%s\n", message);
    printf("%s", log_buffer); // Replace with actual logging mechanism
}

CollectionRecord* create_record(long offset, int key, Record record, time_t event_timestamp) {
    CollectionRecord* new_record = (CollectionRecord*)malloc(sizeof(CollectionRecord));
    if (!new_record) {
        log_message("Memory allocation failed for CollectionRecord");
        return NULL;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->record = record;
    new_record->event_timestamp = event_timestamp;
    return new_record;
}

void free_record(CollectionRecord* record) {
    if (record) {
        free(record);
    }
}

int add_record_to_cache(LRUCache* cache, CollectionRecord* record) {
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) {
        log_message("Memory allocation failed for CacheNode");
        return -1;
    }

    pthread_mutex_lock(&cache_mutex);
    node->record = record;

    if (cache->size == CACHE_SIZE) {
        // Evict LRU
        free_record(cache->tail->record);
        free(cache->tail);
        cache->tail = cache->tail->prev;
        if (cache->tail) {
            cache->tail->next = NULL;
        } else {
            cache->head = NULL;
        }
        cache->size--;
    }

    node->next = cache->head;
    node->prev = NULL;

    if (cache->head) {
        cache->head->prev = node;
    }
    cache->head = node;

    if (!cache->tail) {
        cache->tail = node;
    }
    cache->size++;

    pthread_mutex_unlock(&cache_mutex);
    return 0;
}

CollectionRecord* get_record_from_cache(LRUCache* cache, int key) {
    pthread_mutex_lock(&cache_mutex);

    CacheNode* current = cache->head;
    while (current) {
        if (current->record->key == key) {
            // Move accessed node to head
            if (current != cache->head) {
                if (current->prev) {
                    current->prev->next = current->next;
                }
                if (current->next) {
                    current->next->prev = current->prev;
                }
                if (cache->tail == current) {
                    cache->tail = current->prev;
                }

                current->next = cache->head;
                current->prev = NULL;

                if (cache->head) {
                    cache->head->prev = current;
                }
                cache->head = current;
            }
            pthread_mutex_unlock(&cache_mutex);
            return current->record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

void initialize_cache(LRUCache* cache) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
}

int add_record(long offset, int key, Record record, time_t event_timestamp, size_t memory_budget) {
    pthread_mutex_lock(&record_mutex);

    if (records_count >= MAX_RECORDS) {
        log_message("Record count exceeds maximum limit");
        pthread_mutex_unlock(&record_mutex);
        return -1;
    }

    if ((memory_budget + sizeof(CollectionRecord)) > total_memory_budget) {
        log_message("Memory budget exceeded");
        pthread_mutex_unlock(&record_mutex);
        return -1;
    }

    CollectionRecord* new_record = create_record(offset, key, record, event_timestamp);
    if (!new_record) {
        pthread_mutex_unlock(&record_mutex);
        return -1;
    }

    int cache_status = add_record_to_cache(&cache, new_record);
    if (cache_status != 0) {
        free_record(new_record);
        pthread_mutex_unlock(&record_mutex);
        return -1;
    }

    records_count++;
    pthread_mutex_unlock(&record_mutex);
    return 0;
}

void cleanup() {
    pthread_mutex_lock(&cache_mutex);

    CacheNode* current = cache.head;
    while (current) {
        CacheNode* next = current->next;
        free_record(current->record);
        free(current);
        current = next;
    }

    cache.head = NULL;
    cache.tail = NULL;
    cache.size = 0;

    pthread_mutex_unlock(&cache_mutex);

    pthread_mutex_destroy(&cache_mutex);
    pthread_mutex_destroy(&record_mutex);
}

int main() {
    initialize_cache(&cache);

    Record record = { .value = 42, .priority_level = 1.5 };
    strcpy(record.buffer, "Example buffer");

    add_record(1000L, 1, record, time(NULL), sizeof(CollectionRecord));

    CollectionRecord* cached_record = get_record_from_cache(&cache, 1);
    if (cached_record) {
        printf("Retrieved record with key: %d\n", cached_record->key);
    }

    cleanup();
    return 0;
}
```

