                    double d_value, const char *c_string, int i_value);

// Internal function to handle reallocation
void ensure_capacity(Element ***e_array, size_t *e_size, size_t *e_capacity, size_t new_elements);

void initialize_arrays(double **d_array, size_t *d_size, size_t d_capacity,
                       char ***c_array, size_t *c_size, size_t c_capacity,
                       Element ***e_array, size_t *e_size, size_t e_capacity) {
    // Initialize the arrays
    *d_array = (double *)calloc(d_capacity, sizeof(double));
    if (!*d_array) {
        fprintf(stderr, "Failed to allocate memory for double array\n");
        exit(EXIT_FAILURE);
    }

    *c_array = (char **)calloc(c_capacity, sizeof(char *));
    if (!*c_array) {
        free(*d_array);
        fprintf(stderr, "Failed to allocate memory for char array\n");
        exit(EXIT_FAILURE);
    }

    *e_array = (Element **)malloc(e_capacity * sizeof(Element));
    if (!*e_array) {
        free(*d_array);
        free(*c_array);
        fprintf(stderr, "Failed to allocate memory for element array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize sizes and capacities
    *d_size = 0;
    *c_size = 0;
    *e_size = 0;
}

void append_element(double **d_array, size_t *d_size, char ***c_array, size_t *c_size,
                    Element ***e_array, size_t *e_size, size_t *e_capacity,
                    double d_value, const char *c_string, int i_value) {
    // Ensure enough capacity
    if (*e_size >= *e_capacity) {
        ensure_capacity(e_array, e_size, e_capacity, 1); // Increment capacity by one for simplicity
    }

    // Append to the arrays
    (*d_array)[(*d_size)++] = d_value;

    char *str_copy = strdup(c_string);
    if (!str_copy) {
        fprintf(stderr, "Failed to duplicate string\n");
        exit(EXIT_FAILURE);
    }
    (*c_array)[*c_size] = str_copy;
    (*c_size)++;

    Element new_element = {d_value, str_copy, i_value};
    (*e_array)[(*e_size)] = new_element;
    (*e_size)++;
}

void ensure_capacity(Element ***e_array, size_t *e_size, size_t *e_capacity, size_t new_elements) {
    size_t new_capacity = (*e_capacity == 0) ? 1 : (*e_capacity) * 2; // Double the capacity or set to 1 if initially zero
    while (new_capacity < *e_size + new_elements) {
        new_capacity *= 2;
    }

    Element **temp_array = realloc(*e_array, new_capacity * sizeof(Element));
    if (!temp_array) {
        fprintf(stderr, "Failed to reallocate memory for element array\n");
        exit(EXIT_FAILURE);
    }
    *e_array = temp_array;
    *e_capacity = new_capacity;
}

int main() {
    // Example usage
    double *d_array = NULL;
    size_t d_size = 0, d_capacity = 10;

    char **c_array = NULL;
    size_t c_size = 0, c_capacity = 10;

    Element **e_array = NULL;
    size_t e_size = 0, e_capacity = 10;

    initialize_arrays(&d_array, &d_size, d_capacity,
                      &c_array, &c_size, c_capacity,
                      (Element **)&e_array, &e_size, e_capacity);

    append_element(&d_array, &d_size, &c_array, &c_size,
                   (Element **)&e_array, &e_size, &e_capacity,
                   3.14, "Hello", 42);

    for (size_t i = 0; i < e_size; ++i) {
        printf("Element %zu: {%.2f, \"%s\", %d}\n",
               i, (*((double *)d_array + i)), (*c_array)[i], (*((Element **)e_array)[i]).value);
    }

    // Free allocated memory
    free(d_array);
    for (size_t i = 0; i < c_size; ++i) {
        free(c_array[i]);
    }
    free(c_array);
    free(e_array);

    return 0;
}
