// Function prototypes
Record* allocate_records(size_t size, unsigned int seed);
void free_records(Record* records, size_t size);
OffsetMap* create_offset_map();
void insert_into_offset_map(OffsetMap* map, int key, long offset);
long get_offset_from_map(OffsetMap* map, int key);
void free_offset_map(OffsetMap* map);
void print_offset_map(OffsetMap* map);
void log_memory_usage(size_t size);

// Random number generator
int random_int(unsigned int *seed) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return *seed % 1000 + 1; // Range: [1, 1000]
}

long random_long(unsigned int *seed) {
    long rand_val1 = random_int(seed);
    long rand_val2 = random_int(seed);
    return (rand_val1 - 500) * (rand_val2 - 500); // Approx range: [-250000, 249751]
}

// Allocation and initialization
Record* allocate_records(size_t size, unsigned int seed) {
    Record* records = malloc(size * sizeof(Record));
    if (!records) return NULL;

    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        do {
            records[i].key = random_int(&seed);
        } while (get_offset_from_map(create_offset_map(), records[i].key) != -1);

        records[i].offset = random_long(&seed);
    }

    log_memory_usage(size * sizeof(Record));
    return records;
}

void free_records(Record* records, size_t size) {
    free(records);
    log_memory_usage(0); // Log memory deallocation
}

// OffsetMap operations
OffsetMap* create_offset_map() {
    OffsetMap* map = malloc(sizeof(OffsetMap));
    if (!map) return NULL;
    map->head = NULL;
    return map;
}

void insert_into_offset_map(OffsetMap* map, int key, long offset) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->key = key;
    new_node->offset = offset;
    new_node->next = map->head;
    map->head = new_node;
}

long get_offset_from_map(OffsetMap* map, int key) {
    Node* current = map->head;
    while (current) {
        if (current->key == key) return current->offset;
        current = current->next;
    }
    return -1; // Key not found
}

void free_offset_map(OffsetMap* map) {
    Node* current = map->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(map);
    log_memory_usage(0); // Log memory deallocation
}

// Utility functions
void print_offset_map(OffsetMap* map) {
    Node* current = map->head;
    while (current) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
}

void log_memory_usage(size_t size) {
    // Placeholder for logging memory usage
    printf("Current allocated memory size: %zu bytes\n", size);
}

// Main function for demonstration purposes
int main() {
    unsigned int seed = time(NULL);
    Record* records = allocate_records(INITIAL_SIZE, seed);

    if (!records) {
        fprintf(stderr, "Failed to allocate initial records.\n");
        return EXIT_FAILURE;
    }

    OffsetMap* map = create_offset_map();
    for (size_t i = 0; i < INITIAL_SIZE && records[i].key != 0; ++i) {
        insert_into_offset_map(map, records[i].key, records[i].offset);
    }

    print_offset_map(map);

    free_records(records, INITIAL_SIZE);
    free_offset_map(map);

    return EXIT_SUCCESS;
}
