#define MAX_NFAPI_PDU_COUNT 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to check for uniqueness of RX_UE_INFORMATION_TAG and RNTI
int is_unique(const NFAPI_CRC_INDICATION_PDU_T *array, size_t count, uint16_t tag, uint32_t rnti) {
    for (size_t i = 0; i < count; ++i) {
        if ((array[i].RX_UE_INFORMATION_TAG == tag && array[i].RNTI == rnti)) {
            return 0;
        }
    }
    return 1;
}

// Function to dynamically manage NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *manage_nfa_crc_pdus(size_t count, size_t *allocated_count) {
    if (count > MAX_NFAPI_PDU_COUNT) {
        fprintf(stderr, "Requested count exceeds maximum allowed limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        uint16_t tag;
        uint32_t rnti;

        // Ensure uniqueness
        do {
            tag = rand() % 65536;  // Random value within range of RX_UE_INFORMATION_TAG
            rnti = rand() % 4294967295UL;  // Random value within range of RNTI
        } while (!is_unique(pdus, i, tag, rnti));

        pdus[i].RX_UE_INFORMATION_TAG = tag;
        pdus[i].RNTI = rnti;

        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
    }

    *allocated_count = count;
    return pdus;
}

// Function to free allocated memory
void free_nfa_crc_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}
```

