#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define SESSION_ID_LEN 36

typedef struct {
    char session_id[SESSION_ID_LEN];
    char user_name[256];
    time_t last_active;
    int ref_count;
    int is_valid;
} Session;

typedef struct Node {
    Session session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SessionList;

SessionList* init_session_list() {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int generate_unique_id(char* id) {
    // Implement a simple unique ID generator
    snprintf(id, SESSION_ID_LEN, "%ld", time(NULL)); // Placeholder for real implementation
    return 1; // Success
}

Session* init_session(const char* user_name) {
    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) return NULL;

    generate_unique_id(session->session_id);
    strncpy(session->user_name, user_name, sizeof(session->user_name) - 1);
    session->last_active = time(NULL);
    session->ref_count = 0;
    session->is_valid = 1;

    return session;
}

Session* get_session(SessionList* list, const char* id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->session.session_id, id) == 0 && current->session.is_valid) {
            pthread_mutex_unlock(&list->lock);
            return &current->session;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int increment_ref_count(SessionList* list, const char* id) {
    Session* session = get_session(list, id);
    if (!session || !session->is_valid) return -1;

    pthread_mutex_lock(&list->lock);

    session->ref_count++;
    session->last_active = time(NULL);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int decrement_ref_count(SessionList* list, const char* id) {
    Session* session;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if (strcmp((*current)->session.session_id, id) == 0 && (*current)->session.is_valid) {
            session = &(*current)->session;

            session->ref_count--;
            if (session->ref_count <= 0 && !session->is_valid) {
                Node* to_delete = *current;
                *current = (*current)->next;
                free(to_delete);
            }

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Session not found or invalid
}

int update_last_active(SessionList* list, const char* id) {
    Session* session = get_session(list, id);
    if (!session || !session->is_valid) return -1;

    pthread_mutex_lock(&list->lock);

    session->last_active = time(NULL);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void cleanup_expired_sessions(SessionList* list) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        Node* entry = *current;

        if (entry->session.is_valid && difftime(time(NULL), entry->session.last_active) > 3600) { // 1 hour timeout
            entry->session.is_valid = 0;
        }

        if (!entry->session.is_valid && entry->session.ref_count <= 0) {
            *current = (*current)->next;
            free(entry);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_session_list(SessionList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
