import <string.h>
#include <time.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
} KeyRecord;

typedef struct {
    int value;
    char buffer[256];
    double timestamp;
} Record;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    u_char ip_address[4]; // IPv4
} DNSResolutionResult;

typedef struct {
    char unique_id[64];
    char *variable_length_string;
    int metadata_type_flag;
} CustomMetadataEntry;

int total_records = 0;

// Error log function
void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        return;
    }
    time_t current_time = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&current_time), message);
    fclose(log_file);
}

// Randomly generate char buffer content
void fill_random_buffer(char *buffer, size_t size, const char *charset) {
    for (size_t i = 0; i < size - 1; ++i) {
        buffer[i] = charset[rand() % strlen(charset)];
    }
    buffer[size - 1] = '\0';
}

// Resolve hostname to IP address
int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct hostent *host;
    int retries = 5;

    while (retries > 0) {
        if ((host = gethostbyname(hostname)) != NULL) {
            memcpy(ip_address, host->h_addr, host->h_length);
            return 1; // Success
        }

        retries--;
        sleep(2); // Backoff strategy
    }

    log_error("DNS resolution failed.");
    return 0; // Failure
}

// Serialize data structure to file
int serialize_to_file(FILE *file, long *offsets, KeyRecord *keys, Record *records,
                      NFAPI_CRC_INDICATION_PDU_T *nfa_structures, DNSResolutionResult *dns_results,
                      CustomMetadataEntry *metadata_entries) {
    if (fwrite(offsets, sizeof(long), total_records, file) != total_records ||
        fwrite(keys, sizeof(KeyRecord), total_records, file) != total_records ||
        fwrite(records, sizeof(Record), total_records, file) != total_records ||
        fwrite(nfa_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), total_records, file) != total_records ||
        fwrite(dns_results, sizeof(DNSResolutionResult), total_records, file) != total_records ||
        fwrite(metadata_entries, sizeof(CustomMetadataEntry), total_records, file) != total_records) {

        log_error("Serialization failed.");
        return 0;
    }

    return 1;
}

// Deserialize data structure from file
int deserialize_from_file(FILE *file, long *offsets, KeyRecord *keys, Record *records,
                          NFAPI_CRC_INDICATION_PDU_T *nfa_structures, DNSResolutionResult *dns_results,
                          CustomMetadataEntry *metadata_entries) {
    if (fread(offsets, sizeof(long), total_records, file) != total_records ||
        fread(keys, sizeof(KeyRecord), total_records, file) != total_records ||
        fread(records, sizeof(Record), total_records, file) != total_records ||
        fread(nfa_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), total_records, file) != total_records ||
        fread(dns_results, sizeof(DNSResolutionResult), total_records, file) != total_records ||
        fread(metadata_entries, sizeof(CustomMetadataEntry), total_records, file) != total_records) {

        log_error("Deserialization failed.");
        return 0;
    }

    return 1;
}

// Main function to initialize collections
int initialize_collections(int size, const char *charset) {
    if (total_records + size > MAX_RECORDS || size <= 0) {
        log_error("Invalid size parameter or memory limit exceeded.");
        return 0;
    }

    long *offsets = malloc(size * sizeof(long));
    KeyRecord *keys = malloc(size * sizeof(KeyRecord));
    Record *records = malloc(size * sizeof(Record));
    NFAPI_CRC_INDICATION_PDU_T *nfa_structures = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    DNSResolutionResult *dns_results = malloc(size * sizeof(DNSResolutionResult));
    CustomMetadataEntry *metadata_entries = malloc(size * sizeof(CustomMetadataEntry));

    if (!offsets || !keys || !records || !nfa_structures || !dns_results || !metadata_entries) {
        log_error("Memory allocation failed.");

        free(offsets);
        free(keys);
        free(records);
        free(nfa_structures);
        free(dns_results);
        free(metadata_entries);

        return 0;
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        offsets[i] = rand() % 10000;

        keys[i].key = rand() % 1000;

        records[i].value = rand() % 100;
        fill_random_buffer(records[i].buffer, sizeof(records[i].buffer), charset);
        records[i].timestamp = time(NULL);

        nfa_structures[i].RX_UE_INFORMATION_TAG = rand();
        nfa_structures[i].RNTI = rand() & 0xFFFF;
        nfa_structures[i].CRCFLAG = rand() % 2;

        char hostname[] = "example.com";
        if (!resolve_hostname(hostname, dns_results[i].ip_address)) {
            free(offsets);
            free(keys);
            free(records);
            free(nfa_structures);
            free(dns_results);
            free(metadata_entries);

            return 0;
        }

        snprintf(metadata_entries[i].unique_id, sizeof(metadata_entries[i].unique_id), "ID_%d", i);
        metadata_entries[i].variable_length_string = strdup("Variable length string");
        metadata_entries[i].metadata_type_flag = rand() % 10;

        total_records++;
    }

    return 1;
}

// Deallocate all resources
void deallocate_resources(long *offsets, KeyRecord *keys, Record *records,
                          NFAPI_CRC_INDICATION_PDU_T *nfa_structures, DNSResolutionResult *dns_results,
                          CustomMetadataEntry *metadata_entries) {
    free(offsets);
    free(keys);
    free(records);
    free(nfa_structures);
    free(dns_results);

    for (int i = 0; i < total_records; ++i) {
        free(metadata_entries[i].variable_length_string);
    }
    free(metadata_entries);
}

// Example usage
int main() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (!initialize_collections(10, charset)) {
        return 1;
    }

    FILE *file = fopen("data.bin", "wb");
    if (file == NULL) {
        log_error("Failed to open file for serialization.");
        return 1;
    }

    long offsets[MAX_RECORDS];
    KeyRecord keys[MAX_RECORDS];
    Record records[MAX_RECORDS];
    NFAPI_CRC_INDICATION_PDU_T nfa_structures[MAX_RECORDS];
    DNSResolutionResult dns_results[MAX_RECORDS];
    CustomMetadataEntry metadata_entries[MAX_RECORDS];

    if (!serialize_to_file(file, offsets, keys, records, nfa_structures, dns_results, metadata_entries)) {
        fclose(file);
        return 1;
    }

    fclose(file);

    file = fopen("data.bin", "rb");
    if (file == NULL) {
        log_error("Failed to open file for deserialization.");
        return 1;
    }

    if (!deserialize_from_file(file, offsets, keys, records, nfa_structures, dns_results, metadata_entries)) {
        fclose(file);
        return 1;
    }

    fclose(file);

    deallocate_resources(offsets, keys, records, nfa_structures, dns_results, metadata_entries);
    return 0;
}
