#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 10000000

typedef struct {
    int socket_fd;
    int connection_id;
    time_t timestamp;
    int service_id;
} Connection;

typedef struct Node {
    Connection conn;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} ConnectionList;

unsigned int hash(int connection_id, size_t capacity) {
    return (connection_id & 0x7FFFFFFF) % capacity;
}

ConnectionList* create_connection_list(size_t capacity) {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    list->buckets = (Node**)calloc(capacity, sizeof(Node*));
    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_connection_list(ConnectionList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        Node* current = list->buckets[i];
        while (current) {
            Node* to_free = current;
            current = current->next;
            free(to_free);
        }
    }
    free(list->buckets);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_connection(ConnectionList* list, Connection conn) {
    pthread_mutex_lock(&list->lock);

    unsigned int index = hash(conn.connection_id, list->capacity);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->conn = conn;
    new_node->next = list->buckets[index];
    list->buckets[index] = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_connection(ConnectionList* list, int connection_id) {
    pthread_mutex_lock(&list->lock);

    unsigned int index = hash(connection_id, list->capacity);
    Node* current = list->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->conn.connection_id == connection_id) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->buckets[index] = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Connection not found
}

int update_timestamp(ConnectionList* list, int connection_id) {
    pthread_mutex_lock(&list->lock);

    unsigned int index = hash(connection_id, list->capacity);
    Node* current = list->buckets[index];

    while (current) {
        if (current->conn.connection_id == connection_id) {
            current->conn.timestamp = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Connection not found
}

int batch_add_connections(ConnectionList* list, Connection* conns, size_t count) {
    if (count > MAX_CONNECTIONS) {
        return -2; // Overflow condition
    }

    for (size_t i = 0; i < count; ++i) {
        if (add_connection(list, conns[i]) != 0) {
            return -1; // Failed to add a connection
        }
    }

    return 0;
}

int batch_remove_connections(ConnectionList* list, int* ids, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (remove_connection(list, ids[i]) != 0) {
            return -1; // Failed to remove a connection
        }
    }

    return 0;
}

void log_operation(const char* operation_type, int service_id, int connection_id, time_t timestamp) {
    printf("%s | Service ID: %d | Connection ID: %d | Timestamp: %ld\n", 
           operation_type, service_id, connection_id, (long)timestamp);
}
