Point generate_random_point(int min, int max) {
    Point p;
    srand((unsigned int)time(NULL));
    p.x = rand() % (max - min + 1) + min;
    p.y = rand() % (max - min + 1) + min;
    return p;
}

// Function to generate random strings of specified length
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length; // Leave space for null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof charset - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to initialize the geometry structures
Geometry* init_geometry(size_t count, double range_min, double range_max, int str_len) {
    Geometry *geometry = (Geometry *)malloc(sizeof(Geometry));
