    pthread_mutex_lock(&lock);

    // Allocate memory for arrays and check allocation success
    geometry->doubles = (double *)malloc(count * sizeof(double));
    geometry->strings = (char **)malloc(count * sizeof(char *));
    geometry->points = (Point *)malloc(count * sizeof(Point));

    if (!geometry->doubles || !geometry->strings || !geometry->points) {
        free(geometry->doubles);
        free(geometry->strings);
        free(geometry->points);
        pthread_mutex_unlock(&lock);
        free(geometry);
        return NULL;
    }

    geometry->count = count;

    // Initialize the arrays with random values
    for (size_t i = 0; i < count; ++i) {
        geometry->doubles[i] = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);
        geometry->strings[i] = (char *)malloc((str_len + 1) * sizeof(char));
        if (!geometry->strings[i]) {
            for (size_t j = 0; j < i; ++j) free(geometry->strings[j]);
            free(geometry->doubles);
            free(geometry->points);
            pthread_mutex_unlock(&lock);
            free(geometry->strings);
            free(geometry->doubles);
            free(geometry->points);
            free(geometry);
            return NULL;
        }
        generate_random_string(geometry->strings[i], str_len);

        geometry->points[i] = generate_random_point(0, 100); // Example range
    }

    pthread_mutex_unlock(&lock);
    return geometry;
}

// Function to clean up memory for the geometry structures
void cleanup_geometry(Geometry *geometry) {
    if (!geometry) return;

    pthread_mutex_lock(&lock);

    free(geometry->doubles);
    for (size_t i = 0; i < geometry->count; ++i) {
        free(geometry->strings[i]);
    }
    free(geometry->strings);
    free(geometry->points);

    pthread_mutex_unlock(&lock);
    free(geometry);
}

// Example usage
