    if (geometry) {
        // Use the geometry
        for (size_t i = 0; i < geometry->count; ++i) {
            printf("Point %zu: (%d, %d), Double: %.2f, String: %s\n",
                   i + 1, geometry->points[i].x, geometry->points[i].y,
                   geometry->doubles[i], geometry->strings[i]);
        }

        // Clean up
        cleanup_geometry(geometry);
    } else {
        fprintf(stderr, "Failed to initialize geometry.\n");
    }

    return 0;
}
