#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    int CRCFLAG; // assuming it's an integer for randomization
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables and mutex for thread-safe operations
pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
uint16_t global_rnti_pool[MAX_RNTI] = {0};
int pool_size = 0; // Number of occupied entries in the pool

// Helper functions
static int is_valid_rnti(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    for (int i = 0; i < MAX_RNTI; ++i) {
        if (global_rnti_pool[i] == rnti) {
            pthread_mutex_unlock(&rnti_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&rnti_lock);
    return 1;
}

static void add_to_rnti_pool(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    if (pool_size < MAX_RNTI) {
        global_rnti_pool[pool_size++] = rnti;
    }
    pthread_mutex_unlock(&rnti_lock);
}

static void remove_from_rnti_pool(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    for (int i = 0; i < MAX_RNTI; ++i) {
        if (global_rnti_pool[i] == rnti) {
            global_rnti_pool[i] = 0;
            // Compact the array
            for (; i < pool_size - 1; ++i) {
                global_rnti_pool[i] = global_rnti_pool[i + 1];
            }
            --pool_size;
            break;
        }
    }
    pthread_mutex_unlock(&rnti_lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N, int* success) {
    if (N <= 0 || !success) return NULL;

    *success = 1; // Assume success unless an error occurs
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        *success = 0;
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG[0] = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG[1] = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG[2] = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG[3] = rand() % 256;

        int rnti_generated = 0;
        do {
            uint16_t new_rnti = rand() % MAX_RNTI;
            if (is_valid_rnti(new_rnti)) {
                add_to_rnti_pool(new_rnti);
                array[i].RNTI = new_rnti;
                rnti_generated = 1; // Successfully generated unique RNTI
            }
        } while (!rnti_generated);

        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    return array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        for (int i = 0; i < N; ++i) {
            remove_from_rnti_pool(array[i].RNTI);
        }
        free(array);
    }
}
```"]

