typedef struct HashNode {
    int key;
    long value;
    struct HashNode *next;
} HashNode_t;

#define HASH_TABLE_SIZE 101
HashNode_t *hash_table[HASH_TABLE_SIZE];

unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

void initialize_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

void insert_into_hash_table(int key, long value) {
    unsigned int index = hash(key);
    HashNode_t *new_node = (HashNode_t *)malloc(sizeof(HashNode_t));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for hash table node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->value = value;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

long lookup_in_hash_table(int key) {
    unsigned int index = hash(key);
    HashNode_t *node = hash_table[index];
    while (node != NULL) {
        if (node->key == key) return node->value;
        node = node->next;
    }
    fprintf(stderr, "Key not found in hash table.\n");
    exit(EXIT_FAILURE); // Or handle missing keys gracefully
}

void deallocate_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode_t *node = hash_table[i];
        while (node != NULL) {
            HashNode_t *temp = node;
            node = node->next;
            free(temp);
        }
    }
}

long *allocate_offsets_array(size_t size) {
