    }
    return keys;
}

record_t *initialize_records_array(size_t size, int range_min, int range_max) {
    record_t *records = malloc(size * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        records[i].value = range_min + rand() % (range_max - range_min + 1);
        records[i].offset_reference = i; // Example: offset reference to its own index
    }
    return records;
}

void free_resources(long *offsets, int *keys, record_t *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    deallocate_hash_table();
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void thread_safe_insert(int key, long value) {
    pthread_mutex_lock(&lock);
    insert_into_hash_table(key, value);
    pthread_mutex_unlock(&lock);
}

long thread_safe_lookup(int key) {
    pthread_mutex_lock(&lock);
    long result = lookup_in_hash_table(key);
    pthread_mutex_unlock(&lock);
    return result;
}

int main() {
    size_t offset_size = 100; // Example: User-provided input
    int range_min = 1, range_max = 1000;

    long *offsets = allocate_offsets_array(offset_size);
    int *keys = allocate_keys_array(offset_size);
