    long offset_val = thread_safe_lookup(key_to_lookup);
    printf("Offset value for key %d: %ld\n", key_to_lookup, offset_val);

    free_resources(offsets, keys, records);

    pthread_mutex_destroy(&lock);

    return 0;
}
