#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    float value;
    bool flag;
    size_t count;
} data;

// Function to initialize the array of data pointers
data **initialize_data_array(size_t num_elements) {
    // Validate input range
    if (num_elements < 1 || num_elements > 1000) {
        fprintf(stderr, "Error: Number of elements must be between 1 and 1000.\n");
        return NULL;
    }

    // Allocate memory for the array of pointers
    data **data_array = malloc(num_elements * sizeof(data *));
    if (data_array == NULL) {
        perror("Failed to allocate memory for data array");
        return NULL;
    }

    // Initialize each struct in a thread-safe manner
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&lock);

        data_array[i] = malloc(sizeof(data));
        if (data_array[i] == NULL) {
            perror("Failed to allocate memory for data");
            // Free already allocated pointers before returning
            while (--i > 0) { 
                free(data_array[i]);
            }
            free(data_array);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        // Initialize struct with default values
        data_array[i]->value = 0.0f;
        data_array[i]->flag = false;
        data_array[i]->count = 0;

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return data_array;
}

// Function to free allocated memory
void free_data_array(data **data_array, size_t num_elements) {
    if (data_array == NULL) {
        return;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        if (data_array[i] != NULL) {
            free(data_array[i]);
        }
    }

    free(data_array);
}

// Example of how to integrate this function into a larger application
void example_usage() {
    size_t user_input;
    printf("Enter the number of elements (1-1000): ");
    scanf("%zu", &user_input);

    data **data_arr = initialize_data_array(user_input);
    if (data_arr == NULL) {
        // Handle allocation failure gracefully
        fprintf(stderr, "Failed to allocate and initialize data array.\n");
        return;
    }

    // Simulate work with the data array...

    // Free allocated resources when done
    free_data_array(data_arr, user_input);
}

int main() {
    example_usage();
    return 0;
}
