    return (value == 0 || value == 1);
}

void freeDataStructures(DataStructures *ds) {
    if (ds->doubleArray) free(ds->doubleArray);
    if (ds->charArray) free(ds->charArray);
    for (size_t i = 0; i < ds->elementsProcessed && ds->dataArray; ++i) {
