        printf("Enter size_t value for dataArray[%d] (must not exceed SIZE_MAX): ", i);
        scanf("%zu", &newData->sizeValue);

        ds.dataArray[i] = newData;
        ds.elementsProcessed++;
    }

cleanup:
    if (ds.allocationFailed) {
        freeDataStructures(&ds);
    }

    return ds;
}

// Example usage
