#include <string.h>

typedef struct {
    int key;
    long offset;
} Record;

// Custom realloc function to handle resizing of record array
void* custom_realloc(void *ptr, size_t old_size, size_t new_size) {
    if (new_size == 0) {
        free(ptr);
        return NULL;
    }

    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr && ptr != NULL) {
        // If reallocation fails and original pointer is not NULL
        fprintf(stderr, "Memory allocation failed during resize.\n");
        exit(EXIT_FAILURE);  // Exit or handle error as appropriate
    }

    return new_ptr;
}

// Function to check memory alignment (example for 8-byte alignment)
void* aligned_alloc(size_t size) {
    void *ptr = NULL;
#if defined(_POSIX_C_SOURCE) || defined(_XOPEN_SOURCE)
    if (posix_memalign(&ptr, 8, size) != 0) {
        return NULL; // Allocation failed
    }
#else
    ptr = _aligned_malloc(size, 8);
#endif
    return ptr;
}

// Simulate external key and offset generation
int generate_unique_key(int *last_key) {
    int new_key = ++(*last_key);
    // In a real system, check against an external source to ensure uniqueness
    return new_key;
}

long generate_offset() {
    // Simulate generating unique offset value
    static long last_offset = 0;
    return ++last_offset;
}

// Function to initialize and manage memory allocation for arrays
int init_memory_management(int key_count, int offset_count, int initial_records, int max_records, size_t max_memory) {
    if (key_count <= 0 || offset_count <= 0 || initial_records <= 0 || max_records <= initial_records || max_memory <= 0) {
        fprintf(stderr, "Invalid parameters.\n");
        return -1;
    }

    // Calculate required memory
    size_t key_mem = sizeof(int) * key_count;
    size_t offset_mem = sizeof(long) * offset_count;
    size_t record_mem = sizeof(Record) * initial_records;

    if (key_mem + offset_mem + record_mem > max_memory) {
        fprintf(stderr, "Memory limit exceeded with the initial allocation.\n");
        return -1;
    }

    // Allocate memory for keys and offsets
    int *keys = aligned_alloc(key_mem);
    long *offsets = aligned_alloc(offset_mem);
    Record *records = aligned_alloc(record_mem);

    if (!keys || !offsets || !records) {
        fprintf(stderr, "Failed to allocate initial memory.\n");
        free(keys);  // Safe as keys will be NULL on failure
        free(offsets);
        free(records);
        return -1;
    }

    int last_key = 0;

    for (int i = 0; i < key_count; ++i) {
        keys[i] = generate_unique_key(&last_key);
    }

    for (int i = 0; i < offset_count; ++i) {
        offsets[i] = generate_offset();
    }

    for (int i = 0; i < initial_records; ++i) {
        records[i].key = keys[i % key_count];
        records[i].offset = offsets[i % offset_count];
    }

    size_t current_memory_usage = key_mem + offset_mem + record_mem;

    if (current_memory_usage > max_memory) {
        fprintf(stderr, "Current memory usage exceeds limit after initialization.\n");
        free(keys);
        free(offsets);
        free(records);
        return -1;
    }

    // Function to add a new record dynamically
    void add_record(int new_key, long new_offset) {
        if (initial_records >= max_records) {
            size_t new_size = sizeof(Record) * (2 * initial_records);
            Record* temp_records = custom_realloc(records, sizeof(Record) * initial_records, new_size);

            if (!temp_records) {
                fprintf(stderr, "Failed to resize records array.\n");
                free(keys);  // Safe as keys will be NULL on failure
                free(offsets);
                free(records);
                return;
            }

            records = temp_records;
            current_memory_usage += sizeof(Record) * initial_records; // New added memory size

            if (current_memory_usage > max_memory) {
                fprintf(stderr, "Memory limit exceeded after resizing.\n");
                free(keys);  // Safe as keys will be NULL on failure
                free(offsets);
                free(records);
                exit(EXIT_FAILURE);  // Exit or handle error as appropriate
            }

            initial_records *= 2;
        }

        records[initial_records++] = (Record){new_key, new_offset};
    }

    printf("Initialization successful. Memory usage: %zu bytes.\n", current_memory_usage);

    // Cleanup function to free all allocated memory safely
    void cleanup() {
        free(keys);
        free(offsets);
        free(records);
    }

    return 0;  // Return success status
}

int main() {
    if (init_memory_management(10, 5, 8, 20, 1024) != 0) {
        fprintf(stderr, "Failed to initialize memory management.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
