// Define necessary structs
typedef struct {
    int crcFlag; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfo;
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging levels
typedef enum {
    LOG_LEVEL_NONE,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} LogLevel;

// Logger function prototype
void log_message(LogLevel level, const char* format, ...);

// Thread-safe resource access
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
#define LOCK_LIST() pthread_mutex_lock(&listMutex)
#define UNLOCK_LIST() pthread_mutex_unlock(&listMutex)

// Function to allocate and manage NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_list(size_t count, unsigned long seed, LogLevel logLevel) {
    // Timeout configuration (in milliseconds)
    const int allocationTimeout = 1000; 
    time_t startTime = time(NULL);

    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    // Dynamic memory allocation with timeout
    while ((time(NULL) - startTime) * 1000 < allocationTimeout) {
        LOCK_LIST();
        list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (list != NULL) {
            break;
        }
        UNLOCK_LIST();
    }

    if (list == NULL) {
        log_message(logLevel, "Error: Memory allocation failed after timeout.");
        return NULL;
    }

    srand(seed); // Initialize random seed

    for (size_t i = 0; i < count; ++i) {
        list[i].ueInfo.RNTI = rand(); // Populate with a random RNTI
        list[i].rnti = rand();        // Additional RNTI value if necessary
        list[i].crcIndication.crcFlag = rand() % 2; // Randomly set CRC flag

        log_message(logLevel, "Created NFAPI_CRC_INDICATION_PDU_T: RX_UE_INFORMATION_TAG(%lu), RNTI(%lu), CRC_FLAG(%d)",
                    list[i].ueInfo.RNTI, list[i].rnti, list[i].crcIndication.crcFlag);
    }

    // Validation check
    for (size_t i = 0; i < count; ++i) {
        if ((list[i].crcIndication.crcFlag != 0 && list[i].crcIndication.crcFlag != 1)) {
            log_message(logLevel, "Validation Error: CRC_FLAG not set correctly for element %zu.", i);
            // Implement fallback strategy
            list[i].crcIndication.crcFlag = 0; // Reset to default value
        }
    }

    UNLOCK_LIST();

    return list;
}

// Example logger implementation (can be replaced with a real logging framework)
void log_message(LogLevel level, const char* format, ...) {
    if (level == LOG_LEVEL_NONE) return;

    va_list args;
    va_start(args, format);
    time_t currentTime = time(NULL);
    char timeStr[20];
    strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", localtime(&currentTime));

    printf("[%s] ", timeStr);

    switch (level) {
        case LOG_LEVEL_ERROR:
            printf("ERROR: ");
            break;
        case LOG_LEVEL_INFO:
            printf("INFO: ");
            break;
        case LOG_LEVEL_DEBUG:
            printf("DEBUG: ");
            break;
    }

    vprintf(format, args);
    printf("\n");

    va_end(args);
}

// Example usage
int main() {
    LogLevel logLevel = LOG_LEVEL_DEBUG; // Set desired log level

    size_t count = 10;
    unsigned long seed = 12345;

    NFAPI_CRC_INDICATION_PDU_T* pduList = generate_crc_indication_pdu_list(count, seed, logLevel);

    if (pduList != NULL) {
        free(pduList); // Free memory after usage
    }

    return 0;
}
