#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <sys/time.h>

#define MAX_CONNECTIONS 10000

typedef struct {
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    uint16_t src_port;
    uint16_t dst_port;
    time_t last_activity;
} tcp_connection;

typedef struct node {
    tcp_connection conn;
    struct node* next;
} connection_node;

typedef struct {
    connection_node* head;
    int count;
    pthread_mutex_t lock;
} connection_list;

int ip_equal(const char* ip1, const char* ip2) {
    return strcmp(ip1, ip2) == 0;
}

int add_connection(connection_list* list, tcp_connection new_conn) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_CONNECTIONS) {
        printf("Maximum connection limit reached.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    for (connection_node* curr = list->head; curr != NULL; curr = curr->next) {
        if (ip_equal(curr->conn.src_ip, new_conn.src_ip) &&
            ip_equal(curr->conn.dst_ip, new_conn.dst_ip)) {
            printf("Duplicate connection detected.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    connection_node* new_node = malloc(sizeof(connection_node));
    if (!new_node) {
        perror("Failed to allocate memory for new connection");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    memcpy(&new_node->conn, &new_conn, sizeof(tcp_connection));

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_stale_connections(connection_list* list) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list->lock);

    connection_node** curr = &list->head;

    while (*curr) {
        if (difftime(current_time, (*curr)->conn.last_activity) > 60) { // Example: 1 minute timeout
            connection_node* to_free = *curr;
            *curr = (*curr)->next;
            free(to_free);
            list->count--;
        } else {
            curr = &(*curr)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_connection_list(connection_list* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    fwrite(&list->count, sizeof(int), 1, file);
    connection_node* curr = list->head;

    while (curr) {
        fwrite(&curr->conn, sizeof(tcp_connection), 1, file);
        curr = curr->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

int deserialize_connection_list(connection_list* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return -1;
    }

    int count;
    fread(&count, sizeof(int), 1, file);

    pthread_mutex_lock(&list->lock);

    list->head = NULL;
    list->count = 0;

    while (fread(&((connection_node*)malloc(sizeof(connection_node)))->conn, sizeof(tcp_connection), 1, file) == 1) {
        connection_node* new_node = malloc(sizeof(connection_node));
        if (!new_node) {
            perror("Failed to allocate memory during deserialization");
            break;
        }

        new_node->next = list->head;
        list->head = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

void* process_event(void* arg) {
    tcp_connection* conn = (tcp_connection*)arg;

    struct timeval start, end;
    gettimeofday(&start, NULL);

    // Simulate processing
    usleep(10000); // Example: 10ms delay

    gettimeofday(&end, NULL);
    long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_sec - start.tv_sec);

    printf("Processed connection from %s:%u to %s:%u in %ld microseconds\n",
           conn->src_ip, conn->src_port,
           conn->dst_ip, conn->dst_port,
           duration);

    return NULL;
}

void process_all_connections(connection_list* list) {
    pthread_t threads[MAX_CONNECTIONS];

    pthread_mutex_lock(&list->lock);

    connection_node* curr = list->head;

    while (curr && list->count > 0) {
        pthread_create(&threads[list->count - 1], NULL, process_event, &curr->conn);
        curr = curr->next;
        list->count--;
    }

    pthread_mutex_unlock(&list->lock);

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
        }
    }
}

void initialize_connection_list(connection_list* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int main() {
    connection_list connections;
    initialize_connection_list(&connections);

    tcp_connection conn1 = { .src_ip = "192.168.1.10", .dst_ip = "192.168.1.20", .src_port = 1234, .dst_port = 80, .last_activity = time(NULL) };

    add_connection(&connections, conn1);
    serialize_connection_list(&connections, "connections.dat");

    connection_list new_connections;
    initialize_connection_list(&new_connections);

    deserialize_connection_list(&new_connections, "connections.dat");
    process_all_connections(&new_connections);

    return 0;
}
