#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define HASH_TABLE_SIZE 16384
#define INACTIVITY_THRESHOLD_SECONDS 300 // Example threshold

typedef struct {
    char *session_id;
    time_t last_active_timestamp;
    char *user_agent;
    int connection_status; // 1 for active, 0 for inactive
} DeviceSession;

typedef struct HashNode {
    DeviceSession session;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    pthread_mutex_t lock[HASH_TABLE_SIZE];
    size_t bucket_count;
} HashTable;

unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % HASH_TABLE_SIZE;
}

HashTable* initialize_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->lock[i], NULL);
    }
    table->bucket_count = HASH_TABLE_SIZE;
    return table;
}

void free_hash_node(HashNode *node) {
    if (!node) return;
    free(node->session.session_id);
    free(node->session.user_agent);
    free(node);
}

void add_or_update_session(HashTable *table, const char *session_id, time_t last_active, const char *user_agent, int connection_status) {
    unsigned long index = hash_function(session_id);
    pthread_mutex_lock(&table->lock[index]);

    HashNode *current = table->buckets[index];
    while (current) {
        if (strcmp(current->session.session_id, session_id) == 0) {
            current->session.last_active_timestamp = last_active;
            free(current->session.user_agent);
            current->session.user_agent = strdup(user_agent);
            current->session.connection_status = connection_status;
            pthread_mutex_unlock(&table->lock[index]);
            return;
        }
        current = current->next;
    }

    // Create new session
    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->session.session_id = strdup(session_id);
    new_node->session.last_active_timestamp = last_active;
    new_node->session.user_agent = strdup(user_agent);
    new_node->session.connection_status = connection_status;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->lock[index]);
}

DeviceSession* get_session(HashTable *table, const char *session_id) {
    unsigned long index = hash_function(session_id);
    pthread_mutex_lock(&table->lock[index]);

    HashNode *current = table->buckets[index];
    while (current) {
        if (strcmp(current->session.session_id, session_id) == 0) {
            DeviceSession *result = &current->session;
            pthread_mutex_unlock(&table->lock[index]);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock[index]);
    return NULL;
}

void close_inactive_sessions(HashTable *table, time_t current_time) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table->lock[i]);

        HashNode **current = &table->buckets[i];
        while (*current) {
            if ((current_time - (*current)->session.last_active_timestamp) > INACTIVITY_THRESHOLD_SECONDS && (*current)->session.connection_status == 1) {
                HashNode *to_delete = *current;
                *current = to_free_hash_node(to_delete);
                pthread_mutex_unlock(&table->lock[i]);
                free_hash_node(to_delete);
                continue; // Continue without incrementing current
            }
            current = &(*current)->next;
        }

        pthread_mutex_unlock(&table->lock[i]);
    }
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table->lock[i]);

        HashNode *current = table->buckets[i];
        while (current) {
            HashNode *to_delete = current;
            current = current->next;
            free_hash_node(to_delete);
        }

        pthread_mutex_unlock(&table->lock[i]);
    }
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->lock[i]);
    }
    free(table->buckets);
    free(table);
}

// Example usage
void handle_spikes(HashTable *table, int adjust_threshold) {
    if (adjust_threshold) {
        // Adjust threshold or other performance metrics dynamically based on traffic load
    }
    // Logic to manage spikes gracefully
}

int main() {
    HashTable *session_table = initialize_hash_table();

    time_t now = time(NULL);
    add_or_update_session(session_table, "session1", now, "UserAgentString1", 1);

    DeviceSession *retrieved = get_session(session_table, "session1");
    if (retrieved) {
        printf("Session ID: %s\n", retrieved->session_id);
    }

    close_inactive_sessions(session_table, time(NULL));

    free_hash_table(session_table);
    return 0;
}
