#include <stdio.h>

#define INITIAL_CAPACITY 16
#define LOCK_READ pthread_rwlock_rdlock
#define UNLOCK_READ pthread_rwlock_unlock
#define LOCK_WRITE pthread_rwlock_wrlock
#define UNLOCK_WRITE pthread_rwlock_unlock

struct NetworkServiceManager {
    NetworkService* services;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
};

static int validate_service(const NetworkService* service);
static void resize_services(NetworkServiceManager* manager);

NetworkServiceManager* create_manager() {
    NetworkServiceManager* manager = (NetworkServiceManager*)malloc(sizeof(NetworkServiceManager));
    if (!manager) return NULL;

    manager->services = (NetworkService*)calloc(INITIAL_CAPACITY, sizeof(NetworkService));
    if (!manager->services) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);

    return manager;
}

int add_service(NetworkServiceManager* manager, const char* service_name, int port_number,
                ProtocolType protocol_type, ConnectionHandler callback, int priority_level) {
    LOCK_WRITE(manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->services[i].port_number == port_number) {
            UNLOCK_WRITE(manager->lock);
            return -1;
        }
    }

    if (manager->count >= manager->capacity) {
        resize_services(manager);
    }

    NetworkService* service = &manager->services[manager->count++];
    service->service_name = strdup(service_name);
    service->port_number = port_number;
    service->protocol_type = protocol_type;
    service->callback = callback;
    service->priority_level = priority_level;

    if (!validate_service(service)) {
        UNLOCK_WRITE(manager->lock);
        return -1;
    }

    UNLOCK_WRITE(manager->lock);
    return 0;
}

int remove_service(NetworkServiceManager* manager, int port_number) {
    LOCK_WRITE(manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->services[i].port_number == port_number) {
            free(manager->services[i].service_name);

            memmove(&manager->services[i], &manager->services[i + 1],
                    sizeof(NetworkService) * (manager->count - i - 1));
            manager->count--;

            UNLOCK_WRITE(manager->lock);
            return 0;
        }
    }

    UNLOCK_WRITE(manager->lock);
    return -1;
}

NetworkService* get_service(NetworkServiceManager* manager, int port_number) {
    LOCK_READ(manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->services[i].port_number == port_number) {
            NetworkService* service = &manager->services[i];
            UNLOCK_READ(manager->lock);
            return service;
        }
    }

    UNLOCK_READ(manager->lock);
    return NULL;
}

void delete_manager(NetworkServiceManager* manager) {
    LOCK_WRITE(manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->services[i].service_name);
    }

    free(manager->services);
    pthread_rwlock_destroy(&manager->lock);
    free(manager);
}

static void resize_services(NetworkServiceManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    NetworkService* new_services = (NetworkService*)realloc(manager->services, 
                                                            new_capacity * sizeof(NetworkService));
    if (!new_services) return;

    memset(&new_services[manager->count], 0, 
           (new_capacity - manager->count) * sizeof(NetworkService));

    manager->services = new_services;
    manager->capacity = new_capacity;
}

static int validate_service(const NetworkService* service) {
