#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_DIRNAME_LENGTH 128

struct FileEntry {
    char *filename;
    long file_size;
    time_t last_modified_time;
};

struct Directory {
    char *name;
    struct FileEntry **file_entries;
    size_t entry_count;
};

// Thread-safe memory allocation function
void* thread_safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && size > 0) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize FileEntry from a file
int initialize_file_entry(struct FileEntry *entry, const char *filepath) {
    struct stat st;
    if (stat(filepath, &st) != 0) {
        perror("Error accessing file");
        return -1;
    }

    entry->filename = thread_safe_malloc(MAX_FILENAME_LENGTH + 1);
    strncpy(entry->filename, filepath, MAX_FILENAME_LENGTH);
    entry->filename[MAX_FILENAME_LENGTH] = '\0';

    entry->file_size = st.st_size;
    entry->last_modified_time = st.st_mtime;

    return 0;
}

// Function to create and initialize a directory
struct Directory* create_directory(size_t file_count) {
    struct Directory *dir = thread_safe_malloc(sizeof(struct Directory));
    dir->name = thread_safe_malloc(MAX_DIRNAME_LENGTH + 1);

    dir->file_entries = thread_safe_malloc(file_count * sizeof(struct FileEntry *));
    dir->entry_count = file_count;

    return dir;
}

// Function to initialize directory with files
void load_directory_files(struct Directory *dir, const char *input_file) {
    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < dir->entry_count; ++i) {
        struct FileEntry *file_entry = thread_safe_malloc(sizeof(struct FileEntry));
        char filename[MAX_FILENAME_LENGTH + 1];

        if (fgets(filename, sizeof(filename), fp) == NULL) break;
        filename[strcspn(filename, "\n")] = '\0'; // Remove newline

        strncpy(dir->name, "Directory", MAX_DIRNAME_LENGTH);
        dir->file_entries[i] = file_entry;

        initialize_file_entry(file_entry, filename);
    }

    fclose(fp);
}

// Search function for retrieving file metadata by name
struct FileEntry* search_file(struct Directory *dir, const char *filename) {
    for (size_t i = 0; i < dir->entry_count; ++i) {
        if (strcmp(dir->file_entries[i]->filename, filename) == 0) {
            return dir->file_entries[i];
        }
    }
    return NULL;
}

// Function to list all files in a directory
void list_files_in_directory(const struct Directory *dir) {
    printf("Directory: %s\n", dir->name);
    for (size_t i = 0; i < dir->entry_count; ++i) {
        const struct FileEntry *entry = dir->file_entries[i];
        printf("File: %s, Size: %ld, Last Modified: %s",
               entry->filename,
               entry->file_size,
               ctime(&entry->last_modified_time));
    }
}

// Function to deallocate directory and its entries
void free_directory(struct Directory *dir) {
    for (size_t i = 0; i < dir->entry_count; ++i) {
        free(dir->file_entries[i]->filename);
        free(dir->file_entries[i]);
    }

    free(dir->file_entries);
    free(dir->name);
    free(dir);
}

int main() {
    size_t file_count;
    printf("Enter number of files: ");
    if (scanf("%zu", &file_count) != 1 || file_count <= 0) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    struct Directory *dir = create_directory(file_count);
    load_directory_files(dir, "file_list.txt");

    char search_filename[MAX_FILENAME_LENGTH + 1];
    printf("Enter filename to search: ");
    if (fgets(search_filename, sizeof(search_filename), stdin) != NULL) {
        search_filename[strcspn(search_filename, "\n")] = '\0';
        struct FileEntry *entry = search_file(dir, search_filename);
        if (entry) {
            printf("Found File: %s\n", entry->filename);
        } else {
            printf("File not found.\n");
        }
    }

    list_files_in_directory(dir);
    free_directory(dir);

    return EXIT_SUCCESS;
}
