['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct CacheNode {
    char* cacheEntry;
    size_t key;
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    pthread_mutex_t lock;
} LRUCache;

typedef struct {
    char** entries;
    size_t* keys;
    size_t count;
    LRUCache lruCache;
    size_t capacity;
    pthread_rwlock_t rwlock; // For concurrent access
} MultiTieredCache;

// Hash table structure and functions
#define HASH_TABLE_SIZE 1024

typedef struct {
    CacheNode** buckets;
    int count;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable() {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (CacheNode**)calloc(HASH_TABLE_SIZE, sizeof(CacheNode*));
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hash(size_t key) {
    return key % HASH_TABLE_SIZE;
}

void insertHashTable(HashTable* ht, CacheNode* node) {
    unsigned long index = hash(node->key);
    pthread_mutex_lock(&ht->lock);
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    ht->count++;
    pthread_mutex_unlock(&ht->lock);
}

CacheNode* searchHashTable(HashTable* ht, size_t key) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&ht->lock);
    CacheNode* current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

// Cache management functions
void initCache(MultiTieredCache* cache, size_t capacity) {
    cache->entries = (char**)malloc(capacity * sizeof(char*));
    cache->keys = (size_t*)malloc(capacity * sizeof(size_t));
    cache->count = 0;
    cache->capacity = capacity;
    pthread_rwlock_init(&cache->rwlock, NULL);
    cache->lruCache.head = cache->lruCache.tail = NULL;
    pthread_mutex_init(&cache->lruCache.lock, NULL);

    // Initialize hash table
    HashTable* ht = createHashTable();
    cache->entries[0] = (char*)ht;  // Storing the pointer to hash table in entries for simplicity
}

int allocateCacheEntry(MultiTieredCache* cache, size_t keySize, const char* data) {
    pthread_rwlock_wrlock(&cache->rwlock);

    if (cache->count >= cache->capacity) {
        pthread_rwlock_unlock(&cache->rwlock);
        printf("Error: Cache capacity reached. Consider increasing the capacity.\n");
        return -1;
    }

    char** entries = (char**)malloc((cache->count + 1) * sizeof(char*));
    size_t* keys = (size_t*)malloc((cache->count + 1) * sizeof(size_t));

    if (!entries || !keys) {
        pthread_rwlock_unlock(&cache->rwlock);
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    memcpy(entries, cache->entries, cache->count * sizeof(char*));
    memcpy(keys, cache->keys, cache->count * sizeof(size_t));

    char* entry = (char*)malloc(keySize + 1);
    if (!entry) {
        free(entries);
        free(keys);
        pthread_rwlock_unlock(&cache->rwlock);
        printf("Error: Memory allocation failed for cache entry.\n");
        return -1;
    }

    memcpy(entry, data, keySize);
    entry[keySize] = '\0';

    entries[cache->count] = entry;
    keys[cache->count] = hash(key);

    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) {
        free(entries[cache->count]);
        free(entries);
        free(keys);
        pthread_rwlock_unlock(&cache->rwlock);
        printf("Error: Memory allocation failed for cache node.\n");
        return -1;
    }

    node->cacheEntry = entry;
    node->key = keys[cache->count];
    node->prev = node->next = NULL;

    // Update doubly linked list
    pthread_mutex_lock(&cache->lruCache.lock);
    if (cache->lruCache.head == NULL) {
        cache->lruCache.head = cache->lruCache.tail = node;
    } else {
        cache->lruCache.tail->next = node;
        node->prev = cache->lruCache.tail;
        cache->lruCache.tail = node;
    }
    pthread_mutex_unlock(&cache->lruCache.lock);

    // Update hash table
    HashTable* ht = (HashTable*)entries[0];
    insertHashTable(ht, node);

    free(cache->entries);
    free(cache->keys);
    cache->entries = entries;
    cache->keys = keys;
    cache->count++;

    pthread_rwlock_unlock(&cache->rwlock);
    return 0;
}

void freeCache(MultiTieredCache* cache) {
    pthread_rwlock_wrlock(&cache->rwlock);

    CacheNode* current = cache->lruCache.head;
    while (current != NULL) {
        CacheNode* next = current->next;
        free(current->cacheEntry);
        free(current);
        current = next;
    }

    HashTable* ht = (HashTable*)cache->entries[0];
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        while (ht->buckets[i] != NULL) {
            CacheNode* node = ht->buckets[i];
            ht->buckets[i] = node->next;
            free(node);
        }
    }

    free(ht->buckets);
    free(ht);

    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->entries[i]);
    }

    free(cache->entries);
    free(cache->keys);

    pthread_rwlock_unlock(&cache->rwlock);
}

int main() {
    MultiTieredCache cache;
    initCache(&cache, 100);

    allocateCacheEntry(&cache, strlen("Data1"), "Data1");
    allocateCacheEntry(&cache, strlen("Data2"), "Data2");

    freeCache(&cache);
    return 0;
}
```

This code implements a basic multi-tiered caching system with dynamic memory allocation, key-value pairing using a hash table, and an LRU cache eviction policy. It handles concurrency with read-write locks for thread safety. The hash table is used for fast lookups, and the doubly linked list manages cache entries based on usage patterns. Memory management ensures proper deallocation of resources.']

