void init_interface_queues() {
    for (int i = 0; i < MAX_INTERFACES; i++) {
        interface_queues[i].head = NULL;
        pthread_mutex_init(&interface_queues[i].lock, NULL);
    }
}

NFAPI_SRB1_BUFFER_PDU_T* dequeue_message(int interface_index) {
    if (interface_index < 0 || interface_index >= MAX_INTERFACES) return NULL;

    pthread_mutex_lock(&interface_queues[interface_index].lock);

    if (!interface_queues[interface_index].head) {
        pthread_mutex_unlock(&interface_queues[interface_index].lock);
        return NULL;
    }

    MessageNode* node = interface_queues[interface_index].head;
    NFAPI_SRB1_BUFFER_PDU_T* message = &node->message;

    interface_queues[interface_index].head = node->next;
    free(node);

    pthread_mutex_unlock(&interface_queues[interface_index].lock);
    return message;
}

void enqueue_message(int interface_index, NFAPI_SRB1_BUFFER_PDU_T message) {
    if (interface_index < 0 || interface_index >= MAX_INTERFACES) return;

    MessageNode* new_node = malloc(sizeof(MessageNode));
    if (!new_node) {
        perror("Failed to allocate memory for message node");
        return;
    }
    new_node->message = message;
    new_node->next = NULL;

    pthread_mutex_lock(&interface_queues[interface_index].lock);

    MessageNode** current = &interface_queues[interface_index].head;
    while (*current && (*current)->message.timestamp < message.timestamp) {
        current = &(*current)->next;
    }
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&interface_queues[interface_index].lock);
}

