    for (int i = 0; i < size; ++i) {
        keys[i].key = i + 50; // Ensure no overflow
    }
}

int process_data(int num_offsets, int num_records, long min_random, long max_random, Key *keys) {
    Offset *offsets = malloc(num_offsets * sizeof(Offset));
    Record *records = malloc(num_records * sizeof(Record));

    if (!offsets || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(records);
        return -1;
    }

    // Initialize offsets
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i].value = i;
    }

    // Seed random number generator
    srand(time(NULL));

    // Initialize records with random values in the specified range
    for (int i = 0; i < num_records; ++i) {
        records[i].record = rand() % (max_random - min_random + 1) + min_random;
    }

    int match_count = 0;

    // Check for matches and update records
    for (int i = 0; i < num_records; ++i) {
        for (int j = 0; j < KEY_SIZE; ++j) {
            if (records[i].record == keys[j].key) {
                records[i].record = -1;
                match_count++;
                break; // Break to avoid unnecessary comparisons after a match
            }
        }
    }

    free(offsets);
    free(records);

    return match_count;
}

int main() {
    Key shared_keys[KEY_SIZE];

    initialize_keys(shared_keys, KEY_SIZE);

    int num_runs = 0;
    printf("Enter number of runs (up to %d): ", MAX_RUNS);
    scanf("%d", &num_runs);
    if (num_runs < 1 || num_runs > MAX_RUNS) {
        fprintf(stderr, "Invalid number of runs\n");
        return EXIT_FAILURE;
    }

    int total_matches = 0;

    for (int i = 0; i < num_runs; ++i) {
        int num_offsets = 0, num_records = 0;
        long min_random = 0, max_random = 0;

        printf("Enter number of offsets for run %d: ", i + 1);
        scanf("%d", &num_offsets);
        printf("Enter number of records for run %d: ", i + 1);
