#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000
#define MIN_ELEMENTS 1
#define POOL_SIZE 1024

typedef struct {
    float value;
    bool flag;
    size_t index;
} data_t;

typedef struct memory_pool_node {
    void *memory;
    struct memory_pool_node *next;
} memory_pool_node_t;

typedef struct {
    memory_pool_node_t *free_list;
    pthread_mutex_t lock;
} memory_pool_t;

void initialize_memory_pool(memory_pool_t *pool) {
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_memory_pool(memory_pool_t *pool) {
    memory_pool_node_t *current = pool->free_list;
    while (current != NULL) {
        memory_pool_node_t *next = current->next;
        free(current->memory);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
}

void* allocate_from_pool(memory_pool_t *pool, size_t size) {
    void *block;

    pthread_mutex_lock(&pool->lock);

    if (pool->free_list != NULL) {
        memory_pool_node_t *node = pool->free_list;
        block = node->memory;
        pool->free_list = node->next;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }

    block = malloc(size);
    pthread_mutex_unlock(&pool->lock);

    if (block == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return block;
}

void deallocate_to_pool(memory_pool_t *pool, void *memory, size_t size) {
    memory_pool_node_t *node = malloc(sizeof(memory_pool_node_t));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation for pool node failed\n");
        exit(EXIT_FAILURE);
    }

    node->memory = memory;
    pthread_mutex_lock(&pool->lock);
    node->next = pool->free_list;
    pool->free_list = node;
    pthread_mutex_unlock(&pool->lock);
}

data_t* initialize_data_array(size_t num_elements, const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file\n");
        return NULL;
    }

    int elements_from_config;
    if (fscanf(file, "%d", &elements_from_config) != 1 || elements_from_config < MIN_ELEMENTS || elements_from_config > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid number of elements in config: %d\n", elements_from_config);
        fclose(file);
        return NULL;
    }

    fclose(file);

    memory_pool_t pool;
    initialize_memory_pool(&pool);

    data_t **data_array = (data_t**)allocate_from_pool(&pool, num_elements * sizeof(data_t*));
    for (size_t i = 0; i < num_elements; ++i) {
        data_t *data = (data_t*)allocate_from_pool(&pool, sizeof(data_t));
        data->value = 0.0f;
        data->flag = false;
        data->index = i;
        data_array[i] = data;
    }

    return data_array;
}

int main() {
    const char *config_file = "config.txt";

    // Initialize the config file with a valid number
    FILE *file = fopen(config_file, "w");
    if (file) {
        fprintf(file, "500\n");  // Example configuration value
        fclose(file);
    }

    size_t num_elements = MAX_ELEMENTS;
    data_t **data_array = initialize_data_array(num_elements, config_file);

    if (data_array != NULL) {
        printf("Data array initialized with %zu elements.\n", num_elements);
        // Perform operations on the data_array
    } else {
        fprintf(stderr, "Failed to initialize data array.\n");
    }

    return 0;
}
