#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TOTAL_SIZE 1024 * 1024 // 1MB limit for data storage
#define EXPIRATION_THRESHOLD 60    // seconds

typedef struct {
    size_t id;
    time_t timestamp;
    int status; // e.g., 0 = inactive, 1 = active
    char *data;
    size_t data_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_data_size;
} PacketManager;

// Function prototypes
PacketManager* initialize_packet_manager();
void add_packet(PacketManager* manager, size_t id, const char* data, size_t data_size);
DataPacket* get_packet(PacketManager* manager, size_t id);
void update_packet(PacketManager* manager, size_t id, const char* new_data, size_t new_data_size);
void purge_expired_packets(PacketManager* manager);
void compress_payload(DataPacket *packet); // Placeholder for compression logic
void decompress_payload(DataPacket *packet); // Placeholder for decompression logic
void log_operation(const char* operation_desc);
void free_packet_manager(PacketManager* manager);

PacketManager* initialize_packet_manager() {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->packets = NULL;
    manager->count = 0;
    manager->capacity = 10; // Initial capacity
    manager->total_data_size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->packets = (DataPacket*)malloc(manager->capacity * sizeof(DataPacket));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }
    return manager;
}

void add_packet(PacketManager* manager, size_t id, const char* data, size_t data_size) {
    pthread_mutex_lock(&manager->lock);

    time_t now = time(NULL);
    while (manager->count >= manager->capacity || manager->total_data_size + data_size > MAX_TOTAL_SIZE) {
        purge_expired_packets(manager);
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].id == id) {
            update_packet(manager, id, data, data_size);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->packets = (DataPacket*)realloc(manager->packets, new_capacity * sizeof(DataPacket));
        if (!manager->packets) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->capacity = new_capacity;
    }

    DataPacket packet;
    packet.id = id;
    packet.timestamp = now;
    packet.status = 1; // active
    packet.data_size = data_size;

    if (data_size > 0) {
        packet.data = malloc(data_size);
        memcpy(packet.data, data, data_size);
        manager->total_data_size += data_size;
    } else {
        packet.data = NULL;
    }

    manager->packets[manager->count++] = packet;

    log_operation("Added new packet");

    pthread_mutex_unlock(&manager->lock);
}

DataPacket* get_packet(PacketManager* manager, size_t id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].id == id) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->packets[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_packet(PacketManager* manager, size_t id, const char* new_data, size_t new_data_size) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].id == id) {
            time_t now = time(NULL);
            manager->total_data_size -= manager->packets[i].data_size;

            if (new_data_size > 0) {
                manager->packets[i].data = realloc(manager->packets[i].data, new_data_size);
                memcpy(manager->packets[i].data, new_data, new_data_size);
                manager->total_data_size += new_data_size;
            } else {
                free(manager->packets[i].data);
                manager->packets[i].data = NULL;
            }

            manager->packets[i].data_size = new_data_size;
            manager->packets[i].timestamp = now;

            log_operation("Updated packet");

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void purge_expired_packets(PacketManager* manager) {
    time_t now = time(NULL);

    for (size_t i = 0; i < manager->count;) {
        if ((now - manager->packets[i].timestamp) > EXPIRATION_THRESHOLD && manager->packets[i].status == 1) {
            manager->total_data_size -= manager->packets[i].data_size;
            free(manager->packets[i].data);

            // Shift packets down
            memmove(&manager->packets[i], &manager->packets[i + 1],
                    (manager->count - i - 1) * sizeof(DataPacket));
            manager->count--;
        } else {
            ++i;
        }
    }

    log_operation("Purged expired packets");
}

void compress_payload(DataPacket *packet) {
    // Implement compression logic here
}

void decompress_payload(DataPacket *packet) {
    // Implement decompression logic here
}

void log_operation(const char* operation_desc) {
    printf("%s\n", operation_desc); // Replace with a more sophisticated logging mechanism
}

void free_packet_manager(PacketManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i].data);
    }

    free(manager->packets);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
