#include <time.h>

#define MAX_PREFIX_SUFFIX_LENGTH 100
#define MAX_STRING_LENGTH 256

typedef struct {
    double value;
    char string[MAX_STRING_LENGTH];
} data_point;

void* thread_safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

pthread_mutex_t mutex_alloc = PTHREAD_MUTEX_INITIALIZER;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

double generate_random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

char* create_unique_string(const char** prefixes, const char** suffixes, size_t num_prefixes, size_t num_suffixes) {
    static pthread_mutex_t mutex_string = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex_string);

    size_t prefix_idx = rand() % num_prefixes;
    size_t suffix_idx = rand() % num_suffixes;

    char *unique_str = thread_safe_malloc(MAX_STRING_LENGTH);
    snprintf(unique_str, MAX_STRING_LENGTH, "%s_%s", prefixes[prefix_idx], suffixes[suffix_idx]);

    pthread_mutex_unlock(&mutex_string);
    return unique_str;
}

void free_resources(double *d_array, char *c_array, data_point *dp_array) {
    if (d_array) free(d_array);
    if (c_array) free(c_array);
    if (dp_array) free(dp_array);
}

int parse_config(const char* config_path, double *min_val, double *max_val, const char ***prefixes, const char ***suffixes, size_t *num_prefixes, size_t *num_suffixes) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), file)) sscanf(line, "%lf %lf", min_val, max_val);
    size_t prefix_count = 0;
    while (fgets(line, sizeof(line), file) && line[0] != '#') {
        if (strstr(line, "prefix:")) (*num_prefixes)++;
    }
    rewind(file);

    *prefixes = thread_safe_malloc(*num_prefixes * sizeof(char*));
    size_t prefix_idx = 0;
    while (fgets(line, sizeof(line), file) && line[0] != '#') {
        if (strstr(line, "prefix:")) {
            char buffer[MAX_PREFIX_SUFFIX_LENGTH];
            sscanf(line + strlen("prefix:"), "%s", buffer);
            (*prefixes)[prefix_idx++] = strdup(buffer);
        }
    }

    size_t suffix_count = 0;
    while (fgets(line, sizeof(line), file) && line[0] != '#') {
        if (strstr(line, "suffix:")) (*num_suffixes)++;
    }
    rewind(file);

    *suffixes = thread_safe_malloc(*num_suffixes * sizeof(char*));
    size_t suffix_idx = 0;
    while (fgets(line, sizeof(line), file) && line[0] != '#') {
        if (strstr(line, "suffix:")) {
            char buffer[MAX_PREFIX_SUFFIX_LENGTH];
            sscanf(line + strlen("suffix:"), "%s", buffer);
            (*suffixes)[suffix_idx++] = strdup(buffer);
        }
    }

    fclose(file);
    return 0;
}

void* allocate_and_initialize_arrays(void *arg) {
    const char *config_path = (const char *)arg;

    double min_val, max_val;
    const char **prefixes, **suffixes;
    size_t num_prefixes, num_suffixes;

    if (parse_config(config_path, &min_val, &max_val, &prefixes, &suffixes, &num_prefixes, &num_suffixes) != 0) {
        return NULL;
    }

    pthread_mutex_lock(&mutex_alloc);
    size_t n = 100; // Example number of elements

    double *d_array = thread_safe_malloc(n * sizeof(double));
    char *c_array = thread_safe_malloc(n * MAX_STRING_LENGTH);
    data_point *dp_array = thread_safe_malloc(n * sizeof(data_point));

    pthread_mutex_unlock(&mutex_alloc);

    initialize_random();

    for (size_t i = 0; i < n; ++i) {
        d_array[i] = generate_random_double(min_val, max_val);
        char* unique_str = create_unique_string(prefixes, suffixes, num_prefixes, num_suffixes);
        strncpy(dp_array[i].string, unique_str, MAX_STRING_LENGTH - 1);
        dp_array[i].value = d_array[i];
        free(unique_str); // Free the temporary string after copying
    }

    for (size_t i = 0; i < num_prefixes; ++i) {
        free((void*)prefixes[i]);
    }
    for (size_t j = 0; j < num_suffixes; ++j) {
        free((void*)suffixes[j]);
    }
    free((void*)prefixes);
    free((void*)suffixes);

    pthread_mutex_lock(&mutex_alloc);
    // Do something with the arrays, e.g., pass them to another function or store them.
    pthread_mutex_unlock(&mutex_alloc);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    allocate_and_initialize_arrays((void*)argv[1]);

