```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    int status; // e.g., active/inactive/other statuses
    char *payload;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t maxPayloadSize;
    time_t expirationThreshold;
} PacketManager;

char* compressPayload(const char* data, size_t length) {
    // Placeholder for compression logic (e.g., zlib)
    return strdup(data);  // Simplified for illustration
}

int validateStringLength(char* str, size_t maxLength) {
    if (strlen(str) > maxLength) {
        return -1;
    }
    strcat(str, "/");
    return 0;
}

void logError(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

PacketManager* createPacketManager(size_t maxPayloadSize, time_t expirationThreshold) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) {
        logError("Failed to allocate memory for PacketManager.");
        return NULL;
    }
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxPayloadSize = maxPayloadSize;
    manager->expirationThreshold = expirationThreshold;
    return manager;
}

void purgeExpiredPackets(PacketManager* manager) {
    time_t currentTime = time(NULL);

    Node *current = manager->head, *prev = NULL;
    while (current != NULL) {
        if ((currentTime - current->packet.timestamp) > manager->expirationThreshold) {
            Node* toDelete = current;

            if (prev == NULL)
                manager->head = current->next;  // Removing head
            else
                prev->next = current->next;

            free(toDelete->packet.payload);
            free(toDelete);
            current = prev ? prev->next : manager->head;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void addPacket(PacketManager* manager, int id, const char* payload) {
    pthread_mutex_lock(&manager->lock);

    if (strlen(payload) > manager->maxPayloadSize) {
        logError("Payload size exceeds maximum limit.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        logError("Failed to allocate memory for new packet.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    newNode->packet.id = id;
    newNode->packet.timestamp = time(NULL);
    newNode->packet.status = 1; // Assuming 1 means active
    newNode->packet.payload = compressPayload(strdup(payload), strlen(payload));

    if (newNode->packet.payload == NULL) {
        free(newNode);
        logError("Failed to allocate memory for compressed payload.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    newNode->next = manager->head;
    manager->head = newNode;

    pthread_mutex_unlock(&manager->lock);
}

DataPacket* getPacket(PacketManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL) {
        if (current->packet.id == id) {
            DataPacket* packetCopy = (DataPacket*)malloc(sizeof(DataPacket));
            if (!packetCopy) {
                logError("Failed to allocate memory for packet copy.");
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            *packetCopy = current->packet;
            pthread_mutex_unlock(&manager->lock);
            return packetCopy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void updatePacket(PacketManager* manager, int id, const char* newPayload) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL) {
        if (current->packet.id == id) {
            free(current->packet.payload);
            current->packet.payload = compressPayload(strdup(newPayload), strlen(newPayload));
            current->packet.timestamp = time(NULL); // Update timestamp
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroyPacketManager(PacketManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL) {
        Node *toDelete = current;
        current = current->next;
        free(toDelete->packet.payload);
        free(toDelete);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void dataHandlingSystem() {
    PacketManager* manager = createPacketManager(MAX_PAYLOAD_SIZE, 3600);

    if (manager) {
        addPacket(manager, 1, "Initial payload");
        DataPacket *packet = getPacket(manager, 1);
        if (packet) {
            printf("Retrieved packet: ID=%d, Payload=%s\n", packet->id, packet->payload);
            free(packet->payload);
            free(packet);
        }

        updatePacket(manager, 1, "Updated payload");

        purgeExpiredPackets(manager);

        destroyPacketManager(manager);
    }
}

int main() {
    dataHandlingSystem();
    return 0;
}
