// Function to log events
void log_event(MemoryPool *pool, const char *event) {
    if (pool->logging_enabled && pool->log_file) {
        time_t now = time(NULL);
        fprintf(pool->log_file, "%s: %s\n", ctime(&now), event);
        fflush(pool->log_file);
    }
}

// Initialize Memory Pool
void init_memory_pool(MemoryPool *pool, size_t initial_size, int logging_enabled, const char *log_filename) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->memory_pool = malloc(initial_size);
    pool->pool_size = initial_size;
    pool->used_memory = 0;
    pool->logging_enabled = logging_enabled;

    if (log_filename) {
        pool->log_file = fopen(log_filename, "a");
    } else {
        pool->log_file = NULL;
    }
}

// Resize Memory Pool
int resize_memory_pool(MemoryPool *pool, size_t new_size) {
    pthread_mutex_lock(&pool->lock);

    void *new_memory_pool = realloc(pool->memory_pool, new_size);
    if (!new_memory_pool) {
        log_event(pool, "Failed to resize memory pool");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->memory_pool = new_memory_pool;
    pool->pool_size = new_size;

    log_event(pool, "Resized memory pool");
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Allocate Memory from Pool
void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_memory + size > pool->pool_size) {
        if (resize_memory_pool(pool, pool->pool_size * 2)) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
    }

    void *ptr = (char*)pool->memory_pool + pool->used_memory;
    pool->used_memory += size;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated %zu bytes", size);
    log_event(pool, log_message);

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Deallocate Memory from Pool
