// Function to manage records
int manage_records(MemoryPool *pool, Record **records, size_t count, int resize_flag) {
    if (count <= 0 || !records || !pool) return -1;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < count; ++i) {
        records[i] = (Record *)allocate_from_pool(pool, sizeof(Record));
