    manager->keys[/* current index */] = key;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void configure_from_yaml(EventManager *manager) {
    FILE *file = fopen(manager->config_file_path, "rb");
    if (!file) return;

    yaml_parser_t parser;
    if (!yaml_parser_initialize(&parser)) {
