#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2

typedef struct {
    time_t timestamp;
    char event_type[64];
} Metadata;

typedef struct {
    char key[MAX_KEY_LENGTH];
    char value[MAX_KEY_LENGTH];
    int version;
    Metadata metadata;
} ConfigSetting;

typedef struct HashTableNode {
    ConfigSetting setting;
    struct HashTableNode *next;
} HashTableNode;

typedef struct {
    HashTableNode **buckets;
    size_t capacity;
    pthread_mutex_t lock;
    int log_level;
    char *log_format; // e.g., "key=value, version=%d"
} ConfigurationHashTable;

unsigned int hash(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

ConfigurationHashTable* create_hash_table(size_t capacity, int log_level, const char *log_format) {
    ConfigurationHashTable *table = (ConfigurationHashTable*)malloc(sizeof(ConfigurationHashTable));
    table->buckets = (HashTableNode**)calloc(capacity, sizeof(HashTableNode*));
    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    table->log_level = log_level;
    table->log_format = strdup(log_format);
    return table;
}

void free_hash_table(ConfigurationHashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            HashTableNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table->log_format);
    free(table);
}

void log_event(ConfigurationHashTable *table, const char *event_type, const ConfigSetting *setting) {
    if (table->log_level <= LOG_LEVEL_INFO) {
        printf("Event: %s - ", event_type);
        printf(table->log_format, setting->key, setting->value, setting->version);
        printf("\n");
    }
}

void configure_and_manage_storage(ConfigurationHashTable *table, const char *operation, 
                                  const char *key, const char *value, int version) {
    pthread_mutex_lock(&table->lock);

    unsigned int index = hash(key, table->capacity);
    HashTableNode *node = table->buckets[index];
    while (node && strcmp(node->setting.key, key) != 0) {
        node = node->next;
    }

    if (strcmp(operation, "add") == 0 || strcmp(operation, "update") == 0) {
        if (!node) { // Add new setting
            node = (HashTableNode*)malloc(sizeof(HashTableNode));
            strncpy(node->setting.key, key, MAX_KEY_LENGTH);
            strncpy(node->setting.value, value, MAX_KEY_LENGTH);
            node->setting.version = version;
            time(&(node->setting.metadata.timestamp));
            strcpy(node->setting.metadata.event_type, "ADD");
            node->next = table->buckets[index];
            table->buckets[index] = node;
        } else { // Update existing setting
            strncpy(node->setting.value, value, MAX_KEY_LENGTH);
            node->setting.version = version;
            time(&(node->setting.metadata.timestamp));
            strcpy(node->setting.metadata.event_type, "UPDATE");
        }
        log_event(table, node->setting.metadata.event_type, &node->setting);
    } else if (strcmp(operation, "get") == 0) {
        if (node) {
            printf("Key: %s, Value: %s, Version: %d\n", 
                   node->setting.key, node->setting.value, node->setting.version);
        } else {
            printf("Setting not found.\n");
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void invalidate_settings(ConfigurationHashTable *table, int version_threshold) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            if (node->setting.version < version_threshold) {
                HashTableNode *temp = node;
                node = node->next;
                strncpy(temp->setting.metadata.event_type, "INVALIDATE", sizeof(temp->setting.metadata.event_type));
                log_event(table, temp->setting.metadata.event_type, &temp->setting);
                table->buckets[i] = node;
                free(temp);
            } else {
                node = node->next;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Example usage
int main() {
    ConfigurationHashTable *config_table = create_hash_table(1024, LOG_LEVEL_INFO, "Key: %s, Value: %s, Version: %d");

    configure_and_manage_storage(config_table, "add", "timeout", "30", 1);
    configure_and_manage_storage(config_table, "update", "timeout", "60", 2);
    configure_and_manage_storage(config_table, "get", "timeout", NULL, 0);

    invalidate_settings(config_table, 1);

    free_hash_table(config_table);
    return 0;
}
```

This code implements a basic thread-safe hash table for managing configuration settings with logging and invalidation features. It provides functions to add, update, get, and invalidate settings based on version thresholds. The logging mechanism is simple and can be extended or modified as needed. The example usage demonstrates how to use the `configure_and_manage_storage` function.']

