#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define QUEUE_SIZE 100

typedef struct {
    int connection_id;
    char client_ip[16];
    uint16_t port_number;
    time_t last_data_exchange;
    double flow_rate;
    float weight_factor;
} ConnectionEntry;

typedef struct {
    ConnectionEntry connections[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
} ConnectionManager;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[12];
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int priority_level;
    double estimated_processing_time;
    time_t timeout_value;
    char file_name[256];
} FileConversionTask;

typedef struct {
    FileConversionTask tasks[QUEUE_SIZE];
    int count;
    pthread_mutex_t lock;
} TaskQueue;

int network_load_metric = 1.0; // Simulated dynamic metric
pthread_mutex_t network_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_connection_manager(ConnectionManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_connection(ConnectionManager *manager, const char *client_ip, uint16_t port_number) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONNECTIONS) {
        // Dynamic adjustment based on network load
        pthread_mutex_lock(&network_lock);
        int new_limit = (int)(MAX_CONNECTIONS / network_load_metric);
        if (new_limit < manager->count) {
            manager->count = new_limit;
        }
        pthread_mutex_unlock(&network_lock);
    }

    ConnectionEntry *entry = &manager->connections[manager->count++];
    entry->connection_id = rand();
    strncpy(entry->client_ip, client_ip, sizeof(entry->client_ip));
    entry->port_number = port_number;
    entry->last_data_exchange = time(NULL);
    entry->flow_rate = 0.0; // Initial flow rate
    entry->weight_factor = network_load_metric;

    pthread_mutex_unlock(&manager->lock);
}

void remove_connection(ConnectionManager *manager, int connection_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->connections[i].connection_id == connection_id) {
            memmove(&manager->connections[i], &manager->connections[i + 1],
                    (manager->count - i - 1) * sizeof(ConnectionEntry));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void initialize_task_queue(TaskQueue *queue) {
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

int add_task(TaskQueue *queue, const char *file_name, int priority_level,
             double estimated_processing_time, time_t timeout_value) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= QUEUE_SIZE) return -1;

    FileConversionTask *task = &queue->tasks[queue->count++];
    strncpy(task->file_name, file_name, sizeof(task->file_name));
    task->priority_level = priority_level;
    task->estimated_processing_time = estimated_processing_time;
    task->timeout_value = time(NULL) + timeout_value;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void process_tasks(TaskQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    for (int i = 0; i < queue->count; ++i) {
        if (time(NULL) > queue->tasks[i].timeout_value) {
            // Discard expired tasks
            memmove(&queue->tasks[i], &queue->tasks[i + 1],
                    (queue->count - i - 1) * sizeof(FileConversionTask));
            queue->count--;
            --i;
        }
    }

    pthread_mutex_unlock(&queue->lock);
}

void create_output_directory(const char *path) {
    struct stat st = {0};

    if (stat(path, &st) == -1) {
        mkdir(path, 0700); // Create directory with appropriate permissions
    } else if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: Path exists and is not a directory.\n");
        exit(EXIT_FAILURE);
    }
}

void convert_file_to_pdf(const char *input_file, const char *output_dir) {
    char output_path[512];
    snprintf(output_path, sizeof(output_path), "%s/%s.pdf", output_dir,
             strrchr(input_file, '/') ? strrchr(input_file, '/') + 1 : input_file);

    // Simulated conversion logic
    FILE *out = fopen(output_path, "w");
    if (!out) {
        fprintf(stderr, "Failed to create PDF file: %s\n", strerror(errno));
        return;
    }

    // Dummy content for demonstration
    fputs("PDF Content\n", out);
    fclose(out);

    printf("File converted and saved as %s\n", output_path);
}

void manage_connections_and_tasks(const char *file_name, int list_size,
                                  const char *output_dir, TaskQueue *task_queue) {
    ConnectionManager manager;
    initialize_connection_manager(&manager);

    // Example connections
    add_connection(&manager, "192.168.1.1", 8080);
    add_connection(&manager, "192.168.1.2", 8081);

    // Process and manage tasks
    initialize_task_queue(task_queue);
    add_task(task_queue, file_name, 1, 5.0, 60); // Priority, estimated time, timeout

    process_tasks(task_queue);

    create_output_directory(output_dir);
    convert_file_to_pdf(file_name, output_dir);
}

int main() {
    TaskQueue task_queue;
    manage_connections_and_tasks("example.jpg", MAX_CONNECTIONS, "./output",
                                 &task_queue);
    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes connection management with dynamic adjustment based on network load, task queue handling with timeout checks, directory creation for output, and simulated file conversion to PDF. Error handling and logging mechanisms are simplified for brevity but can be expanded as needed.']

