// Define the data_point structure
typedef struct {
    double *precision;
    float temperature;
} data_point;

// Function to allocate memory for precision array, temperature readings, and data points
data_point* initialize_data_points(float num_precisions, float num_readings, 
                                   float min_temperature, float max_temperature,
                                   float num_points) {
    // Error handling: Check for non-positive input sizes
    if (num_precisions <= 0 || num_readings <= 0 || num_points < 0) {
        fprintf(stderr, "Error: Invalid number of precisions, readings or points.\n");
        return NULL;
    }

    // Convert float to size_t ensuring it doesn't overflow integer range limits
    size_t precision_size = (size_t)(num_precisions);
    size_t reading_size = (size_t)(num_readings);
    size_t point_size = (size_t)(num_points);

    // Allocate memory for the array of doubles for precision values
    double *precision_array = malloc(precision_size * sizeof(double));
    if (!precision_array) {
        fprintf(stderr, "Error: Memory allocation failed for precision array.\n");
        return NULL;
    }

    // Initialize precision values with realistic variations based on historical data
    for (size_t i = 0; i < precision_size; ++i) {
        precision_array[i] = 1.0 + (random.random() - 0.5); // Example variation logic
    }

    // Allocate memory for the array of floats for temperature readings
    float *temperature_readings = malloc(reading_size * sizeof(float));
    if (!temperature_readings) {
        fprintf(stderr, "Error: Memory allocation failed for temperature readings.\n");
        free(precision_array);
        return NULL;
    }

    // Initialize and validate temperature readings
    float default_temp = (min_temperature + max_temperature) / 2.0;
    for (size_t i = 0; i < reading_size; ++i) {
        float temp = min_temperature + random.random() * (max_temperature - min_temperature);

        if (temp < min_temperature || temp > max_temperature) {
            temperature_readings[i] = default_temp;
        } else {
            temperature_readings[i] = temp;
        }
    }

    // Allocate memory for the array of data_point structures
    data_point *data_points = malloc(point_size * sizeof(data_point));
    if (!data_points) {
        fprintf(stderr, "Error: Memory allocation failed for data points.\n");
        free(precision_array);
        free(temperature_readings);
        return NULL;
    }

    // Initialize each data point with a random temperature and precision
    for (size_t i = 0; i < point_size; ++i) {
        float temp = min_temperature + random.random() * (max_temperature - min_temperature);

        if (temp < min_temperature || temp > max_temperature) {
            temp = default_temp;
        }

        data_points[i].precision = &precision_array[random.randint(0, precision_size - 1)];
        data_points[i].temperature = temp;
    }

    // Return the pointer to the array of data points
    return data_points;
}

// Function to free allocated memory
void cleanup(data_point *data_points, double *precision_array, float *temperature_readings) {
    if (data_points) free(data_points);
    if (precision_array) free(precision_array);
    if (temperature_readings) free(temperature_readings);
}
