#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETRIES 5
#define EXP_BACKOFF_BASE_DELAY 100 // milliseconds

typedef struct {
    int id;
    time_t timestamp;
    int status; // e.g., 0 for inactive, 1 for active
    size_t payload_size;
    void* payload;
} DataPacket;

typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

// Dummy function to simulate RESTful API call
int api_call(const char* action, const DataPacket* packet) {
    // Simulate network operation with random success/failure
    return rand() % 2 == 0 ? 1 : -1; // 1 for success, -1 for failure
}

// Exponential backoff retry mechanism
int perform_with_retries(int (*operation)(const char*, const DataPacket*)) {
    int attempt = 0;
    int result = -1;

    while (attempt < MAX_RETRIES && result != 1) {
        result = operation("example_action", NULL);
        if (result == -1) {
            usleep(EXP_BACKOFF_BASE_DELAY * (1 << attempt) * 1000); // Exponential backoff
            attempt++;
        }
    }

    return result;
}

// Helper function to find the largest integer in an array
void find_largest_integer(int* arr, size_t length) {
    if (!arr || length == 0) {
        printf("Array is empty or null\n");
        return;
    }

    int max_value = arr[0];
    for (size_t i = 1; i < length; ++i) {
        if (arr[i] > max_value) {
            max_value = arr[i];
        }
    }
    printf("Largest integer: %d\n", max_value);
}

// Function to initialize and manage packets
void* initialize_and_manage_packets(void* arg) {
    PacketManager* manager = (PacketManager*)arg;

    // Initialize packet manager
    pthread_mutex_init(&manager->lock, NULL);

    while (1) { // Main loop for managing packets
        pthread_mutex_lock(&manager->lock);

        // Purge expired packets based on expiration threshold
        time_t current_time = time(NULL);
        for (size_t i = 0; i < manager->count;) {
            if (difftime(current_time, ((DataPacket*)manager->packets[i])->timestamp) > EXPIRATION_THRESHOLD) {
                free(((DataPacket*)manager->packets[i])->payload);
                free(manager->packets[i]);
                memmove(&manager->packets[i], &manager->packets[i + 1],
                        (manager->count - i - 1) * sizeof(DataPacket*));
                manager->count--;
            } else {
                ++i;
            }
        }

        pthread_mutex_unlock(&manager->lock);

        // Simulate delay between iterations
        usleep(100000); // 100 ms
    }

    return NULL;
}

// Function to add a new packet
int add_packet(PacketManager* manager, DataPacket* packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        DataPacket** new_packets = realloc(manager->packets, new_capacity * sizeof(DataPacket*));
        if (!new_packets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    manager->packets[manager->count] = packet;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    // Persist packet via API call with retry mechanism
    perform_with_retries(api_call, packet);

    return 0; // Success
}

// Function to update an existing packet by identifier
int update_packet(PacketManager* manager, int id, DataPacket* updated_packet) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (((DataPacket*)manager->packets[i])->id == id) {
            free(((DataPacket*)manager->packets[i])->payload);
            ((DataPacket*)manager->packets[i])->payload = malloc(updated_packet->payload_size);
            memcpy(((DataPacket*)manager->packets[i])->payload, updated_packet->payload,
                   updated_packet->payload_size);

            ((DataPacket*)manager->packets[i])->timestamp = updated_packet->timestamp;
            ((DataPacket*)manager->packets[i])->status = updated_packet->status;

            pthread_mutex_unlock(&manager->lock);

            // Persist packet update via API call with retry mechanism
            perform_with_retries(api_call, (DataPacket*)manager->packets[i]);

            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

// Function to retrieve a packet by identifier
DataPacket* get_packet(PacketManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (((DataPacket*)manager->packets[i])->id == id) {
            DataPacket* packet_copy = malloc(sizeof(DataPacket));
            memcpy(packet_copy, manager->packets[i], sizeof(DataPacket));

            pthread_mutex_unlock(&manager->lock);
            return packet_copy;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Packet not found
}

// Function to read integers from standard input and find the largest
void process_input_integers() {
    int size, *arr;

    printf("Enter number of integers: ");
    scanf("%d", &size);

    arr = (int*)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; ++i) {
        scanf("%d", &arr[i]);
    }

    find_largest_integer(arr, size);

    free(arr);
}

int main() {
    // Example usage
    PacketManager manager = {NULL, 0, 0};
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, initialize_and_manage_packets, &manager) != 0) {
        fprintf(stderr, "Failed to create packet management thread\n");
        return 1;
    }

    process_input_integers();

    // Clean up
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.packets[i]->payload);
        free(manager.packets[i]);
    }
    free(manager.packets);

    pthread_join(thread_id, NULL);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
