typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char key[256];
    int value;
} config_record_t;

typedef struct {
    char key[256];
} config_key_t;

typedef long offset_t;

// Custom memory pool allocator
#define FIXED_BLOCK_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define VARIABLE_BLOCK_SIZE (sizeof(config_record_t) + sizeof(char*))

pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;
void* fixed_block_pool;
size_t fixed_block_count;

void* variable_block_pool;
size_t variable_block_size;
size_t variable_block_count;

// Initialize memory pools
void init_memory_pools(size_t fixed_blocks, size_t var_block_size, size_t var_blocks) {
    pthread_mutex_lock(&memory_pool_lock);
    fixed_block_pool = malloc(fixed_blocks * FIXED_BLOCK_SIZE);
    fixed_block_count = fixed_blocks;

    variable_block_pool = malloc(var_blocks * var_block_size);
    variable_block_size = var_block_size;
    variable_block_count = var_blocks;
    pthread_mutex_unlock(&memory_pool_lock);
}

// Allocate a fixed-size block
void* allocate_fixed_block() {
    pthread_mutex_lock(&memory_pool_lock);
    if (fixed_block_count > 0) {
        void* block = fixed_block_pool;
        fixed_block_pool = ((char*)fixed_block_pool) + FIXED_BLOCK_SIZE;
        --fixed_block_count;
        pthread_mutex_unlock(&memory_pool_lock);
        return block;
    }
    pthread_mutex_unlock(&memory_pool_lock);
    return NULL; // No available blocks
}

// Allocate a variable-size block
void* allocate_variable_block(size_t size) {
    pthread_mutex_lock(&memory_pool_lock);
    if (variable_block_count > 0 && size <= variable_block_size - sizeof(char*)) {
        void* block = variable_block_pool;
        variable_block_pool = ((char*)variable_block_pool) + variable_block_size;
        --variable_block_count;
        pthread_mutex_unlock(&memory_pool_lock);
        return block;
    }
    pthread_mutex_unlock(&memory_pool_lock);
    return NULL; // No available blocks
}

// Free all memory in the pools (for simplicity)
void free_memory_pools() {
    pthread_mutex_lock(&memory_pool_lock);
    free(fixed_block_pool);
    fixed_block_pool = NULL;
    fixed_block_count = 0;

    free(variable_block_pool);
    variable_block_pool = NULL;
    variable_block_count = 0;
    pthread_mutex_unlock(&memory_pool_lock);
}

// Function to initialize data structures
void init_data_structures(size_t num_pdu, size_t long_offset_size, size_t int_keys_size) {
    srand(time(NULL));

    // Allocate and initialize NFAPICRC Indication PDU structures
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < num_pdu; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pdus[i].RNTI = rand() % 10000;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    // Allocate and initialize long offset array
    offset_t* offsets = (offset_t*)calloc(long_offset_size, sizeof(offset_t));

    // Allocate and initialize int keys array
    int* keys = (int*)malloc(int_keys_size * sizeof(int));
    for (size_t i = 0; i < int_keys_size; ++i) {
        keys[i] = rand() % 10000;
    }

    // Initialize config records with random values
    size_t record_count = num_pdu;
    config_record_t* records = (config_record_t*)malloc(record_count * sizeof(config_record_t));
    config_key_t* config_keys = (config_key_t*)malloc(record_count * sizeof(config_key_t));

    for (size_t i = 0; i < record_count; ++i) {
        snprintf(config_keys[i].key, sizeof(config_keys[i].key), "%d", i);
        records[i].value = rand() % 201 - 100;
        char* key_ptr = allocate_variable_block(strlen(config_keys[i].key) + 1);
        if (key_ptr) {
            strcpy((char*)key_ptr, config_keys[i].key);
            ((char**)records[i].key)[0] = key_ptr;
        }
    }

    // Placeholder for thread-safe handling and error management
}

int main() {
