    size_t long_offset_size = 5;
    size_t int_keys_size = 8;

    init_memory_pools(20, sizeof(config_record_t) + sizeof(char*), 15);
    init_data_structures(num_pdu, long_offset_size, int_keys_size);

    // Clean up
    free_memory_pools();
    return 0;
}
