#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef enum {
    TYPE_A,
    TYPE_B,
    TYPE_C,
    TYPE_MAX
} DataType;

typedef struct {
    double value;
    DataType type;
    time_t timestamp;
} Data;

typedef struct {
    Data *data_ptr;
} Entry;

void log_event(const char* event, const char* identifier) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), event, identifier);
}

int allocate_memory(float **float_array, size_t float_count,
                    char **char_array, size_t char_count,
                    Data **data_array, size_t data_count,
                    Entry **entry_array, size_t entry_count) {

    // Allocate memory for arrays
    *float_array = (float*)malloc(float_count * sizeof(float));
    if (!*float_array) return -1;

    *char_array = (char*)malloc(char_count * sizeof(char));
    if (!*char_array) { free(*float_array); return -2; }

    *data_array = (Data*)malloc(data_count * sizeof(Data));
    if (!*data_array) { 
        free(*float_array);
        free(*char_array); 
        return -3;
    }

    *entry_array = (Entry*)malloc(entry_count * sizeof(Entry));
    if (!*entry_array) {
        free(*float_array);
        free(*char_array);
        free(*data_array);
        return -4;
    }

    log_event("Allocated memory", "Arrays");

    // Initialize and populate data structures
    double rolling_sum = 0.0;
    for (size_t i = 0; i < data_count; ++i) {
        (*data_array)[i].value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0.0 and 100.0
        (*data_array)[i].type = rand() % TYPE_MAX;
        (*data_array)[i].timestamp = time(NULL);

        rolling_sum += (*data_array)[i].value;
    }

    float rolling_avg = rolling_sum / data_count;

    // Initialize entries
    for (size_t i = 0; i < entry_count; ++i) {
        if (i < data_count) { // Only assign valid pointers within range
            (*entry_array)[i].data_ptr = &(*data_array)[i];
        } else {
            (*entry_array)[i].data_ptr = NULL;
        }
    }

    printf("Rolling average of 'double' values: %.2f\n", rolling_avg);

    log_event("Initialized data structures", "Data and Entries");

    return 0; // Success
}

void deallocate_memory(float *float_array, char *char_array,
                       Data *data_array, Entry *entry_array) {

    free(float_array);
    free(char_array);
    free(data_array);
    free(entry_array);

    log_event("Deallocated memory", "Arrays");
}

int main() {
    srand((unsigned int)time(NULL));

    float *float_array = NULL;
    char *char_array = NULL;
    Data *data_array = NULL;
    Entry *entry_array = NULL;

    size_t float_count = 10, char_count = 20, data_count = 15, entry_count = 15;

    if (allocate_memory(&float_array, float_count,
                        &char_array, char_count,
                        &data_array, data_count,
                        &entry_array, entry_count) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Process and use the allocated structures...

    deallocate_memory(float_array, char_array, data_array, entry_array);

    return EXIT_SUCCESS;
}
