    for (size_t i = 0; i < num_packets; ++i) {
        if (packets[i] && packets[i]->id == id) {
            Packet* packet = packets[i];
            pthread_mutex_unlock(&packet_lock);
            return packet;
        }
    }
    pthread_mutex_unlock(&packet_lock);
    return NULL;
