void add_packet(int id, long timestamp, int status_flag, int value) {
    pthread_mutex_lock(&packet_lock);
    if (num_packets < MAX_PACKETS) {
        Packet* new_packet = malloc(sizeof(Packet));
        if (!new_packet) {
            log_message(LOG_LEVEL_DEBUG, "Memory allocation failed for packet");
