    if (packet) {
        pthread_mutex_lock(&packet_lock);
        packet->status_flag = status_flag;
        packet->value = value;

        log_message(LOG_LEVEL_INFO, "Packet updated");
        pthread_mutex_unlock(&packet_lock);
    } else {
        log_message(LOG_LEVEL_DEBUG, "Packet not found for update");
    }
}

