        transactions[i].client_id = rand() % 1000 + 1; // Random client ID
        transactions[i].transaction_time = time(NULL);
        transactions[i].amount = (rand() % 500) * 10.0 / 3.0; // Random amount
        transactions[i].status = PENDING;
    }

    return transactions;
}

void process_transaction(Transaction* transactions, size_t size, ClientBalance** balances) {
    if (!transactions || !balances) return;

    for (size_t i = 0; i < size; ++i) {
        int retry_count = 0;
        while (retry_count < 3 && transactions[i].status == PENDING) {
            if (validate_transaction(transactions[i].amount)) {
                transactions[i].status = SUCCESS;
                update_balance(balances, transactions[i].client_id, transactions[i].amount);
            } else {
                retry_count++;
                sleep(1 << retry_count); // Exponential backoff
            }
        }

        if (transactions[i].status == PENDING) {
            transactions[i].status = FAILED;
        }
    }
}

ClientBalance* find_balance(ClientBalance* head, int client_id) {
    while (head) {
        if (head->client_id == client_id) return head;
        head = head->next;
    }
    return NULL;
}

void update_balance(ClientBalance** head, int client_id, double amount) {
    ClientBalance* balance = find_balance(*head, client_id);
    if (!balance) {
        balance = malloc(sizeof(ClientBalance));
        if (balance) {
            balance->client_id = client_id;
            balance->balance = 0.0;
            balance->next = *head;
            *head = balance;
        }
    }

    if (balance) {
        balance->balance += amount;
    } else {
        fprintf(stderr, "Failed to update balance for client %d\n", client_id);
    }
}

void free_resources(Transaction* transactions, ClientBalance* balances) {
    free(transactions);

    while (balances) {
        ClientBalance* temp = balances;
        balances = balances->next;
        free(temp);
    }
}

int main() {
    size_t transaction_count = 1000; // Example count
    Transaction* transactions = create_transactions(transaction_count);
    if (!transactions) return EXIT_FAILURE;

    ClientBalance* client_balances = NULL;

    process_transaction(transactions, transaction_count, &client_balances);

    free_resources(transactions, client_balances);
    return EXIT_SUCCESS;
}
