#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example limit: 1 MB
#define TIME_WINDOW_SIZE 60          // Time window in seconds for aggregation
#define SENSOR_ID_MAX 256            // Maximum number of sensors

typedef struct {
    float measurement;
    char location[64];
    time_t timestamp;
    int sensor_id;
} Measurement;

typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t current_memory_usage;
} Queue;

typedef struct {
    Queue queues[SENSOR_ID_MAX];
    pthread_mutex_t global_lock;
} SensorNetwork;

SensorNetwork network;

void initialize_sensor_network() {
    pthread_mutex_init(&network.global_lock, NULL);
    for (int i = 0; i < SENSOR_ID_MAX; ++i) {
        network.queues[i].head = NULL;
        network.queues[i].current_memory_usage = 0;
        pthread_mutex_init(&network.queues[i].lock, NULL);
    }
}

void* process_measurement(void* arg) {
    Measurement* measurement = (Measurement*)arg;

    pthread_mutex_lock(&network.global_lock);

    if (measurement->sensor_id < 0 || measurement->sensor_id >= SENSOR_ID_MAX) {
        fprintf(stderr, "Invalid sensor ID\n");
        pthread_mutex_unlock(&network.global_lock);
        return NULL;
    }

    Queue* queue = &network.queues[measurement->sensor_id];
    pthread_mutex_lock(&queue->lock);

    size_t new_memory_usage = queue->current_memory_usage + sizeof(Measurement) + strlen(measurement->location) + 1;

    if (new_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded\n");
        pthread_mutex_unlock(queue->lock);
        pthread_mutex_unlock(&network.global_lock);
        return NULL;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for measurement node\n");
        pthread_mutex_unlock(queue->lock);
        pthread_mutex_unlock(&network.global_lock);
        return NULL;
    }

    *measurement = *(Measurement*)arg; // Deep copy
    new_node->data = *measurement;

    new_node->next = queue->head;
    queue->head = new_node;
    queue->current_memory_usage = new_memory_usage;

    pthread_mutex_unlock(queue->lock);
    pthread_mutex_unlock(&network.global_lock);

    return NULL;
}

void serialize_data(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        return;
    }

    pthread_mutex_lock(&network.global_lock);

    for (int i = 0; i < SENSOR_ID_MAX; ++i) {
        Queue* queue = &network.queues[i];
        pthread_mutex_lock(queue->lock);

        Node* current = queue->head;
        while (current) {
            fwrite(&(current->data), sizeof(Measurement), 1, file);
            current = current->next;
        }

        pthread_mutex_unlock(queue->lock);
    }

    pthread_mutex_unlock(&network.global_lock);
    fclose(file);
}

void deserialize_data(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return;
    }

    Measurement measurement;

    while (fread(&measurement, sizeof(Measurement), 1, file)) {
        pthread_create(NULL, NULL, process_measurement, &measurement);
    }

    fclose(file);
}

void cleanup_sensor_network() {
    for (int i = 0; i < SENSOR_ID_MAX; ++i) {
        Queue* queue = &network.queues[i];
        pthread_mutex_lock(queue->lock);

        Node* current = queue->head;
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(queue->lock);
        pthread_mutex_destroy(&queue->lock);
    }
    pthread_mutex_destroy(&network.global_lock);
}

int main() {
    initialize_sensor_network();

    // Example usage of serialization and deserialization
    deserialize_data("data.bin");
    serialize_data("backup_data.bin");

    cleanup_sensor_network();
    return 0;
}
```

This code initializes a sensor network, processes incoming measurements, serializes/deserializes data, and cleans up resources. It handles memory limits and concurrency with mutex locks to ensure thread safety and prevent race conditions or deadlocks.']

