#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1000
#define MAX_SESSIONS 100000

typedef struct {
    char client_id[32];
    int connection_state;
    char **recent_messages;
    size_t message_count;
} SessionContext;

typedef struct {
    SessionContext *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} SessionPool;

typedef struct {
    SessionPool pool;
    FILE *log_file;
    time_t last_cleanup_time;
    size_t cleanup_interval;
} SessionManager;

// Function prototypes
SessionManager* create_session_manager(size_t initial_capacity, size_t cleanup_interval);
void destroy_session_manager(SessionManager *manager);
int add_session(SessionManager *manager, const char *client_id, int connection_state);
int receive_message(SessionManager *manager, const char *client_id, const char *message);
void periodic_cleanup(SessionManager *manager);
void* session_pool_worker(void *arg);

// Helper functions
static void log_operation(SessionManager *manager, const char *operation, const char *details) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->pool.lock);
    fprintf(manager->log_file, "[%ld] %s: %s\n", now, operation, details);
    fflush(manager->log_file);
    pthread_mutex_unlock(&manager->pool.lock);
}

static int find_session_index(SessionManager *manager, const char *client_id) {
    for (size_t i = 0; i < manager->pool.count; ++i) {
        if (strcmp(manager->pool.sessions[i].client_id, client_id) == 0) {
            return i;
        }
    }
    return -1;
}

static void resize_session_pool(SessionManager *manager) {
    size_t new_capacity = manager->pool.capacity * 2;
    SessionContext *new_sessions = realloc(manager->pool.sessions, new_capacity * sizeof(SessionContext));
    if (!new_sessions) {
        log_operation(manager, "ERROR", "Memory allocation failed during pool resizing");
        return;
    }
    manager->pool.sessions = new_sessions;
    manager->pool.capacity = new_capacity;
}

SessionManager* create_session_manager(size_t initial_capacity, size_t cleanup_interval) {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) {
        perror("Failed to allocate memory for session manager");
        return NULL;
    }

    manager->pool.sessions = calloc(initial_capacity, sizeof(SessionContext));
    if (!manager->pool.sessions) {
        free(manager);
        perror("Failed to allocate memory for sessions");
        return NULL;
    }
    manager->pool.capacity = initial_capacity;
    manager->pool.count = 0;
    pthread_mutex_init(&manager->pool.lock, NULL);
    pthread_cond_init(&manager->pool.cond_var, NULL);

    manager->log_file = fopen("session_manager.log", "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        free(manager->pool.sessions);
        free(manager);
        return NULL;
    }

    manager->last_cleanup_time = time(NULL);
    manager->cleanup_interval = cleanup_interval;

    pthread_t worker_thread;
    pthread_create(&worker_thread, NULL, session_pool_worker, manager);

    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->pool.lock);
    for (size_t i = 0; i < manager->pool.count; ++i) {
        free(manager->pool.sessions[i].recent_messages);
    }
    free(manager->pool.sessions);
    pthread_mutex_unlock(&manager->pool.lock);

    fclose(manager->log_file);
    pthread_mutex_destroy(&manager->pool.lock);
    pthread_cond_destroy(&manager->pool.cond_var);
    free(manager);
}

int add_session(SessionManager *manager, const char *client_id, int connection_state) {
    if (!manager || !client_id) return -1;

    pthread_mutex_lock(&manager->pool.lock);

    if (find_session_index(manager, client_id) != -1) {
        log_operation(manager, "ERROR", "Duplicate client ID");
        pthread_mutex_unlock(&manager->pool.lock);
        return -1;
    }

    if (manager->pool.count >= manager->pool.capacity) {
        resize_session_pool(manager);
    }

    SessionContext *session = &manager->pool.sessions[manager->pool.count++];
    strncpy(session->client_id, client_id, sizeof(session->client_id) - 1);
    session->connection_state = connection_state;
    session->recent_messages = NULL;
    session->message_count = 0;

    log_operation(manager, "ADD_SESSION", client_id);

    pthread_mutex_unlock(&manager->pool.lock);
    return 0;
}

int receive_message(SessionManager *manager, const char *client_id, const char *message) {
    if (!manager || !client_id || !message) return -1;

    pthread_mutex_lock(&manager->pool.lock);

    int index = find_session_index(manager, client_id);
    if (index == -1) {
        log_operation(manager, "ERROR", "Session not found");
        pthread_mutex_unlock(&manager->pool.lock);
        return -1;
    }

    SessionContext *session = &manager->pool.sessions[index];

    size_t new_count = session->message_count + 1;
    char **new_messages = realloc(session->recent_messages, new_count * sizeof(char *));
    if (!new_messages) {
        log_operation(manager, "ERROR", "Memory allocation failed for message");
        pthread_mutex_unlock(&manager->pool.lock);
        return -1;
    }

    session->recent_messages = new_messages;
    session->recent_messages[session->message_count++] = strdup(message);

    log_operation(manager, "RECEIVE_MESSAGE", client_id);

    pthread_mutex_unlock(&manager->pool.lock);
    return 0;
}

void periodic_cleanup(SessionManager *manager) {
    if (!manager) return;

    time_t now = time(NULL);
    if (now - manager->last_cleanup_time >= manager->cleanup_interval) {
        pthread_mutex_lock(&manager->pool.lock);

        for (size_t i = 0; i < manager->pool.count;) {
            SessionContext *session = &manager->pool.sessions[i];
            // Define your criteria for inactive sessions
            if (/* session is inactive */) {
                free(session->recent_messages);
                memmove(&manager->pool.sessions[i], &manager->pool.sessions[i + 1],
                        (--manager->pool.count - i) * sizeof(SessionContext));
            } else {
                ++i;
            }
        }

        log_operation(manager, "CLEANUP", "Periodic cleanup executed");

        pthread_mutex_unlock(&manager->pool.lock);
        manager->last_cleanup_time = now;
    }
}

void* session_pool_worker(void *arg) {
    SessionManager *manager = (SessionManager *)arg;

    while (1) {
        periodic_cleanup(manager);
        usleep(1000000); // Sleep for 1 second
    }

    return NULL;
}
