#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_SESSION_COUNT 100
#define MAX_SESSIONS 1000
#define SESSION_TIMEOUT 300 // in seconds
#define GRACE_PERIOD 600 // in seconds

typedef struct {
    char name[50];
    char email[100];
    char role[20];
} UserProfile;

typedef struct {
    int sessionID;
    char clientIP[16];
    time_t lastActivity;
    UserProfile userProfile;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t count;
    size_t capacity;
    UserSession *overflow;
    size_t overflowCount;
} SessionManager;

void initSessionManager(SessionManager *manager) {
    manager->sessions = (UserSession *)malloc(INITIAL_SESSION_COUNT * sizeof(UserSession));
    if (!manager->sessions) {
        fprintf(stderr, "Memory allocation failed for sessions.\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = INITIAL_SESSION_COUNT;
    manager->overflow = NULL;
    manager->overflowCount = 0;
}

void resizeSessions(SessionManager *manager) {
    if (manager->count >= manager->capacity && manager->capacity < MAX_SESSIONS) {
        size_t newCapacity = manager->capacity * 2;
        UserSession *newSessions = realloc(manager->sessions, newCapacity * sizeof(UserSession));
        if (!newSessions) {
            fprintf(stderr, "Memory reallocation failed for sessions.\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    } else if (manager->count >= MAX_SESSIONS && manager->overflowCount < MAX_SESSIONS - INITIAL_SESSION_COUNT) {
        size_t newOverflowCapacity = manager->overflowCount + 1;
        UserSession *newOverflow = realloc(manager->overflow, newOverflowCapacity * sizeof(UserSession));
        if (!newOverflow) {
            fprintf(stderr, "Memory reallocation failed for overflow sessions.\n");
            exit(EXIT_FAILURE);
        }
        manager->overflow = newOverflow;
    } else {
        // Handle session expiration and removal
        time_t now = time(NULL);
        for (size_t i = 0; i < manager->count; ++i) {
            if (difftime(now, manager->sessions[i].lastActivity) > GRACE_PERIOD) {
                memmove(&manager->sessions[i], &manager->sessions[i + 1],
                        (manager->count - i - 1) * sizeof(UserSession));
                --manager->count;
                --i; // Adjust index after removal
            }
        }
    }
}

void expireSessions(SessionManager *manager) {
    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(now, manager->sessions[i].lastActivity) > SESSION_TIMEOUT) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(UserSession));
            --manager->count;
            --i; // Adjust index after removal
        }
    }
}

UserSession* getSessionByID(SessionManager *manager, int sessionID) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].sessionID == sessionID) {
            return &manager->sessions[i];
        }
    }
    for (size_t i = 0; i < manager->overflowCount; ++i) {
        if (manager->overflow[i].sessionID == sessionID) {
            return &manager->overflow[i];
        }
    }
    return NULL;
}

void addSession(SessionManager *manager, int sessionID, const char* clientIP, UserProfile userProfile) {
    resizeSessions(manager);
    UserSession newSession = { .sessionID = sessionID, .lastActivity = time(NULL) };
    strncpy(newSession.clientIP, clientIP, sizeof(newSession.clientIP));
    newSession.userProfile = userProfile;
    if (manager->count < MAX_SESSIONS) {
        manager->sessions[manager->count++] = newSession;
    } else {
        manager->overflow[manager->overflowCount++] = newSession;
    }
}

void serializeSessions(const SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization.\n");
        return;
    }
    fwrite(manager->sessions, sizeof(UserSession), manager->count, file);
    fwrite(manager->overflow, sizeof(UserSession), manager->overflowCount, file);
    fclose(file);
}

void deserializeSessions(SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization.\n");
        return;
    }
    size_t sessionsRead = fread(manager->sessions, sizeof(UserSession), manager->capacity, file);
    manager->count = (size_t)fmin(sessionsRead, manager->capacity);

    size_t overflowRead = fread(manager->overflow, sizeof(UserSession), MAX_SESSIONS - INITIAL_SESSION_COUNT, file);
    manager->overflowCount = (size_t)fmin(overflowRead, MAX_SESSIONS - INITIAL_SESSION_COUNT);
    fclose(file);
}

void cleanup(SessionManager *manager) {
    free(manager->sessions);
    if (manager->overflow) {
        free(manager->overflow);
    }
}

// Example logging function
void logSessionEvent(const char* message) {
    printf("LOG: %s\n", message); // Replace with actual logging integration
}
