void initialize_data(int count) {
    if (count > 10000 || count <= 0) {
        fprintf(stderr, "Invalid number of elements. Must be between 1 and 10,000.\n");
        return;
    }

    // Calculate required memory size
    const size_t double_size = sizeof(double);
    const size_t char_pointer_size = sizeof(char*);
    const size_t element_size = sizeof(element_t);

    // Assuming each string will have a max length of 100 chars (including null terminator)
    const size_t max_string_length = 100;

    size_t total_memory_needed =
        count * double_size +       // For the array of doubles
        count * char_pointer_size + // For the array of char pointers
        count * element_size +      // For the array of elements
        count * max_string_length;  // For the strings (worst case)

    const size_t max_heap_size = 2 * 1024 * 1024;

    if (total_memory_needed > max_heap_size) {
        fprintf(stderr, "Insufficient heap memory available.\n");
        return;
    }

    double* double_array = (double*)malloc(count * double_size);
    char** string_array = (char**)malloc(count * char_pointer_size);
    element_t* elements = (element_t*)malloc(count * element_size);

    if (!double_array || !string_array || !elements) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(double_array);
        free(string_array);
        free(elements);
        return;
    }

    // Initialize the string pointers with example strings
    for (int i = 0; i < count; ++i) {
        char* str = (char*)malloc(max_string_length);
        snprintf(str, max_string_length, "Element %d", i + 1);
        string_array[i] = str;
    }

    // Seed random number generator
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        elements[i].identifier = i + 1;
        double range_min = 0.0, range_max = 100.0;

        // In case of API error or delay, fallback to a default seed
        elements[i].value = ((double)rand() / RAND_MAX) * (range_max - range_min) + range_min;

        double_array[i] = elements[i].value;  // Store the random number in double array
    }

    printf("Initialization complete.\n");

    // Free all allocated memory
    for (int i = 0; i < count; ++i) {
        free(string_array[i]);
    }
    free(double_array);
    free(string_array);
    free(elements);

    printf("Memory freed successfully.\n");
}

// Example usage
int main() {
    initialize_data(5000); // Adjust the number of elements as needed
    return 0;
}
