#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_MESSAGES 100000
#define CLEANUP_INTERVAL 86400 // seconds (24 hours)
#define LOG_RETENTION_DAYS 7

typedef enum {
    NFAPI_MSG_TYPE_A,
    NFAPI_MSG_TYPE_B,
    // Add other message types as needed
} NFAPI_MSG_TYPE;

typedef struct {
    NFAPI_MSG_TYPE type;
    void *params; // Replace with specific parameter structures
    time_t last_accessed;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T messages[MAX_MESSAGES];
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    FILE *log_file;
} MessageList;

// Function prototypes
void initialize_message_list(MessageList *list);
int add_message(MessageList *list, NFAPI_MSG_TYPE type, void *params);
int remove_message(MessageList *list, int index);
void* cleanup_messages(void *arg);
void log_operation(MessageList *list, const char *operation, int status);

// Initialize the message list
void initialize_message_list(MessageList *list) {
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->count = 0;

    // Open log file with rotation support
    char log_filename[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    snprintf(log_filename, sizeof(log_filename), "log_%d%02d%02d.log", 
             tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday);

    list->log_file = fopen(log_filename, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

// Add a new message to the list
int add_message(MessageList *list, NFAPI_MSG_TYPE type, void *params) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_MESSAGES) {
        pthread_mutex_unlock(&list->lock);
        log_operation(list, "Add", 0); // Log failure
        return -1;
    }

    list->messages[list->count].type = type;
    list->messages[list->count].params = params;
    time(&(list->messages[list->count].last_accessed));

    list->count++;
    pthread_mutex_unlock(&list->lock);

    log_operation(list, "Add", 1); // Log success
    return 0;
}

// Remove a message from the list by index
int remove_message(MessageList *list, int index) {
    if (index < 0 || index >= list->count) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&list->lock);

    free(list->messages[index].params); // Free associated params if necessary

    for (int i = index; i < list->count - 1; ++i) {
        list->messages[i] = list->messages[i + 1];
    }

    list->count--;
    pthread_mutex_unlock(&list->lock);

    log_operation(list, "Remove", 1); // Log success
    return 0;
}

// Cleanup messages not accessed in the last 24 hours
void* cleanup_messages(void *arg) {
    MessageList *list = (MessageList *)arg;

    while (1) {
        pthread_mutex_lock(&list->lock);

        time_t now = time(NULL);
        int i = 0;

        while (i < list->count) {
            if (difftime(now, list->messages[i].last_accessed) > CLEANUP_INTERVAL) {
                remove_message(list, i);
            } else {
                ++i;
            }
        }

        pthread_mutex_unlock(&list->lock);

        sleep(CLEANUP_INTERVAL); // Sleep for 24 hours
    }

    return NULL;
}

// Log operations to a file with rotation support
void log_operation(MessageList *list, const char *operation, int status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(list->log_file, "[%04d-%02d-%02d %02d:%02d:%02d] Operation: %s, Status: %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            operation, status);

    fflush(list->log_file);
}

// Main function for testing
int main() {
    MessageList list;
    initialize_message_list(&list);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_messages, &list);

    // Example usage
    add_message(&list, NFAPI_MSG_TYPE_A, malloc(100));
    remove_message(&list, 0);

    pthread_join(cleanup_thread, NULL);
    fclose(list.log_file);

    return 0;
}
