typedef struct PacketManager {
    Packet** packets;
    int capacity;
    int size;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* init_packet_manager(int initial_capacity) {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    manager->packets = (Packet**)calloc(initial_capacity, sizeof(Packet*));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void free_packet_manager(PacketManager* manager) {
    for (int i = 0; i < manager->size; ++i) {
        free(manager->packets[i]->payload);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_packet(PacketManager* manager, Packet* packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->packets = (Packet**)realloc(manager->packets, manager->capacity * sizeof(Packet*));
    }

    for (int i = 0; i < manager->size; ++i) {
        if (manager->packets[i]->id == packet->id) {
            free(manager->packets[i]->payload);
            memcpy(manager->packets[i], packet, sizeof(Packet));
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    manager->packets[manager->size++] = packet;
    store_packet(*packet);

    pthread_mutex_unlock(&manager->lock);
}

Packet* get_packet(PacketManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; ++i) {
        if (manager->packets[i]->id == id) {
            Packet* packet_copy = malloc(sizeof(Packet));
            *packet_copy = *(manager->packets[i]);
            pthread_mutex_unlock(&manager->lock);
            return packet_copy;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_packet(PacketManager* manager, Packet* updated_packet) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->size; ++i) {
        if (manager->packets[i]->id == updated_packet->id) {
            free(manager->packets[i]->payload);
            memcpy(manager->packets[i], updated_packet, sizeof(Packet));
            store_packet(*updated_packet);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void purge_old_packets(PacketManager* manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size;) {
        get_config(&current_time, NULL); // Get dynamic expiration threshold
        if (difftime(current_time, manager->packets[i]->timestamp) > current_time) {
            free(manager->packets[i]->payload);
            free(manager->packets[i]);
            for (; i < manager->size - 1; ++i) {
                manager->packets[i] = manager->packets[i + 1];
            }
            --manager->size;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

