    strncpy(new_packet->dst_ip, dst_ip, 15); new_packet->dst_ip[15] = '\0';
    new_packet->src_port = src_port;
    new_packet->dst_port = dst_port;
    strncpy(new_packet->protocol_type, protocol_type, 9); new_packet->protocol_type[9] = '\0';
    new_packet->payload_length = payload_length;
    new_packet->session = session;

    // Insert packet into session
    Packet *current = session->packets;
    if (!current) {
        session->packets = new_packet;
    } else {
        while (current->next) current = current->next;
        current->next = new_packet;
    }

    session->packet_count++;
    pthread_mutex_unlock(&lock_session_list);
}

Session *find_or_create_session(int session_id, const char *src_ip, const char *dst_ip,
                                int src_port, int dst_port, const char *protocol_type) {
    // Thread-safe access to the session list
    pthread_mutex_lock(&lock_session_list);

    for (Session *session = head_sessions; session != NULL; session = session->next_session) {
        if (session->session_id == session_id) {
            pthread_mutex_unlock(&lock_session_list);
            return session;
        }
    }

    Session *new_session = (Session *)malloc(sizeof(Session));
    if (!new_session) {
        fprintf(stderr, "Memory allocation failed for session\n");
        pthread_mutex_unlock(&lock_session_list);
        return NULL;
    }

    new_session->session_id = session_id;
    new_session->packets = NULL;
    new_session->packet_count = 0;
    new_session->encrypted_flag = 0; // Assume not encrypted, logic to determine this should be added
    new_session->next_session = head_sessions;
    head_sessions = new_session;

    pthread_mutex_unlock(&lock_session_list);
    return new_session;
}

ProtocolStats *update_protocol_stats(ProtocolStats *head, const char *protocol_type,
                                     int payload_length, double latency, int error) {
    pthread_mutex_lock(&lock_protocol_list);

    for (ProtocolStats *proto = head; proto != NULL; proto = proto->next_protocol) {
        if (strcmp(proto->protocol_type, protocol_type) == 0) {
            proto->packet_count++;
            proto->byte_count += payload_length;
            proto->average_latency = ((proto->average_latency * (proto->packet_count - 1)) + latency) / proto->packet_count;
            proto->error_rate = ((proto->error_rate * (proto->packet_count - 1)) + error) / proto->packet_count;

            pthread_mutex_unlock(&lock_protocol_list);
            return proto;
        }
    }

    ProtocolStats *new_proto = (ProtocolStats *)malloc(sizeof(ProtocolStats));
    if (!new_proto) {
        fprintf(stderr, "Memory allocation failed for protocol stats\n");
        pthread_mutex_unlock(&lock_protocol_list);
        return head;
    }

    strncpy(new_proto->protocol_type, protocol_type, 9); new_proto->protocol_type[9] = '\0';
    new_proto->packet_count = 1;
    new_proto->byte_count = payload_length;
    new_proto->average_latency = latency;
    new_proto->error_rate = error;

    new_proto->next_protocol = head_protocols;
    head_protocols = new_proto;

    pthread_mutex_unlock(&lock_protocol_list);
    return new_proto;
}

void serialize_data(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
