                    "\"src_port\": %d, \"dst_port\": %d, \"protocol_type\": \"%s\", "
                    "\"payload_length\": %d}", 
                    packet->timestamp, packet->src_ip, packet->dst_ip,
                    packet->src_port, packet->dst_port, packet->protocol_type, packet->payload_length);
            packet = packet->next;
        }
        fputc(']', file);
        fputc('}', file);
    }

    fclose(file);
}

int deserialize_data(const char *filename) {
