// Configuration structure
typedef struct {
    char priorityLevelDistribution[2]; // 'L' or 'H'
    size_t maxMessageLength;
    bool compressMessages;
} Config;

Config config;
bool errorOccurred = false;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t nodeCount = 0;
size_t peakMemoryUsage = 0;
size_t fragmentationLevel = 0;
size_t liveNodes = 0;

// Node structure
typedef struct Node {
    int id;
    char priority;
    char *message;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

// Logger function
void logMessage(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Configuration parsing and validation (simplified)
bool loadConfig(const char *filePath) {
    // Dummy implementation for demonstration
    config.priorityLevelDistribution[0] = 'L';
    config.priorityLevelDistribution[1] = 'H';
    config.maxMessageLength = 256;
    config.compressMessages = false;

    return true; // Assume success for simplicity
}

// Function to compress message (dummy)
char* compress(const char *message) {
    // Dummy implementation: just returns the original message
    size_t len = strlen(message);
    char *compressed = malloc(len + 1); // No real compression here
    if (!compressed) return NULL;
    strcpy(compressed, message);
    return compressed;
}

// Function to decompress message (dummy)
char* decompress(const char *message) {
    // Dummy implementation: just returns the original message
    size_t len = strlen(message);
    char *decompressed = malloc(len + 1); // No real decompression here
    if (!decompressed) return NULL;
    strcpy(decompressed, message);
    return decompressed;
}

// Function to allocate a new node
Node* createNode(int id, char priority, const char *message) {
    Node *newNode = malloc(sizeof(Node));
    if (!newNode) {
        errorOccurred = true;
        logMessage("Memory allocation failed for new node");
        return NULL;
    }

    newNode->id = id;
    newNode->priority = priority;
    size_t messageLen = strlen(message);
    char *allocMsg;

    if (config.compressMessages && messageLen > 0) {
        allocMsg = compress(message);
    } else {
        allocMsg = malloc(config.maxMessageLength + 1);
    }

    if (!allocMsg) {
        free(newNode);
        errorOccurred = true;
        logMessage("Memory allocation failed for node message");
        return NULL;
    }

    strncpy(allocMsg, message, config.maxMessageLength);
    allocMsg[config.maxMessageLength] = '\0';
    newNode->message = allocMsg;
    newNode->next = NULL;

    pthread_mutex_lock(&listLock);
    newNode->next = head;
    head = newNode;
    liveNodes++;
    if (liveNodes > peakMemoryUsage) {
        peakMemoryUsage = liveNodes;
    }
    pthread_mutex_unlock(&listLock);

    logMessage("Node allocated successfully");
    return newNode;
}

// Function to free a node
void freeNode(Node *node) {
    if (!node) return;

    char *toFree = config.compressMessages ? decompress(node->message) : node->message;
    if (toFree) free(toFree);

    pthread_mutex_lock(&listLock);
    Node **current = &head;
    while (*current && *current != node) {
        current = &(*current)->next;
    }

    if (*current) {
        *current = node->next;
        liveNodes--;
    }

    free(node);
    logMessage("Node deallocated successfully");
    pthread_mutex_unlock(&listLock);
}

// Function to monitor memory usage
void reportMemoryUsage() {
    printf("Peak Memory Usage: %zu nodes\n", peakMemoryUsage);
    printf("Current Live Nodes: %zu nodes\n", liveNodes);
    // Fragmentation level could be calculated based on specific criteria
    fragmentationLevel = 0; 
    printf("Fragmentation Level: %zu\n", fragmentationLevel);
}

// Example usage
int main() {
    if (!loadConfig("config.cfg")) {
        logMessage("Failed to load configuration");
        return EXIT_FAILURE;
    }

    // Create nodes concurrently (example)
    pthread_t threads[100];
    for (int i = 0; i < 100; ++i) {
        int id = i;
        pthread_create(&threads[i], NULL, (void *(*)(void *)) createNode, (void *)id);
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    reportMemoryUsage();

    // Clean up
    while (head != NULL) {
        Node *temp = head;
        head = head->next;
        freeNode(temp);
    }

    return EXIT_SUCCESS;
}
