#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h> // JSON library

// Define StatusType enum for network configuration status.
typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_ERROR
} StatusType;

// NetworkConfig struct to store network configurations.
typedef struct NetworkConfig {
    char *name;
    double value;
    StatusType status;
    struct NetworkConfig* next; // For linked list management.
} NetworkConfig;

// Node for hash map implementation.
typedef struct HashMapNode {
    char* key;
    NetworkConfig* config;
    struct HashMapNode* next;
} HashMapNode;

// TaskQueue item and queue definition.
typedef struct TaskQueueItem {
    void (*task)(void*);
    void* arg;
} TaskQueueItem;

#define MAX_QUEUE_SIZE 100
TaskQueueItem task_queue[MAX_QUEUE_SIZE];
int queue_size = 0;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

// Global variables for LRU management.
NetworkConfig *head = NULL, *tail = NULL;
pthread_mutex_t lru_lock = PTHREAD_MUTEX_INITIALIZER;
#define MAX_LRU_SIZE 10

// Memory profiler placeholder function (to be integrated).
void memory_profiler_init() {}

// Logging function placeholder
void log_event(const char* message) {
    printf("%s\n", message); // Simple logging to stdout.
}

// Function prototypes.
NetworkConfig *parse_and_validate_config(const char *json_data);
void store_network_config(NetworkConfig *config);
void evict_lru();
int hash_map_insert(HashMapNode **hash_table, const char *key, NetworkConfig *config);
NetworkConfig* hash_map_search(HashMapNode **hash_table, const char *key);
void add_task_to_queue(void (*task)(void*), void* arg);
void task_worker(); // Background worker thread function.

// Parse and validate configuration data from JSON.
NetworkConfig *parse_and_validate_config(const char *json_data) {
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);

    if (!root) {
        log_event("Error parsing JSON");
        return NULL;
    }

    NetworkConfig *config = malloc(sizeof(NetworkConfig));
    config->name = strdup("example"); // Placeholder for actual name extraction
    config->value = json_real_value(json_object_get(root, "value")); // Example field
    if (json_is_nan(config->value)) {
        free(config);
        return NULL;
    }
    config->status = STATUS_ACTIVE; // Set based on real validation logic

    json_decref(root);
    return config;
}

// Store configuration in LRU list.
void store_network_config(NetworkConfig *config) {
    pthread_mutex_lock(&lru_lock);

    if (!head) {
        head = tail = config;
        config->next = NULL;
    } else {
        tail->next = config;
        tail = config;
        tail->next = NULL;
    }

    evict_lru(); // Ensure LRU size constraint.

    pthread_mutex_unlock(&lru_lock);
}

// Evict least recently used element.
void evict_lru() {
    if (!head) return;

    NetworkConfig *temp = head;
    head = head->next;
    free(temp->name);
    free(temp);

    if (head == NULL) tail = NULL; // If list becomes empty
}

// Insert into hash map for fast lookup.
int hash_map_insert(HashMapNode **hash_table, const char *key, NetworkConfig *config) {
    size_t index = hash_string(key) % 100;
    HashMapNode *node = malloc(sizeof(HashMapNode));
    node->key = strdup(key);
    node->config = config;
    node->next = hash_table[index];
    hash_table[index] = node;

    return 1; // Success
}

// Search in hash map.
NetworkConfig* hash_map_search(HashMapNode **hash_table, const char *key) {
    size_t index = hash_string(key) % 100;
    HashMapNode *node = hash_table[index];

    while (node) {
        if (strcasecmp(node->key, key) == 0)
            return node->config;
        node = node->next;
    }
    return NULL; // Not found
}

// Add a task to the queue.
void add_task_to_queue(void (*task)(void*), void* arg) {
    pthread_mutex_lock(&queue_lock);

    if (queue_size < MAX_QUEUE_SIZE) {
        TaskQueueItem item = { task, arg };
        task_queue[queue_size++] = item;
        pthread_cond_signal(&not_empty);
    }

    pthread_mutex_unlock(&queue_lock);
}

// Worker function to process tasks.
void *task_worker(void *arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);

        while (queue_size == 0)
            pthread_cond_wait(&not_empty, &queue_lock);

        TaskQueueItem task = task_queue[--queue_size];

        pthread_mutex_unlock(&queue_lock);

        task.task(task.arg); // Execute the task.
    }
}

// Hash function for strings.
size_t hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

// Function to initialize and start worker threads.
void init_worker_threads(int num_threads) {
    pthread_t workers[num_threads];

    for (int i = 0; i < num_threads; ++i)
        pthread_create(&workers[i], NULL, task_worker, NULL);
}

int main() {
    memory_profiler_init();

    // Example usage:
    const char *json_data = "{\"value\": 10.5}";
    NetworkConfig *config = parse_and_validate_config(json_data);

    if (config) {
        store_network_config(config);
        add_task_to_queue(log_event, "Task started");
    }

    init_worker_threads(4); // Start worker threads.

    pthread_exit(NULL); // Clean exit
}
```

