        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_log;
    }

    pthread_mutex_unlock(&memory_lock);

    return new_log;
}

void cleanup_memory(OffsetRecord* offset_records, KeyRecord* key_records, size_t key_count, RandomValue* random_values, RecordLog** log_list) {
    if (offset_records != NULL) free(offset_records);
    for (size_t i = 0; i < key_count; ++i) {
        if (key_records[i].offset_record_ptr != NULL) free(key_records[i].offset_record_ptr);
    }
    if (key_records != NULL) free(key_records);
    if (random_values != NULL) free(random_values);

    while (*log_list != NULL) {
        RecordLog* temp = *log_list;
        *log_list = (*log_list)->next;
        free(temp);
    }

    pthread_mutex_lock(&memory_lock);
    total_configurations_allocated = 0; // Reset count
    pthread_mutex_unlock(&memory_lock);
}

int main() {
