// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to generate random integer within a specified range
int rand_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate random double within a specified range
double rand_double(double min, double max) {
    double r = (double)rand() / RAND_MAX;
    return min + r * (max - min);
}

// Log function for error handling
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to initialize records with dynamic memory allocation and alignment checks
Record* initialize_records(size_t num_records, int key_min, int key_max, double value_min, double value_max,
                           size_t alignment, int enable_logging) {

    if (alignment < 64 || alignment % 8 != 0) {
        log_error("Alignment must be a multiple of 8 and at least 64 bytes.");
        return NULL;
    }

    // Seed the random number generator
    srand(time(NULL));

    size_t record_size = sizeof(Record);
    size_t padding = (alignment - (record_size % alignment)) % alignment;

    // Calculate total memory requirement per record with padding for alignment
    size_t aligned_record_size = record_size + padding;

    Record* records = NULL;
    void* ptr;

    // Allocate and align memory for the array of records
    if ((ptr = malloc(num_records * aligned_record_size)) == NULL) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    // Align the pointer to the specified boundary
    uintptr_t addr = (uintptr_t)ptr + padding;
    ptr = (void*)(((addr + alignment - 1) / alignment) * alignment);

    records = (Record*)ptr;

    // Verify that all allocations are correctly aligned
    if ((uintptr_t)records % alignment != 0 && enable_logging) {
        log_error("Alignment verification failed.");
        free(ptr);
        return NULL;
    }

    // Initialize each record
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = i + ((uintptr_t)records - (uintptr_t)ptr) / aligned_record_size;
        records[i].key = rand_int(key_min, key_max);
        records[i].value = rand_double(value_min, value_max);
    }

    return records;
}

// Example usage
int main() {
    size_t num_records = 10;
    int key_min = 1, key_max = 100;
    double value_min = 0.0, value_max = 1.0;
    size_t alignment = 64;
    int enable_logging = 1;

    Record* records = initialize_records(num_records, key_min, key_max, value_min, value_max, alignment, enable_logging);

    if (records != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu: Offset = %ld, Key = %d, Value = %.2f\n", i, records[i].offset, records[i].key, records[i].value);
        }
        free(records); // Free the allocated memory
    }

    return 0;
}
