    }

    // Initialize each config structure
    for (size_t i = 0; i < count; ++i) {
        int port = portStart + i;

        configs[i].configurationName = generate_config_name(baseName, i);
        if (configs[i].configurationName == NULL) {
            perror("Failed to allocate memory for configuration name.");
            // Free previously allocated names and configs
            while (i > 0) free(configs[--i].configurationName);
            aligned_free(configs);
            return NULL;
        }

        int port_available = is_port_available_ext(port);
        if (!port_available) {
            // Fallback to local check
            port_available = is_port_available_local(port);
        }

        configs[i].portNumber = (port_available && port >= 1024 && port <= 65535) ? port : -1;

        init_settings(&configs[i].settingObject);

        if (enable_monitoring) {
            // Log or monitor performance and alignment verification
            printf("Config %zu initialized with name: %s, port: %d\n", i,
                   configs[i].configurationName, configs[i].portNumber);
        }
    }

    return configs;
}

// Example of freeing the allocated memory
void free_config_collection(config* configs, size_t count) {
    if (configs == NULL) return;

    for (size_t i = 0; i < count; ++i) {
        free(configs[i].configurationName);
    }

    aligned_free(configs);
}
