#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct ResourceRequest {
    char id[32];
    int priority;
    int status; // 0: pending, 1: active, 2: evicted
    time_t timeout;
} ResourceRequest;

#define MAX_REQUESTS 1024

typedef struct Node {
    ResourceRequest request;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RequestPool;

// Comparator for priority and expiration policy (for demonstration)
int compareRequests(const void* a, const void* b) {
    const ResourceRequest* reqA = (const ResourceRequest*)a;
    const ResourceRequest* reqB = (const ResourceRequest*)b;

    if (reqA->priority != reqB->priority)
        return reqB->priority - reqA->priority; // Higher priority first
    return (int)(reqA->timeout - reqB->timeout); // Older timeout first
}

// Initialize the request pool
void initRequestPool(RequestPool* pool) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

// Add a new resource request to the pool
void addResourceRequest(RequestPool* pool, ResourceRequest request) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for request");
        return;
    }
    memcpy(&newNode->request, &request, sizeof(ResourceRequest));
    newNode->next = NULL;

    pthread_mutex_lock(&pool->lock);

    // Insert into list maintaining priority order
    Node** current = &(pool->head);
    while (*current && compareRequests(&(*current)->request.request, &request) < 0) {
        current = &((*current)->next);
    }
    newNode->next = *current;
    *current = newNode;

    pthread_mutex_unlock(&pool->lock);
}

// Retrieve a request by ID
ResourceRequest* getResourceById(RequestPool* pool, const char* id) {
    Node* node = NULL;

    pthread_mutex_lock(&pool->lock);

    for (node = pool->head; node != NULL; node = node->next) {
        if (strcmp(node->request.id, id) == 0 && node->request.status != 2) { // Not evicted
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);

    return (node ? &node->request : NULL);
}

// Update a request's status or priority by ID
int updateResourceRequest(RequestPool* pool, const char* id, int newPriority, int newStatus) {
    Node* node = NULL;

    pthread_mutex_lock(&pool->lock);

    for (node = pool->head; node != NULL; node = node->next) {
        if (strcmp(node->request.id, id) == 0 && node->request.status != 2) { // Not evicted
            node->request.priority = newPriority;
            node->request.status = newStatus;

            pthread_mutex_unlock(&pool->lock);

            return 1; // Success
        }
    }

    pthread_mutex_unlock(&pool->lock);

    return 0; // Not found or already evicted
}

// Evict stale requests based on expiration policy
void evictStaleRequests(RequestPool* pool) {
    Node* node = NULL;
    Node* prev = NULL;

    pthread_mutex_lock(&pool->lock);

    time_t now = time(NULL);

    for (node = pool->head; node != NULL;) {
        if (node->request.status == 0 && node->request.timeout < now) { // Pending and expired
            Node* toDelete = node;
            node = node->next;

            prev ? (prev->next = node) : (pool->head = node);

            free(toDelete);
        } else {
            prev = node;
            node = node->next;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Cleanup resources
void cleanupRequestPool(RequestPool* pool) {
    Node* current = pool->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&pool->lock);
}

int main() {
    RequestPool requestPool;
    initRequestPool(&requestPool);

    // Example usage
    ResourceRequest req1 = {.id = "req1", .priority = 5, .status = 0, .timeout = time(NULL) + 10};
    addResourceRequest(&requestPool, req1);

    evictStaleRequests(&requestPool);

    ResourceRequest* foundReq = getResourceById(&requestPool, "req1");
    if (foundReq)
        printf("Found request: %s\n", foundReq->id);

    updateResourceRequest(&requestPool, "req1", 10, 1);

    cleanupRequestPool(&requestPool);

    return 0;
}
