#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h> // JSON handling library
#include <curl/curl.h>

#define MAX_PROFILES 1000

typedef struct {
    char *name;
    char *email;
    json_t *preferences; // Using Jansson for JSON operations
} UserProfile;

typedef struct {
    int user_count;
    UserProfile **profiles;
    pthread_rwlock_t lock;
} ProfileManager;

// Function prototypes
void init_profile_manager(ProfileManager *manager);
void destroy_profile_manager(ProfileManager *manager);
int add_user_profile(ProfileManager *manager, const char *user_id, const char *name, const char *email, json_t *preferences);
UserProfile* get_user_profile(const ProfileManager *manager, const char *user_id);
int update_user_profile(ProfileManager *manager, const char *user_id, const char *name, const char *email, json_t *preferences);
int delete_user_profile(ProfileManager *manager, const char *user_id);

// Web API function prototypes
void handle_get_request(const char *user_id);
void handle_put_request(const char *user_id, const char *name, const char *email, const char *json_preferences);

// Helper functions for JSON and memory management
static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata);
static json_error_t parse_json_string(const char *str, json_t **json);

// Initialization function
void init_profile_manager(ProfileManager *manager) {
    pthread_rwlock_init(&manager->lock, NULL);
    manager->user_count = 0;
    manager->profiles = (UserProfile **)calloc(MAX_PROFILES, sizeof(UserProfile *));
}

// Destruction function
void destroy_profile_manager(ProfileManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);
    for (int i = 0; i < manager->user_count; i++) {
        if (manager->profiles[i]) {
            free(manager->profiles[i]->name);
            free(manager->profiles[i]->email);
            json_decref(manager->profiles[i]->preferences);
            free(manager->profiles[i]);
        }
    }
    free(manager->profiles);
    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

// Add a user profile
int add_user_profile(ProfileManager *manager, const char *user_id, const char *name, const char *email, json_t *preferences) {
    pthread_rwlock_wrlock(&manager->lock);

    if (manager->user_count >= MAX_PROFILES) {
        printf("Error: Maximum profile count exceeded.\n");
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    for (int i = 0; i < manager->user_count; i++) {
        if (strcmp(manager->profiles[i]->name, user_id) == 0) {
            printf("Error: Duplicate user ID.\n");
            pthread_rwlock_unlock(&manager->lock);
            return -1;
        }
    }

    UserProfile *profile = (UserProfile *)malloc(sizeof(UserProfile));
    profile->name = strdup(name);
    profile->email = strdup(email);
    profile->preferences = json_incref(preferences);

    manager->profiles[manager->user_count++] = profile;

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

// Get a user profile
UserProfile* get_user_profile(const ProfileManager *manager, const char *user_id) {
    pthread_rwlock_rdlock(&manager->lock);

    for (int i = 0; i < manager->user_count; i++) {
        if (strcmp(manager->profiles[i]->name, user_id) == 0) {
            UserProfile *profile = malloc(sizeof(UserProfile));
            memcpy(profile, manager->profiles[i], sizeof(UserProfile));
            pthread_rwlock_unlock(&manager->lock);
            return profile;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
    return NULL;
}

// Update a user profile
int update_user_profile(ProfileManager *manager, const char *user_id, const char *name, const char *email, json_t *preferences) {
    pthread_rwlock_wrlock(&manager->lock);

    for (int i = 0; i < manager->user_count; i++) {
        if (strcmp(manager->profiles[i]->name, user_id) == 0) {
            free(manager->profiles[i]->name);
            free(manager->profiles[i]->email);
            json_decref(manager->profiles[i]->preferences);

            manager->profiles[i]->name = strdup(name);
            manager->profiles[i]->email = strdup(email);
            manager->profiles[i]->preferences = json_incref(preferences);

            pthread_rwlock_unlock(&manager->lock);
            return 0;
        }
    }

    printf("Error: User profile not found.\n");
    pthread_rwlock_unlock(&manager->lock);
    return -1;
}

// Delete a user profile
int delete_user_profile(ProfileManager *manager, const char *user_id) {
    pthread_rwlock_wrlock(&manager->lock);

    for (int i = 0; i < manager->user_count; i++) {
        if (strcmp(manager->profiles[i]->name, user_id) == 0) {
            free(manager->profiles[i]->name);
            free(manager->profiles[i]->email);
            json_decref(manager->profiles[i]->preferences);
            free(manager->profiles[i]);

            manager->profiles[i] = manager->profiles[--manager->user_count];
            pthread_rwlock_unlock(&manager->lock);
            return 0;
        }
    }

    printf("Error: User profile not found.\n");
    pthread_rwlock_unlock(&manager->lock);
    return -1;
}

// Web API function to handle GET request
void handle_get_request(const char *user_id) {
    // Simulate retrieving user profile
    UserProfile *profile = get_user_profile(/* manager */, user_id);
    if (profile) {
        printf("User Profile: Name=%s, Email=%s\n", profile->name, profile->email);
        json_t *preferences_str;
        char *serialized = json_dumps(profile->preferences, JSON_INDENT(2));
        preferences_str = json_loads(serialized, 0, NULL);
        printf("Preferences: %s\n", json_dumps(preferences_str, 0));
        free(serialized);
        json_decref(preferences_str);
        free(profile->name);
        free(profile->email);
        json_decref(profile->preferences);
        free(profile);
    } else {
        printf("User profile not found.\n");
    }
}

// Web API function to handle PUT request
void handle_put_request(const char *user_id, const char *name, const char *email, const char *json_preferences) {
    json_error_t error;
    json_t *preferences = parse_json_string(json_preferences, &error);
    if (!preferences) {
        printf("Error parsing JSON: %s\n", error.text);
        return;
    }

    int result = update_user_profile(/* manager */, user_id, name, email, preferences);
    json_decref(preferences);

    if (result == 0) {
        printf("User profile updated successfully.\n");
    } else {
        printf("Failed to update user profile.\n");
    }
}

// JSON parsing helper
static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return fwrite(ptr, size, nmemb, (FILE *)userdata);
}

static json_error_t parse_json_string(const char *str, json_t **json) {
    return json_loads(str, 0, json);
}
