#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
    time_t timestamp;
} record;

static unsigned long total_records = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize arrays
void* allocate_and_initialize_arrays(size_t size) {
    if (size <= 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        return NULL;
    }

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets); 
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(record);
        keys[i] = rand() % 1000;
    }

    // Populate records with random data
    srand((unsigned int)time(NULL));
    char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    for (size_t i = 0; i < size && total_records < size; ++i) {
        pthread_mutex_lock(&lock);
        if (total_records >= size) {
            pthread_mutex_unlock(&lock);
            break;
        }
        records[i].value = rand() % 1000;
        int buffer_length = rand() % BUFFER_SIZE;
        for (int j = 0; j < buffer_length; ++j) {
            records[i].buffer[j] = charset[rand() % (sizeof(charset) - 1)];
        }
        records[i].buffer[buffer_length] = '\0';
        records[i].timestamp = time(NULL);

        // Log the insertion
        printf("Record inserted: value=%d, timestamp=%ld\n", records[i].value, records[i].timestamp);

        total_records++;
        pthread_mutex_unlock(&lock);
    }

    return malloc(sizeof(long*) * 3 + sizeof(int*) * 1 + sizeof(record*) * 1);
}

// Serialize data to a file
int serialize_data(const char *filename, long* offsets, int* keys, record* records, size_t size) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file for writing.\n");
        return -1;
    }

    // Write version
    unsigned char version = 1;
    fwrite(&version, sizeof(version), 1, file);

    // Write size
    fwrite(&size, sizeof(size), 1, file);

    // Write offsets, keys, and records
    fwrite(offsets, sizeof(long), size, file);
    fwrite(keys, sizeof(int), size, file);
    for (size_t i = 0; i < size; ++i) {
        fwrite(&(records[i]), sizeof(record), 1, file);
    }

    fclose(file);
    return 0;
}

// Deserialize data from a file
int deserialize_data(const char *filename, long** offsets, int** keys, record** records, size_t* size) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file for reading.\n");
        return -1;
    }

    unsigned char version;
    fread(&version, sizeof(version), 1, file);
    if (version != 1) {
        fprintf(stderr, "Error: Unsupported serialization format.\n");
        fclose(file);
        return -1;
    }

    // Read size
    fread(size, sizeof(*size), 1, file);

    // Allocate memory
    *offsets = malloc(*size * sizeof(long));
    *keys = malloc(*size * sizeof(int));
    *records = malloc(*size * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Error: Memory allocation failed during deserialization.\n");
        free(*offsets); 
        free(*keys);
        free(*records);
        fclose(file);
        return -1;
    }

    // Read offsets, keys, and records
    fread(*offsets, sizeof(long), *size, file);
    fread(*keys, sizeof(int), *size, file);
    for (size_t i = 0; i < *size; ++i) {
        fread(&((*records)[i]), sizeof(record), 1, file);
    }

    fclose(file);
    return 0;
}

// Cleanup old records
void cleanup_old_records(double grace_period_seconds) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&lock);
    for (unsigned long i = 0; i < total_records;) {
        if (difftime(current_time, ((record*)data)[i].timestamp) > grace_period_seconds) {
            memmove(((long*)data)[i], ((long*)data)[i + 1], (total_records - i - 1) * sizeof(long));
            memmove(((int*)data)[i], ((int*)data)[i + 1], (total_records - i - 1) * sizeof(int));
            memmove(((record*)data)[i], ((record*)data)[i + 1], (total_records - i - 1) * sizeof(record));

            total_records--;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    size_t size = 1000; // Example size
    void* data = allocate_and_initialize_arrays(size);

    if (data) {
        long* offsets = (long*)data;
        int* keys = (int*)(offsets + size);
        record* records = (record*)(keys + size);

        const char *filename = "data.bin";
        if (serialize_data(filename, offsets, keys, records, size) == 0) {
            printf("Data serialized successfully.\n");
        }

        long* deserialized_offsets;
        int* deserialized_keys;
        record* deserialized_records;
        size_t deserialized_size;

        if (deserialize_data(filename, &deserialized_offsets, &deserialized_keys, &deserialized_records, &deserialized_size) == 0) {
            printf("Data deserialized successfully.\n");
        }

        cleanup_old_records(3600.0); // Grace period of 1 hour
    }

    return 0;
}
