```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define EXPIRATION_THRESHOLD_SECONDS 300

typedef struct {
    int id;
    time_t timestamp;
    char status_flag;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t count;
    time_t expiration_threshold;
    FILE *log_file;
    pthread_t purge_thread;
    int max_packets;
} PacketManager;

void log_event(PacketManager *manager, const char *event) {
    if (manager->log_file) {
        fprintf(manager->log_file, "%s\n", event);
        fflush(manager->log_file);
    }
}

PacketManager* init_packet_manager(size_t max_packets, time_t expiration_threshold) {
    PacketManager *manager = malloc(sizeof(PacketManager));
    memset(manager, 0, sizeof(PacketManager));

    manager->max_packets = max_packets;
    manager->expiration_threshold = expiration_threshold;

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        manager->packets[i] = NULL;
    }

    manager->log_file = fopen("packet_log.txt", "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    pthread_create(&manager->purge_thread, NULL, purge_expired_packets, (void*)manager);

    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    if (pthread_join(manager->purge_thread, NULL)) {
        perror("Failed to join purge thread");
    }
    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        free(manager->packets[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    fclose(manager->log_file);
    free(manager);
}

void add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);

    while (manager->count >= manager->max_packets) {
        pthread_cond_wait(&manager->cond, &manager->lock);
    }

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i);

    if (i == MAX_PACKETS) return;

    manager->packets[i] = packet;
    manager->count++;
    log_event(manager, "Packet added");

    pthread_cond_broadcast(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
}

void update_packet(PacketManager *manager, int id, char new_status) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        if (manager->packets[i]->id == id) {
            manager->packets[i]->status_flag = new_status;
            log_event(manager, "Packet updated");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

DataPacket* get_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        if (manager->packets[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->packets[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void purge_expired_packets(PacketManager *manager) {
    while (1) {
        pthread_mutex_lock(&manager->lock);

        time_t now = time(NULL);
        for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
            if (difftime(now, manager->packets[i]->timestamp) > manager->expiration_threshold) {
                DataPacket *expired_packet = manager->packets[i];
                manager->packets[i] = NULL;
                manager->count--;
                free(expired_packet);
                log_event(manager, "Expired packet purged");
            }
        }

        pthread_cond_broadcast(&manager->cond);
        pthread_mutex_unlock(&manager->lock);

        sleep(60); // Run every minute
    }
}

void save_packets_to_file(PacketManager *manager, const char* filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for saving packets");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i) {
        fprintf(file, "%d,%ld,%c\n", manager->packets[i]->id,
                manager->packets[i]->timestamp,
                manager->packets[i]->status_flag);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void load_packets_from_file(PacketManager *manager, const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for loading packets");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    int id;
    time_t timestamp;
    char status_flag;

    while (fscanf(file, "%d,%ld,%c\n", &id, &timestamp, &status_flag) == 3) {
        DataPacket *packet = malloc(sizeof(DataPacket));
        packet->id = id;
        packet->timestamp = timestamp;
        packet->status_flag = status_flag;

        for (size_t i = 0; i < MAX_PACKETS && manager->packets[i]; ++i);

        if (i == MAX_PACKETS) {
            free(packet);
        } else {
            manager->packets[i] = packet;
            manager->count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

int main() {
    PacketManager *manager = init_packet_manager(MAX_PACKETS, EXPIRATION_THRESHOLD_SECONDS);

    // Example usage:
    DataPacket *packet1 = malloc(sizeof(DataPacket));
    packet1->id = 1;
    packet1->timestamp = time(NULL);
    packet1->status_flag = 'A';

    add_packet(manager, packet1);

    save_packets_to_file(manager, "packets_backup.txt");
    load_packets_from_file(manager, "packets_backup.txt");

    destroy_packet_manager(manager);

    return 0;
}
