#include <string.h>
#include <time.h>

#define MAX_CONFIG_LINE_LENGTH 256

typedef struct {
    int priority;
    char status;
    char *command_line_arg;
} Task;

int parse_config_file(const char *filename, int *max_tasks, char ***patterns) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[MAX_CONFIG_LINE_LENGTH];
    int max_tasks_count = 0;
    char **patterns_list = NULL;

    while (fgets(line, sizeof(line), file)) {
        line[strcspn(line, "\n")] = '\0'; // Remove newline character
        if (max_tasks_count == 0) {
            *max_tasks = atoi(line);
        } else {
            patterns_list = realloc(patterns_list, sizeof(char *) * (max_tasks_count + 1));
            patterns_list[max_tasks_count] = strdup(line);
            max_tasks_count++;
        }
    }

    fclose(file);

    if (*max_tasks <= 0 || max_tasks_count < 1) return -2;

    *patterns = patterns_list;
    return 0;
}

char* generate_command_line_arg(const char **patterns, int pattern_count, int len_min, int len_max) {
    const char *pattern = patterns[rand() % pattern_count];
    int length = rand() % (len_max - len_min + 1) + len_min;

    char *command = malloc(length + 1);
    if (!command) return NULL;

    for (int i = 0; i < length && pattern[i] != '\0'; ++i) {
        command[i] = pattern[rand() % strlen(pattern)];
    }
    command[length] = '\0';

    return command;
}

void free_tasks(Task *tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; ++i) {
        free(tasks[i].command_line_arg);
    }
    free(tasks);
}

Task* initialize_tasks(const char *config_file, int *error_flag) {
    srand(time(NULL));

    int max_tasks;
    char **patterns;

    if (parse_config_file(config_file, &max_tasks, &patterns)) {
        *error_flag = 1;
        return NULL;
    }

    Task *tasks = malloc(max_tasks * sizeof(Task));
    if (!tasks) {
        free(patterns);
        *error_flag = 1;
        return NULL;
    }

    for (int i = 0; i < max_tasks; ++i) {
        tasks[i].priority = i + 1;

        int status = rand() % 2;
        tasks[i].status = (status == 0) ? 'R' : 'P';

        tasks[i].command_line_arg = generate_command_line_arg(patterns, max_tasks, 10, 50);
        if (!tasks[i].command_line_arg) {
            free_tasks(tasks, i);
            free(patterns);
            *error_flag = 1;
            return NULL;
        }
    }

    free(patterns);
    *error_flag = 0;

    return tasks;
}

void cleanup_and_free(Task *tasks, int max_tasks, int error_flag) {
    if (error_flag) {
        free_tasks(tasks, max_tasks);
    }
}
