#define MAX_CONFIGS 10000

typedef struct {
    char mac[18];
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

typedef struct {
    NetworkConfig *configs;
    int count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void log_operation(const char *message) {
    printf("LOG: %s\n", message);
}

int mac_is_unique(const char *mac) {
    for (int i = 0; i < manager.count; ++i) {
        if (strcmp(manager.configs[i].mac, mac) == 0) {
            return 0;
        }
    }
    return 1;
}

void validate_and_insert_config(NetworkConfig new_config) {
    pthread_mutex_lock(&manager.lock);

    if (manager.count >= MAX_CONFIGS) {
        log_operation("Maximum configuration count exceeded.");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    if (!mac_is_unique(new_config.mac)) {
        log_operation("Duplicate MAC address found.");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    manager.configs = realloc(manager.configs, (manager.count + 1) * sizeof(NetworkConfig));
    if (!manager.configs) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&manager.lock);
        exit(EXIT_FAILURE);
    }

    memcpy(&manager.configs[manager.count], &new_config, sizeof(NetworkConfig));
    manager.count++;
    log_operation("New configuration added.");

    pthread_mutex_unlock(&manager.lock);
}

void serialize_to_file(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&manager.lock);

    fwrite(&manager.count, sizeof(int), 1, file);
    fwrite(manager.configs, sizeof(NetworkConfig), manager.count, file);

    pthread_mutex_unlock(&manager.lock);

    fclose(file);
    log_operation("Data serialized to file.");
}

void deserialize_from_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    int new_count;
    fread(&new_count, sizeof(int), 1, file);

    manager.configs = realloc(manager.configs, new_count * sizeof(NetworkConfig));
    if (!manager.configs) {
        perror("Memory allocation failed");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&manager.lock);

    fread(manager.configs, sizeof(NetworkConfig), new_count, file);
    manager.count = new_count;

    pthread_mutex_unlock(&manager.lock);

    fclose(file);
    log_operation("Data deserialized from file.");
}

int ping_host(const char *interface, const char *host) {
    int sockfd;
    struct sockaddr_in dest_addr;
    struct pollfd fds[1];
    struct timeval tv;
    char buffer[1024];

    if ((sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP)) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    inet_pton(AF_INET, host, &dest_addr.sin_addr);

    memset(buffer, 0, sizeof(buffer));

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    fds[0].fd = sockfd;
    fds[0].events = POLLIN;

    if (poll(fds, 1, 2000) > 0) {
        ssize_t len = recv(sockfd, buffer, sizeof(buffer), 0);
        log_operation("Ping successful.");
        close(sockfd);
        return len;
    }

    log_operation("Ping failed or timed out.");
    close(sockfd);
    return -1;
}

void health_check(const char *interface, const char *host) {
    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < manager.count; ++i) {
        if (strcmp(manager.configs[i].ip, interface) == 0) {
            int result = ping_host(interface, host);
            log_operation("Health check completed.");
            break;
        }
    }

    pthread_mutex_unlock(&manager.lock);
}

void cleanup() {
    free(manager.configs);
    manager.count = 0;
    log_operation("Resources cleaned up.");
}
