#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_USERNAME_LENGTH 512
#define MAX_EMAIL_LENGTH 256
#define MAX_ROLES_PER_USER 10
#define MAX_USERS 10000

typedef struct {
    char username[MAX_USERNAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    char roles[MAX_ROLES_PER_USER][MAX_USERNAME_LENGTH];
    int role_count;
} UserAccount;

typedef struct {
    UserAccount *users;
    size_t user_count;
    pthread_mutex_t lock;
} UserManager;

UserManager* initialize_user_manager() {
    UserManager *manager = malloc(sizeof(UserManager));
    if (!manager) return NULL;

    manager->users = calloc(MAX_USERS, sizeof(UserAccount));
    if (!manager->users) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->user_count = 0;

    return manager;
}

int add_user_account(UserManager *manager, const char *username, const char *email) {
    if (strlen(username) >= MAX_USERNAME_LENGTH || strlen(email) >= MAX_EMAIL_LENGTH)
        return -1; // Invalid input

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->user_count; ++i) {
        if (strcmp(manager->users[i].username, username) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate username
        }
    }

    if (manager->user_count >= MAX_USERS) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // User count exceeded
    }

    strcpy(manager->users[manager->user_count].username, username);
    strcpy(manager->users[manager->user_count].email, email);
    manager->users[manager->user_count].role_count = 0;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int update_user_role(UserManager *manager, const char *username, const char *role) {
    if (strlen(role) >= MAX_USERNAME_LENGTH)
        return -1; // Invalid role length

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->user_count; ++i) {
        if (strcmp(manager->users[i].username, username) == 0) {
            if (manager->users[i].role_count >= MAX_ROLES_PER_USER) {
                pthread_mutex_unlock(&manager->lock);
                return -2; // Role count exceeded
            }

            strcpy(manager->users[i].roles[manager->users[i].role_count], role);
            manager->users[i].role_count++;

            // Notify user of role update (pseudo-code)
            // send_notification(username, "Role updated: " + role);

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -3; // User not found
}

int serialize_user_manager(const UserManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return -1;

    size_t written_bytes = fwrite(manager->users, sizeof(UserAccount), manager->user_count, file);

    fclose(file);

    return (written_bytes == manager->user_count) ? 0 : -2;
}

int deserialize_user_manager(UserManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file)
        return -1;

    size_t read_bytes = fread(manager->users, sizeof(UserAccount), MAX_USERS, file);

    fclose(file);

    manager->user_count = (read_bytes == MAX_USERS || feof(file)) ? read_bytes : -2;
    return 0;
}

void cleanup_user_manager(UserManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->users);
    free(manager);
}
