#include <stdbool.h>
#include <zlib.h> // For optional compression

// Define structures
typedef struct {
    float score;
    bool active;
    char *buffer;  // Dynamically allocated
} Detail;

typedef struct {
    char identifier;
    double value;
    Detail *detail; // Pointer to dynamically allocated detail
} Item;

// Configuration structure
typedef struct {
    int item_count;
    double range_min;
    double range_max;
    int buffer_length;
    bool use_compression;
} Config;

// Global variables for logging and synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
bool error_flag = false;

// Function prototypes
void *initialize_items(void *arg);
void deallocate_items(Item **items, size_t count);
void log_message(const char *message);

// Configuration management function (simulated)
Config load_config() {
    Config config = {10, 0.0, 100.0, 50, true}; // Example configuration
    return config;
}

// Utility functions
double random_double(double min, double max) {
    double range = (max - min);
    double div = RAND_MAX / range;
    return min + (rand() / div);
}

bool probabilistic_active() {
    return rand() % 2 == 0; // 50% chance to be true
}

char random_alphanumeric_char() {
    const char *charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    return charset[rand() % strlen(charset)];
}

// Compression and decompression utility functions
size_t compress_buffer(const char *input, size_t input_size, unsigned char **output) {
    uLongf compressed_size = compressBound(input_size);
    *output = (unsigned char *)malloc(compressed_size);

    if (!*output || compress(*output, &compressed_size, (const Bytef *)input, input_size) != Z_OK) {
        log_message("Compression failed.");
        free(*output);
        return 0;
    }

    return compressed_size;
}

size_t decompress_buffer(const unsigned char *input, size_t input_size, char **output, size_t original_size) {
    *output = (char *)malloc(original_size);

    if (!*output || uncompress((Bytef *)*output, &original_size, input, input_size) != Z_OK) {
        log_message("Decompression failed.");
        free(*output);
        return 0;
    }

    return original_size;
}

// Main function to initialize items
void *initialize_items(void *arg) {
    Config config = load_config();
    Item **items = (Item **)arg;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < config.item_count && !error_flag; ++i) {
        *items = realloc(*items, sizeof(Item) * (i + 1));
        if (!*items) {
            log_message("Memory allocation failed.");
            error_flag = true;
            break;
        }

        (*items)[i].identifier = 'A' + i;
        (*items)[i].value = random_double(config.range_min, config.range_max);

        Detail *detail = malloc(sizeof(Detail));
        if (!detail) {
            log_message("Memory allocation for detail failed.");
            error_flag = true;
            break;
        }

        (*items)[i].detail = detail;
        detail->score = (float)(rand() % 1000 / 10.0);
        detail->active = probabilistic_active();

        char *buffer = malloc(config.buffer_length);
        if (!buffer) {
            log_message("Memory allocation for buffer failed.");
            error_flag = true;
            break;
        }

        for (int j = 0; j < config.buffer_length; ++j) {
            buffer[j] = random_alphanumeric_char();
        }

        unsigned char *compressed_buffer = NULL;
        if (config.use_compression) {
            size_t compressed_size = compress_buffer(buffer, config.buffer_length, &compressed_buffer);
            free(buffer);

            if (!compressed_buffer || compressed_size == 0) {
                error_flag = true;
                break;
            }

            detail->buffer = (char *)compressed_buffer; // Storing as char pointer for simplicity
        } else {
            detail->buffer = buffer;
        }
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to deallocate items
void deallocate_items(Item **items, size_t count) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        if ((*items)[i].detail->buffer && !((*items)[i].detail->buffer == (char *)malloc(0))) { // Check against empty buffer
            free((*items)[i].detail->buffer);
        }
        free((*items)[i].detail);
    }

    free(*items);
    pthread_mutex_unlock(&mutex);

    log_message("Deallocated all items successfully.");
}

// Logging function
void log_message(const char *message) {
    // Simple logging mechanism (could integrate with a logging library)
    printf("%s\n", message);
}
```

### Notes:
- This implementation assumes the use of zlib for optional compression.
- The `initialize_items` and `deallocate_items` functions are designed to handle synchronization using mutexes, ensuring thread safety during memory operations.
- Error handling is done through setting an `error_flag`, which helps break out of loops in case of allocation failures.
- Configuration values such as item count and buffer length can be easily modified by changing the `load_config()` function.
- The logging mechanism here uses simple `printf` statements; for more robust logging, consider integrating with a dedicated logging library.']

