#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_CONNECTIONS 100
#define BUFFER_SIZE 1024

typedef struct {
    int priority;
    char host_info[BUFFER_SIZE];
    char *buffer_ptr;
} ConnectionMetadata;

typedef struct {
    int socket_descriptors[MAX_CONNECTIONS];
    ConnectionMetadata connection_metadata[MAX_CONNECTIONS];
    char *buffers[MAX_CONNECTIONS]; // Pointers to buffers for storing connection details
    size_t count; // Current number of connections managed
} NetworkConnectionManager;

// Function prototypes
int establish_connection(int sock, const struct sockaddr_in *addr, int timeout);
void update_priority(ConnectionMetadata *meta);
int serialize_data(const NetworkConnectionManager *manager, const char *filename);
int deserialize_data(NetworkConnectionManager *manager, const char *filename);

NetworkConnectionManager* init_network_manager() {
    NetworkConnectionManager *manager = (NetworkConnectionManager *)malloc(sizeof(NetworkConnectionManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for network manager\n");
        return NULL;
    }

    manager->count = 0;

    // Allocate and initialize buffers
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        manager->buffers[i] = (char *)malloc(BUFFER_SIZE);
        if (!manager->buffers[i]) {
            fprintf(stderr, "Memory allocation failed for buffer at index %zu\n", i);
            // Free all previously allocated buffers
            while (i > 0) free(manager->buffers[--i]);
            free(manager);
            return NULL;
        }
        memset(manager->buffers[i], 0, BUFFER_SIZE);
    }

    return manager;
}

void cleanup_network_manager(NetworkConnectionManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        close(manager->socket_descriptors[i]);
        free(manager->connection_metadata[i].buffer_ptr);
    }

    // Free buffers
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        free(manager->buffers[i]);
    }

    free(manager);
}

int add_connection(NetworkConnectionManager *manager, int sock, const struct sockaddr_in *addr) {
    if (manager->count >= MAX_CONNECTIONS) {
        fprintf(stderr, "Maximum connection limit reached\n");
        return -1;
    }

    // Establish a network connection
    int timeout = 5; // seconds
    if (!establish_connection(sock, addr, timeout)) {
        fprintf(stderr, "Failed to establish connection on socket %d\n", sock);
        return -1;
    }

    manager->socket_descriptors[manager->count] = sock;

    ConnectionMetadata meta;
    strcpy(meta.host_info, inet_ntoa(addr->sin_addr));
    meta.buffer_ptr = malloc(BUFFER_SIZE);
    if (!meta.buffer_ptr) {
        fprintf(stderr, "Memory allocation failed for connection metadata buffer\n");
        close(sock);
        return -1;
    }

    update_priority(&meta);

    manager->connection_metadata[manager->count] = meta;
    memcpy(manager->buffers[manager->count], "Connection Details", BUFFER_SIZE);

    ++manager->count;

    return 0;
}

int establish_connection(int sock, const struct sockaddr_in *addr, int timeout) {
    // Set socket options for non-blocking mode
    int flags = fcntl(sock, F_GETFL);
    if (flags == -1 || fcntl(sock, F_SETFL, flags | O_NONBLOCK) == -1) {
        perror("Failed to set non-blocking mode");
        return 0;
    }

    // Set timeout using select() or similar approach
    struct timeval tv = { .tv_sec = timeout, .tv_usec = 0 };
    fd_set write_fds;
    FD_ZERO(&write_fds);
    FD_SET(sock, &write_fds);

    if (select(sock + 1, NULL, &write_fds, NULL, &tv) > 0) {
        // Connection established
        return 1;
    } else {
        // Timeout or error occurred
        return 0;
    }
}

void update_priority(ConnectionMetadata *meta) {
    // Example logic to determine priority based on some conditions
    meta->priority = rand() % 10; // Randomly set for demonstration
}

int serialize_data(const NetworkConnectionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    fwrite(&manager->count, sizeof(manager->count), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(&manager->socket_descriptors[i], sizeof(int), 1, file);
        fwrite(&manager->connection_metadata[i], sizeof(ConnectionMetadata), 1, file);
        fwrite(manager->buffers[i], BUFFER_SIZE, 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_data(NetworkConnectionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fread(&manager->count, sizeof(manager->count), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fread(&manager->socket_descriptors[i], sizeof(int), 1, file);
        fread(&manager->connection_metadata[i], sizeof(ConnectionMetadata), 1, file);
        fread(manager->buffers[i], BUFFER_SIZE, 1, file);
    }

    fclose(file);
    return 0;
}

int main() {
    NetworkConnectionManager *manager = init_network_manager();
    if (!manager) return EXIT_FAILURE;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    addr.sin_port = htons(8080);

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to create a socket");
        cleanup_network_manager(manager);
        return EXIT_FAILURE;
    }

    if (add_connection(manager, sock, &addr) != 0) {
        cleanup_network_manager(manager);
        return EXIT_FAILURE;
    }

    // Serialize and deserialize example
    if (serialize_data(manager, "connections.dat") != 0 || 
        deserialize_data(manager, "connections.dat") != 0) {
        fprintf(stderr, "Serialization or deserialization failed\n");
    }

    cleanup_network_manager(manager);

    return EXIT_SUCCESS;
}
```

This code provides a framework for managing network connections within specified constraints and offers mechanisms to serialize/deserialize connection data. It includes basic error handling and prioritization logic as required by the task.']

