#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    char type[50];
    time_t timestamp;
    double consumption_level;
} ResourceUnit;

typedef struct {
    ResourceUnit *units;
    size_t capacity;
    size_t count;
    double max_consumption_limit;
    double alert_threshold;
} ResourceManager;

ResourceManager* create_resource_manager(size_t initial_capacity, double max_consumption_limit, double alert_threshold) {
    ResourceManager *rm = malloc(sizeof(ResourceManager));
    rm->units = calloc(initial_capacity, sizeof(ResourceUnit));
    rm->capacity = initial_capacity;
    rm->count = 0;
    rm->max_consumption_limit = max_consumption_limit;
    rm->alert_threshold = alert_threshold;
    return rm;
}

void free_resource_manager(ResourceManager *rm) {
    free(rm->units);
    free(rm);
}

int find_unit_index(ResourceManager *rm, int id) {
    for (size_t i = 0; i < rm->count; ++i) {
        if (rm->units[i].id == id) return i;
    }
    return -1;
}

void resize_resource_manager(ResourceManager *rm, size_t new_capacity) {
    ResourceUnit *new_units = realloc(rm->units, new_capacity * sizeof(ResourceUnit));
    if (new_units) {
        rm->units = new_units;
        rm->capacity = new_capacity;
    }
}

void add_or_update_unit(ResourceManager *rm, int id, const char *type, double consumption_level) {
    time_t current_time = time(NULL);
    int index = find_unit_index(rm, id);

    if (index == -1) { // Add new unit
        if (rm->count >= rm->capacity) resize_resource_manager(rm, rm->capacity * 2);
        rm->units[rm->count].id = id;
        strcpy(rm->units[rm->count].type, type);
        rm->units[rm->count].timestamp = current_time;
        rm->units[rm->count++].consumption_level = consumption_level;
    } else { // Update existing unit
        rm->units[index].type[0] = '\0'; // Clear type to allow strcpy safely
        strcpy(rm->units[index].type, type);
        rm->units[index].timestamp = current_time;
        rm->units[index].consumption_level = consumption_level;
    }

    double total_consumption = 0;
    for (size_t i = 0; i < rm->count; ++i) {
        total_consumption += rm->units[i].consumption_level;
    }

    if (total_consumption > rm->max_consumption_limit) {
        printf("Alert: Total consumption exceeded limit!\n");
    } else if (total_consumption > rm->alert_threshold) {
        printf("Warning: Approaching consumption threshold.\n");
    }
}

ResourceUnit* get_unit_by_id(ResourceManager *rm, int id) {
    int index = find_unit_index(rm, id);
    return index != -1 ? &rm->units[index] : NULL;
}

void set_limits(ResourceManager *rm, double max_consumption_limit, double alert_threshold) {
    rm->max_consumption_limit = max_consumption_limit;
    rm->alert_threshold = alert_threshold;
}

void generate_report(const ResourceManager *rm, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "ID,Type,Timestamp,Consumption Level\n");
    for (size_t i = 0; i < rm->count; ++i) {
        fprintf(file, "%d,%s,%ld,%f\n", 
                rm->units[i].id, 
                rm->units[i].type,
                rm->units[i].timestamp, 
                rm->units[i].consumption_level);
    }

    fclose(file);
}

int main() {
    ResourceManager *rm = create_resource_manager(10, 100.0, 80.0);

    add_or_update_unit(rm, 1, "CPU", 30.5);
    add_or_update_unit(rm, 2, "Memory", 20.7);

    ResourceUnit *unit = get_unit_by_id(rm, 1);
    if (unit) {
        printf("Retrieved Unit: ID=%d Type=%s\n", unit->id, unit->type);
    }

    set_limits(rm, 150.0, 120.0);

    generate_report(rm, "resource_report.csv");

    free_resource_manager(rm);

    return 0;
}
