#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_arrays(size_t num_sets, size_t records_per_set, int key_min, int key_max, int log_fd) {
    if (num_sets == 0 || records_per_set == 0) return;

    long *offsets = malloc(num_sets * sizeof(long));
    int *keys = malloc(num_sets * records_per_set * sizeof(int));
    record **records = malloc(num_sets * sizeof(record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_sets; ++i) {
        records[i] = malloc(records_per_set * sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        int key_range = key_max - key_min + 1;
        unsigned int *key_attempts = calloc(key_range, sizeof(unsigned int));

        for (size_t j = 0; j < records_per_set; ++j) {
            int key;
            do {
                key = rand() % key_range + key_min;
                if (key_attempts[key - key_min] == 0) break;
            } while (1);

            keys[i * records_per_set + j] = key;
            key_attempts[key - key_min]++;
            records[i][j].value = rand(); // Assign a random int to record
        }

        if (log_fd != -1) {
            for (size_t k = 0; k < key_range; ++k) {
                if (key_attempts[k] > 1) {
                    fprintf(log_fd, "Key %d encountered %u times\n", k + key_min, key_attempts[k]);
                }
            }
        }

        free(key_attempts);
    }

    // Release allocated memory
    for (size_t i = 0; i < num_sets; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
```

This C function initializes arrays as specified, tracks key generation attempts, logs duplicates to a file if needed, and ensures memory is properly freed in case of an error.']

