    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

// Function to populate the linked list
Node* populate_list(int listSize) {
    Node *head = NULL, *tail = NULL;

    for (int i = 0; i < listSize; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand(); // Simulate valid tag
        data.RNTI = rand(); // Simulate potential corruption

        if (data.RNTI == 0xDEADDEAD) { // Simulated corrupted RNTI
            log_anomaly("Corrupted RNTI detected");
            continue;
        }

        data.CRC_INDICATION_REL8_TAG = compute_crcflag(data.RNTI);

        Node *new_node = create_node(data);
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}

// Function to simulate compression
int compress_data(Node *list, const char *filename) {
    // Placeholder for actual compression logic
    FILE *file = fopen(filename, "w");
    if (!file) return 0;

    Node *current = list;
    while (current) {
        fprintf(file, "%u %u %u\n", current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }

    fclose(file);
    return 1; // Success
}

// Function to simulate file conversion using an external tool
int convert_file(const char *inputFile, const char *outputFile) {
    int result = system(("convert " + inputFile + " " + outputFile).c_str());
    return (result == 0) ? 0 : 1;
}

void processAndConvertFile(const char *inputFile, int listSize, const char *outputFile) {
    Node *list = populate_list(listSize);

    // Verify integrity
    for (Node *current = list; current != NULL; current = current->next) {
        if (!validate_crc(current)) {
            log_anomaly("CRC validation failed");
        }
    }

    // Optional compression
    char tempFile[] = "temp_data.txt";
    if (!compress_data(list, tempFile)) {
        log_anomaly("Compression failed");
    }

    // Convert file
    int conversion_status = convert_file(inputFile, outputFile);
    if (conversion_status != 0) {
        log_anomaly("File conversion failed");
    }

    // Free resources
    free_list(list);

    // Return status based on conversion success
    if (conversion_status == 0) {
        printf("Process completed successfully.\n");
    } else {
        printf("Process encountered errors.\n");
    }
}
