class DataPacket {
  constructor(id, timestamp, status) {
    this.id = id;
    this.timestamp = timestamp;
    this.status = status;
  }
}

function renderPurgeableFooter(dataPackets, expirationThresholdMs) {
  const now = Date.now();
  let lock = false;

  function acquireLock() {
    while (lock) { // Busy-waiting for the lock
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 1);
    }
    lock = true;
    Atomics.store(new Int32Array(new SharedArrayBuffer(4)), 0, 1);
  }

  function releaseLock() {
    lock = false;
    Atomics.notify(new Int32Array(new SharedArrayBuffer(4)), 0, 1);
  }

  async function filterAndRenderPackets(packets) {
    const filteredPackets = packets.filter(packet =>
      now - packet.timestamp < expirationThresholdMs
    );

    return filteredPackets.map(packet => 
      `<script id="${packet.id}" timestamp="${packet.timestamp}">${JSON.stringify({ status: packet.status })}</script>`
    ).join('');
  }

  function purgeUnusedData() {
    // Implement logic to periodically clean up unused DataPacket instances.
    // This can be a simple garbage collection strategy that runs at intervals
    // and removes references to packets older than the expiration threshold.
  }

  async function renderFooter() {
    acquireLock();
    try {
      const htmlContent = await filterAndRenderPackets(dataPackets);
      purgeUnusedData();
      return `<footer>${htmlContent}</footer>`;
    } finally {
      releaseLock();
    }
  }

  return renderFooter();
}
