#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 1000000

typedef struct Edge {
    int destination;
    int weight;
    struct Edge *next;
} Edge;

typedef struct Node {
    int id;
    char name[10]; // Assuming a fixed size for simplicity
    Edge *adjacencyList;
} Node;

typedef struct Graph {
    Node *nodes;
    int numNodes;
} Graph;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash;
}

Graph* initializeGraph(int numNodes, const char *seedString) {
    if (numNodes > MAX_NODES) {
        fprintf(stderr, "Number of nodes exceeds maximum limit.\n");
        return NULL;
    }

    Graph *graph = malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->nodes = malloc(numNodes * sizeof(Node));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    graph->numNodes = numNodes;

    for (int i = 0; i < numNodes; ++i) {
        Node *node = &graph->nodes[i];
        node->id = i + 1;

        char name[10];
        unsigned long hashValue = hash(seedString + i);
        snprintf(name, sizeof(name), "%lu", hashValue % (unsigned long)numNodes); // Simple hashing

        strcpy(node->name, name);
        node->adjacencyList = NULL; 
    }

    return graph;
}

void addEdge(Graph *graph, int fromId, int toId, int weight) {
    if (!graph || fromId < 1 || toId < 1 || fromId > graph->numNodes || toId > graph->numNodes || fromId == toId)
        return;

    Node *fromNode = &graph->nodes[fromId - 1];

    Edge *newEdge = malloc(sizeof(Edge));
    if (!newEdge) return; // Handle allocation failure

    newEdge->destination = toId;
    newEdge->weight = weight;
    newEdge->next = fromNode->adjacencyList;

    fromNode->adjacencyList = newEdge;
}

int getDegree(Graph *graph, int nodeId) {
    if (!graph || nodeId < 1 || nodeId > graph->numNodes)
        return -1;

    Node *node = &graph->nodes[nodeId - 1];
    int degree = 0;
    Edge *edge = node->adjacencyList;

    while (edge) {
        ++degree;
        edge = edge->next;
    }

    return degree;
}

// Placeholder for path and connectivity functions, as they require complex algorithms

void resizeGraph(Graph **graph, int newNumNodes, const char *seedString) {
    if (!graph || !*graph)
        return;

    Graph *newGraph = initializeGraph(newNumNodes, seedString);
    if (!newGraph) return;

    int minNodes = (*graph)->numNodes < newGraph->numNodes ? (*graph)->numNodes : newGraph->numNodes;

    for (int i = 0; i < minNodes; ++i) {
        Node *oldNode = &(*graph)->nodes[i];
        Node *newNode = &newGraph->nodes[i];

        newNode->id = oldNode->id;
        strcpy(newNode->name, oldNode->name);

        Edge *edge = oldNode->adjacencyList;

        while (edge) {
            addEdge(newGraph, oldNode->id, edge->destination, edge->weight);
            edge = edge->next;
        }
    }

    free((*graph)->nodes); // Free old nodes' data
    free(*graph);
    *graph = newGraph;     // Update graph pointer
}

void freeGraph(Graph *graph) {
    if (!graph)
        return;

    for (int i = 0; i < graph->numNodes; ++i) {
        Edge *edge = graph->nodes[i].adjacencyList;

        while (edge) {
            Edge *temp = edge;
            edge = edge->next;
            free(temp);
        }
    }

    free(graph->nodes);
    free(graph);
}

int main() {
    Graph *graph = initializeGraph(5, "seed");
    if (!graph)
        return 1;

    addEdge(graph, 1, 2, 10);
    addEdge(graph, 1, 3, 20);

    printf("Degree of node 1: %d\n", getDegree(graph, 1));

    resizeGraph(&graph, 10, "seed");

    freeGraph(graph);

    return 0;
}
```']

