                if (list->count < MAX_ENTRIES) {
                    list->entries[list->count++] = info;
                } else {
                    fprintf(stderr, "Maximum entry limit reached\n");
                    break;
                }
            }
        }

        pthread_mutex_unlock(&list->lock);
        fclose(file);
    }
