    const char *valid_causes[] = {"CAUSE1", "CAUSE2", "CAUSE3"};
    size_t valid_count = sizeof(valid_causes) / sizeof(char *);

    for (size_t i = 0; i < valid_count; ++i) {
        if (strcmp(cause, valid_causes[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Example usage
