        if (strcmp(valid_srvcc_causes[i], cause) == 0)
            return 1;
    }
    return 0;
}

// Thread-safe function to initialize the list from a JSON configuration file.
int initialize_lte_srvcc_list(SRVCC_LIST *srvcc_list, const char *config_file_path) {
    pthread_mutex_init(&srvcc_list->lock, NULL);
    srvcc_list->data = NULL;
    srvcc_list->count = 0;
    srvcc_list->capacity = 0;

