        fprintf(stderr, "Error parsing JSON\n");
        return -2; // Error parsing the file
    }

    if (!json_object_object_get_ex(parsed_json, "srvcc_list", &json_array)) {
        fprintf(stderr, "JSON does not contain srvcc_list\n");
        json_object_put(parsed_json);
        return -3; // Invalid JSON format
    }

    size_t num_entries = json_object_array_length(json_array);

    pthread_mutex_lock(&srvcc_list->lock);

    if (num_entries > srvcc_list->capacity) {
        srvcc_list->capacity = num_entries;
        srvcc_list->data = realloc(srvcc_list->data, sizeof(LTE_UESRVCC_INFO) * srvcc_list->capacity);
    }

    for (size_t i = 0; i < num_entries; ++i) {
        struct json_object *entry_obj;
        if (!json_object_array_get_idx(json_array, i, &entry_obj)) continue;

        LTE_UESRVCC_INFO info;
        memset(&info, 0, sizeof(info));

        struct json_object *ue_id_obj, *srvcc_cause_obj, *srvcc_ue_state_obj;

        if (json_object_object_get_ex(entry_obj, "ue_id", &ue_id_obj) &&
            json_object_object_get_ex(entry_obj, "srvcc_cause", &srvcc_cause_obj) &&
            json_object_object_get_ex(entry_obj, "srvcc_ue_state", &srvcc_ue_state_obj)) {

            info.ue_id = (int)json_object_get_int(ue_id_obj);
            strncpy(info.srvcc_cause, json_object_get_string(srvcc_cause_obj), sizeof(info.srvcc_cause));
            strncpy(info.srvcc_ue_state, json_object_get_string(srvcc_ue_state_obj), sizeof(info.srvcc_ue_state));

            if (is_valid_cause(info.srvcc_cause)) {
                srvcc_list->data[srvcc_list->count++] = info;
            } else {
                fprintf(stderr, "Invalid SRVCC cause: %s\n", info.srvcc_cause);
                // Optionally handle invalid cause based on context
            }
        }
    }

    pthread_mutex_unlock(&srvcc_list->lock);

    json_object_put(parsed_json); // Free JSON object

    return 0; // Success
}

// Usage example for the initialize_lte_srvcc_list function:
int main() {
    SRVCC_LIST srvcc_list;
    int status = initialize_lte_srvcc_list(&srvcc_list, "config.json");

