        // Use the srvcc_list
    } else {
        fprintf(stderr, "Failed to initialize SRVCC list with error code: %d\n", status);
    }

    pthread_mutex_destroy(&srvcc_list.lock);
    free(srvcc_list.data);

    return 0;
}
