#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000
#define MAX_RECORDS 10000
#define HASH_TABLE_SIZE 13000 // 0.7 * (MAX_RECORDS / 0.7)
#define INITIAL_CAPACITY 10

typedef struct Record {
    int value;
    char buffer[256];
} Record;

typedef struct HashNode {
    int key;
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    long* offsetArray;
    int capacityOffset;
    size_t usedOffset;

    int* keyArray;
    int capacityKeys;
    size_t usedKeys;

    Record* recordArray;
    size_t capacityRecords;
    size_t usedRecords;

    pthread_mutex_t lock;
} DataSet;

typedef struct {
    char** logs;
    size_t count;
    pthread_mutex_t lock;
} LogSystem;

// Utility functions
unsigned int hash(int key, size_t table_size) {
    return (key * 2654435761u % ((1U << 31) - 1)) % table_size;
}

void log_message(LogSystem* log_system, const char* message) {
    pthread_mutex_lock(&log_system->lock);
    if (log_system->count < MAX_LOG_ENTRIES) {
        log_system->logs[log_system->count++] = strdup(message);
    }
    pthread_mutex_unlock(&log_system->lock);
}

void free_logs(LogSystem* log_system) {
    for (size_t i = 0; i < log_system->count; ++i) {
        free(log_system->logs[i]);
    }
    free(log_system->logs);
}

// HashTable functions
HashTable* create_hash_table() {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->table = calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
    ht->size = HASH_TABLE_SIZE;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        HashNode* node = ht->table[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void resize_hash_table(HashTable* ht, size_t new_size) {
    HashTable* new_ht = create_hash_table();
    new_ht->size = new_size;

    for (size_t i = 0; i < ht->size; ++i) {
        HashNode* node = ht->table[i];
        while (node) {
            HashNode* next = node->next;
            unsigned int index = hash(node->key, new_ht->size);
            node->next = new_ht->table[index];
            new_ht->table[index] = node;
            ++new_ht->count;
            node = next;
        }
    }

    free(ht->table);
    ht->table = new_ht->table;
    ht->size = new_ht->size;
    ht->count = new_ht->count;
}

int insert_hash_table(HashTable* ht, int key, Record record) {
    pthread_mutex_lock(&ht->lock);

    if ((float)ht->count / ht->size > 0.7) {
        resize_hash_table(ht, ht->size * 2);
    }

    unsigned int index = hash(key, ht->size);
    HashNode* node = ht->table[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return -1; // Key already exists
        }
        node = node->next;
    }

    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        log_message(log_system, "Memory allocation failed for hash table node.");
        return -1; // Memory allocation failure
    }

    new_node->key = key;
    new_node->record = record;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    ++ht->count;

    pthread_mutex_unlock(&ht->lock);
    return 0; // Success
}

Record* search_hash_table(HashTable* ht, int key) {
    pthread_mutex_lock(&ht->lock);

    unsigned int index = hash(key, ht->size);
    HashNode* node = ht->table[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return &node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL; // Key not found
}

void free_data_set(DataSet* ds, LogSystem* log_system) {
    for (size_t i = 0; i < ds->usedRecords; ++i) {
        free(ds->recordArray[i].buffer); // Assuming dynamic allocation in buffer
    }

    pthread_mutex_destroy(&ds->lock);
    free(ds->offsetArray);
    free(ds->keyArray);
    free(ds->recordArray);
}

DataSet* initialize_data_set() {
    DataSet* ds = malloc(sizeof(DataSet));
    ds->capacityOffset = INITIAL_CAPACITY;
    ds->usedOffset = 0;
    ds->offsetArray = calloc(INITIAL_CAPACITY, sizeof(long));

    ds->capacityKeys = INITIAL_CAPACITY;
    ds->usedKeys = 0;
    ds->keyArray = calloc(INITIAL_CAPACITY, sizeof(int));

    ds->capacityRecords = INITIAL_CAPACITY;
    ds->usedRecords = 0;
    ds->recordArray = malloc(INITIAL_CAPACITY * sizeof(Record));

    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void resize_record_array(DataSet* ds) {
    pthread_mutex_lock(&ds->lock);

    if (ds->usedRecords >= ds->capacityRecords) {
        size_t new_capacity = ds->capacityRecords ? ds->capacityRecords * 2 : INITIAL_CAPACITY;

        Record* new_array = realloc(ds->recordArray, new_capacity * sizeof(Record));
        if (!new_array) {
            pthread_mutex_unlock(&ds->lock);
            log_message(log_system, "Memory allocation failed for record array resizing.");
            return;
        }
        ds->recordArray = new_array;
        ds->capacityRecords = new_capacity;
    }

    pthread_mutex_unlock(&ds->lock);
}

int process_data(DataSet* ds, LogSystem* log_system) {
    int num_integers;
    if (scanf("%d", &num_integers) != 1 || num_integers > 100000) {
        log_message(log_system, "Invalid number of integers to process.");
        return -1;
    }

    HashTable* ht = create_hash_table();

    for (int i = 0; i < num_integers; ++i) {
        int key;
        if (scanf("%d", &key) != 1 || key > MAX_RECORDS || key <= 0) {
            log_message(log_system, "Invalid integer input.");
            free_data_set(ds, log_system);
            free_hash_table(ht);
            return -1;
        }

        pthread_mutex_lock(&ds->lock);

        if (ds->usedRecords >= ds->capacityRecords) {
            resize_record_array(ds);
        }

        Record record;
        record.value = i; // Example value assignment
        snprintf(record.buffer, sizeof(record.buffer), "Buffer content for key %d", key); // Example buffer content

        int insert_result = insert_hash_table(ht, key, record);
        if (insert_result != 0) {
            log_message(log_system, "Failed to insert into hash table.");
            pthread_mutex_unlock(&ds->lock);
            free_data_set(ds, log_system);
            free_hash_table(ht);
            return -1;
        }

        ds->recordArray[ds->usedRecords++] = record;

        if (ds->usedOffset >= ds->capacityOffset) {
            size_t new_capacity = ds->capacityOffset ? ds->capacityOffset * 2 : INITIAL_CAPACITY;
            long* new_array = realloc(ds->offsetArray, new_capacity * sizeof(long));
            if (!new_array) {
                log_message(log_system, "Memory allocation failed for offset array resizing.");
                pthread_mutex_unlock(&ds->lock);
                free_data_set(ds, log_system);
                free_hash_table(ht);
                return -1;
            }
            ds->offsetArray = new_array;
            ds->capacityOffset = new_capacity;
        }

        ds->offsetArray[ds->usedOffset++] = (long) &ds->recordArray[ds->usedRecords - 1];

        pthread_mutex_unlock(&ds->lock);
    }

    free_hash_table(ht);
    return 0; // Success
}

int main() {
    LogSystem log_system;
    log_system.logs = malloc(MAX_LOG_ENTRIES * sizeof(char*));
    log_system.count = 0;
    pthread_mutex_init(&log_system.lock, NULL);

    DataSet* ds = initialize_data_set();

    if (process_data(ds, &log_system) == 0) {
        printf("Data processing completed successfully.\n");
    } else {
        printf("Data processing failed. See logs for details.\n");
    }

    free_logs(&log_system);
    free(log_system.logs);
    free_data_set(ds, &log_system);

    return 0;
}
