// Node structure for linked list of trajectories
typedef struct TrajectoryNode {
    trajectory traj;
    struct TrajectoryNode* next;
} TrajectoryNode;

TrajectoryNode* head = NULL;

// Function to initialize the system
int initialize_system() {
    return pthread_mutex_init(&mutex, NULL);
}

// Function to add a new trajectory
int add_trajectory(double value, float x, float y, status s) {
    pthread_mutex_lock(&mutex);

    TrajectoryNode** current = &head;

    while (*current != NULL) {
        current = &((*current)->next);
    }

    TrajectoryNode* newNode = (TrajectoryNode*)malloc(sizeof(TrajectoryNode));
    if (!newNode) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failed
    }

    newNode->traj.value = value;
    newNode->traj.p.x = x;
    newNode->traj.p.y = y;
    newNode->traj.s = s;
    newNode->next = NULL;

    *current = newNode;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

// Function to remove a trajectory by index
int remove_trajectory(int index) {
    if (index < 0) return -1; // Invalid index

    pthread_mutex_lock(&mutex);

    TrajectoryNode** current = &head;
    int currentIndex = 0;

    while (*current != NULL && currentIndex < index) {
        current = &((*current)->next);
        currentIndex++;
    }

    if (*current == NULL || currentIndex != index) {
        pthread_mutex_unlock(&mutex);
        return -1; // Index out of bounds
    }

    TrajectoryNode* toDelete = *current;
    *current = (*current)->next;

    free(toDelete);

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

// Function to update a trajectory by index
int update_trajectory(int index, double value, float x, float y, status s) {
    if (index < 0) return -1; // Invalid index

    pthread_mutex_lock(&mutex);

    TrajectoryNode* current = head;
    int currentIndex = 0;

    while (current != NULL && currentIndex < index) {
        current = current->next;
        currentIndex++;
    }

    if (current == NULL || currentIndex != index) {
        pthread_mutex_unlock(&mutex);
        return -1; // Index out of bounds
    }

    current->traj.value = value;
    current->traj.p.x = x;
    current->traj.p.y = y;
    current->traj.s = s;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

// Function to free all allocated memory
void free_all() {
    pthread_mutex_lock(&mutex);

    TrajectoryNode* current = head;
    while (current != NULL) {
        TrajectoryNode* next = current->next;
        free(current);
        current = next;
    }

    head = NULL;

    pthread_mutex_unlock(&mutex);
}

// Function to destroy the system and clean up resources
int destroy_system() {
    free_all();
    return pthread_mutex_destroy(&mutex);
}
```

This code defines a simple thread-safe linked list structure for managing trajectories. It includes functions for initializing, adding, removing, updating, freeing memory, and destroying the system. The use of `pthread_mutex` ensures that operations are safe in a multi-threaded environment.']

