typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
} DynamicCollection;

// Custom memory allocator
void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize collection with capacity
int init_collection(DynamicCollection *collection, size_t initial_capacity) {
    if (initial_capacity == 0) return -1;

    collection->records = custom_alloc(initial_capacity * sizeof(Record));
    collection->capacity = initial_capacity;
    collection->count = 0;

    printf("Collection initialized with capacity: %zu\n", initial_capacity);
    return 0;
}

// Reallocate memory block to optimize performance
int reallocate_collection(DynamicCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    Record *new_records = custom_alloc(new_capacity * sizeof(Record));

    if (new_records == NULL) {
        fprintf(stderr, "Reallocation failed\n");
        return -1;
    }

    memcpy(new_records, collection->records, collection->count * sizeof(Record));
    free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;

    printf("Collection reallocated to capacity: %zu\n", new_capacity);
    return 0;
}

// Add record to collection
int add_record(DynamicCollection *collection, int key, long offset) {
    if (collection->count == collection->capacity) {
        if (reallocate_collection(collection) != 0) {
            fprintf(stderr, "Failed to add record: collection full\n");
            return -1;
        }
    }

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    collection->count++;

    printf("Record added: key=%d, offset=%ld\n", key, offset);
    return 0;
}

// Free the allocated memory
void free_collection(DynamicCollection *collection) {
    if (collection->records) {
        free(collection->records);
        collection->records = NULL;
    }
    collection->capacity = 0;
    collection->count = 0;

    printf("Collection freed\n");
}

