['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define EXPIRATION_THRESHOLD_SECONDS 3600 // Example threshold

typedef struct {
    char *key;
    time_t timestamp;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* create_table(size_t initial_capacity);
void free_table(HashTable *table);
int hash_function(const char *key, size_t capacity);
void resize_table(HashTable *table);
void add_record(HashTable *table, const char *key, int value);
Record* get_record(HashTable *table, const char *key);
void update_record(HashTable *table, const char *key, int value);
void purge_expired_records(HashTable *table);

// Create a new hash table
HashTable* create_table(size_t initial_capacity) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node **)calloc(initial_capacity, sizeof(Node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Free the hash table
void free_table(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp->record.key);
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Hash function
int hash_function(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % capacity;
}

// Resize the hash table
void resize_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Node **new_buckets = (Node **)calloc(new_capacity, sizeof(Node *));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node) {
            Node *next_node = node->next;
            int new_index = hash_function(node->record.key, new_capacity);
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Add a record to the hash table
void add_record(HashTable *table, const char *key, int value) {
    if (!key || strlen(key) == 0) return;

    pthread_mutex_lock(&table->lock);

    int index = hash_function(key, table->capacity);
    Node *node = table->buckets[index];

    while (node) {
        if (strcmp(node->record.key, key) == 0) {
            node->record.timestamp = time(NULL);
            node->record.value = value;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        node = node->next;
    }

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->record.key = strdup(key);
    if (!new_node->record.key) {
        free(new_node);
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->record.timestamp = time(NULL);
    new_node->record.value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    if (pthread_mutex_trylock(&table->lock) == 0) {
        pthread_mutex_unlock(&table->lock);
    }

    pthread_mutex_unlock(&table->lock);
}

// Get a record from the hash table
Record* get_record(HashTable *table, const char *key) {
    if (!key || strlen(key) == 0) return NULL;

    int index = hash_function(key, table->capacity);

    pthread_mutex_lock(&table->lock);
    Node *node = table->buckets[index];
    while (node) {
        if (strcmp(node->record.key, key) == 0) {
            Record *result = &node->record;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}

// Update a record in the hash table
void update_record(HashTable *table, const char *key, int value) {
    Record *record = get_record(table, key);
    if (record) {
        record->timestamp = time(NULL);
        record->value = value;
    }
}

// Purge expired records from the hash table
void purge_expired_records(HashTable *table) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        Node **node = &table->buckets[i];
        while (*node) {
            if (current_time - (*node)->record.timestamp > EXPIRATION_THRESHOLD_SECONDS) {
                Node *to_delete = *node;
                *node = to_delete->next;
                free(to_delete->record.key);
                free(to_delete);
            } else {
                node = &(*node)->next;
            }
        }
    }
    pthread_mutex_unlock(&table->lock);
}

// Example usage
int main() {
    HashTable *table = create_table(INITIAL_CAPACITY);

    add_record(table, "key1", 100);
    Record *record = get_record(table, "key1");
    if (record) {
        printf("Record: %s, Value: %d\n", record->key, record->value);
    }

    update_record(table, "key1", 200);

    purge_expired_records(table);

    free_table(table);
    return 0;
}
```

This code provides a basic implementation of the task requirements. It includes functions for creating, adding, updating, and retrieving records in a hash table with thread safety using mutexes. It also handles resizing and purging expired records based on a configurable threshold. Error handling and logging are simplified for clarity.']

