```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the L2_FRAME_T structure
typedef struct L2_FRAME {
    int frame_data; // Placeholder for actual data
    struct L2_FRAME *next;
} L2_FRAME_T;

// Define the MAC_CONTEXT_T structure
typedef struct MAC_CONTEXT {
    unsigned long MAC_ID;              // Unique MAC entity identifier
    time_t timestamp;                  // Timestamp
    L2_FRAME_T *frames_head;           // Head of linked list of frames
    pthread_mutex_t mutex;             // Mutex for thread safety
} MAC_CONTEXT_T;

// Global context array and its metadata
#define MAX_CONTEXTS 1000000000
MAC_CONTEXT_T *contexts[MAX_CONTEXTS];
int context_count = 0;
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging mechanism
void log_operation(const char *operation, unsigned long mac_id) {
    time_t now = time(NULL);
    printf("[%s] %s MAC_ID: %lu\n", ctime(&now), operation, mac_id);
}

// Function to initialize a new context
MAC_CONTEXT_T* init_mac_context(unsigned long mac_id) {
    if (mac_id >= MAX_CONTEXTS) {
        fprintf(stderr, "MAC_ID out of range.\n");
        return NULL;
    }

    // Allocate memory for the MAC_CONTEXT structure
    MAC_CONTEXT_T *context = malloc(sizeof(MAC_CONTEXT_T));
    if (!context) {
        perror("Failed to allocate MAC_CONTEXT_T");
        log_operation("Allocation failed", mac_id);
        return NULL;
    }

    pthread_mutex_init(&context->mutex, NULL);

    context->MAC_ID = mac_id;
    context->timestamp = time(NULL);
    context->frames_head = NULL;

    // Lock the global mutex for thread safety
    pthread_mutex_lock(&global_mutex);
    contexts[mac_id] = context;
    context_count++;
    pthread_mutex_unlock(&global_mutex);

    log_operation("Context initialized", mac_id);

    return context;
}

// Function to add a frame to a MAC_CONTEXT
void add_frame_to_context(unsigned long mac_id, int frame_data) {
    if (mac_id >= MAX_CONTEXTS || !contexts[mac_id]) {
        fprintf(stderr, "Invalid MAC_ID or uninitialized context.\n");
        log_operation("Failed to add frame", mac_id);
        return;
    }

    L2_FRAME_T *new_frame = malloc(sizeof(L2_FRAME_T));
    if (!new_frame) {
        perror("Failed to allocate L2_FRAME_T");
        log_operation("Frame allocation failed", mac_id);
        return;
    }

    new_frame->frame_data = frame_data;
    new_frame->next = NULL;

    // Lock the specific context's mutex for thread safety
    pthread_mutex_lock(&contexts[mac_id]->mutex);

    L2_FRAME_T *current = contexts[mac_id]->frames_head;
    if (current) {
        while (current->next) {
            current = current->next;
        }
        current->next = new_frame;
    } else {
        contexts[mac_id]->frames_head = new_frame;
    }

    pthread_mutex_unlock(&contexts[mac_id]->mutex);

    log_operation("Frame added", mac_id);
}

// Function to free a MAC_CONTEXT and its frames
void free_mac_context(unsigned long mac_id) {
    if (mac_id >= MAX_CONTEXTS || !contexts[mac_id]) {
        fprintf(stderr, "Invalid MAC_ID or uninitialized context.\n");
        return;
    }

    // Lock the specific context's mutex for thread safety
    pthread_mutex_lock(&contexts[mac_id]->mutex);

    L2_FRAME_T *frame = contexts[mac_id]->frames_head;
    while (frame) {
        L2_FRAME_T *temp = frame;
        frame = frame->next;
        free(temp);
    }

    pthread_mutex_unlock(&contexts[mac_id]->mutex);

    // Free the context and its mutex
    pthread_mutex_lock(&global_mutex);
    pthread_mutex_destroy(&contexts[mac_id]->mutex);
    free(contexts[mac_id]);
    contexts[mac_id] = NULL;
    context_count--;
    pthread_mutex_unlock(&global_mutex);

    log_operation("Context freed", mac_id);
}

// Initialize the system
void initialize_system() {
    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        contexts[i] = NULL;
    }
}

// Clean up resources at program termination
void cleanup_system() {
    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        if (contexts[i]) {
            free_mac_context(i);
        }
    }
}
```

### Key Features:
1. **Thread Safety:** Uses mutexes to ensure thread-safe operations on contexts and frames.
2. **Error Handling:** Gracefully handles memory allocation failures with logging for debugging purposes.
3. **Logging Mechanism:** Records all significant operations for monitoring and debugging.
4. **Efficiency Considerations:** Designed for high-throughput, low-latency environments with minimal overhead.

To use this code:
- Call `initialize_system()` at the start of your program to set up the context storage.
- Use `init_mac_context()`, `add_frame_to_context()`, and `free_mac_context()` as needed in your application logic.
- Ensure you call `cleanup_system()` before program termination to free allocated resources.']

