} UserManager;

UserManager userManager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_user_manager(size_t capacity) {
    userManager.users = malloc(capacity * sizeof(User));
    if (!userManager.users) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

StringList create_string_list() {
