    if (userManager.count >= USER_CAPACITY) {
        printf("User capacity reached. Cannot add more users.\n");
        pthread_mutex_unlock(&userManager.lock);
        return;
    }

    User *user = &userManager.users[manager.count++];
    strncpy(user->name, name, MAX_NAME_LENGTH - 1);
    user->age = age;

