        exit(EXIT_FAILURE);
    }
    user->hobbies.length = 0;  // Assume no hobbies fetched initially

    pthread_mutex_unlock(&userManager.lock);
}

void update_user(const char *name, int age) {
    pthread_mutex_lock(&userManager.lock);

    for (size_t i = 0; i < userManager.count; ++i) {
        if (strcmp(userManager.users[i].name, name) == 0) {
            userManager.users[i].age = age;
            break;
        }
    }

    pthread_mutex_unlock(&userManager.lock);
}

void delete_user(const char *name) {
    pthread_mutex_lock(&userManager.lock);

    for (size_t i = 0; i < userManager.count; ++i) {
        if (strcmp(userManager.users[i].name, name) == 0) {
            // Free hobbies memory
            free(userManager.users[i].hobbies.data);
            // Shift users
            memmove(&userManager.users[i], &userManager.users[i + 1],
                    (userManager.count - i - 1) * sizeof(User));
            userManager.count--;
            break;
        }
    }

    pthread_mutex_unlock(&userManager.lock);
}

void list_users() {
    pthread_mutex_lock(&userManager.lock);

    for (size_t i = 0; i < userManager.count; ++i) {
        printf("Name: %s, Age: %d\n", userManager.users[i].name, userManager.users[i].age);
        for (size_t j = 0; j < userManager.users[i].hobbies.length; ++j) {
            printf("\tHobby: %s\n", userManager.users[i].hobbies.data[j]);
        }
    }

    pthread_mutex_unlock(&userManager.lock);
}

void serialize_users(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&userManager.count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < userManager.count; ++i) {
        size_t name_length = strlen(userManager.users[i].name);
        fwrite(&name_length, sizeof(size_t), 1, file);
        fwrite(userManager.users[i].name, sizeof(char), name_length, file);

        int age = userManager.users[i].age;
        fwrite(&age, sizeof(int), 1, file);

        size_t hobbies_count = userManager.users[i].hobbies.length;
        fwrite(&hobbies_count, sizeof(size_t), 1, file);

        for (size_t j = 0; j < hobbies_count; ++j) {
            size_t hobby_length = strlen(userManager.users[i].hobbies.data[j]);
            fwrite(&hobby_length, sizeof(size_t), 1, file);
            fwrite(userManager.users[i].hobbies.data[j], sizeof(char), hobby_length, file);
        }
    }

    fclose(file);
}

void deserialize_users(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(&userManager.count, sizeof(size_t), 1, file);

    initialize_user_manager(userManager.count);  // Reinitialize with new capacity

    for (size_t i = 0; i < userManager.count; ++i) {
        size_t name_length;
        fread(&name_length, sizeof(size_t), 1, file);
        fread(userManager.users[i].name, sizeof(char), name_length, file);

        int age;
        fread(&age, sizeof(int), 1, file);
        userManager.users[i].age = age;

        size_t hobbies_count;
        fread(&hobbies_count, file, sizeof(size_t));

        userManager.users[i].hobbies.data = malloc(hobbies_count * sizeof(char *));
        if (!userManager.users[i].hobbies.data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < hobbies_count; ++j) {
            size_t hobby_length;
            fread(&hobby_length, file, sizeof(size_t));
            userManager.users[i].hobbies.data[j] = malloc(hobby_length + 1);
            if (!userManager.users[i].hobbies.data[j]) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            fread(userManager.users[i].hobbies.data[j], sizeof(char), hobby_length, file);
            userManager.users[i].hobbies.data[j][hobby_length] = '\0';
        }

        userManager.users[i].hobbies.length = hobbies_count;
    }

    fclose(file);
}

void free_user_manager() {
    pthread_mutex_lock(&userManager.lock);

    for (size_t i = 0; i < userManager.count; ++i) {
        free(userManager.users[i].hobbies.data);
    }

    free(userManager.users);
    userManager.count = 0;

    pthread_mutex_unlock(&userManager.lock);
}

int main() {
    initialize_user_manager(USER_CAPACITY);

    // Example usage
    add_user("Alice", 30);
    add_user("Bob", 25);
    list_users();

    serialize_users("users.dat");
    free_user_manager();

    deserialize_users("users.dat");
    list_users();

    free_user_manager();

    return 0;
}
