['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONFIG_KEYS 100
#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int key;
    long offset;
    struct {
        int value;
        char buffer[BUFFER_SIZE];
    } record;
} Record;

typedef struct {
    char *key;
    char *value;
    int version;
    time_t timestamp;
} ConfigSetting;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_rwlock_t lock;
} HashTable;

typedef struct {
    HashTable configSettings;
    HashTable integerRecords;
    size_t currentMemoryUsage;
} SystemState;

// Function prototypes
void handle_config_and_data_storage(SystemState *state);
ConfigSetting* find_config_setting(HashTable *table, const char *key);
Record* find_integer_record(HashTable *table, int key);
void add_or_update_config_setting(HashTable *table, const char *key, const char *value, int version, time_t timestamp);
void process_integer_records(SystemState *state);
void serialize_system_state(const SystemState *state, const char *filename);
void deserialize_system_state(SystemState *state, const char *filename);
void generate_report(const SystemState *state);

// Helper functions
unsigned int hash_function(void *key, size_t key_len);
HashTable* create_hash_table();
Node* create_node(void *data);
void free_node(Node *node);
void resize_hash_table(HashTable *table);

void handle_config_and_data_storage(SystemState *state) {
    pthread_rwlock_init(&state->configSettings.lock, NULL);
    pthread_rwlock_init(&state->integerRecords.lock, NULL);

    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        // Example of processing configuration and records
        if (strncmp(line, "CONFIG ", 7) == 0) {
            // Parse config command: CONFIG <key> <value> <version>
            char key[256], value[256];
            int version;
            sscanf(line + 7, "%s %s %d", key, value, &version);
            time_t timestamp = time(NULL);
            add_or_update_config_setting(&state->configSettings, key, value, version, timestamp);
        } else if (strncmp(line, "RECORD ", 7) == 0) {
            // Parse record command: RECORD <key> <offset> <value>
            int key;
            long offset;
            int value;
            sscanf(line + 7, "%d %ld %d", &key, &offset, &value);
            Record *record = find_integer_record(&state->integerRecords, key);
            if (!record) {
                record = malloc(sizeof(Record));
                record->key = key;
                record->offset = offset;
                pthread_rwlock_wrlock(&state->integerRecords.lock);
                Node *node = create_node(record);
                node->next = state->integerRecords.head;
                state->integerRecords.head = node;
                pthread_rwlock_unlock(&state->integerRecords.lock);
            } else {
                record->record.value = value;
            }
        }
    }

    // Generate report
    generate_report(state);

    // Serialize system state to a file
    serialize_system_state(state, "system_state.bin");

    // Clean up
    Node *current = state->configSettings.head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
    current = state->integerRecords.head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
}

ConfigSetting* find_config_setting(HashTable *table, const char *key) {
    pthread_rwlock_rdlock(&table->lock);
    Node *current = table->head;
    while (current) {
        ConfigSetting *setting = (ConfigSetting*)current->data;
        if (strcmp(setting->key, key) == 0) {
            pthread_rwlock_unlock(&table->lock);
            return setting;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&table->lock);
    return NULL;
}

Record* find_integer_record(HashTable *table, int key) {
    pthread_rwlock_rdlock(&table->lock);
    Node *current = table->head;
    while (current) {
        Record *record = (Record*)current->data;
        if (record->key == key) {
            pthread_rwlock_unlock(&table->lock);
            return record;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&table->lock);
    return NULL;
}

void add_or_update_config_setting(HashTable *table, const char *key, const char *value, int version, time_t timestamp) {
    ConfigSetting *setting = find_config_setting(table, key);
    if (setting) {
        free(setting->value);
        setting->version = version;
        setting->timestamp = timestamp;
    } else {
        setting = malloc(sizeof(ConfigSetting));
        setting->key = strdup(key);
        setting->value = strdup(value);
        setting->version = version;
        setting->timestamp = timestamp;
        pthread_rwlock_wrlock(&table->lock);
        Node *node = create_node(setting);
        node->next = table->head;
        table->head = node;
        pthread_rwlock_unlock(&table->lock);
    }
}

void process_integer_records(SystemState *state) {
    // Implement logic for processing integer records
}

void serialize_system_state(const SystemState *state, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;
    // Serialize config settings
    Node *current = state->configSettings.head;
    while (current) {
        ConfigSetting *setting = (ConfigSetting*)current->data;
        fwrite(&setting->version, sizeof(int), 1, file);
        size_t key_len = strlen(setting->key) + 1;
        fwrite(&key_len, sizeof(size_t), 1, file);
        fwrite(setting->key, sizeof(char), key_len, file);
        size_t value_len = strlen(setting->value) + 1;
        fwrite(&value_len, sizeof(size_t), 1, file);
        fwrite(setting->value, sizeof(char), value_len, file);
        fwrite(&setting->timestamp, sizeof(time_t), 1, file);
        current = current->next;
    }
    // Serialize integer records
    current = state->integerRecords.head;
    while (current) {
        Record *record = (Record*)current->data;
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->record.value, sizeof(int), 1, file);
        size_t buffer_len = strlen(record->record.buffer) + 1;
        fwrite(&buffer_len, sizeof(size_t), 1, file);
        fwrite(record->record.buffer, sizeof(char), buffer_len, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_system_state(SystemState *state, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;
    // Deserialize config settings
    while (1) {
        int version;
        size_t key_len;
        fread(&version, sizeof(int), 1, file);
        if (feof(file)) break;
        fread(&key_len, sizeof(size_t), 1, file);
        char *key = malloc(key_len);
        fread(key, sizeof(char), key_len, file);
        size_t value_len;
        fread(&value_len, sizeof(size_t), 1, file);
        char *value = malloc(value_len);
        fread(value, sizeof(char), value_len, file);
        time_t timestamp;
        fread(&timestamp, sizeof(time_t), 1, file);
        add_or_update_config_setting(&state->configSettings, key, value, version, timestamp);
        free(key);
        free(value);
    }
    // Deserialize integer records
    while (1) {
        int key;
        long offset;
        int record_value;
        fread(&key, sizeof(int), 1, file);
        if (feof(file)) break;
        fread(&offset, sizeof(long), 1, file);
        fread(&record_value, sizeof(int), 1, file);
        size_t buffer_len;
        fread(&buffer_len, sizeof(size_t), 1, file);
        char *buffer = malloc(buffer_len);
        fread(buffer, sizeof(char), buffer_len, file);
        Record *record = find_integer_record(&state->integerRecords, key);
        if (!record) {
            record = malloc(sizeof(Record));
            record->key = key;
            record->offset = offset;
            pthread_rwlock_wrlock(&state->integerRecords.lock);
            Node *node = create_node(record);
            node->next = state->integerRecords.head;
            state->integerRecords.head = node;
            pthread_rwlock_unlock(&state->integerRecords.lock);
        }
        record->record.value = record_value;
        strncpy(record->record.buffer, buffer, BUFFER_SIZE - 1);
        free(buffer);
    }
    fclose(file);
}

