typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void clear_list(Node** head) {
    pthread_mutex_lock(&list_mutex);
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
    pthread_mutex_unlock(&list_mutex);
}

Node* generate_crc_indication_list(int max_structures, int randomness_factor) {
    srand(time(NULL));
    int num_structures = (rand() % max_structures) + 1;

    Node* head = NULL;
    Node** current = &head;

    uint16_t used_rntis[1000] = {0};

    for (int i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&list_mutex);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        do {
            pdu.RX_UE_INFORMATION_TAG = rand() % randomness_factor + 1;
            pdu.RNTI = rand();
        } while (used_rntis[pdu.RNTI % 1000] == 1);

        used_rntis[pdu.RNTI % 1000] = 1;
        pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2;

        Node* new_node = create_node(pdu);
        if (!new_node) {
            clear_list(&head);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        *current = new_node;
        current = &new_node->next;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

int main() {
    Node* list_head = generate_crc_indication_list(1000, 256);

    if (list_head) {
        // Use the linked list
        clear_list(&list_head);
    } else {
        printf("Failed to allocate memory for the list.\n");
    }

    return 0;
}
