- **Unique RNTI Assignment**: An array tracks used RNTIs to prevent duplicates. It uses modulo operation for efficient lookup, considering the limited size of possible unique values.
- **Randomization and Configuration**: Random values are generated using `rand()` seeded with `srand(time(NULL))`, allowing configuration via parameters like `max_structures` and `randomness_factor`.
- **Error Handling**: If memory allocation fails at any point, the list is cleared to prevent leaks.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    time_t creation_time;
} timestamp;

#define MAX_RETRIES 1000
#define RANDOM_MIN 1
#define RANDOM_MAX 10000

static int global_unique_keys = 0;
static pthread_mutex_t lock;

int generate_unique_key(int *keys, int size) {
    int key, retries = 0;
    while (retries < MAX_RETRIES) {
        key = rand() % (RANDOM_MAX - RANDOM_MIN + 1) + RANDOM_MIN;
        for (int i = 0; i < size; i++) {
            if (keys[i] == key)
                break;
            if (i == size - 1) // If no duplicate found
                return key;
        }
        retries++;
    }
    return -1; // Indicating failure to find a unique key within max retries
}

void* initialize_data(int array_size, int log_fd) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    timestamp *timestamps = NULL;

    if (array_size <= 0) {
        fprintf(stderr, "Invalid input: Array size must be positive.\n");
        return NULL;
    }

    offsets = malloc(array_size * sizeof(long));
    keys = malloc(array_size * sizeof(int));
    records = malloc(array_size * sizeof(record));
    timestamps = malloc(array_size * sizeof(timestamp));

    if (!offsets || !keys || !records || !timestamps) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        free(timestamps);
        return NULL;
    }

    srand(time(NULL));

    int retries_stats[array_size] = {0};
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        offsets[i] = 0L;
        keys[i] = -1;
        records[i].value = 0;
        timestamps[i].creation_time = time(NULL);

        int retries = 0;
        while ((keys[i] = generate_unique_key(keys, i)) == -1) {
            retries++;
        }
        if (retries > 0 && log_fd != -1) {
            dprintf(log_fd, "Key %d generated after %d retries.\n", keys[i], retries);
        }

        records[i].value = keys[i];
        global_unique_keys++;

        retries_stats[i] = retries;
    }

    pthread_mutex_unlock(&lock);

    // For demonstration purposes: Print stats
    if (log_fd != -1) {
        for (int i = 0; i < array_size; i++) {
            dprintf(log_fd, "Element %d, Key: %d, Value: %d, Creation Time: %ld, Retries: %d\n", 
                    i, keys[i], records[i].value, timestamps[i].creation_time, retries_stats[i]);
        }
    }

    free(offsets);
    free(keys);
    free(records);
    free(timestamps);

    return NULL;
}

void init_mutex() {
    pthread_mutex_init(&lock, NULL);
}
