```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
    time_t last_accessed;
} record;

// Error log file
FILE *error_log = fopen("memory_errors.log", "a");

void log_error(const char *message) {
    if (error_log) {
        fprintf(error_log, "%s\n", message);
        fflush(error_log);
    }
}

long* allocate_offsets(size_t initial_size) {
    long* array = malloc(initial_size * sizeof(long));
    if (!array) {
        log_error("Failed to allocate offsets");
    }
    return array;
}

int* allocate_keys(size_t initial_size) {
    int* array = malloc(initial_size * sizeof(int));
    if (!array) {
        log_error("Failed to allocate keys");
    }
    return array;
}

record* allocate_records(size_t initial_size) {
    record* array = malloc(initial_size * sizeof(record));
    if (!array) {
        log_error("Failed to allocate records");
    }
    return array;
}

void initialize_arrays(long** offsets, int** keys, record** records, size_t num_elements) {
    srand(time(NULL));

    *offsets = allocate_offsets(1024);
    *keys = allocate_keys(1024);
    *records = allocate_records(1024);

    if (!*offsets || !*keys || !*records) return;

    long offset_sum = 0;
    for (size_t i = 0; i < num_elements && offset_sum <= LIMIT; ++i) {
        (*offsets)[i] = rand() % 100 + 1;
        offset_sum += (*offsets)[i];

        (*keys)[i] = rand() % 100;

        record* rec = &(*records)[i];
        rec->value = rand() % 1000;
        rec->offset_ptr = &((*offsets)[i]);
        rec->key_ptr = &((*keys)[i]);
        rec->last_accessed = time(NULL);
    }
}

void resize_arrays(long** offsets, int** keys, record** records) {
    size_t new_size_offsets = (*offsets ? (1 + (*offsets)) : 0) * 2;
    size_t new_size_keys = (*keys ? (1 + (*keys)) : 0) * 2;
    size_t new_size_records = (*records ? (1 + (*records)) : 0) * 2;

    long* new_offsets = realloc(*offsets, new_size_offsets * sizeof(long));
    int* new_keys = realloc(*keys, new_size_keys * sizeof(int));
    record* new_records = realloc(*records, new_size_records * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        log_error("Failed to resize arrays");
        return;
    }

    *offsets = new_offsets;
    *keys = new_keys;
    *records = new_records;
}

void mark_inactive_records(record* records, size_t num_elements, time_t grace_period) {
    for (size_t i = 0; i < num_elements; ++i) {
        if (difftime(time(NULL), records[i].last_accessed) > grace_period) {
            // Mark as inactive
            records[i].value = -1;
        }
    }
}

int main() {
    size_t num_elements = 1000;
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    initialize_arrays(&offsets, &keys, &records, num_elements);

    // Example usage
    time_t grace_period = 60 * 5; // 5 minutes
    mark_inactive_records(records, num_elements, grace_period);

    // Cleanup
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    fclose(error_log);

    return 0;
}
