void load_list_from_persistent_storage(DoublyLinkedList* list); // Placeholder function

// Helper functions for random number generation and memory management
unsigned short generate_random_rnti(void);
int generate_random_crcflag(void);

DoublyLinkedList* create_list(void) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_rwlock_init(&list->rlock, NULL);

    return list;
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    pthread_rwlock_destroy(&list->rlock);
    free(list);
}

int insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    // Acquire write lock
    pthread_rwlock_wrlock(&list->rlock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&list->rlock);
        return -2; // Memory allocation failure
    }

    new_node->data.RX_UE_INFORMATION_TAG = generate_random_rnti();
    new_node->data.RNTI = data.RNTI;
    new_node->data.CRCFLAG = generate_random_crcflag();

    pthread_mutex_lock(&list->mutex);

    if (find_node_by_rnti(list, new_node->data.RNTI)) {
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        pthread_rwlock_unlock(&list->rlock);
        return -3; // Duplicate RNTI
    }

    if (!list->head) { // Empty list
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    log_operation("Insert", new_node->data);
    pthread_mutex_unlock(&list->mutex);

    list->size++;
    pthread_rwlock_unlock(&list->rlock);

    return 0; // Success
}

Node* find_node_by_rnti(DoublyLinkedList* list, unsigned short rnti) {
    if (!list || !list->head) return NULL;

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti)
            return current;
        current = current->next;
    }
    return NULL;
}

int delete_node_by_rnti(DoublyLinkedList* list, unsigned short rnti) {
    if (!list || !list->head) return -1;

    pthread_rwlock_wrlock(&list->rlock);

    Node* node_to_delete = find_node_by_rnti(list, rnti);
    if (!node_to_delete) {
        pthread_rwlock_unlock(&list->rlock);
        return -2; // Not found
    }

    pthread_mutex_lock(&list->mutex);

    if (node_to_delete == list->head && node_to_delete == list->tail) {
        list->head = list->tail = NULL;
    } else if (node_to_delete == list->head) {
        list->head = node_to_delete->next;
        list->head->prev = NULL;
    } else if (node_to_delete == list->tail) {
        list->tail = node_to_delete->prev;
        list->tail->next = NULL;
    } else {
        node_to_delete->prev->next = node_to_delete->next;
        node_to_delete->next->prev = node_to_delete->prev;
    }

    log_operation("Delete", node_to_delete->data);
    free(node_to_delete);

    pthread_mutex_unlock(&list->mutex);
    list->size--;
    pthread_rwlock_unlock(&list->rlock);

    return 0; // Success
}

void traverse_forward(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !list->head) return;

    Node* current = list->head;
    pthread_rwlock_rdlock(&list->rlock);

    while (current) {
        callback(current->data);
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rlock);
}

void traverse_backward(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !list->tail) return;

    Node* current = list->tail;
    pthread_rwlock_rdlock(&list->rlock);

    while (current) {
        callback(current->data);
        current = current->prev;
    }

    pthread_rwlock_unlock(&list->rlock);
}

void log_operation(const char* operation, NFAPI_CRC_INDICATION_PDU_T data) {
