#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY 1000

typedef struct {
    int key;
    int* offsets;
    size_t offset_count;
    int valid;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct {
    Node* head;
    size_t total_memory_usage;
    size_t max_memory_usage;
    pthread_rwlock_t rwlock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_size, size_t min_offsets, size_t max_offsets, size_t max_memory) {
    if (initial_size == 0 || min_offsets > max_offsets || max_memory == 0) return NULL;

    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    pthread_rwlock_init(&collection->rwlock, NULL);
    collection->head = NULL;
    collection->total_memory_usage = 0;
    collection->max_memory_usage = max_memory;

    for (size_t i = 0; i < initial_size; ++i) {
        add_record(collection, min_offsets, max_offsets);
    }

    return collection;
}

int generate_unique_key(RecordCollection* collection, int key_pool[]) {
    pthread_rwlock_rdlock(&collection->rwlock);
    for (int k = 0; k <= MAX_KEY; ++k) {
        if (!key_pool[k]) {
            key_pool[k] = 1;
            pthread_rwlock_unlock(&collection->rwlock);
            return k;
        }
    }
    pthread_rwlock_unlock(&collection->rwlock);
    return -1;
}

void free_record(Node* node) {
    free(node->record.offsets);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

Node* create_node(int key, int* offsets, size_t offset_count) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->record.key = key;
    new_node->record.offsets = offsets;
    new_node->record.offset_count = offset_count;
    new_node->record.valid = 1;

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = NULL;

    return new_node;
}

void add_record(RecordCollection* collection, size_t min_offsets, size_t max_offsets) {
    pthread_rwlock_wrlock(&collection->rwlock);

    int key_pool[MAX_KEY + 1] = {0};
    for (Node* node = collection->head; node != NULL; node = node->next) {
        key_pool[node->record.key] = 1;
    }

    size_t offset_count = min_offsets + rand() % (max_offsets - min_offsets + 1);
    int* offsets = malloc(offset_count * sizeof(int));
    if (!offsets) {
        pthread_rwlock_unlock(&collection->rwlock);
        return;
    }

    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = rand(); // Ensure unique values
    }

    int key = generate_unique_key(collection, key_pool);
    if (key == -1) {
        free(offsets);
        pthread_rwlock_unlock(&collection->rwlock);
        return;
    }

    size_t record_size = sizeof(Record) + offset_count * sizeof(int);
    if (collection->total_memory_usage + record_size > collection->max_memory_usage) {
        remove_lru_record(collection, record_size);
    }

    Node* new_node = create_node(key, offsets, offset_count);
    if (!new_node) {
        free(offsets);
        pthread_rwlock_unlock(&collection->rwlock);
        return;
    }

    collection->total_memory_usage += record_size;

    // Insert at the head for LRU management
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_rwlock_unlock(&collection->rwlock);
}

void remove_lru_record(RecordCollection* collection, size_t required_space) {
    if (!collection->head) return;

    Node** current = &collection->head;
    while (*current && (collection->total_memory_usage - sizeof(Node) - (*current)->record.offset_count * sizeof(int) < required_space)) {
        current = &(*current)->next;
    }

    if (*current) {
        Node* to_remove = *current;
        *current = to_remove->next;

        pthread_mutex_lock(&to_remove->lock);
        collection->total_memory_usage -= (sizeof(Record) + to_remove->record.offset_count * sizeof(int));
        free_record(to_remove);
        pthread_mutex_unlock(&to_remove->lock);
    }
}

void destroy_collection(RecordCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free_record(current);
        current = next;
    }

    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}
