#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

#define MAX_AGE_SECONDS 3600

typedef enum {
    NF_MSG_TYPE_A,
    NF_MSG_TYPE_B,
    // Add more message types as needed
} NFAPI_MSG_TYPE;

typedef struct {
    NFAPI_MSG_TYPE type;
    int param1;
    int param2; 
    time_t timestamp; 
} NFAPI_MESSAGE_T;

typedef struct OffsetRecord {
    long offset_value;
    int key;
    time_t created_at;
} OffsetRecord;

typedef struct KeyRecord {
    int value;
    OffsetRecord *offset_record;
    volatile int ref_count; // Using volatile for atomic operations
} KeyRecord;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageList;

// Initialize message list
int init_message_list(MessageList *list, size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > SIZE_MAX / sizeof(NFAPI_MESSAGE_T)) {
        return -1; // Invalid capacity
    }

    list->messages = malloc(initial_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!list->messages) {
        return -1; // Memory allocation failed
    }

    list->capacity = initial_capacity;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);

    return 0;
}

// Add a message to the list
int add_message(MessageList *list, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_MESSAGE_T *new_messages = realloc(list->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
        if (!new_messages) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->messages = new_messages;
        list->capacity = new_capacity;
    }

    list->messages[list->count++] = message;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Remove a message by index
int remove_message(MessageList *list, size_t index) {
    if (index >= list->count) {
        return -1; // Index out of bounds
    }

    pthread_mutex_lock(&list->lock);

    memmove(&list->messages[index], &list->messages[index + 1],
            (list->count - index - 1) * sizeof(NFAPI_MESSAGE_T));
    list->count--;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Validate message integrity
int validate_message_integrity(const NFAPI_MESSAGE_T *message) {
    if (!message) {
        return -1; // Null pointer
    }

    if (message->type < NF_MSG_TYPE_A || message->type > NF_MSG_TYPE_B) {
        return -1; // Invalid type
    }

    time_t current_time = time(NULL);
    double age_seconds = difftime(current_time, message->timestamp);

    if (age_seconds > MAX_AGE_SECONDS) {
        return -1; // Message too old
    }

    return 0;
}

// Initialize offset records array
int init_offset_records(OffsetRecord **offsets, size_t num_offsets) {
    if (num_offsets == 0 || num_offsets > SIZE_MAX / sizeof(OffsetRecord)) {
        return -1; // Invalid number of offsets
    }

    *offsets = malloc(num_offsets * sizeof(OffsetRecord));
    if (!(*offsets)) {
        return -1; // Memory allocation failed
    }

    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i].created_at = current_time;
    }

    return 0;
}

// Initialize key records array with random values and thread safety
int init_key_records(KeyRecord **key_records, size_t num_keys, OffsetRecord *offsets) {
    if (num_keys == 0 || num_keys > SIZE_MAX / sizeof(KeyRecord)) {
        return -1; // Invalid number of keys
    }

    *key_records = malloc(num_keys * sizeof(KeyRecord));
    if (!(*key_records)) {
        return -1; // Memory allocation failed
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < num_keys; ++i) {
        (*key_records)[i].value = rand() % 101; // Random value between 0 and 100
        (*key_records)[i].offset_record = &offsets[i]; // Simple direct assignment for demonstration

        pthread_mutex_lock(&lock);
        (*key_records)[i].ref_count = 1;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}

int main() {
    MessageList list;
    if (init_message_list(&list, 10) != 0) {
        fprintf(stderr, "Failed to initialize message list\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_MESSAGE_T msg = { .type = NF_MSG_TYPE_A, .param1 = 1, .param2 = 2, .timestamp = time(NULL) };
    if (add_message(&list, msg) != 0) {
