```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <queue>
#include <condition_variable>
#include <future>
#include <chrono>
#include <arpa/inet.h>
#include <netdb.h>

// Cache entry for DNS resolution
struct CacheEntry {
    std::string hostname;
    u_char ip[4];
    time_t last_accessed;

    CacheEntry(const std::string& host, const u_char* resolved_ip)
        : hostname(host) {
        memcpy(ip, resolved_ip, 4);
        last_accessed = std::time(nullptr);
    }
};

// DNS cache with LRU eviction
class DnsCache {
public:
    DnsCache(size_t max_size) : max_size_(max_size) {}

    bool get(const std::string& hostname, u_char* ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(hostname);
        if (it != cache_.end()) {
            // Update access time
            it->second.last_accessed = std::time(nullptr);
            memcpy(ip, it->second.ip, 4);
            return true;
        }
        return false;
    }

    void put(const std::string& hostname, const u_char* ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (cache_.size() >= max_size_) {
            evict();
        }
        cache_[hostname] = CacheEntry(hostname, ip);
    }

private:
    void evict() {
        // Evict the least recently used entry
        auto lru_it = std::min_element(cache_.begin(), cache_.end(),
                                       [](const auto& a, const auto& b) {
                                           return a.second.last_accessed < b.second.last_accessed;
                                       });
        if (lru_it != cache_.end()) {
            cache_.erase(lru_it);
        }
    }

    size_t max_size_;
    std::unordered_map<std::string, CacheEntry> cache_;
    mutable std::mutex mutex_;
};

// DNS resolver with asynchronous behavior
class AsyncDnsResolver {
public:
    AsyncDnsResolver() {}

    void resolve(const std::string& hostname, std::promise<u_char[4]>* promise) {
        thread_ = std::thread(&AsyncDnsResolver::resolveImpl, this, hostname, promise);
    }

private:
    void resolveImpl(const std::string& hostname, std::promise<u_char[4]> *promise) {
        struct addrinfo hints{}, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;

        int err = getaddrinfo(hostname.c_str(), nullptr, &hints, &res);
        if (err == 0 && res != nullptr) {
            struct sockaddr_in* ipv4 = reinterpret_cast<struct sockaddr_in*>(res->ai_addr);
            u_char ip[4];
            memcpy(ip, &(ipv4->sin_addr), sizeof(ipv4->sin_addr));
            promise->set_value(ip);
        } else {
            promise->set_exception(std::make_error_condition(err));
        }

        freeaddrinfo(res);
    }

    std::thread thread_;
};

// Log utility for debugging and monitoring
void log(const std::string& message) {
    static std::mutex log_mutex;
    std::lock_guard<std::mutex> lock(log_mutex);
    auto now = std::chrono::system_clock::now();
    std::time_t now_time = std::chrono::system_clock::to_time_t(now);
    std::cout << "[" << std::ctime(&now_time) << "] " << message << std::endl;
}

// Process a single file
void processFile(const std::string& filename, DnsCache& cache, AsyncDnsResolver& resolver) {
    std::ifstream infile(filename);
    if (!infile.is_open()) {
        log("Failed to open file: " + filename);
        return;
    }

    std::string line;
    while (std::getline(infile, line)) {
        std::istringstream iss(line);
        std::vector<std::string> tokens{std::istream_iterator<std::string>{iss}, std::istream_iterator<std::string>{}};

        double numeric_sum = 0.0;
        int count = 0;

        for (size_t i = 0; i < tokens.size(); ++i) {
            if (isdigit(tokens[i][0]) || (tokens[i][0] == '-' && isdigit(tokens[i][1]))) {
                numeric_sum += std::stod(tokens[i]);
                ++count;
            } else {
                u_char ip[4] = {0};
                if (!cache.get(tokens[i], ip)) {
                    log("Resolving hostname: " + tokens[i]);
                    auto promise = new std::promise<u_char[4]>();
                    resolver.resolve(tokens[i], promise);
                    try {
                        promise->get_future().wait();
                        cache.put(tokens[i], promise->get());
                    } catch (...) {
                        delete promise;
                    }
                }

                memcpy(&ip, ip, 4); // Assume IP resolution gives us valid bytes
                numeric_sum += reinterpret_cast<int*>(ip)[0]; // Simplified conversion for example
            }
        }

        if (count > 0) {
            double average = numeric_sum / count;
            log("Averaged line: " + line + ", Average: " + std::to_string(average));
        } else {
            log("No numeric fields in line: " + line);
        }
    }

    infile.close();
}

// Main function to run the distributed text processing utility
int main() {
    const size_t num_threads = std::thread::hardware_concurrency();
    DnsCache cache(1000); // Example cache size limit
    AsyncDnsResolver resolver;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < num_threads; ++i) {
        threads.emplace_back([&cache, &resolver] {
            // Assuming we have a list of files to process
            std::vector<std::string> filenames = {"file1.txt", "file2.txt"}; // Example filenames

            for (const auto& filename : filenames) {
                processFile(filename, cache, resolver);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

