#define MAX_MEMORY 1024 * 1024 // Maximum memory limit (1MB for example)
#define CACHE_SIZE 10

typedef struct {
    long offset;
    int key;
} OffsetRecord;

typedef struct {
    int value;
    OffsetRecord* offset_ptr;
} KeyRecord;

typedef struct {
    int random_value;
} RandomValue;

typedef struct MemoryPool {
    void* start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool offset_pool, key_pool;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pools(size_t offset_size, size_t key_record_size) {
    pthread_mutex_init(&offset_pool.lock, NULL);
    pthread_mutex_init(&key_pool.lock, NULL);

    offset_pool.start = malloc(offset_size * CACHE_SIZE);
    offset_pool.size = offset_size * CACHE_SIZE;
    if (!offset_pool.start) abort();

    key_pool.start = malloc(key_record_size * CACHE_SIZE);
    key_pool.size = key_record_size * CACHE_SIZE;
    if (!key_pool.start) {
        free(offset_pool.start);
        abort();
    }
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    void* block = malloc(size);
    if (block && (size <= pool->size)) {
        pool->size -= size;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void deallocate_to_pool(MemoryPool* pool, void* ptr, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (ptr && (size <= pool->size + size)) {
        free(ptr);
        pool->size += size;
    }

    pthread_mutex_unlock(&pool->lock);
}

OffsetRecord* allocate_offset_records(size_t count) {
    size_t offset_size = sizeof(OffsetRecord);
    OffsetRecord* offsets = (OffsetRecord*)allocate_from_pool(&offset_pool, count * offset_size);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for OffsetRecords\n");
        return NULL;
    }
    return offsets;
}

KeyRecord* allocate_key_records(size_t count, size_t offset_count) {
    size_t key_record_size = sizeof(KeyRecord);
    KeyRecord* keys = (KeyRecord*)allocate_from_pool(&key_pool, count * key_record_size);
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for KeyRecords\n");
        return NULL;
    }

    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < count; ++i) {
        keys[i].value = rand();
        if (i < offset_count) {
            keys[i].offset_ptr = &keys[i]; // Example: Pointing to itself
        } else {
            fprintf(stderr, "Index out of bounds for OffsetRecords\n");
            keys[i].offset_ptr = NULL;
        }
    }

    pthread_mutex_unlock(&global_lock);
    return keys;
}

RandomValue* allocate_random_values(size_t count) {
    size_t random_value_size = sizeof(RandomValue);
    RandomValue* values = (RandomValue*)malloc(count * random_value_size);
    if (!values || (count * random_value_size > MAX_MEMORY)) {
        fprintf(stderr, "Memory allocation failed for RandomValues\n");
        return NULL;
    }

    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < count; ++i) {
        values[i].random_value = rand();
    }

    pthread_mutex_unlock(&global_lock);
    return values;
}

void cleanup() {
    free(offset_pool.start);
    free(key_pool.start);
    pthread_mutex_destroy(&offset_pool.lock);
    pthread_mutex_destroy(&key_pool.lock);
    pthread_mutex_destroy(&global_lock);
}

int main() {
    size_t offset_count, key_count, random_value_count;

    printf("Enter number of OffsetRecords: ");
    if (scanf("%zu", &offset_count) != 1 || offset_count * sizeof(OffsetRecord) > MAX_MEMORY) {
        fprintf(stderr, "Invalid input for OffsetRecords\n");
        return EXIT_FAILURE;
    }

    printf("Enter number of KeyRecords: ");
    if (scanf("%zu", &key_count) != 1 || key_count * sizeof(KeyRecord) > MAX_MEMORY) {
        fprintf(stderr, "Invalid input for KeyRecords\n");
        return EXIT_FAILURE;
    }

    printf("Enter number of RandomValues: ");
    if (scanf("%zu", &random_value_count) != 1 || random_value_count * sizeof(RandomValue) > MAX_MEMORY) {
        fprintf(stderr, "Invalid input for RandomValues\n");
        return EXIT_FAILURE;
    }

    initialize_memory_pools(offset_count * sizeof(OffsetRecord), key_count * sizeof(KeyRecord));

    OffsetRecord* offsets = allocate_offset_records(offset_count);
    KeyRecord* keys = allocate_key_records(key_count, offset_count);
    RandomValue* random_values = allocate_random_values(random_value_count);

    if (offsets && keys && random_values) {
        // Use the allocated structures
    }

    cleanup();
    return EXIT_SUCCESS;
}
