#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define structures
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging system
typedef enum { LOG_LEVEL_NONE, LOG_LEVEL_INFO, LOG_LEVEL_ERROR } LogLevel;

static LogLevel current_log_level = LOG_LEVEL_INFO;

void log_message(LogLevel level, const char *format, ...) {
    if (level > current_log_level) return;

    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

// Mutex for synchronization
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic list management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t capacity;
    size_t count;
} NFAPIDynamicList;

NFAPIDynamicList* create_list(size_t initial_capacity) {
    NFAPIDynamicList *dynamic_list = malloc(sizeof(NFAPIDynamicList));
    if (!dynamic_list) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for dynamic list");
        return NULL;
    }

    dynamic_list->list = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_list->list) {
        free(dynamic_list);
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for list elements");
        return NULL;
    }

    dynamic_list->capacity = initial_capacity;
    dynamic_list->count = 0;

    log_message(LOG_LEVEL_INFO, "Dynamic list created with capacity %zu", initial_capacity);

    return dynamic_list;
}

void add_pdu(NFAPIDynamicList *dynamic_list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list_mutex);
    if (dynamic_list->count >= dynamic_list->capacity) {
        size_t new_capacity = dynamic_list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(dynamic_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            log_message(LOG_LEVEL_ERROR, "Memory reallocation failed for list expansion");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        dynamic_list->list = new_list;
        dynamic_list->capacity = new_capacity;
    }

    dynamic_list->list[dynamic_list->count++] = pdu;

    log_message(LOG_LEVEL_INFO, "Added PDU with RX_UE_INFORMATION_TAG %d and RNTI %d", 
                pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);

    pthread_mutex_unlock(&list_mutex);
}

void destroy_list(NFAPIDynamicList *dynamic_list) {
    if (dynamic_list) {
        free(dynamic_list->list);
        free(dynamic_list);
        log_message(LOG_LEVEL_INFO, "Dynamic list destroyed");
    }
}

// Thread function to simulate concurrent access
void* thread_function(void *arg) {
    NFAPIDynamicList *dynamic_list = (NFAPIDynamicList*)arg;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu.RNTI = rand() % 1000;
    pdu.crc_tag.CRCFLAG = rand() % 2; // Random CRC flag

    add_pdu(dynamic_list, pdu);

    return NULL;
}

// Performance analysis tool
void performance_analysis(size_t input_size, int num_threads) {
    NFAPIDynamicList *dynamic_list = create_list(input_size);
    if (!dynamic_list) return;

    pthread_t threads[num_threads];
    clock_t start_time = clock();

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, dynamic_list);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    log_message(LOG_LEVEL_INFO, "Performance analysis completed: %zu elements processed by %d threads in %.2f seconds",
                dynamic_list->count, num_threads, time_taken);

    destroy_list(dynamic_list);
}

int main() {
    srand(time(NULL));
    performance_analysis(10, 4); // Example usage

    return 0;
}
