// Function implementations

void initialize_memory_pool(MemoryPool *mp, size_t size) {
    mp->pool = malloc(size);
    if (!mp->pool) {
        log_event("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    void *ptr = (char*)mp->pool + mp->offset;
    if (mp->offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mp->lock);
        log_event("Memory pool exhausted");
        return NULL;
    }
    mp->offset += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void deallocate_to_pool(MemoryPool *mp, void *ptr, size_t size) {
    // Implement a simple mark-and-sweep or deferred compaction mechanism
    log_event("Memory pool deallocation not implemented");
}

Session* create_session(long session_id, const char *client_ip, const char *metadata) {
    Session *session = (Session*)allocate_from_pool(&memory_pool, sizeof(Session));
    if (!session) return NULL;

    session->session_id = session_id;
    strncpy(session->client_ip, client_ip, sizeof(session->client_ip) - 1);
    time(&session->timestamp);
    session->reference_count = 0;
    strncpy(session->metadata, metadata, sizeof(session->metadata) - 1);

    session->records = NULL; // Initially no records
    session->record_count = 0;

    return session;
}

int add_record(Session *session, long offset, int key, const char *data) {
    if (!session || !data) return -1;
    Record *new_record = (Record*)allocate_from_pool(&memory_pool, sizeof(Record));
    if (!new_record) return -2;

    new_record->offset = offset;
    new_record->key = key;
    strncpy(new_record->buffer, data, SESSION_BUFFER_SIZE - 1);

    // Reallocate memory for records array and add the new record
    session->records = (Record*)realloc(session->records, sizeof(Record) * (session->record_count + 1));
    if (!session->records) {
        deallocate_to_pool(&memory_pool, new_record, sizeof(Record));
        return -3;
    }

    session->records[session->record_count++] = *new_record;
    return 0;
}

Record* find_record_by_key(Session *session, int key) {
    if (!session) return NULL;
    for (size_t i = 0; i < session->record_count; ++i) {
        if (session->records[i].key == key)
            return &session->records[i];
    }
    return NULL;
}

void remove_record(Session *session, Record *record) {
    if (!session || !record) return;

    for (size_t i = 0; i < session->record_count; ++i) {
        if (&session->records[i] == record) {
            // Shift records to fill the gap
            memmove(&session->records[i], &session->records[i + 1],
                    sizeof(Record) * (session->record_count - i - 1));

            session->record_count--;
            deallocate_to_pool(&memory_pool, record, sizeof(Record));
            return;
        }
    }
}

void increment_reference_count(Session *session) {
    if (session)
        session->reference_count++;
}

void decrement_reference_count_and_destroy_if_zero(Session *session) {
    if (session && --session->reference_count == 0) {
        for (size_t i = 0; i < session->record_count; ++i) {
            deallocate_to_pool(&memory_pool, &session->records[i], sizeof(Record));
        }
        free(session->records);
        deallocate_to_pool(&memory_pool, session, sizeof(Session));
    }
}

int serialize_sessions(const Session **sessions, size_t session_count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&session_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < session_count; ++i) {
        Session *session = sessions[i];
        size_t rec_count = session->record_count;
        fwrite(&session->session_id, sizeof(long), 1, file);
        fwrite(session->client_ip, sizeof(char), strlen(session->client_ip) + 1, file);
        fwrite(&session->timestamp, sizeof(time_t), 1, file);
        fwrite(&session->reference_count, sizeof(unsigned int), 1, file);
        fwrite(session->metadata, sizeof(char), strlen(session->metadata) + 1, file);

        fwrite(&rec_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < rec_count; ++j) {
            fwrite(&session->records[j].offset, sizeof(long), 1, file);
            fwrite(&session->records[j].key, sizeof(int), 1, file);
            fwrite(session->records[j].buffer, sizeof(char), SESSION_BUFFER_SIZE, file);
        }
    }

    fclose(file);
    return 0;
}

int deserialize_sessions(Session ***sessions, size_t *session_count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    Session **temp_sessions = malloc(10 * sizeof(Session*)); // Initial allocation
    if (!temp_sessions) return -2;

    fread(session_count, sizeof(size_t), 1, file);
    size_t allocated_size = 10;
    while (*session_count > allocated_size / 2) {
        temp_sessions = realloc(temp_sessions, (allocated_size *= 2) * sizeof(Session*));
        if (!temp_sessions) return -3;
    }

    for (size_t i = 0; i < *session_count; ++i) {
        Session *session = create_session(0L, "", "");
        if (!session) { // Error handling
            while (i-- > 0) decrement_reference_count_and_destroy_if_zero(temp_sessions[i]);
            free(temp_sessions);
            return -4;
        }

        fread(&session->session_id, sizeof(long), 1, file);
        fread(session->client_ip, sizeof(char), sizeof(session->client_ip), file);
        fread(&session->timestamp, sizeof(time_t), 1, file);
        fread(&session->reference_count, sizeof(unsigned int), 1, file);
        session->metadata[0] = '\0';
        fread(session->metadata, sizeof(char), sizeof(session->metadata) - 1, file);

        size_t rec_count;
        fread(&rec_count, sizeof(size_t), 1, file);
        session->records = malloc(rec_count * sizeof(Record));
        if (!session->records) {
            decrement_reference_count_and_destroy_if_zero(session);
            while (i-- > 0) decrement_reference_count_and_destroy_if_zero(temp_sessions[i]);
            free(temp_sessions);
            return -5;
        }
        session->record_count = rec_count;

        for (size_t j = 0; j < rec_count; ++j) {
            fread(&session->records[j].offset, sizeof(long), 1, file);
            fread(&session->records[j].key, sizeof(int), 1, file);
            fread(session->records[j].buffer, sizeof(char), SESSION_BUFFER_SIZE, file);
        }

        temp_sessions[i] = session;
    }

    fclose(file);
    *sessions = temp_sessions;
    return 0;
}

Session* find_session_by_id(long session_id, Session **sessions, size_t session_count) {
    for (size_t i = 0; i < session_count; ++i) {
        if (sessions[i]->session_id == session_id)
            return sessions[i];
    }
    return NULL;
}

Session* find_sessions_by_ip(const char *client_ip, Session **sessions, size_t session_count) {
    for (size_t i = 0; i < session_count; ++i) {
        if (strcmp(sessions[i]->client_ip, client_ip) == 0)
            return sessions[i];
    }
    return NULL;
}

int query_records_by_reference(Session **sessions, size_t session_count, unsigned int ref_count) {
    for (size_t i = 0; i < session_count; ++i) {
        if (sessions[i]->reference_count == ref_count)
            log_event("Session found with matching reference count");
    }
    return 0;
}
