int init_event_collection(EventCollection *collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->events = (NetworkEvent *)malloc(MAX_EVENTS * sizeof(NetworkEvent));
    if (!collection->events) {
        log_operation("ERROR", "Failed to allocate memory for events");
        return -1;
    }
