    if (collection->count >= MAX_EVENTS) {
        log_operation("ERROR", "Event collection full");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    NetworkEvent *event = &collection->events[collection->count];
    time(&event->timestamp);
    strncpy(event->eventType, eventType, sizeof(event->eventType));
    strncpy(event->nni, nni, sizeof(event->nni));

