#define MAX_PATH_LENGTH 1024
#define MEMORY_LIMIT (1 << 30) // 1GB

typedef struct File {
    char path[MAX_PATH_LENGTH];
    time_t last_modified;
    int group_id;
    int is_device;
    struct Directory* dir;
} File;

typedef struct DirectoryEntry {
    char name[MAX_PATH_LENGTH];
    struct List* files;
    int read_only;
    unsigned long disk_space_used;
} DirectoryEntry;

typedef struct Symlink {
    char path[MAX_PATH_LENGTH];
    char target_path[MAX_PATH_LENGTH];
    struct Directory* dir;
} Symlink;

typedef struct Archive {
    char archive_name[MAX_PATH_LENGTH];
    struct List* files;
} Archive;

typedef struct DeviceFile {
    char path[MAX_PATH_LENGTH];
    int device_id;
    char metadata[256];
    struct Directory* dir;
} DeviceFile;

typedef struct Node {
    void* data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t size;
} List;

typedef struct LinkedList {
    List* regular_files;
    List* directories;
    List* archives;
    List* symlinks;
    List* device_files;
    size_t total_allocated;
} LinkedList;

LinkedList* initialize_lists() {
    // Allocate and initialize the linked lists
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    for (int i = 0; i < 5; ++i) {
        List* lst = malloc(sizeof(List));
        if (!lst) { free(list); return NULL; }
        lst->head = NULL;
        lst->size = 0;
        ((void**)(&list->regular_files))[i] = lst;
    }

    list->total_allocated = 0;
    return list;
}

int validate_and_categorize(const char* path, LinkedList* lists) {
    struct stat st;
    if (lstat(path, &st) != 0) {
        perror("Failed to get file status");
        return -1;
    }

    File* file = malloc(sizeof(File));
    if (!file || lists->total_allocated >= MEMORY_LIMIT) {
        free(file);
        fprintf(stderr, "Memory allocation failed or limit reached\n");
        return -1;
    }

    strncpy(file->path, path, MAX_PATH_LENGTH);
    file->last_modified = st.st_mtime;
    file->group_id = st.st_gid;
    file->is_device = S_ISBLK(st.st_mode) || S_ISCHR(st.st_mode);
    file->dir = NULL;

    lists->total_allocated += sizeof(File);

    Node* node = malloc(sizeof(Node));
    if (!node) {
        free(file);
        fprintf(stderr, "Node allocation failed\n");
        return -1;
    }

    node->data = file;
    node->next = ((List*)lists->regular_files)->head;
    ((List*)lists->regular_files)->head = node;
    ((List*)lists->regular_files)->size++;

    if (S_ISDIR(st.st_mode)) {
        // Move to directories list
    } else if (S_ISLNK(st.st_mode)) {
        // Move to symlinks list
    } else if (S_ISREG(st.st_mode) && is_archive(path)) {
        // Move to archives list
    } else if (file->is_device) {
        // Move to device files list
    }

    return 0;
}

void serialize_data_structure(const LinkedList* lists, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) { perror("Failed to open file for writing"); return; }

    for (int i = 0; i < 5; ++i) {
        List* list = ((void**)(&lists->regular_files))[i];
        Node* node = list->head;
        while (node) {
            fwrite(node->data, sizeof(File), 1, file);
            node = node->next;
        }
    }

    fclose(file);
}

void deserialize_data_structure(LinkedList** lists, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) { perror("Failed to open file for reading"); return; }

    File buffer;
    while (fread(&buffer, sizeof(File), 1, file)) {
        LinkedList* lists = initialize_lists();
        validate_and_categorize(buffer.path, lists);
    }

    fclose(file);
}

void traverse_directory(const char* path, LinkedList* lists) {
    DIR* dir = opendir(path);
    if (!dir) { perror("Failed to open directory"); return; }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        validate_and_categorize(full_path, lists);
    }

    closedir(dir);
}

void update_timestamps(const char* path) {
    DIR* dir = opendir(path);
    if (!dir) { perror("Failed to open directory"); return; }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        struct stat st;
        if (lstat(full_path, &st) != 0) {
            perror("Failed to get file status");
            continue;
        }

        File* file = find_file_in_lists(full_path);
        if (!file) continue;

        file->last_modified = st.st_mtime;

        if (S_ISDIR(st.st_mode)) update_timestamps(full_path);
    }

    closedir(dir);
}

void monitor_disk_usage(const char* path, unsigned long threshold) {
    DIR* dir = opendir(path);
    if (!dir) { perror("Failed to open directory"); return; }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        struct stat st;
        if (lstat(full_path, &st) != 0) {
            perror("Failed to get file status");
            continue;
        }

        DirectoryEntry* dir_entry = find_directory_in_lists(path);
        if (!dir_entry) continue;

        dir_entry->disk_space_used += st.st_size;

        if (dir_entry->disk_space_used > threshold)
            printf("Disk space usage exceeded for %s\n", path);

        if (S_ISDIR(st.st_mode)) monitor_disk_usage(full_path, threshold);
    }

    closedir(dir);
}

void generate_summary_report(const LinkedList* lists) {
    int total_files = 0;
    for (int i = 0; i < 5; ++i) {
        List* list = ((void**)(&lists->regular_files))[i];
        total_files += list->size;
    }

    printf("Total files: %d\n", total_files);
}

int main() {
    LinkedList* lists = initialize_lists();
    if (!lists) { fprintf(stderr, "Failed to initialize lists\n"); return 1; }

    char path[MAX_PATH_LENGTH];
    while (fgets(path, sizeof(path), stdin)) {
        path[strcspn(path, "\n")] = '\0'; // Remove newline character
        validate_and_categorize(path, lists);
    }

    generate_summary_report(lists);

    serialize_data_structure(lists, "data.bin");
    deserialize_data_structure(&lists, "data.bin");

    return 0;
