#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_PATH_LENGTH 1024
#define MAX_RECORDS 1000

typedef struct {
    int metadata;
} UserProfile;

typedef struct {
    int value;
    char buffer[256];
    char *path;
    int metadata;
    UserProfile *userProfile;
} Record;

typedef struct {
    long fdOffsets[MAX_RECORDS];
    int dirIndices[MAX_RECORDS];
    Record records[MAX_RECORDS];
    char *paths[MAX_RECORDS];
    int metadataAttributes[MAX_RECORDS];
} FileSystemData;

int totalRecords = 0;
FileSystemData fsData;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void logOperation(const char *operation, const char *path) {
    FILE *logFile = fopen("operations.log", "a");
    if (logFile) {
        fprintf(logFile, "%s: %s\n", operation, path);
        fclose(logFile);
    }
}

int calculateDepth(const char *basePath, int currentDepth) {
    struct stat statbuf;
    if (stat(basePath, &statbuf) != 0 || !S_ISDIR(statbuf.st_mode)) return currentDepth;

    DIR *dir = opendir(basePath);
    if (!dir) return currentDepth;

    int maxDepth = currentDepth;
    char pathBuffer[MAX_PATH_LENGTH];
    struct dirent *entry;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        snprintf(pathBuffer, sizeof(pathBuffer), "%s/%s", basePath, entry->d_name);
        int depth = calculateDepth(pathBuffer, currentDepth + 1);
        if (depth > maxDepth) maxDepth = depth;
    }

    closedir(dir);
    return maxDepth;
}

void processFilePath(const char *filePath) {
    pthread_mutex_lock(&mutex);

    if (totalRecords >= MAX_RECORDS) {
        fprintf(stderr, "Maximum record count exceeded.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    fsData.fdOffsets[totalRecords] = -1; // Placeholder for file descriptor
    fsData.dirIndices[totalRecords] = totalRecords;

    Record *record = &fsData.records[totalRecords];
    record->value = 0;
    strncpy(record->buffer, "Metadata placeholder", sizeof(record->buffer));
    record->path = strdup(filePath);
    record->metadata = 0; // Placeholder for metadata
    record->userProfile = NULL;

    fsData.metadataAttributes[totalRecords] = 1; // Example attribute

    totalRecords++;
    pthread_mutex_unlock(&mutex);

    int depth = calculateDepth(filePath, 0);
    logOperation("Process", filePath);

    printf("Path: %s has directory depth: %d\n", filePath, depth);
}

void serializeToFile(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(&fsData, sizeof(FileSystemData), 1, file);
    fclose(file);
}

void deserializeFromFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    fread(&fsData, sizeof(FileSystemData), 1, file);
    fclose(file);
}

void freeResources() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < totalRecords; ++i) {
        if (fsData.records[i].path) free(fsData.records[i].path);
    }

    pthread_mutex_unlock(&mutex);
}

void processPaths() {
    char buffer[MAX_PATH_LENGTH];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        buffer[strcspn(buffer, "\n")] = '\0';
        processFilePath(buffer);
    }
}

int main() {
    memset(&fsData, 0, sizeof(FileSystemData));
    totalRecords = 0;

    // Process paths from standard input
    processPaths();

    // Serialize data to file
    serializeToFile("filesystem_data.bin");

    // Free allocated resources
    freeResources();

    return 0;
}

