['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DOCS 1000000
#define MAX_KEYWORDS 500

typedef struct {
    char *text;
    char author[256];
    char date[20];
    char tags[1024];
} Document;

typedef struct {
    int doc_id;
    int keyword_index[MAX_KEYWORDS];
    int keyword_count;
} KeywordIndex;

typedef struct {
    Document documents[MAX_DOCS];
    KeywordIndex keyword_indices[MAX_DOCS];
    char metadata_fields[256][256]; // Flexible for predefined and user-defined
    pthread_mutex_t lock;
    int doc_count;
} CorpusManager;

typedef struct {
    int relevance_score;
    int doc_id;
} RankedDocument;

CorpusManager* init_corpus_manager() {
    CorpusManager *manager = (CorpusManager *)malloc(sizeof(CorpusManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->doc_count = 0;

    for (int i = 0; i < MAX_DOCS; i++) {
        manager->documents[i].text = NULL;
        manager->keyword_indices[i].keyword_count = 0;
    }

    return manager;
}

void add_document(CorpusManager *manager, const char *content, const char *author, const char *date, const char *tags) {
    pthread_mutex_lock(&manager->lock);

    if (manager->doc_count >= MAX_DOCS) {
        fprintf(stderr, "Document limit reached\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Document *doc = &manager->documents[manager->doc_count];
    doc->text = strdup(content);
    strncpy(doc->author, author, sizeof(doc->author));
    strncpy(doc->date, date, sizeof(doc->date));
    strncpy(doc->tags, tags, sizeof(doc->tags));

    KeywordIndex *index = &manager->keyword_indices[manager->doc_count];
    index->doc_id = manager->doc_count;
    // Example keyword indexing logic
    char *token = strtok((char *)content, " ");
    int count = 0;
    while (token && count < MAX_KEYWORDS) {
        index->keyword_index[count++] = hash_keyword(token);
        token = strtok(NULL, " ");
    }
    index->keyword_count = count;

    manager->doc_count++;
    pthread_mutex_unlock(&manager->lock);
}

void remove_document(CorpusManager *manager, int doc_id) {
    pthread_mutex_lock(&manager->lock);

    if (doc_id < 0 || doc_id >= manager->doc_count) {
        fprintf(stderr, "Invalid document ID\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    free(manager->documents[doc_id].text);
    memmove(&manager->documents[doc_id], &manager->documents[doc_id + 1],
            (manager->doc_count - doc_id - 1) * sizeof(Document));
    manager->doc_count--;

    pthread_mutex_unlock(&manager->lock);
}

int hash_keyword(const char *keyword) {
    // Simple hashing function for demonstration
    int hash = 0;
    while (*keyword) {
        hash = (hash << 5) + *keyword++;
    }
    return abs(hash % MAX_KEYWORDS);
}

void rank_documents(CorpusManager *manager, const char *query, RankedDocument *results) {
    pthread_mutex_lock(&manager->lock);

    int count = 0;
    for (int i = 0; i < manager->doc_count && count < MAX_DOCS; i++) {
        Document *doc = &manager->documents[i];
        KeywordIndex *index = &manager->keyword_indices[i];

        int relevance_score = calculate_relevance(doc, query, index);

        results[count].relevance_score = relevance_score;
        results[count++].doc_id = i;
    }

    // Sort results based on relevance score
    qsort(results, count, sizeof(RankedDocument), compare_ranked_documents);

    pthread_mutex_unlock(&manager->lock);
}

int calculate_relevance(Document *doc, const char *query, KeywordIndex *index) {
    int relevance_score = 0;
    // Example relevance calculation logic
    for (int i = 0; i < index->keyword_count; i++) {
        if (strstr(doc->text, query)) {
            relevance_score += 10; // Simple keyword match score
        }
    }
    return relevance_score;
}

int compare_ranked_documents(const void *a, const void *b) {
    RankedDocument *docA = (RankedDocument *)a;
    RankedDocument *docB = (RankedDocument *)b;
    return docB->relevance_score - docA->relevance_score;
}

void serialize_corpus(CorpusManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    fwrite(manager, sizeof(CorpusManager), 1, file);
    fclose(file);

    pthread_mutex_unlock(&manager->lock);
}

void deserialize_corpus(CorpusManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        return;
    }

    fread(manager, sizeof(CorpusManager), 1, file);
    fclose(file);
}
