void add_or_update_setting(ConfigHashTable *table, const char *key, const char *value, unsigned int version) {
    // Add or update a setting in the hash table
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key) % table->capacity; // Assume hash_function is defined elsewhere
    HashNode *node = table->buckets[index];
    while (node) {
        if (strcmp(node->setting.key, key) == 0) {
            free(node->setting.value);
            node->setting.value = strdup(value);
            node->setting.version = version;
            node->setting.last_modified = time(NULL);
            log_event(NULL /* Assume logging config is available */, INFO, "Updated setting");
            pthread_mutex_unlock(&table->lock);
            return;
        }
        node = node->next;
    }

    // If not found, add a new node
    HashNode *new_node = create_node(key, value, version);
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return; // Handle error appropriately
    }
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    log_event(NULL /* Assume logging config is available */, INFO, "Added new setting");

    pthread_mutex_unlock(&table->lock);
}

ConfigSetting* get_setting(ConfigHashTable *table, const char *key) {
