    HashNode *node = table->buckets[index];

    while (node) {
        if (strcmp(node->setting.key, key) == 0) {
            return &node->setting;
        }
        node = node->next;
    }

    return NULL; // Not found
}

void invalidate_outdated_settings(ConfigHashTable *table, unsigned int version_threshold) {
    // Invalidate settings based on a version threshold
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        HashNode *prev = NULL;

        while (node) {
            if (node->setting.version < version_threshold) {
                if (prev) {
                    prev->next = node->next;
                } else {
                    table->buckets[i] = node->next;
                }

                // Free the outdated setting
                free(node->setting.key);
                free(node->setting.value);
                free(node);
                log_event(NULL /* Assume logging config is available */, WARN, "Invalidated outdated setting");
            } else {
                prev = node;
            }

            node = node->next;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

