    size_t new_size = 2 * table->size;
    HashNode **new_buckets = calloc(new_size, sizeof(HashNode *));

    if (!new_buckets) {
        perror("Failed to allocate memory for resized hash buckets");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next_node = node->next;
            unsigned int new_index = hash_function(node->id, new_size);

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

