        for (auto endpoint : endpoints) {
            if (!asio::connect(asio::ip::tcp::socket(io_context), endpoint)) {
                server.connectionStatus = true;
                break;
            }
        }
    } catch (...) {
        server.connectionStatus = false;
    }
