    char* value;
} ResourceBundleItem;

int loadResourceBundleFromFile(const std::string& filename, std::unordered_map<std::string, std::string>& cache) {
    if (cache.find(filename) != cache.end()) return cache[filename].size();

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Failed to open resource bundle file: " << filename << std::endl;
        return 0;
    }

    int itemCount = 0;
    ResourceBundleItem* bundle = nullptr;
    char key[256], value[1024];

    while (file >> std::quoted(key) >> std::quoted(value)) {
        ++itemCount;

        if (!bundle) {
            bundle = (ResourceBundleItem*)malloc(itemCount * sizeof(ResourceBundleItem));
        } else {
            ResourceBundleItem* newBundle = (ResourceBundleItem*)realloc(bundle, itemCount * sizeof(ResourceBundleItem));
            if (newBundle) {
                bundle = newBundle;
            } else {
                std::cerr << "Memory allocation failed." << std::endl;
                free(bundle);
                return 0;
            }
        }

        bundle[itemCount - 1].key = strdup(key);
        bundle[itemCount - 1].value = strdup(value);

        cache[filename] += key; // Cache the keys for simplicity
    }

    file.close();

    if (bundle) {
        std::vector<std::thread> cleanupThreads;
        for (int i = 0; i < itemCount; ++i) {
            cleanupThreads.emplace_back([bundle, i]() { 
                free(bundle[i].key); 
                free(bundle[i].value);
            });
        }

        for (auto& t : cleanupThreads) {
            t.join();
        }

        free(bundle);
    }

    return itemCount;
}
