#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_PACKETS 1000000
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    int id;
    time_t timestamp;
    int status_flag;
    int value;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
    time_t expiration_threshold;
    FILE *log_file;
} PacketManager;

void log_message(PacketManager *manager, const char *message, int level) {
    if (level <= manager->log_level) {
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file);
    }
}

PacketManager* create_packet_manager(time_t expiration_threshold, const char *log_path, int log_level) {
    PacketManager *manager = malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->expiration_threshold = expiration_threshold;
    manager->log_file = fopen(log_path, "a");
    if (!manager->log_file) {
        free(manager);
        return NULL;
    }
    manager->log_level = log_level;

    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    fclose(manager->log_file);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_packet(PacketManager *manager, int id, int value) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->id == id) {
            log_message(manager, "Packet update", LOG_LEVEL_INFO);
            manager->packets[i]->value = value;
            manager->packets[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count >= MAX_PACKETS) {
        log_message(manager, "Max packets reached", LOG_LEVEL_INFO);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    DataPacket *packet = malloc(sizeof(DataPacket));
    packet->id = id;
    packet->value = value;
    packet->timestamp = time(NULL);
    packet->status_flag = 1;

    manager->packets[manager->count++] = packet;
    log_message(manager, "Packet added", LOG_LEVEL_INFO);

    pthread_mutex_unlock(&manager->lock);
}

DataPacket* get_packet(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->id == id) {
            DataPacket *packet = malloc(sizeof(DataPacket));
            memcpy(packet, manager->packets[i], sizeof(DataPacket));
            pthread_mutex_unlock(&manager->lock);
            return packet;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void purge_expired_packets(PacketManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if (difftime(current_time, manager->packets[i]->timestamp) > manager->expiration_threshold) {
            free(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], sizeof(DataPacket *) * (manager->count - i - 1));
            manager->count--;
            log_message(manager, "Expired packet purged", LOG_LEVEL_INFO);
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void find_largest_integer() {
    int n, largest = INT_MIN;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    if (n <= 0) return;

    int *numbers = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        scanf("%d", &numbers[i]);
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest integer: %d\n", largest);
    free(numbers);
}

void monitor_resources() {
    // Implement resource monitoring logic here
    log_message(NULL, "Resource monitoring", LOG_LEVEL_INFO);
}

void packet_management_system(PacketManager *manager) {
    pthread_t tid1, tid2;
    pthread_create(&tid1, NULL, (void *)find_largest_integer, NULL);
    pthread_create(&tid2, NULL, (void *)monitor_resources, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    // Simulate periodic packet updates and purges
    while (1) {
        add_packet(manager, rand() % 1000, rand() % 100);
        purge_expired_packets(manager);
        sleep(10);  // Adjust the timing as needed
    }
}

int main() {
    PacketManager *manager = create_packet_manager(3600, "packet_log.txt", LOG_LEVEL_DEBUG);

    if (manager) {
        packet_management_system(manager);
        destroy_packet_manager(manager);
    }

    return 0;
}
