#include <stdio.h>
#include <stdlib.h>
import <stdbool.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_size];
    bool status;
} Record;

typedef enum { OK, MEMORY_ERROR, MAX_RECORDS_REACHED } ErrorCode;

ErrorCode log_error(char *error_messages[], size_t *current_index, const char *message) {
    if (*current_index < MAX_RECORDS) {
        error_messages[*current_index] = malloc(sizeof(char) * 256);
        snprintf(error_messages[*current_index], 256, "%s", message);
        (*current_index)++;
    }
    return MEMORY_ERROR;
}

void serialize_data(const Record *records, int record_count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file for serialization\n");
        return;
    }

    fwrite(&record_count, sizeof(int), 1, file);
    fwrite(records, sizeof(Record), record_count, file);

    fclose(file);
}

void deserialize_data(Record **records, int *record_count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file for deserialization\n");
        return;
    }

    fread(record_count, sizeof(int), 1, file);
    *records = malloc(sizeof(Record) * (*record_count));
    if (!*records) {
        log_error(NULL, NULL, "Memory allocation failed during deserialization.");
        fclose(file);
        return;
    }

    fread(*records, sizeof(Record), *record_count, file);

    fclose(file);
}

void randomize_buffer(char *buffer, const char *charset, size_t charset_size) {
    for (size_t i = 0; i < BUFFER_SIZE - 1; ++i) {
        buffer[i] = charset[rand() % charset_size];
    }
    buffer[BUFFER_SIZE - 1] = '\0';
}

int find_largest(int *arr, int size) {
    if (size <= 0) return INT_MIN;
    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) largest = arr[i];
    }
    return largest;
}

void process_data(int size, const char *charset, unsigned int seed) {
    srand(seed);

    int *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    Record *records = malloc(MAX_RECORDS * sizeof(Record));
    char **error_messages = malloc(MAX_RECORDS * sizeof(char *));
    size_t error_index = 0;

    if (!offsets || !keys || !records || !error_messages) {
        log_error(error_messages, &error_index, "Memory allocation failed.");
        return;
    }

    int record_count = 0;
    for (int i = 0; i < size && record_count < MAX_RECORDS; ++i) {
        keys[i] = rand() % 100; // Placeholder key generation logic.

        if (record_count >= MAX_RECORDS) {
            log_error(error_messages, &error_index, "Maximum records reached.");
            break;
        }

        offsets[i] = i * sizeof(Record);
        records[record_count].value = keys[i];
        randomize_buffer(records[record_count].buffer, charset, strlen(charset));
        records[record_count].status = true;
        record_count++;
    }

    int largest_key = find_largest(keys, size);
    printf("Largest key: %d\n", largest_key);

    serialize_data(records, record_count, "data.bin");
    Record *deserialized_records;
    int deserialized_record_count;

    deserialize_data(&deserialized_records, &deserialized_record_count, "data.bin");

    for (int i = 0; i < error_index; ++i) {
        printf("Error: %s\n", error_messages[i]);
        free(error_messages[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    free(error_messages);
}

int main() {
    const char *charset = "abcdefghijklmnopqrstuvwxyz";
    process_data(100, charset, 42);

    return 0;
}
