#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>

// Define the structures
typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
#define MAX_NFAPIS 10000

NFAPI_CRC_INDICATION_PDU_T* nfaPis = NULL;
int current_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log_operation(const char *operation, int rnti) {
    printf("Operation: %s, RNTI: %d\n", operation, rnti);
}

// MD5 hash function
void compute_md5_hash(const unsigned char* data, size_t length, unsigned char output[MD5_DIGEST_LENGTH]) {
    MD5((unsigned char*)data, length, output);
}

int is_unique_rnti(uint16_t rnti) {
    for (int i = 0; i < current_count; ++i) {
        if (nfaPis[i].rnti == rnti) {
            return 0;
        }
    }
    return 1;
}

int add_nfa_pdu(NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    pthread_mutex_lock(&mutex);

    if (!is_unique_rnti(new_pdu->rnti)) {
        log_operation("Duplicate RNTI", new_pdu->rnti);
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Duplicate RNTI
    }

    if (current_count >= MAX_NFAPIS) {
        log_operation("Max NFAPIs reached", 0);
        pthread_mutex_unlock(&mutex);
        return -2; // Error: List is full
    }

    NFAPI_CRC_INDICATION_PDU_T* resized_list = realloc(nfaPis, (current_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!resized_list) {
        log_operation("Memory allocation failed", new_pdu->rnti);
        pthread_mutex_unlock(&mutex);
        return -3; // Error: Memory allocation failure
    }

    nfaPis = resized_list;

    memcpy(&nfaPis[current_count], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current_count++;

    log_operation("Added NFAPDU", new_pdu->rnti);

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

void free_resources() {
    pthread_mutex_lock(&mutex);
    if (nfaPis) {
        free(nfaPis);
        nfaPis = NULL;
        current_count = 0;
        log_operation("Deallocated NFAPDUs", 0);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.RNTI = 100}, .rnti = 200, {.CRCFLAG = rand() % 2}};

    if (add_nfa_pdu(&pdu1) == 0) {
        printf("PDU added successfully.\n");
    } else {
        fprintf(stderr, "Failed to add PDU.\n");
    }

    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    compute_md5_hash((unsigned const char*)"Example String", strlen("Example String"), md5_hash);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", md5_hash[i]);
    }
    printf("\n");

    free_resources();
    return 0;
}
```

This code provides a thread-safe implementation to manage a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring unique RNTI insertion and robust error handling. Logging is integrated for debugging purposes, and the MD5 hash function is included using OpenSSL's MD5 library.']

['Below is a C function that manages a dynamically allocated graph of `ResourceNodes`. It includes features for adding resources, updating attributes, querying availability, load balancing, and handling dependencies. The code also considers memory management, error checking, and dynamic resizing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *priority;
} task;

typedef struct {
    int id;
    char *type;
    int status;
    double utilization;
    pthread_mutex_t lock; // For thread safety
} ResourceNode;

// Function prototypes
void initializeResources(char **types, int *statuses, double *utilizations, int size);
void updateResource(ResourceNode *resources, int index, const char *type, int status, double utilization);
int queryAvailability(const ResourceNode *resources, int count, const char *type, double minUtilization, double maxUtilization);
void redistributeTasks(ResourceNode *resources, task *tasks, int resourceCount, int taskCount);
void resizeArrays(char ***types, int **statuses, double **utilizations, task ***tasks, int newSize);

// Main function to manage resources
void manageResources(int initialSize, int resizeFlag) {
    char **types = NULL;
    int *statuses = NULL;
    double *utilizations = NULL;
    task **tasks = NULL;
    ResourceNode *resources = NULL;

    // Allocate memory for arrays
    types = (char **)malloc(initialSize * sizeof(char *));
    statuses = (int *)malloc(initialSize * sizeof(int));
    utilizations = (double *)malloc(initialSize * sizeof(double));
    tasks = (task **)malloc(initialSize * sizeof(task *));
    resources = (ResourceNode *)malloc(initialSize * sizeof(ResourceNode));

    if (!types || !statuses || !utilizations || !tasks || !resources) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize arrays
    initializeResources(types, statuses, utilizations, initialSize);

    for (int i = 0; i < initialSize; ++i) {
        resources[i].id = i;
        resources[i].type = types[i];
        resources[i].status = statuses[i];
        resources[i].utilization = utilizations[i];
        pthread_mutex_init(&resources[i].lock, NULL);
    }

    // Populate tasks
    for (int i = 0; i < initialSize; ++i) {
        tasks[i] = (task *)malloc(sizeof(task));
        if (!tasks[i]) {
            fprintf(stderr, "Memory allocation failed for tasks\n");
            return;
        }
        tasks[i]->priority = strdup("medium"); // Example priority
    }

    // Simulate operations
    updateResource(resources, 0, "CPU", 1, 75.5);
    int availableCount = queryAvailability(resources, initialSize, "GPU", 0.2, 0.8);
    redistributeTasks(resources, (task *)tasks, initialSize, initialSize);

    // Resize arrays if needed
    if (resizeFlag) {
        resizeArrays(&types, &statuses, &utilizations, (task ***)&tasks, initialSize * 2);
    }

    // Free memory
    for (int i = 0; i < initialSize; ++i) {
        free(resources[i].type);
        pthread_mutex_destroy(&resources[i].lock);
        free(tasks[i]);
        free(tasks[i]->priority);
    }
    free(types);
    free(statuses);
    free(utilizations);
    free(tasks);
    free(resources);
}

void initializeResources(char **types, int *statuses, double *utilizations, int size) {
    for (int i = 0; i < size; ++i) {
        types[i] = strdup("type");
        statuses[i] = rand() % 2; // Random status
        utilizations[i] = ((double)rand() / RAND_MAX) * 100.0; // Random utilization
    }
}

void updateResource(ResourceNode *resources, int index, const char *type, int status, double utilization) {
    pthread_mutex_lock(&resources[index].lock);
    free(resources[index].type);
    resources[index].type = strdup(type);
    resources[index].status = status;
    resources[index].utilization = utilization;
    pthread_mutex_unlock(&resources[index].lock);
}

int queryAvailability(const ResourceNode *resources, int count, const char *type, double minUtilization, double maxUtilization) {
    int availableCount = 0;
    for (int i = 0; i < count; ++i) {
        if (strcmp(resources[i].type, type) == 0 && resources[i].utilization >= minUtilization && resources[i].utilization <= maxUtilization) {
            ++availableCount;
        }
    }
    return availableCount;
}

void redistributeTasks(ResourceNode *resources, task **tasks, int resourceCount, int taskCount) {
    for (int i = 0; i < taskCount; ++i) {
        // Example redistribution logic
        if (tasks[i]->priority && strcmp(tasks[i]->priority, "high") == 0) {
            for (int j = 0; j < resourceCount; ++j) {
                pthread_mutex_lock(&resources[j].lock);
                if (resources[j].utilization < 50.0) { // Example threshold
                    tasks[i]->priority = strdup("medium");
                    resources[j].utilization += 10.0;
                }
                pthread_mutex_unlock(&resources[j].lock);
            }
        }
    }
}

void resizeArrays(char ***types, int **statuses, double **utilizations, task ***tasks, int newSize) {
    *types = (char **)realloc(*types, newSize * sizeof(char *));
    *statuses = (int *)realloc(*statuses, newSize * sizeof(int));
    *utilizations = (double *)realloc(*utilizations, newSize * sizeof(double));
    *tasks = (task **)realloc(*tasks, newSize * sizeof(task *));

    for (int i = *types ? (newSize - 1) : 0; i < newSize; ++i) {
        (*types)[i] = strdup("type");
        (*statuses)[i] = rand() % 2;
        (*utilizations)[i] = ((double)rand() / RAND_MAX) * 100.0;

        (*tasks)[i] = (task *)malloc(sizeof(task));
        if (!(*tasks)[i]) {
            fprintf(stderr, "Memory allocation failed for tasks\n");
            return;
        }
        (*tasks)[i]->priority = strdup("medium");
    }
}

int main() {
    manageResources(1000, 1);
    return 0;
}
```

This code provides a basic structure to manage resources in a dynamically allocated graph. It includes thread safety mechanisms and handles memory allocation errors gracefully. The `manageResources` function can be expanded or modified based on specific requirements or constraints of the system it will integrate with.']

