#include <time.h>
#include <ctype.h>
#include <jansson.h> // JSON library

#define MAX_EVENT_SIZE 1024
#define INITIAL_ARRAY_CAPACITY 16
#define EVENT_METADATA_LENGTH 10

typedef struct {
    time_t timestamp;
    char eventType[64];
    int uniqueKey;
    char *metadata; // JSON formatted
} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} EventManager;

EventManager* create_event_manager() {
    EventManager *em = (EventManager *)malloc(sizeof(EventManager));
    em->events = (TrafficEvent *)malloc(INITIAL_ARRAY_CAPACITY * sizeof(TrafficEvent));
    em->count = 0;
    em->capacity = INITIAL_ARRAY_CAPACITY;
    pthread_mutex_init(&em->mutex, NULL);
    pthread_cond_init(&em->cond_var, NULL);
    return em;
}

void free_event_manager(EventManager *em) {
    for (size_t i = 0; i < em->count; ++i) {
        free(em->events[i].metadata);
    }
    free(em->events);
    pthread_mutex_destroy(&em->mutex);
    pthread_cond_destroy(&em->cond_var);
    free(em);
}

int generate_random_status() {
    return (rand() % 2 == 0) ? 'A' : 'B';
}

char* generate_random_string(size_t length) {
    char *str = (char *)malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + (rand() % 26);
    }
    str[length] = '\0';
    return str;
}

void create_random_event(TrafficEvent *event, long offset) {
    event->timestamp = time(NULL) + offset;
    snprintf(event->eventType, sizeof(event->eventType), "Type_%ld", offset);
    event->uniqueKey = rand();

    // Random record
    int random_value = rand();
    char status = generate_random_status();
    char *random_string = generate_random_string(EVENT_METADATA_LENGTH);

    json_t *root = json_object();
    json_object_set_new(root, "value", json_integer(random_value));
    json_object_set_new(root, "status", json_string(&status, 1));
    json_object_set_new(root, "text", json_string(random_string));

    event->metadata = strdup(json_dumps(root, JSON_COMPACT));
    json_decref(root);

    free(random_string);
}

void resize_array(EventManager *em) {
    size_t new_capacity = em->capacity * 2;
    TrafficEvent *new_events = (TrafficEvent *)realloc(em->events, new_capacity * sizeof(TrafficEvent));

    if (new_events) {
        em->events = new_events;
        em->capacity = new_capacity;
    } else {
        perror("Failed to resize array");
    }
}

void add_event(EventManager *em, TrafficEvent event) {
    pthread_mutex_lock(&em->mutex);

    if (em->count == em->capacity) {
        resize_array(em);
    }

    em->events[em->count++] = event;

    // Simulated logging
    printf("Event added: %d\n", event.uniqueKey);

    pthread_mutex_unlock(&em->mutex);
}

// Thread-safe method to remove an event by key, if found within a time range
int remove_event(EventManager *em, int uniqueKey, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&em->mutex);

    for (size_t i = 0; i < em->count; ++i) {
        if (em->events[i].uniqueKey == uniqueKey &&
            em->events[i].timestamp >= startTime && 
            em->events[i].timestamp <= endTime) {

            free(em->events[i].metadata);

            for (size_t j = i; j < em->count - 1; ++j) {
                em->events[j] = em->events[j + 1];
            }
            --em->count;
            pthread_cond_signal(&em->cond_var); // Signal any waiting threads
            pthread_mutex_unlock(&em->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&em->mutex);
    return -1; // Not found
}

// Retrieve events in a given time range, thread-safe
void get_events_in_range(EventManager *em, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&em->mutex);

    for (size_t i = 0; i < em->count; ++i) {
        if (em->events[i].timestamp >= startTime && 
            em->events[i].timestamp <= endTime) {

            printf("Event: %d, Type: %s\n", em->events[i].uniqueKey, em->events[i].eventType);
        }
    }

    pthread_mutex_unlock(&em->mutex);
}

// Serialize and deserialize events
char* serialize_events(EventManager *em) {
    json_t *root = json_array();

    pthread_mutex_lock(&em->mutex);

    for (size_t i = 0; i < em->count; ++i) {
        json_t *event_obj = json_object();
        json_object_set_new(event_obj, "timestamp", json_integer(em->events[i].timestamp));
        json_object_set_new(event_obj, "eventType", json_string(em->events[i].eventType));
        json_object_set_new(event_obj, "uniqueKey", json_integer(em->events[i].uniqueKey));
        json_object_set_new(event_obj, "metadata", json_string(em->events[i].metadata));

        json_array_append_new(root, event_obj);
    }

    pthread_mutex_unlock(&em->mutex);

    char *serialized = strdup(json_dumps(root, JSON_COMPACT));
    json_decref(root);

    return serialized;
}

EventManager* deserialize_events(const char *data) {
    json_error_t error;
    json_t *root = json_loads(data, 0, &error);

    if (!root || !json_is_array(root)) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    size_t event_count = json_array_size(root);

    EventManager *em = create_event_manager();
    em->count = event_count;
    em->capacity = event_count;

    if (em->count > 0) {
        em->events = realloc(em->events, em->count * sizeof(TrafficEvent));
    }

    for (size_t i = 0; i < event_count; ++i) {
        json_t *event_obj = json_array_get(root, i);

        if (!json_is_object(event_obj)) continue;

        TrafficEvent event;
        json_t *timestamp = json_object_get(event_obj, "timestamp");
        json_t *eventType = json_object_get(event_obj, "eventType");
        json_t *uniqueKey = json_object_get(event_obj, "uniqueKey");
        json_t *metadata = json_object_get(event_obj, "metadata");

        if (json_is_integer(timestamp) && json_is_string(eventType) &&
            json_is_integer(uniqueKey) && json_is_string(metadata)) {

            event.timestamp = json_integer_value(timestamp);
            strncpy(event.eventType, json_string_value(eventType), sizeof(event.eventType));
            event.uniqueKey = json_integer_value(uniqueKey);
            event.metadata = strdup(json_string_value(metadata));

            em->events[i] = event;
        }
    }

    json_decref(root);
    return em;
}

int main() {
    srand(time(NULL));

    EventManager *em = create_event_manager();

    // Example usage
    TrafficEvent event1, event2;
    create_random_event(&event1, 0);
    create_random_event(&event2, 10);

    add_event(em, event1);
    add_event(em, event2);

    get_events_in_range(em, time(NULL) - 60, time(NULL));

    char *serialized = serialize_events(em);
    printf("Serialized Events: %s\n", serialized);
    free(serialized);

    EventManager *deserialized_em = deserialize_events(serialized);
    if (deserialized_em) {
        free_event_manager(deserialized_em);
    }

    free_event_manager(em);

    return 0;
}
