int convert_png_to_gif(const char* input_file, const char* output_dir) {
    char command[512];
    snprintf(command, sizeof(command), "convert %s/%s %s/output.gif", 
             (input_file == NULL) ? "." : "", (input_file == NULL) ? "" : input_file,
             output_dir);

