int process_file(const char* file_name, size_t list_size, const char* output_directory) {
    if (!validate_network_settings()) {
        fprintf(stderr, "Invalid network configuration settings.\n");
        return 1;
    }

    NFAPI_PHY_RX_FRAME_INFO* frame_info_list = (NFAPI_PHY_RX_FRAME_INFO*)malloc(list_size * sizeof(NFAPI_PHY_RX_FRAME_INFO));
    if (frame_info_list == NULL) {
        perror("Failed to allocate memory for frame info list");
        return 1;
    }

    pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_t threads[list_size];
    int thread_index, retries;

    // Create and populate the frames
    for (thread_index = 0; thread_index < list_size; ++thread_index) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (pthread_create(&threads[thread_index], NULL, populate_rsrp_list, &frame_info_list[thread_index]) == 0)
                break;
            retries++;
            fprintf(stderr, "Retrying creation of thread %d: attempt %d\n", thread_index, retries + 1);
        }

        if (retries == MAX_RETRIES) {
            free(frame_info_list);
            fprintf(stderr, "Failed to create threads after %d attempts.\n", MAX_RETRIES);
            return 1;
        }
    }

    for (thread_index = 0; thread_index < list_size; ++thread_index) {
        pthread_join(threads[thread_index], NULL);
    }

    // Verify RSRP values
    for (thread_index = 0; thread_index < list_size; ++thread_index) {
        if (frame_info_list[thread_index].RSRP < -140 || frame_info_list[thread_index].RSRP > -30) {
            fprintf(stderr, "Invalid RSRP value: %d\n", frame_info_list[thread_index].RSRP);
        }
    }

    // Convert PNG to GIF
    int conversion_success = convert_png_to_gif(file_name, output_directory);

    free(frame_info_list);
    pthread_mutex_destroy(&list_mutex);

    if (conversion_success) {
        fprintf(stderr, "File conversion failed.\n");
        return 1;
    }

    return 0;
}
