static unsigned int seed_initialized = 0;

int initialize_random_generator() {
    pthread_mutex_lock(&rng_lock);
    if (!seed_initialized) {
        time_t t;
        srand((unsigned)time(&t));
        seed_initialized = 1;
    }
    pthread_mutex_unlock(&rng_lock);
    return 0; // Success
