Record* manage_memory_collection(long *offsets, int *keys, size_t keys_len,
                                 int min_val, int max_val, const char* description) {
    assert(sizeof(long) >= 8);

    if (min_val > max_val || min_val < INT_MIN || max_val > INT_MAX) {
        log_error("Invalid random range specified.");
        return NULL;
    }

    Record *records = NULL;

    // Initialize RNG
    initialize_random_generator();

    // Allocate memory for records array
    size_t record_array_size = keys_len * sizeof(Record);
    if (record_array_size == 0 || record_array_size > SIZE_MAX / sizeof(Record)) {
        log_error("Failed to allocate memory: request size is invalid or too large.");
        return NULL;
    }

    records = (Record *)malloc(record_array_size);
    if (!records) {
        log_error("Memory allocation failed for records array.");
        return NULL;
    }

    log_allocation_success("Successfully allocated memory for records.");

    // Populate the records array with random values
    for (size_t i = 0; i < keys_len; ++i) {
        int range = max_val - min_val + 1;
        records[i].value = min_val + rand() % range;
    }

    // Reset function to clear records after initialization
    void reset_records(Record *records, size_t len) {
        for (size_t i = 0; i < len; ++i) {
            records[i].value = 0;
        }
    }

    return records;
}

// Example usage and cleanup
