    long offsets[] = {1L, 2L, 3L};
    int keys[] = {10, 20, 30};
    size_t keys_len = sizeof(keys) / sizeof(keys[0]);

    Record *records = manage_memory_collection(offsets, keys, keys_len, 0, 100, "Example");

    if (records) {
        // Use the records array...

        // Resetting records for repeatable scenarios
        reset_records(records, keys_len);

        free(records);
    }

    return 0;
}
