#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10000
#define MAX_RNTI_VALUE UINT_MAX

// Node for linked list to maintain free indices
typedef struct FreeNode {
    size_t index;
    struct FreeNode* next;
} FreeNode;

// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FreeNode* freeListHead;
} CRCList;

// Function prototypes
CRCList* createCRCList();
void destroyCRCList(CRCList* list);
int addCRCIndication(CRCList* list, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned char CRC_INDICATION_REL8_TAG);
void resizeCRCList(CRCList* list);
int validateRNTI(const CRCList* list, unsigned int RNTI);
void flushUnusedEntries(CRCList* list);
void logError(const char* message, size_t index);

// Create a new dynamic array
CRCList* createCRCList() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for CRCList\n");
        return NULL;
    }

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        fprintf(stderr, "Failed to allocate memory for CRCList data\n");
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->freeListHead = NULL;

    // Initialize free list
    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        FreeNode* node = (FreeNode*)malloc(sizeof(FreeNode));
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for FreeNode\n");
            destroyCRCList(list);
            return NULL;
        }
        node->index = i;
        node->next = list->freeListHead;
        list->freeListHead = node;
    }

    return list;
}

// Destroy the dynamic array
void destroyCRCList(CRCList* list) {
    if (!list) return;

    free(list->data);
    FreeNode* current = list->freeListHead;
    while (current) {
        FreeNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new CRC indication
int addCRCIndication(CRCList* list, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned char CRC_INDICATION_REL8_TAG) {
    if (!list || validateRNTI(list, RNTI)) {
        logError("Duplicate or invalid RNTI", 0);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    FreeNode* freeNode = list->freeListHead;
    if (!freeNode) {
        resizeCRCList(list);
        freeNode = list->freeListHead;
    }

    size_t index = freeNode->index;
    list->freeListHead = freeNode->next;
    free(freeNode);

    NFAPI_CRC_INDICATION_PDU_T* entry = &list->data[index];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Resize the dynamic array
void resizeCRCList(CRCList* list) {
    size_t newCapacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        logError("Failed to resize CRCList", list->capacity);
        return;
    }

    memset(newData + list->capacity, 0, (newCapacity - list->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = list->capacity; i < newCapacity; ++i) {
        FreeNode* node = (FreeNode*)malloc(sizeof(FreeNode));
        if (!node) {
            logError("Failed to allocate memory for FreeNode during resize", i);
            return;
        }
        node->index = i;
        node->next = list->freeListHead;
        list->freeListHead = node;
    }

    list->data = newData;
    list->capacity = newCapacity;
}

// Validate RNTI uniqueness
int validateRNTI(const CRCList* list, unsigned int RNTI) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == RNTI) {
            return 1;
        }
    }
    return 0;
}

// Log errors with detailed information
void logError(const char* message, size_t index) {
    fprintf(stderr, "Error: %s at index %zu\n", message, index);
}

// Periodically flush unused entries (stub for demonstration)
void flushUnusedEntries(CRCList* list) {
    // Implement logic to remove inactive or expired entries
}

int main() {
    srand(time(NULL)); // Seed random number generator

    CRCList* list = createCRCList();
    if (!list) return EXIT_FAILURE;

    // Example usage
    addCRCIndication(list, 12345, 67890, 1);

    destroyCRCList(list);
    return EXIT_SUCCESS;
}
