#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define MAX_REFERENCE_COUNT 5

typedef enum { TYPE_A, TYPE_B, TYPE_C } ResourceType;

typedef struct Resource {
    int id;
    size_t size;
    ResourceType type;
    unsigned version;
    atomic_uint access_frequency;
    time_t expiration_timestamp;
    atomic_uint reference_count;
    pthread_mutex_t lock; // Protecting resource modifications
} Resource;

typedef struct CacheNode {
    Resource *resource;
    struct CacheNode *prev;
    struct CacheNode *next;
} CacheNode;

typedef struct LRUCache {
    size_t capacity;
    size_t current_size;
    atomic_uint64_t hit_count;
    atomic_uint64_t miss_count;
    pthread_mutex_t cache_lock; // Protects the entire cache
    CacheNode *head;
    CacheNode *tail;
    Resource **resources; // Array for O(1) access by ID
} LRUCache;

LRUCache* create_cache(size_t capacity);
void destroy_cache(LRUCache* cache);

int add_resource(LRUCache* cache, int id, size_t size, ResourceType type, unsigned version, time_t expiration);
Resource* get_resource(LRUCache* cache, int id);
void update_resource(LRUCache* cache, int id, size_t new_size, ResourceType new_type, unsigned new_version);
void evict_resources(LRUCache* cache);

static CacheNode* create_node(Resource *resource) {
    CacheNode *node = (CacheNode*)malloc(sizeof(CacheNode));
    node->resource = resource;
    pthread_mutex_init(&resource->lock, NULL);
    return node;
}

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = (LRUCache *)malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->current_size = 0;
    cache->hit_count = ATOMIC_VAR_INIT(0);
    cache->miss_count = ATOMIC_VAR_INIT(0);
    pthread_mutex_init(&cache->cache_lock, NULL);

    cache->resources = (Resource**)calloc(capacity, sizeof(Resource*));
    cache->head = NULL;
    cache->tail = NULL;

    return cache;
}

void destroy_cache(LRUCache* cache) {
    CacheNode *current = cache->head;
    while (current != NULL) {
        CacheNode *next = current->next;
        pthread_mutex_destroy(&current->resource->lock);
        free(current->resource);
        free(current);
        current = next;
    }

    free(cache->resources);
    pthread_mutex_destroy(&cache->cache_lock);
    free(cache);
}

void cache_log(const char* message) {
    printf("[CACHE LOG] %s\n", message); // Simplified logging mechanism
}

Resource* create_resource(int id, size_t size, ResourceType type, unsigned version, time_t expiration) {
    Resource *resource = (Resource*)malloc(sizeof(Resource));
    resource->id = id;
    resource->size = size;
    resource->type = type;
    resource->version = version;
    atomic_init(&resource->access_frequency, 0);
    resource->expiration_timestamp = expiration;
    atomic_init(&resource->reference_count, 1); // Initially referencing
    return resource;
}

int add_resource(LRUCache* cache, int id, size_t size, ResourceType type, unsigned version, time_t expiration) {
    pthread_mutex_lock(&cache->cache_lock);

    if (id < 0 || id >= cache->capacity) {
        pthread_mutex_unlock(&cache->cache_lock);
        return -1; // Invalid ID
    }

    if (cache->resources[id] != NULL && atomic_load(&cache->resources[id]->reference_count) > 0) {
        pthread_mutex_unlock(&cache->cache_lock);
        return -2; // Resource already exists and is busy
    }

    Resource *new_resource = create_resource(id, size, type, version, expiration);
    CacheNode *new_node = create_node(new_resource);

    if (cache->current_size == cache->capacity) {
        evict_resources(cache); // Eviction before adding new resource
    }

    if (cache->resources[id] != NULL) {
        pthread_mutex_lock(&cache->resources[id]->lock);
        atomic_fetch_sub(&cache->resources[id]->reference_count, 1);
        if (atomic_load(&cache->resources[id]->reference_count) == 0) {
            CacheNode *node_to_remove = find_node(cache, cache->resources[id]);
            remove_node(node_to_remove);
            free(cache->resources[id]);
        }
        pthread_mutex_unlock(&cache->resources[id]->lock);
    }

    cache->resources[id] = new_resource;
    if (cache->head == NULL) {
        cache->head = cache->tail = new_node;
    } else {
        cache->tail->next = new_node;
        new_node->prev = cache->tail;
        cache->tail = new_node;
    }
    cache->current_size++;

    pthread_mutex_unlock(&cache->cache_lock);

    return 0; // Success
}

Resource* get_resource(LRUCache* cache, int id) {
    Resource *resource = NULL;

    pthread_mutex_lock(&cache->cache_lock);

    if (id < 0 || id >= cache->capacity) {
        atomic_fetch_add(&cache->miss_count, 1);
        pthread_mutex_unlock(&cache->cache_lock);
        return NULL;
    }

    resource = cache->resources[id];
    if (resource == NULL) {
        atomic_fetch_add(&cache->miss_count, 1);
        pthread_mutex_unlock(&cache->cache_lock);
        return NULL;
    }

    time_t now = time(NULL);
    if (now > resource->expiration_timestamp) {
        // Invalidate expired resource
        cache->resources[id] = NULL;
        atomic_fetch_sub(&resource->reference_count, 1);
        remove_node(find_node(cache, resource));
        free(resource);
        pthread_mutex_unlock(&cache->cache_lock);
        return NULL;
    }

    atomic_fetch_add(&resource->access_frequency, 1);
    if (atomic_load(&resource->reference_count) == 0) {
        CacheNode *node = find_node(cache, resource);
        move_to_front(node); // Update LRU
    } else {
        pthread_mutex_lock(&resource->lock);
        atomic_fetch_add(&resource->reference_count, 1);
        pthread_mutex_unlock(&resource->lock);
    }

    atomic_fetch_add(&cache->hit_count, 1);
    pthread_mutex_unlock(&cache->cache_lock);

    return resource;
}

void update_resource(LRUCache* cache, int id, size_t new_size, ResourceType new_type, unsigned new_version) {
    pthread_mutex_lock(&cache->cache_lock);

    if (id < 0 || id >= cache->capacity || cache->resources[id] == NULL) {
        pthread_mutex_unlock(&cache->cache_lock);
        return;
    }

    Resource *resource = cache->resources[id];
    pthread_mutex_lock(&resource->lock);
    resource->size = new_size;
    resource->type = new_type;
    resource->version = new_version;
    atomic_fetch_add(&resource->access_frequency, 1); // Update frequency on modification
    move_to_front(find_node(cache, resource)); // Update LRU
    pthread_mutex_unlock(&resource->lock);

    pthread_mutex_unlock(&cache->cache_lock);
}

CacheNode* find_node(LRUCache* cache, Resource *resource) {
    CacheNode *current = cache->head;
    while (current != NULL && current->resource != resource) {
        current = current->next;
    }
    return current;
}

void remove_node(CacheNode *node) {
    if (node->prev) node->prev->next = node->next;
    else cache->head = node->next;

    if (node->next) node->next->prev = node->prev;
    else cache->tail = node->prev;

    free(node);
}

void move_to_front(CacheNode *node) {
    if (node == cache->head) return; // Already at the front

    remove_node(node);

    node->next = cache->head;
    node->prev = NULL;

    if (cache->head != NULL) cache->head->prev = node;

    cache->head = node;

    if (cache->tail == NULL) {
        cache->tail = node; // Cache was empty
    }
}

void evict_resources(LRUCache* cache) {
    while (cache->current_size >= cache->capacity) {
        if (cache->head != NULL) {
            Resource *resource = cache->head->resource;
            pthread_mutex_lock(&resource->lock);

            if (atomic_load(&resource->reference_count) <= MAX_REFERENCE_COUNT) {
                CacheNode *node_to_evict = find_node(cache, resource);
                remove_node(node_to_evict);
                atomic_fetch_sub(&resource->reference_count, 1); // Decrease reference count
                if (atomic_load(&resource->reference_count) == 0) { 
                    free(resource); // Only free if no longer in use
                }
            } else {
                pthread_mutex_unlock(&resource->lock);
                move_to_front(find_node(cache, resource)); // Bring busy resources to front
                break; // Exit as this node cannot be evicted
            }

            pthread_mutex_unlock(&resource->lock);
            cache->current_size--;
        }
    }
}

// Additional functions for scaling, logging, and resizing would go here.
