#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define SYSTEM_LIMIT 1024 * 1024 * 1024 // Example system memory limit (1GB)
#define LOG_FILE "memory_log.txt"

typedef struct {
    long offset;
    int key;
} OffsetRecord;

typedef struct {
    int value;
    OffsetRecord* offset_record;
} KeyRecord;

typedef struct {
    int value;
} RandomValue;

typedef struct {
    time_t timestamp;
    char event_type[32];
    int unique_id;
    char metadata[256]; // JSON formatted metadata
} TrafficEvent;

void log_overcommitment(size_t requested, size_t limit) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "Memory overcommitment attempt: %zu bytes requested, limit: %zu bytes\n", requested, limit);
        fclose(file);
    }
}

int validate_input(long long user_input) {
    if (user_input < 0 || user_input > LLONG_MAX / sizeof(OffsetRecord)) {
        return -1;
    }
    return 0;
}

void* allocate_memory(size_t size, const char* type_name) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory for %s\n", type_name);
        exit(EXIT_FAILURE);
    }
    if ((size_t)-1 - sizeof(void*) < size || (void*)-1 - ptr < size) {
        log_overcommitment(size, SYSTEM_LIMIT);
    }
    return ptr;
}

unsigned int custom_random_generator(unsigned int seed) {
    // A simple linear congruential generator for demonstration
    return (1664525 * seed + 1013904223) & 0xFFFFFFFF;
}

void* initialize_random_values(void* arg) {
    RandomValue* values = (RandomValue*)arg;
    unsigned int seed = time(NULL);
    for (size_t i = 0; i < *(size_t*)(arg - sizeof(size_t)); ++i) {
        values[i].value = custom_random_generator(seed++);
    }
    return NULL;
}

void initialize_traffic_event_library(size_t offset_count, size_t key_count, size_t random_value_count) {
    if (validate_input(offset_count) || validate_input(key_count) || validate_input(random_value_count)) {
        fprintf(stderr, "Invalid input\n");
        exit(EXIT_FAILURE);
    }

    size_t total_offset_size = sizeof(OffsetRecord) * offset_count;
    size_t total_key_size = sizeof(KeyRecord) * key_count;
    size_t total_random_value_size = sizeof(RandomValue) * random_value_count;

    if (total_offset_size + total_key_size + total_random_value_size > SYSTEM_LIMIT) {
        log_overcommitment(total_offset_size + total_key_size + total_random_value_size, SYSTEM_LIMIT);
    }

    OffsetRecord* offsets = allocate_memory(total_offset_size, "OffsetRecords");
    KeyRecord* keys = allocate_memory(total_key_size, "KeyRecords");

    RandomValue* random_values = allocate_memory(total_random_value_size, "RandomValues");
    size_t sizes[] = {random_value_count, total_random_value_size};

    pthread_t threads[2];
    pthread_create(&threads[0], NULL, initialize_random_values, random_values);
    pthread_create(&threads[1], NULL, initialize_random_values, &sizes[0]);

    for (size_t i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Initialize offsets and keys
