    }

    for (size_t i = 0; i < key_count; ++i) {
        keys[i].value = random_values[i % random_value_count].value; // Assign random value to KeyRecord
        keys[i].offset_record = &offsets[i % offset_count]; // Example association
    }
}

int main() {
    size_t offset_count, key_count, random_value_count;

    printf("Enter number of OffsetRecords: ");
    scanf("%zu", &offset_count);
    printf("Enter number of KeyRecords: ");
    scanf("%zu", &key_count);
    printf("Enter number of RandomValues: ");
    scanf("%zu", &random_value_count);

    initialize_traffic_event_library(offset_count, key_count, random_value_count);

    return 0;
}
```

