                                   &doubles_array, &strings_array, 
                                   &elements_array) == -1) {
        fprintf(stderr, "Initialization failed\n");
        return 1;
    }

    // Use the arrays...

    free_allocated_memory(doubles_array, strings_array, elements_array, num_elements);
    return 0;
}
*/
```

### Key Points:
- **Memory Allocation**: Uses `malloc` for allocating memory and checks if allocations are successful.
- **Random Number Generation**: Generates a random double between `min_val` and `max_val`.
- **String Initialization**: Allocates space for strings and initializes them with a simple pattern.
- **Synchronization**: Uses a mutex to ensure thread safety during initialization.
- **Error Handling**: Checks for allocation failures and logs errors appropriately.
