// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int error_flag = 0;

void initialize_random() {
    srand((unsigned)time(NULL));
}

char* generate_random_string(size_t length, int compress) {
    char *str = (char *)malloc(length + 1);
    if (!str) return NULL;

    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    str[length] = '\0';

    if (compress) {
        uLongf compressed_length = compressBound(length);
        char *compressed_str = (char *)malloc(compressed_length);
        if (!compressed_str) return NULL;

        int res = compress((Bytef *)compressed_str, &compressed_length,
                           (const Bytef *)str, length);

        free(str);  // Free original string

        if (res != Z_OK) {
            free(compressed_str);
            error_flag = 1;
            return NULL;
        }

        str = compressed_str;  // Use compressed string
    }

    return str;
}

Record* create_records(int record_count, int range_min, int range_max, int compress, int *error) {
    Record *records = (Record *)malloc(record_count * sizeof(Record));
    if (!records) { *error = 1; return NULL; }

    for (int i = 0; i < record_count; ++i) {
        records[i].value = range_min + rand() % (range_max - range_min + 1);
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';
        records[i].dynamic_string = generate_random_string(STRING_LENGTH, compress);

        if (!records[i].dynamic_string) {
            *error = 1;
            // Free already allocated memory in case of error
            for (int j = 0; j < i; ++j)
                free(records[j].dynamic_string);
            free(records);
            return NULL;
        }
    }

    *error = 0;
    return records;
}

void* manage_memory(void *arg) {
    int offset_array[MAX_OFFSET];
    int key_array[KEY_ARRAY_SIZE];
    Record *record_array;

    initialize_random();

    for (int i = 0; i < MAX_OFFSET; ++i)
        offset_array[i] = i;

    for (int i = 0; i < KEY_ARRAY_SIZE; ++i)
        key_array[i] = i;

    int error;
    record_array = create_records(RECORD_ARRAY_SIZE, 0, 100, 1, &error);

    if (error) {
        fprintf(stderr, "Error in memory allocation\n");
        pthread_mutex_lock(&lock);
        error_flag = 1;
        pthread_mutex_unlock(&lock);
    }

    // Simulate work
    for (int i = 0; i < RECORD_ARRAY_SIZE; ++i)
        printf("Record %d: Value=%d, Status=%c, String='%s'\n",
               i, record_array[i].value, record_array[i].status,
               record_array[i].dynamic_string);

    if (!error) {
        for (int i = 0; i < RECORD_ARRAY_SIZE; ++i)
            free(record_array[i].dynamic_string);
