['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[MAX_BUFFER_SIZE];
    char *variableText;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t maxRecords;
    size_t allocatedRecords;
    size_t memoryLimitBytes;
} DataStructure;

void randomizeBuffer(char *buffer, const char *charset, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        buffer[i] = charset[rand() % strlen(charset)];
    }
    buffer[length] = '\0';
}

DataStructure* initializeDataStructure(size_t maxRecords, size_t memoryLimitBytes, const char *charset) {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed for DataStructure.\n");
        return NULL;
    }

    ds->maxRecords = maxRecords;
    ds->allocatedRecords = 0;
    ds->memoryLimitBytes = memoryLimitBytes;

    size_t offsetSize = sizeof(long);
    size_t keySize = sizeof(int);
    size_t recordPointerSize = sizeof(Record*);
    size_t totalPerRecordMemory = offsetSize + keySize + recordPointerSize +
                                  sizeof(Record) + MAX_BUFFER_SIZE + 1; // +1 for null terminator

    ds->offsets = (long*)malloc(maxRecords * offsetSize);
    if (!ds->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->keys = (int*)malloc(maxRecords * keySize);
    if (!ds->keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = (Record**)malloc(maxRecords * recordPointerSize);
    if (!ds->records) {
        fprintf(stderr, "Memory allocation failed for records pointers.\n");
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < maxRecords; ++i) {
        if ((ds->allocatedRecords + totalPerRecordMemory) > ds->memoryLimitBytes) {
            fprintf(stderr, "Reached memory limit. Cannot allocate more records.\n");
            break;
        }

        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for a record.\n");
            continue;
        }

        randomizeBuffer(record->buffer, charset, MAX_BUFFER_SIZE);

        record->variableText = strdup("Variable length text example.");
        if (!record->variableText) {
            free(record);
            fprintf(stderr, "Memory allocation failed for variable text.\n");
            break;
        }

        ds->records[ds->allocatedRecords++] = record;
    }

    return ds;
}

void serializeDataStructure(const DataStructure *ds, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization.\n");
        return;
    }

    fwrite(&ds->maxRecords, sizeof(ds->maxRecords), 1, file);
    fwrite(&ds->allocatedRecords, sizeof(ds->allocatedRecords), 1, file);

    fwrite(ds->offsets, sizeof(long), ds->maxRecords, file);
    fwrite(ds->keys, sizeof(int), ds->maxRecords, file);

    for (size_t i = 0; i < ds->allocatedRecords; ++i) {
        Record *record = ds->records[i];
        fwrite(&record->value, sizeof(record->value), 1, file);
        fwrite(record->buffer, MAX_BUFFER_SIZE + 1, 1, file);

        size_t textLength = strlen(record->variableText) + 1;
        fwrite(&textLength, sizeof(textLength), 1, file);
        fwrite(record->variableText, textLength, 1, file);
    }

    fclose(file);
}

void deserializeDataStructure(DataStructure **ds, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization.\n");
        return;
    }

    size_t maxRecords, allocatedRecords;

    fread(&maxRecords, sizeof(maxRecords), 1, file);
    fread(&allocatedRecords, sizeof(allocatedRecords), 1, file);

    *ds = initializeDataStructure(maxRecords, 0, "abcdefghijklmnopqrstuvwxyz");

    if (!*ds) {
        fclose(file);
        return;
    }

    fread((*ds)->offsets, sizeof(long), maxRecords, file);
    fread((*ds)->keys, sizeof(int), maxRecords, file);

    for (size_t i = 0; i < allocatedRecords; ++i) {
        Record *record = (*ds)->records[i];
        fread(&record->value, sizeof(record->value), 1, file);
        fread(record->buffer, MAX_BUFFER_SIZE + 1, 1, file);

        size_t textLength;
        fread(&textLength, sizeof(textLength), 1, file);
        free(record->variableText);

        record->variableText = (char*)malloc(textLength);
        if (!record->variableText) {
            fprintf(stderr, "Memory allocation failed for variable text during deserialization.\n");
            fclose(file);
            return;
        }

        fread(record->variableText, textLength, 1, file);
    }

    fclose(file);
}

void freeDataStructure(DataStructure *ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->allocatedRecords; ++i) {
        free(ds->records[i]->variableText);
        free(ds->records[i]);
    }

    free(ds->records);
    free(ds->keys);
    free(ds->offsets);
    free(ds);
}

int main() {
    const char *charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    DataStructure *ds = initializeDataStructure(100, 1024 * 1024, charset);

    if (ds) {
        serializeDataStructure(ds, "data.bin");
        DataStructure *loadedDs;
        deserializeDataStructure(&loadedDs, "data.bin");

        freeDataStructure(ds);
        freeDataStructure(loadedDs);
    }

    return 0;
}
