// Custom random number generator structures and functions
typedef struct {
    unsigned int state[16];
} RNGState;

void initialize_rng(RNGState *rng, unsigned long seed) {
    for (int i = 0; i < 16; i++) rng->state[i] = seed + i;
}

unsigned long next_random(RNGState *rng) {
    unsigned long result = rng->state[15];
    unsigned long x = (rng->state[0] & 0x7fffffff) ^ (rng->state[15]);
    for (int i = 1; i < 16; ++i) {
        int j = (16 + i - 13) % 16;
        if (i != 2 && i != 6 && i != 14)
            rng->state[i] ^= rng->state[j];
        else
            rng->state[i] ^= (rng->state[j] >> 16);
    }
    rng->state[15] = x;
    result ^= (x << 18) ^ (result >> 27);
    return result;
}

int random_int(RNGState *rng, int min, int max) {
    return min + next_random(rng) % (max - min + 1);
}

char random_char() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    return charset[rand() % (sizeof(charset) - 1)];
}

// Record structure
typedef struct {
    int value;
    char status;
    char *string;
    u_char ip[4];
} record;

// Global flag for error handling
volatile int error_flag = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resources(long *offsets, int *keys, record *records, size_t count) {
    pthread_mutex_lock(&lock);
    if (offsets) free(offsets);
    if (keys) free(keys);
    for (size_t i = 0; i < count; ++i) {
        if (records[i].string) free(records[i].string);
    }
    if (records) free(records);
    pthread_mutex_unlock(&lock);
}

int initializeRecords(size_t offset_count, size_t key_count, size_t record_count, int value_min, int value_max) {
    // Resource limits and thread safety
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);

    long *offsets = malloc(offset_count * sizeof(long));
    int *keys = malloc(key_count * sizeof(int));
    record *records = calloc(record_count, sizeof(record));

    if (!offsets || !keys || !records) {
        error_flag = 1;
        free_resources(offsets, keys, records, record_count);
        return -1;
    }

    // Initialize RNG
    RNGState rng_state;
    initialize_rng(&rng_state, time(NULL));

    // Fill offset array with sequential values starting from 0
    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = i;
    }

    // Fill keys with unique integer values from 0 to key_count - 1
    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = i;
    }

    // Populate records with random values and statuses
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = random_int(&rng_state, value_min, value_max);
        records[i].status = rand() % 2 ? 'A' : 'B';

        // Allocate and fill string with random characters
        records[i].string = malloc(11); // +1 for null terminator
        if (!records[i].string) {
            error_flag = 1;
            free_resources(offsets, keys, records, record_count);
            return -1;
        }
        for (int j = 0; j < 10; ++j) {
            records[i].string[j] = random_char();
        }
        records[i].string[10] = '\0';

