// Function to generate random numbers from a normal distribution
double normal_random(double mean, double stddev) {
    static int has_spare = 0;
    static double spare;

    if (has_spare) {
        has_spare = 0;
        return mean + spare * stddev;
    }

    double u1, u2, w, mult;
    do {
        u1 = rand() / (RAND_MAX + 1.0);
        u2 = rand() / (RAND_MAX + 1.0);
        w = sqrt(-2.0 * log(u1)) * sin(2 * M_PI * u2);
    } while (w == 0);

    mult = w * sqrt(-2.0 * log(u1));
    spare = u2 * mult;
    has_spare = 1;

    return mean + stddev * w;
}

