['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

char allowed_chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

void initialize_random() {
    srand(time(NULL));
}

char random_char() {
    return allowed_chars[rand() % (sizeof(allowed_chars) - 1)];
}

DataStructure* create_data_structure(size_t size) {
    if (size > MAX_RECORDS) {
        fprintf(stderr, "Exceeded maximum number of records.\n");
        return NULL;
    }

    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate data structure");
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);
    ds->offsets = (long*)calloc(size, sizeof(long));
    ds->keys = (int*)calloc(size, sizeof(int));
    ds->records = (Record**)calloc(size, sizeof(Record*));

    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory for structure");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->count = 0;

    initialize_random();

    return ds;
}

void add_record(DataStructure* ds, int key, Record* record) {
    if (ds == NULL || ds->count >= MAX_RECORDS) {
        fprintf(stderr, "Cannot add more records.\n");
        return;
    }

    pthread_mutex_lock(&ds->lock);

    if (ds->count < MAX_RECORDS) {
        ds->keys[ds->count] = key;

        for (int i = 0; i < BUFFER_SIZE - 1; ++i) {
            record->buffer[i] = random_char();
        }
        record->buffer[BUFFER_SIZE - 1] = '\0';

        ds->records[ds->count] = record;
        ds->offsets[ds->count++] = (long)(record - ds->records[0]); // Example offset calculation
    }

    pthread_mutex_unlock(&ds->lock);
}

int serialize_data_structure(const DataStructure* ds, const char* filename) {
    if (!ds || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&ds->lock);

    fwrite(&ds->count, sizeof(size_t), 1, file);
    fwrite(ds->keys, sizeof(int), ds->count, file);
    fwrite(ds->offsets, sizeof(long), ds->count, file);

    for (size_t i = 0; i < ds->count; ++i) {
        Record* record = ds->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(record->buffer, BUFFER_SIZE, 1, file);
    }

    pthread_mutex_unlock(&ds->lock);

    fclose(file);
    return 0;
}

int deserialize_data_structure(DataStructure** ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    *ds = create_data_structure(count);
    if (*ds == NULL) {
        fclose(file);
        return -1;
    }

    fread((*ds)->keys, sizeof(int), count, file);
    fread((*ds)->offsets, sizeof(long), count, file);

    for (size_t i = 0; i < count; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            fclose(file);
            return -1;
        }

        fread(&record->value, sizeof(int), 1, file);
        fread(record->buffer, BUFFER_SIZE, 1, file);

        (*ds)->records[i] = record;
    }

    pthread_mutex_unlock(&(*ds)->lock);
    fclose(file);

    return 0;
}

void free_data_structure(DataStructure* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }

    pthread_mutex_destroy(&ds->lock);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

void* monitor_memory_usage(void* arg) {
    DataStructure* ds = (DataStructure*)arg;

    while (1) {
        printf("Current record count: %zu\n", ds->count);

        pthread_mutex_lock(&ds->lock);
        for (size_t i = 0; i < ds->count; ++i) {
            printf("Record %zu - Key: %d, Offset: %ld\n", i, ds->keys[i], ds->offsets[i]);
        }
        pthread_mutex_unlock(&ds->lock);

        sleep(5);
    }

    return NULL;
}

int main() {
    DataStructure* ds = create_data_structure(100);

    if (!ds) exit(EXIT_FAILURE);

    for (int i = 0; i < 10; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            free_data_structure(ds);
            exit(EXIT_FAILURE);
        }

        add_record(ds, i, record);
    }

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_memory_usage, ds);

    serialize_data_structure(ds, "data.bin");

    DataStructure* new_ds;
    deserialize_data_structure(&new_ds, "data.bin");

    free_data_structure(ds);
    free_data_structure(new_ds);

    return 0;
}
