#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    struct LogEntry* log_entry;
} Record;

typedef struct LogEntry {
    time_t timestamp;
    char message[256];
    struct LogEntry* next;
} LogEntry;

typedef enum LogLevel {
    INFO,
    DEBUG,
    ERROR
} LogLevel;

LogLevel current_log_level = INFO;
FILE* log_file = NULL;

void set_log_level(LogLevel level) {
    current_log_level = level;
}

void open_log_file(const char* filename, const char* mode) {
    log_file = fopen(filename, mode);
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_log_file() {
    if (log_file) {
        fclose(log_file);
    }
}

void log_message(LogLevel level, const char* format, ...) {
    if (level < current_log_level) return;

    va_list args;
    va_start(args, format);
    vsnprintf(log_file ? log_file : stdout, sizeof(message), format, args);
    va_end(args);

    time_t now = time(NULL);
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Failed to allocate memory for log entry");
        exit(EXIT_FAILURE);
    }
    strncpy(entry->message, message, sizeof(entry->message) - 1);
    entry->timestamp = now;
    entry->next = NULL;

    // Assuming a global head pointer for simplicity
    extern LogEntry* log_head;
    entry->next = log_head;
    log_head = entry;
}

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int generate_random_int(int min, int max) {
    if (min > max || max > INT_MAX) {
        fprintf(stderr, "Invalid range for random number generation\n");
        exit(EXIT_FAILURE);
    }
    return rand() % (max - min + 1) + min;
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    memset(ptr, 0, size);
    log_message(INFO, "Allocated %zu bytes of memory\n", size);
    return ptr;
}

void deallocate_memory(void** ptr) {
    if (ptr && *ptr) {
        free(*ptr);
        *ptr = NULL;
        log_message(INFO, "Freed allocated memory\n");
    }
}

Record* create_records(int num_records, int min_value, int max_value) {
    initialize_random_seed();

    long* offsets = allocate_memory(num_records * sizeof(long));
    int* keys = allocate_memory(num_records * sizeof(int));
    Record* records = allocate_memory(num_records * sizeof(Record));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i;
        keys[i] = i;

        int value = generate_random_int(min_value, max_value);
        records[i].value = value;

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Record %d created with value %d", i, value);
        records[i].log_entry = malloc(sizeof(LogEntry));
        if (!records[i].log_entry) {
            perror("Failed to allocate memory for record's log entry");
            exit(EXIT_FAILURE);
        }
        strncpy(records[i].log_entry->message, log_message, sizeof(log_message) - 1);
        records[i].log_entry->timestamp = time(NULL);
        records[i].log_entry->next = NULL;
    }

    return records;
}

void free_resources(long* offsets, int* keys, Record* records, int num_records) {
    deallocate_memory((void**)&offsets);
    deallocate_memory((void**)&keys);

    for (int i = 0; i < num_records; ++i) {
        if (records[i].log_entry) {
            free(records[i].log_entry);
        }
    }
    deallocate_memory((void**)&records);
}

// Example usage
int main() {
    open_log_file("app.log", "w");
    set_log_level(INFO);

    int num_records = 1000000;
    int min_value = 1;
    int max_value = 100;

    Record* records = create_records(num_records, min_value, max_value);

    free_resources(NULL, NULL, records, num_records);
    close_log_file();

    return 0;
}
```

