```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

// Define data structures
typedef struct {
    int value;
} Record;

typedef struct LogEntry {
    time_t timestamp;
    int record_value;
    char message[256];
    struct LogEntry* next;
} LogEntry;

typedef struct {
    long* offsets;
    size_t offset_count;
    int* keys;
    size_t key_count;
    Record* records;
    size_t record_count;
    LogEntry* log_head;
} DataStructures;

// Custom memory pool allocator
#define POOL_SIZE 1024 * 64 // 64KB
#define BLOCK_SIZE sizeof(long) // example block size, can be configured

typedef struct {
    uint8_t* pool;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* mempool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mempool) return NULL;
    mempool->capacity = initial_capacity;
    mempool->used = 0;
    mempool->pool = (uint8_t*)malloc(mempool->capacity);
    if (!mempool->pool) {
        free(mempool);
        return NULL;
    }
    return mempool;
}

void* pool_alloc(MemoryPool* mempool, size_t size) {
    if (mempool->used + size > mempool->capacity)
        return NULL; // Pool exhausted
    void* ptr = mempool->pool + mempool->used;
    mempool->used += size;
    return ptr;
}

void free_memory_pool(MemoryPool* mempool) {
    if (mempool) {
        free(mempool->pool);
        free(mempool);
    }
}

// Logging system
enum LogLevel { DEBUG, INFO, WARN, ERROR };

typedef struct Logger {
    enum LogLevel level;
    FILE* log_file;
} Logger;

Logger* create_logger(enum LogLevel level, const char* file_name) {
    Logger* logger = (Logger*)malloc(sizeof(Logger));
    if (!logger) return NULL;
    logger->level = level;
    logger->log_file = fopen(file_name, "a");
    if (!logger->log_file) {
        free(logger);
        return NULL;
    }
    return logger;
}

void log_message(Logger* logger, enum LogLevel level, const char* format, ...) {
    if (level < logger->level) return;
    va_list args;
    va_start(args, format);
    vfprintf(logger->log_file, format, args);
    fprintf(logger->log_file, "\n");
    va_end(args);
}

void close_logger(Logger* logger) {
    if (logger && logger->log_file) {
        fclose(logger->log_file);
        free(logger);
    }
}

// Resource monitor
typedef struct {
    size_t memory_usage;
    float cpu_load; // Simplified for demonstration
} ResourceMonitor;

ResourceMonitor* create_resource_monitor() {
    ResourceMonitor* monitor = (ResourceMonitor*)malloc(sizeof(ResourceMonitor));
    if (!monitor) return NULL;
    monitor->memory_usage = 0;
    monitor->cpu_load = 0.0f;
    return monitor;
}

void update_resource_monitor(ResourceMonitor* monitor, size_t memory_used, float cpu_load) {
    if (monitor) {
        monitor->memory_usage = memory_used;
        monitor->cpu_load = cpu_load;
    }
}

void free_resource_monitor(ResourcePool* monitor) {
    if (monitor) {
        free(monitor);
    }
}

// Core function
DataStructures* initialize_data_structures(size_t offset_count, size_t key_count, size_t record_count, int range_min, int range_max, Logger* logger) {
    MemoryPool* mempool = create_memory_pool(POOL_SIZE);
    if (!mempool) return NULL;

    DataStructures* ds = (DataStructures*)pool_alloc(mempool, sizeof(DataStructures));
    if (!ds) {
        free_memory_pool(mempool);
        return NULL;
    }

    ds->offsets = (long*)pool_alloc(mempool, offset_count * sizeof(long));
    ds->keys = (int*)pool_alloc(mempool, key_count * sizeof(int));
    ds->records = (Record*)pool_alloc(mempool, record_count * sizeof(Record));
    ds->log_head = NULL;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free_memory_pool(mempool);
        return NULL;
    }

    ds->offset_count = offset_count;
    ds->key_count = key_count;
    ds->record_count = record_count;

    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        int value = range_min + rand() % (range_max - range_min + 1);
        ds->records[i].value = value;

        // Log creation
        LogEntry* entry = (LogEntry*)pool_alloc(mempool, sizeof(LogEntry));
        if (!entry) continue;

        time_t now = time(NULL);
        snprintf(entry->message, sizeof(entry->message), "Record %zu created with value: %d", i, value);

        entry->timestamp = now;
        entry->record_value = value;
        entry->next = ds->log_head;
        ds->log_head = entry;

        log_message(logger, INFO, "Created record at index %zu with value %d", i, value);
    }

    return ds;
}

// Unit tests
void test_initialize_data_structures() {
    Logger* logger = create_logger(DEBUG, "test_log.txt");
    DataStructures* ds = initialize_data_structures(10, 5, 3, 0, 100, logger);

    if (ds) {
        printf("Test passed: Data structures initialized successfully.\n");
    } else {
        printf("Test failed: Data structure initialization failed.\n");
    }

    // Free resources
    while (ds->log_head) {
        LogEntry* entry = ds->log_head;
        ds->log_head = entry->next;
        free(entry);
    }
    free_memory_pool(ds);

    close_logger(logger);
}

int main() {
    test_initialize_data_structures();
    return 0;
}
