['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example: 1 MB max memory usage
#define INITIAL_TABLE_SIZE 16
#define KEY_RANGE 1000

typedef struct {
    int value;
} record;

typedef struct HashNode {
    int key;
    size_t index;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashMap;

unsigned long hashFunction(int key, size_t tableSize) {
    return (unsigned long)key % tableSize;
}

HashMap* createHashTable(size_t size) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    map->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    map->size = size;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void freeHashTable(HashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        HashNode* node = map->buckets[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(map->buckets);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

int insertToHashTable(HashMap* map, int key, size_t index) {
    unsigned long hashIndex = hashFunction(key, map->size);

    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) return -1;

    pthread_mutex_lock(&map->lock);
    newNode->key = key;
    newNode->index = index;
    newNode->next = map->buckets[hashIndex];
    map->buckets[hashIndex] = newNode;
    pthread_mutex_unlock(&map->lock);

    return 0;
}

size_t* findInHashTable(HashMap* map, int key) {
    unsigned long hashIndex = hashFunction(key, map->size);
    HashNode* node = map->buckets[hashIndex];

    while (node) {
        if (node->key == key) {
            return &node->index;
        }
        node = node->next;
    }

    return NULL;
}

void initializeData(long** offsetArray, int** keysArray, record** recordsArray,
                    HashMap** hashMapPtr, size_t numElements, int valueRangeLow, int valueRangeHigh,
                    size_t maxMemoryUsage) {

    long memoryUsed = 0;

    if (numElements == 0 || maxMemoryUsage < sizeof(HashMap*))
        return;

    *hashMapPtr = createHashTable(INITIAL_TABLE_SIZE);
    memoryUsed += sizeof(HashMap*);

    long* offsetArrayTmp = (long*)malloc(numElements * sizeof(long));
    int* keysArrayTmp = (int*)malloc(numElements * sizeof(int));
    record* recordsArrayTmp = (record*)malloc(numElements * sizeof(record));

    if (!offsetArrayTmp || !keysArrayTmp || !recordsArrayTmp) {
        free(offsetArrayTmp);
        free(keysArrayTmp);
        free(recordsArrayTmp);
        freeHashTable(*hashMapPtr);
        return;
    }

    memoryUsed += numElements * (sizeof(long) + sizeof(int) + sizeof(record));

    if (memoryUsed > maxMemoryUsage) {
        free(offsetArrayTmp);
        free(keysArrayTmp);
        free(recordsArrayTmp);
        freeHashTable(*hashMapPtr);
        return;
    }

    for (size_t i = 0; i < numElements; ++i) {
        offsetArrayTmp[i] = rand() % KEY_RANGE; // Sample offset generation
        keysArrayTmp[i] = rand() % KEY_RANGE;
        recordsArrayTmp[i].value = valueRangeLow + rand() % (valueRangeHigh - valueRangeLow + 1);

        if (insertToHashTable(*hashMapPtr, keysArrayTmp[i], i) == -1) {
            free(offsetArrayTmp);
            free(keysArrayTmp);
            free(recordsArrayTmp);
            freeHashTable(*hashMapPtr);
            return;
        }
    }

    *offsetArray = offsetArrayTmp;
    *keysArray = keysArrayTmp;
    *recordsArray = recordsArrayTmp;
}

void cleanupData(long* offsetArray, int* keysArray, record* recordsArray, HashMap* hashMap) {
    if (offsetArray) free(offsetArray);
