#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for PDCCH resource grid entry
typedef struct {
    int id; // Unique identifier for the entry
    // Add other relevant fields here
} PDCCH_Entry;

// Node structure for linked list
typedef struct PDCCH_Node {
    PDCCH_Entry data;
    struct PDCCH_Node* next;
} PDCCH_Node;

// Dynamic list structure with thread safety
typedef struct {
    PDCCH_Node* head;
    pthread_mutex_t lock;
} PDCCH_List;

// Function to initialize the list
void init_pdcch_list(PDCCH_List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new entry to the list
void add_entry(PDCCH_List* list, PDCCH_Entry entry) {
    pthread_mutex_lock(&list->lock);

    PDCCH_Node* new_node = (PDCCH_Node*)malloc(sizeof(PDCCH_Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Delete an entry from the list by ID
void delete_entry(PDCCH_List* list, int id) {
    pthread_mutex_lock(&list->lock);

    PDCCH_Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Entry not found
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
}

// Lookup an entry by ID
PDCCH_Entry* lookup_entry(PDCCH_List* list, int id) {
    pthread_mutex_lock(&list->lock);

    PDCCH_Node* current = list->head;

    while (current != NULL) {
        if (current->data.id == id) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Entry not found
}

// Free the list and its resources
void free_pdcch_list(PDCCH_List* list) {
    pthread_mutex_lock(&list->lock);

    PDCCH_Node *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
