status_t allocate_records(int num_records, int min_value, int max_value, unsigned int seed,
                          record ***records_out, long **offsets_out, int **keys_out) {
    pthread_mutex_lock(&mutex);

    // Log start of allocation
    printf("[%ld] Starting memory allocation for %d records.\n", time(NULL), num_records);

    *records_out = (record **)malloc(num_records * sizeof(record *));
    if (*records_out == NULL) {
        printf("[%ld] Error: Memory allocation failed for record pointers.\n", time(NULL));
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_FAILURE;
    }

    *offsets_out = (long *)malloc(num_records * sizeof(long));
    if (*offsets_out == NULL) {
        free(*records_out);
        printf("[%ld] Error: Memory allocation failed for offsets.\n", time(NULL));
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_FAILURE;
    }

    *keys_out = (int *)malloc(num_records * sizeof(int));
    if (*keys_out == NULL) {
        free(*offsets_out);
        free(*records_out);
        printf("[%ld] Error: Memory allocation failed for keys.\n", time(NULL));
        pthread_mutex_unlock(&mutex);
        return ALLOCATION_FAILURE;
    }

    // Seed the random number generator
    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        (*records_out)[i] = (record *)malloc(sizeof(record));
        if ((*records_out)[i] == NULL) {
            printf("[%ld] Error: Memory allocation failed for record at index %d.\n", time(NULL), i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) free((*records_out)[j]);
            free(*offsets_out);
            free(*keys_out);
            free(*records_out);
            pthread_mutex_unlock(&mutex);
            return ALLOCATION_FAILURE;
        }
        (*records_out)[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Log successful allocation
    printf("[%ld] Successfully allocated memory for %d records.\n", time(NULL), num_records);

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void free_resources(record **records, long *offsets, int *keys, int num_records) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; ++i) {
        if (records[i]) free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);

    // Log successful deallocation
    printf("[%ld] Successfully freed memory resources.\n", time(NULL));

    pthread_mutex_unlock(&mutex);
}

int main() {
