// log.c
#include "log.h"
#include <stdio.h>
#include <string.h>

LogEntry* create_log_entry(LogLevel level, const char* format, ...) {
    va_list args;
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Failed to allocate memory for log entry");
        return NULL;
    }
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->next = NULL;

    va_start(args, format);
    vsnprintf(entry->message, sizeof(entry->message), format, args);
    va_end(args);

    return entry;
}

void log_message(LogLevel level, const char* format, ...) {
    LogEntry* entry = create_log_entry(level, format);
    if (entry) {
        printf("%s [%ld] %s\n", get_level_string(level), entry->timestamp, entry->message);
    }
}

const char* get_level_string(LogLevel level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO:  return "INFO";
        case WARN:  return "WARN";
        case ERROR: return "ERROR";
        default:    return "UNKNOWN";
    }
}

void print_logs(LogEntry* head) {
    LogEntry* current = head;
    while (current) {
        printf("%s [%ld] %s\n", get_level_string(current->level), current->timestamp, current->message);
        current = current->next;
    }
}

void free_logs(LogEntry** head) {
    LogEntry* current = *head;
    LogEntry* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

