// traffic_event.c
#include "traffic_event.h"
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct DynamicArray {
    TrafficEvent** events;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        return NULL;
    }
    array->events = calloc(initial_capacity, sizeof(TrafficEvent*));
    if (!array->events) {
        free(array);
        perror("Failed to allocate memory for events");
        return NULL;
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void add_event(DynamicArray* array, TrafficEvent* event) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TrafficEvent** new_events = realloc(array->events, new_capacity * sizeof(TrafficEvent*));
        if (!new_events) {
            perror("Failed to reallocate memory for events");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }
    array->events[array->size++] = event;
    pthread_mutex_unlock(&array->mutex);
}

TrafficEvent* get_event(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    TrafficEvent* event = NULL;
    if (index < array->size) {
        event = array->events[index];
    }
    pthread_mutex_unlock(&array->mutex);
    return event;
}

void remove_event(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->size) {
        free(array->events[index]->metadata);
        free(array->events[index]);
        memmove(&array->events[index], &array->events[index + 1],
                (array->size - index - 1) * sizeof(TrafficEvent*));
        --array->size;
    }
    pthread_mutex_unlock(&array->mutex);
}

void serialize_array(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(&array->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->size; ++i) {
        fwrite(&array->events[i]->timestamp, sizeof(time_t), 1, file);
        fwrite(&array->events[i]->event_type, sizeof(int), 1, file);
        fwrite(array->events[i]->identifier, sizeof(char), 64, file);

        size_t json_len = json_object_to_json_string_len(array->events[i]->metadata);
        char* json_str = json_object_to_json_string(array->events[i]->metadata);
        fwrite(&json_len, sizeof(size_t), 1, file);
        fwrite(json_str, sizeof(char), json_len, file);
        free(json_str);
    }

    fclose(file);
}

void deserialize_array(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    fread(&array->size, sizeof(size_t), 1, file);
    array->capacity = array->size;
    TrafficEvent** new_events = realloc(array->events, array->capacity * sizeof(TrafficEvent*));
    if (!new_events) {
        perror("Failed to reallocate memory for events");
        fclose(file);
        return;
    }
    array->events = new_events;

    for (size_t i = 0; i < array->size; ++i) {
        TrafficEvent* event = malloc(sizeof(TrafficEvent));
        if (!event) {
            perror("Failed to allocate memory for traffic event");
            fclose(file);
            return;
        }
        fread(&event->timestamp, sizeof(time_t), 1, file);
        fread(&event->event_type, sizeof(int), 1, file);
        fread(event->identifier, sizeof(char), 64, file);

        size_t json_len;
        fread(&json_len, sizeof(size_t), 1, file);
        char* json_str = malloc(json_len + 1);
        if (!json_str) {
            perror("Failed to allocate memory for JSON string");
            free(event);
            fclose(file);
            return;
        }
        fread(json_str, sizeof(char), json_len, file);
        json_str[json_len] = '\0';
        event->metadata = json_tokener_parse(json_str);
        free(json_str);

        array->events[i] = event;
    }

    fclose(file);
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        json_object_put(array->events[i]->metadata);
        free(array->events[i]);
    }
    free(array->events);
    pthread_mutex_unlock(&array_array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

// main.c
#include "record.h"
#include "log.h"
#include "traffic_event.h"

int main() {
    // Example usage of the library

    // Create and log a record
    Record rec = create_record(1, 100);
    log_message(INFO, "Created record with key: %d and value: %d", rec.key, rec.value);

    // Create a dynamic array for traffic events
    DynamicArray* event_array = create_dynamic_array(10);
    if (!event_array) {
        log_message(ERROR, "Failed to create dynamic array");
        return EXIT_FAILURE;
    }

    // Add an event
    TrafficEvent* event = malloc(sizeof(TrafficEvent));
    if (!event) {
        log_message(ERROR, "Failed to allocate memory for traffic event");
        free_dynamic_array(event_array);
        return EXIT_FAILURE;
    }
    event->timestamp = time(NULL);
    event->event_type = 1;
    snprintf(event->identifier, sizeof(event->identifier), "%ld", (long)time(NULL));
    event->metadata = json_object_new_object();
    json_object_object_add(event->metadata, "example_key", json_object_new_string("example_value"));
    add_event(event_array, event);

    // Serialize and deserialize
    serialize_array(event_array, "events.dat");
    DynamicArray* new_event_array = create_dynamic_array(10);
    if (!new_event_array) {
        log_message(ERROR, "Failed to create dynamic array for deserialization");
        free_dynamic_array(event_array);
        return EXIT_FAILURE;
    }
    deserialize_array(new_event_array, "events.dat");

    // Cleanup
    free_dynamic_array(event_array);
    free_dynamic_array(new_event_array);

    return EXIT_SUCCESS;
}
