#include <stdio.h>
#include <stdlib.h>

// Define maximum size for record array allocation.
#define MAX_RECORD_SIZE 1000

typedef enum {
    TYPE_INT,
    TYPE_LONG
} DataType;

typedef struct {
    union {
        long l_value;
        int i_value;
    } data;
    DataType type;
} Record;

void cleanup(Record *records, long *offsets, int *keys) {
    if (records != NULL) free(records);
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
}

long *allocate_offsets_and_keys(int n, int *keys) {
    for (int size = n; size > 0; --size) {
        long *offsets = malloc(size * sizeof(long));
        keys = malloc(size * sizeof(int));
        if (offsets && keys) return offsets;
        free(offsets);
        free(keys);
    }
    return NULL;
}

Record *allocate_records(int n, int initial_value, int *status) {
    for (int size = n; size > 0; --size) {
        Record *records = malloc(size * sizeof(Record));
        if (records == NULL) {
            *status = -1;
            return NULL;
        }

        for (int i = 0; i < size; ++i) {
            records[i].type = TYPE_INT;
            records[i].data.i_value = initial_value;
        }
        *status = 0;
        return records;
    }
    *status = -1;
    return NULL;
}

void adjust_to_target_sum(Record *records, int n, int target_sum) {
    int current_sum = 0;
    for (int i = 0; i < n; ++i) {
        if (records[i].type == TYPE_INT)
            current_sum += records[i].data.i_value;
    }

    int difference = target_sum - current_sum;
    int adjust_per_record = difference / n;

    for (int i = 0; i < n && difference != 0; ++i) {
        if (records[i].type == TYPE_INT) {
            int adjustment = records[i].data.i_value + adjust_per_record > 0 ? adjust_per_record : -adjust_per_record;
            records[i].data.i_value += adjustment;
            difference -= adjustment;
        }
    }

    for (int i = 0; difference != 0 && i < n; ++i) {
        if (records[i].type == TYPE_INT) {
            int adjustment = difference > 0 ? 1 : -1;
            records[i].data.i_value += adjustment;
            difference -= adjustment;
        }
    }
}

Record *manage_memory(int n, int target_sum, int initial_value) {
    long *offsets = NULL;
    int *keys = NULL;

    offsets = allocate_offsets_and_keys(n, keys);
    if (offsets == NULL || keys == NULL) {
        cleanup(NULL, offsets, keys);
        return NULL;
    }

    Record *records = NULL;
    int status = 0;
    records = allocate_records(n, initial_value, &status);
    if (records == NULL || status != 0) {
        cleanup(records, offsets, keys);
        return NULL;
    }

    adjust_to_target_sum(records, n, target_sum);

    free(offsets); // Free offsets as they are no longer needed after initialization.

    return records; // Return the pointer to records
}

void validate_and_adjust(Record *records, int size, int target_sum) {
    if (records == NULL) return;

    adjust_to_target_sum(records, size, target_sum);
}

int main() {
    int n = 10;
    int target_sum = 50;
    int initial_value = 0;

    Record *records = manage_memory(n, target_sum, initial_value);

    if (records != NULL) {
        validate_and_adjust(records, n, target_sum);
        // Use records...

        cleanup(records, NULL, NULL); // Clean up all allocated memory.
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
```

### Explanation:
- **Allocation and Initialization**: The code attempts to allocate memory for offsets and keys with decreasing sizes if an initial attempt fails. It similarly tries to allocate the record array in a decrementing manner.

- **Record Structure**: The `record` structure uses a union for storing either a `long` or an `int`, along with an enum type to indicate which data is stored.

- **Dynamic Resizing Strategy**: Allocation starts from the requested size and reduces if necessary, minimizing reallocations. 

- **Validation Function**: Adjusts record values so their sum matches the target sum using minimal deviation.

- **Cleanup Function**: Ensures all memory is freed properly regardless of where failure occurs in allocation processes.

The implementation focuses on robust handling for resource-constrained environments by employing strategic fallbacks and cleanup mechanisms to minimize leaks and inconsistencies.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct PacketInfo {
    int frame_number;
    int packet_id;
    int error_status;
    struct PacketInfo* next;
} PacketInfo;

typedef struct FrameStatsNode {
    time_t timestamp;
    int signal_strength;
    PacketInfo* packet_info_list;
    struct FrameStatsNode* next;
} FrameStatsNode;

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    int status_flag;
} DataPacket;

#define MAX_PACKETS 10000
#define EXPIRATION_THRESHOLD 60 // seconds

DataPacket* data_packets = NULL;
FrameStatsNode* frame_stats_head = NULL;

// Function prototypes
void add_data_packet(int packet_id, time_t timestamp, int status_flag);
void update_packet_status(int packet_id, int new_status);
DataPacket* get_packet_by_id(int packet_id);
void purge_expired_packets(time_t current_time);
void cleanup();

void add_data_packet(int packet_id, time_t timestamp, int status_flag) {
    DataPacket** pp = &data_packets;
    while (*pp) {
        if ((*pp)->packet_id == packet_id) {
            return; // Packet already exists
        }
        pp = &((*pp)->next);
    }

    *pp = (DataPacket*)malloc(sizeof(DataPacket));
    (*pp)->packet_id = packet_id;
    (*pp)->timestamp = timestamp;
    (*pp)->status_flag = status_flag;
    (*pp)->next = NULL;
}

void update_packet_status(int packet_id, int new_status) {
    DataPacket* current = data_packets;
    while (current) {
        if (current->packet_id == packet_id) {
            current->status_flag = new_status;
            return;
        }
        current = current->next;
    }
}

DataPacket* get_packet_by_id(int packet_id) {
    DataPacket* current = data_packets;
    while (current) {
        if (current->packet_id == packet_id) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Packet not found
}

void purge_expired_packets(time_t current_time) {
    DataPacket **pp = &data_packets, *temp;

    while (*pp) {
        if (difftime(current_time, (*pp)->timestamp) > EXPIRATION_THRESHOLD) {
            temp = *pp;
            *pp = (*pp)->next;
            free(temp);
        } else {
            pp = &((*pp)->next);
        }
    }

    FrameStatsNode **fps = &frame_stats_head, *f_temp;

    while (*fps) {
        if (difftime(current_time, (*fps)->timestamp) > EXPIRATION_THRESHOLD) {
            f_temp = *fps;
            *fps = (*fps)->next;

            PacketInfo *pip = (*fps)->packet_info_list, *p_temp;
            while (pip) {
                p_temp = pip;
                pip = pip->next;
                free(p_temp);
            }

            free(f_temp);
        } else {
            fps = &((*fps)->next);
        }
    }
}

void cleanup() {
    DataPacket* current = data_packets, *temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    FrameStatsNode* f_current = frame_stats_head, *f_temp;

    while (f_current) {
        f_temp = f_current;
        f_current = f_current->next;

        PacketInfo* pip = f_temp->packet_info_list, *p_temp;
        while (pip) {
            p_temp = pip;
            pip = pip->next;
            free(p_temp);
        }

        free(f_temp);
    }
}
