#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define MEMORY_THRESHOLD 80 // Percentage threshold for memory usage warning

typedef enum { TYPE_INT, TYPE_LONG } DataType;

typedef union {
    long l_value;
    int i_value;
} DataUnion;

typedef struct {
    DataUnion data;
    DataType type;
} Record;

typedef struct {
    int size;
    int used;
    void* start_addr;
} MemoryPool;

MemoryPool memory_pool = {0, 0, NULL};

void log_event(const char *message) {
    printf("%s\n", message);
}

int allocate_memory(size_t size, void **ptr) {
    if (size > MAX_RECORDS * sizeof(Record)) return 0; // Ensure not to exceed max limit

    if (!memory_pool.start_addr) {
        memory_pool.size = size;
        memory_pool.used = size;
        memory_pool.start_addr = malloc(memory_pool.size);
        if (!memory_pool.start_addr) return 0;
    }

    if (size + memory_pool.used > memory_pool.size) {
        void *new_ptr = realloc(memory_pool.start_addr, size + memory_pool.used);
        if (!new_ptr) return 0;

        memory_pool.start_addr = new_ptr;
        memory_pool.size += size;
    }

    *ptr = (char*)memory_pool.start_addr + memory_pool.used;
    memory_pool.used += size;
    log_event("Memory allocated");

    return 1;
}

void free_memory() {
    if (memory_pool.start_addr) {
        free(memory_pool.start_addr);
        memory_pool.start_addr = NULL;
        memory_pool.size = 0;
        memory_pool.used = 0;
        log_event("Memory freed");
    }
}

Record* initialize_records(int num_records, int *int_keys, long *long_offsets) {
    if (!allocate_memory(num_records * sizeof(Record), (void**)&memory_pool.start_addr)) return NULL;

    Record *records = (Record *)memory_pool.start_addr;
    for (int i = 0; i < num_records; ++i) {
        records[i].type = TYPE_INT;
        records[i].data.i_value = 0; // Default initialization
    }

    log_event("Records initialized");

    return records;
}

void validate_and_adjust(Record *records, int num_records, int target_sum) {
    int current_sum = 0;
    for (int i = 0; i < num_records; ++i) {
        if (records[i].type == TYPE_INT) {
            current_sum += records[i].data.i_value;
        }
    }

    while (current_sum != target_sum && num_records > 0) {
        int diff = target_sum - current_sum;
        for (int i = 0; i < num_records; ++i) {
            if (records[i].type == TYPE_INT) {
                records[i].data.i_value += (diff > 0 ? 1 : -1);
                current_sum += (diff > 0 ? 1 : -1);

                if (current_sum == target_sum) break;
            }
        }
    }

    log_event("Validation and adjustment completed");
}

int main() {
    int keys[10];
    long offsets[10];
    Record *records = initialize_records(10, keys, offsets);

    if (!records) {
        printf("Failed to allocate records\n");
        return -1;
    }

    // Simulate an allocation scenario
    validate_and_adjust(records, 10, 50);

    free_memory();
    return 0;
}
```

### Key Points:
- **Memory Pool Management**: A single `MemoryPool` is used for simplicity. It manages allocations and resizes itself as needed.
- **Logging**: Basic logging with `log_event()` helps track allocation/deallocation activities.
- **Record Initialization and Adjustment**: Records are initialized to default values, and adjustments ensure the sum of `int` values reaches a target value if necessary.
- **Memory Management**: The code attempts to allocate within constraints and includes cleanup functionality to prevent leaks.

This solution provides a starting point. Further enhancements could include more sophisticated allocation strategies, improved logging, and additional error handling for robustness in production environments.']

