#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BUFFER_SIZE 256

typedef struct {
    int key;
    char buffer[MAX_BUFFER_SIZE];
    char *string; // Dynamically allocated string for variable-length text
    long offset;
    char **metadata_tags;
    size_t num_metadata_tags;
    time_t timestamp_ns; // Timestamp in nanoseconds
} record;

// Function prototypes
record* allocate_records(size_t count, int use_compression);
void free_records(record *records, size_t count);
char* compress_data(const char *data, size_t *compressed_size);
void decompress_data(char *compressed_data, const size_t compressed_size, char **decompressed_data);

// Main function to dynamically allocate and initialize records
record* allocate_records(size_t count, int use_compression) {
    if (count == 0) return NULL;

    // Estimate memory usage per record without compression
    size_t base_record_size = sizeof(record) + MAX_BUFFER_SIZE;

    // Allocate memory for metadata tags array pointer within each record
    char **metadata_tags_buffer = malloc(count * sizeof(char*));

    if (!metadata_tags_buffer) {
        perror("Failed to allocate metadata tags buffer");
        return NULL;
    }

    // Allocate and initialize records
    record *records = (record *)malloc(count * base_record_size);
    if (!records || !metadata_tags_buffer) {
        free(records);   // Free previously allocated memory in case of failure
        free(metadata_tags_buffer);
        perror("Failed to allocate records");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].key = i; // Example initialization
        records[i].buffer[0] = '\0'; 
        records[i].string = strdup("default string"); // Example allocation
        records[i].offset = 0;

        records[i].metadata_tags = &metadata_tags_buffer[i];
        *records[i].metadata_tags = NULL;  // Initialize as NULL

        // Assign a timestamp (example using current time)
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        records[i].timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

        if (!records[i].string) {
            fprintf(stderr, "Failed to allocate memory for string\n");
            free_records(records, i); // Free up to the current point
            return NULL;
        }
    }

    printf("Allocated %zu records with use_compression = %d\n", count, use_compression);

    if (use_compression) {
        size_t compressed_size = 0;
        char *compressed_data = compress_data((const char *)records, count * base_record_size, &compressed_size);

        // Handle the compressed data as needed...
        free(compressed_data); // Free after processing
    }

    return records;
}

// Function to free allocated memory for records
void free_records(record *records, size_t count) {
    if (!records) return;

    for (size_t i = 0; i < count; ++i) {
        free(records[i].string);
        char **tags = records[i].metadata_tags;
        while (*tags) { // Free metadata tags
            free(*tags);
            *tags++ = NULL;
        }
    }

    free(records); // Finally, free the records array itself
}

// Dummy compress function - replace with actual compression logic as needed
char* compress_data(const char *data, size_t data_size, size_t *compressed_size) {
    *compressed_size = data_size / 2; // Example compression ratio
    char *compressed_data = malloc(*compressed_size);
    if (!compressed_data) return NULL;

    memcpy(compressed_data, data, *compressed_size); // Simulated compression

    printf("Data compressed from %zu to %zu bytes\n", data_size, *compressed_size);

    return compressed_data;
}

// Dummy decompress function - replace with actual decompression logic as needed
void decompress_data(char *compressed_data, const size_t compressed_size, char **decompressed_data) {
    *decompressed_data = malloc(compressed_size * 2); // Example original data size
    if (!*decompressed_data) return;

    memcpy(*decompressed_data, compressed_data, compressed_size); // Simulated decompression

    printf("Data decompressed from %zu to %zu bytes\n", compressed_size, compressed_size * 2);
}

int main() {
    size_t num_records = 10;
    int use_compression = 1;

    record *records = allocate_records(num_records, use_compression);

    if (records) {
        // Use the records...

        free_records(records, num_records); // Free allocated memory
    }

    return 0;
}
