#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define DEFAULT_TIMEOUT 60 // seconds
#define RETRY_LIMIT 3

typedef struct {
    int connection_id;
    char remote_ip[16]; // Assuming IPv4 addresses
    time_t last_successful_communication;
    int reference_count;
    int health_status; // 1 for healthy, 0 for unhealthy
} NetworkConnection;

typedef struct {
    NetworkConnection *connections;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t lock;
    unsigned int timeout;
    int retry_policy;
} ConnectionManager;

int validate_ip(const char* ip) {
    // Simple validation for IPv4 (Assumes well-formed input)
    return sscanf(ip, "%d.%d.%d.%d", &dummy1, &dummy2, &dummy3, &dummy4) == 4;
}

ConnectionManager* create_connection_manager(size_t initial_capacity, unsigned int timeout, int retry_policy) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->connections = calloc(initial_capacity, sizeof(NetworkConnection));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->current_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->timeout = timeout;
    manager->retry_policy = retry_policy;

    return manager;
}

int add_connection(ConnectionManager *manager, int connection_id, const char *remote_ip) {
    if (!manager || !validate_ip(remote_ip)) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check if the IP is already present
    for (size_t i = 0; i < manager->current_size; ++i) {
        if (strcmp(manager->connections[i].remote_ip, remote_ip) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    // Check capacity
    if (manager->current_size >= manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // No space for new connection
    }

    NetworkConnection *conn = &manager->connections[manager->current_size++];
    conn->connection_id = connection_id;
    strncpy(conn->remote_ip, remote_ip, sizeof(conn->remote_ip) - 1);
    conn->last_successful_communication = time(NULL);
    conn->reference_count = 0;
    conn->health_status = 1;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void serialize_connection_list(ConnectionManager *manager, const char *key_value_store) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->current_size; ++i) {
        NetworkConnection conn = manager->connections[i];
        snprintf(key_value_store + strlen(key_value_store), MAX_KEY_VALUE_SIZE, 
                 "conn%d:%d:%s:%ld:%d:%d\n",
                 conn.connection_id, inet_addr(conn.remote_ip),
                 ctime(&conn.last_successful_communication),
                 conn.reference_count,
                 conn.health_status);
    }

    pthread_mutex_unlock(&manager->lock);
}

void deserialize_connection_list(ConnectionManager *manager, const char *data) {
    if (!manager || !data) return;

    pthread_mutex_lock(&manager->lock);

    // Clear existing data
    manager->current_size = 0;

    char buffer[MAX_KEY_VALUE_SIZE];
    while (sscanf(data, "conn%d:%d:%[^:]:%ld:%d:%d\n", &buffer[0], &buffer[1],
                  buffer + 2, &buffer[3], &buffer[4], &buffer[5]) > 0) {
        if (manager->current_size < manager->capacity) {
            NetworkConnection *conn = &manager->connections[manager->current_size++];
            conn->connection_id = atoi(buffer);
            strcpy(conn->remote_ip, inet_ntoa(*(struct in_addr *)(buffer + 1)));
            conn->last_successful_communication = atol(buffer + 3);
            conn->reference_count = atoi(buffer + 4);
            conn->health_status = atoi(buffer + 5);
        } else {
            break; // Capacity full
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

NetworkConnection* find_connection(ConnectionManager *manager, int connection_id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->current_size; ++i) {
        if (manager->connections[i].connection_id == connection_id) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->connections[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void adjust_memory_limit(ConnectionManager *manager, size_t new_capacity) {
    if (!manager || manager->capacity >= new_capacity) return;

    NetworkConnection *new_connections = realloc(manager->connections,
                                                 new_capacity * sizeof(NetworkConnection));
    if (new_connections) {
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
}

void cleanup_connection_manager(ConnectionManager *manager) {
    if (!manager) return;

    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

