} data_t;

typedef enum { EVENT_TYPE_1, EVENT_TYPE_2 } event_type_t;

typedef struct event {
    data_t *data;
    event_type_t type;
    unsigned long timestamp;
} event_t;

typedef struct log {
    size_t total_events;
    event_t *events;
    size_t capacity; // for dynamic resizing
} log_t;

typedef struct record {
    int value;
    char buffer[MAX_CHAR_BUFFER];
    log_t *log;
    static size_t record_count;
} record_t;

size_t record_t::record_count = 0;

void free_record(record_t *record) {
    if (record->log) {
        for (size_t i = 0; i < record->log->total_events; ++i) {
            if (record->log->events[i].data) {
                free(record->log->events[i].data->string);
                free(record->log->events[i].data);
            }
        }
        free(record->log->events);
    }
    --record_t::record_count;
}

int initialize_records(long *offsets, size_t offset_count, int *keys, size_t key_count, record_t **records) {
    if (!offsets || !keys || !records) return -1;

    *records = (record_t *)malloc(key_count * sizeof(record_t));
    if (!*records) return -2;

    for (size_t i = 0; i < key_count; ++i) {
        (*records)[i].value = keys[i];
        snprintf((*records)[i].buffer, MAX_CHAR_BUFFER, "ID_%d", keys[i]);

        log_t *log = (log_t *)malloc(sizeof(log_t));
        if (!log) {
            for (size_t j = 0; j < i; ++j) free_record(&(*records)[j]);
            free(*records);
            return -3;
        }
        log->total_events = 0;
        log->capacity = 4;
        log->events = (event_t *)malloc(log->capacity * sizeof(event_t));
        if (!log->events) {
            free(log);
            for (size_t j = 0; j < i; ++j) free_record(&(*records)[j]);
            free(*records);
            return -4;
        }

        (*records)[i].log = log;
    }
    record_t::record_count += key_count;

    return 0;
}

void serialize_records(record_t *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; ++i) {
        fwrite(&(records[i].value), sizeof(int), 1, file);
        fwrite(records[i].buffer, MAX_CHAR_BUFFER, 1, file);

        size_t event_count = records[i].log->total_events;
        fwrite(&event_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < event_count; ++j) {
            data_t *data = records[i].log->events[j].data;
            fwrite(&(records[i].log->events[j].type), sizeof(event_type_t), 1, file);
            fwrite(&records[i].log->events[j].timestamp, sizeof(unsigned long), 1, file);

            size_t str_len = strlen(data->string) + 1;
            fwrite(&str_len, sizeof(size_t), 1, file);
            fwrite(data->string, str_len, 1, file);

            fwrite(&(data->value), sizeof(float), 1, file);
            fwrite(&data->flag, sizeof(bool), 1, file);
        }
    }

    fclose(file);
}

int deserialize_records(record_t **records, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
