                for (size_t k = 0; k < i; ++k) free_record(&(*records)[k]);
                free(*records);
                fclose(file);
                return -5;
            }
            fread(string, str_len, 1, file);

            data_t *data = (data_t *)malloc(sizeof(data_t));
            if (!data) {
                free(string);
                for (size_t k = 0; k < j; ++k) free(log->events[k].data->string);
                for (size_t k = 0; k <= j; ++k) free(log->events[k].data);
                free(log->events);
                free(log);
                for (size_t k = 0; k < i; ++k) free_record(&(*records)[k]);
                free(*records);
                fclose(file);
