['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_THRESHOLD 1048576 // Example threshold in bytes (1MB)
#define RECORD_COUNT_LIMIT 1000

typedef struct {
    int value;
    char buffer[256];
    time_t timestamp;
} Record;

typedef struct {
    Record* record_ptr;
    time_t last_accessed_time;
} Metadata;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    Metadata* metadata;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

// Error logging function
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

DataStructure* initialize_data_structure(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity * sizeof(Record) > MAX_MEMORY_THRESHOLD) {
        log_error("Invalid or excessive capacity requested.");
        return NULL;
    }

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) {
        log_error("Failed to allocate memory for data structure.");
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = malloc(initial_capacity * sizeof(long));
    ds->keys = malloc(initial_capacity * sizeof(int));
    ds->records = malloc(initial_capacity * sizeof(Record));
    ds->metadata = malloc(initial_capacity * sizeof(Metadata));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->metadata) {
        log_error("Failed to allocate memory for one or more components.");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->metadata);
        free(ds);
        return NULL;
    }

    ds->capacity = initial_capacity;
    ds->count = 0;

    return ds;
}

int add_record(DataStructure* ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);

    if (ds->count >= ds->capacity || ds->count >= RECORD_COUNT_LIMIT) {
        log_error("Record limit reached or capacity exceeded.");
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    ds->keys[ds->count] = key;
    ds->records[ds->count].value = value;
    strncpy(ds->records[ds->count].buffer, "", sizeof(ds->records[ds->count].buffer));
    time(&(ds->records[ds->count].timestamp));

    ds->metadata[ds->count].record_ptr = &ds->records[ds->count];
    time(&(ds->metadata[ds->count].last_accessed_time));

    ds->offsets[ds->count] = (long)(&ds->records[ds->count]);
    ds->count++;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

void serialize_data_structure(DataStructure* ds, const char* filename, int binary_mode) {
    FILE* file = fopen(filename, binary_mode ? "wb" : "w");
    if (!file) {
        log_error("Failed to open file for serialization.");
        return;
    }

    pthread_mutex_lock(&ds->lock);

    size_t count = ds->count;
    fwrite(&count, sizeof(size_t), 1, file);
    fwrite(ds->keys, sizeof(int), count, file);
    fwrite(ds->records, sizeof(Record), count, file);
    fwrite(ds->metadata, sizeof(Metadata), count, file);

    pthread_mutex_unlock(&ds->lock);
    fclose(file);
}

void deserialize_data_structure(DataStructure* ds, const char* filename, int binary_mode) {
    FILE* file = fopen(filename, binary_mode ? "rb" : "r");
    if (!file) {
        log_error("Failed to open file for deserialization.");
        return;
    }

    pthread_mutex_lock(&ds->lock);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > ds->capacity) {
        log_error("Deserialized data exceeds current capacity.");
        pthread_mutex_unlock(&ds->lock);
        fclose(file);
        return;
    }

    fread(ds->keys, sizeof(int), count, file);
    fread(ds->records, sizeof(Record), count, file);
    fread(ds->metadata, sizeof(Metadata), count, file);

    ds->count = count;

    pthread_mutex_unlock(&ds->lock);
    fclose(file);
}

void free_data_structure(DataStructure* ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->metadata);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Example usage
int main() {
    DataStructure* ds = initialize_data_structure(10);
    if (!ds) return EXIT_FAILURE;

    add_record(ds, 1, 100);
    serialize_data_structure(ds, "data.bin", 1);
    deserialize_data_structure(ds, "data.bin", 1);

    free_data_structure(ds);
    return EXIT_SUCCESS;
}
```

