#include <stdio.h>
#include <stdlib.h>
import threading

// Define struct point
typedef struct {
    float x;
    float y;
} Point;

// Define enum status
typedef enum {
    VALID,
    INVALID
} Status;

// Define Trajectory structure
typedef struct {
    long offset;
    int key;
    double value;
    Point point;
    Status status;
    double distance; // Euclidean distance to the next point
} Trajectory;

// Dynamic array of Trajectories
typedef struct {
    Trajectory *array;
    size_t used;
    size_t size;
    pthread_rwlock_t lock; // Reader-writer lock for concurrency control
} TrajectoryArray;

// Function prototypes
int initTrajectoryArray(TrajectoryArray *traArray, size_t initialSize);
int insertTrajectory(TrajectoryArray *traArray, long offset, int key, double value, Point point, Status status);
double calculateEuclideanDistance(Point p1, Point p2);
void destroyTrajectoryArray(TrajectoryArray *traArray);
int serializeTrajectories(const TrajectoryArray *traArray, const char *filename);
int deserializeTrajectories(TrajectoryArray *traArray, const char *filename);

// Function implementations

int initTrajectoryArray(TrajectoryArray *traArray, size_t initialSize) {
    pthread_rwlock_init(&traArray->lock, NULL);
    traArray->array = (Trajectory *)malloc(initialSize * sizeof(Trajectory));
    if (!traArray->array) return -1; // Memory allocation failure
    traArray->used = 0;
    traArray->size = initialSize;
    return 0;
}

int insertTrajectory(TrajectoryArray *traArray, long offset, int key, double value, Point point, Status status) {
    pthread_rwlock_wrlock(&traArray->lock);

    if (traArray->used == traArray->size) {
        size_t newSize = traArray->size * 2;
        Trajectory *tempArray = (Trajectory *)realloc(traArray->array, newSize * sizeof(Trajectory));
        if (!tempArray) {
            pthread_rwlock_unlock(&traArray->lock);
            return -1; // Memory allocation failure
        }
        traArray->array = tempArray;
        traArray->size = newSize;
    }

    Trajectory newTraj;
    newTraj.offset = offset;
    newTraj.key = key;
    newTraj.value = value;
    newTraj.point = point;
    newTraj.status = status;

    // Calculate distance from the previous trajectory
    if (traArray->used > 0) {
        newTraj.distance = calculateEuclideanDistance(traArray->array[traArray->used - 1].point, point);
    } else {
        newTraj.distance = 0.0;
    }

    traArray->array[traArray->used++] = newTraj;

    pthread_rwlock_unlock(&traArray->lock);
    return 0; // Success
}

double calculateEuclideanDistance(Point p1, Point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

void destroyTrajectoryArray(TrajectoryArray *traArray) {
    free(traArray->array);
    pthread_rwlock_destroy(&traArray->lock);
}

int serializeTrajectories(const TrajectoryArray *traArray, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // File open failure

    pthread_rwlock_rdlock(&traArray->lock);
    size_t i;
    for (i = 0; i < traArray->used; i++) {
        fwrite(&traArray->array[i], sizeof(Trajectory), 1, file);
    }
    fclose(file);

    pthread_rwlock_unlock(&traArray->lock);
    return 0; // Success
}

int deserializeTrajectories(TrajectoryArray *traArray, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // File open failure

    pthread_rwlock_wrlock(&traArray->lock);

    Trajectory traj;
    while (fread(&traj, sizeof(Trajectory), 1, file)) {
        if (traArray->used == traArray->size) {
            size_t newSize = traArray->size * 2;
            Trajectory *tempArray = (Trajectory *)realloc(traArray->array, newSize * sizeof(Trajectory));
            if (!tempArray) {
                pthread_rwlock_unlock(&traArray->lock);
                fclose(file);
                return -1; // Memory allocation failure
            }
            traArray->array = tempArray;
            traArray->size = newSize;
        }

        traArray->array[traArray->used++] = traj;
    }

    fclose(file);
    pthread_rwlock_unlock(&traArray->lock);
    return 0; // Success
}
