<?php

use League\OAuth2\Client\Provider\GenericProvider;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

require 'vendor/autoload.php';

session_start();

// Configuration for the OAuth provider
$providerConfig = [
    'clientId'                => 'your-client-id',
    'clientSecret'            => 'your-client-secret',
    'redirectUri'             => 'https://yourapp.com/callback',
    'urlAuthorize'            => 'https://thirdparty.com/oauth2/authorize',
    'urlAccessToken'          => 'https://thirdparty.com/oauth2/token',
    'urlResourceOwnerDetails' => 'https://thirdparty.com/oauth2/resource'
];

// Logger setup
$logger = new Logger('oauth_logger');
$logger->pushHandler(new StreamHandler(__DIR__.'/logs/oauth.log', Logger::DEBUG));

// OAuth Provider instance
$provider = new GenericProvider($providerConfig);

function authenticateUser()
{
    global $provider, $logger;

    if (!isset($_GET['code'])) {
        // Redirect to third-party authentication page
        $authorizationUrl = $provider->getAuthorizationUrl();
        $_SESSION['oauth2state'] = $provider->getState();
        header('Location: ' . $authorizationUrl);
        exit;
    } elseif (empty($_GET['state']) || ($_GET['state'] !== $_SESSION['oauth2state'])) {
        // State validation failed
        unset($_SESSION['oauth2state']);
        $logger->warning('Invalid state returned from provider.');
        exit('Invalid state');
    }

    try {
        // Get access token using authorization code grant
        $accessToken = $provider->getAccessToken('authorization_code', [
            'code' => $_GET['code']
        ]);

        // Save the access token in session securely
        $_SESSION['access_token'] = $accessToken;

        // Fetch user details from provider's API
        $resourceOwner = $provider->getResourceOwner($accessToken);

        // Sync with existing user management system
        syncUserProfile($resourceOwner);

    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        // Handle errors gracefully
        $logger->error('Error getting access token: ' . $e->getMessage());
        exit('Authentication failed: ' . $e->getMessage());
    }
}

function refreshAccessToken()
{
    global $provider, $logger;

    if (isset($_SESSION['access_token']) && $_SESSION['access_token']->hasExpired()) {
        try {
            // Refresh the access token
            $newAccessToken = $provider->getAccessToken('refresh_token', [
                'refresh_token' => $_SESSION['access_token']->getRefreshToken()
            ]);

            // Update session with new token details
            $_SESSION['access_token'] = $newAccessToken;

        } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
            $logger->error('Error refreshing access token: ' . $e->getMessage());
            unset($_SESSION['access_token']);
        }
    }
}

function syncUserProfile($resourceOwner)
{
    global $logger;

    try {
        // Example function to get user details from your existing system
        $existingUser = getUserFromDatabase($resourceOwner->getId());

        if (!$existingUser) {
            // Create new user in database
            createUserInDatabase($resourceOwner);
        } else {
            // Update existing user profile
            updateUserProfile($existingUser, $resourceOwner);
        }
    } catch (Exception $e) {
        $logger->error('Error syncing user profile: ' . $e->getMessage());
    }
}

