        }

        results[i].measurementTag.frequencyBand = freqBand;
        results[i].measurementTag.bandwidth = bw;

        size_t cellsCount = numCells[i];
        if (cellsCount > maxNumCellsPerReport) {
            fprintf(stderr, "Exceeded maximum number of cells per report\n");
            free(results);
            return NULL;
        }

        for (size_t j = 0; j < cellsCount; ++j) {
            int cellId = cellIds[i][j];
            int signalStrength = signalStrengths[i][j];

            if (!validate_signal_strength(signalStrength)) {
                fprintf(stderr, "Invalid signal strength\n");
                free(results);
                return NULL;
            }

            results[i].rrcMeasReport.cells[j].cellId = cellId;
            results[i].rrcMeasReport.cells[j].signalStrength = signalStrength;
        }
        results[i].rrcMeasReport.numCells = cellsCount;
    }

    return results;
}

void free_ue_measurement_results(UeMeasurementResult* results, size_t numResults) {
    if (results == NULL)
        return;

    // In this example, no further dynamic allocation inside UeMeasurementResult structures
    free(results);
}
