typedef struct {
    pthread_mutex_t lock;
    NFAPI_MESSAGE messages[100]; // Assume max 100 messages for scalability.
    size_t message_count;
} NetworkInterface;

// Initialize and configure a network interface
void initialize_network_interface(NetworkInterface *interface) {
    if (!interface) return;

    // Initialize mutex for thread-safe operations
    pthread_mutex_init(&interface->lock, NULL);

    // Simulate fetching dynamic parameters from an external configuration service
    int freq_limit = fetch_dynamic_frequency_limit();
    int bw_limit = fetch_dynamic_bandwidth_limit();

    // Configuration setup
    for (size_t i = 0; i < sizeof(interface->messages) / sizeof(NFAPI_MESSAGE); ++i) {
        NFAPI_CONFIG_REQUEST config_request;
        config_request.frequency = freq_limit - (i * 10); // Example frequency configuration
        config_request.bandwidth = bw_limit - (i * 2);    // Example bandwidth configuration
        config_request.power_level = 20;                  // Static power level for simplicity

        NFAPI_MESSAGE message;
        message.config_request = config_request;

        // Initialize logging information
        for (size_t j = 0; j < sizeof(message.logging_info) / sizeof(NFAPI_LOGGING_INFO); ++j) {
            message.logging_info[j].metric_value = 0.0;    // Mock metric value
            message.logging_info[j].timestamp = 0;         // Mock timestamp
        }
        message.log_count = 0;

        pthread_mutex_lock(&interface->lock);
        interface->messages[i] = message;
        ++interface->message_count;
        pthread_mutex_unlock(&interface->lock);
    }

    printf("Network interface initialized with %zu configuration messages.\n", interface->message_count);
}

// Function to log performance metrics
void log_performance_metrics(NetworkInterface *interface, size_t index, double metric_value) {
    if (!interface || index >= interface->message_count) return;

    pthread_mutex_lock(&interface->lock);

    NFAPI_MESSAGE *msg = &interface->messages[index];
    if (msg->log_count < sizeof(msg->logging_info) / sizeof(NFAPI_LOGGING_INFO)) {
        msg->logging_info[msg->log_count].metric_value = metric_value;
        msg->logging_info[msg->log_count].timestamp = time(NULL);
        ++msg->log_count;
    } else {
        // Handle log overflow by overwriting old logs (simple circular buffer strategy)
        memmove(&msg->logging_info[0], &msg->logging_info[1], sizeof(NFAPI_LOGGING_INFO) * (sizeof(msg->logging_info) / sizeof(NFAPI_LOGGING_INFO) - 1));
        msg->logging_info[sizeof(msg->logging_info) / sizeof(NFAPI_LOGGING_INFO) - 1].metric_value = metric_value;
        msg->logging_info[sizeof(msg->logging_info) / sizeof(NFAPI_LOGGING_INFO) - 1].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&interface->lock);

    printf("Logged performance metrics for message index %zu\n", index);
}

// Cleanup function
void cleanup_network_interface(NetworkInterface *interface) {
    if (!interface) return;

    pthread_mutex_destroy(&interface->lock);
}
