#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define INITIAL_CAPACITY 1024
#define MAX_RECORDS 1000000

typedef struct {
    int key;
    long offset;
    void *info; // Optional metadata
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Custom memory allocator (placeholder for platform-specific optimizations)
void* custom_alloc(size_t size) {
    return malloc(size);
}

void custom_free(void *ptr) {
    free(ptr);
}

// Validate record metadata
bool validate_metadata(void *info) {
    // Implement validation logic here
    return true; // Assume valid for this example
}

// Thread-safe function to add a record
int add_record(DynamicArray *array, int key, long offset, void *info) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > MAX_RECORDS) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Exceeded maximum capacity
        }
        Record *new_records = custom_alloc(new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Allocation failed
        }
        memcpy(new_records, array->records, array->count * sizeof(Record));
        custom_free(array->records);
        array->records = new_records;
        array->capacity = new_capacity;
    }

    if (!validate_metadata(info)) {
        pthread_mutex_unlock(&array->lock);
        return -3; // Invalid metadata
    }

    Record new_record = {key, offset, info};
    array->records[array->count++] = new_record;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

// Function to initialize the dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray *array = custom_alloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->records = custom_alloc(INITIAL_CAPACITY * sizeof(Record));
    if (!array->records) {
        custom_free(array);
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Function to free the dynamic array
void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        custom_free(array->records);
        custom_free(array);
    }
}

// Placeholder for data feed integration
int fetch_data_from_feed(int *key, long *offset, void **info) {
    // Simulate data fetching and validation
    static int counter = 0;
    if (counter < 10) { // Assume valid data for first 10 entries
        *key = counter++;
        *offset = counter * 1000L;
        *info = NULL; // No metadata for simplicity
        return 0; // Success
    }
    return -1; // Data feed unavailable or invalid
}

// Function to populate the dynamic array from data feed
void populate_from_feed(DynamicArray *array) {
    int key, offset;
    void *info;
    while (fetch_data_from_feed(&key, &offset, &info) == 0) {
        add_record(array, key, offset, info);
    }
}

// Serialization function (placeholder)
int serialize_records(const DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;
    fwrite(&array->count, sizeof(size_t), 1, file);
    fwrite(array->records, sizeof(Record), array->count, file);
    fclose(file);
    return 0;
}

// Deserialization function (placeholder)
DynamicArray* deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    DynamicArray *array = init_dynamic_array();
    if (!array || array->capacity < count) {
        fclose(file);
        destroy_dynamic_array(array);
        return NULL;
    }
    array->count = count;
    fread(array->records, sizeof(Record), count, file);
    fclose(file);
    return array;
}

int main() {
    DynamicArray *array = init_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    populate_from_feed(array);

    serialize_records(array, "records.bin");

    DynamicArray *loaded_array = deserialize_records("records.bin");
    if (loaded_array) {
        // Use loaded_array as needed
        destroy_dynamic_array(loaded_array);
    }

    destroy_dynamic_array(array);
    return EXIT_SUCCESS;
}
```

### Key Design Decisions:
- **Thread Safety**: Used `pthread_mutex_t` for synchronization to ensure thread safety.
- **Custom Allocator**: Placeholder functions `custom_alloc` and `custom_free` are used, allowing for platform-specific optimizations.
- **Dynamic Reallocation**: The array is resized when capacity is exceeded, doubling its size each time to balance between frequent allocations and memory usage.
- **Validation**: A simple metadata validation function is included, which can be expanded based on specific requirements.
- **Serialization**: Basic binary serialization/deserialization functions are provided for storing and retrieving records.
- **Error Handling**: Functions return error codes to indicate failure conditions, such as allocation failures or invalid data.

This implementation provides a robust starting point for managing dynamic arrays of `Record` structures with concurrency support and efficient memory management.']

