public class SystemCommandExecutor {

    public static void main(String[] args) {
        String configFilePath = "config.txt";
        String command = "top -b -n 1"; // Example system performance metrics command
        String stdoutLogPath = "stdout.log";
        String stderrLogPath = "stderr.log";

        try {
            // Delete the configuration file if it exists
            Files.deleteIfExists(Paths.get(configFilePath));

            // Set up the environment for running the command
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.redirectErrorStream(false);

            // Redirect output and error streams to log files
            try (OutputStream stdoutLog = new FileOutputStream(stdoutLogPath);
                 OutputStream stderrLog = new FileOutputStream(stderrLogPath)) {
                processBuilder.redirectOutput(ProcessBuilder.Redirect.to(stdoutLog))
                              .redirectError(ProcessBuilder.Redirect.to(stderrLog));

                Process process = processBuilder.start();

                // Wait for the command to complete
                int exitCode = process.waitFor();
                System.out.println("Process exited with code: " + exitCode);

            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
