```c
#include <stdio.h>
#include <stdlib.h>
import time.h
#include <pthread.h>

typedef struct {
    int id;
    time_t timestamp;
    int *values;
    size_t num_values;
} DataSet;

typedef struct {
    int offset;
    int key;
} Record;

#define LOG_FILE "data_processing.log"

// Function to log messages
void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Mutex for thread safety
pthread_mutex_t data_lock;

DataSet *datasets = NULL;
size_t dataset_count = 0;

void process_and_analyze_data_sets(size_t num_offsets, int key_range_min, int key_range_max) {
    long *offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        log_message("Memory allocation for offsets failed.");
        return;
    }

    int *keys = malloc(num_offsets * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        log_message("Memory allocation for keys failed.");
        return;
    }

    Record *records = malloc(num_offsets * sizeof(Record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        log_message("Memory allocation for records failed.");
        return;
    }

    srand((unsigned int) time(NULL));

    // Initialize arrays
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand();
        keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Thread safety setup
    pthread_mutex_init(&data_lock, NULL);

    // Sample function to simulate adding/updating datasets (thread-safe)
    void add_or_update_dataset(int id, time_t timestamp, int *values, size_t num_values) {
        pthread_mutex_lock(&data_lock);
        for (size_t i = 0; i < dataset_count; ++i) {
            if (datasets[i].id == id) {
                free(datasets[i].values);
                datasets[i] = (DataSet){id, timestamp, values, num_values};
                log_message("Dataset updated.");
                pthread_mutex_unlock(&data_lock);
                return;
            }
        }

        DataSet *new_datasets = realloc(datasets, (dataset_count + 1) * sizeof(DataSet));
        if (!new_datasets) {
            log_message("Memory reallocation for datasets failed.");
            pthread_mutex_unlock(&data_lock);
            return;
        }

        new_datasets[dataset_count++] = (DataSet){id, timestamp, values, num_values};
        datasets = new_datasets;
        log_message("New dataset added.");
        pthread_mutex_unlock(&data_lock);
    }

    // Sample function to filter datasets by minimum number of integer values
    void filter_datasets(size_t min_num_values) {
        pthread_mutex_lock(&data_lock);

        size_t count_filtered = 0;
        for (size_t i = 0; i < dataset_count; ++i) {
            if (datasets[i].num_values >= min_num_values) {
                datasets[count_filtered++] = datasets[i];
            } else {
                free(datasets[i].values);
                log_message("Dataset filtered out.");
            }
        }

        size_t new_size = realloc(datasets, count_filtered * sizeof(DataSet));
        if (!new_size && dataset_count > 0) { // Check for failure but allow empty list
            log_message("Memory reallocation during filtering failed.");
        } else {
            datasets = (DataSet *) new_size;
            dataset_count = count_filtered;
        }

        pthread_mutex_unlock(&data_lock);
    }

    // Ensure resources are freed at the end
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&data_lock);

    for (size_t i = 0; i < dataset_count; ++i) {
        free(datasets[i].values);
    }
    free(datasets);
}

int main() {
    // Example usage
    process_and_analyze_data_sets(10, 1, 100);
    return 0;
}
