### C Library (`records.c`)

```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

Record* allocate_records(int num_records, int range_min, int range_max) {
    // Seed the random number generator
    srand((unsigned int) time(NULL));

    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Initialize records with random keys and offsets
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() % (10000 * num_records); // Example offset range
        records[i].key = range_min + rand() % (range_max - range_min + 1);
    }

    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
    }
}
```

### Java Application (`MainApp.java`)

```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class MainApp {

    static {
        System.loadLibrary("records"); // Load the C library
    }

    private native Record[] allocateRecords(int numRecords, int rangeMin, int rangeMax);
    private native void freeRecords(Record[] records);

    public static void main(String[] args) throws IOException {
        new MainApp().run(args);
    }

    private void run(String[] args) throws IOException {
        if (args.length < 3) {
            System.err.println("Usage: java MainApp <numRecords> <rangeMin> <rangeMax>");
            return;
        }

        int numRecords = Integer.parseInt(args[0]);
        int rangeMin = Integer.parseInt(args[1]);
        int rangeMax = Integer.parseInt(args[2]);

        // Allocate records using the C library
        Record[] records = allocateRecords(numRecords, rangeMin, rangeMax);
        if (records == null) {
            System.err.println("Failed to allocate records.");
            return;
        }

        try {
            executeSystemCommand();
        } finally {
            freeRecords(records);  // Ensure memory is freed
        }
    }

    private void executeSystemCommand() throws IOException {
        String[] command = {"top", "-b", "-n", "1"};
        ProcessBuilder pb = new ProcessBuilder(command);

        File logFileOut = Files.createTempFile("performance_metrics_output_", ".log").toFile();
        logFileOut.setReadable(true, false);  // Read by owner only
        File logFileErr = Files.createTempFile("performance_metrics_error_", ".log").toFile();
        logFileErr.setReadable(true, false);

        pb.redirectOutput(new FileOutputStream(logFileOut));
        pb.redirectErrorStream(false);
        pb.redirectError(new FileOutputStream(logFileErr));

        Process process = pb.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);  // Or handle lines as needed
            }
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.err.println("Command execution failed with exit code: " + exitCode);
        }
    }

    private static class Record extends java.util.concurrent.atomic.AtomicReference<Record> {
        long offset;
        int key;

        public Record(long offset, int key) {
            this.offset = offset;
            this.key = key;
        }
    }
}
```

### Makefile

```make
CC=gcc
CFLAGS=-Wall -Wextra -fPIC -shared
JAVA_FILES=MainApp.java
C_FILES=records.c

all: librecords.so MainApp.class

