#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct Record {
    int offset;
    char key[32];
    struct {
        time_t created_at;
        time_t updated_at;
    } timestamps;
    char buffer[BUFFER_SIZE];
} Record;

typedef struct Node {
    Record *record;
    struct Node *prev, *next;
} Node;

typedef struct LRUCache {
    size_t capacity;
    size_t size;
    Node *head, *tail;
    pthread_rwlock_t lock;
    Record **records;
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_rwlock_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(LRUCache *cache) {
    Node *current = cache->head;
    while (current) {
        Node *next = current->next;
        free(current->record);
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&cache->lock);
    free(cache->records);
    free(cache);
}

void move_to_head(LRUCache *cache, Node *node) {
    if (node == cache->head) return;

    if (node == cache->tail) {
        cache->tail = node->prev;
        cache->tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    node->next = cache->head;
    node->prev = NULL;
    cache->head->prev = node;
    cache->head = node;
}

void add_record(LRUCache *cache, Record *record) {
    pthread_rwlock_wrlock(&cache->lock);

    if (cache->size >= cache->capacity) {
        Node *lru = cache->tail;
        if (lru) {
            cache->tail = lru->prev;
            if (cache->tail) cache->tail->next = NULL;
            free(lru->record);
            free(lru);
            cache->size--;
        }
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->record = record;
    new_node->next = cache->head;
    new_node->prev = NULL;

    if (cache->head) {
        cache->head->prev = new_node;
    } else {
        cache->tail = new_node;
    }
    cache->head = new_node;
    cache->size++;

    pthread_rwlock_unlock(&cache->lock);
}

Record* get_record(LRUCache *cache, char *key) {
    pthread_rwlock_rdlock(&cache->lock);

    for (Node *node = cache->head; node != NULL; node = node->next) {
        if (strncmp(node->record->key, key, sizeof(node->record->key)) == 0) {
            move_to_head(cache, node);
            pthread_rwlock_unlock(&cache->lock);
            return node->record;
        }
    }

    pthread_rwlock_unlock(&cache->lock);
    return NULL;
}

void serialize_cache(LRUCache *cache, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    fwrite(&cache->size, sizeof(size_t), 1, file);
    pthread_rwlock_rdlock(&cache->lock);

    Node *current = cache->head;
    while (current) {
        fwrite(current->record, sizeof(Record), 1, file);
        current = current->next;
    }

    pthread_rwlock_unlock(&cache->lock);
    fclose(file);
}

void deserialize_cache(LRUCache *cache, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    pthread_rwlock_wrlock(&cache->lock);

    while (cache->size > 0) {
        Node *current = cache->tail;
        if (current) {
            cache->tail = current->prev;
            if (cache->tail) cache->tail->next = NULL;
            free(current->record);
            free(current);
            cache->size--;
        }
    }

    for (size_t i = 0; i < size && !feof(file); ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        add_record(cache, record);
    }

    pthread_rwlock_unlock(&cache->lock);
    fclose(file);
}

void export_summary(LRUCache *cache) {
    pthread_rwlock_rdlock(&cache->lock);

    size_t total_length = 0;
    for (Node *node = cache->head; node != NULL; node = node->next) {
        total_length += strlen(node->record->buffer);
    }

    double average_length = cache->size > 0 ? (double)total_length / cache->size : 0.0;

    printf("Number of records: %zu\n", cache->size);
    printf("Average buffer length: %.2f\n", average_length);

    pthread_rwlock_unlock(&cache->lock);
}

void* log_access(void *arg) {
    // Placeholder for logging framework integration
    return NULL;
}

int main() {
    LRUCache *cache = create_cache(MAX_RECORDS);

    // Example usage
    Record *record = (Record*)malloc(sizeof(Record));
    strcpy(record->key, "example_key");
    strcpy(record->buffer, "Example data");
    record->timestamps.created_at = time(NULL);
    add_record(cache, record);

    export_summary(cache);

    serialize_cache(cache, "cache.dat");
    deserialize_cache(cache, "cache.dat");

    destroy_cache(cache);
    return 0;
}
```

This code provides a basic implementation of an LRU cache with thread-safe access using read-write locks. It includes functions for adding and retrieving records, serializing and deserializing the cache to/from a file, and exporting a summary report. The logging integration is represented as a placeholder function.']

