class CancellationToken {
  constructor() {
    this.isCancelled = false;
  }

  cancel() {
    this.isCancelled = true;
  }
}

async function reduceAsync(
  array,
  initialValue,
  syncCallback,
  asyncCallback,
  cancellationToken = new CancellationToken()
) {
  let accumulator = initialValue;

  for (let i = 0; i < array.length; i++) {
    if (cancellationToken.isCancelled) break;

    const currentValue = array[i];

    try {
      if (asyncCallback && typeof asyncCallback === 'function') {
        // Asynchronous processing with cancellation support
        accumulator = await new Promise((resolve, reject) => {
          const processAsync = async () => {
            try {
              resolve(await asyncCallback(currentValue, accumulator));
            } catch (error) {
              reject(error);
            }
          };

          if (!cancellationToken.isCancelled) {
            processAsync();
          } else {
            reject(new Error('Operation cancelled'));
          }
        });
      } else {
        // Synchronous processing
        accumulator = syncCallback(currentValue, accumulator);
      }

    } catch (error) {
      throw new Error(`Error during reduction at index ${i}: ${error.message}`);
    }
  }

  return accumulator;
}

// Test Cases

async function testReduceAsync() {
  try {
    // Test with synchronous callback
    const sum = await reduceAsync([1, 2, 3], 0, (x, y) => x + y);
    console.log('Sum:', sum); // Expected: 6

    // Test with asynchronous callback
    const asyncAdd = (currentValue, accumulator) =>
      new Promise((resolve) =>
        setTimeout(() => resolve(currentValue + accumulator), 100)
      );

    const asyncSum = await reduceAsync([1, 2, 3], 0, null, asyncAdd);
    console.log('Async Sum:', asyncSum); // Expected: 6

    // Test with cancellation
    const cancellationToken = new CancellationToken();
    setTimeout(() => cancellationToken.cancel(), 50);

    try {
      await reduceAsync([1, 2, 3], 0, (x, y) => x + y, null, cancellationToken);
    } catch (error) {
      console.log('Cancellation Error:', error.message); // Expected: Operation cancelled
    }

    // Test with empty array
    const emptySum = await reduceAsync([], 10, (x, y) => x + y);
    console.log('Empty Array Sum:', emptySum); // Expected: 10

    // Test with single element
    const singleElementSum = await reduceAsync([5], 0, (x, y) => x + y);
    console.log('Single Element Sum:', singleElementSum); // Expected: 5

    // Complex scenario with frequent cancellation requests and asynchronous delays
    cancellationToken.cancel(); // Start in cancelled state
    try {
      await reduceAsync([1, 2, 3], 0, null, asyncAdd, cancellationToken);
    } catch (error) {
      console.log('Complex Scenario Error:', error.message); // Expected: Operation cancelled

      // Retry logic demonstration
      cancellationToken = new CancellationToken(); // Reset token for retry
      const complexResult = await reduceAsync([1, 2, 3], 0, null, asyncAdd, cancellationToken);
      console.log('Complex Result after Retry:', complexResult); // Expected: 6
    }

  } catch (error) {
    console.error('Unexpected Error:', error.message);
  }
}

testReduceAsync();
