['Below is an implementation that addresses your requirements in C. The code manages memory for three distinct data structures: `offsets`, `keys`, and `records`. It also includes a cache mechanism with LRU eviction policy and ensures thread safety using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct CacheItem {
    int key;
    void *data;
    struct CacheItem *prev, *next;
} CacheItem;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    CacheItem *head, *tail;
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    if (capacity == 0) return NULL;
    LRUCache *cache = malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->head = cache->tail = NULL;
    return cache;
}

void free_cache(LRUCache *cache) {
    if (!cache) return;
    CacheItem *current = cache->head;
    while (current) {
        CacheItem *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void move_to_front(LRUCache *cache, CacheItem *item) {
    if (cache->head == item) return;
    if (item->prev) item->prev->next = item->next;
    if (item->next) item->next->prev = item->prev;
    if (cache->tail == item) cache->tail = item->prev;

    item->next = cache->head;
    item->prev = NULL;
    if (cache->head) cache->head->prev = item;
    cache->head = item;
    if (!cache->tail) cache->tail = item;
}

void put_cache(LRUCache *cache, int key, void *data) {
    pthread_mutex_lock(&cache->lock);

    CacheItem *item = cache->head;
    while (item) {
        if (item->key == key) {
            free(item->data);
            item->data = data;
            move_to_front(cache, item);
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        item = item->next;
    }

    if (cache->count == cache->capacity) {
        CacheItem *old_tail = cache->tail;
        cache->tail = old_tail->prev;
        if (cache->tail) cache->tail->next = NULL;
        free(old_tail->data);
        free(old_tail);
        cache->count--;
    }

    item = malloc(sizeof(CacheItem));
    if (!item) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }
    item->key = key;
    item->data = data;
    item->next = cache->head;
    item->prev = NULL;
    if (cache->head) cache->head->prev = item;
    cache->head = item;
    if (!cache->tail) cache->tail = item;

    cache->count++;
    pthread_mutex_unlock(&cache->lock);
}

void* get_cache(LRUCache *cache, int key) {
    pthread_mutex_lock(&cache->lock);

    CacheItem *item = cache->head;
    while (item) {
        if (item->key == key) {
            move_to_front(cache, item);
            void *data = item->data;
            pthread_mutex_unlock(&cache->lock);
            return data;
        }
        item = item->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

record* manage_memory(size_t num_records, int max_key_value, size_t cache_size_limit,
                      int min_bound, int max_bound) {
    if (num_records <= 0 || max_key_value < 0 || cache_size_limit == 0 || min_bound > max_bound)
        return NULL;

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc((max_key_value + 1) * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    LRUCache *cache = create_cache(cache_size_limit);
    if (!cache) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Populate keys
    for (int i = 0; i <= max_key_value; ++i) {
        keys[i] = i;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_bound + rand() % (max_bound - min_bound + 1);
    }

    // Example cache usage (for demonstration purposes)
    for (size_t i = 0; i < num_records; ++i) {
        char *data = malloc(10); // Dummy data
        snprintf(data, 10, "Record %zu", i);
        put_cache(cache, records[i].value, data);

        void *cached_data = get_cache(cache, records[i].value);
        if (cached_data)
            printf("Cache hit: %s\n", (char*)cached_data);
    }

    // Cleanup
    free_cache(cache);

    return records;
}

int main() {
    size_t num_records = 1000;
    int max_key_value = 50;
    size_t cache_size_limit = 10;
    int min_bound = 1, max_bound = 100;

    record *records = manage_memory(num_records, max_key_value, cache_size_limit, min_bound, max_bound);
    if (records) {
        printf("Memory management and caching successful.\n");
        free(records);
    } else {
        printf("Failed to allocate memory or perform operations.\n");
    }

    return 0;
}
```

