    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = malloc(block_size * total_blocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    if (!mp || mp->used_blocks >= mp->total_blocks) return NULL;

    pthread_mutex_lock(&mp->lock);
    void *block = (char*)mp->pool + mp->used_blocks * mp->block_size;
    ++mp->used_blocks;
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void free_memory_pool(MemoryPool *mp) {
