    fwrite(&record->offset, sizeof(size_t), 1, file);
    size_t len = strlen(record->value) + 1;
    fwrite(&len, sizeof(size_t), 1, file);
    fwrite(record->value, sizeof(char), len, file);
}

void deserialize_record(Record *record, FILE *file) {
    fread(&record->key, sizeof(int64_t), 1, file);
    fread(&record->offset, sizeof(size_t), 1, file);
    size_t len;
    fread(&len, sizeof(size_t), 1, file);
    record->value = (char *)malloc(len * sizeof(char));
    if (record->value) {
        fread(record->value, sizeof(char), len, file);
    }
}

int add_record(Record *record) {
    pthread_mutex_lock(&lock);

    // Check for null pointers
    if (!record || record->value == NULL) return ERROR_NULL_POINTER;

    // Ensure key uniqueness
    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == record->key) {
            pthread_mutex_unlock(&lock);
            return ERROR_DUPLICATE_KEY;
        }
    }

    // Check maximum size
    if (strlen(record->value) > MAX_RECORD_SIZE) {
        pthread_mutex_unlock(&lock);
        return -3;  // Arbitrary error code for size check
    }

    records[record_count++] = *record;

    FILE* file = fopen(STORAGE_FILE, "ab");
    if (!file) {
        pthread_mutex_unlock(&lock);
        return -4;  // Error opening file
    }
    serialize_record(record, file);
    fclose(file);

    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

int update_record(int64_t key, const char* value) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == key) {
            free(records[i].value);

            records[i].value = strdup(value); // Allocate new memory and copy string
            if (!records[i].value) {
                pthread_mutex_unlock(&lock);
                return -1;  // Memory allocation error
            }

            FILE* file = fopen(STORAGE_FILE, "r+b");
            if (!file) {
                pthread_mutex_unlock(&lock);
                return -4;  // Error opening file
            }
            fseek(file, i * sizeof(Record), SEEK_SET);  // Approximation for position
            serialize_record(&records[i], file);
            fclose(file);

            pthread_mutex_unlock(&lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&lock);
    return -5;  // Record not found error code
}

int delete_record(int64_t key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == key) {
            free(records[i].value);

            memmove(&records[i], &records[i + 1], (record_count - i - 1) * sizeof(Record));
            --record_count;

            FILE* file = fopen(STORAGE_FILE, "r+b");
            if (!file) {
                pthread_mutex_unlock(&lock);
                return -4;  // Error opening file
            }
            ftruncate(fileno(file), (i + record_count) * sizeof(Record)); // Truncate file size
            fclose(file);

            pthread_mutex_unlock(&lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&lock);
    return -5;  // Record not found error code
}

const Record* get_record(int64_t key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; ++i) {
        if (records[i].key == key) {
            const Record *record = &records[i];
            pthread_mutex_unlock(&lock);
            return record;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

