from flask import Flask, request, jsonify
import threading

app = Flask(__name__)
library_lock = threading.Lock()

@app.route('/records', methods=['POST'])
def add_record():
    data = request.json
    key = data.get('key')
    value = data.get('value')

    if not key or not value:
        return jsonify({'error': 'Missing key or value'}), 400

    with library_lock:
        # Simulate calling the C library function
        result = add_record(key, value)

    if result == SUCCESS:
        return jsonify({'message': 'Record added successfully'}), 201
    elif result == ERROR_NULL_POINTER:
        return jsonify({'error': 'Null pointer provided'}), 400
    elif result == ERROR_DUPLICATE_KEY:
        return jsonify({'error': 'Duplicate key'}), 409
    else:
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/records/<int:key>', methods=['PUT'])
def update_record(key):
    value = request.json.get('value')

    if not value:
        return jsonify({'error': 'Missing value'}), 400

    with library_lock:
        result = update_record(key, value)

    if result == SUCCESS:
        return jsonify({'message': 'Record updated successfully'}), 200
    elif result == -5:  # Record not found error code
        return jsonify({'error': 'Record not found'}), 404
    else:
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/records/<int:key>', methods=['DELETE'])
def delete_record(key):
    with library_lock:
        result = delete_record(key)

    if result == SUCCESS:
        return jsonify({'message': 'Record deleted successfully'}), 200
    elif result == -5:  # Record not found error code
        return jsonify({'error': 'Record not found'}), 404
    else:
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/records/<int:key>', methods=['GET'])
def get_record(key):
    with library_lock:
        record = get_record(key)

    if record:
        return jsonify({
            'key': record.key,
            'value': record.value
        }), 200
    else:
        return jsonify({'error': 'Record not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
