#define BLOCK_SIZE 1024
#define MAX_DESCRIPTION_LENGTH 50

typedef struct Task {
    int index;
    char description[MAX_DESCRIPTION_LENGTH + 1];
    double estimated_time;
} Task;

typedef struct ProjectNode {
    char name[100]; // Assuming a reasonable max length for project names
    int priority;
    bool status;
    Task* tasks;
    size_t task_count;
    struct ProjectNode* next;
} ProjectNode;

typedef struct MemoryManager {
    void* memory_pool;
    size_t total_size;
    size_t used_size;
    size_t max_projects;
    size_t current_project_count;
    size_t max_tasks;
    size_t current_task_count;
} MemoryManager;

MemoryManager* init_memory_manager(size_t available_bytes) {
    MemoryManager* mem_mgr = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mem_mgr) return NULL;

    size_t blocks = (available_bytes + BLOCK_SIZE - 1) / BLOCK_SIZE;
    mem_mgr->memory_pool = malloc(blocks * BLOCK_SIZE);
    if (!mem_mgr->memory_pool) {
        free(mem_mgr);
        return NULL;
    }

    mem_mgr->total_size = blocks * BLOCK_SIZE;
    mem_mgr->used_size = 0;
    mem_mgr->max_projects = available_bytes / (sizeof(ProjectNode) + MAX_DESCRIPTION_LENGTH);
    mem_mgr->current_project_count = 0;
    mem_mgr->max_tasks = available_bytes / sizeof(Task);
    mem_mgr->current_task_count = 0;

    return mem_mgr;
}

bool allocate_memory(MemoryManager* mem_mgr, size_t size, void** out_ptr) {
    if (mem_mgr->used_size + size > mem_mgr->total_size) return false;

    *out_ptr = ((char*)mem_mgr->memory_pool) + mem_mgr->used_size;
    mem_mgr->used_size += size;
    return true;
}

void free_memory_manager(MemoryManager* mem_mgr) {
    if (mem_mgr) {
        free(mem_mgr->memory_pool);
        free(mem_mgr);
    }
}

bool add_project(MemoryManager* mem_mgr, const char* name, int priority, bool status) {
    if (mem_mgr->current_project_count >= mem_mgr->max_projects) return false;

    ProjectNode* project = (ProjectNode*)malloc(sizeof(ProjectNode));
    if (!project || !allocate_memory(mem_mgr, sizeof(char[100]), &((char*)project)[sizeof(ProjectNode)])) {
        free(project);
        return false;
    }

    strcpy(project->name, name);
    project->priority = priority;
    project->status = status;
    project->tasks = NULL;
    project->task_count = 0;

    // Add to linked list
    project->next = mem_mgr->memory_pool; // Simplified for demonstration
    ((char*)mem_mgr->memory_pool)[0] = (char)project; // Store pointer in first byte

    mem_mgr->current_project_count++;
    return true;
}

bool add_task(MemoryManager* mem_mgr, int project_index, const char* description, double estimated_time) {
    if (mem_mgr->current_task_count >= mem_mgr->max_tasks) return false;

    ProjectNode* proj = ((ProjectNode*)((char*)mem_mgr->memory_pool)[project_index * sizeof(ProjectNode)]);
    Task* task = (Task*)((char*)(proj->tasks) + proj->task_count * sizeof(Task));
    if (!allocate_memory(mem_mgr, sizeof(Task), (void**)&task)) return false;

    task->index = project_index;
    strncpy(task->description, description, MAX_DESCRIPTION_LENGTH);
    task->estimated_time = estimated_time;

    proj->task_count++;
    mem_mgr->current_task_count++;

    return true;
}

void random_description(char* buffer, size_t length) {
    const char valid_chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        buffer[i] = valid_chars[rand() % (sizeof(valid_chars) - 1)];
    }
    buffer[length - 1] = '\0';
}

void serialize(MemoryManager* mem_mgr, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&mem_mgr->current_project_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < mem_mgr->current_project_count; ++i) {
        ProjectNode* project = ((ProjectNode*)((char*)mem_mgr->memory_pool)[i * sizeof(ProjectNode)]);
        fwrite(&project->priority, sizeof(int), 1, file);
        fwrite(project->name, sizeof(char[100]), 1, file);
        fwrite(&project->status, sizeof(bool), 1, file);

        fwrite(&project->task_count, sizeof(size_t), 1, file);
        for (size_t j = 0; j < project->task_count; ++j) {
            Task task = *(((Task*)project->tasks) + j);
            fwrite(&task.index, sizeof(int), 1, file);
            size_t desc_length = strlen(task.description);
            fwrite(&desc_length, sizeof(size_t), 1, file);
            fwrite(task.description, sizeof(char), desc_length, file);
            fwrite(&task.estimated_time, sizeof(double), 1, file);
        }
    }

    fclose(file);
}

bool deserialize(MemoryManager* mem_mgr, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return false;

    size_t project_count;
    fread(&project_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < project_count; ++i) {
        ProjectNode project;
        fread(&project.priority, sizeof(int), 1, file);
        fread(project.name, sizeof(char[100]), 1, file);
        fread(&project.status, sizeof(bool), 1, file);

        size_t task_count;
        fread(&task_count, sizeof(size_t), 1, file);
        project.tasks = (Task*)malloc(task_count * sizeof(Task));

        for (size_t j = 0; j < task_count; ++j) {
            Task* task = &project.tasks[j];
            fread(&task->index, sizeof(int), 1, file);

            size_t desc_length;
            fread(&desc_length, sizeof(size_t), 1, file);
            fread(task->description, sizeof(char), desc_length, file);
            task->description[desc_length] = '\0';

            fread(&task->estimated_time, sizeof(double), 1, file);
        }

        // Add to linked list
        project.next = mem_mgr->memory_pool;
        ((char*)mem_mgr->memory_pool)[i * sizeof(ProjectNode)] = (char)&project;
    }

    fclose(file);
    return true;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
