#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define WINDOW_SIZE_MS 150

typedef struct {
    char id[64];
    size_t size;
    time_t timestamp;
    unsigned int flags;
    char src_ip[16];
    char dest_ip[16];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} SlidingWindow;

typedef struct {
    double cumulative_checksum;
    char highest_id[64];
    double packet_loss_rate;
    int geo_distribution[10]; // Simplified example
} PerformanceMetrics;

// Configuration structure for thresholds and other parameters
typedef struct {
    size_t max_packet_size;
    int frequency_threshold;
    int geo_proximity_threshold;
} Config;

// Global variables (for simplicity)
static SlidingWindow window = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};
static PerformanceMetrics metrics = {0, "", 0.0, {0}};
static pthread_mutex_t metrics_lock = PTHREAD_MUTEX_INITIALIZER;
static Config config = {1024, 10, 5}; // Example defaults

// Helper functions
unsigned int calculate_checksum(Packet *packet) {
    unsigned int checksum = 0;
    char *data = (char*) packet;
    for (size_t i = 0; i < sizeof(Packet); ++i) {
        checksum += data[i];
    }
    return checksum;
}

int is_packet_valid(Packet *packet, Config *config) {
    if (packet->size > config->max_packet_size) return 0;
    // Additional validation logic here
    return 1;
}

void update_sliding_window(Packet *packet) {
    pthread_mutex_lock(&window.lock);
    // Remove old packets from the window
    time_t current_time = time(NULL);
    for (int i = 0; i < window.count; ++i) {
        if ((current_time - window.packets[i].timestamp) > WINDOW_SIZE_MS / 1000.0) {
            memmove(&window.packets[i], &window.packets[i + 1],
                    (window.count - i - 1) * sizeof(Packet));
            --window.count;
            --i; // Adjust index due to move
        }
    }

    // Add new packet
    if (window.count < MAX_PACKETS) {
        window.packets[window.count++] = *packet;
    } else {
        memmove(&window.packets[0], &window.packets[1],
                sizeof(Packet) * (MAX_PACKETS - 1));
        window.packets[MAX_PACKETS - 1] = *packet;
    }
    pthread_mutex_unlock(&window.lock);
}

void process_packet(Packet *packet, Config *config) {
    if (!is_packet_valid(packet, config)) return;

    unsigned int checksum = calculate_checksum(packet);

    pthread_mutex_lock(&metrics_lock);
    metrics.cumulative_checksum += checksum;
    // Update highest_id if necessary
    if (checksum > 0 && strcmp(metrics.highest_id, "") == 0) {
        strncpy(metrics.highest_id, packet->id, sizeof(metrics.highest_id));
    }
    // Simulate packet loss calculation and geo distribution update
    pthread_mutex_unlock(&metrics_lock);

    update_sliding_window(packet);
}

void *packet_processing_thread(void *arg) {
    Packet *packet = (Packet *) arg;
    process_packet(packet, &config);
    return NULL;
}

// Main function to be called with incoming packets
void handle_network_packets(Packet **packets, int packet_count) {
    pthread_t threads[packet_count];
    for (int i = 0; i < packet_count; ++i) {
        if (pthread_create(&threads[i], NULL, packet_processing_thread, (void *) &packets[i]) != 0) {
            perror("Failed to create thread");
            continue;
        }
    }

    for (int i = 0; i < packet_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example of returning metrics
PerformanceMetrics get_performance_metrics() {
    PerformanceMetrics local_metrics;
    pthread_mutex_lock(&metrics_lock);
    local_metrics.cumulative_checksum = metrics.cumulative_checksum;
    strncpy(local_metrics.highest_id, metrics.highest_id, sizeof(local_metrics.highest_id));
    // Assume packet_loss_rate and geo_distribution are updated elsewhere
    local_metrics.packet_loss_rate = metrics.packet_loss_rate;
    memcpy(local_metrics.geo_distribution, metrics.geo_distribution, sizeof(metrics.geo_distribution));
    pthread_mutex_unlock(&metrics_lock);
    return local_metrics;
}
