```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define BLOCK_SIZE 1024
#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
    float extra_field;
} record;

typedef struct {
    long timestamp;
    int record_id;
    char operation[10]; // "INSERT", "UPDATE", "DELETE"
} log_entry;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    log_entry *logs;
    size_t offsets_count, keys_count, records_count, logs_count;
    size_t max_memory_usage;
    pthread_mutex_t lock;
} record_storage;

void* align_to_block(void* ptr) {
    return (void*)(((uintptr_t)(ptr) + BLOCK_SIZE - 1) & ~(BLOCK_SIZE - 1));
}

record_storage* create_record_storage(size_t initial_size, size_t max_memory_usage) {
    record_storage *storage = malloc(sizeof(record_storage));

    pthread_mutex_init(&storage->lock, NULL);

    storage->offsets_count = initial_size;
    storage->keys_count = initial_size;
    storage->records_count = initial_size;
    storage->logs_count = initial_size;

    size_t current_memory_usage = 0;

    storage->offsets = (long*)align_to_block(malloc(BLOCK_SIZE));
    current_memory_usage += BLOCK_SIZE;

    storage->keys = (int*)align_to_block(malloc(BLOCK_SIZE));
    current_memory_usage += BLOCK_SIZE;

    storage->records = (record*)align_to_block(malloc(BLOCK_SIZE * sizeof(record)));
    current_memory_usage += BLOCK_SIZE * sizeof(record);

    storage->logs = (log_entry*)align_to_block(malloc(BLOCK_SIZE * sizeof(log_entry)));
    current_memory_usage += BLOCK_SIZE * sizeof(log_entry);

    storage->max_memory_usage = max_memory_usage;

    return storage;
}

int add_record(record_storage *storage, int key, record new_record) {
    pthread_mutex_lock(&storage->lock);

    if (sizeof(long) * storage->offsets_count + sizeof(int) * storage->keys_count +
        sizeof(record) * storage->records_count + sizeof(log_entry) * storage->logs_count >
        storage->max_memory_usage) {
        printf("Memory limit reached.\n");
        pthread_mutex_unlock(&storage->lock);
        return -1;
    }

    if (storage->records_count >= storage->keys_count) {
        size_t current_size = BLOCK_SIZE;
        while (current_size < storage->keys_count * sizeof(int)) current_size *= 2;

        storage->keys = realloc(align_to_block(storage->keys), current_size);
        storage->offsets = realloc(align_to_block(storage->offsets), current_size / sizeof(long));
    }

    storage->keys[storage->keys_count] = key;
    storage->records[storage->records_count++] = new_record;

    pthread_mutex_unlock(&storage->lock);

    return 0;
}

void serialize_storage(record_storage *storage, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&storage->keys_count, sizeof(storage->keys_count), 1, file);
    fwrite(storage->keys, sizeof(int), storage->keys_count, file);

    for (size_t i = 0; i < storage->records_count; ++i) {
        fwrite(&(storage->keys[i]), sizeof(int), 1, file); // Record ID
        fwrite(&(storage->records[i].value), sizeof(storage->records[i].value), 1, file);
        size_t buffer_len = strlen(storage->records[i].buffer) + 1;
        fwrite(&buffer_len, sizeof(buffer_len), 1, file);
        fwrite(storage->records[i].buffer, sizeof(char), buffer_len, file);
        fwrite(&(storage->records[i].extra_field), sizeof(storage->records[i].extra_field), 1, file);
    }

    fclose(file);
}

void deserialize_storage(record_storage *storage, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t keys_count;
    fread(&keys_count, sizeof(keys_count), 1, file);

    storage->keys_count = keys_count;
    storage->records_count = keys_count;

    free(storage->keys);
    free(storage->offsets);
    free(storage->records);
    free(storage->logs);

    storage->keys = (int*)align_to_block(malloc(BLOCK_SIZE));
    storage->offsets = (long*)align_to_block(malloc(BLOCK_SIZE));
    storage->records = (record*)align_to_block(malloc(keys_count * sizeof(record)));
    storage->logs = (log_entry*)align_to_block(malloc(BLOCK_SIZE));

    fread(storage->keys, sizeof(int), keys_count, file);

    for (size_t i = 0; i < keys_count; ++i) {
        int record_id;
        fread(&record_id, sizeof(record_id), 1, file);
        fread(&(storage->records[i].value), sizeof(storage->records[i].value), 1, file);

        size_t buffer_len;
        fread(&buffer_len, sizeof(buffer_len), 1, file);
        fread(storage->records[i].buffer, sizeof(char), buffer_len, file);

        fread(&(storage->records[i].extra_field), sizeof(storage->records[i].extra_field), 1, file);
    }

    fclose(file);
}

void free_record_storage(record_storage *storage) {
    pthread_mutex_destroy(&storage->lock);

    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    free(storage->logs);
    free(storage);
}

// Basic unit test
void run_tests() {
    record_storage *storage = create_record_storage(10, 10240); // Example initial size and memory limit

    record r1 = {42, "Example", 3.14f};
    add_record(storage, 1, r1);

    serialize_storage(storage, "test.dat");
    free_record_storage(storage);

    storage = create_record_storage(10, 10240);
    deserialize_storage(storage, "test.dat");

    free_record_storage(storage);

    printf("All tests passed.\n");
}

int main() {
    run_tests();
    return 0;
}
