std::mutex globalMutex;
std::unordered_map<int, int> cooldowns; // Maps character ID to the time when they can use a move again

struct Character {
    int id;
    std::string lastMove;
    std::chrono::system_clock::time_point cooldownUntil;

    Character(int id) : id(id), lastMove("") {}
};

std::unordered_map<int, Character> characters; // Maps character ID to their status
const char* moveNames[3] = {"Attack", "Defend", "Special"};

void createDirectoryIfNotExists(const std::string& dirPath) {
    if (mkdir(dirPath.c_str(), 0755) && errno != EEXIST) {
        std::cerr << "Failed to create directory: " << dirPath << std::endl;
    }
