        characters[characterId] = Character(characterId);
    }

    Character& charData = characters[characterId];

    // Check cooldown
    if (now < charData.cooldownUntil) {
        return -1;  // Indicates move is still on cooldown
    }

    std::vector<int> availableMoves;

    for (int i = 0; i < 3; ++i) {
        if (charData.lastMove != moveNames[i]) {
            availableMoves.push_back(i);
        }
    }

    if (availableMoves.empty()) {
        return -1; // All moves are on cooldown
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, availableMoves.size() - 1);

    int selectedMoveIndex = availableMoves[dis(gen)];
    charData.lastMove = moveNames[selectedMoveIndex];

    // Set cooldown based on the move
    switch (selectedMoveIndex) {
        case 0: charData.cooldownUntil = now + std::chrono::seconds(3); break; // Attack cooldown
        case 1: charData.cooldownUntil = now + std::chrono::seconds(5); break; // Defend cooldown
        case 2: charData.cooldownUntil = now + std::chrono::seconds(10); break; // Special cooldown
    }

    const char* envVarName = "CHARACTER_TACTICAL_PATH";
    std::string envValue = getEnvironmentVariable(envVarName.c_str());

    if (envValue.empty()) {
        std::string dirPath = getCharacterDirectoryPath(characterId);
        createDirectoryIfNotExists(dirPath);
        setEnvironmentVariable(envVarName, dirPath);
    }

    return selectedMoveIndex;
}
```

### Key Points:
- **Thread Safety**: Uses `std::mutex` to ensure thread-safe access to shared data structures.
- **Cooldown Mechanism**: Each character's cooldowns are managed individually using a map of characters with their last move and cooldown expiry time.
- **Random Move Selection**: Ensures that the same move is not selected consecutively by filtering out the last used move.
- **Environment Variable Management**: Checks for an existing environment variable path, or creates a new directory if it doesn't exist.
- **Concurrency**: Designed to handle multiple character instances concurrently without performance degradation.']

