#include <memory>
#include <mutex>

class UserProfileManager {
public:
    struct Profile {
        int id;
        std::string username;
        std::vector<int> activities;
        std::chrono::system_clock::time_point lastActivity;

        Profile(int userId, const std::string& uname)
            : id(userId), username(uname), lastActivity(std::chrono::system_clock::now()) {}
    };

private:
    using ProfileMap = std::unordered_map<int, std::shared_ptr<Profile>>;
    ProfileMap profiles;
    mutable std::shared_mutex mutex;

    enum class LogLevel { DEBUG, INFO, WARN, ERROR };
    LogLevel logLevel = LogLevel::INFO;
    std::mutex logMutex;

    void log(const std::string& message, LogLevel level) {
        if (level < logLevel) return;
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[" << to_string(level) << "] " << message << std::endl;
    }

    const char* to_string(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO:  return "INFO";
            case LogLevel::WARN:  return "WARN";
            case LogLevel::ERROR: return "ERROR";
        }
        return "UNKNOWN";
    }

public:
    UserProfileManager() = default;

    void setLogLevel(LogLevel level) {
        logLevel = level;
    }

    bool addProfile(int id, const std::string& username) {
        std::unique_lock lock(mutex);
        if (profiles.find(id) != profiles.end()) {
            log("Profile with ID " + std::to_string(id) + " already exists.", LogLevel::ERROR);
            return false;
        }
        profiles.emplace(id, std::make_shared<Profile>(id, username));
        log("Added profile with ID: " + std::to_string(id), LogLevel::INFO);
        return true;
    }

    bool updateProfile(int id, const std::string& username, const std::vector<int>& activities) {
        std::unique_lock lock(mutex);
        auto it = profiles.find(id);
        if (it == profiles.end()) {
            log("Profile with ID " + std::to_string(id) + " not found.", LogLevel::WARN);
            return false;
        }
        it->second->username = username;
        it->second->activities = activities;
        it->second->lastActivity = std::chrono::system_clock::now();
        log("Updated profile with ID: " + std::to_string(id), LogLevel::INFO);
        return true;
    }

    bool deleteProfile(int id) {
        std::unique_lock lock(mutex);
        if (profiles.erase(id) == 0) {
            log("Failed to delete non-existent profile with ID " + std::to_string(id), LogLevel::WARN);
            return false;
        }
        log("Deleted profile with ID: " + std::to_string(id), LogLevel::INFO);
        return true;
    }

    bool getProfile(int id, Profile& outProfile) {
        std::shared_lock lock(mutex);
        auto it = profiles.find(id);
        if (it == profiles.end()) {
            log("Profile with ID " + std::to_string(id) + " not found.", LogLevel::WARN);
            return false;
        }
        outProfile = *it->second;
        return true;
    }

    void garbageCollect(long durationInMinutes) {
        std::unique_lock lock(mutex);
        auto now = std::chrono::system_clock::now();
        for (auto it = profiles.begin(); it != profiles.end();) {
            if (std::chrono::duration_cast<std::chrono::minutes>(now - it->second->lastActivity).count() > durationInMinutes) {
                log("Removing inactive profile with ID: " + std::to_string(it->first), LogLevel::INFO);
                it = profiles.erase(it);
            } else {
                ++it;
            }
        }
    }

    void runGarbageCollector(long intervalInMinutes, long durationInMinutes) {
        while (true) {
            std::this_thread::sleep_for(std::chrono::minutes(intervalInMinutes));
            garbageCollect(durationInMinutes);
        }
    }
};

int main() {
    UserProfileManager manager;
    manager.setLogLevel(UserProfileManager::LogLevel::DEBUG);

    manager.addProfile(1, "Alice");
    manager.updateProfile(1, "AliceUpdated", {101, 102});

    UserProfileManager::Profile profile;
    if (manager.getProfile(1, profile)) {
        std::cout << "Retrieved Profile: ID=" << profile.id << ", Username=" << profile.username << std::endl;
    }

    manager.deleteProfile(1);

    // Example of garbage collector running in a separate thread
    std::thread gcThread(&UserProfileManager::runGarbageCollector, &manager, 5, 10);
    gcThread.detach();

    return 0;
}
