#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <pthread.h>

#define MAX_RECORDS 100
#define FLOAT_ARRAY_MAX_SIZE 50

typedef struct {
    char *key;
    long value;
    float *float_array;
    size_t array_size;
} Entry;

typedef struct {
    int value;
    char buffer[256];
} Record;

typedef struct {
    Entry *entries;
    size_t entry_count;
    pthread_mutex_t lock;
} ResourceManager;

// Gaussian distribution helper function
double gaussian_rand(double mean, double stddev) {
    static double n2 = 0.0;
    static int n2_cached = 0;

    if (!n2_cached) {
        double u1 = (double)rand() / RAND_MAX;
        double u2 = (double)rand() / RAND_MAX;

        double r = sqrt(-2.0 * log(u1));
        double theta = 2.0 * M_PI * u2;

        n2 = r * sin(theta);
        n2_cached = 1;
    } else {
        n2_cached = 0;
    }

    return mean + stddev * (sqrt(-2.0 * log((double)rand() / RAND_MAX)) *
                            cos(2.0 * M_PI * ((double)rand() / RAND_MAX)));

}

// Serialize and Deserialize functions
int serialize_data(const ResourceManager *manager, const char *filename);
int deserialize_data(ResourceManager *manager, const char *filename);

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

// Helper function to find and print the largest integer
void find_largest_integer(int *array, size_t size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }

    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Initialize resource manager
int initialize_resource_manager(ResourceManager *manager, size_t max_entries) {
    if (max_entries == 0 || max_entries > MAX_RECORDS) {
        handle_error("Invalid number of entries.");
    }

    manager->entries = calloc(max_entries, sizeof(Entry));
    if (!manager->entries) {
        handle_error("Memory allocation failed for entries.");
    }

    manager->entry_count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

// Function to add an entry
int add_entry(ResourceManager *manager, const char *key, long value, double mean, double stddev) {
    if (pthread_mutex_lock(&manager->lock)) {
        handle_error("Mutex lock failed.");
    }

    if (manager->entry_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&manager->lock);
        handle_error("Maximum record count exceeded.");
    }

    Entry *new_entry = &manager->entries[manager->entry_count];
    new_entry->key = strdup(key);
    new_entry->value = value;

    size_t array_size = (size_t) gaussian_rand(mean, stddev);
    if (array_size > FLOAT_ARRAY_MAX_SIZE) {
        pthread_mutex_unlock(&manager->lock);
        handle_error("Float array size exceeds maximum limit.");
    }

    new_entry->float_array = malloc(array_size * sizeof(float));
    if (!new_entry->float_array) {
        free(new_entry->key);
        pthread_mutex_unlock(&manager->lock);
        handle_error("Memory allocation failed for float array.");
    }

    for (size_t i = 0; i < array_size; ++i) {
        new_entry->float_array[i] = gaussian_rand(mean, stddev);
    }

    new_entry->array_size = array_size;
    manager->entry_count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to free resources
void free_resources(ResourceManager *manager) {
    for (size_t i = 0; i < manager->entry_count; ++i) {
        free(manager->entries[i].key);
        free(manager->entries[i].float_array);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}

// Main function to demonstrate usage
int main() {
    ResourceManager manager;
    initialize_resource_manager(&manager, 10);

    add_entry(&manager, "entry1", 1234, 0.0, 1.0);
    add_entry(&manager, "entry2", 5678, 5.0, 2.0);

    int numbers[] = {3, 6, 9, 12, 15};
    find_largest_integer(numbers, sizeof(numbers) / sizeof(numbers[0]));

    serialize_data(&manager, "datafile.dat");
    free_resources(&manager);

    return 0;
}

int serialize_data(const ResourceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        handle_error("Failed to open file for serialization.");
    }

    fwrite(&manager->entry_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->entry_count; ++i) {
        size_t key_len = strlen(manager->entries[i].key) + 1;
        fwrite(&key_len, sizeof(size_t), 1, file);
        fwrite(manager->entries[i].key, sizeof(char), key_len, file);

        fwrite(&manager->entries[i].value, sizeof(long), 1, file);
        fwrite(&manager->entries[i].array_size, sizeof(size_t), 1, file);
        fwrite(manager->entries[i].float_array, sizeof(float), manager->entries[i].array_size, file);
    }

    fclose(file);
    return 0;
}

int deserialize_data(ResourceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        handle_error("Failed to open file for deserialization.");
    }

    fread(&manager->entry_count, sizeof(size_t), 1, file);
    manager->entries = realloc(manager->entries, manager->entry_count * sizeof(Entry));
    if (!manager->entries) {
        fclose(file);
        handle_error("Memory allocation failed during deserialization.");
    }

    for (size_t i = 0; i < manager->entry_count; ++i) {
        size_t key_len;
        fread(&key_len, sizeof(size_t), 1, file);

        manager->entries[i].key = malloc(key_len);
        if (!manager->entries[i].key) {
            fclose(file);
            handle_error("Memory allocation failed for key during deserialization.");
        }
        fread(manager->entries[i].key, sizeof(char), key_len, file);

        fread(&manager->entries[i].value, sizeof(long), 1, file);
        fread(&manager->entries[i].array_size, sizeof(size_t), 1, file);
        manager->entries[i].float_array = malloc(manager->entries[i].array_size * sizeof(float));
        if (!manager->entries[i].float_array) {
            free(manager->entries[i].key);
            fclose(file);
            handle_error("Memory allocation failed for float array during deserialization.");
        }
        fread(manager->entries[i].float_array, sizeof(float), manager->entries[i].array_size, file);
    }

    fclose(file);
    return 0;
}
