void initializeDatabase(long limit, int key_size, int range_min, int range_max, unsigned int seed) {
    if (limit <= 0 || key_size <= 0 || range_min > range_max) return;

    srand(seed);

    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;
    int initialized_count = 0;
    int failure_count = 0;

    offsets = (long *)malloc((size_t)limit * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets.\n");
        goto cleanup;
    }

    keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed for keys.\n");
        free(offsets);
        goto cleanup;
    }

    records = (record **)malloc(limit * sizeof(record *));
    if (!records) {
        printf("Memory allocation failed for record pointers.\n");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Initialize offsets and keys
    for (long i = 0; i < limit; ++i) {
        offsets[i] = i;
    }

    for (int i = 0; i < key_size; ++i) {
        keys[i] = i;
    }

    // Initialize records
    for (long i = 0; i < limit; ++i) {
        record *rec = (record *)malloc(sizeof(record));
        if (!rec) {
            printf("Memory allocation failed for record at index %ld.\n", i);
            failure_count++;
            continue;
        }

        rec->value = rand() % (range_max - range_min + 1) + range_min;

        // Randomly assign 'A' or 'B'
        rec->status = (rand() % 2 == 0) ? 'A' : 'B';

        // Allocate and initialize string
        char *name = (char *)malloc(11); // +1 for null terminator
        if (!name) {
            printf("Memory allocation failed for record name at index %ld.\n", i);
            failure_count++;
            free(rec);
            continue;
        }

        for (int j = 0; j < 10; ++j) {
            char c = 'A' + rand() % 26;
            name[j] = c;
        }
        name[10] = '\0';

        rec->name = name;
        records[i] = rec;
        initialized_count++;
    }

cleanup:
    if (initialized_count == 0 && failure_count > 0) {
        printf("No records were successfully initialized.\n");
    } else {
        printf("%d records successfully initialized. %d failures due to memory allocation issues.\n",
               initialized_count, failure_count);
    }

    // Free allocated memory
    for (long i = 0; i < limit && records[i]; ++i) {
        free(records[i]->name);
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    initializeDatabase(100, 50, 1, 100, 42);
    return 0;
}
