#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include "zlib.h"  // Make sure zlib is installed

#define MAX_RECORDS 100000
#define BUFFER_SIZE 256
#define CHARSET "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
#define CHARSET_SIZE (sizeof(CHARSET) - 1)

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
    double floating_point;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t record_count;
    pthread_mutex_t lock; // For thread safety
} RecordManager;

// Forward declarations
void init_random_seed();
char random_char_from_set(const char* charset, size_t set_size);
double generate_random_double(double min, double max);

RecordManager* create_record_manager(size_t size) {
    if (size > MAX_RECORDS) {
        fprintf(stderr, "Requested size exceeds maximum allowed records.\n");
        return NULL;
    }

    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for RecordManager.");
        return NULL;
    }

    manager->offsets = calloc(size, sizeof(long));
    manager->keys = calloc(size, sizeof(int));
    manager->records = calloc(size, sizeof(Record));
    manager->record_count = 0;

    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    init_random_seed();

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&manager->lock); // Ensure thread safety

        manager->keys[i] = rand() % 10000;

        for (int j = 0; j < BUFFER_SIZE - 1; ++j) {
            manager->records[i].buffer[j] = random_char_from_set(CHARSET, CHARSET_SIZE);
        }
        manager->records[i].buffer[BUFFER_SIZE - 1] = '\0';

        manager->records[i].value = rand() % 10000;
        manager->records[i].floating_point = generate_random_double(-100.0, 100.0);

        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

void free_record_manager(RecordManager *manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int serialize_records(const RecordManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    gzFile compressed_file = gzdopen(fileno(file), "wb9");
    if (!compressed_file) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < manager->record_count; ++i) {
        fprintf(compressed_file, "%d|%s|%.2f\n", manager->records[i].value,
                manager->records[i].buffer, manager->records[i].floating_point);
    }

    gzclose(compressed_file);
    fclose(file);

    return 0;
}

int deserialize_records(RecordManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    gzFile compressed_file = gzdopen(fileno(file), "rb");
    if (!compressed_file) {
        fclose(file);
        return -1;
    }

    char line[BUFFER_SIZE * 2];
    while (fgets(line, sizeof(line), compressed_file)) {
        if (manager->record_count >= MAX_RECORDS) break;

        pthread_mutex_lock(&manager->lock);

        int value;
        double floating_point;
        sscanf(line, "%d|%255[^|]|%lf", &value, manager->records[manager->record_count].buffer, &floating_point);

        manager->records[manager->record_count].value = value;
        manager->records[manager->record_count].floating_point = floating_point;

        pthread_mutex_unlock(&manager->lock);

        ++manager->record_count;
    }

    gzclose(compressed_file);
    fclose(file);

    return 0;
}

void init_random_seed() {
    srand(time(NULL));
}

char random_char_from_set(const char* charset, size_t set_size) {
    return charset[rand() % set_size];
}

double generate_random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Example usage
int main() {
    RecordManager *manager = create_record_manager(1000);

    if (manager) {
        serialize_records(manager, "records.gz");

        RecordManager *new_manager = create_record_manager(1000);
        deserialize_records(new_manager, "records.gz");

        free_record_manager(manager);
        free_record_manager(new_manager);
    }

    return 0;
}
```

