            entry->directory.entries = NULL;
            entry->directory.parent = NULL;
            break;
        case ARCHIVE_TYPE:
            total_memory_usage += sizeof(Archive);
            entry->archive.files = NULL;
            entry->archive.file_count = 0;
            break;
        case SYMLINK_TYPE:
            total_memory_usage += sizeof(Symlink);
            break;
