#include <stdio.h>
#include <stdlib.h>
import pthread.h

typedef struct {
    char *DeviceId;
    char *Location;
} NetworkConnectionStatus;

typedef struct {
    char *DeviceId;
    char *Location;
    NetworkConnectionStatus **Connections;
    size_t connection_count;
} DeviceStatus;

// Mutex for thread safety
pthread_mutex_t device_list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct Node {
    DeviceStatus *device_status;
    struct Node *next;
} Node;

Node *head = NULL;

DeviceStatus* create_device_status(const char *deviceId, const char *location) {
    if (!deviceId || !location) return NULL;

    DeviceStatus *new_device = (DeviceStatus*)malloc(sizeof(DeviceStatus));
    if (!new_device) return NULL;

    new_device->DeviceId = strdup(deviceId);
    new_device->Location = strdup(location);
    new_device->Connections = NULL;
    new_device->connection_count = 0;

    return new_device;
}

void add_network_connection(DeviceStatus *device, const char *deviceId, const char *location) {
    if (!device || !deviceId || !location) return;

    device->Connections = (NetworkConnectionStatus**)realloc(device->Connections,
        sizeof(NetworkConnectionStatus*) * (device->connection_count + 1));
    if (!device->Connections) return;

    NetworkConnectionStatus *new_connection = (NetworkConnectionStatus*)malloc(sizeof(NetworkConnectionStatus));
    if (!new_connection) {
        free(device->Connections);
        device->Connections = NULL;
        return;
    }

    new_connection->DeviceId = strdup(deviceId);
    new_connection->Location = strdup(location);

    device->Connections[device->connection_count] = new_connection;
    device->connection_count++;
}

void delete_device_status(DeviceStatus *device) {
    if (!device) return;

    free(device->DeviceId);
    free(device->Location);

    for (size_t i = 0; i < device->connection_count; ++i) {
        free(device->Connections[i]->DeviceId);
        free(device->Connections[i]->Location);
        free(device->Connections[i]);
    }
    free(device->Connections);

    free(device);
}

void add_device_to_list(DeviceStatus *device) {
    if (!device) return;

    pthread_mutex_lock(&device_list_mutex);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&device_list_mutex);
        delete_device_status(device); // Cleanup device in case of allocation failure
        return;
    }

    new_node->device_status = device;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&device_list_mutex);
}

void remove_device_from_list(const char *deviceId) {
    if (!deviceId) return;

    pthread_mutex_lock(&device_list_mutex);

    Node **current = &head;
    while (*current) {
        Node *entry = *current;

        if (strcmp(entry->device_status->DeviceId, deviceId) == 0) {
            *current = entry->next;
            delete_device_status(entry->device_status);
            free(entry);
            pthread_mutex_unlock(&device_list_mutex);
            return;
        }
        current = &entry->next;
    }

    pthread_mutex_unlock(&device_list_mutex);
}

void cleanup_device_list() {
    pthread_mutex_lock(&device_list_mutex);

    Node *current = head;
    while (current) {
        Node *next = current->next;
        delete_device_status(current->device_status);
        free(current);
        current = next;
    }
    head = NULL;

    pthread_mutex_unlock(&device_list_mutex);
}

// Example integration with a mock real-time update function
void real_time_update(const char *deviceId, const char *location) {
    DeviceStatus *device = create_device_status(deviceId, location);

    if (!device) return;

    // Mock external data source for network connections
    add_network_connection(device, "conn1", "loc1");

    add_device_to_list(device);
}

int main() {
    real_time_update("dev1", "locA");

    // Simulate updates and operations

    cleanup_device_list();
    pthread_mutex_destroy(&device_list_mutex);

    return 0;
}
