        measurements[i].measurementTag.bandwidth = bandwidth;

        measurements[i].measReports = malloc(maxCellsPerMeasurement * sizeof(RrcMeasReport));
        if (measurements[i].measReports == NULL) {
            log_message("Failed to allocate memory for RRC measurement reports.");
            // Clean up previously allocated memory
            while (--i >= 0) free(measurements[i].measReports);
            free(measurements);
            return NULL;
        }

        measurements[i].numCells = maxCellsPerMeasurement;

        for (size_t j = 0; j < maxCellsPerMeasurement; ++j) {
            int signalStrength = -70 + rand() % 51; // Example range [-70, -19]

            if (!is_measurement_valid(signalStrength)) {
                log_message("Signal strength out of valid range.");
                continue;
            }

            measurements[i].measReports[j].cellId = j + 1;
            measurements[i].measReports[j].signalStrength = signalStrength;
        }
    }

    log_message("Measurement initialization successful.");
    return measurements;
}

void free_measurements(UeMeasurementResult* measurements, size_t numMeasurements) {
    if (measurements == NULL) return;

    for (size_t i = 0; i < numMeasurements; ++i) {
        free(measurements[i].measReports);
    }

    free(measurements);
