#include <functional>

// Constants for session expiration
const int INACTIVITY_TIMEOUT = 300; // seconds
const int GRACE_PERIOD = 60;        // seconds

struct Session {
    std::string sessionId;
    std::string clientIp;
    long lastActivityTimestamp;
    int referenceCount;
    std::string metadata;

    bool isExpired() const {
        auto now = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
        return (lastActivityTimestamp + INACTIVITY_TIMEOUT + GRACE_PERIOD) < duration;
    }
};

class SessionManager {
public:
    SessionManager(int initialCapacity)
        : maxSessions(initialCapacity), lastAttackTime(0) {
        sessions.reserve(maxSessions);
        std::lock_guard<std::mutex> lock(mutex_);
    }

    void addSession(const Session& session) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions.size() < maxSessions) {
            sessions.push_back(session);
        } else {
            expireSessions();
            if (sessions.size() < maxSessions) {
                sessions.push_back(session);
            }
        }
    }

    void updateSession(const std::string& sessionId, long activityTimestamp) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& session : sessions) {
            if (session.sessionId == sessionId) {
                session.lastActivityTimestamp = activityTimestamp;
                return;
            }
        }
    }

    void expireSessions() {
        auto now = std::chrono::system_clock::now();
        long currentTimestamp = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();

        sessions.erase(std::remove_if(sessions.begin(), sessions.end(),
                                      [currentTimestamp](const Session& session) {
                                          return session.isExpired() || (session.referenceCount == 0);
                                      }),
                       sessions.end());
    }

    void selectRandomAttack() {
        std::lock_guard<std::mutex> lock(mutex_);
        auto now = std::chrono::system_clock::now();
        long currentTimestamp = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();

        if (currentTimestamp - lastAttackTime >= 9) {
            int attackNumber = rand() % 3 + 1;
            std::cout << "Selected Attack: " << attackNumber << std::endl;
            lastAttackTime = currentTimestamp;
        }
    }

private:
    std::vector<Session> sessions;
    int maxSessions;
    long lastAttackTime;
    mutable std::mutex mutex_;

public:
    void adjustMemoryLimitBasedOnLoad() {
        // Placeholder for dynamic adjustment logic
        // This would involve system load metrics like CPU usage, available memory, etc.
    }
};

int main() {
    SessionManager manager(100); // Initial capacity of 100 sessions

    std::thread addThread([&manager]() {
        for (int i = 0; i < 150; ++i) { // Simulate adding more sessions than the initial limit
            Session session = {"id" + std::to_string(i), "192.168.1." + std::to_string(i % 255),
                               std::chrono::system_clock::now().time_since_epoch().count(), 1, "metadata"};
            manager.addSession(session);
        }
    });

    std::thread updateThread([&manager]() {
        for (int i = 0; i < 100; ++i) { // Simulate updating sessions
            manager.updateSession("id" + std::to_string(i), 
                                  std::chrono::system_clock::now().time_since_epoch().count());
        }
    });

    std::thread attackThread([&manager]() {
        while (true) {
            manager.selectRandomAttack();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    addThread.join();
    updateThread.join();
    attackThread.detach(); // Detach for continuous operation

    return 0;
}
```

### Key Features:
- **Thread Safety:** Uses `std::mutex` to ensure thread-safe operations.
- **Session Management:** Adds, updates, and expires sessions based on inactivity.
- **Random Attack Selection:** Selects a random attack every 9 seconds if conditions are met.
- **Dynamic Memory Adjustment:** Placeholder for adjusting memory limits based on system load.
- **Concurrency:** Handles concurrent modifications using threads.

This implementation focuses on efficiency, usability, and scalability while maintaining thread safety.']

