        str[i] = charset[rand() % strlen(charset)];
    }
    str[length - 1] = '\0';
}

// Function to initialize the RecordManager
int init_record_manager(RecordManager *manager, const char *charset, size_t initial_size) {
    if (initial_size == 0 || manager == NULL) return -1;

    size_t record_size = sizeof(Record);
    size_t total_size = initial_size * record_size;

    if (total_size > MEMORY_LIMIT) return -2;

    manager->records = malloc(total_size);
    if (!manager->records) return -3;

    manager->allocated_count = 0;
    manager->total_allocated_size = total_size;

    for (size_t i = 0; i < initial_size; ++i) {
        Record *rec = &manager->records[i];
        rec->key = rand();
        generate_random_string(rec->data, charset, MAX_CHAR_BUFFER);
        rec->id = i;
    }

    manager->allocated_count = initial_size;

    return 0;
}

// Function to add a new record
int add_record(RecordManager *manager, const char *charset) {
    if (manager == NULL || manager->total_allocated_size >= MEMORY_LIMIT) return -1;

    size_t additional_records = 10; // Example batch size for reallocations
    size_t record_size = sizeof(Record);
    size_t new_total_size = (manager->allocated_count + additional_records) * record_size;

    if (new_total_size > MEMORY_LIMIT) return -2;

    RecordManager temp_manager;
    temp_manager.records = realloc(manager->records, new_total_size);

    if (!temp_manager.records) return -3;

    for (size_t i = manager->allocated_count; i < manager->allocated_count + additional_records; ++i) {
        Record *rec = &temp_manager.records[i];
        rec->key = rand();
        generate_random_string(rec->data, charset, MAX_CHAR_BUFFER);
        rec->id = i;
    }

    manager->records = temp_manager.records;
    manager->total_allocated_size = new_total_size;
    manager->allocated_count += additional_records;

    return 0;
}

// Function to serialize the record data to a file
int save_to_file(RecordManager *manager, const char *filename) {
    if (manager == NULL || filename == NULL) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -2;

    size_t count = manager->allocated_count;
    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        Record *rec = &manager->records[i];
        fwrite(rec, sizeof(Record), 1, file);
    }

    fclose(file);
    return 0;
}

// Function to deserialize the record data from a file
int load_from_file(RecordManager *manager, const char *filename) {
    if (manager == NULL || filename == NULL) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -2;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    manager->records = realloc(manager->records, count * sizeof(Record));
    for (size_t i = 0; i < count; ++i) {
        Record *rec = &manager->records[i];
        fread(rec, sizeof(Record), 1, file);
    }

    manager->allocated_count = count;
    manager->total_allocated_size = count * sizeof(Record);

    fclose(file);
    return 0;
}

// Function to free all resources
void cleanup_record_manager(RecordManager *manager) {
    if (manager && manager->records) {
        free(manager->records);
        manager->records = NULL;
        manager->allocated_count = 0;
        manager->total_allocated_size = 0;
    }
}
