#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct {
    int id;
    char key[32];
    char data[BUFFER_SIZE];
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    size_t count;
} RecordCollection;

// Function prototypes
RecordCollection* initialize_collection(size_t max_records);
int add_record(RecordCollection *collection, int id, const char *key, const char *charset);
void serialize_to_file(const RecordCollection *collection, const char *filename);
int deserialize_from_file(RecordCollection *collection, const char *filename);
void free_collection(RecordCollection *collection);
void handle_error(const char *message);

// Initialize the random number generator
static void init_random() {
    srand((unsigned)time(NULL));
}

// Generate random buffer content based on given charset
static void generate_random_data(char *buffer, size_t length, const char *charset) {
    for (size_t i = 0; i < length - 1; ++i) { // leave space for null terminator
        buffer[i] = charset[rand() % strlen(charset)];
    }
    buffer[length - 1] = '\0';
}

// Initialize a collection with the specified maximum number of records
RecordCollection* initialize_collection(size_t max_records) {
    if (max_records > MAX_RECORDS) {
        handle_error("Maximum record limit exceeded.");
        return NULL;
    }

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        handle_error("Failed to allocate memory for collection");
        return NULL;
    }

    collection->count = 0;

    // Initialize records with NULL pointers
    for (size_t i = 0; i < max_records; ++i) {
        collection->records[i] = NULL;
    }

    init_random();
    return collection;
}

// Add a record to the collection
int add_record(RecordCollection *collection, int id, const char *key, const char *charset) {
    if (collection->count >= MAX_RECORDS) {
        handle_error("Cannot add more records; limit reached.");
        return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        handle_error("Failed to allocate memory for record");
        return -1;
    }

    strncpy(record->key, key, sizeof(record->key) - 1);
    record->key[sizeof(record->key) - 1] = '\0';
    record->id = id;

    generate_random_data(record->data, BUFFER_SIZE, charset);

    collection->records[collection->count++] = record;
    return 0;
}

// Serialize the collection to a file
void serialize_to_file(const RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        handle_error("Failed to open file for writing");
        return;
    }

    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];
        fwrite(&record->id, sizeof(int), 1, file);
        fwrite(record->key, sizeof(record->key), 1, file);
        fwrite(record->data, BUFFER_SIZE, 1, file);
    }

    fclose(file);
}

// Deserialize the collection from a file
int deserialize_from_file(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        handle_error("Failed to open file for reading");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (count > MAX_RECORDS) {
        fclose(file);
        handle_error("Deserialization error: record limit exceeded.");
        return -1;
    }

    collection->count = count;

    for (size_t i = 0; i < count; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fclose(file);
            handle_error("Failed to allocate memory during deserialization");
            return -1;
        }

        fread(&record->id, sizeof(int), 1, file);
        fread(record->key, sizeof(record->key), 1, file);
        fread(record->data, BUFFER_SIZE, 1, file);

        collection->records[i] = record;
    }

    fclose(file);
    return 0;
}

// Free all allocated resources in the collection
void free_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }

    free(collection);
}

// Handle errors by logging them and exiting if necessary
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}
