float findHighestValue(float *array, int size) {
    if (size <= 0) return -1.0f; // Error value

    float highest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > highest) {
            highest = array[i];
        }
    }
    return highest;
}

void readFloatsAndFindHighest() {
    int count, i;
    float *values;

    printf("Enter the number of floats: ");
    scanf("%d", &count);

    values = malloc(count * sizeof(float));
    if (!values) {
        perror("Failed to allocate memory for floats");
        return;
    }

    printf("Enter %d floats:\n", count);
    for (i = 0; i < count; ++i) {
        scanf("%f", &values[i]);
    }

    float highest = findHighestValue(values, count);
    printf("The highest value is: %.2f\n", highest);

    free(values);
}

int addResource(int resourceId, int availabilityStatus) {
    pthread_mutex_lock(&resourceMutex);

    if (numResources >= MAX_RESOURCES) {
        pthread_mutex_unlock(&resourceMutex);
        return -1; // Resource limit reached
    }

    resources = realloc(resources, (numResources + 1) * sizeof(ResourceMetadata));
    if (!resources) {
        perror("Failed to allocate memory for resources");
        pthread_mutex_unlock(&resourceMutex);
        return -1;
    }

    resources[numResources].resourceId = resourceId;
    resources[numResources].availabilityStatus = availabilityStatus;
    resources[numResources].lastAccessedTime = time(NULL);
    resources[numResources].accessFrequency = 0;

    ++numResources;

    pthread_mutex_unlock(&resourceMutex);
    return 0; // Success
}

int updateResource(int resourceId, int newAvailability) {
    pthread_mutex_lock(&resourceMutex);

    for (int i = 0; i < numResources; ++i) {
        if (resources[i].resourceId == resourceId) {
            resources[i].availabilityStatus = newAvailability;
            resources[i].lastAccessedTime = time(NULL);
            resources[i].accessFrequency++;

            pthread_mutex_unlock(&resourceMutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&resourceMutex);
    return -1; // Resource not found
}

ResourceMetadata* getResource(int resourceId) {
    pthread_mutex_lock(&resourceMutex);

    for (int i = 0; i < numResources; ++i) {
        if (resources[i].resourceId == resourceId) {
            pthread_mutex_unlock(&resourceMutex);
            return &resources[i];
        }
    }

    pthread_mutex_unlock(&resourceMutex);
    return NULL;
}

int purgeUnusedResources(int usageThreshold, int accessFrequencyThreshold) {
    pthread_mutex_lock(&resourceMutex);

    for (int i = 0; i < numResources; ++i) {
        if ((resources[i].availabilityStatus == 0 && resources[i].accessFrequency < accessFrequencyThreshold)
            || resources[i].accessFrequency > usageThreshold) {

            memmove(&resources[i], &resources[i + 1],
                    (numResources - i - 1) * sizeof(ResourceMetadata));

            --numResources;
            resources = realloc(resources, numResources * sizeof(ResourceMetadata));

            if (!resources && numResources > 0) {
                perror("Failed to reallocate memory for resources");
                pthread_mutex_unlock(&resourceMutex);
                return -1;
            }
        }
    }

    pthread_mutex_unlock(&resourceMutex);
    return 0; // Success
}

