        printf("Resource added successfully\n");

    if (updateResource(1, 0) == 0)
        printf("Resource updated successfully\n");

    ResourceMetadata* resource = getResource(1);
    if (resource) {
        printf("Resource %d accessed at %ld with frequency %d\n",
               resource->resourceId, resource->lastAccessedTime, resource->accessFrequency);
    }

    // Purge unused resources as needed
    purgeUnusedResources(100, 5);

    free(resources);
    pthread_mutex_destroy(&resourceMutex);

    return 0;
}
