    size_t current_memory_usage;
} DataManager;

DataManager* create_data_manager(size_t initial_capacity) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));
    dm->records = (Record **)calloc(initial_capacity, sizeof(Record *));
    dm->count = 0;
    dm->capacity = initial_capacity;
    dm->current_memory_usage = 0;
    return dm;
}

void free_data_manager(DataManager *dm) {
    for (size_t i = 0; i < dm->count; ++i) {
        free(dm->records[i]);
    }
    free(dm->records);
    free(dm);
}

int add_record(DataManager *dm, int key) {
    if (dm->current_memory_usage + sizeof(Record) > MEMORY_LIMIT || dm->count >= dm->capacity) {
        return -1; // Memory limit reached or no capacity
    }

    Record *record = (Record *)malloc(sizeof(Record));
    record->key = key;

    for (int i = 0; i < MAX_BUFFER_SIZE; ++i) {
        char random_char = PREDEFINED_CHAR_SET[rand() % strlen(PREDEFINED_CHAR_SET)];
        record->data[i] = random_char;
    }

    if (dm->count == dm->capacity) {
        dm->capacity *= 2;
        dm->records = (Record **)realloc(dm->records, dm->capacity * sizeof(Record *));
    }

    dm->records[dm->count++] = record;
    dm->current_memory_usage += sizeof(Record);

    return 0; // Success
}

int serialize(DataManager *dm, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&dm->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < dm->count; ++i) {
        fwrite(dm->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize(DataManager *dm, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fread(&dm->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < dm->count; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        fread(record, sizeof(Record), 1, file);
        if (i >= dm->capacity) {
            dm->capacity *= 2;
            dm->records = (Record **)realloc(dm->records, dm->capacity * sizeof(Record *));
        }
        dm->records[i] = record;
    }

    fclose(file);
    return 0;
}

