}

void deserializeData(long*& fdOffsets, int*& dirIndices, Record*& records, char**& pathStrings, size_t& recordCount) {
    std::ifstream inFile("data.bin", std::ios::binary);
    if (!inFile) throw std::runtime_error("Failed to open file for deserialization.");

    // Deserialization logic here
}

int main() {
    NetworkServiceManager manager;

    try {
        std::vector<std::string> configPaths;
        std::string path;
        while (std::cin >> path) {
