    free(string);

    SensorData *data = malloc(sizeof(SensorData));

    if (!json_object_object_get_ex(jobj, "timestamp", &jsonTimestamp)) {
        // Error handling
        json_object_put(jobj); 
        return NULL;
    }

    data->timestamp = json_integer_value(jsonTimestamp);
    // Populate other fields similarly

    json_object_put(jobj);

    return data;
}

