['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *key;
    char *value;
    int version;
    time_t timestamp;
} ConfigSetting;

typedef struct {
    ConfigSetting *setting;
    pthread_mutex_t lock; // Lock for thread safety
} HashTableEntry;

#define HASH_TABLE_SIZE 1024

typedef enum { INFO, DEBUG, ERROR } LogLevel;

typedef struct {
    LogLevel level;
    void (*log_func)(const char *);
} Logger;

typedef struct {
    int version_threshold;
    ConfigSetting *settings[HASH_TABLE_SIZE];
    pthread_mutex_t hash_table_lock;
    Logger logger;
} StorageManager;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % HASH_TABLE_SIZE;
}

void default_log_func(const char *message) {
    printf("%s\n", message);
}

void init_storage_manager(StorageManager *manager, int version_threshold, LogLevel level) {
    memset(manager->settings, 0, sizeof(manager->settings));
    pthread_mutex_init(&manager->hash_table_lock, NULL);
    manager->version_threshold = version_threshold;
    manager->logger.level = level;
    manager->logger.log_func = default_log_func;
}

void free_config_setting(ConfigSetting *setting) {
    if (setting) {
        free(setting->key);
        free(setting->value);
        free(setting);
    }
}

int add_or_update_setting(StorageManager *manager, const char *key, const char *value, int version) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&manager->hash_table_lock);

    HashTableEntry *entry = manager->settings[index];
    if (entry && entry->setting && strcmp(entry->setting->key, key) == 0) {
        if (version > entry->setting->version) {
            free_config_setting(entry->setting);
            ConfigSetting *new_setting = malloc(sizeof(ConfigSetting));
            new_setting->key = strdup(key);
            new_setting->value = strdup(value);
            new_setting->version = version;
            new_setting->timestamp = time(NULL);
            entry->setting = new_setting;

            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Updated setting %s to version %d", key, version);
            manager->logger.log_func(log_message);
        }
    } else {
        HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
        pthread_mutex_init(&new_entry->lock, NULL);

        ConfigSetting *setting = malloc(sizeof(ConfigSetting));
        setting->key = strdup(key);
        setting->value = strdup(value);
        setting->version = version;
        setting->timestamp = time(NULL);
        new_entry->setting = setting;

        manager->settings[index] = new_entry;
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Added setting %s with version %d", key, version);
        manager->logger.log_func(log_message);
    }

    pthread_mutex_unlock(&manager->hash_table_lock);
    return 0;
}

ConfigSetting *get_setting(StorageManager *manager, const char *key) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&manager->hash_table_lock);

    ConfigSetting *setting = NULL;
    HashTableEntry *entry = manager->settings[index];
    if (entry && entry->setting && strcmp(entry->setting->key, key) == 0) {
        setting = entry->setting;
    }

    pthread_mutex_unlock(&manager->hash_table_lock);
    return setting;
}

void invalidate_settings(StorageManager *manager) {
    pthread_mutex_lock(&manager->hash_table_lock);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = manager->settings[i];
        if (entry && entry->setting && entry->setting->version <= manager->version_threshold) {
            free_config_setting(entry->setting);
            pthread_mutex_destroy(&entry->lock);
            free(entry);
            manager->settings[i] = NULL;
        }
    }

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Invalidated settings below version %d", manager->version_threshold);
    manager->logger.log_func(log_message);

    pthread_mutex_unlock(&manager->hash_table_lock);
}

void free_storage_manager(StorageManager *manager) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = manager->settings[i];
        if (entry) {
            pthread_mutex_destroy(&entry->lock);
            free_config_setting(entry->setting);
            free(entry);
        }
    }

    pthread_mutex_destroy(&manager->hash_table_lock);
}

void configure_and_manage_storage() {
    StorageManager manager;
    init_storage_manager(&manager, 1, INFO);

    add_or_update_setting(&manager, "timeout", "30", 1);
    ConfigSetting *setting = get_setting(&manager, "timeout");
    if (setting) {
        printf("Retrieved setting: %s=%s\n", setting->key, setting->value);
    }

    invalidate_settings(&manager);

    free_storage_manager(&manager);
}

int main() {
    configure_and_manage_storage();
    return 0;
}
