#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_BUFFER_SIZE 256
#define MEMORY_LIMIT 1000

typedef struct {
    int value;
    char buffer[MAX_BUFFER_SIZE];
} Record;

typedef struct {
    uint32_t tag;        // Unique identifier for the structure
    uint16_t rnti;       // RNTI field
    uint8_t crcFlag;     // CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    NFAPI_CRC_INDICATION_PDU_T **nfapi_pdus;
    size_t count;  // Total number of records allocated
} MemoryManager;

// Function to calculate MD5 hash (simple implementation)
void md5_hash(const char *str, unsigned char digest[16]) {
    for (int i = 0; i < 16; ++i) {
        digest[i] = str[i % strlen(str)] + i;
    }
}

MemoryManager* initialize_memory_manager(size_t size) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offsets = calloc(size, sizeof(long));
    manager->keys = calloc(size, sizeof(int));
    manager->records = calloc(size, sizeof(Record*));
    manager->nfapi_pdus = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!manager->offsets || !manager->keys || !manager->records || !manager->nfapi_pdus) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager->nfapi_pdus);
        free(manager);
        return NULL;
    }

    manager->count = 0;
    return manager;
}

int allocate_record(MemoryManager *manager, int key, const char *data) {
    if (manager->count >= MEMORY_LIMIT) return -1;

    long offset = rand();
    Record *record = malloc(sizeof(Record));
    if (!record) return -1;

    record->value = key;
    strncpy(record->buffer, data, MAX_BUFFER_SIZE);

    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;
    manager->records[manager->count] = record;

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        free(record);
        return -1;
    }

    pdu->rx_ue_information_tag = rand();
    pdu->rnti = (uint16_t)(key % 65535); // Simple RNTI generation
    pdu->crc_indication_rel8_tag.crcFlag = rand() & 0x01; // Random CRC flag

    manager->nfapi_pdus[manager->count] = pdu;
    manager->count++;

    return 0;
}

void free_memory_manager(MemoryManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
        free(manager->nfapi_pdus[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->nfapi_pdus);
    free(manager);
}

void serialize_memory_manager(const MemoryManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(&manager->offsets[i], sizeof(long), 1, file);
        fwrite(&manager->keys[i], sizeof(int), 1, file);
        fwrite(manager->records[i]->buffer, MAX_BUFFER_SIZE, 1, file);

        fwrite(&manager->nfapi_pdus[i]->rx_ue_information_tag, sizeof(uint32_t), 1, file);
        fwrite(&manager->nfapi_pdus[i]->rnti, sizeof(uint16_t), 1, file);
        fwrite(&manager->nfapi_pdus[i]->crc_indication_rel8_tag.crcFlag, sizeof(uint8_t), 1, file);
    }

    fclose(file);
}

int deserialize_memory_manager(MemoryManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fread(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        fread(&manager->offsets[i], sizeof(long), 1, file);
        fread(&manager->keys[i], sizeof(int), 1, file);

        Record *record = malloc(sizeof(Record));
        if (!record) return -1;
        fread(record->buffer, MAX_BUFFER_SIZE, 1, file);
        record->value = manager->keys[i];

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            free(record);
            return -1;
        }
        fread(&pdu->rx_ue_information_tag, sizeof(uint32_t), 1, file);
        fread(&pdu->rnti, sizeof(uint16_t), 1, file);
        fread(&pdu->crc_indication_rel8_tag.crcFlag, sizeof(uint8_t), 1, file);

        manager->records[i] = record;
        manager->nfapi_pdus[i] = pdu;
    }

    fclose(file);
    return 0;
}

int main() {
    MemoryManager *manager = initialize_memory_manager(100);
    if (!manager) {
        printf("Failed to initialize memory manager.\n");
        return -1;
    }

    for (int i = 0; i < 10; ++i) {
        char data[MAX_BUFFER_SIZE] = "Sample record";
        allocate_record(manager, i, data);
    }

    serialize_memory_manager(manager, "data.bin");

    MemoryManager *newManager = initialize_memory_manager(100);
    if (!newManager) {
        printf("Failed to reinitialize memory manager.\n");
        free_memory_manager(manager);
        return -1;
    }

    deserialize_memory_manager(newManager, "data.bin");

    free_memory_manager(manager);
    free_memory_manager(newManager);

    return 0;
}
