['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 // 1MB for example

typedef struct {
    int id;
    char data[256];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T record;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    size_t block_size;
    size_t current_memory_usage;
    size_t max_memory_usage;
    MemoryPoolNode* free_list;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool memory_pool = { sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, MAX_MEMORY_BUDGET, NULL, PTHREAD_MUTEX_INITIALIZER };
FILE* usage_log = NULL;
pthread_mutex_t file_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_memory_pool() {
    pthread_mutex_lock(&memory_pool.mutex);
    memory_pool.free_list = (MemoryPoolNode*)malloc(MAX_MEMORY_BUDGET / sizeof(MemoryPoolNode));
    if (!memory_pool.free_list) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < MAX_MEMORY_BUDGET / sizeof(MemoryPoolNode); ++i) {
        memory_pool.free_list[i].next = &memory_pool.free_list[i + 1];
    }
    memory_pool.free_list[MAX_MEMORY_BUDGET / sizeof(MemoryPoolNode) - 1].next = NULL;
    pthread_mutex_unlock(&memory_pool.mutex);
}

MemoryPoolNode* allocate_memory_block() {
    pthread_mutex_lock(&memory_pool.mutex);
    if (memory_pool.free_list == NULL || 
        ((size_t)(memory_pool.current_memory_usage + memory_pool.block_size) > memory_pool.max_memory_usage)) {
        fprintf(stderr, "Allocation failed due to insufficient memory\n");
        exit(EXIT_FAILURE);
    }
    MemoryPoolNode* node = memory_pool.free_list;
    memory_pool.free_list = node->next;
    memory_pool.current_memory_usage += memory_pool.block_size;
    pthread_mutex_unlock(&memory_pool.mutex);
    return node;
}

void free_memory_block(MemoryPoolNode* node) {
    pthread_mutex_lock(&memory_pool.mutex);
    node->next = memory_pool.free_list;
    memory_pool.free_list = node;
    memory_pool.current_memory_usage -= memory_pool.block_size;
    update_usage_log();
    pthread_mutex_unlock(&memory_pool.mutex);
}

void update_usage_log() {
    if (!usage_log) {
        usage_log = fopen("usage.log", "a");
        if (!usage_log) return;
    }
    time_t now = time(NULL);
    char* timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = 0; // Remove newline
    fprintf(usage_log, "[%s] Peak: %zu Current: %zu Records: %ld\n",
            timestamp, memory_pool.max_memory_usage, memory_pool.current_memory_usage, 
            (long)(memory_pool.max_memory_usage / memory_pool.block_size - 
                   memory_pool.free_list));
    fflush(usage_log);
}

void append_to_file(const char* filename, const NFAPI_CRC_INDICATION_PDU_T* record) {
    pthread_mutex_lock(&file_mutex);
    FILE* file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open %s\n", filename);
        exit(EXIT_FAILURE);
    }
    fprintf(file, "ID: %d, Data: %s\n", record->id, record->data);
    fclose(file);
    pthread_mutex_unlock(&file_mutex);
}

void print_record_to_file(const char* filename, const NFAPI_CRC_INDICATION_PDU_T* record) {
    append_to_file(filename, record);
}

int main() {
    init_memory_pool();

    // Example usage
    MemoryPoolNode* node = allocate_memory_block();
    strcpy(node->record.data, "Example data");
    node->record.id = 1;
    print_record_to_file("output.txt", &node->record);
    free_memory_block(node);

    fclose(usage_log);
    return 0;
}
