int create_random_sentence(char **sentence, size_t max_length) {
    const char *words[] = {"apple", "banana", "cherry", "date", "elderberry"};
    int num_words = sizeof(words) / sizeof(words[0]);
    size_t length = 0;
    *sentence = malloc(max_length);

    if (*sentence == NULL) return -1;

    for (int i = 0; i < rand() % 10 + 5 && length < max_length - 1; ++i) {
        int word_len = strlen(words[rand() % num_words]);
        if (length + word_len >= max_length - 1) break;
        strcpy(*sentence + length, words[rand() % num_words]);
        *(*sentence + length + word_len) = ' ';
        length += word_len + 1;
    }

    (*sentence)[--length] = '\0'; // Remove trailing space
    return 0;
}

int create_record(int key_range_min, int key_range_max, long offset_range_min, long offset_range_max, size_t desc_length) {
    if (manager.count >= MAX_RECORDS || manager.memory_usage + sizeof(Record) + desc_length > MEMORY_POOL_SIZE) {
        log_info("Memory limit reached or record limit exceeded");
        return -1;
    }

    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        log_error("Failed to allocate memory for record");
        return -1;
    }

    record->key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
    record->offset = rand() % (offset_range_max - offset_range_min + 1) + offset_range_min;

    char *desc;
    if (create_random_sentence(&desc, desc_length) != 0 || desc == NULL) {
        free(record);
        log_error("Failed to create random sentence for description");
        return -1;
    }

    record->description = desc;
    size_t memory_needed = sizeof(Record) + strlen(desc) + 1;

    pthread_mutex_lock(&manager.lock);
    manager.records[manager.count++] = record;
    manager.memory_usage += memory_needed;
    log_info("Created record: Key=%d, Offset=%ld, Description Length=%zu", record->key, record->offset, strlen(record->description));
    pthread_mutex_unlock(&manager.lock);

    return 0;
}

void cleanup_records_manager() {
    for (size_t i = 0; i < manager.count; ++i) {
        free_record(manager.records[i]);
    }
    pthread_mutex_destroy(&manager.lock);
}

int main(int argc, char *argv[]) {
    if (!initialize_records_manager()) {
        srand(time(NULL));

        Config config;
        if (!parse_config_file("config.cfg", &config)) {
            log_error("Failed to parse configuration file");
            cleanup_records_manager();
            return -1;
        }

        for (int i = 0; i < config.record_count && create_record(config.key_range_min, config.key_range_max, config.offset_range_min, config.offset_range_max, config.desc_length) == 0; ++i);

        log_memory_statistics("Final");

        cleanup_records_manager();
    }

    return 0;
}
