    game_event *events;
    size_t event_count;
    size_t max_events;
    record *records;
    size_t record_count;
    long offsets;
    int keys;
    size_t memory_used; // Track memory usage for records
} session;

typedef struct {
    session **sessions;
    size_t session_count;
    size_t max_sessions;
    size_t total_records_allocated;
    const size_t memory_limit;
} session_manager;

session_manager* create_session_manager(size_t max_sessions, size_t memory_limit) {
    session_manager *manager = malloc(sizeof(session_manager));
    manager->sessions = calloc(max_sessions, sizeof(session *));
    manager->session_count = 0;
    manager->max_sessions = max_sessions;
    manager->total_records_allocated = 0;
    manager->memory_limit = memory_limit;
    return manager;
}

int add_session(session_manager *manager, const char *uuid) {
    if (manager->session_count >= manager->max_sessions) return -1;

    session *new_session = malloc(sizeof(session));
    strcpy(new_session->uuid, uuid);
    new_session->events = NULL;
    new_session->event_count = 0;
    new_session->max_events = 10; // Initial size
    new_session->records = NULL;
    new_session->record_count = 0;
    new_session->offsets = 0;
    new_session->keys = 0;
    new_session->memory_used = 0;

    manager->sessions[manager->session_count++] = new_session;
    return 0;
}

int add_event(session_manager *manager, const char *uuid, game_event event) {
    for (size_t i = 0; i < manager->session_count; ++i) {
        if (strcmp(manager->sessions[i]->uuid, uuid) == 0) {
            session *s = manager->sessions[i];
            if (s->event_count >= s->max_events) {
                size_t new_max = s->max_events * 2;
                game_event *new_events = realloc(s->events, new_max * sizeof(game_event));
                if (!new_events) return -1;
                s->events = new_events;
                s->max_events = new_max;
            }
            s->events[s->event_count++] = event;
            return 0;
        }
    }
    return -1;
}

int add_record(session_manager *manager, const char *uuid, record rec) {
    if (manager->total_records_allocated >= manager->memory_limit) return -1;

    for (size_t i = 0; i < manager->session_count; ++i) {
        if (strcmp(manager->sessions[i]->uuid, uuid) == 0) {
            session *s = manager->sessions[i];
            size_t new_size = s->record_count + 1;
            record *new_records = realloc(s->records, new_size * sizeof(record));
            if (!new_records) return -1;

            s->records = new_records;
            s->records[s->record_count++] = rec;
            s->memory_used += sizeof(record);
            manager->total_records_allocated++;

            return 0;
        }
    }
    return -1;
}

void serialize_sessions(const session_manager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->session_count, sizeof(manager->session_count), 1, file);
    for (size_t i = 0; i < manager->session_count; ++i) {
        session *s = manager->sessions[i];
        fwrite(s->uuid, sizeof(char), 37, file);
        fwrite(&s->event_count, sizeof(s->event_count), 1, file);
        fwrite(s->events, sizeof(game_event), s->event_count, file);
        fwrite(&s->record_count, sizeof(s->record_count), 1, file);
        fwrite(s->records, sizeof(record), s->record_count, file);
    }
    fclose(file);
}

int deserialize_sessions(session_manager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t session_count;
    fread(&session_count, sizeof(session_count), 1, file);

    manager->sessions = realloc(manager->sessions, session_count * sizeof(session *));
    manager->session_count = session_count;

    for (size_t i = 0; i < session_count; ++i) {
        session *s = malloc(sizeof(session));
        fread(s->uuid, sizeof(char), 37, file);
        fread(&s->event_count, sizeof(s->event_count), 1, file);

        s->events = malloc(s->event_count * sizeof(game_event));
        fread(s->events, sizeof(game_event), s->event_count, file);

        fread(&s->record_count, sizeof(s->record_count), 1, file);
        s->records = malloc(s->record_count * sizeof(record));
        fread(s->records, sizeof(record), s->record_count, file);

        manager->sessions[i] = s;
    }

    fclose(file);
    return 0;
}

void free_session_manager(session_manager *manager) {
    for (size_t i = 0; i < manager->session_count; ++i) {
        session *s = manager->sessions[i];
        free(s->events);
        free(s->records);
        free(s);
    }
    free(manager->sessions);
    free(manager);
}

int main() {
    session_manager *manager = create_session_manager(100, MEMORY_LIMIT);

    add_session(manager, "123e4567-e89b-12d3-a456-426614174000");
    game_event event = {1, time(NULL), "Event details"};
    add_event(manager, "123e4567-e89b-12d3-a456-426614174000", event);

    record rec = {42, "Record data"};
    add_record(manager, "123e4567-e89b-12d3-a456-426614174000", rec);

    serialize_sessions(manager, "sessions.dat");
    session_manager *new_manager = create_session_manager(100, MEMORY_LIMIT);
    deserialize_sessions(new_manager, "sessions.dat");

    free_session_manager(manager);
    free_session_manager(new_manager);

    return 0;
}
```

### Key Points:
- **Memory Management**: The code uses dynamic memory allocation for sessions, events, and records. It also tracks total memory usage to prevent exceeding a predefined limit.
- **Serialization/Deserialization**: Sessions are serialized to and deserialized from a binary file, ensuring efficient storage and retrieval.
- **Scalability**: The implementation supports scaling by pre-allocating arrays and doubling their size when needed, minimizing reallocations.
- **Error Handling**: Basic error handling is included for memory allocation failures.']

