```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_OFFSET_SUM 1000000
#define INITIAL_SIZE 1024
#define RESIZE_FACTOR 2
#define GRACE_PERIOD 60 // seconds

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
    time_t last_access_time;
    int active;
} Record;

long offsets_sum = 0;

void custom_alloc(long** arr, size_t* current_size) {
    if (*arr == NULL) {
        *current_size = INITIAL_SIZE;
        *arr = (long*)aligned_alloc(16, sizeof(long) * *current_size);
    } else {
        size_t new_size = *current_size + INITIAL_SIZE;
        long* temp = (long*)realloc(*arr, sizeof(long) * new_size);
        if (!temp) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        memset(&temp[*current_size], 0, sizeof(long) * INITIAL_SIZE);
        *arr = temp;
        *current_size = new_size;
    }
}

void custom_alloc_int(int** arr, size_t* current_size) {
    if (*arr == NULL) {
        *current_size = INITIAL_SIZE;
        *arr = (int*)aligned_alloc(16, sizeof(int) * *current_size);
    } else {
        size_t new_size = *current_size + INITIAL_SIZE;
        int* temp = (int*)realloc(*arr, sizeof(int) * new_size);
        if (!temp) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        memset(&temp[*current_size], 0, sizeof(int) * INITIAL_SIZE);
        *arr = temp;
        *current_size = new_size;
    }
}

void init_records_array(Record** records, size_t* current_capacity, size_t* current_count) {
    if (*records == NULL || *current_count >= (*current_capacity * 0.9)) {
        size_t new_capacity = (*current_capacity == 0) ? INITIAL_SIZE : (*current_capacity * RESIZE_FACTOR);
        Record* temp = (Record*)realloc(*records, sizeof(Record) * new_capacity);
        if (!temp) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        memset(&temp[*current_count], 0, sizeof(Record) * (new_capacity - *current_count));
        *records = temp;
        *current_capacity = new_capacity;
    }
}

void update_records_access_time(Record* records, size_t count) {
    time_t now = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        if (now - records[i].last_access_time > GRACE_PERIOD) {
            records[i].active = 0;
        } else {
            records[i].last_access_time = now;
        }
    }
}

void fetch_external_metadata(Record* record, long offset, int key) {
    // Placeholder for fetching metadata from external data sources
    printf("Fetching metadata for record with offset %ld and key %d\n", offset, key);
}

void manage_memory(int num_elements) {
    long* offsets = NULL;
    size_t offsets_size = 0;

    int* keys = NULL;
    size_t keys_size = 0;

    Record* records = NULL;
    size_t records_capacity = 0, records_count = 0;

    srand(time(NULL));

    for (int i = 0; i < num_elements; ++i) {
        if (offsets_sum + rand() % 100 > MAX_OFFSET_SUM) continue;

        custom_alloc(&offsets, &offsets_size);
        offsets[offsets_size - INITIAL_SIZE + i] = rand() % 100;
        offsets_sum += offsets[offsets_size - INITIAL_SIZE + i];

        custom_alloc_int(&keys, &keys_size);
        keys[keys_size - INITIAL_SIZE + i] = rand() % 1000;

        init_records_array(&records, &records_capacity, &records_count);

        Record* record = &records[records_count++];
        record->value = rand() % 100;
        record->offset_ptr = &offsets[offsets_size - INITIAL_SIZE + i];
        record->key_ptr = &keys[keys_size - INITIAL_SIZE + i];
        record->last_access_time = time(NULL);
        record->active = 1;

        fetch_external_metadata(record, offsets[offsets_size - INITIAL_SIZE + i], keys[keys_size - INITIAL_SIZE + i]);
    }

    update_records_access_time(records, records_count);

    // Free resources
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manage_memory(1000000); // Example call with a large number of elements
    return 0;
}
