def update_user_profiles(user_ids, api_endpoints):
    results = {}

    for user_id in user_ids:
        attempts = 3
        while attempts > 0:
            try:
                responses = []
                for endpoint in api_endpoints:
                    response = requests.get(endpoint.format(user_id=user_id))
                    if response.status_code == 429: # Handle rate limiting
                        sleep(1)
                        continue
                    response.raise_for_status()
                    data = response.json()

                    validate(instance=data, schema=user_data_schema) # Validate against schema

                    responses.append(data)

                # Assume updating in a database (placeholder for actual update logic)
                results[user_id] = {"status": "success", "data": responses}
                break
            except requests.RequestException as e:
                attempts -= 1
                if attempts == 0:
                    results[user_id] = {"status": "failed", "reason": str(e)}
            except ValidationError as ve:
                results[user_id] = {"status": "failed", "reason": f"Data validation error: {str(ve)}"}

    return results

# Example usage
