#define MAX_PACKETS 1000000

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;
DataPacket* data_packets[MAX_PACKETS];
size_t packet_count = 0;

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest(EVP_sha1());
}

int find_largest(int* array, size_t size) {
    if (size == 0) return INT_MIN;
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void add_packet(int64_t id, time_t timestamp, uint8_t status, int value) {
    pthread_mutex_lock(&global_lock);
    if (packet_count >= MAX_PACKETS) {
        fprintf(stderr, "Memory limit reached\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }
    data_packets[packet_count] = malloc(sizeof(DataPacket));
    data_packets[packet_count]->id = id;
    data_packets[packet_count]->timestamp = timestamp;
    data_packets[packet_count]->status = status;
    data_packets[packet_count]->value = value;
    packet_count++;
    pthread_mutex_unlock(&global_lock);
}

DataPacket* get_packet(int64_t id) {
    pthread_mutex_lock(&global_lock);
    for (size_t i = 0; i < packet_count; ++i) {
        if (data_packets[i]->id == id) {
            DataPacket* packet = data_packets[i];
            pthread_mutex_unlock(&global_lock);
            return packet;
        }
    }
    pthread_mutex_unlock(&global_lock);
    return NULL;
}

void update_packet(int64_t id, uint8_t status, int value) {
    pthread_mutex_lock(&global_lock);
    for (size_t i = 0; i < packet_count; ++i) {
        if (data_packets[i]->id == id) {
            data_packets[i]->status = status;
            data_packets[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(&global_lock);
}

void purge_expired_packets(time_t expiration_threshold) {
    pthread_mutex_lock(&global_lock);
    size_t new_count = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        if (data_packets[i]->timestamp > expiration_threshold) {
            data_packets[new_count++] = data_packets[i];
        } else {
            free(data_packets[i]);
        }
    }
    packet_count = new_count;
    pthread_mutex_unlock(&global_lock);
}

void process_input() {
