    scanf("%d", &n);
    array = malloc(n * sizeof(int));
    for (i = 0; i < n; ++i) {
        scanf("%d", &array[i]);
    }
    int largest = find_largest(array, n);
    printf("Largest integer: %d\n", largest);
    free(array);
}

void log_operation(const char* message) {
    // Implement logging mechanism
}

int main() {
