    DataPacket* packet = get_packet(1);
    if (packet) {
        printf("Packet found: ID=%ld, Value=%d\n", packet->id, packet->value);
    }

    update_packet(1, 1, 200);
    packet = get_packet(1);
    if (packet) {
        printf("Updated Packet: ID=%ld, Value=%d\n", packet->id, packet->value);
    }

    purge_expired_packets(time(NULL) - 3600);

    // Clean up
    pthread_mutex_destroy(&global_lock);
    for (size_t i = 0; i < packet_count; ++i) {
        free(data_packets[i]);
    }
    return 0;
}
