#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 1024
#define INCREMENT_SIZE 1024
#define ALIGNMENT 64
#define MAX_OFFSET_SUM 1000000
#define GRACE_PERIOD_SECONDS 300

typedef struct {
    int value;
    long* offset;
    int* key;
    time_t last_access_time;
} record;

// Custom allocator for aligned memory
void* custom_aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0)
        return NULL;
    return ptr;
}

typedef struct {
    long* data;
    int capacity;
    int count;
} DynamicArray;

// Function to initialize the arrays with random values
int init_arrays(DynamicArray* offsets, DynamicArray* keys, DynamicArray* records, int range) {
    srand(time(NULL));

