        return -1;
    }
    keys->capacity = INITIAL_SIZE;
    keys->count = 0;

    records->data = (record*)malloc(INITIAL_SIZE * sizeof(record));
    if (!records->data) {
        free(offsets->data);
        free(keys->data);
        return -1;
    }
    records->capacity = INITIAL_SIZE;
    records->count = 0;

    long offset_sum = 0;
    for (int i = 0; i < INITIAL_SIZE; ++i) {
        if (offsets->count >= offsets->capacity) {
            size_t new_capacity = offsets->capacity + INCREMENT_SIZE;
            long* new_data = (long*)custom_aligned_alloc(new_capacity * sizeof(long), ALIGNMENT);
            if (!new_data) return -1;
            memcpy(new_data, offsets->data, offsets->capacity * sizeof(long));
            free(offsets->data);
            offsets->data = new_data;
            offsets->capacity = new_capacity;
        }

        long offset_value = rand() % 1000; // Random value for demonstration
        if ((offset_sum + offset_value) > MAX_OFFSET_SUM)
            break;

        offsets->data[offsets->count++] = offset_value;
        offset_sum += offset_value;

        if (keys->count >= keys->capacity) {
            size_t new_capacity = keys->capacity + INCREMENT_SIZE;
            int* new_data = (int*)custom_aligned_alloc(new_capacity * sizeof(int), ALIGNMENT);
            if (!new_data) return -1;
            memcpy(new_data, keys->data, keys->capacity * sizeof(int));
            free(keys->data);
            keys->data = new_data;
            keys->capacity = new_capacity;
        }

        keys->data[keys->count++] = rand() % 1000; // Random key for demonstration

        if (records->count >= records->capacity * 0.9) {
            size_t new_capacity = records->capacity * 2;
            record* new_data = (record*)realloc(records->data, new_capacity * sizeof(record));
