            records->data = new_data;
            records->capacity = new_capacity;
        }

        record rec;
        rec.value = rand() % range; // Random value within range
        rec.offset = &offsets->data[offsets->count - 1];
        rec.key = &keys->data[keys->count - 1];
        time(&rec.last_access_time);
        records->data[records->count++] = rec;
    }

    return 0; // Success
}

// Function to mark inactive records
void mark_inactive_records(DynamicArray* records) {
    time_t current_time;
    time(&current_time);

    for (int i = 0; i < records->count; ++i) {
        if (difftime(current_time, records->data[i].last_access_time) > GRACE_PERIOD_SECONDS) {
            // Mark as inactive by setting value to a sentinel or similar logic
            records->data[i].value = -1;
        }
    }
}

// Periodic background task for reorganizing records based on access frequency
void* reorganize_records(void* arg) {
