### Python Code for API Integration

```python
import requests
from datetime import datetime, timedelta
import jsonschema
from time import sleep

# Define schema for validation
user_profile_schema = {
    "type": "object",
    "properties": {
        "contact_info": {"type": "string"},
        "last_accessed": {"type": "string", "format": "date-time"},
        "device_type": {"type": "string"}
    },
    "required": ["contact_info", "last_accessed", "device_type"]
}

def fetch_data_from_api(api_endpoint):
    retry_count = 3
    for attempt in range(retry_count):
        try:
            response = requests.get(api_endpoint)
            if response.status_code == 429:  # Rate limit exceeded
                sleep(2 ** attempt)  # Exponential backoff
                continue
            response.raise_for_status()
            return response.json()
        except (requests.exceptions.RequestException, json.JSONDecodeError):
            if attempt == retry_count - 1:
                raise

def update_user_profile(user_id, new_data):
    try:
        # Validate incoming data against schema
        jsonschema.validate(instance=new_data, schema=user_profile_schema)

        # Simulate database update
        print(f"Updating user {user_id} with {new_data}")
        return {"success": True}
    except jsonschema.exceptions.ValidationError as e:
        return {"success": False, "error": str(e)}

def integrate_api_data(user_ids, api_endpoints):
    results = {}

    for user_id in user_ids:
        try:
            api_data = fetch_data_from_api(api_endpoints[user_id])

            # Update profile with new data
            result = update_user_profile(user_id, api_data)
            results[user_id] = {"status": "success", "details": result}

        except Exception as e:
            results[user_id] = {"status": "failed", "reason": str(e)}

    return results

# Example usage
user_ids = [1, 2, 3]
api_endpoints = {
    1: "https://api.example.com/user/1/contact",
    2: "https://api.example.com/user/2/contact",
    3: "https://api.example.com/user/3/contact"
}

report = integrate_api_data(user_ids, api_endpoints)
print(json.dumps(report, indent=4))
