```python
import requests
from requests.adapters import HTTPAdapter
from requests.packages.urllib3.util.retry import Retry
from jsonschema import validate, ValidationError

def fetch_and_update_user_profiles(user_ids):
    api_urls = {
        'contact_info': 'https://api.example.com/contact',
        'device_type': 'https://api.example.com/device'
    }

    schema = {
        "type": "object",
        "properties": {
            "user_id": {"type": "string"},
            "last_accessed": {"type": "integer"},
            "contact_info": {"type": "string"},
            "device_type": {"type": "string"}
        },
        "required": ["user_id", "last_accessed", "contact_info", "device_type"]
    }

    session = requests.Session()
    retry_strategy = Retry(
        total=3,
        backoff_factor=1,
        status_forcelist=[429, 500, 502, 503, 504],
        method_whitelist=["HEAD", "GET", "OPTIONS"]
    )
    adapter = HTTPAdapter(max_retries=retry_strategy)
    session.mount("https://", adapter)

    report = {"success": [], "failed": []}

    for user_id in user_ids:
        try:
            contact_info_response = session.get(f"{api_urls['contact_info']}/{user_id}")
            device_type_response = session.get(f"{api_urls['device_type']}/{user_id}")

            if not contact_info_response.ok or not device_type_response.ok:
                raise Exception("API request failed")

            user_data = {
                "user_id": user_id,
                "last_accessed": int(time.time()),
                "contact_info": contact_info_response.json().get('info'),
                "device_type": device_type_response.json().get('type')
            }

            try:
                validate(instance=user_data, schema=schema)
                # Update user profile in the database
                report["success"].append(user_id)
            except ValidationError as ve:
                raise Exception(f"Data validation failed: {ve}")

        except Exception as e:
            report["failed"].append({"user_id": user_id, "reason": str(e)})

    return report

# Example usage
if __name__ == "__main__":
    user_ids = ['123', '456', '789']
    update_report = fetch_and_update_user_profiles(user_ids)
    print(update_report)
```

