    size_t count;
    Workitem **workitems;
    pthread_rwlock_t rwlock; // Read-write lock for concurrent access
    int error_flag;
} WorkitemCollection;

// Utility function prototypes
char* load_random_description(const char *filename);
int get_priority_bias();
void init_workitem_id(WorkitemID *id);

// Main memory management functions
WorkitemCollection* create_workitems(size_t num_items, const char *config_file) {
    if (num_items <= 0 || config_file == NULL) return NULL;

    WorkitemCollection *collection = malloc(sizeof(WorkitemCollection));
    if (!collection) {
        log_error("Memory allocation failed for workitem collection.");
        return NULL;
    }
    memset(collection, 0, sizeof(WorkitemCollection));

    pthread_rwlock_init(&collection->rwlock, NULL);
    collection->count = num_items;
    collection->workitems = malloc(num_items * sizeof(Workitem*));
    if (!collection->workitems) {
        log_error("Memory allocation failed for workitem array.");
        free(collection);
        return NULL;
    }

    // Load configurations
    char **descriptions = load_descriptions_from_config(config_file);

    for (size_t i = 0; i < num_items; ++i) {
        Workitem *workitem = malloc(sizeof(Workitem));
        if (!workitem) {
            log_error("Memory allocation failed for a workitem.");
            collection->error_flag = 1;
            break;
        }

        pthread_mutex_init(&workitem->lock, NULL);

        // Load description
        workitem->description = load_random_description(config_file);
        if (workitem->description == NULL) {
            log_error("Failed to load a valid description.");
            collection->error_flag = 1;
            break;
        }

        // Set priority with bias
        int priority_bias = get_priority_bias();
        workitem->priority = rand() % 5 + 1 + (rand() % 2 == 0 ? priority_bias : 0);

        // Initialize dependencies as an acyclic graph
        workitem->dependencies = NULL;
        size_t num_dependencies = rand() % 5; // Random number of dependencies for illustration

        WorkitemID *prev_id = NULL;
        for (size_t j = 0; j < num_dependencies; ++j) {
            WorkitemID *new_id = malloc(sizeof(WorkitemID));
            if (!new_id) {
                log_error("Memory allocation failed for workitem ID.");
                collection->error_flag = 1;
                break;
            }

            init_workitem_id(new_id);
            new_id->status = PENDING;

            if (prev_id != NULL) prev_id->next = new_id;
            else workitem->dependencies = new_id;
            prev_id = new_id;
        }

        collection->workitems[i] = workitem;
    }

    // Log initialization
    log_info("Workitem collection initialized with %zu items.", num_items);

    return collection;
}

void destroy_workitems(WorkitemCollection *collection) {
    if (collection == NULL) return;

    pthread_rwlock_wrlock(&collection->rwlock);
    for (size_t i = 0; i < collection->count; ++i) {
        Workitem *workitem = collection->workitems[i];

        if (workitem != NULL) {
            free(workitem->description);

            WorkitemID *dep = workitem->dependencies;
            while (dep != NULL) {
                WorkitemID *temp = dep;
                dep = dep->next;
                free(temp);
            }

            pthread_mutex_destroy(&workitem->lock);
            free(workitem);
        }
    }

    free(collection->workitems);
    pthread_rwlock_unlock(&collection->rwlock);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);

    log_info("Workitem collection deallocated.");
}

// Example utility function implementations
char* load_random_description(const char *filename) {
    // Implement logic to read and randomize descriptions from the file, ensuring uniqueness.
    return strdup("Example description"); // Placeholder implementation
}

int get_priority_bias() {
    // Logic to determine priority bias based on system resources or workload.
    return (rand() % 2 == 0 ? 1 : 0); // Example logic for bias
}

void init_workitem_id(WorkitemID *id) {
    uuid_t binuuid;
    uuid_generate_random(binuuid);
    char struuid[37];
    uuid_unparse_lower(binuuid, struuid);
    strcpy(id->uuid, struuid);
}
