['Below is a C code implementing the described functionality. This example uses POSIX threads for concurrency control, `pthread_mutex_t` for mutual exclusion, and standard file I/O for serialization/deserialization.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define MAX_NODES 1000
#define MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct Data {
    char* string;
    double value;
    struct Data* next;
} Data;

typedef struct Node {
    int key;
    time_t timestamp;
    struct Node* next;
    Data* data_head;
} Node;

typedef struct Manager {
    Node* head;
    size_t total_memory_used;
    pthread_mutex_t lock;
    size_t node_count;
} Manager;

Manager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0};

void add_data(Data** data_head, const char* string, double value) {
    Data* new_data = malloc(sizeof(Data));
    if (!new_data) {
        perror("Failed to allocate memory for new data");
        return;
    }

    new_data->string = strdup(string);
    new_data->value = value;
    new_data->next = *data_head;
    *data_head = new_data;
}

void cleanup_node(Node* node) {
    Data* current, *tmp;
    current = node->data_head;
    while (current) {
        tmp = current;
        current = current->next;
        free(tmp->string);
        free(tmp);
    }
    free(node);
}

int find_and_update(Node** head, int key, const char* string, double value) {
    Node* current = *head;
    while (current) {
        if (current->key == key) {
            add_data(&current->data_head, string, value);
            return 0; // Updated successfully
        }
        current = current->next;
    }
    return -1; // Key not found
}

int insert_node(Manager* manager, int key, const char* data_string, double data_value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->node_count >= MAX_NODES || manager->total_memory_used + sizeof(Node) > MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded or max node count reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_node->key = key;
    new_node->timestamp = time(NULL);
    new_node->data_head = NULL;

    add_data(&new_node->data_head, data_string, data_value);

    new_node->next = manager->head;
    manager->head = new_node;
    manager->node_count++;
    manager->total_memory_used += sizeof(Node) + strlen(data_string) + 1;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

Node* find_node(Manager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (current->key == key) {
            current->timestamp = time(NULL); // Update access timestamp
            pthread_mutex_unlock(&manager->lock);
            return current; // Found node
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

void serialize(Manager* manager, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->timestamp, sizeof(time_t), 1, file);

        Data* data_current = current->data_head;
        while (data_current) {
            size_t len = strlen(data_current->string) + 1;
            fwrite(&len, sizeof(size_t), 1, file);
            fwrite(data_current->string, sizeof(char), len, file);
            fwrite(&data_current->value, sizeof(double), 1, file);
            data_current = data_current->next;
        }

        size_t end_marker = -1; // Marker for end of node's data
        fwrite(&end_marker, sizeof(size_t), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void deserialize(Manager* manager, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    Node* prev_node = NULL;
    int key;
    time_t timestamp;
    while (fread(&key, sizeof(int), 1, file)) {
        if (key == -1) break; // End of file marker

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for deserialized node");
            continue;
        }

        fread(&timestamp, sizeof(time_t), 1, file);
        new_node->key = key;
        new_node->timestamp = timestamp;
        new_node->data_head = NULL;

        size_t len;
        while (fread(&len, sizeof(size_t), 1, file) && len != -1) {
            char* string = malloc(len);
            if (!string) {
                perror("Failed to allocate memory for deserialized data");
                cleanup_node(new_node);
                break;
            }

            fread(string, sizeof(char), len, file);
            double value;
            fread(&value, sizeof(double), 1, file);

            add_data(&new_node->data_head, string, value);
        }

        if (prev_node) {
            prev_node->next = new_node;
        } else {
            manager->head = new_node;
        }

        prev_node = new_node;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void periodic_cleanup(Manager* manager, time_t duration_threshold) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current) {
        if (difftime(time(NULL), current->timestamp) > duration_threshold) {
            if (prev) prev->next = current->next; else manager->head = current->next;

            cleanup_node(current);
            manager->node_count--;
            manager->total_memory_used -= sizeof(Node); // Approximation
        } else {
            prev = current;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    insert_node(&manager, 1, "example data", 123.45);

    Node* node = find_node(&manager, 1);
    if (node) {
        printf("Found node with key %d\n", node->key);
    }

    serialize(&manager, "nodes.dat");
    deserialize(&manager, "nodes.dat");

    periodic_cleanup(&manager, 3600); // Cleanup nodes not accessed in the last hour

    return 0;
}
```

This code provides a basic implementation of the described functionalities. It supports adding new nodes, updating existing ones, and retrieving data by key with thread safety ensured through mutex locks. Serialization and deserialization are implemented using simple file I/O for demonstration purposes. Error handling is included for memory allocation failures, exceeding limits, and file operations. The periodic cleanup function removes nodes not accessed within a specified duration to manage memory usage effectively.

Note: For production use, consider more robust error checking, dynamic resizing of the data structure, and exploring efficient serialization libraries as mentioned in the task description.']

