#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct PacketInfo {
    int frame_number;
    int packet_id;
    int error_status;
    struct PacketInfo *next;
} PacketInfo;

typedef struct FrameStatsNode {
    time_t timestamp;
    int signal_strength;
    PacketInfo *packet_info_list;
    struct FrameStatsNode *next;
} FrameStatsNode;

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    int status_flag;
    struct DataPacket *next;
} DataPacket;

typedef struct CacheEntry {
    int packet_id;
    PacketInfo *info;
    struct CacheEntry *next;
} CacheEntry;

typedef struct {
    DataPacket *packets;
    FrameStatsNode *frames;
    CacheEntry *cache;
    pthread_mutex_t lock;
    time_t expiration_threshold;
    size_t cache_size_limit;
} DataManager;

// Function prototypes
DataManager* initialize_manager(size_t cache_size, time_t exp_threshold);
void destroy_manager(DataManager *manager);

void add_packet(DataManager *manager, int packet_id, time_t timestamp, int status_flag);
DataPacket* get_packet(DataManager *manager, int packet_id);
void update_packet_status(DataManager *manager, int packet_id, int new_status);
void purge_expired_packets(DataManager *manager);
void fetch_packet_info(DataManager *manager, int frame_number);

// Utility functions
static CacheEntry* find_cache_entry(DataManager *manager, int packet_id);
static void add_to_cache(DataManager *manager, int packet_id, PacketInfo *info);
static void remove_from_cache(DataManager *manager, int packet_id);

DataManager* initialize_manager(size_t cache_size, time_t exp_threshold) {
    DataManager *manager = malloc(sizeof(DataManager));
    manager->packets = NULL;
    manager->frames = NULL;
    manager->cache = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->expiration_threshold = exp_threshold;
    manager->cache_size_limit = cache_size;
    return manager;
}

void destroy_manager(DataManager *manager) {
    DataPacket *packet = manager->packets;
    while (packet) {
        DataPacket *next_packet = packet->next;
        free(packet);
        packet = next_packet;
    }

    FrameStatsNode *frame = manager->frames;
    while (frame) {
        FrameStatsNode *next_frame = frame->next;
        PacketInfo *info = frame->packet_info_list;
        while (info) {
            PacketInfo *next_info = info->next;
            free(info);
            info = next_info;
        }
        free(frame);
        frame = next_frame;
    }

    CacheEntry *cache_entry = manager->cache;
    while (cache_entry) {
        CacheEntry *next_cache_entry = cache_entry->next;
        PacketInfo *info = cache_entry->info;
        while (info) {
            PacketInfo *next_info = info->next;
            free(info);
            info = next_info;
        }
        free(cache_entry);
        cache_entry = next_cache_entry;
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_packet(DataManager *manager, int packet_id, time_t timestamp, int status_flag) {
    pthread_mutex_lock(&manager->lock);

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->status_flag = status_flag;
    new_packet->next = manager->packets;
    manager->packets = new_packet;

    pthread_mutex_unlock(&manager->lock);
}

DataPacket* get_packet(DataManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);

    DataPacket *packet = manager->packets;
    while (packet) {
        if (packet->packet_id == packet_id) {
            pthread_mutex_unlock(&manager->lock);
            return packet;
        }
        packet = packet->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_packet_status(DataManager *manager, int packet_id, int new_status) {
    pthread_mutex_lock(&manager->lock);

    DataPacket *packet = manager->packets;
    while (packet) {
        if (packet->packet_id == packet_id) {
            packet->status_flag = new_status;
            break;
        }
        packet = packet->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void purge_expired_packets(DataManager *manager) {
    pthread_mutex_lock(&manager->lock);

    DataPacket **packet_ptr = &manager->packets;
    while (*packet_ptr) {
        DataPacket *current_packet = *packet_ptr;
        if (difftime(time(NULL), current_packet->timestamp) > manager->expiration_threshold) {
            *packet_ptr = current_packet->next;
            free(current_packet);
        } else {
            packet_ptr = &current_packet->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void fetch_packet_info(DataManager *manager, int frame_number) {
    // Simulate fetching from an external source
    PacketInfo *info = malloc(sizeof(PacketInfo));
    info->frame_number = frame_number;
    info->packet_id = rand();  // Example packet ID
    info->error_status = rand() % 2;  // Random error status
    info->next = NULL;

    pthread_mutex_lock(&manager->lock);
    add_to_cache(manager, info->packet_id, info);
    pthread_mutex_unlock(&manager->lock);
}

static CacheEntry* find_cache_entry(DataManager *manager, int packet_id) {
    CacheEntry *entry = manager->cache;
    while (entry) {
        if (entry->packet_id == packet_id) {
            return entry;
        }
        entry = entry->next;
    }
    return NULL;
}

static void add_to_cache(DataManager *manager, int packet_id, PacketInfo *info) {
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    new_entry->packet_id = packet_id;
    new_entry->info = info;
    new_entry->next = manager->cache;
    manager->cache = new_entry;

    // Enforce cache size limit
    if (manager->cache_size_limit) {
        CacheEntry **entry_ptr = &manager->cache;
        while (*entry_ptr && --manager->cache_size_limit > 0) {
            entry_ptr = &(*entry_ptr)->next;
        }
        if (*entry_ptr) {
            CacheEntry *old_entry = *entry_ptr;
            *entry_ptr = old_entry->next;
            PacketInfo *info_to_free = old_entry->info;
            while (info_to_free) {
                PacketInfo *next_info = info_to_free->next;
                free(info_to_free);
                info_to_free = next_info;
            }
            free(old_entry);
        }
    }
}

static void remove_from_cache(DataManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);

    CacheEntry **entry_ptr = &manager->cache;
    while (*entry_ptr) {
        if ((*entry_ptr)->packet_id == packet_id) {
            CacheEntry *to_remove = *entry_ptr;
            *entry_ptr = to_remove->next;
            PacketInfo *info_to_free = to_remove->info;
            while (info_to_free) {
                PacketInfo *next_info = info_to_free->next;
                free(info_to_free);
                info_to_free = next_info;
            }
            free(to_remove);
            break;
        }
        entry_ptr = &(*entry_ptr)->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    DataManager *manager = initialize_manager(100, 60);

    add_packet(manager, 1, time(NULL), 0);
    DataPacket *packet = get_packet(manager, 1);
    if (packet) {
        printf("Packet ID: %d\n", packet->packet_id);
    }

    update_packet_status(manager, 1, 1);
    purge_expired_packets(manager);

    fetch_packet_info(manager, 123);

    destroy_manager(manager);
    return 0;
}
