#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000
#define LOG_MESSAGE_SIZE 1024

typedef struct {
    time_t timestamp;
    int severity_level;
    char message[LOG_MESSAGE_SIZE];
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogManager;

LogManager* create_log_manager(size_t initial_capacity) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    manager->entries = (LogEntry *)malloc(initial_capacity * sizeof(LogEntry));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_log_manager(LogManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LogEntry *new_entries = (LogEntry *)realloc(manager->entries, new_capacity * sizeof(LogEntry));
    if (new_entries) {
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }
}

void log_entry(LogManager *manager, int severity_level, const char *message) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_log_manager(manager);
    }

    LogEntry *entry = &manager->entries[manager->count++];
    entry->timestamp = time(NULL);
    entry->severity_level = severity_level;
    strncpy(entry->message, message, LOG_MESSAGE_SIZE - 1);

    pthread_mutex_unlock(&manager->lock);
}

void filter_and_retrieve_logs(LogManager *manager, int min_severity, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LogEntry *entry = &manager->entries[i];
        if (entry->severity_level >= min_severity &&
            entry->timestamp >= start_time &&
            entry->timestamp <= end_time) {
            printf("Timestamp: %ld, Severity: %d, Message: %s\n", 
                   entry->timestamp, entry->severity_level, entry->message);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_log_manager(LogManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->entries);
    free(manager);
}

int main() {
    LogManager *log_manager = create_log_manager(10);

    log_entry(log_manager, 1, "This is an info message.");
    log_entry(log_manager, 2, "This is a warning message.");
    log_entry(log_manager, 3, "This is an error message.");

    time_t now = time(NULL);
    filter_and_retrieve_logs(log_manager, 1, now - 3600, now);

    free_log_manager(log_manager);
    return 0;
}
