#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define constants
#define MAX_BUFFER_SIZE 1024

// Structure for linked list node representing related events
typedef struct EventNode {
    void *event;
    struct EventNode *next;
} EventNode;

// Structure to hold event data
typedef struct Event {
    char buffer[MAX_BUFFER_SIZE];
    float severity_score;
    EventNode *related_events;
} Event;

// Global variables for managing memory and concurrency
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function prototypes
void free_all_resources(float *timestamps, char **event_ids, Event *events, size_t size);

// Main function to allocate and initialize resources
void* allocate_and_initialize(size_t num_events) {
    if (num_events == 0) {
        fprintf(stderr, "Error: Number of events must be greater than zero.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex); // Ensure thread-safe access

    float *timestamps = malloc(num_events * sizeof(float));
    char **event_ids = malloc(num_events * sizeof(char *));
    Event *events = malloc(num_events * sizeof(Event));

    if (!timestamps || !event_ids || !events) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free_all_resources(timestamps, event_ids, events, num_events);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize timestamps and event IDs
    for (size_t i = 0; i < num_events; ++i) {
        timestamps[i] = 0.0f;

        event_ids[i] = malloc(10); // Assuming a maximum length of 9 characters + null terminator
        if (!event_ids[i]) {
            fprintf(stderr, "Error: Memory allocation for event ID failed.\n");
            free_all_resources(timestamps, event_ids, events, num_events);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        snprintf(event_ids[i], 10, "ID%zu", i + 1);

        // Initialize each event
        events[i].related_events = NULL; // No related events initially
    }

    pthread_mutex_unlock(&mutex); // Release the lock

    // Return a pointer to an anonymous structure containing all allocated resources
    return malloc(sizeof(float *) * 3);
}

void free_all_resources(float *timestamps, char **event_ids, Event *events, size_t size) {
    if (timestamps) free(timestamps);
    for (size_t i = 0; i < size; ++i) {
        if (event_ids[i]) free(event_ids[i]);
        // Free linked list of related events
        EventNode *node = events[i].related_events;
        while (node) {
            EventNode *next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    if (event_ids) free(event_ids);
    if (events) free(events);
}

int main() {
    size_t num_events = 5; // Example usage
    void* resources = allocate_and_initialize(num_events);

    if (!resources) {
        fprintf(stderr, "Failed to initialize resources.\n");
        return EXIT_FAILURE;
    }

    float **all_resources = (float **)resources;

    free_all_resources(all_resources[0], (char **)all_resources[1], (Event *)all_resources[2], num_events);
    free(resources);

    return 0;
}
