['Below is a C implementation of the `packet_manager` function. This code includes the necessary components to manage packets, handle cryptographic keys, integrate with an external configuration service, ensure thread safety, and provide logging mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for packet status
#define PACKET_STATUS_ACTIVE 1
#define PACKET_STATUS_EXPIRED 0

// Define cryptographic algorithms
typedef enum {
    AES,
    CAMELLIA,
    MD5,
    SHA,
    RSA_SHA1
} CryptoAlgorithm;

// DataPacket structure
typedef struct {
    int id;
    time_t timestamp;
    int status;
    char crypto_hash[64]; // Assuming a fixed size for simplicity
} DataPacket;

// Cryptographic key pool structure
typedef struct {
    CryptoAlgorithm algorithm;
    void *key; // Pointer to the actual key data
    size_t key_size;
} CryptoKeyPool;

// Packet Manager structure
typedef struct {
    DataPacket **packets;
    int packet_count;
    pthread_mutex_t lock;
    time_t expiration_threshold;
    CryptoKeyPool *key_pool;
    int key_pool_size;
    FILE *log_file;
} PacketManager;

// Function prototypes
void packet_manager_init(PacketManager *manager);
void packet_manager_destroy(PacketManager *manager);
int add_packet(PacketManager *manager, DataPacket *packet);
DataPacket* get_packet_by_id(PacketManager *manager, int id);
int update_packet(PacketManager *manager, DataPacket *packet);
void purge_expired_packets(PacketManager *manager);
void adjust_expiration_threshold(PacketManager *manager);
void log_event(const char *message);

// Initialize the packet manager
void packet_manager_init(PacketManager *manager) {
    manager->packets = NULL;
    manager->packet_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->expiration_threshold = 3600; // Default to 1 hour
    manager->key_pool_size = 5; // Example size
    manager->key_pool = malloc(manager->key_pool_size * sizeof(CryptoKeyPool));
    manager->log_file = fopen("packet_manager.log", "a");
}

// Destroy the packet manager and free resources
void packet_manager_destroy(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->packet_count; ++i) {
        free(manager->packets[i]);
    }
    free(manager->packets);
    free(manager->key_pool);
    fclose(manager->log_file);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Add a new packet
int add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);

    // Check if the packet already exists
    for (int i = 0; i < manager->packet_count; ++i) {
        if (manager->packets[i]->id == packet->id) {
            log_event("Packet with existing ID attempted to be added.");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    // Allocate memory for the new packet
    manager->packets = realloc(manager->packets, (manager->packet_count + 1) * sizeof(DataPacket*));
    if (!manager->packets) {
        log_event("Memory allocation failed when adding a new packet.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Add the packet
    manager->packets[manager->packet_count] = malloc(sizeof(DataPacket));
    if (!manager->packets[manager->packet_count]) {
        log_event("Memory allocation failed when adding a new packet.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    memcpy(manager->packets[manager->packet_count], packet, sizeof(DataPacket));
    manager->packets[manager->packet_count]->timestamp = time(NULL);

    // Update count
    manager->packet_count++;
    log_event("Packet added successfully.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Retrieve a packet by its ID
DataPacket* get_packet_by_id(PacketManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->packet_count; ++i) {
        if (manager->packets[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->packets[i];
        }
    }

    log_event("Packet with specified ID not found.");
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Update an existing packet
int update_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->packet_count; ++i) {
        if (manager->packets[i]->id == packet->id) {
            memcpy(manager->packets[i], packet, sizeof(DataPacket));
            log_event("Packet updated successfully.");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    log_event("Packet with specified ID not found for update.");
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Purge expired packets
void purge_expired_packets(PacketManager *manager) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->packet_count; ++i) {
        if ((current_time - manager->packets[i]->timestamp) > manager->expiration_threshold) {
            free(manager->packets[i]);
            // Shift remaining packets
            for (int j = i; j < manager->packet_count - 1; ++j) {
                manager->packets[j] = manager->packets[j + 1];
            }
            manager->packet_count--;
            log_event("Expired packet purged.");
        }
    }

    // Resize the packets array
    manager->packets = realloc(manager->packets, manager->packet_count * sizeof(DataPacket*));

    pthread_mutex_unlock(&manager->lock);
}

// Adjust expiration threshold based on external configuration service
void adjust_expiration_threshold(PacketManager *manager) {
    // Simulate fetching from an external service
    time_t new_threshold = 7200; // Example: 2 hours

    pthread_mutex_lock(&manager->lock);
    manager->expiration_threshold = new_threshold;
    log_event("Expiration threshold adjusted.");
    pthread_mutex_unlock(&manager->lock);
}

// Log events to a file or console
void log_event(const char *message) {
    time_t now = time(NULL);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock(&manager->log_file->mutex); // Assuming a mutex for thread safety
    fprintf(manager->log_file, "[%s] %s\n", buffer, message);
    fflush(manager->log_file);
    pthread_mutex_unlock(&manager->log_file->mutex);
}

// Example usage
int main() {
    PacketManager manager;
    packet_manager_init(&manager);

    DataPacket new_packet = {1, 0, PACKET_STATUS_ACTIVE, "hash_value"};
    add_packet(&manager, &new_packet);

    DataPacket *retrieved_packet = get_packet_by_id(&manager, 1);
    if (retrieved_packet) {
        printf("Packet ID: %d\n", retrieved_packet->id);
    }

    adjust_expiration_threshold(&manager);
    purge_expired_packets(&manager);

    packet_manager_destroy(&manager);
    return 0;
}
