#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef enum {
    TEXT_DATA,
    IMAGE_DATA,
    AUDIO_DATA
} DataType;

typedef struct {
    int key;
    time_t timestamp;
    char buffer[BUFFER_SIZE];
    DataType type;
    time_t last_accessed;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordList;

char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
int charset_size = sizeof(charset) - 1;

void generate_random_string(char *str, size_t length) {
    for (size_t i = 0; i < length; i++) {
        str[i] = charset[rand() % charset_size];
    }
    str[length] = '\0';
}

RecordList* create_record_list() {
    RecordList* list = malloc(sizeof(RecordList));
    if (!list) {
        perror("Failed to allocate memory for record list");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_record(RecordList* list, int key, DataType type) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data.key = key;
    time(&(new_node->data.timestamp));
    generate_random_string(new_node->data.buffer, BUFFER_SIZE - 1);
    new_node->data.type = type;
    new_node->data.last_accessed = new_node->data.timestamp;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

Record* retrieve_record(RecordList* list, int key) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.key == key) {
            current->data.last_accessed = time(NULL);
            Record* record = &current->data;
            pthread_mutex_unlock(&list->lock);
            return record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void serialize_record(Record* record, FILE* file) {
    if (record) {
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->timestamp, sizeof(time_t), 1, file);
        fwrite(record->buffer, BUFFER_SIZE, 1, file);
        fwrite(&record->type, sizeof(DataType), 1, file);
        fwrite(&record->last_accessed, sizeof(time_t), 1, file);
    }
}

void deserialize_record(Record* record, FILE* file) {
    if (record && file) {
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->timestamp, sizeof(time_t), 1, file);
        fread(record->buffer, BUFFER_SIZE, 1, file);
        fread(&record->type, sizeof(DataType), 1, file);
        fread(&record->last_accessed, sizeof(time_t), 1, file);
    }
}

void log_operation(const char* operation) {
    FILE* log_file = fopen("operation_log.txt", "a");
    if (log_file) {
        time_t now;
        time(&now);
        fprintf(log_file, "[%s] %s\n", ctime(&now), operation);
        fclose(log_file);
    }
}

void archive_records(RecordList* list, FILE* archive_file) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if ((time(NULL) - current->data.last_accessed) > 86400) { // Archive records not accessed for a day
            serialize_record(&current->data, archive_file);
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
            list->head = current;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void* background_archiver(void* arg) {
    RecordList* list = (RecordList*)arg;
    FILE* archive_file;

    while ((archive_file = fopen("archive.dat", "ab")) != NULL) {
        archive_records(list, archive_file);
        fclose(archive_file);

        sleep(3600); // Archive every hour
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    RecordList* list = create_record_list();

    pthread_t archiver_thread;
    if (pthread_create(&archiver_thread, NULL, background_archiver, list) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    insert_record(list, 1, TEXT_DATA);
    log_operation("Inserted record with key 1");

    Record* record = retrieve_record(list, 1);
    if (record) {
        printf("Retrieved record: %s\n", record->buffer);
        log_operation("Retrieved record with key 1");
    }

    pthread_join(archiver_thread, NULL);

    // Cleanup
    free(list);

    return EXIT_SUCCESS;
}
