public class ByteArrayProcessor
{
    private readonly ILogger<ByteArrayProcessor> _logger;
    private readonly HttpClient _httpClient;

    public ByteArrayProcessor(ILogger<ByteArrayProcessor> logger, IHttpClientFactory httpClientFactory)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _httpClient = httpClientFactory.CreateClient();
    }

    public async Task<(bool Success, string ErrorMessage)> ProcessAndForwardAsync(byte[] data)
