        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                var response = await ForwardDataWithRetryAsync(connectionSettings, data).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    return (true, null);
