    struct Activity *next;
} Activity;

// Structure for user profile
typedef struct UserProfile {
    int id;
    char name[64];
    struct Activity *activities;
    struct UserProfile *next;
} UserProfile;

// Global variables
#define MAX_PROFILES 1000
UserProfile *profiles = NULL;
int profile_count = 0;
pthread_mutex_t profiles_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = fopen("error_log.txt", "a");

// Function to log errors
void log_error(const char *message) {
    pthread_mutex_lock(&profiles_mutex);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&profiles_mutex);
}

// Function to add a new user profile
int add_user_profile(int id, const char *name) {
    if (profile_count >= MAX_PROFILES || name == NULL || strlen(name) >= 64) {
        log_error("Failed to add user: Maximum profiles reached or invalid input.");
        return -1;
    }

    UserProfile *new_profile = (UserProfile *)malloc(sizeof(UserProfile));
    if (!new_profile) {
        log_error("Memory allocation failed for new profile.");
        return -1;
    }

    pthread_mutex_lock(&profiles_mutex);
    new_profile->id = id;
    strncpy(new_profile->name, name, sizeof(new_profile->name) - 1);
    new_profile->activities = NULL;
    new_profile->next = profiles;
    profiles = new_profile;
    profile_count++;
    pthread_mutex_unlock(&profiles_mutex);

    return 0;
}

// Function to add an activity to a user profile
int add_activity(int profile_id, ActivityType type, const char *description) {
    if (description == NULL || strlen(description) >= 128) {
        log_error("Failed to add activity: Invalid description.");
        return -1;
    }

    pthread_mutex_lock(&profiles_mutex);
    UserProfile *current = profiles;
    while (current != NULL && current->id != profile_id) {
        current = current->next;
    }
    if (!current) {
        log_error("User profile not found for adding activity.");
        pthread_mutex_unlock(&profiles_mutex);
        return -1;
    }

    Activity *new_activity = (Activity *)malloc(sizeof(Activity));
    if (!new_activity) {
        log_error("Memory allocation failed for new activity.");
        pthread_mutex_unlock(&profiles_mutex);
        return -1;
    }

    new_activity->timestamp = time(NULL);
    new_activity->type = type;
    strncpy(new_activity->description, description, sizeof(new_activity->description) - 1);
    new_activity->next = current->activities;
    current->activities = new_activity;

    pthread_mutex_unlock(&profiles_mutex);

    return 0;
}

// Example usage
int main() {
    if (add_user_profile(1, "Alice") == 0) {
        printf("User Alice added successfully.\n");
    }

    if (add_activity(1, ACTIVITY_LOGIN, "Logged in from home") == 0) {
        printf("Activity logged for user ID 1.\n");
    }

    // Clean-up logic should be implemented here

    fclose(log_file);
    return 0;
}
