    private static readonly byte[] TripleDesKey = Encoding.UTF8.GetBytes("YourTripleDESKey123"); // Ensure key is 24 bytes for Triple DES
    private static readonly byte[] TripleDesIV = Encoding.UTF8.GetBytes("YourTripleDESIV12");   // Ensure IV is 8 bytes

    public async Task LoadAndExecuteJavaScriptFiles(string base64EncodedMessage)
    {
        try
        {
            string decryptedMessage = DecryptTripleDESEncryptedMessage(base64EncodedMessage, TripleDesKey, TripleDesIV);
            string[] filePaths = decryptedMessage.Split(',');

            var tasks = new Task[filePaths.Length];

            for (int i = 0; i < filePaths.Length; i++)
            {
                string path = filePaths[i].Trim();
                if (!string.IsNullOrEmpty(path) && File.Exists(path))
                {
                    tasks[i] = ExecuteJavaScriptFileAsync(path);
                }
                else
                {
                    Console.WriteLine($"Warning: JavaScript file at {path} is missing or unavailable.");
                }
            }

            await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing request: {ex.Message}");
        }
    }

    private string DecryptTripleDESEncryptedMessage(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

        using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;

            using (MemoryStream memoryStream = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream cryptoStream = new CryptoStream(memoryStream, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (StreamReader reader = new StreamReader(cryptoStream))
                    {
                        return reader.ReadToEnd();
                    }
                }
            }
        }
    }

    private async Task ExecuteJavaScriptFileAsync(string path)
    {
        try
        {
            string jsCode = await File.ReadAllTextAsync(path);
            // Assuming a method EvaluateJavaScript exists that safely evaluates JS in the context of your application.
            EvaluateJavaScript(jsCode);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to load JavaScript file at {path}: {ex.Message}");
        }
    }

    private void EvaluateJavaScript(string jsCode)
    {
        // Implementation depends on the environment, e.g., using a WebView2 control or similar.
        Console.WriteLine("Executing JavaScript:");
        Console.WriteLine(jsCode);
    }
}
