['Below is a C implementation for managing a dynamic list of records in a resource-constrained embedded system environment. This solution includes initialization, adding, removing, updating records, and handling memory efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    float data;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} RecordList;

// Function to initialize the record list
RecordList* init_record_list(size_t initial_capacity) {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a new record
int add_record(RecordList *list, long offset, float data) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Record *new_records = (Record *)realloc(list->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }

    list->records[list->count].offset = offset;
    list->records[list->count].data = data;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove a record by index
int remove_record(RecordList *list, size_t index) {
    if (index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);

    memmove(&list->records[index], &list->records[index + 1],
            (list->count - index - 1) * sizeof(Record));
    list->count--;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to update records using a transformation function
void update_records(RecordList *list, float (*transform)(float)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->records[i].data = transform(list->records[i].data);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example transformation function
float example_transform(float data) {
    return data * 1.05f; // Increase by 5%
}

// Function to free the record list and its resources
void free_record_list(RecordList *list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->records);
    free(list);
}

// Initialize arrays for offsets, keys, and records with random int values
void init_arrays(size_t size, long* offset_array, int* key_array, Record* record_array, int min_val, int max_val) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        offset_array[i] = rand() % 1000;
        key_array[i] = rand() % 100;

        record_array[i].offset = offset_array[i];
        record_array[i].data = (float)(min_val + rand() % (max_val - min_val));
    }
}

int main() {
    size_t initial_capacity = 10;
    RecordList *list = init_record_list(initial_capacity);

    if (!list) {
        fprintf(stderr, "Failed to initialize record list.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    add_record(list, 123L, 45.67f);
    update_records(list, example_transform);

    free_record_list(list);

    size_t array_size = 5;
    long offsets[array_size];
    int keys[array_size];
    Record records[array_size];

    init_arrays(array_size, offsets, keys, records, 10, 100);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Memory Management**: Efficiently handles memory allocation and reallocation using `realloc`.
- **Thread Safety**: Uses a mutex lock to ensure thread-safe operations on the record list.
- **Initialization and Randomization**: Initializes arrays with random values for testing purposes.
- **Transformation Functionality**: Updates records using a transformation function passed as a parameter.
- **Memory Cleanup**: Properly frees allocated resources to prevent memory leaks.
- **Modularity and Documentation**: Code is structured into functions, each handling specific tasks, making it easy to maintain and extend.']

