#include <time.h>

// Define a ResourceNode structure
typedef struct ResourceNode {
    int id;
    int *dependencies; // Dynamic array of node IDs this node depends on
    size_t dep_count;
    double load_status;
    pthread_mutex_t lock; // Mutex for thread-safe access
} ResourceNode;

// Define a Graph structure to manage ResourceNodes
typedef struct {
    ResourceNode **nodes;
    size_t node_count;
    pthread_rwlock_t graph_lock;
} ResourceGraph;

// Log structure for operations
typedef struct OperationLog {
    char message[256];
    time_t timestamp;
    struct OperationLog *next;
} OperationLog;

OperationLog *log_head = NULL;
pthread_mutex_t log_lock;

// Function to initialize a resource node
ResourceNode* create_node(int id, double load_status) {
    ResourceNode *node = (ResourceNode *)malloc(sizeof(ResourceNode));
    if (!node) return NULL;

    node->id = id;
    node->dependencies = NULL;
    node->dep_count = 0;
    node->load_status = load_status;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

// Function to initialize a graph
ResourceGraph* create_graph() {
    ResourceGraph *graph = (ResourceGraph *)malloc(sizeof(ResourceGraph));
    if (!graph) return NULL;

    graph->nodes = NULL;
    graph->node_count = 0;
    pthread_rwlock_init(&graph->graph_lock, NULL);

    return graph;
}

// Function to add a new node to the graph
void add_node(ResourceGraph *graph, int id, double load_status) {
    pthread_rwlock_wrlock(&graph->graph_lock);

    ResourceNode *node = create_node(id, load_status);
    if (!node) {
        printf("Failed to allocate memory for new node\n");
        pthread_rwlock_unlock(&graph->graph_lock);
        return;
    }

    graph->nodes = (ResourceNode**)realloc(graph->nodes, sizeof(ResourceNode*) * (graph->node_count + 1));
    if (!graph->nodes) {
        free(node);
        printf("Failed to reallocate memory for nodes array\n");
        pthread_rwlock_unlock(&graph->graph_lock);
        return;
    }

    graph->nodes[graph->node_count] = node;
    graph->node_count++;

    log_operation("Node added with ID: %d", id);

    pthread_rwlock_unlock(&graph->graph_lock);
}

// Function to update resource dependencies
void update_dependencies(ResourceGraph *graph, int id, int *new_deps, size_t new_dep_count) {
    pthread_rwlock_wrlock(&graph->graph_lock);

    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i]->id == id) {
            pthread_mutex_lock(&graph->nodes[i]->lock);

            free(graph->nodes[i]->dependencies); // Free existing dependencies
            graph->nodes[i]->dependencies = (int *)malloc(sizeof(int) * new_dep_count);
            if (!graph->nodes[i]->dependencies) {
                printf("Failed to allocate memory for new dependencies\n");
                pthread_mutex_unlock(&graph->nodes[i]->lock);
                pthread_rwlock_unlock(&graph->graph_lock);
                return;
            }

            memcpy(graph->nodes[i]->dependencies, new_deps, sizeof(int) * new_dep_count);
            graph->nodes[i]->dep_count = new_dep_count;

            log_operation("Dependencies updated for node ID: %d", id);

            pthread_mutex_unlock(&graph->nodes[i]->lock);
            break;
        }
    }

    pthread_rwlock_unlock(&graph->graph_lock);
}

// Function to retrieve a node by its identifier
ResourceNode* get_node_by_id(ResourceGraph *graph, int id) {
    pthread_rwlock_rdlock(&graph->graph_lock);

    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i]->id == id) {
            pthread_rwlock_unlock(&graph->graph_lock);
            return graph->nodes[i];
        }
    }

    pthread_rwlock_unlock(&graph->graph_lock);
    return NULL;
}

// Function to log operations
void log_operation(const char *format, ...) {
    va_list args;
    va_start(args, format);

    OperationLog *new_log = (OperationLog *)malloc(sizeof(OperationLog));
    if (!new_log) return;

    pthread_mutex_lock(&log_lock);

    snprintf(new_log->message, sizeof(new_log->message), format, args);
    new_log->timestamp = time(NULL);
    new_log->next = log_head;
    log_head = new_log;

    pthread_mutex_unlock(&log_lock);

    va_end(args);
}

// Function to detect and resolve resource contention
void balance_load(ResourceGraph *graph) {
    // Placeholder for load balancing logic
    log_operation("Load balancing initiated");
}

// Function to handle periodic updates from an external data source
void update_topology_from_source(ResourceGraph *graph, void (*data_fetch)(ResourceGraph*)) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))data_fetch, graph) != 0) {
        printf("Failed to create a thread for updating topology\n");
    }
}

// Mock function to simulate fetching data from an external source
void* mock_data_source(void *graph_ptr) {
    ResourceGraph *graph = (ResourceGraph *)graph_ptr;

    while (1) {
        sleep(5); // Simulate periodic updates every 5 seconds

        pthread_rwlock_wrlock(&graph->graph_lock);

        for (size_t i = 0; i < graph->node_count; ++i) {
            pthread_mutex_lock(&graph->nodes[i]->lock);

            // Mock update: Randomly adjust load status
            graph->nodes[i]->load_status += ((double)rand() / RAND_MAX - 0.5);
            log_operation("Load status updated for node ID: %d", graph->nodes[i]->id);

            pthread_mutex_unlock(&graph->nodes[i]->lock);
        }

        pthread_rwlock_unlock(&graph->graph_lock);
    }

    return NULL;
}

// Cleanup function to deallocate resources
void cleanup_graph(ResourceGraph *graph) {
    pthread_rwlock_wrlock(&graph->graph_lock);

    for (size_t i = 0; i < graph->node_count; ++i) {
        free(graph->nodes[i]->dependencies);
        pthread_mutex_destroy(&graph->nodes[i]->lock);
        free(graph->nodes[i]);
    }

    free(graph->nodes);
    pthread_rwlock_unlock(&graph->graph_lock);
    pthread_rwlock_destroy(&graph->graph_lock);

    // Free log list
    OperationLog *current = log_head;
    while (current) {
        OperationLog *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&log_lock);
}

int main() {
    ResourceGraph *graph = create_graph();
    if (!graph) return 1;

    add_node(graph, 1, 0.5);
    add_node(graph, 2, 0.3);

    int deps[] = {2};
    update_dependencies(graph, 1, deps, 1);

    ResourceNode *node = get_node_by_id(graph, 1);
    if (node) {
        printf("Retrieved Node ID: %d\n", node->id);
    }

    balance_load(graph);
    update_topology_from_source(graph, mock_data_source);

    sleep(15); // Allow some time for updates

    cleanup_graph(graph);

    return 0;
}
