#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_PACKETS_PER_TYPE 100

typedef struct {
    char *identifier;
    int value;
} DataPacket;

typedef struct PacketType {
    const char *type_name;
    size_t max_count;
    pthread_mutex_t lock;
    DataPacket **packets;
    unsigned int count;
    struct PacketType *next;
} PacketType;

typedef struct {
    PacketType *types;
    pthread_mutex_t global_lock;
    FILE *log_file;
    int log_mode; // 0 for append, 1 for overwrite
} PacketManager;

PacketManager manager = {NULL, PTHREAD_MUTEX_INITIALIZER, NULL, 0};

int register_packet_type(const char *type_name) {
    pthread_mutex_lock(&manager.global_lock);

    PacketType **current = &manager.types;
    while (*current) {
        if (strcmp((*current)->type_name, type_name) == 0) {
            pthread_mutex_unlock(&manager.global_lock);
            return -1; // Type already registered
        }
        current = &(*current)->next;
    }

    PacketType *new_type = malloc(sizeof(PacketType));
    new_type->type_name = strdup(type_name);
    new_type->max_count = MAX_PACKETS_PER_TYPE;
    pthread_mutex_init(&new_type->lock, NULL);
    new_type->packets = calloc(new_type->max_count, sizeof(DataPacket *));
    new_type->count = 0;
    new_type->next = NULL;

    *current = new_type;
    log_operation("Register packet type", "Success");

    pthread_mutex_unlock(&manager.global_lock);
    return 0;
}

int add_packet(const char *type_name, const char *identifier) {
    pthread_mutex_lock(&manager.global_lock);

    PacketType **current = &manager.types;
    while (*current) {
        if (strcmp((*current)->type_name, type_name) == 0) {
            break;
        }
        current = &(*current)->next;
    }

    if (!*current) {
        log_operation("Add packet", "Failure: Type not registered");
        pthread_mutex_unlock(&manager.global_lock);
        return -1;
    }

    PacketType *packet_type = *current;

    pthread_mutex_lock(&packet_type->lock);

    if (packet_type->count >= packet_type->max_count) {
        log_operation("Add packet", "Failure: Max packets reached");
        pthread_mutex_unlock(&packet_type->lock);
        pthread_mutex_unlock(&manager.global_lock);
        return -2;
    }

    for (unsigned int i = 0; i < packet_type->count; ++i) {
        if (strcmp(packet_type->packets[i]->identifier, identifier) == 0) {
            log_operation("Add packet", "Failure: Identifier already exists");
            pthread_mutex_unlock(&packet_type->lock);
            pthread_mutex_unlock(&manager.global_lock);
            return -3;
        }
    }

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->identifier = strdup(identifier);
    new_packet->value = rand(); // Assign a random value for demonstration

    packet_type->packets[packet_type->count++] = new_packet;
    log_operation("Add packet", "Success");

    pthread_mutex_unlock(&packet_type->lock);
    pthread_mutex_unlock(&manager.global_lock);
    return 0;
}

int update_packet(const char *type_name, const char *identifier, int new_value) {
    pthread_mutex_lock(&manager.global_lock);

    PacketType **current = &manager.types;
    while (*current) {
        if (strcmp((*current)->type_name, type_name) == 0) {
            break;
        }
        current = &(*current)->next;
    }

    if (!*current) {
        log_operation("Update packet", "Failure: Type not registered");
        pthread_mutex_unlock(&manager.global_lock);
        return -1;
    }

    PacketType *packet_type = *current;

    pthread_mutex_lock(&packet_type->lock);

    for (unsigned int i = 0; i < packet_type->count; ++i) {
        if (strcmp(packet_type->packets[i]->identifier, identifier) == 0) {
            packet_type->packets[i]->value = new_value;
            log_operation("Update packet", "Success");
            pthread_mutex_unlock(&packet_type->lock);
            pthread_mutex_unlock(&manager.global_lock);
            return 0;
        }
    }

    log_operation("Update packet", "Failure: Identifier not found");
    pthread_mutex_unlock(&packet_type->lock);
    pthread_mutex_unlock(&manager.global_lock);
    return -2;
}

DataPacket* get_packet(const char *type_name, const char *identifier) {
    pthread_mutex_lock(&manager.global_lock);

    PacketType **current = &manager.types;
    while (*current) {
        if (strcmp((*current)->type_name, type_name) == 0) {
            break;
        }
        current = &(*current)->next;
    }

    if (!*current) {
        log_operation("Get packet", "Failure: Type not registered");
        pthread_mutex_unlock(&manager.global_lock);
        return NULL;
    }

    PacketType *packet_type = *current;

    pthread_mutex_lock(&packet_type->lock);

    for (unsigned int i = 0; i < packet_type->count; ++i) {
        if (strcmp(packet_type->packets[i]->identifier, identifier) == 0) {
            log_operation("Get packet", "Success");
            pthread_mutex_unlock(&packet_type->lock);
            pthread_mutex_unlock(&manager.global_lock);
            return packet_type->packets[i];
        }
    }

    log_operation("Get packet", "Failure: Identifier not found");
    pthread_mutex_unlock(&packet_type->lock);
    pthread_mutex_unlock(&manager.global_lock);
    return NULL;
}

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_alias("md5", "MD5");
    EVP_add_digest(EVP_sha1());
    EVP_add_cipher(EVP_camellia_128_cbc());
}

int log_operation(const char *action, const char *status) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';

    if (manager.log_file == NULL) {
        manager.log_file = fopen("packet_log.txt", manager.log_mode ? "w" : "a");
        if (!manager.log_file) return -1;
    }

    fprintf(manager.log_file, "[%s] %s: %s\n", timestamp, action, status);
    fflush(manager.log_file);

    return 0;
}

void find_largest_integer() {
    int n, max = INT_MIN;
    printf("Enter numbers (end with non-integer input):\n");
    while (scanf("%d", &n) == 1) {
        if (n > max) max = n;
    }
    printf("Largest integer: %d\n", max);
}

void initialize_and_manage_packets() {
