['Below is a C code implementation tailored for managing a dynamic list of records in a resource-constrained embedded system environment. This solution addresses the requirements specified, including efficient memory management, thread safety, logging, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for array sizes and range limits
#define INITIAL_SIZE 10
#define MAX_OFFSETS 100
#define KEY_RANGE_MAX 1000

typedef struct {
    long offset;
    float data;
    char status;
} Record;

typedef struct {
    Record *records;
    int *keys;
    char *statuses;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

// Function prototypes
void initRecordList(RecordList *list);
void freeRecordList(RecordList *list);
int addRecord(RecordList *list, long offset, float data, char status);
int removeRecord(RecordList *list, int key);
void updateRecords(RecordList *list, float (*transform)(float));
void logMessage(const char *message);

// Initialize the record list
void initRecordList(RecordList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = INITIAL_SIZE;
    list->count = 0;

    list->records = (Record *)malloc(list->capacity * sizeof(Record));
    list->keys = (int *)malloc(list->capacity * sizeof(int));
    list->statuses = (char *)malloc(list->capacity);

    if (!list->records || !list->keys || !list->statuses) {
        logMessage("Failed to allocate memory for record list.");
        exit(EXIT_FAILURE);
    }
}

// Free the resources associated with the record list
void freeRecordList(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->records);
    free(list->keys);
    free(list->statuses);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Add a new record to the list
int addRecord(RecordList *list, long offset, float data, char status) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Record *new_records = (Record *)realloc(list->records, new_capacity * sizeof(Record));
        int *new_keys = (int *)realloc(list->keys, new_capacity * sizeof(int));
        char *new_statuses = (char *)realloc(list->statuses, new_capacity);

        if (!new_records || !new_keys || !new_statuses) {
            logMessage("Failed to reallocate memory for record list.");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->records = new_records;
        list->keys = new_keys;
        list->statuses = new_statuses;
        list->capacity = new_capacity;
    }

    int key = rand() % KEY_RANGE_MAX; // Generate a random key
    while (key == 0 || key >= list->count) { // Ensure key is unique and valid
        key = rand() % KEY_RANGE_MAX;
    }

    list->records[list->count] = (Record){offset, data, status};
    list->keys[list->count] = key;
    list->statuses[list->count] = status;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a record from the list by key
int removeRecord(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->keys[i] == key) {
            memmove(&list->records[i], &list->records[i + 1],
                    (list->count - i - 1) * sizeof(Record));
            memmove(&list->keys[i], &list->keys[i + 1],
                    (list->count - i - 1) * sizeof(int));
            memmove(&list->statuses[i], &list->statuses[i + 1],
                    list->count - i - 1);

            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Key not found
}

// Update all records using a transformation function
void updateRecords(RecordList *list, float (*transform)(float)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->records[i].data = transform(list->records[i].data);
    }

    pthread_mutex_unlock(&list->lock);
}

// Log a message
void logMessage(const char *message) {
    printf("LOG: %s\n", message);
}

// Example transformation function
float exampleTransform(float data) {
    return data * 1.05; // Increase by 5%
}

int main() {
    RecordList list;
    initRecordList(&list);

    srand(time(NULL)); // Seed random number generator

    // Add some records
    for (int i = 0; i < 15; ++i) {
        addRecord(&list, rand(), (float)rand() / RAND_MAX, 'A' + (rand() % 3));
    }

    // Update records
    updateRecords(&list, exampleTransform);

    // Remove a record
    removeRecord(&list, list.keys[0]);

    freeRecordList(&list);
    return 0;
}
```

### Key Features:

1. **Dynamic Memory Management**: Uses `malloc` and `realloc` to manage dynamic arrays efficiently.
2. **Thread Safety**: Uses `pthread_mutex_t` for locking mechanisms to ensure thread safety.
3. **Error Handling**: Logs errors and exits gracefully if memory allocation fails.
4. **Logging Mechanism**: Simple logging function to track operations and errors.
5. **Modular Design**: Functions are modular, facilitating maintenance and extension.
6. **Efficiency Considerations**: Balances between stack and heap allocation, minimizes fragmentation with reallocation strategies.

This implementation provides a robust foundation for managing records in an embedded system while considering resource constraints and performance optimization.']

