    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
}

// Resize the dynamic list to accommodate more records
int resizeDynamicList(DynamicList *list, int newCapacity) {
    Record *newRecords = realloc(list->records, newCapacity * sizeof(Record));
    if (!newRecords) return -1; // Memory allocation failed

    memset(newRecords + list->count, 0, (newCapacity - list->capacity) * sizeof(Record)); // Clear new memory
    list->records = newRecords;
    list->capacity = newCapacity;

    return 0; // Success
}

// Add a new record to the dynamic list
int addRecord(DynamicList *list, Record record) {
    if (list->count == list->capacity) {
        int newCapacity = list->capacity ? list->capacity * 2 : 4;
        if (resizeDynamicList(list, newCapacity) != 0)
            return -1; // Memory allocation failed
    }

    list->records[list->count++] = record;
    return 0; // Success
}

// Remove a record from the dynamic list by index
int removeRecord(DynamicList *list, int index) {
    if (index < 0 || index >= list->count)
        return -1; // Invalid index

    memmove(&list->records[index], &list->records[index + 1],
            (list->count - index - 1) * sizeof(Record));
    list->count--;

    return 0; // Success
}

