['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RANGE 1000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t length;
    pthread_mutex_t lock;
} data_structure;

void handle_memory_failure(void **ptr) {
    if (*ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

data_structure* initialize_data_structure(size_t config_length) {
    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) return NULL;

    ds->offsets = malloc(config_length * sizeof(long));
    handle_memory_failure((void**)&ds->offsets);

    ds->keys = malloc(config_length * sizeof(int));
    handle_memory_failure((void**)&ds->keys);

    ds->records = malloc(config_length * sizeof(record));
    handle_memory_failure((void**)&ds->records);

    ds->length = config_length;

    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

int generate_unique_key(int used_keys[], size_t length) {
    int key;
    do {
        key = rand() % MAX_RANGE;
    } while (used_keys[key] == 1);

    used_keys[key] = 1; // Mark this key as used
    return key;
}

void initialize_records(data_structure *ds) {
    int used_keys[MAX_RANGE] = {0};
    for (size_t i = 0; i < ds->length; ++i) {
        pthread_mutex_lock(&ds->lock);

        int key = generate_unique_key(used_keys, MAX_RANGE);

        ds->keys[i] = key;
        ds->records[i].value = rand() % MAX_RANGE;

        pthread_mutex_unlock(&ds->lock);
    }
}

void serialize_data_structure(const data_structure *ds, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(ds->length, sizeof(size_t), 1, file);

    fwrite(ds->offsets, sizeof(long), ds->length, file);
    fwrite(ds->keys, sizeof(int), ds->length, file);

    for (size_t i = 0; i < ds->length; ++i) {
        int value = ds->records[i].value;
        fwrite(&value, sizeof(int), 1, file);
    }

    fclose(file);
}

data_structure* deserialize_data_structure(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) return NULL;

    size_t length;
    fread(&length, sizeof(size_t), 1, file);

    ds->offsets = malloc(length * sizeof(long));
    handle_memory_failure((void**)&ds->offsets);
    ds->keys = malloc(length * sizeof(int));
    handle_memory_failure((void**)&ds->keys);
    ds->records = malloc(length * sizeof(record));
    handle_memory_failure((void**)&ds->records);

    fread(ds->offsets, sizeof(long), length, file);
    fread(ds->keys, sizeof(int), length, file);

    for (size_t i = 0; i < length; ++i) {
        int value;
        fread(&value, sizeof(int), 1, file);
        ds->records[i].value = value;
    }

    ds->length = length;
    pthread_mutex_init(&ds->lock, NULL);

    fclose(file);
    return ds;
}

void free_data_structure(data_structure *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
    }
}

int main() {
    srand(time(NULL));

    size_t config_length = 1000;
    data_structure *ds = initialize_data_structure(config_length);

    if (!ds) return EXIT_FAILURE;

    initialize_records(ds);

    serialize_data_structure(ds, "data.bin");

    data_structure *loaded_ds = deserialize_data_structure("data.bin");

    free_data_structure(ds);
    free_data_structure(loaded_ds);

    return 0;
}
```

