#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_CONFIGS 10000
#define LOG_FILE "network_log.txt"

typedef struct {
    char mac[18];
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} ConfigList;

// Logging function
void log_message(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

// Initialize configuration list
ConfigList* init_config_list() {
    ConfigList* list = malloc(sizeof(ConfigList));
    if (!list) {
        log_message("Failed to allocate memory for config list");
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Check uniqueness of MAC address
int is_unique_mac(const char* mac, ConfigList* list) {
    Node* current = list->head;
    while (current) {
        if (strcmp(current->config.mac, mac) == 0) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

// Add configuration
int add_config(ConfigList* list, NetworkConfig config) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_CONFIGS || !is_unique_mac(config.mac, list)) {
        pthread_mutex_unlock(&list->lock);
        log_message("Failed to add config: max configs reached or duplicate MAC");
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&new_node->config, &config, sizeof(NetworkConfig));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    log_message("Added new network configuration");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Serialize to file
int serialize_list(ConfigList* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_message("Failed to open file for serialization");
        return -1;
    }

    Node* current = list->head;
    while (current) {
        fprintf(file, "%s,%s,%s,%s\n", 
                current->config.mac,
                current->config.ip,
                current->config.subnet_mask,
                current->config.gateway);
        current = current->next;
    }

    fclose(file);
    log_message("Serialized configuration list to file");
    return 0;
}

// Deserialize from file
int deserialize_list(ConfigList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_message("Failed to open file for deserialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    Node* current;
    while ((current = list->head)) {
        list->head = current->next;
        free(current);
    }
    list->count = 0;

    char line[256];
    NetworkConfig config;
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%17[^,],%15[^,],%15[^,],%15[^\n]",
                   config.mac, config.ip, config.subnet_mask, config.gateway) == 4) {
            add_config(list, config);
        }
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
    log_message("Deserialized configuration list from file");
    return 0;
}

// Free the list
void free_list(ConfigList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
    log_message("Freed configuration list");
}

// Example function to perform network health check
void network_health_check(const char* interface, const char* host) {
    // This is a placeholder for ping or similar functionality
    log_message("Performing network health check on interface: ");
    log_message(interface);
    log_message(", pinging host: ");
    log_message(host);
    // Implement actual network health check logic here
}

// Main function to demonstrate usage
int main() {
    ConfigList* list = init_config_list();
    if (!list) return -1;

    NetworkConfig config = {"00:11:22:33:44:55", "192.168.0.2", "255.255.255.0", "192.168.0.1"};
    add_config(list, config);

    serialize_list(list, "network_configs.txt");
    deserialize_list(list, "network_configs.txt");

    network_health_check("eth0", "8.8.8.8");

    free_list(list);
    return 0;
}
