    double *measurements;
} Record;

// Thread data for managing contexts in multi-threaded environment
typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *md_ctx;
    pthread_mutex_t lock; // For thread safety
} ThreadData;

// Function prototypes
Record* initialize_record(size_t size, int range_min, int range_max);
void free_record(Record *record);
int perform_encryption(ThreadData *thread_data, const unsigned char *plaintext, int plaintext_len,
                       unsigned char *ciphertext, int *ciphertext_len);
int perform_decryption(ThreadData *thread_data, const unsigned char *ciphertext, int ciphertext_len,
                       unsigned char *plaintext, int *plaintext_len);
void compute_statistics(const Record *record, size_t size, double *mean, double *std_dev);

// Initialize and populate the record
Record* initialize_record(size_t size, int range_min, int range_max) {
    if (size == 0 || range_min >= range_max) return NULL;

    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    // Allocate memory for offsets, keys, and measurements
    record->offsets = malloc(size * sizeof(long));
    record->keys = malloc(size * sizeof(int));
    record->measurements = malloc(size * sizeof(double));

    if (!record->offsets || !record->keys || !record->measurements) {
        free(record->offsets);
        free(record->keys);
        free(record->measurements);
        free(record);
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        record->keys[i] = range_min + rand() % (range_max - range_min + 1);
        record->measurements[i] = (double)record->keys[i] / RAND_MAX;
        record->offsets[i] = (long)(record->measurements[i] * 10000);
    }

    return record;
}

// Free the allocated memory for the record
void free_record(Record *record) {
    if (!record) return;

    free(record->offsets);
    free(record->keys);
    free(record->measurements);

    free(record);
}

// Thread-safe encryption function
int perform_encryption(ThreadData *thread_data, const unsigned char *plaintext, int plaintext_len,
                       unsigned char *ciphertext, int *ciphertext_len) {
    pthread_mutex_lock(&thread_data->lock);

    if (!EVP_EncryptInit_ex(thread_data->cipher_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }

    // Example key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};
    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};

    if (!EVP_EncryptInit_ex(thread_data->cipher_ctx, NULL, NULL, key, iv)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }

    int len;
    if (!EVP_EncryptUpdate(thread_data->cipher_ctx, ciphertext, &len, plaintext, plaintext_len)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }
    *ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(thread_data->cipher_ctx, ciphertext + len, &len)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }
    *ciphertext_len += len;

    pthread_mutex_unlock(&thread_data->lock);

    return 0;
}

// Thread-safe decryption function
int perform_decryption(ThreadData *thread_data, const unsigned char *ciphertext, int ciphertext_len,
                       unsigned char *plaintext, int *plaintext_len) {
    pthread_mutex_lock(&thread_data->lock);

    if (!EVP_DecryptInit_ex(thread_data->cipher_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }

    // Example key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};
    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};

    if (!EVP_DecryptInit_ex(thread_data->cipher_ctx, NULL, NULL, key, iv)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }

    int len;
    if (!EVP_DecryptUpdate(thread_data->cipher_ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }
    *plaintext_len = len;

    if (!EVP_DecryptFinal_ex(thread_data->cipher_ctx, plaintext + len, &len)) {
        pthread_mutex_unlock(&thread_data->lock);
        return -1;
    }
    *plaintext_len += len;

    pthread_mutex_unlock(&thread_data->lock);

    return 0;
}

// Compute statistics on double fields
void compute_statistics(const Record *record, size_t size, double *mean, double *std_dev) {
    if (!record || !mean || !std_dev || size == 0) return;

    double sum = 0.0, sq_sum = 0.0;
    for (size_t i = 0; i < size; ++i) {
        sum += record->measurements[i];
        sq_sum += record->measurements[i] * record->measurements[i];
    }

    *mean = sum / size;
    double variance = (sq_sum / size) - (*mean) * (*mean);
    if (variance < 0.0) variance = 0.0; // Guard against numerical issues
    *std_dev = sqrt(variance);
}

// Main function to demonstrate usage
int main() {
    size_t record_size = 100;
    int range_min = 1, range_max = 100;

    Record *record = initialize_record(record_size, range_min, range_max);
    if (!record) {
        fprintf(stderr, "Failed to initialize record\n");
        return -1;
    }

    // Example usage of encryption/decryption
    ThreadData thread_data;
    pthread_mutex_init(&thread_data.lock, NULL);
    thread_data.cipher_ctx = EVP_CIPHER_CTX_new();
    thread_data.md_ctx = EVP_MD_CTX_new();

    if (!thread_data.cipher_ctx || !thread_data.md_ctx) {
        fprintf(stderr, "Failed to initialize cipher or digest context\n");
        free_record(record);
        pthread_mutex_destroy(&thread_data.lock);
        EVP_CIPHER_CTX_free(thread_data.cipher_ctx);
        EVP_MD_CTX_free(thread_data.md_ctx);
        return -1;
    }

    unsigned char plaintext[] = "Sample data for encryption";
    unsigned char ciphertext[128];
    int ciphertext_len;

    if (perform_encryption(&thread_data, plaintext, sizeof(plaintext), ciphertext, &ciphertext_len) != 0) {
        fprintf(stderr, "Encryption failed\n");
    } else {
        printf("Encrypted data: %s\n", ciphertext);
    }

    unsigned char decryptedtext[128];
    int decryptedtext_len;

    if (perform_decryption(&thread_data, ciphertext, ciphertext_len, decryptedtext, &decryptedtext_len) != 0) {
        fprintf(stderr, "Decryption failed\n");
    } else {
        printf("Decrypted data: %s\n", decryptedtext);
    }

    double mean = 0.0, std_dev = 0.0;
    compute_statistics(record, record_size, &mean, &std_dev);

    printf("Mean: %.2f, Standard Deviation: %.2f\n", mean, std_dev);

    // Cleanup
    free_record(record);
    pthread_mutex_destroy(&thread_data.lock);
    EVP_CIPHER_CTX_free(thread_data.cipher_ctx);
    EVP_MD_CTX_free(thread_data.md_ctx);

    return 0;
}
```

