    int unique_id;
    char* metadata_json;
} TrafficEvent;

typedef struct Node {
    TrafficEvent event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TrafficArray;

TrafficArray* create_traffic_array() {
    TrafficArray* array = malloc(sizeof(TrafficArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

char random_char() {
    return 'A' + rand() % 2;
}

char* generate_random_string(size_t length) {
    char* str = malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    str[length] = '\0';
    return str;
}

TrafficEvent generate_event(int offset, int key) {
    TrafficEvent event;
    event.timestamp = time(NULL) + offset;
    event.event_type = rand() % 100; // Example range
    event.unique_id = key;

    json_object* jobj = json_object_new_object();
    json_object* value = json_object_new_int(rand());
    json_object* status = json_object_new_string(random_char() == 'A' ? "Active" : "Inactive");
    char* random_str = generate_random_string(10);
    json_object* metadata = json_object_new_string(random_str);
    free(random_str);

    json_object_object_add(jobj, "value", value);
    json_object_object_add(jobj, "status", status);
    json_object_object_add(jobj, "metadata", metadata);

    const char* metadata_json = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN | JSON_C_TO_STRING_PRETTY);
    event.metadata_json = strdup(metadata_json);

    json_object_put(jobj); // Free JSON object
    return event;
}

void add_event(TrafficArray* array, TrafficEvent event) {
    pthread_mutex_lock(&array->lock);

    Node* new_node = malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = array->head;
    array->head = new_node;

    // Log the event
    log_event(event);

    pthread_mutex_unlock(&array->lock);
}

void remove_event(TrafficArray* array, int unique_id) {
    pthread_mutex_lock(&array->lock);

    Node **indirect = &array->head;
    while (*indirect && (*indirect)->event.unique_id != unique_id) {
        indirect = &(*indirect)->next;
    }
    if (*indirect) {
        Node* node_to_remove = *indirect;
        *indirect = node_to_remove->next;
        free(node_to_remove->event.metadata_json);
        free(node_to_remove);
    }

    pthread_mutex_unlock(&array->lock);
}

void serialize_events(const TrafficArray* array, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        fprintf(file, "%ld,%d,%d,%s\n",
                current->event.timestamp,
                current->event.event_type,
                current->event.unique_id,
                current->event.metadata_json);
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

void deserialize_events(TrafficArray* array, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return;

    pthread_mutex_lock(&array->lock);

    TrafficEvent event;
    while (fscanf(file, "%ld,%d,%d,%ms",
                  &event.timestamp,
                  &event.event_type,
                  &event.unique_id,
                  &event.metadata_json) == 4) {
        add_event(array, event);
    }

    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

// Placeholder for more complex query functions
void query_events(TrafficArray* array, int start_time, int end_time);

// Example usage of the library
int main() {
    srand(time(NULL));

    TrafficArray* traffic_array = create_traffic_array();

    // Simulate adding events
    for (int i = 0; i < 100; ++i) {
        add_event(traffic_array, generate_event(i, rand()));
    }

    serialize_events(traffic_array, "events.log");
    deserialize_events(traffic_array, "events.log");

    remove_event(traffic_array, 42); // Example removal

    // Cleanup
    pthread_mutex_destroy(&traffic_array->lock);
    while (traffic_array->head) {
        Node* temp = traffic_array->head;
        traffic_array->head = temp->next;
        free(temp->event.metadata_json);
        free(temp);
    }
    free(traffic_array);

    return 0;
}
