static size_t total_records = 0;
const size_t MAX_RECORDS = 1000; // Maximum number of records allowed

// Function to generate random content for the char buffer
void generate_random_content(char *buffer, const char *charset, size_t length) {
    const size_t charset_size = strlen(charset);
    for (size_t i = 0; i < length - 1; ++i) { // Leave space for null terminator
        buffer[i] = charset[rand() % charset_size];
    }
    buffer[length - 1] = '\0';
}

// Function to initialize records based on specified proportions
Record* init_records(size_t size, double static_prop, double dynamic_prop, double temporary_prop, const char *charset) {
    if (size > MAX_RECORDS || total_records + size > MAX_RECORDS) {
        fprintf(stderr, "Error: Exceeding maximum record count.\n");
        return NULL;
    }

    Record* records = malloc(size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int static_count = (int)(size * static_prop);
    int dynamic_count = (int)(size * dynamic_prop);
    int temporary_count = size - static_count - dynamic_count;

    for (size_t i = 0; i < size; ++i) {
        if (i < static_count) {
            records[i].metadata = STATIC;
        } else if (i < static_count + dynamic_count) {
            records[i].metadata = DYNAMIC;
        } else {
            records[i].metadata = TEMPORARY;
        }

        generate_random_content(records[i].buffer, charset, sizeof(records[i].buffer));
        records[i].value = rand(); // Example value initialization
    }

    total_records += size;
    return records;
}

// Function to serialize records to a file
int serialize_records(const char *filename, Record *records, size_t size) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    const char* metadata_strings[] = {"STATIC", "DYNAMIC", "TEMPORARY"};

    for (size_t i = 0; i < size; ++i) {
        fprintf(file, "%d %s %s\n", records[i].value, metadata_strings[records[i].metadata], records[i].buffer);
    }

    fclose(file);
    return 0;
}

// Function to deserialize records from a file
Record* deserialize_records(const char *filename, size_t *size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Record temp_record;
    char buffer[256];
    int metadata_map[] = {STATIC, DYNAMIC, TEMPORARY};

    *size = 0;
    while (fscanf(file, "%d %s %[^\n]", &temp_record.value, buffer, temp_record.buffer) == 3) {
        for (int i = 0; i < 3; ++i) {
            if (strcmp(buffer, metadata_strings[i]) == 0) {
                temp_record.metadata = metadata_map[i];
                break;
            }
        }

        Record* records = realloc(records, (*size + 1) * sizeof(Record));
        if (!records) {
            perror("Failed to reallocate memory for deserialized records");
            fclose(file);
            return NULL;
        }

        records[*size] = temp_record;
        ++(*size);
    }

    fclose(file);
    return records;
}

// Function to clear and reset the data structure
void clear_records(Record **records) {
    if (*records) {
        free(*records);
        *records = NULL;
    }
    total_records = 0;
}

int main() {
    srand(time(NULL));

    const char charset[] = "abcdefghijklmnopqrstuvwxyz";
    Record* records = init_records(10, 0.5, 0.3, 0.2, charset);

