        serialize_records("records.txt", records, 10);

        size_t deserialized_size;
        Record* loaded_records = deserialize_records("records.txt", &deserialized_size);

        // Use loaded_records as needed...

        clear_records(&loaded_records);
        clear_records(&records);
    }

    return 0;
}
