#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { TYPE_A, TYPE_B } ResourceType;
typedef struct {
    char category[50];
} Metadata;

typedef struct VersionInfo {
    int version_id;
    time_t last_accessed;
    struct VersionInfo* next;
} VersionInfo;

typedef struct Resource {
    int resource_id;
    Metadata metadata;
    size_t size;
    ResourceType type;
    unsigned long access_count;
    time_t expiration_timestamp;
    VersionInfo* versions;
    pthread_mutex_t lock;
} Resource;

typedef struct CacheNode {
    Resource* resource;
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

typedef struct Cache {
    CacheNode* head;
    CacheNode* tail;
    size_t capacity;
    size_t current_size;
    pthread_rwlock_t cache_lock;
    pthread_mutex_t config_lock;
    unsigned long hit_count;
    unsigned long miss_count;
    pthread_t monitor_thread;
    int dynamic_config;
} Cache;

Cache* create_cache(size_t capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    cache->current_size = 0;
    pthread_rwlock_init(&cache->cache_lock, NULL);
    pthread_mutex_init(&cache->config_lock, NULL);
    cache->hit_count = 0;
    cache->miss_count = 0;

    if (pthread_create(&cache->monitor_thread, NULL, monitor_cache, cache) != 0) {
        free(cache);
        return NULL;
    }

    return cache;
}

void destroy_cache(Cache* cache) {
    CacheNode* node = cache->head;
    while (node) {
        CacheNode* next = node->next;
        Resource* resource = node->resource;

        VersionInfo* version = resource->versions;
        while (version) {
            VersionInfo* temp = version;
            version = version->next;
            free(temp);
        }

        pthread_mutex_destroy(&resource->lock);
        free(resource);
        free(node);
        node = next;
    }

    pthread_rwlock_destroy(&cache->cache_lock);
    pthread_mutex_destroy(&cache->config_lock);
    pthread_cancel(cache->monitor_thread);
    pthread_join(cache->monitor_thread, NULL);
    free(cache);
}

int add_or_update_resource(Cache* cache, int resource_id, Metadata metadata, size_t size, ResourceType type, time_t expiration) {
    pthread_rwlock_wrlock(&cache->cache_lock);

    CacheNode* node = cache->head;
    while (node) {
        if (pthread_mutex_trylock(&node->resource->lock) == 0) {
            if (node->resource->resource_id == resource_id) {
                Resource* resource = node->resource;

                VersionInfo* new_version = (VersionInfo*)malloc(sizeof(VersionInfo));
                new_version->version_id = rand(); // Unique version ID
                new_version->last_accessed = time(NULL);
                new_version->next = resource->versions;
                resource->versions = new_version;

                pthread_mutex_unlock(&resource->lock);
                pthread_rwlock_unlock(&cache->cache_lock);
                return 1; // Updated existing resource
            }
            pthread_mutex_unlock(&node->resource->lock);
        }
        node = node->next;
    }

    if (cache->current_size >= cache->capacity) {
        evict_resource(cache); // Eviction policy here
    }

    Resource* new_resource = (Resource*)malloc(sizeof(Resource));
    if (!new_resource) {
        pthread_rwlock_unlock(&cache->cache_lock);
        return 0; // Memory allocation failed
    }

    new_resource->resource_id = resource_id;
    memcpy(&new_resource->metadata, &metadata, sizeof(Metadata));
    new_resource->size = size;
    new_resource->type = type;
    new_resource->access_count = 1;
    new_resource->expiration_timestamp = expiration;
    new_resource->versions = NULL;

    pthread_mutex_init(&new_resource->lock, NULL);

    VersionInfo* initial_version = (VersionInfo*)malloc(sizeof(VersionInfo));
    if (!initial_version) {
        pthread_mutex_destroy(&new_resource->lock);
        free(new_resource);
        pthread_rwlock_unlock(&cache->cache_lock);
        return 0; // Memory allocation failed
    }

    initial_version->version_id = rand(); // Unique version ID
    initial_version->last_accessed = time(NULL);
    initial_version->next = NULL;
    new_resource->versions = initial_version;

    CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!new_node) {
        free(initial_version);
        pthread_mutex_destroy(&new_resource->lock);
        free(new_resource);
        pthread_rwlock_unlock(&cache->cache_lock);
        return 0; // Memory allocation failed
    }

    new_node->resource = new_resource;
    new_node->prev = cache->tail;
    new_node->next = NULL;

    if (cache->tail) {
        cache->tail->next = new_node;
    } else {
        cache->head = new_node;
    }
    cache->tail = new_node;
    cache->current_size++;

    pthread_rwlock_unlock(&cache->cache_lock);
    return 1; // Resource added
}

void evict_resource(Cache* cache) {
    // Implement eviction policy (LRU, LFU, LRA-C)
    // For simplicity, let's assume we're using LRU here

    CacheNode* node = cache->head;
    if (!node) return;

    while (node && node->prev) {
        node = node->prev; // Move to the least recently used
    }

    if (node) {
        pthread_mutex_lock(&node->resource->lock);
        CacheNode* evict_node = node;
        node = node->next;

        if (evict_node == cache->head) cache->head = node;
        if (evict_node == cache->tail) cache->tail = evict_node->prev;
        if (node) node->prev = evict_node->prev;

        if (evict_node->prev) evict_node->prev->next = node;

        pthread_mutex_unlock(&evict_node->resource->lock);

        free(evict_node->resource->versions);
        pthread_mutex_destroy(&evict_node->resource->lock);
        free(evict_node->resource);
        free(evict_node);

        cache->current_size--;
    }
}

void* monitor_cache(void* arg) {
    Cache* cache = (Cache*)arg;
    while (1) {
        sleep(60); // Monitor every 60 seconds

        pthread_rwlock_rdlock(&cache->cache_lock);
        size_t total_memory = 0;
        CacheNode* node = cache->head;

        while (node) {
            Resource* resource = node->resource;
            if (time(NULL) > resource->expiration_timestamp) {
                // Invalidate expired resources
                pthread_mutex_lock(&resource->lock);

                VersionInfo* version = resource->versions;
                while (version) {
                    VersionInfo* temp = version;
                    version = version->next;
                    free(temp);
                }

                CacheNode* to_delete = node;
                node = node->next;

                if (to_delete == cache->head) cache->head = node;
                if (to_delete == cache->tail) cache->tail = to_delete->prev;
                if (node) node->prev = to_delete->prev;
                if (to_delete->prev) to_delete->prev->next = node;

                pthread_mutex_unlock(&resource->lock);
                pthread_mutex_destroy(&to_delete->resource->lock);
                free(to_delete->resource);
                free(to_delete);

                cache->current_size--;
            } else {
                total_memory += sizeof(Resource) + resource->size;
                node = node->next;
            }
        }

        pthread_rwlock_unlock(&cache->cache_lock);

        printf("Cache Monitor: Total Memory Usage: %zu bytes\n", total_memory);
    }

    return NULL;
}

int main() {
    Cache* cache = create_cache(100);
    if (!cache) {
        fprintf(stderr, "Failed to create cache\n");
        return 1;
    }

    Metadata metadata = {.category = "CategoryA"};
    add_or_update_resource(cache, 1, metadata, 1024, TYPE_A, time(NULL) + 3600);

    // Simulate other operations...

    destroy_cache(cache);
    return 0;
}
