#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 256
#define STATIC 1
#define DYNAMIC 2
#define TEMPORARY 3

typedef struct {
    char buffer[MAX_BUFFER_SIZE];
} Metadata;

typedef struct {
    int value;
    char textBuffer[MAX_BUFFER_SIZE];
    Metadata metadataTag;
} Record;

typedef struct {
    char ipAddress[16]; // Simple IP address storage; no validation.
