    size_t bufferSize;
    void *dataBuffer;
} NetworkConnection;

typedef struct {
    long offset;
    int key;
    Record record;
} DataRecord;

typedef struct {
    NetworkConnection *connections;
    DataRecord *records;
    unsigned int numConnections;
    unsigned int maxRecords;
    unsigned int currentRecords;
    pthread_mutex_t lock; // For thread-safe operations
} DataContainer;

DataContainer* initDataContainer(size_t size, float staticProportion, float dynamicProportion) {
    if (staticProportion + dynamicProportion > 1.0f) return NULL;

    DataContainer *dc = malloc(sizeof(DataContainer));
    if (!dc) return NULL;

    dc->numConnections = size / 2; // Example split
    dc->maxRecords = size - dc->numConnections;
    dc->currentRecords = 0;

    pthread_mutex_init(&dc->lock, NULL);

    dc->connections = malloc(dc->numConnections * sizeof(NetworkConnection));
    if (!dc->connections) {
        free(dc);
        return NULL;
    }

    for (unsigned int i = 0; i < dc->numConnections; ++i) {
        dc->connections[i].dataBuffer = calloc(1024, 1); // Arbitrary buffer size
        dc->connections[i].bufferSize = 1024;
    }

    dc->records = malloc(dc->maxRecords * sizeof(DataRecord));
    if (!dc->records) {
        free(dc->connections);
        free(dc);
        return NULL;
    }

    // Initialize proportions
    unsigned int staticCount = (unsigned int)(staticProportion * dc->maxRecords);
    unsigned int dynamicCount = (unsigned int)(dynamicProportion * dc->maxRecords);

    for (unsigned int i = 0; i < dc->currentRecords < staticCount; ++i) {
        dc->records[i].record.metadataTag = STATIC;
    }

    for (unsigned int i = staticCount; i < dc->currentRecords < staticCount + dynamicCount; ++i) {
        dc->records[i].record.metadataTag = DYNAMIC;
    }

    // Rest are TEMPORARY by default
    for (unsigned int i = staticCount + dynamicCount; i < dc->maxRecords; ++i) {
        dc->records[i].record.metadataTag = TEMPORARY;
    }

    return dc;
}

int addRecord(DataContainer *dc, long offset, int key, const char *content) {
    pthread_mutex_lock(&dc->lock);
    if (dc->currentRecords >= dc->maxRecords) {
        pthread_mutex_unlock(&dc->lock);
        return -1; // Memory limit reached
    }

    DataRecord *dr = &dc->records[dc->currentRecords];
    dr->offset = offset;
    dr->key = key;

    strncpy(dr->record.textBuffer, content, MAX_BUFFER_SIZE - 1);
    dr->record.textBuffer[MAX_BUFFER_SIZE - 1] = '\0'; // Ensure null-termination

    dc->currentRecords++;
    pthread_mutex_unlock(&dc->lock);

    return 0;
}

void randomizeRecordBuffers(DataContainer *dc) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t charsetSize = sizeof(charset) - 1;

    for (unsigned int i = 0; i < dc->currentRecords; ++i) {
        for (size_t j = 0; j < MAX_BUFFER_SIZE; ++j) {
            dc->records[i].record.textBuffer[j] = charset[rand() % charsetSize];
        }
        dc->records[i].record.textBuffer[MAX_BUFFER_SIZE - 1] = '\0'; // Ensure null-termination
    }
}

int serializeDataContainer(DataContainer *dc, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&dc->numConnections, sizeof(dc->numConnections), 1, file);
    fwrite(&dc->maxRecords, sizeof(dc->maxRecords), 1, file);
    fwrite(&dc->currentRecords, sizeof(dc->currentRecords), 1, file);

    for (unsigned int i = 0; i < dc->numConnections; ++i) {
        fwrite(&dc->connections[i], sizeof(NetworkConnection), 1, file);
    }

    for (unsigned int i = 0; i < dc->currentRecords; ++i) {
        fwrite(&dc->records[i], sizeof(DataRecord), 1, file);
    }

    fclose(file);
    return 0;
}

DataContainer* deserializeDataContainer(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    DataContainer *dc = malloc(sizeof(DataContainer));
    if (!dc) {
        fclose(file);
        return NULL;
    }

    fread(&dc->numConnections, sizeof(dc->numConnections), 1, file);
    fread(&dc->maxRecords, sizeof(dc->maxRecords), 1, file);
    fread(&dc->currentRecords, sizeof(dc->currentRecords), 1, file);

    dc->connections = malloc(dc->numConnections * sizeof(NetworkConnection));
    if (!dc->connections) {
        free(dc);
        fclose(file);
        return NULL;
    }

    for (unsigned int i = 0; i < dc->numConnections; ++i) {
        fread(&dc->connections[i], sizeof(NetworkConnection), 1, file);
    }

    dc->records = malloc(dc->maxRecords * sizeof(DataRecord));
    if (!dc->records) {
        free(dc->connections);
        free(dc);
        fclose(file);
        return NULL;
    }

    for (unsigned int i = 0; i < dc->currentRecords; ++i) {
        fread(&dc->records[i], sizeof(DataRecord), 1, file);
    }

    pthread_mutex_init(&dc->lock, NULL);

    fclose(file);
    return dc;
}

void cleanupDataContainer(DataContainer *dc) {
    if (!dc) return;

    for (unsigned int i = 0; i < dc->numConnections; ++i) {
        free(dc->connections[i].dataBuffer);
    }

    free(dc->connections);
    free(dc->records);
    pthread_mutex_destroy(&dc->lock);
    free(dc);
}

