    DataContainer *loadedContainer = deserializeDataContainer("data.bin");
    if (!loadedContainer) {
        fprintf(stderr, "Deserialization failed\n");
    }

    cleanupDataContainer(container);
    cleanupDataContainer(loadedContainer);

