#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MEMORY_THRESHOLD 1048576 // 1MB for example

typedef enum {
    RED, GREEN, BLUE, YELLOW, BLACK, WHITE
} Color;

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    unsigned char *pixels;
    int width;
    int height;
} Image;

typedef struct {
    double *doubles;
    Point *points;
    Color *colors;
    Image *images;
    size_t doubles_count;
    size_t points_count;
    size_t colors_count;
    size_t images_count;
    size_t total_memory_used;
} DataManager;

DataManager* init_data_manager(size_t max_records) {
    DataManager *manager = (DataManager *)malloc(sizeof(DataManager));
    if (!manager) {
        fprintf(stderr, "Error: Memory allocation failed for DataManager.\n");
        return NULL;
    }
    manager->doubles_count = 0;
    manager->points_count = 0;
    manager->colors_count = 0;
    manager->images_count = 0;
    manager->total_memory_used = 0;

    // Pre-calculate the size for each type
    size_t double_size = sizeof(double);
    size_t point_size = sizeof(Point);
    size_t color_size = sizeof(Color);
    size_t image_pointer_size = sizeof(unsigned char *);
    size_t image_struct_size = sizeof(Image) - image_pointer_size; // excluding pixels

    while (manager->doubles_count < max_records || manager->points_count < max_records ||
           manager->colors_count < max_records || manager->images_count < max_records) {

        if (manager->total_memory_used + double_size > MEMORY_THRESHOLD &&
            manager->total_memory_used + point_size > MEMORY_THRESHOLD &&
            manager->total_memory_used + color_size > MEMORY_THRESHOLD &&
            manager->total_memory_used + image_struct_size > MEMORY_THRESHOLD) {
            fprintf(stderr, "Error: Memory threshold exceeded.\n");
            break;
        }

        if (manager->doubles_count < max_records && 
            manager->total_memory_used + double_size <= MEMORY_THRESHOLD) {
            manager->doubles = realloc(manager->doubles, sizeof(double) * (manager->doubles_count + 1));
            if (!manager->doubles) {
                fprintf(stderr, "Error: Memory allocation failed for doubles.\n");
                break;
            }
            manager->total_memory_used += double_size;
            manager->doubles_count++;
        }

        if (manager->points_count < max_records && 
            manager->total_memory_used + point_size <= MEMORY_THRESHOLD) {
            manager->points = realloc(manager->points, sizeof(Point) * (manager->points_count + 1));
            if (!manager->points) {
                fprintf(stderr, "Error: Memory allocation failed for points.\n");
                break;
            }
            manager->total_memory_used += point_size;
            manager->points_count++;
        }

        if (manager->colors_count < max_records && 
            manager->total_memory_used + color_size <= MEMORY_THRESHOLD) {
            manager->colors = realloc(manager->colors, sizeof(Color) * (manager->colors_count + 1));
            if (!manager->colors) {
                fprintf(stderr, "Error: Memory allocation failed for colors.\n");
                break;
            }
            manager->total_memory_used += color_size;
            manager->colors_count++;
        }

        if (manager->images_count < max_records && 
            manager->total_memory_used + image_struct_size <= MEMORY_THRESHOLD) {
            manager->images = realloc(manager->images, sizeof(Image) * (manager->images_count + 1));
            if (!manager->images) {
                fprintf(stderr, "Error: Memory allocation failed for images.\n");
                break;
            }
            Image new_image = {NULL, 0, 0};
            manager->total_memory_used += image_struct_size;
            manager->images[manager->images_count++] = new_image;
        }

    }

    return manager;
}

void free_data_manager(DataManager *manager) {
    if (manager) {
        free(manager->doubles);
        free(manager->points);
        free(manager->colors);
        for (size_t i = 0; i < manager->images_count; ++i) {
            free(manager->images[i].pixels); // Assuming image pixels are dynamically allocated
        }
        free(manager->images);
        free(manager);
    }
}

// Serialization and deserialization stubs

int serialize_data_manager(DataManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file for writing.\n");
        return -1;
    }

    // Write metadata
    size_t header[4] = {manager->doubles_count, manager->points_count, manager->colors_count, manager->images_count};
    fwrite(header, sizeof(size_t), 4, file);

    // Write data
    fwrite(manager->doubles, sizeof(double), manager->doubles_count, file);
    fwrite(manager->points, sizeof(Point), manager->points_count, file);
    fwrite(manager->colors, sizeof(Color), manager->colors_count, file);

    for (size_t i = 0; i < manager->images_count; ++i) {
        Image img = manager->images[i];
        int valid_pixels = (img.pixels != NULL);
        fwrite(&valid_pixels, sizeof(int), 1, file);
        if (valid_pixels) {
            size_t pixel_size = img.width * img.height;
            fwrite(&pixel_size, sizeof(size_t), 1, file);
            fwrite(img.pixels, sizeof(unsigned char), pixel_size, file);
        }
        fwrite(&img.width, sizeof(int), 1, file);
        fwrite(&img.height, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_data_manager(DataManager **manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Could not open file for reading.\n");
        return -1;
    }

    size_t header[4];
    fread(header, sizeof(size_t), 4, file);

    DataManager *new_manager = init_data_manager(0);
    if (!new_manager) {
        fclose(file);
        return -1;
    }

    new_manager->doubles_count = header[0];
    new_manager->points_count = header[1];
    new_manager->colors_count = header[2];
    new_manager->images_count = header[3];

    new_manager->doubles = realloc(new_manager->doubles, sizeof(double) * new_manager->doubles_count);
    fread(new_manager->doubles, sizeof(double), new_manager->doubles_count, file);

    new_manager->points = realloc(new_manager->points, sizeof(Point) * new_manager->points_count);
    fread(new_manager->points, sizeof(Point), new_manager->points_count, file);

    new_manager->colors = realloc(new_manager->colors, sizeof(Color) * new_manager->colors_count);
    fread(new_manager->colors, sizeof(Color), new_manager->colors_count, file);

    for (size_t i = 0; i < new_manager->images_count; ++i) {
        int valid_pixels;
        fread(&valid_pixels, sizeof(int), 1, file);

        if (valid_pixels) {
            size_t pixel_size;
            fread(&pixel_size, sizeof(size_t), 1, file);
            unsigned char *pixels = malloc(pixel_size);
            fread(pixels, sizeof(unsigned char), pixel_size, file);
            new_manager->images[i].pixels = pixels;
        } else {
            new_manager->images[i].pixels = NULL;
        }

        int width, height;
        fread(&width, sizeof(int), 1, file);
        fread(&height, sizeof(int), 1, file);
        new_manager->images[i].width = width;
        new_manager->images[i].height = height;
    }

    fclose(file);
    *manager = new_manager;
    return 0;
}
