// Thread-safe random number generator
pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int thread_safe_rand(void) {
    static unsigned int seed = 0;
    pthread_mutex_lock(&rand_lock);
    if (!seed) {
        srand((unsigned int)time(NULL));
        seed = 1;
    }
    unsigned int result = rand();
    pthread_mutex_unlock(&rand_lock);
    return result;
}

void initialize_arrays(long *offsets, size_t num_offsets, int *keys, size_t num_keys, record **records) {
    if (num_offsets == 0 || num_keys == 0) {
        fprintf(stderr, "Error: Array sizes must be greater than zero.\n");
        return;
    }

    // Initialize offsets and keys based on user input
    for (size_t i = 0; i < num_offsets; ++i) {
        if (scanf("%ld", &offsets[i]) != 1) {
            fprintf(stderr, "Error reading offset value at index %zu.\n", i);
            free_memory(offsets, keys, NULL);
            return;
        }
    }

    for (size_t i = 0; i < num_keys; ++i) {
        if (scanf("%d", &keys[i]) != 1) {
            fprintf(stderr, "Error reading key value at index %zu.\n", i);
            free_memory(offsets, keys, NULL);
            return;
        }
    }

    // Calculate the maximum offset
    long max_offset = offsets[0];
    for (size_t i = 1; i < num_offsets; ++i) {
        if (offsets[i] > max_offset) {
            max_offset = offsets[i];
        }
    }

    // Allocate memory for records
    *records = malloc(10000 * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free_memory(offsets, keys, NULL);
        return;
    }

    // Populate the records array
    for (size_t i = 0; i < 10000; ++i) {
        (*records)[i].key = keys[thread_safe_rand() % num_keys];
        (*records)[i].offset = thread_safe_rand() % (max_offset + 1);
    }

    // Log performance metrics
    printf("Initialization completed successfully.\n");
}

void free_memory(long *offsets, int *keys, record *records) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
