#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <string.h>

#define MAX_RECORDS 50000

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} record;

// Function prototypes
long* initialize_offsets(size_t num_values);
int* initialize_keys(size_t num_values, size_t num_unique_keys);
void validate_key(int key); // Simulate network API call
record* initialize_records(long *offsets, int *keys, size_t num_keys, size_t num_records);
size_t get_random_duration();
time_t get_current_time_minus_random_duration(size_t duration);

// External API simulation (mock function)
void simulate_network_delay() {
    struct timespec req = {0};
    req.tv_sec = 1;
    nanosleep(&req, (struct timespec *)NULL);
}

long* initialize_offsets(size_t num_values) {
    long *offsets = malloc(num_values * sizeof(long));
    if (!offsets) return NULL;

    for (size_t i = 0; i < num_values; ++i) {
        offsets[i] = rand() % (1000000 - 1) + 1;
    }
    return offsets;
}

int* initialize_keys(size_t num_values, size_t num_unique_keys) {
    int *keys = malloc(num_values * sizeof(int));
    if (!keys) return NULL;

    bool exists[MAX_RECORDS];
    memset(exists, false, MAX_RECORDS);

    for (size_t i = 0; i < num_unique_keys; ++i) {
        int key;
        do {
            key = rand() % MAX_RECORDS;
        } while (exists[key]);

        exists[key] = true;
        keys[i] = key;

        // Simulate network delay
        simulate_network_delay();
        validate_key(key);
    }

    return keys;
}

record* initialize_records(long *offsets, int *keys, size_t num_keys, size_t num_records) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    srand((unsigned) time(NULL));

    long max_offset = offsets[0];
    for (size_t i = 1; i < num_keys; ++i) {
        if (offsets[i] > max_offset) {
            max_offset = offsets[i];
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        int key_index = rand() % num_keys;
        records[i].key = keys[key_index];
        records[i].offset = rand() % (max_offset + 1);
        size_t duration = get_random_duration();
        records[i].timestamp = get_current_time_minus_random_duration(duration);
    }

    return records;
}

size_t get_random_duration() {
    return rand() % (86401); // Random duration from 0 to 86400
}

time_t get_current_time_minus_random_duration(size_t duration) {
    time_t current_time = time(NULL);
    return current_time - duration;
}

void free_resources(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t num_offsets = 1000; // Example number of offsets
    size_t num_keys = 500;     // Number of unique keys (example)
    size_t num_records = MAX_RECORDS;

    long *offsets = initialize_offsets(num_offsets);
    if (!offsets) return EXIT_FAILURE;

    int *keys = initialize_keys(num_offsets, num_keys);
    if (!keys) {
        free(offsets);
        return EXIT_FAILURE;
    }

    record *records = initialize_records(offsets, keys, num_keys, num_records);
    if (!records) {
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    // Simulate usage of records...

    free_resources(offsets, keys, records);

    return EXIT_SUCCESS;
}
