#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <time.h>

typedef struct {
    char user_id[64];
    time_t timestamp;
    int status; // 0 for inactive, 1 for active
    char password_hash[256];
} UserProfile;

typedef struct {
    UserProfile **profiles;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ProfileManager;

// Function prototypes
void manage_user_profiles(ProfileManager *manager);
int add_profile(ProfileManager *manager, const char *user_id, const char *password);
UserProfile* get_profile_by_id(const ProfileManager *manager, const char *user_id);
int update_password(ProfileManager *manager, const char *user_id, const char *new_password);
void purge_expired_profiles(ProfileManager *manager, time_t expiration_threshold);
void validate_and_update_password_strength(const char *password);
void log_audit_trail(const char *user_id, const char *operation_type, const char *context);

// Helper functions
int hash_password(const char *password, unsigned char *hash_out) {
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx) return 0;

    if (1 != EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) {
        EVP_MD_CTX_free(mdctx);
        return 0;
    }

    if (1 != EVP_DigestUpdate(mdctx, password, strlen(password))) {
        EVP_MD_CTX_free(mdctx);
        return 0;
    }

    unsigned int len = 0;
    if (1 != EVP_DigestFinal_ex(mdctx, hash_out, &len)) {
        EVP_MD_CTX_free(mdctx);
        return 0;
    }
    EVP_MD_CTX_free(mdctx);

    // Ensure the hash is null-terminated
    memset(hash_out + len, 0, sizeof(hash_out) - len);
    return 1;
}

// Main function to manage user profiles
void manage_user_profiles(ProfileManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->profiles = NULL;
    manager->count = 0;
    manager->capacity = 0;

    // Example usage:
    add_profile(manager, "user123", "Password1!");
    UserProfile *profile = get_profile_by_id(manager, "user123");
    if (profile) {
        update_password(manager, "user123", "NewPassword2@");
    }
}

int add_profile(ProfileManager *manager, const char *user_id, const char *password) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 4 : manager->capacity * 2;
        UserProfile **new_profiles = realloc(manager->profiles, new_capacity * sizeof(UserProfile *));
        if (!new_profiles) {
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        manager->profiles = new_profiles;
        manager->capacity = new_capacity;
    }

    UserProfile *profile = malloc(sizeof(UserProfile));
    if (!profile) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    strncpy(profile->user_id, user_id, sizeof(profile->user_id));
    profile->timestamp = time(NULL);
    profile->status = 1;

    unsigned char hash[256];
    if (!hash_password(password, hash)) {
        free(profile);
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }
    strncpy(profile->password_hash, (char *)hash, sizeof(profile->password_hash));

    manager->profiles[manager->count++] = profile;

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

UserProfile* get_profile_by_id(const ProfileManager *manager, const char *user_id) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->profiles[i]->user_id, user_id) == 0) {
            UserProfile *profile = malloc(sizeof(UserProfile));
            memcpy(profile, manager->profiles[i], sizeof(UserProfile));
            pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
            return profile;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return NULL;
}

int update_password(ProfileManager *manager, const char *user_id, const char *new_password) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->profiles[i]->user_id, user_id) == 0) {
            unsigned char hash[256];
            if (!hash_password(new_password, hash)) {
                pthread_mutex_unlock(&manager->lock);
                return 0;
            }
            strncpy(manager->profiles[i]->password_hash, (char *)hash, sizeof(manager->profiles[i]->password_hash));
            manager->profiles[i]->timestamp = time(NULL);

            log_audit_trail(user_id, "UPDATE_PASSWORD", "Password updated successfully.");
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void purge_expired_profiles(ProfileManager *manager, time_t expiration_threshold) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(time(NULL), manager->profiles[i]->timestamp) > expiration_threshold) {
            free(manager->profiles[i]);
            memmove(&manager->profiles[i], &manager->profiles[i + 1],
                    (manager->count - i - 1) * sizeof(UserProfile *));
            manager->count--;
            i--; // Adjust index after removal
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void validate_and_update_password_strength(const char *password) {
    if (strlen(password) < 8 ||
        strspn(password, "abcdefghijklmnopqrstuvwxyz") == strlen(password) ||
        strspn(password, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") == strlen(password) ||
        strspn(password, "0123456789") == strlen(password)) {
        fprintf(stderr, "Password does not meet strength requirements.\n");
    }
}

void log_audit_trail(const char *user_id, const char *operation_type, const char *context) {
    printf("Audit Trail - User: %s, Operation: %s, Context: %s\n", user_id, operation_type, context);
}
