#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

// Global variables for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long *offsets = NULL;
int *keys = NULL;
record *records = NULL;
size_t records_count = 0;
const size_t MAX_RECORDS = 10000;

// Function prototypes
void initialize_from_config(const char* config_path);
void free_resources();
void insert_record(record rec, const char* log_file_path);
size_t get_records_count() {
    pthread_mutex_lock(&lock);
    size_t count = records_count;
    pthread_mutex_unlock(&lock);
    return count;
}

record* get_record_by_key(int key) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < records_count; ++i) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&lock);
            return &records[i];
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void serialize_records(const char* file_path);
int deserialize_records(const char* file_path);

// Main function to manage memory and perform operations
void manage_memory_and_operations(const char *config_path, const char* log_file_path) {
    initialize_from_config(config_path);

    if (log_file_path != NULL) {
        FILE *log_file = fopen(log_file_path, "a");
        if (!log_file) {
            perror("Error opening log file");
            free_resources();
            return;
        }
    }

    srand(time(NULL));

    // Populate records array
    for (size_t i = 0; i < MAX_RECORDS && records_count < MAX_RECORDS; ++i) {
        int key_index = rand() % (sizeof(keys) / sizeof(int));
        record new_record = {keys[key_index], rand() % (*max_element(offsets, offsets + sizeof(offsets)/sizeof(long)))};

        insert_record(new_record, log_file_path);
    }

    // Close the log file if it was opened
    if (log_file_path != NULL) {
        fclose(log_file);
    }
}

void initialize_from_config(const char* config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Error opening configuration file");
        exit(EXIT_FAILURE);
    }

    // Assume configuration format is:
    // <number_of_offsets>
    // <offset1> <offset2> ... <offsetN>
    // <number_of_keys>
    // <key1> <key2> ... <keyM>

    size_t num_offsets, num_keys;
    fscanf(file, "%zu", &num_offsets);
    offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        fscanf(file, "%ld", &offsets[i]);
    }

    fscanf(file, "%zu", &num_keys);
    keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_keys; ++i) {
        fscanf(file, "%d", &keys[i]);
    }

    records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void insert_record(record rec, const char* log_file_path) {
    pthread_mutex_lock(&lock);
    if (records_count < MAX_RECORDS) {
        records[records_count++] = rec;

        // Log the operation
        if (log_file_path != NULL) {
            FILE *log_file = fopen(log_file_path, "a");
            if (log_file) {
                fprintf(log_file, "Inserted record - Key: %d, Offset: %ld, Timestamp: %ld\n",
                        rec.key, rec.offset, time(NULL));
                fclose(log_file);
            }
        }
    }
    pthread_mutex_unlock(&lock);
}

void free_resources() {
    pthread_mutex_lock(&lock);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    offsets = keys = records = NULL;
    records_count = 0;
    pthread_mutex_unlock(&lock);
}

long* max_element(long* start, long* end) {
    if (start == end) return end;
    long* largest = start++;
    while (start != end) {
        if (*start > *largest)
            largest = start;
        ++start;
    }
    return largest;
}

void serialize_records(const char* file_path) {
    pthread_mutex_lock(&lock);
    FILE *file = fopen(file_path, "wb");
    if (!file) {
        perror("Error opening file for serialization");
        pthread_mutex_unlock(&lock);
        return;
    }

    fwrite(&records_count, sizeof(size_t), 1, file);
    fwrite(records, sizeof(record), records_count, file);

    fclose(file);
    pthread_mutex_unlock(&lock);
}

int deserialize_records(const char* file_path) {
    pthread_mutex_lock(&lock);
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Error opening file for deserialization");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    free(records); // Free existing records
    records = (record*)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for deserialized records");
        fclose(file);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    fread(records, sizeof(record), count, file);
    records_count = count;

    fclose(file);
    pthread_mutex_unlock(&lock);

    return 0;
}
