#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB

typedef struct {
    int key;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t n, m, k;
    pthread_mutex_t lock;
} memory_pool;

void validate_parameters(size_t n, size_t m, size_t k) {
    if (n == 0 || m == 0 || k == 0) {
        fprintf(stderr, "Parameters must be greater than zero.\n");
        exit(EXIT_FAILURE);
    }
}

void* centralized_error_logging(const char *error_message) {
    // Centralized logging logic
    time_t now = time(NULL);
    printf("[%s] Error: %s\n", ctime(&now), error_message);
}

memory_pool* create_memory_pool(size_t n, size_t m, size_t k) {
    validate_parameters(n, m, k);

    memory_pool *pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) {
        centralized_error_logging("Failed to allocate memory for pool structure.");
        return NULL;
    }

    size_t total_size = n * sizeof(long) + m * sizeof(int) + k * sizeof(record);
    if (total_size > MAX_MEMORY_USAGE) {
        centralized_error_logging("Requested memory exceeds maximum allowed usage.");
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    pool->offsets = (long*)aligned_alloc(64, n * sizeof(long));
    pool->keys = (int*)aligned_alloc(64, m * sizeof(int));
    pool->records = (record*)aligned_alloc(64, k * sizeof(record));

    if (!pool->offsets || !pool->keys || !pool->records) {
        centralized_error_logging("Failed to allocate aligned memory for data.");
        free_memory_pool(pool);
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    srand(time(NULL));
    for (size_t i = 0; i < k; ++i) {
        pool->records[i].key = rand() % 2001 - 1000;
    }
    pthread_mutex_unlock(&pool->lock);

    pool->n = n;
    pool->m = m;
    pool->k = k;

    return pool;
}

void free_memory_pool(memory_pool *pool) {
    if (!pool) return;
    pthread_mutex_destroy(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

int main() {
    size_t n = 1000, m = 500, k = 300;

    memory_pool *mp = create_memory_pool(n, m, k);

    if (!mp) {
        centralized_error_logging("Memory pool creation failed.");
        return EXIT_FAILURE;
    }

    // Simulate operations on the memory pool
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->k; ++i) {
        printf("Record %zu: Key = %d\n", i, mp->records[i].key);
    }
    pthread_mutex_unlock(&mp->lock);

    free_memory_pool(mp);
    return EXIT_SUCCESS;
}
