int initialize_data_structures(long num_offsets, record **records) {
    if (num_offsets <= 0 || num_offsets >= MAX_OFFSETS) return 0;

    // Calculate sizes for keys and records
    size_t num_keys = num_offsets / 2;
    size_t num_records = num_keys; // Assuming one record per key

    // Allocate memory for offsets
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) return 0;

    // Initialize offsets with some values (example: incrementing numbers)
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }

    // Allocate memory for keys
    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return 0;
    }

    // Initialize keys with some values (example: incrementing numbers)
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records
    *records = (record *)malloc(num_records * sizeof(record));
    if (!(*records)) {
        free(offsets);
        free(keys);
        return 0;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset_ptr = &offsets[i * 2]; // Point to a value in offsets
        (*records)[i].key = keys[i];
        (*records)[i].character = 'A' + (rand() % ('Z' - 'A' + 1)); // Random char between 'A' and 'Z'
    }

    return 1; // Success
}

void free_data_structures(long *offsets, int *keys, record *records) {
