```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define structures
typedef struct {
    size_t latency;
    int responseStatusCode;
} ResponseDetail;

typedef struct {
    char* timestamp;
    char* uniqueIdentifier;
    char* serviceName;
    char* requestMethod;
    int responseStatusCode;
    size_t requestBodySize;
    ResponseDetail details;
    char* requestBody; // Dynamically allocated
} LogEntry;

typedef struct {
    char* ISBN;
    char* title;
    char* author;
    int publicationYear;
    _Atomic int availabilityStatus;
} Book;

// Function prototypes
void initializeLibraryManager();
LogEntry* createLogEntry(const char* timestamp, const char* uniqueIdentifier,
                         const char* serviceName, const char* requestMethod,
                         int responseStatusCode, size_t requestBodySize,
                         ResponseDetail details, const char* requestBody);
Book* createBook(const char* ISBN, const char* title, const char* author,
                 int publicationYear, int availabilityStatus);
void freeLogEntry(LogEntry* logEntry);
void freeBook(Book* book);

// Synchronization primitives
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t bookMutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic arrays for storage
LogEntry** logEntries = NULL;
size_t logCount = 0;
Book** books = NULL;
size_t bookCount = 0;

void initializeLibraryManager() {
    // Initialize any necessary resources or perform setup operations
}

LogEntry* createLogEntry(const char* timestamp, const char* uniqueIdentifier,
                         const char* serviceName, const char* requestMethod,
                         int responseStatusCode, size_t requestBodySize,
                         ResponseDetail details, const char* requestBody) {

    pthread_mutex_lock(&logMutex);

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) {
        pthread_mutex_unlock(&logMutex);
        return NULL;
    }

    entry->timestamp = strdup(timestamp);
    entry->uniqueIdentifier = strdup(uniqueIdentifier);
    entry->serviceName = strdup(serviceName);
    entry->requestMethod = strdup(requestMethod);
    entry->responseStatusCode = responseStatusCode;
    entry->requestBodySize = requestBodySize;
    entry->details = details;

    // Allocate memory for request body
    entry->requestBody = (char*)malloc(requestBodySize + 1);
    if (!entry->requestBody) {
        freeLogEntry(entry); // Free other allocated resources
        pthread_mutex_unlock(&logMutex);
        return NULL;
    }
    strncpy(entry->requestBody, requestBody, requestBodySize);
    entry->requestBody[requestBodySize] = '\0';

    logEntries = (LogEntry**)realloc(logEntries, sizeof(LogEntry*) * (logCount + 1));
    if (!logEntries) {
        freeLogEntry(entry);
        pthread_mutex_unlock(&logMutex);
        return NULL;
    }

    logEntries[logCount++] = entry;

    pthread_mutex_unlock(&logMutex);

    return entry;
}

Book* createBook(const char* ISBN, const char* title, const char* author,
                 int publicationYear, int availabilityStatus) {

    pthread_mutex_lock(&bookMutex);

    Book* book = (Book*)malloc(sizeof(Book));
    if (!book) {
        pthread_mutex_unlock(&bookMutex);
        return NULL;
    }

    book->ISBN = strdup(ISBN);
    book->title = strdup(title);
    book->author = strdup(author);
    book->publicationYear = publicationYear;
    atomic_store(&book->availabilityStatus, availabilityStatus);

    books = (Book**)realloc(books, sizeof(Book*) * (bookCount + 1));
    if (!books) {
        freeBook(book);
        pthread_mutex_unlock(&bookMutex);
        return NULL;
    }

    books[bookCount++] = book;

    pthread_mutex_unlock(&bookMutex);

    return book;
}

void freeLogEntry(LogEntry* logEntry) {
    if (logEntry) {
        free(logEntry->timestamp);
        free(logEntry->uniqueIdentifier);
        free(logEntry->serviceName);
        free(logEntry->requestMethod);
        free(logEntry->requestBody);
        free(logEntry);
    }
}

void freeBook(Book* book) {
    if (book) {
        free(book->ISBN);
        free(book->title);
        free(book->author);
        free(book);
    }
}

// Further functions for adding, removing, and retrieving entries
// would be implemented here following the above patterns.

int main() {
    initializeLibraryManager();

    // Example usage of creating a log entry and a book
    ResponseDetail details = {100, 200};
    LogEntry* log = createLogEntry("2023-10-01T12:00:00Z", "ID12345",
                                   "AuthService", "GET", 200, 128,
                                   details, "{\"key\":\"value\"}");

    Book* book = createBook("978-3-16-148410-0", "Example Title", "Author Name", 2023, 1);

    // Cleanup
    freeLogEntry(log);
    freeBook(book);

    return 0;
}
