['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 2 * 1024 * 1024 // 2 MB

typedef struct {
    int identifier;
    long timestamp;
    double value;
} DataRecord;

typedef struct MemoryPool {
    size_t total_size;
    char* pool_memory;
    pthread_mutex_t lock;
} MemoryPool;

static void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

static int validate_parameters(size_t n, size_t m, size_t k) {
    return (n * sizeof(long) + m * sizeof(int) + k * sizeof(DataRecord)) <= MAX_MEMORY_USAGE;
}

MemoryPool* create_memory_pool(size_t total_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        log_error("Failed to allocate memory for memory pool.");
        return NULL;
    }

    pool->total_size = total_size;
    pool->pool_memory = malloc(total_size);
    if (!pool->pool_memory) {
        free(pool);
        log_error("Failed to allocate memory pool space.");
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->pool_memory);
        free(pool);
    }
}

int dynamic_memory_and_data_manager(size_t n, size_t m, size_t k, DataRecord** records_out) {
    if (!validate_parameters(n, m, k)) {
        log_error("Input parameters exceed memory limits.");
        return -1;
    }

    MemoryPool* pool = create_memory_pool(MAX_MEMORY_USAGE);
    if (!pool) {
        return -1;
