    if (!mm) return NULL;

    const size_t TOTAL_MEMORY_MB = 1;
    const size_t TOTAL_MEMORY_BYTES = TOTAL_MEMORY_MB * 1024 * 1024;
    if ((n * sizeof(long)) + (m * sizeof(int)) + (k * sizeof(record_t)) > TOTAL_MEMORY_BYTES)
